-- deployment-mode: rolling
-- Opengeni baseline part 1 of 22: the schema as of migration 0977,
-- replacing migrations 0000-0977 (see packages/db/src/migration-baseline.ts).
-- A fresh database runs every part; a database that applied all of 0000-0977
-- records the parts without running them. The runner replaces {{schema}},
-- {{schema_oid}}, {{owner}} and {{migrated_at}} with the migration session's
-- current schema, its OID, the current user and now().
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS btree_gin;
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

CREATE SCHEMA IF NOT EXISTS opengeni_host_export;

CREATE SCHEMA IF NOT EXISTS opengeni_insights_internal;

CREATE SCHEMA IF NOT EXISTS opengeni_private;

CREATE SCHEMA IF NOT EXISTS opengeni_subscription_internal;

CREATE FUNCTION opengeni_host_export.ack_host_export_batch(p_export_kind text, p_consumer_id text, p_lease_token uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE v_checkpoint bigint;
    BEGIN
      UPDATE {{schema}}.host_export_consumers c
      SET checkpoint = c.lease_through,
          lease_token = NULL, lease_holder_id = NULL, lease_expires_at = NULL,
          lease_from = NULL, lease_through = NULL,
          consecutive_failures = 0, next_attempt_at = now(),
          last_error = NULL, last_error_codec_version = NULL,
          last_error_at = NULL, updated_at = now()
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id
        AND c.lease_token = p_lease_token AND c.lease_through IS NOT NULL
      RETURNING c.checkpoint INTO v_checkpoint;
      IF v_checkpoint IS NULL THEN
        RAISE EXCEPTION 'host export lease is stale' USING ERRCODE = '40001';
      END IF;
      RETURN v_checkpoint;
    END $$;

CREATE FUNCTION opengeni_host_export.allocate_host_export_cursors(p_export_kind text, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_id uuid;
      v_next bigint;
      v_count integer := 0;
      v_limit integer := greatest(1, least(coalesce(p_limit, 512), 4096));
    BEGIN
      SELECT s.next_cursor INTO v_next
      FROM {{schema}}.host_export_cursor_state s
      WHERE s.export_kind = p_export_kind
      FOR UPDATE;
      IF v_next IS NULL THEN
        RAISE EXCEPTION 'unknown host export kind' USING ERRCODE = '22023';
      END IF;

      WHILE v_count < v_limit LOOP
        SELECT o.id INTO v_id
        FROM {{schema}}.host_export_outbox o
        WHERE o.export_kind = p_export_kind
          AND o.export_cursor IS NULL
          AND (
            o.session_id IS NULL OR o.session_sequence IS NULL OR NOT EXISTS (
              SELECT 1 FROM {{schema}}.host_export_outbox earlier
              WHERE earlier.export_kind = o.export_kind
                AND earlier.session_id = o.session_id
                AND earlier.session_sequence IS NOT NULL
                AND earlier.session_sequence < o.session_sequence
                AND earlier.export_cursor IS NULL
            )
          )
        ORDER BY o.enqueued_at, o.id
        FOR UPDATE SKIP LOCKED
        LIMIT 1;
        EXIT WHEN v_id IS NULL;

        UPDATE {{schema}}.host_export_outbox
        SET export_cursor = v_next
        WHERE id = v_id AND export_cursor IS NULL;
        v_next := v_next + 1;
        v_count := v_count + 1;
        v_id := NULL;
      END LOOP;

      UPDATE {{schema}}.host_export_cursor_state
      SET next_cursor = v_next, updated_at = now()
      WHERE export_kind = p_export_kind;
      RETURN v_count;
    END $$;

CREATE FUNCTION opengeni_host_export.claim_host_export_batch(p_export_kind text, p_consumer_id text, p_lease_token uuid, p_lease_holder_id text, p_lease_seconds integer, p_limit integer, p_max_bytes integer) RETURNS TABLE(consumer_id text, export_kind text, checkpoint bigint, lease_token uuid, lease_through bigint, export_cursor bigint, source_id uuid, account_id uuid, workspace_id uuid, session_id uuid, turn_id uuid, turn_generation integer, turn_attempt_id uuid, session_sequence integer, client_event_id text, turn_association text, duplicate_of_event_id uuid, duplicate_reason text, event_type text, idempotency_key text, initiator jsonb, initiator_context jsonb, origin text, payload jsonb, occurred_at timestamp with time zone, source_recorded_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_consumer {{schema}}.host_export_consumers%ROWTYPE;
      v_through bigint;
      v_limit integer := greatest(1, least(coalesce(p_limit, 100), 256));
      v_max_bytes integer := greatest(98304, least(coalesce(p_max_bytes, 1048576), 4194304));
      v_lease_seconds integer := greatest(5, least(coalesce(p_lease_seconds, 60), 300));
    BEGIN
      IF p_lease_token IS NULL THEN
        RAISE EXCEPTION 'host export lease token is required' USING ERRCODE = '22023';
      END IF;
      IF p_lease_holder_id IS NULL OR length(p_lease_holder_id) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'host export lease holder id is invalid' USING ERRCODE = '22023';
      END IF;
      PERFORM opengeni_host_export.allocate_host_export_cursors(
        p_export_kind, greatest(v_limit, 512)
      );

      SELECT * INTO v_consumer
      FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id
      FOR UPDATE;
      IF NOT FOUND OR NOT v_consumer.enabled OR v_consumer.blocked_at IS NOT NULL
        OR v_consumer.next_attempt_at > now()
        OR (v_consumer.lease_expires_at IS NOT NULL AND v_consumer.lease_expires_at > now()) THEN
        RETURN;
      END IF;

      WITH candidates AS MATERIALIZED (
        SELECT o.export_cursor, o.envelope_bytes
        FROM {{schema}}.host_export_outbox o
        WHERE o.export_kind = p_export_kind
          AND o.export_cursor > v_consumer.checkpoint
        ORDER BY o.export_cursor
        LIMIT v_limit
      ), ranked AS (
        SELECT o.export_cursor,
          row_number() OVER (ORDER BY o.export_cursor) AS row_number,
          sum(o.envelope_bytes) OVER (ORDER BY o.export_cursor) AS running_bytes
        FROM candidates o
      ), selected AS (
        SELECT r.export_cursor FROM ranked r
        WHERE r.running_bytes <= v_max_bytes OR r.row_number = 1
      )
      SELECT max(s.export_cursor) INTO v_through FROM selected s;
      IF v_through IS NULL THEN
        RETURN;
      END IF;

      UPDATE {{schema}}.host_export_consumers c
      SET lease_token = p_lease_token,
          lease_holder_id = left(p_lease_holder_id, 128),
          lease_expires_at = now() + make_interval(secs => v_lease_seconds),
          lease_from = v_consumer.checkpoint,
          lease_through = v_through,
          updated_at = now()
      WHERE c.id = v_consumer.id;

      RETURN QUERY
      SELECT p_consumer_id, p_export_kind, v_consumer.checkpoint,
        p_lease_token, v_through, o.export_cursor, o.source_id,
        o.account_id, o.workspace_id, o.session_id, o.turn_id,
        o.turn_generation, o.turn_attempt_id, o.session_sequence,
        o.client_event_id, o.turn_association, o.duplicate_of_event_id,
        o.duplicate_reason,
        o.event_type, o.idempotency_key, o.initiator,
        o.initiator_context, o.origin, o.payload, o.occurred_at,
        o.source_recorded_at
      FROM {{schema}}.host_export_outbox o
      WHERE o.export_kind = p_export_kind
        AND o.export_cursor > v_consumer.checkpoint
        AND o.export_cursor <= v_through
      ORDER BY o.export_cursor;
    END $$;

CREATE FUNCTION opengeni_host_export.dead_letter_host_export_head(p_export_kind text, p_consumer_id text, p_lease_token uuid, p_export_cursor bigint, p_reason text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_consumer {{schema}}.host_export_consumers%ROWTYPE;
      v_row {{schema}}.host_export_outbox%ROWTYPE;
      v_envelope jsonb;
    BEGIN
      IF p_reason IS NULL OR length(p_reason) NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION 'dead-letter reason must contain 1 to 500 characters'
          USING ERRCODE = '22023';
      END IF;
      SELECT * INTO v_consumer
      FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id
      FOR UPDATE;
      IF NOT FOUND OR v_consumer.lease_token IS DISTINCT FROM p_lease_token
        OR v_consumer.lease_through IS NULL THEN
        RAISE EXCEPTION 'host export lease is stale' USING ERRCODE = '40001';
      END IF;
      IF p_export_cursor IS NULL OR p_export_cursor <> v_consumer.checkpoint + 1
        OR p_export_cursor > v_consumer.lease_through THEN
        RAISE EXCEPTION 'only the leased head event may be dead-lettered'
          USING ERRCODE = '22023';
      END IF;

      SELECT * INTO STRICT v_row FROM {{schema}}.host_export_outbox o
      WHERE o.export_kind = p_export_kind AND o.export_cursor = p_export_cursor;
      IF p_export_kind = 'session_event' THEN
        v_envelope := jsonb_build_object(
          'schemaRevision', '2026-07-host-export-v1',
          'cursor', v_row.export_cursor::text,
          'idempotencyKey', v_row.idempotency_key,
          'accountId', v_row.account_id,
          'workspaceId', v_row.workspace_id,
          'initiator', v_row.initiator,
          'initiatorContext', v_row.initiator_context,
          'origin', v_row.origin,
          'event', jsonb_strip_nulls(jsonb_build_object(
            'id', v_row.source_id,
            'workspaceId', v_row.workspace_id,
            'sessionId', v_row.session_id,
            'sequence', v_row.session_sequence,
            'type', v_row.event_type,
            'payload', v_row.payload,
            'occurredAt', v_row.occurred_at,
            'clientEventId', v_row.client_event_id,
            'turnId', v_row.turn_id,
            'turnGeneration', v_row.turn_generation,
            'turnAttemptId', v_row.turn_attempt_id,
            'turnAssociation', v_row.turn_association,
            'duplicateOfEventId', v_row.duplicate_of_event_id,
            'duplicateReason', v_row.duplicate_reason
          ))
        );
      ELSIF p_export_kind = 'lifecycle_fact' THEN
        v_envelope := jsonb_build_object(
          'schemaRevision', '2026-07-host-export-v1',
          'cursor', v_row.export_cursor::text,
          'idempotencyKey', v_row.idempotency_key,
          'accountId', v_row.account_id,
          'workspaceId', v_row.workspace_id,
          'fact', jsonb_build_object(
            'id', v_row.source_id,
            'type', v_row.event_type,
            'attribute', v_row.payload -> 'attribute',
            'subjectKind', v_row.payload -> 'subjectKind',
            'subjectId', v_row.initiator -> 'subjectId',
            'occurredAt', v_row.occurred_at
          )
        );
      ELSE
        v_envelope := jsonb_build_object(
          'schemaRevision', '2026-07-host-export-v1',
          'cursor', v_row.export_cursor::text,
          'accountId', v_row.account_id,
          'workspaceId', v_row.workspace_id,
          'sessionId', v_row.session_id,
          'turnId', v_row.turn_id,
          'turnAttemptId', v_row.turn_attempt_id,
          'initiator', v_row.initiator,
          'initiatorContext', v_row.initiator_context,
          'origin', v_row.origin,
          'usage', v_row.payload
        );
      END IF;

      INSERT INTO {{schema}}.host_export_dead_letters (
        consumer_id, export_kind, export_cursor, source_id, reason, envelope,
        envelope_codec_version, event_payload_codec_version
      ) VALUES (
        p_consumer_id, p_export_kind, p_export_cursor, v_row.source_id,
        p_reason, v_envelope, NULL,
        CASE WHEN p_export_kind = 'session_event' THEN v_row.payload_codec_version ELSE NULL END
      ) ON CONFLICT (export_kind, consumer_id, export_cursor) DO NOTHING;

      UPDATE {{schema}}.host_export_consumers c
      SET (
        checkpoint, lease_token, lease_holder_id, lease_expires_at,
        lease_from, lease_through, consecutive_failures, next_attempt_at,
        last_error, last_error_codec_version, last_error_at, blocked_at, updated_at
      ) = (
        p_export_cursor, NULL::uuid, NULL::text, NULL::timestamptz,
        NULL::bigint, NULL::bigint, 0, now(),
        'dead-lettered: ' || p_reason, NULL::integer, now(), NULL::timestamptz, now()
      )
      WHERE c.id = v_consumer.id;
      RETURN p_export_cursor;
    END $$;

CREATE FUNCTION opengeni_host_export.disable_host_export_consumer(p_export_kind text, p_consumer_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      PERFORM 1 FROM {{schema}}.host_export_cursor_state s
      WHERE s.export_kind = p_export_kind
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown host export kind' USING ERRCODE = '22023';
      END IF;

      UPDATE {{schema}}.host_export_consumers c
      SET enabled = false, updated_at = now()
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'host export consumer not found' USING ERRCODE = 'P0002';
      END IF;

      IF NOT EXISTS (
        SELECT 1 FROM {{schema}}.host_export_consumers c
        WHERE c.export_kind = p_export_kind AND c.enabled
      ) THEN
        UPDATE {{schema}}.host_export_config
        SET session_events_enabled = CASE
              WHEN p_export_kind = 'session_event' THEN false
              ELSE session_events_enabled
            END,
            usage_events_enabled = CASE
              WHEN p_export_kind = 'usage_event' THEN false
              ELSE usage_events_enabled
            END,
            lifecycle_facts_enabled = CASE
              WHEN p_export_kind = 'lifecycle_fact' THEN false
              ELSE lifecycle_facts_enabled
            END,
            updated_at = now()
        WHERE id = 1;
      END IF;
    END $$;

CREATE FUNCTION opengeni_host_export.fail_host_export_batch(p_export_kind text, p_consumer_id text, p_lease_token uuid, p_error text, p_max_failures integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE v_failures integer;
    BEGIN
      UPDATE {{schema}}.host_export_consumers c
      SET consecutive_failures = c.consecutive_failures + 1,
          lease_token = NULL, lease_holder_id = NULL, lease_expires_at = NULL,
          lease_from = NULL, lease_through = NULL,
          next_attempt_at = now() + make_interval(
            secs => least(300, greatest(1, power(2, least(c.consecutive_failures, 8))::integer))
          ),
          last_error = coalesce(p_error, 'host sink failed'),
          last_error_codec_version = NULL,
          last_error_at = now(),
          blocked_at = CASE
            WHEN c.consecutive_failures + 1 >= greatest(1, least(coalesce(p_max_failures, 20), 1000))
            THEN now() ELSE NULL END,
          updated_at = now()
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id
        AND c.lease_token = p_lease_token
      RETURNING c.consecutive_failures INTO v_failures;
      IF v_failures IS NULL THEN
        RAISE EXCEPTION 'host export lease is stale' USING ERRCODE = '40001';
      END IF;
      RETURN v_failures;
    END $$;

CREATE FUNCTION opengeni_host_export.fail_host_export_batch(p_export_kind text, p_consumer_id text, p_lease_token uuid, p_error text, p_max_failures integer, p_error_codec_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE v_failures integer;
    BEGIN
      IF p_error_codec_version IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'host export error codec version must be 1'
          USING ERRCODE = '22023';
      END IF;
      UPDATE {{schema}}.host_export_consumers c
      SET consecutive_failures = c.consecutive_failures + 1,
          lease_token = NULL, lease_holder_id = NULL, lease_expires_at = NULL,
          lease_from = NULL, lease_through = NULL,
          next_attempt_at = now() + make_interval(
            secs => least(300, greatest(1, power(2, least(c.consecutive_failures, 8))::integer))
          ),
          last_error = coalesce(p_error, 'host sink failed'),
          last_error_codec_version = p_error_codec_version,
          last_error_at = now(),
          blocked_at = CASE
            WHEN c.consecutive_failures + 1 >= greatest(1, least(coalesce(p_max_failures, 20), 1000))
            THEN now() ELSE NULL END,
          updated_at = now()
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id
        AND c.lease_token = p_lease_token
      RETURNING c.consecutive_failures INTO v_failures;
      IF v_failures IS NULL THEN
        RAISE EXCEPTION 'host export lease is stale' USING ERRCODE = '40001';
      END IF;
      RETURN v_failures;
    END $$;

CREATE FUNCTION opengeni_host_export.host_export_claim_analytics_sidecars(p_export_kind text, p_consumer_id text, p_lease_token uuid) RETURNS TABLE(export_cursor bigint, surface text, model_provider text, tool_family text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_consumer {{schema}}.host_export_consumers%ROWTYPE;
    BEGIN
      SELECT * INTO v_consumer
      FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind
        AND c.consumer_id = p_consumer_id
      FOR UPDATE;
      IF NOT FOUND
        OR v_consumer.lease_token IS DISTINCT FROM p_lease_token
        OR v_consumer.lease_from IS NULL
        OR v_consumer.lease_through IS NULL
        OR v_consumer.lease_expires_at IS NULL
        OR v_consumer.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'host export lease is not current'
          USING ERRCODE = '55000';
      END IF;

      RETURN QUERY
      SELECT o.export_cursor, o.surface, o.model_provider, o.tool_family
      FROM {{schema}}.host_export_outbox o
      WHERE o.export_kind = p_export_kind
        AND o.export_cursor > v_consumer.lease_from
        AND o.export_cursor <= v_consumer.lease_through
      ORDER BY o.export_cursor;
    END $$;

CREATE FUNCTION opengeni_host_export.host_export_claim_sidecars(p_export_kind text, p_consumer_id text, p_lease_token uuid) RETURNS TABLE(export_cursor bigint, root_session_id uuid, payload_codec_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_consumer {{schema}}.host_export_consumers%ROWTYPE;
    BEGIN
      SELECT * INTO v_consumer
      FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind
        AND c.consumer_id = p_consumer_id
      FOR UPDATE;
      IF NOT FOUND
        OR v_consumer.lease_token IS DISTINCT FROM p_lease_token
        OR v_consumer.lease_from IS NULL
        OR v_consumer.lease_through IS NULL
        OR v_consumer.lease_expires_at IS NULL
        OR v_consumer.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'host export lease is not current'
          USING ERRCODE = '55000';
      END IF;

      RETURN QUERY
      SELECT o.export_cursor, o.root_session_id, o.payload_codec_version
      FROM {{schema}}.host_export_outbox o
      WHERE o.export_kind = p_export_kind
        AND o.export_cursor > v_consumer.lease_from
        AND o.export_cursor <= v_consumer.lease_through
      ORDER BY o.export_cursor;
    END $$;

CREATE FUNCTION opengeni_host_export.host_export_consumer_status(p_export_kind text, p_consumer_id text) RETURNS TABLE(export_kind text, consumer_id text, checkpoint bigint, enabled boolean, consecutive_failures integer, next_attempt_at timestamp with time zone, last_error text, last_error_at timestamp with time zone, blocked_at timestamp with time zone, lease_expires_at timestamp with time zone, max_cursor bigint, pending_count bigint, unassigned_count bigint, pruned_through bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT c.export_kind, c.consumer_id, c.checkpoint, c.enabled,
        c.consecutive_failures, c.next_attempt_at, c.last_error,
        c.last_error_at, c.blocked_at, c.lease_expires_at,
        greatest(s.next_cursor - 1, c.checkpoint),
        (
          SELECT count(*) FROM {{schema}}.host_export_outbox assigned
          WHERE assigned.export_kind = c.export_kind
            AND assigned.export_cursor > c.checkpoint
        ) + (
          SELECT count(*) FROM {{schema}}.host_export_outbox unassigned
          WHERE unassigned.export_kind = c.export_kind
            AND unassigned.export_cursor IS NULL
        ),
        (
          SELECT count(*) FROM {{schema}}.host_export_outbox unassigned
          WHERE unassigned.export_kind = c.export_kind
            AND unassigned.export_cursor IS NULL
        ),
        s.pruned_through
      FROM {{schema}}.host_export_consumers c
      JOIN {{schema}}.host_export_cursor_state s ON s.export_kind = c.export_kind
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id;
    $$;

CREATE FUNCTION opengeni_host_export.host_export_consumer_status_sidecar(p_export_kind text, p_consumer_id text) RETURNS TABLE(last_error_codec_version integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT c.last_error_codec_version
      FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id;
    $$;

CREATE FUNCTION opengeni_host_export.host_export_cursor_roots(p_export_kind text, p_consumer_id text, p_lease_token uuid) RETURNS TABLE(export_cursor bigint, root_session_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_consumer {{schema}}.host_export_consumers%ROWTYPE;
    BEGIN
      SELECT * INTO v_consumer
      FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind
        AND c.consumer_id = p_consumer_id
      FOR UPDATE;
      IF NOT FOUND
        OR v_consumer.lease_token IS DISTINCT FROM p_lease_token
        OR v_consumer.lease_from IS NULL
        OR v_consumer.lease_through IS NULL
        OR v_consumer.lease_expires_at IS NULL
        OR v_consumer.lease_expires_at <= now() THEN
        RAISE EXCEPTION 'host export lease is not current'
          USING ERRCODE = '55000';
      END IF;

      RETURN QUERY
      SELECT o.export_cursor, o.root_session_id
      FROM {{schema}}.host_export_outbox o
      WHERE o.export_kind = p_export_kind
        AND o.export_cursor > v_consumer.lease_from
        AND o.export_cursor <= v_consumer.lease_through
      ORDER BY o.export_cursor;
    END $$;

CREATE FUNCTION opengeni_host_export.prune_host_export_outbox(p_export_kind text, p_grace_seconds integer, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE v_checkpoint bigint; v_deleted integer; v_pruned_through bigint;
    BEGIN
      PERFORM 1 FROM {{schema}}.host_export_cursor_state s
      WHERE s.export_kind = p_export_kind
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown host export kind' USING ERRCODE = '22023';
      END IF;
      SELECT min(c.checkpoint) INTO v_checkpoint FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind;
      IF v_checkpoint IS NULL OR v_checkpoint = 0 THEN RETURN 0; END IF;
      WITH doomed AS (
        SELECT o.id FROM {{schema}}.host_export_outbox o
        WHERE o.export_kind = p_export_kind
          AND o.export_cursor <= v_checkpoint
          AND o.enqueued_at < now() - make_interval(
            secs => greatest(0, least(coalesce(p_grace_seconds, 3600), 604800))
          )
        ORDER BY o.export_cursor
        LIMIT greatest(1, least(coalesce(p_limit, 1000), 10000))
        FOR UPDATE SKIP LOCKED
      ), deleted AS (
        DELETE FROM {{schema}}.host_export_outbox o
        USING doomed d WHERE o.id = d.id
        RETURNING o.export_cursor
      )
      SELECT count(*)::integer, max(d.export_cursor)
      INTO v_deleted, v_pruned_through
      FROM deleted d;
      IF v_pruned_through IS NOT NULL THEN
        UPDATE {{schema}}.host_export_cursor_state s
        SET pruned_through = greatest(s.pruned_through, v_pruned_through),
            updated_at = now()
        WHERE s.export_kind = p_export_kind;
      END IF;
      RETURN v_deleted;
    END $$;

CREATE FUNCTION opengeni_host_export.register_host_export_consumer(p_export_kind text, p_consumer_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
    DECLARE v_checkpoint bigint;
    BEGIN
      IF p_export_kind NOT IN ('session_event', 'usage_event', 'lifecycle_fact') THEN
        RAISE EXCEPTION 'invalid host export kind' USING ERRCODE = '22023';
      END IF;
      IF p_consumer_id IS NULL OR length(p_consumer_id) NOT BETWEEN 1 AND 128
        OR p_consumer_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN
        RAISE EXCEPTION 'invalid host export consumer id' USING ERRCODE = '22023';
      END IF;

      SELECT s.pruned_through INTO v_checkpoint
      FROM {{schema}}.host_export_cursor_state s
      WHERE s.export_kind = p_export_kind
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown host export kind' USING ERRCODE = '22023';
      END IF;

      INSERT INTO {{schema}}.host_export_consumers (consumer_id, export_kind, checkpoint)
      VALUES (p_consumer_id, p_export_kind, v_checkpoint)
      ON CONFLICT (export_kind, consumer_id) DO UPDATE
      SET enabled = true, updated_at = now();

      UPDATE {{schema}}.host_export_config
      SET session_events_enabled = CASE WHEN p_export_kind = 'session_event' THEN true ELSE session_events_enabled END,
          usage_events_enabled = CASE WHEN p_export_kind = 'usage_event' THEN true ELSE usage_events_enabled END,
          lifecycle_facts_enabled = CASE WHEN p_export_kind = 'lifecycle_fact' THEN true ELSE lifecycle_facts_enabled END,
          updated_at = now()
      WHERE id = 1;
    END $_$;

CREATE FUNCTION opengeni_host_export.resume_host_export_consumer(p_export_kind text, p_consumer_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      UPDATE {{schema}}.host_export_consumers c
      SET blocked_at = NULL, consecutive_failures = 0, next_attempt_at = now(),
          lease_token = NULL, lease_holder_id = NULL, lease_expires_at = NULL,
          lease_from = NULL, lease_through = NULL,
          last_error = NULL, last_error_codec_version = NULL,
          last_error_at = NULL, updated_at = now()
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'host export consumer not found' USING ERRCODE = 'P0002';
      END IF;
    END $$;

CREATE FUNCTION opengeni_host_export.retire_host_export_consumer(p_export_kind text, p_consumer_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      PERFORM 1 FROM {{schema}}.host_export_cursor_state s
      WHERE s.export_kind = p_export_kind
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown host export kind' USING ERRCODE = '22023';
      END IF;

      DELETE FROM {{schema}}.host_export_consumers c
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'host export consumer not found' USING ERRCODE = 'P0002';
      END IF;

      IF NOT EXISTS (
        SELECT 1 FROM {{schema}}.host_export_consumers c
        WHERE c.export_kind = p_export_kind AND c.enabled
      ) THEN
        UPDATE {{schema}}.host_export_config
        SET session_events_enabled = CASE
              WHEN p_export_kind = 'session_event' THEN false
              ELSE session_events_enabled
            END,
            usage_events_enabled = CASE
              WHEN p_export_kind = 'usage_event' THEN false
              ELSE usage_events_enabled
            END,
            lifecycle_facts_enabled = CASE
              WHEN p_export_kind = 'lifecycle_fact' THEN false
              ELSE lifecycle_facts_enabled
            END,
            updated_at = now()
        WHERE id = 1;
      END IF;
    END $$;

CREATE FUNCTION opengeni_host_export.rewind_host_export_consumer(p_export_kind text, p_consumer_id text, p_checkpoint bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE v_pruned_through bigint; v_max bigint;
    BEGIN
      IF p_checkpoint < 0 THEN RAISE EXCEPTION 'checkpoint must be nonnegative' USING ERRCODE = '22023'; END IF;
      SELECT s.pruned_through, s.next_cursor - 1
      INTO v_pruned_through, v_max
      FROM {{schema}}.host_export_cursor_state s
      WHERE s.export_kind = p_export_kind
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown host export kind' USING ERRCODE = '22023';
      END IF;
      IF p_checkpoint < v_pruned_through THEN
        RAISE EXCEPTION 'requested host export cursor is no longer retained' USING ERRCODE = '22023';
      END IF;
      IF p_checkpoint > v_max THEN
        RAISE EXCEPTION 'requested host export cursor has not been allocated' USING ERRCODE = '22023';
      END IF;
      UPDATE {{schema}}.host_export_consumers c
      SET checkpoint = p_checkpoint, blocked_at = NULL, consecutive_failures = 0,
          next_attempt_at = now(), lease_token = NULL, lease_holder_id = NULL,
          lease_expires_at = NULL, lease_from = NULL, lease_through = NULL,
          updated_at = now()
      WHERE c.export_kind = p_export_kind AND c.consumer_id = p_consumer_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'host export consumer not found' USING ERRCODE = 'P0002'; END IF;
    END $$;

CREATE FUNCTION opengeni_insights_internal.insights_usage_amount_inputs(a uuid, w uuid, lo timestamp with time zone, hi timestamp with time zone, p_granularity text) RETURNS TABLE(session_id uuid, provider text, model text, payer text, scheduled_task_id uuid, occurred_at timestamp with time zone, recorded_at timestamp with time zone, m jsonb, charge_row boolean)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $_$
    BEGIN
      -- EXECUTE alone must never expose an intermediate private identity or
      -- per-call amount. The approved definer calls this as the schema owner.
      IF current_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='{{schema}}.model_call_facts'::regclass)) THEN
        RAISE EXCEPTION 'Insights input is owner-invoked only' USING ERRCODE='42501';END IF;
      
      -- Complete UTC hours use rollups; each ragged edge uses an exact raw
      -- predicate. Even a sub-hour request reads each fact exactly once.
      RETURN QUERY WITH bounds AS (
        SELECT CASE WHEN lo=date_trunc('hour',lo AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' THEN lo
          ELSE (date_trunc('hour',lo AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')+interval '1 hour' END AS first_hour,
          date_trunc('hour',hi AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS last_hour
      ), amounts AS (
        SELECT r.* FROM opengeni_private.insights_usage_hourly_rollups r CROSS JOIN bounds b
          WHERE r.account_id=a AND r.workspace_id=w AND r.hour>=b.first_hour AND r.hour<b.last_hour
        UNION ALL SELECT r.* FROM bounds b CROSS JOIN LATERAL
          opengeni_insights_internal.insights_usage_hourly_scan(a,w,lo,least(hi,b.first_hour)) r WHERE lo<b.first_hour
        UNION ALL SELECT r.* FROM bounds b CROSS JOIN LATERAL
          opengeni_insights_internal.insights_usage_hourly_scan(a,w,greatest(lo,b.last_hour),hi) r
          WHERE hi>b.last_hour AND b.last_hour>=b.first_hour
      
      ), bucketed AS (
        SELECT r.account_id,r.workspace_id,
          date_trunc(p_granularity,r.hour AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour,
          r.session_id,r.provider,r.model,r.payer,r.scheduled_task_id,max(r.recorded_at) AS recorded_at,
          sum(r.calls)::bigint AS calls,sum(r."tokenKnownCalls")::bigint AS "tokenKnownCalls",
          sum(r."cacheKnownCalls")::bigint AS "cacheKnownCalls",sum(r."cacheWriteKnownCalls")::bigint AS "cacheWriteKnownCalls",
          sum(r."listClassKnownCalls")::bigint AS "listClassKnownCalls",sum(r."uncachedInput")::bigint AS "uncachedInput",
          sum(r."cacheRead")::bigint AS "cacheRead",sum(r."cacheWrite")::bigint AS "cacheWrite",
          sum(r.output)::bigint AS output,sum(r.reasoning)::bigint AS reasoning,sum(r."listMicros")::bigint AS "listMicros",
          sum(r."pricedCalls")::bigint AS "pricedCalls",sum(r."listApproxCalls")::bigint AS "listApproxCalls",
          sum(r."listUncachedInput")::bigint AS "listUncachedInput",sum(r."listCacheRead")::bigint AS "listCacheRead",
          sum(r."listCacheWrite")::bigint AS "listCacheWrite",sum(r."listOutput")::bigint AS "listOutput"
        FROM amounts r GROUP BY r.account_id,r.workspace_id,3,r.session_id,r.provider,r.model,r.payer,r.scheduled_task_id
      ) SELECT r.session_id,r.provider,r.model,r.payer,r.scheduled_task_id,r.hour,r.recorded_at,
        (to_jsonb(r)-ARRAY['account_id','workspace_id','hour','session_id','provider','model','payer','scheduled_task_id','recorded_at'])
          ||jsonb_build_object('chargedMicros',0),false FROM bucketed r;
      RETURN QUERY SELECT coalesce(f.session_id,CASE WHEN c.metadata->>'sessionId'~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN(c.metadata->>'sessionId')::uuid END),
        f.provider,f.model,'opengeni_credits',f.scheduled_task_id,c.occurred_at,null::timestamptz,
        jsonb_build_object('calls',0,'tokenKnownCalls',0,'cacheKnownCalls',0,'cacheWriteKnownCalls',0,'listClassKnownCalls',0,
          'uncachedInput',0,'cacheRead',0,'cacheWrite',0,'output',0,'reasoning',0,'chargedMicros',-c.amount_micros,
          'listMicros',0,'pricedCalls',0,'listApproxCalls',0,'listUncachedInput',0,'listCacheRead',0,'listCacheWrite',0,'listOutput',0),true
      FROM {{schema}}.credit_ledger_entries c LEFT JOIN {{schema}}.model_call_facts f ON f.account_id=c.account_id AND f.workspace_id=c.workspace_id
        AND f.turn_id=CASE WHEN c.source_id~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}:.' THEN left(c.source_id,36)::uuid END
        AND f.source_key=substr(c.source_id,38)
      WHERE c.account_id=a AND c.workspace_id IS NOT DISTINCT FROM w AND c.type='model_usage_debit'
        AND c.source_type='model_response' AND c.amount_micros<0 AND c.occurred_at>=lo AND c.occurred_at<hi;
    END
    $_$;

CREATE FUNCTION opengeni_insights_internal.insights_usage_hour_lock(w uuid, h timestamp with time zone) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT hashtextextended('insights-usage-hour:'||w::text||':'||extract(epoch FROM h)::bigint::text,0)
$$;

CREATE TABLE opengeni_private.insights_usage_hourly_rollups (
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    hour timestamp with time zone NOT NULL,
    session_id uuid,
    provider text NOT NULL,
    model text NOT NULL,
    payer text NOT NULL,
    scheduled_task_id uuid,
    recorded_at timestamp with time zone,
    calls bigint NOT NULL,
    "tokenKnownCalls" bigint NOT NULL,
    "cacheKnownCalls" bigint NOT NULL,
    "cacheWriteKnownCalls" bigint NOT NULL,
    "listClassKnownCalls" bigint NOT NULL,
    "uncachedInput" bigint NOT NULL,
    "cacheRead" bigint NOT NULL,
    "cacheWrite" bigint NOT NULL,
    output bigint NOT NULL,
    reasoning bigint NOT NULL,
    "listMicros" bigint NOT NULL,
    "pricedCalls" bigint NOT NULL,
    "listApproxCalls" bigint NOT NULL,
    "listUncachedInput" bigint NOT NULL,
    "listCacheRead" bigint NOT NULL,
    "listCacheWrite" bigint NOT NULL,
    "listOutput" bigint NOT NULL
);

CREATE FUNCTION opengeni_insights_internal.insights_usage_hourly_delta(v opengeni_private.insights_usage_hourly_rollups, d bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE latest timestamptz; remaining bigint;
    BEGIN
      -- A workspace cascade has already removed its parent; do not resurrect
      -- a rollup through the fact table's own cascading deletes.
      IF d<0 AND NOT EXISTS(SELECT 1 FROM {{schema}}.workspaces WHERE id=v.workspace_id) THEN RETURN; END IF;
      INSERT INTO opengeni_private.insights_usage_hourly_rollups AS r
      SELECT v.account_id,v.workspace_id,v.hour,v.session_id,v.provider,v.model,v.payer,v.scheduled_task_id,v.recorded_at,
        d*v.calls,d*v."tokenKnownCalls",d*v."cacheKnownCalls",d*v."cacheWriteKnownCalls",d*v."listClassKnownCalls",
        d*v."uncachedInput",d*v."cacheRead",d*v."cacheWrite",d*v.output,d*v.reasoning,d*v."listMicros",d*v."pricedCalls",
        d*v."listApproxCalls",d*v."listUncachedInput",d*v."listCacheRead",d*v."listCacheWrite",d*v."listOutput"
      ON CONFLICT(account_id,workspace_id,hour,session_id,provider,model,payer,scheduled_task_id) DO UPDATE SET
        recorded_at=CASE WHEN d>0 THEN greatest(r.recorded_at,excluded.recorded_at) ELSE r.recorded_at END,
        calls=r.calls+excluded.calls,"tokenKnownCalls"=r."tokenKnownCalls"+excluded."tokenKnownCalls",
        "cacheKnownCalls"=r."cacheKnownCalls"+excluded."cacheKnownCalls",
        "cacheWriteKnownCalls"=r."cacheWriteKnownCalls"+excluded."cacheWriteKnownCalls",
        "listClassKnownCalls"=r."listClassKnownCalls"+excluded."listClassKnownCalls",
        "uncachedInput"=r."uncachedInput"+excluded."uncachedInput","cacheRead"=r."cacheRead"+excluded."cacheRead",
        "cacheWrite"=r."cacheWrite"+excluded."cacheWrite",output=r.output+excluded.output,reasoning=r.reasoning+excluded.reasoning,
        "listMicros"=r."listMicros"+excluded."listMicros","pricedCalls"=r."pricedCalls"+excluded."pricedCalls",
        "listApproxCalls"=r."listApproxCalls"+excluded."listApproxCalls",
        "listUncachedInput"=r."listUncachedInput"+excluded."listUncachedInput","listCacheRead"=r."listCacheRead"+excluded."listCacheRead",
        "listCacheWrite"=r."listCacheWrite"+excluded."listCacheWrite","listOutput"=r."listOutput"+excluded."listOutput"
      RETURNING r.recorded_at,r.calls INTO latest,remaining;
      IF d<0 THEN
        IF remaining=0 THEN
          DELETE FROM opengeni_private.insights_usage_hourly_rollups r WHERE r.account_id=v.account_id AND r.workspace_id=v.workspace_id
            AND r.hour=v.hour AND r.session_id IS NOT DISTINCT FROM v.session_id AND r.provider=v.provider AND r.model=v.model
            AND r.payer=v.payer AND r.scheduled_task_id IS NOT DISTINCT FROM v.scheduled_task_id;
        ELSIF latest<=v.recorded_at THEN
          -- The upsert holds the group row lock. A concurrent delta cannot
          -- overwrite the repaired max, including a move between groups.
          UPDATE opengeni_private.insights_usage_hourly_rollups r SET recorded_at=(
            SELECT x.recorded_at FROM opengeni_insights_internal.insights_usage_hourly_raw(v.account_id,v.workspace_id,v.hour,v.hour+interval '1 hour') x
            WHERE x.session_id IS NOT DISTINCT FROM v.session_id AND x.provider=v.provider AND x.model=v.model
              AND x.payer=v.payer AND x.scheduled_task_id IS NOT DISTINCT FROM v.scheduled_task_id
          ) WHERE r.account_id=v.account_id AND r.workspace_id=v.workspace_id AND r.hour=v.hour
            AND r.session_id IS NOT DISTINCT FROM v.session_id AND r.provider=v.provider AND r.model=v.model
            AND r.payer=v.payer AND r.scheduled_task_id IS NOT DISTINCT FROM v.scheduled_task_id;
        END IF;
      END IF;
    END
    $$;

CREATE FUNCTION opengeni_insights_internal.insights_usage_hourly_maintain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE old_value opengeni_private.insights_usage_hourly_rollups; new_value opengeni_private.insights_usage_hourly_rollups;
      old_lock bigint;new_lock bigint;
    BEGIN
      IF TG_OP<>'INSERT' THEN
        old_value:=opengeni_insights_internal.insights_usage_hourly_value(OLD);
        old_lock:=opengeni_insights_internal.insights_usage_hour_lock(old_value.workspace_id,old_value.hour);
      END IF;
      IF TG_OP<>'DELETE' THEN
        new_value:=opengeni_insights_internal.insights_usage_hourly_value(NEW);
        new_lock:=opengeni_insights_internal.insights_usage_hour_lock(new_value.workspace_id,new_value.hour);
      END IF;
      IF TG_OP='UPDATE' AND old_value IS NOT DISTINCT FROM new_value THEN RETURN NULL; END IF;
      -- Deterministic ordering when an UPDATE moves across hours/workspaces.
      PERFORM pg_advisory_xact_lock_shared(least(old_lock,new_lock));
      IF old_lock IS DISTINCT FROM new_lock THEN
        PERFORM pg_advisory_xact_lock_shared(greatest(old_lock,new_lock));
      END IF;
      IF TG_OP<>'INSERT' THEN PERFORM opengeni_insights_internal.insights_usage_hourly_delta(old_value,-1); END IF;
      IF TG_OP<>'DELETE' THEN PERFORM opengeni_insights_internal.insights_usage_hourly_delta(new_value,1); END IF;
      RETURN NULL;
    END
    $$;

CREATE FUNCTION opengeni_insights_internal.insights_usage_hourly_raw(a uuid, w uuid, lo timestamp with time zone, hi timestamp with time zone) RETURNS SETOF opengeni_private.insights_usage_hourly_rollups
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE prior_account text:=current_setting('opengeni.account_id',true);
      prior_workspace text:=current_setting('opengeni.workspace_id',true);
      prior_cap opengeni_private.insights_fact_read_runtime_capabilities;
    BEGIN
      IF current_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='{{schema}}.model_call_facts'::regclass)) THEN
        RAISE EXCEPTION 'Insights hourly raw input is owner-invoked only' USING ERRCODE='42501'; END IF;
      -- Account-only ledger rows have no fact workspace. Match the old
      -- f.workspace_id=w predicate without trying to mint a NULL capability.
      IF w IS NULL OR lo>=hi THEN RETURN; END IF;
      SELECT * INTO prior_cap FROM opengeni_private.insights_fact_read_runtime_capabilities
        WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND capability_kind='model_call_facts';
      PERFORM set_config('opengeni.account_id',a::text,true),set_config('opengeni.workspace_id',w::text,true);
      INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities
        (backend_pid,transaction_id,capability_kind,account_id,workspace_id,subject_id,initiating_human_subject_id)
      VALUES(pg_backend_pid(),pg_current_xact_id(),'model_call_facts',a,w,
        nullif(current_setting('opengeni.subject_id',true),''),nullif(current_setting('opengeni.initiating_human_subject_id',true),''))
      ON CONFLICT(backend_pid,transaction_id,capability_kind) DO UPDATE SET
        account_id=excluded.account_id,workspace_id=excluded.workspace_id,
        subject_id=excluded.subject_id,initiating_human_subject_id=excluded.initiating_human_subject_id;
      RETURN QUERY SELECT * FROM opengeni_insights_internal.insights_usage_hourly_scan(a,w,lo,hi);
      DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
        WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id() AND capability_kind='model_call_facts';
      IF prior_cap.backend_pid IS NOT NULL THEN
        INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities SELECT prior_cap.*;
      END IF;
      PERFORM set_config('opengeni.account_id',coalesce(prior_account,''),true),
        set_config('opengeni.workspace_id',coalesce(prior_workspace,''),true);
    EXCEPTION WHEN OTHERS THEN
      -- The subtransaction rolls back capability changes before this handler.
      PERFORM set_config('opengeni.account_id',coalesce(prior_account,''),true),
        set_config('opengeni.workspace_id',coalesce(prior_workspace,''),true);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_insights_internal.insights_usage_hourly_recompute(a uuid, w uuid, h timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    BEGIN
      IF current_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='{{schema}}.model_call_facts'::regclass)) THEN
        RAISE EXCEPTION 'Insights hourly recompute is owner-invoked only' USING ERRCODE='42501'; END IF;
      IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION 'Hourly recompute requires READ COMMITTED' USING ERRCODE='25001'; END IF;
      IF h IS NULL OR NOT isfinite(h) OR h IS DISTINCT FROM date_trunc('hour',h AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' THEN
        RAISE EXCEPTION 'Expected a finite UTC hour' USING ERRCODE='22023'; END IF;
      -- Match the FK writer prefix before the hour fence. Otherwise workspace
      -- deletion could hold its parent row while waiting for our hourly lock,
      -- and our rebuilt INSERT would wait for that same parent FK lock.
      PERFORM 1 FROM {{schema}}.workspaces WHERE account_id=a AND id=w FOR KEY SHARE;
      IF NOT FOUND THEN RETURN true; END IF;
      PERFORM pg_advisory_xact_lock(opengeni_insights_internal.insights_usage_hour_lock(w,h));
      -- VOLATILE + READ COMMITTED: take the raw snapshot AFTER acquiring the
      -- fence, not in the statement that waited for a concurrent fact writer.
      DELETE FROM opengeni_private.insights_usage_hourly_rollups WHERE account_id=a AND workspace_id=w AND hour=h;
      INSERT INTO opengeni_private.insights_usage_hourly_rollups
        SELECT * FROM opengeni_insights_internal.insights_usage_hourly_raw(a,w,h,h+interval '1 hour');
      RETURN true;
    END
    $$;

CREATE FUNCTION opengeni_insights_internal.insights_usage_hourly_scan(a uuid, w uuid, lo timestamp with time zone, hi timestamp with time zone) RETURNS SETOF opengeni_private.insights_usage_hourly_rollups
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
      WITH fact_values AS MATERIALIZED(
        SELECT opengeni_insights_internal.insights_usage_hourly_value(f) v FROM {{schema}}.model_call_facts f
        WHERE f.account_id=a AND f.workspace_id=w AND f.occurred_at>=lo AND f.occurred_at<hi
      ) SELECT a,w,(v).hour,(v).session_id,(v).provider,(v).model,(v).payer,(v).scheduled_task_id,max((v).recorded_at),
        sum((v).calls)::bigint,sum((v)."tokenKnownCalls")::bigint,sum((v)."cacheKnownCalls")::bigint,
        sum((v)."cacheWriteKnownCalls")::bigint,sum((v)."listClassKnownCalls")::bigint,sum((v)."uncachedInput")::bigint,
        sum((v)."cacheRead")::bigint,sum((v)."cacheWrite")::bigint,sum((v).output)::bigint,sum((v).reasoning)::bigint,
        sum((v)."listMicros")::bigint,sum((v)."pricedCalls")::bigint,sum((v)."listApproxCalls")::bigint,
        sum((v)."listUncachedInput")::bigint,sum((v)."listCacheRead")::bigint,sum((v)."listCacheWrite")::bigint,sum((v)."listOutput")::bigint
      FROM fact_values GROUP BY (v).hour,(v).session_id,(v).provider,(v).model,(v).payer,(v).scheduled_task_id
    $$;

CREATE FUNCTION opengeni_private.model_context_contributions_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  contribution jsonb;
  contribution_source text;
  metric text;
  seen_sources text[] := ARRAY[]::text[];
BEGIN
  IF value IS NULL THEN
    RETURN true;
  END IF;
  IF jsonb_typeof(value) <> 'array'
    OR jsonb_array_length(value) > 6
    OR octet_length(value::text) > 8192
  THEN
    RETURN false;
  END IF;

  FOR contribution IN SELECT element FROM jsonb_array_elements(value) AS entries(element)
  LOOP
    IF jsonb_typeof(contribution) <> 'object'
      OR (SELECT count(*) FROM pg_catalog.jsonb_object_keys(contribution)) <> 4
      OR NOT (contribution ?& ARRAY['source', 'items', 'utf8Bytes', 'estimatedTokens'])
    THEN
      RETURN false;
    END IF;

    contribution_source := contribution->>'source';
    IF contribution_source NOT IN (
      'workspace_instruction_policy',
      'legacy_workspace_instructions',
      'preference_registry_descriptor',
      'company_profile',
      'legacy_memory_v1',
      'runtime_skill_catalog'
    ) OR contribution_source = ANY(seen_sources)
    THEN
      RETURN false;
    END IF;
    seen_sources := array_append(seen_sources, contribution_source);

    FOREACH metric IN ARRAY ARRAY['items', 'utf8Bytes', 'estimatedTokens']
    LOOP
      IF jsonb_typeof(contribution->metric) <> 'number'
        OR contribution->>metric !~ '^(0|[1-9][0-9]{0,15})$'
        OR (contribution->>metric)::numeric > 9007199254740991
      THEN
        RETURN false;
      END IF;
    END LOOP;
  END LOOP;
  RETURN true;
END;
$_$;

CREATE TABLE model_call_facts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid NOT NULL,
    turn_attempt_id uuid,
    source_key text NOT NULL,
    provider text NOT NULL,
    provider_api text NOT NULL,
    model text NOT NULL,
    billing_path text NOT NULL,
    turn_source text,
    initiator_kind text,
    initiator_subject_id text,
    scheduled_task_id uuid,
    input_tokens bigint,
    output_tokens bigint,
    cached_tokens bigint,
    cache_write_tokens bigint,
    reasoning_tokens bigint,
    total_tokens bigint,
    priced_cost_micros bigint DEFAULT 0 NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    estimated_provider_cost_micros bigint,
    pricing_source text,
    context_contributions jsonb,
    equivalent_credit_cost_micros bigint,
    list_uncached_input_cost_micros bigint,
    list_cache_read_cost_micros bigint,
    list_cache_write_cost_micros bigint,
    list_output_cost_micros bigint,
    list_cost_is_approx boolean,
    connection_id uuid,
    site_id uuid,
    pre_dispatch_ms integer,
    time_to_first_token_ms integer,
    time_to_first_text_ms integer,
    duration_ms integer,
    CONSTRAINT model_call_facts_billing_path_check CHECK ((billing_path = ANY (ARRAY['opengeni_credits'::text, 'external'::text]))),
    CONSTRAINT model_call_facts_context_contributions_check CHECK (opengeni_private.model_context_contributions_valid(context_contributions)),
    CONSTRAINT model_call_facts_equivalent_credit_cost_check CHECK (((equivalent_credit_cost_micros IS NULL) OR ((equivalent_credit_cost_micros >= 0) AND (estimated_provider_cost_micros IS NOT NULL)))),
    CONSTRAINT model_call_facts_estimated_provider_cost_check CHECK (((estimated_provider_cost_micros IS NULL) OR (estimated_provider_cost_micros >= 0))),
    CONSTRAINT model_call_facts_initiator_check CHECK ((((initiator_kind IS NULL) AND (initiator_subject_id IS NULL)) OR ((initiator_kind = ANY (ARRAY['subject'::text, 'service'::text])) AND (initiator_subject_id IS NOT NULL) AND ((octet_length(initiator_subject_id) >= 1) AND (octet_length(initiator_subject_id) <= 1024))))),
    CONSTRAINT model_call_facts_list_cache_read_cost_micros_check CHECK ((list_cache_read_cost_micros >= 0)),
    CONSTRAINT model_call_facts_list_cache_write_cost_micros_check CHECK ((list_cache_write_cost_micros >= 0)),
    CONSTRAINT model_call_facts_list_classes_check CHECK ((((list_uncached_input_cost_micros IS NULL) AND (list_cache_read_cost_micros IS NULL) AND (list_cache_write_cost_micros IS NULL) AND (list_output_cost_micros IS NULL)) OR ((estimated_provider_cost_micros IS NOT NULL) AND (list_cost_is_approx IS NOT NULL) AND (list_uncached_input_cost_micros IS NOT NULL) AND (list_cache_read_cost_micros IS NOT NULL) AND (list_cache_write_cost_micros IS NOT NULL) AND (list_output_cost_micros IS NOT NULL) AND ((estimated_provider_cost_micros)::numeric = ((((list_uncached_input_cost_micros)::numeric + (list_cache_read_cost_micros)::numeric) + (list_cache_write_cost_micros)::numeric) + (list_output_cost_micros)::numeric))))),
    CONSTRAINT model_call_facts_list_output_cost_micros_check CHECK ((list_output_cost_micros >= 0)),
    CONSTRAINT model_call_facts_list_uncached_input_cost_micros_check CHECK ((list_uncached_input_cost_micros >= 0)),
    CONSTRAINT model_call_facts_model_bytes_check CHECK (((octet_length(model) >= 1) AND (octet_length(model) <= 512))),
    CONSTRAINT model_call_facts_priced_cost_check CHECK ((priced_cost_micros >= 0)),
    CONSTRAINT model_call_facts_pricing_source_check CHECK ((((estimated_provider_cost_micros IS NULL) AND (pricing_source IS NULL)) OR ((estimated_provider_cost_micros IS NOT NULL) AND (pricing_source = ANY (ARRAY['configured_list_price'::text, 'gateway_reported'::text]))))),
    CONSTRAINT model_call_facts_provider_api_bytes_check CHECK (((octet_length(provider_api) >= 1) AND (octet_length(provider_api) <= 256))),
    CONSTRAINT model_call_facts_provider_bytes_check CHECK (((octet_length(provider) >= 1) AND (octet_length(provider) <= 256))),
    CONSTRAINT model_call_facts_source_key_bytes_check CHECK (((octet_length(source_key) >= 1) AND (octet_length(source_key) <= 1024)))
);

ALTER TABLE ONLY model_call_facts FORCE ROW LEVEL SECURITY;

COMMENT ON COLUMN model_call_facts.pre_dispatch_ms IS 'Opengeni work from SDK model entry to the call''s first provider dispatch, in milliseconds.';

COMMENT ON COLUMN model_call_facts.time_to_first_token_ms IS 'First provider dispatch to the first streamed reasoning or answer fragment, in milliseconds.';

COMMENT ON COLUMN model_call_facts.time_to_first_text_ms IS 'First provider dispatch to the first streamed answer text fragment, in milliseconds.';

COMMENT ON COLUMN model_call_facts.duration_ms IS 'First provider dispatch to the terminal response as read by the worker, in milliseconds. Retries and provider continuations are included.';

CREATE FUNCTION opengeni_insights_internal.insights_usage_hourly_value(f model_call_facts) RETURNS opengeni_private.insights_usage_hourly_rollups
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'opengeni_private'
    AS $$
      SELECT ROW(f.account_id,f.workspace_id,date_trunc('hour',f.occurred_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC',
        f.session_id,f.provider,f.model,opengeni_private.insights_usage_payer(f.provider,f.billing_path),f.scheduled_task_id,
        f.recorded_at,1,
        CASE WHEN f.total_tokens IS NOT NULL THEN 1 ELSE 0 END,
        CASE WHEN f.input_tokens IS NOT NULL AND f.cached_tokens IS NOT NULL THEN 1 ELSE 0 END,
        CASE WHEN f.cache_write_tokens IS NOT NULL THEN 1 ELSE 0 END,
        CASE WHEN f.list_uncached_input_cost_micros IS NOT NULL THEN 1 ELSE 0 END,
        CASE WHEN f.input_tokens IS NOT NULL AND f.cached_tokens IS NOT NULL AND f.cache_write_tokens IS NOT NULL
          AND f.input_tokens>=0 AND f.cached_tokens>=0 AND f.cache_write_tokens>=0
          AND f.cached_tokens::numeric+f.cache_write_tokens::numeric<=f.input_tokens::numeric
          THEN f.input_tokens-f.cached_tokens-f.cache_write_tokens ELSE 0 END,
        coalesce(f.cached_tokens,0),coalesce(f.cache_write_tokens,0),coalesce(f.output_tokens,0),coalesce(f.reasoning_tokens,0),
        coalesce(f.estimated_provider_cost_micros,0),CASE WHEN f.estimated_provider_cost_micros IS NOT NULL THEN 1 ELSE 0 END,
        CASE WHEN f.list_cost_is_approx THEN 1 ELSE 0 END,coalesce(f.list_uncached_input_cost_micros,0),
        coalesce(f.list_cache_read_cost_micros,0),coalesce(f.list_cache_write_cost_micros,0),coalesce(f.list_output_cost_micros,0)
      )::opengeni_private.insights_usage_hourly_rollups
    $$;

CREATE FUNCTION opengeni_private.abandon_session_content_archive(p_workspace_id uuid, p_session_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  target record;
  planned_key text;
BEGIN
  PERFORM acquire_session_tenancy_fence(p_workspace_id);
  SELECT account_id, content_archive_state, content_archive INTO target
  FROM sessions WHERE workspace_id = p_workspace_id AND id = p_session_id
  FOR NO KEY UPDATE;
  IF NOT FOUND OR target.content_archive_state IS DISTINCT FROM 'archiving' THEN
    RETURN false;
  END IF;
  FOR planned_key IN
    SELECT value FROM jsonb_array_elements_text(
      coalesce(target.content_archive->'objectKeys', '[]'::jsonb))
  LOOP
    INSERT INTO opengeni_private.session_archive_object_deletions
      (object_key, account_id, workspace_id, session_id)
    VALUES (planned_key, target.account_id, p_workspace_id, p_session_id)
    ON CONFLICT (object_key) DO NOTHING;
  END LOOP;
  UPDATE sessions
  SET content_archive_state = NULL, content_archive_started_at = NULL, content_archive = NULL
  WHERE workspace_id = p_workspace_id AND id = p_session_id;
  RETURN true;
END;
$$;

CREATE FUNCTION opengeni_private.accept_session_file_attachments(p_account uuid, p_workspace uuid, p_session uuid, p_turn uuid, p_subject text, p_files uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE accepted_turn record;
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR p_subject IS NULL OR p_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_subject IS DISTINCT FROM nullif(current_setting('opengeni.private_file_owner',true),'')
    OR cardinality(p_files)>1000
  THEN RAISE EXCEPTION 'attachment acceptance scope mismatch' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM sessions WHERE account_id=p_account AND workspace_id=p_workspace AND id=p_session
    AND (visibility='workspace_shared' OR session_private_actor_visible(account_id,workspace_id,owner_organization_membership_id,owner_subject_id)) FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'attachment session unavailable' USING ERRCODE='42501'; END IF;
  IF p_turn IS NULL THEN
    PERFORM 1 FROM sessions WHERE account_id=p_account AND workspace_id=p_workspace AND id=p_session
      AND imported_archive_import_id IS NOT NULL AND imported_archive_subject_id=p_subject
      AND created_by_kind='subject' AND created_by_subject_id=p_subject;
    IF NOT FOUND THEN RAISE EXCEPTION 'attachment requires accepted human archive' USING ERRCODE='42501'; END IF;
    INSERT INTO opengeni_private.session_file_attachments(account_id,workspace_id,session_id,file_id,accepted_by,accepted_event_id)
      SELECT p_account,p_workspace,p_session,f.id,p_subject,accepted.id FROM files f
      CROSS JOIN LATERAL (
        SELECT e.id FROM session_events e
        WHERE e.account_id=p_account AND e.workspace_id=p_workspace AND e.session_id=p_session
          AND EXISTS (SELECT 1 FROM (
            SELECT jsonb_path_query(e.payload,'lax $.**.fileId') AS ref
            UNION ALL SELECT jsonb_path_query(e.payload,'lax $.**.fileIds[*]') AS ref
          ) refs WHERE lower(refs.ref#>>'{}')=f.id::text)
        ORDER BY e.sequence LIMIT 1
      ) accepted
      WHERE f.account_id=p_account AND f.workspace_id=p_workspace AND f.id=ANY(p_files) AND f.status='ready'
        AND p_subject=ANY(f.private_owner_subject_ids)
        AND EXISTS (SELECT 1 FROM file_uploads u WHERE u.account_id=p_account AND u.workspace_id=p_workspace
          AND u.file_id=f.id AND u.status='completed' AND u.private_file_owner_subject_id=p_subject)
        AND google_drive_file_authorized(p_account,p_workspace,p_subject,f.id)
      ON CONFLICT DO NOTHING;
    RETURN;
  END IF;
  SELECT t.* INTO accepted_turn FROM session_turns t WHERE t.account_id=p_account AND t.workspace_id=p_workspace
    AND t.session_id=p_session AND t.id=p_turn AND t.source IN ('user','api')
    AND t.initiator_kind='subject' AND t.initiator_subject_id=p_subject;
  IF NOT FOUND THEN RAISE EXCEPTION 'attachment requires accepted human input' USING ERRCODE='42501'; END IF;
  -- Preserve the ordinary accepted-input path exactly, including its completed
  -- original-upload gate; provider originals never gain a session grant.
  INSERT INTO opengeni_private.session_file_attachments(account_id,workspace_id,session_id,file_id,accepted_by,accepted_event_id)
    SELECT p_account,p_workspace,p_session,f.id,p_subject,accepted_turn.trigger_event_id FROM files f
    WHERE f.account_id=p_account AND f.workspace_id=p_workspace AND f.id=ANY(p_files) AND f.status='ready'
      AND p_subject=ANY(f.private_owner_subject_ids)
      AND EXISTS (SELECT 1 FROM session_events e CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(e.payload->'resources')='array' THEN e.payload->'resources' ELSE '[]'::jsonb END) r
        WHERE e.account_id=p_account AND e.workspace_id=p_workspace AND e.session_id=p_session
          AND r->>'kind'='file' AND r->>'fileId'=f.id::text
          AND ((e.id=accepted_turn.trigger_event_id AND e.type='user.message') OR (
            e.type='session.created' AND e.payload#>>'{createdBy,kind}'='subject'
            AND e.payload#>>'{createdBy,subjectId}'=p_subject
            AND NOT EXISTS (SELECT 1 FROM session_events prior, session_events current_input
              WHERE prior.account_id=p_account AND prior.workspace_id=p_workspace AND prior.session_id=p_session
              AND current_input.id=accepted_turn.trigger_event_id AND current_input.session_id=p_session
              AND prior.type='user.message' AND prior.sequence<current_input.sequence))))
      AND EXISTS (SELECT 1 FROM file_uploads u WHERE u.account_id=p_account AND u.workspace_id=p_workspace
        AND u.file_id=f.id AND u.status='completed' AND u.private_file_owner_subject_id=p_subject)
      AND google_drive_file_authorized(p_account,p_workspace,p_subject,f.id)
    ON CONFLICT DO NOTHING;
END $_$;

CREATE FUNCTION opengeni_private.account_rls_visible(account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT account_id = opengeni_private.current_account_id();
$$;

CREATE FUNCTION opengeni_private.active_external_owning_subject(p_account_id uuid, p_subject_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  result boolean;
  previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF p_account_id IS NULL OR p_subject_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
  THEN RETURN false; END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'external_identity_provisioning', true);
  SELECT EXISTS (
    SELECT 1 FROM external_identities identity_row
    JOIN organization_memberships membership
      ON membership.id = identity_row.organization_membership_id
      AND membership.account_id = identity_row.account_id
      AND membership.subject_id = identity_row.subject_id
      AND membership.personal_workspace_id = identity_row.personal_workspace_id
    WHERE identity_row.account_id = p_account_id AND identity_row.subject_id = p_subject_id
      AND identity_row.status = 'active' AND membership.status = 'active'
  ) INTO result;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
  RAISE;
END
$$;

CREATE FUNCTION opengeni_private.advance_editable_artifact_authorization_revision(p_account_id uuid, p_workspace_id uuid, p_artifact_id text, p_expected_revision bigint, p_next_revision bigint, p_data_schema name DEFAULT "current_schema"()) RETURNS TABLE(applied boolean, authorization_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE affected integer;
DECLARE current_revision bigint;
DECLARE data_schema name;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_artifact_id IS NULL
    OR p_data_schema IS NULL
    OR p_artifact_id !~ '^[0-9a-f]{32}$' OR p_artifact_id ~ '^0+$'
    OR p_expected_revision IS NULL
    OR p_expected_revision NOT BETWEEN 0 AND 9007199254740991
    OR p_next_revision IS NULL
    OR p_next_revision NOT BETWEEN 1 AND 9007199254740991
    OR p_next_revision <= p_expected_revision
  THEN
    RAISE EXCEPTION 'invalid editable artifact authorization revision bounds'
      USING ERRCODE = '22023';
  END IF;
  IF NOT opengeni_private.editable_artifact_scope_matches_context(
    p_account_id, p_workspace_id
  ) THEN
    RAISE EXCEPTION 'editable artifact authorization scope is unavailable'
      USING ERRCODE = '42501';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  EXECUTE pg_catalog.format($query$
    UPDATE %I.editable_artifacts target
    SET authorization_revision = $4,
      updated_at = GREATEST(
        target.updated_at, pg_catalog.statement_timestamp()
      )
    WHERE target.account_id = $1
      AND target.workspace_id = $2
      AND target.id = $3
      AND target.authorization_revision = $5
    RETURNING target.authorization_revision
  $query$, data_schema)
  INTO current_revision
  USING p_account_id, p_workspace_id, p_artifact_id, p_next_revision, p_expected_revision;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected = 1 THEN
    RETURN QUERY SELECT true, current_revision;
    RETURN;
  END IF;
  EXECUTE pg_catalog.format($query$
    SELECT target.authorization_revision
    FROM %I.editable_artifacts target
    WHERE target.account_id = $1
      AND target.workspace_id = $2
      AND target.id = $3
  $query$, data_schema)
  INTO current_revision
  USING p_account_id, p_workspace_id, p_artifact_id;
  RETURN QUERY SELECT false, current_revision;
END;
$_$;

CREATE FUNCTION opengeni_private.advance_editable_artifact_scope_authorization_revision(p_account_id uuid, p_workspace_id uuid, p_expected_revision bigint, p_next_revision bigint, p_data_schema name DEFAULT "current_schema"()) RETURNS TABLE(applied boolean, authorization_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
DECLARE current_revision bigint;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_data_schema IS NULL
    OR p_expected_revision IS NULL
    OR p_expected_revision NOT BETWEEN 1 AND 9007199254740991
    OR p_next_revision IS NULL
    OR p_next_revision NOT BETWEEN 1 AND 9007199254740991
    OR p_next_revision <= p_expected_revision
    OR NOT opengeni_private.editable_artifact_scope_matches_context(
      p_account_id, p_workspace_id
    )
  THEN
    RAISE EXCEPTION 'invalid editable artifact scope authorization revision bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  -- Ensure the default head exists before the compare-and-swap. Both statements
  -- remain in the caller transaction, so create's FOR SHARE and this UPDATE
  -- serialize revocation against genesis publication.
  PERFORM opengeni_private.ensure_editable_artifact_scope_authorization_head(
    p_account_id, p_workspace_id, data_schema
  );
  EXECUTE pg_catalog.format($query$
    UPDATE %I.editable_artifact_scope_authorization_heads target
    SET create_revision = $3,
      updated_at = GREATEST(target.updated_at, pg_catalog.statement_timestamp())
    WHERE target.account_id = $1
      AND target.workspace_id = $2
      AND target.create_revision = $4
    RETURNING target.create_revision
  $query$, data_schema)
  INTO current_revision
  USING p_account_id, p_workspace_id, p_next_revision, p_expected_revision;
  IF current_revision IS NOT NULL THEN
    RETURN QUERY SELECT true, current_revision;
    RETURN;
  END IF;
  EXECUTE pg_catalog.format($query$
    SELECT target.create_revision
    FROM %I.editable_artifact_scope_authorization_heads target
    WHERE target.account_id = $1 AND target.workspace_id = $2
  $query$, data_schema) INTO current_revision USING p_account_id, p_workspace_id;
  RETURN QUERY SELECT false, current_revision;
END;
$_$;

CREATE FUNCTION opengeni_private.advance_session_execution_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
BEGIN
  -- Unqualified history/audit events are not proof that an accepted attempt started.
  IF NEW.type = 'turn.started' AND NEW.turn_association = 'current' AND NEW.turn_attempt_id IS NOT NULL
  THEN
    UPDATE sessions s SET execution_context_turn_id = NEW.turn_id
      FROM session_turns t JOIN session_turn_attempts a
        ON a.id = t.active_attempt_id AND a.turn_id = t.id AND a.session_id = t.session_id
          AND a.workspace_id = t.workspace_id AND a.account_id = t.account_id
      WHERE s.id = NEW.session_id AND s.workspace_id = NEW.workspace_id
        AND s.account_id = NEW.account_id AND t.id = NEW.turn_id AND t.session_id = s.id
        AND t.workspace_id = s.workspace_id AND t.account_id = s.account_id
        AND t.source IN ('user','api') AND t.scheduled_task_run_id IS NULL
        AND t.status = 'running' AND s.active_turn_id = t.id AND a.id = NEW.turn_attempt_id
        AND a.authority_epoch BETWEEN s.execution_authority_epoch AND s.authority_epoch
        AND NOT EXISTS (SELECT 1 FROM session_events e JOIN session_turn_attempts prior
          ON prior.id = e.turn_attempt_id AND prior.turn_id = e.turn_id
            AND prior.session_id = e.session_id AND prior.workspace_id = e.workspace_id
            AND prior.account_id = e.account_id
          WHERE e.account_id = NEW.account_id AND e.workspace_id = NEW.workspace_id
            AND e.session_id = NEW.session_id AND e.turn_id = NEW.turn_id
            AND e.type = 'turn.started' AND e.turn_association = 'current' AND e.sequence < NEW.sequence);
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.analytics_model_provider(p_provider_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT CASE
    WHEN p_provider_id IN (
      'openai', 'azure', 'codex-subscription', 'supergrok-subscription',
      'opengeni-gateway', 'workspace-gateway', 'organization-gateway',
      'openrouter', 'workspace-openrouter', 'organization-openrouter',
      'opper', 'workspace-opper', 'organization-opper', 'organization-openai',
      'organization-azure-openai'
    ) THEN p_provider_id
    WHEN p_provider_id ~ '^[A-Za-z0-9_-]{1,128}$' THEN 'registry'
    ELSE NULL
  END
$_$;

CREATE FUNCTION opengeni_private.append_subscription_usage_reading(p_account uuid, p_connection uuid, p_provider text, p_reading jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE provider_id text; workspace_id uuid; subject_id text;
    BEGIN
      IF p_account IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid THEN
        RAISE EXCEPTION 'Subscription history scope mismatch' USING ERRCODE = '42501';
      END IF;
      SELECT c.provider INTO provider_id FROM subscription_connections c
        WHERE c.id = p_connection AND c.account_id = p_account AND c.provider = p_provider
          AND c.disconnected_at IS NULL;
      -- Personal turn writes arrive with the exact accepted-turn capability;
      -- ordinary personal-owner reads still use the owner-only seam below.
      IF provider_id IS NULL THEN
        workspace_id := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
        subject_id := nullif(current_setting('opengeni.subject_id', true), '');
        IF workspace_id IS NOT NULL AND subject_id IS NOT NULL THEN
          SELECT p_provider INTO provider_id FROM opengeni_private.subscription_core_personal_connections(
            p_provider, p_account, workspace_id, subject_id) c WHERE c.id = p_connection;
        END IF;
      END IF;
      IF provider_id IS NULL THEN RAISE EXCEPTION 'Subscription history connection not visible' USING ERRCODE = '42501'; END IF;
      PERFORM opengeni_subscription_internal.append_usage_reading(p_account, p_connection, p_reading);
    END $$;

CREATE FUNCTION opengeni_private.apply_document_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  reclassification_allowed boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.authority_kind IS DISTINCT FROM OLD.authority_kind
    OR NEW.authority_workspace_id IS DISTINCT FROM OLD.authority_workspace_id
    OR NEW.authority_subject_id IS DISTINCT FROM OLD.authority_subject_id
    OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
    OR NEW.owner_organization_membership_id
      IS DISTINCT FROM OLD.owner_organization_membership_id
    OR NEW.origin_workspace_id IS DISTINCT FROM OLD.origin_workspace_id
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.visibility IS DISTINCT FROM OLD.visibility
  ) THEN
    IF opengeni_private.document_migration_capability_active('reclassify') THEN
      SELECT EXISTS (
        SELECT 1
        FROM document_authority_reclassifications receipt
        WHERE receipt.document_id = OLD.id
          AND receipt.account_id = OLD.account_id
          AND receipt.previous_authority_kind = OLD.authority_kind
          AND receipt.previous_authority_workspace_id
            IS NOT DISTINCT FROM OLD.authority_workspace_id
          AND receipt.previous_authority_subject_id
            IS NOT DISTINCT FROM OLD.authority_subject_id
          AND receipt.previous_authority_id IS NOT DISTINCT FROM OLD.authority_id
          AND receipt.previous_owner_organization_membership_id
            IS NOT DISTINCT FROM OLD.owner_organization_membership_id
          AND receipt.resulting_authority_kind = NEW.authority_kind
          AND receipt.resulting_authority_workspace_id
            IS NOT DISTINCT FROM NEW.authority_workspace_id
          AND receipt.resulting_authority_subject_id
            IS NOT DISTINCT FROM NEW.authority_subject_id
          AND receipt.resulting_authority_id IS NOT DISTINCT FROM NEW.authority_id
          AND receipt.resulting_owner_organization_membership_id
            IS NOT DISTINCT FROM NEW.owner_organization_membership_id
      ) INTO reclassification_allowed;
    END IF;
    IF NOT reclassification_allowed
      OR NEW.origin_workspace_id IS DISTINCT FROM OLD.origin_workspace_id
      OR NEW.created_by IS DISTINCT FROM OLD.created_by
    THEN
      RAISE EXCEPTION 'document authority is immutable';
    END IF;
  END IF;
  IF NEW.authority_kind IS NULL OR (
    NEW.authority_kind = 'workspace'
    AND NEW.authority_workspace_id IS NULL
    AND NEW.visibility = 'private'
  ) THEN
    NEW.authority_kind := CASE
      WHEN NEW.visibility = 'private' THEN 'personal'
      ELSE 'workspace'
    END;
  END IF;
  NEW.origin_workspace_id := NEW.workspace_id;
  CASE NEW.authority_kind
    WHEN 'organization' THEN
      NEW.authority_workspace_id := NULL;
      NEW.authority_subject_id := NULL;
      NEW.authority_id := NULL;
      NEW.owner_organization_membership_id := NULL;
      NEW.visibility := 'workspace';
    WHEN 'workspace' THEN
      NEW.authority_workspace_id := NEW.workspace_id;
      NEW.authority_subject_id := NULL;
      NEW.authority_id := NULL;
      NEW.owner_organization_membership_id := NULL;
      NEW.visibility := 'workspace';
    WHEN 'personal' THEN
      NEW.authority_subject_id := coalesce(
        nullif(btrim(NEW.authority_subject_id), ''),
        nullif(btrim(NEW.created_by), '')
      );
      IF NEW.authority_id IS NULL THEN
        NEW.authority_workspace_id := NEW.workspace_id;
        NEW.owner_organization_membership_id := NULL;
      ELSE
        NEW.authority_workspace_id := NULL;
      END IF;
      NEW.visibility := 'private';
    ELSE
      RAISE EXCEPTION 'invalid document authority kind: %', NEW.authority_kind;
  END CASE;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.apply_document_chunk_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  parent documents%ROWTYPE;
  reclassification_allowed boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.authority_kind IS DISTINCT FROM OLD.authority_kind
    OR NEW.authority_workspace_id IS DISTINCT FROM OLD.authority_workspace_id
    OR NEW.authority_subject_id IS DISTINCT FROM OLD.authority_subject_id
    OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
    OR NEW.owner_organization_membership_id
      IS DISTINCT FROM OLD.owner_organization_membership_id
    OR NEW.document_id IS DISTINCT FROM OLD.document_id
  ) THEN
    IF opengeni_private.document_migration_capability_active('reclassify') THEN
      SELECT EXISTS (
        SELECT 1
        FROM document_authority_reclassifications receipt
        WHERE receipt.document_id = OLD.document_id
          AND receipt.account_id = OLD.account_id
          AND receipt.previous_authority_kind = OLD.authority_kind
          AND receipt.previous_authority_workspace_id
            IS NOT DISTINCT FROM OLD.authority_workspace_id
          AND receipt.previous_authority_subject_id
            IS NOT DISTINCT FROM OLD.authority_subject_id
          AND receipt.previous_authority_id IS NOT DISTINCT FROM OLD.authority_id
          AND receipt.previous_owner_organization_membership_id
            IS NOT DISTINCT FROM OLD.owner_organization_membership_id
          AND receipt.resulting_authority_kind = NEW.authority_kind
          AND receipt.resulting_authority_workspace_id
            IS NOT DISTINCT FROM NEW.authority_workspace_id
          AND receipt.resulting_authority_subject_id
            IS NOT DISTINCT FROM NEW.authority_subject_id
          AND receipt.resulting_authority_id IS NOT DISTINCT FROM NEW.authority_id
          AND receipt.resulting_owner_organization_membership_id
            IS NOT DISTINCT FROM NEW.owner_organization_membership_id
      ) INTO reclassification_allowed;
    END IF;
    IF NOT reclassification_allowed OR NEW.document_id IS DISTINCT FROM OLD.document_id THEN
      RAISE EXCEPTION 'document chunk authority is immutable';
    END IF;
  END IF;
  SELECT * INTO parent FROM documents WHERE id = NEW.document_id;
  IF NOT FOUND
    OR parent.account_id IS DISTINCT FROM NEW.account_id
    OR parent.workspace_id IS DISTINCT FROM NEW.workspace_id
    OR parent.base_id IS DISTINCT FROM NEW.base_id
    OR parent.file_id IS DISTINCT FROM NEW.file_id
  THEN
    RAISE EXCEPTION 'document chunk parent identity mismatch';
  END IF;
  NEW.authority_kind := parent.authority_kind;
  NEW.authority_workspace_id := parent.authority_workspace_id;
  NEW.authority_subject_id := parent.authority_subject_id;
  NEW.authority_id := parent.authority_id;
  NEW.owner_organization_membership_id := parent.owner_organization_membership_id;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.archived_session_event_types() RETURNS SETOF text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT unnest(ARRAY[
    'agent.message.delta',
    'agent.reasoning.delta',
    'sandbox.command.output.delta',
    'terminal.pty.output.delta',
    'agent.model.request',
    'system.update.pending',
    'system.update.delivered',
    'system.update.settled',
    'turn.startup.phase.started',
    'turn.startup.phase.completed',
    'codex.credential.selected',
    'turn.event.rejected_late'
  ]);
$$;

CREATE FUNCTION opengeni_private.arm_usage_allowances_for_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      affected uuid[];
      v_data_schema text:='{{schema}}';
      projection text:='jsonb_build_array(to_jsonb(row)->''account_id'',to_jsonb(row)->''subject_id'',
        to_jsonb(row)->''workspace_id'',to_jsonb(row)->''personal_workspace_id'',to_jsonb(row)->''status'',
        to_jsonb(row)->''external_source'',to_jsonb(row)->''external_id'')';
      account_column text:='account_id';
    BEGIN
      IF TG_TABLE_NAME='managed_accounts' THEN
        account_column:='id';
        IF TG_OP='DELETE' THEN
          DELETE FROM opengeni_private.usage_allowance_membership_changes
            WHERE data_schema=v_data_schema AND account_id=OLD.id;
          RETURN NULL;
        END IF;
      END IF;
      IF TG_OP='INSERT' THEN
        EXECUTE format('SELECT array_agg(DISTINCT %I ORDER BY %I) FROM new_members',account_column,account_column) INTO affected;
      ELSIF TG_OP='DELETE' THEN
        SELECT array_agg(DISTINCT account_id ORDER BY account_id) INTO affected FROM old_members;
      ELSE
        EXECUTE 'SELECT array_agg(DISTINCT account_id ORDER BY account_id) FROM (
          (SELECT '||account_column||' AS account_id,'||projection||' AS fact FROM new_members row
            EXCEPT SELECT '||account_column||','||projection||' AS fact FROM old_members row)
          UNION
          (SELECT '||account_column||','||projection||' AS fact FROM old_members row
            EXCEPT SELECT '||account_column||','||projection||' AS fact FROM new_members row)
          ) changed' INTO affected;
      END IF;
      IF affected IS NULL THEN RETURN NULL; END IF;
      -- Never acquire allowance-row locks from a membership transaction: a
      -- bounded maintenance batch can hold several rows in deadline order.
      -- A monotonic marker also preserves a re-arm racing maintenance.
      INSERT INTO opengeni_private.usage_allowance_membership_changes(data_schema,account_id)
        SELECT v_data_schema,id FROM unnest(affected) id ORDER BY id
      ON CONFLICT(data_schema,account_id) DO UPDATE
        SET revision=usage_allowance_membership_changes.revision+1,changed_at=clock_timestamp();
      RETURN NULL;
    END $$;

CREATE FUNCTION opengeni_private.assert_organization_administrator(p_account uuid, p_actor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  permissions_value jsonb;
  member_id uuid;
BEGIN
  IF p_account IS NULL OR p_actor IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_actor IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'organization administration scope invalid' USING ERRCODE = '42501';
  END IF;
  IF p_actor LIKE 'api_key:%' THEN
    SELECT permissions INTO permissions_value FROM api_keys
      WHERE account_id = p_account AND 'api_key:' || id::text = p_actor
        AND credential_kind = 'organization' AND workspace_id IS NULL AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > clock_timestamp()) FOR SHARE;
    IF NOT coalesce(permissions_value ? 'workspace:admin', false) THEN
      RAISE EXCEPTION 'organization administrator required' USING ERRCODE = '42501';
    END IF;
  ELSE
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_private_session_settings', true);
    SELECT id INTO member_id FROM organization_memberships
      WHERE account_id = p_account AND subject_id = p_actor AND status = 'active' AND role IN ('owner','admin') FOR SHARE;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
    IF member_id IS NULL THEN RAISE EXCEPTION 'organization administrator required' USING ERRCODE = '42501'; END IF;
  END IF;
END $$;

CREATE FUNCTION opengeni_private.assert_organization_integration_policy_administrator(p_account uuid, p_actor text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT opengeni_private.assert_organization_administrator(p_account, p_actor)
$$;

CREATE FUNCTION opengeni_private.assert_organization_retention_account(p_account_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'retention organization context mismatch' USING ERRCODE = '42501';
  END IF;
END
$$;

CREATE FUNCTION opengeni_private.assert_organization_shared_workspace_administrator(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS NULL
    OR p_workspace_id IS NULL
    OR p_actor_subject_id IS NULL
    OR p_actor_subject_id NOT LIKE 'user:%'
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization shared-workspace administration authority is invalid'
      USING ERRCODE = '42501';
  END IF;

  -- Serialize role/personal-workspace changes with this transaction. The lock
  -- has no row-level dependency and therefore keeps the canonical lifecycle
  -- ordering intact.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || p_account_id::text, 0
  ));

  IF NOT EXISTS (
    SELECT 1
    FROM organization_memberships actor
    WHERE actor.account_id = p_account_id
      AND actor.subject_id = p_actor_subject_id
      AND actor.status = 'active'
      AND actor.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM workspaces workspace
    WHERE workspace.account_id = p_account_id
      AND workspace.id = p_workspace_id
      AND NOT EXISTS (
        SELECT 1
        FROM organization_memberships membership
        WHERE membership.account_id = p_account_id
          AND membership.personal_workspace_id = workspace.id
      )
  ) THEN
    -- Cross-organization, missing, and Personal workspaces intentionally share
    -- one non-enumerating result.
    RAISE EXCEPTION 'shared workspace not found' USING ERRCODE = 'P0002';
  END IF;
END
$$;

CREATE FUNCTION opengeni_private.assert_session_ownership_scope(p_organization_id uuid, p_run_key text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'session ownership classification requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_organization_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'session ownership classification scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF nullif(pg_catalog.current_setting('opengeni.subject_id', true), '') IS NOT NULL THEN
    RAISE EXCEPTION 'session ownership classification must run outside an actor subject scope'
      USING ERRCODE = '42501';
  END IF;
  IF p_run_key IS NOT NULL AND length(btrim(p_run_key)) = 0 THEN
    RAISE EXCEPTION 'session ownership run key must not be blank'
      USING ERRCODE = '22023';
  END IF;
END;
$$;

CREATE FUNCTION opengeni_private.assert_workspace_membership_removal_actor(p_account_id uuid, p_workspace_id uuid, p_actor_subject text, p_target_subject text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  actor_is_organization_administrator boolean;
  actor_can_administer boolean;
  service_permissions jsonb;
  service_can_administer boolean := false;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM workspaces workspace
    WHERE workspace.account_id = p_account_id
      AND workspace.id = p_workspace_id
      AND NOT EXISTS (
        SELECT 1 FROM organization_memberships membership
        WHERE membership.account_id = p_account_id
          AND membership.personal_workspace_id = workspace.id
      )
  ) THEN
    RAISE EXCEPTION 'shared workspace not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT EXISTS (
    SELECT 1
    FROM organization_memberships org_actor
    JOIN organization_shared_workspace_administration_capabilities capability
      ON capability.account_id = org_actor.account_id
      AND capability.workspace_id = p_workspace_id
      AND capability.actor_subject_id = org_actor.subject_id
      AND capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id()
      AND capability.capability_id::text = pg_catalog.current_setting(
        'opengeni.organization_shared_workspace_administration_capability', true
      )
    WHERE org_actor.account_id = p_account_id
      AND org_actor.subject_id = p_actor_subject
      AND p_actor_subject LIKE 'user:%'
      AND org_actor.status = 'active'
      AND org_actor.role IN ('owner', 'admin')
  ) INTO actor_is_organization_administrator;
  IF p_actor_subject = p_target_subject
    AND NOT actor_is_organization_administrator
  THEN
    RAISE EXCEPTION 'a member cannot remove their own workspace membership'
      USING ERRCODE = '55000';
  END IF;

  IF p_actor_subject LIKE 'api_key:%' THEN
    -- The API authenticates the key before supplying this subject. This is a
    -- live consistency fence, not authentication from an arbitrary UUID.
    SELECT credential.permissions INTO service_permissions
    FROM api_keys credential
    WHERE credential.account_id = p_account_id
      AND 'api_key:' || credential.id::text = p_actor_subject
      AND credential.workspace_id IS NULL
      AND credential.credential_kind = 'organization'
      AND credential.revoked_at IS NULL
      AND (credential.expires_at IS NULL OR credential.expires_at > clock_timestamp())
    FOR SHARE;
    service_can_administer := coalesce(
      service_permissions ?| ARRAY['workspace:admin', 'members:manage'], false
    ) AND EXISTS (
      SELECT 1 FROM organization_memberships target
      WHERE target.account_id = p_account_id
        AND target.subject_id = p_target_subject
        AND target.subject_id ~ '^external_user:[0-9a-f-]{36}$'
    );
  END IF;
  SELECT actor_is_organization_administrator OR service_can_administer OR EXISTS (

    SELECT 1 FROM workspace_memberships actor_row
    WHERE actor_row.account_id = p_account_id
      AND actor_row.workspace_id = p_workspace_id
      AND actor_row.subject_id = p_actor_subject
      AND actor_row.permissions ?| ARRAY['workspace:admin', 'members:manage']
  ) INTO actor_can_administer;
  IF NOT actor_can_administer THEN
    RAISE EXCEPTION 'workspace member administration required' USING ERRCODE = '42501';
  END IF;
  IF NOT actor_is_organization_administrator
    AND EXISTS (
      SELECT 1 FROM workspace_memberships target_row
      WHERE target_row.account_id = p_account_id
        AND target_row.workspace_id = p_workspace_id
        AND target_row.subject_id = p_target_subject
        AND target_row.permissions ?| ARRAY['workspace:admin', 'members:manage']
    ) AND NOT EXISTS (
      SELECT 1 FROM workspace_memberships other
      WHERE other.account_id = p_account_id
        AND other.workspace_id = p_workspace_id
        AND other.subject_id <> p_target_subject
        AND other.permissions ?| ARRAY['workspace:admin', 'members:manage']
    )
  THEN
    RAISE EXCEPTION 'cannot remove the last administering workspace member'
      USING ERRCODE = '55000';
  END IF;
END
$_$;

CREATE FUNCTION opengeni_private.assign_managed_self_organization_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM managed_accounts account
    WHERE account.id = NEW.account_id
      AND (
        (
          account.external_source = 'better-auth:user'
          AND NEW.subject_id = 'user:' || account.external_id
        ) OR (
          account.external_source = 'opengeni:local'
          AND account.external_id = 'default'
          AND NEW.subject_id = 'dev'
        )
      )
  ) THEN
    NEW.role := 'owner';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.attached_browser_devices_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  enrollment_transfer_allowed boolean;
BEGIN
  IF ROW(
    NEW.id, NEW.account_id, NEW.workspace_id, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.id, OLD.account_id, OLD.workspace_id, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Attached browser endpoint identity cannot change'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.enrollment_id IS DISTINCT FROM OLD.enrollment_id THEN
    SELECT
      EXISTS (
        SELECT 1
        FROM enrollments previous_enrollment
        WHERE previous_enrollment.id = OLD.enrollment_id
          AND previous_enrollment.account_id = OLD.account_id
          AND previous_enrollment.workspace_id = OLD.workspace_id
          AND previous_enrollment.status = 'revoked'
      )
      AND EXISTS (
        SELECT 1
        FROM enrollments next_enrollment
        WHERE next_enrollment.id = NEW.enrollment_id
          AND next_enrollment.account_id = NEW.account_id
          AND next_enrollment.workspace_id = NEW.workspace_id
          AND next_enrollment.status = 'active'
      )
    INTO enrollment_transfer_allowed;

    IF NOT coalesce(enrollment_transfer_allowed, false) THEN
      RAISE EXCEPTION 'Attached browser endpoint enrollment can move only from revoked to active'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.last_seen_at < OLD.last_seen_at OR NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'Attached browser endpoint time cannot move backwards'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.connection_generation = OLD.connection_generation
     AND NEW.inventory_revision < OLD.inventory_revision THEN
    RAISE EXCEPTION 'Attached browser inventory revision cannot move backwards'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.authorize_editable_artifact_actor(p_account_id uuid, p_workspace_id uuid, p_artifact_id text, p_actor_kind text, p_actor_subject_id text, p_agent_session_id text, p_agent_turn_id text, p_agent_attempt_id text, p_agent_generation integer, p_service_name text, p_permission text, p_data_schema name DEFAULT "current_schema"()) RETURNS TABLE(allowed boolean, authorization_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
DECLARE required_permission text;
DECLARE current_revision bigint;
DECLARE principal_allowed boolean := false;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL
    OR p_artifact_id IS NULL
    OR p_artifact_id !~ '^[0-9a-f]{32}$' OR p_artifact_id ~ '^0+$'
    OR p_actor_kind IS NULL OR p_actor_kind NOT IN ('human', 'agent', 'service')
    OR p_actor_subject_id IS NULL
    OR octet_length(p_actor_subject_id) NOT BETWEEN 1 AND 1024
    OR p_actor_subject_id <> btrim(p_actor_subject_id)
    OR p_permission IS NULL
    OR p_permission NOT IN ('create', 'read', 'edit', 'import', 'export', 'manage')
    OR NOT opengeni_private.editable_artifact_scope_matches_context(
      p_account_id, p_workspace_id
    )
  THEN
    RAISE EXCEPTION 'editable artifact authorization request is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (p_actor_kind = 'human' AND (
      p_agent_session_id IS NOT NULL OR p_agent_turn_id IS NOT NULL
      OR p_agent_attempt_id IS NOT NULL OR p_agent_generation IS NOT NULL
      OR p_service_name IS NOT NULL
    )) OR (p_actor_kind = 'agent' AND (
      p_agent_session_id IS NULL OR p_agent_turn_id IS NULL
      OR p_agent_attempt_id IS NULL OR p_agent_generation IS NULL
      OR p_agent_generation < 0 OR p_service_name IS NOT NULL
    )) OR (p_actor_kind = 'service' AND (
      p_agent_session_id IS NOT NULL OR p_agent_turn_id IS NOT NULL
      OR p_agent_attempt_id IS NOT NULL OR p_agent_generation IS NOT NULL
      OR p_service_name IS NULL
    ))
  THEN
    RAISE EXCEPTION 'editable artifact authorization actor is invalid'
      USING ERRCODE = '22023';
  END IF;

  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  required_permission := CASE
    WHEN p_permission IN ('read', 'export') THEN 'artifacts:read'
    ELSE 'artifacts:publish'
  END;

  IF p_permission IN ('create', 'import') THEN
    current_revision := opengeni_private.ensure_editable_artifact_scope_authorization_head(
      p_account_id, p_workspace_id, data_schema
    );
  ELSE
    EXECUTE pg_catalog.format($query$
      SELECT artifact.authorization_revision
      FROM %I.editable_artifacts artifact
      WHERE artifact.account_id = $1 AND artifact.workspace_id = $2
        AND artifact.id = $3
    $query$, data_schema)
      INTO current_revision
      USING p_account_id, p_workspace_id, p_artifact_id;
    current_revision := coalesce(current_revision, 1);
  END IF;

  IF p_actor_kind = 'agent' THEN
    EXECUTE pg_catalog.format($query$
      SELECT true
      FROM %I.sessions session
      JOIN %I.session_turns turn
        ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id
        AND turn.session_id = session.id
      JOIN %I.session_turn_attempts attempt
        ON attempt.account_id = turn.account_id
        AND attempt.workspace_id = turn.workspace_id
        AND attempt.session_id = turn.session_id
        AND attempt.turn_id = turn.id
      WHERE session.account_id = $1 AND session.workspace_id = $2
        AND session.id::text = $3
        AND turn.id::text = $4
        AND attempt.id::text = $5
        AND session.active_turn_id = turn.id
        AND turn.active_attempt_id = attempt.id
        AND turn.execution_generation = $6
        AND attempt.execution_generation = $6
        AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
        AND attempt.state IN ('claimed', 'running')
        AND attempt.closed_at IS NULL AND attempt.quiesced_at IS NULL
        AND NOT EXISTS (
          SELECT 1
          FROM %I.session_attempt_interruptions interruption
          WHERE interruption.account_id = session.account_id
            AND interruption.workspace_id = session.workspace_id
            AND interruption.session_id = session.id
            AND interruption.attempt_id = attempt.id
            AND interruption.state IN ('pending', 'delivered', 'acknowledged')
        )
        AND (
          session.first_party_mcp_permissions IS NULL
          OR session.first_party_mcp_permissions ? $7
          OR session.first_party_mcp_permissions ? 'workspace:admin'
        )
      LIMIT 1
      FOR SHARE OF session, turn, attempt
    $query$, data_schema, data_schema, data_schema, data_schema)
      INTO principal_allowed
      USING p_account_id, p_workspace_id, p_agent_session_id,
        p_agent_turn_id, p_agent_attempt_id, p_agent_generation,
        required_permission;
  ELSIF p_actor_kind = 'service'
    AND p_service_name = 'api_key'
    AND p_actor_subject_id ~ '^api_key:[0-9a-fA-F-]{36}$'
  THEN
    EXECUTE pg_catalog.format($query$
      SELECT true
      FROM %I.api_keys api_key
      WHERE api_key.account_id = $1 AND api_key.workspace_id = $2
        AND api_key.id::text = substring($3 from 9)
        AND api_key.revoked_at IS NULL
        AND (api_key.expires_at IS NULL OR api_key.expires_at > pg_catalog.clock_timestamp())
        AND (api_key.permissions ? $4 OR api_key.permissions ? 'workspace:admin')
      LIMIT 1
      FOR SHARE OF api_key
    $query$, data_schema)
      INTO principal_allowed
      USING p_account_id, p_workspace_id, p_actor_subject_id, required_permission;
  ELSIF p_actor_kind = 'human'
    OR (p_actor_kind = 'service' AND p_service_name = 'configured_key')
  THEN
    EXECUTE pg_catalog.format($query$
      SELECT true
      FROM %I.workspace_memberships membership
      WHERE membership.account_id = $1 AND membership.workspace_id = $2
        AND membership.subject_id = $3
        AND (membership.permissions ? $4 OR membership.permissions ? 'workspace:admin')
      LIMIT 1
      FOR SHARE OF membership
    $query$, data_schema)
      INTO principal_allowed
      USING p_account_id, p_workspace_id, p_actor_subject_id, required_permission;
    -- A person's own personal workspace has no membership row (0869).
    IF NOT coalesce(principal_allowed, false) AND p_actor_kind = 'human'
      AND p_actor_subject_id ~ '^(user|external_user):'
    THEN
      DECLARE prior_lifecycle text := pg_catalog.current_setting(
        'opengeni.organization_tenancy_lifecycle', true
      );
      BEGIN
        PERFORM pg_catalog.set_config(
          'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
        );
        EXECUTE pg_catalog.format($personal$
          SELECT true
          FROM %I.organization_memberships owner_membership
          WHERE owner_membership.account_id = $1
            AND owner_membership.subject_id = $3
            AND owner_membership.personal_workspace_id = $2
            AND owner_membership.status = 'active'
            AND owner_membership.revoked_at IS NULL
          LIMIT 1
          FOR SHARE OF owner_membership
        $personal$, data_schema)
          INTO principal_allowed
          USING p_account_id, p_workspace_id, p_actor_subject_id;
        PERFORM pg_catalog.set_config(
          'opengeni.organization_tenancy_lifecycle', coalesce(prior_lifecycle, ''), true
        );
      END;
    END IF;
  ELSE
    principal_allowed := false;
  END IF;

  RETURN QUERY SELECT coalesce(principal_allowed, false), current_revision;
END;
$_$;

CREATE FUNCTION opengeni_private.authorize_subscription_ownerless_session_access(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      allowed boolean;
      minted_lifecycle boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR nullif(current_setting('opengeni.subject_id', true), '') IS DISTINCT FROM 'service:subscription-core'
        OR nullif(current_setting('opengeni.initiating_human_subject_id', true), '') IS NOT NULL
      THEN RETURN false; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'lifecycle', p_account_id)
      ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id) DO NOTHING
      RETURNING true INTO minted_lifecycle;
      SELECT EXISTS (
        SELECT 1 FROM sessions session
        JOIN session_turns turn ON turn.account_id = session.account_id
          AND turn.workspace_id = session.workspace_id AND turn.session_id = session.id
        WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
          AND session.id = p_session_id AND session.owner_subject_id IS NULL
          AND session.owner_organization_membership_id IS NULL
          AND session.visibility <> 'user_private'
          AND turn.id = p_turn_id
          AND session_reference_visible(p_account_id, p_workspace_id, p_session_id)
      ) INTO allowed;
      -- Remove only a lifecycle capability this call created.
      IF coalesce(minted_lifecycle, false) THEN
        DELETE FROM opengeni_private.subscription_runtime_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'lifecycle' AND capability.account_id = p_account_id;
      END IF;
      IF NOT allowed THEN RETURN false; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        session_id, turn_id, connection_id, session_owner_subject_id, turn_human_subject_id
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'session_access',
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_session_id, NULL, NULL
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
      DO UPDATE SET workspace_id = EXCLUDED.workspace_id, session_id = EXCLUDED.session_id,
        turn_id = EXCLUDED.turn_id, session_owner_subject_id = NULL, turn_human_subject_id = NULL;
      PERFORM pg_catalog.set_config('opengeni.session_owner_subject_id', '', true);
      PERFORM pg_catalog.set_config('opengeni.turn_human_subject_id', '', true);
      RETURN true;
    END
    $$;

CREATE FUNCTION opengeni_private.authorize_subscription_personal_access(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_connection_id uuid, p_provider text, p_session_owner_subject_id text, p_turn_human_subject_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      v2_snapshot jsonb;
      owner_membership uuid;
      connection_generation bigint;
      provider_core boolean := false;
      record_entry jsonb;
      authorized boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_turn_human_subject_id IS DISTINCT FROM nullif(current_setting('opengeni.initiating_human_subject_id', true), '')
        OR p_session_owner_subject_id IS NULL OR p_turn_human_subject_id IS NULL
      THEN RETURN false; END IF;
      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        session_id, turn_id, connection_id, provider,
        session_owner_subject_id, turn_human_subject_id
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'personal_access',
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_connection_id, p_provider,
        p_session_owner_subject_id, p_turn_human_subject_id)
      ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
      DO UPDATE SET workspace_id = EXCLUDED.workspace_id, session_id = EXCLUDED.session_id,
        turn_id = EXCLUDED.turn_id, provider = EXCLUDED.provider,
        session_owner_subject_id = EXCLUDED.session_owner_subject_id,
        turn_human_subject_id = EXCLUDED.turn_human_subject_id;

      -- A provider reads its v2 entry only after its own receipt and with
      -- an enabled cutover row. Without a receipt, without a row, or with a
      -- disabled row this grants nothing.
      IF opengeni_private.subscription_provider_cutover_committed(p_provider) THEN
        SELECT coalesce(cutover.enabled, false) INTO provider_core
        FROM subscription_provider_cutovers cutover
        WHERE cutover.account_id = p_account_id AND cutover.provider = p_provider;
        provider_core := coalesce(provider_core, false);
      END IF;

      SELECT turn.subscription_authority, membership.id, connection.authority_generation
      INTO v2_snapshot, owner_membership, connection_generation
      FROM sessions session
      JOIN session_turns turn ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id AND turn.session_id = session.id
      JOIN subscription_connections connection ON connection.account_id = session.account_id
        AND connection.id = p_connection_id AND connection.provider = p_provider
      JOIN organization_memberships membership ON membership.id = connection.owner_organization_membership_id
        AND membership.account_id = connection.account_id
      JOIN organization_user_resource_authorities authority ON authority.id = connection.authority_id
        AND authority.account_id = connection.account_id AND authority.organization_membership_id = membership.id
        AND authority.resource_kind = 'subscription_connection' AND authority.resource_id = connection.id
        AND authority.generation = connection.authority_generation AND authority.status = 'active'
        AND authority.revoked_at IS NULL
      WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
        AND session.id = p_session_id AND session.owner_subject_id = p_session_owner_subject_id
        AND turn.id = p_turn_id AND turn.initiating_human_subject_id = p_turn_human_subject_id
        AND membership.subject_id = p_turn_human_subject_id AND membership.status = 'active'
        AND membership.revoked_at IS NULL AND connection.ownership = 'personal'
        AND connection.owner_subject_id = p_turn_human_subject_id
        AND connection.status = 'active'
        AND (
          (p_turn_human_subject_id = p_session_owner_subject_id
            AND session.owner_organization_membership_id = connection.owner_organization_membership_id
            AND (session.visibility = 'user_private' OR membership.personal_workspace_id = p_workspace_id))
          OR (p_turn_human_subject_id LIKE 'user:%'
            AND subscription_personal_authority_v2_valid(turn.subscription_authority)
            AND EXISTS (SELECT 1 FROM jsonb_array_elements(turn.subscription_authority->'personal') entry
              WHERE entry->>'provider' = p_provider
                AND entry->>'ownerMembershipId' = membership.id::text
                AND entry->>'authorityGeneration' = connection.authority_generation::text
                AND entry->'sharedSessionChoice'->>'sessionId' = p_session_id::text
                AND entry->'sharedSessionChoice'->>'connectionId' = p_connection_id::text)
            AND EXISTS (SELECT 1 FROM workspace_memberships participant
              WHERE participant.account_id = p_account_id AND participant.workspace_id = p_workspace_id
                AND participant.subject_id = p_turn_human_subject_id))
        );

      IF NOT provider_core THEN
        authorized := false;
      ELSIF NOT opengeni_subscription_internal.subscription_compat_v2_has_entry(
        v2_snapshot, p_provider)
      THEN
        -- No v2 entry for the provider: the turn's compatibility record, for
        -- the exact owner membership and current generation, and only for
        -- the exact connections it lists.
        SELECT record.personal->0 INTO record_entry
        FROM opengeni_private.subscription_authority_compat record
        WHERE record.account_id = p_account_id AND record.workspace_id = p_workspace_id
          AND record.turn_id = p_turn_id AND record.carrier_kind = 'session_turn'
          AND record.provider = p_provider
          AND record.owner_subject_id = p_session_owner_subject_id;
        authorized := coalesce(owner_membership IS NOT NULL
          AND record_entry IS NOT NULL
          AND record_entry->>'ownerMembershipId' = owner_membership::text
          AND record_entry->>'authorityGeneration' = connection_generation::text
          AND record_entry->'connectionIds' ? p_connection_id::text
          AND coalesce((subscription_effective_settings(p_account_id, p_workspace_id)
            #>> '{values,personalConnectionsAllowed}')::boolean, false), false);
      ELSE
        -- The exact frozen v2 entry: provider, canonical owner membership and
        -- the connection's current active authority generation.
        authorized := coalesce(owner_membership IS NOT NULL
          AND v2_snapshot IS NOT NULL
          AND subscription_personal_authority_v2_valid(v2_snapshot)
          AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(v2_snapshot->'personal') entry
            WHERE entry->>'provider' = p_provider
              AND (entry->>'ownerMembershipId')::uuid = owner_membership
              AND entry->>'authorityGeneration' = connection_generation::text
              AND (NOT entry ? 'sharedSessionChoice' OR (
                entry->'sharedSessionChoice'->>'sessionId' = p_session_id::text
                AND entry->'sharedSessionChoice'->>'connectionId' = p_connection_id::text
                AND p_turn_human_subject_id LIKE 'user:%'
                AND current_setting('opengeni.shared_personal_choice_v1', true) = '1'
                AND nullif(current_setting('opengeni.subject_id', true), '') IN (
                  p_turn_human_subject_id, 'service:subscription-core')
                AND EXISTS (SELECT 1 FROM workspace_memberships participant
                  WHERE participant.account_id = p_account_id AND participant.workspace_id = p_workspace_id
                    AND participant.subject_id = p_turn_human_subject_id)))
          )
          AND coalesce((subscription_effective_settings(p_account_id, p_workspace_id)
            #>> '{values,personalConnectionsAllowed}')::boolean, false), false);
      END IF;
      IF NOT authorized OR NOT session_reference_visible(p_account_id, p_workspace_id, p_session_id)
      THEN
        DELETE FROM opengeni_private.subscription_runtime_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'personal_access'
          AND capability.account_id = p_account_id AND capability.connection_id = p_connection_id;
        RETURN false;
      END IF;
      PERFORM pg_catalog.set_config('opengeni.session_owner_subject_id', p_session_owner_subject_id, true);
      PERFORM pg_catalog.set_config('opengeni.turn_human_subject_id', p_turn_human_subject_id, true);
      RETURN true;
    END
    $$;

CREATE FUNCTION opengeni_private.authorize_subscription_personal_placement_access(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_provider text, p_owner_membership_id uuid, p_authority_generation bigint, p_session_owner_subject_id text, p_turn_human_subject_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      authority_snapshot jsonb;
      enabled boolean := false;
      allowed boolean := false;
      minted_lifecycle boolean := false;
      minted_connections uuid[] := '{}'::uuid[];
      record_connections uuid[];
      restricted_connection uuid;
      selected_entry jsonb;
      turn_found boolean;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR nullif(current_setting('opengeni.subject_id', true), '') IS DISTINCT FROM 'service:subscription-core'
        OR p_turn_human_subject_id IS NULL
        OR p_turn_human_subject_id IS DISTINCT FROM nullif(current_setting('opengeni.initiating_human_subject_id', true), '')
        OR p_session_owner_subject_id IS NULL
        OR p_session_owner_subject_id IS DISTINCT FROM nullif(current_setting('opengeni.session_owner_subject_id', true), '')
        OR p_owner_membership_id IS NULL OR p_authority_generation IS NULL OR p_authority_generation < 1
        OR NOT coalesce(opengeni_private.subscription_provider_cutover_committed(p_provider), false)
      THEN RETURN false; END IF;

      -- This precursor remains inert until the provider's cutover row is
      -- explicitly enabled by the later drained migration. Check this before
      -- consulting v2 so v1 remains authoritative during rolling deploys.
      SELECT cutover.enabled INTO enabled
      FROM subscription_provider_cutovers cutover
      WHERE cutover.account_id = p_account_id AND cutover.provider = p_provider;
      IF enabled IS DISTINCT FROM true THEN RETURN false; END IF;

      IF NOT EXISTS (
        SELECT 1 FROM opengeni_private.subscription_runtime_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'session_access'
          AND capability.account_id = p_account_id
          AND capability.workspace_id = p_workspace_id
          AND capability.session_id = p_session_id
          AND capability.turn_id = p_turn_id
          AND capability.session_owner_subject_id = p_session_owner_subject_id
          AND capability.turn_human_subject_id = p_turn_human_subject_id
      ) THEN RETURN false; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'lifecycle', p_account_id)
      ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id) DO NOTHING
      RETURNING true INTO minted_lifecycle;
      minted_lifecycle := coalesce(minted_lifecycle, false);

      SELECT turn.subscription_authority, true INTO authority_snapshot, turn_found
      FROM sessions session
      JOIN session_turns turn ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id AND turn.session_id = session.id
      JOIN organization_memberships membership ON membership.account_id = session.account_id
        AND membership.id = p_owner_membership_id
        AND membership.subject_id = p_turn_human_subject_id
      WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
        AND session.id = p_session_id AND session.owner_subject_id = p_session_owner_subject_id
        AND turn.id = p_turn_id AND turn.initiating_human_subject_id = p_turn_human_subject_id
        AND membership.status = 'active' AND membership.revoked_at IS NULL
        AND (
          (session.owner_subject_id = p_turn_human_subject_id
            AND session.owner_organization_membership_id = p_owner_membership_id
            AND (session.visibility = 'user_private' OR membership.personal_workspace_id = p_workspace_id))
          OR (p_turn_human_subject_id LIKE 'user:%'
            AND subscription_personal_authority_v2_valid(turn.subscription_authority)
            AND EXISTS (SELECT 1 FROM jsonb_array_elements(turn.subscription_authority->'personal') entry
              WHERE entry->>'provider' = p_provider
                AND entry->>'ownerMembershipId' = p_owner_membership_id::text
                AND entry->>'authorityGeneration' = p_authority_generation::text
                AND entry->'sharedSessionChoice'->>'sessionId' = p_session_id::text)
            AND EXISTS (SELECT 1 FROM workspace_memberships participant
              WHERE participant.account_id = p_account_id AND participant.workspace_id = p_workspace_id
                AND participant.subject_id = p_turn_human_subject_id))
        )
        AND session_reference_visible(p_account_id, p_workspace_id, p_session_id);

      IF turn_found IS TRUE
        AND NOT opengeni_subscription_internal.subscription_compat_v2_has_entry(
          authority_snapshot, p_provider)
      THEN
        -- No v2 entry for the provider: the turn's compatibility record. Its
        -- exact connections bound everything minted below; membership and
        -- generation alone never grant a record's personal access.
        SELECT coalesce(array_agg(connection_id.value::uuid), '{}'::uuid[])
        INTO record_connections
        FROM opengeni_private.subscription_authority_compat record
        CROSS JOIN LATERAL jsonb_array_elements_text(record.personal->0->'connectionIds')
          connection_id(value)
        WHERE record.account_id = p_account_id AND record.workspace_id = p_workspace_id
          AND record.turn_id = p_turn_id AND record.carrier_kind = 'session_turn'
          AND record.provider = p_provider
          AND record.owner_subject_id = p_session_owner_subject_id
          AND record.personal->0->>'ownerMembershipId' = p_owner_membership_id::text
          AND record.personal->0->>'authorityGeneration' = p_authority_generation::text;
        allowed := cardinality(record_connections) > 0;
      ELSIF authority_snapshot IS NOT NULL
        AND subscription_personal_authority_v2_valid(authority_snapshot)
        AND authority_snapshot->>'version' = '2'
        AND jsonb_typeof(authority_snapshot->'personal') = 'array'
      THEN
        SELECT EXISTS (
          SELECT 1 FROM jsonb_array_elements(authority_snapshot->'personal') entry
          WHERE entry->>'provider' = p_provider
            AND (entry->>'ownerMembershipId')::uuid = p_owner_membership_id
            AND entry->>'authorityGeneration' = p_authority_generation::text
        ) INTO allowed;
        SELECT entry INTO selected_entry FROM jsonb_array_elements(authority_snapshot->'personal') entry
        WHERE entry->>'provider' = p_provider;
        IF selected_entry ? 'sharedSessionChoice' THEN
          IF selected_entry->'sharedSessionChoice'->>'sessionId' IS DISTINCT FROM p_session_id::text
            OR current_setting('opengeni.shared_personal_choice_v1', true) IS DISTINCT FROM '1'
            OR p_turn_human_subject_id NOT LIKE 'user:%'
            OR NOT EXISTS (SELECT 1 FROM workspace_memberships participant
              WHERE participant.account_id = p_account_id AND participant.workspace_id = p_workspace_id
                AND participant.subject_id = p_turn_human_subject_id)
          THEN
            allowed := false;
          END IF;
          restricted_connection := (selected_entry->'sharedSessionChoice'->>'connectionId')::uuid;
          record_connections := ARRAY[restricted_connection];
        END IF;
      END IF;
      IF NOT allowed OR NOT coalesce((subscription_effective_settings(
        p_account_id, p_workspace_id
      ) #>> '{values,personalConnectionsAllowed}')::boolean, false) THEN
        IF minted_lifecycle THEN
          DELETE FROM opengeni_private.subscription_runtime_capabilities capability
          WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
            AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
            AND capability.capability_kind = 'lifecycle' AND capability.account_id = p_account_id;
        END IF;
        RETURN false;
      END IF;

      -- Authorities identify exact personal resource IDs. Mint temporary
      -- per-connection capabilities only for those whose current authority
      -- generation matches the frozen v2 generation, then remove any whose
      -- connection row does not prove the same owner/provider/generation.
      -- Never rewrite or remove a capability the caller already held for a
      -- connection (for example an earlier v1 Claude authorization in the
      -- same transaction): conflicts are left untouched, and every cleanup
      -- below is limited to the rows this call inserted.
      WITH inserted AS (
        INSERT INTO opengeni_private.subscription_runtime_capabilities (
          backend_pid, transaction_id, capability_kind, account_id, workspace_id,
          session_id, turn_id, connection_id, provider,
          session_owner_subject_id, turn_human_subject_id
        )
        SELECT pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'personal_access',
          p_account_id, p_workspace_id, p_session_id, p_turn_id, authority.resource_id,
          p_provider, p_session_owner_subject_id, p_turn_human_subject_id
        FROM organization_user_resource_authorities authority
        WHERE authority.account_id = p_account_id
          AND authority.organization_membership_id = p_owner_membership_id
          AND authority.resource_kind = 'subscription_connection'
          AND authority.generation = p_authority_generation
          AND authority.status = 'active' AND authority.revoked_at IS NULL
          AND (record_connections IS NULL OR authority.resource_id = ANY (record_connections))
        ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
        RETURNING connection_id
      )
      SELECT coalesce(array_agg(inserted.connection_id), '{}'::uuid[])
        INTO minted_connections FROM inserted;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'personal_access'
        AND capability.account_id = p_account_id AND capability.workspace_id = p_workspace_id
        AND capability.connection_id = ANY (minted_connections)
        AND capability.session_id = p_session_id AND capability.turn_id = p_turn_id
        AND capability.provider = p_provider
        AND capability.session_owner_subject_id = p_session_owner_subject_id
        AND capability.turn_human_subject_id = p_turn_human_subject_id
        AND NOT EXISTS (
          SELECT 1 FROM subscription_connections connection
          JOIN organization_user_resource_authorities authority
            ON authority.id = connection.authority_id
            AND authority.account_id = connection.account_id
            AND authority.organization_membership_id = p_owner_membership_id
            AND authority.resource_kind = 'subscription_connection'
            AND authority.resource_id = connection.id
            AND authority.generation = p_authority_generation
            AND authority.status = 'active' AND authority.revoked_at IS NULL
          WHERE connection.account_id = capability.account_id
            AND connection.id = capability.connection_id
            AND connection.provider = p_provider AND connection.ownership = 'personal'
            AND connection.owner_organization_membership_id = p_owner_membership_id
            AND connection.owner_subject_id = p_turn_human_subject_id
            AND connection.authority_generation = p_authority_generation
            AND connection.status = 'active'
        );

      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.subscription_runtime_capabilities capability
        JOIN subscription_connections connection ON connection.account_id = capability.account_id
          AND connection.id = capability.connection_id AND connection.provider = capability.provider
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'personal_access'
          AND capability.account_id = p_account_id AND capability.workspace_id = p_workspace_id
          AND capability.session_id = p_session_id AND capability.turn_id = p_turn_id
          AND capability.provider = p_provider
          AND capability.session_owner_subject_id = p_session_owner_subject_id
          AND capability.turn_human_subject_id = p_turn_human_subject_id
          AND connection.ownership = 'personal'
          AND connection.owner_organization_membership_id = p_owner_membership_id
          AND connection.authority_generation = p_authority_generation
          AND (record_connections IS NULL OR connection.id = ANY (record_connections))
          AND opengeni_private.subscription_personal_connection_visible(
            p_account_id, connection.id, p_owner_membership_id,
            p_session_owner_subject_id, p_turn_human_subject_id, p_provider
          )
      ) INTO allowed;

      IF minted_lifecycle THEN
        DELETE FROM opengeni_private.subscription_runtime_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'lifecycle' AND capability.account_id = p_account_id;
      END IF;
      IF NOT allowed THEN
        DELETE FROM opengeni_private.subscription_runtime_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'personal_access'
          AND capability.account_id = p_account_id AND capability.workspace_id = p_workspace_id
          AND capability.connection_id = ANY (minted_connections)
          AND capability.session_id = p_session_id AND capability.turn_id = p_turn_id
          AND capability.provider = p_provider
          AND capability.session_owner_subject_id = p_session_owner_subject_id
          AND capability.turn_human_subject_id = p_turn_human_subject_id;
        RETURN false;
      END IF;
      PERFORM pg_catalog.set_config('opengeni.session_owner_subject_id', p_session_owner_subject_id, true);
      PERFORM pg_catalog.set_config('opengeni.turn_human_subject_id', p_turn_human_subject_id, true);
      RETURN true;
    END
    $$;

CREATE FUNCTION opengeni_private.authorize_subscription_service_session_access(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_session_owner_subject_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE allowed boolean;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    OR nullif(current_setting('opengeni.subject_id', true), '') IS DISTINCT FROM 'service:subscription-core'
    OR p_session_owner_subject_id IS NULL
    OR nullif(current_setting('opengeni.initiating_human_subject_id', true), '')
      IS DISTINCT FROM p_session_owner_subject_id
  THEN RETURN false; END IF;

  INSERT INTO opengeni_private.subscription_runtime_capabilities (
    backend_pid, transaction_id, capability_kind, account_id
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'lifecycle', p_account_id)
  ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id) DO NOTHING;
  SELECT EXISTS (
    SELECT 1 FROM sessions session
    JOIN session_turns turn ON turn.account_id = session.account_id
      AND turn.workspace_id = session.workspace_id AND turn.session_id = session.id
    JOIN organization_memberships membership ON membership.account_id = session.account_id
      AND membership.id = session.owner_organization_membership_id
      AND membership.subject_id = session.owner_subject_id
    WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
      AND session.id = p_session_id AND session.owner_subject_id = p_session_owner_subject_id
      AND turn.id = p_turn_id AND turn.initiating_human_subject_id IS NULL
      AND membership.status = 'active' AND membership.revoked_at IS NULL
      AND session_reference_visible(p_account_id, p_workspace_id, p_session_id)
  ) INTO allowed;
  DELETE FROM opengeni_private.subscription_runtime_capabilities capability
  WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
    AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability.capability_kind = 'lifecycle' AND capability.account_id = p_account_id;
  IF NOT allowed THEN RETURN false; END IF;

  INSERT INTO opengeni_private.subscription_runtime_capabilities (
    backend_pid, transaction_id, capability_kind, account_id, workspace_id,
    session_id, turn_id, connection_id, session_owner_subject_id, turn_human_subject_id
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'session_access',
    p_account_id, p_workspace_id, p_session_id, p_turn_id, p_session_id,
    p_session_owner_subject_id, p_session_owner_subject_id)
  ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
  DO UPDATE SET workspace_id = EXCLUDED.workspace_id, session_id = EXCLUDED.session_id,
    turn_id = EXCLUDED.turn_id,
    session_owner_subject_id = EXCLUDED.session_owner_subject_id,
    turn_human_subject_id = EXCLUDED.turn_human_subject_id;
  PERFORM pg_catalog.set_config('opengeni.session_owner_subject_id', p_session_owner_subject_id, true);
  PERFORM pg_catalog.set_config('opengeni.turn_human_subject_id', p_session_owner_subject_id, true);
  RETURN true;
END
$$;

CREATE FUNCTION opengeni_private.authorize_subscription_session_access(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_session_owner_subject_id text, p_turn_human_subject_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    OR p_turn_human_subject_id IS DISTINCT FROM nullif(current_setting('opengeni.initiating_human_subject_id', true), '')
    OR p_session_owner_subject_id IS NULL OR p_turn_human_subject_id IS NULL
  THEN RETURN false; END IF;
  INSERT INTO opengeni_private.subscription_runtime_capabilities (
    backend_pid, transaction_id, capability_kind, account_id, workspace_id,
    session_id, turn_id, connection_id, session_owner_subject_id, turn_human_subject_id
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'session_access',
    p_account_id, p_workspace_id, p_session_id, p_turn_id, p_session_id,
    p_session_owner_subject_id, p_turn_human_subject_id)
  ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
  DO UPDATE SET workspace_id = EXCLUDED.workspace_id, session_id = EXCLUDED.session_id,
    turn_id = EXCLUDED.turn_id,
    session_owner_subject_id = EXCLUDED.session_owner_subject_id,
    turn_human_subject_id = EXCLUDED.turn_human_subject_id;
  IF NOT EXISTS (
      SELECT 1 FROM sessions session
      JOIN session_turns turn ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id AND turn.session_id = session.id
      JOIN organization_memberships membership ON membership.account_id = session.account_id
        AND membership.subject_id = session.owner_subject_id
      WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
        AND session.id = p_session_id AND session.owner_subject_id = p_session_owner_subject_id
        AND turn.id = p_turn_id AND turn.initiating_human_subject_id = p_turn_human_subject_id
        AND membership.status = 'active' AND membership.revoked_at IS NULL
        AND session_reference_visible(p_account_id, p_workspace_id, p_session_id)
    ) THEN
    DELETE FROM opengeni_private.subscription_runtime_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND capability.capability_kind = 'session_access'
      AND capability.account_id = p_account_id AND capability.connection_id = p_session_id;
    RETURN false;
  END IF;
  PERFORM pg_catalog.set_config('opengeni.session_owner_subject_id', p_session_owner_subject_id, true);
  PERFORM pg_catalog.set_config('opengeni.turn_human_subject_id', p_turn_human_subject_id, true);
  RETURN true;
END
$$;

CREATE FUNCTION opengeni_private.auto_assign_subscription_core_personal_workspace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      reach_provider text;
      previous text := current_setting('opengeni.subscription_core_auto_assign', true);
    BEGIN
      IF NEW.personal_workspace_id IS NOT NULL AND (TG_OP = 'INSERT'
          OR NEW.personal_workspace_id IS DISTINCT FROM OLD.personal_workspace_id) THEN
        FOR reach_provider IN SELECT DISTINCT auto.provider
            FROM opengeni_private.subscription_core_auto_assignments auto
            WHERE auto.account_id = NEW.account_id ORDER BY auto.provider LOOP
          PERFORM pg_catalog.set_config('opengeni.subscription_core_auto_assign',
            NEW.account_id::text, true);
          PERFORM opengeni_subscription_internal.apply_subscription_core_auto_assignments(
            reach_provider, NEW.account_id, NEW.personal_workspace_id, true);
          PERFORM pg_catalog.set_config('opengeni.subscription_core_auto_assign',
            coalesce(previous, ''), true);
        END LOOP;
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.auto_assign_subscription_core_workspace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      reach_provider text;
      previous text := current_setting('opengeni.subscription_core_auto_assign', true);
    BEGIN
      FOR reach_provider IN SELECT DISTINCT auto.provider
          FROM opengeni_private.subscription_core_auto_assignments auto
          WHERE auto.account_id = NEW.account_id ORDER BY auto.provider LOOP
        PERFORM pg_catalog.set_config('opengeni.subscription_core_auto_assign',
          NEW.account_id::text, true);
        PERFORM opengeni_subscription_internal.apply_subscription_core_auto_assignments(
          reach_provider, NEW.account_id, NEW.id, false);
        PERFORM pg_catalog.set_config('opengeni.subscription_core_auto_assign',
          coalesce(previous, ''), true);
      END LOOP;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.automatic_session_title_fanout_due_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT EXISTS (
      SELECT 1 FROM opengeni_private.automatic_session_title_fanout_outbox_v1 pending
      WHERE pending.delivered_at IS NULL
    )
  $$;

CREATE FUNCTION opengeni_private.backfill_product_lifecycle_facts(p_source text, p_batch_size integer DEFAULT 500) RETURNS TABLE(backfill_source text, enqueued_count integer, scanned_count integer, backfill_completed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
    DECLARE
      v_enabled boolean;
      v_progress opengeni_private.product_lifecycle_backfill_progress%ROWTYPE;
      v_registered_at timestamptz;
      v_boundary timestamptz;
      v_query text;
      v_row record;
      v_materialized bigint;
      v_scanned integer := 0;
      v_enqueued integer := 0;
      v_last_seq bigint;
      v_tables text[];
      v_table text;
      v_marker text;
      v_fact_type text;
      v_attribute text;
      v_subject_id text;
      v_account_id uuid;
      v_workspace_id uuid;
      v_dedupe_key text;
      v_occurred_at timestamptz;
      v_exported_subject text;
      v_subject_kind text;
      v_initiator jsonb;
      v_source_id uuid;
      v_payload jsonb;
      v_inserted integer := 0;
    BEGIN
      -- Operator-only: the login must be (a member of) the migration owner.
      IF NOT pg_has_role(session_user, '{{owner}}', 'MEMBER') THEN
        RAISE EXCEPTION 'the lifecycle backfill runs only as the migration owner'
          USING ERRCODE = '42501';
      END IF;
      IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 10000 THEN
        RAISE EXCEPTION 'backfill batch size must be between 1 and 10000'
          USING ERRCODE = '22023';
      END IF;
      SELECT c.lifecycle_facts_enabled INTO v_enabled
      FROM {{schema}}.host_export_config c WHERE c.id = 1;
      IF coalesce(v_enabled, false) = false THEN
        RAISE EXCEPTION 'no enabled lifecycle_fact consumer is registered'
          USING ERRCODE = '55000';
      END IF;
      SELECT * INTO v_progress
      FROM opengeni_private.product_lifecycle_backfill_progress progress
      WHERE progress.source = p_source
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'unknown lifecycle backfill source' USING ERRCODE = '22023';
      END IF;
      IF v_progress.completed_at IS NOT NULL THEN
        RETURN QUERY SELECT p_source, 0, 0, true;
        RETURN;
      END IF;

      -- Transaction-local capability for this call only: it opens the
      -- SELECT-only source policies (migrations 0568 onward). It is removed
      -- before returning.
      INSERT INTO opengeni_private.lifecycle_backfill_read_capabilities (
        backend_pid, transaction_id
      ) VALUES (pg_backend_pid(), pg_current_xact_id())
      ON CONFLICT DO NOTHING;

      IF v_progress.materialized_at IS NULL THEN
        -- Live capture of the new kinds began at this migration or at the
        -- first lifecycle consumer registration, whichever came later.
        SELECT min(consumer.created_at) INTO v_registered_at
        FROM {{schema}}.host_export_consumers consumer
        WHERE consumer.export_kind = 'lifecycle_fact';
        v_boundary := CASE WHEN v_progress.live_capture_from IS NULL THEN 'infinity'::timestamptz
          ELSE greatest(v_progress.live_capture_from, coalesce(v_registered_at, '-infinity'))
        END;
        v_query := CASE p_source
          WHEN 'auth.sign_up' THEN $q$
            SELECT 'auth.sign_up',
              opengeni_private.product_lifecycle_auth_method(first.provider_id),
              'user:' || first.user_id, NULL::uuid, NULL::uuid, first.user_id::text,
              first.created_at
            FROM (
              SELECT DISTINCT ON (identity.user_id) identity.user_id, identity.provider_id,
                identity.created_at
              FROM {{schema}}.auth_identities identity
              ORDER BY identity.user_id, identity.created_at, identity.id
            ) first
          $q$
          WHEN 'auth.email_verified' THEN $q$
            -- A social provider verified the address at creation; a verified
            -- email-password account is dated by its last update (approximate).
            SELECT 'auth.email_verified', NULL::text, 'user:' || person.id, NULL::uuid,
              NULL::uuid, person.id::text, coalesce((
                SELECT CASE WHEN identity.provider_id <> 'credential' THEN person.created_at END
                FROM {{schema}}.auth_identities identity
                WHERE identity.user_id = person.id
                ORDER BY identity.created_at, identity.id
                LIMIT 1
              ), person.updated_at)
            FROM {{schema}}.auth_users person
            WHERE person.email_verified
          $q$
          WHEN 'auth.sign_in' THEN $q$
            -- Discarded session-set provider sessions are created already expired.
            SELECT 'auth.sign_in',
              opengeni_private.product_lifecycle_auth_method(coalesce(binding.provider_id, (
                SELECT min(identity.provider_id) FROM {{schema}}.auth_identities identity
                WHERE identity.user_id = session.user_id HAVING count(*) = 1
              ))),
              'user:' || session.user_id, NULL::uuid, NULL::uuid, session.id::text,
              session.created_at
            FROM {{schema}}.auth_sessions session
            LEFT JOIN {{schema}}.canonical_human_login_bindings binding
              ON binding.id = session.login_binding_id
            WHERE session.expires_at > session.created_at + interval '1 minute'
          $q$
          WHEN 'organization.setup' THEN $q$
            SELECT 'organization.setup', 'created', 'user:' || receipt.auth_user_id,
              receipt.account_id, NULL::uuid, receipt.account_id::text, receipt.created_at
            FROM {{schema}}.self_service_organization_setup_receipts receipt
            UNION ALL
            SELECT 'organization.setup', 'additional', receipt.actor_subject_id,
              receipt.account_id, NULL::uuid, receipt.account_id::text, receipt.created_at
            FROM {{schema}}.additional_organization_creation_receipts receipt
          $q$
          WHEN 'model.connected' THEN $q$
            SELECT 'model.connected', 'codex', credential.connected_by_subject_id,
              credential.account_id, credential.workspace_id, credential.id::text,
              credential.created_at
            FROM {{schema}}.codex_subscription_credentials credential
            UNION ALL
            SELECT 'model.connected', 'supergrok', credential.connected_by_subject_id,
              credential.account_id, credential.workspace_id, credential.id::text,
              credential.created_at
            FROM {{schema}}.xai_subscription_credentials credential
            UNION ALL
            -- A provider row is connected by its first operation and by every
            -- operation that reactivates it after a revoke, as the live trigger.
            SELECT 'model.connected', operation.provider_kind, NULL::text,
              operation.account_id, NULL::uuid,
              connection.id::text || ':' || operation.operation_id::text,
              operation.created_at
            FROM (
              SELECT candidate.*, lag(candidate.result_status) OVER (
                PARTITION BY candidate.account_id, candidate.provider_kind
                ORDER BY candidate.created_at, candidate.id
              ) AS previous_status
              FROM {{schema}}.organization_model_provider_connection_operations candidate
            ) operation
            JOIN {{schema}}.organization_model_provider_connections connection
              ON connection.account_id = operation.account_id
              AND connection.provider_kind = operation.provider_kind
            WHERE operation.result_status = 'active'
              AND operation.previous_status IS DISTINCT FROM 'active'
          $q$
          WHEN 'credits.purchased' THEN $q$
            SELECT 'credits.purchased', NULL::text, NULL::text, entry.account_id, NULL::uuid,
              entry.id::text, entry.created_at
            FROM {{schema}}.credit_ledger_entries entry
            WHERE entry.type = 'credit_topup'
          $q$
          WHEN 'credits.granted' THEN $q$
            -- The trial grant ran as its new owner, whose id is its source id.
            SELECT 'credits.granted',
              opengeni_private.credit_grant_class(entry.type, entry.source_type),
              CASE WHEN entry.source_type = 'verified_signup_trial'
                THEN 'user:' || entry.source_id END,
              entry.account_id, NULL::uuid, entry.id::text, entry.created_at
            FROM {{schema}}.credit_ledger_entries entry
            WHERE entry.type IN ('grant', 'manual_credit_grant') AND entry.amount_micros > 0
          $q$
          WHEN 'connection.created' THEN $q$
            SELECT 'connection.created',
              opengeni_private.product_lifecycle_connection_class(connection.provider_domain),
              connection.created_by_subject_id, connection.account_id,
              connection.workspace_id, connection.id::text, connection.created_at
            FROM {{schema}}.connections connection
          $q$
          WHEN 'connection.revoked' THEN $q$
            SELECT 'connection.revoked',
              opengeni_private.product_lifecycle_connection_class(connection.provider_domain),
              connection.updated_by_subject_id, connection.account_id,
              connection.workspace_id,
              connection.id::text || ':revoked:' || connection.version::text,
              connection.updated_at
            FROM {{schema}}.connections connection
            WHERE connection.status = 'revoked' AND connection.updated_at < $1
          $q$
          WHEN 'scheduled_task.created' THEN $q$
            SELECT 'scheduled_task.created', NULL::text, task.created_by_subject_id,
              task.account_id, task.workspace_id, task.id::text, task.created_at
            FROM {{schema}}.scheduled_tasks task
          $q$
          WHEN 'skill.installed' THEN $q$
            SELECT 'skill.installed', NULL::text, preference.created_by_subject_id,
              binding.account_id, binding.workspace_id, binding.preference_id::text,
              preference.created_at
            FROM {{schema}}.skill_source_bindings binding
            JOIN {{schema}}.preference_registry_preferences preference
              ON preference.account_id = binding.account_id
              AND preference.id = binding.preference_id
          $q$
          WHEN 'slack.user_linked' THEN $q$
            SELECT 'slack.user_linked', NULL::text, link.subject_id, link.account_id,
              link.workspace_id, link.id::text, link.created_at
            FROM {{schema}}.slack_bot_user_links link
          $q$
          WHEN 'machine.enrolled' THEN $q$
            SELECT 'machine.enrolled', NULL::text, NULL::text, enrollment.account_id,
              enrollment.workspace_id, enrollment.id::text, enrollment.created_at
            FROM {{schema}}.enrollments enrollment
          $q$
          WHEN 'member.joined' THEN $q$
            -- A provisioning row never became a member; the founder is covered
            -- by organization.setup.
            SELECT 'member.joined', NULL::text, membership.subject_id,
              membership.account_id, NULL::uuid, membership.id::text, membership.created_at
            FROM {{schema}}.organization_memberships membership
            WHERE membership.status <> 'provisioning'
              AND EXISTS (
                SELECT 1 FROM {{schema}}.organization_memberships earlier
                WHERE earlier.account_id = membership.account_id
                  AND earlier.id <> membership.id
                  AND earlier.subject_id <> membership.subject_id
                  AND earlier.created_at <= membership.created_at
              )
          $q$
          WHEN 'user.active' THEN $q$
            -- Approximation from stored browser sessions: the UTC days on
            -- which a person signed in or a session was refreshed.
            SELECT 'user.active', NULL::text, 'user:' || activity.user_id, NULL::uuid,
              NULL::uuid, 'user:' || activity.user_id || ':' || activity.day::text,
              min(activity.at)
            FROM (
              SELECT session.user_id, session.created_at AS at,
                (session.created_at AT TIME ZONE 'UTC')::date AS day
              FROM {{schema}}.auth_sessions session
              WHERE session.expires_at > session.created_at + interval '1 minute'
              UNION ALL
              SELECT session.user_id, session.updated_at,
                (session.updated_at AT TIME ZONE 'UTC')::date
              FROM {{schema}}.auth_sessions session
              WHERE session.expires_at > session.created_at + interval '1 minute'
            ) activity
            WHERE activity.at < $1
              AND ('user:' || activity.user_id) ~ '^user:[A-Za-z0-9_-]{8,128}$'
            GROUP BY activity.user_id, activity.day
          $q$
          ELSE NULL
        END;
        IF v_query IS NULL THEN
          RAISE EXCEPTION 'unknown lifecycle backfill source' USING ERRCODE = '22023';
        END IF;

        -- Fail closed rather than complete with zero rows: every FORCE-RLS
        -- source table must carry the read policy, and each of its
        -- restrictive SELECT policies must admit the capability.
        v_tables := CASE p_source
          WHEN 'organization.setup' THEN ARRAY[
            'self_service_organization_setup_receipts',
            'additional_organization_creation_receipts'
          ]
          WHEN 'model.connected' THEN ARRAY[
            'codex_subscription_credentials', 'xai_subscription_credentials',
            'organization_model_provider_connections',
            'organization_model_provider_connection_operations'
          ]
          WHEN 'credits.purchased' THEN ARRAY['credit_ledger_entries']
          WHEN 'credits.granted' THEN ARRAY['credit_ledger_entries']
          WHEN 'connection.created' THEN ARRAY['connections']
          WHEN 'connection.revoked' THEN ARRAY['connections']
          WHEN 'scheduled_task.created' THEN ARRAY['scheduled_tasks']
          WHEN 'skill.installed' THEN ARRAY[
            'skill_source_bindings', 'preference_registry_preferences'
          ]
          WHEN 'slack.user_linked' THEN ARRAY['slack_bot_user_links']
          WHEN 'machine.enrolled' THEN ARRAY['enrollments']
          WHEN 'member.joined' THEN ARRAY['organization_memberships']
          ELSE ARRAY[]::text[]
        END;
        FOREACH v_table IN ARRAY v_tables LOOP
          IF NOT EXISTS (
            SELECT 1 FROM pg_policy policy
            WHERE policy.polrelid = format('%I.%I', '{{schema}}', v_table)::regclass
              AND policy.polname = 'lifecycle_backfill_read'
          ) OR EXISTS (
            SELECT 1 FROM pg_policy policy
            WHERE policy.polrelid = format('%I.%I', '{{schema}}', v_table)::regclass
              AND NOT policy.polpermissive
              AND policy.polcmd IN ('r', '*')
              AND position('lifecycle_backfill_read_active'
                IN coalesce(pg_get_expr(policy.polqual, policy.polrelid), '')) = 0
          ) THEN
            RAISE EXCEPTION 'lifecycle backfill read access is missing on %', v_table
              USING ERRCODE = '55000';
          END IF;
        END LOOP;

        -- One read of the source tables, ACCESS SHARE only, under the
        -- transaction-local read capability opened above. Sign-in methods are
        -- read under the canonical identity lifecycle marker, exactly like the
        -- live sign-in capture. The statement is bounded by the caller's
        -- statement_timeout (the runner sets one).
        v_marker := current_setting('opengeni.canonical_human_identity_lifecycle', true);
        PERFORM set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
        EXECUTE
          'INSERT INTO opengeni_private.product_lifecycle_backfill_queue ('
            || 'source, fact_type, attribute, subject_id, account_id, workspace_id, '
            || 'dedupe_key, occurred_at) '
            || 'SELECT $2, candidate.* FROM (' || v_query || ') AS candidate('
            || 'fact_type, attribute, subject_id, account_id, workspace_id, dedupe_key, '
            || 'occurred_at) ORDER BY candidate.occurred_at, candidate.dedupe_key'
          USING v_boundary, p_source;
        GET DIAGNOSTICS v_materialized = ROW_COUNT;
        PERFORM set_config(
          'opengeni.canonical_human_identity_lifecycle', coalesce(v_marker, ''), true
        );
        UPDATE opengeni_private.product_lifecycle_backfill_progress progress
        SET materialized_at = clock_timestamp(), materialized = v_materialized,
            updated_at = clock_timestamp()
        WHERE progress.source = p_source;
      END IF;

      -- One primary-key page of the private queue.
      FOR v_row IN
        SELECT queued.* FROM opengeni_private.product_lifecycle_backfill_queue queued
        WHERE queued.source = p_source
        ORDER BY queued.seq
        LIMIT p_batch_size
      LOOP
        v_scanned := v_scanned + 1;
        v_last_seq := v_row.seq;
        v_fact_type := v_row.fact_type;
        v_attribute := v_row.attribute;
        v_subject_id := v_row.subject_id;
        v_account_id := v_row.account_id;
        v_workspace_id := v_row.workspace_id;
        v_dedupe_key := v_row.dedupe_key;
        v_occurred_at := v_row.occurred_at;
        v_inserted := 0;
        -- Validate and write the one fact: a fixed type and attribute, a
        -- pseudonymous subject, and a deterministic name-based id.
        IF v_fact_type IS NOT NULL THEN
          SELECT c.lifecycle_facts_enabled INTO v_enabled
          FROM {{schema}}.host_export_config c WHERE c.id = 1
          FOR SHARE;
          IF coalesce(v_enabled, false) THEN
            IF NOT opengeni_private.product_lifecycle_fact_valid(v_fact_type, v_attribute) THEN
              RAISE EXCEPTION 'invalid product lifecycle fact' USING ERRCODE = '22023';
            END IF;
            IF v_dedupe_key IS NULL OR length(v_dedupe_key) NOT BETWEEN 1 AND 512 THEN
              RAISE EXCEPTION 'invalid product lifecycle fact key' USING ERRCODE = '22023';
            END IF;
            IF v_workspace_id IS NOT NULL AND v_account_id IS NULL THEN
              RAISE EXCEPTION 'product lifecycle workspace requires its organization'
                USING ERRCODE = '22023';
            END IF;
            v_exported_subject := CASE
              WHEN v_subject_id ~ '^(user|api_key):[A-Za-z0-9_-]{8,128}$' THEN v_subject_id
              ELSE NULL
            END;
            v_subject_kind := CASE
              WHEN nullif(btrim(coalesce(v_subject_id, '')), '') IS NULL THEN 'none'
              WHEN v_exported_subject IS NOT NULL AND starts_with(v_exported_subject, 'user:') THEN 'user'
              WHEN v_exported_subject IS NOT NULL THEN 'api_key'
              WHEN starts_with(v_subject_id, 'service:') THEN 'service'
              ELSE 'other'
            END;
            v_initiator := CASE
              WHEN v_exported_subject IS NULL THEN NULL
              ELSE jsonb_build_object('kind', 'subject', 'subjectId', v_exported_subject)
            END;
            v_source_id := overlay(overlay(md5(
              'opengeni-product-lifecycle-fact:v1:' || v_fact_type || ':' || v_dedupe_key
            ) placing '5' from 13) placing '8' from 17)::uuid;
            v_payload := jsonb_build_object(
              'factType', v_fact_type,
              'attribute', v_attribute,
              'subjectKind', v_subject_kind
            );
            INSERT INTO {{schema}}.host_export_outbox (
              export_kind, source_id, account_id, workspace_id, event_type,
              idempotency_key, initiator, initiator_context, origin, payload,
              envelope_bytes, occurred_at, source_recorded_at, enqueued_at
            ) VALUES (
              'lifecycle_fact', v_source_id, v_account_id, v_workspace_id, v_fact_type,
              'lifecycle_fact:' || v_source_id::text, v_initiator, '{}'::jsonb, NULL,
              v_payload,
              octet_length(v_payload::text)
                + octet_length(coalesce(v_initiator, 'null'::jsonb)::text) + 512,
              coalesce(v_occurred_at, clock_timestamp()), clock_timestamp(), clock_timestamp()
            )
            ON CONFLICT (export_kind, source_id) DO NOTHING;
            GET DIAGNOSTICS v_inserted = ROW_COUNT;
          END IF;
        END IF;
        v_enqueued := v_enqueued + v_inserted;
      END LOOP;
      IF v_last_seq IS NOT NULL THEN
        DELETE FROM opengeni_private.product_lifecycle_backfill_queue queued
        WHERE queued.source = p_source AND queued.seq <= v_last_seq;
      END IF;

      DELETE FROM opengeni_private.lifecycle_backfill_read_capabilities capability
      WHERE capability.backend_pid = pg_backend_pid()
        AND capability.transaction_id = pg_current_xact_id();

      UPDATE opengeni_private.product_lifecycle_backfill_progress progress
      SET cursor_seq = coalesce(v_last_seq, progress.cursor_seq),
          scanned = progress.scanned + v_scanned,
          enqueued = progress.enqueued + v_enqueued,
          completed_at = CASE WHEN v_scanned < p_batch_size THEN clock_timestamp() END,
          updated_at = clock_timestamp()
      WHERE progress.source = p_source;
      RETURN QUERY SELECT p_source, v_enqueued, v_scanned, v_scanned < p_batch_size;
    END $_$;

CREATE FUNCTION opengeni_private.begin_site_session_cancellation(a uuid, w uuid, site uuid, root uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE token uuid:=gen_random_uuid(); actor text:=nullif(current_setting('opengeni.subject_id',true),'');
      human text:=nullif(current_setting('opengeni.initiating_human_subject_id',true),'');
    BEGIN
      IF a IS NULL OR w IS NULL OR site IS NULL OR root IS NULL
        OR a IS DISTINCT FROM nullif(current_setting('opengeni.account_id',true),'')::uuid
        OR w IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id',true),'')::uuid
        OR actor LIKE 'site:%' THEN
        RAISE EXCEPTION 'Site lifecycle cancellation requires exact host scope' USING ERRCODE='42501';
      END IF;
      -- Trusted application lifecycle only. The mapping proves association
      -- without granting a service principal transcript access.
      IF NOT EXISTS(SELECT 1 FROM {{schema}}.site_runtime_conversations c
        WHERE c.account_id=a AND c.workspace_id=w AND c.site_id=site AND c.session_id=root) THEN
        RAISE EXCEPTION 'Site cancellation target is unavailable' USING ERRCODE='42501';
      END IF;
      INSERT INTO opengeni_private.site_session_cancellation_capabilities
        VALUES(token,{{schema_oid}}::oid,pg_backend_pid(),pg_current_xact_id(),a,w,site,root,actor,human);
      -- Root identity avoids the generic hidden-ancestor reader entirely.
      IF NOT EXISTS(SELECT 1 FROM {{schema}}.sessions s WHERE s.account_id=a AND s.workspace_id=w
        AND s.id=root AND s.site_id=site AND s.site_access_root_id=root
        AND s.root_session_id=root AND s.parent_session_id IS NULL) THEN
        DELETE FROM opengeni_private.site_session_cancellation_capabilities WHERE capability_id=token;
        RETURN NULL;
      END IF;
      RETURN token;
    END
    $$;

CREATE FUNCTION opengeni_private.begin_subscription_codex_apps_refresh(p_account_id uuid, p_workspace_id uuid, p_connection_id uuid) RETURNS TABLE(refresh_generation bigint, credential_encrypted text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      target subscription_connections%ROWTYPE;
      minted boolean := false;
    BEGIN
      IF p_connection_id IS NULL
        OR p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
      THEN RETURN; END IF;
      -- The same key as chat refresh: one provider refresh per connection.
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('subscription-refresh:' || p_connection_id::text, 0)
      );
      SELECT * INTO target
      FROM opengeni_private.subscription_codex_apps_designation_target(
        p_account_id, p_workspace_id
      );
      IF NOT FOUND OR target.id IS DISTINCT FROM p_connection_id
        OR target.status IS DISTINCT FROM 'active'
      THEN RETURN; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        connection_id, provider
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
        'codex_apps_refresh_authorized', p_account_id, p_workspace_id, p_connection_id, 'codex'
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO minted;
      -- One refresh per connection per transaction.
      IF minted IS DISTINCT FROM true THEN RETURN; END IF;

      refresh_generation := target.refresh_generation;
      credential_encrypted := target.credential_encrypted;
      expires_at := target.expires_at;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION opengeni_private.begin_subscription_core_connection_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_connection_id uuid, p_operation_id uuid, p_attempt_id uuid, p_holder_id text, p_generation bigint) RETURNS TABLE(refresh_generation bigint, credential_encrypted text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      target subscription_connections%ROWTYPE;
      minted boolean := false;
    BEGIN
      IF p_connection_id IS NULL
        OR p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
      THEN RETURN; END IF;
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('subscription-refresh:' || p_connection_id::text, 0)
      );
      SELECT * INTO target
      FROM opengeni_subscription_internal.subscription_core_connection_target(
        p_provider, p_account_id, p_workspace_id, p_connection_id,
        p_operation_id, p_attempt_id, p_holder_id, p_generation
      );
      IF NOT FOUND OR target.status IS DISTINCT FROM 'active' THEN RETURN; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        connection_id, provider
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
        'connection_refresh_authorized', p_account_id, p_workspace_id, p_connection_id, p_provider
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO minted;
      IF minted IS DISTINCT FROM true THEN RETURN; END IF;

      refresh_generation := target.refresh_generation;
      credential_encrypted := target.credential_encrypted;
      expires_at := target.expires_at;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION opengeni_private.begin_subscription_core_owned_connection_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_connection_id uuid) RETURNS TABLE(refresh_generation bigint, credential_encrypted text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      target subscription_connections%ROWTYPE;
      owned boolean := false;
      minted boolean := false;
    BEGIN
      
      IF p_workspace_id IS NULL OR p_connection_id IS NULL
        OR NOT opengeni_subscription_internal.subscription_core_writer_context(
          p_provider, p_account_id, p_workspace_id, p_subject_id)

      THEN RETURN; END IF;
      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('subscription-refresh:' || p_connection_id::text, 0)
      );
      
      PERFORM opengeni_subscription_internal.grant_subscription_core_owner_capability(
        p_provider, 'connection_owner', p_account_id, p_workspace_id, p_subject_id,
        '00000000-0000-0000-0000-000000000000'::uuid);
      SELECT connection.* INTO target
      FROM subscription_connections connection
      JOIN organization_memberships membership
        ON membership.account_id = connection.account_id
       AND membership.id = connection.owner_organization_membership_id
      JOIN organization_user_resource_authorities authority
        ON authority.account_id = connection.account_id
       AND authority.id = connection.authority_id
       AND authority.resource_kind = 'subscription_connection'
       AND authority.resource_id = connection.id
       AND authority.organization_membership_id = membership.id
       AND authority.generation = connection.authority_generation
       AND authority.status = 'active' AND authority.revoked_at IS NULL
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
        AND connection.provider = p_provider
        AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND connection.ownership = 'personal' AND connection.disconnected_at IS NULL
        AND connection.owner_subject_id = p_subject_id
        AND membership.subject_id = p_subject_id
        AND membership.personal_workspace_id = p_workspace_id
        AND membership.status = 'active' AND membership.revoked_at IS NULL;
      -- The organization's effective personal-connections rule, exactly as
      -- the 0707 turn target, refresh begin and personal connect apply it
      -- (an override of a locked setting is already ignored there).
      owned := FOUND AND coalesce((subscription_effective_settings(p_account_id, p_workspace_id)
        #>> '{values,personalConnectionsAllowed}')::boolean, false);

      IF owned AND target.status = 'active' AND target.credential_encrypted IS NOT NULL THEN
        INSERT INTO opengeni_private.subscription_runtime_capabilities (
          backend_pid, transaction_id, capability_kind, account_id, workspace_id,
          connection_id, provider
        ) VALUES (
          pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
          'connection_refresh_authorized', p_account_id, p_workspace_id, target.id, p_provider
        ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
          DO NOTHING
        RETURNING true INTO minted;
      END IF;
      PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(
        p_provider, p_account_id);
      IF minted IS DISTINCT FROM true THEN RETURN; END IF;
      refresh_generation := target.refresh_generation;
      credential_encrypted := target.credential_encrypted;
      expires_at := target.expires_at;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION opengeni_private.begin_subscription_core_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_session_owner_subject_id text, p_turn_human_subject_id text, p_connection_id uuid, p_holder_id text, p_lease_generation bigint) RETURNS TABLE(refresh_generation bigint, credential_encrypted text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      session_owner text;
      turn_human text;
      capability_owner text;
      capability_human text;
      target subscription_connections%ROWTYPE;
      authorized boolean := false;
      personal_authorized boolean := false;
      ownerless_session boolean := false;
      had_personal_access boolean := false;
      minted boolean := false;
      lease_current boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL OR p_session_id IS NULL OR p_turn_id IS NULL
        OR p_lease_generation IS NULL OR p_lease_generation < 1
        OR p_holder_id IS NULL OR length(btrim(p_holder_id)) NOT BETWEEN 1 AND 256
        OR NOT EXISTS (SELECT 1 FROM opengeni_private.subscription_core_providers registry
          WHERE registry.provider = p_provider)
      THEN RETURN; END IF;

      PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('subscription-refresh:' || p_connection_id::text, 0)
      );

      SELECT session.owner_subject_id, turn.initiating_human_subject_id
        INTO session_owner, turn_human
      FROM sessions session
      JOIN session_turns turn ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id AND turn.session_id = session.id
      WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
        AND session.id = p_session_id AND turn.id = p_turn_id;
      IF NOT FOUND OR session_owner IS DISTINCT FROM p_session_owner_subject_id
        OR turn_human IS DISTINCT FROM p_turn_human_subject_id
      THEN RETURN; END IF;
      ownerless_session := session_owner IS NULL;

      IF session_owner IS NULL THEN
        authorized := opengeni_private.authorize_subscription_ownerless_session_access(
            p_account_id, p_workspace_id, p_session_id, p_turn_id
          );
      ELSIF turn_human IS NULL THEN
        authorized := opengeni_private.authorize_subscription_service_session_access(
          p_account_id, p_workspace_id, p_session_id, p_turn_id, session_owner
        );
      ELSE
        authorized := opengeni_private.authorize_subscription_session_access(
          p_account_id, p_workspace_id, p_session_id, p_turn_id, session_owner, turn_human
        );
      END IF;
      IF NOT authorized THEN RETURN; END IF;
      IF ownerless_session THEN
        capability_owner := NULL;
        capability_human := NULL;
      ELSE
        capability_owner := session_owner;
        capability_human := coalesce(turn_human, session_owner);
      END IF;

      SELECT EXISTS (
        SELECT 1 FROM subscription_leases lease
        WHERE lease.account_id = p_account_id AND lease.workspace_id = p_workspace_id
          AND lease.session_id = p_session_id AND lease.turn_id = p_turn_id
          AND lease.provider = p_provider AND lease.connection_id = p_connection_id
          AND lease.holder_id = p_holder_id AND lease.generation = p_lease_generation
          AND lease.leased_until > pg_catalog.clock_timestamp()
      ) INTO lease_current;
      IF NOT lease_current THEN RETURN; END IF;

      IF NOT ownerless_session AND turn_human IS NOT NULL THEN
        SELECT EXISTS (
          SELECT 1 FROM opengeni_private.subscription_runtime_capabilities capability
          WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
            AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
            AND capability.capability_kind = 'personal_access'
            AND capability.account_id = p_account_id
            AND capability.connection_id = p_connection_id
        ) INTO had_personal_access;
        IF had_personal_access THEN
          SELECT EXISTS (
            SELECT 1 FROM opengeni_private.subscription_runtime_capabilities capability
            WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
              AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
              AND capability.capability_kind = 'personal_access'
              AND capability.account_id = p_account_id
              AND capability.connection_id = p_connection_id
              AND capability.workspace_id = p_workspace_id
              AND capability.session_id = p_session_id
              AND capability.turn_id = p_turn_id
              AND capability.provider = p_provider
              AND capability.session_owner_subject_id = session_owner
              AND capability.turn_human_subject_id = turn_human
          ) INTO personal_authorized;
        ELSE
          personal_authorized := opengeni_private.authorize_subscription_personal_access(
            p_account_id, p_workspace_id, p_session_id, p_turn_id, p_connection_id,
            p_provider, session_owner, turn_human
          );
        END IF;
      END IF;

      SELECT connection.* INTO target
      FROM subscription_connections connection
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
        AND connection.provider = p_provider AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND connection.status = 'active';
      authorized := FOUND
        AND NOT (ownerless_session AND (
          target.ownership IS DISTINCT FROM 'shared'
          OR (
            target.scope_kind IS DISTINCT FROM 'organization'
            AND target.scope_kind IS DISTINCT FROM 'workspaces'
          )
        ))
        AND NOT (target.ownership = 'personal' AND NOT personal_authorized)
        AND NOT (target.ownership = 'personal' AND NOT coalesce((subscription_effective_settings(
          p_account_id, p_workspace_id
        ) #>> '{values,personalConnectionsAllowed}')::boolean, false))
        AND opengeni_private.subscription_connection_visible(
          p_account_id, p_workspace_id, target.id, target.ownership, target.scope_kind,
          target.owner_organization_membership_id, target.owner_subject_id, target.provider
        );

      IF NOT had_personal_access THEN
        DELETE FROM opengeni_private.subscription_runtime_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_kind = 'personal_access'
          AND capability.account_id = p_account_id
          AND capability.connection_id = p_connection_id;
      END IF;
      IF NOT coalesce(authorized, false) THEN RETURN; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        session_id, turn_id, connection_id, provider,
        session_owner_subject_id, turn_human_subject_id
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'refresh_authorized',
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_connection_id, p_provider,
        capability_owner, capability_human
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO minted;
      IF minted IS DISTINCT FROM true THEN RETURN; END IF;

      refresh_generation := target.refresh_generation;
      credential_encrypted := target.credential_encrypted;
      expires_at := target.expires_at;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION opengeni_private.bind_connection_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  caller_subject text := nullif(pg_catalog.current_setting('opengeni.subject_id', true), '');
  membership_id uuid;
  authority_value uuid;
  identity_changed boolean;
  backfill_transition boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.origin_workspace_id := NEW.workspace_id;
    NEW.authority_generation := 1;
    IF NEW.subject_id IS NULL THEN
      NEW.authority_scope := 'workspace';
      NEW.authority_id := NULL;
      NEW.owner_organization_membership_id := NULL;
      RETURN NEW;
    END IF;
    IF caller_subject IS DISTINCT FROM NEW.subject_id THEN
      RAISE EXCEPTION 'personal connection owner must be the authenticated subject'
        USING ERRCODE = '42501';
    END IF;
    SELECT binding.membership_id, binding.authority_id
      INTO membership_id, authority_value
    FROM opengeni_private.bind_connection_owner_authority(
      NEW.account_id, caller_subject, NEW.id, NEW.workspace_id
    ) binding;
    IF membership_id IS NULL THEN
      IF opengeni_private.session_tenancy_account_activated(NEW.account_id) THEN
        RAISE EXCEPTION 'activated organization requires connection membership authority'
          USING ERRCODE = '42501';
      END IF;
      NEW.authority_scope := 'legacy_user';
      NEW.authority_id := NULL;
      NEW.owner_organization_membership_id := NULL;
      RETURN NEW;
    END IF;
    NEW.authority_scope := 'user';
    NEW.authority_id := authority_value;
    NEW.owner_organization_membership_id := membership_id;
    RETURN NEW;
  END IF;

  backfill_transition :=
    opengeni_private.connection_tenancy_backfill_capability_active(NEW.account_id)
    AND OLD.authority_scope = 'legacy_user'
    AND OLD.subject_id IS NOT NULL
    AND OLD.authority_id IS NULL
    AND OLD.owner_organization_membership_id IS NULL
    AND NEW.account_id IS NOT DISTINCT FROM OLD.account_id
    AND NEW.workspace_id IS NOT DISTINCT FROM OLD.workspace_id
    AND NEW.subject_id IS NOT DISTINCT FROM OLD.subject_id
    AND NEW.authority_scope = 'user'
    AND NEW.authority_id IS NOT NULL
    AND NEW.owner_organization_membership_id IS NOT NULL
    AND NEW.origin_workspace_id IS NOT DISTINCT FROM OLD.origin_workspace_id;

  IF NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
    OR NEW.subject_id IS DISTINCT FROM OLD.subject_id
    OR NEW.authority_scope IS DISTINCT FROM OLD.authority_scope
    OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
    OR NEW.owner_organization_membership_id IS DISTINCT FROM OLD.owner_organization_membership_id
    OR NEW.origin_workspace_id IS DISTINCT FROM OLD.origin_workspace_id
  THEN
    IF NOT backfill_transition THEN
      RAISE EXCEPTION 'connection owner authority is immutable' USING ERRCODE = '23514';
    END IF;
    SELECT binding.membership_id INTO membership_id
    FROM opengeni_private.bind_connection_owner_authority(
      NEW.account_id, NEW.subject_id
    ) binding;
    IF membership_id IS DISTINCT FROM NEW.owner_organization_membership_id THEN
      RAISE EXCEPTION 'connection backfill membership authority is unavailable'
        USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM organization_user_resource_authorities authority
    WHERE authority.id = NEW.authority_id
      AND authority.account_id = NEW.account_id
      AND authority.organization_membership_id = NEW.owner_organization_membership_id
      AND authority.resource_kind = 'connection' AND authority.resource_id = NEW.id
      AND authority.origin_workspace_id = NEW.origin_workspace_id
      AND authority.generation = 1
      AND authority.status = 'active' AND authority.revoked_at IS NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'connection backfill common authority is unavailable'
        USING ERRCODE = '42501';
    END IF;
    NEW.authority_generation := OLD.authority_generation + 1;
    RETURN NEW;
  END IF;

  identity_changed := NEW.provider_domain IS DISTINCT FROM OLD.provider_domain
    OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.status IS DISTINCT FROM OLD.status;
  IF identity_changed THEN
    NEW.authority_generation := OLD.authority_generation + 1;
  ELSIF NEW.authority_generation NOT IN (
    OLD.authority_generation, OLD.authority_generation + 1
  ) THEN
    RAISE EXCEPTION 'connection authority generation must be stable or advance once'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.bind_connection_owner_authority(p_account_id uuid, p_subject_id text, p_connection_id uuid DEFAULT NULL::uuid, p_workspace_id uuid DEFAULT NULL::uuid, OUT membership_id uuid, OUT authority_id uuid) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  previous_lifecycle text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  membership_id := NULL;
  authority_id := NULL;
  IF pg_catalog.pg_trigger_depth() = 0
    OR p_account_id IS NULL OR p_subject_id IS NULL
    OR p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RETURN;
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'connection_authority_binding', true
  );
  SELECT membership.id INTO membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_subject_id
    AND membership.status = 'active' AND membership.revoked_at IS NULL
  FOR SHARE;
  IF membership_id IS NOT NULL AND p_connection_id IS NOT NULL
    AND p_workspace_id IS NOT NULL
  THEN
    authority_id := pg_catalog.gen_random_uuid();
    INSERT INTO organization_user_resource_authorities (
      id, account_id, organization_membership_id, resource_kind, resource_id,
      origin_workspace_id, generation, status
    ) VALUES (
      authority_id, p_account_id, membership_id, 'connection', p_connection_id,
      p_workspace_id, 1, 'active'
    );
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RETURN;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

CREATE FUNCTION opengeni_private.bound_workspace_control_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  source_bytes integer;
BEGIN
  IF NEW.reason IS NULL THEN
    NEW.reason_original_bytes := NULL;
  ELSE
    source_bytes := octet_length(NEW.reason);
    IF TG_OP = 'INSERT' THEN
      NEW.reason_original_bytes := greatest(source_bytes, coalesce(NEW.reason_original_bytes, 0));
    ELSIF NEW.reason IS DISTINCT FROM OLD.reason THEN
      -- An update from an old binary carries the old metadata column even
      -- though it knows only `reason`. A genuinely changed raw value starts a
      -- new byte fact instead of inheriting the previous value's larger count.
      NEW.reason_original_bytes := source_bytes;
    ELSE
      NEW.reason_original_bytes := greatest(
        source_bytes,
        coalesce(NEW.reason_original_bytes, OLD.reason_original_bytes, 0)
      );
    END IF;
    NEW.reason := opengeni_private.truncate_workspace_control_text(NEW.reason, 8192);
  END IF;

  source_bytes := octet_length(NEW.actor);
  IF TG_OP = 'INSERT' THEN
    NEW.actor_original_bytes := greatest(source_bytes, coalesce(NEW.actor_original_bytes, 0));
  ELSIF NEW.actor IS DISTINCT FROM OLD.actor THEN
    NEW.actor_original_bytes := source_bytes;
  ELSE
    NEW.actor_original_bytes := greatest(
      source_bytes,
      coalesce(NEW.actor_original_bytes, OLD.actor_original_bytes, 0)
    );
  END IF;
  NEW.actor := opengeni_private.truncate_workspace_control_text(NEW.actor, 1024);
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.browser_deadline_checkpoint(p_target jsonb, p_prepare boolean, p_touch boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      access_id uuid;
      reason text := coalesce(p_target->>'reason', 'provider_deadline');
      actor text;
      idle_ms bigint;
      holder_heartbeat timestamptz;
      lease {{schema}}.sandbox_leases%ROWTYPE;
      browser {{schema}}.browser_sessions%ROWTYPE;
      operation {{schema}}.interaction_operations%ROWTYPE;
      scope_digest text;
      operation_id_value uuid;
      result jsonb;
    BEGIN
      IF reason NOT IN ('provider_deadline', 'idle') THEN
        RAISE EXCEPTION 'Invalid browser checkpoint reason' USING ERRCODE = '22023';
      END IF;
      actor := CASE reason WHEN 'idle' THEN 'system:sandbox-idle'
        ELSE 'system:sandbox-provider-deadline' END;
      PERFORM set_config('opengeni.sandbox_recovery_protocol_v2', '1', true);
      PERFORM {{schema}}.acquire_session_tenancy_fence((p_target->>'workspaceId')::uuid);
      access_id := opengeni_private.open_session_tenancy_fenced_access(
        {{schema}}.session_tenancy_fence_target_schema());
      -- Fence -> lease -> holder -> operation -> browser is the reaper's order.
      SELECT candidate.* INTO lease FROM {{schema}}.sandbox_leases candidate
      WHERE candidate.id = (p_target->>'leaseId')::uuid
        AND candidate.account_id = (p_target->>'accountId')::uuid
        AND candidate.workspace_id = (p_target->>'workspaceId')::uuid
        AND candidate.sandbox_group_id = (p_target->>'sandboxGroupId')::uuid
        AND candidate.lease_epoch = (p_target->>'leaseEpoch')::bigint
        AND candidate.instance_id = p_target->>'instanceId'
        AND candidate.backend = 'modal' AND candidate.liveness IN ('warming', 'warm')
        AND (reason = 'idle' OR (candidate.rotation_reason = 'provider_deadline'
          AND candidate.rotation_requested_at IS NOT NULL AND candidate.provider_deadline_at > now()))
      FOR UPDATE;
      IF NOT FOUND THEN
        PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
        RETURN NULL;
      END IF;
      SELECT holder.last_heartbeat_at INTO holder_heartbeat FROM {{schema}}.sandbox_lease_holders holder
      WHERE holder.lease_id = lease.id AND holder.account_id = lease.account_id
        AND holder.workspace_id = lease.workspace_id AND holder.kind = 'interaction'
        AND holder.holder_id = 'browser-session:' || (p_target->>'browserSessionId')
      FOR UPDATE;
      IF NOT FOUND THEN
        PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
        RETURN NULL;
      END IF;
      scope_digest := opengeni_private.browser_system_checkpoint_digest(reason,
        lease.account_id, lease.workspace_id, lease.id, lease.lease_epoch, lease.instance_id,
        p_target->>'browserSessionId', p_target->>'controllerGeneration');
      operation_id_value := opengeni_private.browser_system_checkpoint_operation_id(scope_digest);
      SELECT candidate.* INTO operation FROM {{schema}}.interaction_operations candidate
      WHERE candidate.workspace_id = lease.workspace_id
        AND candidate.resource_kind = 'browser_session'
        AND candidate.resource_id = (p_target->>'browserSessionId')::uuid
        AND (candidate.state IN ('prepared', 'dispatched') OR candidate.operation_id = operation_id_value)
      -- A different live operation wins over this checkpoint's completed
      -- receipt, so cleanup cannot cross a concurrent human transition.
      ORDER BY (candidate.state IN ('prepared', 'dispatched')) DESC,
        candidate.operation_id LIMIT 1 FOR UPDATE;
      IF FOUND AND (operation.operation_id <> operation_id_value
        OR operation.account_id <> lease.account_id OR operation.kind <> 'suspend'
        OR operation.actor_subject_id <> actor
        OR operation.request_digest <> scope_digest
        OR operation.state NOT IN ('prepared', 'dispatched', 'completed')) THEN
        PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
        RETURN NULL;
      END IF;
      SELECT candidate.* INTO browser FROM {{schema}}.browser_sessions candidate
      WHERE candidate.id = (p_target->>'browserSessionId')::uuid
        AND candidate.account_id = lease.account_id AND candidate.workspace_id = lease.workspace_id
        AND candidate.placement_kind = 'sandbox_group'
        AND candidate.controller_host_sandbox_group_id = lease.sandbox_group_id
        AND candidate.placement_instance_id = lease.instance_id
        AND candidate.controller_generation = p_target->>'controllerGeneration'
        AND candidate.controller_id IS NOT NULL
        AND candidate.capabilities->>'privateCheckpoint' = 'true'
      FOR UPDATE;
      IF NOT FOUND OR (operation.operation_id IS NULL AND (NOT p_prepare OR browser.lifecycle <> 'active'))
        OR (operation.state IN ('prepared', 'dispatched') AND browser.lifecycle <> 'suspending')
        OR (operation.state = 'completed' AND browser.lifecycle <> 'suspended') THEN
        PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
        RETURN NULL;
      END IF;
      IF operation.operation_id IS NULL AND reason = 'idle' THEN
        -- Only the reaper's tenant-scoped idle decision prepares an idle save
        -- (it re-checked the whole sandbox group under the control fence).
        -- Someone using the browser (the live view's poll and heartbeat, a
        -- person's input, an agent tool call) is activity; a checkpoint never
        -- starts inside the idle window.
        idle_ms := (p_target->>'idleMs')::bigint;
        IF current_setting('opengeni.account_id', true) IS DISTINCT FROM lease.account_id::text
          OR current_setting('opengeni.workspace_id', true) IS DISTINCT FROM lease.workspace_id::text
          OR idle_ms IS NULL OR idle_ms < 60000 OR greatest(browser.last_used_at,
            browser.controller_heartbeat_at, holder_heartbeat)
            >= now() - idle_ms * interval '1 millisecond' THEN
          PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
          RETURN NULL;
        END IF;
      END IF;
      IF operation.operation_id IS NULL THEN
        INSERT INTO {{schema}}.interaction_operations (
          operation_id, account_id, workspace_id, resource_kind, resource_id,
          kind, request_digest, state, actor_subject_id
        ) VALUES (operation_id_value, lease.account_id, lease.workspace_id, 'browser_session',
          browser.id, 'suspend', scope_digest, 'prepared', actor)
        RETURNING * INTO operation;
        UPDATE {{schema}}.browser_sessions SET lifecycle = 'suspending', failure_code = NULL, updated_at = now()
        WHERE id = browser.id;
        UPDATE {{schema}}.workspace_interaction_revisions SET revision = revision + 1, updated_at = now()
        WHERE workspace_id = lease.workspace_id;
      END IF;
      IF p_touch AND operation.state IN ('prepared', 'dispatched') THEN
        UPDATE {{schema}}.interaction_operations SET updated_at = now() WHERE operation_id = operation_id_value;
        UPDATE {{schema}}.sandbox_lease_holders SET last_heartbeat_at = now()
        WHERE lease_id = lease.id AND kind = 'interaction' AND holder_id = 'browser-session:' || browser.id::text;
      END IF;
      result := jsonb_build_object('operationId', operation_id_value, 'state', operation.state);
      PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.browser_deadline_checkpoint_due_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_leases lease
        JOIN opengeni_private.maintenance_probe_browser_sessions browser
          ON browser.account_id = lease.account_id AND browser.workspace_id = lease.workspace_id
          AND browser.controller_host_sandbox_group_id = lease.sandbox_group_id
          AND browser.placement_instance_id = lease.instance_id
        WHERE lease.backend = 'modal' AND lease.liveness IN ('warming', 'warm')
          AND lease.instance_id IS NOT NULL
          AND browser.placement_kind = 'sandbox_group'
          AND browser.controller_generation IS NOT NULL AND browser.controller_id IS NOT NULL
          AND browser.capabilities->>'privateCheckpoint' = 'true'
          AND (
            browser.lifecycle IN ('suspending', 'suspended')
            OR (browser.lifecycle = 'active'
              AND lease.rotation_reason = 'provider_deadline'
              AND lease.rotation_requested_at IS NOT NULL
              AND lease.provider_deadline_at > now())
          )
          AND EXISTS (SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_lease_holders holder
            WHERE holder.lease_id = lease.id AND holder.kind = 'interaction'
              AND holder.account_id = browser.account_id
              AND holder.workspace_id = browser.workspace_id
              AND holder.holder_id = 'browser-session:' || browser.id::text)
      )
    $$;

CREATE FUNCTION opengeni_private.browser_identities_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF ROW(
    NEW.id, NEW.account_id, NEW.workspace_id, NEW.create_operation_id,
    NEW.created_by_subject_id, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.id, OLD.account_id, OLD.workspace_id, OLD.create_operation_id,
    OLD.created_by_subject_id, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'BrowserIdentity immutable authority cannot change'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.revision_count < OLD.revision_count
     OR NEW.revision_count > OLD.revision_count + 1 THEN
    RAISE EXCEPTION 'BrowserIdentity revision count must advance monotonically by one'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.default_revision_id IS DISTINCT FROM OLD.default_revision_id THEN
    IF NEW.head_generation <> OLD.head_generation + 1 THEN
      RAISE EXCEPTION 'BrowserIdentity default change must advance its head generation'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.head_generation <> OLD.head_generation THEN
    RAISE EXCEPTION 'BrowserIdentity head generation requires a default change'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'BrowserIdentity updated time cannot move backwards'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.browser_state_artifacts_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF ROW(
    NEW.id, NEW.account_id, NEW.workspace_id, NEW.source_browser_session_id,
    NEW.purpose, NEW.kind, NEW.format, NEW.artifact_digest, NEW.content_digest,
    NEW.manifest_digest, NEW.object_key, NEW.size_bytes, NEW.materialization,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.id, OLD.account_id, OLD.workspace_id, OLD.source_browser_session_id,
    OLD.purpose, OLD.kind, OLD.format, OLD.artifact_digest, OLD.content_digest,
    OLD.manifest_digest, OLD.object_key, OLD.size_bytes, OLD.materialization,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Browser state artifact immutable authority cannot change'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.purpose = 'revision_component'
     AND ROW(
       NEW.state, NEW.retained_until, NEW.delete_claim_id, NEW.delete_claimed_at,
       NEW.deleted_at, NEW.encrypted_data_key
     ) IS DISTINCT FROM ROW(
       OLD.state, OLD.retained_until, OLD.delete_claim_id, OLD.delete_claimed_at,
       OLD.deleted_at, OLD.encrypted_data_key
     ) THEN
    RAISE EXCEPTION 'Published BrowserRevision artifact immutable authority cannot change'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state IS DISTINCT FROM OLD.state
     AND NOT (
       (OLD.state = 'available' AND NEW.state = 'delete_pending')
       OR (OLD.state = 'delete_pending' AND NEW.state = 'deleting')
       OR (OLD.state = 'deleting' AND NEW.state = 'deleted')
     ) THEN
    RAISE EXCEPTION 'Browser state artifact lifecycle cannot move backwards or skip a phase'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state = OLD.state AND NEW.state <> 'deleting'
     AND ROW(
       NEW.retained_until, NEW.delete_claim_id, NEW.delete_claimed_at,
       NEW.deleted_at, NEW.encrypted_data_key
     ) IS DISTINCT FROM ROW(
       OLD.retained_until, OLD.delete_claim_id, OLD.delete_claimed_at,
       OLD.deleted_at, OLD.encrypted_data_key
     ) THEN
    RAISE EXCEPTION 'Browser state artifact lifecycle authority cannot change in place'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state = OLD.state AND NEW.state = 'deleting'
     AND (
       NEW.retained_until IS DISTINCT FROM OLD.retained_until
       OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
       OR NEW.encrypted_data_key IS DISTINCT FROM OLD.encrypted_data_key
       OR NEW.delete_claimed_at < OLD.delete_claimed_at
     ) THEN
    RAISE EXCEPTION 'Browser state artifact delete claim cannot weaken authority'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.browser_state_uploads_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF ROW(
    NEW.id, NEW.account_id, NEW.workspace_id, NEW.operation_id,
    NEW.source_browser_session_id, NEW.purpose, NEW.object_key, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.id, OLD.account_id, OLD.workspace_id, OLD.operation_id,
    OLD.source_browser_session_id, OLD.purpose, OLD.object_key, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Browser state upload immutable authority cannot change'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state IS DISTINCT FROM OLD.state
     AND NOT (
       (OLD.state = 'prepared' AND NEW.state IN ('delete_pending', 'deleting', 'committed'))
       OR (OLD.state = 'delete_pending' AND NEW.state = 'deleting')
       OR (OLD.state = 'deleting' AND NEW.state = 'deleted')
     ) THEN
    RAISE EXCEPTION 'Browser state upload lifecycle cannot move backwards or skip authority'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state = OLD.state AND NEW.state = 'prepared'
     AND (
       NEW.cleanup_after < OLD.cleanup_after
       OR NEW.committed_artifact_id IS DISTINCT FROM OLD.committed_artifact_id
       OR NEW.delete_claim_id IS DISTINCT FROM OLD.delete_claim_id
       OR NEW.delete_claimed_at IS DISTINCT FROM OLD.delete_claimed_at
       OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     ) THEN
    RAISE EXCEPTION 'Browser state upload lease cannot weaken authority'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state = OLD.state AND NEW.state NOT IN ('prepared', 'deleting')
     AND ROW(
       NEW.cleanup_after, NEW.committed_artifact_id, NEW.delete_claim_id,
       NEW.delete_claimed_at, NEW.deleted_at
     ) IS DISTINCT FROM ROW(
       OLD.cleanup_after, OLD.committed_artifact_id, OLD.delete_claim_id,
       OLD.delete_claimed_at, OLD.deleted_at
     ) THEN
    RAISE EXCEPTION 'Browser state upload lifecycle authority cannot change in place'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.state = OLD.state AND NEW.state = 'deleting'
     AND (
       NEW.cleanup_after IS DISTINCT FROM OLD.cleanup_after
       OR NEW.committed_artifact_id IS DISTINCT FROM OLD.committed_artifact_id
       OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
       OR NEW.delete_claimed_at < OLD.delete_claimed_at
     ) THEN
    RAISE EXCEPTION 'Browser state upload delete claim cannot weaken authority'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'Browser state upload time cannot move backwards'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.browser_system_checkpoint_digest(p_reason text, p_account_id uuid, p_workspace_id uuid, p_lease_id uuid, p_lease_epoch bigint, p_instance_id text, p_browser_session_id text, p_controller_generation text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT encode(sha256(convert_to(jsonb_build_array(
        CASE p_reason WHEN 'idle' THEN 'browser-idle.v1' ELSE 'browser-provider-deadline.v1' END,
        p_account_id, p_workspace_id, p_lease_id, p_lease_epoch, p_instance_id,
        p_browser_session_id, p_controller_generation
      )::text, 'UTF8')), 'hex')
    $$;

CREATE FUNCTION opengeni_private.browser_system_checkpoint_operation_id(p_digest text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT (substr(p_digest, 1, 8) || '-' || substr(p_digest, 9, 4)
        || '-4' || substr(p_digest, 14, 3) || '-8' || substr(p_digest, 18, 3)
        || '-' || substr(p_digest, 21, 12))::uuid
    $$;

CREATE FUNCTION opengeni_private.capture_accepted_turn_connection_authorities() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  sender_prior_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  session_row sessions%ROWTYPE;
  item jsonb;
  connection_row connections%ROWTYPE;
  membership_row organization_memberships%ROWTYPE;
  authority_row organization_user_resource_authorities%ROWTYPE;
  canonical jsonb;
  existing_digest bytea;
  existing_snapshot jsonb;
  initiating_subject text;
  verified_causal_subject text := coalesce(
    nullif(current_setting('opengeni.initiating_human_subject_id', true), ''),
    nullif(current_setting('opengeni.subject_id', true), '')
  );
BEGIN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true);
  IF TG_OP = 'UPDATE' THEN
    IF NEW.personal_connection_delegations IS NOT DISTINCT FROM OLD.personal_connection_delegations
    THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN NEW;
    END IF;
    IF NEW.status <> 'queued' OR EXISTS (
      SELECT 1 FROM session_turn_attempts attempt
      WHERE attempt.turn_id = NEW.id AND attempt.workspace_id = NEW.workspace_id
    ) THEN
      RAISE EXCEPTION 'accepted connection authority cannot change after claim'
        USING ERRCODE = '42501';
    END IF;
    DELETE FROM turn_connection_authority_snapshots snapshot
    WHERE snapshot.turn_id = NEW.id AND snapshot.workspace_id = NEW.workspace_id;
  END IF;
  SELECT session_value.* INTO STRICT session_row
  FROM sessions session_value
  WHERE session_value.id = NEW.session_id
    AND session_value.account_id = NEW.account_id
    AND session_value.workspace_id = NEW.workspace_id
  FOR SHARE;
  initiating_subject := coalesce(
    nullif(btrim(NEW.initiating_human_subject_id), ''),
    CASE WHEN NEW.initiator_kind = 'subject'
      THEN nullif(btrim(NEW.initiator_subject_id), '') END
  );


  IF NEW.execution_context_turn_id IS NOT NULL
    -- 0755: freshly resolved accounts are captured below like any other turn.
    AND NEW.personal_connection_delegations IS NOT DISTINCT FROM (
      SELECT context_turn.personal_connection_delegations FROM {{schema}}.session_turns context_turn
      WHERE context_turn.id = NEW.execution_context_turn_id
        AND context_turn.account_id = NEW.account_id
        AND context_turn.workspace_id = NEW.workspace_id
        AND context_turn.session_id = NEW.session_id)
  THEN
    FOR item IN SELECT value FROM jsonb_array_elements(NEW.personal_connection_delegations)
      WHERE value ->> 'connectionType' IS DISTINCT FROM 'social'
    LOOP
      IF NOT EXISTS (SELECT 1 FROM turn_connection_authority_snapshots source
        WHERE source.turn_id = NEW.execution_context_turn_id AND source.account_id = NEW.account_id
          AND source.workspace_id = NEW.workspace_id AND source.session_id = NEW.session_id
          AND source.server_id = item ->> 'serverId' AND source.connection_id::text = item ->> 'connectionId'
          AND source.owner_subject_id IS NOT DISTINCT FROM initiating_subject
          AND source.snapshot_digest = digest(convert_to(source.canonical_snapshot::text,'UTF8'),'sha256'))
        AND NOT EXISTS (SELECT 1 FROM session_turns lapsed_source
          WHERE lapsed_source.id = NEW.execution_context_turn_id
            AND lapsed_source.account_id = NEW.account_id
            AND lapsed_source.workspace_id = NEW.workspace_id
            AND lapsed_source.session_id = NEW.session_id
            AND lapsed_source.personal_connection_delegations @> pg_catalog.jsonb_build_array(item)
            AND NOT EXISTS (SELECT 1 FROM turn_connection_authority_snapshots lapsed
              WHERE lapsed.turn_id = lapsed_source.id
                AND lapsed.account_id = NEW.account_id
                AND lapsed.workspace_id = NEW.workspace_id
                AND lapsed.server_id = item ->> 'serverId'
                AND lapsed.connection_id::text = item ->> 'connectionId'))
      THEN RAISE EXCEPTION 'receiving connection receipt is unavailable' USING ERRCODE = '42501'; END IF;
    END LOOP;
    INSERT INTO turn_connection_authority_snapshots (
      account_id,workspace_id,session_id,turn_id,server_id,connection_id,connection_generation,
      origin_workspace_id,provider_domain,connection_kind,authority_scope,authority_source,owner_subject_id,
      owner_organization_membership_id,membership_authorization_revision,authority_id,authority_generation,
      grant_id,grant_generation,grant_mode,grant_context,grant_session_id,grant_authority_epoch,
      session_visibility,session_authority_epoch,canonical_snapshot,snapshot_digest)
    SELECT account_id,workspace_id,session_id,NEW.id,server_id,connection_id,connection_generation,
      origin_workspace_id,provider_domain,connection_kind,authority_scope,authority_source,owner_subject_id,
      owner_organization_membership_id,membership_authorization_revision,authority_id,authority_generation,
      grant_id,grant_generation,grant_mode,grant_context,grant_session_id,grant_authority_epoch,
      session_visibility,session_authority_epoch,
      jsonb_set(canonical_snapshot,'{acceptedWork}',jsonb_build_object('kind','turn','turnId',NEW.id)),
      digest(convert_to(jsonb_set(canonical_snapshot,'{acceptedWork}',jsonb_build_object('kind','turn','turnId',NEW.id))::text,'UTF8'),'sha256')
    FROM turn_connection_authority_snapshots WHERE turn_id = NEW.execution_context_turn_id
      AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id AND session_id = NEW.session_id;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true);
    RETURN NEW;
  END IF;
  FOR item IN
    SELECT value FROM jsonb_array_elements(NEW.personal_connection_delegations)

  LOOP
    IF item ? 'userDelegation' THEN
      RAISE EXCEPTION 'connection grants are retired; refresh the client' USING ERRCODE = '22023';
    END IF;
    -- Social uses a distinct store. It is not activated here and must never
    -- smuggle the common connection-authority envelope past this boundary.
    IF item ->> 'connectionType' = 'social' THEN
      CONTINUE;
    END IF;
    IF nullif(item ->> 'serverId', '') IS NULL
      OR octet_length(item ->> 'serverId') > 256
      OR nullif(item ->> 'connectionId', '') IS NULL
    THEN
      RAISE EXCEPTION 'invalid accepted connection selection' USING ERRCODE = '22023';
    END IF;
    IF initiating_subject IS NULL OR verified_causal_subject IS DISTINCT FROM initiating_subject THEN
      RAISE EXCEPTION 'accepted connection authority causal human is unverified' USING ERRCODE = '42501';
    END IF;
    SELECT connection_value.* INTO connection_row
    FROM opengeni_private.read_sender_connection(
      NEW.account_id, nullif(item ->> 'originWorkspaceId', '')::uuid,
      (item ->> 'connectionId')::uuid, initiating_subject
    ) connection_value;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'accepted connection selection is unavailable'
        USING ERRCODE = '42501';
    END IF;

    IF connection_row.authority_scope <> 'user' THEN
      RAISE EXCEPTION 'accepted personal connection scope is unavailable'
        USING ERRCODE = '42501';
    END IF;
    -- An exact owner account that lapsed stays accepted without authority.
    IF initiating_subject IS NOT NULL
      AND connection_row.subject_id IS NOT DISTINCT FROM initiating_subject
      AND connection_row.status <> 'active'
      AND lower(connection_row.provider_domain) IS NOT DISTINCT FROM lower(item ->> 'providerDomain')
      AND NOT (item ? 'kind' AND connection_row.kind IS DISTINCT FROM item ->> 'kind')
    THEN
      CONTINUE;
    END IF;
    IF initiating_subject IS NULL OR connection_row.subject_id IS DISTINCT FROM initiating_subject
      OR connection_row.status <> 'active'
      OR lower(connection_row.provider_domain) IS DISTINCT FROM lower(item ->> 'providerDomain')
      OR (item ? 'kind' AND connection_row.kind IS DISTINCT FROM item ->> 'kind')
    THEN
      RAISE EXCEPTION 'accepted personal connection identity is unavailable'
        USING ERRCODE = '42501';
    END IF;
    IF verified_causal_subject IS DISTINCT FROM initiating_subject THEN
      RAISE EXCEPTION 'accepted connection authority causal human is unverified'
        USING ERRCODE = '42501';
    END IF;

    SELECT membership.* INTO STRICT membership_row
    FROM organization_memberships membership
    WHERE membership.id = connection_row.owner_organization_membership_id
      AND membership.account_id = NEW.account_id
      AND membership.subject_id = initiating_subject
      AND membership.status = 'active'
      AND membership.revoked_at IS NULL
    FOR SHARE;
    IF membership_row.personal_workspace_id IS DISTINCT FROM NEW.workspace_id
      AND NOT EXISTS (
        SELECT 1 FROM workspace_memberships workspace_membership
        WHERE workspace_membership.account_id = NEW.account_id
          AND workspace_membership.workspace_id = NEW.workspace_id
          AND workspace_membership.subject_id = initiating_subject
      )
    THEN
      RAISE EXCEPTION 'personal connection owner lacks target workspace access'
        USING ERRCODE = '42501';
    END IF;

    SELECT authority.* INTO STRICT authority_row
    FROM organization_user_resource_authorities authority
    WHERE authority.id = connection_row.authority_id
      AND authority.account_id = NEW.account_id
      AND authority.organization_membership_id = membership_row.id
      AND authority.resource_kind = 'connection'
      AND authority.resource_id = connection_row.id
      AND authority.origin_workspace_id = connection_row.origin_workspace_id
      AND authority.status = 'active'
      AND authority.revoked_at IS NULL
    FOR SHARE;

    IF nullif(item ->> 'originWorkspaceId', '')::uuid
      IS DISTINCT FROM connection_row.origin_workspace_id
    THEN
      RAISE EXCEPTION 'accepted connection origin is not server-resolved'
        USING ERRCODE = '42501';
    END IF;

    canonical := jsonb_build_object(
      'organizationId', NEW.account_id,
      'originWorkspaceId', connection_row.origin_workspace_id,
      'targetWorkspaceId', NEW.workspace_id,
      'targetSessionId', NEW.session_id,
      'targetSessionVisibility', session_row.visibility,
      'targetSessionAuthorityEpoch', session_row.authority_epoch,
      'acceptedWork', jsonb_build_object('kind', 'turn', 'turnId', NEW.id),
      'connectionId', connection_row.id,
      'connectionGeneration', connection_row.authority_generation,
      'connectionStatus', 'active',
      'providerDomain', lower(connection_row.provider_domain),
      'connectionKind', connection_row.kind,
      'scope', 'user',
      'ownerSubjectId', initiating_subject,
      'ownerOrganizationMembershipId', membership_row.id,
      'ownerMembershipAuthorizationRevision', membership_row.authorization_revision,
      'authoritySource', 'sender',
      'selectionSources', jsonb_build_array('mcp:' || (item ->> 'serverId')),
      'userDelegation', NULL
    );

    SELECT snapshot.snapshot_digest, snapshot.canonical_snapshot
    INTO existing_digest, existing_snapshot
    FROM turn_connection_authority_snapshots snapshot
    WHERE snapshot.turn_id = NEW.id AND snapshot.server_id = item ->> 'serverId';
    IF FOUND THEN
      IF existing_snapshot IS DISTINCT FROM canonical
        OR existing_digest IS DISTINCT FROM digest(convert_to(canonical::text, 'UTF8'), 'sha256')
      THEN
        RAISE EXCEPTION 'accepted connection authority changed across recovery'
          USING ERRCODE = '42501';
      END IF;
      CONTINUE;
    END IF;

    INSERT INTO turn_connection_authority_snapshots (
      account_id, workspace_id, session_id, turn_id, server_id,
      connection_id, connection_generation, origin_workspace_id,
      provider_domain, connection_kind, authority_scope, authority_source, owner_subject_id,
      owner_organization_membership_id, membership_authorization_revision,
      authority_id, authority_generation, grant_id, grant_generation,
      grant_mode, grant_context, grant_session_id, grant_authority_epoch,
      session_visibility, session_authority_epoch, canonical_snapshot, snapshot_digest
    ) VALUES (
      NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.id, item ->> 'serverId',
      connection_row.id, connection_row.authority_generation,
      connection_row.origin_workspace_id, lower(connection_row.provider_domain),
      connection_row.kind, 'user', 'sender', initiating_subject, membership_row.id,
      membership_row.authorization_revision, authority_row.id, authority_row.generation,
      NULL, NULL, NULL, NULL, NULL, NULL,
      session_row.visibility, session_row.authority_epoch, canonical,
      digest(convert_to(canonical::text, 'UTF8'), 'sha256')
    );
  END LOOP;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN NEW;
EXCEPTION WHEN OTHERS THEN RAISE;
END
$$;

CREATE FUNCTION opengeni_private.capture_host_export_root_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      NEW.root_session_id := opengeni_private.host_export_session_root(
        NEW.workspace_id,
        NEW.session_id
      );
      IF NEW.session_id IS NOT NULL AND NEW.root_session_id IS NULL THEN
        RAISE EXCEPTION 'host export session % does not exist in workspace %',
          NEW.session_id, NEW.workspace_id
          USING ERRCODE = '23503';
      END IF;
      RETURN NEW;
    END $$;

CREATE FUNCTION opengeni_private.capture_product_lifecycle_fact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
    DECLARE
      v_enabled boolean;
      v_provider text;
      v_marker text;
      v_fact_type text;
      v_attribute text;
      v_subject_id text;
      v_account_id uuid;
      v_workspace_id uuid;
      v_dedupe_key text;
      v_occurred_at timestamptz;
      v_exported_subject text;
      v_subject_kind text;
      v_initiator jsonb;
      v_source_id uuid;
      v_payload jsonb;
      v_inserted integer := 0;
    BEGIN
      IF TG_TABLE_SCHEMA NOT IN ('{{schema}}', 'opengeni_private') THEN
        RETURN NULL;
      END IF;
      SELECT c.lifecycle_facts_enabled INTO v_enabled
      FROM {{schema}}.host_export_config c WHERE c.id = 1;
      IF coalesce(v_enabled, false) = false THEN
        RETURN NULL;
      END IF;

      BEGIN
        CASE TG_TABLE_NAME
          WHEN 'auth_identities' THEN
            IF NOT EXISTS (
              SELECT 1 FROM {{schema}}.auth_identities other
              WHERE other.user_id = NEW.user_id AND other.id <> NEW.id
            ) THEN
              SELECT 'auth.sign_up',
                opengeni_private.product_lifecycle_auth_method(NEW.provider_id),
                'user:' || NEW.user_id, NULL, NULL, NEW.user_id
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            END IF;
          WHEN 'auth_users' THEN
            SELECT 'auth.email_verified', NULL, 'user:' || NEW.id, NULL, NULL, NEW.id
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'auth_sessions' THEN
            -- Session-set modes create and immediately discard an expired
            -- provider session; only a live session is a sign-in.
            IF NEW.expires_at > clock_timestamp() THEN
              v_marker := current_setting('opengeni.canonical_human_identity_lifecycle', true);
              PERFORM set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
              SELECT binding.provider_id INTO v_provider
              FROM {{schema}}.canonical_human_login_bindings binding
              WHERE binding.id = NEW.login_binding_id;
              PERFORM set_config(
                'opengeni.canonical_human_identity_lifecycle', coalesce(v_marker, ''), true
              );
              IF v_provider IS NULL THEN
                SELECT min(identity.provider_id) INTO v_provider
                FROM {{schema}}.auth_identities identity
                WHERE identity.user_id = NEW.user_id
                HAVING count(*) = 1;
              END IF;
              SELECT 'auth.sign_in',
                opengeni_private.product_lifecycle_auth_method(v_provider),
                'user:' || NEW.user_id, NULL, NULL, NEW.id
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            END IF;
          WHEN 'self_service_organization_setup_receipts' THEN
            SELECT 'organization.setup', 'created', 'user:' || NEW.auth_user_id,
              NEW.account_id, NULL, NEW.account_id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'additional_organization_creation_receipts' THEN
            SELECT 'organization.setup', 'additional', NEW.actor_subject_id,
              NEW.account_id, NULL, NEW.account_id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'codex_subscription_credentials' THEN
            SELECT 'model.connected', 'codex', NEW.connected_by_subject_id,
              NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'xai_subscription_credentials' THEN
            SELECT 'model.connected', 'supergrok', NEW.connected_by_subject_id,
              NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'claude_subscription_credentials' THEN
            SELECT 'model.connected', 'claude_subscription', NEW.connected_by_subject_id,
              NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'subscription_connections' THEN
            SELECT 'model.connected', attribute.value, NEW.connected_by_subject_id,
              NEW.account_id, NULL, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key
            FROM (VALUES ('codex', 'codex'), ('xai', 'supergrok'),
              ('claude', 'claude_subscription')) attribute(provider, value)
            WHERE attribute.provider = NEW.provider;
          WHEN 'organization_model_provider_connections' THEN
            SELECT 'model.connected', NEW.provider_kind, NEW.updated_by_subject_id,
              NEW.account_id, NULL, NEW.id::text || ':' || NEW.operation_id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'credit_ledger_entries' THEN
            IF NEW.type = 'credit_topup' THEN
              SELECT 'credits.purchased', NULL, NULL,
                NEW.account_id, NULL, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            ELSE
              -- The verified-signup trial grant runs as the new owner, so its
              -- subject is that person; webhook and operator grants carry none.
              SELECT 'credits.granted',
                opengeni_private.credit_grant_class(NEW.type, NEW.source_type),
                opengeni_private.current_subject_id(),
                NEW.account_id, NULL, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            END IF;
          WHEN 'connections' THEN
            IF TG_OP = 'INSERT' THEN
              SELECT 'connection.created',
                opengeni_private.product_lifecycle_connection_class(NEW.provider_domain),
                NEW.created_by_subject_id, NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            ELSIF TG_OP = 'UPDATE' THEN
              -- Every revocation advances the connection version, so a
              -- reconnect-then-revoke is a second fact.
              SELECT 'connection.revoked',
                opengeni_private.product_lifecycle_connection_class(NEW.provider_domain),
                NEW.updated_by_subject_id, NEW.account_id, NEW.workspace_id,
                NEW.id::text || ':revoked:' || NEW.version::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            ELSE
              SELECT 'connection.revoked',
                opengeni_private.product_lifecycle_connection_class(OLD.provider_domain),
                opengeni_private.current_subject_id(), OLD.account_id, OLD.workspace_id,
                OLD.id::text || ':deleted'
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            END IF;
          WHEN 'scheduled_tasks' THEN
            SELECT 'scheduled_task.created', NULL, NEW.created_by_subject_id,
              NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'skill_source_bindings' THEN
            SELECT 'skill.installed', NULL, opengeni_private.current_subject_id(),
              NEW.account_id, NEW.workspace_id, NEW.preference_id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'slack_bot_user_links' THEN
            SELECT 'slack.user_linked', NULL, NEW.subject_id,
              NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'enrollments' THEN
            SELECT 'machine.enrolled', NULL, opengeni_private.current_subject_id(),
              NEW.account_id, NEW.workspace_id, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          WHEN 'organization_memberships' THEN
            -- The founder's own membership is covered by organization.setup.
            IF EXISTS (
              SELECT 1 FROM {{schema}}.organization_memberships earlier
              WHERE earlier.account_id = NEW.account_id
                AND earlier.id <> NEW.id
                AND earlier.subject_id <> NEW.subject_id
                AND earlier.created_at <= NEW.created_at
            ) THEN
              SELECT 'member.joined', NULL, NEW.subject_id,
                NEW.account_id, NULL, NEW.id::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
            END IF;
          WHEN 'user_activity_presence' THEN
            -- A person belongs to no single organization, like a sign-in.
            SELECT 'user.active', NULL, NEW.subject_id, NULL, NULL,
              NEW.subject_id || ':' || NEW.active_day::text
              INTO v_fact_type, v_attribute, v_subject_id, v_account_id,
                v_workspace_id, v_dedupe_key;
          ELSE
            NULL;
        END CASE;

      -- Validate and write the one fact: a fixed type and attribute, a
      -- pseudonymous subject, and a deterministic name-based id.
      IF v_fact_type IS NOT NULL THEN
        SELECT c.lifecycle_facts_enabled INTO v_enabled
        FROM {{schema}}.host_export_config c WHERE c.id = 1
        FOR SHARE;
        IF coalesce(v_enabled, false) THEN
          IF NOT opengeni_private.product_lifecycle_fact_valid(v_fact_type, v_attribute) THEN
            RAISE EXCEPTION 'invalid product lifecycle fact' USING ERRCODE = '22023';
          END IF;
          IF v_dedupe_key IS NULL OR length(v_dedupe_key) NOT BETWEEN 1 AND 512 THEN
            RAISE EXCEPTION 'invalid product lifecycle fact key' USING ERRCODE = '22023';
          END IF;
          IF v_workspace_id IS NOT NULL AND v_account_id IS NULL THEN
            RAISE EXCEPTION 'product lifecycle workspace requires its organization'
              USING ERRCODE = '22023';
          END IF;
          v_exported_subject := CASE
            WHEN v_subject_id ~ '^(user|api_key):[A-Za-z0-9_-]{8,128}$' THEN v_subject_id
            ELSE NULL
          END;
          v_subject_kind := CASE
            WHEN nullif(btrim(coalesce(v_subject_id, '')), '') IS NULL THEN 'none'
            WHEN v_exported_subject IS NOT NULL AND starts_with(v_exported_subject, 'user:') THEN 'user'
            WHEN v_exported_subject IS NOT NULL THEN 'api_key'
            WHEN starts_with(v_subject_id, 'service:') THEN 'service'
            ELSE 'other'
          END;
          v_initiator := CASE
            WHEN v_exported_subject IS NULL THEN NULL
            ELSE jsonb_build_object('kind', 'subject', 'subjectId', v_exported_subject)
          END;
          v_source_id := overlay(overlay(md5(
            'opengeni-product-lifecycle-fact:v1:' || v_fact_type || ':' || v_dedupe_key
          ) placing '5' from 13) placing '8' from 17)::uuid;
          v_payload := jsonb_build_object(
            'factType', v_fact_type,
            'attribute', v_attribute,
            'subjectKind', v_subject_kind
          );
          INSERT INTO {{schema}}.host_export_outbox (
            export_kind, source_id, account_id, workspace_id, event_type,
            idempotency_key, initiator, initiator_context, origin, payload,
            envelope_bytes, occurred_at, source_recorded_at, enqueued_at
          ) VALUES (
            'lifecycle_fact', v_source_id, v_account_id, v_workspace_id, v_fact_type,
            'lifecycle_fact:' || v_source_id::text, v_initiator, '{}'::jsonb, NULL,
            v_payload,
            octet_length(v_payload::text)
              + octet_length(coalesce(v_initiator, 'null'::jsonb)::text) + 512,
            coalesce(v_occurred_at, clock_timestamp()), clock_timestamp(), clock_timestamp()
          )
          ON CONFLICT (export_kind, source_id) DO NOTHING;
          GET DIAGNOSTICS v_inserted = ROW_COUNT;
        END IF;
      END IF;
      EXCEPTION WHEN OTHERS THEN
        -- Telemetry only: roll back the fact, never the product change.
        RAISE WARNING 'product lifecycle fact capture skipped (%)', SQLSTATE;
      END;
      RETURN NULL;
    END $_$;

CREATE FUNCTION opengeni_private.capture_scheduled_turn_connection_authorities() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  run_row record;
  run_snapshot record;
  item jsonb;
  selected_count integer;
  snapshot_count integer;
  canonical jsonb;
  accepted jsonb;
  execution_policy jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.scheduled_task_run_id IS DISTINCT FROM OLD.scheduled_task_run_id THEN
      RAISE EXCEPTION 'scheduled logical-turn occurrence identity is immutable'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.personal_connection_delegations IS NOT DISTINCT FROM OLD.personal_connection_delegations
    THEN RETURN NEW;
    END IF;
    RAISE EXCEPTION 'scheduled connection authority cannot change after acceptance'
      USING ERRCODE = '42501';
  END IF;

  SELECT run.* INTO STRICT run_row FROM scheduled_task_runs run
  WHERE run.id = NEW.scheduled_task_run_id AND run.account_id = NEW.account_id
    AND run.workspace_id = NEW.workspace_id
  FOR UPDATE;
  IF run_row.status NOT IN ('queued', 'dispatched')
    OR run_row.session_id IS DISTINCT FROM NEW.session_id
  THEN
    RAISE EXCEPTION 'scheduled turn does not match its run session'
      USING ERRCODE = '42501';
  END IF;
  accepted := run_row.accepted_execution_snapshot;
  execution_policy := accepted -> 'targetSessionExecution';
  IF execution_policy = 'null'::jsonb THEN
    IF NEW.model IS DISTINCT FROM accepted ->> 'resolvedModel'
      OR NEW.reasoning_effort IS DISTINCT FROM accepted ->> 'resolvedReasoningEffort'
      OR NEW.latency_mode IS DISTINCT FROM accepted ->> 'resolvedLatencyMode'
      OR NEW.tools IS DISTINCT FROM accepted -> 'resolvedTools'
      OR NEW.sandbox_backend IS DISTINCT FROM accepted ->> 'resolvedSandboxBackend'
      OR NEW.sandbox_os IS DISTINCT FROM accepted ->> 'resolvedSandboxOs'
    THEN RAISE EXCEPTION 'generated scheduled turn differs from accepted execution policy'
      USING ERRCODE = '42501'; END IF;
  ELSE
    IF execution_policy ->> 'sessionId' IS DISTINCT FROM NEW.session_id::text
      OR NEW.model IS DISTINCT FROM execution_policy ->> 'model'
      OR NEW.reasoning_effort IS DISTINCT FROM execution_policy ->> 'reasoningEffort'
      OR NEW.latency_mode IS DISTINCT FROM execution_policy ->> 'latencyMode'
      OR NEW.tools IS DISTINCT FROM execution_policy -> 'tools'
      OR NEW.sandbox_backend IS DISTINCT FROM execution_policy ->> 'sandboxBackend'
      OR NEW.sandbox_os IS DISTINCT FROM execution_policy ->> 'sandboxOs'
    THEN RAISE EXCEPTION 'targeted scheduled turn differs from accepted execution policy'
      USING ERRCODE = '42501'; END IF;
  END IF;
  IF NEW.personal_connection_delegations IS DISTINCT FROM accepted -> 'personalConnectionDelegations'
    OR NEW.initiating_human_subject_id IS DISTINCT FROM accepted ->> 'causalHumanSubjectId'
  THEN RAISE EXCEPTION 'scheduled turn differs from its accepted owner accounts'
    USING ERRCODE = '42501'; END IF;
  PERFORM bind_scheduled_task_run_connection_authorities(
    NEW.account_id, NEW.workspace_id, NEW.scheduled_task_run_id, NEW.session_id
  );

  SELECT count(*)::integer INTO snapshot_count
  FROM scheduled_task_run_connection_authority_snapshots snapshot
  WHERE snapshot.run_id = NEW.scheduled_task_run_id;
  SELECT count(*)::integer INTO selected_count
  FROM jsonb_array_elements(NEW.personal_connection_delegations) selected
  WHERE selected ->> 'connectionType' IS DISTINCT FROM 'social';
  IF selected_count IS DISTINCT FROM snapshot_count THEN
    RAISE EXCEPTION 'scheduled turn connection authority widened or disappeared'
      USING ERRCODE = '42501';
  END IF;

  FOR run_snapshot IN SELECT snapshot.*
    FROM scheduled_task_run_connection_authority_snapshots snapshot
    WHERE snapshot.run_id = NEW.scheduled_task_run_id
    ORDER BY snapshot.server_id
  LOOP
    SELECT value INTO STRICT item
    FROM jsonb_array_elements(NEW.personal_connection_delegations)
    WHERE value ->> 'serverId' = run_snapshot.server_id;
    IF run_snapshot.canonical_snapshot ->> 'authoritySource' IS DISTINCT FROM 'sender'
      OR NEW.initiating_human_subject_id IS DISTINCT FROM run_snapshot.owner_subject_id
      OR item IS DISTINCT FROM run_snapshot.canonical_snapshot -> 'selection'
    THEN RAISE EXCEPTION 'scheduled turn connection selection changed from its run'
      USING ERRCODE = '42501'; END IF;
    canonical := jsonb_build_object(
      'organizationId', NEW.account_id,
      'originWorkspaceId', run_snapshot.origin_workspace_id,
      'targetWorkspaceId', NEW.workspace_id,
      'targetSessionId', NEW.session_id,
      'targetSessionVisibility', run_snapshot.session_visibility,
      'targetSessionAuthorityEpoch', run_snapshot.session_authority_epoch,
      'acceptedWork', jsonb_build_object(
        'kind', 'scheduled_task', 'taskId', run_snapshot.task_id,
        'taskAuthorityRevision', run_snapshot.task_authority_revision,
        'runId', run_snapshot.run_id
      ),
      'connectionId', run_snapshot.connection_id,
      'connectionGeneration', run_snapshot.connection_generation,
      'connectionStatus', 'active', 'providerDomain', run_snapshot.provider_domain,
      'connectionKind', run_snapshot.connection_kind, 'scope', 'user',
      'ownerSubjectId', run_snapshot.owner_subject_id,
      'ownerOrganizationMembershipId', run_snapshot.owner_organization_membership_id,
      'ownerMembershipAuthorizationRevision', run_snapshot.membership_authorization_revision,
      'authoritySource', 'sender',
      'selectionSources', to_jsonb(run_snapshot.selection_sources),
      'userDelegation', NULL
    );
    INSERT INTO turn_connection_authority_snapshots (
      account_id, workspace_id, session_id, turn_id, server_id,
      connection_id, connection_generation, origin_workspace_id,
      provider_domain, connection_kind, authority_scope, authority_source,
      owner_subject_id, owner_organization_membership_id,
      membership_authorization_revision, authority_id, authority_generation,
      grant_id, grant_generation, grant_mode, grant_context, grant_session_id,
      grant_authority_epoch, session_visibility, session_authority_epoch,
      canonical_snapshot, snapshot_digest
    ) VALUES (
      NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.id, run_snapshot.server_id,
      run_snapshot.connection_id, run_snapshot.connection_generation,
      run_snapshot.origin_workspace_id, run_snapshot.provider_domain,
      run_snapshot.connection_kind, 'user', 'sender',
      run_snapshot.owner_subject_id, run_snapshot.owner_organization_membership_id,
      run_snapshot.membership_authorization_revision, run_snapshot.authority_id,
      run_snapshot.authority_generation, NULL,
      NULL, NULL,
      NULL, NULL,
      NULL, run_snapshot.session_visibility,
      run_snapshot.session_authority_epoch, canonical,
      digest(convert_to(canonical::text, 'UTF8'), 'sha256')
    );
  END LOOP;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.check_organization_tenancy_parity_pre_0340(p_organization_id uuid, p_evidence_limit integer DEFAULT 10, p_observation_window_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    SET statement_timeout TO '60s'
    AS $$
DECLARE
  result jsonb;
  evidence_limit integer := least(greatest(coalesce(p_evidence_limit, 10), 0), 50);
  window_days integer := least(greatest(coalesce(p_observation_window_days, 30), 1), 365);
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'tenancy parity check requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_organization_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'tenancy parity scope mismatch'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO opengeni_private.organization_tenancy_parity_capabilities (
    backend_pid, transaction_id
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id())
  ON CONFLICT DO NOTHING;

  WITH gate_catalog(gate_id) AS (
    VALUES
      ('membership_personal_workspace_pointer'::text),
      ('membership_personal_workspace_exclusive'),
      ('membership_personal_workspace_same_organization'),
      ('personal_workspace_has_no_membership_row'),
      ('authority_resource_single_owner'),
      ('grant_delegation_fence_complete'),
      ('grant_owner_membership_active'),
      ('grant_authority_live'),
      ('grant_session_fence_not_ahead'),
      ('session_owner_provenance_paired'),
      ('session_owner_subject_matches_membership'),
      ('session_owner_membership_same_organization'),
      ('login_binding_dispute_propagated'),
      ('identity_active_binding_owned'),
      ('user_scoped_resource_live_anchor')
  ),
  -- Canonical human identities are organization-INDEPENDENT by design, so an
  -- organization-scoped parity report may only inspect the identities that
  -- actually anchor a subject of THIS organization. `user:<auth_user_id>` is
  -- the canonical subject encoding used by organization_memberships.
  scoped_identities AS (
    SELECT DISTINCT identity_subject.identity_id
    FROM canonical_human_identity_subjects identity_subject
    JOIN organization_memberships membership
      ON membership.account_id = p_organization_id
     AND membership.subject_id = 'user:' || identity_subject.auth_user_id
  ),
  violations(gate_id, evidence_id) AS (
    -- An active membership must identify a personal workspace.
    SELECT 'membership_personal_workspace_pointer'::text, membership.id
    FROM organization_memberships membership
    WHERE membership.account_id = p_organization_id
      AND membership.status = 'active'
      AND membership.personal_workspace_id IS NULL

    UNION ALL
    -- A personal workspace may identify at most one organization membership.
    SELECT 'membership_personal_workspace_exclusive', membership.id
    FROM organization_memberships membership
    WHERE membership.account_id = p_organization_id
      AND membership.personal_workspace_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM organization_memberships other
        WHERE other.account_id = p_organization_id
          AND other.id <> membership.id
          AND other.personal_workspace_id = membership.personal_workspace_id
      )

    UNION ALL
    -- The personal workspace must belong to the same organization.
    SELECT 'membership_personal_workspace_same_organization', membership.id
    FROM organization_memberships membership
    WHERE membership.account_id = p_organization_id
      AND membership.personal_workspace_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM workspaces workspace
        WHERE workspace.id = membership.personal_workspace_id
          AND workspace.account_id = p_organization_id
      )

    UNION ALL
    -- A managed personal workspace deliberately has NO workspace_memberships
    -- row: the owner-only access projection is derived, not delegable. A
    -- persisted row there is precisely how membership CRUD and the subject-
    -- membership fallback would widen it. Evidence is the workspace id.
    SELECT DISTINCT 'personal_workspace_has_no_membership_row',
      membership.personal_workspace_id
    FROM organization_memberships membership
    JOIN workspace_memberships workspace_membership
      ON workspace_membership.account_id = p_organization_id
     AND workspace_membership.workspace_id = membership.personal_workspace_id
    WHERE membership.account_id = p_organization_id
      AND membership.personal_workspace_id IS NOT NULL

    UNION ALL
    -- Stable authority uniqueness. The physical unique index is per
    -- (account, membership, kind, resource), so two DIFFERENT memberships can
    -- still claim the same resource - the ambiguity that must never be
    -- resolved toward either user.
    SELECT 'authority_resource_single_owner', authority.id
    FROM organization_user_resource_authorities authority
    WHERE authority.account_id = p_organization_id
      AND authority.status <> 'revoked'
      AND EXISTS (
        SELECT 1 FROM organization_user_resource_authorities rival
        WHERE rival.account_id = p_organization_id
          AND rival.status <> 'revoked'
          AND rival.resource_kind = authority.resource_kind
          AND rival.resource_id = authority.resource_id
          AND rival.organization_membership_id
            <> authority.organization_membership_id
      )

    UNION ALL
    -- Zero partial delegations: `always` carries neither fence, once/session
    -- carry both.
    SELECT 'grant_delegation_fence_complete', resource_grant.id
    FROM organization_user_resource_grants resource_grant
    WHERE resource_grant.account_id = p_organization_id
      AND NOT (
        (resource_grant.mode = 'always'
          AND resource_grant.session_id IS NULL
          AND resource_grant.authority_epoch IS NULL)
        OR (resource_grant.mode IN ('once', 'session')
          AND resource_grant.session_id IS NOT NULL
          AND resource_grant.authority_epoch IS NOT NULL
          AND resource_grant.authority_epoch > 0)
      )

    UNION ALL
    -- A live personal delegation owned by a human whose organization
    -- membership is suspended or revoked is a fallback to user authority.
    -- Suspension revokes personal-resource grants and offboarding runs the
    -- same teardown, so the drained state is the normal one.
    SELECT 'grant_owner_membership_active', resource_grant.id
    FROM organization_user_resource_grants resource_grant
    JOIN organization_memberships membership
      ON membership.id = resource_grant.owner_organization_membership_id
     AND membership.account_id = resource_grant.account_id
    WHERE resource_grant.account_id = p_organization_id
      AND resource_grant.status = 'active'
      AND membership.status <> 'active'

    UNION ALL
    -- An active grant over a revoked authority.
    SELECT 'grant_authority_live', resource_grant.id
    FROM organization_user_resource_grants resource_grant
    JOIN organization_user_resource_authorities authority
      ON authority.id = resource_grant.authority_id
     AND authority.account_id = resource_grant.account_id
    WHERE resource_grant.account_id = p_organization_id
      AND resource_grant.status = 'active'
      AND authority.status = 'revoked'

    UNION ALL
    -- A session-fenced grant whose epoch is AHEAD of the session it fences
    -- would survive the epoch advance that is supposed to revoke it. Epochs
    -- are monotonic and the fence is copied from the session at issuance, so
    -- `grant.authority_epoch <= session.authority_epoch` always holds.
    SELECT 'grant_session_fence_not_ahead', resource_grant.id
    FROM organization_user_resource_grants resource_grant
    JOIN sessions session_row
      ON session_row.id = resource_grant.session_id
     AND session_row.workspace_id = resource_grant.workspace_id
    WHERE resource_grant.account_id = p_organization_id
      AND resource_grant.session_id IS NOT NULL
      AND resource_grant.authority_epoch > session_row.authority_epoch

    UNION ALL
    -- Session owner provenance is paired, and a user_private session always
    -- has an owner.
    SELECT 'session_owner_provenance_paired', session_row.id
    FROM sessions session_row
    WHERE session_row.account_id = p_organization_id
      AND (
        (session_row.owner_organization_membership_id IS NULL)
          <> (session_row.owner_subject_id IS NULL)
        OR (session_row.visibility = 'user_private'
          AND session_row.owner_organization_membership_id IS NULL)
      )

    UNION ALL
    -- The denormalized owner subject must still name the owning membership.
    SELECT 'session_owner_subject_matches_membership', session_row.id
    FROM sessions session_row
    JOIN organization_memberships membership
      ON membership.id = session_row.owner_organization_membership_id
     AND membership.account_id = session_row.account_id
    WHERE session_row.account_id = p_organization_id
      AND session_row.owner_subject_id IS DISTINCT FROM membership.subject_id

    UNION ALL
    -- The owning membership must exist in this organization.
    SELECT 'session_owner_membership_same_organization', session_row.id
    FROM sessions session_row
    WHERE session_row.account_id = p_organization_id
      AND session_row.owner_organization_membership_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM organization_memberships membership
        WHERE membership.id = session_row.owner_organization_membership_id
          AND membership.account_id = p_organization_id
      )

    UNION ALL
    -- Provider-account collision rule: the physical unique index makes a
    -- second binding for one (provider, provider_account) impossible, so the
    -- collision is recorded by DISPUTING the existing binding and BOTH
    -- identities. A disputed binding whose identity is still usable is a
    -- collision that never fenced its identity.
    SELECT 'login_binding_dispute_propagated', binding.id
    FROM canonical_human_login_bindings binding
    JOIN scoped_identities scoped ON scoped.identity_id = binding.identity_id
    JOIN canonical_human_identities identity ON identity.id = binding.identity_id
    WHERE binding.status = 'disputed'
      AND identity.status <> 'disputed'

    UNION ALL
    -- The FK on active_login_binding_id proves existence, never ownership.
    SELECT 'identity_active_binding_owned', identity.id
    FROM canonical_human_identities identity
    JOIN scoped_identities scoped ON scoped.identity_id = identity.id
    WHERE identity.active_login_binding_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM canonical_human_login_bindings binding
        WHERE binding.id = identity.active_login_binding_id
          AND binding.identity_id = identity.id
      )

    UNION ALL
    -- Shadow comparison, connections lane: legacy effective scope is
    -- workspace; the proposed effective scope is `user`. A row claiming user
    -- authority without a live authority AND a live owning membership has no
    -- reachable user resolution - it must fall back to workspace or deny.
    SELECT 'user_scoped_resource_live_anchor', connection_row.id
    FROM connections connection_row
    WHERE connection_row.account_id = p_organization_id
      AND connection_row.authority_scope = 'user'
      AND NOT EXISTS (
        SELECT 1
        FROM organization_user_resource_authorities authority
        JOIN organization_memberships membership
          ON membership.id = authority.organization_membership_id
         AND membership.account_id = authority.account_id
        WHERE authority.id = connection_row.authority_id
          AND authority.account_id = p_organization_id
          AND authority.status = 'active'
          AND membership.status = 'active'
      )

    UNION ALL
    SELECT 'user_scoped_resource_live_anchor', variable_set.id
    FROM workspace_variable_sets variable_set
    WHERE variable_set.account_id = p_organization_id
      AND variable_set.authority_scope = 'user'
      AND NOT EXISTS (
        SELECT 1
        FROM organization_user_resource_authorities authority
        JOIN organization_memberships membership
          ON membership.id = authority.organization_membership_id
         AND membership.account_id = authority.account_id
        WHERE authority.id = variable_set.authority_id
          AND authority.account_id = p_organization_id
          AND authority.status = 'active'
          AND membership.status = 'active'
      )

    UNION ALL
    SELECT 'user_scoped_resource_live_anchor', rig_row.id
    FROM rigs rig_row
    WHERE rig_row.account_id = p_organization_id
      AND rig_row.authority_scope = 'user'
      AND NOT EXISTS (
        SELECT 1
        FROM organization_user_resource_authorities authority
        JOIN organization_memberships membership
          ON membership.id = authority.organization_membership_id
         AND membership.account_id = authority.account_id
        WHERE authority.id = rig_row.authority_id
          AND authority.account_id = p_organization_id
          AND authority.status = 'active'
          AND membership.status = 'active'
      )

    UNION ALL
    SELECT 'user_scoped_resource_live_anchor', enrollment.id
    FROM enrollments enrollment
    WHERE enrollment.account_id = p_organization_id
      AND enrollment.authority_scope = 'user'
      AND NOT EXISTS (
        SELECT 1
        FROM organization_user_resource_authorities authority
        JOIN organization_memberships membership
          ON membership.id = authority.organization_membership_id
         AND membership.account_id = authority.account_id
        WHERE authority.id = enrollment.authority_id
          AND authority.account_id = p_organization_id
          AND authority.status = 'active'
          AND membership.status = 'active'
      )

    UNION ALL
    -- Documents carry the same claim as authority_kind='personal' WITH a
    -- non-null authority_id (a null authority_id there is the separate,
    -- deliberately bounded legacy lane reported under `lanes`).
    SELECT 'user_scoped_resource_live_anchor', document.id
    FROM documents document
    WHERE document.account_id = p_organization_id
      AND document.authority_kind = 'personal'
      AND document.authority_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM organization_user_resource_authorities authority
        JOIN organization_memberships membership
          ON membership.id = authority.organization_membership_id
         AND membership.account_id = authority.account_id
        WHERE authority.id = document.authority_id
          AND authority.account_id = p_organization_id
          AND authority.status = 'active'
          AND membership.status = 'active'
      )
  ),
  aggregated AS (
    SELECT
      violation.gate_id,
      count(*)::int AS violation_count,
      (pg_catalog.array_agg(
        violation.evidence_id ORDER BY violation.evidence_id
      ))[1:evidence_limit] AS evidence
    FROM violations violation
    GROUP BY violation.gate_id
  )
  SELECT pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'organizationId', p_organization_id,
    'evidenceLimit', evidence_limit,
    'observationWindowDays', window_days,
    'gates', (
      SELECT pg_catalog.jsonb_object_agg(
        catalog.gate_id,
        pg_catalog.jsonb_build_object(
          'violations', coalesce(aggregated.violation_count, 0),
          'evidence', pg_catalog.to_jsonb(
            coalesce(aggregated.evidence, ARRAY[]::uuid[])
          ),
          'truncated', coalesce(aggregated.violation_count, 0)
            > coalesce(pg_catalog.array_length(aggregated.evidence, 1), 0)
        )
      )
      FROM gate_catalog catalog
      LEFT JOIN aggregated ON aggregated.gate_id = catalog.gate_id
    ),
    -- Compatibility lanes. These are populations the phase-D backfill drains;
    -- they are NOT invariant violations and must never be read as such.
    'lanes', pg_catalog.jsonb_build_object(
      'connectionsLegacyUser', (
        SELECT count(*)::int FROM connections connection_row
        WHERE connection_row.account_id = p_organization_id
          AND connection_row.authority_scope = 'legacy_user'
      ),
      -- Workspace-writer admissions and retained processes are immutable
      -- history: they are settled by UPDATE, nothing in the tree DELETEs them,
      -- and 0277's one-shot backfill only reached rows whose actor was a turn
      -- (`actor_kind`/`owner_actor_kind` = 'turn'), so every pre-0277 `direct:`
      -- or `process:` admission keeps the legacy_unattributed sentinel
      -- permanently. An all-time count of them therefore can never drain, and
      -- marking it drainable would make cutoverReady structurally unreachable
      -- for any deployment carrying one. Same treatment as the connection-use
      -- lane below: report the bounded recent window, where zero IS reachable
      -- and the honest signal is "the lane stopped being exercised".
      'workspaceWriterAdmissionsLegacyUnattributedInWindow', (
        SELECT count(*)::int FROM sandbox_workspace_mutation_admissions admission
        WHERE admission.account_id = p_organization_id
          AND admission.initiator_kind = 'legacy_unattributed'
          AND admission.admitted_at
            >= pg_catalog.now() - pg_catalog.make_interval(days => window_days)
      ),
      'workspaceWriterProcessesLegacyUnattributedInWindow', (
        SELECT count(*)::int FROM sandbox_retained_processes retained_process
        WHERE retained_process.account_id = p_organization_id
          AND retained_process.initiator_kind = 'legacy_unattributed'
          AND retained_process.started_at
            >= pg_catalog.now() - pg_catalog.make_interval(days => window_days)
      ),
      'documentsLegacyPersonalNullAuthority', (
        SELECT count(*)::int FROM documents document
        WHERE document.account_id = p_organization_id
          AND document.authority_kind = 'personal'
          AND document.authority_id IS NULL
      ),
      'codexCredentialsUnattributedConnector', (
        SELECT count(*)::int FROM codex_subscription_credentials credential
        WHERE credential.account_id = p_organization_id
          AND credential.connected_by_subject_id IS NULL
      ),
      'workspaceMemberSubjectsWithoutMembershipAnchor', (
        SELECT count(DISTINCT workspace_membership.subject_id)::int
        FROM workspace_memberships workspace_membership
        JOIN workspaces workspace ON workspace.id = workspace_membership.workspace_id
        WHERE workspace.account_id = p_organization_id
          AND workspace_membership.subject_id LIKE 'user:%'
          AND NOT EXISTS (
            SELECT 1 FROM organization_memberships membership
            WHERE membership.account_id = p_organization_id
              AND membership.subject_id = workspace_membership.subject_id
          )
      ),
      -- The DRAINABLE refinement of "ownerless sessions": a session whose
      -- creating subject would be attributed by today's write fence but whose
      -- owner is still null. Total ownerlessness is deliberately NOT reported
      -- as drainable - a service/API-key session is permanently ownerless.
      'sessionsAttributableButUnattributed', (
        SELECT count(*)::int FROM sessions session_row
        WHERE session_row.account_id = p_organization_id
          AND session_row.owner_organization_membership_id IS NULL
          AND session_row.created_by_kind = 'subject'
          AND session_row.created_by_subject_id IS NOT NULL
          AND EXISTS (
            SELECT 1 FROM organization_memberships membership
            WHERE membership.account_id = p_organization_id
              AND membership.subject_id = session_row.created_by_subject_id
              AND membership.status = 'active'
          )
          AND EXISTS (
            SELECT 1 FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = p_organization_id
              AND workspace_membership.workspace_id = session_row.workspace_id
              AND workspace_membership.subject_id = session_row.created_by_subject_id
          )
      ),
      -- Connection-use audit facts are immutable history, so the all-time
      -- count can never drain. The reachable-zero signal is "was the bounded
      -- pre-snapshot/legacy resolution lane exercised inside the observation
      -- window".
      'connectionUseLegacyResolutionsInWindow', (
        SELECT count(*)::int FROM connection_use_audit_facts audit_fact
        WHERE audit_fact.account_id = p_organization_id
          AND audit_fact.authority_scope = 'legacy_user'
          AND audit_fact.occurred_at
            >= pg_catalog.now() - pg_catalog.make_interval(days => window_days)
      )
    )
  ) INTO result;

  DELETE FROM opengeni_private.organization_tenancy_parity_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.organization_tenancy_parity_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION opengeni_private.claim_automatic_session_title_fanout_v1(p_limit integer) RETURNS TABLE(outbox_id uuid, account_id uuid, workspace_id uuid, session_id uuid, event_id uuid, sequence integer, type text, payload jsonb, payload_codec_version integer, occurred_at timestamp with time zone, client_event_id text, turn_id uuid, turn_generation integer, turn_attempt_id uuid, turn_association text, duplicate_of_event_id uuid, duplicate_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'titles');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_claim_titles_inner($1);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.claim_browser_state_artifact_cleanup(p_claim_timeout_ms bigint, p_limit integer) RETURNS TABLE(claim_id uuid, artifact_id uuid, account_id uuid, workspace_id uuid, object_key text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      WITH candidates AS (
        SELECT A.id, gen_random_uuid() AS claim_id
        FROM {{schema}}.browser_state_artifacts A
        WHERE A.purpose = 'private_checkpoint'
          AND (
            (
              A.state = 'delete_pending'
              AND A.retained_until <= clock_timestamp()
            )
            OR (
              A.state = 'deleting'
              AND A.delete_claimed_at <= clock_timestamp() - (
                greatest(p_claim_timeout_ms, 0)::double precision * interval '1 millisecond'
              )
            )
          )
        ORDER BY coalesce(A.delete_claimed_at, A.retained_until), A.id
        LIMIT least(greatest(p_limit, 0), 1000)
        FOR UPDATE SKIP LOCKED
      ), claimed AS (
        UPDATE {{schema}}.browser_state_artifacts A
        SET state = 'deleting',
          delete_claim_id = C.claim_id,
          delete_claimed_at = clock_timestamp()
        FROM candidates C
        WHERE A.id = C.id
        RETURNING A.*, C.claim_id
      )
      SELECT C.claim_id, C.id, C.account_id, C.workspace_id, C.object_key
      FROM claimed C;
    $$;

CREATE FUNCTION opengeni_private.claim_browser_state_upload_cleanup(p_claim_timeout_ms bigint, p_limit integer) RETURNS TABLE(claim_id uuid, upload_id uuid, account_id uuid, workspace_id uuid, object_key text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      WITH due AS MATERIALIZED (
        SELECT U.id, U.workspace_id, U.operation_id
        FROM {{schema}}.browser_state_uploads U
        WHERE (
            U.state IN ('prepared', 'delete_pending')
            AND U.cleanup_after <= clock_timestamp()
          ) OR (
            U.state = 'deleting'
            AND U.delete_claimed_at <= clock_timestamp() - (
              greatest(p_claim_timeout_ms, 0)::double precision * interval '1 millisecond'
            )
          )
        ORDER BY coalesce(U.delete_claimed_at, U.cleanup_after), U.id
        LIMIT least(greatest(p_limit, 0), 1000)
      ), locked_operations AS MATERIALIZED (
        SELECT O.workspace_id, O.operation_id,
          O.state AS operation_state, O.kind AS operation_kind
        FROM {{schema}}.interaction_operations O
        WHERE EXISTS (
          SELECT 1 FROM due D
          WHERE D.workspace_id = O.workspace_id
            AND D.operation_id = O.operation_id
        )
        FOR UPDATE OF O SKIP LOCKED
      ), candidates AS (
        SELECT U.id, gen_random_uuid() AS claim_id, U.state AS upload_state,
          O.operation_state, O.operation_kind
        FROM due D
        JOIN locked_operations O
          ON O.workspace_id = D.workspace_id
         AND O.operation_id = D.operation_id
        JOIN {{schema}}.browser_state_uploads U ON U.id = D.id
        WHERE (
            U.state IN ('prepared', 'delete_pending')
            AND U.cleanup_after <= clock_timestamp()
          ) OR (
            U.state = 'deleting'
            AND U.delete_claimed_at <= clock_timestamp() - (
              greatest(p_claim_timeout_ms, 0)::double precision * interval '1 millisecond'
            )
          )
        ORDER BY coalesce(U.delete_claimed_at, U.cleanup_after), U.id
        FOR UPDATE OF U SKIP LOCKED
      ), claimed AS (
        UPDATE {{schema}}.browser_state_uploads U
        SET state = 'deleting', delete_claim_id = C.claim_id,
          delete_claimed_at = clock_timestamp(), updated_at = clock_timestamp()
        FROM candidates C
        WHERE U.id = C.id
        RETURNING U.*, C.claim_id, C.upload_state, C.operation_state, C.operation_kind
      ), timed_out_operations AS (
        UPDATE {{schema}}.interaction_operations O
        SET state = CASE
            WHEN C.operation_state = 'dispatched' THEN 'outcome_unknown'
            ELSE 'failed'
          END,
          error_code = 'browser_state_upload_expired',
          error_message = CASE
            WHEN C.operation_state = 'dispatched'
              THEN 'Browser state upload outcome was not published before its authority expired'
            ELSE 'Browser state upload authority expired before dispatch'
          END,
          error_retryable = false, error_details = null,
          settled_at = clock_timestamp(), updated_at = clock_timestamp()
        FROM claimed C
        WHERE C.upload_state = 'prepared'
          AND O.workspace_id = C.workspace_id
          AND O.operation_id = C.operation_id
          AND O.state IN ('prepared', 'dispatched')
        RETURNING O.account_id, O.workspace_id, O.resource_id, O.kind,
          C.operation_state
      ), timed_out_sessions AS (
        UPDATE {{schema}}.browser_sessions S
        SET lifecycle = CASE
            WHEN T.operation_state = 'dispatched' THEN 'lost'
            ELSE 'active'
          END,
          failure_code = CASE
            WHEN T.operation_state = 'dispatched' THEN 'browser_state_upload_expired'
            ELSE NULL
          END,
          updated_at = clock_timestamp()
        FROM timed_out_operations T
        WHERE T.kind = 'suspend'
          AND S.workspace_id = T.workspace_id
          AND S.id = T.resource_id
          AND S.lifecycle = 'suspending'
        RETURNING S.account_id, S.workspace_id
      ), advanced_revisions AS (
        UPDATE {{schema}}.workspace_interaction_revisions R
        SET revision = R.revision + 1, updated_at = clock_timestamp()
        FROM (
          SELECT DISTINCT account_id, workspace_id FROM timed_out_sessions
        ) S
        WHERE R.account_id = S.account_id AND R.workspace_id = S.workspace_id
        RETURNING R.workspace_id
      )
      SELECT C.claim_id, C.id, C.account_id, C.workspace_id, C.object_key
      FROM claimed C;
    $$;

CREATE FUNCTION opengeni_private.claim_connected_command_output_releases(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint, p_due_before timestamp with time zone) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, command_id uuid, claim_id uuid, command_state text, control_workspace_id uuid, enrollment_id uuid, connection_instance_id text, op_id text, reconcile_attempts integer, reconcile_proof_outcome text, reconcile_proof_exit_code integer, reconcile_proof_reason text, reconcile_proof_observed_at timestamp with time zone, output_exit_seq text, output_attach_generation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'output_release');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_claim_output_release_inner($1, $2, $3, $4);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.claim_connected_machine_background_commands(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, command_id uuid, claim_id uuid, command_state text, control_workspace_id uuid, enrollment_id uuid, connection_instance_id text, op_id text, reconcile_attempts integer, reconcile_proof_outcome text, reconcile_proof_exit_code integer, reconcile_proof_reason text, reconcile_proof_observed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'connected-command reconciliation limit must be between 1 and 100'
          USING ERRCODE = '22023';
      END IF;
      IF p_claim_ttl_ms < 0 OR p_claim_ttl_ms > 3600000 THEN
        RAISE EXCEPTION 'connected-command reconciliation claim TTL is invalid'
          USING ERRCODE = '22023';
      END IF;

      RETURN QUERY
      WITH candidates AS MATERIALIZED (
        SELECT command.id, command.reconcile_after, command.started_at
        FROM {{schema}}.session_background_commands command
        WHERE command.provider = 'connected_machine'
          AND command.state IN ('running', 'stopping')
          AND command.reconcile_after <= pg_catalog.now()
          AND (
            command.reconcile_claim_id IS NULL
            OR command.reconcile_claimed_at <= pg_catalog.now()
              - pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0)
          )
        ORDER BY command.reconcile_after, command.started_at, command.id
        FOR UPDATE OF command SKIP LOCKED
        LIMIT p_limit
      ), claimed AS (
        UPDATE {{schema}}.session_background_commands command SET
          reconcile_after = pg_catalog.now()
            + pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0),
          reconcile_claim_id = p_claim_id,
          reconcile_claimed_at = pg_catalog.now(),
          reconcile_attempts = command.reconcile_attempts + 1,
          last_reconcile_outcome = 'claimed',
          updated_at = pg_catalog.clock_timestamp()
        FROM candidates
        WHERE command.id = candidates.id
          AND command.provider = 'connected_machine'
          AND command.state IN ('running', 'stopping')
        RETURNING command.*, candidates.reconcile_after AS due_at,
          candidates.started_at AS candidate_started_at
      )
      SELECT claimed.account_id,
        claimed.workspace_id,
        claimed.session_id,
        claimed.id,
        claimed.reconcile_claim_id,
        claimed.state,
        claimed.control_workspace_id,
        claimed.enrollment_id,
        claimed.connection_instance_id,
        claimed.op_id,
        claimed.reconcile_attempts,
        claimed.reconcile_proof_outcome,
        claimed.reconcile_proof_exit_code,
        claimed.reconcile_proof_reason,
        claimed.reconcile_proof_observed_at
      FROM claimed
      ORDER BY claimed.due_at, claimed.candidate_started_at, claimed.id;
    END;
    $$;

CREATE FUNCTION opengeni_private.claim_connected_machine_background_commands(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint, p_due_before timestamp with time zone) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, command_id uuid, claim_id uuid, command_state text, control_workspace_id uuid, enrollment_id uuid, connection_instance_id text, op_id text, reconcile_attempts integer, reconcile_proof_outcome text, reconcile_proof_exit_code integer, reconcile_proof_reason text, reconcile_proof_observed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      inventory_id uuid;
      access_id uuid;
      workspace_ids uuid[];
      workspace_value uuid;
      owns_compute_capability boolean := false;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'connected-command reconciliation limit must be between 1 and 100'
          USING ERRCODE = '22023';
      END IF;
      IF p_claim_ttl_ms < 0 OR p_claim_ttl_ms > 3600000 THEN
        RAISE EXCEPTION 'connected-command reconciliation claim TTL is invalid'
          USING ERRCODE = '22023';
      END IF;

      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      SELECT array_agg(DISTINCT command.workspace_id ORDER BY command.workspace_id) INTO workspace_ids
      FROM {{schema}}.session_background_commands command
      WHERE command.provider = 'connected_machine' AND command.state IN ('running','stopping')
        AND command.reconcile_after <= LEAST(p_due_before, pg_catalog.now());
      FOREACH workspace_value IN ARRAY COALESCE(workspace_ids, ARRAY[]::uuid[]) LOOP
        PERFORM {{schema}}.acquire_session_tenancy_fence(workspace_value);
      END LOOP;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      access_id := opengeni_private.open_session_tenancy_fenced_access({{schema}}.session_tenancy_fence_target_schema());
      INSERT INTO opengeni_private.scoped_compute_capabilities(backend_pid, transaction_id, capability_kind)
        VALUES(pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
        ON CONFLICT DO NOTHING;
      owns_compute_capability := FOUND;
      RETURN QUERY
      WITH candidates AS MATERIALIZED (
        SELECT command.id, command.reconcile_after, command.started_at,
          CASE
          WHEN enrollment.status = 'revoked' THEN 'op_enrollment_revoked'
          WHEN enrollment.connection_instance_id IS NOT NULL
            AND enrollment.connection_instance_id <> command.connection_instance_id
            THEN 'op_connection_replaced'
          WHEN enrollment.connection_instance_id IS NULL
            AND enrollment.went_offline_reason IN (
              'GOING_OFFLINE_REASON_USER_STOP', 'GOING_OFFLINE_REASON_UPDATE',
              'GOING_OFFLINE_REASON_HOST_SHUTDOWN')
            THEN 'op_connection_stopped'
          ELSE NULL END AS retirement_reason
        FROM {{schema}}.session_background_commands command
        JOIN {{schema}}.enrollments enrollment ON enrollment.id = command.enrollment_id
          AND enrollment.account_id = command.account_id
          AND enrollment.workspace_id = command.control_workspace_id
        WHERE command.provider = 'connected_machine'
          AND command.workspace_id = ANY(workspace_ids)
          AND command.state IN ('running', 'stopping')
          AND command.reconcile_after <= LEAST(p_due_before, pg_catalog.now())
          AND (
            command.reconcile_claim_id IS NULL
            OR command.reconcile_claimed_at <= pg_catalog.now()
              - pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0)
          )
        AND ((enrollment.kind <> 'sandbox' AND (command.state <> 'running' OR command.last_reconcile_outcome IS DISTINCT FROM 'provider_unanswered')) OR enrollment.status = 'revoked' OR (enrollment.connection_instance_id IS NOT NULL AND enrollment.connection_instance_id <> command.connection_instance_id) OR command.state = 'stopping' OR command.completion_notified_at IS NOT NULL OR command.reconcile_proof_outcome IS NOT NULL)
        ORDER BY command.reconcile_after, command.started_at, command.id
        FOR UPDATE OF command SKIP LOCKED
        LIMIT p_limit
      ), claimed AS (
        UPDATE {{schema}}.session_background_commands command SET
          reconcile_after = pg_catalog.now()
            + pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0),
          reconcile_claim_id = p_claim_id,
          reconcile_claimed_at = pg_catalog.now(),
          reconcile_attempts = command.reconcile_attempts + 1,
          last_reconcile_outcome = 'claimed',
          reconcile_proof_outcome = COALESCE(command.reconcile_proof_outcome,
            CASE WHEN candidates.retirement_reason IS NOT NULL THEN 'lost' END),
          reconcile_proof_reason = COALESCE(command.reconcile_proof_reason, candidates.retirement_reason),
          reconcile_proof_observed_at = COALESCE(command.reconcile_proof_observed_at,
            CASE WHEN candidates.retirement_reason IS NOT NULL THEN pg_catalog.clock_timestamp() END),
          updated_at = pg_catalog.clock_timestamp()
        FROM candidates
        WHERE command.id = candidates.id
          AND command.provider = 'connected_machine'
          AND command.state IN ('running', 'stopping')
        RETURNING command.*, candidates.reconcile_after AS due_at,
          candidates.started_at AS candidate_started_at
      )
      SELECT claimed.account_id,
        claimed.workspace_id,
        claimed.session_id,
        claimed.id,
        claimed.reconcile_claim_id,
        claimed.state,
        claimed.control_workspace_id,
        claimed.enrollment_id,
        claimed.connection_instance_id,
        claimed.op_id,
        claimed.reconcile_attempts,
        claimed.reconcile_proof_outcome,
        claimed.reconcile_proof_exit_code,
        claimed.reconcile_proof_reason,
        claimed.reconcile_proof_observed_at
      FROM claimed
      ORDER BY claimed.due_at, claimed.candidate_started_at, claimed.id;
      IF owns_compute_capability THEN
        DELETE FROM opengeni_private.scoped_compute_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id() AND capability_kind = 'read';
      END IF;
      PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      IF owns_compute_capability THEN
        DELETE FROM opengeni_private.scoped_compute_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id() AND capability_kind = 'read';
      END IF;
      PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END;
    $$;

CREATE FUNCTION opengeni_private.claim_due_transcription_recording_object_cleanup(p_grace_ms bigint, p_claim_timeout_ms bigint, p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, subject_id text, recording_id uuid, object_key text, cleanup_claim_id uuid)
    LANGUAGE sql STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      WITH due_recordings AS MATERIALIZED (
        SELECT R.id, R.account_id, R.workspace_id, R.subject_id, R.expires_at
        FROM {{schema}}.transcription_recordings R
        WHERE EXISTS (
          SELECT 1
          FROM {{schema}}.transcription_recording_objects O
          WHERE O.recording_id = R.id
            AND O.cleaned_at IS NULL
            AND O.cleanup_after <=
              clock_timestamp() - greatest(p_grace_ms, 0) * interval '1 millisecond'
            AND (
              O.cleanup_claim_id IS NULL
              OR O.cleanup_claimed_at <=
                clock_timestamp() - greatest(p_claim_timeout_ms, 0) * interval '1 millisecond'
            )
        )
        ORDER BY R.expires_at, R.id
        FOR UPDATE OF R SKIP LOCKED
        LIMIT least(greatest(p_limit, 0), 1000)
      ), expired_recordings AS (
        UPDATE {{schema}}.transcription_recordings R
        SET state = 'discarded',
            processing_owner = NULL,
            processing_started_at = NULL,
            error_code = NULL,
            retryable = false,
            updated_at = clock_timestamp()
        FROM due_recordings D
        WHERE R.id = D.id
          AND D.expires_at <=
            clock_timestamp() - greatest(p_grace_ms, 0) * interval '1 millisecond'
          AND R.state <> 'discarded'
        RETURNING R.id
      ), candidates AS MATERIALIZED (
        SELECT O.object_key
        FROM {{schema}}.transcription_recording_objects O
        JOIN due_recordings R ON R.id = O.recording_id
        WHERE O.cleaned_at IS NULL
          AND O.cleanup_after <=
            clock_timestamp() - greatest(p_grace_ms, 0) * interval '1 millisecond'
          AND (
            O.cleanup_claim_id IS NULL
            OR O.cleanup_claimed_at <=
              clock_timestamp() - greatest(p_claim_timeout_ms, 0) * interval '1 millisecond'
          )
        ORDER BY O.cleanup_after, O.object_key
        FOR UPDATE OF O SKIP LOCKED
        LIMIT least(greatest(p_limit, 0), 1000)
      ), claimed AS (
        UPDATE {{schema}}.transcription_recording_objects O
        SET cleanup_claim_id = gen_random_uuid(), cleanup_claimed_at = clock_timestamp()
        FROM candidates C
        WHERE O.object_key = C.object_key
        RETURNING
          O.account_id,
          O.workspace_id,
          O.subject_id,
          O.recording_id,
          O.object_key,
          O.cleanup_claim_id
      )
      SELECT
        C.account_id,
        C.workspace_id,
        C.subject_id,
        C.recording_id,
        C.object_key,
        C.cleanup_claim_id
      FROM claimed C, (SELECT count(*) FROM expired_recordings) AS fence;
    $$;

CREATE FUNCTION opengeni_private.claim_editable_artifact_live_outbox(p_owner text, p_lease_duration_ms integer, p_limit integer, p_data_schema name) RETURNS TABLE(outbox_id text, account_id uuid, workspace_id uuid, artifact_id text, transaction_id text, snapshot_id text, event_kind text, event jsonb, state text, attempt_count integer, lease_owner text, lease_expires_at timestamp with time zone, next_attempt_at timestamp with time zone, last_error_code text, published_at timestamp with time zone, dead_lettered_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
BEGIN
  IF p_owner IS NULL OR pg_catalog.octet_length(p_owner) NOT BETWEEN 1 AND 256
    OR p_lease_duration_ms IS NULL
    OR p_lease_duration_ms NOT BETWEEN 1 AND 86400000
    OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000
    OR p_data_schema IS NULL
  THEN
    RAISE EXCEPTION 'invalid editable artifact outbox claim bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  RETURN QUERY EXECUTE pg_catalog.format($query$
    WITH exhausted_candidates AS MATERIALIZED (
      SELECT candidate.id
      FROM %1$I.editable_artifact_live_outbox candidate
      WHERE candidate.attempt_count >= 1000000
        AND ((candidate.state = 'pending'
            AND candidate.next_attempt_at <= pg_catalog.statement_timestamp())
          OR (candidate.state = 'publishing'
            AND candidate.lease_expires_at <= pg_catalog.statement_timestamp()))
      ORDER BY candidate.next_attempt_at, candidate.created_at, candidate.id
      FOR UPDATE SKIP LOCKED
      LIMIT $1
    ), exhausted AS (
      UPDATE %1$I.editable_artifact_live_outbox target
      SET state = 'dead_lettered', lease_owner = NULL, lease_expires_at = NULL,
        last_error_code = 'attempts_exhausted',
        dead_lettered_at = pg_catalog.statement_timestamp()
      FROM exhausted_candidates
      WHERE target.id = exhausted_candidates.id
      RETURNING target.id
    ), candidates AS (
      SELECT candidate.id
      FROM %1$I.editable_artifact_live_outbox candidate
      WHERE candidate.attempt_count < 1000000
        AND ((candidate.state = 'pending'
            AND candidate.next_attempt_at <= pg_catalog.statement_timestamp())
          OR (candidate.state = 'publishing'
            AND candidate.lease_expires_at <= pg_catalog.statement_timestamp()))
      ORDER BY candidate.next_attempt_at, candidate.created_at, candidate.id
      FOR UPDATE SKIP LOCKED
      LIMIT $1
    ), claimed AS (
      UPDATE %1$I.editable_artifact_live_outbox target
      SET state = 'publishing',
        attempt_count = target.attempt_count + 1,
        lease_owner = $2,
        lease_expires_at = pg_catalog.statement_timestamp()
          + pg_catalog.make_interval(secs => $3 / 1000.0),
        last_error_code = NULL
      FROM candidates
      WHERE target.id = candidates.id
      RETURNING target.*
    )
    SELECT claimed.id, claimed.account_id, claimed.workspace_id,
      claimed.artifact_id, claimed.transaction_id, claimed.snapshot_id,
      claimed.event_kind, claimed.event, claimed.state, claimed.attempt_count,
      claimed.lease_owner, claimed.lease_expires_at, claimed.next_attempt_at,
      claimed.last_error_code, claimed.published_at, claimed.dead_lettered_at,
      claimed.created_at
    FROM claimed
    CROSS JOIN (SELECT count(*) FROM exhausted) exhausted_barrier
    ORDER BY claimed.created_at, claimed.id
  $query$, data_schema) USING p_limit, p_owner, p_lease_duration_ms;
END;
$_$;

CREATE FUNCTION opengeni_private.claim_editable_artifact_materializations(p_owner text, p_lease_duration_ms integer, p_limit integer, p_data_schema name) RETURNS TABLE(account_id uuid, workspace_id uuid, artifact_id text, job_id text, version_id text, modality text, input_snapshot_id text, target_head_sequence bigint, state_hash text, source_object_reference text, source_byte_size bigint, source_content_hash text, source_mime_type text, model_schema_version integer, operation_protocol_version integer, snapshot_protocol_version integer, format text, codec_id text, normalized_options text, options_hash text, codec_version text, kernel_version text, font_registry_hash text, policy_hash text, attempt_count integer, lease_owner text, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
BEGIN
  IF p_owner IS NULL OR pg_catalog.octet_length(p_owner) NOT BETWEEN 1 AND 256
    OR p_owner <> pg_catalog.btrim(p_owner)
    OR p_lease_duration_ms IS NULL
    OR p_lease_duration_ms NOT BETWEEN 1 AND 86400000
    OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000
    OR p_data_schema IS NULL
  THEN
    RAISE EXCEPTION 'invalid editable artifact materialization claim bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  RETURN QUERY EXECUTE pg_catalog.format($query$
    WITH exhausted_candidates AS MATERIALIZED (
      SELECT candidate.account_id, candidate.workspace_id,
        candidate.artifact_id, candidate.id
      FROM %1$I.editable_artifact_materialization_jobs candidate
      WHERE candidate.state = 'running'
        AND candidate.attempt_count >= 1000
        AND candidate.lease_expires_at <= pg_catalog.statement_timestamp()
      ORDER BY candidate.lease_expires_at, candidate.created_at,
        candidate.account_id, candidate.workspace_id, candidate.artifact_id, candidate.id
      FOR UPDATE OF candidate SKIP LOCKED
      LIMIT $1
    ), exhausted AS (
      UPDATE %1$I.editable_artifact_materialization_jobs target
      SET state = 'failed', settled_by_owner = target.lease_owner,
        lease_owner = NULL, lease_expires_at = NULL,
        error_code = 'attempts_exhausted',
        completed_at = pg_catalog.statement_timestamp()
      FROM exhausted_candidates
      WHERE target.account_id = exhausted_candidates.account_id
        AND target.workspace_id = exhausted_candidates.workspace_id
        AND target.artifact_id = exhausted_candidates.artifact_id
        AND target.id = exhausted_candidates.id
      RETURNING target.id
    ), candidates AS (
      SELECT candidate.account_id, candidate.workspace_id,
        candidate.artifact_id, candidate.id
      FROM %1$I.editable_artifact_materialization_jobs candidate
      WHERE candidate.attempt_count < 1000
        AND (candidate.state = 'pending' OR (
          candidate.state = 'running'
          AND candidate.lease_expires_at <= pg_catalog.statement_timestamp()
        ))
      ORDER BY COALESCE(candidate.lease_expires_at, candidate.created_at),
        candidate.created_at, candidate.account_id, candidate.workspace_id,
        candidate.artifact_id, candidate.id
      FOR UPDATE OF candidate SKIP LOCKED
      LIMIT $1
    ), claimed AS (
      UPDATE %1$I.editable_artifact_materialization_jobs target
      SET state = 'running', attempt_count = target.attempt_count + 1,
        lease_owner = $2,
        lease_expires_at = pg_catalog.statement_timestamp()
          + pg_catalog.make_interval(secs => $3 / 1000.0),
        settled_by_owner = NULL, error_code = NULL,
        started_at = pg_catalog.statement_timestamp(), completed_at = NULL
      FROM candidates
      WHERE target.account_id = candidates.account_id
        AND target.workspace_id = candidates.workspace_id
        AND target.artifact_id = candidates.artifact_id
        AND target.id = candidates.id
      RETURNING target.*
    )
    SELECT claimed.account_id, claimed.workspace_id, claimed.artifact_id,
      claimed.id, claimed.version_id, artifact.modality, claimed.input_snapshot_id,
      claimed.target_head_sequence, claimed.state_hash,
      source_blob.object_reference, source_blob.byte_size,
      source_blob.content_hash, source_blob.mime_type,
      source_snapshot.model_schema_version, source_snapshot.operation_protocol_version,
      source_snapshot.crdt_state_version,
      claimed.format, claimed.codec_id, claimed.normalized_options,
      claimed.options_hash, claimed.codec_version, claimed.kernel_version,
      claimed.font_registry_hash, claimed.policy_hash, claimed.attempt_count,
      claimed.lease_owner, claimed.lease_expires_at
    FROM claimed
    CROSS JOIN (SELECT count(*) FROM exhausted) exhausted_barrier
    JOIN %1$I.editable_artifacts artifact
      ON artifact.account_id = claimed.account_id
     AND artifact.workspace_id = claimed.workspace_id
     AND artifact.id = claimed.artifact_id
    JOIN %1$I.editable_artifact_snapshots source_snapshot
      ON source_snapshot.account_id = claimed.account_id
     AND source_snapshot.workspace_id = claimed.workspace_id
     AND source_snapshot.artifact_id = claimed.artifact_id
     AND source_snapshot.id = claimed.input_snapshot_id
     AND source_snapshot.covered_head_sequence = claimed.target_head_sequence
     AND source_snapshot.state_hash = claimed.state_hash
    JOIN %1$I.editable_artifact_blob_refs source_blob
      ON source_blob.account_id = source_snapshot.account_id
     AND source_blob.workspace_id = source_snapshot.workspace_id
     AND source_blob.artifact_id = source_snapshot.artifact_id
     AND source_blob.id = source_snapshot.blob_ref_id
     AND source_blob.kind = 'snapshot'
     AND source_blob.byte_size = source_snapshot.byte_size
     AND source_blob.content_hash = source_snapshot.content_hash
     AND source_blob.mime_type = source_snapshot.mime_type
    ORDER BY claimed.created_at, claimed.account_id, claimed.workspace_id,
      claimed.artifact_id, claimed.id
  $query$, data_schema) USING p_limit, p_owner, p_lease_duration_ms;
END;
$_$;

CREATE FUNCTION opengeni_private.claim_expired_file_upload_cleanup(p_grace_ms bigint, p_claim_timeout_ms bigint, p_limit integer) RETURNS TABLE(upload_id uuid, account_id uuid, workspace_id uuid, file_id uuid, object_key text)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  WITH candidates AS (
    SELECT U.id
    FROM file_uploads U
    WHERE
      (
        U.status = 'pending'
        AND U.expires_at <= clock_timestamp() - (
          greatest(p_grace_ms, 0)::double precision * interval '1 millisecond'
        )
      )
      OR
      (
        U.status = 'cleanup_pending'
        AND U.updated_at <= clock_timestamp() - (
          greatest(p_claim_timeout_ms, 0)::double precision * interval '1 millisecond'
        )
      )
    ORDER BY U.expires_at, U.id
    -- Defense in depth: the worker asks for 100, but the privileged function
    -- itself stays bounded even if an application caller passes a huge limit.
    LIMIT least(greatest(p_limit, 0), 1000)
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE file_uploads U
    SET status = 'cleanup_pending', updated_at = clock_timestamp()
    FROM candidates C
    WHERE U.id = C.id
    RETURNING U.id, U.account_id, U.workspace_id, U.file_id
  ), failed_files AS (
    UPDATE files F
    SET status = 'failed', updated_at = clock_timestamp()
    FROM claimed C
    WHERE F.id = C.file_id AND F.workspace_id = C.workspace_id
    RETURNING F.id, F.object_key
  )
  SELECT C.id, C.account_id, C.workspace_id, C.file_id, F.object_key
  FROM claimed C
  JOIN failed_files F ON F.id = C.file_id;
$$;

CREATE TABLE memory_slack_publications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    configuration_id uuid NOT NULL,
    configuration_revision integer NOT NULL,
    connection_id uuid NOT NULL,
    slack_team_id text NOT NULL,
    slack_channel_id text NOT NULL,
    source_type text NOT NULL,
    source_id text NOT NULL,
    source_version text,
    source_idempotency_key text NOT NULL,
    projection jsonb NOT NULL,
    projection_sha256 text NOT NULL,
    importance text NOT NULL,
    delivery_mode text NOT NULL,
    state text NOT NULL,
    operation_id uuid NOT NULL,
    initiator_kind text NOT NULL,
    initiator_subject_id text NOT NULL,
    initiating_human_subject_id text,
    session_id uuid,
    turn_id uuid,
    attempt_id uuid,
    claim_holder_id uuid,
    claim_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    retry_at timestamp with time zone,
    last_error_code text,
    slack_message_timestamp text,
    delivered_at timestamp with time zone,
    terminal_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT memory_slack_publications_attempt_check CHECK ((attempt_count >= 0)),
    CONSTRAINT memory_slack_publications_claim_check CHECK ((((state = 'delivering'::text) AND (claim_holder_id IS NOT NULL) AND (claim_expires_at IS NOT NULL) AND (retry_at IS NULL)) OR ((state = 'retry_wait'::text) AND (claim_holder_id IS NULL) AND (claim_expires_at IS NULL) AND (retry_at IS NOT NULL)) OR ((state <> ALL (ARRAY['delivering'::text, 'retry_wait'::text])) AND (claim_holder_id IS NULL) AND (claim_expires_at IS NULL) AND (retry_at IS NULL)))),
    CONSTRAINT memory_slack_publications_destination_check CHECK (((configuration_revision > 0) AND ((octet_length(slack_team_id) >= 1) AND (octet_length(slack_team_id) <= 64)) AND ((octet_length(slack_channel_id) >= 1) AND (octet_length(slack_channel_id) <= 64)))),
    CONSTRAINT memory_slack_publications_distribution_check CHECK (((importance = ANY (ARRAY['major'::text, 'normal'::text, 'minor'::text])) AND (delivery_mode = ANY (ARRAY['auto'::text, 'review'::text])))),
    CONSTRAINT memory_slack_publications_error_check CHECK (((last_error_code IS NULL) OR ((octet_length(last_error_code) >= 1) AND (octet_length(last_error_code) <= 128)))),
    CONSTRAINT memory_slack_publications_initiator_check CHECK (((initiator_kind = ANY (ARRAY['human'::text, 'agent'::text, 'service'::text])) AND ((octet_length(initiator_subject_id) >= 1) AND (octet_length(initiator_subject_id) <= 1024)) AND ((initiating_human_subject_id IS NULL) OR ((octet_length(initiating_human_subject_id) >= 1) AND (octet_length(initiating_human_subject_id) <= 1024))))),
    CONSTRAINT memory_slack_publications_projection_check CHECK (((jsonb_typeof(projection) = 'object'::text) AND ((octet_length((projection)::text) >= 2) AND (octet_length((projection)::text) <= 8192)) AND (projection_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT memory_slack_publications_source_check CHECK ((((octet_length(source_id) >= 1) AND (octet_length(source_id) <= 1024)) AND ((source_version IS NULL) OR ((octet_length(source_version) >= 1) AND (octet_length(source_version) <= 512))) AND ((octet_length(source_idempotency_key) >= 1) AND (octet_length(source_idempotency_key) <= 256)))),
    CONSTRAINT memory_slack_publications_source_type_check CHECK ((source_type = ANY (ARRAY['workspace_memory'::text, 'durable_learning'::text]))),
    CONSTRAINT memory_slack_publications_state_check CHECK ((state = ANY (ARRAY['review_pending'::text, 'queued'::text, 'delivering'::text, 'retry_wait'::text, 'delivered'::text, 'rejected'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT memory_slack_publications_terminal_check CHECK ((((state = 'delivered'::text) AND (claim_holder_id IS NULL) AND (claim_expires_at IS NULL) AND (retry_at IS NULL) AND (slack_message_timestamp IS NOT NULL) AND (delivered_at IS NOT NULL) AND (terminal_at IS NOT NULL)) OR ((state = ANY (ARRAY['rejected'::text, 'failed'::text, 'cancelled'::text])) AND (claim_holder_id IS NULL) AND (claim_expires_at IS NULL) AND (retry_at IS NULL) AND (terminal_at IS NOT NULL)) OR ((state <> ALL (ARRAY['delivered'::text, 'rejected'::text, 'failed'::text, 'cancelled'::text])) AND (slack_message_timestamp IS NULL) AND (delivered_at IS NULL) AND (terminal_at IS NULL))))
);

ALTER TABLE ONLY memory_slack_publications FORCE ROW LEVEL SECURITY;

CREATE FUNCTION opengeni_private.claim_memory_slack_publication(p_holder uuid, p_lease_ms integer) RETURNS SETOF memory_slack_publications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_lease_ms < 1000 OR p_lease_ms > 300000 THEN
        RAISE EXCEPTION 'invalid memory Slack publication claim lease';
      END IF;
      RETURN QUERY
      WITH candidate AS (
        SELECT P.id
        FROM {{schema}}.memory_slack_publications P
        WHERE (
            P.state = 'queued'
          ) OR (
            P.state = 'retry_wait'
            AND P.retry_at <= now()
          ) OR (
            P.state = 'delivering'
            AND P.claim_expires_at <= now()
          )
        ORDER BY P.retry_at NULLS FIRST, P.created_at, P.id
        FOR UPDATE SKIP LOCKED
        LIMIT 1
      ), claimed AS (
        UPDATE {{schema}}.memory_slack_publications P
        SET state = 'delivering',
            claim_holder_id = p_holder,
            claim_expires_at = now() + make_interval(secs => p_lease_ms::double precision / 1000),
            retry_at = NULL,
            attempt_count = P.attempt_count + 1,
            updated_at = now()
        FROM candidate C
        WHERE P.id = C.id
        RETURNING P.*
      ), receipt AS (
        INSERT INTO {{schema}}.memory_slack_publication_receipts (
          account_id, workspace_id, publication_id, sequence, kind, state,
          attempt_number, actor_kind, actor_subject_id, operation_id
        )
        SELECT
          C.account_id, C.workspace_id, C.id,
          COALESCE((
            SELECT max(R.sequence)
            FROM {{schema}}.memory_slack_publication_receipts R
            WHERE R.publication_id = C.id
          ), 0) + 1,
          'delivery_claimed', 'delivering', C.attempt_count,
          'service', 'memory-slack-delivery', C.operation_id
        FROM claimed C
        RETURNING publication_id
      )
      SELECT C.*
      FROM claimed C
      JOIN receipt R ON R.publication_id = C.id;
    END
    $$;

CREATE FUNCTION opengeni_private.claim_native_push_deliveries_v1(p_claim_id uuid, p_limit integer, p_claim_seconds integer) RETURNS TABLE(delivery_id uuid, platform text, app_id text, environment text, token text, payload jsonb, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_claim_id IS NULL THEN
    RAISE EXCEPTION 'native push claim id is required' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH picked AS (
    SELECT delivery.id FROM opengeni_private.native_push_deliveries delivery
    WHERE delivery.delivered_at IS NULL AND delivery.failed_at IS NULL
      AND delivery.next_attempt_at <= now()
      AND (delivery.claimed_until IS NULL OR delivery.claimed_until < now())
    ORDER BY delivery.next_attempt_at, delivery.created_at
    LIMIT greatest(1, least(p_limit, 100))
    FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE opengeni_private.native_push_deliveries delivery SET
      claim_id = p_claim_id,
      claimed_until = now() + make_interval(secs => greatest(5, least(p_claim_seconds, 600))),
      attempts = delivery.attempts + 1
    FROM picked WHERE delivery.id = picked.id
    RETURNING delivery.id, delivery.auth_session_id, delivery.payload, delivery.attempts
  )
  SELECT claimed.id, device.platform, device.app_id, device.environment, device.token,
    claimed.payload, claimed.attempts
  FROM claimed
  JOIN opengeni_private.native_push_devices device
    ON device.auth_session_id = claimed.auth_session_id;
END
$$;

CREATE FUNCTION opengeni_private.claim_organization_user_setup_delivery_unfenced_0401(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  invitation_id_value uuid := nullif(p_command ->> 'invitationId', '')::uuid;
  invitation_operation_id_value uuid := nullif(p_command ->> 'invitationOperationId', '')::uuid;
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  actor organization_memberships%ROWTYPE;
  invitation organization_membership_invitations%ROWTYPE;
  delivery organization_user_setup_deliveries%ROWTYPE;
  attempt organization_user_setup_delivery_attempts%ROWTYPE;
  normalized_email text;
  workspace_snapshot jsonb;
  now_value timestamptz := clock_timestamp();
  delivery_id_value uuid;
  verified_invitation_operation_id uuid;
BEGIN
  IF account_id_value IS NULL
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
    OR actor_subject IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR invitation_id_value IS NULL
    OR operation_id_value IS NULL
  THEN
    RAISE EXCEPTION 'organization setup delivery authority is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT lower(btrim(candidate.target_email)) INTO normalized_email
  FROM organization_membership_invitations candidate
  WHERE candidate.account_id = account_id_value AND candidate.id = invitation_id_value;
  IF normalized_email IS NULL THEN
    RAISE EXCEPTION 'organization invitation is unavailable' USING ERRCODE = 'P0002';
  END IF;
  PERFORM pg_advisory_xact_lock(
    hashtextextended('organization-invitation-email:' || normalized_email, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('organization-membership:' || account_id_value::text, 0)
  );
  PERFORM 1 FROM managed_accounts account
  WHERE account.id = account_id_value FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.subject_id = actor_subject FOR UPDATE;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO invitation FROM organization_membership_invitations candidate
  WHERE candidate.account_id = account_id_value AND candidate.id = invitation_id_value
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization invitation is unavailable' USING ERRCODE = 'P0002';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'workspaceId', workspace.id,
    'workspaceName', workspace.name,
    'role', 'member'
  ) ORDER BY lower(workspace.name), workspace.id), '[]'::jsonb)
  INTO workspace_snapshot
  FROM unnest(invitation.initial_workspace_ids) requested(workspace_id)
  JOIN workspaces workspace
    ON workspace.account_id = account_id_value AND workspace.id = requested.workspace_id
  WHERE NOT EXISTS (
    SELECT 1 FROM organization_memberships personal_owner
    WHERE personal_owner.account_id = account_id_value
      AND personal_owner.personal_workspace_id = workspace.id
  );
  IF jsonb_array_length(workspace_snapshot) <> cardinality(invitation.initial_workspace_ids) THEN
    RAISE EXCEPTION 'organization invitation workspace snapshot is invalid'
      USING ERRCODE = '55000';
  END IF;

  SELECT * INTO delivery FROM organization_user_setup_deliveries candidate
  WHERE candidate.account_id = account_id_value
    AND candidate.invitation_id = invitation_id_value FOR UPDATE;
  IF NOT FOUND THEN
    -- An authorized retry can recover a crash after the invitation commit but
    -- before this journal was created. Resolve the immutable invite receipt
    -- server-side; a supplied operation id must still match it exactly.
    SELECT receipt.operation_id INTO verified_invitation_operation_id
      FROM organization_membership_operation_receipts receipt
      WHERE receipt.account_id = account_id_value
        AND receipt.action = 'invite'
        AND receipt.result ->> 'id' = invitation_id_value::text
        AND (
          invitation_operation_id_value IS NULL
          OR receipt.operation_id = invitation_operation_id_value
        )
      LIMIT 1;
    IF verified_invitation_operation_id IS NULL THEN
      RAISE EXCEPTION 'organization invitation operation is unavailable'
        USING ERRCODE = '42501';
    END IF;
    invitation_operation_id_value := verified_invitation_operation_id;
    delivery_id_value := gen_random_uuid();
    INSERT INTO organization_user_setup_deliveries (
      id, account_id, invitation_id, invitation_operation_id,
      created_by_membership_id, provider_key, recipient_email, recipient_name,
      organization_name, organization_role, shared_workspace_access
    ) SELECT
      delivery_id_value, account_id_value, invitation.id, invitation_operation_id_value,
      invitation.created_by_membership_id,
      'opengeni-organization-setup-v1-' || delivery_id_value::text,
      normalized_email, invitation.target_name, account.name, invitation.role,
      workspace_snapshot
    FROM managed_accounts account WHERE account.id = account_id_value
    RETURNING * INTO delivery;
  ELSIF invitation_operation_id_value IS NOT NULL
    AND delivery.invitation_operation_id IS DISTINCT FROM invitation_operation_id_value
  THEN
    RAISE EXCEPTION 'organization setup delivery identity changed' USING ERRCODE = '23505';
  END IF;

  -- Reconcile an expired lease before returning a terminal invitation. An
  -- invitation can expire or be accepted after a worker has claimed it; once
  -- that lease expires, leaving the attempt open would permanently retain a
  -- live-looking claim that no administrator can safely recover.
  IF delivery.claim_holder_id IS NOT NULL AND delivery.claim_expires_at <= now_value THEN
    UPDATE organization_user_setup_delivery_attempts SET
      result = CASE WHEN provider_started_at IS NULL THEN 'failed' ELSE 'outcome_unknown' END,
      error_class = CASE
        WHEN provider_started_at IS NULL THEN 'claim_expired_before_provider'
        ELSE 'provider_started_claim_expired'
      END,
      settled_at = now_value
    WHERE delivery_id = delivery.id AND claim_holder_id = delivery.claim_holder_id
      AND result IS NULL;
    UPDATE organization_user_setup_deliveries SET
      state = CASE
        WHEN provider_started_at IS NULL AND unresolved_provider_outcome_at IS NULL
        THEN 'failed'
        ELSE 'outcome_unknown'
      END,
      failed_at = CASE
        WHEN provider_started_at IS NULL AND unresolved_provider_outcome_at IS NULL
        THEN now_value
        ELSE NULL
      END,
      outcome_unknown_at = CASE
        WHEN provider_started_at IS NOT NULL OR unresolved_provider_outcome_at IS NOT NULL
        THEN coalesce(unresolved_provider_outcome_at, now_value)
        ELSE NULL
      END,
      unresolved_provider_outcome_at = CASE
        WHEN provider_started_at IS NOT NULL
        THEN coalesce(unresolved_provider_outcome_at, now_value)
        ELSE unresolved_provider_outcome_at
      END,
      error_class = CASE
        WHEN provider_started_at IS NULL AND unresolved_provider_outcome_at IS NULL
        THEN 'claim_expired_before_provider'
        WHEN provider_started_at IS NULL THEN 'prior_provider_outcome_unresolved'
        ELSE 'provider_started_claim_expired'
      END,
      claim_holder_id = NULL, claim_expires_at = NULL,
      revision = revision + 1, updated_at = now_value
    WHERE id = delivery.id RETURNING * INTO delivery;
  END IF;

  IF invitation.status <> 'pending' OR invitation.expires_at <= now_value THEN
    IF invitation.status = 'revoked' AND delivery.state <> 'revoked' THEN
      UPDATE organization_user_setup_deliveries SET
        state = 'revoked', revision = revision + 1, revoked_at = now_value,
        claim_holder_id = NULL, claim_expires_at = NULL,
        unresolved_provider_outcome_at = NULL,
        error_class = NULL, updated_at = now_value
      WHERE id = delivery.id RETURNING * INTO delivery;
    END IF;
    RETURN jsonb_build_object(
      'claimed', false,
      'delivery', opengeni_private.organization_user_setup_delivery_json(delivery)
    );
  END IF;
  IF delivery.state IN ('sent', 'revoked') THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'delivery', opengeni_private.organization_user_setup_delivery_json(delivery)
    );
  END IF;

  SELECT * INTO attempt FROM organization_user_setup_delivery_attempts candidate
  WHERE candidate.delivery_id = delivery.id AND candidate.operation_id = operation_id_value;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'delivery', opengeni_private.organization_user_setup_delivery_json(delivery),
      'attemptId', attempt.id,
      'claimHolderId', attempt.claim_holder_id,
      'invitationId', delivery.invitation_id,
      'providerKey', delivery.provider_key,
      'recipientEmail', delivery.recipient_email,
      'recipientName', delivery.recipient_name,
      'organizationName', delivery.organization_name,
      'organizationRole', delivery.organization_role,
      'sharedWorkspaceAccess', delivery.shared_workspace_access,
      'expiresAt', invitation.expires_at
    );
  END IF;

  IF delivery.unresolved_provider_outcome_at IS NOT NULL
    AND (
      delivery.provider_retry_safe_until IS NULL
      OR delivery.provider_retry_safe_until <= now_value
    )
  THEN
    RAISE EXCEPTION 'organization setup delivery requires provider reconciliation'
      USING ERRCODE = '55000';
  END IF;

  IF delivery.claim_holder_id IS NOT NULL THEN
    RAISE EXCEPTION 'organization setup delivery is already claimed' USING ERRCODE = '55000';
  END IF;

  INSERT INTO organization_user_setup_delivery_attempts (
    account_id, delivery_id, operation_id, attempt_number,
    claim_holder_id, claim_expires_at
  ) VALUES (
    account_id_value, delivery.id, operation_id_value, delivery.attempt_count + 1,
    gen_random_uuid(), now_value + interval '2 minutes'
  ) RETURNING * INTO attempt;
  UPDATE organization_user_setup_deliveries SET
    state = 'pending', revision = revision + 1,
    claim_holder_id = attempt.claim_holder_id,
    claim_expires_at = attempt.claim_expires_at,
    attempt_count = attempt.attempt_number,
    provider_started_at = NULL, error_class = NULL, provider_message_id = NULL,
    sent_at = NULL, failed_at = NULL, outcome_unknown_at = NULL, revoked_at = NULL,
    updated_at = now_value
  WHERE id = delivery.id RETURNING * INTO delivery;
  RETURN jsonb_build_object(
    'claimed', true,
    'delivery', opengeni_private.organization_user_setup_delivery_json(delivery),
    'attemptId', attempt.id,
    'claimHolderId', attempt.claim_holder_id,
    'invitationId', delivery.invitation_id,
    'providerKey', delivery.provider_key,
    'recipientEmail', delivery.recipient_email,
    'recipientName', delivery.recipient_name,
    'organizationName', delivery.organization_name,
    'organizationRole', delivery.organization_role,
    'sharedWorkspaceAccess', delivery.shared_workspace_access,
    'expiresAt', invitation.expires_at
  );
END
$$;

COMMENT ON FUNCTION opengeni_private.claim_organization_user_setup_delivery_unfenced_0401(p_command jsonb) IS 'Private 0351 claim implementation used only by the 0401-aware v2 capability.';

CREATE FUNCTION opengeni_private.claim_organization_webhook_deliveries_v1(p_claim_id uuid, p_limit integer, p_claim_seconds integer) RETURNS TABLE(delivery_id uuid, account_id uuid, workspace_id uuid, webhook_id uuid, event_id uuid, event_type text, payload jsonb, attempts integer, url text, secret_encrypted text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF p_claim_id IS NULL THEN RAISE EXCEPTION 'webhook delivery claim id is required' USING ERRCODE = '22023'; END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  RETURN QUERY WITH candidates AS MATERIALIZED (
    SELECT delivery.id FROM organization_webhook_deliveries delivery
    JOIN organization_webhooks webhook ON webhook.account_id = delivery.account_id AND webhook.id = delivery.webhook_id
    WHERE delivery.delivered_at IS NULL AND delivery.failed_at IS NULL AND delivery.next_attempt_at <= now()
      AND (delivery.claim_until IS NULL OR delivery.claim_until < now()) AND webhook.enabled
      AND NOT EXISTS (SELECT 1 FROM organization_memberships membership
        WHERE membership.account_id = delivery.account_id AND membership.personal_workspace_id = delivery.workspace_id)
    ORDER BY delivery.next_attempt_at, delivery.id FOR UPDATE OF delivery SKIP LOCKED
    LIMIT greatest(1, least(coalesce(p_limit, 32), 100))
  ), claimed AS (
    UPDATE organization_webhook_deliveries delivery SET claim_id = p_claim_id,
      claim_until = now() + make_interval(secs => greatest(5, least(coalesce(p_claim_seconds, 60), 300))),
      attempts = delivery.attempts + 1 FROM candidates WHERE delivery.id = candidates.id RETURNING delivery.*
  )
  SELECT claimed.id, claimed.account_id, claimed.workspace_id, claimed.webhook_id, claimed.event_id,
    claimed.event_type, claimed.payload, claimed.attempts, webhook.url, webhook.secret_encrypted
  FROM claimed JOIN organization_webhooks webhook ON webhook.account_id = claimed.account_id AND webhook.id = claimed.webhook_id
  ORDER BY claimed.next_attempt_at, claimed.id;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
  RAISE;
END $$;

CREATE FUNCTION opengeni_private.claim_retained_screenshot_maintenance(p_pending_grace_ms bigint, p_claim_timeout_ms bigint, p_limit integer) RETURNS TABLE(action text, claim_id uuid, artifact_id uuid, account_id uuid, workspace_id uuid, session_id uuid, object_key text, media_type text, size_bytes bigint, sha256 text, width integer, height integer, retention_expires_at timestamp with time zone, cleanup_reason text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      WITH candidates AS (
        SELECT
          A.artifact_id,
          gen_random_uuid() AS claim_id,
          CASE
            WHEN A.status IN ('pending', 'reconciling') THEN 'reconcile'
            ELSE 'delete'
          END AS action,
          CASE
            WHEN A.status = 'ready' THEN 'expired'
            WHEN A.status IN ('cleanup_queued', 'cleanup_pending')
              THEN coalesce(A.cleanup_reason, 'orphaned')
            ELSE NULL
          END AS cleanup_reason
        FROM {{schema}}.retained_screenshot_artifacts A
        WHERE
          (A.status = 'ready' AND A.retention_expires_at <= clock_timestamp())
          OR A.status = 'cleanup_queued'
          OR (
            A.status = 'pending'
            AND A.updated_at <= clock_timestamp() - (
              greatest(p_pending_grace_ms, 0)::double precision * interval '1 millisecond'
            )
          )
          OR (
            A.status IN ('reconciling', 'cleanup_pending')
            AND A.maintenance_claimed_at <= clock_timestamp() - (
              greatest(p_claim_timeout_ms, 0)::double precision * interval '1 millisecond'
            )
          )
        ORDER BY A.maintenance_claimed_at NULLS FIRST, A.retention_expires_at, A.artifact_id
        LIMIT least(greatest(p_limit, 0), 1000)
        FOR UPDATE SKIP LOCKED
      ), claimed AS (
        UPDATE {{schema}}.retained_screenshot_artifacts A
        SET
          status = CASE WHEN C.action = 'reconcile' THEN 'reconciling' ELSE 'cleanup_pending' END,
          cleanup_reason = C.cleanup_reason,
          maintenance_claim_id = C.claim_id,
          maintenance_claimed_at = clock_timestamp(),
          updated_at = clock_timestamp()
        FROM candidates C
        WHERE A.artifact_id = C.artifact_id
        RETURNING A.*, C.action, C.claim_id
      )
      SELECT C.action, C.claim_id, C.artifact_id, C.account_id, C.workspace_id, C.session_id,
        F.object_key, C.media_type, C.size_bytes, C.sha256, C.width, C.height,
        C.retention_expires_at, C.cleanup_reason
      FROM claimed C
      JOIN {{schema}}.files F
        ON F.workspace_id = C.workspace_id
       AND F.id = C.artifact_id;
    $$;

CREATE FUNCTION opengeni_private.claim_sandbox_checkpoint_artifacts(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint) RETURNS TABLE(id uuid, provider_backend text, provider_binding_key text, provider_binding jsonb, object_kind text, object_id text, delete_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'checkpoint_gc');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_claim_checkpoint_gc_inner($1, $2, $3);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.claim_session_archive_object_deletions(p_claim_timeout_seconds integer, p_limit integer) RETURNS TABLE(object_key text, workspace_id uuid, session_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH candidates AS (
    SELECT D.object_key FROM opengeni_private.session_archive_object_deletions D
    WHERE D.claimed_at IS NULL
      OR D.claimed_at < clock_timestamp() - make_interval(secs => greatest(p_claim_timeout_seconds, 60))
    ORDER BY D.enqueued_at, D.object_key
    LIMIT least(greatest(p_limit, 0), 1000)
    FOR UPDATE SKIP LOCKED
  )
  UPDATE opengeni_private.session_archive_object_deletions D
  SET claimed_at = clock_timestamp(), attempts = D.attempts + 1
  FROM candidates C WHERE D.object_key = C.object_key
  RETURNING D.object_key, D.workspace_id, D.session_id;
$$;

CREATE FUNCTION opengeni_private.claim_session_system_update_outbox(p_limit integer) RETURNS TABLE(id uuid, account_id uuid, workspace_id uuid, source_session_id uuid, target_session_id uuid, dedupe_key text, kind text, classification text, source_id text, summary text, summary_codec_version integer, payload jsonb, payload_codec_version integer, lineage jsonb, mcp_account_bindings jsonb, personal_connection_delegations jsonb, codex_provider_account_authority_snapshot jsonb, xai_provider_account_authority_snapshot jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}'
    AS $$
BEGIN
  RETURN QUERY
    WITH claimed AS (
      SELECT o.id, o.created_at FROM session_system_update_outbox o
      WHERE o.status = 'pending'
      ORDER BY o.created_at, o.id
      FOR UPDATE SKIP LOCKED
      LIMIT greatest(1, least(coalesce(p_limit, 100), 100))
    ), bumped AS (
      UPDATE session_system_update_outbox o
      SET attempts = o.attempts + 1, updated_at = now()
      FROM claimed c WHERE o.id = c.id
      RETURNING o.id, o.account_id, o.workspace_id, o.source_session_id, o.target_session_id, o.dedupe_key, o.kind, o.classification, o.source_id, o.summary, o.summary_codec_version, o.payload, o.payload_codec_version, o.lineage, o.mcp_account_bindings, o.personal_connection_delegations, o.codex_provider_account_authority_snapshot, o.xai_provider_account_authority_snapshot
    )
    SELECT b.* FROM bumped b
    JOIN claimed c ON c.id = b.id
    ORDER BY c.created_at, c.id;
END
$$;

