CREATE TABLE slack_app_home_refreshes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    slack_team_id text NOT NULL,
    slack_user_id text NOT NULL,
    provider_event_id text NOT NULL,
    provider_view_hash text,
    desired_revision integer DEFAULT 1 NOT NULL,
    processed_revision integer DEFAULT 0 NOT NULL,
    claim_holder_id uuid,
    claim_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    retry_at timestamp with time zone,
    last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slack_app_home_refreshes_bounds_check CHECK ((((octet_length(slack_team_id) >= 1) AND (octet_length(slack_team_id) <= 64)) AND ((octet_length(slack_user_id) >= 1) AND (octet_length(slack_user_id) <= 64)) AND ((octet_length(provider_event_id) >= 1) AND (octet_length(provider_event_id) <= 256)) AND ((provider_view_hash IS NULL) OR ((octet_length(provider_view_hash) >= 1) AND (octet_length(provider_view_hash) <= 256))) AND ((last_error_code IS NULL) OR ((octet_length(last_error_code) >= 1) AND (octet_length(last_error_code) <= 128))))),
    CONSTRAINT slack_app_home_refreshes_claim_check CHECK (((claim_holder_id IS NULL) = (claim_expires_at IS NULL))),
    CONSTRAINT slack_app_home_refreshes_revisions_check CHECK (((desired_revision > 0) AND (processed_revision >= 0) AND (processed_revision <= desired_revision) AND (attempt_count >= 0)))
);

ALTER TABLE ONLY slack_app_home_refreshes FORCE ROW LEVEL SECURITY;

CREATE FUNCTION opengeni_private.claim_slack_app_home_refresh(p_holder uuid, p_lease_ms integer) RETURNS SETOF slack_app_home_refreshes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_lease_ms < 1000 OR p_lease_ms > 300000 THEN
        RAISE EXCEPTION 'invalid Slack App Home claim lease';
      END IF;
      RETURN QUERY
      WITH candidate AS (
        SELECT refresh.id
        FROM {{schema}}.slack_app_home_refreshes refresh
        WHERE refresh.processed_revision < refresh.desired_revision
          AND (refresh.retry_at IS NULL OR refresh.retry_at <= now())
          AND (refresh.claim_holder_id IS NULL OR refresh.claim_expires_at <= now())
        ORDER BY refresh.retry_at NULLS FIRST, refresh.updated_at, refresh.id
        FOR UPDATE SKIP LOCKED
        LIMIT 1
      )
      UPDATE {{schema}}.slack_app_home_refreshes refresh
      SET claim_holder_id = p_holder,
          claim_expires_at = now() + make_interval(secs => p_lease_ms::double precision / 1000),
          retry_at = NULL,
          attempt_count = refresh.attempt_count + 1,
          updated_at = now()
      FROM candidate
      WHERE refresh.id = candidate.id
      RETURNING refresh.*;
    END
    $$;

CREATE TABLE slack_interactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    slack_team_id text NOT NULL,
    slack_channel_id text NOT NULL,
    slack_thread_ts text NOT NULL,
    route_key text NOT NULL,
    triggering_provider_event_id text NOT NULL,
    owning_subject_id text NOT NULL,
    visibility text NOT NULL,
    session_reservation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid,
    last_delivered_session_event_sequence integer DEFAULT 0 NOT NULL,
    delivery_claim_holder_id uuid,
    delivery_claim_expires_at timestamp with time zone,
    ack_slack_message_ts text,
    progress_count integer DEFAULT 0 NOT NULL,
    terminal_delivery_state text DEFAULT 'open'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    delivery_attempt_count integer DEFAULT 0 NOT NULL,
    delivery_retry_at timestamp with time zone,
    delivery_last_error_code text,
    initiating_slack_user_id text,
    first_task_hint boolean,
    routed_workspace_label text,
    session_defaults_line text,
    start_message_line text,
    CONSTRAINT slack_interactions_bounds_check CHECK ((((octet_length(slack_team_id) >= 1) AND (octet_length(slack_team_id) <= 64)) AND ((octet_length(slack_channel_id) >= 1) AND (octet_length(slack_channel_id) <= 64)) AND ((octet_length(slack_thread_ts) >= 1) AND (octet_length(slack_thread_ts) <= 64)) AND ((octet_length(route_key) >= 1) AND (octet_length(route_key) <= 256)) AND ((octet_length(triggering_provider_event_id) >= 1) AND (octet_length(triggering_provider_event_id) <= 256)) AND ((octet_length(owning_subject_id) >= 1) AND (octet_length(owning_subject_id) <= 1024)) AND ((ack_slack_message_ts IS NULL) OR ((octet_length(ack_slack_message_ts) >= 1) AND (octet_length(ack_slack_message_ts) <= 64))) AND (last_delivered_session_event_sequence >= 0) AND ((progress_count >= 0) AND (progress_count <= 3)))),
    CONSTRAINT slack_interactions_delivery_attempt_check CHECK ((delivery_attempt_count >= 0)),
    CONSTRAINT slack_interactions_delivery_claim_check CHECK (((delivery_claim_holder_id IS NULL) = (delivery_claim_expires_at IS NULL))),
    CONSTRAINT slack_interactions_delivery_error_check CHECK (((delivery_last_error_code IS NULL) OR ((octet_length(delivery_last_error_code) >= 1) AND (octet_length(delivery_last_error_code) <= 128)))),
    CONSTRAINT slack_interactions_initiating_user_check CHECK (((initiating_slack_user_id IS NULL) OR ((octet_length(initiating_slack_user_id) >= 1) AND (octet_length(initiating_slack_user_id) <= 64)))),
    CONSTRAINT slack_interactions_routed_label_check CHECK (((routed_workspace_label IS NULL) OR ((octet_length(routed_workspace_label) >= 1) AND (octet_length(routed_workspace_label) <= 128)))),
    CONSTRAINT slack_interactions_session_binding_check CHECK (((session_id IS NULL) OR (session_id = session_reservation_id))),
    CONSTRAINT slack_interactions_session_defaults_line_check CHECK (((session_defaults_line IS NULL) OR ((octet_length(session_defaults_line) >= 1) AND (octet_length(session_defaults_line) <= 1024)))),
    CONSTRAINT slack_interactions_start_message_line_check CHECK (((start_message_line IS NULL) OR ((octet_length(start_message_line) >= 1) AND (octet_length(start_message_line) <= 2048)))),
    CONSTRAINT slack_interactions_terminal_check CHECK ((terminal_delivery_state = ANY (ARRAY['open'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'blocked'::text]))),
    CONSTRAINT slack_interactions_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'workspace'::text])))
);

ALTER TABLE ONLY slack_interactions FORCE ROW LEVEL SECURITY;

CREATE FUNCTION opengeni_private.claim_slack_interaction_delivery(p_holder uuid, p_lease_ms integer) RETURNS SETOF slack_interactions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_lease_ms < 1000 OR p_lease_ms > 300000 THEN
        RAISE EXCEPTION 'invalid Slack delivery claim lease';
      END IF;
      RETURN QUERY
      WITH candidate AS (
        SELECT I.id
        FROM {{schema}}.slack_interactions I
        WHERE I.session_id IS NOT NULL
          AND I.terminal_delivery_state = 'open'
          AND (I.delivery_retry_at IS NULL OR I.delivery_retry_at <= now())
          AND (I.delivery_claim_holder_id IS NULL OR I.delivery_claim_expires_at <= now())
          AND NOT (
            I.visibility = 'private'
            AND I.triggering_provider_event_id LIKE 'shortcut:%'
            AND I.ack_slack_message_ts IS NULL
          )
          AND EXISTS (
            SELECT 1
            FROM {{schema}}.session_events E
            WHERE E.workspace_id = I.workspace_id
              AND E.session_id = I.session_id
              AND E.sequence > I.last_delivered_session_event_sequence
              AND E.type IN (
                'agent.message.completed',
                'session.humanInput.requested',
                'turn.completed',
                'turn.failed',
                'turn.cancelled',
                'session.status.changed',
                'system.update.pending',
                'goal.paused'
              )
          )
        ORDER BY I.delivery_retry_at NULLS FIRST, I.updated_at, I.id
        FOR UPDATE SKIP LOCKED
        LIMIT 1
      )
      UPDATE {{schema}}.slack_interactions I
      SET delivery_claim_holder_id = p_holder,
          delivery_claim_expires_at = now() + make_interval(secs => p_lease_ms::double precision / 1000),
          delivery_attempt_count = I.delivery_attempt_count + 1,
          updated_at = now()
      FROM candidate C
      WHERE I.id = C.id
      RETURNING I.*;
    END
    $$;

CREATE TABLE slack_interaction_inbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    provider_event_id text NOT NULL,
    provider_message_id text NOT NULL,
    slack_team_id text NOT NULL,
    slack_user_id text NOT NULL,
    slack_channel_id text NOT NULL,
    slack_message_ts text NOT NULL,
    slack_thread_ts text,
    trigger_kind text NOT NULL,
    text text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    claim_holder_id uuid,
    claim_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error_code text,
    processed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    retry_at timestamp with time zone,
    reaction_context_checkpoint jsonb,
    has_files boolean DEFAULT false NOT NULL,
    route_state text,
    target_account_id uuid,
    target_workspace_id uuid,
    route_prompt_id uuid,
    route_prompt_expires_at timestamp with time zone,
    CONSTRAINT slack_interaction_inbox_bounds_check CHECK ((((octet_length(provider_event_id) >= 1) AND (octet_length(provider_event_id) <= 256)) AND ((octet_length(provider_message_id) >= 1) AND (octet_length(provider_message_id) <= 256)) AND ((octet_length(slack_team_id) >= 1) AND (octet_length(slack_team_id) <= 64)) AND ((octet_length(slack_user_id) >= 1) AND (octet_length(slack_user_id) <= 64)) AND ((octet_length(slack_channel_id) >= 1) AND (octet_length(slack_channel_id) <= 64)) AND ((octet_length(slack_message_ts) >= 1) AND (octet_length(slack_message_ts) <= 64)) AND ((slack_thread_ts IS NULL) OR ((octet_length(slack_thread_ts) >= 1) AND (octet_length(slack_thread_ts) <= 64))) AND ((octet_length(text) >= 1) AND (octet_length(text) <= 12000)) AND ((last_error_code IS NULL) OR ((octet_length(last_error_code) >= 1) AND (octet_length(last_error_code) <= 128))))),
    CONSTRAINT slack_interaction_inbox_claim_check CHECK (((claim_holder_id IS NULL) = (claim_expires_at IS NULL))),
    CONSTRAINT slack_interaction_inbox_completion_check CHECK (((status = ANY (ARRAY['processed'::text, 'failed'::text])) = (processed_at IS NOT NULL))),
    CONSTRAINT slack_interaction_inbox_reaction_checkpoint_check CHECK (((reaction_context_checkpoint IS NULL) OR ((trigger_kind = 'reaction'::text) AND (status = ANY (ARRAY['pending'::text, 'processing'::text])) AND (jsonb_typeof(reaction_context_checkpoint) = 'object'::text) AND (octet_length((reaction_context_checkpoint)::text) <= 131072)))),
    CONSTRAINT slack_interaction_inbox_route_check CHECK (((route_state IS NULL) OR ((route_state = ANY (ARRAY['resolved'::text, 'awaiting_choice'::text, 'denied'::text])) AND ((route_state = 'resolved'::text) = (target_workspace_id IS NOT NULL)) AND ((target_account_id IS NULL) = (target_workspace_id IS NULL)) AND ((target_account_id IS NULL) OR (target_account_id = account_id)) AND ((route_state = 'awaiting_choice'::text) = (route_prompt_id IS NOT NULL))))),
    CONSTRAINT slack_interaction_inbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'processed'::text, 'failed'::text]))),
    CONSTRAINT slack_interaction_inbox_trigger_check CHECK ((trigger_kind = ANY (ARRAY['app_mention'::text, 'dm'::text, 'reaction'::text, 'slash_command'::text, 'message_shortcut'::text, 'thread_reply'::text, 'block_action'::text])))
);

ALTER TABLE ONLY slack_interaction_inbox FORCE ROW LEVEL SECURITY;

CREATE FUNCTION opengeni_private.claim_slack_interaction_inbox(p_holder uuid, p_lease_ms integer) RETURNS SETOF slack_interaction_inbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_lease_ms < 1000 OR p_lease_ms > 300000 THEN
        RAISE EXCEPTION 'invalid Slack inbox claim lease';
      END IF;
      RETURN QUERY
      WITH candidate AS (
        SELECT I.id
        FROM {{schema}}.slack_interaction_inbox I
        WHERE (
            I.status = 'pending'
            AND (I.retry_at IS NULL OR I.retry_at <= now())
          ) OR (
            I.status = 'processing'
            AND I.claim_expires_at <= now()
          )
        ORDER BY I.retry_at NULLS FIRST, I.created_at, I.id
        FOR UPDATE SKIP LOCKED
        LIMIT 1
      )
      UPDATE {{schema}}.slack_interaction_inbox I
      SET status = 'processing',
          claim_holder_id = p_holder,
          claim_expires_at = now() + make_interval(secs => p_lease_ms::double precision / 1000),
          retry_at = NULL,
          attempt_count = I.attempt_count + 1,
          updated_at = now()
      FROM candidate C
      WHERE I.id = C.id
      RETURNING I.*;
    END
    $$;

CREATE FUNCTION opengeni_private.claim_temporal_schedule_cleanups(p_claim_id uuid, p_limit integer, p_claim_seconds integer) RETURNS TABLE(id uuid, account_id uuid, workspace_id uuid, temporal_schedule_id text, scheduled_task_id uuid, connector_cleanup_subject_id text, connector_cleanup_snapshot jsonb, connector_cleanup_completed_at timestamp with time zone, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'schedule_cleanup');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_schedule_cleanup_claim_inner($1, $2, $3);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.claim_terminal_retained_processes(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, process_id uuid, claim_id uuid, owner_state text, owner_attempt_outcome text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
      SELECT * FROM opengeni_private.claim_terminal_retained_processes(
        p_claim_id, p_limit, p_claim_ttl_ms, 1
      )
    $$;

CREATE FUNCTION opengeni_private.claim_terminal_retained_processes(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint, p_reconciler_version integer) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, process_id uuid, claim_id uuid, owner_state text, owner_attempt_outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      fenced_access_capability_id uuid;
    BEGIN
      IF p_reconciler_version IS NULL OR p_reconciler_version < 1 THEN
        RAISE EXCEPTION 'retained-process reconciler version is invalid'
          USING ERRCODE = '22023';
      END IF;
      IF p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'retained-process reconciliation limit must be between 1 and 100'
          USING ERRCODE = '22023';
      END IF;
      IF p_claim_ttl_ms < 0 OR p_claim_ttl_ms > 3600000 THEN
        RAISE EXCEPTION 'retained-process reconciliation claim TTL is invalid'
          USING ERRCODE = '22023';
      END IF;

      PERFORM acquire_due_retained_process_session_tenancy_fences();
      fenced_access_capability_id :=
        opengeni_private.open_session_tenancy_fenced_access(
          session_tenancy_fence_target_schema()
        );

      PERFORM pg_catalog.set_config('opengeni.sandbox_recovery_protocol_v2', '1', true);

      RETURN QUERY
      WITH candidate_window AS MATERIALIZED (
        SELECT process.id,
          process.workspace_id,
          process.parent_admission_id,
          process.owner_actor_kind,
          process.owner_turn_id,
          process.owner_attempt_id,
          process.reconcile_after AS due_at,
          process.started_at
        FROM {{schema}}.sandbox_retained_processes process
        WHERE process.state = 'active'
          AND process.reconcile_after <= pg_catalog.now()
          AND process.reconciler_version <= p_reconciler_version
        ORDER BY process.reconcile_after, process.started_at, process.id
        FOR UPDATE OF process SKIP LOCKED
        LIMIT p_limit
      ), classified AS MATERIALIZED (
        SELECT candidate.id,
          candidate.due_at,
          candidate.started_at,
          command.state AS command_state,
          command.id IS NOT NULL OR CASE
            WHEN candidate.owner_actor_kind = 'direct' THEN direct_owner.live IS NULL
            ELSE attempt.state = 'closed'
          END AS eligible,
          CASE
            WHEN command.state = 'stopping' THEN 'background_stopping'
            WHEN command.state = 'running' THEN 'background_running'
            WHEN candidate.owner_actor_kind = 'direct' THEN 'direct'
            ELSE COALESCE(turn_row.status, 'missing')
          END AS owner_state,
          attempt.outcome AS owner_attempt_outcome
        FROM candidate_window candidate
        LEFT JOIN {{schema}}.session_background_commands command
          ON command.retained_process_id = candidate.id
         AND command.state IN ('running', 'stopping')
        LEFT JOIN LATERAL (
          SELECT true AS live
          FROM {{schema}}.sandbox_workspace_mutation_admissions admission
          JOIN {{schema}}.sandbox_lease_holders holder
            ON holder.lease_id = admission.lease_id
           AND holder.account_id = admission.account_id
           AND holder.workspace_id = admission.workspace_id
           AND holder.kind = 'direct'
           AND holder.holder_id = admission.holder_id
           AND holder.subject_id = admission.session_id
          WHERE candidate.owner_actor_kind = 'direct'
            AND admission.id = candidate.parent_admission_id
            AND admission.actor_kind = 'direct'
          LIMIT 1
        ) direct_owner ON true
        LEFT JOIN LATERAL (
          SELECT source_turn.status
          FROM {{schema}}.session_turns source_turn
          WHERE source_turn.workspace_id = candidate.workspace_id
            AND source_turn.id = candidate.owner_turn_id
          LIMIT 1
        ) turn_row ON true
        LEFT JOIN LATERAL (
          SELECT source_attempt.state, source_attempt.outcome
          FROM {{schema}}.session_turn_attempts source_attempt
          WHERE source_attempt.workspace_id = candidate.workspace_id
            AND source_attempt.id = candidate.owner_attempt_id
          LIMIT 1
        ) attempt ON true
      ), inspected AS (
        UPDATE {{schema}}.sandbox_retained_processes process SET
          reconcile_after = CASE
            WHEN classified.eligible THEN pg_catalog.now()
              + pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0)
            ELSE pg_catalog.now() + interval '30 seconds'
          END,
          reconcile_claim_id = CASE WHEN classified.eligible THEN p_claim_id ELSE NULL END,
          reconcile_claimed_at = CASE
            WHEN classified.eligible THEN pg_catalog.now() ELSE NULL
          END,
          reconcile_attempts = process.reconcile_attempts
            + CASE WHEN classified.eligible THEN 1 ELSE 0 END,
          last_reconcile_outcome = CASE
            WHEN classified.eligible THEN 'claimed' ELSE 'owner_active'
          END
        FROM classified
        WHERE process.id = classified.id
          AND process.state = 'active'
        RETURNING process.account_id,
          process.workspace_id,
          process.session_id,
          process.id,
          process.reconcile_claim_id,
          classified.due_at,
          classified.started_at,
          classified.eligible,
          classified.owner_state,
          classified.owner_attempt_outcome
      )
      SELECT inspected.account_id,
        inspected.workspace_id,
        inspected.session_id,
        inspected.id,
        inspected.reconcile_claim_id,
        inspected.owner_state,
        inspected.owner_attempt_outcome
      FROM inspected
      WHERE inspected.eligible
      ORDER BY inspected.due_at, inspected.started_at, inspected.id;

      SET CONSTRAINTS {{schema}}.sandbox_retained_processes_identity_v2 IMMEDIATE;
      SET CONSTRAINTS {{schema}}.sandbox_retained_processes_identity_v2 DEFERRED;
      PERFORM opengeni_private.close_session_tenancy_fenced_access(
        fenced_access_capability_id
      );
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fenced_access(
        fenced_access_capability_id
      );
      RAISE;
    END;
    $$;

CREATE FUNCTION opengeni_private.claim_video_generation_operations(p_owner text, p_lease_seconds integer, p_limit integer) RETURNS TABLE(operation_id uuid, account_id uuid, workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'opengeni_private'
    AS $$
BEGIN
  IF p_owner IS NULL OR length(btrim(p_owner)) NOT BETWEEN 1 AND 256
    OR p_lease_seconds NOT BETWEEN 5 AND 600
    OR p_limit NOT BETWEEN 1 AND 100
  THEN
    RAISE EXCEPTION 'invalid video generation claim request';
  END IF;
  RETURN QUERY
  WITH candidates AS (
    SELECT operation.id
    FROM public.video_generation_operations AS operation
    WHERE (
        (
          operation.status IN ('accepted','submission_uncertain','provider_started','retaining')
          AND coalesce(operation.next_reconcile_at, operation.updated_at) <= clock_timestamp()
        )
        OR (
          operation.status IN (
            'completed','provider_failed','cancelled_before_submit','outcome_unknown','retention_failed'
          )
          AND (
            operation.terminal_update_state IN ('pending','leased')
            OR EXISTS (
              SELECT 1
              FROM public.video_generation_references AS reference
              WHERE reference.operation_id = operation.id
                AND reference.staging_object_key IS NOT NULL
                AND reference.cleaned_at IS NULL
                AND coalesce(reference.cleanup_after, operation.recovery_deadline_at)
                  <= clock_timestamp()
            )
          )
        )
      )
      AND (
        operation.reconcile_lease_expires_at IS NULL
        OR operation.reconcile_lease_expires_at <= clock_timestamp()
      )
    ORDER BY coalesce(operation.next_reconcile_at, operation.updated_at), operation.id
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  ), claimed AS (
    UPDATE public.video_generation_operations AS operation
    SET reconcile_lease_owner = p_owner,
        reconcile_lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
        reconcile_revision = operation.reconcile_revision + 1,
        updated_at = clock_timestamp()
    FROM candidates
    WHERE operation.id = candidates.id
    RETURNING operation.id, operation.account_id, operation.workspace_id
  )
  SELECT claimed.id, claimed.account_id, claimed.workspace_id FROM claimed;
END;
$$;

CREATE FUNCTION opengeni_private.claim_workspace_webhook_deliveries_v1(p_claim_id uuid, p_limit integer, p_claim_seconds integer) RETURNS TABLE(delivery_id uuid, account_id uuid, workspace_id uuid, webhook_id uuid, event_id uuid, event_type text, payload jsonb, attempts integer, url text, secret_encrypted text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF p_claim_id IS NULL THEN
    RAISE EXCEPTION 'webhook delivery claim id is required' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  WITH candidates AS MATERIALIZED (
    SELECT delivery.id
    FROM workspace_webhook_deliveries delivery
    JOIN workspace_webhooks webhook
      ON webhook.workspace_id = delivery.workspace_id
     AND webhook.id = delivery.webhook_id
    WHERE delivery.delivered_at IS NULL
      AND delivery.failed_at IS NULL
      AND delivery.next_attempt_at <= pg_catalog.now()
      AND (delivery.claim_until IS NULL OR delivery.claim_until < pg_catalog.now())
      AND webhook.enabled
    ORDER BY delivery.next_attempt_at, delivery.id
    FOR UPDATE OF delivery SKIP LOCKED
    LIMIT greatest(1, least(coalesce(p_limit, 32), 100))
  ),
  claimed AS (
    UPDATE workspace_webhook_deliveries delivery
    SET claim_id = p_claim_id,
        claim_until = pg_catalog.now() + pg_catalog.make_interval(
          secs => greatest(5, least(coalesce(p_claim_seconds, 60), 300))
        ),
        attempts = delivery.attempts + 1
    FROM candidates
    WHERE delivery.id = candidates.id
    RETURNING delivery.*
  )
  SELECT
    claimed.id,
    claimed.account_id,
    claimed.workspace_id,
    claimed.webhook_id,
    claimed.event_id,
    claimed.event_type,
    claimed.payload,
    claimed.attempts,
    webhook.url,
    webhook.secret_encrypted
  FROM claimed
  JOIN workspace_webhooks webhook
    ON webhook.workspace_id = claimed.workspace_id
   AND webhook.id = claimed.webhook_id
  ORDER BY claimed.next_attempt_at, claimed.id;
END
$$;

CREATE FUNCTION opengeni_private.classify_connected_command_ops(p_control_workspace_id uuid, p_enrollment_id uuid, p_connection_instance_id text, p_op_ids text[]) RETURNS TABLE(op_id text, account_id uuid, workspace_id uuid, session_id uuid, command_id uuid, state text, output_exit_seq text, output_consumed boolean, output_released boolean, output_unavailable boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT command.op_id, command.account_id, command.workspace_id,
          command.session_id, command.id, command.state::text, command.output_exit_seq,
          command.output_consumed_at IS NOT NULL,
          command.output_release_observed_at IS NOT NULL,
          command.output_unavailable_at IS NOT NULL
        FROM {{schema}}.session_background_commands command
        WHERE command.provider = 'connected_machine'
          AND command.control_workspace_id = p_control_workspace_id
          AND command.enrollment_id = p_enrollment_id
          AND command.connection_instance_id = p_connection_instance_id
          AND command.op_id = ANY(p_op_ids);
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.claude_subscription_pool_protocol_v1_active() RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT true $$;

CREATE FUNCTION opengeni_private.cleanup_expired_editable_artifact_live_tickets(p_limit integer, p_data_schema name DEFAULT "current_schema"()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
DECLARE removed integer;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
    RAISE EXCEPTION 'editable artifact live ticket cleanup limit is invalid'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_ticket_data_schema(
    p_data_schema
  );
  EXECUTE pg_catalog.format($query$
    WITH expired AS (
      SELECT ticket.token_digest
      FROM %I.editable_artifact_live_tickets ticket
      WHERE ticket.expires_at <= pg_catalog.clock_timestamp()
      ORDER BY ticket.expires_at, ticket.token_digest
      LIMIT $1
      FOR UPDATE SKIP LOCKED
    )
    DELETE FROM %I.editable_artifact_live_tickets ticket
    USING expired
    WHERE ticket.token_digest = expired.token_digest
  $query$, data_schema, data_schema) USING p_limit;
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;
$_$;

CREATE FUNCTION opengeni_private.clear_command_containment_reason() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  -- Runs after sandbox_clear_unobservable_command_drain (name order).
  IF NEW.unobservable_command_drain_ids IS NULL THEN
    NEW.command_containment_reason := NULL;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.clear_context_compaction_pending_attempt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.state <> 'closed' AND NEW.state = 'closed' THEN
    DELETE FROM opengeni_private.context_compaction_pending_observations pending
    WHERE pending.workspace_id = NEW.workspace_id
      AND pending.attempt_id = NEW.id;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.clear_context_compaction_pending_turn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.active_attempt_id IS NOT NULL
    AND OLD.active_attempt_id IS DISTINCT FROM NEW.active_attempt_id
  THEN
    DELETE FROM opengeni_private.context_compaction_pending_observations pending
    WHERE pending.workspace_id = NEW.workspace_id
      AND pending.attempt_id = OLD.active_attempt_id;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.clear_deadline_forced_admissions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.lease_epoch IS DISTINCT FROM OLD.lease_epoch
    OR NEW.instance_id IS DISTINCT FROM OLD.instance_id
    OR NEW.liveness = 'cold'
    OR (NEW.liveness = 'warm' AND OLD.liveness IS DISTINCT FROM 'warm') THEN
    NEW.deadline_forced_admission_ids := NULL;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.clear_subscription_settings_locked_overrides() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  added text[];
BEGIN
  IF NEW.workspace_id IS NOT NULL THEN
    RETURN NULL;
  END IF;
  added := ARRAY(
    SELECT setting FROM pg_catalog.unnest(NEW.locked_settings) setting
    EXCEPT
    SELECT setting FROM pg_catalog.unnest(
      CASE WHEN TG_OP = 'UPDATE' THEN OLD.locked_settings ELSE '{}'::text[] END) setting
  );
  IF pg_catalog.cardinality(added) = 0 THEN
    RETURN NULL;
  END IF;
  -- READ UNCOMMITTED runs as READ COMMITTED in PostgreSQL.
  IF pg_catalog.current_setting('transaction_isolation') NOT IN ('read committed', 'read uncommitted') THEN
    RAISE EXCEPTION 'subscription settings locks are written at READ COMMITTED only'
      USING ERRCODE = '0A000', DETAIL = 'subscription_settings_requires_read_committed';
  END IF;
  -- Try, never wait: an upsert holding the shared lock may be waiting for a
  -- workspace row this transaction holds (see 4. above).
  IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
      'subscription-settings-locks:' || NEW.account_id::text, 0)) THEN
    RAISE EXCEPTION 'a workspace settings write is in flight; retry the lock change'
      USING ERRCODE = '55P03', DETAIL = 'subscription_settings_lock_busy';
  END IF;
  -- Holding the exclusive lock, never wait for a row either: a writer that
  -- locked a row it is about to widen waits for this lock (see 4. above).
  BEGIN
    PERFORM 1 FROM subscription_settings workspace_row
    WHERE workspace_row.account_id = NEW.account_id
      AND workspace_row.workspace_id IS NOT NULL
      AND (('rotation' = ANY(added) AND workspace_row.rotation IS NOT NULL)
        OR ('providers' = ANY(added) AND workspace_row.providers IS NOT NULL)
        OR ('fallbackOrder' = ANY(added) AND workspace_row.fallback_order IS NOT NULL)
        OR ('crossProviderFailover' = ANY(added) AND workspace_row.cross_provider_failover IS NOT NULL)
        OR ('personalConnectionsAllowed' = ANY(added)
          AND workspace_row.personal_connections_allowed IS NOT NULL)
        OR ('personalFallbackAllowed' = ANY(added)
          AND workspace_row.personal_fallback_allowed IS NOT NULL))
    FOR UPDATE NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'a workspace settings write is in flight; retry the lock change'
      USING ERRCODE = '55P03', DETAIL = 'subscription_settings_lock_busy';
  END;
  UPDATE subscription_settings workspace_row SET
    rotation = CASE WHEN 'rotation' = ANY(added) THEN NULL ELSE workspace_row.rotation END,
    providers = CASE WHEN 'providers' = ANY(added) THEN NULL ELSE workspace_row.providers END,
    fallback_order = CASE WHEN 'fallbackOrder' = ANY(added) THEN NULL ELSE workspace_row.fallback_order END,
    cross_provider_failover = CASE WHEN 'crossProviderFailover' = ANY(added)
      THEN NULL ELSE workspace_row.cross_provider_failover END,
    personal_connections_allowed = CASE WHEN 'personalConnectionsAllowed' = ANY(added)
      THEN NULL ELSE workspace_row.personal_connections_allowed END,
    personal_fallback_allowed = CASE WHEN 'personalFallbackAllowed' = ANY(added)
      THEN NULL ELSE workspace_row.personal_fallback_allowed END,
    version = workspace_row.version + 1,
    updated_by_subject_id = NEW.updated_by_subject_id,
    updated_at = pg_catalog.clock_timestamp()
  WHERE workspace_row.account_id = NEW.account_id
    AND workspace_row.workspace_id IS NOT NULL
    AND (('rotation' = ANY(added) AND workspace_row.rotation IS NOT NULL)
      OR ('providers' = ANY(added) AND workspace_row.providers IS NOT NULL)
      OR ('fallbackOrder' = ANY(added) AND workspace_row.fallback_order IS NOT NULL)
      OR ('crossProviderFailover' = ANY(added) AND workspace_row.cross_provider_failover IS NOT NULL)
      OR ('personalConnectionsAllowed' = ANY(added)
        AND workspace_row.personal_connections_allowed IS NOT NULL)
      OR ('personalFallbackAllowed' = ANY(added)
        AND workspace_row.personal_fallback_allowed IS NOT NULL));
  RETURN NULL;
END
$$;

CREATE FUNCTION opengeni_private.clear_unobservable_command_drain() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.lease_epoch IS DISTINCT FROM OLD.lease_epoch
    OR NEW.instance_id IS DISTINCT FROM OLD.instance_id
    OR NEW.liveness = 'cold' THEN
    NEW.unobservable_command_drain_ids := NULL;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.clear_untracked_writer_since() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  NEW.untracked_writer_since := NULL;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.clear_workspace_codex_session_affinity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
BEGIN
  UPDATE sessions
  SET codex_pinned_credential_id = NULL,
      codex_pin_source = NULL,
      codex_last_credential_id = NULL
  WHERE account_id = NEW.account_id AND workspace_id = NEW.workspace_id
    AND (codex_pinned_credential_id IS NOT NULL OR codex_last_credential_id IS NOT NULL);
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.close_inbox_items_v1(p_session_id uuid, p_kinds text[], p_source_key text, p_status text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE opengeni_private.inbox_items item
  SET status = p_status, resolved_at = now(), updated_at = now()
  WHERE item.session_id = p_session_id
    AND item.kind = ANY (p_kinds)
    AND (p_source_key IS NULL OR item.source_key = p_source_key)
    AND item.status IN ('open', 'dismissed');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END
$$;

CREATE FUNCTION opengeni_private.close_session_tenancy_fence_inventory(p_capability_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  DELETE FROM opengeni_private.session_tenancy_fence_inventory_capabilities
  WHERE capability_id = p_capability_id
    AND backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
$$;

CREATE FUNCTION opengeni_private.close_session_tenancy_fenced_access(p_capability_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  DELETE FROM opengeni_private.session_tenancy_fenced_access_capabilities
  WHERE capability_id = p_capability_id
    AND backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
$$;

CREATE FUNCTION opengeni_private.codex_cooldown_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.exhausted_until IS DISTINCT FROM OLD.exhausted_until THEN
    IF NEW.exhausted_revision = OLD.exhausted_revision THEN
      -- Compatibility path for a pre-0382 writer: retain the cooldown but do
      -- not let a new usage reader mistake its unknown cause for quota.
      NEW.exhausted_kind := NULL;
      NEW.exhausted_revision := OLD.exhausted_revision + 1;
    ELSIF NEW.exhausted_revision <> OLD.exhausted_revision + 1 THEN
      RAISE EXCEPTION 'Codex cooldown revision must advance exactly once';
    END IF;
  ELSIF NEW.exhausted_kind IS DISTINCT FROM OLD.exhausted_kind
    OR NEW.exhausted_revision IS DISTINCT FROM OLD.exhausted_revision
  THEN
    IF NEW.exhausted_revision <> OLD.exhausted_revision + 1 THEN
      RAISE EXCEPTION 'Codex cooldown metadata revision must advance exactly once';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.codex_credential_serves_turn(p_account_id uuid, p_workspace_id uuid, p_credential_id uuid, p_turn_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE accepted_source text;
    BEGIN
      IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
      THEN RETURN false; END IF;
      SELECT coalesce(turn.metadata #>> '{codexCredentialPolicySnapshotV1,source}', binding.source)
        INTO accepted_source
      FROM session_turns turn
      JOIN sessions session ON session.id = turn.session_id
        AND session.workspace_id = turn.workspace_id AND session.account_id = turn.account_id
      LEFT JOIN codex_turn_source_bindings binding ON binding.turn_id = turn.id
        AND binding.account_id = turn.account_id AND binding.workspace_id = turn.workspace_id
      WHERE turn.id = p_turn_id AND turn.account_id = p_account_id
        AND turn.workspace_id = p_workspace_id
        AND turn.model LIKE 'codex/%'
        AND turn.status IN ('queued', 'running', 'requires_action', 'recovering', 'waiting_capacity');
      IF NOT FOUND THEN RETURN false; END IF;
      -- Before the first cutover a legacy policy can still use current source.
      -- Every source mutation captures its pre-change authority in the sidecar.
      IF accepted_source IS NULL THEN
        RETURN opengeni_private.codex_credential_serves_workspace(
          p_account_id, p_workspace_id, p_credential_id);
      END IF;
      RETURN EXISTS (
        SELECT 1 FROM codex_subscription_credentials credential
        WHERE credential.id = p_credential_id AND credential.account_id = p_account_id
          AND (
            (accepted_source = 'workspace' AND credential.workspace_id = p_workspace_id
              AND credential.authority_scope IN ('workspace', 'user'))
            OR (accepted_source = 'organization' AND credential.organization_id = p_account_id
              AND credential.authority_scope = 'organization'
              AND opengeni_private.codex_organization_scope_visible(p_account_id))
          )
      );
    END
    $$;

CREATE FUNCTION opengeni_private.codex_credential_serves_workspace(p_account_id uuid, p_workspace_id uuid, p_credential_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      credential codex_subscription_credentials%ROWTYPE;
      mode_value text := 'automatic';
      effective_source text;
    BEGIN
      SELECT * INTO credential
      FROM codex_subscription_credentials candidate
      WHERE candidate.account_id = p_account_id AND candidate.id = p_credential_id;
      IF NOT FOUND THEN RETURN false; END IF;
      SELECT preference.mode INTO mode_value
      FROM workspace_codex_subscription_preferences preference
      WHERE preference.account_id = p_account_id
        AND preference.workspace_id = p_workspace_id;
      mode_value := coalesce(mode_value, 'automatic');
      IF mode_value <> 'automatic' THEN
        effective_source := mode_value;
      ELSIF EXISTS (
        SELECT 1 FROM codex_subscription_credentials candidate
        WHERE candidate.account_id = p_account_id
          AND candidate.workspace_id = p_workspace_id
          AND candidate.authority_scope IN ('workspace', 'user')
      ) THEN
        effective_source := 'workspace';
      ELSIF EXISTS (
        SELECT 1 FROM codex_subscription_credentials candidate
        WHERE candidate.account_id = p_account_id
          AND candidate.organization_id = p_account_id
          AND candidate.authority_scope = 'organization'
      ) THEN
        effective_source := 'organization';
      ELSE
        effective_source := 'workspace';
      END IF;
      IF credential.authority_scope IN ('workspace', 'user') THEN
        RETURN credential.workspace_id = p_workspace_id
          AND effective_source = 'workspace';
      END IF;
      RETURN credential.authority_scope = 'organization'
        AND credential.organization_id = p_account_id
        AND effective_source = 'organization';
    END
    $$;

CREATE FUNCTION opengeni_private.codex_organization_admin_visible(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT opengeni_private.current_workspace_id() IS NULL
    AND opengeni_private.codex_organization_scope_visible(p_account_id)
$$;

CREATE FUNCTION opengeni_private.codex_organization_live_lease_count(p_account_id uuid, p_credential_id uuid, p_exclude_turn_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE live_count integer;
    BEGIN
      IF p_account_id IS NULL
        OR p_credential_id IS NULL
        OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR opengeni_private.current_workspace_id() IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM codex_subscription_credentials credential
          WHERE credential.account_id = p_account_id
            AND credential.id = p_credential_id
            AND credential.organization_id = p_account_id
            AND credential.authority_scope = 'organization'
        )
        OR NOT (CASE WHEN p_exclude_turn_id IS NULL THEN
          opengeni_private.codex_credential_serves_workspace(p_account_id, opengeni_private.current_workspace_id(), p_credential_id)
        ELSE opengeni_private.codex_credential_serves_turn(p_account_id, opengeni_private.current_workspace_id(), p_credential_id, p_exclude_turn_id) END)
      THEN
        RAISE EXCEPTION 'organization Codex lease-count authority required'
          USING ERRCODE = '42501';
      END IF;
      SELECT count(*)::integer INTO live_count
      FROM codex_credential_leases lease
      WHERE lease.account_id = p_account_id
        AND lease.credential_id = p_credential_id
        AND lease.leased_until > clock_timestamp()
        AND (p_exclude_turn_id IS NULL OR lease.turn_id <> p_exclude_turn_id);
      RETURN live_count;
    END
    $$;

CREATE FUNCTION opengeni_private.codex_organization_scope_visible(p_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      workspace_value uuid := opengeni_private.current_workspace_id();
      subject_value text := opengeni_private.current_subject_id();
      visible boolean := false;
      previous_lifecycle text := pg_catalog.current_setting(
        'opengeni.organization_tenancy_lifecycle', true
      );
    BEGIN
      IF p_account_id IS NULL
        OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
      THEN
        RETURN false;
      END IF;
      IF workspace_value IS NOT NULL THEN
        PERFORM pg_catalog.set_config(
          'opengeni.organization_tenancy_lifecycle',
          'organization_membership_lifecycle', true
        );
        SELECT EXISTS (
          SELECT 1 FROM {{schema}}.workspaces workspace
          WHERE workspace.account_id = p_account_id AND workspace.id = workspace_value
        ) INTO visible;
        PERFORM pg_catalog.set_config(
          'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
        );
        RETURN coalesce(visible, false);
      END IF;
      IF subject_value IS NULL OR NOT (
        subject_value LIKE 'user:%'
        OR (
          subject_value = 'dev'
          AND EXISTS (
            SELECT 1 FROM {{schema}}.managed_accounts account
            WHERE account.id = p_account_id
              AND account.external_source = 'opengeni:local'
              AND account.external_id = 'default'
          )
        )
      ) THEN
        RETURN false;
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        'organization_membership_lifecycle', true
      );
      SELECT EXISTS (
        SELECT 1 FROM {{schema}}.organization_memberships membership
        WHERE membership.account_id = p_account_id
          AND membership.subject_id = subject_value
          AND membership.status = 'active'
          AND membership.role IN ('owner', 'admin')
      ) INTO visible;
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
      );
      RETURN coalesce(visible, false);
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
      );
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.compact_session_content_row(p_kind text, p_workspace_id uuid, p_attempt_id uuid, p_stored jsonb, p_refs jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  row_account uuid;
  row_session uuid;
  original jsonb;
  expected jsonb;
  rebuilt jsonb;
  rebuilt_text text;
  chunks_complete boolean;
BEGIN
  IF p_refs IS NULL OR jsonb_typeof(p_refs) <> 'object' OR (p_refs->>'v')::integer <> 1 THEN
    RETURN false;
  END IF;
  IF p_kind = 'tool_catalog' THEN
    SELECT C.account_id, C.session_id, C.catalog INTO row_account, row_session, original
    FROM session_attempt_tool_catalogs C
    WHERE C.workspace_id = p_workspace_id AND C.attempt_id = p_attempt_id
      AND C.content_refs IS NULL
    FOR UPDATE;
    IF NOT FOUND OR jsonb_typeof(p_refs->'entries') <> 'array' THEN
      RETURN false;
    END IF;
    expected := jsonb_set(original, '{entries}', '[]'::jsonb);
    IF p_stored IS DISTINCT FROM expected THEN
      RETURN false;
    END IF;
    SELECT coalesce(jsonb_agg(B.value ORDER BY E.ordinality), '[]'::jsonb) INTO rebuilt
    FROM jsonb_array_elements_text(p_refs->'entries') WITH ORDINALITY AS E(digest, ordinality)
    JOIN session_content_blobs B
      ON B.workspace_id = p_workspace_id AND B.session_id = row_session
      AND B.account_id = row_account AND B.digest = E.digest;
    IF rebuilt IS DISTINCT FROM original->'entries' THEN
      RETURN false;
    END IF;
    UPDATE session_attempt_tool_catalogs
    SET catalog = p_stored, content_refs = p_refs
    WHERE workspace_id = p_workspace_id AND attempt_id = p_attempt_id;
    RETURN true;
  ELSIF p_kind = 'model_context_snapshot' THEN
    SELECT S.account_id, S.session_id, S.snapshot INTO row_account, row_session, original
    FROM session_attempt_model_context_snapshots S
    WHERE S.workspace_id = p_workspace_id AND S.attempt_id = p_attempt_id
      AND S.content_refs IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
      RETURN false;
    END IF;
    expected := original
      || jsonb_build_object('instructions', '', 'layers', '[]'::jsonb, 'tools', '[]'::jsonb,
        'skills', '[]'::jsonb);
    IF jsonb_typeof(p_refs->'body') = 'array' THEN
      IF jsonb_typeof(original #> '{providerRequest,body}') IS DISTINCT FROM 'string' THEN
        RETURN false;
      END IF;
      expected := jsonb_set(expected, '{providerRequest,body}', 'null'::jsonb);
      SELECT string_agg(B.value #>> '{}', '' ORDER BY E.ordinality),
        count(*) FILTER (WHERE jsonb_typeof(B.value) = 'string')
          = jsonb_array_length(p_refs->'body')
      INTO rebuilt_text, chunks_complete
      FROM jsonb_array_elements_text(p_refs->'body') WITH ORDINALITY AS E(digest, ordinality)
      JOIN session_content_blobs B
        ON B.workspace_id = p_workspace_id AND B.session_id = row_session
        AND B.account_id = row_account AND B.digest = E.digest;
      IF chunks_complete IS NOT TRUE
        OR coalesce(rebuilt_text, '') IS DISTINCT FROM original #>> '{providerRequest,body}' THEN
        RETURN false;
      END IF;
    ELSIF p_refs->'body' IS DISTINCT FROM 'null'::jsonb THEN
      RETURN false;
    END IF;
    IF p_stored IS DISTINCT FROM expected THEN
      RETURN false;
    END IF;
    IF (SELECT count(*) FROM (VALUES ('instructions'), ('layers'), ('tools'), ('skills')) AS K(name)
        JOIN session_content_blobs B
          ON B.workspace_id = p_workspace_id AND B.session_id = row_session
          AND B.account_id = row_account AND B.digest = p_refs->>K.name
          AND B.value = original->K.name) <> 4 THEN
      RETURN false;
    END IF;
    UPDATE session_attempt_model_context_snapshots
    SET snapshot = p_stored, content_refs = p_refs
    WHERE workspace_id = p_workspace_id AND attempt_id = p_attempt_id;
    RETURN true;
  END IF;
  RAISE EXCEPTION 'unknown session content kind' USING ERRCODE = '22023';
END;
$$;

CREATE FUNCTION opengeni_private.company_brain_legacy_instruction_projection(value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  original_bytes integer := octet_length(value);
  marker text;
  budget integer;
  lower_chars integer := 0;
  upper_chars integer := length(value);
  midpoint integer;
BEGIN
  IF original_bytes <= 131072 THEN
    RETURN value;
  END IF;
  marker := E'\n[legacy workspace instructions truncated; original UTF-8 bytes=' || original_bytes::text || ']';
  budget := greatest(0, 131072 - octet_length(marker));
  WHILE lower_chars < upper_chars LOOP
    midpoint := (lower_chars + upper_chars + 1) / 2;
    IF octet_length(left(value, midpoint)) <= budget THEN
      lower_chars := midpoint;
    ELSE
      upper_chars := midpoint - 1;
    END IF;
  END LOOP;
  RETURN left(value, lower_chars) || marker;
END;
$$;

CREATE FUNCTION opengeni_private.company_brain_memory_selections_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  item jsonb;
  item_id text;
  seen_ids text[] := ARRAY[]::text[];
BEGIN
  IF jsonb_typeof(value) <> 'array'
    OR jsonb_array_length(value) > 50
    OR octet_length(value::text) > 16384
  THEN
    RETURN false;
  END IF;
  FOR item IN SELECT element FROM jsonb_array_elements(value) AS entries(element)
  LOOP
    IF jsonb_typeof(item) <> 'object'
      OR (SELECT count(*) FROM pg_catalog.jsonb_object_keys(item)) <> 7
      OR NOT (item ?& ARRAY['id','kind','textHash','contentHash','textCodecVersion','memoryVersion','pinned'])
      OR jsonb_typeof(item->'id') <> 'string'
      OR jsonb_typeof(item->'kind') <> 'string'
      OR jsonb_typeof(item->'textHash') <> 'string'
      OR jsonb_typeof(item->'contentHash') <> 'string'
      OR jsonb_typeof(item->'textCodecVersion') NOT IN ('number','null')
      OR jsonb_typeof(item->'memoryVersion') <> 'number'
      OR jsonb_typeof(item->'pinned') <> 'boolean'
      OR item->>'id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      OR item->>'kind' NOT IN ('semantic','procedural','decision','preference')
      OR item->>'textHash' !~ '^[0-9a-f]{64}$'
      OR item->>'contentHash' !~ '^[0-9a-f]{64}$'
      OR (jsonb_typeof(item->'textCodecVersion') = 'number' AND (
        item->>'textCodecVersion' !~ '^(0|[1-9][0-9]{0,9})$'
        OR (item->>'textCodecVersion')::numeric > 2147483647
      ))
      OR item->>'memoryVersion' !~ '^[1-9][0-9]{0,9}$'
      OR (item->>'memoryVersion')::numeric > 2147483647
    THEN
      RETURN false;
    END IF;
    item_id := item->>'id';
    IF item_id = ANY(seen_ids) THEN
      RETURN false;
    END IF;
    seen_ids := array_append(seen_ids, item_id);
  END LOOP;
  RETURN true;
END;
$_$;

CREATE FUNCTION opengeni_private.complete_session_archive_object_deletion(p_object_key text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH deleted AS (
    DELETE FROM opengeni_private.session_archive_object_deletions
    WHERE object_key = p_object_key RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM deleted);
$$;

CREATE FUNCTION opengeni_private.complete_temporal_schedule_connector_cleanup(p_id uuid, p_claim_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value boolean;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'schedule_cleanup');
        result_value := opengeni_private.maintenance_schedule_cleanup_connector_inner($1, $2);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN result_value;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.complete_workspace_insights_usage_projection(p_workspace_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_event_types text[]) RETURNS TABLE(event_type text, quantity bigint, occurred_at timestamp with time zone, source_resource_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET enable_nestloop TO 'off'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
    DECLARE
      context_account_id uuid;
      context_workspace_id uuid;
      context_subject_id text;
      context_initiating_human_subject_id text;
    BEGIN
      PERFORM opengeni_private.session_variable_set_attachments_protocol_v1_active();
      BEGIN
        context_account_id := nullif(
          pg_catalog.current_setting('opengeni.account_id', true), ''
        )::uuid;
        context_workspace_id := nullif(
          pg_catalog.current_setting('opengeni.workspace_id', true), ''
        )::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Insights RLS context is malformed'
          USING ERRCODE = '42501';
      END;
      context_subject_id := nullif(
        pg_catalog.current_setting('opengeni.subject_id', true), ''
      );
      context_initiating_human_subject_id := nullif(
        pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''
      );
      IF context_account_id IS NULL
        OR context_workspace_id IS NULL
        OR context_workspace_id IS DISTINCT FROM p_workspace_id
      THEN
        RAISE EXCEPTION 'Insights RLS context does not match the requested workspace'
          USING ERRCODE = '42501';
      END IF;
      IF p_since IS NULL
        OR p_until IS NULL
        OR p_since IN (
          '-infinity'::timestamp with time zone,
          'infinity'::timestamp with time zone
        )
        OR p_until = '-infinity'::timestamp with time zone
        OR p_until < p_since
        OR (
          p_until <> 'infinity'::timestamp with time zone
          AND p_until - p_since > interval '370 days'
        )
        OR (
          p_until = 'infinity'::timestamp with time zone
          AND p_since < CURRENT_TIMESTAMP - interval '370 days'
        )
      THEN
        RAISE EXCEPTION 'Insights fact window must be non-negative and at most 370 days'
          USING ERRCODE = '22023';
      END IF;
      IF p_event_types IS NULL
        OR pg_catalog.array_ndims(p_event_types) <> 1
        OR pg_catalog.cardinality(p_event_types) < 1
        OR pg_catalog.cardinality(p_event_types) > 16
        OR EXISTS (
          SELECT 1
          FROM pg_catalog.unnest(p_event_types) event_type(value)
          WHERE event_type.value IS NULL
            OR pg_catalog.btrim(event_type.value) = ''
            OR pg_catalog.octet_length(event_type.value) > 256
        )
        OR (
          SELECT pg_catalog.count(DISTINCT event_type.value COLLATE "C")
          FROM pg_catalog.unnest(p_event_types) event_type(value)
        ) <> pg_catalog.cardinality(p_event_types)
      THEN
        RAISE EXCEPTION 'Insights usage event types must contain 1-16 unique bounded values'
          USING ERRCODE = '22023';
      END IF;
      IF p_until = p_since THEN
        RETURN;
      END IF;

      INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities (
        backend_pid,
        transaction_id,
        capability_kind,
        account_id,
        workspace_id,
        subject_id,
        initiating_human_subject_id
      ) VALUES (
        pg_catalog.pg_backend_pid(),
        pg_catalog.pg_current_xact_id(),
        'usage_events',
        context_account_id,
        context_workspace_id,
        context_subject_id,
        context_initiating_human_subject_id
      );
      BEGIN
        RETURN QUERY
        WITH visible_sessions AS MATERIALIZED (
          SELECT
            id, account_id, workspace_id, sandbox_group_id, visibility,
            owner_organization_membership_id, owner_subject_id
          FROM {{schema}}.insights_audience_sessions
          WHERE account_id = context_account_id
            AND workspace_id = p_workspace_id
        )
        , visible_warm_groups AS MATERIALIZED (
          SELECT DISTINCT coalesce(sandbox_group_id, id)::text AS group_id
          FROM visible_sessions
          WHERE (context_subject_id IS NULL OR visibility = 'workspace_shared'
            OR {{schema}}.session_private_actor_visible(account_id, workspace_id,
              owner_organization_membership_id, owner_subject_id))
            AND (sandbox_group_id IS NULL OR sandbox_group_id = id)
        )
        SELECT usage_row.event_type, usage_row.quantity,
          usage_row.occurred_at, CASE WHEN (usage_row.session_id IS NULL
          OR (session_row.id IS NOT NULL AND (context_subject_id IS NULL
            OR session_row.visibility = 'workspace_shared'
            OR {{schema}}.session_private_actor_visible(session_row.account_id, session_row.workspace_id,
              session_row.owner_organization_membership_id, session_row.owner_subject_id))))
          AND (usage_row.event_type <> 'sandbox.warm_seconds' OR warm_group.group_id IS NOT NULL)
          THEN usage_row.source_resource_id END
        FROM {{schema}}.usage_events usage_row
        LEFT JOIN visible_sessions session_row
          ON session_row.account_id = usage_row.account_id
          AND session_row.workspace_id = usage_row.workspace_id
          AND session_row.id = usage_row.session_id
        LEFT JOIN visible_warm_groups warm_group
          ON usage_row.event_type = 'sandbox.warm_seconds'
          AND warm_group.group_id = split_part(usage_row.source_resource_id, ':', 1)
        WHERE usage_row.account_id = context_account_id
          AND usage_row.workspace_id = p_workspace_id
          AND usage_row.event_type = ANY (p_event_types)
          AND usage_row.occurred_at >= p_since
          AND usage_row.occurred_at < p_until;

        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'usage_events';
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'usage_events';
        RAISE;
      END;
    END
    $$;

CREATE FUNCTION opengeni_private.complete_workspace_temporal_connector_cleanups(p_account_id uuid, p_workspace_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE completed_rows bigint := 0;
    BEGIN
      IF p_account_id IS DISTINCT FROM
          nullif(pg_catalog.current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM
          nullif(pg_catalog.current_setting('opengeni.workspace_id', true), '')::uuid
      THEN
        RAISE EXCEPTION 'workspace connector cleanup scope is invalid'
          USING ERRCODE = '42501';
      END IF;
      UPDATE {{schema}}.temporal_schedule_cleanup_outbox cleanup
      SET scheduled_task_id = NULL,
          connector_cleanup_subject_id = NULL,
          connector_cleanup_snapshot = NULL,
          connector_cleanup_completed_at = NULL,
          updated_at = pg_catalog.clock_timestamp()
      WHERE cleanup.account_id = p_account_id
        AND cleanup.workspace_id = p_workspace_id
        AND cleanup.connector_cleanup_snapshot IS NOT NULL;
      GET DIAGNOSTICS completed_rows = ROW_COUNT;
      RETURN completed_rows;
    END
    $$;

CREATE FUNCTION opengeni_private.configure_fork_session_runtime(p_account_id uuid, p_workspace_id uuid, p_source_session_id uuid, p_destination_session_id uuid, p_actor_subject_id text, p_variable_set_ids jsonb, p_rig_id uuid, p_rig_version_id uuid, p_configuration_digest text) RETURNS TABLE(runtime_event_id uuid, runtime_event_sequence integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  destination_session sessions%ROWTYPE;
  runtime_marker jsonb;
  selected_count integer;
  selected_last uuid;
  destination_activity_revision bigint;
  previous_gate_state text := current_setting('opengeni.session_activity_gate_state', true);
  previous_gate_workspace text := current_setting(
    'opengeni.session_activity_gate_workspace_id', true
  );
BEGIN
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
  THEN
    RAISE EXCEPTION 'fork runtime configuration authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF p_account_id IS NULL OR p_workspace_id IS NULL
    OR p_source_session_id IS NULL OR p_destination_session_id IS NULL
    OR p_actor_subject_id IS NULL OR p_variable_set_ids IS NULL
    OR p_configuration_digest !~ '^[0-9a-f]{64}$'
    OR nullif(previous_gate_state, '') IS NOT NULL
    OR nullif(previous_gate_workspace, '') IS NOT NULL
  THEN
    RAISE EXCEPTION 'fork runtime configuration request is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM acquire_session_tenancy_fence(p_workspace_id);
  SELECT session_value.* INTO destination_session
  FROM sessions session_value
  WHERE session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND session_value.id = p_destination_session_id
  FOR UPDATE;
  IF NOT FOUND
    OR destination_session.forked_from_session_id IS DISTINCT FROM p_source_session_id
    OR destination_session.owner_subject_id IS DISTINCT FROM p_actor_subject_id
  THEN
    RAISE EXCEPTION 'fork runtime destination is unavailable'
      USING ERRCODE = '42501';
  END IF;

  runtime_marker := destination_session.metadata -> 'forkRuntimeConfiguration';
  IF runtime_marker IS NOT NULL THEN
    IF runtime_marker ->> 'digest' IS DISTINCT FROM p_configuration_digest THEN
      RAISE EXCEPTION 'session fork idempotency conflict' USING ERRCODE = '23505';
    END IF;
    runtime_event_id := nullif(runtime_marker ->> 'eventId', '')::uuid;
    runtime_event_sequence := (runtime_marker ->> 'eventSequence')::integer;
    IF runtime_event_id IS NULL OR runtime_event_sequence IS NULL THEN
      RAISE EXCEPTION 'fork runtime configuration marker is incomplete'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEXT;
    RETURN;
  END IF;

  IF destination_session.status <> 'idle'
    OR destination_session.active_turn_id IS NOT NULL
    OR destination_session.active_sandbox_id IS NOT NULL
    OR destination_session.sandbox_group_id IS DISTINCT FROM destination_session.id
  THEN
    RAISE EXCEPTION 'fork runtime destination is not fresh and quiescent'
      USING ERRCODE = '23514';
  END IF;
  IF jsonb_typeof(p_variable_set_ids) <> 'array' THEN
    RAISE EXCEPTION 'fork runtime Variable Set ids must be an array'
      USING ERRCODE = '22023';
  END IF;
  selected_count := jsonb_array_length(p_variable_set_ids);
  IF selected_count > 25
    OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(p_variable_set_ids) item(value)
      WHERE jsonb_typeof(item.value) <> 'string'
        OR (item.value #>> '{}') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    )
    OR selected_count <> (
      SELECT count(DISTINCT value)
      FROM jsonb_array_elements_text(p_variable_set_ids) selected(value)
    )
  THEN
    RAISE EXCEPTION 'fork runtime Variable Set selection is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF selected_count <> (
    SELECT count(*)
    FROM workspace_variable_sets variable_set
    JOIN jsonb_array_elements_text(p_variable_set_ids) selected(value)
      ON selected.value::uuid = variable_set.id
    WHERE variable_set.account_id = p_account_id
      AND variable_set.status = 'active'
  ) THEN
    RAISE EXCEPTION 'fork runtime Variable Set selection is unavailable'
      USING ERRCODE = '42501';
  END IF;
  SELECT selected.value::uuid INTO selected_last
  FROM jsonb_array_elements_text(p_variable_set_ids)
    WITH ORDINALITY selected(value, position)
  ORDER BY selected.position DESC
  LIMIT 1;

  IF (p_rig_id IS NULL) <> (p_rig_version_id IS NULL)
    OR (
      p_rig_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM rig_versions rig_version
        WHERE rig_version.account_id = p_account_id
          AND rig_version.rig_id = p_rig_id
          AND rig_version.id = p_rig_version_id
          AND rig_version.active
          AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              coalesce(rig_version.default_variable_set_ids, '[]'::jsonb)
            ) default_set(value)
            WHERE NOT EXISTS (
              SELECT 1
              FROM workspace_variable_sets variable_set
              WHERE variable_set.account_id = p_account_id
                AND variable_set.id = default_set.value::uuid
                AND variable_set.status = 'active'
            )
          )
      )
    )
  THEN
    RAISE EXCEPTION 'fork runtime Rig selection is unavailable'
      USING ERRCODE = '42501';
  END IF;

  runtime_event_id := gen_random_uuid();
  runtime_event_sequence := destination_session.last_sequence + 1;
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard DEFERRED;
  PERFORM set_config('opengeni.session_activity_gate_state', 'open', true);
  PERFORM set_config('opengeni.session_activity_gate_workspace_id', p_workspace_id::text, true);
  UPDATE sessions session_value SET
    variable_set_ids = p_variable_set_ids,
    variable_set_id = selected_last,
    rig_id = p_rig_id,
    rig_version_id = p_rig_version_id,
    metadata = session_value.metadata || jsonb_build_object(
      'forkRuntimeConfiguration', jsonb_build_object(
        'digest', p_configuration_digest,
        'eventId', runtime_event_id,
        'eventSequence', runtime_event_sequence,
        'variableSetIds', p_variable_set_ids,
        'rigId', p_rig_id,
        'rigVersionId', p_rig_version_id
      )
    ),
    last_sequence = runtime_event_sequence,
    updated_at = clock_timestamp()
  WHERE session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND session_value.id = p_destination_session_id;

  INSERT INTO session_events (
    id, account_id, workspace_id, session_id, sequence, type, payload, occurred_at
  ) VALUES (
    runtime_event_id, p_account_id, p_workspace_id, p_destination_session_id,
    runtime_event_sequence, 'session.runtime.configured', jsonb_build_object(
      'sourceSessionId', p_source_session_id,
      'variableSetIds', p_variable_set_ids,
      'rigId', p_rig_id,
      'rigVersionId', p_rig_version_id,
      'collisionPolicy', 'later_selected_set_wins'
    ), clock_timestamp()
  );
  INSERT INTO audit_events (
    account_id, workspace_id, subject_id, action, target_type, target_id,
    metadata, metadata_codec_version
  ) VALUES (
    p_account_id, p_workspace_id, p_actor_subject_id,
    'session.runtime.configured', 'session', p_destination_session_id::text,
    jsonb_build_object(
      'sourceSessionId', p_source_session_id,
      'variableSetIds', p_variable_set_ids,
      'rigId', p_rig_id,
      'rigVersionId', p_rig_version_id,
      'collisionPolicy', 'later_selected_set_wins'
    ), 1
  );

  PERFORM set_config('opengeni.session_activity_gate_state', 'preparing', true);
  SET CONSTRAINTS ALL IMMEDIATE;
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard DEFERRED;
  PERFORM set_config('opengeni.session_activity_gate_state', 'finalizing', true);
  UPDATE workspace_session_activity_revisions counter
  SET revision = counter.revision + 1
  WHERE counter.workspace_id = p_workspace_id
  RETURNING counter.revision INTO destination_activity_revision;
  IF destination_activity_revision IS NULL THEN
    RAISE EXCEPTION 'fork runtime destination activity counter is unavailable'
      USING ERRCODE = '23514';
  END IF;
  UPDATE sessions session_value SET
    activity_revision = destination_activity_revision,
    activity_revision_pending_xid = NULL
  WHERE session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND session_value.id = p_destination_session_id
    AND session_value.activity_revision_pending_xid = pg_current_xact_id()::text::bigint;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'fork runtime destination activity was not finalized'
      USING ERRCODE = '23514';
  END IF;
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard IMMEDIATE;
  PERFORM set_config('opengeni.session_activity_gate_state', '', true);
  PERFORM set_config('opengeni.session_activity_gate_workspace_id', '', true);
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'opengeni.session_activity_gate_state', coalesce(previous_gate_state, ''), true
  );
  PERFORM set_config(
    'opengeni.session_activity_gate_workspace_id',
    coalesce(previous_gate_workspace, ''), true
  );
  RAISE;
END
$_$;

CREATE FUNCTION opengeni_private.connect_subscription_core_personal(p_provider text, p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_credential_encrypted text, p_provider_account_id text, p_provider_subject_id text, p_plan_type text, p_provider_state jsonb, p_expires_at timestamp with time zone, p_last_refresh_at timestamp with time zone, p_account_email text, p_label text, p_connected_by_subject_id text) RETURNS TABLE(outcome text, connection_id uuid, is_new boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      owner_membership uuid;
      existing_id uuid;
      new_id uuid;
      authority uuid;
      authority_gen bigint;
      personal_allowed boolean;
    BEGIN
      IF NOT opengeni_subscription_internal.subscription_core_writer_context(
          p_provider, p_account_id, p_workspace_id, p_subject_id)
        OR p_credential_encrypted IS NULL OR length(p_credential_encrypted) = 0
        OR (p_provider_state IS NOT NULL AND jsonb_typeof(p_provider_state) <> 'object')
      THEN
        outcome := 'refused'; RETURN NEXT; RETURN;
      END IF;
      PERFORM opengeni_subscription_internal.grant_subscription_core_owner_capability(
        p_provider, 'connection_owner', p_account_id, p_workspace_id, p_subject_id,
        '00000000-0000-0000-0000-000000000000'::uuid);
      SELECT membership.id INTO owner_membership
      FROM organization_memberships membership
      WHERE membership.account_id = p_account_id AND membership.subject_id = p_subject_id
        AND membership.status = 'active' AND membership.revoked_at IS NULL
        AND membership.personal_workspace_id = p_workspace_id;
      IF owner_membership IS NULL THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'not_personal_workspace'; RETURN NEXT; RETURN;
      END IF;
      personal_allowed := coalesce((subscription_effective_settings(p_account_id, p_workspace_id)
        #>> '{values,personalConnectionsAllowed}')::boolean, false);
      IF NOT personal_allowed THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'personal_connections_disabled'; RETURN NEXT; RETURN;
      END IF;
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'subscription-personal-authority:' || p_account_id::text || ':' || owner_membership::text, 0));
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'subscription-connect:' || p_account_id::text || ':' || p_provider || ':' || owner_membership::text
          || ':' || coalesce(p_provider_account_id, ''), 0));
      IF p_provider_account_id IS NULL OR p_provider_subject_id IS NULL
        OR p_provider_subject_id LIKE 'legacy:%'
        OR EXISTS (SELECT 1 FROM subscription_connections connection
          WHERE connection.account_id = p_account_id AND connection.provider = p_provider
            AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider) AND connection.ownership = 'personal'
            AND connection.owner_organization_membership_id = owner_membership
            AND connection.provider_account_id = p_provider_account_id
            AND (connection.provider_subject_id IS NULL OR connection.provider_subject_id LIKE 'legacy:%'))
      THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'identity_unverified'; RETURN NEXT; RETURN;
      END IF;
      IF p_provider_account_id IS NOT NULL THEN
        SELECT connection.id INTO existing_id
        FROM subscription_connections connection
        WHERE connection.account_id = p_account_id AND connection.provider = p_provider
          AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider) AND connection.ownership = 'personal'
          AND connection.owner_organization_membership_id = owner_membership
          AND connection.provider_account_id = p_provider_account_id
          AND connection.provider_subject_id = p_provider_subject_id;
      END IF;
      IF existing_id IS NOT NULL THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          'subscription-refresh:' || existing_id::text, 0));
        PERFORM 1 FROM subscription_connections connection
        WHERE connection.account_id = p_account_id AND connection.id = existing_id
        FOR UPDATE;
        UPDATE subscription_connections connection SET
          credential_encrypted = p_credential_encrypted, credential_format = 'v1',
          expires_at = p_expires_at, last_refresh_at = p_last_refresh_at,
          refresh_generation = connection.refresh_generation + 1,
          version = connection.version + 1, status = 'active', last_error = NULL,
          plan_type = coalesce(p_plan_type, connection.plan_type),
          provider_state = connection.provider_state || coalesce(p_provider_state, '{}'::jsonb),
          account_email = coalesce(p_account_email, connection.account_email),
          label = coalesce(connection.label, p_label),
          connected_by_subject_id = p_connected_by_subject_id, updated_at = clock_timestamp()
        WHERE connection.account_id = p_account_id AND connection.id = existing_id;
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'connected'; connection_id := existing_id; is_new := false;
        RETURN NEXT; RETURN;
      END IF;
      SELECT max(resource.generation) INTO authority_gen
      FROM subscription_connections connection
      JOIN organization_user_resource_authorities resource
        ON resource.account_id = connection.account_id AND resource.id = connection.authority_id
       AND resource.status = 'active' AND resource.revoked_at IS NULL
      WHERE connection.account_id = p_account_id AND connection.provider = p_provider
        AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND connection.ownership = 'personal'
        AND connection.owner_organization_membership_id = owner_membership;
      IF authority_gen IS NULL THEN
        SELECT coalesce(max(resource.generation), 0) + 1 INTO authority_gen
        FROM organization_user_resource_authorities resource
        WHERE resource.account_id = p_account_id
          AND resource.organization_membership_id = owner_membership
          AND resource.resource_kind = 'subscription_connection';
      END IF;
      new_id := gen_random_uuid();
      INSERT INTO organization_user_resource_authorities (
        account_id, organization_membership_id, resource_kind, resource_id,
        origin_workspace_id, generation, status
      ) VALUES (
        p_account_id, owner_membership, 'subscription_connection', new_id, p_workspace_id,
        authority_gen, 'active'
      ) RETURNING id INTO authority;
      INSERT INTO subscription_connections (
        id, account_id, provider, kind, provider_account_id, provider_subject_id, account_email, label, plan_type,
        credential_encrypted, credential_format, expires_at, last_refresh_at, status,
        ownership, owner_organization_membership_id, owner_subject_id, authority_id,
        authority_resource_kind, authority_generation, connected_by_subject_id, scope_kind,
        allow_personal_workspaces, managed_by_workspace_id, provider_state
      ) VALUES (
        new_id, p_account_id, p_provider, opengeni_private.subscription_core_connection_kind(p_provider), p_provider_account_id, p_provider_subject_id, p_account_email,
        p_label, p_plan_type, p_credential_encrypted, 'v1', p_expires_at, p_last_refresh_at,
        'active', 'personal', owner_membership, p_subject_id, authority,
        'subscription_connection', authority_gen, p_connected_by_subject_id, 'people', true, NULL,
        coalesce(p_provider_state, '{}'::jsonb)
      );
      PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
      outcome := 'connected'; connection_id := new_id; is_new := true;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION opengeni_private.connect_subscription_core_personal(p_provider text, p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_credential_encrypted text, p_provider_account_id text, p_provider_subject_id text, p_plan_type text, p_provider_state jsonb, p_expires_at timestamp with time zone, p_last_refresh_at timestamp with time zone, p_account_email text, p_label text, p_connected_by_subject_id text, p_credential_format text) RETURNS TABLE(outcome text, connection_id uuid, is_new boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $_$
    DECLARE
      owner_membership uuid;
      existing_id uuid;
      new_id uuid;
      authority uuid;
      authority_gen bigint;
      personal_allowed boolean;
    BEGIN
      IF NOT opengeni_subscription_internal.subscription_core_writer_context(
          p_provider, p_account_id, p_workspace_id, p_subject_id)
        OR p_credential_encrypted IS NULL OR length(p_credential_encrypted) = 0
        OR p_credential_format IS NULL OR p_credential_format !~ '^[a-z][a-z0-9_]{0,63}$'
        OR (p_provider_state IS NOT NULL AND jsonb_typeof(p_provider_state) <> 'object')
      THEN
        outcome := 'refused'; RETURN NEXT; RETURN;
      END IF;
      PERFORM opengeni_subscription_internal.grant_subscription_core_owner_capability(
        p_provider, 'connection_owner', p_account_id, p_workspace_id, p_subject_id,
        '00000000-0000-0000-0000-000000000000'::uuid);
      SELECT membership.id INTO owner_membership
      FROM organization_memberships membership
      WHERE membership.account_id = p_account_id AND membership.subject_id = p_subject_id
        AND membership.status = 'active' AND membership.revoked_at IS NULL
        AND membership.personal_workspace_id = p_workspace_id;
      IF owner_membership IS NULL THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'not_personal_workspace'; RETURN NEXT; RETURN;
      END IF;
      personal_allowed := coalesce((subscription_effective_settings(p_account_id, p_workspace_id)
        #>> '{values,personalConnectionsAllowed}')::boolean, false);
      IF NOT personal_allowed THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'personal_connections_disabled'; RETURN NEXT; RETURN;
      END IF;
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'subscription-personal-authority:' || p_account_id::text || ':' || owner_membership::text, 0));
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'subscription-connect:' || p_account_id::text || ':' || p_provider || ':' || owner_membership::text
          || ':' || coalesce(p_provider_account_id, ''), 0));
      IF p_provider_account_id IS NULL OR p_provider_subject_id IS NULL
        OR p_provider_subject_id LIKE 'legacy:%'
        OR EXISTS (SELECT 1 FROM subscription_connections connection
          WHERE connection.account_id = p_account_id AND connection.provider = p_provider
            AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider) AND connection.ownership = 'personal'
            AND connection.owner_organization_membership_id = owner_membership
            AND connection.provider_account_id = p_provider_account_id
            AND (connection.provider_subject_id IS NULL OR connection.provider_subject_id LIKE 'legacy:%'))
      THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'identity_unverified'; RETURN NEXT; RETURN;
      END IF;
      IF p_provider_account_id IS NOT NULL THEN
        SELECT connection.id INTO existing_id
        FROM subscription_connections connection
        WHERE connection.account_id = p_account_id AND connection.provider = p_provider
          AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider) AND connection.ownership = 'personal'
          AND connection.owner_organization_membership_id = owner_membership
          AND connection.provider_account_id = p_provider_account_id
          AND connection.provider_subject_id = p_provider_subject_id;
      END IF;
      IF existing_id IS NOT NULL THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          'subscription-refresh:' || existing_id::text, 0));
        PERFORM 1 FROM subscription_connections connection
        WHERE connection.account_id = p_account_id AND connection.id = existing_id
        FOR UPDATE;
        UPDATE subscription_connections connection SET
          credential_encrypted = p_credential_encrypted, credential_format = p_credential_format,
          expires_at = p_expires_at, last_refresh_at = p_last_refresh_at,
          refresh_generation = connection.refresh_generation + 1,
          version = connection.version + 1, status = 'active', last_error = NULL,
          plan_type = coalesce(p_plan_type, connection.plan_type),
          provider_state = connection.provider_state || coalesce(p_provider_state, '{}'::jsonb),
          account_email = coalesce(p_account_email, connection.account_email),
          label = coalesce(connection.label, p_label),
          connected_by_subject_id = p_connected_by_subject_id, updated_at = clock_timestamp()
        WHERE connection.account_id = p_account_id AND connection.id = existing_id;
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        outcome := 'connected'; connection_id := existing_id; is_new := false;
        RETURN NEXT; RETURN;
      END IF;
      SELECT max(resource.generation) INTO authority_gen
      FROM subscription_connections connection
      JOIN organization_user_resource_authorities resource
        ON resource.account_id = connection.account_id AND resource.id = connection.authority_id
       AND resource.status = 'active' AND resource.revoked_at IS NULL
      WHERE connection.account_id = p_account_id AND connection.provider = p_provider
        AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND connection.ownership = 'personal'
        AND connection.owner_organization_membership_id = owner_membership;
      IF authority_gen IS NULL THEN
        SELECT coalesce(max(resource.generation), 0) + 1 INTO authority_gen
        FROM organization_user_resource_authorities resource
        WHERE resource.account_id = p_account_id
          AND resource.organization_membership_id = owner_membership
          AND resource.resource_kind = 'subscription_connection';
      END IF;
      new_id := gen_random_uuid();
      INSERT INTO organization_user_resource_authorities (
        account_id, organization_membership_id, resource_kind, resource_id,
        origin_workspace_id, generation, status
      ) VALUES (
        p_account_id, owner_membership, 'subscription_connection', new_id, p_workspace_id,
        authority_gen, 'active'
      ) RETURNING id INTO authority;
      INSERT INTO subscription_connections (
        id, account_id, provider, kind, provider_account_id, provider_subject_id, account_email, label, plan_type,
        credential_encrypted, credential_format, expires_at, last_refresh_at, status,
        ownership, owner_organization_membership_id, owner_subject_id, authority_id,
        authority_resource_kind, authority_generation, connected_by_subject_id, scope_kind,
        allow_personal_workspaces, managed_by_workspace_id, provider_state
      ) VALUES (
        new_id, p_account_id, p_provider, opengeni_private.subscription_core_connection_kind(p_provider), p_provider_account_id, p_provider_subject_id, p_account_email,
        p_label, p_plan_type, p_credential_encrypted, p_credential_format, p_expires_at, p_last_refresh_at,
        'active', 'personal', owner_membership, p_subject_id, authority,
        'subscription_connection', authority_gen, p_connected_by_subject_id, 'people', true, NULL,
        coalesce(p_provider_state, '{}'::jsonb)
      );
      PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
      outcome := 'connected'; connection_id := new_id; is_new := true;
      RETURN NEXT;
    END
    $_$;

CREATE FUNCTION opengeni_private.connected_command_output_release_due_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_session_background_commands command
        WHERE command.provider = 'connected_machine' AND command.state = 'exited'
          AND command.output_release_observed_at IS NULL
          AND command.output_unavailable_at IS NULL
          AND command.reconcile_after <= now()
          AND opengeni_private.maintenance_probe_output_runner_eligible_v1(
            command.control_workspace_id, command.enrollment_id, command.connection_instance_id)
      )
    $$;

CREATE FUNCTION opengeni_private.connected_command_reconciliation_due_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_session_background_commands command
        WHERE command.state IN ('running', 'stopping')
          AND command.reconcile_after <= now()
          AND command.provider = 'connected_machine'
          AND NOT EXISTS (SELECT 1 FROM opengeni_private.maintenance_probe_enrollments enrollment WHERE enrollment.id = command.enrollment_id AND enrollment.workspace_id = command.control_workspace_id AND (enrollment.kind = 'sandbox' OR command.last_reconcile_outcome = 'provider_unanswered') AND enrollment.status <> 'revoked' AND (enrollment.connection_instance_id IS NULL OR enrollment.connection_instance_id = command.connection_instance_id) AND command.state = 'running' AND command.completion_notified_at IS NULL AND command.reconcile_proof_outcome IS NULL)
      )
    $$;

CREATE FUNCTION opengeni_private.connected_output_runner_eligible_v1(p_workspace_id uuid, p_enrollment_id uuid, p_connection_instance_id text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM {{schema}}.enrollments enrollment
        WHERE enrollment.workspace_id = p_workspace_id
          AND enrollment.id = p_enrollment_id
          AND (
            enrollment.status = 'revoked'
            OR (enrollment.connection_instance_id IS NOT NULL
              AND enrollment.connection_instance_id <> p_connection_instance_id)
            OR (enrollment.connection_instance_id IS NULL
              AND enrollment.went_offline_reason IN (
                'GOING_OFFLINE_REASON_USER_STOP',
                'GOING_OFFLINE_REASON_UPDATE',
                'GOING_OFFLINE_REASON_HOST_SHUTDOWN'))
            OR (enrollment.status = 'active'
              AND enrollment.connection_instance_id = p_connection_instance_id
              AND enrollment.connection_lease_expires_at > now()
              AND enrollment.went_offline_at IS NULL)
          )
      )
    $$;

CREATE FUNCTION opengeni_private.connection_account_intent_is_valid(intent jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT intent IS NULL OR (
    jsonb_typeof(intent) = 'object'
    AND intent - ARRAY['version','principal','selections'] = '{}'::jsonb
    AND intent -> 'version' = '1'::jsonb
    AND jsonb_typeof(intent -> 'principal') = 'object'
    AND (
      (intent #>> '{principal,kind}' = 'none' AND intent -> 'principal' = '{"kind":"none"}'::jsonb)
      OR (intent #>> '{principal,kind}' = 'subject'
        AND (intent -> 'principal') - ARRAY['kind','subjectId'] = '{}'::jsonb
        AND jsonb_typeof(intent #> '{principal,subjectId}') = 'string'
        AND length(intent #>> '{principal,subjectId}') BETWEEN 1 AND 512)
    )
    AND jsonb_typeof(intent -> 'selections') = 'array'
    AND jsonb_array_length(intent -> 'selections') <= 128
  )
$$;

CREATE FUNCTION opengeni_private.connection_tenancy_backfill_capability_active(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'opengeni_private'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM opengeni_private.connection_tenancy_backfill_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND capability.account_id = p_account_id
  )
$$;

CREATE FUNCTION opengeni_private.consume_editable_artifact_live_ticket(p_token_digest text, p_data_schema name DEFAULT "current_schema"()) RETURNS TABLE(token_digest text, account_id uuid, workspace_id uuid, artifact_id text, modality text, actor_kind text, actor_subject_id text, replica_id text, agent_session_id text, agent_turn_id text, agent_attempt_id text, agent_generation integer, service_name text, allow_edit boolean, protocol_version integer, issued_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
BEGIN
  IF p_token_digest !~ '^sha256:[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'editable artifact live ticket digest is malformed'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_ticket_data_schema(
    p_data_schema
  );
  RETURN QUERY EXECUTE pg_catalog.format($query$
    WITH consumed AS (
      DELETE FROM %I.editable_artifact_live_tickets ticket
      WHERE ticket.token_digest = $1
      RETURNING ticket.token_digest, ticket.account_id, ticket.workspace_id,
        ticket.artifact_id, ticket.modality, ticket.actor_kind,
        ticket.actor_subject_id, ticket.replica_id, ticket.agent_session_id,
        ticket.agent_turn_id, ticket.agent_attempt_id, ticket.agent_generation,
        ticket.service_name, ticket.allow_edit, ticket.protocol_version,
        ticket.issued_at, ticket.expires_at
    )
    SELECT consumed.*
    FROM consumed
    WHERE consumed.expires_at > pg_catalog.clock_timestamp()
  $query$, data_schema) USING p_token_digest;
END;
$_$;

CREATE FUNCTION opengeni_private.context_compaction_pending_summary() RETURNS TABLE(pending_count bigint, oldest_started_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT
    count(*)::bigint AS pending_count,
    min(pending.started_at) AS oldest_started_at
  FROM opengeni_private.context_compaction_pending_observations pending
$$;

CREATE FUNCTION opengeni_private.continue_session_waiting_work_v1(p_account_id uuid, p_workspace_id uuid, p_session_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  chat sessions%ROWTYPE;
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  access jsonb;
  context_human text;
  continued integer;
BEGIN
  IF caller_subject IS NULL
    OR p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
  THEN RAISE EXCEPTION 'waiting work can only be continued by its machine owner' USING ERRCODE = '42501'; END IF;
  -- The caller's own RLS view of the chat: lock it against a concurrent claim.
  SELECT * INTO chat FROM sessions
  WHERE id = p_session_id AND workspace_id = p_workspace_id AND account_id = p_account_id
  FOR UPDATE;
  IF chat.id IS NULL OR chat.active_sandbox_id IS NULL THEN
    RAISE EXCEPTION 'waiting work can only be continued by its machine owner' USING ERRCODE = '42501';
  END IF;
  access := get_session_machine_access(p_account_id, p_workspace_id, p_session_id);
  IF access IS NULL OR access ->> 'sandboxId' IS DISTINCT FROM chat.active_sandbox_id::text
    OR (access ->> 'isOwner')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'waiting work can only be continued by its machine owner' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(context.initiating_human_subject_id,
      CASE WHEN context.initiator_kind = 'subject' THEN context.initiator_subject_id END)
    INTO context_human
  FROM session_turns context
  WHERE context.id = chat.execution_context_turn_id AND context.session_id = chat.id
    AND context.workspace_id = p_workspace_id AND context.account_id = p_account_id;
  IF context_human IS DISTINCT FROM caller_subject THEN
    RAISE EXCEPTION 'the chat is not continuing your own work yet' USING ERRCODE = '55000';
  END IF;

  UPDATE session_system_updates waiting_update
  SET continued_by_subject_id = caller_subject, continued_at = clock_timestamp()
  WHERE waiting_update.workspace_id = p_workspace_id AND waiting_update.session_id = p_session_id
    AND waiting_update.account_id = p_account_id
    AND waiting_update.state = 'pending' AND waiting_update.scheduled_task_run_id IS NULL
    AND (waiting_update.kind = 'agent_message' OR waiting_update.kind LIKE 'child_%')
    AND waiting_update.continued_by_subject_id IS NULL
    AND opengeni_private.informational_update_origin_human_v1(
      waiting_update.account_id, waiting_update.workspace_id, waiting_update.session_id,
      waiting_update.kind, waiting_update.lineage) IS DISTINCT FROM caller_subject;
  GET DIAGNOSTICS continued = ROW_COUNT;
  RETURN continued;
END
$$;

CREATE FUNCTION opengeni_private.copy_subscription_authority_compat(p_provider text, p_carrier_kind text, p_workspace_id uuid, p_carrier_id uuid, p_task_authority_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  committed timestamptz;
  carrier_state record;
  expected record;
  stored opengeni_private.subscription_authority_compat%ROWTYPE;
  prior text[];
BEGIN
  SELECT receipt.committed_at INTO committed
  FROM opengeni_private.subscription_provider_cutover_receipts receipt
  WHERE receipt.provider = p_provider AND receipt.committed_at > '-infinity'::timestamptz;
  IF committed IS NULL THEN RETURN false; END IF;
  IF p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid THEN
    RAISE EXCEPTION 'subscription authority carrier is outside the current workspace'
      USING ERRCODE = '42501';
  END IF;
  -- Visible to the caller under its own row security, and inserted by this
  -- transaction: a record is copied once, when its carrier is accepted.
  SELECT * INTO carrier_state FROM opengeni_subscription_internal.subscription_compat_carrier_state(
    p_carrier_kind, p_workspace_id, p_carrier_id, p_task_authority_revision);
  IF carrier_state.inserted_at IS NULL
    OR carrier_state.account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
  THEN
    RAISE EXCEPTION 'subscription authority carrier is not visible' USING ERRCODE = '42501';
  END IF;
  IF carrier_state.inserted_at <> pg_catalog.transaction_timestamp() THEN
    RAISE EXCEPTION 'subscription authority is copied only into a carrier this transaction inserted'
      USING ERRCODE = '55000';
  END IF;
  prior := opengeni_subscription_internal.subscription_compat_enter_scope(
    carrier_state.account_id, p_workspace_id);
  SELECT * INTO expected FROM opengeni_subscription_internal.subscription_compat_carrier_expected(
    p_provider, committed, p_carrier_kind, p_workspace_id, p_carrier_id, p_task_authority_revision);
  IF expected.has_record THEN
    INSERT INTO opengeni_private.subscription_authority_compat (
      account_id, workspace_id, provider, carrier_kind, session_id, turn_id, scheduled_task_id,
      task_authority_revision, system_update_id, outbox_id, personal, shared_pool, legacy_scope,
      owner_subject_id
    ) VALUES (
      carrier_state.account_id, p_workspace_id, p_provider, p_carrier_kind,
      CASE WHEN p_carrier_kind = 'session_initial' THEN p_carrier_id END,
      CASE WHEN p_carrier_kind = 'session_turn' THEN p_carrier_id END,
      CASE WHEN p_carrier_kind IN ('scheduled_task', 'scheduled_task_revision') THEN p_carrier_id END,
      CASE WHEN p_carrier_kind = 'scheduled_task_revision' THEN p_task_authority_revision END,
      CASE WHEN p_carrier_kind = 'session_system_update' THEN p_carrier_id END,
      CASE WHEN p_carrier_kind = 'session_system_update_outbox' THEN p_carrier_id END,
      expected.personal, expected.shared_pool, expected.legacy_scope, expected.owner_subject_id
    ) ON CONFLICT DO NOTHING;
    SELECT * INTO stored FROM opengeni_subscription_internal.subscription_compat_record(
      p_provider, p_carrier_kind, p_workspace_id, p_carrier_id, p_task_authority_revision);
    IF stored.personal IS DISTINCT FROM expected.personal
      OR stored.shared_pool IS DISTINCT FROM expected.shared_pool
      OR stored.legacy_scope IS DISTINCT FROM expected.legacy_scope
      OR stored.owner_subject_id IS DISTINCT FROM expected.owner_subject_id
    THEN
      RAISE EXCEPTION 'subscription authority compatibility record mismatch for % % (%)',
        p_carrier_kind, p_carrier_id, p_provider USING ERRCODE = '23514';
    END IF;
  END IF;
  PERFORM opengeni_subscription_internal.subscription_compat_leave_scope(prior);
  RETURN expected.has_record;
END
$$;

CREATE FUNCTION opengeni_private.count_active_retained_processes_by_owner_state() RETURNS TABLE(owner_state text, active_count bigint, terminal_owner_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        IF NOT EXISTS (SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_retained_processes WHERE state='active') THEN RETURN; END IF;
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'inventory');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_inventory_retained_inner();
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $$;

CREATE FUNCTION opengeni_private.count_active_users() RETURNS TABLE(time_window text, user_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH recent AS (
    SELECT presence.last_seen_at
    FROM opengeni_private.user_activity_presence presence
    WHERE presence.last_seen_at >= now() - interval '30 days'
  )
  SELECT window_row.time_window,
    (SELECT count(*) FROM recent WHERE recent.last_seen_at >= now() - window_row.span)::bigint
  FROM (VALUES
    ('5m', interval '5 minutes'),
    ('15m', interval '15 minutes'),
    ('1h', interval '1 hour'),
    ('24h', interval '24 hours'),
    ('7d', interval '7 days'),
    ('30d', interval '30 days')
  ) AS window_row(time_window, span)
$$;

CREATE FUNCTION opengeni_private.count_expired_draining_sandbox_leases() RETURNS TABLE(backend text, age_bucket text, count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        IF NOT EXISTS (SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_leases WHERE liveness='draining') THEN RETURN; END IF;
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'inventory');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_inventory_draining_inner();
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $$;

CREATE FUNCTION opengeni_private.count_queued_turns() RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    AS $$
  SELECT count(*)::bigint
  FROM session_turns
  WHERE status = 'queued';
$$;

CREATE FUNCTION opengeni_private.count_sandbox_leases_by_liveness() RETURNS TABLE(liveness text, count bigint)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  SELECT L.liveness, count(*)::bigint
  FROM sandbox_leases L
  GROUP BY L.liveness;
$$;

CREATE FUNCTION opengeni_private.count_session_recovery_backlog() RETURNS TABLE(state text, count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  SELECT summary.state, summary.count
  FROM opengeni_private.summarize_session_recovery_backlog() summary
  ORDER BY summary.state;
$$;

CREATE FUNCTION opengeni_private.credit_balance_by_account() RETURNS TABLE(account_id uuid, balance_micros bigint)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  SELECT L.account_id, coalesce(sum(L.amount_micros), 0)::bigint AS balance_micros
  FROM credit_ledger_entries L
  GROUP BY L.account_id
  ORDER BY L.account_id;
$$;

CREATE FUNCTION opengeni_private.credit_grant_class(p_type text, p_source_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN p_source_type = 'verified_signup_trial' THEN 'signup_trial'
    WHEN p_source_type = 'stripe_checkout_coupon' THEN 'coupon'
    WHEN p_type = 'manual_credit_grant' OR p_source_type = 'operator_adjustment' THEN 'manual'
    ELSE 'other'
  END
$$;

CREATE FUNCTION opengeni_private.credit_grant_totals() RETURNS TABLE(grant_class text, grant_count bigint, granted_micros bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT class.name,
    count(observation.ledger_entry_id)::bigint,
    coalesce(sum(observation.amount_micros), 0)::bigint
  FROM (VALUES ('signup_trial'), ('coupon'), ('manual'), ('other')) AS class(name)
  LEFT JOIN opengeni_private.credit_grant_observations observation
    ON observation.grant_class = class.name
  GROUP BY class.name
  ORDER BY class.name
$$;

