CREATE FUNCTION opengeni_private.dead_letter_editable_artifact_live_outbox(p_outbox_id text, p_owner text, p_attempt_count integer, p_error_code text, p_data_schema name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE affected integer;
DECLARE data_schema name;
BEGIN
  IF p_outbox_id IS NULL OR p_outbox_id !~ '^[0-9a-f]{32}$' OR p_outbox_id ~ '^0+$'
    OR p_owner IS NULL OR pg_catalog.octet_length(p_owner) NOT BETWEEN 1 AND 256
    OR p_attempt_count IS NULL OR p_attempt_count NOT BETWEEN 1 AND 1000000
    OR p_error_code NOT IN ('invalid_hint', 'oversized_hint')
    OR p_data_schema IS NULL
  THEN
    RAISE EXCEPTION 'invalid editable artifact outbox dead-letter bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  EXECUTE pg_catalog.format($query$
    UPDATE %I.editable_artifact_live_outbox target
    SET state = 'dead_lettered', lease_owner = NULL, lease_expires_at = NULL,
      last_error_code = $4, dead_lettered_at = pg_catalog.statement_timestamp()
    WHERE target.id = $1
      AND target.state = 'publishing'
      AND target.lease_owner = $2
      AND target.attempt_count = $3
      AND target.lease_expires_at > pg_catalog.statement_timestamp()
  $query$, data_schema)
  USING p_outbox_id, p_owner, p_attempt_count, p_error_code;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected = 1 THEN RETURN true; END IF;
  EXECUTE pg_catalog.format($query$
    SELECT count(*)::integer
    FROM %I.editable_artifact_live_outbox target
    WHERE target.id = $1 AND target.state = 'dead_lettered'
      AND target.attempt_count = $2 AND target.last_error_code = $3
  $query$, data_schema) INTO affected
  USING p_outbox_id, p_attempt_count, p_error_code;
  RETURN affected = 1;
END;
$_$;

CREATE FUNCTION opengeni_private.default_interaction_device_workspace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.device_id IS NULL THEN
    NEW.device_workspace_id := NULL;
  ELSIF NEW.device_workspace_id IS NULL THEN
    NEW.device_workspace_id := NEW.workspace_id;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.defer_workspace_cascade_foreign_keys() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    DECLARE
      constraint_names text;
    BEGIN
      -- Every table a workspace deletion removes, through cascading keys.
      WITH RECURSIVE removed(relation_id) AS (
        SELECT '{{schema}}.workspaces'::regclass::oid
        UNION
        SELECT c.conrelid
        FROM pg_constraint c
        JOIN removed ON c.confrelid = removed.relation_id
        WHERE c.contype = 'f' AND c.confdeltype = 'c' AND c.conparentid = 0
      )
      SELECT string_agg(DISTINCT format('%I.%I', n.nspname, c.conname), ', ')
      INTO constraint_names
      FROM pg_constraint c
      JOIN pg_namespace n ON n.oid = c.connamespace
      WHERE c.contype = 'f' AND c.conparentid = 0
        AND c.condeferrable AND c.confdeltype = 'a'
        AND c.conrelid IN (SELECT relation_id FROM removed)
        AND c.confrelid IN (SELECT relation_id FROM removed);
      IF constraint_names IS NOT NULL THEN
        EXECUTE 'SET CONSTRAINTS ' || constraint_names || ' DEFERRED';
      END IF;
    END
    $$;

CREATE FUNCTION opengeni_private.detach_retention_variable_set_session_selections(p_account_id uuid, p_membership_id uuid, p_operation_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  workspace_id_value uuid;
  session_row sessions%ROWTYPE;
  group_member_id uuid;
  previous_ids jsonb;
  next_ids jsonb;
  removed_ids jsonb;
  next_last_id uuid;
  affected_session_ids uuid[];
  activity_revision_value bigint;
  detached_sessions integer := 0;
  previous_workspace text := current_setting('opengeni.workspace_id', true);
  previous_gate_state text := current_setting('opengeni.session_activity_gate_state', true);
  previous_gate_workspace text := current_setting(
    'opengeni.session_activity_gate_workspace_id', true
  );
  finalized_session_count integer;
  write_capability_preexisting boolean;
  fenced_access_capability_id uuid;
BEGIN
  IF p_account_id IS NULL OR p_membership_id IS NULL OR p_operation_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR current_setting('opengeni.organization_tenancy_lifecycle', true)
      IS DISTINCT FROM 'organization_membership_lifecycle'
    OR nullif(previous_gate_state, '') IS NOT NULL
    OR nullif(previous_gate_workspace, '') IS NOT NULL
  THEN
    RAISE EXCEPTION 'retention Variable Set detach authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM organization_memberships membership
    JOIN organization_user_retention_deletions deletion
      ON deletion.account_id = membership.account_id
     AND deletion.membership_id = membership.id
    WHERE membership.account_id = p_account_id
      AND membership.id = p_membership_id
      AND membership.status = 'revoked'
      AND membership.personal_retention_until IS NOT NULL
      AND membership.personal_retention_until <= clock_timestamp()
      AND deletion.state = 'claimed'
      AND deletion.claim_operation_id = p_operation_id
      AND deletion.claim_expires_at > clock_timestamp()
      AND deletion.database_finalized_at IS NULL
  ) THEN
    RAISE EXCEPTION 'retention Variable Set detach claim is stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT opengeni_private.variable_set_authority_capability_active('write')
  INTO write_capability_preexisting;
  INSERT INTO opengeni_private.variable_set_authority_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'write')
  ON CONFLICT DO NOTHING;
  fenced_access_capability_id :=
    opengeni_private.open_session_tenancy_fenced_access(
      session_tenancy_fence_target_schema()
    );

  FOR workspace_id_value IN
    SELECT DISTINCT session_value.workspace_id
    FROM sessions session_value
    WHERE session_value.account_id = p_account_id
      AND EXISTS (
        SELECT 1
        FROM session_variable_set_attachments attachment
        JOIN workspace_variable_sets variable_set
          ON variable_set.account_id = p_account_id
         AND variable_set.id = attachment.variable_set_id
        JOIN organization_user_resource_authorities authority
          ON authority.account_id = variable_set.account_id
         AND authority.id = variable_set.authority_id
         AND authority.organization_membership_id = p_membership_id
         AND authority.resource_kind = 'variable_set'
         AND authority.resource_id = variable_set.id
        WHERE attachment.account_id = p_account_id
          AND attachment.workspace_id = session_value.workspace_id
          AND attachment.session_id = session_value.id
          AND variable_set.owner_organization_membership_id = p_membership_id
      )
    ORDER BY session_value.workspace_id
  LOOP
    PERFORM set_config('opengeni.workspace_id', workspace_id_value::text, true);
    PERFORM 1 FROM workspace_inference_controls control
    WHERE control.account_id = p_account_id
      AND control.workspace_id = workspace_id_value
    FOR SHARE;
    PERFORM 1 FROM workspaces workspace
    WHERE workspace.account_id = p_account_id
      AND workspace.id = workspace_id_value
    FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'retention Variable Set detach workspace is unavailable'
        USING ERRCODE = '40001';
    END IF;

    affected_session_ids := ARRAY[]::uuid[];
    FOR session_row IN
      SELECT session_value.*
      FROM sessions session_value
      WHERE session_value.account_id = p_account_id
        AND session_value.workspace_id = workspace_id_value
        AND EXISTS (
          SELECT 1
          FROM session_variable_set_attachments attachment
          JOIN workspace_variable_sets variable_set
            ON variable_set.account_id = p_account_id
           AND variable_set.id = attachment.variable_set_id
          JOIN organization_user_resource_authorities authority
            ON authority.account_id = variable_set.account_id
           AND authority.id = variable_set.authority_id
           AND authority.organization_membership_id = p_membership_id
           AND authority.resource_kind = 'variable_set'
           AND authority.resource_id = variable_set.id
          WHERE attachment.account_id = p_account_id
            AND attachment.workspace_id = session_value.workspace_id
            AND attachment.session_id = session_value.id
            AND variable_set.owner_organization_membership_id = p_membership_id
        )
      ORDER BY session_value.id
      FOR NO KEY UPDATE
    LOOP
      IF (
          session_row.owner_organization_membership_id IS NOT NULL
          AND session_row.owner_organization_membership_id IS DISTINCT FROM p_membership_id
        )
        OR session_row.active_turn_id IS NOT NULL
        OR session_row.status NOT IN ('queued', 'idle', 'failed', 'cancelled')
      THEN
        RAISE EXCEPTION 'retention Variable Set detach requires a quiescent eligible session'
          USING ERRCODE = '55000';
      END IF;
      PERFORM assert_session_tenancy_quiescent(
        p_account_id, workspace_id_value, session_row.id, false
      );
      IF EXISTS (
        SELECT 1 FROM sessions group_member
        WHERE group_member.account_id = p_account_id
          AND group_member.workspace_id = workspace_id_value
          AND group_member.sandbox_group_id = session_row.sandbox_group_id
          AND (
            (
              group_member.owner_organization_membership_id IS NOT NULL
              AND group_member.owner_organization_membership_id
                IS DISTINCT FROM p_membership_id
            )
            OR group_member.active_turn_id IS NOT NULL
            OR group_member.status NOT IN ('queued', 'idle', 'failed', 'cancelled')
          )
      ) THEN
        RAISE EXCEPTION 'retention Variable Set detach cannot rotate a foreign or active sandbox group'
          USING ERRCODE = '55000';
      END IF;
      FOR group_member_id IN
        SELECT group_member.id
        FROM sessions group_member
        WHERE group_member.account_id = p_account_id
          AND group_member.workspace_id = workspace_id_value
          AND group_member.sandbox_group_id = session_row.sandbox_group_id
        ORDER BY group_member.id
      LOOP
        PERFORM assert_session_tenancy_quiescent(
          p_account_id, workspace_id_value, group_member_id, false
        );
      END LOOP;

      PERFORM pg_advisory_xact_lock(hashtextextended(
        'sandbox-lease-admission:' || workspace_id_value::text || ':'
          || session_row.sandbox_group_id::text,
        0
      ));
      PERFORM 1 FROM sandbox_leases lease
      WHERE lease.account_id = p_account_id
        AND lease.workspace_id = workspace_id_value
        AND lease.sandbox_group_id = session_row.sandbox_group_id
      FOR UPDATE;
      IF EXISTS (
        SELECT 1 FROM sandbox_lease_holders holder
        JOIN sandbox_leases lease ON lease.id = holder.lease_id
        WHERE lease.account_id = p_account_id
          AND lease.workspace_id = workspace_id_value
          AND lease.sandbox_group_id = session_row.sandbox_group_id
      ) THEN
        RAISE EXCEPTION 'retention Variable Set detach requires an unheld sandbox group'
          USING ERRCODE = '55000';
      END IF;

      previous_ids := coalesce(
        session_row.variable_set_ids,
        CASE WHEN session_row.variable_set_id IS NULL THEN '[]'::jsonb
          ELSE jsonb_build_array(session_row.variable_set_id::text) END
      );
      SELECT coalesce(jsonb_agg(selected.value ORDER BY selected.position)
          FILTER (WHERE variable_set.id IS NULL), '[]'::jsonb),
        coalesce(jsonb_agg(selected.value ORDER BY selected.position)
          FILTER (WHERE variable_set.id IS NOT NULL), '[]'::jsonb)
      INTO next_ids, removed_ids
      FROM jsonb_array_elements_text(previous_ids)
        WITH ORDINALITY selected(value, position)
      LEFT JOIN workspace_variable_sets variable_set
        ON variable_set.account_id = p_account_id
       AND variable_set.id = selected.value::uuid
       AND variable_set.owner_organization_membership_id = p_membership_id
       AND EXISTS (
         SELECT 1 FROM organization_user_resource_authorities authority
         WHERE authority.account_id = p_account_id
           AND authority.id = variable_set.authority_id
           AND authority.organization_membership_id = p_membership_id
           AND authority.resource_kind = 'variable_set'
           AND authority.resource_id = variable_set.id
       );
      IF removed_ids = '[]'::jsonb THEN
        RAISE EXCEPTION 'retention Variable Set detach projection drifted from the session selection'
          USING ERRCODE = '55000';
      END IF;
      SELECT selected.value::uuid INTO next_last_id
      FROM jsonb_array_elements_text(next_ids)
        WITH ORDINALITY selected(value, position)
      ORDER BY selected.position DESC
      LIMIT 1;

      SET CONSTRAINTS sessions_activity_insert_commit_guard,
        sessions_activity_update_commit_guard DEFERRED;
      PERFORM set_config('opengeni.session_activity_gate_state', 'open', true);
      PERFORM set_config(
        'opengeni.session_activity_gate_workspace_id', workspace_id_value::text, true
      );
      UPDATE sessions affected SET
        variable_set_ids = next_ids,
        variable_set_id = next_last_id,
        last_sequence = affected.last_sequence + 1,
        updated_at = clock_timestamp()
      WHERE affected.account_id = p_account_id
        AND affected.workspace_id = workspace_id_value
        AND affected.id = session_row.id;
      INSERT INTO session_events (
        account_id, workspace_id, session_id, sequence, type, payload,
        payload_codec_version, occurred_at
      ) VALUES (
        p_account_id, workspace_id_value, session_row.id,
        session_row.last_sequence + 1, 'session.variable_sets.updated',
        jsonb_build_object(
          'actor', 'service:organization_retention',
          'organizationMembershipId', p_membership_id,
          'operationId', p_operation_id,
          'variableSetIds', next_ids,
          'removedIds', removed_ids,
          'collisionPolicy', 'later_selected_set_wins',
          'effectiveOn', 'next_turn_or_sandbox_operation',
          'reason', 'owner_retention_deleted'
        ), 1, clock_timestamp()
      );
      INSERT INTO audit_events (
        account_id, workspace_id, subject_id, action, target_type, target_id,
        metadata, metadata_codec_version
      )
      SELECT p_account_id, workspace_id_value, NULL,
        'session.variable_set.detached', 'session', session_row.id::text,
        jsonb_build_object(
          'actorKind', 'service',
          'organizationMembershipId', p_membership_id,
          'operationId', p_operation_id,
          'variableSetId', removed.value,
          'reason', 'owner_retention_deleted'
        ), 1
      FROM jsonb_array_elements_text(removed_ids) removed(value);
      UPDATE sandbox_leases lease SET
        rotation_requested_at = coalesce(lease.rotation_requested_at, clock_timestamp()),
        rotation_reason = coalesce(lease.rotation_reason, 'operator'),
        expires_at = least(lease.expires_at, clock_timestamp()),
        updated_at = clock_timestamp()
      WHERE lease.account_id = p_account_id
        AND lease.workspace_id = workspace_id_value
        AND lease.sandbox_group_id = session_row.sandbox_group_id
        AND lease.liveness <> 'cold';

      affected_session_ids := array_append(affected_session_ids, session_row.id);
      detached_sessions := detached_sessions + 1;
    END LOOP;

    IF coalesce(array_length(affected_session_ids, 1), 0) > 0 THEN
      PERFORM set_config('opengeni.session_activity_gate_state', 'preparing', true);
      SET CONSTRAINTS ALL IMMEDIATE;
      SET CONSTRAINTS sessions_activity_insert_commit_guard,
        sessions_activity_update_commit_guard DEFERRED;
      PERFORM set_config('opengeni.session_activity_gate_state', 'finalizing', true);
      UPDATE workspace_session_activity_revisions counter
      SET revision = counter.revision + 1
      WHERE counter.account_id = p_account_id
        AND counter.workspace_id = workspace_id_value
      RETURNING counter.revision INTO activity_revision_value;
      IF activity_revision_value IS NULL THEN
        RAISE EXCEPTION 'retention Variable Set detach activity counter is unavailable'
          USING ERRCODE = '55000';
      END IF;
      UPDATE sessions affected SET
        activity_revision = activity_revision_value,
        activity_revision_pending_xid = NULL
      WHERE affected.account_id = p_account_id
        AND affected.workspace_id = workspace_id_value
        AND affected.id = ANY(affected_session_ids)
        AND affected.activity_revision_pending_xid = pg_current_xact_id()::text::bigint;
      GET DIAGNOSTICS finalized_session_count = ROW_COUNT;
      IF finalized_session_count <> array_length(affected_session_ids, 1) THEN
        RAISE EXCEPTION 'retention Variable Set detach activity was not finalized'
          USING ERRCODE = '55000';
      END IF;
      SET CONSTRAINTS sessions_activity_insert_commit_guard,
        sessions_activity_update_commit_guard IMMEDIATE;
      PERFORM set_config('opengeni.session_activity_gate_state', '', true);
      PERFORM set_config('opengeni.session_activity_gate_workspace_id', '', true);
    END IF;
  END LOOP;
  PERFORM opengeni_private.close_session_tenancy_fenced_access(
    fenced_access_capability_id
  );
  IF NOT write_capability_preexisting THEN
    DELETE FROM opengeni_private.variable_set_authority_capabilities
    WHERE backend_pid = pg_backend_pid()
      AND transaction_id = pg_current_xact_id_if_assigned()
      AND capability_kind = 'write';
  END IF;
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace, ''), true);
  RETURN detached_sessions;
EXCEPTION WHEN OTHERS THEN
  PERFORM opengeni_private.close_session_tenancy_fenced_access(
    fenced_access_capability_id
  );
  IF NOT coalesce(write_capability_preexisting, false) THEN
    DELETE FROM opengeni_private.variable_set_authority_capabilities
    WHERE backend_pid = pg_backend_pid()
      AND transaction_id = pg_current_xact_id_if_assigned()
      AND capability_kind = 'write';
  END IF;
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace, ''), true);
  PERFORM set_config(
    'opengeni.session_activity_gate_state', coalesce(previous_gate_state, ''), true
  );
  PERFORM set_config(
    'opengeni.session_activity_gate_workspace_id',
    coalesce(previous_gate_workspace, ''), true
  );
  RAISE;
END
$$;

CREATE FUNCTION opengeni_private.disconnect_subscription_core_connection(p_provider text, p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_connection_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      target subscription_connections%ROWTYPE;
      owner_personal_workspace uuid;
    BEGIN
      IF NOT opengeni_subscription_internal.subscription_core_writer_context(
          p_provider, p_account_id, p_workspace_id, p_subject_id) OR p_connection_id IS NULL THEN
        RETURN 'refused';
      END IF;
      PERFORM opengeni_subscription_internal.grant_subscription_core_owner_capability(
        p_provider, 'connection_owner', p_account_id, p_workspace_id, p_subject_id, p_connection_id);
      SELECT connection.* INTO target FROM subscription_connections connection
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
        AND connection.provider = p_provider AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider);
      IF NOT FOUND THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        RETURN 'not_found';
      END IF;
      IF target.ownership = 'shared' THEN
        -- An organization administrator removes any shared connection; the
        -- managing workspace's administrator only the workspace's own
        -- account (migration 0777).
        IF NOT opengeni_private.subscription_organization_admin(p_account_id)
          AND NOT (target.scope_kind = 'workspaces'
            AND NOT target.allow_personal_workspaces
            AND p_workspace_id IS NOT NULL
            AND target.managed_by_workspace_id = p_workspace_id
            AND EXISTS (SELECT 1 FROM workspace_memberships manager
              WHERE manager.account_id = p_account_id AND manager.workspace_id = p_workspace_id
                AND manager.subject_id = p_subject_id AND opengeni_private.workspace_membership_administers(manager.role, manager.permissions))
            AND NOT EXISTS (SELECT 1 FROM subscription_connection_workspaces assignment
              WHERE assignment.account_id = p_account_id
                AND assignment.connection_id = p_connection_id
                AND assignment.workspace_id <> p_workspace_id))
        THEN
          PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
          RETURN 'forbidden';
        END IF;
      ELSE
        SELECT membership.personal_workspace_id INTO owner_personal_workspace
        FROM organization_memberships membership
        WHERE membership.account_id = p_account_id
          AND membership.id = target.owner_organization_membership_id
          AND membership.subject_id = p_subject_id;
        IF target.owner_subject_id IS DISTINCT FROM p_subject_id
          OR owner_personal_workspace IS DISTINCT FROM p_workspace_id THEN
          PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
          RETURN 'not_found';
        END IF;
      END IF;
      IF target.ownership = 'personal' THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          'subscription-personal-authority:' || p_account_id::text || ':' ||
          target.owner_organization_membership_id::text, 0));
      END IF;
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'subscription-refresh:' || p_connection_id::text, 0));
      PERFORM 1 FROM subscription_connections connection
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
      FOR UPDATE;
      UPDATE subscription_connections connection SET
        disconnected_at = coalesce(connection.disconnected_at, clock_timestamp()),
        status = 'disabled', credential_encrypted = '', provider_account_id = NULL,
        allocator_enabled = false, expires_at = NULL, last_error = NULL,
        updated_at = clock_timestamp()
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
        AND connection.disconnected_at IS NULL;
      DELETE FROM subscription_apps_designations designation
      WHERE designation.account_id = p_account_id AND designation.connection_id = p_connection_id;
      IF target.ownership = 'personal' THEN
        UPDATE organization_user_resource_authorities resource
        SET status = 'revoked', revoked_at = clock_timestamp(), updated_at = clock_timestamp()
        WHERE resource.account_id = p_account_id AND resource.id = target.authority_id
          AND resource.resource_id = p_connection_id AND resource.status <> 'revoked';
      END IF;
      PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
      RETURN 'removed';
    END
    $$;

CREATE FUNCTION opengeni_private.dismiss_inbox_notification_v1(p_item_id uuid, p_account_id uuid, p_subject_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  UPDATE opengeni_private.inbox_items item
  SET status = 'dismissed', updated_at = now()
  WHERE item.id = p_item_id AND item.account_id = p_account_id
    AND item.recipient_subject_id = p_subject_id
    AND item.kind = 'notification' AND item.status = 'open'
  RETURNING item.id INTO v_id;
  RETURN v_id;
END
$$;

CREATE FUNCTION opengeni_private.document_migration_capability_active(p_capability_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM opengeni_private.document_migration_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND capability.capability_kind = p_capability_kind
  )
$$;

CREATE FUNCTION opengeni_private.editable_artifact_actor_key_matches(value text, actor_kind text, actor_subject_id text, agent_session_id text, agent_turn_id text, agent_attempt_id text, agent_generation integer, service_name text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE parsed jsonb;
BEGIN
  IF octet_length(convert_to(value, 'UTF8')) NOT BETWEEN 1 AND 8192 THEN
    RETURN false;
  END IF;
  IF NOT opengeni_private.editable_artifact_identity_valid(actor_subject_id) THEN
    RETURN false;
  END IF;
  parsed := value::jsonb;
  IF actor_kind = 'human' THEN
    RETURN parsed = jsonb_build_array('human', actor_subject_id)
      AND value = '[' || to_json('human'::text)::text || ','
        || to_json(actor_subject_id)::text || ']';
  ELSIF actor_kind = 'agent' THEN
    IF NOT opengeni_private.editable_artifact_identity_valid(agent_session_id)
      OR NOT opengeni_private.editable_artifact_identity_valid(agent_turn_id)
      OR NOT opengeni_private.editable_artifact_identity_valid(agent_attempt_id)
    THEN
      RETURN false;
    END IF;
    RETURN parsed = jsonb_build_array(
        'agent', actor_subject_id, agent_session_id, agent_turn_id,
        agent_attempt_id, agent_generation
      ) AND value = '[' || to_json('agent'::text)::text || ','
        || to_json(actor_subject_id)::text || ',' || to_json(agent_session_id)::text
        || ',' || to_json(agent_turn_id)::text || ',' || to_json(agent_attempt_id)::text
        || ',' || agent_generation::text || ']';
  ELSIF actor_kind = 'service' THEN
    IF NOT opengeni_private.editable_artifact_identity_valid(service_name) THEN
      RETURN false;
    END IF;
    RETURN parsed = jsonb_build_array('service', actor_subject_id, service_name)
      AND value = '[' || to_json('service'::text)::text || ','
        || to_json(actor_subject_id)::text || ',' || to_json(service_name)::text || ']';
  END IF;
  RETURN false;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$$;

CREATE FUNCTION opengeni_private.editable_artifact_frontier_dominates(candidate jsonb, required jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NOT opengeni_private.editable_artifact_frontier_valid(candidate)
    OR NOT opengeni_private.editable_artifact_frontier_valid(required)
  THEN
    RETURN false;
  END IF;
  RETURN NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(required) AS required_entries(entry)
    LEFT JOIN jsonb_array_elements(candidate) AS candidate_entries(candidate_entry)
      ON candidate_entry->>'replicaId' = entry->>'replicaId'
    WHERE candidate_entry IS NULL
      OR (candidate_entry->>'counter')::bigint < (entry->>'counter')::bigint
  );
END;
$$;

CREATE FUNCTION opengeni_private.editable_artifact_frontier_merge_dot_equals(result_frontier jsonb, left_frontier jsonb, right_frontier jsonb, dot_replica_id text, dot_counter bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE matches boolean;
BEGIN
  IF NOT opengeni_private.editable_artifact_frontier_valid(result_frontier)
    OR NOT opengeni_private.editable_artifact_frontier_valid(left_frontier)
    OR NOT opengeni_private.editable_artifact_frontier_valid(right_frontier)
    OR dot_replica_id !~ '^[0-9a-f]{16}$'
    OR dot_replica_id ~ '^0+$'
    OR dot_counter NOT BETWEEN 0 AND 9007199254740991
  THEN
    RETURN false;
  END IF;
  WITH entries AS (
    SELECT entry->>'replicaId' AS replica_id, (entry->>'counter')::bigint AS counter
    FROM jsonb_array_elements(left_frontier) AS left_entries(entry)
    UNION ALL
    SELECT entry->>'replicaId', (entry->>'counter')::bigint
    FROM jsonb_array_elements(right_frontier) AS right_entries(entry)
    UNION ALL
    SELECT dot_replica_id, dot_counter WHERE dot_counter > 0
  ), merged AS (
    SELECT replica_id, max(counter) AS counter
    FROM entries
    GROUP BY replica_id
  ), canonical AS (
    SELECT coalesce(
      jsonb_agg(
        jsonb_build_object('replicaId', replica_id, 'counter', counter)
        ORDER BY convert_to(replica_id, 'UTF8')
      ),
      '[]'::jsonb
    ) AS value
    FROM merged
  )
  SELECT result_frontier = canonical.value INTO matches FROM canonical;
  RETURN matches;
END;
$_$;

CREATE FUNCTION opengeni_private.editable_artifact_frontier_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE entry jsonb;
DECLARE replica text;
DECLARE counter_text text;
DECLARE previous_replica text;
BEGIN
  IF value IS NULL
    OR jsonb_typeof(value) IS DISTINCT FROM 'array'
    OR jsonb_array_length(value) > 65536
    OR pg_column_size(value) > 1048576
    OR octet_length(value::text) > 1048576
  THEN
    RETURN false;
  END IF;
  FOR entry IN SELECT item FROM jsonb_array_elements(value) AS items(item) LOOP
    IF jsonb_typeof(entry) <> 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(entry)) <> 2
      OR NOT (entry ? 'replicaId' AND entry ? 'counter')
      OR jsonb_typeof(entry->'replicaId') <> 'string'
      OR jsonb_typeof(entry->'counter') <> 'number'
    THEN
      RETURN false;
    END IF;
    replica := entry->>'replicaId';
    counter_text := entry->>'counter';
    IF replica !~ '^[0-9a-f]{16}$' OR replica ~ '^0+$'
      OR counter_text !~ '^[1-9][0-9]{0,15}$'
      OR counter_text::numeric > 9007199254740991
      OR (previous_replica IS NOT NULL
        AND convert_to(replica, 'UTF8') <= convert_to(previous_replica, 'UTF8'))
    THEN
      RETURN false;
    END IF;
    previous_replica := replica;
  END LOOP;
  RETURN true;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$_$;

CREATE FUNCTION opengeni_private.editable_artifact_id_array_valid(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  SELECT CASE
    WHEN value IS NULL OR jsonb_typeof(value) IS DISTINCT FROM 'array' THEN false
    ELSE jsonb_array_length(value) <= 10000
      AND pg_column_size(value) <= 1048576
      AND octet_length(value::text) <= 1048576
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(value) AS entries(entry)
        WHERE jsonb_typeof(entry) <> 'string'
          OR entry #>> '{}' !~ '^[0-9a-f]{32}$'
          OR entry #>> '{}' ~ '^0+$'
      )
      AND (
        SELECT count(*) = count(DISTINCT entry #>> '{}')
        FROM jsonb_array_elements(value) AS entries(entry)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM (
          SELECT entry #>> '{}' AS current_value,
            lag(entry #>> '{}') OVER (ORDER BY ordinal) AS previous_value
          FROM jsonb_array_elements(value) WITH ORDINALITY AS entries(entry, ordinal)
        ) ordered
        WHERE previous_value IS NOT NULL
          AND convert_to(previous_value, 'UTF8') >= convert_to(current_value, 'UTF8')
      )
  END;
$_$;

CREATE FUNCTION opengeni_private.editable_artifact_identity_valid(value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE code_units integer;
BEGIN
  IF value IS NULL OR value = '' OR octet_length(convert_to(value, 'UTF8')) > 1024
    OR value <> btrim(
      value,
      U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'
    )
  THEN
    RETURN false;
  END IF;
  SELECT sum(CASE WHEN ascii(character) > 65535 THEN 2 ELSE 1 END)::integer
  INTO code_units
  FROM unnest(string_to_array(value, NULL)) AS characters(character);
  RETURN code_units BETWEEN 1 AND 256;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$$;

CREATE FUNCTION opengeni_private.editable_artifact_object_has_exact_keys(value jsonb, expected text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT jsonb_typeof(value) = 'object'
    AND (SELECT array_agg(key ORDER BY convert_to(key, 'UTF8'))
         FROM jsonb_object_keys(value) AS keys(key))
      = (SELECT array_agg(key ORDER BY convert_to(key, 'UTF8'))
         FROM unnest(expected) AS keys(key));
$$;

CREATE FUNCTION opengeni_private.editable_artifact_operation_id_list_valid(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  SELECT CASE
    WHEN value IS NULL OR jsonb_typeof(value) IS DISTINCT FROM 'array' THEN false
    ELSE jsonb_array_length(value) <= 4096
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(value) AS entries(entry)
        WHERE jsonb_typeof(entry) <> 'string'
          OR entry #>> '{}' !~ '^[0-9a-f]{32}$'
          OR entry #>> '{}' ~ '^0+$'
      )
      AND (
        SELECT count(*) = count(DISTINCT entry #>> '{}')
        FROM jsonb_array_elements(value) AS entries(entry)
      )
  END;
$_$;

CREATE FUNCTION opengeni_private.editable_artifact_scope_matches_context(p_account_id uuid, p_workspace_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL THEN RETURN false; END IF;
  RETURN p_account_id = nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
    AND p_workspace_id = nullif(
      pg_catalog.current_setting('opengeni.workspace_id', true), ''
    )::uuid;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$$;

CREATE FUNCTION opengeni_private.editable_artifact_text_sha256(value text) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT pg_catalog.sha256(pg_catalog.convert_to(value, 'UTF8'));
$$;

CREATE FUNCTION opengeni_private.end_site_session_cancellation(token uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      DELETE FROM opengeni_private.site_session_cancellation_capabilities c
        WHERE c.capability_id=token AND c.target_schema={{schema_oid}}::oid
          AND c.backend_pid=pg_backend_pid() AND c.transaction_id=pg_current_xact_id_if_assigned()
    $$;

CREATE FUNCTION opengeni_private.enforce_automatic_session_title_policy_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  candidate text := nullif(
    pg_catalog.current_setting('opengeni.automatic_session_title_v1_candidate', true),
    ''
  );
BEGIN
  IF TG_OP = 'INSERT'
     AND NEW.title_source IS DISTINCT FROM 'user'
     AND (
       NEW.title IS DISTINCT FROM 'New conversation'
       OR NEW.title_source IS DISTINCT FROM 'agent'
     )
     AND (candidate IS NULL OR candidate IS DISTINCT FROM NEW.title)
  THEN
    -- Old create/fork/clone paths remain rolling- and rollback-compatible, but
    -- no unversioned automatic title crosses the new display boundary.
    NEW.title := 'New conversation';
    NEW.title_source := 'agent';
  ELSIF TG_OP = 'UPDATE'
     AND (OLD.title IS DISTINCT FROM NEW.title
      OR OLD.title_source IS DISTINCT FROM NEW.title_source)
     AND NEW.title_source = 'agent'
     AND (NEW.title IS DISTINCT FROM 'New conversation' OR OLD.title_source = 'user')
     AND (candidate IS NULL OR candidate IS DISTINCT FROM NEW.title)
  THEN
    -- Cancel the row operation instead of returning a rewritten success. The
    -- pre-policy helper therefore receives no UPDATE ... RETURNING row, reports
    -- updated=false, and skips its separate title-event transaction. Its caller
    -- still continues scheduled dispatch, while a newer title can no longer be
    -- followed by a higher-sequence stale legacy event.
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.enforce_codex_credential_workspace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE candidate uuid;
    BEGIN
      IF TG_TABLE_NAME = 'codex_rotation_settings' THEN
        candidate := NEW.active_credential_id;
        IF candidate IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM codex_subscription_credentials credential
          WHERE credential.id = candidate
            AND credential.account_id = NEW.account_id
            AND credential.workspace_id = NEW.workspace_id
            AND credential.authority_scope IN ('workspace', 'user')
        ) THEN
          RAISE EXCEPTION 'Codex rotation credential must remain workspace-owned'
            USING ERRCODE = '23514';
        END IF;
      ELSIF TG_TABLE_NAME = 'organization_codex_rotation_settings' THEN
        candidate := NEW.active_credential_id;
        IF candidate IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM codex_subscription_credentials credential
          WHERE credential.id = candidate
            AND credential.account_id = NEW.account_id
            AND credential.organization_id = NEW.account_id
            AND credential.authority_scope = 'organization'
        ) THEN
          RAISE EXCEPTION 'Codex rotation credential must remain organization-owned'
            USING ERRCODE = '23514';
        END IF;
      ELSIF TG_ARGV[0] = 'pinned' THEN
        candidate := NEW.codex_pinned_credential_id;
      ELSE
        candidate := NEW.codex_last_credential_id;
      END IF;
      IF candidate IS NULL OR TG_TABLE_NAME IN (
        'codex_rotation_settings', 'organization_codex_rotation_settings'
      ) THEN
        RETURN NEW;
      END IF;
      IF NOT opengeni_private.codex_credential_serves_workspace(
        NEW.account_id, NEW.workspace_id, candidate
      ) AND NOT opengeni_private.codex_credential_serves_turn(
        NEW.account_id, NEW.workspace_id, candidate, NEW.active_turn_id
      ) THEN
        RAISE EXCEPTION 'Codex session credential is outside the workspace effective pool'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.enforce_codex_lease_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    BEGIN
      IF NOT opengeni_private.codex_credential_serves_turn(
        NEW.account_id, NEW.workspace_id, NEW.credential_id, NEW.turn_id
      ) THEN
        RAISE EXCEPTION 'Codex credential is outside the accepted turn pool' USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.enforce_model_connection_access_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF (NEW.allowed_model_ids, NEW.allowed_workspace_ids, NEW.allow_personal_workspaces,
      NEW.access_policy_version, NEW.access_policy_updated_by, NEW.access_policy_updated_at)
    IS NOT DISTINCT FROM
     (OLD.allowed_model_ids, OLD.allowed_workspace_ids, OLD.allow_personal_workspaces,
      OLD.access_policy_version, OLD.access_policy_updated_by, OLD.access_policy_updated_at)
  THEN RETURN NEW; END IF;
  IF (TG_TABLE_NAME = 'organization_model_provider_connections'
      OR to_jsonb(OLD)->>'authority_scope' = 'organization')
    AND NOT opengeni_private.codex_organization_admin_visible(OLD.account_id) THEN
    RAISE EXCEPTION 'organization connection access requires organization administration'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.access_policy_version <> OLD.access_policy_version + 1
    OR NEW.access_policy_updated_by IS DISTINCT FROM current_setting('opengeni.subject_id', true)
    OR nullif(NEW.access_policy_updated_by, '') IS NULL
    OR NEW.access_policy_updated_at IS NULL THEN
    RAISE EXCEPTION 'connection access policy revision required' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.enforce_organization_codex_runtime_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.authority_scope IS DISTINCT FROM 'organization'
    OR opengeni_private.current_workspace_id() IS NULL
  THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
    OR NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
    OR NEW.authority_scope IS DISTINCT FROM OLD.authority_scope
    OR NEW.owner_organization_membership_id IS DISTINCT FROM OLD.owner_organization_membership_id
    OR NEW.organization_user_resource_authority_id IS DISTINCT FROM OLD.organization_user_resource_authority_id
    OR NEW.organization_user_resource_kind IS DISTINCT FROM OLD.organization_user_resource_kind
    OR NEW.organization_user_resource_authority_generation IS DISTINCT FROM OLD.organization_user_resource_authority_generation
    OR NEW.chatgpt_account_id IS DISTINCT FROM OLD.chatgpt_account_id
    OR NEW.scopes IS DISTINCT FROM OLD.scopes
    -- A provider plan observation may rewrite plan_type and the plan change
    -- record, but only together with a new plan_checked_at stamp.
    OR (
      (
        NEW.plan_type IS DISTINCT FROM OLD.plan_type
        OR NEW.plan_previous_type IS DISTINCT FROM OLD.plan_previous_type
        OR NEW.plan_changed_at IS DISTINCT FROM OLD.plan_changed_at
      )
      AND (
        NEW.plan_checked_at IS NULL
        OR NEW.plan_checked_at IS NOT DISTINCT FROM OLD.plan_checked_at
      )
    )
    OR NEW.is_fedramp IS DISTINCT FROM OLD.is_fedramp
    OR NEW.label IS DISTINCT FROM OLD.label
    OR NEW.account_email IS DISTINCT FROM OLD.account_email
    OR NEW.extra_credits_enabled IS DISTINCT FROM OLD.extra_credits_enabled
    OR NEW.extra_credits_version IS DISTINCT FROM OLD.extra_credits_version
    OR NEW.extra_credits_updated_by_subject_id IS DISTINCT FROM OLD.extra_credits_updated_by_subject_id
    OR NEW.extra_credits_updated_at IS DISTINCT FROM OLD.extra_credits_updated_at
    OR NEW.allocator_enabled IS DISTINCT FROM OLD.allocator_enabled
    OR NEW.allocator_version IS DISTINCT FROM OLD.allocator_version
    OR NEW.allocator_updated_by_subject_id IS DISTINCT FROM OLD.allocator_updated_by_subject_id
    OR NEW.allocator_updated_at IS DISTINCT FROM OLD.allocator_updated_at
    OR NEW.connected_by_subject_id IS DISTINCT FROM OLD.connected_by_subject_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'organization Codex credential management requires organization administration'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.credential_encrypted IS DISTINCT FROM OLD.credential_encrypted
    OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
    OR NEW.last_refresh_at IS DISTINCT FROM OLD.last_refresh_at
    OR NEW.version IS DISTINCT FROM OLD.version
  THEN
    IF NEW.credential_encrypted IS NOT DISTINCT FROM OLD.credential_encrypted
      OR NEW.version IS DISTINCT FROM OLD.version + 1
      OR NEW.last_refresh_at IS NULL
      OR NEW.last_refresh_at IS NOT DISTINCT FROM OLD.last_refresh_at
      OR NEW.status IS DISTINCT FROM 'active'
      OR NEW.last_error IS NOT NULL
      OR NEW.primary_used_percent IS DISTINCT FROM OLD.primary_used_percent
      OR NEW.primary_reset_at IS DISTINCT FROM OLD.primary_reset_at
      OR NEW.secondary_used_percent IS DISTINCT FROM OLD.secondary_used_percent
      OR NEW.secondary_reset_at IS DISTINCT FROM OLD.secondary_reset_at
      OR NEW.usage_checked_at IS DISTINCT FROM OLD.usage_checked_at
      OR NEW.exhausted_until IS DISTINCT FROM OLD.exhausted_until
      OR NEW.reset_credit_available_count IS DISTINCT FROM OLD.reset_credit_available_count
      OR NEW.reset_credits_checked_at IS DISTINCT FROM OLD.reset_credits_checked_at
      OR NEW.selection_count IS DISTINCT FROM OLD.selection_count
      OR NEW.last_selected_at IS DISTINCT FROM OLD.last_selected_at
    THEN
      RAISE EXCEPTION 'organization Codex runtime token refresh has an invalid mutation shape'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.enforce_organization_plan_seats() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE seat_limit integer; seats integer; reserved boolean := false;
  previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  previous_account text := current_setting('opengeni.account_id', true);
BEGIN
  IF TG_TABLE_NAME = 'organization_memberships' THEN
    IF NEW.subject_id NOT LIKE 'user:%' OR NEW.status NOT IN ('active','provisioning') THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND OLD.account_id = NEW.account_id AND OLD.subject_id = NEW.subject_id
      AND OLD.status IN ('active','provisioning') THEN RETURN NEW; END IF;
  ELSE
    IF NEW.status <> 'pending' OR NEW.expires_at <= clock_timestamp() THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND OLD.account_id = NEW.account_id AND OLD.status = 'pending'
      AND OLD.expires_at > clock_timestamp() AND OLD.target_subject_id IS NOT DISTINCT FROM NEW.target_subject_id THEN RETURN NEW; END IF;
  END IF;
  -- The existing membership lifecycle already owns this lock. Reuse its exact
  -- key/order; do not add an account row FOR UPDATE or a second membership lock.
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || NEW.account_id::text, 0));
  PERFORM set_config('opengeni.account_id', NEW.account_id::text, true);
  SELECT (opengeni_private.subscription_plan_definition(plan_key)->>'seatLimit')::integer INTO seat_limit
    FROM organization_plans WHERE account_id = NEW.account_id;
  IF seat_limit IS NULL THEN
    PERFORM set_config('opengeni.account_id', coalesce(previous_account,''), true);
    RETURN NEW;
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  IF TG_TABLE_NAME = 'organization_memberships' THEN
    SELECT EXISTS (SELECT 1 FROM organization_membership_invitations WHERE account_id = NEW.account_id
      AND target_subject_id = NEW.subject_id AND status = 'pending' AND expires_at > clock_timestamp()) INTO reserved;
  ELSE
    SELECT EXISTS (SELECT 1 FROM organization_memberships WHERE account_id = NEW.account_id
      AND subject_id = NEW.target_subject_id AND subject_id LIKE 'user:%' AND status IN ('active','provisioning')) INTO reserved;
  END IF;
  -- Acceptance converts an already-counted reservation, even after a downgrade.
  IF NOT reserved THEN
    seats := organization_plan_seats_used(NEW.account_id);
    IF TG_TABLE_NAME = 'organization_membership_invitations' THEN
      IF TG_OP = 'UPDATE' AND OLD.account_id = NEW.account_id AND OLD.status = 'pending' AND OLD.expires_at > clock_timestamp() THEN
        seats := seats - 1;
      END IF;
    END IF;
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  PERFORM set_config('opengeni.account_id', coalesce(previous_account,''), true);
  IF NOT reserved AND seats >= seat_limit THEN
    RAISE EXCEPTION 'Organization seat limit reached; upgrade your plan to add people'
      USING ERRCODE = 'P0S01', DETAIL = jsonb_build_object('seatLimit',seat_limit,'seatsUsed',seats,'action','upgrade')::text;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  PERFORM set_config('opengeni.account_id', coalesce(previous_account,''), true);
  RAISE;
END $$;

CREATE FUNCTION opengeni_private.enforce_rig_platform_base_only_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.image IS NOT NULL THEN
    RAISE EXCEPTION
      'Rig image overrides are unsupported; Rigs use the deployment platform sandbox image'
      USING ERRCODE = '23514',
        CONSTRAINT = 'rig_versions_platform_base_only';
  END IF;

  IF TG_OP = 'UPDATE'
    AND NEW.image IS NOT NULL
    AND NEW.image IS DISTINCT FROM OLD.image
  THEN
    RAISE EXCEPTION
      'Rig image overrides are unsupported; Rigs use the deployment platform sandbox image'
      USING ERRCODE = '23514',
        CONSTRAINT = 'rig_versions_platform_base_only';
  END IF;

  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.enforce_sandbox_checkpoint_artifact_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF ROW(
    NEW.id, NEW.account_id, NEW.workspace_id, NEW.sandbox_group_id,
    NEW.source_lease_id, NEW.source_lease_epoch, NEW.source_instance_id,
    NEW.source_workspace_generation, NEW.provenance, NEW.provider_backend,
    NEW.provider_binding_key, NEW.provider_binding, NEW.object_kind,
    NEW.object_id, NEW.archive_base64, NEW.archive_sha256, NEW.archive_bytes,
    NEW.descriptor, NEW.descriptor_revision, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.id, OLD.account_id, OLD.workspace_id, OLD.sandbox_group_id,
    OLD.source_lease_id, OLD.source_lease_epoch, OLD.source_instance_id,
    OLD.source_workspace_generation, OLD.provenance, OLD.provider_backend,
    OLD.provider_binding_key, OLD.provider_binding, OLD.object_kind,
    OLD.object_id, OLD.archive_base64, OLD.archive_sha256, OLD.archive_bytes,
    OLD.descriptor, OLD.descriptor_revision, OLD.created_at
  )
  THEN
    RAISE EXCEPTION 'checkpoint artifact identity and receipt fields are immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.enforce_sandbox_recovery_protocol_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_roles WHERE rolname = session_user AND rolsuper
  ) AND current_setting('opengeni.sandbox_recovery_protocol_v2', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'sandbox recovery protocol v2 marker is required for % on %', TG_OP, TG_TABLE_NAME
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.enforce_session_inference_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status = 'running' AND OLD.status <> 'running'
     AND coalesce(current_setting('opengeni.session_inference_claim', true), '') <> '1' THEN
    RAISE EXCEPTION 'session inference must be claimed through the fenced claim transaction'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.enqueue_automatic_session_title_fanout_v1(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_event_id uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path FROM CURRENT
    AS $$
  WITH enqueued AS (
    INSERT INTO opengeni_private.automatic_session_title_fanout_outbox_v1 (
      account_id,
      workspace_id,
      session_id,
      event_id
    ) VALUES (
      p_account_id,
      p_workspace_id,
      p_session_id,
      p_event_id
    )
    ON CONFLICT (event_id) DO NOTHING
    RETURNING true AS changed
  )
  SELECT coalesce((SELECT changed FROM enqueued), false);
$$;

CREATE FUNCTION opengeni_private.enqueue_host_session_event_export() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
    DECLARE
      v_enabled boolean;
      v_initiator jsonb;
      v_context jsonb := '{}'::jsonb;
      v_origin text;
      v_surface text;
      v_model_provider text;
      v_tool_family text;
      v_attribution_turn_id uuid;
      v_source_payload_bytes integer;
      v_export_payload jsonb;
      v_export_payload_codec_version smallint;
      v_payload_bytes integer;
    BEGIN
      IF NEW.type IN (
        'agent.message.delta', 'agent.reasoning.delta',
        'sandbox.command.output.delta', 'terminal.pty.output.delta'
      ) THEN
        RETURN NEW;
      END IF;

      SELECT c.session_events_enabled INTO v_enabled
      FROM {{schema}}.host_export_config c WHERE c.id = 1
      FOR SHARE;
      IF coalesce(v_enabled, false) = false THEN
        RETURN NEW;
      END IF;

      v_attribution_turn_id := NEW.turn_id;
      IF v_attribution_turn_id IS NULL AND NEW.type = 'user.message' THEN
        SELECT min(t.id::text)::uuid INTO v_attribution_turn_id
        FROM {{schema}}.session_turns t
        WHERE t.account_id = NEW.account_id
          AND t.workspace_id = NEW.workspace_id
          AND t.session_id = NEW.session_id
          AND t.trigger_event_id = NEW.id
        HAVING count(*) = 1;
      END IF;

      IF v_attribution_turn_id IS NOT NULL THEN
        SELECT
          CASE WHEN octet_length(t.initiator_subject_id) <= 1024 THEN
            jsonb_strip_nulls(jsonb_build_object(
              'kind', t.initiator_kind,
              'subjectId', t.initiator_subject_id,
              'label', CASE
                WHEN jsonb_typeof(t.initiator_context -> 'label') = 'string'
                THEN left(t.initiator_context ->> 'label', 256)
                ELSE NULL
              END
            ))
          ELSE NULL END,
          jsonb_strip_nulls(jsonb_build_object(
            'label', CASE
              WHEN jsonb_typeof(t.initiator_context -> 'label') = 'string'
              THEN left(t.initiator_context ->> 'label', 256)
              ELSE NULL
            END,
            'backfill', CASE
              WHEN jsonb_typeof(t.initiator_context -> 'backfill') = 'boolean'
              THEN t.initiator_context -> 'backfill'
              ELSE NULL
            END,
            'attributionOmitted', CASE
              WHEN octet_length(t.initiator_subject_id) > 1024 THEN 'subject_id_too_large'
              ELSE NULL
            END
          )),
          t.source,
          t.surface,
          opengeni_private.analytics_model_provider(
            CASE
              WHEN jsonb_typeof(t.metadata #> '{turnExecutionPolicyV1,providerId}') = 'string'
              THEN t.metadata #>> '{turnExecutionPolicyV1,providerId}'
              ELSE NULL
            END
          )
        INTO v_initiator, v_context, v_origin, v_surface, v_model_provider
        FROM {{schema}}.session_turns t
        WHERE t.account_id = NEW.account_id
          AND t.workspace_id = NEW.workspace_id
          AND t.session_id = NEW.session_id
          AND t.id = v_attribution_turn_id;
      ELSIF NEW.type = 'session.created' THEN
        SELECT
          CASE WHEN octet_length(s.created_by_subject_id) <= 1024 THEN
            jsonb_strip_nulls(jsonb_build_object(
              'kind', s.created_by_kind,
              'subjectId', s.created_by_subject_id,
              'label', CASE
                WHEN jsonb_typeof(s.created_by_context -> 'label') = 'string'
                THEN left(s.created_by_context ->> 'label', 256)
                ELSE NULL
              END
            ))
          ELSE NULL END,
          jsonb_strip_nulls(jsonb_build_object(
            'label', CASE
              WHEN jsonb_typeof(s.created_by_context -> 'label') = 'string'
              THEN left(s.created_by_context ->> 'label', 256)
              ELSE NULL
            END,
            'backfill', CASE
              WHEN jsonb_typeof(s.created_by_context -> 'backfill') = 'boolean'
              THEN s.created_by_context -> 'backfill'
              ELSE NULL
            END,
            'attributionOmitted', CASE
              WHEN octet_length(s.created_by_subject_id) > 1024 THEN 'subject_id_too_large'
              ELSE NULL
            END
          )),
          NULL
        INTO v_initiator, v_context, v_origin
        FROM {{schema}}.sessions s
        WHERE s.workspace_id = NEW.workspace_id AND s.id = NEW.session_id;
      END IF;

      -- The worker stamps a content-free family on the tool-call event. Check
      -- the fixed wire format again so a malformed value exports as NULL.
      IF NEW.type = 'agent.toolCall.created'
        AND jsonb_typeof(NEW.payload -> 'toolFamily') = 'string' THEN
        v_tool_family := NEW.payload ->> 'toolFamily';
        IF v_tool_family !~
          '^(custom|integration:[a-z0-9]([a-z0-9.-]{0,150}[a-z0-9])?|[a-z][a-z0-9_]{0,63})$' THEN
          v_tool_family := NULL;
        END IF;
      END IF;
      IF v_surface IS NOT NULL AND v_surface NOT IN (
        'web', 'slack', 'api_key', 'embedded', 'scheduled', 'agent',
        'voice', 'site', 'automation', 'mcp', 'system'
      ) THEN
        v_surface := NULL;
      END IF;

      v_source_payload_bytes := octet_length(NEW.payload::text);
      v_export_payload := NEW.payload;
      v_export_payload_codec_version := NEW.payload_codec_version;
      IF v_source_payload_bytes > 65536 THEN
        v_export_payload := jsonb_build_object(
          '_hostExport', jsonb_build_object(
            'payloadMode', 'summary',
            'payloadTruncated', true,
            'originalBytes', v_source_payload_bytes,
            'sourceEventId', NEW.id,
            'fullPayload', 'retained in canonical session event'
          ),
          'preview', '[host-export payload omitted at bounded projection boundary]'
        );
        -- The projection is literal PostgreSQL JSON, not an application-codec
        -- envelope. Preserve codec truth only when the original payload is kept.
        v_export_payload_codec_version := NULL;
      END IF;

      v_payload_bytes := octet_length(v_export_payload::text)
        + octet_length(NEW.type)
        + coalesce(octet_length(NEW.client_event_id), 0)
        + coalesce(octet_length(NEW.turn_association), 0)
        + coalesce(octet_length(NEW.duplicate_reason), 0)
        + octet_length(coalesce(v_initiator, 'null'::jsonb)::text)
        + octet_length(v_context::text)
        + coalesce(octet_length(v_surface), 0)
        + coalesce(octet_length(v_model_provider), 0)
        + coalesce(octet_length(v_tool_family), 0)
        + 768;
      INSERT INTO {{schema}}.host_export_outbox (
        export_kind, source_id, account_id, workspace_id, session_id,
        turn_id, turn_generation, turn_attempt_id, session_sequence,
        client_event_id, turn_association, duplicate_of_event_id, duplicate_reason,
        event_type, idempotency_key, initiator, initiator_context, origin,
        surface, model_provider, tool_family,
        payload, payload_codec_version, envelope_bytes, occurred_at,
        source_recorded_at, enqueued_at
      ) VALUES (
        'session_event', NEW.id, NEW.account_id, NEW.workspace_id, NEW.session_id,
        NEW.turn_id, NEW.turn_generation, NEW.turn_attempt_id, NEW.sequence,
        NEW.client_event_id, NEW.turn_association, NEW.duplicate_of_event_id,
        NEW.duplicate_reason,
        NEW.type, 'session_event:' || NEW.id::text, v_initiator,
        coalesce(v_context, '{}'::jsonb), v_origin,
        v_surface, v_model_provider, v_tool_family,
        v_export_payload,
        v_export_payload_codec_version, greatest(1, v_payload_bytes), NEW.occurred_at,
        NEW.created_at, clock_timestamp()
      )
      ON CONFLICT (export_kind, source_id) DO NOTHING;
      RETURN NEW;
    END $_$;

CREATE FUNCTION opengeni_private.enqueue_host_usage_event_export() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_enabled boolean;
      v_initiator jsonb := CASE
        WHEN NEW.initiator_kind IS NOT NULL THEN jsonb_strip_nulls(jsonb_build_object(
          'kind', NEW.initiator_kind,
          'subjectId', NEW.initiator_subject_id,
          'label', CASE
            WHEN jsonb_typeof(NEW.initiator_context -> 'label') = 'string'
            THEN left(NEW.initiator_context ->> 'label', 256)
            ELSE NULL
          END
        ))
        ELSE NULL
      END;
      v_context jsonb := jsonb_strip_nulls(jsonb_build_object(
        'label', CASE
          WHEN jsonb_typeof(NEW.initiator_context -> 'label') = 'string'
          THEN left(NEW.initiator_context ->> 'label', 256)
          ELSE NULL
        END,
        'backfill', CASE
          WHEN jsonb_typeof(NEW.initiator_context -> 'backfill') = 'boolean'
          THEN NEW.initiator_context -> 'backfill'
          ELSE NULL
        END
      ));
      v_origin text := NEW.origin;
      v_surface text;
      v_model_provider text;
      v_payload jsonb;
      v_payload_bytes integer;
    BEGIN
      SELECT c.usage_events_enabled INTO v_enabled
      FROM {{schema}}.host_export_config c WHERE c.id = 1
      FOR SHARE;
      IF coalesce(v_enabled, false) = false THEN
        RETURN NEW;
      END IF;

      -- Export-specific bounds apply only while the optional host stream is
      -- enabled. Standalone/custom usage writers retain their historical
      -- behavior; an embedded writer that cannot be represented fails its
      -- source transaction visibly instead of committing a poison outbox row.
      IF octet_length(NEW.event_type) NOT BETWEEN 1 AND 256
        OR octet_length(NEW.unit) NOT BETWEEN 1 AND 128
        OR (NEW.subject_id IS NOT NULL AND octet_length(NEW.subject_id) > 1024)
        OR (NEW.source_resource_type IS NOT NULL
          AND octet_length(NEW.source_resource_type) > 256)
        OR (NEW.source_resource_id IS NOT NULL
          AND octet_length(NEW.source_resource_id) > 2048)
        OR octet_length(NEW.idempotency_key) NOT BETWEEN 1 AND 2048
        OR (NEW.billing_provider_event_id IS NOT NULL
          AND octet_length(NEW.billing_provider_event_id) > 2048) THEN
        RAISE EXCEPTION 'usage event exceeds the enabled host-export wire bounds'
          USING ERRCODE = '22001';
      END IF;

      IF NEW.turn_id IS NOT NULL THEN
        SELECT
          CASE WHEN octet_length(t.initiator_subject_id) <= 1024 THEN
            jsonb_strip_nulls(jsonb_build_object(
              'kind', t.initiator_kind,
              'subjectId', t.initiator_subject_id,
              'label', CASE
                WHEN jsonb_typeof(t.initiator_context -> 'label') = 'string'
                THEN left(t.initiator_context ->> 'label', 256)
                ELSE NULL
              END
            ))
          ELSE NULL END,
          jsonb_strip_nulls(jsonb_build_object(
            'label', CASE
              WHEN jsonb_typeof(t.initiator_context -> 'label') = 'string'
              THEN left(t.initiator_context ->> 'label', 256)
              ELSE NULL
            END,
            'backfill', CASE
              WHEN jsonb_typeof(t.initiator_context -> 'backfill') = 'boolean'
              THEN t.initiator_context -> 'backfill'
              ELSE NULL
            END,
            'attributionOmitted', CASE
              WHEN octet_length(t.initiator_subject_id) > 1024 THEN 'subject_id_too_large'
              ELSE NULL
            END
          )),
          t.source,
          t.surface,
          opengeni_private.analytics_model_provider(
            CASE
              WHEN jsonb_typeof(t.metadata #> '{turnExecutionPolicyV1,providerId}') = 'string'
              THEN t.metadata #>> '{turnExecutionPolicyV1,providerId}'
              ELSE NULL
            END
          )
        INTO v_initiator, v_context, v_origin, v_surface, v_model_provider
        FROM {{schema}}.session_turns t
        WHERE t.workspace_id = NEW.workspace_id AND t.id = NEW.turn_id;
      ELSIF v_initiator IS NULL AND NEW.subject_id IS NOT NULL
        AND octet_length(NEW.subject_id) <= 1024 THEN
        v_initiator := jsonb_build_object('kind', 'subject', 'subjectId', NEW.subject_id);
      END IF;
      IF v_surface IS NOT NULL AND v_surface NOT IN (
        'web', 'slack', 'api_key', 'embedded', 'scheduled', 'agent',
        'voice', 'site', 'automation', 'mcp', 'system'
      ) THEN
        v_surface := NULL;
      END IF;

      v_payload := jsonb_build_object(
        'id', NEW.id,
        'workspaceId', NEW.workspace_id,
        'accountId', NEW.account_id,
        'subjectId', NEW.subject_id,
        'eventType', NEW.event_type,
        'quantity', NEW.quantity,
        'unit', NEW.unit,
        'sourceResourceType', NEW.source_resource_type,
        'sourceResourceId', NEW.source_resource_id,
        'idempotencyKey', NEW.idempotency_key,
        'occurredAt', NEW.occurred_at,
        'recordedAt', NEW.recorded_at,
        'exportedToBillingAt', NEW.exported_to_billing_at,
        'billingProviderEventId', NEW.billing_provider_event_id
      );
      v_payload_bytes := octet_length(v_payload::text)
        + octet_length(coalesce(v_initiator, 'null'::jsonb)::text)
        + octet_length(v_context::text)
        + coalesce(octet_length(v_surface), 0)
        + coalesce(octet_length(v_model_provider), 0)
        + 768;
      INSERT INTO {{schema}}.host_export_outbox (
        export_kind, source_id, account_id, workspace_id, session_id,
        turn_id, turn_attempt_id, event_type, idempotency_key, initiator,
        initiator_context, origin, surface, model_provider, payload,
        envelope_bytes, occurred_at, source_recorded_at, enqueued_at
      ) VALUES (
        'usage_event', NEW.id, NEW.account_id, NEW.workspace_id, NEW.session_id,
        NEW.turn_id, NEW.turn_attempt_id, NEW.event_type, NEW.idempotency_key,
        v_initiator, coalesce(v_context, '{}'::jsonb), v_origin,
        v_surface, v_model_provider, v_payload,
        greatest(1, v_payload_bytes), NEW.occurred_at,
        NEW.recorded_at, clock_timestamp()
      )
      ON CONFLICT (export_kind, source_id) DO NOTHING;
      RETURN NEW;
    END $$;

CREATE FUNCTION opengeni_private.enqueue_native_push_for_session_event_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_rule text;
  v_body text;
BEGIN
  BEGIN
    v_rule := CASE NEW.type
      WHEN 'session.humanInput.requested' THEN 'needs_input'
      WHEN 'session.requiresAction' THEN 'needs_input'
      WHEN 'turn.completed' THEN 'reply_ready'
      WHEN 'turn.failed' THEN 'failed'
    END;
    v_body := CASE NEW.type
      WHEN 'session.humanInput.requested' THEN coalesce(
        NEW.payload #>> '{request,questions,0,prompt}', 'The agent has a question for you.')
      WHEN 'session.requiresAction' THEN 'Approve ' || coalesce(
        NEW.payload #>> '{approvals,0,display,toolName}', NEW.payload #>> '{approvals,0,name}',
        'a tool call') || '?'
      WHEN 'turn.completed' THEN 'The agent replied.'
      WHEN 'turn.failed' THEN 'The agent ran into a problem. Open the session to retry.'
    END;
    IF v_rule IN ('reply_ready', 'failed') AND EXISTS (
      SELECT 1 FROM sessions session
      WHERE session.id = NEW.session_id AND session.parent_session_id IS NOT NULL
    ) THEN
      v_rule := NULL;
    END IF;
    -- A person who muted this session hears no replies from it.
    IF v_rule = 'reply_ready' AND opengeni_private.session_replies_muted_v1(NEW.session_id) THEN
      v_rule := NULL;
    END IF;
    IF v_rule = 'reply_ready' AND NEW.turn_id IS NOT NULL
      AND NOT opengeni_private.session_hands_back_v1(NEW.session_id, NEW.turn_id) THEN
      v_rule := NULL;
    END IF;
    IF v_rule IS NOT NULL AND NEW.session_id IS NOT NULL THEN
      PERFORM opengeni_private.enqueue_native_push_v2(
        NEW.session_id, v_rule, NEW.id::text, NULL, left(v_body, 240), NEW.type,
        jsonb_build_object('sequence', NEW.sequence));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'native push enqueue skipped for event %: %', NEW.id, SQLSTATE;
  END;
  RETURN NULL;
END
$$;

CREATE FUNCTION opengeni_private.enqueue_native_push_v1(p_session_id uuid, p_rule text, p_dedupe_key text, p_title text, p_body text, p_event_type text) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT opengeni_private.enqueue_native_push_v2(
    p_session_id, p_rule, p_dedupe_key, p_title, left(p_body, 240), p_event_type, '{}'::jsonb)
$$;

CREATE FUNCTION opengeni_private.enqueue_native_push_v2(p_session_id uuid, p_rule text, p_dedupe_key text, p_title text, p_body text, p_event_type text, p_extra jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_session record;
  v_recipient text;
  v_urgency jsonb := '{}'::jsonb;
  v_count integer;
BEGIN
  SELECT session.id, session.account_id, session.workspace_id, session.created_by_subject_id,
      session.owner_subject_id, session.title
    INTO v_session
  FROM sessions session
  WHERE session.id = p_session_id
    AND session.account_id = opengeni_private.current_account_id()
    AND session.workspace_id = opengeni_private.current_workspace_id();
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  -- Needs-you and the agent's own notifications reach the owner; replies and
  -- failures only the person who started the session.
  v_recipient := CASE WHEN p_rule IN ('needs_input', 'agent')
    THEN opengeni_private.session_person_v1(v_session.workspace_id, v_session.id,
      v_session.owner_subject_id, v_session.created_by_subject_id)
    ELSE opengeni_private.session_recipient_v1(NULL, v_session.created_by_subject_id)
  END;
  IF v_recipient IS NULL THEN
    RETURN 0;
  END IF;
  IF p_rule = 'needs_input' AND EXISTS (
    SELECT 1 FROM opengeni_private.inbox_settings settings
    WHERE settings.account_id = v_session.account_id
      AND settings.subject_id = v_recipient
      AND settings.time_sensitive_needs_you
  ) THEN
    v_urgency := jsonb_build_object('urgency', 'time_sensitive');
  END IF;
  INSERT INTO opengeni_private.native_push_deliveries (auth_session_id, dedupe_key, rule, payload)
  SELECT device.auth_session_id, p_dedupe_key, p_rule,
    jsonb_strip_nulls(jsonb_build_object(
      'rule', p_rule,
      'eventType', p_event_type,
      'sessionId', p_session_id,
      'workspaceId', v_session.workspace_id,
      'subjectId', device.subject_id,
      'title', left(coalesce(nullif(btrim(p_title), ''), nullif(btrim(v_session.title), '')), 120),
      'body', left(nullif(btrim(p_body), ''), 1000)
    )) || coalesce(p_extra, '{}'::jsonb) || v_urgency
  FROM opengeni_private.native_push_devices device
  JOIN auth_sessions auth ON auth.id = device.auth_session_id AND auth.expires_at > now()
  WHERE device.subject_id = v_recipient AND p_rule = ANY (device.rules)
  ON CONFLICT (auth_session_id, dedupe_key) DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END
$$;

CREATE FUNCTION opengeni_private.enqueue_native_push_v3(p_session_id uuid, p_rule text, p_dedupe_key text, p_title text, p_body text, p_event_type text, p_extra jsonb, p_recipient text, p_link_session boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_session record;
  v_recipient text;
  v_count integer;
BEGIN
  SELECT session.id, session.account_id, session.workspace_id, session.created_by_subject_id,
      session.owner_subject_id, session.title
    INTO v_session
  FROM sessions session
  WHERE session.id = p_session_id
    AND session.account_id = opengeni_private.current_account_id()
    AND session.workspace_id = opengeni_private.current_workspace_id();
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  v_recipient := CASE
    WHEN p_recipient IS NOT NULL THEN p_recipient
    WHEN p_rule IN ('needs_input', 'agent')
    THEN opengeni_private.session_person_v1(v_session.workspace_id, v_session.id,
      v_session.owner_subject_id, v_session.created_by_subject_id)
    ELSE opengeni_private.session_recipient_v1(NULL, v_session.created_by_subject_id)
  END;
  IF v_recipient IS NULL THEN
    RETURN 0;
  END IF;
  INSERT INTO opengeni_private.native_push_deliveries (auth_session_id, dedupe_key, rule, payload)
  SELECT device.auth_session_id, p_dedupe_key, p_rule,
    jsonb_strip_nulls(jsonb_build_object(
      'rule', p_rule,
      'eventType', p_event_type,
      'sessionId', CASE WHEN p_link_session THEN p_session_id END,
      'workspaceId', v_session.workspace_id,
      'subjectId', device.subject_id,
      'title', left(coalesce(nullif(btrim(p_title), ''),
        CASE WHEN p_link_session THEN nullif(btrim(v_session.title), '') END), 120),
      'body', left(nullif(btrim(p_body), ''), 1000)
    ) || coalesce(p_extra, '{}'::jsonb))
  FROM opengeni_private.native_push_devices device
  JOIN auth_sessions auth ON auth.id = device.auth_session_id AND auth.expires_at > now()
  WHERE device.subject_id = v_recipient AND p_rule = ANY (device.rules)
  ON CONFLICT (auth_session_id, dedupe_key) DO NOTHING;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END
$$;

CREATE FUNCTION opengeni_private.enqueue_organization_webhook_deliveries_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  BEGIN
    IF NEW.account_id IS NULL OR NEW.workspace_id IS NULL
      OR NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
      OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
      OR NOT EXISTS (SELECT 1 FROM workspaces WHERE id = NEW.workspace_id AND account_id = NEW.account_id)
      OR get_workspace_kind(NEW.account_id, NEW.workspace_id) <> 'shared'
    THEN RETURN NULL; END IF;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
    IF EXISTS (SELECT 1 FROM organization_memberships
      WHERE account_id = NEW.account_id AND personal_workspace_id = NEW.workspace_id)
    THEN
      PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
      RETURN NULL;
    END IF;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
    IF TG_TABLE_NAME = 'recording_events' THEN
      INSERT INTO organization_webhook_deliveries(account_id, workspace_id, webhook_id, event_id, event_type, payload)
        SELECT webhook.account_id, NEW.workspace_id, webhook.id, NEW.id, NEW.type,
          jsonb_build_object(
            'id', NEW.id, 'type', NEW.type, 'lane', 'organization', 'workspaceId', NEW.workspace_id,
            'workspace', jsonb_build_object('id', workspace.id, 'externalSource', workspace.external_source,
              'externalId', workspace.external_id),
            'occurredAt', to_char(NEW.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
            'data', NEW.data
          )
        FROM (
          SELECT registration.* FROM organization_webhooks registration
          WHERE registration.account_id = NEW.account_id AND registration.enabled
            AND NEW.type = ANY(registration.event_types)
          ORDER BY registration.created_at, registration.id LIMIT 10
        ) webhook
        JOIN workspaces workspace ON workspace.id = NEW.workspace_id AND workspace.account_id = webhook.account_id
        WHERE webhook.workspace_filter IS NULL
          OR webhook.workspace_filter ->> 'externalSource' = workspace.external_source
        ON CONFLICT(webhook_id, event_id) DO NOTHING;
      RETURN NULL;
    END IF;
    INSERT INTO organization_webhook_deliveries(account_id, workspace_id, webhook_id, event_id, event_type, payload)
      SELECT webhook.account_id, NEW.workspace_id, webhook.id, NEW.id, NEW.type,
        opengeni_private.integration_webhook_payload_v1(
          NEW.account_id, NEW.workspace_id, NEW.id, NEW.type, NEW.session_id,
          NEW.turn_id, NEW.sequence, NEW.occurred_at, NEW.payload, 'organization')
      FROM (
        SELECT registration.* FROM organization_webhooks registration
        WHERE registration.account_id = NEW.account_id AND registration.enabled
          AND NEW.type = ANY(registration.event_types)
        ORDER BY registration.created_at, registration.id LIMIT 10
      ) webhook
      JOIN workspaces workspace ON workspace.id = NEW.workspace_id AND workspace.account_id = webhook.account_id
      WHERE webhook.account_id = NEW.account_id AND webhook.enabled AND NEW.type = ANY(webhook.event_types)
        AND (webhook.workspace_filter IS NULL
          OR webhook.workspace_filter ->> 'externalSource' = workspace.external_source)
      ON CONFLICT(webhook_id, event_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
    RAISE WARNING 'organization webhook enqueue skipped for event %: %', NEW.id, SQLSTATE;
  END;
  RETURN NULL;
END $$;

CREATE FUNCTION opengeni_private.enqueue_recording_event_workspace_webhooks_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  BEGIN
    INSERT INTO workspace_webhook_deliveries (account_id, workspace_id, webhook_id, event_id, event_type, payload)
    SELECT webhook.account_id, webhook.workspace_id, webhook.id, NEW.id, NEW.type,
      jsonb_build_object(
        'id', NEW.id, 'type', NEW.type, 'lane', 'workspace', 'workspaceId', NEW.workspace_id,
        'workspace', jsonb_build_object('id', workspace.id, 'externalSource', workspace.external_source,
          'externalId', workspace.external_id),
        'occurredAt', to_char(NEW.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'data', NEW.data
      )
    FROM workspace_webhooks webhook
    JOIN workspaces workspace ON workspace.id = NEW.workspace_id AND workspace.account_id = NEW.account_id
    WHERE webhook.account_id = NEW.account_id AND webhook.workspace_id = NEW.workspace_id
      AND webhook.enabled AND NEW.type = ANY(webhook.event_types)
    ON CONFLICT (webhook_id, event_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'recording webhook enqueue skipped for event %: %', NEW.id, SQLSTATE;
  END;
  RETURN NULL;
END
$$;

CREATE FUNCTION opengeni_private.enqueue_session_archive_object_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  planned_key text;
BEGIN
  IF OLD.content_archive IS NOT NULL THEN
    FOR planned_key IN
      SELECT value FROM jsonb_array_elements_text(
        coalesce(OLD.content_archive->'objectKeys', '[]'::jsonb))
    LOOP
      INSERT INTO opengeni_private.session_archive_object_deletions
        (object_key, account_id, workspace_id, session_id)
      VALUES (planned_key, OLD.account_id, OLD.workspace_id, OLD.id)
      ON CONFLICT (object_key) DO NOTHING;
    END LOOP;
  END IF;
  RETURN OLD;
END;
$$;

CREATE FUNCTION opengeni_private.enqueue_workspace_webhook_deliveries_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NEW.type LIKE 'usage.%' THEN RETURN NULL; END IF;
  BEGIN
    INSERT INTO workspace_webhook_deliveries(account_id, workspace_id, webhook_id, event_id, event_type, payload)
      SELECT webhook.account_id, webhook.workspace_id, webhook.id, NEW.id, NEW.type,
        opengeni_private.integration_webhook_payload_v1(
          NEW.account_id, NEW.workspace_id, NEW.id, NEW.type, NEW.session_id,
          NEW.turn_id, NEW.sequence, NEW.occurred_at, NEW.payload)
      FROM workspace_webhooks webhook
      WHERE webhook.account_id = NEW.account_id AND webhook.workspace_id = NEW.workspace_id
        AND webhook.enabled AND NEW.type = ANY(webhook.event_types)
      ON CONFLICT(webhook_id, event_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'workspace webhook enqueue skipped for event %: %', NEW.id, SQLSTATE;
  END;
  RETURN NULL;
END $$;

CREATE FUNCTION opengeni_private.ensure_editable_artifact_scope_authorization_head(p_account_id uuid, p_workspace_id uuid, p_data_schema name DEFAULT "current_schema"()) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
DECLARE current_revision bigint;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_data_schema IS NULL
    OR NOT opengeni_private.editable_artifact_scope_matches_context(
      p_account_id, p_workspace_id
    )
  THEN
    RAISE EXCEPTION 'editable artifact scope authorization context is unavailable'
      USING ERRCODE = '42501';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  EXECUTE pg_catalog.format($query$
    INSERT INTO %I.editable_artifact_scope_authorization_heads (
      account_id, workspace_id, create_revision
    ) VALUES ($1, $2, 1)
    ON CONFLICT (account_id, workspace_id) DO NOTHING
  $query$, data_schema) USING p_account_id, p_workspace_id;
  EXECUTE pg_catalog.format($query$
    SELECT create_revision
    FROM %I.editable_artifact_scope_authorization_heads
    WHERE account_id = $1 AND workspace_id = $2
    FOR SHARE
  $query$, data_schema) INTO current_revision USING p_account_id, p_workspace_id;
  IF current_revision IS NULL THEN
    RAISE EXCEPTION 'editable artifact scope authorization head is unavailable'
      USING ERRCODE = '55000';
  END IF;
  RETURN current_revision;
END;
$_$;

CREATE FUNCTION opengeni_private.ensure_workspace_session_activity_revision(target_schema text, target_workspace_id uuid, target_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  previous_account_id text := current_setting('opengeni.account_id', true);
  previous_workspace_id text := current_setting('opengeni.workspace_id', true);
BEGIN
  -- FORCE RLS applies to supported non-bypass table owners too. Establish only
  -- the row's own trusted scope, then restore the caller's transaction-local
  -- context so structural initialization cannot leak authority downstream.
  PERFORM set_config('opengeni.account_id', target_account_id::text, true);
  PERFORM set_config('opengeni.workspace_id', target_workspace_id::text, true);
  EXECUTE format(
    'INSERT INTO %I.workspace_session_activity_revisions '
    || '(workspace_id, account_id, revision) VALUES ($1, $2, 0) '
    || 'ON CONFLICT (workspace_id) DO NOTHING',
    target_schema
  )
  USING target_workspace_id, target_account_id;
  PERFORM set_config('opengeni.account_id', coalesce(previous_account_id, ''), true);
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace_id, ''), true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.account_id', coalesce(previous_account_id, ''), true);
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace_id, ''), true);
  RAISE;
END;
$_$;

CREATE FUNCTION opengeni_private.expire_refunded_plan_credit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE debit credit_ledger_entries%ROWTYPE; period plan_credit_periods%ROWTYPE;
  plan_paid bigint; already_expired bigint; late_refunds bigint; effective_grant bigint;
BEGIN
  IF NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Plan refund account scope mismatch' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(NEW.account_id::text));
  SELECT * INTO debit FROM credit_ledger_entries WHERE account_id = NEW.account_id
    AND type = 'video_generation_debit' AND source_type = NEW.source_type AND source_id = NEW.source_id
    ORDER BY created_at, id LIMIT 1;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT * INTO period FROM plan_credit_periods WHERE account_id = NEW.account_id
    AND debit.created_at >= greatest(period_start, granted_at)
    AND debit.created_at < least(period_end, coalesce(expired_at, 'infinity'::timestamptz))
    ORDER BY granted_at DESC LIMIT 1;
  IF NOT FOUND OR (period.expired_at IS NULL AND period.period_end > NEW.created_at) THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM credit_ledger_entries WHERE id = period.grant_entry_id AND eligible_model_ids IS NOT NULL) THEN
    RETURN NEW;
  END IF;
  IF period.expired_at IS NULL THEN
    RAISE EXCEPTION 'Ended plan must be settled before a video refund' USING ERRCODE = '55000';
  END IF;
  SELECT coalesce(sum(refund.amount_micros), 0) INTO late_refunds FROM credit_ledger_entries refund
    WHERE refund.account_id = NEW.account_id AND refund.type = 'video_generation_refund'
      AND refund.created_at >= least(period.period_end, period.expired_at)
      AND EXISTS (SELECT 1 FROM credit_ledger_entries original
        WHERE original.account_id = NEW.account_id AND original.type = 'video_generation_debit'
          AND original.source_type = refund.source_type AND original.source_id = refund.source_id
          AND original.created_at >= greatest(period.period_start, period.granted_at)
          AND original.created_at < least(period.period_end, period.expired_at));
  effective_grant := period.granted_micros - period.opening_debt_micros;
  plan_paid := greatest(0, effective_grant - greatest(0, period.usage_at_expiry_micros - late_refunds))
    - greatest(0, effective_grant - period.usage_at_expiry_micros);
  SELECT coalesce(-sum(amount_micros), 0) INTO already_expired FROM credit_ledger_entries
    WHERE account_id = NEW.account_id AND type = 'plan_credit_expiry'
      AND source_type = 'plan_credit_video_refund' AND metadata->>'periodId' = period.id::text;
  plan_paid := least(NEW.amount_micros, greatest(0, plan_paid - already_expired));
  IF plan_paid > 0 THEN
    INSERT INTO credit_ledger_entries(account_id, workspace_id, type, amount_micros, source_type, source_id,
      idempotency_key, metadata, occurred_at, created_at)
    VALUES (NEW.account_id, NULL, 'plan_credit_expiry', -plan_paid, 'plan_credit_video_refund', debit.id::text,
      'plan-credit-refund-expiry:' || NEW.id::text,
      jsonb_build_object('periodId',period.id,'refundEntryId',NEW.id), clock_timestamp(), clock_timestamp())
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.external_membership_service_authority(p_command jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  actor_subject text := p_command ->> 'actorSubjectId';
  account_id_value uuid := (p_command ->> 'organizationId')::uuid;
  membership_id_value uuid := (p_command ->> 'membershipId')::uuid;
  permissions_value jsonb;
  allowed boolean;
  previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF actor_subject NOT LIKE 'api_key:%' THEN RETURN false; END IF;
  IF actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
    OR (p_command ->> 'action') IS NULL
    OR (p_command ->> 'action') NOT IN ('suspend', 'reactivate', 'offboard')
    OR account_id_value IS NULL OR membership_id_value IS NULL
  THEN RAISE EXCEPTION 'external lifecycle authority invalid' USING ERRCODE = '42501'; END IF;
  SELECT credential.permissions INTO permissions_value FROM api_keys credential
  WHERE credential.account_id = account_id_value
    AND 'api_key:' || credential.id::text = actor_subject
    AND credential.workspace_id IS NULL AND credential.credential_kind = 'organization'
    AND credential.revoked_at IS NULL
    AND (credential.expires_at IS NULL OR credential.expires_at > clock_timestamp())
  FOR SHARE;
  IF NOT coalesce(permissions_value ? 'account:admin', false) THEN
    RAISE EXCEPTION 'external lifecycle service administration required' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'external_identity_provisioning', true);
  SELECT EXISTS (
    SELECT 1 FROM external_identities identity_row
    JOIN organization_memberships membership
      ON membership.id = identity_row.organization_membership_id
      AND membership.account_id = identity_row.account_id
      AND membership.subject_id = identity_row.subject_id
      AND membership.personal_workspace_id = identity_row.personal_workspace_id
    WHERE identity_row.account_id = account_id_value
      AND membership.id = membership_id_value AND membership.role = 'member'
  ) INTO allowed;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
  IF NOT allowed THEN
    RAISE EXCEPTION 'external lifecycle target unavailable' USING ERRCODE = '42501';
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker, ''), true);
  RAISE;
END
$$;

CREATE FUNCTION opengeni_private.external_workspace_service_permissions(p_account uuid, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE permissions_value jsonb;
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_actor IS NULL OR p_actor IS DISTINCT FROM opengeni_private.current_subject_id()
  THEN RAISE EXCEPTION 'external workspace service scope invalid' USING ERRCODE = '42501'; END IF;
  SELECT k.permissions INTO permissions_value FROM api_keys k
  WHERE k.account_id = p_account AND 'api_key:' || k.id::text = p_actor
    AND k.credential_kind = 'organization' AND k.workspace_id IS NULL
    AND k.revoked_at IS NULL AND (k.expires_at IS NULL OR k.expires_at > clock_timestamp())
  FOR SHARE;
  IF NOT coalesce(permissions_value ?| ARRAY['members:manage', 'workspace:admin'], false)
  THEN RAISE EXCEPTION 'external workspace service administration required' USING ERRCODE = '42501'; END IF;
  RETURN permissions_value;
END $$;

CREATE FUNCTION opengeni_private.fail_editable_artifact_materialization(p_account_id uuid, p_workspace_id uuid, p_artifact_id text, p_job_id text, p_owner text, p_attempt_count integer, p_error_code text, p_data_schema name) RETURNS TABLE(outcome text, account_id uuid, workspace_id uuid, artifact_id text, job_id text, settled_by_owner text, attempt_count integer, error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE data_schema name;
DECLARE affected integer := 0;
DECLARE job_state text;
DECLARE job_attempt integer;
DECLARE job_owner text;
DECLARE job_lease_expires_at timestamptz;
DECLARE job_settled_by_owner text;
DECLARE job_error_code text;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL
    OR p_artifact_id IS NULL OR p_artifact_id !~ '^[0-9a-f]{32}$'
    OR p_artifact_id ~ '^0+$'
    OR p_job_id IS NULL OR p_job_id !~ '^[0-9a-f]{32}$' OR p_job_id ~ '^0+$'
    OR p_owner IS NULL OR pg_catalog.octet_length(p_owner) NOT BETWEEN 1 AND 256
    OR p_owner <> pg_catalog.btrim(p_owner)
    OR p_attempt_count IS NULL OR p_attempt_count NOT BETWEEN 1 AND 1000
    OR p_error_code IS NULL OR p_error_code !~ '^[a-z][a-z0-9_.-]{0,127}$'
    OR p_data_schema IS NULL
  THEN
    RAISE EXCEPTION 'invalid editable artifact materialization failure bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  job_state := NULL;
  EXECUTE pg_catalog.format($query$
    SELECT target.state, target.attempt_count, target.lease_owner,
      target.lease_expires_at, target.settled_by_owner, target.error_code
    FROM %I.editable_artifact_materialization_jobs target
    WHERE target.account_id = $1 AND target.workspace_id = $2
      AND target.artifact_id = $3 AND target.id = $4
    FOR UPDATE
  $query$, data_schema)
  INTO job_state, job_attempt, job_owner, job_lease_expires_at,
    job_settled_by_owner, job_error_code
  USING p_account_id, p_workspace_id, p_artifact_id, p_job_id;

  IF job_state = 'failed' AND job_attempt = p_attempt_count
    AND job_settled_by_owner = p_owner AND job_error_code = p_error_code
  THEN
    RETURN QUERY SELECT 'replayed'::text, p_account_id, p_workspace_id,
      p_artifact_id, p_job_id, job_settled_by_owner, job_attempt, job_error_code;
    RETURN;
  END IF;
  IF job_state <> 'running' OR job_owner IS DISTINCT FROM p_owner
    OR job_attempt IS DISTINCT FROM p_attempt_count
    OR job_lease_expires_at <= pg_catalog.statement_timestamp()
  THEN
    RETURN QUERY SELECT 'fenced'::text, p_account_id, p_workspace_id,
      p_artifact_id, p_job_id, p_owner, p_attempt_count, p_error_code;
    RETURN;
  END IF;

  EXECUTE pg_catalog.format($query$
    UPDATE %I.editable_artifact_materialization_jobs target
    SET state = 'failed', settled_by_owner = target.lease_owner,
      lease_owner = NULL, lease_expires_at = NULL, error_code = $7,
      completed_at = pg_catalog.statement_timestamp()
    WHERE target.account_id = $1 AND target.workspace_id = $2
      AND target.artifact_id = $3 AND target.id = $4
      AND target.state = 'running' AND target.lease_owner = $5
      AND target.attempt_count = $6
      AND target.lease_expires_at > pg_catalog.statement_timestamp()
  $query$, data_schema)
  USING p_account_id, p_workspace_id, p_artifact_id, p_job_id, p_owner,
    p_attempt_count, p_error_code;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RETURN QUERY SELECT 'fenced'::text, p_account_id, p_workspace_id,
      p_artifact_id, p_job_id, p_owner, p_attempt_count, p_error_code;
    RETURN;
  END IF;
  RETURN QUERY SELECT 'failed'::text, p_account_id, p_workspace_id,
    p_artifact_id, p_job_id, p_owner, p_attempt_count, p_error_code;
END;
$_$;

CREATE FUNCTION opengeni_private.fail_subscription_codex_apps_refresh(p_account_id uuid, p_workspace_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_last_error text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      write_minted boolean := false;
      marked boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
      THEN RETURN false; END IF;
      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'codex_apps_refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = 'codex';
      IF NOT FOUND THEN RETURN false; END IF;
      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        connection_id, provider
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'codex_refresh_write',
        p_account_id, p_workspace_id, p_connection_id, 'codex'
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      UPDATE subscription_connections
      SET status = 'needs_relogin',
          last_error = left(coalesce(nullif(btrim(p_last_error), ''), 'Codex sign-in expired'), 512),
          version = version + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = 'codex' AND kind = 'subscription' AND status = 'active'
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      marked := FOUND;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'codex_refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN marked;
    END
    $$;

CREATE FUNCTION opengeni_private.fail_subscription_core_connection_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_last_error text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      write_minted boolean := false;
      marked boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
      THEN RETURN false; END IF;
      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'connection_refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = p_provider;
      IF NOT FOUND THEN RETURN false; END IF;
      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        connection_id, provider
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'refresh_write',
        p_account_id, p_workspace_id, p_connection_id, p_provider
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      UPDATE subscription_connections
      SET status = 'needs_relogin',
          last_error = left(coalesce(nullif(btrim(p_last_error), ''), 'Sign-in expired'), 512),
          version = version + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = p_provider AND kind = opengeni_private.subscription_core_connection_kind(p_provider) AND status = 'active'
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      marked := FOUND;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN marked;
    END
    $$;

CREATE FUNCTION opengeni_private.fail_subscription_core_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_last_error text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      capability_owner text;
      capability_human text;
      write_minted boolean := false;
      marked boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL OR p_session_id IS NULL OR p_turn_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
      THEN RETURN false; END IF;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.session_id = p_session_id
        AND capability.turn_id = p_turn_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = p_provider
      RETURNING capability.session_owner_subject_id, capability.turn_human_subject_id
        INTO capability_owner, capability_human;
      IF NOT FOUND THEN RETURN false; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        session_id, turn_id, connection_id, provider,
        session_owner_subject_id, turn_human_subject_id
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'refresh_write',
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_connection_id, p_provider,
        capability_owner, capability_human
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      UPDATE subscription_connections
      SET status = 'needs_relogin',
          last_error = left(coalesce(nullif(btrim(p_last_error), ''), 'Sign-in expired'), 512),
          version = version + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = p_provider AND kind = opengeni_private.subscription_core_connection_kind(p_provider) AND status = 'active'
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      marked := FOUND;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN marked;
    END
    $$;

CREATE FUNCTION opengeni_private.fence_inbox_execution_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $_$
DECLARE context session_turns%ROWTYPE; target sessions%ROWTYPE; human text; u record;
  origin session_turns%ROWTYPE; origin_session sessions%ROWTYPE;
  pure_goal boolean := true; goal_turn uuid; expected_v2 jsonb; delivery_source record;
  providers text[];
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.execution_context_turn_id IS DISTINCT FROM OLD.execution_context_turn_id THEN
      RAISE EXCEPTION 'accepted execution context is immutable' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.execution_context_turn_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO target FROM sessions WHERE id = NEW.session_id AND workspace_id = NEW.workspace_id
    AND account_id = NEW.account_id;
  SELECT * INTO context FROM session_turns WHERE id = NEW.execution_context_turn_id
    AND session_id = NEW.session_id AND workspace_id = NEW.workspace_id AND account_id = NEW.account_id;
  human := coalesce(context.initiating_human_subject_id,
    CASE WHEN context.initiator_kind = 'subject' THEN context.initiator_subject_id END);
  FOR delivery_source IN SELECT * FROM opengeni_subscription_internal.subscription_compat_delivery_sources(
    NEW.workspace_id, NEW.session_id, NEW.id, NEW.execution_context_turn_id, NEW.initiating_human_subject_id)
  LOOP
    IF delivery_source.path = 'pure_goal_continuation' THEN goal_turn := delivery_source.source_id;
    ELSIF delivery_source.path = 'informational_delivery' THEN pure_goal := false; END IF;
  END LOOP;
  IF pure_goal THEN
    SELECT goal_source.subscription_authority INTO expected_v2 FROM session_turns goal_source
    WHERE goal_source.workspace_id = NEW.workspace_id AND goal_source.session_id = NEW.session_id
      AND goal_source.id = goal_turn;
  ELSE
    expected_v2 := context.subscription_authority;
  END IF;
  providers := opengeni_private.subscription_authority_compat_providers();
  IF context.id IS NULL OR context.id = NEW.id OR target.execution_context_turn_id IS DISTINCT FROM context.id
    OR NEW.source NOT IN ('system','goal') OR NEW.status <> 'running' OR NEW.scheduled_task_run_id IS NOT NULL
    OR human IS NULL OR NEW.initiating_human_subject_id IS DISTINCT FROM human
    OR (NEW.connection_account_intent IS NOT NULL
      AND NEW.connection_account_intent IS DISTINCT FROM context.connection_account_intent)
    OR ((NEW.personal_connection_delegations IS DISTINCT FROM context.personal_connection_delegations
      OR NEW.mcp_account_bindings IS DISTINCT FROM context.mcp_account_bindings)
      -- 0755: carrying the context's intent, the turn resolved it afresh.
      AND NEW.connection_account_intent IS NULL)
    OR NEW.xai_provider_account_authority_snapshot IS DISTINCT FROM context.xai_provider_account_authority_snapshot
    OR NEW.claude_provider_account_authority_snapshot IS DISTINCT FROM context.claude_provider_account_authority_snapshot
    OR NOT opengeni_subscription_internal.subscription_v2_copy_matches(NEW.subscription_authority, expected_v2)
    OR ((context.initiator_context ->> 'credentialRestriction' = 'developer_setup'
      OR context.metadata #>> '{turnExecutionPolicyV1,credentialRestriction}' = 'developer_setup')
      AND NEW.initiator_context ->> 'credentialRestriction' IS DISTINCT FROM 'developer_setup')
    OR EXISTS (SELECT 1 FROM external_link_turn_authorities WHERE turn_id = context.id)
    OR NOT EXISTS (SELECT 1 FROM session_system_updates WHERE delivered_turn_id = NEW.id AND state = 'delivered'
      AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id AND session_id = NEW.session_id)
  THEN RAISE EXCEPTION 'invalid receiving execution context' USING ERRCODE = '42501'; END IF;
  FOR u IN SELECT * FROM session_system_updates WHERE delivered_turn_id = NEW.id AND state = 'delivered'
    AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id AND session_id = NEW.session_id
  LOOP
    IF u.scheduled_task_run_id IS NOT NULL OR u.kind = 'agent_steer_instruction' THEN
      RAISE EXCEPTION 'control input cannot borrow receiving execution context' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO origin FROM session_turns t WHERE t.account_id = NEW.account_id AND t.workspace_id = NEW.workspace_id
      AND t.id = CASE WHEN pg_catalog.octet_length((CASE WHEN u.kind = 'agent_message' THEN u.lineage ->> 'callerTurnId'
        WHEN u.kind LIKE 'child_%' THEN u.lineage ->> 'parentTurnId' ELSE u.lineage ->> 'causalTurnId' END)) = 36 AND (CASE WHEN u.kind = 'agent_message' THEN u.lineage ->> 'callerTurnId'
        WHEN u.kind LIKE 'child_%' THEN u.lineage ->> 'parentTurnId' ELSE u.lineage ->> 'causalTurnId' END) COLLATE pg_catalog."C" OPERATOR(pg_catalog.~) '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN (CASE WHEN u.kind = 'agent_message' THEN u.lineage ->> 'callerTurnId'
        WHEN u.kind LIKE 'child_%' THEN u.lineage ->> 'parentTurnId' ELSE u.lineage ->> 'causalTurnId' END)::pg_catalog.uuid END
      AND t.session_id = CASE WHEN pg_catalog.octet_length((CASE WHEN u.kind = 'agent_message' THEN u.lineage ->> 'callerSessionId'
        ELSE NEW.session_id::text END)) = 36 AND (CASE WHEN u.kind = 'agent_message' THEN u.lineage ->> 'callerSessionId'
        ELSE NEW.session_id::text END) COLLATE pg_catalog."C" OPERATOR(pg_catalog.~) '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN (CASE WHEN u.kind = 'agent_message' THEN u.lineage ->> 'callerSessionId'
        ELSE NEW.session_id::text END)::pg_catalog.uuid END;
    IF (u.kind = 'agent_message' OR u.kind LIKE 'child_%')
      AND u.continued_by_subject_id IS NOT NULL AND u.continued_by_subject_id = human THEN
      NULL; -- its machine owner let it continue under this receiving context
    ELSIF u.kind = 'agent_message' OR u.kind LIKE 'child_%' THEN
      SELECT * INTO origin_session FROM sessions WHERE id = origin.session_id;
      IF origin.id IS NULL OR coalesce(origin.initiating_human_subject_id,
          CASE WHEN origin.initiator_kind = 'subject' THEN origin.initiator_subject_id END) IS DISTINCT FROM human
        OR EXISTS (SELECT 1 FROM external_link_turn_authorities WHERE turn_id = origin.id)
        OR u.lineage ? 'credentialRestriction' OR origin.initiator_context ? 'credentialRestriction'
        OR origin.metadata #>> '{turnExecutionPolicyV1,credentialRestriction}' IS NOT NULL
        OR origin_session.metadata #>> '{turnExecutionPolicyV1,credentialRestriction}' IS NOT NULL
        OR (u.kind = 'agent_message' AND (
          coalesce(u.lineage ->> 'callerAttemptId','') !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
          OR CASE WHEN jsonb_typeof(u.lineage -> 'callerExecutionGeneration') = 'number' THEN
            (u.lineage ->> 'callerExecutionGeneration')::numeric NOT BETWEEN 1 AND 9007199254740991
            OR mod((u.lineage ->> 'callerExecutionGeneration')::numeric, 1) <> 0
          ELSE true END))
      THEN RAISE EXCEPTION 'informational input has different execution authority' USING ERRCODE = '42501'; END IF;
    ELSE
      IF u.mcp_account_bindings IS DISTINCT FROM context.mcp_account_bindings
        OR u.personal_connection_delegations IS DISTINCT FROM context.personal_connection_delegations
        OR u.xai_provider_account_authority_snapshot IS DISTINCT FROM NEW.xai_provider_account_authority_snapshot
        OR u.claude_provider_account_authority_snapshot IS DISTINCT FROM NEW.claude_provider_account_authority_snapshot
        OR (NOT pure_goal AND u.subscription_authority IS NOT NULL
          AND u.subscription_authority IS DISTINCT FROM NEW.subscription_authority)
        OR (NOT pure_goal AND EXISTS (
          SELECT 1 FROM pg_catalog.unnest(providers) provider(value)
          CROSS JOIN LATERAL (SELECT
            opengeni_subscription_internal.subscription_compat_effective(
              provider.value, 'session_system_update', NEW.workspace_id, u.id, NULL) AS of_update,
            opengeni_subscription_internal.subscription_compat_effective(
              provider.value, 'session_turn', NEW.workspace_id, context.id, NULL) AS of_context) effective
          WHERE NOT (u.subscription_authority IS NULL
              AND effective.of_update = '{"authority":"none"}'::jsonb)
            AND effective.of_update IS DISTINCT FROM effective.of_context))
        OR (u.kind IN ('goal_continuation','background_command_result','session_wait_timeout') AND (
          origin.id IS NULL OR coalesce(origin.initiating_human_subject_id,
            CASE WHEN origin.initiator_kind = 'subject' THEN origin.initiator_subject_id END) IS DISTINCT FROM human
          OR EXISTS (SELECT 1 FROM external_link_turn_authorities WHERE turn_id = origin.id)))
      THEN RAISE EXCEPTION 'causal input has different execution authority' USING ERRCODE = '42501'; END IF;
    END IF;
  END LOOP;
  RETURN NEW;
END $_$;

CREATE FUNCTION opengeni_private.fence_legacy_lossless_content_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF current_setting('opengeni.lossless_content_writer', true) = '1'
    OR current_setting('application_name', true) IN (
      'opengeni-lossless-v1',
      'opengeni-lossless-v1-session-variable-sets-v1'
    )
  THEN
    RETURN NEW;
  END IF;

  CASE TG_TABLE_NAME
    WHEN 'sessions' THEN
      IF NEW.initial_message IS DISTINCT FROM OLD.initial_message
        AND NEW.initial_message_codec_version IS NOT DISTINCT FROM OLD.initial_message_codec_version THEN
        NEW.initial_message_codec_version := NULL;
      END IF;
    WHEN 'session_realtime_entries' THEN
      IF NEW.text IS DISTINCT FROM OLD.text
        AND NEW.text_codec_version IS NOT DISTINCT FROM OLD.text_codec_version THEN
        NEW.text_codec_version := NULL;
      END IF;
      IF NEW.payload IS DISTINCT FROM OLD.payload
        AND NEW.payload_codec_version IS NOT DISTINCT FROM OLD.payload_codec_version THEN
        NEW.payload_codec_version := NULL;
      END IF;
    WHEN 'knowledge_memories' THEN
      IF NEW.text IS DISTINCT FROM OLD.text
        AND NEW.text_codec_version IS NOT DISTINCT FROM OLD.text_codec_version THEN
        NEW.text_codec_version := NULL;
      END IF;
    WHEN 'session_turns' THEN
      IF NEW.prompt IS DISTINCT FROM OLD.prompt
        AND NEW.prompt_codec_version IS NOT DISTINCT FROM OLD.prompt_codec_version THEN
        NEW.prompt_codec_version := NULL;
      END IF;
    WHEN 'session_system_updates' THEN
      IF NEW.summary IS DISTINCT FROM OLD.summary
        AND NEW.summary_codec_version IS NOT DISTINCT FROM OLD.summary_codec_version THEN
        NEW.summary_codec_version := NULL;
      END IF;
      IF NEW.payload IS DISTINCT FROM OLD.payload
        AND NEW.payload_codec_version IS NOT DISTINCT FROM OLD.payload_codec_version THEN
        NEW.payload_codec_version := NULL;
      END IF;
    WHEN 'session_system_update_outbox' THEN
      IF NEW.summary IS DISTINCT FROM OLD.summary
        AND NEW.summary_codec_version IS NOT DISTINCT FROM OLD.summary_codec_version THEN
        NEW.summary_codec_version := NULL;
      END IF;
      IF NEW.payload IS DISTINCT FROM OLD.payload
        AND NEW.payload_codec_version IS NOT DISTINCT FROM OLD.payload_codec_version THEN
        NEW.payload_codec_version := NULL;
      END IF;
    WHEN 'session_events' THEN
      IF NEW.payload IS DISTINCT FROM OLD.payload
        AND NEW.payload_codec_version IS NOT DISTINCT FROM OLD.payload_codec_version THEN
        NEW.payload_codec_version := NULL;
      END IF;
    WHEN 'host_export_outbox' THEN
      IF NEW.payload IS DISTINCT FROM OLD.payload
        AND NEW.payload_codec_version IS NOT DISTINCT FROM OLD.payload_codec_version THEN
        NEW.payload_codec_version := NULL;
      END IF;
    WHEN 'host_export_consumers' THEN
      IF NEW.last_error IS DISTINCT FROM OLD.last_error
        AND NEW.last_error_codec_version IS NOT DISTINCT FROM OLD.last_error_codec_version THEN
        NEW.last_error_codec_version := NULL;
      END IF;
    WHEN 'agent_run_states' THEN
      IF NEW.serialized_run_state IS DISTINCT FROM OLD.serialized_run_state
        AND NEW.serialized_run_state_codec_version IS NOT DISTINCT FROM OLD.serialized_run_state_codec_version THEN
        NEW.serialized_run_state_codec_version := NULL;
      END IF;
      IF NEW.pending_approvals IS DISTINCT FROM OLD.pending_approvals
        AND NEW.pending_approvals_codec_version IS NOT DISTINCT FROM OLD.pending_approvals_codec_version THEN
        NEW.pending_approvals_codec_version := NULL;
      END IF;
    WHEN 'session_history_items' THEN
      IF NEW.item IS DISTINCT FROM OLD.item
        AND NEW.item_codec_version IS NOT DISTINCT FROM OLD.item_codec_version THEN
        NEW.item_codec_version := NULL;
      END IF;
    WHEN 'session_pending_tool_calls' THEN
      IF NEW.call_item IS DISTINCT FROM OLD.call_item
        AND NEW.call_item_codec_version IS NOT DISTINCT FROM OLD.call_item_codec_version THEN
        NEW.call_item_codec_version := NULL;
      END IF;
      IF NEW.result_item IS DISTINCT FROM OLD.result_item
        AND NEW.result_item_codec_version IS NOT DISTINCT FROM OLD.result_item_codec_version THEN
        NEW.result_item_codec_version := NULL;
      END IF;
    WHEN 'sandbox_session_envelopes' THEN
      IF NEW.envelope IS DISTINCT FROM OLD.envelope
        AND NEW.envelope_codec_version IS NOT DISTINCT FROM OLD.envelope_codec_version THEN
        NEW.envelope_codec_version := NULL;
      END IF;
    WHEN 'session_recordings' THEN
      IF NEW.reason IS DISTINCT FROM OLD.reason
        AND NEW.reason_codec_version IS NOT DISTINCT FROM OLD.reason_codec_version THEN
        NEW.reason_codec_version := NULL;
      END IF;
    WHEN 'host_export_dead_letters' THEN
      IF NEW.envelope IS DISTINCT FROM OLD.envelope
        AND NEW.envelope_codec_version IS NOT DISTINCT FROM OLD.envelope_codec_version THEN
        NEW.envelope_codec_version := NULL;
      END IF;
      IF NEW.envelope #> '{event,payload}' IS DISTINCT FROM OLD.envelope #> '{event,payload}'
        AND NEW.event_payload_codec_version IS NOT DISTINCT FROM OLD.event_payload_codec_version THEN
        NEW.event_payload_codec_version := NULL;
      END IF;
    WHEN 'audit_events' THEN
      IF NEW.metadata IS DISTINCT FROM OLD.metadata
        AND NEW.metadata_codec_version IS NOT DISTINCT FROM OLD.metadata_codec_version THEN
        NEW.metadata_codec_version := NULL;
      END IF;
    WHEN 'rig_changes' THEN
      IF NEW.payload IS DISTINCT FROM OLD.payload
        AND NEW.payload_codec_version IS NOT DISTINCT FROM OLD.payload_codec_version THEN
        NEW.payload_codec_version := NULL;
      END IF;
      IF NEW.verification IS DISTINCT FROM OLD.verification
        AND NEW.verification_codec_version IS NOT DISTINCT FROM OLD.verification_codec_version THEN
        NEW.verification_codec_version := NULL;
      END IF;
    WHEN 'transcription_recordings' THEN
      IF NEW.transcript_text IS DISTINCT FROM OLD.transcript_text
        AND NEW.transcript_text_codec_version IS NOT DISTINCT FROM OLD.transcript_text_codec_version THEN
        NEW.transcript_text_codec_version := NULL;
      END IF;
    WHEN 'transcription_recording_segments' THEN
      IF NEW.transcript_text IS DISTINCT FROM OLD.transcript_text
        AND NEW.transcript_text_codec_version IS NOT DISTINCT FROM OLD.transcript_text_codec_version THEN
        NEW.transcript_text_codec_version := NULL;
      END IF;
    ELSE
      RAISE EXCEPTION 'unsupported lossless-content fence table: %', TG_TABLE_NAME;
  END CASE;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.fence_mcp_account_bindings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE document jsonb := to_jsonb(NEW); old_document jsonb; bindings jsonb; old_bindings jsonb;
  delegations jsonb; item jsonb; connection_row record; column_name text; run_bindings jsonb;
  visibility_cleanup boolean := false;
  inherited_bindings boolean := false;
BEGIN
  column_name := CASE WHEN TG_TABLE_NAME = 'sessions' THEN 'initial_mcp_account_bindings'
    ELSE 'mcp_account_bindings' END;
  IF TG_TABLE_NAME = 'scheduled_task_runs' THEN
    bindings := nullif(document #> '{accepted_execution_snapshot,mcpAccountBindings}','null'::jsonb);
    delegations := document #> '{accepted_execution_snapshot,personalConnectionDelegations}';
  ELSE
    bindings := nullif(document -> column_name,'null'::jsonb);
    delegations := document -> CASE WHEN TG_TABLE_NAME = 'sessions' THEN 'initial_personal_connection_delegations'
      ELSE 'personal_connection_delegations' END;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    old_document := to_jsonb(OLD);
    old_bindings := CASE WHEN TG_TABLE_NAME = 'scheduled_task_runs'
      THEN nullif(old_document #> '{accepted_execution_snapshot,mcpAccountBindings}','null'::jsonb)
      ELSE nullif(old_document -> column_name,'null'::jsonb) END;
    IF TG_TABLE_NAME = 'sessions' AND (document ->> 'visibility' IS DISTINCT FROM old_document ->> 'visibility'
      -- 0873: membership revocation clears delegations under the same capability.
      OR (delegations = '[]'::jsonb
        AND old_document -> 'initial_personal_connection_delegations' IS DISTINCT FROM '[]'::jsonb
        -- Without the capability every other write keeps its original refusal.
        AND EXISTS (
          SELECT 1 FROM session_visibility_write_capabilities capability
          WHERE capability.backend_pid = pg_backend_pid()
            AND capability.transaction_id = pg_current_xact_id()
            AND capability.capability_id = nullif(current_setting('opengeni.session_visibility_write_capability',true),'')::uuid))) THEN
      -- Match 0481's native visibility cleanup capability. A caller-set GUC
      -- alone cannot clear a receipt or re-enable legacy ambient fallback.
      IF (document ->> 'authority_epoch')::integer IS DISTINCT FROM (old_document ->> 'authority_epoch')::integer + 1
        OR document -> 'owner_subject_id' IS DISTINCT FROM old_document -> 'owner_subject_id'
        OR document -> 'owner_organization_membership_id' IS DISTINCT FROM old_document -> 'owner_organization_membership_id'
        OR document -> 'parent_turn_id' IS DISTINCT FROM old_document -> 'parent_turn_id'
        OR (bindings IS DISTINCT FROM old_bindings AND bindings IS DISTINCT FROM '[]'::jsonb)
      THEN RAISE EXCEPTION 'invalid MCP account visibility cleanup' USING ERRCODE = '42501'; END IF;
      IF NOT EXISTS (
        SELECT 1 FROM session_visibility_write_capabilities capability
        WHERE capability.backend_pid = pg_backend_pid()
          AND capability.transaction_id = pg_current_xact_id()
          AND capability.capability_id = nullif(current_setting('opengeni.session_visibility_write_capability',true),'')::uuid
      ) THEN RAISE EXCEPTION 'MCP account cleanup requires the visibility lifecycle capability' USING ERRCODE = '42501'; END IF;
      bindings := CASE WHEN document ->> 'visibility' = 'workspace_shared'
        AND old_document ->> 'visibility' IS DISTINCT FROM 'workspace_shared'
        THEN old_bindings ELSE '[]'::jsonb END;
      NEW := jsonb_populate_record(NEW,jsonb_build_object(column_name,bindings));
      visibility_cleanup := true;
    END IF;
    IF bindings IS DISTINCT FROM old_bindings AND NOT visibility_cleanup THEN
      RAISE EXCEPTION 'accepted MCP account bindings are immutable' USING ERRCODE = '42501';
    END IF;
  END IF;
  PERFORM opengeni_private.validate_mcp_account_bindings(bindings,delegations);
  -- Only new execution acceptance validates live workspace identity. Updates
  -- and outbox rows carry already accepted causal evidence: revocation must
  -- not strand terminal settlement or delivery. Shape/immutability still apply
  -- to those carriers above; execution revalidates live authority below.
  IF TG_OP = 'INSERT' AND TG_TABLE_NAME IN ('sessions','session_turns','scheduled_task_runs') THEN
    IF TG_TABLE_NAME = 'session_turns' AND document ->> 'scheduled_task_run_id' IS NOT NULL THEN
      SELECT nullif(r.accepted_execution_snapshot -> 'mcpAccountBindings','null'::jsonb)
      INTO run_bindings FROM scheduled_task_runs r
      WHERE r.id = (document ->> 'scheduled_task_run_id')::uuid
        AND r.account_id = NEW.account_id AND r.workspace_id = NEW.workspace_id FOR SHARE;
      IF NOT FOUND OR bindings IS DISTINCT FROM run_bindings THEN
        RAISE EXCEPTION 'scheduled turn differs from accepted MCP account bindings' USING ERRCODE = '42501';
      END IF;
    END IF;
    IF TG_TABLE_NAME = 'session_turns'
      AND document ->> 'source' IN ('system','goal')
      AND document ->> 'status' = 'running'
    THEN
      -- Claim marks the exact delivered batch before inserting its turn (the
      -- delivery FK is deferred). A copied receipt is not new account admission.
      -- Require both the delivered carrier and its immutable causal turn; a
      -- caller-supplied lineage, actor, or matching account alone is insufficient.
      SELECT EXISTS (
        SELECT 1 FROM session_system_updates update_value
        JOIN session_turns origin ON origin.account_id = NEW.account_id
          AND origin.workspace_id = NEW.workspace_id
          AND origin.id = CASE WHEN pg_catalog.octet_length((CASE
            WHEN update_value.kind IN ('agent_message','agent_steer_instruction')
              THEN update_value.lineage ->> 'callerTurnId'
            WHEN update_value.kind LIKE 'child_%'
              THEN update_value.lineage ->> 'parentTurnId'
            ELSE update_value.lineage ->> 'causalTurnId' END)) = 36 AND (CASE
            WHEN update_value.kind IN ('agent_message','agent_steer_instruction')
              THEN update_value.lineage ->> 'callerTurnId'
            WHEN update_value.kind LIKE 'child_%'
              THEN update_value.lineage ->> 'parentTurnId'
            ELSE update_value.lineage ->> 'causalTurnId' END) COLLATE pg_catalog."C" OPERATOR(pg_catalog.~) '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN (CASE
            WHEN update_value.kind IN ('agent_message','agent_steer_instruction')
              THEN update_value.lineage ->> 'callerTurnId'
            WHEN update_value.kind LIKE 'child_%'
              THEN update_value.lineage ->> 'parentTurnId'
            ELSE update_value.lineage ->> 'causalTurnId' END)::pg_catalog.uuid END
          AND origin.session_id = CASE WHEN pg_catalog.octet_length((CASE
            WHEN update_value.kind IN ('agent_message','agent_steer_instruction')
              THEN update_value.lineage ->> 'callerSessionId'
            ELSE document ->> 'session_id' END)) = 36 AND (CASE
            WHEN update_value.kind IN ('agent_message','agent_steer_instruction')
              THEN update_value.lineage ->> 'callerSessionId'
            ELSE document ->> 'session_id' END) COLLATE pg_catalog."C" OPERATOR(pg_catalog.~) '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN (CASE
            WHEN update_value.kind IN ('agent_message','agent_steer_instruction')
              THEN update_value.lineage ->> 'callerSessionId'
            ELSE document ->> 'session_id' END)::pg_catalog.uuid END
        WHERE update_value.account_id = NEW.account_id
          AND update_value.workspace_id = NEW.workspace_id
          AND update_value.session_id = NEW.session_id
          AND update_value.state = 'delivered'
          AND update_value.delivered_turn_id = NEW.id
          AND update_value.mcp_account_bindings IS NOT DISTINCT FROM bindings
          AND origin.mcp_account_bindings IS NOT DISTINCT FROM bindings
          AND (coalesce(origin.initiating_human_subject_id,
            CASE WHEN origin.initiator_kind = 'subject' THEN origin.initiator_subject_id END)
            IS NOT DISTINCT FROM coalesce(NEW.initiating_human_subject_id,
              CASE WHEN NEW.initiator_kind = 'subject' THEN NEW.initiator_subject_id END)
            OR (
              -- Ordinary workspace-only agent messages execute as a service,
              -- not as the origin's human. Preserve that absence of personal
              -- authority without stranding delivery of the exact receipt.
              update_value.kind = 'agent_message'
              AND NEW.initiator_kind = 'service'
              AND NEW.initiating_human_subject_id IS NULL
              AND origin.personal_connection_delegations = '[]'::jsonb
              AND update_value.personal_connection_delegations = '[]'::jsonb
              AND delegations = '[]'::jsonb
              AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(bindings) selected
                WHERE selected ->> 'subjectScope' IS DISTINCT FROM 'workspace')
            ))
      ) AND NOT EXISTS (
        SELECT 1 FROM session_system_updates update_value
        WHERE update_value.account_id = NEW.account_id
          AND update_value.workspace_id = NEW.workspace_id
          AND update_value.session_id = NEW.session_id
          AND update_value.state = 'delivered'
          AND update_value.delivered_turn_id = NEW.id
          AND update_value.mcp_account_bindings IS DISTINCT FROM bindings
      ) INTO inherited_bindings;
    END IF;

    IF TG_TABLE_NAME = 'session_turns' AND document ->> 'execution_context_turn_id' IS NOT NULL
      -- 0755: freshly resolved accounts are admitted live below.
      AND EXISTS (SELECT 1 FROM {{schema}}.session_turns context_turn
        WHERE context_turn.id = (document ->> 'execution_context_turn_id')::uuid
          AND context_turn.account_id = NEW.account_id
          AND context_turn.workspace_id = NEW.workspace_id
          AND nullif(context_turn.mcp_account_bindings, 'null'::jsonb) IS NOT DISTINCT FROM bindings)
    THEN
      inherited_bindings := true; -- validated by inbox_execution_context_fence
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(bindings) LOOP
      IF item ->> 'subjectScope' = 'workspace' AND NOT inherited_bindings THEN
        SELECT c.* INTO connection_row FROM opengeni_private.read_sender_connection(
          NEW.account_id, NEW.workspace_id, (item ->> 'connectionId')::uuid, NULL) c;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'MCP workspace account missing' USING ERRCODE = '42501';
        END IF;
        IF item ->> 'originWorkspaceId' IS DISTINCT FROM NEW.workspace_id::text
          OR connection_row.authority_scope IS DISTINCT FROM 'workspace'
          OR connection_row.workspace_id IS DISTINCT FROM NEW.workspace_id
          OR connection_row.origin_workspace_id IS DISTINCT FROM NEW.workspace_id
          OR connection_row.status IS DISTINCT FROM 'active'
          OR lower(connection_row.provider_domain) IS DISTINCT FROM lower(item ->> 'providerDomain')
          OR connection_row.kind IS DISTINCT FROM item ->> 'kind'
          OR (item ->> 'connectionAuthorityGeneration')::bigint IS DISTINCT FROM connection_row.authority_generation
        THEN RAISE EXCEPTION 'MCP workspace account identity changed' USING ERRCODE = '42501'; END IF;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $_$;

CREATE FUNCTION opengeni_private.fence_new_session_draft_project_provenance_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  project_channel_is_valid boolean;
  old_compute_snapshot jsonb;
  new_compute_snapshot jsonb;
  provenance_was_replaced boolean;
BEGIN
  IF NEW."session_options" ? 'selectedProjectChannelId' THEN
    project_channel_is_valid :=
      jsonb_typeof(NEW."session_options" -> 'selectedProjectChannelId') = 'string'
      AND (NEW."session_options" ->> 'selectedProjectChannelId')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

    NEW."selected_project_channel_id" := CASE
      WHEN project_channel_is_valid
      THEN (NEW."session_options" ->> 'selectedProjectChannelId')::uuid
      ELSE NULL
    END;
    NEW."selected_project_compute_snapshot" := CASE
      WHEN jsonb_typeof(NEW."session_options" -> 'selectedProjectChannelId') = 'null'
        OR project_channel_is_valid
      THEN
        CASE WHEN NEW."session_options" ? 'sandboxBackend'
          THEN jsonb_build_object('sandboxBackend', NEW."session_options" -> 'sandboxBackend')
          ELSE '{}'::jsonb END
        || CASE WHEN NEW."session_options" ? 'targetSandboxId'
          THEN jsonb_build_object('targetSandboxId', NEW."session_options" -> 'targetSandboxId')
          ELSE '{}'::jsonb END
        || CASE WHEN NEW."session_options" ? 'workingDir'
          THEN jsonb_build_object('workingDir', NEW."session_options" -> 'workingDir')
          ELSE '{}'::jsonb END
      ELSE NULL
    END;
    NEW."session_options" := NEW."session_options" - 'selectedProjectChannelId';
  ELSIF TG_OP = 'UPDATE' THEN
    old_compute_snapshot :=
      CASE WHEN OLD."session_options" ? 'sandboxBackend'
        THEN jsonb_build_object('sandboxBackend', OLD."session_options" -> 'sandboxBackend')
        ELSE '{}'::jsonb END
      || CASE WHEN OLD."session_options" ? 'targetSandboxId'
        THEN jsonb_build_object('targetSandboxId', OLD."session_options" -> 'targetSandboxId')
        ELSE '{}'::jsonb END
      || CASE WHEN OLD."session_options" ? 'workingDir'
        THEN jsonb_build_object('workingDir', OLD."session_options" -> 'workingDir')
        ELSE '{}'::jsonb END;
    new_compute_snapshot :=
      CASE WHEN NEW."session_options" ? 'sandboxBackend'
        THEN jsonb_build_object('sandboxBackend', NEW."session_options" -> 'sandboxBackend')
        ELSE '{}'::jsonb END
      || CASE WHEN NEW."session_options" ? 'targetSandboxId'
        THEN jsonb_build_object('targetSandboxId', NEW."session_options" -> 'targetSandboxId')
        ELSE '{}'::jsonb END
      || CASE WHEN NEW."session_options" ? 'workingDir'
        THEN jsonb_build_object('workingDir', NEW."session_options" -> 'workingDir')
        ELSE '{}'::jsonb END;

    IF old_compute_snapshot IS DISTINCT FROM new_compute_snapshot THEN
      -- An old binary cannot name either additive column, so both arrive here
      -- byte-identical to OLD. A new binary replaces the pair and stamps the
      -- incoming compute snapshot in the same UPDATE. Require both pieces of
      -- evidence before retaining provenance: merely changing one stale column
      -- must not make a later compute ABA capable of revalidating it.
      provenance_was_replaced :=
        (
          NEW."selected_project_channel_id"
            IS DISTINCT FROM OLD."selected_project_channel_id"
          OR NEW."selected_project_compute_snapshot"
            IS DISTINCT FROM OLD."selected_project_compute_snapshot"
        )
        AND (
          (
            NEW."selected_project_channel_id" IS NULL
            AND NEW."selected_project_compute_snapshot" IS NULL
          )
          OR NEW."selected_project_compute_snapshot"
            IS NOT DISTINCT FROM new_compute_snapshot
        );

      IF NOT provenance_was_replaced THEN
        NEW."selected_project_channel_id" := NULL;
        NEW."selected_project_compute_snapshot" := NULL;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END
$_$;

CREATE FUNCTION opengeni_private.fence_session_execution_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.execution_context_turn_id IS NOT NULL THEN
      RAISE EXCEPTION 'a new session has no started execution context' USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.execution_authority_epoch IS DISTINCT FROM OLD.execution_authority_epoch THEN
    NEW.execution_context_turn_id := NULL;
  ELSIF NEW.execution_context_turn_id IS DISTINCT FROM OLD.execution_context_turn_id THEN
    IF NEW.execution_context_turn_id IS NULL THEN
      IF EXISTS (SELECT 1 FROM session_turns WHERE id = OLD.execution_context_turn_id) THEN
        RAISE EXCEPTION 'execution context is lifecycle-owned' USING ERRCODE = '42501';
      END IF;
    ELSIF NOT EXISTS (
      SELECT 1 FROM session_turns t JOIN session_turn_attempts a
        ON a.id = t.active_attempt_id AND a.turn_id = t.id AND a.session_id = t.session_id
        AND a.workspace_id = t.workspace_id AND a.account_id = t.account_id
      JOIN session_events e ON e.turn_id = t.id AND e.turn_attempt_id = a.id
        AND e.account_id = t.account_id AND e.workspace_id = t.workspace_id AND e.session_id = t.session_id
      WHERE t.id = NEW.execution_context_turn_id AND t.session_id = NEW.id
        AND t.account_id = NEW.account_id AND t.workspace_id = NEW.workspace_id
        AND t.source IN ('user','api') AND t.scheduled_task_run_id IS NULL
        AND t.status = 'running' AND NEW.active_turn_id = t.id
        AND e.type = 'turn.started' AND e.turn_association = 'current'
        AND a.authority_epoch BETWEEN NEW.execution_authority_epoch AND NEW.authority_epoch
        AND NOT EXISTS (SELECT 1 FROM session_events earlier JOIN session_turn_attempts prior
          ON prior.id = earlier.turn_attempt_id AND prior.turn_id = earlier.turn_id
            AND prior.session_id = earlier.session_id AND prior.workspace_id = earlier.workspace_id
            AND prior.account_id = earlier.account_id
          WHERE earlier.account_id = e.account_id AND earlier.workspace_id = e.workspace_id
            AND earlier.session_id = e.session_id AND earlier.turn_id = e.turn_id
            AND earlier.type = 'turn.started' AND earlier.turn_association = 'current'
            AND earlier.sequence < e.sequence)
    ) THEN RAISE EXCEPTION 'execution context requires an exact started request' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.fence_slack_bot_post_claim_mode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  acquires_claim boolean;
BEGIN
  IF NEW."claim_holder_id" IS NULL THEN
    NEW."claim_mode" := NULL;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- Rolling old writers insert directly at provider_started. They remain
    -- compatible for their first attempt, but any abandoned attempt is fenced
    -- by the UPDATE branch below.
    IF NEW."claim_mode" IS NULL AND NEW."status" IN ('pending', 'provider_started') THEN
      NEW."claim_mode" := 'send';
    END IF;
    RETURN NEW;
  END IF;

  acquires_claim :=
    OLD."claim_holder_id" IS NULL
    OR OLD."claim_holder_id" IS DISTINCT FROM NEW."claim_holder_id"
    OR OLD."claim_expires_at" IS NULL
    OR OLD."claim_expires_at" <= statement_timestamp();

  IF acquires_claim AND OLD."status" IN ('provider_started', 'outcome_unknown') THEN
    IF NEW."status" <> 'outcome_unknown' OR NEW."claim_mode" <> 'reconcile' THEN
      RAISE EXCEPTION
        'Slack post outcome requires reconciliation before another provider mutation'
        USING ERRCODE = '23514';
    END IF;
  ELSIF acquires_claim AND OLD."status" = 'pending' AND NEW."claim_mode" IS NULL THEN
    -- A rolling old writer may safely claim a request that never crossed the
    -- provider-admission boundary.
    NEW."claim_mode" := 'send';
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.file_private_to_another(p_account uuid, p_workspace uuid, p_file uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE probe_nonce uuid := gen_random_uuid(); found_private boolean;
BEGIN
  IF p_account IS NULL OR p_workspace IS NULL OR p_file IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'file access scope mismatch' USING ERRCODE = '42501'; END IF;
  INSERT INTO opengeni_private.session_file_read_capabilities
    VALUES (pg_backend_pid(), pg_current_xact_id(), probe_nonce, p_account, p_workspace, p_file);
  SELECT EXISTS (SELECT 1 FROM files f
    WHERE f.account_id = p_account AND f.workspace_id = p_workspace AND f.id = p_file
      AND f.status = 'ready' AND f.private_owner_subject_ids IS NOT NULL
      AND NOT coalesce(nullif(current_setting('opengeni.private_file_owner',true),'') = ANY(f.private_owner_subject_ids), false))
    INTO found_private;
  DELETE FROM opengeni_private.session_file_read_capabilities
    WHERE nonce = probe_nonce AND backend_pid = pg_backend_pid();
  RETURN found_private;
END $$;

CREATE FUNCTION opengeni_private.fold_session_event_delta_run(p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_first integer, p_last integer, p_ids uuid[], p_payload jsonb, p_payload_codec_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  turn_status text;
  previous_writer text;
  matched integer;
  removed integer;
BEGIN
  IF p_last <= p_first OR array_length(p_ids, 1) IS DISTINCT FROM p_last - p_first + 1
    OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
    OR (p_payload->>'coalescedUntil')::integer IS DISTINCT FROM p_last
    OR p_payload->'folded'->>'v' IS DISTINCT FROM '1' THEN
    RETURN -1;
  END IF;
  SELECT T.status INTO turn_status FROM session_turns T
  WHERE T.workspace_id = p_workspace_id AND T.session_id = p_session_id AND T.id = p_turn_id;
  IF turn_status IS NULL
    OR turn_status NOT IN ('completed', 'failed', 'cancelled', 'superseded', 'withdrawn_for_edit') THEN
    RETURN -1;
  END IF;
  WITH rows AS (
    SELECT E.id, E.sequence, E.type, E.turn_id, E.producer_id, E.turn_generation,
      E.turn_attempt_id, E.turn_association, E.client_event_id, E.duplicate_of_event_id
    FROM session_events E
    WHERE E.workspace_id = p_workspace_id AND E.session_id = p_session_id
      AND E.sequence BETWEEN p_first AND p_last
    FOR UPDATE
  ), first_row AS (
    SELECT * FROM rows WHERE sequence = p_first
  )
  SELECT count(*) INTO matched
  FROM rows R, first_row F
  WHERE R.id = p_ids[R.sequence - p_first + 1]
    AND R.type IN ('agent.message.delta', 'agent.reasoning.delta')
    AND R.type = F.type
    AND R.producer_id IS NOT DISTINCT FROM F.producer_id
    AND R.turn_generation IS NOT DISTINCT FROM F.turn_generation
    AND R.turn_attempt_id IS NOT DISTINCT FROM F.turn_attempt_id
    AND R.turn_association IS NOT DISTINCT FROM F.turn_association
    AND R.client_event_id IS NULL
    AND R.duplicate_of_event_id IS NULL
    AND R.turn_id = p_turn_id;
  IF matched <> p_last - p_first + 1 THEN
    RETURN -1;
  END IF;
  -- The payload is written with its codec version explicitly (lossless writer).
  previous_writer := current_setting('opengeni.lossless_content_writer', true);
  PERFORM set_config('opengeni.lossless_content_writer', '1', true);
  UPDATE session_events
  SET payload = p_payload, payload_codec_version = p_payload_codec_version
  WHERE workspace_id = p_workspace_id AND session_id = p_session_id AND sequence = p_first;
  PERFORM set_config('opengeni.lossless_content_writer', coalesce(previous_writer, ''), true);
  DELETE FROM session_events
  WHERE workspace_id = p_workspace_id AND session_id = p_session_id
    AND sequence > p_first AND sequence <= p_last;
  GET DIAGNOSTICS removed = ROW_COUNT;
  RETURN removed;
END;
$$;

CREATE FUNCTION opengeni_private.google_drive_object_acl_capability_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'opengeni_private', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM google_drive_object_acl_runtime_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND capability.capability_kind IN ('authorize', 'citation')
  );
$$;

CREATE FUNCTION opengeni_private.governed_learning_derived_uuid(p_operation_id uuid, p_label text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT (
    substr(value, 1, 8) || '-' || substr(value, 9, 4) || '-5' || substr(value, 14, 3)
    || '-' || substr('89ab', 1 + (get_byte(decode(substr(value, 17, 2), 'hex'), 0) & 3), 1)
    || substr(value, 18, 3) || '-' || substr(value, 21, 12)
  )::uuid
  FROM (
    SELECT encode(sha256(convert_to(
      concat('governed-learning-activation:v1:', p_operation_id, ':', p_label), 'UTF8'
    )), 'hex') AS value
  ) digest;
$$;

CREATE FUNCTION opengeni_private.governed_learning_reason_codes_valid(value text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  canonical constant text[] := ARRAY[
    'policy_off', 'evidence_revoked', 'proposal_stale', 'evidence_conflict',
    'confidence_below_floor', 'policy_suggest', 'policy_automatic'
  ]::text[];
  expected text[] := ARRAY[]::text[];
  candidate text;
BEGIN
  IF value IS NULL OR pg_catalog.cardinality(value) NOT BETWEEN 1 AND 7 THEN
    RETURN false;
  END IF;
  FOREACH candidate IN ARRAY canonical LOOP
    IF candidate = ANY(value) THEN
      expected := pg_catalog.array_append(expected, candidate);
    END IF;
  END LOOP;
  RETURN expected = value;
END;
$$;

CREATE FUNCTION opengeni_private.grant_verified_signup_trial_credit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE verified_owner boolean; account_owner boolean; inserted_count integer; model_ids jsonb;
BEGIN
  -- The legacy environment flag and runtime money-grant switch no longer gate
  -- this non-monetary eligibility witness. Neither can re-enable a bonus.
  SELECT candidate.email_verified IS TRUE INTO verified_owner
    FROM auth_users candidate WHERE candidate.id = NEW.auth_user_id;
  SELECT account.external_source = 'better-auth:user' AND account.external_id = NEW.auth_user_id
    INTO account_owner FROM managed_accounts account WHERE account.id = NEW.account_id;
  IF verified_owner IS DISTINCT FROM TRUE OR account_owner IS DISTINCT FROM TRUE
    OR opengeni_private.current_subject_id() IS DISTINCT FROM 'user:' || NEW.auth_user_id
    OR opengeni_private.current_account_id() IS DISTINCT FROM NEW.account_id
    OR NEW.result ->> 'organizationId' IS DISTINCT FROM NEW.account_id::text THEN
    RAISE EXCEPTION 'verified signup eligibility requires an exact new owner' USING ERRCODE = '42501';
  END IF;
  SELECT coalesce(policy->'signupModelIds', policy->'defaultModelIds') INTO model_ids
    FROM opengeni_private.credit_promotion_policy_revisions ORDER BY revision DESC LIMIT 1;
  model_ids := coalesce(model_ids, nullif(pg_catalog.current_setting('opengeni.signup_credit_model_ids', true), '')::jsonb);
  INSERT INTO credit_ledger_entries(account_id, workspace_id, type, amount_micros, source_type, source_id,
    idempotency_key, metadata, eligible_model_ids)
  VALUES (NEW.account_id, NULL, 'grant', 0, 'verified_signup_trial', NEW.auth_user_id,
    'verified-signup-trial:v1:' || NEW.auth_user_id,
    jsonb_build_object('campaign','free_plan_eligibility_v1','creditOfferLabel','Free plan eligibility'),
    CASE WHEN model_ids IS NULL THEN NULL ELSE ARRAY(SELECT jsonb_array_elements_text(model_ids)) END)
  ON CONFLICT (idempotency_key) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count <> 1 THEN
    RAISE EXCEPTION 'verified signup eligibility idempotency collision' USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.guard_activated_tenancy_writer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
BEGIN
  IF NEW.initiator_kind = 'legacy_unattributed'
    AND opengeni_private.session_tenancy_account_activated(NEW.account_id)
  THEN
    RAISE EXCEPTION 'activated organization refuses unattributed workspace writers'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_connect_attempt_origin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF ROW(NEW.id, NEW.account_id, NEW.workspace_id, NEW.subject_id, NEW.idempotency_key_hash,
      NEW.request_digest, NEW.return_url, NEW.external_continuation, NEW.expires_at, NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.workspace_id, OLD.subject_id, OLD.idempotency_key_hash,
      OLD.request_digest, OLD.return_url, OLD.external_continuation, OLD.expires_at, OLD.created_at) THEN
    RAISE EXCEPTION 'Connect origin is immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_editable_artifact_mutable_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  PERFORM set_config(
    'search_path', 'pg_catalog,' || quote_ident(TG_TABLE_SCHEMA) || ',pg_temp', true
  );
  IF TG_TABLE_NAME = 'editable_artifact_materialization_jobs' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.state <> 'pending' OR NEW.attempt_count <> 0
        OR NEW.lease_owner IS NOT NULL OR NEW.lease_expires_at IS NOT NULL
        OR NEW.settled_by_owner IS NOT NULL OR NEW.error_code IS NOT NULL
        OR NEW.started_at IS NOT NULL
        OR NEW.completed_at IS NOT NULL
      THEN
        RAISE EXCEPTION 'materialization jobs must begin pending and unleased'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END IF;
    IF NEW.account_id <> OLD.account_id OR NEW.workspace_id <> OLD.workspace_id
      OR NEW.artifact_id <> OLD.artifact_id OR NEW.id <> OLD.id
      OR NEW.version_id IS DISTINCT FROM OLD.version_id
      OR NEW.input_snapshot_id <> OLD.input_snapshot_id
      OR NEW.target_head_sequence <> OLD.target_head_sequence
      OR NEW.state_hash <> OLD.state_hash OR NEW.format <> OLD.format
      OR NEW.normalized_options <> OLD.normalized_options
      OR NEW.options_hash <> OLD.options_hash OR NEW.codec_id <> OLD.codec_id
      OR NEW.codec_version <> OLD.codec_version
      OR NEW.kernel_version <> OLD.kernel_version
      OR NEW.font_registry_hash <> OLD.font_registry_hash OR NEW.policy_hash <> OLD.policy_hash
      OR NEW.created_at <> OLD.created_at
    THEN
      RAISE EXCEPTION 'invalid materialization job mutation' USING ERRCODE = '23514';
    END IF;
    IF OLD.state IN ('succeeded', 'failed') THEN
      RAISE EXCEPTION 'terminal materialization job is immutable' USING ERRCODE = '23514';
    ELSIF OLD.state = 'pending' THEN
      IF NEW.state <> 'running' OR NEW.attempt_count <> OLD.attempt_count + 1
        OR NEW.settled_by_owner IS NOT NULL
      THEN
        RAISE EXCEPTION 'pending materialization job must be claimed exactly once'
          USING ERRCODE = '23514';
      END IF;
    ELSIF OLD.state = 'running' AND NEW.state = 'running' THEN
      IF NOT (
        -- Heartbeats extend one still-live claim without changing its fencing
        -- token. They cannot resurrect an expired lease or move ownership.
        (NEW.attempt_count = OLD.attempt_count
          AND NEW.lease_owner IS NOT DISTINCT FROM OLD.lease_owner
          AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at
          AND OLD.lease_expires_at > pg_catalog.statement_timestamp()
          AND NEW.lease_expires_at > OLD.lease_expires_at
          AND NEW.settled_by_owner IS NULL)
        OR
        -- Reclaim is a distinct transition: only an expired claim may advance
        -- the attempt-count fence and reset its owner/start/expiration.
        (NEW.attempt_count = OLD.attempt_count + 1
          AND OLD.lease_expires_at <= pg_catalog.statement_timestamp()
          AND NEW.started_at >= OLD.started_at
          AND NEW.settled_by_owner IS NULL)
      )
      THEN
        RAISE EXCEPTION 'invalid materialization renewal or reclaim transition'
          USING ERRCODE = '23514';
      END IF;
    ELSIF OLD.state = 'running' AND NEW.state IN ('succeeded', 'failed') THEN
      IF NOT (
        (NEW.attempt_count = OLD.attempt_count
          AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at
          AND NEW.settled_by_owner IS NOT DISTINCT FROM OLD.lease_owner
          AND OLD.lease_expires_at > pg_catalog.statement_timestamp())
        OR
        (NEW.state = 'failed' AND NEW.error_code = 'attempts_exhausted'
          AND NEW.attempt_count = 1000
          AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at
          AND NEW.settled_by_owner IS NOT DISTINCT FROM OLD.lease_owner
          AND OLD.lease_expires_at <= pg_catalog.statement_timestamp())
      ) THEN
        RAISE EXCEPTION 'materialization settlement attempt is inconsistent'
          USING ERRCODE = '23514';
      END IF;
    ELSE
      RAISE EXCEPTION 'invalid materialization job state transition' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'editable_artifact_live_outbox' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.state <> 'pending' OR NEW.attempt_count <> 0
        OR NEW.lease_owner IS NOT NULL OR NEW.lease_expires_at IS NOT NULL
        OR NEW.next_attempt_at IS DISTINCT FROM NEW.created_at
        OR NEW.last_error_code IS NOT NULL OR NEW.published_at IS NOT NULL
        OR NEW.dead_lettered_at IS NOT NULL
      THEN
        RAISE EXCEPTION 'outbox events must begin pending and unleased'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END IF;
    IF NEW.account_id <> OLD.account_id OR NEW.workspace_id <> OLD.workspace_id
      OR NEW.artifact_id <> OLD.artifact_id OR NEW.id <> OLD.id
      OR NEW.transaction_id IS DISTINCT FROM OLD.transaction_id
      OR NEW.snapshot_id IS DISTINCT FROM OLD.snapshot_id
      OR NEW.event_kind <> OLD.event_kind OR NEW.event <> OLD.event
      OR NEW.created_at <> OLD.created_at OR NEW.attempt_count < OLD.attempt_count
      OR NEW.attempt_count > OLD.attempt_count + 1
      OR OLD.state IN ('published', 'dead_lettered')
    THEN
      RAISE EXCEPTION 'invalid editable artifact outbox mutation' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'editable_artifact_replica_leases' THEN
    IF NEW.account_id <> OLD.account_id OR NEW.workspace_id <> OLD.workspace_id
      OR NEW.artifact_id <> OLD.artifact_id OR NEW.replica_id <> OLD.replica_id
      OR NEW.modality <> OLD.modality
      OR NEW.actor_key <> OLD.actor_key OR NEW.created_at <> OLD.created_at
      OR NEW.applied_head_sequence < OLD.applied_head_sequence
      OR NEW.last_seen_at < OLD.last_seen_at
      OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
    THEN
      RAISE EXCEPTION 'invalid editable artifact replica lease mutation'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.guard_editable_artifact_transaction_child_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE owner_transaction_id text;
DECLARE owner_sequence_end bigint;
DECLARE owner_modality text;
DECLARE published_head bigint;
BEGIN
  PERFORM set_config(
    'search_path', 'pg_catalog,' || quote_ident(TG_TABLE_SCHEMA) || ',pg_temp', true
  );
  IF TG_TABLE_NAME = 'editable_artifact_operations' THEN
    owner_transaction_id := NEW.transaction_id;
  ELSIF TG_TABLE_NAME = 'editable_artifact_idempotency_receipts' THEN
    IF NEW.operation_kind <> 'edit' THEN RETURN NEW; END IF;
    owner_transaction_id := NEW.server_transaction_id;
  ELSIF TG_TABLE_NAME = 'editable_artifact_undo_claims' THEN
    owner_transaction_id := NEW.claiming_transaction_id;
  ELSIF TG_TABLE_NAME = 'editable_artifact_sequence_checkpoints' THEN
    IF NEW.transaction_id IS NULL THEN RETURN NEW; END IF;
    owner_transaction_id := NEW.transaction_id;
  ELSIF TG_TABLE_NAME = 'editable_artifact_live_outbox' THEN
    IF NEW.event_kind <> 'transaction_committed' THEN RETURN NEW; END IF;
    owner_transaction_id := NEW.transaction_id;
  END IF;

  SELECT transaction.sequence_end, transaction.modality
  INTO owner_sequence_end, owner_modality
  FROM editable_artifact_transactions transaction
  WHERE transaction.account_id = NEW.account_id
    AND transaction.workspace_id = NEW.workspace_id
    AND transaction.artifact_id = NEW.artifact_id
    AND transaction.id = owner_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transaction child must follow its transaction header'
      USING ERRCODE = '23503';
  END IF;
  IF TG_TABLE_NAME IN ('editable_artifact_operations', 'editable_artifact_undo_claims')
    AND owner_modality <> 'spreadsheet'
  THEN
    RAISE EXCEPTION 'serialized artifact transactions cannot receive CRDT children'
      USING ERRCODE = '23514';
  END IF;

  SELECT artifact.head_sequence INTO published_head
  FROM editable_artifacts artifact
  WHERE artifact.account_id = NEW.account_id
    AND artifact.workspace_id = NEW.workspace_id
    AND artifact.id = NEW.artifact_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transaction child artifact is missing'
      USING ERRCODE = '23503';
  END IF;
  IF published_head >= owner_sequence_end THEN
    RAISE EXCEPTION 'committed transaction history cannot receive additional children'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.guard_editable_artifact_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE old_snapshot_coverage bigint;
DECLARE new_snapshot_coverage bigint;
DECLARE table_owner name;
BEGIN
  PERFORM set_config(
    'search_path', 'pg_catalog,' || quote_ident(TG_TABLE_SCHEMA) || ',pg_temp', true
  );
  IF NEW.account_id <> OLD.account_id OR NEW.workspace_id <> OLD.workspace_id
    OR NEW.id <> OLD.id OR NEW.modality <> OLD.modality
    OR NEW.created_by_subject_id <> OLD.created_by_subject_id
    OR NEW.created_at <> OLD.created_at
    OR NEW.head_sequence < OLD.head_sequence
    OR NEW.updated_at < OLD.updated_at
    OR (NEW.head_sequence = OLD.head_sequence AND (
      NEW.causal_frontier IS DISTINCT FROM OLD.causal_frontier
      OR NEW.state_hash <> OLD.state_hash
    ))
  THEN
    RAISE EXCEPTION 'invalid editable artifact head or identity mutation'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.authorization_revision < OLD.authorization_revision THEN
    RAISE EXCEPTION 'editable artifact authorization revision cannot regress'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.authorization_revision > OLD.authorization_revision THEN
    SELECT pg_catalog.pg_get_userbyid(relation.relowner) INTO table_owner
    FROM pg_catalog.pg_class relation
    WHERE relation.oid = TG_RELID;
    IF table_owner IS NULL OR current_user <> table_owner THEN
      RAISE EXCEPTION 'editable artifact authorization revision requires its owner capability'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.title <> OLD.title
      OR NEW.lifecycle_state <> OLD.lifecycle_state
      OR NEW.head_sequence <> OLD.head_sequence
      OR NEW.causal_frontier IS DISTINCT FROM OLD.causal_frontier
      OR NEW.state_hash <> OLD.state_hash
      OR NEW.current_snapshot_id IS DISTINCT FROM OLD.current_snapshot_id
    THEN
      RAISE EXCEPTION 'editable artifact authorization revision must advance independently'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  IF OLD.lifecycle_state = 'archived' AND NEW.lifecycle_state <> 'archived' THEN
    RAISE EXCEPTION 'archived editable artifact cannot be reactivated implicitly'
      USING ERRCODE = '23514';
  END IF;
  IF OLD.lifecycle_state = 'archived' AND (
    NEW.head_sequence <> OLD.head_sequence
    OR NEW.causal_frontier IS DISTINCT FROM OLD.causal_frontier
    OR NEW.state_hash <> OLD.state_hash
  ) THEN
    RAISE EXCEPTION 'archived editable artifact authority cannot advance'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.current_snapshot_id IS DISTINCT FROM OLD.current_snapshot_id THEN
    IF NEW.current_snapshot_id IS NULL THEN
      RAISE EXCEPTION 'editable artifact current snapshot cannot be cleared'
        USING ERRCODE = '23514';
    END IF;
    SELECT snapshot.covered_head_sequence INTO new_snapshot_coverage
    FROM editable_artifact_snapshots snapshot
    WHERE snapshot.account_id = NEW.account_id
      AND snapshot.workspace_id = NEW.workspace_id
      AND snapshot.artifact_id = NEW.id
      AND snapshot.id = NEW.current_snapshot_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'editable artifact current snapshot is missing'
        USING ERRCODE = '23503';
    END IF;
    IF OLD.current_snapshot_id IS NOT NULL THEN
      SELECT snapshot.covered_head_sequence INTO old_snapshot_coverage
      FROM editable_artifact_snapshots snapshot
      WHERE snapshot.account_id = OLD.account_id
        AND snapshot.workspace_id = OLD.workspace_id
        AND snapshot.artifact_id = OLD.id
        AND snapshot.id = OLD.current_snapshot_id;
      IF NOT FOUND OR new_snapshot_coverage <= old_snapshot_coverage THEN
        RAISE EXCEPTION 'editable artifact current snapshot coverage must advance'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.guard_external_identity_link_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'pending' OR NEW.revision <> 1 OR NEW.confirm_before <= clock_timestamp()
      OR NEW.confirm_before > clock_timestamp() + interval '11 minutes'
      OR (NEW.expires_at IS NOT NULL AND NEW.expires_at <= clock_timestamp()) THEN
      RAISE EXCEPTION 'invalid identity link request' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.id, NEW.account_id, NEW.external_identity_id, NEW.external_subject_id,
      NEW.external_authorization_revision, NEW.challenge_digest, NEW.confirm_before, NEW.expires_at, NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.external_identity_id, OLD.external_subject_id,
      OLD.external_authorization_revision, OLD.challenge_digest, OLD.confirm_before, OLD.expires_at, OLD.created_at)
    OR NEW.revision <> OLD.revision + 1 OR OLD.status = 'revoked' THEN
    RAISE EXCEPTION 'identity link provenance is immutable' USING ERRCODE = '42501';
  END IF;
  IF NEW.status = 'active' THEN
    IF OLD.status <> 'pending' OR OLD.confirm_before <= clock_timestamp()
      OR (OLD.expires_at IS NOT NULL AND OLD.expires_at <= clock_timestamp())
      OR NOT NEW.permissions <@ OLD.permissions THEN
      RAISE EXCEPTION 'identity link confirmation unavailable' USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.status = 'revoked' THEN
    IF ROW(NEW.native_subject_id, NEW.native_membership_id, NEW.native_authorization_revision,
        NEW.permissions, NEW.confirmed_at) IS DISTINCT FROM
      ROW(OLD.native_subject_id, OLD.native_membership_id, OLD.native_authorization_revision,
        OLD.permissions, OLD.confirmed_at) THEN
      RAISE EXCEPTION 'revocation cannot retarget identity' USING ERRCODE = '42501';
    END IF;
  ELSE RAISE EXCEPTION 'identity link cannot be reset' USING ERRCODE = '42501'; END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_external_link_work_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  l external_identity_links%ROWTYPE;
  t session_turns%ROWTYPE;
  s sessions%ROWTYPE;
  source_snapshot jsonb;
  revision_authority jsonb;
BEGIN
  IF TG_OP <> 'INSERT' OR NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id() THEN
    RAISE EXCEPTION 'external link work scope unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO l FROM external_identity_links WHERE id = NEW.link_id AND account_id = NEW.account_id;
  IF NOT FOUND OR l.native_subject_id IS NULL
    OR NEW.canonical_snapshot #>> '{actor,accountId}' IS DISTINCT FROM NEW.account_id::text
    OR NEW.canonical_snapshot #>> '{actor,linkId}' IS DISTINCT FROM NEW.link_id::text
    OR NEW.canonical_snapshot #>> '{actor,linkRevision}' IS DISTINCT FROM NEW.link_revision::text
    OR NEW.canonical_snapshot #>> '{actor,actingMode}' IS DISTINCT FROM 'linked_native'
    OR NEW.canonical_snapshot #>> '{actor,effectiveSubjectId}' IS DISTINCT FROM l.native_subject_id
    OR NEW.canonical_snapshot #>> '{actor,externalIdentityId}' IS DISTINCT FROM l.external_identity_id::text
    OR NEW.canonical_snapshot #>> '{actor,externalSubjectId}' IS DISTINCT FROM l.external_subject_id
    OR NEW.canonical_snapshot #>> '{actor,externalAuthorizationRevision}' IS DISTINCT FROM l.external_authorization_revision::text
    OR jsonb_typeof(NEW.canonical_snapshot -> 'permissions') IS DISTINCT FROM 'array'
    OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(NEW.canonical_snapshot -> 'permissions') p
      WHERE jsonb_typeof(p) <> 'string' OR NOT (
        l.permissions ? (p #>> '{}') OR
        (l.permissions ? 'workspace:admin' AND p #>> '{}' <> 'secrets:read')
      )
    ) THEN
    RAISE EXCEPTION 'invalid external link work snapshot' USING ERRCODE = '42501';
  END IF;
  IF TG_TABLE_NAME = 'external_link_task_authorities' THEN
    IF NOT EXISTS (SELECT 1 FROM scheduled_tasks task WHERE task.id = NEW.task_id
      AND task.account_id = NEW.account_id AND task.workspace_id = NEW.workspace_id
      AND task.authority_revision = NEW.task_revision) THEN
      RAISE EXCEPTION 'external link task revision unavailable' USING ERRCODE = '42501';
    END IF;
    revision_authority := scheduled_task_revision_authority_snapshot(NEW.account_id, NEW.workspace_id, NEW.task_id, NEW.task_revision);
    IF revision_authority IS NULL OR revision_authority ->> 'subjectId' IS DISTINCT FROM l.native_subject_id
      OR revision_authority ->> 'organizationMembershipId' IS DISTINCT FROM l.native_membership_id::text
      OR revision_authority ->> 'membershipAuthorizationRevision' IS DISTINCT FROM l.native_authorization_revision::text THEN
      RAISE EXCEPTION 'external link task owner changed' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO t FROM session_turns WHERE id = NEW.turn_id AND session_id = NEW.session_id
    AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id;
  SELECT * INTO s FROM sessions WHERE id = NEW.session_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id;
  IF t.id IS NULL OR s.id IS NULL OR t.initiating_human_subject_id IS DISTINCT FROM l.native_subject_id
    OR EXISTS (SELECT 1 FROM session_turn_attempts a WHERE a.turn_id = t.id) THEN
    RAISE EXCEPTION 'external link turn admission unavailable' USING ERRCODE = '42501';
  END IF;
  IF NEW.source_kind = 'direct' THEN
    IF t.source NOT IN ('user','api') OR t.status <> 'queued' OR t.active_attempt_id IS NOT NULL
      OR l.status <> 'active' OR l.revision <> NEW.link_revision
      OR (l.expires_at IS NOT NULL AND l.expires_at <= clock_timestamp()) THEN
      RAISE EXCEPTION 'external link direct admission unavailable' USING ERRCODE = '42501';
    END IF;

  ELSIF NEW.source_kind = 'agent' THEN
    SELECT a.canonical_snapshot INTO source_snapshot FROM external_link_turn_authorities a
      WHERE a.turn_id = NEW.source_turn_id AND a.account_id = NEW.account_id AND a.workspace_id = NEW.workspace_id;
    IF source_snapshot IS DISTINCT FROM NEW.canonical_snapshot OR t.source NOT IN ('goal','system') OR t.status <> 'running'
      OR NOT EXISTS (
        SELECT 1 FROM session_system_updates u JOIN session_turns origin ON origin.id = NEW.source_turn_id
          AND origin.account_id = NEW.account_id AND origin.workspace_id = NEW.workspace_id
        WHERE u.account_id = NEW.account_id AND u.workspace_id = NEW.workspace_id AND u.session_id = NEW.session_id
          AND u.delivered_turn_id = NEW.turn_id AND u.state = 'delivered' AND u.delivered_history_item_id IS NOT NULL
          AND u.kind IN ('agent_message','agent_steer_instruction') AND u.lineage ->> 'callerTurnId' = origin.id::text
          AND u.lineage ->> 'callerSessionId' = origin.session_id::text)
    THEN RAISE EXCEPTION 'external link exact execution source unavailable' USING ERRCODE = '42501'; END IF;
  ELSIF NEW.source_kind IN ('causal','child') THEN

    SELECT a.canonical_snapshot INTO source_snapshot FROM external_link_turn_authorities a
      WHERE a.turn_id = NEW.source_turn_id AND a.account_id = NEW.account_id AND a.workspace_id = NEW.workspace_id;
    IF source_snapshot IS DISTINCT FROM NEW.canonical_snapshot THEN
      RAISE EXCEPTION 'external link source snapshot changed' USING ERRCODE = '42501';
    END IF;
    IF NEW.source_kind = 'child' AND (s.parent_turn_id IS DISTINCT FROM NEW.source_turn_id OR t.status <> 'queued') THEN
      RAISE EXCEPTION 'external link child source unavailable' USING ERRCODE = '42501';
    END IF;
    IF NEW.source_kind = 'child' AND NOT EXISTS (SELECT 1 FROM session_turns source
      WHERE source.id = NEW.source_turn_id AND source.session_id = s.parent_session_id) THEN
      RAISE EXCEPTION 'external link child parent mismatch' USING ERRCODE = '42501';
    END IF;
    IF NEW.source_kind = 'causal' AND (t.source NOT IN ('goal','system') OR t.status <> 'running'
      OR NOT EXISTS (SELECT 1 FROM session_turns source WHERE source.id = NEW.source_turn_id AND source.session_id = t.session_id)) THEN
      RAISE EXCEPTION 'external link causal source unavailable' USING ERRCODE = '42501';
    END IF;
    IF NEW.source_kind = 'causal' AND NOT EXISTS (SELECT 1 FROM session_system_updates u
      WHERE u.account_id = NEW.account_id AND u.workspace_id = NEW.workspace_id AND u.session_id = NEW.session_id
        AND u.delivered_turn_id = NEW.turn_id AND u.state = 'delivered' AND u.delivered_history_item_id IS NOT NULL
        AND ((u.kind = 'goal_continuation' AND u.lineage ->> 'causalTurnId' = NEW.source_turn_id::text)
          OR (u.kind IN ('child_terminal_result','child_requires_action','child_requires_action_resolved','child_paused','child_waiting_capacity','child_progress')
            AND u.lineage ->> 'parentTurnId' = NEW.source_turn_id::text))) THEN
      RAISE EXCEPTION 'external link exact causal delivery unavailable' USING ERRCODE = '42501';
    END IF;
  ELSE
    SELECT a.canonical_snapshot INTO source_snapshot FROM external_link_task_authorities a
      WHERE a.task_id = NEW.source_task_id AND a.task_revision = NEW.source_task_revision
        AND a.account_id = NEW.account_id AND a.workspace_id = NEW.workspace_id;
    IF source_snapshot IS DISTINCT FROM NEW.canonical_snapshot OR t.source <> 'system' OR t.status <> 'running' THEN
      RAISE EXCEPTION 'external link scheduled source unavailable' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM scheduled_task_runs r WHERE r.id = t.scheduled_task_run_id
      AND r.task_id = NEW.source_task_id AND r.task_authority_revision = NEW.source_task_revision
      AND r.account_id = NEW.account_id AND r.workspace_id = NEW.workspace_id AND r.session_id = NEW.session_id
      AND r.status = 'dispatched'
      AND r.accepted_execution_snapshot ->> 'causalHumanSubjectId' = l.native_subject_id
      AND validate_scheduled_agent_run_live_authority(NEW.account_id, NEW.workspace_id, r.id) IS NULL) THEN
      RAISE EXCEPTION 'external link scheduled run mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_binding_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF ROW(NEW.id, NEW.account_id, NEW.workspace_id, NEW.owner_subject_id,
      NEW.authorization_revision, NEW.operation_id, NEW.request_digest, NEW.definition, NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.workspace_id, OLD.owner_subject_id,
      OLD.authorization_revision, OLD.operation_id, OLD.request_digest, OLD.definition, OLD.created_at)
    OR OLD.status <> 'active' OR NEW.status <> 'revoked'
    OR NEW.generation <> OLD.generation + 1 OR NEW.revoked_at IS NULL THEN
    RAISE EXCEPTION 'host binding identity is immutable and revocation is terminal' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_child_turn_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  s sessions%ROWTYPE;
  p sessions%ROWTYPE;
  t session_turns%ROWTYPE;
  a host_mcp_turn_authorities%ROWTYPE;
  d host_mcp_delegations%ROWTYPE;
  b host_mcp_bindings%ROWTYPE;
  membership jsonb;
  expected jsonb;
BEGIN
  IF TG_OP <> 'INSERT' OR NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NEW.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'host child authority scope unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || NEW.account_id::text, 0));
  SELECT value INTO membership FROM jsonb_array_elements(list_self_organization_memberships(NEW.owner_subject_id))
    WHERE value ->> 'organizationId' = NEW.account_id::text AND value ->> 'status' = 'active';
  IF membership IS NULL OR NOT (EXISTS (SELECT 1 FROM workspace_memberships w
    WHERE w.workspace_id = NEW.workspace_id AND w.subject_id = NEW.owner_subject_id)
    OR coalesce(membership ->> 'personalWorkspaceId' = NEW.workspace_id::text, false)) THEN
    RAISE EXCEPTION 'host child membership unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO s FROM sessions WHERE id = NEW.session_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR SHARE;
  IF NOT FOUND OR s.parent_session_id IS NULL OR s.parent_turn_id IS NULL
    OR (s.visibility = 'user_private' AND s.owner_subject_id IS DISTINCT FROM NEW.owner_subject_id) THEN
    RAISE EXCEPTION 'host child parent unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO p FROM sessions WHERE id = s.parent_session_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR SHARE;
  IF NOT FOUND OR p.visibility <> s.visibility THEN
    RAISE EXCEPTION 'host child visibility changed' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM session_turns WHERE id = NEW.turn_id AND session_id = NEW.session_id
    AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR SHARE;
  IF NOT FOUND OR t.status <> 'queued' OR t.active_attempt_id IS NOT NULL OR t.source NOT IN ('user','api')
    OR t.initiating_human_subject_id IS DISTINCT FROM NEW.owner_subject_id
    OR EXISTS (SELECT 1 FROM session_turns other WHERE other.session_id = s.id AND other.id <> t.id)
    OR EXISTS (SELECT 1 FROM session_turn_attempts attempt WHERE attempt.turn_id = t.id)
    OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(s.tools) tool WHERE tool ->> 'kind' = 'mcp' AND tool ->> 'id' = NEW.server_id) THEN
    RAISE EXCEPTION 'host child initial turn unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO a FROM host_mcp_turn_authorities WHERE turn_id = s.parent_turn_id AND session_id = s.parent_session_id
    AND server_id = NEW.server_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id;
  IF NOT FOUND OR a.binding_id <> NEW.binding_id OR a.delegation_id <> NEW.delegation_id
    OR a.canonical_snapshot ->> 'targetSessionAuthorityEpoch' IS DISTINCT FROM p.authority_epoch::text
    OR a.canonical_snapshot ->> 'targetSessionVisibility' IS DISTINCT FROM p.visibility
    OR a.canonical_snapshot ->> 'ownerOrganizationMembershipId' IS DISTINCT FROM membership ->> 'id'
    OR a.canonical_snapshot ->> 'ownerMembershipAuthorizationRevision' IS DISTINCT FROM membership ->> 'authorizationRevision' THEN
    RAISE EXCEPTION 'host child source changed' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM host_mcp_delegations WHERE id = NEW.delegation_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR d.status <> 'active' OR d.revoked_at IS NOT NULL OR d.grant_definition ->> 'mode' <> 'always'
    OR d.generation::text IS DISTINCT FROM a.canonical_snapshot ->> 'delegationGeneration'
    OR d.owner_authorization_revision::text IS DISTINCT FROM membership ->> 'authorizationRevision' THEN
    RAISE EXCEPTION 'host child delegation unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO b FROM host_mcp_bindings WHERE id = NEW.binding_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR b.status <> 'active' OR b.revoked_at IS NOT NULL OR b.generation <> d.binding_generation
    OR b.generation::text IS DISTINCT FROM a.canonical_snapshot ->> 'bindingGeneration'
    OR b.definition IS DISTINCT FROM a.canonical_snapshot -> 'definition' THEN
    RAISE EXCEPTION 'host child binding unavailable' USING ERRCODE = '42501';
  END IF;
  expected := a.canonical_snapshot || jsonb_build_object('targetSessionId',s.id,
    'targetSessionAuthorityEpoch',s.authority_epoch,'targetSessionVisibility',s.visibility,
    'acceptedWork',jsonb_build_object('kind','turn','turnId',t.id),
    'source',jsonb_build_object('kind','child_turn','sessionId',p.id,'turnId',s.parent_turn_id));
  IF NEW.canonical_snapshot IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'host child authority is not an exact copy' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_delegation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE binding host_mcp_bindings%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF ROW(NEW.id, NEW.account_id, NEW.workspace_id, NEW.owner_subject_id,
        NEW.owner_authorization_revision, NEW.binding_id, NEW.binding_generation,
        NEW.operation_id, NEW.request_digest, NEW.grant_definition, NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.workspace_id, OLD.owner_subject_id,
        OLD.owner_authorization_revision, OLD.binding_id, OLD.binding_generation,
        OLD.operation_id, OLD.request_digest, OLD.grant_definition, OLD.created_at)
      OR OLD.status <> 'active' OR NEW.status <> 'revoked'
      OR NEW.generation <> OLD.generation + 1 OR NEW.revoked_at IS NULL THEN
      RAISE EXCEPTION 'host delegation identity is immutable and revocation is terminal' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;
  SELECT b.* INTO binding FROM host_mcp_bindings b WHERE b.id = NEW.binding_id FOR SHARE;
  IF NOT FOUND OR binding.status <> 'active' OR binding.revoked_at IS NOT NULL
    OR binding.account_id <> NEW.account_id OR binding.workspace_id <> NEW.workspace_id
    OR binding.owner_subject_id <> NEW.owner_subject_id
    OR binding.authorization_revision <> NEW.owner_authorization_revision
    OR binding.generation <> NEW.binding_generation
    OR NEW.status <> 'active' OR NEW.generation <> 1 OR NEW.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'host delegation binding unavailable' USING ERRCODE = '42501';
  END IF;
  IF (NEW.grant_definition ->> 'scope') IS DISTINCT FROM 'user'
    OR coalesce(NEW.grant_definition ->> 'mode', '') NOT IN ('session','always')
    OR coalesce(NEW.grant_definition ->> 'context', '') NOT IN ('user_private','workspace_shared')
    OR jsonb_typeof(NEW.grant_definition -> 'workspaceSharedAcknowledged') IS DISTINCT FROM 'boolean'
    OR (NEW.grant_definition ->> 'context' = 'workspace_shared'
      AND NEW.grant_definition -> 'workspaceSharedAcknowledged' <> 'true'::jsonb)
    OR NEW.grant_definition - ARRAY['scope','mode','context','sessionId','expectedAuthorityEpoch','workspaceSharedAcknowledged'] <> '{}'::jsonb
    OR ((NEW.grant_definition ->> 'sessionId') IS NULL) IS DISTINCT FROM
       ((NEW.grant_definition ->> 'expectedAuthorityEpoch') IS NULL)
    OR (NEW.grant_definition ->> 'mode' = 'session' AND NEW.grant_definition ->> 'sessionId' IS NULL)
    OR (NEW.grant_definition ->> 'mode' = 'always' AND NEW.grant_definition ->> 'sessionId' IS NOT NULL)
  THEN RAISE EXCEPTION 'invalid host delegation scope' USING ERRCODE = '22023'; END IF;
  IF NEW.grant_definition ->> 'sessionId' IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM sessions s WHERE s.id = (NEW.grant_definition ->> 'sessionId')::uuid
      AND s.account_id = NEW.account_id AND s.workspace_id = NEW.workspace_id
      AND s.visibility = NEW.grant_definition ->> 'context'
      AND s.authority_epoch = (NEW.grant_definition ->> 'expectedAuthorityEpoch')::bigint
      AND (s.visibility = 'workspace_shared' OR s.owner_subject_id = NEW.owner_subject_id)
  ) THEN RAISE EXCEPTION 'host delegation session unavailable' USING ERRCODE = '42501'; END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_inherited_turn_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  s sessions%ROWTYPE;
  t session_turns%ROWTYPE;
  prior host_mcp_turn_authorities%ROWTYPE;
  d host_mcp_delegations%ROWTYPE;
  b host_mcp_bindings%ROWTYPE;
  membership jsonb;
  expected jsonb;
  causal_id text;
BEGIN
  IF TG_OP <> 'INSERT' OR NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NEW.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR current_setting('opengeni.session_inference_claim', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'host inherited authority scope unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || NEW.account_id::text, 0));
  SELECT value INTO membership FROM jsonb_array_elements(list_self_organization_memberships(NEW.owner_subject_id))
    WHERE value ->> 'organizationId' = NEW.account_id::text AND value ->> 'status' = 'active';
  IF membership IS NULL OR NOT (EXISTS (
    SELECT 1 FROM workspace_memberships w WHERE w.workspace_id = NEW.workspace_id AND w.subject_id = NEW.owner_subject_id
  ) OR coalesce(membership ->> 'personalWorkspaceId' = NEW.workspace_id::text, false)) THEN
    RAISE EXCEPTION 'host inherited membership unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO s FROM sessions WHERE id = NEW.session_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR UPDATE;
  IF NOT FOUND OR (s.visibility = 'user_private' AND s.owner_subject_id IS DISTINCT FROM NEW.owner_subject_id) THEN
    RAISE EXCEPTION 'host inherited session unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM session_turns WHERE id = NEW.turn_id AND session_id = NEW.session_id
    AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR UPDATE;
  IF NOT FOUND OR t.source NOT IN ('goal','system') OR t.status <> 'running'
    OR t.execution_generation <> 1 OR t.active_attempt_id IS NULL OR t.scheduled_task_run_id IS NOT NULL
    OR t.initiating_human_subject_id IS DISTINCT FROM NEW.owner_subject_id
    OR EXISTS (SELECT 1 FROM session_turn_attempts a WHERE a.turn_id = t.id AND a.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'host inherited turn unavailable' USING ERRCODE = '42501';
  END IF;
  causal_id := NEW.canonical_snapshot #>> '{source,turnId}';
  IF causal_id IS NULL OR causal_id = NEW.turn_id::text
    OR NEW.canonical_snapshot #>> '{source,sessionId}' IS DISTINCT FROM NEW.session_id::text THEN
    RAISE EXCEPTION 'host inherited source unavailable' USING ERRCODE = '42501';
  END IF;
  -- The canonical claim has already delivered the exact machine input. Never
  -- inherit from the latest turn, a creator, or an unconsumed queued notice.
  IF NOT EXISTS (SELECT 1 FROM session_system_updates u
    WHERE u.account_id = NEW.account_id AND u.workspace_id = NEW.workspace_id AND u.session_id = NEW.session_id
      AND u.delivered_turn_id = NEW.turn_id AND u.state = 'delivered' AND u.delivered_history_item_id IS NOT NULL
      AND ((u.kind = 'goal_continuation' AND u.lineage ->> 'causalTurnId' = causal_id)
        OR (u.kind IN ('child_terminal_result','child_requires_action','child_requires_action_resolved','child_paused','child_waiting_capacity','child_progress')
          AND u.lineage ->> 'parentTurnId' = causal_id))) THEN
    RAISE EXCEPTION 'host inherited causal delivery unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO prior FROM host_mcp_turn_authorities WHERE turn_id = causal_id::uuid
    AND server_id = NEW.server_id AND session_id = NEW.session_id AND workspace_id = NEW.workspace_id
    AND account_id = NEW.account_id AND owner_subject_id = NEW.owner_subject_id;
  IF NOT FOUND OR prior.binding_id <> NEW.binding_id OR prior.delegation_id <> NEW.delegation_id
    OR prior.canonical_snapshot ->> 'targetSessionVisibility' IS DISTINCT FROM s.visibility
    OR prior.canonical_snapshot ->> 'targetSessionAuthorityEpoch' IS DISTINCT FROM s.authority_epoch::text
    OR prior.canonical_snapshot ->> 'ownerOrganizationMembershipId' IS DISTINCT FROM membership ->> 'id'
    OR prior.canonical_snapshot ->> 'ownerMembershipAuthorizationRevision' IS DISTINCT FROM membership ->> 'authorizationRevision' THEN
    RAISE EXCEPTION 'host inherited source changed' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM host_mcp_delegations WHERE id = NEW.delegation_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR d.status <> 'active' OR d.revoked_at IS NOT NULL OR d.binding_id <> NEW.binding_id
    OR d.generation::text IS DISTINCT FROM prior.canonical_snapshot ->> 'delegationGeneration'
    OR d.owner_authorization_revision::text IS DISTINCT FROM membership ->> 'authorizationRevision' THEN
    RAISE EXCEPTION 'host inherited delegation unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO b FROM host_mcp_bindings WHERE id = NEW.binding_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR b.status <> 'active' OR b.revoked_at IS NOT NULL OR b.generation <> d.binding_generation
    OR b.generation::text IS DISTINCT FROM prior.canonical_snapshot ->> 'bindingGeneration'
    OR b.definition IS DISTINCT FROM prior.canonical_snapshot -> 'definition'
    OR b.authorization_revision <> d.owner_authorization_revision THEN
    RAISE EXCEPTION 'host inherited binding unavailable' USING ERRCODE = '42501';
  END IF;
  expected := prior.canonical_snapshot || jsonb_build_object(
    'acceptedWork', jsonb_build_object('kind','turn','turnId',NEW.turn_id),
    'source', jsonb_build_object('kind','inherited_turn','sessionId',NEW.session_id,'turnId',causal_id));
  IF NEW.canonical_snapshot IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'host inherited authority is not an exact copy' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_resolver_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE permissions_value jsonb;
BEGIN
  SELECT credential.permissions INTO permissions_value FROM api_keys credential
  WHERE credential.account_id = NEW.account_id
    AND 'api_key:' || credential.id::text = opengeni_private.current_subject_id()
    AND credential.workspace_id IS NULL AND credential.credential_kind = 'organization'
    AND credential.revoked_at IS NULL
    AND (credential.expires_at IS NULL OR credential.expires_at > clock_timestamp())
  FOR SHARE;
  IF NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NOT coalesce(permissions_value ? 'workspace:admin', false) THEN
    RAISE EXCEPTION 'organization service administration required' USING ERRCODE = '42501';
  END IF;
  IF TG_TABLE_NAME = 'host_mcp_resolvers' THEN
    IF TG_OP = 'UPDATE' THEN
      IF ROW(NEW.id, NEW.account_id, NEW.external_source, NEW.created_at)
        IS DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.external_source, OLD.created_at)
        OR NEW.generation <> OLD.generation + 1 THEN
        RAISE EXCEPTION 'resolver identity or generation conflict' USING ERRCODE = '40001';
      END IF;
    ELSIF NEW.generation <> 1 THEN
      RAISE EXCEPTION 'initial resolver generation invalid' USING ERRCODE = '22023';
    END IF;
  ELSIF NEW.actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'resolver operation actor invalid' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_scheduled_turn_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  t session_turns%ROWTYPE;
  s sessions%ROWTYPE;
  r scheduled_task_runs%ROWTYPE;
  a host_mcp_task_authorities%ROWTYPE;
  d host_mcp_delegations%ROWTYPE;
  b host_mcp_bindings%ROWTYPE;
  membership jsonb;
  expected jsonb;
  origin jsonb;
BEGIN
  IF TG_OP <> 'INSERT' OR NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NEW.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR current_setting('opengeni.session_inference_claim', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'host scheduled turn scope unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || NEW.account_id::text, 0));
  SELECT value INTO membership FROM jsonb_array_elements(list_self_organization_memberships(NEW.owner_subject_id))
    WHERE value ->> 'organizationId' = NEW.account_id::text AND value ->> 'status' = 'active';
  SELECT * INTO s FROM sessions WHERE id = NEW.session_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR SHARE;
  IF NOT FOUND OR membership IS NULL OR (s.visibility = 'user_private' AND s.owner_subject_id IS DISTINCT FROM NEW.owner_subject_id) THEN
    RAISE EXCEPTION 'host scheduled session authority unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM session_turns WHERE id = NEW.turn_id AND session_id = NEW.session_id
    AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR SHARE;
  IF NOT FOUND OR t.source <> 'system' OR t.status <> 'running' OR t.execution_generation <> 1
    OR t.active_attempt_id IS NULL OR t.scheduled_task_run_id IS NULL
    OR t.initiating_human_subject_id IS DISTINCT FROM NEW.owner_subject_id
    OR EXISTS (SELECT 1 FROM session_turn_attempts attempt WHERE attempt.turn_id = t.id AND attempt.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'host scheduled turn unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO r FROM scheduled_task_runs WHERE id = t.scheduled_task_run_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND session_id = NEW.session_id FOR SHARE;
  IF NOT FOUND OR r.status <> 'dispatched' OR r.accepted_execution_snapshot IS NULL
    OR r.accepted_execution_snapshot ->> 'causalHumanSubjectId' IS DISTINCT FROM NEW.owner_subject_id
    OR validate_scheduled_agent_run_live_authority(NEW.account_id, NEW.workspace_id, r.id) IS NOT NULL THEN
    RAISE EXCEPTION 'host scheduled run authority unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO a FROM host_mcp_task_authorities WHERE task_id = r.task_id AND task_authority_revision = r.task_authority_revision
    AND server_id = NEW.server_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id
    AND owner_subject_id = NEW.owner_subject_id;
  IF NOT FOUND OR a.binding_id <> NEW.binding_id OR a.delegation_id <> NEW.delegation_id
    OR a.canonical_snapshot ->> 'taskExecutionDigest' IS DISTINCT FROM r.task_execution_digest
    OR a.canonical_snapshot ->> 'context' IS DISTINCT FROM s.visibility
    OR a.canonical_snapshot ->> 'ownerOrganizationMembershipId' IS DISTINCT FROM membership ->> 'id'
    OR a.canonical_snapshot ->> 'ownerMembershipAuthorizationRevision' IS DISTINCT FROM membership ->> 'authorizationRevision' THEN
    RAISE EXCEPTION 'host scheduled selection changed' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM host_mcp_delegations WHERE id = NEW.delegation_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR d.status <> 'active' OR d.revoked_at IS NOT NULL
    OR d.generation::text IS DISTINCT FROM a.canonical_snapshot ->> 'delegationGeneration'
    OR d.owner_authorization_revision::text IS DISTINCT FROM membership ->> 'authorizationRevision'
    OR (d.grant_definition ->> 'mode' = 'session' AND (
      d.grant_definition ->> 'sessionId' IS DISTINCT FROM s.id::text
      OR d.grant_definition ->> 'expectedAuthorityEpoch' IS DISTINCT FROM s.authority_epoch::text)) THEN
    RAISE EXCEPTION 'host scheduled delegation unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO b FROM host_mcp_bindings WHERE id = NEW.binding_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR b.status <> 'active' OR b.revoked_at IS NOT NULL OR b.generation <> d.binding_generation
    OR b.generation::text IS DISTINCT FROM a.canonical_snapshot ->> 'bindingGeneration'
    OR b.definition IS DISTINCT FROM a.canonical_snapshot -> 'definition' THEN
    RAISE EXCEPTION 'host scheduled binding unavailable' USING ERRCODE = '42501';
  END IF;
  origin := jsonb_build_object('taskId',r.task_id,'taskAuthorityRevision',r.task_authority_revision,'runId',r.id);
  expected := (a.canonical_snapshot - ARRAY['taskId','taskAuthorityRevision','taskExecutionDigest','context'])
    || jsonb_build_object('targetSessionId',s.id,'targetSessionVisibility',s.visibility,'targetSessionAuthorityEpoch',s.authority_epoch,
      'acceptedWork',origin || jsonb_build_object('kind','scheduled_task'),'scheduledOrigin',origin,
      'source',jsonb_build_object('kind','scheduled_task'));
  IF NEW.canonical_snapshot IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'host scheduled snapshot is not canonical' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_task_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  t scheduled_tasks%ROWTYPE;
  s sessions%ROWTYPE;
  d host_mcp_delegations%ROWTYPE;
  b host_mcp_bindings%ROWTYPE;
  membership jsonb;
  revision_authority jsonb;
  expected jsonb;
  target_context text := 'workspace_shared';
BEGIN
  IF TG_OP <> 'INSERT' OR NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NEW.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'host task authority scope unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || NEW.account_id::text, 0));
  SELECT value INTO membership FROM jsonb_array_elements(list_self_organization_memberships(NEW.owner_subject_id))
    WHERE value ->> 'organizationId' = NEW.account_id::text AND value ->> 'status' = 'active';
  IF membership IS NULL OR NOT (EXISTS (
    SELECT 1 FROM workspace_memberships w WHERE w.workspace_id = NEW.workspace_id AND w.subject_id = NEW.owner_subject_id
  ) OR coalesce(membership ->> 'personalWorkspaceId' = NEW.workspace_id::text, false)) THEN
    RAISE EXCEPTION 'host task membership unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM scheduled_tasks WHERE id = NEW.task_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND authority_revision = NEW.task_authority_revision FOR SHARE;
  IF NOT FOUND OR t.deleted_at IS NOT NULL OR t.action ->> 'kind' <> 'agent_turn' THEN
    RAISE EXCEPTION 'host task revision unavailable' USING ERRCODE = '42501';
  END IF;
  revision_authority := scheduled_task_revision_authority_snapshot(NEW.account_id, NEW.workspace_id, NEW.task_id, NEW.task_authority_revision);
  IF revision_authority IS NULL OR revision_authority ->> 'subjectId' IS DISTINCT FROM NEW.owner_subject_id
    OR revision_authority ->> 'organizationMembershipId' IS DISTINCT FROM membership ->> 'id'
    OR revision_authority ->> 'membershipAuthorizationRevision' IS DISTINCT FROM membership ->> 'authorizationRevision' THEN
    RAISE EXCEPTION 'host task causal authority unavailable' USING ERRCODE = '42501';
  END IF;
  IF t.run_mode = 'existing_session' THEN
    SELECT * INTO s FROM sessions WHERE id = t.reusable_session_id AND workspace_id = NEW.workspace_id AND account_id = NEW.account_id FOR SHARE;
    IF NOT FOUND OR (s.visibility = 'user_private' AND s.owner_subject_id IS DISTINCT FROM NEW.owner_subject_id) THEN
      RAISE EXCEPTION 'host task target unavailable' USING ERRCODE = '42501';
    END IF;
    target_context := s.visibility;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
    CASE WHEN t.run_mode = 'existing_session' THEN s.tools ELSE t.agent_config -> 'tools' END
  ) tool WHERE tool ->> 'kind' = 'mcp' AND tool ->> 'id' = NEW.server_id) THEN
    RAISE EXCEPTION 'host task server is not selected' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM host_mcp_delegations WHERE id = NEW.delegation_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR d.status <> 'active' OR d.revoked_at IS NOT NULL OR d.binding_id <> NEW.binding_id
    OR d.owner_authorization_revision::text IS DISTINCT FROM membership ->> 'authorizationRevision'
    OR d.grant_definition ->> 'context' IS DISTINCT FROM target_context
    OR (d.grant_definition ->> 'mode' = 'session' AND (t.run_mode <> 'existing_session'
      OR d.grant_definition ->> 'sessionId' IS DISTINCT FROM s.id::text
      OR d.grant_definition ->> 'expectedAuthorityEpoch' IS DISTINCT FROM s.authority_epoch::text)) THEN
    RAISE EXCEPTION 'host task delegation unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO b FROM host_mcp_bindings WHERE id = NEW.binding_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR b.status <> 'active' OR b.revoked_at IS NOT NULL OR b.generation <> d.binding_generation
    OR b.authorization_revision <> d.owner_authorization_revision OR b.definition ->> 'serverId' IS DISTINCT FROM NEW.server_id THEN
    RAISE EXCEPTION 'host task binding unavailable' USING ERRCODE = '42501';
  END IF;
  expected := jsonb_build_object('version',1,'accountId',NEW.account_id,'workspaceId',NEW.workspace_id,
    'taskId',t.id,'taskAuthorityRevision',t.authority_revision,'taskExecutionDigest',t.execution_digest,
    'ownerSubjectId',NEW.owner_subject_id,'ownerOrganizationMembershipId',membership ->> 'id',
    'ownerMembershipAuthorizationRevision',(membership ->> 'authorizationRevision')::bigint,
    'bindingId',b.id,'bindingGeneration',b.generation,'delegationId',d.id,'delegationGeneration',d.generation,
    'definition',b.definition,'context',target_context);
  IF NEW.canonical_snapshot IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'host task snapshot is not canonical' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_host_mcp_turn_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  s sessions%ROWTYPE;
  t session_turns%ROWTYPE;
  d host_mcp_delegations%ROWTYPE;
  b host_mcp_bindings%ROWTYPE;
  membership jsonb;
  expected jsonb;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'accepted host authority is immutable' USING ERRCODE = '42501';
  END IF;
  IF NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR NEW.workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NEW.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'host authority scope unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || NEW.account_id::text, 0));
  SELECT value INTO membership FROM jsonb_array_elements(list_self_organization_memberships(NEW.owner_subject_id))
    WHERE value ->> 'organizationId' = NEW.account_id::text AND value ->> 'status' = 'active';
  IF membership IS NULL OR NOT (EXISTS (
    SELECT 1 FROM workspace_memberships w WHERE w.workspace_id = NEW.workspace_id AND w.subject_id = NEW.owner_subject_id
  ) OR coalesce(membership ->> 'personalWorkspaceId' = NEW.workspace_id::text, false)) THEN
    RAISE EXCEPTION 'host authority membership unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO s FROM sessions WHERE id = NEW.session_id AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR UPDATE;
  IF NOT FOUND OR (s.visibility = 'user_private' AND s.owner_subject_id IS DISTINCT FROM NEW.owner_subject_id) THEN
    RAISE EXCEPTION 'host authority session unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO t FROM session_turns WHERE id = NEW.turn_id AND session_id = NEW.session_id
    AND account_id = NEW.account_id AND workspace_id = NEW.workspace_id FOR UPDATE;
  IF NOT FOUND OR t.status <> 'queued' OR t.active_attempt_id IS NOT NULL
    OR t.source NOT IN ('user','api') OR t.initiator_kind <> 'subject'
    OR t.initiator_subject_id <> NEW.owner_subject_id
    OR (t.initiating_human_subject_id IS NOT NULL AND t.initiating_human_subject_id <> NEW.owner_subject_id)
    OR t.initiator_context ?| ARRAY['via','viaTruncated','provenanceError','backfill']
    OR EXISTS (SELECT 1 FROM session_turn_attempts a WHERE a.turn_id = t.id AND a.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'host direct turn unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM host_mcp_delegations WHERE id = NEW.delegation_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR d.status <> 'active' OR d.revoked_at IS NOT NULL OR d.binding_id <> NEW.binding_id
    OR d.owner_authorization_revision::text IS DISTINCT FROM membership ->> 'authorizationRevision'
    OR d.grant_definition ->> 'context' IS DISTINCT FROM s.visibility
    OR (d.grant_definition ->> 'mode' = 'session' AND (
      d.grant_definition ->> 'sessionId' IS DISTINCT FROM s.id::text
      OR d.grant_definition ->> 'expectedAuthorityEpoch' IS DISTINCT FROM s.authority_epoch::text)) THEN
    RAISE EXCEPTION 'host delegation unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO b FROM host_mcp_bindings WHERE id = NEW.binding_id AND account_id = NEW.account_id
    AND workspace_id = NEW.workspace_id AND owner_subject_id = NEW.owner_subject_id FOR SHARE;
  IF NOT FOUND OR b.status <> 'active' OR b.revoked_at IS NOT NULL
    OR b.generation <> d.binding_generation OR b.authorization_revision <> d.owner_authorization_revision
    OR b.definition ->> 'serverId' IS DISTINCT FROM NEW.server_id THEN
    RAISE EXCEPTION 'host binding unavailable' USING ERRCODE = '42501';
  END IF;
  expected := jsonb_build_object(
    'version', 1, 'accountId', NEW.account_id, 'workspaceId', NEW.workspace_id,
    'targetSessionId', s.id, 'targetSessionVisibility', s.visibility, 'targetSessionAuthorityEpoch', s.authority_epoch,
    'acceptedWork', jsonb_build_object('kind','turn','turnId',t.id),
    'bindingId', b.id, 'bindingGeneration', b.generation, 'definition', b.definition,
    'ownerSubjectId', NEW.owner_subject_id, 'ownerOrganizationMembershipId', membership ->> 'id',
    'ownerMembershipAuthorizationRevision', (membership ->> 'authorizationRevision')::bigint,
    'delegationId', d.id, 'delegationGeneration', d.generation, 'source', jsonb_build_object('kind','direct')
  );
  IF NEW.canonical_snapshot IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'host authority snapshot is not canonical' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_mcp_operation_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF (to_jsonb(NEW) - ARRAY['original_outcome','original_result','original_result_codec_version',
      'observation_result','observation_result_codec_version','receipt_revision','receipt_digest','observed_at',
      'observation_claim_id','observation_claim_attempt_id','observation_claim_expires_at'])
    IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['original_outcome','original_result','original_result_codec_version',
      'observation_result','observation_result_codec_version','receipt_revision','receipt_digest','observed_at',
      'observation_claim_id','observation_claim_attempt_id','observation_claim_expires_at'])
    OR (OLD.original_outcome<>'captured' AND
      (NEW.original_outcome,NEW.original_result,NEW.original_result_codec_version)
        IS DISTINCT FROM (OLD.original_outcome,OLD.original_result,OLD.original_result_codec_version))
    OR (OLD.receipt_digest IS NOT NULL AND
      (NEW.observation_result,NEW.observation_result_codec_version,NEW.receipt_revision,NEW.receipt_digest,NEW.observed_at,
        NEW.observation_claim_id,NEW.observation_claim_attempt_id,NEW.observation_claim_expires_at)
      IS DISTINCT FROM (OLD.observation_result,OLD.observation_result_codec_version,OLD.receipt_revision,OLD.receipt_digest,OLD.observed_at,
        OLD.observation_claim_id,OLD.observation_claim_attempt_id,OLD.observation_claim_expires_at))
  THEN RAISE EXCEPTION 'MCP operation identity and settled outcomes are immutable'; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.guard_memory_slack_publication_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW."account_id", NEW."workspace_id", NEW."configuration_id",
    NEW."configuration_revision", NEW."connection_id", NEW."slack_team_id",
    NEW."slack_channel_id", NEW."source_type", NEW."source_id",
    NEW."source_version", NEW."source_idempotency_key", NEW."projection",
    NEW."projection_sha256", NEW."importance", NEW."delivery_mode",
    NEW."operation_id", NEW."initiator_kind", NEW."initiator_subject_id",
    NEW."initiating_human_subject_id", NEW."session_id", NEW."turn_id",
    NEW."attempt_id", NEW."created_at"
  ) IS DISTINCT FROM ROW(
    OLD."account_id", OLD."workspace_id", OLD."configuration_id",
    OLD."configuration_revision", OLD."connection_id", OLD."slack_team_id",
    OLD."slack_channel_id", OLD."source_type", OLD."source_id",
    OLD."source_version", OLD."source_idempotency_key", OLD."projection",
    OLD."projection_sha256", OLD."importance", OLD."delivery_mode",
    OLD."operation_id", OLD."initiator_kind", OLD."initiator_subject_id",
    OLD."initiating_human_subject_id", OLD."session_id", OLD."turn_id",
    OLD."attempt_id", OLD."created_at"
  ) THEN
    RAISE EXCEPTION 'memory Slack publication identity is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.guard_pending_tool_event_output_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.event_output IS NOT NULL
    AND nullif(current_setting('opengeni.account_id', true), '') IS NOT NULL
    AND current_setting('opengeni.pending_tool_event_output_v1', true) IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'rich pending tool output requires a v1-aware settlement worker';
  END IF;
  RETURN OLD;
END;
$$;

CREATE FUNCTION opengeni_private.guard_scheduled_admission_diagnostic() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE task_row scheduled_tasks%ROWTYPE; item jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.admission_diagnostic IS DISTINCT FROM OLD.admission_diagnostic
      OR (OLD.admission_diagnostic IS NOT NULL AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD))
    THEN RAISE EXCEPTION 'scheduled admission refusal is immutable' USING ERRCODE = '42501'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.admission_diagnostic IS NULL THEN RETURN NEW; END IF;
  IF NEW.action_kind IS DISTINCT FROM 'agent_turn'
    OR NEW.status IS DISTINCT FROM 'failed'
    OR NEW.error IS DISTINCT FROM 'connection_account_unavailable'
    OR NEW.completed_at IS NULL OR nullif(btrim(NEW.producer_key),'') IS NULL
    OR NEW.session_id IS NOT NULL OR NEW.trigger_event_id IS NOT NULL
    OR NEW.accepted_execution_snapshot IS NOT NULL OR NEW.accepted_execution_digest IS NOT NULL
    OR NEW.knowledge_sync_run_id IS NOT NULL OR NEW.knowledge_summary IS NOT NULL
    OR jsonb_typeof(NEW.admission_diagnostic) IS DISTINCT FROM 'object'
    OR NEW.admission_diagnostic - ARRAY['version','reason','accounts'] <> '{}'::jsonb
    OR NEW.admission_diagnostic -> 'version' IS DISTINCT FROM '1'::jsonb
    OR coalesce(NEW.admission_diagnostic ->> 'reason','') NOT IN (
      'selected_account_unavailable','owner_access_unavailable','ambiguous_account',
      'parent_accounts_required','selection_unavailable')
    OR jsonb_typeof(NEW.admission_diagnostic -> 'accounts') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'invalid scheduled admission diagnostic' USING ERRCODE = '22023'; END IF;
  SELECT task.* INTO STRICT task_row FROM scheduled_tasks task
    WHERE task.id = NEW.task_id AND task.workspace_id = NEW.workspace_id
      AND task.account_id = NEW.account_id FOR UPDATE;
  IF task_row.status <> 'active' OR task_row.deleted_at IS NOT NULL
    OR task_row.action ->> 'kind' IS DISTINCT FROM 'agent_turn'
    OR NEW.task_authority_revision IS DISTINCT FROM task_row.authority_revision
    OR NEW.task_execution_digest IS DISTINCT FROM task_row.execution_digest
  THEN RAISE EXCEPTION 'scheduled task changed before refusal recording' USING ERRCODE = '40001'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(NEW.admission_diagnostic -> 'accounts') LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object'
      OR item - ARRAY['serverId','connectionId','reason'] <> '{}'::jsonb
      OR jsonb_typeof(item -> 'serverId') IS DISTINCT FROM 'string'
      OR length(item ->> 'serverId') NOT BETWEEN 1 AND 256
      OR NOT item ? 'connectionId'
      OR (item -> 'connectionId' <> 'null'::jsonb AND
        (jsonb_typeof(item -> 'connectionId') <> 'string' OR
         item ->> 'connectionId' !~ '^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$'))
      OR coalesce(item ->> 'reason','') NOT IN (
        'connector_unavailable','account_not_visible','account_inactive',
        'account_mismatch','selection_unavailable')
    THEN RAISE EXCEPTION 'invalid scheduled account diagnostic' USING ERRCODE = '22023'; END IF;
  END LOOP;
  RETURN NEW;
END $_$;

CREATE FUNCTION opengeni_private.guard_scheduled_admission_refusal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE task_row scheduled_tasks%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.admission_refusal IS DISTINCT FROM OLD.admission_refusal
      OR (OLD.admission_refusal IS NOT NULL AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD))
    THEN RAISE EXCEPTION 'scheduled admission refusal is immutable' USING ERRCODE = '42501'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.admission_refusal IS NULL THEN RETURN NEW; END IF;
  IF NEW.action_kind IS DISTINCT FROM 'agent_turn'
    OR NEW.admission_diagnostic IS NOT NULL
    OR jsonb_typeof(NEW.admission_refusal) IS DISTINCT FROM 'object'
    OR NEW.admission_refusal - ARRAY['version','reason','retryable'] <> '{}'::jsonb
    OR NEW.admission_refusal -> 'version' IS DISTINCT FROM '1'::jsonb
    OR jsonb_typeof(NEW.admission_refusal -> 'retryable') IS DISTINCT FROM 'boolean'
    OR coalesce(NEW.admission_refusal ->> 'reason', '') NOT IN (
      'scheduled_authority_unavailable',
      'machine_target_unavailable', 'machine_enrollment_inactive',
      'variable_set_unavailable', 'rig_version_unavailable',
      'insufficient_credits', 'monthly_model_cost_limit', 'monthly_agent_run_limit', 'allowance_exhausted', 'scheduled_model_unavailable', 'session_usage_limit')
    OR NEW.error IS DISTINCT FROM NEW.admission_refusal ->> 'reason'
    OR NEW.status IS DISTINCT FROM (CASE WHEN (NEW.admission_refusal ->> 'retryable')::boolean
      THEN 'skipped' ELSE 'failed' END)
    OR NEW.completed_at IS NULL OR nullif(btrim(NEW.producer_key),'') IS NULL
    OR NEW.session_id IS NOT NULL OR NEW.trigger_event_id IS NOT NULL
    OR NEW.accepted_execution_snapshot IS NOT NULL OR NEW.accepted_execution_digest IS NOT NULL
    OR NEW.knowledge_sync_run_id IS NOT NULL OR NEW.knowledge_summary IS NOT NULL
  THEN RAISE EXCEPTION 'invalid scheduled admission refusal' USING ERRCODE = '22023'; END IF;
  SELECT task.* INTO STRICT task_row FROM scheduled_tasks task
    WHERE task.id = NEW.task_id AND task.workspace_id = NEW.workspace_id
      AND task.account_id = NEW.account_id FOR UPDATE;
  IF task_row.status <> 'active' OR task_row.deleted_at IS NOT NULL
    OR task_row.action ->> 'kind' IS DISTINCT FROM 'agent_turn'
    OR NEW.task_authority_revision IS DISTINCT FROM task_row.authority_revision
    OR NEW.task_execution_digest IS DISTINCT FROM task_row.execution_digest
  THEN RAISE EXCEPTION 'scheduled task changed before refusal recording' USING ERRCODE = '40001'; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.guard_scheduled_run_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE expected_owner text;
BEGIN
  IF NEW.action_kind <> 'agent_turn' THEN RETURN NEW; END IF;
  SELECT task.owner_subject_id INTO STRICT expected_owner FROM scheduled_tasks task
  WHERE task.id = NEW.task_id AND task.account_id = NEW.account_id
    AND task.workspace_id = NEW.workspace_id FOR SHARE;
  IF NEW.accepted_execution_snapshot ->> 'causalHumanSubjectId' IS DISTINCT FROM expected_owner
    OR NEW.accepted_execution_snapshot #>> '{task,ownerSubjectId}' IS DISTINCT FROM expected_owner
  THEN RAISE EXCEPTION 'scheduled run differs from immutable execution owner' USING ERRCODE = '42501'; END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_scheduled_task_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE expected_owner text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.owner_subject_id IS DISTINCT FROM OLD.owner_subject_id THEN
      RAISE EXCEPTION 'schedule owner is immutable; copy the schedule to use another account'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    expected_owner := CASE WHEN NEW.action ->> 'kind' = 'agent_turn'
      THEN nullif(current_setting('opengeni.initiating_human_subject_id', true), '') END;
    IF NEW.owner_subject_id IS DISTINCT FROM expected_owner THEN
      RAISE EXCEPTION 'schedule owner differs from verified creator' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_session_title_operation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    BEGIN
      IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'pending' OR NEW.generation <> 0 OR NEW.holder_id IS NOT NULL
          OR NEW.request_operation_id IS NOT NULL OR NEW.response_encrypted IS NOT NULL
          OR NOT EXISTS (
            SELECT 1 FROM session_turns turn
            JOIN sessions session ON session.account_id = turn.account_id
              AND session.workspace_id = turn.workspace_id AND session.id = turn.session_id
            JOIN session_turn_attempts attempt ON attempt.account_id = turn.account_id
              AND attempt.workspace_id = turn.workspace_id AND attempt.turn_id = turn.id
              AND attempt.session_id = session.id AND attempt.id = turn.active_attempt_id
            WHERE turn.account_id = NEW.account_id AND turn.workspace_id = NEW.workspace_id
              AND turn.session_id = NEW.session_id AND turn.id = NEW.source_turn_id
              AND turn.status = 'running' AND session.status = 'running'
              AND session.active_turn_id = turn.id AND attempt.state IN ('claimed', 'running')
              AND attempt.id = NEW.source_attempt_id
              AND attempt.execution_generation = NEW.source_execution_generation
              AND turn.execution_generation = NEW.source_execution_generation
          ) THEN
          RAISE EXCEPTION 'session title requires the live source attempt' USING ERRCODE = '42501';
        END IF;
        IF NEW.connection_id IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM subscription_leases lease
          WHERE lease.account_id = NEW.account_id AND lease.workspace_id = NEW.workspace_id
            AND lease.session_id = NEW.session_id AND lease.turn_id = NEW.source_turn_id
            AND lease.provider = NEW.provider AND lease.connection_id = NEW.connection_id
            AND lease.leased_until > clock_timestamp()
        ) THEN
          RAISE EXCEPTION 'session title requires the selected live subscription lease' USING ERRCODE = '42501';
        END IF;
      ELSE
        IF ROW(NEW.id, NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.source_turn_id,
          NEW.source_attempt_id, NEW.source_execution_generation, NEW.provider, NEW.connection_id)
          IS DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.workspace_id, OLD.session_id,
          OLD.source_turn_id, OLD.source_attempt_id, OLD.source_execution_generation,
          OLD.provider, OLD.connection_id)
          OR (NEW.request_encrypted IS DISTINCT FROM OLD.request_encrypted
            AND NOT (NEW.request_encrypted IS NULL AND NEW.state IN ('completed', 'failed', 'unknown')))
          OR (OLD.request_operation_id IS NOT NULL AND NEW.request_operation_id IS DISTINCT FROM OLD.request_operation_id
            AND NOT (OLD.state = 'dispatching' AND NEW.state = 'dispatching'
              AND OLD.holder_id = NEW.holder_id AND OLD.generation = NEW.generation
              AND OLD.leased_until > clock_timestamp()
              AND EXISTS (SELECT 1 FROM subscription_operation_leases request
                WHERE request.account_id = OLD.account_id AND request.workspace_id = OLD.workspace_id
                  AND request.operation_id = OLD.request_operation_id
                  AND request.request_outcome = 'refused')))
          OR (OLD.state IN ('completed', 'failed', 'unknown') AND NEW IS DISTINCT FROM OLD)
        THEN
          RAISE EXCEPTION 'session title admission is immutable' USING ERRCODE = '55000';
        END IF;
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.guard_subscription_binding_provider() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.provider IS DISTINCT FROM OLD.provider THEN
    RAISE EXCEPTION 'a subscription session binding never changes provider'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_connection_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  session_owner text;
  session_owner_membership uuid;
  turn_human text;
  target subscription_connections%ROWTYPE;
  visible boolean;
  personal_authorized boolean := false;
  ownerless_session boolean := false;
BEGIN
  IF NEW.connection_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR NEW.workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    OR NOT session_reference_visible(NEW.account_id, NEW.workspace_id, NEW.session_id)
  THEN
    RAISE EXCEPTION 'subscription connection target is outside the visible session'
      USING ERRCODE = '42501';
  END IF;
  SELECT session.owner_subject_id, session.owner_organization_membership_id
    INTO session_owner, session_owner_membership
  FROM sessions session
  WHERE session.account_id = NEW.account_id AND session.workspace_id = NEW.workspace_id
    AND session.id = NEW.session_id;
  IF NOT FOUND OR (session_owner IS NULL) <> (session_owner_membership IS NULL) THEN
    RAISE EXCEPTION 'subscription session owner authority is unavailable or malformed'
      USING ERRCODE = '42501';
  END IF;
  ownerless_session := session_owner IS NULL;

  IF TG_TABLE_NAME = 'subscription_leases' THEN
    SELECT turn.initiating_human_subject_id INTO turn_human
    FROM session_turns turn
    WHERE turn.account_id = NEW.account_id AND turn.workspace_id = NEW.workspace_id
      AND turn.session_id = NEW.session_id AND turn.id = NEW.turn_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'subscription lease turn is not in the referenced session'
        USING ERRCODE = '42501';
    END IF;
    IF ownerless_session THEN
      IF NOT opengeni_private.authorize_subscription_ownerless_session_access(
        NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id
      ) THEN
        RAISE EXCEPTION 'ownerless subscription lease turn is not authorized for this session'
          USING ERRCODE = '42501';
      END IF;
    ELSIF turn_human IS NULL THEN
      IF NOT opengeni_private.authorize_subscription_service_session_access(
        NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id, session_owner
      ) THEN
        RAISE EXCEPTION 'non-human subscription lease turn is not authorized for this session'
          USING ERRCODE = '42501';
      END IF;
      turn_human := session_owner;
    ELSIF NOT opengeni_private.authorize_subscription_session_access(
      NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id, session_owner, turn_human
    ) THEN
      RAISE EXCEPTION 'subscription lease turn is not authorized for this session'
        USING ERRCODE = '42501';
    END IF;
    IF NOT ownerless_session THEN
      personal_authorized := opengeni_private.authorize_subscription_personal_access(
        NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id, NEW.connection_id,
        NEW.provider, session_owner, turn_human
      );
    END IF;
  ELSE
    -- Bindings have no turn id, so there is no exact ownerless turn to verify.
    -- Keep ownerless binding writes fail-closed until that contract is explicit.
    IF ownerless_session THEN
      RAISE EXCEPTION 'ownerless subscription bindings require an exact accepted turn'
        USING ERRCODE = '42501';
    END IF;
    turn_human := nullif(current_setting('opengeni.initiating_human_subject_id', true), '');
    IF turn_human IS NULL THEN
      RAISE EXCEPTION 'subscription binding requires an initiating human'
        USING ERRCODE = '42501';
    END IF;
    INSERT INTO opengeni_private.subscription_runtime_capabilities (
      backend_pid, transaction_id, capability_kind, account_id, workspace_id,
      session_id, connection_id, provider, session_owner_subject_id, turn_human_subject_id
    ) VALUES (
      pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'binding_access',
      NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.connection_id, NEW.provider,
      session_owner, turn_human
    )
    ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
    DO UPDATE SET workspace_id = EXCLUDED.workspace_id, session_id = EXCLUDED.session_id,
      provider = EXCLUDED.provider,
      session_owner_subject_id = EXCLUDED.session_owner_subject_id,
      turn_human_subject_id = EXCLUDED.turn_human_subject_id;
    PERFORM pg_catalog.set_config('opengeni.session_owner_subject_id', session_owner, true);
    PERFORM pg_catalog.set_config('opengeni.turn_human_subject_id', turn_human, true);
  END IF;

  SELECT connection.* INTO target
  FROM subscription_connections connection
  WHERE connection.account_id = NEW.account_id AND connection.id = NEW.connection_id
    AND connection.provider = NEW.provider AND connection.status = 'active';
  IF NOT FOUND OR NOT opengeni_private.subscription_connection_visible(
    NEW.account_id, NEW.workspace_id, target.id, target.ownership, target.scope_kind,
    target.owner_organization_membership_id, target.owner_subject_id, target.provider
  ) THEN
    RAISE EXCEPTION 'subscription connection is not in the session eligible pool'
      USING ERRCODE = '42501';
  END IF;
  IF ownerless_session AND (target.ownership <> 'shared'
    OR target.scope_kind NOT IN ('organization', 'workspaces')) THEN
    RAISE EXCEPTION 'ownerless subscription sessions require organization- or workspace-scoped shared connections'
      USING ERRCODE = '42501';
  END IF;
  IF target.ownership = 'personal' AND TG_TABLE_NAME = 'subscription_leases'
    AND (ownerless_session OR NOT personal_authorized OR NOT coalesce((subscription_effective_settings(
      NEW.account_id, NEW.workspace_id
    ) #>> '{values,personalConnectionsAllowed}')::boolean, false)) THEN
    RAISE EXCEPTION 'personal subscription lease lacks current settings or frozen user authority'
      USING ERRCODE = '42501';
  END IF;
  IF target.ownership = 'personal' AND TG_TABLE_NAME = 'subscription_session_bindings' THEN
    SELECT EXISTS (
      SELECT 1 FROM sessions session
      JOIN organization_memberships membership ON membership.account_id = session.account_id
        AND membership.id = target.owner_organization_membership_id
        AND membership.subject_id = turn_human
      JOIN organization_user_resource_authorities authority
        ON authority.id = target.authority_id AND authority.account_id = target.account_id
        AND authority.organization_membership_id = membership.id
        AND authority.resource_kind = target.authority_resource_kind
        AND authority.resource_id = target.id
        AND authority.generation = target.authority_generation
        AND authority.status = 'active' AND authority.revoked_at IS NULL
      WHERE session.account_id = NEW.account_id AND session.workspace_id = NEW.workspace_id
        AND session.id = NEW.session_id AND target.owner_subject_id = turn_human
        AND membership.status = 'active' AND membership.revoked_at IS NULL
        AND (
          (session.owner_subject_id = turn_human
            AND (session.visibility = 'user_private' OR membership.personal_workspace_id = NEW.workspace_id))
          OR (session.visibility = 'workspace_shared' AND NEW.choice = 'explicit'
            AND turn_human LIKE 'user:%'
            AND EXISTS (SELECT 1 FROM workspace_memberships participant
              WHERE participant.account_id = NEW.account_id AND participant.workspace_id = NEW.workspace_id
                AND participant.subject_id = turn_human)
            AND (nullif(current_setting('opengeni.subject_id', true), '') = turn_human
              OR EXISTS (SELECT 1 FROM opengeni_private.subscription_runtime_capabilities accepted
                WHERE accepted.backend_pid = pg_catalog.pg_backend_pid()
                  AND accepted.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
                  AND accepted.capability_kind = 'personal_access'
                  AND accepted.account_id = NEW.account_id AND accepted.workspace_id = NEW.workspace_id
                  AND accepted.session_id = NEW.session_id AND accepted.turn_id IS NOT NULL
                  AND accepted.connection_id = target.id AND accepted.provider = target.provider
                  AND accepted.session_owner_subject_id = session_owner
                  AND accepted.turn_human_subject_id = turn_human)))
        )
    ) INTO visible;
    IF NOT visible OR NOT coalesce((subscription_effective_settings(
      NEW.account_id, NEW.workspace_id
    ) #>> '{values,personalConnectionsAllowed}')::boolean, false) THEN
      RAISE EXCEPTION 'personal subscription connection is not eligible for this session'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_connection_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    BEGIN
      IF TG_OP = 'UPDATE' AND (
          NEW.account_id IS DISTINCT FROM OLD.account_id
          OR NEW.provider IS DISTINCT FROM OLD.provider
          OR NEW.kind IS DISTINCT FROM OLD.kind
          OR NEW.ownership IS DISTINCT FROM OLD.ownership
          OR NEW.owner_organization_membership_id IS DISTINCT FROM OLD.owner_organization_membership_id
          OR NEW.owner_subject_id IS DISTINCT FROM OLD.owner_subject_id
          OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
          OR NEW.authority_resource_kind IS DISTINCT FROM OLD.authority_resource_kind
          OR NEW.authority_generation IS DISTINCT FROM OLD.authority_generation
          OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
          OR NEW.allow_personal_workspaces IS DISTINCT FROM OLD.allow_personal_workspaces
          OR NEW.managed_by_workspace_id IS DISTINCT FROM OLD.managed_by_workspace_id
          OR NEW.excluded_models IS DISTINCT FROM OLD.excluded_models
      ) AND NOT opengeni_private.subscription_organization_admin(OLD.account_id) THEN
        RAISE EXCEPTION 'only organization administrators may change subscription connection scope or ownership'
          USING ERRCODE = '42501';
      END IF;
      -- The models of a workspace-managed shared connection are also its
      -- managing workspace's admins' decision, in that workspace's context.
      IF TG_OP = 'UPDATE' AND NEW.allowed_model_ids IS DISTINCT FROM OLD.allowed_model_ids
        AND NOT (OLD.ownership = 'shared' AND OLD.managed_by_workspace_id IS NOT NULL
          AND OLD.managed_by_workspace_id::text = nullif(current_setting('opengeni.workspace_id', true), '')
          AND EXISTS (SELECT 1 FROM workspace_memberships manager
            WHERE manager.account_id = OLD.account_id
              AND manager.workspace_id = OLD.managed_by_workspace_id
              AND manager.subject_id = nullif(current_setting('opengeni.subject_id', true), '')
              AND opengeni_private.workspace_membership_administers(manager.role, manager.permissions)))
        AND NOT opengeni_private.subscription_organization_admin(OLD.account_id) THEN
        RAISE EXCEPTION 'only organization administrators may change subscription connection scope or ownership'
          USING ERRCODE = '42501';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.guard_subscription_designation_disconnect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('subscription-refresh:' || NEW.connection_id::text, 0));
  IF NOT EXISTS (SELECT 1 FROM subscription_connections connection
    WHERE connection.account_id = NEW.account_id AND connection.id = NEW.connection_id
      AND connection.provider = 'codex' AND connection.disconnected_at IS NULL
      AND connection.status = 'active') THEN
    RAISE EXCEPTION 'Apps designation source is no longer available' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_disconnect_admission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NEW.connection_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM opengeni_private.subscription_core_providers registry
    WHERE registry.provider = NEW.provider) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'subscription_operation_leases' THEN
    IF NEW.operation_kind IN ('model', 'credential_request') AND NEW.turn_id IS NOT NULL
        AND NEW.request_id IS NOT NULL THEN
      PERFORM 1 FROM session_turns turn WHERE turn.account_id = NEW.account_id
        AND turn.workspace_id = NEW.workspace_id AND turn.session_id = NEW.session_id
        AND turn.id = NEW.turn_id AND turn.active_attempt_id = NEW.attempt_id
        AND turn.execution_generation = NEW.generation AND turn.status = 'running'
        FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'model request no longer owns its exact attempt' USING ERRCODE = '42501';
      END IF;
      IF NEW.operation_kind = 'model' AND EXISTS (SELECT 1 FROM subscription_operation_leases prior
        WHERE prior.account_id = NEW.account_id AND prior.workspace_id = NEW.workspace_id
          AND prior.session_id = NEW.session_id AND prior.turn_id = NEW.turn_id
          AND prior.operation_kind = 'model'
          AND prior.request_id IS NOT NULL AND (prior.request_outcome = 'unknown'
            OR (prior.request_outcome = 'reserved' AND prior.attempt_id <> NEW.attempt_id))
          AND NOT EXISTS (SELECT 1 FROM session_turn_attempts attempt
            WHERE attempt.account_id = prior.account_id AND attempt.workspace_id = prior.workspace_id
              AND attempt.session_id = prior.session_id AND attempt.turn_id = prior.turn_id
              AND attempt.id = prior.attempt_id AND attempt.execution_generation < NEW.generation
              AND prior.provider = NEW.provider AND attempt.state = 'closed'
              AND attempt.outcome IN ('failed', 'interrupted_recoverable', 'lease_lost_recoverable'))) THEN
        RAISE EXCEPTION 'prior request outcome is unresolved' USING ERRCODE = '55000';
      END IF;
    END IF;
  END IF;
  -- Match the caller's turn-before-connection lock order.
  PERFORM pg_advisory_xact_lock(hashtextextended('subscription-refresh:' || NEW.connection_id::text, 0));
  IF NOT EXISTS (SELECT 1 FROM subscription_connections connection
      WHERE connection.account_id = NEW.account_id AND connection.id = NEW.connection_id
        AND connection.disconnected_at IS NULL AND connection.status = 'active') THEN
    RAISE EXCEPTION 'subscription source is disconnected or unavailable' USING ERRCODE = '55000';
  END IF;
  IF TG_TABLE_NAME = 'subscription_operation_leases' THEN
    IF NEW.operation_kind = 'apps' AND NOT EXISTS (
      SELECT 1 FROM opengeni_private.resolve_subscription_codex_apps_designation(NEW.account_id, NEW.workspace_id) designated
      WHERE designated.connection_id = NEW.connection_id AND designated.status = 'active'
    ) THEN
      RAISE EXCEPTION 'Apps request requires its exact active designation' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_disconnect_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF OLD.disconnected_at IS NOT NULL AND
    (NEW.disconnected_at IS DISTINCT FROM OLD.disconnected_at
      OR NEW.status <> 'disabled' OR NEW.credential_encrypted <> ''
      OR NEW.provider_account_id IS NOT NULL OR NEW.allocator_enabled) THEN
    RAISE EXCEPTION 'disconnected subscription identity cannot be reactivated' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_operation_lease_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      target subscription_connections%ROWTYPE;
      session_owner text;
      session_owner_membership uuid;
      turn_human text;
      turn_status text;
      turn_attempt uuid;
      turn_generation bigint;
      personal_authorized boolean := false;
      ownerless_session boolean := false;
    BEGIN
      IF NEW.account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR NEW.workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
      THEN
        RAISE EXCEPTION 'subscription operation lease is outside the scoped account or workspace'
          USING ERRCODE = '42501';
      END IF;

      IF NEW.session_id IS NULL THEN
        IF NEW.operation_kind NOT IN ('transcription', 'credential_request', 'apps', 'completion')
          OR (NEW.operation_kind = 'apps' AND NEW.provider <> 'codex')
          OR (NEW.operation_kind <> 'apps' AND (
            nullif(current_setting('opengeni.subject_id', true), '') IS NULL
            OR nullif(current_setting('opengeni.initiating_human_subject_id', true), '') IS NULL))
        THEN
          RAISE EXCEPTION 'sessionless subscription operation requires explicit transcription authority'
            USING ERRCODE = '42501';
        END IF;
      ELSE
        IF NOT session_reference_visible(NEW.account_id, NEW.workspace_id, NEW.session_id) THEN
          RAISE EXCEPTION 'subscription operation session is not visible'
            USING ERRCODE = '42501';
        END IF;
        SELECT session.owner_subject_id, session.owner_organization_membership_id
          INTO session_owner, session_owner_membership
        FROM sessions session
        WHERE session.account_id = NEW.account_id AND session.workspace_id = NEW.workspace_id
          AND session.id = NEW.session_id;
        IF NOT FOUND OR (session_owner IS NULL) <> (session_owner_membership IS NULL) THEN
          RAISE EXCEPTION 'subscription operation session owner authority is unavailable or malformed'
            USING ERRCODE = '42501';
        END IF;
        ownerless_session := session_owner IS NULL;

        IF NEW.turn_id IS NOT NULL THEN
          SELECT turn.initiating_human_subject_id, turn.status, turn.active_attempt_id,
              turn.execution_generation
            INTO turn_human, turn_status, turn_attempt, turn_generation
          FROM session_turns turn
          WHERE turn.account_id = NEW.account_id AND turn.workspace_id = NEW.workspace_id
            AND turn.session_id = NEW.session_id AND turn.id = NEW.turn_id;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'subscription operation turn is not in the referenced session'
              USING ERRCODE = '42501';
          END IF;
          -- A turn-bound operation belongs to the turn's live attempt: running
          -- on exactly this attempt and execution generation, with its live
          -- chat-turn lease on the same connection.
          IF (CASE WHEN NEW.operation_kind = 'session_title' THEN NOT EXISTS (
              SELECT 1 FROM session_title_operations title
              JOIN sessions session ON session.account_id = title.account_id
                AND session.workspace_id = title.workspace_id AND session.id = title.session_id
              WHERE title.account_id = NEW.account_id AND title.workspace_id = NEW.workspace_id
                AND ((NEW.request_id IS NULL AND title.id = NEW.operation_id)
                  OR (NEW.request_id IS NOT NULL AND title.request_operation_id = NEW.operation_id))
                AND title.session_id = NEW.session_id AND title.source_turn_id = NEW.turn_id
                AND title.source_attempt_id = NEW.attempt_id
                AND title.provider = NEW.provider AND title.connection_id = NEW.connection_id
                AND title.holder_id = NEW.holder_id AND title.generation = NEW.generation
                AND title.leased_until > clock_timestamp()
                AND title.state IN ('pending', 'dispatching') AND session.content_archive_state IS NULL
            ) ELSE (turn_status IS DISTINCT FROM 'running'
            OR turn_attempt IS DISTINCT FROM NEW.attempt_id
            OR turn_generation IS DISTINCT FROM NEW.generation
            OR NOT EXISTS (
              SELECT 1 FROM subscription_leases chat
              WHERE chat.account_id = NEW.account_id AND chat.workspace_id = NEW.workspace_id
                AND chat.session_id = NEW.session_id AND chat.turn_id = NEW.turn_id
                AND chat.provider = NEW.provider AND chat.connection_id = NEW.connection_id
                AND chat.leased_until > pg_catalog.clock_timestamp()
            )) END)
          THEN
            RAISE EXCEPTION 'subscription operation turn is not the live attempt holding this connection'
              USING ERRCODE = '42501';
          END IF;
          IF ownerless_session THEN
            IF NOT opengeni_private.authorize_subscription_ownerless_session_access(
              NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id
            ) THEN
              RAISE EXCEPTION 'ownerless subscription operation turn is not authorized for this session'
                USING ERRCODE = '42501';
            END IF;
          ELSIF turn_human IS NULL THEN
            IF NOT opengeni_private.authorize_subscription_service_session_access(
              NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id, session_owner
            ) THEN
              RAISE EXCEPTION 'non-human subscription operation is not authorized for this session'
                USING ERRCODE = '42501';
            END IF;
            turn_human := session_owner;
          ELSIF NOT opengeni_private.authorize_subscription_session_access(
            NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id, session_owner, turn_human
          ) THEN
            RAISE EXCEPTION 'subscription operation turn is not authorized for this session'
              USING ERRCODE = '42501';
          END IF;
        ELSIF ownerless_session THEN
          -- An ownerless session has no owner context to carry; only its
          -- realtime and video operations exist (shared connections only),
          -- and no person stands behind them.
          IF NEW.operation_kind NOT IN ('realtime', 'video')
            OR nullif(current_setting('opengeni.initiating_human_subject_id', true), '') IS NOT NULL
          THEN
            RAISE EXCEPTION 'ownerless session-bound subscription operation is not authorized'
              USING ERRCODE = '42501';
          END IF;
        ELSE
          turn_human := nullif(current_setting('opengeni.initiating_human_subject_id', true), '');
          IF turn_human IS NULL OR turn_human IS DISTINCT FROM session_owner THEN
            RAISE EXCEPTION 'session-bound subscription operation requires its accepted owner context'
              USING ERRCODE = '42501';
          END IF;
        END IF;
      END IF;

      IF NEW.session_id IS NOT NULL AND NEW.turn_id IS NOT NULL AND NOT ownerless_session THEN
        personal_authorized := opengeni_private.authorize_subscription_personal_access(
          NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.turn_id, NEW.connection_id,
          NEW.provider, session_owner, turn_human
        );
      END IF;

      SELECT connection.* INTO target
      FROM subscription_connections connection
      WHERE connection.account_id = NEW.account_id AND connection.id = NEW.connection_id
        AND connection.provider = NEW.provider AND connection.status = 'active';
      IF NOT FOUND OR NOT opengeni_private.subscription_connection_visible(
        NEW.account_id, NEW.workspace_id, target.id, target.ownership, target.scope_kind,
        target.owner_organization_membership_id, target.owner_subject_id, target.provider
      ) THEN
        RAISE EXCEPTION 'subscription operation connection is not in the authorized pool'
          USING ERRCODE = '42501';
      END IF;
      IF ownerless_session AND (target.ownership <> 'shared'
        OR target.scope_kind NOT IN ('organization', 'workspaces')) THEN
        RAISE EXCEPTION 'ownerless subscription operations require organization- or workspace-scoped shared connections'
          USING ERRCODE = '42501';
      END IF;
      IF target.ownership = 'personal' THEN
        IF NEW.session_id IS NULL OR NEW.turn_id IS NULL OR NOT personal_authorized
          OR NOT coalesce((subscription_effective_settings(
            NEW.account_id, NEW.workspace_id
          ) #>> '{values,personalConnectionsAllowed}')::boolean, false)
        THEN
          RAISE EXCEPTION 'personal subscription operation lacks frozen owner authority or current settings'
            USING ERRCODE = '42501';
        END IF;
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.guard_subscription_provider_connection_kind() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.connection_kind IS DISTINCT FROM OLD.connection_kind THEN
    RAISE EXCEPTION 'subscription core provider connection kind is immutable'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_provider_registry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    BEGIN
      IF TG_OP IN ('DELETE', 'TRUNCATE')
        OR (TG_OP = 'UPDATE' AND NEW.provider IS DISTINCT FROM OLD.provider) THEN
        RAISE EXCEPTION 'subscription core providers are append-only' USING ERRCODE = '55000';
      END IF;
      IF NEW.primary_setting_column IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute attribute
        WHERE attribute.attrelid = '{{schema}}.subscription_settings'::regclass
          AND attribute.attname = NEW.primary_setting_column
          AND attribute.atttypid = 'uuid'::regtype AND NOT attribute.attisdropped
      ) THEN
        RAISE EXCEPTION 'subscription_settings primary column is missing' USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.guard_subscription_request_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.request_id IS NOT NULL THEN
      NEW.request_reserved_at := clock_timestamp();
      NEW.request_outcome := 'reserved';
      NEW.request_observed_at := NULL;
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.request_id IS NULL THEN
    IF TG_OP = 'UPDATE' AND NEW.request_id IS NOT NULL THEN
      RAISE EXCEPTION 'a request requires a new operation identity' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  -- Ordinary retention may cascade from a deleted session/workspace. Lease
  -- release, expiry and replacement must not erase unresolved request custody.
  IF TG_OP = 'DELETE' THEN
    IF pg_trigger_depth() > 1 THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'request history is not an expiring lease' USING ERRCODE = '55000';
  END IF;
  IF ROW(NEW.account_id, NEW.workspace_id, NEW.operation_id, NEW.attempt_id,
      NEW.operation_kind, NEW.session_id, NEW.turn_id, NEW.provider, NEW.connection_id,
      NEW.holder_id, NEW.generation, NEW.request_id, NEW.transport_attempt, NEW.request_reserved_at)
    IS DISTINCT FROM ROW(OLD.account_id, OLD.workspace_id, OLD.operation_id, OLD.attempt_id,
      OLD.operation_kind, OLD.session_id, OLD.turn_id, OLD.provider, OLD.connection_id,
      OLD.holder_id, OLD.generation, OLD.request_id, OLD.transport_attempt, OLD.request_reserved_at)
    OR (OLD.request_outcome IN ('response_received', 'refused')
      AND NEW.request_outcome IS DISTINCT FROM OLD.request_outcome)
    OR (OLD.request_outcome <> 'reserved' AND NEW.request_outcome = 'reserved') THEN
    RAISE EXCEPTION 'request reservation is immutable and single use' USING ERRCODE = '55000';
  END IF;
  IF NEW.request_outcome IS DISTINCT FROM OLD.request_outcome THEN
    NEW.request_observed_at := clock_timestamp();
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_settings_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.account_id IS DISTINCT FROM OLD.account_id
      OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN
    RAISE EXCEPTION 'a subscription settings row cannot move to another organization or workspace'
      USING ERRCODE = '42501', DETAIL = 'subscription_settings_identity_immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_settings_locked_overrides() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  locked text[];
  new_row jsonb;
  old_row jsonb;
  setting text;
  column_name text;
  keyed boolean;
BEGIN
  IF NEW.workspace_id IS NULL THEN
    RETURN NEW;
  END IF;
  new_row := pg_catalog.to_jsonb(NEW);
  old_row := CASE WHEN TG_OP = 'UPDATE' THEN pg_catalog.to_jsonb(OLD) ELSE '{}'::jsonb END;
  -- A write that only clears or keeps values needs no lock check (and no
  -- advisory lock): clearing an override is always allowed.
  IF NOT EXISTS (
      SELECT 1 FROM (VALUES ('rotation', true), ('providers', true), ('fallback_order', true),
          ('cross_provider_failover', false), ('personal_connections_allowed', false),
          ('personal_fallback_allowed', false)) setting_column(name, keyed)
      WHERE opengeni_private.subscription_setting_override_widened(
        new_row -> setting_column.name, old_row -> setting_column.name, setting_column.keyed))
    AND NOT EXISTS (
      SELECT 1 FROM pg_catalog.jsonb_object_keys(new_row) entry(key)
      WHERE entry.key LIKE '%\_primary\_connection\_id'
        AND opengeni_private.subscription_setting_override_widened(
          new_row -> entry.key, old_row -> entry.key, false)) THEN
    RETURN NEW;
  END IF;
  -- READ UNCOMMITTED runs as READ COMMITTED in PostgreSQL.
  IF pg_catalog.current_setting('transaction_isolation') NOT IN ('read committed', 'read uncommitted') THEN
    RAISE EXCEPTION 'subscription settings overrides are written at READ COMMITTED only'
      USING ERRCODE = '0A000', DETAIL = 'subscription_settings_requires_read_committed';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended(
    'subscription-settings-locks:' || NEW.account_id::text, 0));
  PERFORM pg_catalog.set_config('opengeni.subscription_settings_lock_probe', NEW.account_id::text, true);
  SELECT organization.locked_settings INTO locked
  FROM subscription_settings organization
  WHERE organization.account_id = NEW.account_id AND organization.workspace_id IS NULL;
  PERFORM pg_catalog.set_config('opengeni.subscription_settings_lock_probe', '', true);
  IF locked IS NULL OR pg_catalog.cardinality(locked) = 0 THEN
    RETURN NEW;
  END IF;
  FOREACH setting IN ARRAY locked LOOP
    column_name := CASE setting
      WHEN 'rotation' THEN 'rotation'
      WHEN 'providers' THEN 'providers'
      WHEN 'fallbackOrder' THEN 'fallback_order'
      WHEN 'crossProviderFailover' THEN 'cross_provider_failover'
      WHEN 'personalConnectionsAllowed' THEN 'personal_connections_allowed'
      WHEN 'personalFallbackAllowed' THEN 'personal_fallback_allowed'
    END;
    IF column_name IS NULL THEN
      RAISE EXCEPTION 'unknown subscription setting lock' USING ERRCODE = '22023';
    END IF;
    keyed := setting IN ('rotation', 'providers', 'fallbackOrder');
    IF opengeni_private.subscription_setting_override_widened(
        new_row -> column_name, old_row -> column_name, keyed) THEN
      RAISE EXCEPTION 'subscription setting % is locked by the organization', setting
        USING ERRCODE = '42501', DETAIL = 'subscription_setting_locked:' || setting;
    END IF;
    IF setting = 'rotation' THEN
      FOR column_name IN
        SELECT entry.key FROM pg_catalog.jsonb_object_keys(new_row) entry(key)
        WHERE entry.key LIKE '%\_primary\_connection\_id'
      LOOP
        IF opengeni_private.subscription_setting_override_widened(
            new_row -> column_name, old_row -> column_name, false) THEN
          RAISE EXCEPTION 'subscription setting rotation is locked by the organization'
            USING ERRCODE = '42501', DETAIL = 'subscription_setting_locked:rotation';
        END IF;
      END LOOP;
    END IF;
  END LOOP;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_turn_session_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1 FROM session_turns turn
  WHERE turn.account_id = NEW.account_id AND turn.workspace_id = NEW.workspace_id
    AND turn.session_id = NEW.session_id AND turn.id = NEW.turn_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription turn does not belong to the referenced session'
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.guard_subscription_workspace_owner_reach() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    BEGIN
      IF TG_TABLE_NAME = 'subscription_connection_workspaces' THEN
        IF EXISTS (SELECT 1 FROM subscription_connections connection
            WHERE connection.account_id = NEW.account_id AND connection.id = NEW.connection_id
              AND connection.managed_by_workspace_id IS NOT NULL
              AND connection.managed_by_workspace_id <> NEW.workspace_id) THEN
          RAISE EXCEPTION 'a workspace''s own subscription connection serves only that workspace'
            USING ERRCODE = '23514';
        END IF;
      ELSIF NEW.managed_by_workspace_id IS NOT NULL AND EXISTS (
          SELECT 1 FROM subscription_connection_workspaces assignment
          WHERE assignment.account_id = NEW.account_id AND assignment.connection_id = NEW.id
            AND assignment.workspace_id <> NEW.managed_by_workspace_id) THEN
        RAISE EXCEPTION 'a workspace''s own subscription connection serves only that workspace'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.guard_unresolved_provider_create() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF OLD.provider_create_attempt IS NOT NULL
     AND OLD.provider_create_attempt->'instanceId' = 'null'::jsonb THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'provider_create_outcome_unknown: cannot delete unresolved lease';
    END IF;
    IF NEW.provider_create_attempt IS NULL
       OR (NEW.provider_create_attempt - 'instanceId') IS DISTINCT FROM
          (OLD.provider_create_attempt - 'instanceId')
       OR NEW.lease_epoch IS DISTINCT FROM OLD.lease_epoch
       OR NEW.backend IS DISTINCT FROM OLD.backend
       OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
       OR NEW.sandbox_group_id IS DISTINCT FROM OLD.sandbox_group_id
       OR NEW.current_checkpoint_artifact_id IS DISTINCT FROM OLD.current_checkpoint_artifact_id
       OR NEW.previous_checkpoint_artifact_id IS DISTINCT FROM OLD.previous_checkpoint_artifact_id
       OR NEW.workspace_generation IS DISTINCT FROM OLD.workspace_generation
       OR NEW.archive_generation IS DISTINCT FROM OLD.archive_generation
       OR NEW.liveness IS DISTINCT FROM OLD.liveness
       OR (NEW.provider_create_attempt->'instanceId' = 'null'::jsonb
          AND NEW.resume_state IS DISTINCT FROM OLD.resume_state)
       OR (NEW.instance_id IS DISTINCT FROM OLD.instance_id AND
          NEW.instance_id IS DISTINCT FROM NEW.provider_create_attempt->>'instanceId') THEN
      RAISE EXCEPTION 'provider_create_outcome_unknown: preserve operation until exact provider attribution';
    END IF;
    IF NEW.provider_create_attempt->'instanceId' <> 'null'::jsonb
       AND NEW.instance_id IS DISTINCT FROM NEW.provider_create_attempt->>'instanceId' THEN
      RAISE EXCEPTION 'provider_create_outcome_unknown: attribution must bind authoritative instance';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.guard_workspace_owned_skill_head_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE old_account text := current_setting('opengeni.account_id', true);
  old_workspace text := current_setting('opengeni.workspace_id', true);
BEGIN
  IF TG_OP='DELETE'
    AND current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID))
    AND current_setting('opengeni.skill_remove_head',true)=OLD.id::text
    AND nullif(current_setting('opengeni.account_id',true),'')::uuid=OLD.account_id
    AND (OLD.scope='user' OR (OLD.scope='workspace' AND OLD.scope_workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid))
  THEN RETURN OLD; END IF;
  IF TG_OP <> 'DELETE' OR pg_trigger_depth() <= 1 OR OLD.scope <> 'workspace' THEN
    RAISE EXCEPTION 'preference registry heads cannot be deleted' USING ERRCODE = '55000';
  END IF;
  IF (nullif(old_account, '') IS NOT NULL AND old_account::uuid IS DISTINCT FROM OLD.account_id)
    OR (nullif(old_workspace, '') IS NOT NULL AND old_workspace::uuid IS DISTINCT FROM OLD.scope_workspace_id)
  THEN
    RAISE EXCEPTION 'Skill parent cascade tenant context mismatch' USING ERRCODE = '42501';
  END IF;
  RETURN OLD;
END $$;

CREATE FUNCTION opengeni_private.guard_workspace_owned_skill_history_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF TG_TABLE_NAME='skill_write_receipts' AND TG_OP='UPDATE' AND pg_trigger_depth()>1 THEN
    IF OLD.activation_event_id IS NOT NULL AND NEW.activation_event_id IS NULL
      AND (to_jsonb(NEW)-'activation_event_id')=(to_jsonb(OLD)-'activation_event_id')
    THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP='DELETE'
    AND current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID))
    AND nullif(current_setting('opengeni.skill_remove_head',true),'') IS NOT NULL
    AND nullif(current_setting('opengeni.account_id',true),'')::uuid=OLD.account_id THEN
    IF TG_TABLE_NAME='company_brain_preference_proposal_receipts' THEN
      IF OLD.workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid
        AND OLD.preference_id::text=current_setting('opengeni.skill_remove_head',true) THEN RETURN OLD; END IF;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'preference registry history is immutable' USING ERRCODE = '55000';
END $$;

CREATE FUNCTION opengeni_private.guard_workspace_session_activity_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  gate_state text := nullif(current_setting('opengeni.session_activity_gate_state', true), '');
  gate_workspace_id uuid := nullif(
    current_setting('opengeni.session_activity_gate_workspace_id', true),
    ''
  )::uuid;
BEGIN
  IF gate_state <> 'finalizing'
    OR gate_workspace_id IS DISTINCT FROM OLD.workspace_id
    OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
    OR NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.revision IS DISTINCT FROM OLD.revision + 1
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'Workspace session activity revision requires the finalizing commit gate';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.hold_deleted_site_hostname() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF OLD.released_at IS NOT NULL AND OLD.released_at <= now() - interval '30 days' THEN
    RETURN OLD;
  END IF;
  INSERT INTO site_hostname_holds (label, site_id, workspace_id, reason, held_by, kind, expires_at)
  VALUES (
    OLD.label, OLD.site_id, OLD.workspace_id, 'Released when its Site or workspace was deleted',
    'system', 'release', coalesce(OLD.released_at, now()) + interval '30 days'
  )
  ON CONFLICT (label) DO UPDATE SET site_id = excluded.site_id,
    workspace_id = excluded.workspace_id, reason = excluded.reason, held_by = excluded.held_by,
    expires_at = excluded.expires_at, created_at = now()
  WHERE site_hostname_holds.kind = 'release';
  RETURN OLD;
END
$$;

CREATE FUNCTION opengeni_private.host_export_session_root(p_workspace_id uuid, p_session_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      v_root_id uuid;
      v_parent_id uuid;
      v_depth integer;
      v_cycle boolean;
    BEGIN
      IF p_session_id IS NULL THEN
        RETURN NULL;
      END IF;
      WITH RECURSIVE lineage(id, parent_session_id, depth, path, cycle) AS (
        SELECT s.id, s.parent_session_id, 0, ARRAY[s.id], false
        FROM {{schema}}.sessions s
        WHERE s.workspace_id = p_workspace_id AND s.id = p_session_id
        UNION ALL
        SELECT parent.id, parent.parent_session_id, lineage.depth + 1,
          lineage.path || parent.id, parent.id = ANY(lineage.path)
        FROM {{schema}}.sessions parent
        JOIN lineage ON lineage.parent_session_id = parent.id
        WHERE parent.workspace_id = p_workspace_id
          AND NOT lineage.cycle
          AND lineage.depth < 64
      )
      SELECT id, parent_session_id, depth, cycle
      INTO v_root_id, v_parent_id, v_depth, v_cycle
      FROM lineage
      ORDER BY depth DESC
      LIMIT 1;

      IF v_root_id IS NULL THEN
        RETURN NULL;
      END IF;
      IF v_cycle OR v_parent_id IS NOT NULL OR v_depth >= 64 THEN
        RAISE EXCEPTION 'session lineage for % has no valid workspace root', p_session_id
          USING ERRCODE = '23514';
      END IF;
      RETURN v_root_id;
    END $$;

CREATE FUNCTION opengeni_private.immutable_memory_lifecycle_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.workspace_id)
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'knowledge memory lifecycle events are immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION opengeni_private.inbox_item_v1(p_item_id uuid, p_account_id uuid, p_subject_id text) RETURNS TABLE(id uuid, workspace_id uuid, session_id uuid, kind text, source_key text, status text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT item.id, item.workspace_id, item.session_id, item.kind, item.source_key, item.status
  FROM opengeni_private.inbox_items item
  WHERE item.id = p_item_id AND item.account_id = p_account_id
    AND item.recipient_subject_id = p_subject_id
$$;

CREATE FUNCTION opengeni_private.inbox_settings_v1(p_account_id uuid, p_subject_id text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce(
    (SELECT settings.tidy_policy FROM opengeni_private.inbox_settings settings
     WHERE settings.account_id = p_account_id AND settings.subject_id = p_subject_id),
    'own_sessions')
$$;

CREATE FUNCTION opengeni_private.inbox_settings_v2(p_account_id uuid, p_subject_id text) RETURNS TABLE(tidy_policy text, paused_goals boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce(settings.tidy_policy, 'own_sessions'), coalesce(settings.paused_goals, false)
  FROM (SELECT 1) AS one
  LEFT JOIN opengeni_private.inbox_settings settings
    ON settings.account_id = p_account_id AND settings.subject_id = p_subject_id
$$;

CREATE FUNCTION opengeni_private.inbox_settings_v3(p_account_id uuid, p_subject_id text) RETURNS TABLE(tidy_policy text, paused_goals boolean, replies boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce(settings.tidy_policy, 'own_sessions'), coalesce(settings.paused_goals, false),
    coalesce(settings.replies, false)
  FROM (SELECT 1) AS one
  LEFT JOIN opengeni_private.inbox_settings settings
    ON settings.account_id = p_account_id AND settings.subject_id = p_subject_id
$$;

CREATE FUNCTION opengeni_private.inbox_settings_v4(p_account_id uuid, p_subject_id text) RETURNS TABLE(tidy_policy text, paused_goals boolean, replies boolean, time_sensitive_needs_you boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce(settings.tidy_policy, 'own_sessions'), coalesce(settings.paused_goals, false),
    coalesce(settings.replies, false), coalesce(settings.time_sensitive_needs_you, false)
  FROM (SELECT 1) AS one
  LEFT JOIN opengeni_private.inbox_settings settings
    ON settings.account_id = p_account_id AND settings.subject_id = p_subject_id
$$;

CREATE FUNCTION opengeni_private.index_session_message_search_text() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  INSERT INTO session_message_search_texts
    (account_id, workspace_id, session_id, sequence, encoded, text)
  VALUES (
    NEW.account_id, NEW.workspace_id, NEW.session_id, NEW.sequence,
    starts_with(NEW.payload->>'text', 'opengeni_lossless_json_string_v2_81f06e15:'),
    NEW.payload->>'text'
  )
  ON CONFLICT DO NOTHING;
  RETURN NULL;
END
$$;

CREATE FUNCTION opengeni_private.informational_update_origin_human_v1(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_kind text, p_lineage jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path FROM CURRENT
    AS $_$
  SELECT coalesce(origin.initiating_human_subject_id,
    CASE WHEN origin.initiator_kind = 'subject' THEN origin.initiator_subject_id END)
  FROM session_turns origin
  WHERE (p_kind = 'agent_message' OR p_kind LIKE 'child_%')
    AND origin.account_id = p_account_id AND origin.workspace_id = p_workspace_id
    AND origin.id = CASE WHEN pg_catalog.octet_length((CASE WHEN p_kind = 'agent_message'
        THEN p_lineage ->> 'callerTurnId' ELSE p_lineage ->> 'parentTurnId' END)) = 36
      AND (CASE WHEN p_kind = 'agent_message' THEN p_lineage ->> 'callerTurnId'
        ELSE p_lineage ->> 'parentTurnId' END) COLLATE pg_catalog."C"
        OPERATOR(pg_catalog.~) '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
      THEN (CASE WHEN p_kind = 'agent_message' THEN p_lineage ->> 'callerTurnId'
        ELSE p_lineage ->> 'parentTurnId' END)::pg_catalog.uuid END
    AND origin.session_id::text = CASE WHEN p_kind = 'agent_message'
      THEN p_lineage ->> 'callerSessionId' ELSE p_session_id::text END
$_$;

CREATE FUNCTION opengeni_private.initialize_workspace_session_activity_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM opengeni_private.ensure_workspace_session_activity_revision(
    TG_TABLE_SCHEMA,
    NEW.id,
    NEW.account_id
  );
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.insights_raw_amount_inputs(a uuid, w uuid, lo timestamp with time zone, hi timestamp with time zone) RETURNS TABLE(session_id uuid, provider text, model text, payer text, scheduled_task_id uuid, occurred_at timestamp with time zone, recorded_at timestamp with time zone, m jsonb, charge_row boolean)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $_$
    BEGIN
      -- EXECUTE alone must never expose an intermediate private identity or
      -- per-call amount. The approved definer calls this as the schema owner.
      IF current_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid='{{schema}}.model_call_facts'::regclass)) THEN
        RAISE EXCEPTION 'Insights input is owner-invoked only' USING ERRCODE='42501';END IF;
      
      -- Complete UTC hours use rollups; each ragged edge uses an exact raw
      -- predicate. Even a sub-hour request reads each fact exactly once.
      RETURN QUERY WITH bounds AS (
        SELECT CASE WHEN lo=date_trunc('hour',lo AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' THEN lo
          ELSE (date_trunc('hour',lo AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')+interval '1 hour' END AS first_hour,
          date_trunc('hour',hi AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS last_hour
      ), amounts AS (
        SELECT r.* FROM opengeni_private.insights_usage_hourly_rollups r CROSS JOIN bounds b
          WHERE r.account_id=a AND r.workspace_id=w AND r.hour>=b.first_hour AND r.hour<b.last_hour
        UNION ALL SELECT r.* FROM bounds b CROSS JOIN LATERAL
          opengeni_insights_internal.insights_usage_hourly_scan(a,w,lo,least(hi,b.first_hour)) r WHERE lo<b.first_hour
        UNION ALL SELECT r.* FROM bounds b CROSS JOIN LATERAL
          opengeni_insights_internal.insights_usage_hourly_scan(a,w,greatest(lo,b.last_hour),hi) r
          WHERE hi>b.last_hour AND b.last_hour>=b.first_hour
      ) SELECT r.session_id,r.provider,r.model,r.payer,r.scheduled_task_id,r.hour,r.recorded_at,
        (to_jsonb(r)-ARRAY['account_id','workspace_id','hour','session_id','provider','model','payer','scheduled_task_id','recorded_at'])
          ||jsonb_build_object('chargedMicros',0),false FROM amounts r;
      RETURN QUERY SELECT coalesce(f.session_id,CASE WHEN c.metadata->>'sessionId'~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN(c.metadata->>'sessionId')::uuid END),
        f.provider,f.model,'opengeni_credits',f.scheduled_task_id,c.occurred_at,null::timestamptz,
        jsonb_build_object('calls',0,'tokenKnownCalls',0,'cacheKnownCalls',0,'cacheWriteKnownCalls',0,'listClassKnownCalls',0,
          'uncachedInput',0,'cacheRead',0,'cacheWrite',0,'output',0,'reasoning',0,'chargedMicros',-c.amount_micros,
          'listMicros',0,'pricedCalls',0,'listApproxCalls',0,'listUncachedInput',0,'listCacheRead',0,'listCacheWrite',0,'listOutput',0),true
      FROM {{schema}}.credit_ledger_entries c LEFT JOIN {{schema}}.model_call_facts f ON f.account_id=c.account_id AND f.workspace_id=c.workspace_id
        AND f.turn_id=CASE WHEN c.source_id~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}:.' THEN left(c.source_id,36)::uuid END
        AND f.source_key=substr(c.source_id,38)
      WHERE c.account_id=a AND c.workspace_id IS NOT DISTINCT FROM w AND c.type='model_usage_debit'
        AND c.source_type='model_response' AND c.amount_micros<0 AND c.occurred_at>=lo AND c.occurred_at<hi;
    END
    $_$;

CREATE FUNCTION opengeni_private.insights_scoped_calls_rows(p_account uuid, p_workspace uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_query jsonb, p_cursor_at timestamp with time zone, p_cursor_id uuid, p_limit integer, p_details uuid[], p_shared boolean) RETURNS TABLE(payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET jit TO 'off'
    SET enable_nestloop TO 'on'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
    DECLARE a uuid;prior_workspace text:=current_setting('opengeni.workspace_id',true);prior_lifecycle text;
      subject_value text:=nullif(current_setting('opengeni.subject_id',true),'');human_value text:=nullif(current_setting('opengeni.initiating_human_subject_id',true),'');
      shared_ids uuid[]:='{}';personal_ids uuid[]:='{}';personal_owners text[]:='{}';owner_index int;w record;
    BEGIN
      PERFORM opengeni_private.session_variable_set_attachments_protocol_v1_active();
      BEGIN a:=nullif(current_setting('opengeni.account_id',true),'')::uuid;
        IF nullif(prior_workspace,'')::uuid IS DISTINCT FROM p_workspace THEN RAISE EXCEPTION 'Insights calls scope mismatch' USING ERRCODE='42501';END IF;
      EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Insights calls scope malformed' USING ERRCODE='42501';END;
      IF a IS NULL OR a IS DISTINCT FROM p_account THEN RAISE EXCEPTION 'Insights calls account mismatch' USING ERRCODE='42501';END IF;
      IF p_since IS NULL OR p_until IS NULL OR NOT isfinite(p_since) OR NOT isfinite(p_until) OR p_until<p_since OR p_until-p_since>interval '370 days'
        OR p_limit IS NULL OR p_limit<1 OR p_limit>101 OR(p_cursor_at IS NULL)<>(p_cursor_id IS NULL)
        OR(p_cursor_at IS NOT NULL AND NOT isfinite(p_cursor_at)) OR p_query IS NULL OR jsonb_typeof(p_query)<>'object'
        OR p_details IS NULL OR p_shared IS NULL THEN RAISE EXCEPTION 'Insights calls input invalid' USING ERRCODE='22023';END IF;
      IF p_until=p_since THEN RETURN;END IF;
      IF p_workspace IS NULL THEN
        SELECT coalesce(array_agg(workspace_id),'{}') INTO shared_ids FROM {{schema}}.list_organization_workspace_ids(a);
      END IF;
      prior_lifecycle:=current_setting('opengeni.organization_tenancy_lifecycle',true);
      PERFORM set_config('opengeni.organization_tenancy_lifecycle','organization_membership_lifecycle',true);
      BEGIN SELECT coalesce(array_agg(m.personal_workspace_id ORDER BY m.id),'{}'),coalesce(array_agg(m.subject_id ORDER BY m.id),'{}')
        INTO personal_ids,personal_owners FROM {{schema}}.organization_memberships m WHERE m.account_id=a AND m.personal_workspace_id IS NOT NULL;
      EXCEPTION WHEN OTHERS THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);RAISE;END;
      PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);
      IF p_workspace IS NOT NULL AND NOT p_workspace=ANY(personal_ids) THEN shared_ids:=ARRAY[p_workspace];END IF;
      BEGIN
        FOR w IN SELECT id FROM {{schema}}.workspaces WHERE account_id=a AND(p_workspace IS NULL OR id=p_workspace)
          AND(id=ANY(p_details) OR p_shared AND id=ANY(shared_ids))
          AND(NOT p_query?'workspaceId' OR id::text IN(SELECT jsonb_array_elements_text(p_query->'workspaceId'))) ORDER BY id LOOP
          owner_index:=array_position(personal_ids,w.id);
          IF owner_index IS NOT NULL AND personal_owners[owner_index] IS DISTINCT FROM subject_value
            AND personal_owners[owner_index] IS DISTINCT FROM human_value THEN CONTINUE;END IF;
          PERFORM set_config('opengeni.workspace_id',w.id::text,true);
          INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities
            (backend_pid,transaction_id,capability_kind,account_id,workspace_id,subject_id,initiating_human_subject_id)
          VALUES(pg_backend_pid(),pg_current_xact_id(),'model_call_facts',a,w.id,subject_value,human_value);
          RETURN QUERY SELECT jsonb_build_object('id',f.id,'occurredAt',to_char(f.occurred_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'workspaceId',w.id,
            'sessionId',leaf.id,'sessionTitle',leaf.title,'sessionKind','visible','personKey',meta->>'person',
            'provider',f.provider,'model',f.model,'payer',meta->>'payer','tokens',CASE WHEN
              f.input_tokens IS NOT NULL AND f.cached_tokens IS NOT NULL AND f.cache_write_tokens IS NOT NULL
              AND f.output_tokens IS NOT NULL AND f.reasoning_tokens IS NOT NULL
              AND f.input_tokens>=0 AND f.cached_tokens>=0 AND f.cache_write_tokens>=0 AND f.output_tokens>=0
              AND f.reasoning_tokens>=0 AND f.reasoning_tokens<=f.output_tokens
              AND f.cached_tokens::numeric+f.cache_write_tokens::numeric<=f.input_tokens::numeric THEN jsonb_build_object(
              'uncachedInput',f.input_tokens-f.cached_tokens-f.cache_write_tokens,'cacheRead',f.cached_tokens,
              'cacheWrite',f.cache_write_tokens,'output',f.output_tokens,'reasoning',f.reasoning_tokens) END,
            'chargedMicros',(SELECT coalesce(-sum(c.amount_micros),0) FROM {{schema}}.credit_ledger_entries c
              WHERE c.account_id=a AND c.workspace_id=w.id AND c.type='model_usage_debit' AND c.source_type='model_response'
                AND c.amount_micros<0 AND c.source_id=f.turn_id::text||':'||f.source_key),
            'listMicros',f.estimated_provider_cost_micros,'listByClassMicros',CASE WHEN f.list_uncached_input_cost_micros IS NOT NULL THEN jsonb_build_object(
              'uncachedInput',f.list_uncached_input_cost_micros,'cacheRead',f.list_cache_read_cost_micros,
              'cacheWrite',f.list_cache_write_cost_micros,'output',f.list_output_cost_micros) END)
          FROM {{schema}}.model_call_facts f JOIN {{schema}}.insights_audience_sessions leaf ON leaf.id=f.session_id AND leaf.account_id=a AND leaf.workspace_id=w.id
          LEFT JOIN {{schema}}.insights_audience_sessions root ON root.id=leaf.root_session_id AND root.account_id=a AND root.workspace_id=w.id
          LEFT JOIN {{schema}}.channels project ON project.id=root.channel_id AND project.account_id=a AND project.workspace_id=w.id
          LEFT JOIN {{schema}}.scheduled_tasks task ON task.id=f.scheduled_task_id AND task.account_id=a AND task.workspace_id=w.id
          CROSS JOIN LATERAL(SELECT jsonb_build_object('kind','item','workspaceId',w.id,'provider',f.provider,'model',f.model,
            'payer',opengeni_private.insights_usage_payer(f.provider,f.billing_path),'rootSessionId',CASE WHEN root.visibility='workspace_shared'
              OR subject_value IS NULL OR {{schema}}.session_private_actor_visible(root.account_id,root.workspace_id,root.owner_organization_membership_id,root.owner_subject_id) THEN root.id END,
            'projectId',CASE WHEN root.visibility='workspace_shared' OR subject_value IS NULL OR {{schema}}.session_private_actor_visible(
              root.account_id,root.workspace_id,root.owner_organization_membership_id,root.owner_subject_id) THEN project.id END,
            'scheduleId',task.id,'person',CASE WHEN coalesce(leaf.owner_subject_id,leaf.owner_organization_membership_id::text) IS NOT NULL THEN
              encode(sha256(convert_to(a::text||':'||coalesce(leaf.owner_subject_id,leaf.owner_organization_membership_id::text),'UTF8')),'hex') END) AS meta) metadata
          WHERE f.account_id=a AND f.workspace_id=w.id AND f.occurred_at>=p_since AND f.occurred_at<p_until
            AND(p_cursor_at IS NULL OR(f.occurred_at,f.id)<(p_cursor_at,p_cursor_id))
            AND(subject_value IS NULL OR leaf.visibility='workspace_shared' OR {{schema}}.session_private_actor_visible(
              leaf.account_id,leaf.workspace_id,leaf.owner_organization_membership_id,leaf.owner_subject_id))
            AND opengeni_private.insights_usage_filter(meta,p_query)
          ORDER BY f.occurred_at DESC,f.id DESC LIMIT p_limit;
          DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities WHERE backend_pid=pg_backend_pid()
            AND transaction_id=pg_current_xact_id_if_assigned() AND capability_kind='model_call_facts';
        END LOOP;
        PERFORM set_config('opengeni.workspace_id',coalesce(prior_workspace,''),true);
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities WHERE backend_pid=pg_backend_pid()
          AND transaction_id=pg_current_xact_id_if_assigned() AND capability_kind='model_call_facts';
        PERFORM set_config('opengeni.workspace_id',coalesce(prior_workspace,''),true);RAISE;
      END;
    END
    $$;

CREATE FUNCTION opengeni_private.insights_scoped_usage_rows(p_account uuid, p_workspace uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_granularity text, p_details uuid[], p_shared boolean) RETURNS TABLE(payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET jit TO 'off'
    SET enable_nestloop TO 'off'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
    DECLARE a uuid;prior_workspace text:=current_setting('opengeni.workspace_id',true);prior_lifecycle text;
      subject_value text:=nullif(current_setting('opengeni.subject_id',true),'');human_value text:=nullif(current_setting('opengeni.initiating_human_subject_id',true),'');
      w record;personal_ids uuid[]:='{}';personal_owners text[]:='{}';shared_ids uuid[]:='{}';owner_index int;owner_key text;
      detail_allowed boolean;inventory uuid;
    BEGIN
      PERFORM opengeni_private.session_variable_set_attachments_protocol_v1_active();
      BEGIN a:=nullif(current_setting('opengeni.account_id',true),'')::uuid;
        IF nullif(prior_workspace,'')::uuid IS DISTINCT FROM p_workspace THEN RAISE EXCEPTION 'Insights usage requires exact scope' USING ERRCODE='42501';END IF;
      EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Insights usage scope malformed' USING ERRCODE='42501';END;
      IF a IS NULL OR a IS DISTINCT FROM p_account THEN RAISE EXCEPTION 'Insights usage account mismatch' USING ERRCODE='42501';END IF;
      IF p_since IS NULL OR p_until IS NULL OR NOT isfinite(p_since) OR NOT isfinite(p_until) OR p_until<p_since
        OR p_until-p_since>interval '370 days' OR p_granularity IS NULL OR p_granularity NOT IN('day','hour')
        OR(p_granularity='hour' AND p_until-p_since>interval '1 day') OR p_details IS NULL OR p_shared IS NULL
      THEN RAISE EXCEPTION 'Insights usage window invalid' USING ERRCODE='22023';END IF;
      IF p_until=p_since THEN RETURN;END IF;
      IF p_workspace IS NULL THEN
        SELECT coalesce(array_agg(workspace_id),'{}') INTO shared_ids FROM {{schema}}.list_organization_workspace_ids(a);
      END IF;
      prior_lifecycle:=current_setting('opengeni.organization_tenancy_lifecycle',true);
      PERFORM set_config('opengeni.organization_tenancy_lifecycle','organization_membership_lifecycle',true);
      BEGIN
        SELECT coalesce(array_agg(m.personal_workspace_id ORDER BY m.id),'{}'),coalesce(array_agg(m.subject_id ORDER BY m.id),'{}')
        INTO personal_ids,personal_owners FROM {{schema}}.organization_memberships m JOIN {{schema}}.workspaces pw
          ON pw.id=m.personal_workspace_id AND pw.account_id=a WHERE m.account_id=a AND m.personal_workspace_id IS NOT NULL;
      EXCEPTION WHEN OTHERS THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);RAISE;END;
      PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);
      IF p_workspace IS NOT NULL AND NOT p_workspace=ANY(personal_ids) THEN shared_ids:=ARRAY[p_workspace];END IF;
      BEGIN
        FOR w IN SELECT id,name FROM {{schema}}.workspaces WHERE account_id=a AND(p_workspace IS NULL OR id=p_workspace) ORDER BY id LOOP
          PERFORM set_config('opengeni.workspace_id',w.id::text,true);
          owner_index:=array_position(personal_ids,w.id);
          owner_key:=CASE WHEN owner_index IS NOT NULL THEN encode(sha256(convert_to(a::text||':'||personal_owners[owner_index],'UTF8')),'hex') END;
          detail_allowed:=(w.id=ANY(p_details) OR p_shared AND w.id=ANY(shared_ids))
            AND(owner_index IS NULL OR personal_owners[owner_index]=subject_value OR personal_owners[owner_index]=human_value);
          inventory:=opengeni_private.open_session_tenancy_fence_inventory({{schema_oid}}::oid);
          PERFORM set_config('opengeni.organization_tenancy_lifecycle','organization_membership_lifecycle',true);
          INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities
            (backend_pid,transaction_id,capability_kind,account_id,workspace_id,subject_id,initiating_human_subject_id)
          VALUES(pg_backend_pid(),pg_current_xact_id(),'model_call_facts',a,w.id,subject_value,human_value);
          BEGIN
            RETURN QUERY WITH inventory_sessions AS MATERIALIZED(
              SELECT s.id,s.root_session_id,s.title,s.channel_id,s.owner_subject_id,s.owner_organization_membership_id,s.visibility,
                (subject_value IS NULL OR s.visibility='workspace_shared' OR coalesce((s.owner_organization_membership_id::text||':'||s.owner_subject_id)=ANY((SELECT {{schema}}.session_private_actor_visible_keys())::text[]),false)) AS actor_visible
              FROM {{schema}}.insights_audience_sessions s WHERE s.account_id=a AND s.workspace_id=w.id
            ), classified AS MATERIALIZED(
              SELECT f.*,s.id AS leaf_id,s.owner_subject_id,s.owner_organization_membership_id,s.root_session_id,
                CASE WHEN p_workspace IS NULL AND owner_index IS NOT NULL AND NOT detail_allowed THEN 'personal'
                  WHEN s.id IS NOT NULL AND s.visibility='user_private' AND(NOT s.actor_visible OR NOT detail_allowed) THEN 'private'
                  WHEN s.id IS NOT NULL AND NOT detail_allowed THEN 'restricted'
                  WHEN f.charge_row AND f.provider IS NULL THEN 'restricted'
                  WHEN (s.id IS NULL OR r.id IS NULL) AND EXISTS(SELECT 1 FROM {{schema}}.model_call_facts sf
          WHERE sf.account_id=a AND sf.workspace_id=w.id AND sf.session_id=f.session_id AND sf.site_id IS NOT NULL)
          THEN 'restricted' WHEN s.id IS NULL OR r.id IS NULL THEN 'deleted'
                  WHEN NOT s.actor_visible OR NOT r.actor_visible THEN 'restricted' ELSE 'item' END AS kind
              FROM opengeni_insights_internal.insights_usage_amount_inputs(a,w.id,p_since,p_until,p_granularity) f
              LEFT JOIN inventory_sessions s ON s.id=f.session_id LEFT JOIN inventory_sessions r ON r.id=s.root_session_id
            ), projected AS MATERIALIZED(
              SELECT jsonb_build_object('kind',f.kind,'occurredAt',f.occurred_at,'recordedAt',CASE WHEN f.kind='item' THEN f.recorded_at END,
                'workspaceId',CASE WHEN f.kind='item' OR(f.kind IN('restricted','service','deleted') AND w.id=ANY(shared_ids)) THEN w.id END,
                'workspaceName',CASE WHEN f.kind='item' OR(f.kind IN('restricted','service','deleted') AND w.id=ANY(shared_ids)) THEN w.name END,
                'personal',owner_index IS NOT NULL,'provider',CASE WHEN f.kind='item' THEN f.provider END,
                'model',CASE WHEN f.kind='item' THEN f.model END,'payer',f.payer,
                'rootSessionId',CASE WHEN f.kind='item' THEN f.root_session_id END,'rootTitle',CASE WHEN f.kind='item' THEN root.title END,
                'projectId',CASE WHEN f.kind='item' THEN project.id END,'projectName',CASE WHEN f.kind='item' THEN project.name END,
                'scheduleId',CASE WHEN f.kind='item' THEN task.id END,'scheduleName',CASE WHEN f.kind='item' THEN task.name END,
                'person',CASE WHEN f.kind='personal' THEN owner_key WHEN f.kind IN('item','private')
                  AND coalesce(f.owner_subject_id,f.owner_organization_membership_id::text) IS NOT NULL THEN
                    encode(sha256(convert_to(a::text||':'||coalesce(f.owner_subject_id,f.owner_organization_membership_id::text),'UTF8')),'hex') END,
                'personName',CASE WHEN f.kind IN('item','private') THEN coalesce(u.name,access.subject_label) END,
                'you',CASE WHEN f.kind='personal' THEN personal_owners[owner_index]=subject_value
                  WHEN f.kind='item' THEN f.owner_subject_id=subject_value ELSE false END,'m',f.m) AS p
              FROM classified f LEFT JOIN inventory_sessions root ON f.kind='item' AND root.id=f.root_session_id
              LEFT JOIN {{schema}}.channels project ON project.id=root.channel_id AND project.account_id=a AND project.workspace_id=w.id
              LEFT JOIN {{schema}}.scheduled_tasks task ON f.kind='item' AND task.id=f.scheduled_task_id AND task.account_id=a AND task.workspace_id=w.id
              LEFT JOIN {{schema}}.workspace_memberships access ON access.account_id=a AND access.workspace_id=w.id AND access.subject_id=f.owner_subject_id
              LEFT JOIN {{schema}}.auth_users u ON access.subject_id='user:'||u.id
            ), hidden_fields AS(
              SELECT p->>'kind' AS kind,p->>'person' AS person,p->>'payer' AS payer,p->>'workspaceId' AS workspace,
                date_trunc(p_granularity,(p->>'occurredAt')::timestamptz AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS bucket,
                max(p->>'workspaceName') AS workspace_name,max(p->>'personName') AS name,bool_or(coalesce((p->>'you')::boolean,false)) AS you,
                field.key,sum(field.value::bigint)::bigint AS amount
              FROM projected CROSS JOIN LATERAL jsonb_each_text(p->'m') field WHERE p->>'kind'<>'item' GROUP BY 1,2,3,4,5,field.key
            ) SELECT p FROM projected WHERE p->>'kind'='item'
              UNION ALL SELECT jsonb_build_object('kind',kind,'person',person,'personName',max(name),'you',bool_or(you),
                'payer',payer,'workspaceId',workspace,'workspaceName',max(workspace_name),'occurredAt',bucket,'recordedAt',null,
                'm',jsonb_object_agg(key,amount)) FROM hidden_fields GROUP BY kind,person,payer,workspace,bucket;
            DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities WHERE backend_pid=pg_backend_pid()
              AND transaction_id=pg_current_xact_id_if_assigned() AND capability_kind='model_call_facts';
            PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory);
            PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);
          EXCEPTION WHEN OTHERS THEN
            DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities WHERE backend_pid=pg_backend_pid()
              AND transaction_id=pg_current_xact_id_if_assigned() AND capability_kind='model_call_facts';
            PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory);
            PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);RAISE;
          END;
        END LOOP;
        IF p_workspace IS NULL THEN RETURN QUERY
          SELECT jsonb_build_object('kind','restricted','payer','opengeni_credits','occurredAt',bucket,'m',jsonb_object_agg(key,amount))
          FROM(SELECT date_trunc(p_granularity,occurred_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS bucket,
            field.key,sum(field.value::bigint)::bigint AS amount FROM opengeni_insights_internal.insights_usage_amount_inputs(a,null,p_since,p_until,p_granularity)
            CROSS JOIN LATERAL jsonb_each_text(m) field GROUP BY 1,field.key) unassigned GROUP BY bucket;END IF;
        PERFORM set_config('opengeni.workspace_id',coalesce(prior_workspace,''),true);
      EXCEPTION WHEN OTHERS THEN PERFORM set_config('opengeni.workspace_id',coalesce(prior_workspace,''),true);RAISE;END;
    END
    $$;

CREATE FUNCTION opengeni_private.insights_site_usage(a uuid, w uuid, lo timestamp with time zone, hi timestamp with time zone, viewer text) RETURNS TABLE(payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET jit TO 'off'
    AS $$
    DECLARE actor text:=nullif(current_setting('opengeni.subject_id',true),'');
      human text:=nullif(current_setting('opengeni.initiating_human_subject_id',true),'');
    BEGIN
      IF a IS NULL OR w IS NULL OR a IS DISTINCT FROM nullif(current_setting('opengeni.account_id',true),'')::uuid
        OR w IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id',true),'')::uuid THEN
        RAISE EXCEPTION 'Site Insights requires exact tenant scope' USING ERRCODE='42501'; END IF;
      IF lo IS NULL OR hi IS NULL OR hi<lo OR hi-lo>interval '370 days' THEN
        RAISE EXCEPTION 'Invalid Site Insights window' USING ERRCODE='22023'; END IF;
      IF viewer IS NOT NULL AND viewer IS DISTINCT FROM actor AND viewer IS DISTINCT FROM human THEN
        RAISE EXCEPTION 'Site Insights viewer differs from the verified actor' USING ERRCODE='42501'; END IF;
      -- The existing owner+witness fact capability admits costs, not transcripts.
      INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities
        (backend_pid,transaction_id,capability_kind,account_id,workspace_id,subject_id,initiating_human_subject_id)
        VALUES(pg_backend_pid(),pg_current_xact_id(),'model_call_facts',a,w,actor,human);
      BEGIN
        RETURN QUERY WITH amounts AS MATERIALIZED (
          SELECT f.site_id,1::bigint calls,CASE WHEN f.estimated_provider_cost_micros IS NULL THEN 0 ELSE 1 END::bigint priced,
            0::bigint charged,coalesce(f.estimated_provider_cost_micros,0) equivalent,
            CASE WHEN opengeni_private.insights_usage_payer(f.provider,f.billing_path)='subscription'
              THEN coalesce(f.estimated_provider_cost_micros,0) ELSE 0 END subscription,
            CASE WHEN opengeni_private.insights_usage_payer(f.provider,f.billing_path)='own_key'
              THEN coalesce(f.estimated_provider_cost_micros,0) ELSE 0 END own_key
          FROM {{schema}}.model_call_facts f WHERE f.account_id=a AND f.workspace_id=w
            AND f.site_id IS NOT NULL AND f.occurred_at>=lo AND f.occurred_at<hi
          UNION ALL
          SELECT c.site_id,0,0,-c.amount_micros,0,0,0 FROM {{schema}}.credit_ledger_entries c
            WHERE c.account_id=a AND c.workspace_id=w AND c.site_id IS NOT NULL
              AND c.type='model_usage_debit' AND c.source_type='model_response' AND c.amount_micros<0
              AND c.occurred_at>=lo AND c.occurred_at<hi
        ), visible AS MATERIALIZED (
          -- Match workspace-artifacts.visibleTo: its RLS is tenant-only.
          -- Private/unavailable Sites share one bucket; never leak their ids.
          SELECT site.id,site.title FROM {{schema}}.workspace_artifacts site
            WHERE site.account_id=a AND site.workspace_id=w
              AND (site.visibility='workspace_shared' OR site.owner_subject_id=viewer)
        ), grouped AS (
          SELECT v.id,coalesce(v.title,'Private or unavailable Sites') title,
            CASE WHEN v.id IS NULL THEN 'restricted' ELSE 'site' END kind,
            sum(calls)::bigint calls,sum(priced)::bigint priced,sum(charged)::bigint charged,
            sum(equivalent)::bigint equivalent,sum(subscription)::bigint subscription,sum(own_key)::bigint own_key
          FROM amounts x LEFT JOIN visible v ON v.id=x.site_id GROUP BY v.id,v.title
        ), ranked AS (
          SELECT *,row_number() OVER(ORDER BY charged DESC,equivalent DESC,id NULLS LAST) position FROM grouped
        ), bounded AS (
          SELECT id,title,kind,calls,priced,charged,equivalent,subscription,own_key FROM ranked WHERE position<=200
          UNION ALL SELECT NULL,'Other Sites','other',sum(calls)::bigint,sum(priced)::bigint,sum(charged)::bigint,
            sum(equivalent)::bigint,sum(subscription)::bigint,sum(own_key)::bigint FROM ranked WHERE position>200 HAVING count(*)>0
        ) SELECT jsonb_build_object('siteId',id,'title',title,'kind',kind,'calls',calls,'pricedCalls',priced,
          'chargedMicros',charged,'apiEquivalentMicros',equivalent,'subscriptionApiEquivalentMicros',subscription,
          'ownKeyApiEquivalentMicros',own_key) FROM bounded ORDER BY charged DESC,equivalent DESC,id NULLS LAST;
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities WHERE backend_pid=pg_backend_pid()
          AND transaction_id=pg_current_xact_id_if_assigned() AND capability_kind='model_call_facts';
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities WHERE backend_pid=pg_backend_pid()
          AND transaction_id=pg_current_xact_id_if_assigned() AND capability_kind='model_call_facts';
        RAISE;
      END;
    END
    $$;

CREATE FUNCTION opengeni_private.insights_usage_filter(p jsonb, q jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT NOT EXISTS(SELECT 1 FROM jsonb_each(q) f WHERE f.key IN
    ('workspaceId','provider','model','payer','projectId','person','rootSessionId','scheduleId') AND
    ((p->>'kind' IN('private','personal')) OR NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements_text(f.value) requested(value) WHERE value=CASE f.key
        WHEN 'model' THEN(p->>'provider')||'/'||(p->>'model')
        WHEN 'projectId' THEN CASE WHEN p->>'kind'='item' AND p->>'rootSessionId' IS NOT NULL THEN coalesce(p->>'projectId','unfiled') END
        ELSE p->>f.key END)))
$$;

CREATE FUNCTION opengeni_private.insights_usage_payer(provider text, billing text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE WHEN billing='opengeni_credits' THEN 'opengeni_credits'
    WHEN provider IN('codex-subscription','supergrok-subscription','workspace-claude-subscription','organization-claude-subscription')
    THEN 'subscription' ELSE 'own_key' END
$$;

CREATE FUNCTION opengeni_private.inspect_slack_installation_binding(p_team_id text, p_bot_id text, p_bot_user_id text) RETURNS TABLE(outcome text, connection_id uuid, connection_version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      context_account_id uuid := NULLIF(current_setting('opengeni.account_id', true), '')::uuid;
      context_workspace_id uuid := NULLIF(current_setting('opengeni.workspace_id', true), '')::uuid;
      active_binding record;
    BEGIN
      IF context_account_id IS NULL OR context_workspace_id IS NULL THEN
        RAISE EXCEPTION 'Slack installation binding inspection requires tenant context';
      END IF;
      IF octet_length(p_team_id) NOT BETWEEN 1 AND 64
        OR octet_length(p_bot_id) NOT BETWEEN 1 AND 64
        OR octet_length(p_bot_user_id) NOT BETWEEN 1 AND 64
      THEN
        RAISE EXCEPTION 'invalid Slack installation principal';
      END IF;

      PERFORM pg_advisory_xact_lock(hashtextextended('opengeni:slack-install:' || p_team_id, 0));

      IF EXISTS (
        SELECT 1 FROM {{schema}}.slack_installation_bindings B
        WHERE B.slack_team_id = p_team_id AND B.state = 'quarantined'
      ) THEN
        RETURN QUERY SELECT 'legacy_quarantine'::text, NULL::uuid, NULL::integer;
        RETURN;
      END IF;

      SELECT B.*, C.version AS current_connection_version
      INTO active_binding
      FROM {{schema}}.slack_installation_bindings B
      JOIN {{schema}}.connections C ON C.id = B.connection_id
      WHERE B.slack_team_id = p_team_id AND B.state = 'active';

      IF active_binding IS NULL THEN
        RETURN QUERY SELECT 'available'::text, NULL::uuid, NULL::integer;
      ELSIF active_binding.account_id IS DISTINCT FROM context_account_id
        OR active_binding.workspace_id IS DISTINCT FROM context_workspace_id
      THEN
        RETURN QUERY SELECT 'conflicting_workspace'::text, NULL::uuid, NULL::integer;
      ELSIF active_binding.bot_id IS DISTINCT FROM p_bot_id
        OR active_binding.bot_user_id IS DISTINCT FROM p_bot_user_id
      THEN
        RETURN QUERY SELECT 'conflicting_principal'::text, NULL::uuid, NULL::integer;
      ELSE
        RETURN QUERY SELECT
          'same_binding'::text,
          active_binding.connection_id,
          active_binding.current_connection_version;
      END IF;
    END
    $$;

CREATE FUNCTION opengeni_private.integration_webhook_payload_v1(p_account uuid, p_workspace uuid, p_event uuid, p_type text, p_session uuid, p_turn uuid, p_sequence bigint, p_occurred timestamp with time zone, p_payload jsonb, p_lane text DEFAULT 'workspace'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE workspace_value jsonb; subject_value text; human_value jsonb; data_value jsonb;
BEGIN
  IF p_lane NOT IN ('workspace', 'organization') OR p_lane IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'integration payload scope invalid' USING ERRCODE = '42501'; END IF;
  SELECT jsonb_build_object('id', id, 'externalSource', external_source, 'externalId', external_id)
    INTO workspace_value FROM workspaces WHERE id = p_workspace AND account_id = p_account;
  IF p_type IN ('turn.completed', 'turn.failed', 'turn.cancelled') AND p_turn IS NOT NULL THEN
    SELECT initiating_human_subject_id INTO subject_value FROM session_turns
      WHERE id = p_turn AND session_id = p_session AND workspace_id = p_workspace AND account_id = p_account;
    human_value := opengeni_private.resolve_integration_initiating_human_v1(p_account, p_workspace, subject_value, p_turn);
  END IF;
  IF p_type IN ('session.notification.posted', 'session.notification.withdrawn') THEN
    data_value := jsonb_strip_nulls(jsonb_build_object(
      'key', CASE WHEN jsonb_typeof(p_payload->'key') = 'string' THEN left(p_payload->>'key', 120) END,
      'recipientSubjectId', CASE WHEN jsonb_typeof(p_payload->'recipientSubjectId') = 'string'
        THEN left(p_payload->>'recipientSubjectId', 300) END
    ));
    IF p_type = 'session.notification.posted' THEN
      data_value := data_value || jsonb_strip_nulls(jsonb_build_object(
        'title', CASE WHEN jsonb_typeof(p_payload->'title') = 'string' THEN left(p_payload->>'title', 80) END,
        'subtitle', CASE WHEN jsonb_typeof(p_payload->'subtitle') = 'string' THEN left(p_payload->>'subtitle', 80) END,
        'body', CASE WHEN jsonb_typeof(p_payload->'body') = 'string' THEN left(p_payload->>'body', 1000) END,
        'urgency', CASE WHEN p_payload->>'urgency' IN ('normal', 'time_sensitive') THEN p_payload->>'urgency' END,
        'replaced', CASE WHEN jsonb_typeof(p_payload->'replaced') = 'boolean' THEN p_payload->'replaced' END,
        'facts', CASE WHEN jsonb_typeof(p_payload->'facts') = 'array' THEN (
          SELECT coalesce(jsonb_agg(jsonb_build_object(
            'label', left(fact->>'label', 24), 'value', left(fact->>'value', 80)
          ) ORDER BY position), '[]'::jsonb)
          FROM jsonb_array_elements(p_payload->'facts') WITH ORDINALITY AS facts(fact, position)
          WHERE position <= 4 AND jsonb_typeof(fact->'label') = 'string'
            AND jsonb_typeof(fact->'value') = 'string'
        ) END,
        'link', CASE WHEN jsonb_typeof(p_payload->'link'->'url') = 'string'
          AND jsonb_typeof(p_payload->'link'->'label') = 'string' THEN jsonb_build_object(
            'url', left(p_payload->'link'->>'url', 2000), 'label', left(p_payload->'link'->>'label', 40)
          ) END,
        'sender', CASE WHEN jsonb_typeof(p_payload->'sender'->'subjectId') = 'string'
          AND jsonb_typeof(p_payload->'sender'->'label') = 'string' THEN jsonb_build_object(
            'subjectId', left(p_payload->'sender'->>'subjectId', 300), 'label', left(p_payload->'sender'->>'label', 200)
          ) END,
        'undeliveredReason', CASE WHEN p_payload->>'undeliveredReason' IN ('no_human_recipient')
          THEN p_payload->>'undeliveredReason' END
      ));
    END IF;
  ELSE
    data_value := jsonb_strip_nulls(jsonb_build_object(
      'status', CASE WHEN jsonb_typeof(p_payload -> 'status') = 'string' THEN left(p_payload ->> 'status', 64) END,
      'reason', CASE WHEN jsonb_typeof(p_payload -> 'reason') = 'string' THEN left(p_payload ->> 'reason', 200) END
    ));
  END IF;
  RETURN jsonb_build_object(
    'id', p_event, 'type', p_type, 'lane', p_lane, 'workspaceId', p_workspace, 'workspace', workspace_value,
    'sessionId', p_session, 'turnId', p_turn, 'initiatingHuman', human_value,
    'sequence', p_sequence,
    'occurredAt', to_char(p_occurred AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'data', data_value
  );
END $$;

CREATE FUNCTION opengeni_private.invalidate_stale_verified_install() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (
    NEW."subject_id" IS DISTINCT FROM OLD."subject_id"
    OR NEW."provider_domain" IS DISTINCT FROM OLD."provider_domain"
    OR NEW."kind" IS DISTINCT FROM OLD."kind"
    OR NEW."credential_encrypted" IS DISTINCT FROM OLD."credential_encrypted"
    OR NEW."granted_scopes" IS DISTINCT FROM OLD."granted_scopes"
    OR NEW."metadata" IS DISTINCT FROM OLD."metadata"
    OR NEW."version" IS DISTINCT FROM OLD."version"
  )
  AND NEW."verified_install_at" IS NOT DISTINCT FROM OLD."verified_install_at"
  AND NEW."verified_install_version" IS NOT DISTINCT FROM OLD."verified_install_version"
  THEN
    NEW."verified_install_at" := NULL;
    NEW."verified_install_version" := NULL;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.keep_subscription_codex_cutover_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF (OLD.provider = 'codex' OR NEW.provider = 'codex')
    AND (NEW.provider IS DISTINCT FROM OLD.provider OR NEW.account_id IS DISTINCT FROM OLD.account_id)
  THEN
    RAISE EXCEPTION 'a Codex cutover row keeps its organization and provider'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.knowledge_index_due_v1(p_model text, p_dimensions integer) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE previous text := current_setting('opengeni.knowledge_index_dispatcher', true);
      due boolean;
    BEGIN
      IF p_model IS NULL OR p_dimensions IS NULL OR length(p_model) NOT BETWEEN 1 AND 512
        OR p_dimensions NOT BETWEEN 1 AND 4096 THEN
        RAISE EXCEPTION 'Invalid Knowledge indexing probe' USING ERRCODE = '22023';
      END IF;
      PERFORM set_config('opengeni.knowledge_index_dispatcher', '1', true);
      SELECT EXISTS (
        SELECT 1 FROM {{schema}}.knowledge_index_jobs j
        WHERE j.state <> 'obsolete' AND j.next_attempt_at <= clock_timestamp()
          AND (j.lease_until IS NULL OR j.lease_until <= clock_timestamp())
          AND (j.state <> 'ready' OR j.model IS DISTINCT FROM p_model
            OR j.dimensions IS DISTINCT FROM p_dimensions)
      ) INTO due;
      PERFORM set_config('opengeni.knowledge_index_dispatcher', coalesce(previous, ''), true);
      RETURN due;
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('opengeni.knowledge_index_dispatcher', coalesce(previous, ''), true);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.knowledge_memory_relationship_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  lifecycle_writer boolean;
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.workspace_id)
  THEN
    RETURN OLD;
  END IF;
  SELECT current_user = pg_get_userbyid(procedure_row.proowner)
  INTO lifecycle_writer
  FROM pg_proc procedure_row
  WHERE procedure_row.oid = to_regprocedure(format(
    '%I.knowledge_memory_apply_operation(jsonb,text,text,text,uuid,uuid,uuid,integer)',
    TG_TABLE_SCHEMA
  ));
  lifecycle_writer := coalesce(lifecycle_writer, false)
    AND nullif(current_setting('opengeni.memory_lifecycle_operation', true), '') = '1';
  IF NOT lifecycle_writer THEN
    RAISE EXCEPTION 'knowledge memory relationships mutate only through lifecycle operations'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'knowledge memory relationships are retained and retired, never deleted'
      USING ERRCODE = '55000';
  END IF;
  IF ROW(
    NEW.id, NEW.account_id, NEW.workspace_id, NEW.source_memory_id,
    NEW.target_memory_id, NEW.relationship_type, NEW.created_by_event_id, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.id, OLD.account_id, OLD.workspace_id, OLD.source_memory_id,
    OLD.target_memory_id, OLD.relationship_type, OLD.created_by_event_id, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'knowledge memory relationship identity is immutable'
      USING ERRCODE = '55000';
  END IF;
  NEW.version := OLD.version + 1;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.knowledge_memory_row_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  typed_change boolean;
  lifecycle_writer boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.scope_type IS NULL
      OR (NEW.scope_type = 'workspace' AND NEW.scope <> 'workspace'
        AND NEW.scope_subject_id IS NULL AND NEW.scope_role_key IS NULL
        AND NEW.scope_session_id IS NULL)
    THEN
      NEW.scope_type := CASE WHEN NEW.scope = 'workspace' THEN 'workspace' ELSE 'legacy' END;
      NEW.scope_subject_id := NULL;
      NEW.scope_role_key := NULL;
      NEW.scope_session_id := NULL;
    END IF;
    IF opengeni_private.current_memory_actor_kind() IN ('subject', 'service')
      AND length(btrim(opengeni_private.current_memory_actor_id())) BETWEEN 1 AND 1024
    THEN
      NEW.created_by_kind := opengeni_private.current_memory_actor_kind();
      NEW.created_by_subject_id := opengeni_private.current_memory_actor_id();
      NEW.created_by_context := jsonb_strip_nulls(jsonb_build_object(
        'sessionId', opengeni_private.current_memory_session_id()
      ));
    ELSE
      NEW.created_by_kind := 'service';
      NEW.created_by_subject_id := 'unattributed-legacy';
      NEW.created_by_context := '{"legacyWriter":true}'::jsonb;
    END IF;
    NEW.memory_version := 1;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.created_by_kind, NEW.created_by_subject_id, NEW.created_by_context, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.created_by_kind, OLD.created_by_subject_id, OLD.created_by_context, OLD.created_at
  )
    OR (NEW.created_by_session_id IS DISTINCT FROM OLD.created_by_session_id
      AND (NEW.created_by_session_id IS NOT NULL OR pg_trigger_depth() <= 1))
  THEN
    RAISE EXCEPTION 'knowledge memory creator authority is immutable'
      USING ERRCODE = '55000';
  END IF;

  SELECT current_user = pg_get_userbyid(procedure_row.proowner)
  INTO lifecycle_writer
  FROM pg_proc procedure_row
  WHERE procedure_row.oid = to_regprocedure(format(
    '%I.knowledge_memory_apply_operation(jsonb,text,text,text,uuid,uuid,uuid,integer)',
    TG_TABLE_SCHEMA
  ));
  lifecycle_writer := coalesce(lifecycle_writer, false)
    AND nullif(current_setting('opengeni.memory_lifecycle_operation', true), '') = '1';

  IF NEW.scope IS DISTINCT FROM OLD.scope
    AND ROW(NEW.scope_type, NEW.scope_subject_id, NEW.scope_role_key, NEW.scope_session_id)
      IS NOT DISTINCT FROM ROW(OLD.scope_type, OLD.scope_subject_id, OLD.scope_role_key, OLD.scope_session_id)
    AND NOT lifecycle_writer
  THEN
    NEW.scope_type := CASE WHEN NEW.scope = 'workspace' THEN 'workspace' ELSE 'legacy' END;
    NEW.scope_subject_id := NULL;
    NEW.scope_role_key := NULL;
    NEW.scope_session_id := NULL;
  END IF;

  IF ROW(
    NEW.scope_type, NEW.scope_subject_id, NEW.scope_role_key,
    NEW.scope_session_id, NEW.namespace_key, NEW.labels
  ) IS DISTINCT FROM ROW(
    OLD.scope_type, OLD.scope_subject_id, OLD.scope_role_key,
    OLD.scope_session_id, OLD.namespace_key, OLD.labels
  ) AND NOT lifecycle_writer
  THEN
    RAISE EXCEPTION 'typed memory governance fields mutate only through lifecycle operations'
      USING ERRCODE = '55000';
  END IF;

  typed_change := ROW(
    NEW.status, NEW.scope_type, NEW.scope_subject_id, NEW.scope_role_key,
    NEW.scope_session_id, NEW.namespace_key, NEW.labels, NEW.valid_from,
    NEW.valid_until, NEW.supersedes_id, NEW.superseded_by_id
  ) IS DISTINCT FROM ROW(
    OLD.status, OLD.scope_type, OLD.scope_subject_id, OLD.scope_role_key,
    OLD.scope_session_id, OLD.namespace_key, OLD.labels, OLD.valid_from,
    OLD.valid_until, OLD.supersedes_id, OLD.superseded_by_id
  );
  NEW.memory_version := OLD.memory_version + CASE WHEN typed_change THEN 1 ELSE 0 END;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.lifecycle_backfill_read_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM opengeni_private.lifecycle_backfill_read_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
  )
$$;

CREATE FUNCTION opengeni_private.list_artifact_pins(p_account uuid, p_workspace uuid) RETURNS TABLE(kind text, artifact_id text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_account IS NULL OR p_workspace IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'artifact pin scope mismatch' USING ERRCODE = '42501'; END IF;
  -- Only joined to independently authorized candidates. Private files remain
  -- hidden even when the migration owner is a superuser rather than FORCE-RLS-bound.
  RETURN QUERY SELECT p.kind,p.artifact_id FROM opengeni_private.artifact_catalog_pins p
    WHERE p.account_id=p_account AND p.workspace_id=p_workspace
      AND (p.kind NOT IN ('file','image') OR EXISTS (SELECT 1 FROM files f
        WHERE f.account_id=p_account AND f.workspace_id=p_workspace AND f.id::text=p.artifact_id AND f.status='ready'
          AND (f.private_owner_subject_ids IS NULL OR nullif(current_setting('opengeni.private_file_owner',true),'')=ANY(f.private_owner_subject_ids))));
END $$;

CREATE FUNCTION opengeni_private.list_browser_deadline_checkpoints(p_limit integer) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 500 THEN
        RAISE EXCEPTION 'Invalid browser checkpoint inventory bound' USING ERRCODE = '22023';
      END IF;
      PERFORM set_config('opengeni.sandbox_recovery_protocol_v2', '1', true);
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory(
        {{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY
      SELECT due.target FROM (
        SELECT jsonb_build_object(
            'accountId', lease.account_id, 'workspaceId', lease.workspace_id,
            'sandboxGroupId', lease.sandbox_group_id, 'leaseId', lease.id,
            'leaseEpoch', lease.lease_epoch, 'instanceId', lease.instance_id,
            'browserSessionId', browser.id, 'controllerGeneration', browser.controller_generation
          ) AS target, 0 AS lane, lease.provider_deadline_at AS due_at,
          lease.id AS lease_id, browser.id AS browser_id
        FROM {{schema}}.sandbox_leases lease
        JOIN {{schema}}.browser_sessions browser
          ON browser.account_id = lease.account_id AND browser.workspace_id = lease.workspace_id
          AND browser.controller_host_sandbox_group_id = lease.sandbox_group_id
          AND browser.placement_instance_id = lease.instance_id
        WHERE lease.backend = 'modal' AND lease.liveness IN ('warming', 'warm')
          AND lease.rotation_reason = 'provider_deadline' AND lease.rotation_requested_at IS NOT NULL
          AND lease.provider_deadline_at > now() AND lease.instance_id IS NOT NULL
          AND browser.placement_kind = 'sandbox_group'
          AND browser.lifecycle IN ('active', 'suspending', 'suspended')
          AND browser.controller_generation IS NOT NULL AND browser.controller_id IS NOT NULL
          AND browser.capabilities->>'privateCheckpoint' = 'true'
          AND EXISTS (SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
            WHERE holder.lease_id = lease.id AND holder.kind = 'interaction'
              AND holder.account_id = browser.account_id AND holder.workspace_id = browser.workspace_id
              AND holder.holder_id = 'browser-session:' || browser.id::text)
        UNION ALL
        SELECT jsonb_build_object(
            'accountId', lease.account_id, 'workspaceId', lease.workspace_id,
            'sandboxGroupId', lease.sandbox_group_id, 'leaseId', lease.id,
            'leaseEpoch', lease.lease_epoch, 'instanceId', lease.instance_id,
            'browserSessionId', browser.id, 'controllerGeneration', browser.controller_generation,
            'reason', 'idle'
          ), 1, operation.created_at, lease.id, browser.id
        FROM {{schema}}.sandbox_leases lease
        JOIN {{schema}}.browser_sessions browser
          ON browser.account_id = lease.account_id AND browser.workspace_id = lease.workspace_id
          AND browser.controller_host_sandbox_group_id = lease.sandbox_group_id
          AND browser.placement_instance_id = lease.instance_id
        JOIN {{schema}}.interaction_operations operation
          ON operation.workspace_id = browser.workspace_id
          AND operation.account_id = browser.account_id
          AND operation.resource_kind = 'browser_session' AND operation.resource_id = browser.id
          AND operation.operation_id = opengeni_private.browser_system_checkpoint_operation_id(
            opengeni_private.browser_system_checkpoint_digest('idle', lease.account_id,
              lease.workspace_id, lease.id, lease.lease_epoch, lease.instance_id,
              browser.id::text, browser.controller_generation))
        WHERE lease.backend = 'modal' AND lease.liveness IN ('warming', 'warm')
          AND lease.instance_id IS NOT NULL
          AND browser.placement_kind = 'sandbox_group'
          AND browser.lifecycle IN ('suspending', 'suspended')
          AND browser.controller_generation IS NOT NULL AND browser.controller_id IS NOT NULL
          AND browser.capabilities->>'privateCheckpoint' = 'true'
          AND operation.kind = 'suspend' AND operation.actor_subject_id = 'system:sandbox-idle'
          AND operation.state IN ('prepared', 'dispatched', 'completed')
          AND EXISTS (SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
            WHERE holder.lease_id = lease.id AND holder.kind = 'interaction'
              AND holder.account_id = browser.account_id AND holder.workspace_id = browser.workspace_id
              AND holder.holder_id = 'browser-session:' || browser.id::text)
      ) due
      ORDER BY due.lane, due.due_at, due.lease_id, due.browser_id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.list_command_containment_candidates(p_limit integer, p_idle_ms bigint) RETURNS TABLE(account_id uuid, workspace_id uuid, sandbox_group_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE inventory_id uuid; idle_before timestamptz;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid drain batch'; END IF;
      IF p_idle_ms IS NOT NULL AND p_idle_ms < 1 THEN RAISE EXCEPTION 'invalid idle window'; END IF;
      idle_before := now() - p_idle_ms * interval '1 millisecond';
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT lease.account_id, lease.workspace_id, lease.sandbox_group_id
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.backend IN ('modal', 'docker', 'local') AND lease.liveness IN ('warm', 'draining')
        AND (lease.unobservable_command_drain_ids IS NOT NULL OR (
          lease.archive_capture_id IS NULL
          AND (lease.reaper_hold_until IS NULL OR lease.reaper_hold_until <= now())
          AND EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_retained_processes process
            WHERE process.lease_id = lease.id AND process.state = 'active'
          )
          AND NOT EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_retained_processes process
            WHERE process.lease_id = lease.id AND process.state = 'active'
              AND coalesce(process.provider_command, '{}'::jsonb) ? 'supervision'
          )
          AND NOT EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
            WHERE holder.lease_id = lease.id AND holder.kind <> 'process'
          )
          AND (lease.rotation_requested_at IS NOT NULL OR (
            idle_before IS NOT NULL
            AND lease.holders_changed_at < idle_before
            AND NOT EXISTS (
              SELECT 1 FROM {{schema}}.sandbox_workspace_mutation_admissions admission
              WHERE admission.lease_id = lease.id AND admission.lease_epoch = lease.lease_epoch
                AND coalesce(admission.settled_at, admission.admitted_at) >= idle_before
            )
            AND NOT EXISTS (
              SELECT 1 FROM {{schema}}.sessions member
              WHERE member.workspace_id = lease.workspace_id
                AND (member.sandbox_group_id = lease.sandbox_group_id OR EXISTS (
                  SELECT 1 FROM {{schema}}.sandbox_retained_processes owned
                  WHERE owned.lease_id = lease.id AND owned.state = 'active'
                    AND owned.session_id = member.id))
                AND (
                  -- Unclaimed turn-starting machine input, on the idle
                  -- clock from its creation (a paused session may never
                  -- deliver it). A held input wait is not itself a fact.
                  EXISTS (
                    SELECT 1 FROM {{schema}}.session_system_updates pending_update
                    WHERE pending_update.workspace_id = member.workspace_id
                      AND pending_update.session_id = member.id
                      AND pending_update.state = 'pending'
                      AND pending_update.created_at >= idle_before
                      AND (pending_update.kind IN ('scheduled_occurrence', 'goal_continuation',
                          'agent_message', 'agent_steer_instruction', 'session_wait_timeout',
                          'media_generation_result', 'secret_use_approval_decided', 'capability_setup_completed')
                        OR (pending_update.kind IN ('child_terminal_result', 'child_requires_action')
                          AND EXISTS (
                            SELECT 1 FROM {{schema}}.session_goals goal
                            WHERE goal.workspace_id = member.workspace_id
                              AND goal.session_id = member.id AND goal.status = 'active')))
                  )
                  OR
                  EXISTS (
                    SELECT 1 FROM {{schema}}.session_turns turn
                    WHERE turn.workspace_id = member.workspace_id AND turn.session_id = member.id
                      -- requires_action waits for a person: not use.
                      AND turn.status IN ('queued', 'running', 'waiting_capacity')
                  )
                  OR EXISTS (
                    SELECT 1 FROM {{schema}}.session_turns turn
                    WHERE turn.workspace_id = member.workspace_id AND turn.session_id = member.id
                      AND turn.finished_at >= idle_before
                  )
                  OR EXISTS (
                    SELECT 1 FROM {{schema}}.session_turn_attempts attempt
                    WHERE attempt.workspace_id = member.workspace_id
                      AND attempt.session_id = member.id
                      AND (attempt.state <> 'closed' OR coalesce(attempt.quiesced_at,
                        attempt.closed_at, attempt.updated_at) >= idle_before)
                  )
                )
            )
          ))
        ))
      ORDER BY
        CASE WHEN lease.rotation_reason = 'provider_deadline'
          AND lease.rotation_requested_at IS NOT NULL THEN 0 ELSE 1 END,
        CASE WHEN lease.rotation_reason = 'provider_deadline'
          AND lease.rotation_requested_at IS NOT NULL
          THEN lease.provider_deadline_at END NULLS LAST,
        lease.unobservable_command_checked_at NULLS FIRST,
        lease.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.list_continuable_sessions(p_workspace_id uuid, p_root_session_id uuid) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, temporal_workflow_id text, reasons text[])
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
      WITH RECURSIVE control_tree AS (
        SELECT session.workspace_id, session.id, session.parent_session_id,
               greatest(control.workspace_pause_revision, session.direct_pause_revision)
                 AS max_pause_revision,
               session.subtree_run_override_revision AS max_override_revision,
               0::integer AS depth
        FROM {{schema}}.sessions session
        JOIN {{schema}}.workspace_inference_controls control
          ON control.workspace_id = session.workspace_id
        WHERE session.parent_session_id IS NULL
          AND (p_workspace_id IS NULL OR session.workspace_id = p_workspace_id)
        UNION ALL
        SELECT child.workspace_id, child.id, child.parent_session_id,
               greatest(parent.max_pause_revision, child.direct_pause_revision),
               greatest(parent.max_override_revision, child.subtree_run_override_revision),
               parent.depth + 1
        FROM control_tree parent
        JOIN {{schema}}.sessions child
          ON child.workspace_id = parent.workspace_id
         AND child.parent_session_id = parent.id
        WHERE parent.depth < 10000
      ), descendants AS (
        SELECT tree.workspace_id, tree.id
        FROM control_tree tree
        WHERE p_root_session_id IS NOT NULL AND tree.id = p_root_session_id
        UNION ALL
        SELECT child.workspace_id, child.id
        FROM descendants parent
        JOIN control_tree child
          ON child.workspace_id = parent.workspace_id
         AND child.parent_session_id = parent.id
      ), scope_sessions AS (
        SELECT session.*, tree.max_pause_revision, tree.max_override_revision
        FROM {{schema}}.sessions session
        JOIN control_tree tree
          ON tree.workspace_id = session.workspace_id AND tree.id = session.id
        WHERE (
            p_root_session_id IS NULL
            OR EXISTS (
              SELECT 1 FROM descendants descendant
              WHERE descendant.workspace_id = session.workspace_id
                AND descendant.id = session.id
            )
          )
      ), control_state AS (
        SELECT session.workspace_id, session.id AS session_id,
               session.max_pause_revision IS NOT NULL
                 AND (
                   session.max_override_revision IS NULL
                   OR session.max_pause_revision >= session.max_override_revision
                 ) AS blocked
        FROM scope_sessions session
      ), unsettled_interruptions AS (
        SELECT DISTINCT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        JOIN {{schema}}.session_attempt_interruptions interruption
          ON interruption.workspace_id = session.workspace_id
         AND interruption.session_id = session.id
        WHERE interruption.state IN ('pending', 'delivered', 'acknowledged')
      ), queued_human AS (
        SELECT DISTINCT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        JOIN {{schema}}.session_turns turn
          ON turn.workspace_id = session.workspace_id AND turn.session_id = session.id
        WHERE turn.status = 'queued' AND turn.source IN ('user', 'api')
      ), recovering_turn AS (
        SELECT DISTINCT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        JOIN {{schema}}.session_turns turn
          ON turn.workspace_id = session.workspace_id
         AND turn.session_id = session.id
         AND turn.id = session.active_turn_id
        WHERE turn.status = 'recovering'
      ), capacity_wait AS (
        SELECT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        WHERE EXISTS (
            SELECT 1 FROM {{schema}}.codex_capacity_waiters waiter
            WHERE waiter.workspace_id = session.workspace_id
              AND waiter.session_id = session.id
              AND waiter.status = 'waiting'
          )
          OR EXISTS (
            SELECT 1 FROM {{schema}}.subscription_capacity_waiters waiter
            WHERE waiter.workspace_id = session.workspace_id
              AND waiter.session_id = session.id
          )
          OR EXISTS (
            SELECT 1 FROM {{schema}}.session_turns turn
            WHERE turn.workspace_id = session.workspace_id
              AND turn.session_id = session.id
              AND turn.id = session.active_turn_id
              AND turn.status = 'waiting_capacity'
          )
      ), decided_approval AS (
        SELECT DISTINCT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        JOIN {{schema}}.session_turns turn
          ON turn.workspace_id = session.workspace_id
         AND turn.session_id = session.id
         AND turn.id = session.active_turn_id
        JOIN {{schema}}.session_events trigger_event
          ON trigger_event.workspace_id = turn.workspace_id
         AND trigger_event.id = turn.trigger_event_id
        JOIN {{schema}}.session_events decision
          ON decision.workspace_id = turn.workspace_id
         AND decision.session_id = turn.session_id
         AND decision.sequence > trigger_event.sequence
         AND decision.type = 'user.approvalDecision'
        WHERE turn.status = 'requires_action'
      ), active_goal AS (
        SELECT DISTINCT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        JOIN {{schema}}.session_goals goal
          ON goal.workspace_id = session.workspace_id AND goal.session_id = session.id
        WHERE goal.status = 'active'
      ), pending_internal_updates AS (
        SELECT DISTINCT session.workspace_id, session.id AS session_id
        FROM scope_sessions session
        JOIN {{schema}}.session_system_updates update_row
          ON update_row.workspace_id = session.workspace_id
         AND update_row.session_id = session.id
        WHERE update_row.state = 'pending'
      ), classified AS (
        SELECT session.account_id, session.workspace_id, session.id AS session_id,
               coalesce(session.temporal_workflow_id, 'session-' || session.id::text)
                 AS temporal_workflow_id,
               array_remove(ARRAY[
                 CASE WHEN interruption.session_id IS NOT NULL
                   THEN 'interruption_settlement' END,
                 CASE WHEN NOT control.blocked AND queued.session_id IS NOT NULL
                   THEN 'queued_human' END,
                 CASE WHEN NOT control.blocked AND recovering.session_id IS NOT NULL
                   THEN 'recovering_turn' END,
                 CASE WHEN NOT control.blocked AND capacity.session_id IS NOT NULL
                   THEN 'capacity_wait' END,
                 CASE WHEN NOT control.blocked AND approval.session_id IS NOT NULL
                   THEN 'decided_approval' END,
                 CASE WHEN NOT control.blocked AND goal.session_id IS NOT NULL
                   THEN 'active_goal' END,
                 CASE WHEN NOT control.blocked AND updates.session_id IS NOT NULL
                   THEN 'pending_internal_updates' END,
                 CASE WHEN NOT control.blocked AND session.compact_requested
                   THEN 'compaction_requested' END
               ]::text[], NULL) AS reasons
        FROM scope_sessions session
        JOIN control_state control
          ON control.workspace_id = session.workspace_id AND control.session_id = session.id
        LEFT JOIN unsettled_interruptions interruption
          ON interruption.workspace_id = session.workspace_id
         AND interruption.session_id = session.id
        LEFT JOIN queued_human queued
          ON queued.workspace_id = session.workspace_id AND queued.session_id = session.id
        LEFT JOIN recovering_turn recovering
          ON recovering.workspace_id = session.workspace_id AND recovering.session_id = session.id
        LEFT JOIN capacity_wait capacity
          ON capacity.workspace_id = session.workspace_id AND capacity.session_id = session.id
        LEFT JOIN decided_approval approval
          ON approval.workspace_id = session.workspace_id AND approval.session_id = session.id
        LEFT JOIN active_goal goal
          ON goal.workspace_id = session.workspace_id AND goal.session_id = session.id
        LEFT JOIN pending_internal_updates updates
          ON updates.workspace_id = session.workspace_id AND updates.session_id = session.id
      )
      SELECT classified.account_id, classified.workspace_id, classified.session_id,
             classified.temporal_workflow_id, classified.reasons
      FROM classified
      WHERE cardinality(classified.reasons) > 0
      ORDER BY classified.workspace_id, classified.session_id
    $$;

CREATE FUNCTION opengeni_private.list_due_event_source_feeds_v1(p_limit integer) RETURNS TABLE(source_id uuid, workspace_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  SELECT feed.source_id, feed.workspace_id
  FROM event_source_feeds feed
  WHERE feed.next_action_at <= pg_catalog.now()
    AND (feed.lease_until IS NULL OR feed.lease_until <= pg_catalog.now())
  ORDER BY feed.next_action_at, feed.source_id
  LIMIT greatest(1, least(coalesce(p_limit, 32), 200));
$$;

CREATE FUNCTION opengeni_private.list_due_event_trigger_tasks_v1(p_limit integer) RETURNS TABLE(task_id uuid, workspace_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  SELECT settings.task_id, settings.workspace_id
  FROM scheduled_task_event_settings settings
  WHERE settings.dispatch_due_at IS NOT NULL
    AND settings.dispatch_due_at <= pg_catalog.now()
  ORDER BY settings.dispatch_due_at, settings.task_id
  LIMIT greatest(1, least(coalesce(p_limit, 32), 200));
$$;

CREATE FUNCTION opengeni_private.list_due_mcp_event_subscriptions_v1(p_limit integer) RETURNS TABLE(subscription_id uuid, workspace_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  SELECT subscription.id, subscription.workspace_id
  FROM mcp_event_subscriptions subscription
  WHERE subscription.next_action_at <= pg_catalog.now()
    AND (subscription.lease_until IS NULL OR subscription.lease_until <= pg_catalog.now())
  ORDER BY subscription.next_action_at, subscription.id
  LIMIT greatest(1, least(coalesce(p_limit, 32), 200));
$$;

CREATE FUNCTION opengeni_private.list_due_recording_retention_v1(p_limit integer) RETURNS TABLE(kind text, account_id uuid, workspace_id uuid, recording_id uuid, owner_subject_id text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  WITH retention AS (
    SELECT workspace.id AS workspace_id,
      CASE WHEN pg_catalog.jsonb_typeof(workspace.settings #> '{recordings,retention,audioDays}') = 'number'
        THEN least(greatest(floor((workspace.settings #>> '{recordings,retention,audioDays}')::numeric), 0), 36500)::integer
      END AS audio_days,
      CASE WHEN pg_catalog.jsonb_typeof(workspace.settings #> '{recordings,retention,transcriptDays}') = 'number'
        THEN least(greatest(floor((workspace.settings #>> '{recordings,retention,transcriptDays}')::numeric), 1), 36500)::integer
      END AS transcript_days
    FROM workspaces workspace
    WHERE pg_catalog.jsonb_typeof(workspace.settings #> '{recordings,retention}') = 'object'
  )
  (
    SELECT 'recording', recording.account_id, recording.workspace_id, recording.id,
      recording.owner_subject_id
    FROM retention
    JOIN recordings recording ON recording.workspace_id = retention.workspace_id
    WHERE retention.transcript_days IS NOT NULL
      AND recording.purpose = 'meeting'
      AND recording.state IN ('ready', 'failed')
      AND coalesce(recording.capture_ended_at, recording.started_at)
        < pg_catalog.now() - pg_catalog.make_interval(days => retention.transcript_days)
    ORDER BY recording.started_at, recording.id
    LIMIT greatest(1, least(coalesce(p_limit, 50), 200))
  )
  UNION ALL
  (
    SELECT 'audio', recording.account_id, recording.workspace_id, recording.id,
      recording.owner_subject_id
    FROM retention
    JOIN recordings recording ON recording.workspace_id = retention.workspace_id
    WHERE retention.audio_days IS NOT NULL
      AND recording.purpose = 'meeting'
      AND recording.state IN ('ready', 'failed')
      AND (
        (
          recording.audio_deleted_at IS NULL
          AND coalesce(recording.capture_ended_at, recording.started_at)
            < pg_catalog.now() - pg_catalog.make_interval(days => retention.audio_days)
          AND NOT EXISTS (
            SELECT 1 FROM recording_transcript_versions version
            WHERE version.workspace_id = recording.workspace_id
              AND version.recording_id = recording.id
              AND version.state IN ('queued', 'processing')
          )
        )
        -- Stamped, but the worker stopped before every object was gone.
        OR (
          recording.audio_deleted_at IS NOT NULL
          AND (
            EXISTS (
              SELECT 1 FROM recording_chunks chunk
              WHERE chunk.workspace_id = recording.workspace_id
                AND chunk.recording_id = recording.id
            )
            OR EXISTS (
              SELECT 1 FROM recording_tracks track
              WHERE track.workspace_id = recording.workspace_id
                AND track.recording_id = recording.id
                AND track.prepared_object_key IS NOT NULL
            )
          )
        )
      )
    ORDER BY recording.started_at, recording.id
    LIMIT greatest(1, least(coalesce(p_limit, 50), 200))
  );
$$;

CREATE FUNCTION opengeni_private.list_due_workspace_pause_timers(p_limit integer) RETURNS TABLE(workspace_id uuid, timer_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE previous text := current_setting('opengeni.pause_timer_discovery', true);
    BEGIN
      PERFORM set_config('opengeni.pause_timer_discovery', '1', true);
      RETURN QUERY SELECT c.workspace_id, c.timer_id FROM {{schema}}.workspace_inference_controls c
        WHERE c.timer_id IS NOT NULL AND c.timer_due_at <= clock_timestamp()
        ORDER BY c.timer_due_at, c.workspace_id LIMIT greatest(1, least(coalesce(p_limit, 100), 1000));
      PERFORM set_config('opengeni.pause_timer_discovery', coalesce(previous, ''), true);
    END $$;

CREATE FUNCTION opengeni_private.list_exhausted_scheduled_tasks(p_limit integer) RETURNS TABLE(id uuid, workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'Invalid exhausted schedule inventory bound' USING ERRCODE = '22023';
      END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT task.id, task.workspace_id FROM {{schema}}.scheduled_tasks task
        WHERE task.status = 'active' AND task.deleted_at IS NULL
          AND {{schema}}.scheduled_task_is_exhausted(task.id)
        ORDER BY task.updated_at, task.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.list_idle_checkpoint_candidates(p_limit integer, p_interval_ms bigint) RETURNS TABLE(account_id uuid, workspace_id uuid, sandbox_group_id uuid, lease_epoch integer, instance_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid; due_before timestamptz;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid checkpoint batch'; END IF;
      IF p_interval_ms IS NULL OR p_interval_ms < 1 THEN
        RAISE EXCEPTION 'invalid checkpoint interval';
      END IF;
      due_before := now() - p_interval_ms * interval '1 millisecond';
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT lease.account_id, lease.workspace_id, lease.sandbox_group_id,
        lease.lease_epoch, lease.instance_id
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.backend = 'modal' AND lease.liveness = 'warm'
        AND lease.instance_id IS NOT NULL
        AND lease.turn_holders = 0
        -- Something other than a turn keeps it warm; a box no holder keeps
        -- warm belongs to the idle drain, which captures before teardown.
        AND lease.refcount > 0
        AND lease.unobservable_command_drain_ids IS NULL
        AND lease.rotation_requested_at IS NULL
        AND (lease.reaper_hold_until IS NULL OR lease.reaper_hold_until <= now())
        AND (lease.archive_generation IS NULL
          OR lease.archive_generation < lease.workspace_generation
          OR lease.untracked_writer_since IS NOT NULL
          OR EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_lease_holders writer
            WHERE writer.lease_id = lease.id AND writer.kind IN ('viewer', 'interaction')))
        -- Coalesced with every other warm capture of the box on one clock.
        AND (lease.archive_capture_last_attempt_at IS NULL
          OR lease.archive_capture_last_attempt_at <= due_before)
        -- And never more than once per interval from this sweep, whatever the
        -- previous attempt's outcome.
        AND (lease.idle_checkpoint_attempted_at IS NULL
          OR lease.idle_checkpoint_attempted_at <= due_before)
        -- No capture in progress, or one whose owner died: past its deadline,
        -- takeover-safe and never published.
        AND (lease.archive_capture_id IS NULL OR (
          lease.archive_capture_published_at IS NULL
          AND lease.archive_capture_deadline_at <= now()
          AND lease.archive_capture_takeover_safe))
        -- Only a paused-box (native Modal) image may run around commands.
        -- Same resolution as the claim path's leaseCaptureIsPointInTime.
        AND (CASE
          WHEN jsonb_typeof(lease.resume_state -> 'sessionState') = 'object' THEN coalesce(
            CASE WHEN jsonb_typeof(lease.resume_state #> '{sessionState,providerState}') = 'object'
              THEN lease.resume_state #>> '{sessionState,providerState,workspacePersistence}' END,
            lease.resume_state #>> '{sessionState,workspacePersistence}')
          ELSE coalesce(
            CASE WHEN jsonb_typeof(lease.resume_state -> 'providerState') = 'object'
              THEN lease.resume_state #>> '{providerState,workspacePersistence}' END,
            lease.resume_state ->> 'workspacePersistence')
        END) IN ('snapshot_filesystem', 'snapshot_directory')
        -- Every holder is one the capture may run around: a viewer, an
        -- interaction, or an active command (supervised or not) on this
        -- exact box.
        -- A direct request or any other process holder blocks the claim.
        AND NOT EXISTS (
          SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
          WHERE holder.lease_id = lease.id
            AND holder.kind NOT IN ('viewer', 'interaction')
            AND NOT (holder.kind = 'process' AND EXISTS (
              SELECT 1 FROM {{schema}}.sandbox_retained_processes process
              WHERE process.holder_id = holder.holder_id
                AND process.lease_id = lease.id AND process.lease_epoch = lease.lease_epoch
                AND process.provider_instance_id = lease.instance_id
                AND process.state = 'active'))
        )
      -- Least recently tried first; greatest() ignores a null clock.
      ORDER BY greatest(lease.archive_capture_last_attempt_at,
        lease.idle_checkpoint_attempted_at) NULLS FIRST, lease.id
      LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.list_idle_interaction_leases(p_limit integer, p_idle_ms bigint) RETURNS TABLE(account_id uuid, workspace_id uuid, sandbox_group_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE inventory_id uuid; idle_before timestamptz;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid idle interaction batch'; END IF;
      IF p_idle_ms IS NULL OR p_idle_ms < 60000 THEN RAISE EXCEPTION 'invalid idle window'; END IF;
      idle_before := now() - p_idle_ms * interval '1 millisecond';
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT lease.account_id, lease.workspace_id, lease.sandbox_group_id
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.backend = 'modal' AND lease.liveness = 'warm' AND lease.instance_id IS NOT NULL
        AND lease.rotation_requested_at IS NULL AND lease.archive_capture_id IS NULL
        AND lease.unobservable_command_drain_ids IS NULL
        AND (lease.reaper_hold_until IS NULL OR lease.reaper_hold_until <= now())
        AND lease.holders_changed_at < idle_before
        AND EXISTS (SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
          WHERE holder.lease_id = lease.id AND holder.kind = 'interaction')
        AND NOT EXISTS (SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
          WHERE holder.lease_id = lease.id AND holder.kind NOT IN ('interaction', 'process'))
        AND NOT EXISTS (
          SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
          LEFT JOIN {{schema}}.browser_sessions browser
            ON holder.holder_id LIKE 'browser-session:%'
            AND browser.id = CASE WHEN holder.holder_id ~ '^browser-session:[0-9a-f-]{36}$'
              THEN substr(holder.holder_id, 17)::uuid END
            AND browser.account_id = holder.account_id AND browser.workspace_id = holder.workspace_id
          LEFT JOIN {{schema}}.computer_sessions computer
            ON holder.holder_id LIKE 'computer-session:%'
            AND computer.id = CASE WHEN holder.holder_id ~ '^computer-session:[0-9a-f-]{36}$'
              THEN substr(holder.holder_id, 18)::uuid END
            AND computer.account_id = holder.account_id AND computer.workspace_id = holder.workspace_id
          WHERE holder.lease_id = lease.id AND holder.kind = 'interaction'
            AND (greatest(holder.last_heartbeat_at, browser.last_used_at,
                browser.controller_heartbeat_at, computer.last_used_at,
                computer.controller_heartbeat_at) >= idle_before
              OR EXISTS (SELECT 1 FROM {{schema}}.interaction_operations operation
                WHERE operation.workspace_id = holder.workspace_id
                  AND operation.state IN ('prepared', 'dispatched')
                  AND ((operation.resource_kind = 'browser_session' AND operation.resource_id = browser.id)
                    OR (operation.resource_kind = 'computer_session'
                      AND operation.resource_id = computer.id))))
        )
      ORDER BY lease.holders_changed_at, lease.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $_$;

CREATE FUNCTION opengeni_private.list_inbox_items_v1(p_account_id uuid, p_subject_id text) RETURNS TABLE(id uuid, workspace_id uuid, session_id uuid, kind text, source_key text, title text, body text, choices jsonb, urgency text, status text, unread boolean, snoozed_until timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, resolved_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT item.id, item.workspace_id, item.session_id, item.kind,
    item.source_key, item.title, item.body, item.choices, item.urgency, item.status,
    item.seen_version < item.content_version, item.snoozed_until, item.created_at,
    item.updated_at, item.resolved_at
  FROM opengeni_private.inbox_items item
  WHERE item.account_id = p_account_id
    AND item.recipient_subject_id = p_subject_id
    AND item.status = 'open'
  ORDER BY item.updated_at DESC
  LIMIT 500
$$;

