CREATE FUNCTION opengeni_private.list_legacy_modal_checkpoint_slots(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, sandbox_group_id uuid, lease_id uuid, lease_epoch integer, instance_id text, workspace_generation integer, slot text, archive_base64 text, descriptor jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_limit IS NULL OR p_limit < 1 OR p_limit > 500 THEN
        RAISE EXCEPTION 'legacy checkpoint slot limit must be between 1 and 500'
          USING ERRCODE = '22023';
      END IF;

      RETURN QUERY
        SELECT lease.account_id, lease.workspace_id, lease.sandbox_group_id, lease.id,
          lease.lease_epoch, lease.instance_id,
          lease.workspace_generation, candidate.slot, candidate.archive_base64,
          candidate.descriptor
        FROM {{schema}}.sandbox_leases lease
        CROSS JOIN LATERAL (
          VALUES
            (
              'current'::text,
              lease.resume_state #>> '{sessionState,workspaceArchive}',
              lease.resume_state #> '{sessionState,workspaceArchiveMeta}',
              lease.current_checkpoint_artifact_id
            ),
            (
              'previous'::text,
              lease.resume_state #>> '{sessionState,workspaceArchivePrev}',
              lease.resume_state #> '{sessionState,workspaceArchivePrevMeta}',
              lease.previous_checkpoint_artifact_id
            )
        ) candidate(slot, archive_base64, descriptor, artifact_id)
        WHERE candidate.artifact_id IS NULL
          AND lease.backend = 'modal'
          AND lease.liveness IN ('warming', 'warm', 'draining')
          AND lease.instance_id IS NOT NULL
          AND coalesce(candidate.archive_base64, '') <> ''
          AND candidate.descriptor ->> 'version' = '2'
          AND candidate.descriptor ->> 'provider'
            IN ('modal_snapshot_filesystem', 'modal_snapshot_directory')
        ORDER BY lease.updated_at, lease.id, candidate.slot
        LIMIT p_limit;
    END;
    $$;

CREATE FUNCTION opengeni_private.list_live_modal_sandbox_leases() RETURNS TABLE(lease_id uuid, workspace_id uuid, sandbox_group_id uuid, instance_id text, liveness text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE opened integer;
    BEGIN
      INSERT INTO opengeni_private.modal_inventory_read_capabilities (
        backend_pid, transaction_id, data_schema
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), '{{schema}}')
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS opened = ROW_COUNT;

      RETURN QUERY SELECT lease.id, lease.workspace_id, lease.sandbox_group_id,
        lease.instance_id, lease.liveness
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.liveness IN ('warming', 'warm', 'draining')
        AND (lease.backend = 'modal' OR lease.resume_backend_id = 'modal');

      IF opened = 1 THEN
        DELETE FROM opengeni_private.modal_inventory_read_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.data_schema = '{{schema}}';
      END IF;
      RETURN;
    END
    $$;

CREATE FUNCTION opengeni_private.list_meterable_warm_leases() RETURNS TABLE(account_id uuid, workspace_id uuid, sandbox_group_id uuid, lease_epoch integer, backend text)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  SELECT L.account_id, L.workspace_id, L.sandbox_group_id, L.lease_epoch, L.backend
  FROM sandbox_leases L
  WHERE L.liveness = 'warm' AND L.turn_holders = 0;
$$;

CREATE FUNCTION opengeni_private.list_organization_slack_bots(p_account uuid, p_target uuid) RETURNS TABLE(connection_id uuid, home_workspace_id uuid, generation bigint, connection_version integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE access record; prior_workspace text;
BEGIN
  IF p_account IS NULL OR p_target IS NULL OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_target IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'Slack bot discovery scope mismatch' USING ERRCODE = '42501'; END IF;
  PERFORM 1 FROM workspaces w WHERE w.id = p_target AND w.account_id = p_account;
  IF NOT FOUND THEN RAISE EXCEPTION 'Slack bot target unavailable' USING ERRCODE = '42501'; END IF;
  prior_workspace := current_setting('opengeni.workspace_id', true);
  FOR access IN SELECT a.* FROM opengeni_private.organization_slack_bot_access a
    WHERE a.account_id = p_account AND a.enabled
      AND (a.workspace_ids IS NULL OR p_target = ANY(a.workspace_ids)) ORDER BY a.connection_id
  LOOP
    PERFORM set_config('opengeni.workspace_id', access.home_workspace_id::text, true);
    RETURN QUERY SELECT c.id, c.workspace_id, access.generation, c.version FROM connections c
      WHERE c.id = access.connection_id AND c.account_id = p_account AND c.workspace_id = access.home_workspace_id
      AND c.subject_id IS NULL AND c.kind = 'app_install' AND c.provider_domain = 'slack.com'
      AND c.metadata->>'credentialRole' = 'opengeni_slack_bot' AND c.status = 'active'
      AND c.verified_install_at IS NOT NULL AND c.verified_install_version = c.version;
  END LOOP;
  PERFORM set_config('opengeni.workspace_id', coalesce(prior_workspace, ''), true);
END $$;

CREATE FUNCTION opengeni_private.list_orphaned_idle_browser_checkpoints(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, browser_session_id uuid, controller_generation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid idle checkpoint cleanup batch'; END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT browser.account_id, browser.workspace_id, browser.id, browser.controller_generation
      FROM {{schema}}.browser_sessions browser
      WHERE browser.lifecycle = 'suspended'
        AND browser.private_checkpoint_artifact_id IS NOT NULL
        AND browser.controller_generation IS NOT NULL
        AND EXISTS (SELECT 1 FROM {{schema}}.interaction_operations operation
          WHERE operation.workspace_id = browser.workspace_id
            AND operation.resource_kind = 'browser_session' AND operation.resource_id = browser.id
            AND operation.kind = 'suspend' AND operation.state = 'completed'
            AND operation.actor_subject_id = 'system:sandbox-idle'
            AND operation.controller_generation = browser.controller_generation)
        AND NOT EXISTS (SELECT 1 FROM {{schema}}.interaction_operations operation
          WHERE operation.workspace_id = browser.workspace_id
            AND operation.resource_kind = 'browser_session' AND operation.resource_id = browser.id
            AND operation.state IN ('prepared', 'dispatched'))
        AND NOT EXISTS (SELECT 1 FROM {{schema}}.sandbox_lease_holders holder
          WHERE holder.workspace_id = browser.workspace_id AND holder.kind = 'interaction'
            AND holder.holder_id = 'browser-session:' || browser.id::text)
      ORDER BY browser.updated_at, browser.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.list_pending_child_terminal_wake_repairs_v1(p_limit integer, p_after_workspace_id uuid, p_after_session_id uuid) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid child repair batch'; END IF;
      IF (p_after_workspace_id IS NULL) <> (p_after_session_id IS NULL) THEN
        RAISE EXCEPTION 'incomplete child repair cursor';
      END IF;
      RETURN QUERY
        SELECT DISTINCT input.account_id, input.workspace_id, input.session_id
        FROM {{schema}}.session_system_updates input
        JOIN {{schema}}.sessions parent ON parent.account_id = input.account_id
          AND parent.workspace_id = input.workspace_id AND parent.id = input.session_id
        JOIN {{schema}}.session_system_update_outbox producer
          ON producer.account_id = input.account_id AND producer.workspace_id = input.workspace_id
          AND producer.target_session_id = input.session_id AND producer.dedupe_key = input.dedupe_key
          AND producer.source_id = input.source_id AND producer.kind = 'child_terminal_result'
          AND producer.status = 'delivered'
        JOIN {{schema}}.sessions child ON child.account_id = input.account_id
          AND child.workspace_id = input.workspace_id AND child.id = producer.source_session_id
          AND child.parent_session_id = input.session_id AND child.id::text = input.source_id
        LEFT JOIN {{schema}}.session_workflow_wake_outbox wake
          ON wake.account_id = input.account_id AND wake.workspace_id = input.workspace_id
          AND wake.session_id = input.session_id
        WHERE input.state = 'pending' AND input.kind = 'child_terminal_result'
          AND input.payload ->> 'childSessionId' = input.source_id
          AND parent.status = 'idle' AND parent.active_turn_id IS NULL AND parent.admission_block IS NULL
          AND NOT EXISTS (SELECT 1 FROM {{schema}}.session_goals goal
            WHERE goal.workspace_id = input.workspace_id AND goal.session_id = input.session_id)
          AND (wake.session_id IS NULL OR wake.wake_revision = wake.delivered_revision)
          AND (p_after_workspace_id IS NULL OR
            (input.workspace_id, input.session_id) > (p_after_workspace_id, p_after_session_id))
        ORDER BY input.workspace_id, input.session_id, input.account_id LIMIT p_limit;
    END $$;

CREATE FUNCTION opengeni_private.list_pending_modal_provider_creates() RETURNS TABLE(workspace_id uuid, sandbox_group_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE opened integer;
    BEGIN
      INSERT INTO opengeni_private.modal_inventory_read_capabilities
        (backend_pid, transaction_id, data_schema)
      VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), '{{schema}}')
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS opened = ROW_COUNT;
      RETURN QUERY SELECT lease.workspace_id, lease.sandbox_group_id
        FROM {{schema}}.sandbox_leases lease
        WHERE lease.backend = 'modal' AND lease.liveness = 'warming'
          AND lease.instance_id IS NULL
          AND lease.provider_create_attempt->'instanceId' = 'null'::jsonb
          AND lease.expires_at < now()
          AND coalesce(lease.provider_create_recovery_after, '-infinity'::timestamptz) <= now()
        ORDER BY coalesce(lease.provider_create_recovery_after, '-infinity'::timestamptz), lease.id LIMIT 32;
      IF opened = 1 THEN
        DELETE FROM opengeni_private.modal_inventory_read_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.data_schema = '{{schema}}';
      END IF;
    END
    $$;

CREATE FUNCTION opengeni_private.list_quiescence_receipt_wake_repairs_v1(p_limit integer, p_after_workspace_id uuid, p_after_session_id uuid) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    #variable_conflict use_column
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid quiescence repair batch'; END IF;
      IF (p_after_workspace_id IS NULL) <> (p_after_session_id IS NULL) THEN
        RAISE EXCEPTION 'incomplete quiescence repair cursor';
      END IF;
      RETURN QUERY
        WITH candidate AS MATERIALIZED (
          SELECT session.account_id AS candidate_account_id,
            session.workspace_id AS candidate_workspace_id,
            session.id AS candidate_session_id,
            session.status = 'recovering' AS projection_recovering,
            session.admission_block IS NOT NULL AS admission_blocked,
            attempt.quiesced_at IS NOT NULL AS quiesced,
            (
              (turn.metadata -> 'sandboxSetupOutcomeUnknown') @> jsonb_build_object(
                'version', 1, 'reason', 'sandbox_command_start_outcome_unknown')
              AND jsonb_typeof(turn.metadata -> 'sandboxSetupOutcomeUnknown' -> 'turnId') = 'string'
              AND turn.metadata -> 'sandboxSetupOutcomeUnknown' ->> 'turnId' <> ''
              AND jsonb_typeof(turn.metadata -> 'sandboxSetupOutcomeUnknown' -> 'attemptId') = 'string'
              AND turn.metadata -> 'sandboxSetupOutcomeUnknown' ->> 'attemptId' <> ''
            ) IS TRUE OR (
              (turn.metadata -> 'sandboxSetupRecoveryExhausted') @> jsonb_build_object(
                'version', 1, 'reason', 'sandbox_command_start_recovery_exhausted',
                'setupOutcome', 'not_started', 'providerRecoveryCount', 5)
              AND jsonb_typeof(turn.metadata -> 'sandboxSetupRecoveryExhausted' -> 'turnId') = 'string'
              AND turn.metadata -> 'sandboxSetupRecoveryExhausted' ->> 'turnId' <> ''
              AND jsonb_typeof(turn.metadata -> 'sandboxSetupRecoveryExhausted' -> 'attemptId') = 'string'
              AND turn.metadata -> 'sandboxSetupRecoveryExhausted' ->> 'attemptId' <> ''
            ) IS TRUE AS setup_blocked
          FROM {{schema}}.sessions session
          JOIN {{schema}}.session_turns turn ON turn.workspace_id = session.workspace_id
            AND turn.session_id = session.id AND turn.id = session.active_turn_id
          JOIN LATERAL (
            SELECT latest.id, latest.state, latest.outcome, latest.quiesced_at,
              coalesce(latest.closed_at, latest.updated_at) AS closed_at
            FROM {{schema}}.session_turn_attempts latest
            WHERE latest.workspace_id = turn.workspace_id AND latest.session_id = turn.session_id
              AND latest.turn_id = turn.id
            ORDER BY latest.execution_generation DESC, latest.updated_at DESC, latest.id DESC LIMIT 1
          ) attempt ON true
          LEFT JOIN {{schema}}.session_workflow_wake_outbox wake ON wake.workspace_id = session.workspace_id AND wake.session_id = session.id
          WHERE turn.status = 'recovering' AND turn.active_attempt_id IS NULL
            AND attempt.state = 'closed' AND attempt.outcome = 'interrupted_recoverable'
            AND (attempt.quiesced_at IS NULL AND session.status = 'recovering'
              OR attempt.quiesced_at IS NOT NULL AND session.status NOT IN ('failed', 'cancelled'))
            AND attempt.closed_at < now() - interval '2 minutes'
            AND (EXISTS (
              SELECT 1 FROM {{schema}}.session_attempt_interruptions interruption
              WHERE interruption.workspace_id = session.workspace_id AND interruption.session_id = session.id
                AND interruption.attempt_id = attempt.id AND interruption.state IN ('settled', 'rejected_stale'))
              OR EXISTS (
                SELECT 1 FROM {{schema}}.session_events event WHERE event.workspace_id = session.workspace_id
                  AND event.session_id = session.id AND event.turn_id = turn.id
                  AND event.turn_attempt_id = attempt.id AND event.type = 'turn.recovery.requested'))
            AND (wake.session_id IS NULL OR (wake.wake_revision = wake.delivered_revision
              AND wake.updated_at < now() - interval '10 minutes'))
            AND (p_after_workspace_id IS NULL OR
              (session.workspace_id, session.id) > (p_after_workspace_id, p_after_session_id))
        )
        SELECT candidate.candidate_account_id, candidate.candidate_workspace_id,
          candidate.candidate_session_id
        FROM candidate
        CROSS JOIN LATERAL (
          -- Each quiesced candidate walks only its own ancestry through the
          -- primary key. The bound and cycle guard match the canonical
          -- effective-control algebra (packages/db/src/session-control.ts)
          -- and 0633's backlog.
          WITH RECURSIVE ancestry AS (
            SELECT path_row.workspace_id AS ancestry_workspace_id,
              path_row.parent_session_id AS ancestry_parent_id,
              path_row.direct_control_state AS ancestry_direct_state,
              path_row.direct_pause_revision AS ancestry_pause_revision,
              path_row.subtree_run_override_revision AS ancestry_override_revision,
              0::integer AS ancestry_depth,
              ARRAY[path_row.id]::uuid[] AS ancestry_path,
              false AS ancestry_cycle
            FROM {{schema}}.sessions path_row
            WHERE candidate.quiesced AND path_row.workspace_id = candidate.candidate_workspace_id
              AND path_row.id = candidate.candidate_session_id
            UNION ALL
            SELECT parent.workspace_id, parent.parent_session_id,
              parent.direct_control_state, parent.direct_pause_revision,
              parent.subtree_run_override_revision, child.ancestry_depth + 1,
              child.ancestry_path || parent.id, parent.id = ANY(child.ancestry_path)
            FROM ancestry child
            JOIN {{schema}}.sessions parent ON parent.workspace_id = child.ancestry_workspace_id
              AND parent.id = child.ancestry_parent_id
            WHERE child.ancestry_parent_id IS NOT NULL AND NOT child.ancestry_cycle
              AND child.ancestry_depth < 10000
          )
          SELECT (
            -- A session pause is defeated only by a strictly newer override
            -- on a strictly deeper (descendant-side) path row.
            EXISTS (
              SELECT 1 FROM ancestry pause
              WHERE NOT pause.ancestry_cycle
                AND pause.ancestry_direct_state = 'paused'
                AND pause.ancestry_pause_revision IS NOT NULL
                AND NOT EXISTS (
                  SELECT 1 FROM ancestry override_row
                  WHERE override_row.ancestry_depth < pause.ancestry_depth
                    AND override_row.ancestry_override_revision > pause.ancestry_pause_revision))
            -- A workspace pause is defeated by any newer override on the path.
            OR candidate.quiesced AND EXISTS (
              SELECT 1 FROM {{schema}}.workspace_inference_controls control_row
              WHERE control_row.workspace_id = candidate.candidate_workspace_id
                AND control_row.workspace_state = 'paused'
                AND NOT EXISTS (
                  SELECT 1 FROM ancestry override_row
                  WHERE control_row.workspace_pause_revision IS NOT NULL
                    AND override_row.ancestry_override_revision > control_row.workspace_pause_revision))
          ) AS effectively_paused
        ) control
        WHERE NOT candidate.quiesced
          OR (control.effectively_paused AND candidate.projection_recovering)
          OR (NOT control.effectively_paused AND NOT candidate.admission_blocked
            AND NOT candidate.setup_blocked)
        ORDER BY candidate.candidate_workspace_id, candidate.candidate_session_id LIMIT p_limit;
    END $$;

CREATE FUNCTION opengeni_private.list_sandbox_ended_epoch_blockers(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, lease_id uuid, sandbox_group_id uuid, lease_epoch bigint, provider_backend text, provider_instance_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'ended_epoch');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_claim_ended_blockers_inner($1);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.list_sandbox_ended_epoch_setup_uncertainties(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, turn_id uuid, attempt_id uuid, lease_id uuid, sandbox_group_id uuid, lease_epoch bigint, provider_backend text, provider_instance_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'ended_epoch');
        RETURN QUERY SELECT * FROM opengeni_private.maintenance_claim_ended_setup_inner($1);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.list_sandbox_file_publications(p_account uuid, p_workspace uuid, p_query jsonb) RETURNS TABLE(file_id uuid, title text, kind text, source_session_id uuid, published_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_limit integer := (p_query->>'limit')::integer;
  v_sort text := p_query->>'sort';
  v_after text := p_query#>>'{after,key}';
BEGIN
  IF p_account IS NULL OR p_workspace IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR v_limit IS NULL OR v_limit NOT BETWEEN 1 AND 201
    OR v_sort IS NULL OR v_sort NOT IN ('updated','newest','title')
    OR jsonb_typeof(p_query) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_query->'kinds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_query->'kinds') NOT BETWEEN 1 AND 2
    OR length(coalesce(p_query->>'q',''))>200
  THEN RAISE EXCEPTION 'publication list scope mismatch' USING ERRCODE = '42501'; END IF;
  RETURN QUERY WITH candidates AS (
    SELECT p.file_id, f.filename AS title,
      CASE WHEN f.content_type IN ('image/png','image/jpeg','image/gif','image/webp','image/avif','image/svg+xml')
        THEN 'image' ELSE 'file' END AS kind,
      p.source_session_id, p.published_at,
      CASE WHEN v_sort='title' THEN lower(f.filename)
        ELSE to_char(p.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US') END AS sort_key
    FROM opengeni_private.sandbox_file_publications p JOIN files f
      ON f.account_id=p.account_id AND f.workspace_id=p.workspace_id AND f.id=p.file_id
    WHERE p.account_id=p_account AND p.workspace_id=p_workspace AND f.status='ready'
      AND (f.private_owner_subject_ids IS NULL OR nullif(current_setting('opengeni.private_file_owner',true),'')=ANY(f.private_owner_subject_ids))
      AND (p_query->>'sourceSessionId' IS NULL OR p.source_session_id=(p_query->>'sourceSessionId')::uuid)
      AND p.published_at<=(p_query->>'snapshotAt')::timestamptz
      AND strpos(lower(f.filename),lower(coalesce(p_query->>'q','')))>0
  ) SELECT c.file_id,c.title,c.kind,c.source_session_id,c.published_at FROM candidates c
    WHERE (p_query->'kinds') ? c.kind AND (v_after IS NULL OR
      (v_sort='title' AND c.sort_key COLLATE "C">v_after COLLATE "C") OR
      (v_sort<>'title' AND c.sort_key COLLATE "C"<v_after COLLATE "C") OR
      (c.sort_key=v_after AND (c.kind COLLATE "C",c.file_id::text COLLATE "C")>
        ((p_query#>>'{after,kind}') COLLATE "C",(p_query#>>'{after,id}') COLLATE "C")))
    ORDER BY CASE WHEN v_sort='title' THEN c.sort_key END COLLATE "C" ASC,
      CASE WHEN v_sort<>'title' THEN c.sort_key END COLLATE "C" DESC,c.kind COLLATE "C",c.file_id::text COLLATE "C"
    LIMIT v_limit;
END $$;

CREATE FUNCTION opengeni_private.list_sandbox_file_publications_pinned(p_account uuid, p_workspace uuid, p_query jsonb) RETURNS TABLE(file_id uuid, title text, kind text, source_session_id uuid, published_at timestamp with time zone, pinned boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_limit integer := (p_query->>'limit')::integer;
  v_sort text := p_query->>'sort';
  v_after text := p_query#>>'{after,key}';
  v_after_pinned boolean := coalesce((p_query#>>'{after,pinned}')::boolean,false);
BEGIN
  IF p_account IS NULL OR p_workspace IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR v_limit IS NULL OR v_limit NOT BETWEEN 1 AND 201
    OR v_sort IS NULL OR v_sort NOT IN ('updated','newest','title')
    OR jsonb_typeof(p_query) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_query->'kinds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_query->'kinds') NOT BETWEEN 1 AND 2
    OR length(coalesce(p_query->>'q',''))>200
  THEN RAISE EXCEPTION 'publication list scope mismatch' USING ERRCODE = '42501'; END IF;
  RETURN QUERY WITH candidates AS (
    SELECT p.file_id, f.filename AS title,
      CASE WHEN f.content_type IN ('image/png','image/jpeg','image/gif','image/webp','image/avif','image/svg+xml')
        THEN 'image' ELSE 'file' END AS kind,
      p.source_session_id, p.published_at,
      CASE WHEN v_sort='title' THEN lower(f.filename)
        ELSE to_char(p.published_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US') END AS sort_key
    FROM opengeni_private.sandbox_file_publications p JOIN files f
      ON f.account_id=p.account_id AND f.workspace_id=p.workspace_id AND f.id=p.file_id
    WHERE p.account_id=p_account AND p.workspace_id=p_workspace AND f.status='ready'
      AND (f.private_owner_subject_ids IS NULL OR nullif(current_setting('opengeni.private_file_owner',true),'')=ANY(f.private_owner_subject_ids))
      AND (p_query->>'sourceSessionId' IS NULL OR p.source_session_id=(p_query->>'sourceSessionId')::uuid)
      AND p.published_at<=(p_query->>'snapshotAt')::timestamptz
      AND strpos(lower(f.filename),lower(coalesce(p_query->>'q','')))>0
  ), ordered AS (
    SELECT c.*, (pins.artifact_id IS NOT NULL) AS pinned FROM candidates c
      LEFT JOIN opengeni_private.list_artifact_pins(p_account,p_workspace) pins
        ON pins.kind=c.kind AND pins.artifact_id=c.file_id::text
  ) SELECT c.file_id,c.title,c.kind,c.source_session_id,c.published_at,c.pinned FROM ordered c
    WHERE (p_query->'kinds') ? c.kind AND (v_after IS NULL OR c.pinned<v_after_pinned OR
      (c.pinned=v_after_pinned AND (
        (v_sort='title' AND c.sort_key COLLATE "C">v_after COLLATE "C") OR
        (v_sort<>'title' AND c.sort_key COLLATE "C"<v_after COLLATE "C") OR
        (c.sort_key=v_after AND (c.kind COLLATE "C",c.file_id::text COLLATE "C")>
          ((p_query#>>'{after,kind}') COLLATE "C",(p_query#>>'{after,id}') COLLATE "C")))))
    ORDER BY c.pinned DESC, CASE WHEN v_sort='title' THEN c.sort_key END COLLATE "C" ASC,
      CASE WHEN v_sort<>'title' THEN c.sort_key END COLLATE "C" DESC,c.kind COLLATE "C",c.file_id::text COLLATE "C"
    LIMIT v_limit;
END $$;

CREATE FUNCTION opengeni_private.list_sandbox_viewer_force_drain_workspaces() RETURNS TABLE(workspace_id uuid)
    LANGUAGE sql SECURITY DEFINER
    AS $$
  SELECT W.id
  FROM workspaces W
  WHERE W.sandbox_viewer_force_drain_reason IS NOT NULL
  ORDER BY W.id;
$$;

CREATE FUNCTION opengeni_private.list_scheduled_task_blocker_reviews(p_limit integer) RETURNS TABLE(id uuid, workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'Invalid schedule blocker inventory bound' USING ERRCODE = '22023';
      END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT task.id, task.workspace_id
        FROM {{schema}}.scheduled_tasks task
        LEFT JOIN {{schema}}.scheduled_task_blocker_reviews review
          ON review.task_id = task.id AND review.workspace_id = task.workspace_id
        LEFT JOIN LATERAL (
          SELECT run.id, run.status FROM {{schema}}.scheduled_task_runs run
          WHERE run.workspace_id = task.workspace_id AND run.task_id = task.id
            AND run.account_id = task.account_id
            AND run.trigger_type IN ('scheduled', 'event') AND run.action_kind = 'agent_turn'
          ORDER BY run.created_at DESC, run.id DESC LIMIT 1
        ) latest ON true
        WHERE review.notice_pending IS NOT NULL
          OR (task.deleted_at IS NOT NULL AND review.state IN ('notified', 'paused'))
          OR (task.deleted_at IS NULL AND review.state = 'paused' AND task.status = 'active')
          OR (task.deleted_at IS NULL AND review.state = 'notified' AND task.status <> 'active')
          OR (task.deleted_at IS NULL AND task.status = 'active'
            AND latest.status IN ('succeeded', 'failed', 'skipped')
            AND latest.id IS DISTINCT FROM review.reviewed_run_id
            AND (latest.status <> 'succeeded' OR review.state = 'notified'))
        ORDER BY task.updated_at, task.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.list_scheduled_task_schedule_reconciliations(p_limit integer) RETURNS TABLE(id uuid, task_id uuid, workspace_id uuid, temporal_schedule_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'Invalid schedule reconciliation inventory bound' USING ERRCODE = '22023';
      END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT pending.id, pending.task_id, pending.workspace_id, pending.temporal_schedule_id
        FROM {{schema}}.scheduled_task_schedule_outbox pending WHERE pending.next_attempt_at <= now()
        ORDER BY pending.next_attempt_at, pending.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.list_stale_compute_sandbox_enrollments(after_enrollment uuid) RETURNS TABLE(workspace_id uuid, enrollment_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE opened integer;
    BEGIN
      INSERT INTO opengeni_private.modal_inventory_read_capabilities
        (backend_pid, transaction_id, data_schema)
      VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), '{{schema}}')
      ON CONFLICT DO NOTHING;
      GET DIAGNOSTICS opened = ROW_COUNT;
      RETURN QUERY SELECT enrollment.workspace_id, enrollment.id
        FROM {{schema}}.enrollments enrollment
        WHERE enrollment.kind = 'sandbox' AND enrollment.status = 'active'
          AND enrollment.created_at < now() - interval '10 minutes'
          AND NOT EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_leases lease
            WHERE lease.workspace_id = enrollment.workspace_id
              AND lease.sandbox_group_id = enrollment.sandbox_group_id
              AND (lease.liveness = 'warming'
                OR (lease.backend = 'compute' AND lease.liveness IN ('warm', 'draining')
                  AND lease.instance_id IS NOT NULL
                  AND lease.resume_state #>> '{sessionState,providerState,enrollmentId}' IS NULL)
                OR lease.resume_state #>> '{sessionState,providerState,enrollmentId}'
                  = enrollment.id::text)
          )
          AND (after_enrollment IS NULL OR enrollment.id > after_enrollment)
        ORDER BY enrollment.id LIMIT 100;
      IF opened = 1 THEN
        DELETE FROM opengeni_private.modal_inventory_read_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.data_schema = '{{schema}}';
      END IF;
    END
    $$;

CREATE FUNCTION opengeni_private.list_stalled_recording_work_v1(p_limit integer) RETURNS TABLE(kind text, account_id uuid, workspace_id uuid, recording_id uuid, version_id uuid, owner_subject_id text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  (
    SELECT 'transcript', version.account_id, version.workspace_id, version.recording_id,
      version.id, recording.owner_subject_id
    FROM recording_transcript_versions version
    JOIN recordings recording
      ON recording.workspace_id = version.workspace_id AND recording.id = version.recording_id
    WHERE recording.state <> 'deleting'
      AND (
        (version.state = 'queued' AND version.created_at < pg_catalog.now() - interval '2 minutes')
        OR (version.state = 'processing'
          AND version.processing_started_at < pg_catalog.now() - interval '3 hours')
      )
    ORDER BY version.created_at, version.id
    LIMIT greatest(1, least(coalesce(p_limit, 50), 200))
  )
  UNION ALL
  (
    SELECT 'deletion', recording.account_id, recording.workspace_id, recording.id,
      NULL::uuid, recording.owner_subject_id
    FROM recordings recording
    WHERE recording.state = 'deleting'
      AND recording.updated_at < pg_catalog.now() - interval '2 minutes'
    ORDER BY recording.updated_at, recording.id
    LIMIT greatest(1, least(coalesce(p_limit, 50), 200))
  );
$$;

CREATE FUNCTION opengeni_private.list_subscription_plan_maintenance_accounts(p_limit integer) RETURNS TABLE(account_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid; sweep_time timestamptz := clock_timestamp();
    BEGIN
      IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'Invalid subscription plan maintenance bound' USING ERRCODE = '22023';
      END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY
        SELECT candidate.account_id FROM (
          (SELECT period.account_id FROM {{schema}}.plan_credit_periods period
            WHERE period.expired_at IS NULL AND period.period_end <= sweep_time
            ORDER BY period.period_end, period.account_id LIMIT p_limit)
          UNION
          (SELECT account.id AS account_id FROM {{schema}}.managed_accounts account
            LEFT JOIN {{schema}}.organization_plans state ON state.account_id = account.id
            CROSS JOIN LATERAL opengeni_private.subscription_plan_free_anniversary(account.created_at, greatest(account.created_at, sweep_time)) anniversary
            WHERE account.created_at <= sweep_time
              AND (state.account_id IS NULL
                OR (state.plan_key IN ('pro', 'max') AND state.status IN ('canceled', 'unpaid', 'incomplete_expired') AND state.current_period_end <= sweep_time)
                OR (state.plan_key = 'free' AND state.status IN ('active', 'trialing') AND state.stripe_subscription_id IS NULL
                  AND (opengeni_private.subscription_plan_definition('free')->>'freeCredit')::boolean
                  AND EXISTS (SELECT 1 FROM {{schema}}.credit_ledger_entries trial
                    WHERE trial.account_id = account.id AND trial.type = 'grant' AND trial.source_type = 'verified_signup_trial'
                      AND trial.idempotency_key = 'verified-signup-trial:v1:' || trial.source_id AND trial.amount_micros >= 0)
                  AND NOT EXISTS (SELECT 1 FROM {{schema}}.plan_credit_periods receipt
                    WHERE receipt.account_id = account.id
                      AND receipt.idempotency_key = 'plan-credit:free:' || account.id::text || ':' || to_char(anniversary.period_start AT TIME ZONE 'UTC', 'YYYY-MM'))))
              AND NOT EXISTS (SELECT 1 FROM {{schema}}.plan_credit_periods live
                WHERE live.account_id = account.id AND live.expired_at IS NULL AND live.period_end > sweep_time)
            ORDER BY account.id LIMIT p_limit)
        ) candidate ORDER BY candidate.account_id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.list_unobservable_command_drain_candidates(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, sandbox_group_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 100 THEN RAISE EXCEPTION 'invalid drain batch'; END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT lease.account_id, lease.workspace_id, lease.sandbox_group_id
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.backend = 'modal' AND lease.liveness IN ('warm', 'draining')
        AND (lease.unobservable_command_drain_ids IS NOT NULL OR EXISTS (
          SELECT 1 FROM {{schema}}.sandbox_retained_processes process
          WHERE process.lease_id = lease.id AND process.state = 'active'
            AND (
              process.last_reconcile_outcome IN (
                'process_observation_unavailable', 'quarantined_process_observation_unavailable',
                'provider_binding_missing', 'quarantined_provider_binding_missing',
                'provider_binding_mismatch', 'quarantined_provider_binding_mismatch'
              )
              OR (
                process.last_reconcile_outcome = 'provider_error'
                AND process.reconcile_attempts >= 5
                AND EXISTS (
                  SELECT 1 FROM {{schema}}.session_background_commands command
                  WHERE command.retained_process_id = process.id
                    AND command.workspace_id = process.workspace_id
                    AND command.session_id = process.session_id
                    AND command.provider = 'managed' AND command.state = 'stopping'
                    AND command.cancel_requested_at IS NOT NULL
                )
              )
              OR (
                lease.rotation_reason = 'provider_deadline'
                AND lease.rotation_requested_at IS NOT NULL
                AND process.deadline_cancellation_requested_at < now() - interval '2 minutes'
                AND process.reconcile_attempts >= 1
              )
            )
        ))
      ORDER BY
        CASE WHEN lease.rotation_reason = 'provider_deadline'
          AND lease.rotation_requested_at IS NOT NULL THEN 0 ELSE 1 END,
        CASE WHEN lease.rotation_reason = 'provider_deadline'
          AND lease.rotation_requested_at IS NOT NULL
          THEN lease.provider_deadline_at END NULLS LAST,
        lease.unobservable_command_checked_at NULLS FIRST,
        lease.id LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.locate_connected_command_completion(p_control_workspace_id uuid, p_enrollment_id uuid, p_connection_instance_id text, p_op_id text) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, command_id uuid, terminal boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY SELECT command.account_id, command.workspace_id, command.session_id, command.id,
        command.state IN ('exited', 'lost')
        FROM {{schema}}.session_background_commands command
        WHERE command.provider = 'connected_machine'
          AND command.control_workspace_id = p_control_workspace_id
          AND command.enrollment_id = p_enrollment_id
          AND command.connection_instance_id = p_connection_instance_id
          AND command.op_id = p_op_id;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.lock_nested_agent_workspace_policy_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  control_account_id uuid;
BEGIN
  IF OLD.settings -> 'maxNestedAgentDepth'
       IS NOT DISTINCT FROM NEW.settings -> 'maxNestedAgentDepth' THEN
    RETURN NEW;
  END IF;
  EXECUTE format('SELECT account_id FROM %I.workspace_inference_controls '
      'WHERE workspace_id = $1 FOR UPDATE', TG_TABLE_SCHEMA)
    INTO control_account_id USING NEW.id;
  IF control_account_id IS NULL THEN
    RAISE EXCEPTION 'workspace has no mandatory inference-control row' USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END
$_$;

CREATE FUNCTION opengeni_private.maintenance_claim_active(p_actor text, p_operation text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT p_actor = current_user AND EXISTS (
    SELECT 1 FROM opengeni_private.maintenance_claim_capabilities c
    WHERE c.backend_pid = pg_backend_pid()
      AND c.transaction_id = pg_current_xact_id_if_assigned()
      AND c.operation = p_operation
  )
$$;

CREATE FUNCTION opengeni_private.maintenance_claim_checkpoint_gc_inner(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint) RETURNS TABLE(id uuid, provider_backend text, provider_binding_key text, provider_binding jsonb, object_kind text, object_id text, delete_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    BEGIN
      IF p_claim_id IS NULL THEN
        RAISE EXCEPTION 'checkpoint artifact claim id is required'
          USING ERRCODE = '22023';
      END IF;
      IF p_limit IS NULL OR p_limit < 1 OR p_limit > 500 THEN
        RAISE EXCEPTION 'checkpoint artifact claim limit must be between 1 and 500'
          USING ERRCODE = '22023';
      END IF;
      IF p_claim_ttl_ms IS NULL
        OR p_claim_ttl_ms < 1000
        OR p_claim_ttl_ms > 3600000
      THEN
        RAISE EXCEPTION 'checkpoint artifact claim TTL must be between 1s and 1h'
          USING ERRCODE = '22023';
      END IF;

      PERFORM pg_catalog.set_config('opengeni.sandbox_recovery_protocol_v2', '1', true);

      WITH stale_claims AS MATERIALIZED (
        SELECT artifact.id
        FROM {{schema}}.sandbox_checkpoint_artifacts artifact
        WHERE artifact.state = 'deleting'
          AND artifact.delete_claimed_at
            < pg_catalog.now()
              - pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0)
        ORDER BY artifact.delete_claimed_at, artifact.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_limit
      )
      UPDATE {{schema}}.sandbox_checkpoint_artifacts artifact SET
        state = 'delete_failed',
        delete_after = pg_catalog.now(),
        delete_claim_id = null,
        delete_claimed_at = null,
        last_delete_error = coalesce(
          last_delete_error, 'stale delete claim recovered'
        ),
        updated_at = pg_catalog.now()
      FROM stale_claims
      WHERE artifact.id = stale_claims.id;

      RETURN QUERY
      WITH candidates AS (
        SELECT artifact.id
        FROM {{schema}}.sandbox_checkpoint_artifacts artifact
        WHERE (
            (
              artifact.state = 'candidate'
              AND artifact.created_at < pg_catalog.now() - interval '15 minutes'
            )
            OR (
              artifact.state IN ('current', 'previous')
              AND artifact.created_at < pg_catalog.now() - interval '15 minutes'
            )
            OR (
              artifact.state IN ('delete_pending', 'delete_failed')
              AND coalesce(artifact.delete_after, artifact.created_at)
                <= pg_catalog.now()
            )
          )
          AND NOT EXISTS (
            SELECT 1
            FROM (
              SELECT current_checkpoint_artifact_id AS id
              FROM {{schema}}.sandbox_leases WHERE current_checkpoint_artifact_id IS NOT NULL
              UNION
              SELECT previous_checkpoint_artifact_id AS id
              FROM {{schema}}.sandbox_leases WHERE previous_checkpoint_artifact_id IS NOT NULL
            ) referenced
            WHERE referenced.id = artifact.id
          )
          AND NOT EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_leases lease
            WHERE (
                 artifact.provenance = 'native_capture'
                 AND lease.id = artifact.source_lease_id
                 AND lease.lease_epoch = artifact.source_lease_epoch
                 AND lease.instance_id = artifact.source_instance_id
                 AND lease.backend = artifact.provider_backend
                 AND lease.archive_capture_id IS NOT NULL
                 AND lease.archive_capture_generation
                   = artifact.source_workspace_generation
               )
          )
          AND NOT EXISTS (
            SELECT 1
            FROM {{schema}}.rig_versions version
            CROSS JOIN LATERAL pg_catalog.jsonb_each(version.provider_images) provider_image
            WHERE provider_image.value ->> 'artifactId' = artifact.id::text
              AND provider_image.value ->> 'status' = 'ready'
          )
          AND NOT EXISTS (
            SELECT 1
            FROM {{schema}}.rig_changes change
            JOIN {{schema}}.rig_versions base
              ON base.id = change.base_version_id
             AND base.workspace_id = change.workspace_id
             AND base.active = true
            WHERE change.status IN ('verifying', 'proposed')
              AND change.verification #>> '{providerImage,artifactId}' = artifact.id::text
              AND change.verification #>> '{providerImage,status}' = 'ready'
          )
        ORDER BY coalesce(artifact.delete_after, artifact.created_at), artifact.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_limit
      )
      UPDATE {{schema}}.sandbox_checkpoint_artifacts artifact SET
        state = 'deleting',
        delete_attempts = artifact.delete_attempts + 1,
        delete_claim_id = p_claim_id,
        delete_claimed_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
      FROM candidates
      WHERE artifact.id = candidates.id
      RETURNING artifact.id, artifact.provider_backend, artifact.provider_binding_key,
        artifact.provider_binding, artifact.object_kind, artifact.object_id,
        artifact.delete_attempts;
    END;
    $$;

CREATE FUNCTION opengeni_private.maintenance_claim_checkpoint_prune_inner(p_retention_ms bigint, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE pruned integer;
    BEGIN
      IF p_retention_ms IS NULL
        OR p_retention_ms < 86400000
        OR p_retention_ms > 31536000000
      THEN
        RAISE EXCEPTION 'checkpoint tombstone retention must be between 1 and 365 days'
          USING ERRCODE = '22023';
      END IF;
      IF p_limit IS NULL OR p_limit < 1 OR p_limit > 1000 THEN
        RAISE EXCEPTION 'checkpoint tombstone prune limit must be between 1 and 1000'
          USING ERRCODE = '22023';
      END IF;

      PERFORM pg_catalog.set_config('opengeni.sandbox_recovery_protocol_v2', '1', true);
      WITH candidates AS MATERIALIZED (
        SELECT artifact.id
        FROM {{schema}}.sandbox_checkpoint_artifacts artifact
        WHERE artifact.state = 'deleted'
          AND artifact.deleted_at
            < pg_catalog.now()
              - pg_catalog.make_interval(secs => p_retention_ms / 1000.0)
          AND NOT EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_leases lease
            WHERE lease.current_checkpoint_artifact_id = artifact.id
               OR lease.previous_checkpoint_artifact_id = artifact.id
          )
        ORDER BY artifact.deleted_at, artifact.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_limit
      ),
      removed AS (
        DELETE FROM {{schema}}.sandbox_checkpoint_artifacts artifact
        USING candidates
        WHERE artifact.id = candidates.id
        RETURNING artifact.id
      )
      SELECT pg_catalog.count(*)::integer INTO pruned FROM removed;
      RETURN pruned;
    END;
    $$;

CREATE FUNCTION opengeni_private.maintenance_claim_checkpoint_settle_inner(p_id uuid, p_claim_id uuid, p_deleted boolean, p_error text, p_retry_after_ms bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE changed integer;
    BEGIN
      IF p_id IS NULL OR p_claim_id IS NULL THEN
        RAISE EXCEPTION 'checkpoint artifact and claim ids are required'
          USING ERRCODE = '22023';
      END IF;
      IF p_deleted IS NULL THEN
        RAISE EXCEPTION 'checkpoint artifact deletion outcome is required'
          USING ERRCODE = '22023';
      END IF;
      IF p_retry_after_ms IS NULL
        OR p_retry_after_ms < 0
        OR p_retry_after_ms > 86400000
      THEN
        RAISE EXCEPTION 'checkpoint artifact retry delay must be between 0 and 24h'
          USING ERRCODE = '22023';
      END IF;

      PERFORM pg_catalog.set_config('opengeni.sandbox_recovery_protocol_v2', '1', true);
      UPDATE {{schema}}.sandbox_checkpoint_artifacts SET
        state = CASE WHEN p_deleted THEN 'deleted' ELSE 'delete_failed' END,
        deleted_at = CASE WHEN p_deleted THEN pg_catalog.now() ELSE null END,
        delete_after = CASE
          WHEN p_deleted THEN null
          ELSE pg_catalog.now()
            + pg_catalog.make_interval(secs => greatest(1000, p_retry_after_ms) / 1000.0)
        END,
        delete_claim_id = null,
        delete_claimed_at = null,
        last_delete_error = CASE
          WHEN p_deleted THEN null
          ELSE pg_catalog.left(coalesce(p_error, 'unknown'), 4000)
        END,
        updated_at = pg_catalog.now()
      WHERE id = p_id
        AND state = 'deleting'
        AND delete_claim_id = p_claim_id;
      GET DIAGNOSTICS changed = ROW_COUNT;
      RETURN changed = 1;
    END;
    $$;

CREATE FUNCTION opengeni_private.maintenance_claim_ended_blockers_inner(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, lease_id uuid, sandbox_group_id uuid, lease_epoch bigint, provider_backend text, provider_instance_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 500 THEN RAISE EXCEPTION 'invalid ended-epoch batch'; END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY
      WITH blockers AS (
        SELECT DISTINCT admission.account_id, admission.workspace_id, admission.lease_id,
          admission.sandbox_group_id, admission.lease_epoch, admission.provider_backend,
          admission.provider_instance_id
        FROM {{schema}}.sandbox_workspace_mutation_admissions admission
        WHERE admission.settled_at IS NULL AND admission.route_kind = 'home'
          AND admission.provider_backend = 'modal'
      )
      SELECT blocker.account_id, blocker.workspace_id, blocker.lease_id,
        blocker.sandbox_group_id, blocker.lease_epoch::bigint, blocker.provider_backend,
        blocker.provider_instance_id
      FROM blockers blocker
      JOIN {{schema}}.sandbox_leases lease
        ON lease.id = blocker.lease_id
       AND lease.account_id = blocker.account_id
       AND lease.workspace_id = blocker.workspace_id
       AND lease.sandbox_group_id = blocker.sandbox_group_id
      WHERE blocker.provider_instance_id IS NOT NULL
        AND lease.backend = 'modal'
        AND lease.lease_epoch > blocker.lease_epoch
        AND lease.instance_id IS DISTINCT FROM blocker.provider_instance_id
        AND NOT EXISTS (
          SELECT 1 FROM {{schema}}.sandbox_retained_processes process
          WHERE process.lease_id = blocker.lease_id
            AND process.lease_epoch = blocker.lease_epoch
            AND process.provider_backend = blocker.provider_backend
            AND process.provider_instance_id = blocker.provider_instance_id
            AND process.state = 'active'
        )
      ORDER BY random()
      LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.maintenance_claim_ended_setup_inner(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, turn_id uuid, attempt_id uuid, lease_id uuid, sandbox_group_id uuid, lease_epoch bigint, provider_backend text, provider_instance_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      IF p_limit < 1 OR p_limit > 500 THEN
        RAISE EXCEPTION 'invalid ended-epoch setup batch';
      END IF;
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY
      WITH waiting AS (
        SELECT turn.account_id, turn.workspace_id, turn.session_id, turn.id AS turn_id,
          attempt.id AS attempt_id
        FROM {{schema}}.session_turns turn
        JOIN {{schema}}.sessions session
          ON session.workspace_id = turn.workspace_id
         AND session.id = turn.session_id
         AND session.active_turn_id = turn.id
        JOIN {{schema}}.session_turn_attempts attempt
          ON attempt.workspace_id = turn.workspace_id
         AND attempt.session_id = turn.session_id
         AND attempt.turn_id = turn.id
         AND attempt.id::text = turn.metadata #>> '{sandboxSetupOutcomeUnknown,attemptId}'
        WHERE turn.status = 'recovering'
          AND turn.metadata ? 'sandboxSetupOutcomeUnknown'
          AND turn.metadata -> 'sandboxSetupOutcomeUnknown' @> jsonb_build_object(
            'version', 1, 'turnId', turn.id::text,
            'reason', 'sandbox_command_start_outcome_unknown')
          AND NOT turn.metadata ? 'sandboxSetupRecoveryExhausted'
          AND turn.active_attempt_id IS NULL
          AND session.status = 'recovering'
          AND session.direct_control_state = 'active'
          AND attempt.state = 'closed'
          AND attempt.quiesced_at IS NOT NULL
          AND attempt.execution_generation = turn.execution_generation
          AND NOT EXISTS (
            SELECT 1 FROM {{schema}}.sandbox_retained_processes process
            WHERE process.workspace_id = turn.workspace_id
              AND process.session_id = turn.session_id
              AND process.owner_attempt_id = attempt.id
              AND process.state = 'active'
          )
      ), boxes AS (
        SELECT DISTINCT waiting.account_id, waiting.workspace_id, waiting.session_id,
          waiting.turn_id, waiting.attempt_id, admission.lease_id, admission.sandbox_group_id,
          admission.lease_epoch, admission.provider_backend, admission.provider_instance_id
        FROM waiting
        JOIN {{schema}}.sandbox_workspace_mutation_admissions admission
          ON admission.workspace_id = waiting.workspace_id
         AND admission.session_id = waiting.session_id
         AND admission.attempt_id = waiting.attempt_id
         AND admission.turn_id = waiting.turn_id
         AND admission.actor_kind = 'turn'
         AND admission.actor_id = waiting.attempt_id
         AND admission.operation IN ('lazyOwnedSandboxSetup', 'eagerOwnedSandboxSetup')
         AND admission.route_kind = 'home'
      ), single_box AS (
        SELECT box.* FROM boxes box
        WHERE NOT EXISTS (
          SELECT 1 FROM boxes other
          WHERE other.turn_id = box.turn_id
            AND (other.lease_id, other.lease_epoch, other.provider_backend,
                 other.provider_instance_id)
              IS DISTINCT FROM (box.lease_id, box.lease_epoch, box.provider_backend,
                 box.provider_instance_id)
        )
      )
      SELECT box.account_id, box.workspace_id, box.session_id, box.turn_id, box.attempt_id,
        box.lease_id, box.sandbox_group_id, box.lease_epoch::bigint, box.provider_backend,
        box.provider_instance_id
      FROM single_box box
      JOIN {{schema}}.sandbox_leases lease
        ON lease.id = box.lease_id
       AND lease.account_id = box.account_id
       AND lease.workspace_id = box.workspace_id
       AND lease.sandbox_group_id = box.sandbox_group_id
      WHERE box.provider_backend = 'modal'
        AND box.provider_instance_id IS NOT NULL
        AND lease.backend = 'modal'
        AND lease.lease_epoch > box.lease_epoch
        AND lease.instance_id IS DISTINCT FROM box.provider_instance_id
      ORDER BY random()
      LIMIT p_limit;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END $$;

CREATE FUNCTION opengeni_private.maintenance_claim_output_release_inner(p_claim_id uuid, p_limit integer, p_claim_ttl_ms bigint, p_due_before timestamp with time zone) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, command_id uuid, claim_id uuid, command_state text, control_workspace_id uuid, enrollment_id uuid, connection_instance_id text, op_id text, reconcile_attempts integer, reconcile_proof_outcome text, reconcile_proof_exit_code integer, reconcile_proof_reason text, reconcile_proof_observed_at timestamp with time zone, output_exit_seq text, output_attach_generation text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      inventory_id uuid;
      access_id uuid;
      workspace_ids uuid[];
      workspace_value uuid;
    BEGIN
      IF p_claim_id IS NULL OR p_due_before IS NULL THEN
        RAISE EXCEPTION 'connected-command output claim identity and due frontier are required'
          USING ERRCODE = '22023';
      END IF;
      IF p_limit IS NULL OR p_limit < 1 OR p_limit > 100 THEN
        RAISE EXCEPTION 'connected-command reconciliation limit must be between 1 and 100'
          USING ERRCODE = '22023';
      END IF;
      IF p_claim_ttl_ms IS NULL OR p_claim_ttl_ms < 0 OR p_claim_ttl_ms > 3600000 THEN
        RAISE EXCEPTION 'connected-command reconciliation claim TTL is invalid'
          USING ERRCODE = '22023';
      END IF;

      inventory_id := opengeni_private.open_session_tenancy_fence_inventory({{schema}}.session_tenancy_fence_target_schema());
      SELECT array_agg(DISTINCT command.workspace_id ORDER BY command.workspace_id) INTO workspace_ids
      FROM {{schema}}.session_background_commands command
      WHERE command.provider = 'connected_machine' AND command.state = 'exited'
        AND command.output_release_observed_at IS NULL AND command.output_unavailable_at IS NULL
        AND command.reconcile_after <= LEAST(p_due_before, pg_catalog.now())
        AND opengeni_private.connected_output_runner_eligible_v1(
          command.control_workspace_id, command.enrollment_id, command.connection_instance_id);
      FOREACH workspace_value IN ARRAY COALESCE(workspace_ids, ARRAY[]::uuid[]) LOOP
        PERFORM {{schema}}.acquire_session_tenancy_fence(workspace_value);
      END LOOP;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      access_id := opengeni_private.open_session_tenancy_fenced_access({{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY
      WITH candidates AS MATERIALIZED (
        SELECT command.id, command.reconcile_after, command.started_at,
          command.output_consumed_at IS NULL AS output_uncaptured
        FROM {{schema}}.session_background_commands command
        WHERE command.provider = 'connected_machine'
          AND command.workspace_id = ANY(workspace_ids)
          AND command.state = 'exited'
          AND command.output_release_observed_at IS NULL AND command.output_unavailable_at IS NULL
          AND command.reconcile_after <= LEAST(p_due_before, pg_catalog.now())
          AND opengeni_private.connected_output_runner_eligible_v1(
            command.control_workspace_id, command.enrollment_id, command.connection_instance_id)
          AND (command.reconcile_claim_id IS NULL
            OR command.reconcile_claimed_at <= pg_catalog.now()
              - pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0))
        ORDER BY command.output_consumed_at IS NULL,
          command.reconcile_after, command.started_at, command.id
        FOR UPDATE OF command SKIP LOCKED
        LIMIT p_limit
      ), claimed AS (
        UPDATE {{schema}}.session_background_commands command SET
          reconcile_after = pg_catalog.now() + pg_catalog.make_interval(secs => p_claim_ttl_ms / 1000.0),
          reconcile_claim_id = p_claim_id, reconcile_claimed_at = pg_catalog.now(),
          reconcile_attempts = command.reconcile_attempts + 1,
          last_reconcile_outcome = 'claimed', updated_at = pg_catalog.clock_timestamp()
        FROM candidates WHERE command.id = candidates.id
          AND command.provider = 'connected_machine' AND command.state = 'exited'
          AND command.output_release_observed_at IS NULL AND command.output_unavailable_at IS NULL
        RETURNING command.*, candidates.reconcile_after AS due_at,
          candidates.started_at AS candidate_started_at, candidates.output_uncaptured
      )
      SELECT claimed.account_id, claimed.workspace_id, claimed.session_id, claimed.id,
        claimed.reconcile_claim_id, claimed.state, claimed.control_workspace_id,
        claimed.enrollment_id, claimed.connection_instance_id, claimed.op_id,
        claimed.reconcile_attempts, claimed.reconcile_proof_outcome,
        claimed.reconcile_proof_exit_code, claimed.reconcile_proof_reason,
        claimed.reconcile_proof_observed_at, claimed.output_exit_seq,
        claimed.output_attach_generation
      FROM claimed ORDER BY claimed.output_uncaptured, claimed.due_at,
        claimed.candidate_started_at, claimed.id;
      PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fenced_access(access_id);
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END;
    $$;

CREATE FUNCTION opengeni_private.maintenance_claim_site_auth_inner(p_claim_timeout_ms bigint, p_limit integer) RETURNS TABLE(operation_id uuid, session_id uuid, account_id uuid, workspace_id uuid, site_auth_connection_id uuid, connection_version bigint, action text, due_at timestamp with time zone, claimed_at timestamp with time zone, name text, account_label text, login_url text, verification_url_prefixes jsonb, preferred_identity_id uuid, preferred_placement jsonb, preferred_network_route_id uuid, health_policy jsonb, verification_state text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
      WITH candidates AS MATERIALIZED (
        SELECT
          C.id,
          C.maintenance_operation_id,
          C.maintenance_session_id,
          C.maintenance_started_at,
          S.status AS session_status
        FROM {{schema}}.site_auth_connections C
        LEFT JOIN {{schema}}.sessions S
          ON S.workspace_id = C.workspace_id
          AND S.id = C.maintenance_session_id
        WHERE C.status = 'active'
          AND C.health_policy->>'mode' = 'maintained'
          AND C.next_check_at <= clock_timestamp()
          AND (
            C.maintenance_operation_id IS NULL
            OR (
              C.maintenance_started_at IS NULL
              AND C.maintenance_claimed_at <= clock_timestamp() - (
                greatest(coalesce(p_claim_timeout_ms, 0), 0)::double precision * interval '1 millisecond'
              )
            )
            OR (
              C.maintenance_started_at IS NOT NULL
              AND S.status = 'queued'
              AND NOT EXISTS (
                SELECT 1
                FROM {{schema}}.auth_runs R
                WHERE R.workspace_id = C.workspace_id
                  AND R.maintenance_operation_id = C.maintenance_operation_id
                  AND R.settled_at IS NULL
              )
              AND C.maintenance_claimed_at <= clock_timestamp() - (
                greatest(coalesce(p_claim_timeout_ms, 0), 0)::double precision * interval '1 millisecond'
              )
            )
            OR (
              C.maintenance_started_at IS NOT NULL
              AND (S.id IS NULL OR S.status IN ('idle', 'failed', 'cancelled'))
              AND NOT EXISTS (
                SELECT 1
                FROM {{schema}}.auth_runs R
                WHERE R.workspace_id = C.workspace_id
                  AND R.maintenance_operation_id = C.maintenance_operation_id
                  AND R.settled_at IS NULL
              )
              AND C.maintenance_claimed_at <= clock_timestamp() - (
                greatest(coalesce(p_claim_timeout_ms, 0), 0)::double precision * interval '1 millisecond'
              )
            )
          )
        ORDER BY C.next_check_at, C.id
        LIMIT least(greatest(coalesce(p_limit, 0), 0), 1000)
        FOR UPDATE OF C SKIP LOCKED
      ), prepared AS (
        SELECT
          X.id,
          CASE
            WHEN X.maintenance_operation_id IS NOT NULL
              AND (
                X.maintenance_started_at IS NULL
                OR X.session_status = 'queued'
              )
              THEN X.maintenance_operation_id
            ELSE gen_random_uuid()
          END AS operation_id,
          CASE
            WHEN X.maintenance_session_id IS NOT NULL
              AND (
                X.maintenance_started_at IS NULL
                OR X.session_status = 'queued'
              )
              THEN X.maintenance_session_id
            ELSE gen_random_uuid()
          END AS session_id
        FROM candidates X
      ), claimed AS (
        UPDATE {{schema}}.site_auth_connections C
        SET
          maintenance_operation_id = P.operation_id,
          maintenance_action = CASE
            WHEN C.verification_state IN ('needs_repair', 'failed')
              AND (C.health_policy->>'automaticRepair')::boolean
              THEN 'repair'
            ELSE 'health_check'
          END,
          maintenance_due_at = C.next_check_at,
          maintenance_claimed_at = clock_timestamp(),
          maintenance_session_id = P.session_id,
          maintenance_started_at = NULL,
          version = C.version + 1,
          updated_by_subject_id = 'site-auth-maintenance',
          updated_at = clock_timestamp()
        FROM prepared P
        WHERE C.id = P.id
        RETURNING C.*
      ), revisions AS (
        INSERT INTO {{schema}}.workspace_interaction_revisions (
          workspace_id, account_id, revision, updated_at
        )
        SELECT DISTINCT C.workspace_id, C.account_id, 1, clock_timestamp()
        FROM claimed C
        ON CONFLICT (workspace_id) DO UPDATE
        SET revision = {{schema}}.workspace_interaction_revisions.revision + 1,
          updated_at = excluded.updated_at
        RETURNING workspace_id
      )
      SELECT
        C.maintenance_operation_id,
        C.maintenance_session_id,
        C.account_id,
        C.workspace_id,
        C.id,
        C.version,
        C.maintenance_action,
        C.maintenance_due_at,
        C.maintenance_claimed_at,
        C.name,
        C.account_label,
        C.login_url,
        C.verification_url_prefixes,
        C.preferred_identity_id,
        C.preferred_placement,
        C.preferred_network_route_id,
        C.health_policy,
        C.verification_state
      FROM claimed C;
    $$;

CREATE FUNCTION opengeni_private.maintenance_claim_snapshots_inner(p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE deleted_count integer;
    BEGIN
      WITH victims AS (
        SELECT s.id
        FROM {{schema}}.session_list_snapshots s
        WHERE s.expires_at < now()
        ORDER BY s.expires_at, s.id
        FOR UPDATE SKIP LOCKED
        LIMIT greatest(1, least(coalesce(p_limit, 500), 5000))
      ), deleted AS (
        DELETE FROM {{schema}}.session_list_snapshots s
        USING victims
        WHERE s.id = victims.id
        RETURNING s.id
      )
      SELECT count(*)::integer INTO deleted_count FROM deleted;
      RETURN deleted_count;
    END $$;

CREATE FUNCTION opengeni_private.maintenance_claim_titles_inner(p_limit integer) RETURNS TABLE(outbox_id uuid, account_id uuid, workspace_id uuid, session_id uuid, event_id uuid, sequence integer, type text, payload jsonb, payload_codec_version integer, occurred_at timestamp with time zone, client_event_id text, turn_id uuid, turn_generation integer, turn_attempt_id uuid, turn_association text, duplicate_of_event_id uuid, duplicate_reason text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  WITH candidates AS MATERIALIZED (
    SELECT pending.id
    FROM opengeni_private.automatic_session_title_fanout_outbox_v1 pending
    WHERE pending.delivered_at IS NULL
    ORDER BY pending.created_at, pending.id
    FOR UPDATE SKIP LOCKED
    LIMIT greatest(1, least(coalesce(p_limit, 100), 1000))
  ),
  claimed AS (
    UPDATE opengeni_private.automatic_session_title_fanout_outbox_v1 pending
    SET attempts = pending.attempts + 1,
        updated_at = pg_catalog.clock_timestamp()
    FROM candidates
    WHERE pending.id = candidates.id
      AND pending.delivered_at IS NULL
    RETURNING pending.id, pending.event_id
  )
  SELECT
    claimed.id,
    event.account_id,
    event.workspace_id,
    event.session_id,
    event.id,
    event.sequence,
    event.type,
    event.payload,
    event.payload_codec_version,
    event.occurred_at,
    event.client_event_id,
    event.turn_id,
    event.turn_generation,
    event.turn_attempt_id,
    event.turn_association,
    event.duplicate_of_event_id,
    event.duplicate_reason
  FROM claimed
  JOIN session_events event ON event.id = claimed.event_id
  ORDER BY event.workspace_id, event.session_id, event.sequence;
$$;

CREATE FUNCTION opengeni_private.maintenance_claim_updates_inner(p_limit integer) RETURNS TABLE(id uuid, account_id uuid, workspace_id uuid, source_session_id uuid, target_session_id uuid, dedupe_key text, kind text, classification text, source_id text, summary text, summary_codec_version integer, payload jsonb, payload_codec_version integer, lineage jsonb, mcp_account_bindings jsonb, personal_connection_delegations jsonb, codex_provider_account_authority_snapshot jsonb, xai_provider_account_authority_snapshot jsonb, claude_provider_account_authority_snapshot jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
    WITH claimed AS (
      SELECT o.id, o.created_at FROM session_system_update_outbox o
      WHERE o.status = 'pending'
      ORDER BY o.created_at, o.id
      FOR UPDATE SKIP LOCKED
      LIMIT greatest(1, least(coalesce(p_limit, 100), 100))
    ), bumped AS (
      UPDATE session_system_update_outbox o
      SET attempts = o.attempts + 1, updated_at = now()
      FROM claimed c WHERE o.id = c.id
      RETURNING o.id, o.account_id, o.workspace_id, o.source_session_id, o.target_session_id, o.dedupe_key, o.kind, o.classification, o.source_id, o.summary, o.summary_codec_version, o.payload, o.payload_codec_version, o.lineage, o.mcp_account_bindings, o.personal_connection_delegations, o.codex_provider_account_authority_snapshot, o.xai_provider_account_authority_snapshot, o.claude_provider_account_authority_snapshot
    )
    SELECT b.* FROM bumped b
    JOIN claimed c ON c.id = b.id
    ORDER BY c.created_at, c.id;
END
$$;

CREATE FUNCTION opengeni_private.maintenance_claim_wakes_inner(p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, temporal_workflow_id text, wake_revision bigint, interruption_requested boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      candidate record;
      claimed_ids uuid[] := ARRAY[]::uuid[];
      claim_limit integer := greatest(1, least(coalesce(p_limit, 100), 1000));
    BEGIN
      -- This is an UNLOCKED preview, not a lease. Traverse the explicit due
      -- ledger in workspace/session UUID order, matching multi-session writers.
      -- Do not LIMIT the preview: busy earlier candidates must not hide later
      -- free wakes. Only actual lockable leases count against p_limit.
      FOR candidate IN
        SELECT o.account_id, o.workspace_id, o.session_id
        FROM {{schema}}.session_workflow_wake_outbox o
        WHERE o.wake_revision > o.delivered_revision AND o.next_attempt_at <= now()
        ORDER BY o.workspace_id, o.session_id
      LOOP
        -- Nonblocking admission fences precede all rows, as in withRlsContext
        -- and lockSessionEventWriteRows. Never queue while retaining other
        -- tenants' row locks. A later dispatcher pass retries skipped work.
        IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(
          'session-tenancy:' || candidate.workspace_id::text, 0
        )) THEN CONTINUE; END IF;
        IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(
          'workspace-control:' || candidate.workspace_id::text, 0
        )) THEN CONTINUE; END IF;

        PERFORM 1 FROM {{schema}}.workspace_inference_controls control
        WHERE control.workspace_id = candidate.workspace_id
          AND control.account_id = candidate.account_id
        FOR SHARE SKIP LOCKED;
        IF NOT FOUND THEN CONTINUE; END IF;

        PERFORM 1 FROM {{schema}}.workspaces workspace
        WHERE workspace.id = candidate.workspace_id
          AND workspace.account_id = candidate.account_id
        FOR KEY SHARE SKIP LOCKED;
        IF NOT FOUND THEN CONTINUE; END IF;

        PERFORM 1 FROM {{schema}}.sessions session
        WHERE session.id = candidate.session_id
          AND session.workspace_id = candidate.workspace_id
          AND session.account_id = candidate.account_id
        FOR NO KEY UPDATE SKIP LOCKED;
        IF NOT FOUND THEN CONTINUE; END IF;

        -- Recheck eligibility after the session prefix. Lock the CURRENT row,
        -- never the revision/timestamp observed by the unlocked preview.
        PERFORM 1 FROM {{schema}}.session_workflow_wake_outbox o
        WHERE o.session_id = candidate.session_id
          AND o.workspace_id = candidate.workspace_id
          AND o.account_id = candidate.account_id
          AND o.wake_revision > o.delivered_revision AND o.next_attempt_at <= now()
        FOR UPDATE SKIP LOCKED;
        IF NOT FOUND THEN CONTINUE; END IF;
        claimed_ids := array_append(claimed_ids, candidate.session_id);
        EXIT WHEN cardinality(claimed_ids) >= claim_limit;
      END LOOP;

      -- Every selected session is already held before ANY wake mutation.
      -- 0560's guard/FK checks now reacquire only locks this transaction owns.
      RETURN QUERY
        UPDATE {{schema}}.session_workflow_wake_outbox o
        SET attempts = o.attempts + 1,
            next_attempt_at = now() + make_interval(
              secs => least(300, greatest(1, power(2, least(o.attempts, 8))::integer))
            ),
            updated_at = now()
        WHERE o.session_id = ANY(claimed_ids)
          AND o.wake_revision > o.delivered_revision AND o.next_attempt_at <= now()
        RETURNING o.account_id, o.workspace_id, o.session_id,
          o.temporal_workflow_id, o.wake_revision,
          o.control_revision > o.delivered_revision
          OR EXISTS (
            SELECT 1 FROM {{schema}}.session_attempt_interruptions interruption
            JOIN {{schema}}.session_turn_attempts attempt
              ON attempt.workspace_id = interruption.workspace_id
             AND attempt.session_id = interruption.session_id
             AND attempt.id = interruption.attempt_id
            WHERE interruption.workspace_id = o.workspace_id
              AND interruption.session_id = o.session_id
              AND (
                interruption.state IN ('pending', 'delivered', 'acknowledged')
                OR (
                  interruption.state IN ('settled', 'rejected_stale')
                  AND attempt.quiesced_at IS NULL
                )
              )
          ) AS interruption_requested;
    END $$;

CREATE FUNCTION opengeni_private.maintenance_inventory_draining_inner() RETURNS TABLE(backend text, age_bucket text, count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
      SELECT lease.backend,
        CASE
          WHEN pg_catalog.now() - lease.expires_at < interval '5 minutes' THEN 'lt_5m'
          WHEN pg_catalog.now() - lease.expires_at < interval '1 hour' THEN '5m_1h'
          WHEN pg_catalog.now() - lease.expires_at < interval '1 day' THEN '1h_1d'
          ELSE 'gte_1d'
        END AS age_bucket,
        pg_catalog.count(*)::bigint
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.liveness = 'draining'
        AND lease.expires_at < pg_catalog.now()
      GROUP BY lease.backend, age_bucket;
    $$;

CREATE FUNCTION opengeni_private.maintenance_inventory_retained_inner() RETURNS TABLE(owner_state text, active_count bigint, terminal_owner_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
      SELECT inventory.owner_state,
        pg_catalog.count(*)::bigint AS active_count,
        pg_catalog.count(*) FILTER (WHERE inventory.terminal_owner)::bigint
          AS terminal_owner_count
      FROM (
        SELECT CASE
            WHEN command.state = 'stopping' THEN 'background_stopping'
            WHEN command.state = 'running' THEN 'background_running'
            WHEN process.owner_actor_kind = 'direct' THEN 'direct'
            ELSE COALESCE(turn_row.status, 'missing')
          END AS owner_state,
          CASE
            WHEN command.state = 'stopping' THEN true
            WHEN command.state = 'running' THEN false
            WHEN process.owner_actor_kind = 'direct' THEN NOT EXISTS (
              SELECT 1
              FROM {{schema}}.sandbox_workspace_mutation_admissions admission
              JOIN {{schema}}.sandbox_lease_holders holder
                ON holder.lease_id = admission.lease_id
               AND holder.account_id = admission.account_id
               AND holder.workspace_id = admission.workspace_id
               AND holder.kind = 'direct'
               AND holder.holder_id = admission.holder_id
               AND holder.subject_id = admission.session_id
              WHERE admission.id = process.parent_admission_id
                AND admission.actor_kind = 'direct'
            )
            ELSE attempt.state = 'closed'
          END AS terminal_owner
        FROM {{schema}}.sandbox_retained_processes process
        LEFT JOIN {{schema}}.session_background_commands command
          ON command.retained_process_id = process.id
         AND command.state IN ('running', 'stopping')
        LEFT JOIN LATERAL (
          SELECT source_turn.status
          FROM {{schema}}.session_turns source_turn
          WHERE source_turn.workspace_id = process.workspace_id
            AND source_turn.id = process.owner_turn_id
          LIMIT 1
        ) turn_row ON true
        LEFT JOIN LATERAL (
          SELECT source_attempt.state
          FROM {{schema}}.session_turn_attempts source_attempt
          WHERE source_attempt.workspace_id = process.workspace_id
            AND source_attempt.id = process.owner_attempt_id
          LIMIT 1
        ) attempt ON true
        WHERE process.state = 'active'
          AND process.owner_actor_kind IN ('direct', 'turn')
      ) inventory
      GROUP BY inventory.owner_state;
    $$;

CREATE FUNCTION opengeni_private.maintenance_probe_browser_sessions_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      BEGIN
        IF TG_OP = 'TRUNCATE' THEN
          TRUNCATE opengeni_private.maintenance_probe_browser_sessions;
          RETURN NULL;
        END IF;
        IF TG_OP = 'UPDATE' AND ROW(NEW.id, NEW.account_id, NEW.workspace_id, NEW.controller_host_sandbox_group_id, NEW.placement_instance_id, NEW.placement_kind, NEW.controller_generation, NEW.controller_id, jsonb_build_object('privateCheckpoint', NEW.capabilities->'privateCheckpoint'), NEW.lifecycle) IS NOT DISTINCT FROM ROW(OLD.id, OLD.account_id, OLD.workspace_id, OLD.controller_host_sandbox_group_id, OLD.placement_instance_id, OLD.placement_kind, OLD.controller_generation, OLD.controller_id, jsonb_build_object('privateCheckpoint', OLD.capabilities->'privateCheckpoint'), OLD.lifecycle) THEN
          RETURN NULL;
        END IF;
        IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.id IS DISTINCT FROM NEW.id) THEN
          DELETE FROM opengeni_private.maintenance_probe_browser_sessions WHERE id = OLD.id;
        END IF;
        IF TG_OP <> 'DELETE' THEN
          INSERT INTO opengeni_private.maintenance_probe_browser_sessions (id, account_id, workspace_id, controller_host_sandbox_group_id, placement_instance_id, placement_kind, controller_generation, controller_id, capabilities, lifecycle) VALUES (NEW.id, NEW.account_id, NEW.workspace_id, NEW.controller_host_sandbox_group_id, NEW.placement_instance_id, NEW.placement_kind, NEW.controller_generation, NEW.controller_id, jsonb_build_object('privateCheckpoint', NEW.capabilities->'privateCheckpoint'), NEW.lifecycle)
          ON CONFLICT (id) DO UPDATE SET (id, account_id, workspace_id, controller_host_sandbox_group_id, placement_instance_id, placement_kind, controller_generation, controller_id, capabilities, lifecycle) = (EXCLUDED.id, EXCLUDED.account_id, EXCLUDED.workspace_id, EXCLUDED.controller_host_sandbox_group_id, EXCLUDED.placement_instance_id, EXCLUDED.placement_kind, EXCLUDED.controller_generation, EXCLUDED.controller_id, EXCLUDED.capabilities, EXCLUDED.lifecycle);
        END IF;
        RETURN NULL;
      END $$;

