    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      BEGIN
        IF TG_OP = 'TRUNCATE' THEN
          TRUNCATE opengeni_private.maintenance_probe_sandbox_workspace_mutation_admissions;
          RETURN NULL;
        END IF;
        IF TG_OP = 'UPDATE' AND ROW(NEW.id, NEW.settled_at, NEW.route_kind, NEW.provider_backend) IS NOT DISTINCT FROM ROW(OLD.id, OLD.settled_at, OLD.route_kind, OLD.provider_backend) THEN
          RETURN NULL;
        END IF;
        IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.id IS DISTINCT FROM NEW.id) THEN
          DELETE FROM opengeni_private.maintenance_probe_sandbox_workspace_mutation_admissions WHERE id = OLD.id;
        END IF;
        IF TG_OP <> 'DELETE' THEN
          INSERT INTO opengeni_private.maintenance_probe_sandbox_workspace_mutation_admissions (id, settled_at, route_kind, provider_backend) VALUES (NEW.id, NEW.settled_at, NEW.route_kind, NEW.provider_backend)
          ON CONFLICT (id) DO UPDATE SET (id, settled_at, route_kind, provider_backend) = (EXCLUDED.id, EXCLUDED.settled_at, EXCLUDED.route_kind, EXCLUDED.provider_backend);
        END IF;
        RETURN NULL;
      END $$;

