          ON CONFLICT (id) DO UPDATE SET (id, state, reconcile_after, provider, output_release_observed_at, output_unavailable_at, control_workspace_id, enrollment_id, connection_instance_id, completion_notified_at, reconcile_proof_outcome, last_reconcile_outcome) = (EXCLUDED.id, EXCLUDED.state, EXCLUDED.reconcile_after, EXCLUDED.provider, EXCLUDED.output_release_observed_at, EXCLUDED.output_unavailable_at, EXCLUDED.control_workspace_id, EXCLUDED.enrollment_id, EXCLUDED.connection_instance_id, EXCLUDED.completion_notified_at, EXCLUDED.reconcile_proof_outcome, EXCLUDED.last_reconcile_outcome);
        END IF;
