CREATE FUNCTION opengeni_private.maintenance_schedule_cleanup_claim_inner(p_claim_id uuid, p_limit integer, p_claim_seconds integer) RETURNS TABLE(id uuid, account_id uuid, workspace_id uuid, temporal_schedule_id text, scheduled_task_id uuid, connector_cleanup_subject_id text, connector_cleanup_snapshot jsonb, connector_cleanup_completed_at timestamp with time zone, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    BEGIN
      IF p_claim_id IS NULL THEN
        RAISE EXCEPTION 'temporal schedule cleanup claim id is required'
          USING ERRCODE = '22023';
      END IF;

      RETURN QUERY
        WITH due AS (
          SELECT cleanup.id
          FROM {{schema}}.temporal_schedule_cleanup_outbox cleanup
          WHERE cleanup.next_attempt_at <= pg_catalog.now()
            AND (cleanup.claim_until IS NULL OR cleanup.claim_until <= pg_catalog.now())
          ORDER BY cleanup.next_attempt_at, cleanup.created_at, cleanup.id
          FOR UPDATE SKIP LOCKED
          LIMIT greatest(1, least(coalesce(p_limit, 32), 100))
        )
        UPDATE {{schema}}.temporal_schedule_cleanup_outbox cleanup
        SET claim_id = p_claim_id,
            claim_until = pg_catalog.now() + pg_catalog.make_interval(
              secs => greatest(5, least(coalesce(p_claim_seconds, 15), 300))
            ),
            attempt_count = cleanup.attempt_count + 1,
            updated_at = pg_catalog.now()
        FROM due
        WHERE cleanup.id = due.id
        RETURNING cleanup.id, cleanup.account_id, cleanup.workspace_id,
          cleanup.temporal_schedule_id, cleanup.scheduled_task_id,
          cleanup.connector_cleanup_subject_id, cleanup.connector_cleanup_snapshot,
          cleanup.connector_cleanup_completed_at, cleanup.attempt_count;
    END $$;

CREATE FUNCTION opengeni_private.maintenance_schedule_cleanup_connector_inner(p_id uuid, p_claim_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE completed_rows bigint := 0;
    BEGIN
      IF p_id IS NULL OR p_claim_id IS NULL THEN
        RAISE EXCEPTION 'temporal connector cleanup id and claim id are required'
          USING ERRCODE = '22023';
      END IF;
      UPDATE {{schema}}.temporal_schedule_cleanup_outbox cleanup
      SET connector_cleanup_completed_at = COALESCE(
            cleanup.connector_cleanup_completed_at,
            pg_catalog.clock_timestamp()
          ),
          updated_at = pg_catalog.clock_timestamp()
      WHERE cleanup.id = p_id
        AND cleanup.claim_id = p_claim_id
        AND cleanup.connector_cleanup_snapshot IS NOT NULL;
      GET DIAGNOSTICS completed_rows = ROW_COUNT;
      RETURN completed_rows = 1;
    END
    $$;

CREATE FUNCTION opengeni_private.maintenance_schedule_cleanup_settle_inner(p_id uuid, p_claim_id uuid, p_error text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE settled_rows bigint := 0;
    BEGIN
      IF p_id IS NULL OR p_claim_id IS NULL THEN
        RAISE EXCEPTION 'temporal schedule cleanup id and claim id are required'
          USING ERRCODE = '22023';
      END IF;

      IF p_error IS NULL THEN
        DELETE FROM {{schema}}.temporal_schedule_cleanup_outbox cleanup
        WHERE cleanup.id = p_id AND cleanup.claim_id = p_claim_id;
        GET DIAGNOSTICS settled_rows = ROW_COUNT;
        RETURN settled_rows = 1;
      END IF;

      UPDATE {{schema}}.temporal_schedule_cleanup_outbox cleanup
      SET claim_id = NULL,
          claim_until = NULL,
          next_attempt_at = pg_catalog.now() + pg_catalog.make_interval(
            secs => least(
              300,
              greatest(
                1,
                pg_catalog.power(2, least(cleanup.attempt_count - 1, 8))::integer
              )
            )
          ),
          last_error = pg_catalog.left(p_error, 2000),
          updated_at = pg_catalog.now()
      WHERE cleanup.id = p_id AND cleanup.claim_id = p_claim_id;
      GET DIAGNOSTICS settled_rows = ROW_COUNT;
      RETURN settled_rows = 1;
    END $$;

CREATE FUNCTION opengeni_private.maintenance_title_event_visible(p_actor text, p_event_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT opengeni_private.maintenance_claim_active(p_actor,'titles') AND EXISTS (
    SELECT 1 FROM opengeni_private.automatic_session_title_fanout_outbox_v1 p
    WHERE p.event_id=p_event_id AND p.delivered_at IS NULL
  )
$$;

CREATE FUNCTION opengeni_private.maintenance_workspace_commands_prepare_inner(p_account_id uuid, p_workspace_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      active_count integer := 0;
    BEGIN
      IF pg_catalog.current_setting('opengeni.account_id', true)
          IS DISTINCT FROM p_account_id::text
        OR pg_catalog.current_setting('opengeni.workspace_id', true)
          IS DISTINCT FROM p_workspace_id::text THEN
        RAISE EXCEPTION 'workspace background-command deletion scope mismatch'
          USING ERRCODE = '42501';
      END IF;

      BEGIN
        PERFORM command.id
        FROM {{schema}}.session_background_commands command
        WHERE command.account_id = p_account_id
          AND command.state IN ('running', 'stopping')
          AND (
            command.workspace_id = p_workspace_id
            OR command.control_workspace_id = p_workspace_id
          )
        ORDER BY command.id
        FOR UPDATE NOWAIT;
        GET DIAGNOSTICS active_count = ROW_COUNT;
      EXCEPTION WHEN lock_not_available THEN
        -- A reconciler currently owns lifecycle proof for a matching command;
        -- deletion remains blocked rather than waiting or losing its locator.
        RETURN 1;
      END;

      RETURN active_count;
    END
    $$;

CREATE FUNCTION opengeni_private.maintenance_workspace_commands_prune_inner(p_account_id uuid, p_workspace_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      deleted_count integer := 0;
    BEGIN
      IF pg_catalog.current_setting('opengeni.account_id', true)
          IS DISTINCT FROM p_account_id::text
        OR pg_catalog.current_setting('opengeni.workspace_id', true)
          IS DISTINCT FROM p_workspace_id::text THEN
        RAISE EXCEPTION 'workspace background-command deletion scope mismatch'
          USING ERRCODE = '42501';
      END IF;

      DELETE FROM {{schema}}.session_background_commands command
      WHERE command.account_id = p_account_id
        AND command.control_workspace_id = p_workspace_id
        AND command.workspace_id <> p_workspace_id
        AND command.state IN ('exited', 'lost');
      GET DIAGNOSTICS deleted_count = ROW_COUNT;
      RETURN deleted_count;
    END
    $$;

CREATE FUNCTION opengeni_private.make_room_for_retained_screenshot(p_account_id uuid, p_workspace_id uuid, p_needed_bytes bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      leaving bigint;
      candidate record;
    BEGIN
      -- The quota is workspace-wide, so eviction sees every image of the
      -- workspace regardless of session visibility. The caller must already
      -- be scoped to that workspace; nothing about the rows is returned.
      IF NOT opengeni_private.workspace_rls_visible(p_account_id, p_workspace_id) THEN
        RAISE EXCEPTION 'retained screenshot workspace is not in scope' USING ERRCODE = '42501';
      END IF;
      SELECT coalesce(sum(A.size_bytes), 0)::bigint INTO leaving
      FROM {{schema}}.retained_screenshot_artifacts A
      WHERE A.account_id = p_account_id
        AND A.workspace_id = p_workspace_id
        AND A.status IN ('cleanup_queued', 'cleanup_pending');
      IF leaving >= p_needed_bytes THEN
        RETURN leaving;
      END IF;
      FOR candidate IN
        SELECT A.artifact_id, A.size_bytes
        FROM {{schema}}.retained_screenshot_artifacts A
        WHERE A.account_id = p_account_id
          AND A.workspace_id = p_workspace_id
          AND A.status = 'ready'
        ORDER BY A.retention_expires_at, A.artifact_id
        FOR UPDATE SKIP LOCKED
      LOOP
        UPDATE {{schema}}.retained_screenshot_artifacts
        SET status = 'cleanup_queued',
          cleanup_reason = 'evicted',
          updated_at = clock_timestamp()
        WHERE artifact_id = candidate.artifact_id;
        leaving := leaving + candidate.size_bytes;
        EXIT WHEN leaving >= p_needed_bytes;
      END LOOP;
      RETURN leaving;
    END;
    $$;

CREATE FUNCTION opengeni_private.manage_subscription_core_personal(p_provider text, p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_connection_id uuid, p_action text, p_label text, p_enabled boolean, p_expected_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $_$
    DECLARE target subscription_connections%ROWTYPE; result jsonb; mode text;
      registry opengeni_private.subscription_core_providers%ROWTYPE;
    BEGIN
      IF NOT opengeni_subscription_internal.subscription_core_writer_context(p_provider, p_account_id, p_workspace_id, p_subject_id)
        OR p_action NOT IN ('resolve', 'rename', 'allocator', 'primary', 'extra_credits') OR p_connection_id IS NULL
      THEN RETURN NULL; END IF;
      SELECT provider_row.* INTO registry FROM opengeni_private.subscription_core_providers provider_row
      WHERE provider_row.provider = p_provider;
      IF NOT FOUND OR (p_action = 'extra_credits' AND NOT registry.extra_credits)
        OR (p_action = 'primary' AND registry.primary_setting_column IS NULL)
      THEN RETURN NULL; END IF;
      PERFORM opengeni_subscription_internal.grant_subscription_core_owner_capability(
        p_provider, 'connection_owner', p_account_id, p_workspace_id, p_subject_id,
        '00000000-0000-0000-0000-000000000000'::uuid);
      SELECT coalesce((SELECT alias.connection_id FROM subscription_connection_aliases alias
        WHERE alias.account_id = p_account_id AND alias.provider = p_provider
          AND alias.alias_connection_id = p_connection_id), p_connection_id) INTO p_connection_id;
      SELECT connection.* INTO target FROM subscription_connections connection
      JOIN organization_memberships membership
        ON membership.account_id = connection.account_id AND membership.id = connection.owner_organization_membership_id
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
        AND connection.provider = p_provider
        AND connection.kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND connection.ownership = 'personal'
        AND connection.owner_subject_id = p_subject_id AND membership.subject_id = p_subject_id
        AND membership.personal_workspace_id = p_workspace_id
        AND membership.status = 'active' AND membership.revoked_at IS NULL;
      IF NOT FOUND THEN
        PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
        RETURN NULL;
      END IF;
      result := jsonb_build_object('id', target.id, 'kind', 'unchanged');
      IF p_action <> 'resolve' THEN
        SELECT * INTO target FROM subscription_connections WHERE id = target.id FOR UPDATE;
        IF NOT FOUND OR target.disconnected_at IS NOT NULL THEN
          PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
          RETURN NULL;
        END IF;
      END IF;
      IF p_action = 'rename' THEN
        UPDATE subscription_connections SET label = nullif(left(btrim(p_label), 200), ''),
          version = version + 1, updated_at = clock_timestamp() WHERE id = target.id;
      ELSIF p_action = 'allocator' THEN
        IF p_enabled IS NULL OR p_expected_version IS NULL THEN
          PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
          RETURN NULL;
        END IF;
        IF target.allocator_enabled IS DISTINCT FROM p_enabled THEN
          IF target.allocator_version <> p_expected_version THEN
            result := result || '{"kind":"conflict"}'::jsonb;
          ELSE
            UPDATE subscription_connections SET allocator_enabled = p_enabled,
              allocator_version = allocator_version + 1, updated_at = clock_timestamp()
            WHERE id = target.id RETURNING * INTO target;
            result := result || '{"kind":"updated"}'::jsonb;
          END IF;
        END IF;
        result := result || jsonb_build_object('allocatorEnabled', target.allocator_enabled,
          'allocatorVersion', target.allocator_version, 'allocatorUpdatedAt', target.updated_at);
      ELSIF p_action = 'extra_credits' THEN
        IF p_enabled IS NULL OR p_expected_version IS NULL THEN
          PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
          RETURN NULL;
        END IF;
        IF target.extra_credits_enabled IS DISTINCT FROM p_enabled THEN
          IF target.extra_credits_version <> p_expected_version THEN
            result := result || '{"kind":"conflict"}'::jsonb;
          ELSE
            UPDATE subscription_connections SET extra_credits_enabled = p_enabled,
              extra_credits_version = extra_credits_version + 1,
              extra_credits_updated_by_subject_id = p_subject_id,
              extra_credits_updated_at = clock_timestamp(), updated_at = clock_timestamp()
            WHERE id = target.id RETURNING * INTO target;
            result := result || '{"kind":"updated"}'::jsonb;
          END IF;
        END IF;
        result := result || jsonb_build_object('extraCreditsEnabled', target.extra_credits_enabled,
          'extraCreditsVersion', target.extra_credits_version,
          'extraCreditsUpdatedAt', target.extra_credits_updated_at);
      ELSIF p_action = 'primary' THEN
        mode := coalesce(subscription_effective_settings(p_account_id, p_workspace_id)
          #>> ARRAY['values', 'rotation', p_provider, 'mode'], 'spread');
        -- The provider's primary column comes from its registry row (owner
        -- data, format-checked) until settings are keyed by provider.
        EXECUTE pg_catalog.format(
          'INSERT INTO subscription_settings (account_id, workspace_id, rotation, %1$I,
             updated_by_subject_id) VALUES ($1, $2, $3, $4, $5)
           ON CONFLICT (account_id, workspace_id) DO UPDATE SET
             rotation = coalesce(subscription_settings.rotation, ''{}''::jsonb) || EXCLUDED.rotation,
             %1$I = EXCLUDED.%1$I,
             updated_by_subject_id = $5, version = subscription_settings.version + 1,
             updated_at = clock_timestamp()', registry.primary_setting_column)
        USING p_account_id, p_workspace_id,
          jsonb_build_object(p_provider, jsonb_build_object('mode', mode)), target.id, p_subject_id;
      END IF;
      PERFORM opengeni_subscription_internal.drop_subscription_core_owner_capabilities(p_provider, p_account_id);
      RETURN result;
    END
    $_$;

CREATE FUNCTION opengeni_private.mark_automatic_session_title_fanout_delivered_v1(p_outbox_id uuid, p_event_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  WITH delivered AS (
    UPDATE opengeni_private.automatic_session_title_fanout_outbox_v1 pending
    SET delivered_at = pg_catalog.clock_timestamp(),
        last_error = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE pending.id = p_outbox_id
      AND pending.event_id = p_event_id
      AND pending.delivered_at IS NULL
    RETURNING true AS changed
  )
  SELECT coalesce((SELECT changed FROM delivered), false);
$$;

CREATE FUNCTION opengeni_private.mark_automatic_session_title_fanout_failed_v1(p_outbox_id uuid, p_event_id uuid, p_error text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  WITH failed AS (
    UPDATE opengeni_private.automatic_session_title_fanout_outbox_v1 pending
    SET last_error = pg_catalog.left(coalesce(p_error, 'unknown failure'), 500),
        updated_at = pg_catalog.clock_timestamp()
    WHERE pending.id = p_outbox_id
      AND pending.event_id = p_event_id
      AND pending.delivered_at IS NULL
    RETURNING true AS changed
  )
  SELECT coalesce((SELECT changed FROM failed), false);
$$;

CREATE FUNCTION opengeni_private.mark_editable_artifact_live_outbox_published(p_outbox_id text, p_owner text, p_attempt_count integer, p_data_schema name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE affected integer;
DECLARE data_schema name;
BEGIN
  IF p_outbox_id IS NULL
    OR p_outbox_id !~ '^[0-9a-f]{32}$' OR p_outbox_id ~ '^0+$'
    OR p_owner IS NULL OR pg_catalog.octet_length(p_owner) NOT BETWEEN 1 AND 256
    OR p_attempt_count IS NULL OR p_attempt_count NOT BETWEEN 1 AND 1000000
    OR p_data_schema IS NULL
  THEN
    RAISE EXCEPTION 'invalid editable artifact outbox settlement bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  EXECUTE pg_catalog.format($query$
    UPDATE %I.editable_artifact_live_outbox target
    SET state = 'published', published_at = pg_catalog.statement_timestamp(),
      lease_owner = NULL, lease_expires_at = NULL, last_error_code = NULL
    WHERE target.id = $1
      AND target.state = 'publishing'
      AND target.lease_owner = $2
      AND target.attempt_count = $3
      AND target.lease_expires_at > pg_catalog.statement_timestamp()
  $query$, data_schema) USING p_outbox_id, p_owner, p_attempt_count;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected = 1 THEN RETURN true; END IF;
  EXECUTE pg_catalog.format($query$
    SELECT count(*)::integer
    FROM %I.editable_artifact_live_outbox target
    WHERE target.id = $1
      AND target.attempt_count = $2
      AND target.state = 'published'
  $query$, data_schema) INTO affected USING p_outbox_id, p_attempt_count;
  RETURN affected = 1;
END;
$_$;

CREATE FUNCTION opengeni_private.mark_inbox_item_event_v1(p_session_id uuid, p_kind text, p_source_key text, p_sequence integer) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  UPDATE opengeni_private.inbox_items item SET event_sequence = p_sequence
  WHERE item.session_id = p_session_id AND item.kind = p_kind
    AND item.source_key = p_source_key
$$;

CREATE FUNCTION opengeni_private.mark_session_activity_pending() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  gate_state text := nullif(current_setting('opengeni.session_activity_gate_state', true), '');
  gate_workspace_id uuid := nullif(current_setting('opengeni.session_activity_gate_workspace_id', true), '')::uuid;
BEGIN
  IF gate_state = 'open' AND gate_workspace_id = NEW.workspace_id THEN
    NEW.activity_revision_pending_xid := pg_current_xact_id()::text::bigint;
  ELSIF gate_state = 'finalizing' THEN
    IF TG_OP <> 'UPDATE' OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
      OR NEW.updated_at IS DISTINCT FROM OLD.updated_at
      OR OLD.activity_revision_pending_xid IS DISTINCT FROM pg_current_xact_id()::text::bigint
      OR NEW.activity_revision_pending_xid IS NOT NULL
      OR NEW.activity_revision <= OLD.activity_revision THEN
      RAISE EXCEPTION 'Invalid session activity finalization' USING ERRCODE = '55000';
    END IF;
  ELSE
    -- No deferred guard is queued and no second session-row write is needed.
    NEW.activity_revision_pending_xid := NULL;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.mark_session_turn_deltas_folded(p_workspace_id uuid, p_turn_id uuid, p_folded_runs integer, p_removed_rows integer) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    AS $$
  INSERT INTO opengeni_private.session_turn_delta_folds
    (workspace_id, turn_id, folded_runs, removed_rows)
  SELECT T.workspace_id, T.id, greatest(p_folded_runs, 0), greatest(p_removed_rows, 0)
  FROM session_turns T
  WHERE T.workspace_id = p_workspace_id AND T.id = p_turn_id
  ON CONFLICT (workspace_id, turn_id) DO UPDATE
    SET folded_runs = opengeni_private.session_turn_delta_folds.folded_runs + EXCLUDED.folded_runs,
      removed_rows = opengeni_private.session_turn_delta_folds.removed_rows + EXCLUDED.removed_rows,
      folded_at = now();
$$;

CREATE FUNCTION opengeni_private.mcp_operation_command_scoped(p_scope jsonb, p_action text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      v_account uuid := (p_scope->>'accountId')::uuid;
      v_workspace uuid := (p_scope->>'workspaceId')::uuid;
      v_session uuid := (p_scope->>'sessionId')::uuid;
      v_turn uuid := (p_scope->>'turnId')::uuid;
      v_attempt uuid := (p_scope->>'attemptId')::uuid;
      v_generation integer := (p_scope->>'executionGeneration')::integer;
      v_principal_id text; v_principal_kind text;
      v_op uuid := (p_payload->>'operationId')::uuid;
      v_row mcp_operations%ROWTYPE;
      v_ids uuid[];
      v_digest text;
      v_claim uuid;
      v_operation jsonb;
      v_membership jsonb; v_external_membership jsonb;
      v_principal_membership uuid; v_principal_revision bigint;
      v_link_snapshot jsonb; v_link external_identity_links%ROWTYPE;
      v_run uuid;
      v_control workspace_inference_controls%ROWTYPE;
      v_control_active boolean;
    BEGIN
      IF v_account IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true),'')::uuid
        OR v_workspace IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true),'')::uuid
        OR v_generation IS NULL OR v_generation < 1
        OR jsonb_typeof(p_scope) IS DISTINCT FROM 'object'
        OR p_scope - ARRAY['accountId','workspaceId','sessionId','turnId','attemptId','executionGeneration'] <> '{}'::jsonb
        OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
      THEN RAISE EXCEPTION 'MCP operation scope mismatch' USING ERRCODE='42501'; END IF;

      IF p_action IS NULL OR p_action NOT IN ('capture','read','settle_original','claim_read','release_read','settle_observation')
      THEN RAISE EXCEPTION 'unknown MCP ledger action'; END IF;

      -- Membership lifecycle precedes tenancy/control/session locks. Scheduled
      -- run validation follows the session lock, matching canonical claim/resume.
      -- p_scope is authenticated by the calling worker; these checks validate
      -- canonical authority, never authenticate arbitrary request JSON.
      PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || v_account::text,0));
      SELECT coalesce(nullif(t.initiating_human_subject_id,''),t.initiator_subject_id),
        CASE WHEN nullif(t.initiating_human_subject_id,'') IS NOT NULL THEN 'subject' ELSE t.initiator_kind END
        INTO v_principal_id,v_principal_kind
      FROM session_turns t WHERE t.id=v_turn AND t.account_id=v_account AND t.workspace_id=v_workspace AND t.session_id=v_session;
      IF v_principal_id IS NULL OR v_principal_id IN ('','unattributed-legacy')
      THEN RAISE EXCEPTION 'MCP operation canonical principal missing' USING ERRCODE='42501'; END IF;
      -- Only the immutable turn chooses the subject. The outer definer restores
      -- these settings on success/error, so this cannot become a subject oracle.
      PERFORM set_config('opengeni.subject_id',v_principal_id,true);
      PERFORM set_config('opengeni.initiating_human_subject_id',CASE WHEN v_principal_kind='subject' THEN v_principal_id ELSE '' END,true);
      IF v_principal_kind='subject' THEN
        IF v_principal_id LIKE 'user:%' OR v_principal_id LIKE 'external_user:%' THEN
          SELECT value INTO v_membership FROM jsonb_array_elements(list_self_organization_memberships(v_principal_id))
            WHERE value->>'organizationId'=v_account::text;
          -- An absent organization membership preserves an explicit legacy
          -- workspace grant; a present inactive membership revokes it.
          IF v_membership IS NOT NULL AND v_membership->>'status'<>'active' THEN
            RAISE EXCEPTION 'MCP operation principal membership revoked' USING ERRCODE='42501'; END IF;
          v_principal_membership := (v_membership->>'id')::uuid;
          v_principal_revision := (v_membership->>'authorizationRevision')::bigint;
        END IF;
        -- Same stated-workspace rule as subjectHasLiveWorkspaceAuthorityInScope:
        -- explicit membership OR exact active Personal pointer, never a default.
        IF NOT EXISTS(SELECT 1 FROM workspace_memberships WHERE account_id=v_account
          AND workspace_id=v_workspace AND subject_id=v_principal_id)
          AND (v_membership IS NULL OR v_membership->>'personalWorkspaceId' IS DISTINCT FROM v_workspace::text)
        THEN RAISE EXCEPTION 'MCP operation workspace membership revoked' USING ERRCODE='42501'; END IF;
      END IF;

      SELECT canonical_snapshot INTO v_link_snapshot FROM external_link_turn_authorities
        WHERE account_id=v_account AND workspace_id=v_workspace AND session_id=v_session AND turn_id=v_turn;
      IF v_link_snapshot IS NOT NULL THEN
        SELECT * INTO v_link FROM external_identity_links WHERE id=(v_link_snapshot#>>'{actor,linkId}')::uuid
          AND account_id=v_account FOR SHARE;
        IF NOT FOUND OR v_link.status<>'active' OR (v_link.expires_at IS NOT NULL AND v_link.expires_at<=clock_timestamp())
          OR v_link.revision IS DISTINCT FROM (v_link_snapshot#>>'{actor,linkRevision}')::bigint
          OR v_link.native_subject_id IS DISTINCT FROM v_principal_id
          OR v_link.native_membership_id IS DISTINCT FROM v_principal_membership
          OR v_link.native_authorization_revision IS DISTINCT FROM v_principal_revision
          OR v_link.external_identity_id::text IS DISTINCT FROM v_link_snapshot#>>'{actor,externalIdentityId}'
          OR v_link.external_subject_id IS DISTINCT FROM v_link_snapshot#>>'{actor,externalSubjectId}'
          OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_link_snapshot->'permissions') permission
            WHERE NOT (v_link.permissions ? permission) AND NOT(permission<>'secrets:read' AND v_link.permissions ? 'workspace:admin'))
        THEN RAISE EXCEPTION 'MCP operation linked authority revoked' USING ERRCODE='42501'; END IF;
        PERFORM set_config('opengeni.subject_id',v_link.external_subject_id,true);
        SELECT value INTO v_external_membership FROM jsonb_array_elements(list_self_organization_memberships(v_link.external_subject_id))
          WHERE value->>'organizationId'=v_account::text;
        PERFORM set_config('opengeni.subject_id',v_principal_id,true);
        IF v_external_membership IS NULL OR v_external_membership->>'status'<>'active'
          OR (v_external_membership->>'authorizationRevision')::bigint IS DISTINCT FROM v_link.external_authorization_revision
          OR v_link.external_authorization_revision IS DISTINCT FROM (v_link_snapshot#>>'{actor,externalAuthorizationRevision}')::bigint
        THEN RAISE EXCEPTION 'MCP operation external membership revoked' USING ERRCODE='42501'; END IF;
      END IF;

      PERFORM pg_advisory_xact_lock_shared(hashtextextended('session-tenancy:' || v_workspace::text,0));
      PERFORM pg_advisory_xact_lock_shared(hashtextextended('workspace-control:' || v_workspace::text,0));
      SELECT * INTO v_control FROM workspace_inference_controls WHERE workspace_id=v_workspace AND account_id=v_account FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION 'MCP operation workspace control missing' USING ERRCODE='42501'; END IF;
      -- Canonical effective-control algebra from session-control.ts: only a
      -- strictly newer DESCENDANT override defeats a session pause; any newer
      -- path override defeats workspace pause. Same 10,000 ancestry bound.
      WITH RECURSIVE ancestry AS (
        SELECT id,parent_session_id,direct_control_state,direct_pause_revision,subtree_run_override_revision,0 AS depth
          FROM sessions WHERE id=v_session AND workspace_id=v_workspace AND account_id=v_account
        UNION ALL SELECT p.id,p.parent_session_id,p.direct_control_state,p.direct_pause_revision,p.subtree_run_override_revision,c.depth+1
          FROM ancestry c JOIN sessions p ON p.id=c.parent_session_id AND p.workspace_id=v_workspace AND p.account_id=v_account
          WHERE c.depth<10000
      ), path AS (SELECT *,max(subtree_run_override_revision) OVER(ORDER BY depth ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS descendant_override FROM ancestry)
      SELECT EXISTS(SELECT 1 FROM path WHERE parent_session_id IS NULL)
        AND NOT EXISTS(SELECT 1 FROM path WHERE depth>=10000 AND parent_session_id IS NOT NULL)
        AND NOT EXISTS(SELECT 1 FROM path WHERE direct_control_state='paused' AND direct_pause_revision IS NOT NULL
          AND (descendant_override IS NULL OR descendant_override<=direct_pause_revision))
        AND (v_control.workspace_state<>'paused' OR (v_control.workspace_pause_revision IS NOT NULL
          AND EXISTS(SELECT 1 FROM path WHERE subtree_run_override_revision>v_control.workspace_pause_revision)))
        INTO v_control_active;
      IF NOT v_control_active THEN RAISE EXCEPTION 'MCP operation effective control paused or unavailable' USING ERRCODE='42501'; END IF;
      PERFORM 1 FROM workspaces WHERE id=v_workspace AND account_id=v_account FOR KEY SHARE;
      PERFORM 1 FROM sessions WHERE id=v_session AND workspace_id=v_workspace AND account_id=v_account FOR SHARE;
      -- Canonical claim/resume owns control/session before scheduled run rows.
      -- Taking a run first can deadlock a stale read against replacement claim.
      -- Include inherited host-MCP scheduled origin, not only direct run turns.
      FOR v_run IN SELECT t.scheduled_task_run_id FROM session_turns t WHERE t.id=v_turn
        AND t.account_id=v_account AND t.workspace_id=v_workspace AND t.scheduled_task_run_id IS NOT NULL
        UNION SELECT (h.canonical_snapshot#>>'{scheduledOrigin,runId}')::uuid FROM host_mcp_turn_authorities h
          WHERE h.account_id=v_account AND h.workspace_id=v_workspace AND h.turn_id=v_turn
            AND h.canonical_snapshot#>>'{scheduledOrigin,runId}' IS NOT NULL
      LOOP
        IF validate_scheduled_agent_run_live_authority(v_account,v_workspace,v_run) IS NOT NULL
        THEN RAISE EXCEPTION 'MCP operation scheduled authority revoked' USING ERRCODE='42501'; END IF;
      END LOOP;
      PERFORM 1 FROM session_turns WHERE id=v_turn AND workspace_id=v_workspace AND account_id=v_account FOR SHARE;
      SELECT coalesce(nullif(t.initiating_human_subject_id,''),t.initiator_subject_id),
        CASE WHEN nullif(t.initiating_human_subject_id,'') IS NOT NULL THEN 'subject' ELSE t.initiator_kind END
        INTO v_principal_id,v_principal_kind
      FROM sessions s JOIN session_turns t ON t.id=s.active_turn_id AND t.session_id=s.id
        AND t.workspace_id=s.workspace_id AND t.account_id=s.account_id
      JOIN session_turn_attempts a ON a.id=t.active_attempt_id AND a.turn_id=t.id
        AND a.session_id=s.id AND a.account_id=s.account_id AND a.workspace_id=s.workspace_id
      WHERE s.account_id=v_account AND s.workspace_id=v_workspace AND s.id=v_session
        AND t.id=v_turn AND t.status='running'
        AND a.id=v_attempt AND a.execution_generation=v_generation AND t.execution_generation=v_generation
        AND a.state IN ('claimed','running') AND a.closed_at IS NULL AND a.quiesced_at IS NULL
        AND (a.authority_epoch BETWEEN s.execution_authority_epoch AND s.authority_epoch)
        AND a.authority_owner_organization_membership_id IS NOT DISTINCT FROM s.owner_organization_membership_id
        AND NOT EXISTS (SELECT 1 FROM session_attempt_interruptions i
          WHERE i.account_id=v_account AND i.workspace_id=v_workspace AND i.session_id=v_session
            AND i.attempt_id=a.id AND i.state IN ('pending','delivered','acknowledged'))
      FOR UPDATE OF a;
      IF v_principal_id IS NULL OR v_principal_id IN ('','unattributed-legacy') OR v_principal_kind NOT IN ('subject','service')
      THEN RAISE EXCEPTION 'MCP operation requires exact live canonical attempt' USING ERRCODE='42501'; END IF;

      IF p_action='capture' THEN
        IF v_op IS NULL OR p_payload - ARRAY['operationId','sourceCallId','serverId','originalTool','observerTool',
          'argumentDigest','destinationDigest','authorityDigest'] <> '{}'::jsonb
        THEN RAISE EXCEPTION 'invalid MCP capture metadata'; END IF;
        PERFORM pg_advisory_xact_lock(hashtextextended('mcp-operation:' || v_op::text,0));
        SELECT * INTO v_row FROM mcp_operations WHERE operation_id=v_op FOR UPDATE;
        IF FOUND THEN
          IF (v_row.account_id,v_row.workspace_id,v_row.session_id,v_row.source_turn_id,v_row.source_attempt_id,
              v_row.source_execution_generation,v_row.principal_kind,v_row.principal_id,v_row.principal_membership_id,v_row.principal_membership_revision,v_row.source_call_id,
              v_row.server_id,v_row.original_tool,v_row.observer_tool,v_row.argument_digest,v_row.destination_digest,v_row.authority_digest)
            IS DISTINCT FROM (v_account,v_workspace,v_session,v_turn,v_attempt,v_generation,v_principal_kind,v_principal_id,v_principal_membership,v_principal_revision,
              p_payload->>'sourceCallId',p_payload->>'serverId',p_payload->>'originalTool',p_payload->>'observerTool',
              p_payload->>'argumentDigest',p_payload->>'destinationDigest',p_payload->>'authorityDigest')
          THEN RAISE EXCEPTION 'MCP operation immutable identity conflict' USING ERRCODE='23505'; END IF;
          RETURN '"existing"'::jsonb;
        END IF;
        INSERT INTO mcp_operations(operation_id,account_id,workspace_id,session_id,source_turn_id,source_attempt_id,
          source_execution_generation,principal_kind,principal_id,principal_membership_id,principal_membership_revision,source_call_id,server_id,original_tool,observer_tool,
          argument_digest,destination_digest,authority_digest)
        VALUES(v_op,v_account,v_workspace,v_session,v_turn,v_attempt,v_generation,v_principal_kind,v_principal_id,v_principal_membership,v_principal_revision,
          p_payload->>'sourceCallId',p_payload->>'serverId',p_payload->>'originalTool',p_payload->>'observerTool',
          p_payload->>'argumentDigest',p_payload->>'destinationDigest',p_payload->>'authorityDigest');
        RETURN '"created"'::jsonb;
      END IF;

      IF p_action='read' AND v_op IS NULL THEN
        IF p_payload - ARRAY['sourceTurnId','sourceCallId'] <> '{}'::jsonb
          OR p_payload->>'sourceTurnId' IS NULL OR coalesce(p_payload->>'sourceCallId','')=''
        THEN RAISE EXCEPTION 'invalid exact MCP operation selector'; END IF;
        SELECT array_agg(operation_id) INTO v_ids FROM (
          SELECT operation_id FROM mcp_operations WHERE account_id=v_account AND workspace_id=v_workspace
            AND session_id=v_session AND principal_kind=v_principal_kind AND principal_id=v_principal_id
            AND source_turn_id=(p_payload->>'sourceTurnId')::uuid AND source_call_id=p_payload->>'sourceCallId'
          LIMIT 2) candidates;
        IF cardinality(v_ids)>1 THEN RETURN jsonb_build_object('status','ambiguous'); END IF;
        v_op := v_ids[1];
      ELSIF p_action='read' AND p_payload - ARRAY['operationId'] <> '{}'::jsonb THEN
        RAISE EXCEPTION 'invalid exact MCP operation selector';
      END IF;
      SELECT * INTO v_row FROM mcp_operations WHERE operation_id=v_op AND account_id=v_account
        AND workspace_id=v_workspace AND session_id=v_session
        AND principal_kind=v_principal_kind AND principal_id=v_principal_id FOR UPDATE;
      IF NOT FOUND THEN RETURN jsonb_build_object('status','not_found'); END IF;
      IF v_row.principal_membership_id IS DISTINCT FROM v_principal_membership
        OR v_row.principal_membership_revision IS DISTINCT FROM v_principal_revision
      THEN RAISE EXCEPTION 'MCP operation original membership authority changed' USING ERRCODE='42501'; END IF;
      IF p_action='settle_original' THEN
        IF v_row.source_turn_id<>v_turn OR v_row.source_attempt_id<>v_attempt
          OR v_row.source_execution_generation<>v_generation
        THEN RAISE EXCEPTION 'original MCP settlement requires source attempt' USING ERRCODE='42501'; END IF;
        IF p_payload->>'outcome' NOT IN ('completed','outcome_unknown')
          OR p_payload->>'outcome' IS NULL
          OR (p_payload->>'outcome'='completed' AND jsonb_typeof(p_payload->'result') IS DISTINCT FROM 'object')
          OR (p_payload->>'outcome'='outcome_unknown' AND p_payload ? 'result')
        THEN RAISE EXCEPTION 'invalid original MCP outcome'; END IF;
        IF v_row.original_outcome<>'captured' THEN
          IF v_row.original_outcome IS DISTINCT FROM p_payload->>'outcome'
            OR v_row.original_result IS DISTINCT FROM p_payload->'result'
            OR v_row.original_result_codec_version IS DISTINCT FROM (p_payload->>'resultCodecVersion')::integer
          THEN RAISE EXCEPTION 'original MCP outcome is immutable'; END IF;
        ELSE
          UPDATE mcp_operations SET original_outcome=p_payload->>'outcome', original_result=p_payload->'result',
            original_result_codec_version=(p_payload->>'resultCodecVersion')::integer
            WHERE operation_id=v_op;
        END IF;
        RETURN jsonb_build_object('status','settled');
      ELSIF p_action='claim_read' THEN
        IF v_row.receipt_digest IS NOT NULL OR v_row.original_outcome='completed' THEN RETURN jsonb_build_object('status','terminal'); END IF;
        IF v_row.observation_claim_expires_at>clock_timestamp() THEN RETURN jsonb_build_object('status','busy'); END IF;
        v_claim := gen_random_uuid();
        UPDATE mcp_operations SET observation_claim_id=v_claim,observation_claim_attempt_id=v_attempt,
          observation_claim_expires_at=clock_timestamp()+interval '30 seconds' WHERE operation_id=v_op;
        RETURN jsonb_build_object('status','claimed','claimId',v_claim);
      ELSIF p_action='release_read' THEN
        IF v_row.receipt_digest IS NOT NULL THEN RETURN jsonb_build_object('status','terminal'); END IF;
        IF v_row.observation_claim_id IS DISTINCT FROM (p_payload->>'claimId')::uuid
          OR v_row.observation_claim_attempt_id IS DISTINCT FROM v_attempt
        THEN RETURN jsonb_build_object('status','stale_claim'); END IF;
        UPDATE mcp_operations SET observation_claim_id=NULL,observation_claim_attempt_id=NULL,observation_claim_expires_at=NULL WHERE operation_id=v_op;
        RETURN jsonb_build_object('status','released');
      ELSIF p_action='settle_observation' THEN
        IF v_row.original_outcome='completed' THEN RETURN jsonb_build_object('status','original_completed'); END IF;
        IF v_row.observation_claim_id IS DISTINCT FROM (p_payload->>'claimId')::uuid
          OR v_row.observation_claim_attempt_id IS DISTINCT FROM v_attempt
        THEN RETURN jsonb_build_object('status','stale_claim'); END IF;
        IF jsonb_typeof(p_payload->'result') IS DISTINCT FROM 'object'
          OR octet_length((p_payload->'result')::text)>16777216
          OR coalesce(octet_length(p_payload->>'receiptRevision'),0) NOT BETWEEN 1 AND 1024
        THEN RAISE EXCEPTION 'invalid terminal MCP receipt'; END IF;
        -- PostgreSQL canonical jsonb representation; revision is part of identity.
        v_digest := encode(sha256(convert_to(jsonb_build_object('version',1,'codecVersion',p_payload->'resultCodecVersion','revision',p_payload->>'receiptRevision',
          'result',p_payload->'result')::text,'UTF8')),'hex');
        IF v_row.receipt_digest IS NOT NULL THEN
          RETURN jsonb_build_object('status',CASE WHEN v_row.receipt_digest=v_digest THEN 'existing' ELSE 'conflict' END,
            'receiptDigest',v_row.receipt_digest);
        END IF;
        IF v_row.observation_claim_expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('status','stale_claim'); END IF;
        UPDATE mcp_operations SET observation_result=p_payload->'result',receipt_revision=p_payload->>'receiptRevision',
          observation_result_codec_version=(p_payload->>'resultCodecVersion')::integer,
          receipt_digest=v_digest,observed_at=clock_timestamp() WHERE operation_id=v_op;
        RETURN jsonb_build_object('status','settled','receiptDigest',v_digest);
      ELSIF p_action<>'read' THEN RAISE EXCEPTION 'unknown MCP ledger action'; END IF;

      v_operation := jsonb_build_object('operationId',v_row.operation_id,'sourceCallId',v_row.source_call_id,
        'accountId',v_row.account_id,'workspaceId',v_row.workspace_id,'sessionId',v_row.session_id,
        'sourceTurnId',v_row.source_turn_id,'sourceAttemptId',v_row.source_attempt_id,
        'sourceExecutionGeneration',v_row.source_execution_generation,'principalKind',v_row.principal_kind,
        'principalId',v_row.principal_id,'serverId',v_row.server_id,'originalTool',v_row.original_tool,
        'observerTool',v_row.observer_tool,'argumentDigest',v_row.argument_digest,'destinationDigest',v_row.destination_digest,
        'authorityDigest',v_row.authority_digest,'originalOutcome',v_row.original_outcome,'originalResult',v_row.original_result,
        'originalResultCodecVersion',v_row.original_result_codec_version,
        'observationResultCodecVersion',v_row.observation_result_codec_version,
        'observationResult',v_row.observation_result,'receiptRevision',v_row.receipt_revision,'receiptDigest',v_row.receipt_digest);
      RETURN jsonb_build_object('status','found','operation',v_operation);
    END $$;

CREATE FUNCTION opengeni_private.member_notifications_allowed_v1(p_workspace_id uuid, p_subject_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM opengeni_private.inbox_member_notify_optins optin
    WHERE optin.workspace_id = p_workspace_id AND optin.subject_id = p_subject_id
  )
$$;

CREATE FUNCTION opengeni_private.memory_labels_valid(value text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT coalesce(cardinality(value), 0) <= 16
    AND NOT EXISTS (
      SELECT 1 FROM unnest(value) AS label
      WHERE label IS NULL
        OR length(label) > 64
        OR label !~ '^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$'
    )
    AND value = ARRAY(SELECT label FROM unnest(value) AS label ORDER BY label)
    AND cardinality(value) = cardinality(ARRAY(SELECT DISTINCT label FROM unnest(value) AS label));
$_$;

CREATE FUNCTION opengeni_private.memory_scope_authorized(row_scope_type text, row_subject_id text, row_role_key text, row_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(CASE row_scope_type
    WHEN 'workspace' THEN true
    WHEN 'user' THEN row_subject_id = opengeni_private.current_subject_id()
    WHEN 'role' THEN row_role_key = opengeni_private.current_memory_role_key()
    WHEN 'session' THEN row_session_id = opengeni_private.current_memory_session_id()
    WHEN 'ephemeral' THEN row_session_id = opengeni_private.current_memory_session_id()
    WHEN 'legacy' THEN false
    ELSE false
  END, false);
$$;

CREATE FUNCTION opengeni_private.memory_scope_visible(row_scope_type text, row_subject_id text, row_role_key text, row_session_id uuid, row_valid_from timestamp with time zone, row_valid_until timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT opengeni_private.memory_scope_authorized(
    row_scope_type, row_subject_id, row_role_key, row_session_id
  ) AND (
    row_scope_type <> 'ephemeral'
    OR (
      row_valid_from <= transaction_timestamp()
      AND row_valid_until > transaction_timestamp()
    )
  );
$$;

CREATE FUNCTION opengeni_private.model_context_value_valid(value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE code_units integer;
BEGIN
  IF value = '' OR value <> btrim(
    value,
    U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'
  )
  THEN
    RETURN false;
  END IF;
  SELECT sum(CASE WHEN ascii(character) > 65535 THEN 2 ELSE 1 END)::integer
  INTO code_units
  FROM unnest(string_to_array(value, NULL)) AS characters(character);
  RETURN code_units BETWEEN 1 AND 32768;
EXCEPTION WHEN others THEN
  RETURN false;
END;
$$;

CREATE FUNCTION opengeni_private.native_push_device_v1(p_auth_session_id text) RETURNS TABLE(platform text, app_id text, environment text, token text, rules text[], updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT device.platform, device.app_id, device.environment, device.token, device.rules,
    device.updated_at
  FROM opengeni_private.native_push_devices device
  JOIN auth_sessions session ON session.id = device.auth_session_id
  WHERE device.auth_session_id = p_auth_session_id AND session.expires_at > now()
$$;

CREATE FUNCTION opengeni_private.normalize_api_key_credential_kind() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.workspace_id IS NOT NULL THEN
    NEW.credential_kind := 'workspace';
  ELSIF NEW.credential_kind IS NULL THEN
    -- The previous application version omitted this column. Its organization-key
    -- route is the only null-workspace insert path with this exact fixed grant.
    IF NEW.permissions = '["account:read","workspace:create","workspace:read","workspace:admin","api_keys:manage"]'::jsonb THEN
      NEW.credential_kind := 'organization';
    ELSE
      NEW.credential_kind := 'legacy_account';
    END IF;
  END IF;

  -- Old application versions authorize every active null-workspace row by
  -- shape alone. Keep ambiguous legacy rows unusable through that old lookup
  -- path for the entire rolling window; only the exact previous organization
  -- writer above may create an active null-workspace credential.
  IF NEW.credential_kind = 'legacy_account' AND NEW.revoked_at IS NULL THEN
    NEW.revoked_at := CURRENT_TIMESTAMP;
    NEW.updated_at := CURRENT_TIMESTAMP;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.normalize_legacy_member_connection_read_0516() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  pre_0516 jsonb := opengeni_private.workspace_member_legacy_permissions_0516();
  pre_0555 jsonb := opengeni_private.workspace_member_legacy_permissions_0555();
  pre_0865 jsonb := opengeni_private.workspace_member_legacy_permissions_0865();
BEGIN
  IF NEW.role = 'member'
    AND NEW.subject_id NOT LIKE 'external_user:%'
    AND (
      (NEW.permissions @> pre_0516 AND pre_0516 @> NEW.permissions)
      OR (NEW.permissions @> pre_0555 AND pre_0555 @> NEW.permissions)
      OR (NEW.permissions @> pre_0865 AND pre_0865 @> NEW.permissions)
    )
  THEN
    NEW.permissions := '[
      "workspace:read", "sessions:create", "sessions:read", "sessions:control",
      "stream:view", "stream:control", "stream:acknowledge", "terminal:attach",
      "codemode:call", "files:upload", "files:read", "files:write",
      "documents:manage", "documents:search", "scheduled_tasks:manage",
      "scheduled_tasks:run", "github:use", "connections:read", "connections:write",
      "variable-sets:list", "variable-sets:read", "variable-sets:write",
      "variable-sets:attach", "variable-sets:use", "secrets:list", "secrets:write",
      "mcp_servers:attach", "goals:manage", "rigs:use", "rigs:manage",
      "enrollments:read", "artifacts:read", "artifacts:publish"
    ]'::jsonb;
    NEW.updated_at := pg_catalog.clock_timestamp();
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.observe_credit_grant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF TG_TABLE_SCHEMA <> '{{schema}}' THEN
        RETURN NULL;
      END IF;
      BEGIN
        INSERT INTO opengeni_private.credit_grant_observations (
          ledger_entry_id, grant_class, amount_micros
        ) VALUES (
          NEW.id, opengeni_private.credit_grant_class(NEW.type, NEW.source_type),
          NEW.amount_micros
        )
        ON CONFLICT (ledger_entry_id) DO NOTHING;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'credit grant observation skipped (%)', SQLSTATE;
      END;
      RETURN NULL;
    END $$;

CREATE FUNCTION opengeni_private.open_inbox_item_v1(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_recipient text, p_kind text, p_source_key text, p_title text, p_body text, p_urgency text, p_choices jsonb DEFAULT '[]'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_previous text;
BEGIN
  SELECT item.status INTO v_previous FROM opengeni_private.inbox_items item
  WHERE item.session_id = p_session_id AND item.kind = p_kind
    AND item.source_key = p_source_key AND item.recipient_subject_id = p_recipient;
  INSERT INTO opengeni_private.inbox_items AS item (
    account_id, workspace_id, session_id, recipient_subject_id, kind, source_key,
    title, body, urgency, choices
  ) VALUES (
    p_account_id, p_workspace_id, p_session_id, p_recipient, p_kind, p_source_key,
    left(coalesce(nullif(btrim(p_title), ''), 'Needs you'), 200),
    left(coalesce(btrim(p_body), ''), 2000),
    coalesce(p_urgency, 'normal'),
    coalesce(p_choices, '[]'::jsonb)
  )
  ON CONFLICT (session_id, kind, source_key, recipient_subject_id) DO UPDATE SET
    title = excluded.title,
    body = excluded.body,
    choices = excluded.choices,
    urgency = excluded.urgency,
    status = CASE WHEN item.status IN ('resolved', 'withdrawn') THEN 'open' ELSE item.status END,
    resolved_at = CASE WHEN item.status IN ('resolved', 'withdrawn') THEN NULL ELSE item.resolved_at END,
    content_version = item.content_version + 1,
    updated_at = now();
  RETURN v_previous IS NULL OR v_previous IN ('resolved', 'withdrawn');
END
$$;

CREATE FUNCTION opengeni_private.open_session_tenancy_fence_inventory(p_target_schema oid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  capability_id_value uuid := pg_catalog.gen_random_uuid();
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_namespace namespace
    JOIN opengeni_private.session_tenancy_fence_target_registry registry
      ON registry.target_schema = namespace.nspname
      AND registry.singleton
    WHERE namespace.oid = p_target_schema
  ) THEN
    RAISE EXCEPTION 'session tenancy inventory target schema is not registered'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO opengeni_private.session_tenancy_fence_inventory_capabilities (
    capability_id, target_schema, backend_pid, transaction_id
  ) VALUES (
    capability_id_value,
    p_target_schema,
    pg_catalog.pg_backend_pid(),
    pg_catalog.pg_current_xact_id()
  );
  RETURN capability_id_value;
END
$$;

CREATE FUNCTION opengeni_private.open_session_tenancy_fenced_access(p_target_schema oid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  capability_id_value uuid := pg_catalog.gen_random_uuid();
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_namespace namespace
    JOIN opengeni_private.session_tenancy_fence_target_registry registry
      ON registry.target_schema = namespace.nspname
      AND registry.singleton
    WHERE namespace.oid = p_target_schema
  ) THEN
    RAISE EXCEPTION 'session tenancy fenced-access target schema is not registered'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO opengeni_private.session_tenancy_fenced_access_capabilities (
    capability_id, target_schema, backend_pid, transaction_id
  ) VALUES (
    capability_id_value,
    p_target_schema,
    pg_catalog.pg_backend_pid(),
    pg_catalog.pg_current_xact_id()
  );
  RETURN capability_id_value;
END
$$;

CREATE FUNCTION opengeni_private.optional_workspace_rls_visible(account_id uuid, workspace_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT account_id = opengeni_private.current_account_id()
    AND (
      opengeni_private.current_workspace_id() IS NULL
      OR workspace_id IS NULL
      OR workspace_id = opengeni_private.current_workspace_id()
    );
$$;

CREATE TABLE organization_membership_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    target_subject_id text,
    target_email text NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_by_membership_id uuid NOT NULL,
    accepted_membership_id uuid,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    target_name text,
    initial_workspace_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    CONSTRAINT organization_membership_invitations_acceptance_check CHECK ((((status = 'accepted'::text) AND (accepted_membership_id IS NOT NULL)) OR ((status <> 'accepted'::text) AND (accepted_membership_id IS NULL)))),
    CONSTRAINT organization_membership_invitations_email_check CHECK (((target_email = lower(btrim(target_email))) AND ((octet_length(convert_to(target_email, 'UTF8'::name)) >= 3) AND (octet_length(convert_to(target_email, 'UTF8'::name)) <= 320)))),
    CONSTRAINT organization_membership_invitations_name_check CHECK (((target_name IS NULL) OR ((target_name = btrim(target_name)) AND ((octet_length(convert_to(target_name, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(target_name, 'UTF8'::name)) <= 120))))),
    CONSTRAINT organization_membership_invitations_revision_check CHECK ((revision > 0)),
    CONSTRAINT organization_membership_invitations_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text]))),
    CONSTRAINT organization_membership_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT organization_membership_invitations_subject_check CHECK (((target_subject_id IS NULL) OR ((target_subject_id = btrim(target_subject_id)) AND (target_subject_id ~~ 'user:%'::text) AND ((octet_length(convert_to(target_subject_id, 'UTF8'::name)) >= 6) AND (octet_length(convert_to(target_subject_id, 'UTF8'::name)) <= 1024))))),
    CONSTRAINT organization_membership_invitations_workspace_count_check CHECK (((cardinality(initial_workspace_ids) >= 0) AND (cardinality(initial_workspace_ids) <= 100)))
);

ALTER TABLE ONLY organization_membership_invitations FORCE ROW LEVEL SECURITY;

COMMENT ON TABLE organization_membership_invitations IS 'Registered-human organization invitations; acceptance is exact-subject and provider delivery is external.';

CREATE FUNCTION opengeni_private.organization_invitation_row_json(p_invitation organization_membership_invitations) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT pg_catalog.jsonb_build_object(
    'id', p_invitation.id,
    'organizationId', p_invitation.account_id,
    'targetEmail', p_invitation.target_email,
    'targetName', p_invitation.target_name,
    'initialWorkspaceIds', p_invitation.initial_workspace_ids,
    'role', p_invitation.role,
    'status', CASE
      WHEN p_invitation.status = 'pending'
        AND p_invitation.expires_at <= pg_catalog.clock_timestamp()
      THEN 'expired'
      ELSE p_invitation.status
    END,
    'revision', p_invitation.revision,
    'expiresAt', p_invitation.expires_at,
    'acceptedMembershipId', p_invitation.accepted_membership_id,
    'createdAt', p_invitation.created_at,
    'updatedAt', p_invitation.updated_at,
    'delivery', (
      SELECT opengeni_private.organization_user_setup_delivery_json(delivery)
      FROM organization_user_setup_deliveries delivery
      WHERE delivery.account_id = p_invitation.account_id
        AND delivery.invitation_id = p_invitation.id
    )
  )
$$;

CREATE FUNCTION opengeni_private.organization_membership_history_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN RAISE EXCEPTION 'organization membership history is immutable' USING ERRCODE = '55000'; END
$$;

CREATE TABLE organization_memberships (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    subject_id text NOT NULL,
    status text DEFAULT 'provisioning'::text NOT NULL,
    personal_workspace_id uuid,
    authorization_revision bigint DEFAULT 1 NOT NULL,
    revoked_at timestamp with time zone,
    personal_retention_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    CONSTRAINT organization_memberships_active_personal_workspace_check CHECK (((status <> 'active'::text) OR (personal_workspace_id IS NOT NULL))),
    CONSTRAINT organization_memberships_revision_check CHECK ((authorization_revision > 0)),
    CONSTRAINT organization_memberships_revocation_check CHECK ((((status = 'revoked'::text) AND (revoked_at IS NOT NULL)) OR ((status <> 'revoked'::text) AND (revoked_at IS NULL)))),
    CONSTRAINT organization_memberships_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text]))),
    CONSTRAINT organization_memberships_status_check CHECK ((status = ANY (ARRAY['provisioning'::text, 'active'::text, 'suspended'::text, 'revoked'::text]))),
    CONSTRAINT organization_memberships_subject_check CHECK (((length(btrim(subject_id)) >= 1) AND (length(btrim(subject_id)) <= 1024)))
);

ALTER TABLE ONLY organization_memberships FORCE ROW LEVEL SECURITY;

COMMENT ON TABLE organization_memberships IS 'Organization membership and personal-workspace lifecycle metadata; not workspace content access.';

COMMENT ON COLUMN organization_memberships.personal_workspace_id IS 'One personal workspace per membership; lifecycle metadata, never user-resource ownership.';

CREATE FUNCTION opengeni_private.organization_membership_row_json(p_membership organization_memberships) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT pg_catalog.jsonb_build_object(
    'id', p_membership.id,
    'organizationId', p_membership.account_id,
    'subjectId', p_membership.subject_id,
    'role', p_membership.role,
    'status', p_membership.status,
    'authorizationRevision', p_membership.authorization_revision,
    'personalWorkspaceId', p_membership.personal_workspace_id,
    'revokedAt', p_membership.revoked_at,
    'personalRetentionUntil', p_membership.personal_retention_until,
    'createdAt', p_membership.created_at,
    'updatedAt', p_membership.updated_at
  )
$$;

CREATE FUNCTION opengeni_private.organization_model_provider_scope_visible(p_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      workspace_value uuid := opengeni_private.current_workspace_id();
      subject_value text := opengeni_private.current_subject_id();
      visible boolean := false;
      previous_lifecycle text := pg_catalog.current_setting(
        'opengeni.organization_tenancy_lifecycle', true
      );
    BEGIN
      IF p_account_id IS NULL
        OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
      THEN RETURN false; END IF;

      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        'organization_membership_lifecycle', true
      );
      IF workspace_value IS NOT NULL THEN
        SELECT EXISTS (
          SELECT 1 FROM {{schema}}.workspaces workspace
          WHERE workspace.account_id = p_account_id AND workspace.id = workspace_value
        ) AND NOT EXISTS (
          SELECT 1 FROM {{schema}}.organization_memberships membership
          WHERE membership.account_id = p_account_id
            AND membership.personal_workspace_id = workspace_value
        ) INTO visible;
      ELSIF subject_value IS NOT NULL AND (
        subject_value LIKE 'user:%'
        OR (
          subject_value = 'dev'
          AND EXISTS (
            SELECT 1 FROM {{schema}}.managed_accounts account
            WHERE account.id = p_account_id
              AND account.external_source = 'opengeni:local'
              AND account.external_id = 'default'
          )
        )
      ) THEN
        SELECT EXISTS (
          SELECT 1 FROM {{schema}}.organization_memberships membership
          WHERE membership.account_id = p_account_id
            AND membership.subject_id = subject_value
            AND membership.status = 'active'
            AND membership.role IN ('owner', 'admin')
        ) INTO visible;
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
      );
      RETURN coalesce(visible, false);
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
      );
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.organization_model_usage_summary(p_account_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_after_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET enable_nestloop TO 'off'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
    DECLARE
      context_account_id uuid;
      context_subject_id text;
      context_human_id text;
      shared_ids uuid[];
      page_ids uuid[];
      next_cursor uuid;
      workspace_row record;
      fact_rows jsonb := '[]'::jsonb;
      response jsonb;
    BEGIN
      PERFORM opengeni_private.session_variable_set_attachments_protocol_v1_active();
      BEGIN
        context_account_id := nullif(pg_catalog.current_setting('opengeni.account_id', true), '')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Organization model usage account context is malformed' USING ERRCODE = '42501';
      END;
      context_subject_id := nullif(pg_catalog.current_setting('opengeni.subject_id', true), '');
      context_human_id := nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), '');
      IF context_account_id IS NULL OR context_account_id IS DISTINCT FROM p_account_id
        OR nullif(pg_catalog.current_setting('opengeni.workspace_id', true), '') IS NOT NULL
      THEN
        RAISE EXCEPTION 'Organization model usage requires the exact account-only context'
          USING ERRCODE = '42501';
      END IF;
      IF p_since IS NULL OR p_until IS NULL OR NOT pg_catalog.isfinite(p_since)
        OR NOT pg_catalog.isfinite(p_until) OR p_until < p_since
        OR p_until - p_since > interval '366 days'
      THEN
        RAISE EXCEPTION 'Organization model usage window is invalid' USING ERRCODE = '22023';
      END IF;

      -- The same canonical shared-workspace inventory as the 0473 summary: every
      -- Personal workspace is excluded before paging.
      SELECT coalesce(pg_catalog.array_agg(listed.workspace_id ORDER BY listed.workspace_id), '{}'::uuid[])
      INTO shared_ids
      FROM {{schema}}.list_organization_workspace_ids(context_account_id) listed;
      SELECT coalesce(pg_catalog.array_agg(id ORDER BY id), '{}'::uuid[]) INTO page_ids
      FROM (
        SELECT id FROM {{schema}}.workspaces
        WHERE account_id = context_account_id
          AND id = ANY(shared_ids)
          AND (p_after_workspace_id IS NULL OR id > p_after_workspace_id)
        ORDER BY id
        LIMIT 51
      ) page;
      IF pg_catalog.cardinality(page_ids) > 50 THEN
        next_cursor := page_ids[50];
        page_ids := page_ids[1:50];
      END IF;

      BEGIN
        FOR workspace_row IN
          SELECT id FROM {{schema}}.workspaces WHERE account_id = context_account_id ORDER BY id
        LOOP
          -- Bind the exact workspace so the unchanged workspace RLS and the 0359
          -- capability each admit only this workspace's facts.
          PERFORM pg_catalog.set_config('opengeni.workspace_id', workspace_row.id::text, true);
          INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities (
            backend_pid, transaction_id, capability_kind, account_id, workspace_id,
            subject_id, initiating_human_subject_id
          ) VALUES (
            pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'model_call_facts',
            context_account_id, workspace_row.id, context_subject_id, context_human_id
          );
          fact_rows := fact_rows || coalesce((
            WITH visible_sessions AS MATERIALIZED (
              SELECT id, account_id, workspace_id
              FROM {{schema}}.sessions session_row
              WHERE account_id = context_account_id
                AND workspace_id = workspace_row.id
                AND (context_subject_id IS NULL OR visibility = 'workspace_shared'
                  OR {{schema}}.session_private_actor_visible(account_id, workspace_id,
                    owner_organization_membership_id, owner_subject_id))
            ), grouped AS (
              SELECT fact.provider, fact.model, fact.billing_path,
                pg_catalog.count(*) AS calls,
                coalesce(pg_catalog.sum(fact.input_tokens), 0) AS input_tokens,
                coalesce(pg_catalog.sum(fact.output_tokens), 0) AS output_tokens,
                coalesce(pg_catalog.sum(fact.cached_tokens), 0) AS cached_tokens,
                coalesce(pg_catalog.sum(fact.input_tokens) FILTER (
                  WHERE fact.cached_tokens IS NOT NULL AND fact.input_tokens IS NOT NULL
                ), 0) AS cache_input_tokens,
                coalesce(pg_catalog.sum(fact.cache_write_tokens), 0) AS cache_write_tokens,
                coalesce(pg_catalog.sum(fact.total_tokens), 0) AS total_tokens,
                pg_catalog.count(fact.total_tokens) AS token_known_calls,
                pg_catalog.count(*) FILTER (
                  WHERE fact.cached_tokens IS NOT NULL AND fact.input_tokens IS NOT NULL
                ) AS cache_known_calls,
                coalesce(pg_catalog.sum(fact.priced_cost_micros) FILTER (
                  WHERE fact.billing_path = 'opengeni_credits'
                ), 0) AS credit_micros,
                coalesce(pg_catalog.sum(fact.estimated_provider_cost_micros), 0)
                  AS estimated_provider_micros,
                pg_catalog.count(fact.estimated_provider_cost_micros)
                  AS estimated_provider_known_calls
              FROM {{schema}}.model_call_facts fact
              
              WHERE fact.account_id = context_account_id
                AND fact.workspace_id = workspace_row.id
                AND fact.occurred_at >= p_since
                AND fact.occurred_at < p_until
              GROUP BY fact.provider, fact.model, fact.billing_path
            )
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'workspace_id', workspace_row.id, 'provider', provider, 'model', model,
              'billing_path', billing_path, 'calls', calls, 'input_tokens', input_tokens,
              'output_tokens', output_tokens, 'cached_tokens', cached_tokens,
              'cache_input_tokens', cache_input_tokens, 'cache_write_tokens', cache_write_tokens,
              'total_tokens', total_tokens, 'token_known_calls', token_known_calls,
              'cache_known_calls', cache_known_calls, 'credit_micros', credit_micros,
              'estimated_provider_micros', estimated_provider_micros,
              'estimated_provider_known_calls', estimated_provider_known_calls
            ))
            FROM grouped
          ), '[]'::jsonb);
          DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
          WHERE backend_pid = pg_catalog.pg_backend_pid()
            AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
            AND capability_kind = 'model_call_facts';
        END LOOP;
        PERFORM pg_catalog.set_config('opengeni.workspace_id', '', true);
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'model_call_facts';
        PERFORM pg_catalog.set_config('opengeni.workspace_id', '', true);
        RAISE;
      END;

      WITH fact AS (
        SELECT * FROM pg_catalog.jsonb_to_recordset(fact_rows) AS row_value(
          workspace_id uuid, provider text, model text, billing_path text, calls bigint,
          input_tokens bigint, output_tokens bigint, cached_tokens bigint,
          cache_input_tokens bigint, cache_write_tokens bigint, total_tokens bigint,
          token_known_calls bigint, cache_known_calls bigint, credit_micros bigint,
          estimated_provider_micros bigint, estimated_provider_known_calls bigint
        )
      ), payer_grouped AS (
        SELECT CASE WHEN billing_path = 'opengeni_credits' THEN 'opengeni_credits'
          WHEN provider IN ('codex-subscription', 'supergrok-subscription',
            'workspace-claude-subscription', 'organization-claude-subscription') THEN 'subscription'
          ELSE 'own_key' END AS payer,
          jsonb_build_object(
            'calls', sum(calls)::text, 'inputTokens', sum(input_tokens)::text,
            'outputTokens', sum(output_tokens)::text, 'cachedTokens', sum(cached_tokens)::text,
            'cacheInputTokens', sum(cache_input_tokens)::text, 'cacheWriteTokens', sum(cache_write_tokens)::text,
            'totalTokens', sum(total_tokens)::text, 'tokenKnownCalls', sum(token_known_calls)::text,
            'cacheKnownCalls', sum(cache_known_calls)::text, 'creditMicros', sum(credit_micros)::text,
            'estimatedProviderMicros', sum(estimated_provider_micros)::text,
            'estimatedProviderKnownCalls', sum(estimated_provider_known_calls)::text
          ) AS totals
        FROM fact GROUP BY 1
      ), grouped AS (
        SELECT
          grouping(fact.provider, fact.model) = 0 AS by_model,
          grouping(fact.workspace_id) = 0 AS by_workspace,
          grouping(personal) = 0 AS by_personal,
          fact.provider, fact.model, fact.workspace_id, personal, fact.billing_path,
          pg_catalog.jsonb_build_object(
            'billingPath', fact.billing_path,
            'calls', pg_catalog.sum(fact.calls)::text,
            'inputTokens', pg_catalog.sum(fact.input_tokens)::text,
            'outputTokens', pg_catalog.sum(fact.output_tokens)::text,
            'cachedTokens', pg_catalog.sum(fact.cached_tokens)::text,
            'cacheInputTokens', pg_catalog.sum(fact.cache_input_tokens)::text,
            'cacheWriteTokens', pg_catalog.sum(fact.cache_write_tokens)::text,
            'totalTokens', pg_catalog.sum(fact.total_tokens)::text,
            'tokenKnownCalls', pg_catalog.sum(fact.token_known_calls)::text,
            'cacheKnownCalls', pg_catalog.sum(fact.cache_known_calls)::text,
            'creditMicros', pg_catalog.sum(fact.credit_micros)::text,
            'estimatedProviderMicros', pg_catalog.sum(fact.estimated_provider_micros)::text,
            'estimatedProviderKnownCalls', pg_catalog.sum(fact.estimated_provider_known_calls)::text
          ) AS totals,
          pg_catalog.sum(fact.total_tokens) AS sort_tokens
        FROM (
          SELECT fact.*, NOT (fact.workspace_id = ANY(shared_ids)) AS personal FROM fact
        ) fact
        GROUP BY GROUPING SETS (
          (fact.billing_path),
          (fact.provider, fact.model, fact.billing_path),
          (fact.workspace_id, fact.billing_path),
          (personal, fact.billing_path)
        )
      ), models AS (
        SELECT provider, model, totals, sort_tokens
        FROM grouped WHERE by_model
        ORDER BY sort_tokens DESC, provider, model, billing_path
        LIMIT 51
      )
      SELECT pg_catalog.jsonb_build_object(
        'payers', coalesce((SELECT jsonb_agg(totals || jsonb_build_object('payer', payer) ORDER BY payer) FROM payer_grouped), '[]'::jsonb),
        'billing', coalesce((
          SELECT pg_catalog.jsonb_agg(totals ORDER BY billing_path)
          FROM grouped WHERE NOT by_model AND NOT by_workspace AND NOT by_personal
        ), '[]'::jsonb),
        'models', coalesce((
          SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'provider', provider, 'model', model, 'totals', totals
          ) ORDER BY sort_tokens DESC, provider, model)
          FROM (SELECT * FROM models ORDER BY sort_tokens DESC, provider, model LIMIT 50) listed
        ), '[]'::jsonb),
        'modelsTruncated', (SELECT pg_catalog.count(*) > 50 FROM models),
        'workspaces', coalesce((
          SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'workspaceId', workspace.id, 'name', workspace.name,
            'billing', coalesce((
              SELECT pg_catalog.jsonb_agg(grouped.totals ORDER BY grouped.billing_path)
              FROM grouped WHERE grouped.by_workspace AND grouped.workspace_id = workspace.id
            ), '[]'::jsonb)
          ) ORDER BY workspace.id)
          FROM {{schema}}.workspaces workspace
          WHERE workspace.account_id = context_account_id AND workspace.id = ANY(page_ids)
        ), '[]'::jsonb),
        'personal', pg_catalog.jsonb_build_object(
          'workspacesWithUsage', (
            SELECT pg_catalog.count(DISTINCT fact.workspace_id) FROM fact
            WHERE NOT (fact.workspace_id = ANY(shared_ids))
          )::text,
          'billing', coalesce((
            SELECT pg_catalog.jsonb_agg(totals ORDER BY billing_path)
            FROM grouped WHERE by_personal AND personal
          ), '[]'::jsonb)
        ),
        'nextWorkspaceCursor', next_cursor
      ) INTO response;
      RETURN response;
    END
    $$;

CREATE FUNCTION opengeni_private.organization_retention_file_candidates(p_account_id uuid, p_membership_id uuid) RETURNS TABLE(file_id uuid, object_bucket text, object_key text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  WITH authority_context AS MATERIALIZED (
    SELECT opengeni_private.assert_organization_retention_account(p_account_id)
  ), member AS (
    SELECT membership.personal_workspace_id
    FROM organization_memberships membership
    CROSS JOIN authority_context
    WHERE membership.account_id = p_account_id
      AND membership.id = p_membership_id
  ), owned_document_files AS (
    SELECT document.file_id
    FROM documents document
    JOIN organization_user_resource_authorities authority
      ON authority.id = document.authority_id
     AND authority.account_id = document.account_id
     AND authority.organization_membership_id = document.owner_organization_membership_id
     AND authority.resource_kind = 'document'
     AND authority.resource_id = document.id
    WHERE authority.account_id = p_account_id
      AND authority.organization_membership_id = p_membership_id
  )
  SELECT file.id, file.bucket, file.object_key
  FROM files file
  CROSS JOIN member
  WHERE file.account_id = p_account_id
    AND (
      file.workspace_id = member.personal_workspace_id
      OR file.id IN (SELECT owned.file_id FROM owned_document_files owned)
    )
    AND NOT EXISTS (
      SELECT 1
      FROM documents other
      LEFT JOIN organization_user_resource_authorities other_authority
        ON other_authority.id = other.authority_id
       AND other_authority.account_id = other.account_id
       AND other_authority.organization_membership_id = other.owner_organization_membership_id
       AND other_authority.resource_kind = 'document'
       AND other_authority.resource_id = other.id
      WHERE other.file_id = file.id
        AND (
          other_authority.id IS NULL
          OR other_authority.account_id <> p_account_id
          OR other_authority.organization_membership_id <> p_membership_id
        )
    )
  ORDER BY file.id
$$;

CREATE FUNCTION opengeni_private.organization_retention_object_candidates(p_account_id uuid, p_membership_id uuid) RETURNS TABLE(object_kind text, source_id text, object_bucket text, object_key text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  WITH authority_context AS MATERIALIZED (
    SELECT opengeni_private.assert_organization_retention_account(p_account_id)
  ), member AS (
    SELECT membership.personal_workspace_id
    FROM organization_memberships membership
    CROSS JOIN authority_context
    WHERE membership.account_id = p_account_id
      AND membership.id = p_membership_id
  )
  SELECT 'file'::text, candidate.file_id::text, candidate.object_bucket, candidate.object_key
  FROM opengeni_private.organization_retention_file_candidates(
    p_account_id, p_membership_id
  ) candidate
  UNION ALL
  SELECT 'session_recording', recording.id::text, NULL::text, recording.storage_key
  FROM session_recordings recording CROSS JOIN member
  WHERE recording.account_id = p_account_id
    AND recording.workspace_id = member.personal_workspace_id
    AND recording.storage_key IS NOT NULL
  UNION ALL
  SELECT 'browser_state_artifact', artifact.id::text, NULL::text, artifact.object_key
  FROM browser_state_artifacts artifact CROSS JOIN member
  WHERE artifact.account_id = p_account_id
    AND artifact.workspace_id = member.personal_workspace_id
    AND artifact.state <> 'deleted'
  UNION ALL
  SELECT 'browser_state_upload', upload.id::text, NULL::text, upload.object_key
  FROM browser_state_uploads upload CROSS JOIN member
  WHERE upload.account_id = p_account_id
    AND upload.workspace_id = member.personal_workspace_id
    AND upload.state <> 'deleted'
    AND (
      upload.state <> 'committed'
      OR NOT EXISTS (
        SELECT 1
        FROM browser_state_artifacts committed
        WHERE committed.account_id = upload.account_id
          AND committed.workspace_id = upload.workspace_id
          AND committed.id = upload.committed_artifact_id
          AND committed.object_key = upload.object_key
          AND committed.state <> 'deleted'
      )
    )
  UNION ALL
  SELECT 'transcription_recording_object',
    recording_object.recording_id::text || ':' || encode(
      digest(recording_object.object_key, 'sha256'), 'hex'
    ),
    NULL::text,
    recording_object.object_key
  FROM transcription_recording_objects recording_object CROSS JOIN member
  WHERE recording_object.account_id = p_account_id
    AND recording_object.workspace_id = member.personal_workspace_id
    AND recording_object.cleaned_at IS NULL
  UNION ALL
  SELECT 'video_staging_reference',
    reference.operation_id::text || ':' || reference.ordinal::text,
    NULL::text,
    reference.staging_object_key
  FROM video_generation_references reference CROSS JOIN member
  WHERE reference.account_id = p_account_id
    AND reference.workspace_id = member.personal_workspace_id
    AND reference.staging_object_key IS NOT NULL
    AND reference.cleaned_at IS NULL
  UNION ALL
  SELECT 'workspace_artifact_version', version.id::text, NULL::text, version.content_key
  FROM workspace_artifact_versions version CROSS JOIN member
  WHERE version.account_id = p_account_id
    AND version.workspace_id = member.personal_workspace_id
  UNION ALL
  SELECT 'editable_artifact_blob',
    blob.artifact_id || ':' || blob.id,
    NULL::text,
    blob.object_reference
  FROM editable_artifact_blob_refs blob CROSS JOIN member
  WHERE blob.account_id = p_account_id
    AND blob.workspace_id = member.personal_workspace_id
  UNION ALL
  SELECT 'workspace_capture_manifest', capture.id::text, NULL::text, capture.manifest_key
  FROM workspace_captures capture CROSS JOIN member
  WHERE capture.account_id = p_account_id
    AND capture.workspace_id = member.personal_workspace_id
    AND capture.manifest_key IS NOT NULL
  UNION ALL
  SELECT 'workspace_capture_tree_index', capture.id::text, NULL::text, capture.tree_index_key
  FROM workspace_captures capture CROSS JOIN member
  WHERE capture.account_id = p_account_id
    AND capture.workspace_id = member.personal_workspace_id
    AND capture.tree_index_key IS NOT NULL
  UNION ALL
  SELECT 'workspace_capture_blob',
    capture.id::text || ':' || blob.ordinality::text,
    NULL::text,
    blob.value #>> '{}'
  FROM workspace_captures capture CROSS JOIN member
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE WHEN jsonb_typeof(capture.blob_keys) = 'array'
      THEN capture.blob_keys ELSE '[]'::jsonb END
  ) WITH ORDINALITY AS blob(value, ordinality)
  WHERE capture.account_id = p_account_id
    AND capture.workspace_id = member.personal_workspace_id
    AND jsonb_typeof(blob.value) = 'string'
  ORDER BY 1, 2
$$;

CREATE FUNCTION opengeni_private.organization_subscription_model_scope_visible(p_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  workspace_value uuid := opengeni_private.current_workspace_id();
  visible boolean := false;
  previous_lifecycle text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  IF p_account_id IS NULL
    OR workspace_value IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN RETURN false; END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT EXISTS (
    SELECT 1 FROM public.workspaces workspace
    WHERE workspace.account_id = p_account_id AND workspace.id = workspace_value
  ) INTO visible;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RETURN coalesce(visible, false);
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

CREATE FUNCTION opengeni_private.organization_tenancy_inventory_capability_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM opengeni_private.organization_tenancy_inventory_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
  )
$$;

CREATE FUNCTION opengeni_private.organization_tenancy_parity_capability_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM opengeni_private.organization_tenancy_parity_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
  )
$$;

CREATE FUNCTION opengeni_private.organization_usage_summary(p_account_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_granularity text, p_after_workspace_id uuid, p_include_period boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    SET enable_nestloop TO 'off'
    AS $$
    DECLARE
      context_account_id uuid;
      context_subject_id text;
      context_human_id text;
      page_ids uuid[];
      next_cursor uuid;
      personal_workspace_ids uuid[] := '{}'::uuid[];
      personal_membership_ids uuid[] := '{}'::uuid[];
      previous_lifecycle text; inventory uuid;
      response jsonb;
    BEGIN
      PERFORM opengeni_private.session_variable_set_attachments_protocol_v1_active();
      BEGIN
        context_account_id := nullif(current_setting('opengeni.account_id', true), '')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Organization usage account context is malformed' USING ERRCODE = '42501';
      END;
      context_subject_id := nullif(current_setting('opengeni.subject_id', true), '');
      context_human_id := nullif(current_setting('opengeni.initiating_human_subject_id', true), '');
      IF context_account_id IS NULL OR context_account_id IS DISTINCT FROM p_account_id
        OR nullif(current_setting('opengeni.workspace_id', true), '') IS NOT NULL
      THEN
        RAISE EXCEPTION 'Organization usage requires the exact account-only context' USING ERRCODE = '42501';
      END IF;
      IF p_since IS NULL OR p_until IS NULL OR NOT isfinite(p_since) OR NOT isfinite(p_until)
        OR p_until < p_since OR p_until - p_since > interval '366 days'
        OR p_granularity IS NULL OR p_granularity NOT IN ('hour', 'day')
        OR (p_granularity = 'hour' AND p_until - p_since > interval '1 day')
        OR p_include_period IS NULL
      THEN
        RAISE EXCEPTION 'Organization usage window or granularity is invalid' USING ERRCODE = '22023';
      END IF;
      -- Match listSharedWorkspacesForAccount: canonical membership pointers
      -- exclude EVERY Personal workspace before lookahead/cursor selection.
      -- Names, kind guesses and caller-owned Personal exceptions are forbidden.
      SELECT coalesce(array_agg(id ORDER BY id), '{}'::uuid[]) INTO page_ids
      FROM (SELECT id FROM {{schema}}.workspaces
        WHERE account_id = context_account_id
          AND id IN (SELECT workspace_id FROM {{schema}}.list_organization_workspace_ids(context_account_id))
          AND (p_after_workspace_id IS NULL OR id > p_after_workspace_id)
        ORDER BY id LIMIT 51) page;
      IF cardinality(page_ids) > 50 THEN
        next_cursor := page_ids[50];
        page_ids := page_ids[1:50];
      END IF;

      -- Personal rows come only with the period view. The same canonical
      -- pointers classify them, read through the membership-lifecycle policy
      -- that list_organization_workspace_ids uses, restored before any usage
      -- fact is read.
      IF p_include_period THEN
        previous_lifecycle := current_setting('opengeni.organization_tenancy_lifecycle', true);
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
        BEGIN
          SELECT coalesce(array_agg(membership.personal_workspace_id ORDER BY membership.id), '{}'::uuid[]),
            coalesce(array_agg(membership.id ORDER BY membership.id), '{}'::uuid[])
          INTO personal_workspace_ids, personal_membership_ids
          FROM {{schema}}.organization_memberships membership
          JOIN {{schema}}.workspaces workspace
            ON workspace.id = membership.personal_workspace_id
            AND workspace.account_id = context_account_id
          WHERE membership.account_id = context_account_id
            AND membership.personal_workspace_id IS NOT NULL;
        EXCEPTION WHEN OTHERS THEN
          PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true);
          RAISE;
        END;
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true);
      END IF;

      inventory := opengeni_private.open_session_tenancy_fence_inventory(session_tenancy_fence_target_schema());
      INSERT INTO opengeni_private.organization_usage_read_capabilities
        (backend_pid, transaction_id, account_id, subject_id, initiating_human_subject_id)
      VALUES (pg_backend_pid(), pg_current_xact_id(), context_account_id, context_subject_id, context_human_id);
      BEGIN
        WITH visible AS NOT MATERIALIZED (
          SELECT usage_row.workspace_id, usage_row.event_type, usage_row.unit, usage_row.quantity,
            CASE WHEN p_include_period THEN date_trunc(p_granularity, usage_row.occurred_at AT TIME ZONE 'UTC') END AS bucket
          FROM {{schema}}.usage_events usage_row
          
          WHERE usage_row.account_id = context_account_id
            AND usage_row.occurred_at >= p_since AND usage_row.occurred_at < p_until
            AND (p_include_period OR usage_row.workspace_id = ANY(page_ids))
            
        ), aggregates AS MATERIALIZED (
          SELECT workspace_id, bucket, grouping(workspace_id) AS all_workspaces,
            grouping(bucket) AS all_buckets,
            jsonb_build_object('eventType', event_type, 'unit', unit,
              'quantity', sum(quantity)::text, 'eventCount', count(*)::text) AS total
          FROM visible GROUP BY GROUPING SETS
            ((event_type, unit), (bucket, event_type, unit), (workspace_id, event_type, unit))
        ), bucket_rows AS (
          SELECT to_char(bucket, CASE WHEN p_granularity = 'hour' THEN 'YYYY-MM-DD"T"HH24:00' ELSE 'YYYY-MM-DD' END) AS bucket,
            jsonb_agg(total ORDER BY total->>'eventType', total->>'unit') AS totals
          FROM aggregates WHERE all_buckets = 0 AND p_include_period GROUP BY bucket
        ), workspace_rows AS (
          SELECT workspace_id, jsonb_agg(total ORDER BY total->>'eventType', total->>'unit') AS totals
          FROM aggregates WHERE all_workspaces = 0 AND workspace_id = ANY(page_ids) GROUP BY workspace_id
        ), personal_rows AS MATERIALIZED (
          -- Only Personal workspaces with visible usage in the window. Ranked
          -- by spend, then tokens, so a bounded list keeps the largest.
          SELECT pointer.membership_id,
            jsonb_agg(aggregate_row.total ORDER BY aggregate_row.total->>'eventType', aggregate_row.total->>'unit') AS totals,
            coalesce(sum((aggregate_row.total->>'quantity')::numeric) FILTER (
              WHERE aggregate_row.total->>'eventType' = 'model.cost' AND aggregate_row.total->>'unit' = 'usd_micros'), 0) AS spend,
            coalesce(sum((aggregate_row.total->>'quantity')::numeric) FILTER (
              WHERE aggregate_row.total->>'eventType' = 'model.tokens'), 0) AS tokens
          FROM unnest(personal_workspace_ids, personal_membership_ids) AS pointer(workspace_id, membership_id)
          JOIN aggregates aggregate_row
            ON aggregate_row.all_workspaces = 0 AND aggregate_row.all_buckets = 1
            AND aggregate_row.workspace_id = pointer.workspace_id
          WHERE p_include_period
          GROUP BY pointer.membership_id
        )
        SELECT jsonb_build_object(
          'totals', CASE WHEN p_include_period THEN coalesce((SELECT jsonb_agg(total ORDER BY total->>'eventType', total->>'unit')
            FROM aggregates WHERE all_workspaces = 1 AND all_buckets = 1), '[]'::jsonb) ELSE NULL END,
          'buckets', CASE WHEN p_include_period THEN coalesce((SELECT jsonb_agg(jsonb_build_object('bucket', bucket, 'totals', totals) ORDER BY bucket)
            FROM bucket_rows), '[]'::jsonb) ELSE NULL END,
          'workspaces', coalesce((SELECT jsonb_agg(jsonb_build_object('workspaceId', w.id, 'name', w.name,
            'totals', coalesce(r.totals, '[]'::jsonb)) ORDER BY w.id)
            FROM {{schema}}.workspaces w LEFT JOIN workspace_rows r ON r.workspace_id = w.id
            WHERE w.account_id = context_account_id AND w.id = ANY(page_ids)), '[]'::jsonb),
          'nextWorkspaceCursor', next_cursor,
          'personalWorkspaces', CASE WHEN p_include_period THEN coalesce((
            SELECT jsonb_agg(jsonb_build_object('membershipId', ranked.membership_id, 'totals', ranked.totals)
              ORDER BY ranked.spend DESC, ranked.tokens DESC, ranked.membership_id)
            FROM (SELECT membership_id, totals, spend, tokens FROM personal_rows
              ORDER BY spend DESC, tokens DESC, membership_id LIMIT 50) ranked), '[]'::jsonb) ELSE NULL END,
          'personalWorkspaceCount', CASE WHEN p_include_period THEN (SELECT count(*) FROM personal_rows) ELSE NULL END
        ) INTO response;

        
      IF p_include_period THEN
        previous_lifecycle := current_setting('opengeni.organization_tenancy_lifecycle', true);
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
        BEGIN
        WITH private_sessions AS MATERIALIZED (
          SELECT session_row.id, session_row.workspace_id, session_row.owner_subject_id,
            session_row.owner_organization_membership_id
          FROM {{schema}}.sessions session_row
          WHERE session_row.account_id = context_account_id
            AND session_row.workspace_id IN (
              SELECT workspace_id FROM {{schema}}.list_organization_workspace_ids(context_account_id)
            )
            AND context_subject_id IS NOT NULL AND session_row.visibility = 'user_private'
            AND NOT {{schema}}.session_private_actor_visible(session_row.account_id, session_row.workspace_id,
              session_row.owner_organization_membership_id, session_row.owner_subject_id)
        ), usage_by_session AS MATERIALIZED (
          SELECT usage_row.workspace_id, usage_row.session_id, usage_row.event_type, usage_row.unit,
            sum(usage_row.quantity) AS quantity, count(*) AS event_count
          FROM {{schema}}.usage_events usage_row
          JOIN private_sessions matched_session ON matched_session.id = usage_row.session_id
            AND matched_session.workspace_id = usage_row.workspace_id
          WHERE usage_row.account_id = context_account_id
            AND usage_row.occurred_at >= p_since AND usage_row.occurred_at < p_until
          GROUP BY usage_row.workspace_id, usage_row.session_id, usage_row.event_type, usage_row.unit
        ), owner_totals AS (
          SELECT session_row.workspace_id, session_row.owner_subject_id,
            session_row.owner_organization_membership_id AS membership_id,
            usage_row.event_type, usage_row.unit, sum(usage_row.quantity) AS quantity,
            sum(usage_row.event_count) AS event_count
          FROM usage_by_session usage_row JOIN private_sessions session_row ON session_row.id = usage_row.session_id
            AND session_row.workspace_id = usage_row.workspace_id
          GROUP BY session_row.workspace_id, session_row.owner_subject_id,
            session_row.owner_organization_membership_id, usage_row.event_type, usage_row.unit
        ), owners AS MATERIALIZED (
          SELECT owner_row.workspace_id, owner_row.owner_subject_id, owner_row.membership_id,
            coalesce(auth_user.name, access.subject_label) AS name,
            jsonb_agg(jsonb_build_object('eventType', event_type, 'unit', unit,
              'quantity', quantity::text, 'eventCount', event_count::text) ORDER BY event_type, unit) AS totals,
            coalesce(sum(quantity) FILTER (WHERE event_type = 'model.cost' AND unit = 'usd_micros'), 0) AS spend
          FROM owner_totals owner_row
          LEFT JOIN {{schema}}.workspace_memberships access ON access.account_id = context_account_id
            AND access.workspace_id = owner_row.workspace_id AND access.subject_id = owner_row.owner_subject_id
          LEFT JOIN {{schema}}.auth_users auth_user ON access.subject_id = 'user:' || auth_user.id
          GROUP BY owner_row.workspace_id, owner_row.owner_subject_id, owner_row.membership_id,
            auth_user.name, access.subject_label
        )
        SELECT response || jsonb_build_object(
          'privateChats', coalesce((SELECT jsonb_agg(jsonb_build_object(
            'workspaceId', workspace_id, 'membershipId', membership_id, 'name', name, 'totals', totals
          ) ORDER BY spend DESC, workspace_id, membership_id, owner_subject_id)
          FROM (SELECT * FROM owners ORDER BY spend DESC, workspace_id, membership_id, owner_subject_id LIMIT 200) listed), '[]'::jsonb),
          'privateChatsTruncated', (SELECT count(*) > 200 FROM owners)
        ) INTO response;
        EXCEPTION WHEN OTHERS THEN
          PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true);
          RAISE;
        END;
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true);
      END IF;
  
        DELETE FROM opengeni_private.organization_usage_read_capabilities
          WHERE backend_pid = pg_backend_pid() AND transaction_id = pg_current_xact_id_if_assigned();
        PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory);
        RETURN response;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.organization_usage_read_capabilities
          WHERE backend_pid = pg_backend_pid() AND transaction_id = pg_current_xact_id_if_assigned();
        PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory);
        RAISE;
      END;
    END
    $$;

CREATE TABLE organization_user_setup_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    invitation_id uuid NOT NULL,
    invitation_operation_id uuid NOT NULL,
    created_by_membership_id uuid NOT NULL,
    setup_intent_id uuid,
    provider_key text NOT NULL,
    recipient_email text NOT NULL,
    recipient_name text,
    organization_name text NOT NULL,
    organization_role text NOT NULL,
    shared_workspace_access jsonb DEFAULT '[]'::jsonb NOT NULL,
    token_digest text,
    payload_digest text,
    state text DEFAULT 'pending'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    claim_holder_id uuid,
    claim_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    provider_idempotency_scope text,
    provider_retry_safe_until timestamp with time zone,
    provider_retry_window_started_at timestamp with time zone,
    provider_started_at timestamp with time zone,
    unresolved_provider_outcome_at timestamp with time zone,
    error_class text,
    provider_message_id text,
    sent_at timestamp with time zone,
    failed_at timestamp with time zone,
    outcome_unknown_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    setup_token_transport text,
    CONSTRAINT organization_user_setup_deliveries_bounds_check CHECK (((recipient_email = lower(btrim(recipient_email))) AND ((octet_length(convert_to(recipient_email, 'UTF8'::name)) >= 3) AND (octet_length(convert_to(recipient_email, 'UTF8'::name)) <= 320)) AND ((recipient_name IS NULL) OR ((octet_length(convert_to(recipient_name, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(recipient_name, 'UTF8'::name)) <= 120))) AND ((octet_length(convert_to(organization_name, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(organization_name, 'UTF8'::name)) <= 120)) AND ((octet_length(convert_to(provider_key, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(provider_key, 'UTF8'::name)) <= 200)) AND ((provider_idempotency_scope IS NULL) OR (((octet_length(convert_to(provider_idempotency_scope, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(provider_idempotency_scope, 'UTF8'::name)) <= 200)) AND (provider_idempotency_scope ~ '^[a-z0-9][a-z0-9:._-]*$'::text))) AND (jsonb_typeof(shared_workspace_access) = 'array'::text) AND (jsonb_array_length(shared_workspace_access) <= 100) AND ((error_class IS NULL) OR ((octet_length(convert_to(error_class, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(error_class, 'UTF8'::name)) <= 64))) AND ((provider_message_id IS NULL) OR ((octet_length(convert_to(provider_message_id, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(provider_message_id, 'UTF8'::name)) <= 255))) AND (attempt_count >= 0) AND (revision > 0))),
    CONSTRAINT organization_user_setup_deliveries_claim_check CHECK ((((claim_holder_id IS NULL) AND (claim_expires_at IS NULL)) OR ((claim_holder_id IS NOT NULL) AND (claim_expires_at IS NOT NULL)))),
    CONSTRAINT organization_user_setup_deliveries_digest_check CHECK ((((token_digest IS NULL) OR (token_digest ~ '^[0-9a-f]{64}$'::text)) AND ((payload_digest IS NULL) OR (payload_digest ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT organization_user_setup_deliveries_provider_fence_check CHECK ((((provider_idempotency_scope IS NULL) AND (provider_retry_safe_until IS NULL) AND (provider_retry_window_started_at IS NULL)) OR ((provider_idempotency_scope IS NOT NULL) AND (provider_retry_safe_until IS NOT NULL) AND (provider_retry_window_started_at IS NOT NULL) AND (provider_retry_safe_until >= provider_retry_window_started_at)))),
    CONSTRAINT organization_user_setup_deliveries_role_check CHECK ((organization_role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text]))),
    CONSTRAINT organization_user_setup_deliveries_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text, 'outcome_unknown'::text, 'revoked'::text]))),
    CONSTRAINT organization_user_setup_deliveries_terminal_check CHECK ((((state = 'pending'::text) AND (sent_at IS NULL) AND (failed_at IS NULL) AND (outcome_unknown_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'sent'::text) AND (sent_at IS NOT NULL) AND (failed_at IS NULL) AND (outcome_unknown_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'failed'::text) AND (sent_at IS NULL) AND (failed_at IS NOT NULL) AND (outcome_unknown_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'outcome_unknown'::text) AND (sent_at IS NULL) AND (failed_at IS NULL) AND (outcome_unknown_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((state = 'revoked'::text) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT organization_user_setup_deliveries_token_transport_check CHECK (((setup_token_transport IS NULL) OR (setup_token_transport = ANY (ARRAY['fragment'::text, 'query'::text])))),
    CONSTRAINT organization_user_setup_deliveries_unresolved_outcome_check CHECK (((unresolved_provider_outcome_at IS NULL) OR ((provider_idempotency_scope IS NOT NULL) AND (state = ANY (ARRAY['pending'::text, 'outcome_unknown'::text])))))
);

ALTER TABLE ONLY organization_user_setup_deliveries FORCE ROW LEVEL SECURITY;

COMMENT ON TABLE organization_user_setup_deliveries IS 'Digest-only durable projection for invitation setup email claims, stable provider identity, and reconciliation.';

COMMENT ON COLUMN organization_user_setup_deliveries.setup_token_transport IS 'Fragment or query transport frozen at first preparation; NULL only for rolling old-binary rows pending digest recovery.';

CREATE FUNCTION opengeni_private.organization_user_setup_delivery_json(p_delivery organization_user_setup_deliveries) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT pg_catalog.jsonb_build_object(
    'id', p_delivery.id,
    'state', CASE
      WHEN p_delivery.state = 'pending'
        AND p_delivery.claim_expires_at <= pg_catalog.clock_timestamp()
      THEN CASE
        WHEN p_delivery.provider_started_at IS NULL
          AND p_delivery.unresolved_provider_outcome_at IS NULL
        THEN 'failed'
        ELSE 'outcome_unknown'
      END
      ELSE p_delivery.state
    END,
    'attemptCount', p_delivery.attempt_count,
    'revision', p_delivery.revision,
    'errorClass', CASE
      WHEN p_delivery.state = 'pending'
        AND p_delivery.claim_expires_at <= pg_catalog.clock_timestamp()
      THEN CASE
        WHEN p_delivery.provider_started_at IS NULL
          AND p_delivery.unresolved_provider_outcome_at IS NULL
        THEN 'claim_expired_before_provider'
        WHEN p_delivery.provider_started_at IS NULL
        THEN 'prior_provider_outcome_unresolved'
        ELSE 'provider_started_claim_expired'
      END
      ELSE p_delivery.error_class
    END,
    'retryState', CASE
      WHEN p_delivery.state = 'failed' THEN 'available'
      WHEN p_delivery.state = 'pending'
        AND p_delivery.claim_expires_at <= pg_catalog.clock_timestamp()
        AND p_delivery.provider_started_at IS NULL
        AND p_delivery.unresolved_provider_outcome_at IS NULL
      THEN 'available'
      WHEN (
        p_delivery.state = 'outcome_unknown'
        OR (
          p_delivery.state = 'pending'
          AND p_delivery.claim_expires_at <= pg_catalog.clock_timestamp()
          AND (
            p_delivery.provider_started_at IS NOT NULL
            OR p_delivery.unresolved_provider_outcome_at IS NOT NULL
          )
        )
      )
      THEN CASE
        WHEN p_delivery.provider_retry_safe_until IS NOT NULL
          AND p_delivery.provider_retry_safe_until > pg_catalog.clock_timestamp()
        THEN 'available'
        ELSE 'reconciliation_required'
      END
      ELSE 'unavailable'
    END,
    'sentAt', p_delivery.sent_at,
    'updatedAt', p_delivery.updated_at
  )
$$;

CREATE FUNCTION opengeni_private.pause_private_scheduled_task(p_account uuid, p_workspace uuid, p_exclude_owner text, p_task uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      a uuid;
      w uuid;
      subject_value text := nullif(current_setting('opengeni.subject_id', true), '');
      human_value text := nullif(current_setting('opengeni.initiating_human_subject_id', true), '');
      found_task boolean;
    BEGIN
      BEGIN
        a := nullif(current_setting('opengeni.account_id', true), '')::uuid;
        w := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Private schedule pause scope malformed' USING ERRCODE = '42501';
      END;
      IF a IS NULL OR a IS DISTINCT FROM p_account OR w IS NULL OR w IS DISTINCT FROM p_workspace
        OR p_task IS NULL THEN
        RAISE EXCEPTION 'Private schedule pause requires exact scope' USING ERRCODE = '42501';
      END IF;
      -- The same workspace mutation fence every schedule writer takes.
      PERFORM {{schema}}.acquire_session_tenancy_fence(w);
      INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities
        (backend_pid, transaction_id, capability_kind, account_id, workspace_id, subject_id, initiating_human_subject_id)
      VALUES
        (pg_backend_pid(), pg_current_xact_id(), 'private_scheduled_task_summary', a, w, subject_value, human_value);
      BEGIN
        UPDATE {{schema}}.scheduled_tasks task SET status = 'paused', updated_at = now()
          WHERE task.account_id = a AND task.workspace_id = w AND task.id = p_task
            AND task.deleted_at IS NULL AND task.visibility = 'user_private'
            AND task.owner_subject_id IS NOT NULL
            AND task.owner_subject_id IS DISTINCT FROM p_exclude_owner
            AND task.status IS DISTINCT FROM 'paused';
        SELECT EXISTS (
          SELECT 1 FROM {{schema}}.scheduled_tasks task
          WHERE task.account_id = a AND task.workspace_id = w AND task.id = p_task
            AND task.deleted_at IS NULL AND task.visibility = 'user_private'
            AND task.owner_subject_id IS NOT NULL
            AND task.owner_subject_id IS DISTINCT FROM p_exclude_owner
        ) INTO found_task;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
          WHERE backend_pid = pg_backend_pid() AND transaction_id = pg_current_xact_id_if_assigned()
            AND capability_kind = 'private_scheduled_task_summary';
        RAISE;
      END;
      DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
        WHERE backend_pid = pg_backend_pid() AND transaction_id = pg_current_xact_id_if_assigned()
          AND capability_kind = 'private_scheduled_task_summary';
      RETURN found_task;
    END
    $$;

CREATE FUNCTION opengeni_private.persist_subscription_codex_apps_refresh(p_account_id uuid, p_workspace_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_credential_encrypted text, p_expires_at timestamp with time zone, p_last_refresh_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET lock_timeout TO '0'
    AS $_$
    DECLARE
      write_minted boolean := false;
      refresh_persisted boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
        OR p_credential_encrypted IS NULL
        OR p_credential_encrypted !~ '^v[12]:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+$'
        OR p_last_refresh_at IS NULL
      THEN RETURN false; END IF;
      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'codex_apps_refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = 'codex';
      IF NOT FOUND THEN RETURN false; END IF;
      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        connection_id, provider
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'codex_refresh_write',
        p_account_id, p_workspace_id, p_connection_id, 'codex'
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      UPDATE subscription_connections
      SET credential_encrypted = p_credential_encrypted,
          credential_format = split_part(p_credential_encrypted, ':', 1),
          expires_at = p_expires_at,
          last_refresh_at = p_last_refresh_at,
          refresh_generation = subscription_connections.refresh_generation + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = 'codex' AND kind = 'subscription'
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      refresh_persisted := FOUND;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'codex_refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN refresh_persisted;
    END
    $_$;

CREATE FUNCTION opengeni_private.persist_subscription_core_connection_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_credential_encrypted text, p_expires_at timestamp with time zone, p_last_refresh_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET lock_timeout TO '0'
    AS $_$
    DECLARE
      write_minted boolean := false;
      refresh_persisted boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
        OR p_credential_encrypted IS NULL
        OR p_credential_encrypted !~ '^v[12]:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+$'
        OR p_last_refresh_at IS NULL
      THEN RETURN false; END IF;
      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'connection_refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = p_provider;
      IF NOT FOUND THEN RETURN false; END IF;
      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        connection_id, provider
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'refresh_write',
        p_account_id, p_workspace_id, p_connection_id, p_provider
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      UPDATE subscription_connections
      SET credential_encrypted = p_credential_encrypted,
          
          expires_at = p_expires_at,
          last_refresh_at = p_last_refresh_at,
          refresh_generation = subscription_connections.refresh_generation + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = p_provider AND kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      refresh_persisted := FOUND;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN refresh_persisted;
    END
    $_$;

CREATE FUNCTION opengeni_private.persist_subscription_core_refresh(p_provider text, p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_credential_encrypted text, p_expires_at timestamp with time zone, p_last_refresh_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET lock_timeout TO '0'
    AS $_$
    DECLARE
      capability_owner text;
      capability_human text;
      write_minted boolean := false;
      refresh_persisted boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL OR p_session_id IS NULL OR p_turn_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
        OR p_credential_encrypted IS NULL
        OR p_credential_encrypted !~ '^v[12]:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+$'
        OR p_last_refresh_at IS NULL
      THEN RETURN false; END IF;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.session_id = p_session_id
        AND capability.turn_id = p_turn_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = p_provider
      RETURNING capability.session_owner_subject_id, capability.turn_human_subject_id
        INTO capability_owner, capability_human;
      IF NOT FOUND THEN RETURN false; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        session_id, turn_id, connection_id, provider,
        session_owner_subject_id, turn_human_subject_id
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'refresh_write',
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_connection_id, p_provider,
        capability_owner, capability_human
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      UPDATE subscription_connections
      SET credential_encrypted = p_credential_encrypted,
          
          expires_at = p_expires_at,
          last_refresh_at = p_last_refresh_at,
          refresh_generation = subscription_connections.refresh_generation + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = p_provider AND kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      refresh_persisted := FOUND;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN refresh_persisted;
    END
    $_$;

CREATE FUNCTION opengeni_private.persist_subscription_core_refresh_with_plan(p_provider text, p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_connection_id uuid, p_expected_refresh_generation bigint, p_credential_encrypted text, p_expires_at timestamp with time zone, p_last_refresh_at timestamp with time zone, p_plan_type text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET lock_timeout TO '0'
    AS $_$
    DECLARE
      capability_owner text;
      capability_human text;
      write_minted boolean := false;
      refresh_persisted boolean := false;
      plan_value text := nullif(btrim(coalesce(p_plan_type, '')), '');
      previous_plan text;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_connection_id IS NULL OR p_session_id IS NULL OR p_turn_id IS NULL
        OR p_expected_refresh_generation IS NULL OR p_expected_refresh_generation < 1
        OR p_credential_encrypted IS NULL
        OR p_credential_encrypted !~ '^v[12]:[A-Za-z0-9+/=]+:[A-Za-z0-9+/=]+$'
        OR p_last_refresh_at IS NULL
        OR (plan_value IS NOT NULL AND (length(plan_value) > 64 OR plan_value !~ '^[A-Za-z0-9_.-]+$'))
      THEN RETURN false; END IF;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_authorized'
        AND capability.account_id = p_account_id
        AND capability.workspace_id = p_workspace_id
        AND capability.session_id = p_session_id
        AND capability.turn_id = p_turn_id
        AND capability.connection_id = p_connection_id
        AND capability.provider = p_provider
      RETURNING capability.session_owner_subject_id, capability.turn_human_subject_id
        INTO capability_owner, capability_human;
      IF NOT FOUND THEN RETURN false; END IF;

      INSERT INTO opengeni_private.subscription_runtime_capabilities (
        backend_pid, transaction_id, capability_kind, account_id, workspace_id,
        session_id, turn_id, connection_id, provider,
        session_owner_subject_id, turn_human_subject_id
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'refresh_write',
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_connection_id, p_provider,
        capability_owner, capability_human
      ) ON CONFLICT (backend_pid, transaction_id, capability_kind, account_id, connection_id)
        DO NOTHING
      RETURNING true INTO write_minted;
      IF write_minted IS DISTINCT FROM true THEN RETURN false; END IF;

      SELECT connection.plan_type INTO previous_plan
      FROM subscription_connections connection
      WHERE connection.account_id = p_account_id AND connection.id = p_connection_id
        AND connection.provider = p_provider;

      UPDATE subscription_connections
      SET credential_encrypted = p_credential_encrypted,
          
          expires_at = p_expires_at,
          last_refresh_at = p_last_refresh_at,
          plan_type = coalesce(plan_value, subscription_connections.plan_type),
          refresh_generation = subscription_connections.refresh_generation + 1,
          updated_at = pg_catalog.clock_timestamp()
      WHERE account_id = p_account_id AND id = p_connection_id
        AND provider = p_provider AND kind = opengeni_private.subscription_core_connection_kind(p_provider)
        AND subscription_connections.refresh_generation = p_expected_refresh_generation;
      refresh_persisted := FOUND;

      IF refresh_persisted AND plan_value IS NOT NULL AND previous_plan IS NOT NULL
        AND plan_value IS DISTINCT FROM previous_plan
      THEN
        UPDATE subscription_connection_quota quota
        SET quota = pg_catalog.jsonb_set(quota.quota, '{modelCooldowns}', '{}'::jsonb),
            revision = quota.revision + 1
        WHERE quota.account_id = p_account_id AND quota.connection_id = p_connection_id
          AND pg_catalog.jsonb_typeof(quota.quota->'modelCooldowns') = 'object'
          AND quota.quota->'modelCooldowns' <> '{}'::jsonb;
      END IF;

      DELETE FROM opengeni_private.subscription_runtime_capabilities capability
      WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
        AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability.capability_kind = 'refresh_write'
        AND capability.account_id = p_account_id
        AND capability.connection_id = p_connection_id;
      RETURN refresh_persisted;
    END
    $_$;

CREATE FUNCTION opengeni_private.personal_document_authority_capability_active(p_capability_kind text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM opengeni_private.personal_document_authority_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND (
        p_capability_kind IS NULL
        OR capability.capability_kind = p_capability_kind
      )
  )
$$;

