$$;

CREATE FUNCTION opengeni_private.plan_general_balance(p_account_id uuid) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
  SELECT coalesce(sum(amount_micros), 0) - coalesce((
    SELECT sum(grant_row.amount_micros - coalesce(allocated.amount, 0))
    FROM credit_ledger_entries grant_row LEFT JOIN LATERAL (
      SELECT sum(amount_micros) amount FROM credit_debit_allocations
      WHERE account_id = p_account_id AND grant_entry_id = grant_row.id
    ) allocated ON true
    WHERE grant_row.account_id = p_account_id AND grant_row.eligible_model_ids IS NOT NULL
      AND grant_row.amount_micros > coalesce(allocated.amount, 0)
  ), 0) FROM credit_ledger_entries WHERE account_id = p_account_id
$$;

CREATE TABLE plan_credit_periods (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    plan_key text NOT NULL,
    catalog_revision bigint NOT NULL,
    stripe_subscription_id text,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    granted_micros bigint NOT NULL,
    opening_debt_micros bigint NOT NULL,
    grant_entry_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    granted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expired_at timestamp with time zone,
    expiry_entry_id uuid,
    usage_at_expiry_micros bigint,
    CONSTRAINT plan_credit_period_bounds CHECK ((isfinite(period_start) AND isfinite(period_end) AND (period_end > period_start))),
    CONSTRAINT plan_credit_period_expiry CHECK ((((expired_at IS NULL) AND (expiry_entry_id IS NULL) AND (usage_at_expiry_micros IS NULL)) OR ((expired_at IS NOT NULL) AND (expiry_entry_id IS NOT NULL) AND (usage_at_expiry_micros IS NOT NULL)))),
    CONSTRAINT plan_credit_periods_granted_micros_check CHECK ((granted_micros >= 0)),
    CONSTRAINT plan_credit_periods_opening_debt_check CHECK (((opening_debt_micros >= 0) AND (opening_debt_micros <= granted_micros)))
);

ALTER TABLE ONLY plan_credit_periods FORCE ROW LEVEL SECURITY;

CREATE FUNCTION opengeni_private.plan_period_usage(p_period plan_credit_periods, p_until timestamp with time zone) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM credit_ledger_entries
    WHERE id = p_period.grant_entry_id AND eligible_model_ids IS NOT NULL)
  THEN (SELECT coalesce(sum(a.amount_micros), 0)::bigint
    FROM credit_debit_allocations a JOIN credit_ledger_entries debit ON debit.id = a.debit_entry_id
    WHERE a.account_id = p_period.account_id AND a.grant_entry_id = p_period.grant_entry_id
      AND debit.type <> 'plan_credit_expiry'
      AND debit.created_at < least(p_period.period_end, p_until))
  ELSE (
    SELECT greatest(0, coalesce(sum(-entry.amount_micros - coalesce(allocated.amount, 0)), 0))::bigint
    FROM credit_ledger_entries entry
    LEFT JOIN LATERAL (SELECT sum(amount_micros) amount FROM credit_debit_allocations
      WHERE account_id = entry.account_id AND debit_entry_id = entry.id) allocated ON true
    WHERE entry.account_id = p_period.account_id
      AND entry.created_at >= greatest(p_period.period_start, p_period.granted_at)
      AND entry.created_at < least(p_period.period_end, p_until)
      AND entry.type NOT IN ('credit_topup','grant','manual_credit_grant','plan_credit_grant','plan_credit_expiry',
        'credit_refund','credit_dispute_hold','credit_dispute_release')
      AND (entry.type <> 'video_generation_refund' OR EXISTS (
        SELECT 1 FROM credit_ledger_entries debit
        WHERE debit.account_id = entry.account_id AND debit.type = 'video_generation_debit'
          AND debit.source_type = entry.source_type AND debit.source_id = entry.source_id
          AND debit.created_at >= greatest(p_period.period_start, p_period.granted_at)
          AND debit.created_at < least(p_period.period_end, p_until)))
  ) END
$$;

CREATE FUNCTION opengeni_private.preference_registry_scope_visible(row_account_id uuid, row_scope text, row_workspace_id uuid, row_subject_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT row_account_id = opengeni_private.current_account_id()
    AND (
      row_scope = 'organization'
      OR (row_scope = 'workspace' AND row_workspace_id = opengeni_private.current_workspace_id())
      OR (row_scope = 'user' AND row_subject_id = opengeni_private.current_subject_id())
    );
$$;

CREATE FUNCTION opengeni_private.prepare_organization_slack_bot_message(p_account uuid, p_workspace uuid, p_session uuid, p_task uuid, p_connection uuid, p_version integer, p_home uuid, p_generation bigint, p_channel text, p_thread text, p_text text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE v_id uuid; prior_workspace text; shared record;
BEGIN
  IF p_account IS NULL OR p_workspace IS NULL OR p_session IS NULL OR p_connection IS NULL
    OR p_home IS NULL OR p_generation IS NULL OR p_version IS NULL OR p_channel IS NULL OR p_text IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'Slack message scope mismatch' USING ERRCODE = '42501'; END IF;
  PERFORM 1 FROM sessions s WHERE s.id = p_session AND s.workspace_id = p_workspace AND s.account_id = p_account;
  IF NOT FOUND THEN RAISE EXCEPTION 'Slack message session unavailable' USING ERRCODE = '42501'; END IF;
  IF p_task IS NOT NULL THEN
    PERFORM 1 FROM sessions s JOIN scheduled_tasks t ON t.id = p_task AND t.workspace_id = s.workspace_id AND t.account_id = s.account_id
      WHERE s.id = p_session AND s.account_id = p_account AND s.workspace_id = p_workspace
      AND s.created_by_kind = 'service' AND s.created_by_subject_id = 'scheduler'
      AND s.created_by_context->>'scheduledTaskId' = p_task::text AND s.metadata->>'scheduledTaskId' = p_task::text
      AND s.created_by_context->>'scheduledTaskRunId' = s.metadata->>'scheduledTaskRunId'
      AND s.metadata->>'opengeniSlackBotConnectionId' = p_connection::text
      AND t.run_mode <> 'existing_session' AND t.agent_config->>'slackBotConnectionId' = p_connection::text
      AND t.agent_config->>'slackBotChannelId' = p_channel;
    IF NOT FOUND THEN RAISE EXCEPTION 'Scheduled Slack destination unavailable' USING ERRCODE = '42501'; END IF;
  END IF;
  IF p_home <> p_workspace THEN
    SELECT * INTO shared FROM opengeni_private.list_organization_slack_bots(p_account, p_workspace) a
      WHERE a.connection_id = p_connection AND a.home_workspace_id = p_home AND a.generation = p_generation;
    IF NOT FOUND THEN RAISE EXCEPTION 'Organization Slack access changed' USING ERRCODE = '42501'; END IF;
  ELSIF p_generation <> 0 THEN RAISE EXCEPTION 'Local Slack access generation mismatch' USING ERRCODE = '42501'; END IF;
  prior_workspace := current_setting('opengeni.workspace_id', true);
  PERFORM set_config('opengeni.workspace_id', p_home::text, true);
  PERFORM 1 FROM connections c WHERE c.id = p_connection AND c.account_id = p_account AND c.workspace_id = p_home
    AND c.version = p_version AND c.verified_install_at IS NOT NULL AND c.verified_install_version = c.version
    AND c.subject_id IS NULL AND c.kind = 'app_install' AND c.provider_domain = 'slack.com' AND c.status = 'active'
    AND c.metadata->>'credentialRole' = 'opengeni_slack_bot';
  IF NOT FOUND THEN RAISE EXCEPTION 'Slack message connection unavailable' USING ERRCODE = '42501'; END IF;
  PERFORM set_config('opengeni.workspace_id', coalesce(prior_workspace, ''), true);
  INSERT INTO opengeni_private.scheduled_slack_bot_messages(account_id, workspace_id, session_id, scheduled_task_id,
    connection_id, connection_version, home_workspace_id, sharing_generation, channel_id, thread_timestamp, message_text)
    VALUES(p_account, p_workspace, p_session, p_task, p_connection, p_version, p_home, p_generation, p_channel, p_thread, p_text)
    RETURNING id INTO v_id;
  RETURN v_id;
END $$;

CREATE FUNCTION opengeni_private.prepare_scheduled_slack_bot_message(p_account uuid, p_workspace uuid, p_session uuid, p_task uuid, p_connection uuid, p_connection_version integer, p_channel text, p_thread text, p_text text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_account IS NULL OR p_workspace IS NULL OR p_session IS NULL OR p_task IS NULL
    OR p_connection IS NULL OR p_connection_version IS NULL OR p_channel IS NULL OR p_text IS NULL
    OR p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'scheduled Slack message scope mismatch' USING ERRCODE = '42501'; END IF;
  PERFORM 1 FROM sessions s
    WHERE s.account_id = p_account AND s.workspace_id = p_workspace AND s.id = p_session
      AND s.created_by_kind = 'service' AND s.created_by_subject_id = 'scheduler'
      AND s.created_by_context->>'scheduledTaskId' = p_task::text
      AND s.metadata->>'scheduledTaskId' = p_task::text
      AND s.created_by_context->>'scheduledTaskRunId' = s.metadata->>'scheduledTaskRunId'
      AND s.metadata->>'opengeniSlackBotConnectionId' = p_connection::text;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled Slack message session unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM scheduled_tasks t
    WHERE t.account_id = p_account AND t.workspace_id = p_workspace AND t.id = p_task
      AND t.run_mode <> 'existing_session'
      AND t.agent_config->>'slackBotConnectionId' = p_connection::text
      AND t.agent_config->>'slackBotChannelId' = p_channel;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled Slack message destination unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM connections c
    WHERE c.account_id = p_account AND c.workspace_id = p_workspace AND c.id = p_connection
      AND c.version = p_connection_version AND c.verified_install_version = c.version
      AND c.subject_id IS NULL AND c.kind = 'app_install'
      AND c.provider_domain = 'slack.com' AND c.status = 'active';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled Slack message connection unavailable' USING ERRCODE = '42501';
  END IF;
  INSERT INTO opengeni_private.scheduled_slack_bot_messages(
    account_id, workspace_id, session_id, scheduled_task_id, connection_id,
    connection_version, channel_id, thread_timestamp, message_text
  ) VALUES (
    p_account, p_workspace, p_session, p_task, p_connection,
    p_connection_version, p_channel, p_thread, p_text
  ) RETURNING id INTO v_id;
  RETURN v_id;
END $$;

CREATE FUNCTION opengeni_private.prepare_workspace_background_command_deletion(p_account_id uuid, p_workspace_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
      DECLARE capability_id uuid := gen_random_uuid(); result_value integer;
      BEGIN
        
        INSERT INTO opengeni_private.maintenance_claim_capabilities VALUES
          (capability_id,pg_backend_pid(),pg_current_xact_id(),'workspace_commands');
        result_value := opengeni_private.maintenance_workspace_commands_prepare_inner($1, $2);
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RETURN result_value;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.maintenance_claim_capabilities c WHERE c.id=capability_id;
        RAISE;
      END
    $_$;

CREATE FUNCTION opengeni_private.preserve_credit_grant_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.eligible_model_ids IS DISTINCT FROM OLD.eligible_model_ids
    OR (OLD.eligible_model_ids IS NOT NULL AND (
      NEW.amount_micros IS DISTINCT FROM OLD.amount_micros
      OR NEW.account_id IS DISTINCT FROM OLD.account_id
      OR NEW.metadata->>'creditOfferLabel' IS DISTINCT FROM OLD.metadata->>'creditOfferLabel'
      OR NEW.metadata->>'creditOfferId' IS DISTINCT FROM OLD.metadata->>'creditOfferId'
      OR NEW.source_type IS DISTINCT FROM OLD.source_type
    )) THEN
    RAISE EXCEPTION 'Issued promotional credit terms are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.prevent_connection_account_intent_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.connection_account_intent IS DISTINCT FROM OLD.connection_account_intent THEN
    RAISE EXCEPTION 'accepted connection account intent is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.prevent_connector_action_request_identity_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
    OR NEW.session_id IS DISTINCT FROM OLD.session_id
    OR NEW.turn_id IS DISTINCT FROM OLD.turn_id
    OR NEW.creation_attempt_id IS DISTINCT FROM OLD.creation_attempt_id
    OR NEW.creation_execution_generation IS DISTINCT FROM OLD.creation_execution_generation
    OR NEW.approval_id IS DISTINCT FROM OLD.approval_id
    OR NEW.initiator_kind IS DISTINCT FROM OLD.initiator_kind
    OR NEW.initiator_subject_id IS DISTINCT FROM OLD.initiator_subject_id
    OR NEW.connection_id IS DISTINCT FROM OLD.connection_id
    OR NEW.connection_version IS DISTINCT FROM OLD.connection_version
    OR NEW.server_id IS DISTINCT FROM OLD.server_id
    OR NEW.tool_name IS DISTINCT FROM OLD.tool_name
    OR NEW.action_name IS DISTINCT FROM OLD.action_name
    OR NEW.policy_id IS DISTINCT FROM OLD.policy_id
    OR NEW.policy_version IS DISTINCT FROM OLD.policy_version
    OR NEW.policy_source IS DISTINCT FROM OLD.policy_source
    OR NEW.policy_decision IS DISTINCT FROM OLD.policy_decision
    OR NEW.action_fingerprint IS DISTINCT FROM OLD.action_fingerprint
  THEN
    RAISE EXCEPTION 'connector action request identity is immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.execution_attempt_id IS NOT NULL AND (
    NEW.execution_attempt_id IS DISTINCT FROM OLD.execution_attempt_id
    OR NEW.execution_attempt_generation IS DISTINCT FROM OLD.execution_attempt_generation
  ) THEN
    RAISE EXCEPTION 'connector action execution attempt is immutable' USING ERRCODE = '23514';
  END IF;
  IF OLD.decision IS NOT NULL AND (
    NEW.decision IS DISTINCT FROM OLD.decision
    OR NEW.decision_by_subject_id IS DISTINCT FROM OLD.decision_by_subject_id
    OR NEW.decision_event_id IS DISTINCT FROM OLD.decision_event_id
    OR NEW.decided_at IS DISTINCT FROM OLD.decided_at
    OR NEW.decision_by_kind IS DISTINCT FROM OLD.decision_by_kind
    OR NEW.decision_by_signed_in_person IS DISTINCT FROM OLD.decision_by_signed_in_person
  ) THEN
    RAISE EXCEPTION 'connector action approval decision is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.prevent_organization_codex_disconnect_with_live_leases() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}'
    AS $$
    BEGIN
      IF EXISTS (
        SELECT 1 FROM codex_credential_leases lease
        WHERE lease.account_id = OLD.account_id
          AND lease.credential_id = OLD.id
          AND lease.leased_until > clock_timestamp()
      ) THEN
        RAISE EXCEPTION 'Codex subscription cannot disconnect while active turns are using it'
          USING ERRCODE = '55006';
      END IF;
      RETURN OLD;
    END
    $$;

CREATE FUNCTION opengeni_private.prevent_personal_connection_authority_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'sessions' THEN
    IF NEW.parent_turn_id IS DISTINCT FROM OLD.parent_turn_id THEN
      RAISE EXCEPTION 'session parent turn authority is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.initial_personal_connection_delegations IS DISTINCT FROM OLD.initial_personal_connection_delegations THEN
      IF NEW.initial_personal_connection_delegations IS DISTINCT FROM '[]'::jsonb
        OR NEW.authority_epoch IS DISTINCT FROM OLD.authority_epoch + 1
        OR NEW.owner_subject_id IS DISTINCT FROM OLD.owner_subject_id
        OR NEW.owner_organization_membership_id IS DISTINCT FROM OLD.owner_organization_membership_id
      THEN
        RAISE EXCEPTION 'session initial personal MCP authority is immutable' USING ERRCODE = '23514';
      END IF;
      -- A caller-set GUC is insufficient: only the existing protected capability
      -- row minted by the native visibility transition permits this cleanup.
      IF NOT EXISTS (
        SELECT 1 FROM session_visibility_write_capabilities capability
        WHERE capability.backend_pid = pg_backend_pid()
          AND capability.transaction_id = pg_current_xact_id()
          AND capability.capability_id = nullif(current_setting(
            'opengeni.session_visibility_write_capability', true
          ), '')::uuid
      ) THEN
        RAISE EXCEPTION 'session personal authority cleanup requires the visibility lifecycle capability' USING ERRCODE = '42501';
      END IF;
    END IF;
  ELSIF NEW.personal_connection_delegations IS DISTINCT FROM OLD.personal_connection_delegations THEN
    RAISE EXCEPTION '% personal MCP authority is immutable', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION opengeni_private.prevent_scheduled_task_creator_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by_kind IS DISTINCT FROM OLD.created_by_kind
    OR NEW.created_by_subject_id IS DISTINCT FROM OLD.created_by_subject_id
    OR NEW.created_by_context IS DISTINCT FROM OLD.created_by_context
  THEN
    RAISE EXCEPTION 'scheduled task creator is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.prevent_session_creator_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.created_by_kind IS DISTINCT FROM OLD.created_by_kind
    OR NEW.created_by_subject_id IS DISTINCT FROM OLD.created_by_subject_id
    OR NEW.created_by_context IS DISTINCT FROM OLD.created_by_context
  THEN
    RAISE EXCEPTION 'session creator is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION opengeni_private.prevent_session_turn_initiator_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.initiator_kind IS DISTINCT FROM OLD.initiator_kind
    OR NEW.initiator_subject_id IS DISTINCT FROM OLD.initiator_subject_id
    OR NEW.initiator_context IS DISTINCT FROM OLD.initiator_context
  THEN
    RAISE EXCEPTION 'session turn initiator is immutable' USING ERRCODE = '23514';
