CREATE FUNCTION opengeni_private.resolve_slack_installation(p_team_id text) RETURNS TABLE(account_id uuid, workspace_id uuid, connection_id uuid, bot_id text, bot_user_id text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT B.account_id, B.workspace_id, B.connection_id, B.bot_id, B.bot_user_id
      FROM {{schema}}.slack_installation_bindings B
      JOIN {{schema}}.connections C ON C.id = B.connection_id
      WHERE B.slack_team_id = p_team_id
        AND B.state = 'active'
        AND C.account_id = B.account_id
        AND C.workspace_id = B.workspace_id
        AND C.status = 'active'
        AND C.subject_id IS NULL
        AND C.provider_domain = 'slack.com'
        AND C.kind = 'app_install'
        AND C.verified_install_at IS NOT NULL
        AND C.verified_install_version = C.version
        AND C.metadata->>'credentialRole' = 'opengeni_slack_bot'
        AND C.metadata->>'slackTeamId' = B.slack_team_id
        AND C.metadata->>'botId' = B.bot_id
        AND C.metadata->>'botUserId' = B.bot_user_id
      LIMIT 1
    $$;

CREATE FUNCTION opengeni_private.resolve_slack_interaction_tenancy(p_connection_id uuid, p_route_key text) RETURNS TABLE(account_id uuid, workspace_id uuid, interaction_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    BEGIN
      IF p_connection_id IS NULL OR p_route_key IS NULL THEN
        RETURN;
      END IF;
      INSERT INTO opengeni_private.slack_routing_runtime_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'interaction_tenancy'
      ) ON CONFLICT DO NOTHING;
      BEGIN
        RETURN QUERY
          SELECT I.account_id, I.workspace_id, I.id
          FROM slack_interactions I
          WHERE I.connection_id = p_connection_id
            AND I.route_key = p_route_key
          LIMIT 1;
        DELETE FROM opengeni_private.slack_routing_runtime_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'interaction_tenancy';
        RETURN;
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.slack_routing_runtime_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'interaction_tenancy';
        RAISE;
      END;
    END;
    $$;

