CREATE FUNCTION opengeni_private.retry_editable_artifact_live_outbox(p_outbox_id text, p_owner text, p_attempt_count integer, p_retry_delay_ms integer, p_error_code text, p_data_schema name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE affected integer;
DECLARE data_schema name;
BEGIN
  IF p_outbox_id IS NULL OR p_outbox_id !~ '^[0-9a-f]{32}$' OR p_outbox_id ~ '^0+$'
    OR p_owner IS NULL OR pg_catalog.octet_length(p_owner) NOT BETWEEN 1 AND 256
    OR p_attempt_count IS NULL OR p_attempt_count NOT BETWEEN 1 AND 1000000
    OR p_retry_delay_ms IS NULL OR p_retry_delay_ms NOT BETWEEN 1 AND 86400000
    OR p_error_code NOT IN ('broker_unavailable', 'broker_backpressure', 'publish_timeout')
    OR p_data_schema IS NULL
  THEN
    RAISE EXCEPTION 'invalid editable artifact outbox retry bounds'
      USING ERRCODE = '22023';
  END IF;
  data_schema := opengeni_private.resolve_editable_artifact_data_schema(p_data_schema);
  EXECUTE pg_catalog.format($query$
    UPDATE %I.editable_artifact_live_outbox target
    SET state = 'pending', lease_owner = NULL, lease_expires_at = NULL,
      next_attempt_at = pg_catalog.statement_timestamp()
        + pg_catalog.make_interval(secs => $4 / 1000.0),
      last_error_code = $5
    WHERE target.id = $1
      AND target.state = 'publishing'
      AND target.lease_owner = $2
      AND target.attempt_count = $3
      AND target.lease_expires_at > pg_catalog.statement_timestamp()
      AND target.lease_expires_at > pg_catalog.statement_timestamp()
  $query$, data_schema)
  USING p_outbox_id, p_owner, p_attempt_count, p_retry_delay_ms, p_error_code;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected = 1 THEN RETURN true; END IF;
  EXECUTE pg_catalog.format($query$
    SELECT count(*)::integer
    FROM %I.editable_artifact_live_outbox target
    WHERE target.id = $1 AND target.state = 'pending'
      AND target.attempt_count = $2 AND target.last_error_code = $3
  $query$, data_schema) INTO affected
  USING p_outbox_id, p_attempt_count, p_error_code;
  RETURN affected = 1;
END;
$_$;

CREATE FUNCTION opengeni_private.sandbox_checkpoint_artifact_gc_due_v1(p_claim_ttl_ms bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    BEGIN
      IF p_claim_ttl_ms IS NULL OR p_claim_ttl_ms < 1000 OR p_claim_ttl_ms > 3600000 THEN
        RAISE EXCEPTION 'invalid checkpoint artifact claim TTL' USING ERRCODE = '22023';
      END IF;
      RETURN EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_checkpoint_artifacts artifact
        WHERE artifact.state = 'deleting'
          AND artifact.delete_claimed_at
            < now() - make_interval(secs => p_claim_ttl_ms / 1000.0)
      ) OR EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_checkpoint_artifacts artifact
        WHERE (
            (artifact.state IN ('candidate', 'current', 'previous')
              AND artifact.created_at < now() - interval '15 minutes')
            OR (artifact.state IN ('delete_pending', 'delete_failed')
              AND coalesce(artifact.delete_after, artifact.created_at) <= now())
          )
          AND NOT EXISTS (
            SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_leases lease
            WHERE lease.current_checkpoint_artifact_id = artifact.id
               OR lease.previous_checkpoint_artifact_id = artifact.id
               OR (
                 artifact.provenance = 'native_capture'
                 AND lease.id = artifact.source_lease_id
                 AND lease.lease_epoch = artifact.source_lease_epoch
                 AND lease.instance_id = artifact.source_instance_id
                 AND lease.backend = artifact.provider_backend
                 AND lease.archive_capture_id IS NOT NULL
                 AND lease.archive_capture_generation = artifact.source_workspace_generation
               )
          )
          AND NOT EXISTS (
            SELECT 1 FROM opengeni_private.maintenance_probe_rig_versions version
            CROSS JOIN LATERAL jsonb_each(version.provider_images) provider_image
            WHERE provider_image.value ->> 'artifactId' = artifact.id::text
              AND provider_image.value ->> 'status' = 'ready'
          )
          AND NOT EXISTS (
            SELECT 1 FROM opengeni_private.maintenance_probe_rig_changes change
            JOIN opengeni_private.maintenance_probe_rig_versions base
              ON base.id = change.base_version_id
             AND base.workspace_id = change.workspace_id
             AND base.active = true
            WHERE change.status IN ('verifying', 'proposed')
              AND change.verification #>> '{providerImage,artifactId}' = artifact.id::text
              AND change.verification #>> '{providerImage,status}' = 'ready'
          )
      );
    END $$;

CREATE FUNCTION opengeni_private.sandbox_checkpoint_artifact_inventory() RETURNS TABLE(state text, count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT artifact.state, pg_catalog.count(*)::bigint
      FROM {{schema}}.sandbox_checkpoint_artifacts artifact
      GROUP BY artifact.state
      ORDER BY artifact.state;
    $$;

CREATE FUNCTION opengeni_private.sandbox_checkpoint_staleness() RETURNS TABLE(dirty bigint, stale_4h bigint, stale_12h bigint, max_age_seconds double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_id uuid;
    BEGIN
      inventory_id := opengeni_private.open_session_tenancy_fence_inventory(
        {{schema}}.session_tenancy_fence_target_schema());
      RETURN QUERY
      WITH live AS (
        SELECT
          lease.id,
          lease.instance_id,
          coalesce(lease.archive_generation, 0) AS archived_generation,
          coalesce(lease.provider_created_at, lease.created_at) AS box_created_at,
          opengeni_private.sandbox_checkpoint_staleness_at(
            lease.resume_state #>> '{sessionState,workspaceArchiveAt}') AS checkpoint_at,
          (SELECT pg_catalog.min(holder.created_at)
             FROM {{schema}}.sandbox_lease_holders holder
            WHERE holder.lease_id = lease.id
              AND holder.kind IN ('viewer', 'interaction')) AS writer_attached_at,
          lease.untracked_writer_since
        FROM {{schema}}.sandbox_leases lease
        WHERE lease.backend = 'modal'
          AND lease.liveness IN ('warm', 'draining')
          AND lease.instance_id IS NOT NULL
      ),
      evidence AS MATERIALIZED (
        SELECT
          live.box_created_at,
          -- A write admitted after the captured generation: unsaved since it
          -- was admitted.
          (SELECT pg_catalog.min(admission.admitted_at)
             FROM {{schema}}.sandbox_workspace_mutation_admissions admission
            WHERE admission.lease_id = live.id
              AND admission.provider_instance_id = live.instance_id
              AND admission.workspace_generation > live.archived_generation
          ) AS newer_write_at,
          -- A write the checkpoint ran around (a background command still
          -- open, or any captured write that settled after the checkpoint):
          -- unsaved since that checkpoint.
          CASE WHEN EXISTS (
              SELECT 1
                FROM {{schema}}.sandbox_workspace_mutation_admissions admission
               WHERE admission.lease_id = live.id
                 AND admission.provider_instance_id = live.instance_id
                 AND admission.workspace_generation <= live.archived_generation
                 AND admission.settled_at IS NULL
            ) OR EXISTS (
              SELECT 1
                FROM {{schema}}.sandbox_workspace_mutation_admissions admission
               WHERE admission.lease_id = live.id
                 AND admission.settled_at > live.checkpoint_at
                 AND admission.provider_instance_id = live.instance_id
                 AND admission.workspace_generation <= live.archived_generation
            )
            THEN coalesce(live.checkpoint_at, live.box_created_at)
          END AS spanning_write_at,
          -- A writer that bypasses admissions, attached now or since the last
          -- capture that did not run around one: unsaved since it first
          -- attached, or since the checkpoint it was attached through.
          CASE WHEN coalesce(live.untracked_writer_since, live.writer_attached_at) IS NOT NULL
            THEN greatest(
              least(live.untracked_writer_since, live.writer_attached_at),
              coalesce(live.checkpoint_at, live.box_created_at))
          END AS untracked_write_at
        FROM live
      ),
      dirty_leases AS (
        SELECT extract(epoch FROM pg_catalog.now() - greatest(
          least(evidence.newer_write_at, evidence.spanning_write_at,
            evidence.untracked_write_at),
          evidence.box_created_at
        ))::double precision AS age_seconds
        FROM evidence
        WHERE evidence.newer_write_at IS NOT NULL
           OR evidence.spanning_write_at IS NOT NULL
           OR evidence.untracked_write_at IS NOT NULL
      )
      SELECT
        pg_catalog.count(*)::bigint,
        pg_catalog.count(*) FILTER (WHERE age_seconds > 4 * 3600)::bigint,
        pg_catalog.count(*) FILTER (WHERE age_seconds > 12 * 3600)::bigint,
        coalesce(pg_catalog.max(age_seconds), 0)::double precision
      FROM dirty_leases;
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory_id);
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.sandbox_checkpoint_staleness_at(value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
    BEGIN
      IF value IS NULL
        OR value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+(Z|[+-][0-9:]+)$' THEN
        RETURN NULL;
      END IF;
      RETURN value::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RETURN NULL;
    END
    $_$;

CREATE FUNCTION opengeni_private.sandbox_ended_epoch_blockers_due_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_workspace_mutation_admissions admission
        WHERE admission.settled_at IS NULL AND admission.route_kind = 'home'
          AND admission.provider_backend = 'modal'
      ) OR EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_session_turns turn
        JOIN opengeni_private.maintenance_probe_sessions session
          ON session.workspace_id = turn.workspace_id
         AND session.id = turn.session_id
         AND session.active_turn_id = turn.id
        WHERE turn.status = 'recovering'
          AND turn.metadata ? 'sandboxSetupOutcomeUnknown'
          AND session.direct_control_state = 'active'
      )
    $$;

CREATE FUNCTION opengeni_private.sandbox_idle_checkpoint_due_v1(p_interval_ms bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE due_before timestamptz;
    BEGIN
      IF p_interval_ms IS NULL OR p_interval_ms < 1 THEN
        RAISE EXCEPTION 'invalid checkpoint interval' USING ERRCODE = '22023';
      END IF;
      due_before := now() - p_interval_ms * interval '1 millisecond';
      RETURN EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_leases lease
        WHERE lease.liveness = 'warm' AND lease.backend = 'modal'
          AND lease.instance_id IS NOT NULL
          AND lease.turn_holders = 0 AND lease.refcount > 0
          AND lease.unobservable_command_drain_ids IS NULL
          AND lease.rotation_requested_at IS NULL
          AND (lease.reaper_hold_until IS NULL OR lease.reaper_hold_until <= now())
          AND (lease.archive_capture_last_attempt_at IS NULL
            OR lease.archive_capture_last_attempt_at <= due_before)
          AND (lease.idle_checkpoint_attempted_at IS NULL
            OR lease.idle_checkpoint_attempted_at <= due_before)
      );
    END $$;

CREATE FUNCTION opengeni_private.sandbox_lease_reaper_due_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_leases lease
        WHERE lease.liveness IN ('warming', 'warm', 'draining')
      ) OR EXISTS (SELECT 1 FROM opengeni_private.maintenance_probe_sandbox_lease_holders holder)
    $$;

CREATE FUNCTION opengeni_private.sandbox_recovery_observations() RETURNS TABLE(provider_losses bigint, fallback_selections bigint, fresh_workspace_selections bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
      SELECT
        count(*) FILTER (WHERE kind = 'provider_missing_before_capture')::bigint,
        count(*) FILTER (WHERE kind = 'checkpoint_fallback_selected')::bigint,
        count(*) FILTER (WHERE kind = 'fresh_workspace_selected')::bigint
      FROM opengeni_private.sandbox_recovery_operator_receipts
      WHERE occurred_at >= pg_catalog.clock_timestamp() - interval '30 minutes'
    $$;

CREATE FUNCTION opengeni_private.sandbox_rotation_backlog() RETURNS TABLE(requested bigint, overdue bigint, turn_blocked bigint, direct_blocked bigint, process_blocked bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE inventory_capability_id uuid;
    BEGIN
      inventory_capability_id :=
        opengeni_private.open_session_tenancy_fence_inventory(
          {{schema}}.session_tenancy_fence_target_schema()
        );
      RETURN QUERY
      SELECT
        pg_catalog.count(*) FILTER (
          WHERE lease.rotation_requested_at IS NOT NULL
        )::bigint,
        pg_catalog.count(*) FILTER (
          WHERE lease.rotation_requested_at IS NOT NULL
            AND lease.provider_deadline_at <= pg_catalog.now()
        )::bigint,
        pg_catalog.count(*) FILTER (
          WHERE lease.rotation_requested_at IS NOT NULL
            AND EXISTS (
              SELECT 1
              FROM {{schema}}.sandbox_lease_holders holder
              WHERE holder.lease_id = lease.id
                AND holder.kind = 'turn'
            )
        )::bigint,
        pg_catalog.count(*) FILTER (
          WHERE lease.rotation_requested_at IS NOT NULL
            AND EXISTS (
              SELECT 1
              FROM {{schema}}.sandbox_lease_holders holder
              WHERE holder.lease_id = lease.id
                AND holder.kind = 'direct'
            )
        )::bigint,
        pg_catalog.count(*) FILTER (
          WHERE lease.rotation_requested_at IS NOT NULL
            AND EXISTS (
              SELECT 1
              FROM {{schema}}.sandbox_lease_holders holder
              WHERE holder.lease_id = lease.id
                AND holder.kind = 'process'
            )
        )::bigint
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.backend = 'modal'
        AND lease.liveness IN ('warming', 'warm', 'draining');
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(
        inventory_capability_id
      );
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(
        inventory_capability_id
      );
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.sandbox_rotation_interaction_blocked() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE
      inventory_capability_id uuid;
      blocked_count bigint;
    BEGIN
      inventory_capability_id :=
        opengeni_private.open_session_tenancy_fence_inventory(
          {{schema}}.session_tenancy_fence_target_schema()
        );
      SELECT pg_catalog.count(*)::bigint
      INTO blocked_count
      FROM {{schema}}.sandbox_leases lease
      WHERE lease.backend = 'modal'
        AND lease.liveness IN ('warming', 'warm', 'draining')
        AND lease.rotation_requested_at IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM {{schema}}.sandbox_lease_holders holder
          WHERE holder.lease_id = lease.id
            AND holder.kind = 'interaction'
        );
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(
        inventory_capability_id
      );
      RETURN blocked_count;
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.close_session_tenancy_fence_inventory(
        inventory_capability_id
      );
      RAISE;
    END
    $$;

CREATE FUNCTION opengeni_private.scheduled_personal_resource_capability_active(p_capability_kind text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM opengeni_private.scheduled_personal_resource_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND (
        p_capability_kind IS NULL
        OR capability.capability_kind = p_capability_kind
      )
  )
$$;

CREATE FUNCTION opengeni_private.scoped_compute_capability_active(p_capability_kind text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM opengeni_private.scoped_compute_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND (p_capability_kind IS NULL OR capability.capability_kind = p_capability_kind)
  )
$$;

CREATE FUNCTION opengeni_private.scoped_knowledge_actor_authorized(row_actor_kind text, row_actor_subject_id text, row_initiating_human_subject_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT opengeni_private.scoped_knowledge_actor_valid(
      row_actor_kind, row_actor_subject_id, row_initiating_human_subject_id
    )
    AND (
      (
        row_actor_kind = 'human'
        AND row_actor_subject_id = opengeni_private.current_subject_id()
        AND row_initiating_human_subject_id = opengeni_private.current_subject_id()
      )
      OR (
        row_actor_kind = 'service'
        AND row_initiating_human_subject_id
          IS NOT DISTINCT FROM opengeni_private.current_subject_id()
      )
    );
$$;

CREATE FUNCTION opengeni_private.scoped_knowledge_actor_valid(row_actor_kind text, row_actor_subject_id text, row_initiating_human_subject_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT length(btrim(row_actor_subject_id)) BETWEEN 1 AND 1024
    AND (
      (
        row_actor_kind = 'human'
        AND row_initiating_human_subject_id = row_actor_subject_id
      )
      OR (
        row_actor_kind = 'service'
        AND (
          row_initiating_human_subject_id IS NULL
          OR length(btrim(row_initiating_human_subject_id)) BETWEEN 1 AND 1024
        )
      )
    );
$$;

CREATE FUNCTION opengeni_private.scoped_knowledge_scope_key(row_scope text, row_workspace_id uuid, row_subject_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT row_scope || ':' || coalesce(row_workspace_id::text, '-') || ':' ||
    coalesce(row_subject_id, '-');
$$;

CREATE FUNCTION opengeni_private.scoped_knowledge_scope_valid(row_scope text, row_workspace_id uuid, row_subject_id text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT
    (row_scope = 'organization' AND row_workspace_id IS NULL AND row_subject_id IS NULL)
    OR (row_scope = 'workspace' AND row_workspace_id IS NOT NULL AND row_subject_id IS NULL)
    OR (
      row_scope = 'personal'
      AND nullif(btrim(row_subject_id), '') IS NOT NULL
      AND octet_length(convert_to(row_subject_id, 'UTF8')) <= 1024
    );
$$;

CREATE FUNCTION opengeni_private.scoped_knowledge_scope_visible(row_account_id uuid, row_scope text, row_workspace_id uuid, row_subject_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT row_account_id = opengeni_private.current_account_id()
    AND (
      row_scope = 'organization'
      OR (
        row_scope = 'workspace'
        AND row_workspace_id = opengeni_private.current_workspace_id()
      )
      OR (
        row_scope = 'personal'
        AND row_subject_id = opengeni_private.current_subject_id()
        AND (
          row_workspace_id IS NULL
          OR row_workspace_id = opengeni_private.current_workspace_id()
        )
      )
    );
$$;

CREATE FUNCTION opengeni_private.seed_subscription_codex_cutover() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      previous text := current_setting('opengeni.subscription_cutover_seed', true);
      seeded_rotation jsonb;
    BEGIN
      SELECT jsonb_object_agg(receipt.provider, receipt.seed_rotation) INTO seeded_rotation
      FROM opengeni_private.subscription_provider_cutover_receipts receipt;
      IF seeded_rotation IS NULL THEN RETURN NEW; END IF;
      PERFORM pg_catalog.set_config('opengeni.subscription_cutover_seed', NEW.id::text, true);
      -- A brand-new organization has no rows yet. (ON CONFLICT would need a
      -- SELECT policy for the arbiter and is deliberately not used.)
      INSERT INTO subscription_provider_cutovers (account_id, provider, enabled, updated_by_subject_id)
      SELECT NEW.id, receipt.provider, true, 'service:subscription-core-cutover'
      FROM opengeni_private.subscription_provider_cutover_receipts receipt
      ORDER BY receipt.provider;
      -- The account-level settings row is unique per organization: one row
      -- with the defaults of every provider that has a receipt.
      INSERT INTO subscription_settings (
        account_id, workspace_id, rotation, providers, cross_provider_failover, fallback_order,
        personal_connections_allowed, personal_fallback_allowed, updated_by_subject_id
      ) VALUES (
        NEW.id, NULL, seeded_rotation, '{}'::jsonb, false, '{}'::jsonb,
        true, false, 'service:subscription-core-cutover'
      );
      PERFORM pg_catalog.set_config('opengeni.subscription_cutover_seed', coalesce(previous, ''), true);
      RETURN NEW;
    END
    $$;

CREATE FUNCTION opengeni_private.session_archive_candidates(p_idle_seconds bigint, p_limit integer, p_session_id uuid DEFAULT NULL::uuid) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  WITH params AS (
    SELECT clock_timestamp() - make_interval(secs => greatest(p_idle_seconds, 3600)) AS cutoff
  )
  SELECT S.account_id, S.workspace_id, S.id
  FROM sessions S, params P
  WHERE S.content_archive_state IS NULL
    AND (p_session_id IS NULL OR S.id = p_session_id)
    AND NOT S.keep_live
    AND S.imported_archive_import_id IS NULL
    AND S.status IN ('idle', 'failed', 'cancelled')
    AND S.active_turn_id IS NULL
    AND S.input_wait_until IS NULL
    AND S.created_at < P.cutoff
    AND NOT EXISTS (
      SELECT 1 FROM session_turns T
      WHERE T.workspace_id = S.workspace_id AND T.session_id = S.id
        AND (T.status IN ('queued', 'running', 'requires_action', 'recovering', 'waiting_capacity')
          OR greatest(T.created_at, T.updated_at) >= P.cutoff))
    AND NOT EXISTS (
      SELECT 1 FROM session_human_input_requests H
      WHERE H.workspace_id = S.workspace_id AND H.session_id = S.id AND H.status = 'pending')
    AND NOT EXISTS (
      SELECT 1 FROM session_goals G
      WHERE G.workspace_id = S.workspace_id AND G.session_id = S.id AND G.status = 'active')
    AND NOT EXISTS (
      SELECT 1 FROM session_system_updates U
      WHERE U.workspace_id = S.workspace_id AND U.session_id = S.id AND U.state = 'pending')
    AND NOT EXISTS (
      SELECT 1 FROM session_system_update_outbox O
      WHERE O.workspace_id = S.workspace_id AND O.target_session_id = S.id
        AND O.status = 'pending')
    AND NOT EXISTS (
      SELECT 1 FROM session_background_commands B
      WHERE B.workspace_id = S.workspace_id AND B.session_id = S.id
        AND B.state IN ('running', 'stopping'))
    AND NOT EXISTS (
      SELECT 1 FROM scheduled_tasks K
      WHERE K.workspace_id = S.workspace_id AND K.reusable_session_id = S.id
        AND K.deleted_at IS NULL)
    AND NOT EXISTS (
      SELECT 1 FROM site_auth_connections A
      WHERE A.workspace_id = S.workspace_id AND A.maintenance_session_id = S.id)
    AND NOT EXISTS (
      SELECT 1 FROM sessions C
      WHERE C.workspace_id = S.workspace_id AND C.parent_session_id = S.id
        AND C.content_archive_state IS NULL
        AND (C.status NOT IN ('idle', 'failed', 'cancelled')
          OR C.created_at >= P.cutoff
          OR EXISTS (
            SELECT 1 FROM session_turns CT
            WHERE CT.workspace_id = C.workspace_id AND CT.session_id = C.id
              AND greatest(CT.created_at, CT.updated_at) >= P.cutoff)))
  ORDER BY S.created_at, S.id
  LIMIT least(greatest(p_limit, 0), 100);
$$;

CREATE FUNCTION opengeni_private.session_archive_preference_snapshot_rows(p_workspace_id uuid, p_session_id uuid, p_after_id uuid, p_limit integer) RETURNS TABLE(id uuid, row_json text)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT P.id, row_to_json(P)::text
  FROM preference_registry_snapshots P
  WHERE P.workspace_id = p_workspace_id
    AND P.session_id = p_session_id
    AND (p_after_id IS NULL OR P.id > p_after_id)
    AND EXISTS (
      SELECT 1 FROM sessions S
      WHERE S.workspace_id = p_workspace_id AND S.id = p_session_id
        AND S.content_archive_state = 'archiving')
  ORDER BY P.id
  LIMIT least(greatest(p_limit, 0), 1000);
$$;

CREATE FUNCTION opengeni_private.session_archive_unfinished(p_stale_seconds bigint, p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT S.account_id, S.workspace_id, S.id, S.content_archive_state
  FROM sessions S
  WHERE (S.content_archive_state = 'archiving'
      AND S.content_archive_started_at
        < clock_timestamp() - make_interval(secs => greatest(p_stale_seconds, 300)))
    OR (S.content_archive_state = 'archived' AND S.content_archive_purged_at IS NULL)
  ORDER BY S.content_archive_started_at, S.id
  LIMIT least(greatest(p_limit, 0), 100);
$$;

CREATE FUNCTION opengeni_private.session_content_compaction_candidates(p_kind text, p_after_attempt_id uuid, p_limit integer) RETURNS TABLE(attempt_id uuid, account_id uuid, workspace_id uuid, session_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  IF p_kind = 'tool_catalog' THEN
    RETURN QUERY
      SELECT C.attempt_id, C.account_id, C.workspace_id, C.session_id
      FROM session_attempt_tool_catalogs C
      WHERE C.content_refs IS NULL
        AND (p_after_attempt_id IS NULL OR C.attempt_id > p_after_attempt_id)
      ORDER BY C.attempt_id
      LIMIT least(greatest(p_limit, 0), 1000);
  ELSIF p_kind = 'model_context_snapshot' THEN
    RETURN QUERY
      SELECT S.attempt_id, S.account_id, S.workspace_id, S.session_id
      FROM session_attempt_model_context_snapshots S
      WHERE S.content_refs IS NULL
        AND (p_after_attempt_id IS NULL OR S.attempt_id > p_after_attempt_id)
      ORDER BY S.attempt_id
      LIMIT least(greatest(p_limit, 0), 1000);
  ELSE
    RAISE EXCEPTION 'unknown session content kind' USING ERRCODE = '22023';
  END IF;
END;
$$;

CREATE FUNCTION opengeni_private.session_create_idempotency_guard_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  inserted_rows integer;
  new_outcome text;
  new_session_id uuid;
  new_denial_id uuid;
  new_idempotency_key text;
BEGIN
  IF TG_TABLE_NAME = 'sessions' THEN
    new_idempotency_key := NEW.create_idempotency_key;
    new_outcome := 'session';
    new_session_id := NEW.id;
    new_denial_id := NULL;
  ELSE
    new_idempotency_key := NEW.idempotency_key;
    new_outcome := 'denial';
    new_session_id := NULL;
    new_denial_id := NEW.id;
  END IF;
  IF new_idempotency_key IS NULL THEN
    RETURN NEW;
  END IF;

  -- This is the exact lock used by the application admission path. The
  -- trigger must take it before reserving the cross-outcome ledger row so an
  -- old writer and a current writer cannot choose different winners for the
  -- same workspace/key. The depth trigger already took this same advisory
  -- lock and checked for an existing winner; taking it again is
  -- transaction-reentrant and keeps this guard safe for direct old writers as
  -- well as the current application.
  PERFORM pg_advisory_xact_lock(
    hashtext('session-create:' || NEW.workspace_id::text || ':' || new_idempotency_key)
  );

  EXECUTE format($sql$
    INSERT INTO %I."session_create_idempotency_guard"
      ("workspace_id", "idempotency_key", "outcome", "session_id", "denial_id")
    VALUES ($1, $2, $3, $4, $5)
    ON CONFLICT ("workspace_id", "idempotency_key") DO NOTHING
  $sql$, TG_TABLE_SCHEMA)
  USING NEW.workspace_id, new_idempotency_key, new_outcome, new_session_id, new_denial_id;
  GET DIAGNOSTICS inserted_rows = ROW_COUNT;
  IF inserted_rows = 1 THEN
    RETURN NEW;
  END IF;

  -- The durable ledger row is the winner. Returning NULL from a BEFORE INSERT
  -- trigger suppresses this source row without aborting the transaction, so
  -- old writers and current writers both receive an empty RETURNING result and
  -- can replay the winner. Raising 23505 here would abort the transaction
  -- before the application could inspect the durable winner.
  RETURN NULL;
END
$_$;

CREATE FUNCTION opengeni_private.session_delta_fold_candidates(p_settle_seconds bigint, p_limit integer) RETURNS TABLE(account_id uuid, workspace_id uuid, session_id uuid, turn_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT T.account_id, T.workspace_id, T.session_id, T.id
  FROM session_turns T
  JOIN sessions S ON S.workspace_id = T.workspace_id AND S.id = T.session_id
  WHERE T.status IN ('completed', 'failed', 'cancelled', 'superseded', 'withdrawn_for_edit')
    AND T.updated_at < clock_timestamp() - make_interval(secs => greatest(p_settle_seconds, 60))
    AND S.content_archive_state IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM opengeni_private.session_turn_delta_folds F
      WHERE F.workspace_id = T.workspace_id AND F.turn_id = T.id)
  ORDER BY T.updated_at, T.id
  LIMIT least(greatest(p_limit, 0), 500);
$$;

CREATE FUNCTION opengeni_private.session_depth_policy_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  workspace_policy integer;
  workspace_has_policy boolean;
  workspace_account_id uuid;
  control_account_id uuid;
  deployment_policy integer;
  deployment_source text;
  parent_root uuid;
  parent_depth integer;
  parent_effective integer;
  parent_source text;
  parent_policy_session uuid;
  expected_root uuid;
  expected_depth bigint;
  expected_effective integer;
  expected_source text;
  expected_policy_session uuid;
  new_idempotency_key text;
  ledger_winner_exists boolean;
BEGIN
  -- Keep direct/older writers on the same control -> advisory -> workspace
  -- ordering as pre-boundary application admission. The control prefix is
  -- required for rolling compatibility: an old binary can already hold this
  -- row before its insert reaches this trigger. The keyed advisory lock below
  -- still fences the cross-outcome ledger before policy evaluation.
  EXECUTE format('SELECT account_id FROM %I.workspace_inference_controls '
      'WHERE workspace_id = $1 FOR SHARE', TG_TABLE_SCHEMA)
    INTO control_account_id USING NEW.workspace_id;
  IF control_account_id IS NULL THEN
    RAISE EXCEPTION 'workspace has no mandatory inference-control row' USING ERRCODE = '23503';
  END IF;

  -- Take the same transaction advisory lock as current and old application
  -- admission, then check the durable outcome before policy/control suffix
  -- reads. A retry must replay its winner even if the retry's parent would now
  -- exceed the effective depth policy. Waiting on the advisory lock also makes
  -- an uncommitted winner visible before this check, instead of allowing a
  -- mixed-version loser to evaluate policy first.
  IF TG_TABLE_NAME = 'sessions' THEN
    new_idempotency_key := NEW.create_idempotency_key;
    IF new_idempotency_key IS NOT NULL THEN
      PERFORM pg_advisory_xact_lock(
        hashtext('session-create:' || NEW.workspace_id::text || ':' || new_idempotency_key)
      );
      EXECUTE format('SELECT EXISTS (
          SELECT 1
          FROM %I.session_create_idempotency_guard
          WHERE workspace_id = $1 AND idempotency_key = $2
        )', TG_TABLE_SCHEMA)
        INTO ledger_winner_exists
        USING NEW.workspace_id, new_idempotency_key;
      IF ledger_winner_exists THEN
        RETURN NULL;
      END IF;
    END IF;
  END IF;

  EXECUTE format('SELECT CASE WHEN jsonb_typeof(settings -> ''maxNestedAgentDepth'') = ''number''
      AND settings ->> ''maxNestedAgentDepth'' ~ ''^(0|[1-9][0-9]{0,9})$''
      AND (settings ->> ''maxNestedAgentDepth'')::numeric BETWEEN 0 AND 2147483647
      THEN (settings ->> ''maxNestedAgentDepth'')::integer ELSE NULL END,
      coalesce((jsonb_typeof(settings -> ''maxNestedAgentDepth'') = ''number''
       AND settings ->> ''maxNestedAgentDepth'' ~ ''^(0|[1-9][0-9]{0,9})$''
       AND (settings ->> ''maxNestedAgentDepth'')::numeric BETWEEN 0 AND 2147483647), false),
      account_id
      FROM %I.workspaces WHERE id = $1', TG_TABLE_SCHEMA)
    INTO workspace_policy, workspace_has_policy, workspace_account_id USING NEW.workspace_id;
  IF workspace_account_id IS NULL THEN
    RAISE EXCEPTION 'workspace not found for session insert' USING ERRCODE = '23503';
  END IF;
  EXECUTE format('SELECT max_nested_agent_depth, policy_source FROM %I.lock_nested_agent_depth_configuration()', TG_TABLE_SCHEMA)
    INTO deployment_policy, deployment_source;
  IF deployment_policy IS NULL THEN
    RAISE EXCEPTION 'nested-agent deployment policy is not configured' USING ERRCODE = '23514';
  END IF;

  IF NEW.parent_session_id IS NULL THEN
    expected_root := NEW.id;
    expected_depth := 0;
  ELSE
    EXECUTE format('SELECT root_session_id, nested_agent_depth, effective_max_nested_agent_depth,
        nested_agent_depth_policy_source, nested_agent_depth_policy_session_id
        FROM %I.sessions WHERE workspace_id = $1 AND id = $2 FOR SHARE', TG_TABLE_SCHEMA)
      INTO parent_root, parent_depth, parent_effective, parent_source, parent_policy_session
      USING NEW.workspace_id, NEW.parent_session_id;
    IF parent_root IS NULL OR parent_depth IS NULL THEN
      -- During 0111, a legacy parent can still have nullable lineage columns.
      -- Walk that existing tree and derive the missing snapshot from the
      -- nearest materialized ancestor, or from the legacy root and workspace
      -- policy when the whole chain predates this boundary. This keeps old
      -- trees writable while the bounded backfill catches up; it does not
      -- bypass the effective-depth check below.
      EXECUTE format($sql$
        WITH RECURSIVE lineage AS (
          SELECT
            node.id,
            node.parent_session_id,
            node.root_session_id,
            node.nested_agent_depth,
            node.effective_max_nested_agent_depth,
            node.nested_agent_depth_policy_source,
            node.nested_agent_depth_policy_session_id,
            0::bigint AS distance,
            ARRAY[node.id]::uuid[] AS path
          FROM %I.sessions AS node
          WHERE node.workspace_id = $1 AND node.id = $2
          UNION ALL
          SELECT
            ancestor.id,
            ancestor.parent_session_id,
            ancestor.root_session_id,
            ancestor.nested_agent_depth,
            ancestor.effective_max_nested_agent_depth,
            ancestor.nested_agent_depth_policy_source,
            ancestor.nested_agent_depth_policy_session_id,
            lineage.distance + 1,
            lineage.path || ancestor.id
          FROM %I.sessions AS ancestor
          JOIN lineage
            ON ancestor.workspace_id = $1
           AND ancestor.id = lineage.parent_session_id
          WHERE NOT ancestor.id = ANY(lineage.path)
        ),
        complete AS (
          SELECT *
          FROM lineage
          WHERE root_session_id IS NOT NULL
            AND nested_agent_depth IS NOT NULL
            AND effective_max_nested_agent_depth IS NOT NULL
            AND nested_agent_depth_policy_source IS NOT NULL
        )
        SELECT
          COALESCE(
            (SELECT root_session_id FROM lineage
             WHERE root_session_id IS NOT NULL
             ORDER BY distance LIMIT 1),
            (SELECT id FROM lineage
             WHERE parent_session_id IS NULL
             ORDER BY distance DESC LIMIT 1)
          ),
          COALESCE(
            (SELECT nested_agent_depth::bigint + distance FROM lineage
             WHERE nested_agent_depth IS NOT NULL
             ORDER BY distance LIMIT 1),
            (SELECT max(distance) FROM lineage)
          ),
          (SELECT effective_max_nested_agent_depth FROM complete
           ORDER BY distance LIMIT 1),
          (SELECT nested_agent_depth_policy_source FROM complete
           ORDER BY distance LIMIT 1),
          (SELECT nested_agent_depth_policy_session_id FROM complete
           ORDER BY distance LIMIT 1)
      $sql$, TG_TABLE_SCHEMA, TG_TABLE_SCHEMA)
        INTO parent_root, parent_depth, parent_effective, parent_source, parent_policy_session
        USING NEW.workspace_id, NEW.parent_session_id;
    END IF;
    IF parent_root IS NULL OR parent_depth IS NULL THEN
      RAISE EXCEPTION 'parent session not found for nested insert' USING ERRCODE = '23503';
    END IF;
    expected_root := parent_root;
    expected_depth := parent_depth + 1;
  END IF;

  IF NEW.max_nested_agent_depth_override IS NOT NULL THEN
    expected_effective := NEW.max_nested_agent_depth_override;
    expected_source := 'session';
    expected_policy_session := NEW.id;
  ELSIF NEW.parent_session_id IS NOT NULL AND parent_source = 'session' THEN
    expected_effective := parent_effective;
    expected_source := 'session';
    expected_policy_session := parent_policy_session;
  ELSIF workspace_has_policy THEN
    expected_effective := workspace_policy;
    expected_source := 'workspace';
    expected_policy_session := NULL;
  ELSE
    expected_effective := deployment_policy;
    expected_source := deployment_source;
    expected_policy_session := NULL;
  END IF;

  IF expected_depth > expected_effective THEN
    RAISE EXCEPTION 'nested agent depth exceeds effective maximum' USING ERRCODE = '23514';
  END IF;
  NEW.root_session_id := expected_root;
  NEW.nested_agent_depth := expected_depth;
  NEW.effective_max_nested_agent_depth := expected_effective;
  NEW.nested_agent_depth_policy_source := expected_source;
  NEW.nested_agent_depth_policy_session_id := expected_policy_session;
  RETURN NEW;
END
$_$;

CREATE FUNCTION opengeni_private.session_depth_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.parent_session_id IS DISTINCT FROM OLD.parent_session_id
     OR NEW.root_session_id IS DISTINCT FROM OLD.root_session_id
     OR NEW.nested_agent_depth IS DISTINCT FROM OLD.nested_agent_depth
     OR NEW.max_nested_agent_depth_override IS DISTINCT FROM OLD.max_nested_agent_depth_override
     OR NEW.effective_max_nested_agent_depth IS DISTINCT FROM OLD.effective_max_nested_agent_depth
     OR NEW.nested_agent_depth_policy_source IS DISTINCT FROM OLD.nested_agent_depth_policy_source
     OR NEW.nested_agent_depth_policy_session_id IS DISTINCT FROM OLD.nested_agent_depth_policy_session_id THEN
    RAISE EXCEPTION 'session lineage and nested-agent policy snapshot are immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION opengeni_private.session_file_read_allowed(p_account uuid, p_workspace uuid, p_file uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
