    AS $$
  SELECT EXISTS (SELECT 1 FROM opengeni_private.session_file_read_capabilities c
    WHERE c.backend_pid=pg_backend_pid() AND c.transaction_id=pg_current_xact_id_if_assigned()
      AND c.account_id=p_account AND c.workspace_id=p_workspace AND c.file_id=p_file)
$$;

CREATE FUNCTION opengeni_private.session_hands_back_v1(p_session_id uuid, p_turn_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT NOT EXISTS (
      SELECT 1 FROM sessions session
      WHERE session.id = p_session_id
        AND session.input_wait_turn_id = p_turn_id
        AND (session.input_wait_until IS NULL OR session.input_wait_until > now())
    )
    AND NOT EXISTS (
      SELECT 1 FROM session_goals goal
      WHERE goal.session_id = p_session_id AND goal.status = 'active'
    )
    AND NOT EXISTS (
      SELECT 1 FROM session_turns turn
      WHERE turn.session_id = p_session_id AND turn.status = 'queued'
        AND turn.id <> p_turn_id
    )
    AND NOT EXISTS (
      SELECT 1 FROM session_realtime_modes call
      WHERE call.session_id = p_session_id AND call.state = 'active'
        AND call.lease_expires_at > now()
    )
$$;

CREATE FUNCTION opengeni_private.session_list_snapshots_expired_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
