    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.maintenance_probe_session_list_snapshots s WHERE s.expires_at < now()
      )
    $$;

CREATE FUNCTION opengeni_private.session_ownership_capability_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
