CREATE FUNCTION opengeni_private.session_person_v1(p_workspace_id uuid, p_session_id uuid, p_owner text, p_creator text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce(
    opengeni_private.session_recipient_v1(p_owner, p_creator),
    (SELECT task.owner_subject_id
     FROM scheduled_task_runs run
     JOIN scheduled_tasks task ON task.id = run.task_id
     WHERE run.workspace_id = p_workspace_id AND run.session_id = p_session_id
       AND (starts_with(task.owner_subject_id, 'user:')
         OR starts_with(task.owner_subject_id, 'external_user:'))
     ORDER BY run.created_at DESC
     LIMIT 1),
    (SELECT 'dev'
     FROM workspaces workspace
     JOIN managed_accounts account ON account.id = workspace.account_id
     WHERE workspace.id = p_workspace_id
       AND account.external_source = 'opengeni:local'
       AND account.external_id = 'default'
       AND ('dev' IN (p_owner, p_creator) OR EXISTS (
         SELECT 1
         FROM scheduled_task_runs run
         JOIN scheduled_tasks task ON task.id = run.task_id
         WHERE run.workspace_id = p_workspace_id AND run.session_id = p_session_id
           AND task.owner_subject_id = 'dev'
       )))
  )
$$;

CREATE FUNCTION opengeni_private.session_recipient_v1(p_owner text, p_creator text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN starts_with(p_owner, 'user:') OR starts_with(p_owner, 'external_user:') THEN p_owner
    WHEN starts_with(p_creator, 'user:') OR starts_with(p_creator, 'external_user:') THEN p_creator
  END
$$;

CREATE FUNCTION opengeni_private.session_replies_muted_for_v1(p_session_id uuid, p_subject_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT p_subject_id IS NOT NULL AND (
    EXISTS (
      SELECT 1 FROM opengeni_private.inbox_session_mutes mute
      WHERE mute.session_id = p_session_id AND mute.subject_id = p_subject_id
    )
    OR EXISTS (
      SELECT 1 FROM opengeni_private.inbox_session_mutes mute
      WHERE mute.scheduled_task_id =
          (SELECT opengeni_private.session_reply_mute_schedule_v1(p_session_id))
        AND mute.subject_id = p_subject_id
    )
  )
$$;

CREATE FUNCTION opengeni_private.session_replies_muted_v1(p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT opengeni_private.session_replies_muted_for_v1(session.id,
    opengeni_private.session_person_v1(session.workspace_id, session.id,
      session.owner_subject_id, session.created_by_subject_id))
  FROM sessions session
  WHERE session.id = p_session_id
$$;

CREATE FUNCTION opengeni_private.session_reply_mute_schedule_v1(p_session_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT task.id
  FROM sessions session
  JOIN scheduled_task_runs run
    ON run.workspace_id = session.workspace_id AND run.session_id = session.id
  JOIN scheduled_tasks task ON task.id = run.task_id
  WHERE session.id = p_session_id AND task.run_mode = 'new_session_per_run'
  ORDER BY run.created_at DESC
  LIMIT 1
$$;

CREATE FUNCTION opengeni_private.session_spawn_denials_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  workspace_exists boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Workspace/account deletion is intentionally allowed to cascade through
    -- evidence rows. A direct row delete while its workspace still exists is
    -- never allowed, preserving append-only audit evidence for live tenants.
    IF pg_trigger_depth() > 1 THEN
      RETURN OLD;
    END IF;
    -- The FK cascade removes the parent workspace before its child rows are
    -- deleted. Resolve the target schema dynamically because embedded hosts
    -- run the same migration chain outside public.
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.workspaces WHERE id = $1)', TG_TABLE_SCHEMA)
      INTO workspace_exists
      USING OLD.workspace_id;
    IF NOT workspace_exists THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'session spawn denial evidence is append-only' USING ERRCODE = '55000';
END
$_$;

