CREATE FUNCTION opengeni_private.set_inbox_settings_v1(p_account_id uuid, p_subject_id text, p_tidy_policy text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
