CREATE FUNCTION opengeni_private.wake_teams_route_for_session_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
 prior_account text:=coalesce(current_setting('opengeni.account_id',true),'');
 prior_workspace text:=coalesce(current_setting('opengeni.workspace_id',true),'');
BEGIN
 -- The already-authorized native event supplies the exact scope. This uses
 -- the inserting role's ordinary Teams-table privileges, never an owner role.
 -- Some native lifecycle writers establish their own event audience rather
 -- than caller workspace GUCs; no actor identity is borrowed or changed here.
 PERFORM set_config('opengeni.account_id',NEW.account_id::text,true);
 PERFORM set_config('opengeni.workspace_id',NEW.workspace_id::text,true);
 UPDATE teams_bot_routes SET relevant_event_sequence=greatest(relevant_event_sequence,NEW.sequence)
 WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id AND session_id=NEW.session_id;
 PERFORM set_config('opengeni.account_id',prior_account,true);
 PERFORM set_config('opengeni.workspace_id',prior_workspace,true);
 RETURN NULL;
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('opengeni.account_id',prior_account,true);
 PERFORM set_config('opengeni.workspace_id',prior_workspace,true);
 RAISE;
END
$$;

CREATE FUNCTION opengeni_private.warming_reset_resume_state_v2(p_backend text, p_resume_backend_id text, p_resume_state jsonb, p_workspace_generation integer, p_archive_generation integer, p_reset_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql
    AS $$
  SELECT CASE
    WHEN coalesce(p_resume_state #>> '{sessionState,workspaceArchive}', '') <> ''
      OR coalesce(p_resume_state #>> '{sessionState,workspaceArchivePrev}', '') <> ''
    THEN jsonb_strip_nulls(jsonb_build_object(
      'backendId', coalesce(p_resume_state ->> 'backendId', p_resume_backend_id, p_backend),
      'sessionState', jsonb_strip_nulls(jsonb_build_object(
        'workspaceArchive', p_resume_state #> '{sessionState,workspaceArchive}',
        'workspaceArchiveMeta', p_resume_state #> '{sessionState,workspaceArchiveMeta}',
        'workspaceArchivePrev', p_resume_state #> '{sessionState,workspaceArchivePrev}',
        'workspaceArchivePrevMeta', p_resume_state #> '{sessionState,workspaceArchivePrevMeta}',
        'workspaceArchiveAt', p_resume_state #> '{sessionState,workspaceArchiveAt}'
      )),
      'opengeniRecovery', jsonb_build_object(
        'provider', jsonb_build_object(
          'status', 'not_created', 'instanceId', null, 'observedAt', to_jsonb(p_reset_at)
        ),
        'archive', coalesce(
          p_resume_state #> '{opengeniRecovery,archive}',
          jsonb_build_object(
            'status', CASE
              WHEN coalesce(p_resume_state #>> '{sessionState,workspaceArchive}', '') <> ''
                AND p_resume_state #> '{sessionState,workspaceArchiveMeta}' IS NOT NULL
              THEN 'available' ELSE 'unverified' END,
            'current', p_resume_state #> '{sessionState,workspaceArchiveMeta}',
            'previous', p_resume_state #> '{sessionState,workspaceArchivePrevMeta}'
          )
        ),
        'restore', jsonb_strip_nulls(jsonb_build_object(
          'status', CASE
            WHEN p_archive_generation = p_workspace_generation
              AND coalesce(p_resume_state #>> '{sessionState,workspaceArchive}', '') <> ''
              AND p_resume_state #> '{sessionState,workspaceArchiveMeta}' IS NOT NULL
            THEN 'pending' ELSE 'degraded' END,
          'rematerializationId', null,
          'selectedRevision', coalesce(
            p_resume_state #>> '{opengeniRecovery,archive,current,revision}',
            p_resume_state #>> '{sessionState,workspaceArchiveMeta,revision}'
          ),
          'startedAt', null,
          'completedAt', to_jsonb(p_reset_at),
          'failureCode', CASE
            WHEN p_archive_generation = p_workspace_generation
              AND coalesce(p_resume_state #>> '{sessionState,workspaceArchive}', '') <> ''
              AND p_resume_state #> '{sessionState,workspaceArchiveMeta}' IS NOT NULL
            THEN null ELSE 'archive_generation_mismatch' END,
          'retryable', CASE
            WHEN p_archive_generation = p_workspace_generation
              AND coalesce(p_resume_state #>> '{sessionState,workspaceArchive}', '') <> ''
              AND p_resume_state #> '{sessionState,workspaceArchiveMeta}' IS NOT NULL
            THEN null ELSE to_jsonb(false) END
        )),
        'workspace', jsonb_build_object(
          'status', CASE
            WHEN p_archive_generation = p_workspace_generation
              AND coalesce(p_resume_state #>> '{sessionState,workspaceArchive}', '') <> ''
              AND p_resume_state #> '{sessionState,workspaceArchiveMeta}' IS NOT NULL
            THEN 'not_ready' ELSE 'degraded' END,
          'verifiedRevision', null, 'verifiedAt', null
        )
      )
    ))
    ELSE null
  END;
$$;

CREATE FUNCTION opengeni_private.workspace_insights_amount_fact_rows(p_workspace_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_provider text, p_model text, p_root_session_id uuid, p_session_id uuid) RETURNS TABLE(id uuid, session_id uuid, root_session_id uuid, turn_id uuid, provider text, provider_api text, model text, billing_path text, scheduled_task_id uuid, input_tokens bigint, output_tokens bigint, cached_tokens bigint, cache_write_tokens bigint, reasoning_tokens bigint, total_tokens bigint, priced_cost_micros bigint, estimated_provider_cost_micros bigint, equivalent_credit_cost_micros bigint, pricing_source text, context_contributions jsonb, occurred_at timestamp with time zone, recorded_at timestamp with time zone, private_owner_key text, private_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    SET enable_nestloop TO 'off'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
    DECLARE
      account_value uuid;
      workspace_value uuid;
      subject_value text := nullif(current_setting('opengeni.subject_id', true), '');
      human_value text := nullif(current_setting('opengeni.initiating_human_subject_id', true), '');
      inventory uuid;
      previous_lifecycle text;
    BEGIN
      PERFORM opengeni_private.session_variable_set_attachments_protocol_v1_active();
      BEGIN
        account_value := nullif(current_setting('opengeni.account_id', true), '')::uuid;
        workspace_value := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'Insights amount context is malformed' USING ERRCODE = '42501';
      END;
      IF account_value IS NULL OR workspace_value IS DISTINCT FROM p_workspace_id
        OR p_workspace_id IS NULL THEN
        RAISE EXCEPTION 'Insights amount context does not match workspace' USING ERRCODE = '42501';
      END IF;
      IF p_since IS NULL OR p_until IS NULL OR NOT isfinite(p_since)
        OR NOT isfinite(p_until) OR p_until < p_since OR p_until - p_since > interval '370 days'
        OR (p_provider IS NOT NULL AND (btrim(p_provider) = '' OR octet_length(p_provider) > 256))
        OR (p_model IS NOT NULL AND (btrim(p_model) = '' OR octet_length(p_model) > 512)) THEN
        RAISE EXCEPTION 'Insights amount window or filters are invalid' USING ERRCODE = '22023';
      END IF;
      IF p_root_session_id IS NOT NULL OR p_session_id IS NOT NULL THEN
        -- No private amounts in a drilldown. Keep its exact existing visibility.
        RETURN QUERY SELECT visible.*, null::text, null::text
          FROM opengeni_private.visible_workspace_insights_model_fact_rows(
            p_workspace_id, p_since, p_until, p_provider, p_model, p_root_session_id, p_session_id
          ) visible;
        RETURN;
      END IF;
      inventory := opengeni_private.open_session_tenancy_fence_inventory({{schema_oid}}::oid);
      previous_lifecycle := current_setting('opengeni.organization_tenancy_lifecycle', true);
      PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
      INSERT INTO opengeni_private.insights_fact_read_runtime_capabilities
        (backend_pid, transaction_id, capability_kind, account_id, workspace_id, subject_id, initiating_human_subject_id)
      VALUES (pg_backend_pid(), pg_current_xact_id(), 'model_call_facts', account_value, p_workspace_id, subject_value, human_value);
      BEGIN
        RETURN QUERY
          WITH inventory_sessions AS MATERIALIZED (
            SELECT session_row.id, session_row.root_session_id,
              session_row.owner_subject_id, session_row.owner_organization_membership_id,
              (subject_value IS NULL OR session_row.visibility = 'workspace_shared'
                OR {{schema}}.session_private_actor_visible(session_row.account_id, session_row.workspace_id,
                  session_row.owner_organization_membership_id, session_row.owner_subject_id)) AS visible
            FROM {{schema}}.insights_audience_sessions session_row
            WHERE session_row.account_id = account_value AND session_row.workspace_id = p_workspace_id
          )
          SELECT
            CASE WHEN session_row.visible THEN fact.id END,
            CASE WHEN session_row.visible THEN fact.session_id END,
            CASE WHEN session_row.visible AND root_row.visible THEN root_row.id END,
            CASE WHEN session_row.visible THEN fact.turn_id END,
            fact.provider, fact.provider_api, fact.model, fact.billing_path,
            CASE WHEN session_row.visible THEN fact.scheduled_task_id END,
            fact.input_tokens, fact.output_tokens, fact.cached_tokens, fact.cache_write_tokens,
            fact.reasoning_tokens, fact.total_tokens, fact.priced_cost_micros,
            fact.estimated_provider_cost_micros, fact.equivalent_credit_cost_micros,
            fact.pricing_source, CASE WHEN session_row.visible THEN fact.context_contributions END,
            fact.occurred_at, fact.recorded_at,
            CASE WHEN NOT session_row.visible AND coalesce(session_row.owner_subject_id,
                session_row.owner_organization_membership_id::text) IS NOT NULL
              THEN encode(sha256(convert_to(account_value::text || ':' || coalesce(
                session_row.owner_subject_id, session_row.owner_organization_membership_id::text), 'UTF8')), 'hex') END,
            CASE WHEN NOT session_row.visible THEN coalesce(auth_user.name, access.subject_label) END
          FROM {{schema}}.model_call_facts fact
          LEFT JOIN inventory_sessions session_row ON session_row.id = fact.session_id
          LEFT JOIN inventory_sessions root_row ON root_row.id = session_row.root_session_id
          LEFT JOIN {{schema}}.workspace_memberships access ON access.account_id = account_value
            AND access.workspace_id = p_workspace_id AND access.subject_id = session_row.owner_subject_id
          LEFT JOIN {{schema}}.auth_users auth_user ON access.subject_id = 'user:' || auth_user.id
          WHERE fact.account_id = account_value AND fact.workspace_id = p_workspace_id
            AND fact.occurred_at >= p_since AND fact.occurred_at < p_until
            AND (p_provider IS NULL OR fact.provider = p_provider)
            AND (p_model IS NULL OR fact.model = p_model);
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
          WHERE backend_pid = pg_backend_pid() AND transaction_id = pg_current_xact_id_if_assigned()
            AND capability_kind = 'model_call_facts';
        PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory);
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true);
      EXCEPTION WHEN OTHERS THEN
        DELETE FROM opengeni_private.insights_fact_read_runtime_capabilities
          WHERE backend_pid = pg_backend_pid() AND transaction_id = pg_current_xact_id_if_assigned()
            AND capability_kind = 'model_call_facts';
        PERFORM opengeni_private.close_session_tenancy_fence_inventory(inventory);
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true);
        RAISE;
      END;
    END
    $$;

CREATE FUNCTION opengeni_private.workspace_member_custom_permissions_valid(p_permissions jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN pg_catalog.jsonb_typeof(p_permissions) IS DISTINCT FROM 'array' THEN false
    ELSE pg_catalog.jsonb_array_length(p_permissions) <= 128
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements_text(p_permissions) permission(value)
        WHERE permission.value NOT IN (
        'members:manage', 'workspace:read', 'workspace:admin',
        'sessions:create', 'sessions:read', 'sessions:control', 'stream:view',
        'stream:control', 'stream:acknowledge', 'files:upload', 'files:read',
        'files:write', 'terminal:attach', 'documents:manage', 'documents:search',
        'scheduled_tasks:manage', 'scheduled_tasks:run', 'github:manage',
        'github:use', 'api_keys:manage', 'connections:read', 'connections:write',
        'environments:manage', 'environments:use', 'variable-sets:list',
        'variable-sets:read', 'variable-sets:write', 'variable-sets:manage',
        'variable-sets:attach', 'variable-sets:use', 'secrets:list',
        'secrets:read', 'secrets:write', 'mcp_servers:attach', 'codemode:call',
        'goals:manage', 'enrollments:read', 'enrollments:manage', 'rigs:use',
        'rigs:manage', 'artifacts:read', 'artifacts:publish'
      )
    ) END
$$;

