CREATE TABLE governed_learning_decision_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    input_hash text NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    execution_generation integer NOT NULL,
    initiating_human_subject_id text NOT NULL,
    policy_snapshot_id uuid NOT NULL,
    policy_snapshot_hash text NOT NULL,
    policy_revision_id uuid,
    policy_activation_version bigint NOT NULL,
    source_kind text NOT NULL,
    source_id uuid NOT NULL,
    proposal_id uuid NOT NULL,
    proposal_input_hash text NOT NULL,
    proposal_content_hash text NOT NULL,
    claim_id uuid NOT NULL,
    claim_input_hash text NOT NULL,
    evidence_id uuid NOT NULL,
    evidence_input_hash text NOT NULL,
    evidence_content_hash text NOT NULL,
    evidence_authority_hash text NOT NULL,
    review_revision bigint NOT NULL,
    review_state text NOT NULL,
    effective_mode text NOT NULL,
    confidence_bps integer NOT NULL,
    conflict_count integer NOT NULL,
    outcome text NOT NULL,
    reason_codes text[] NOT NULL,
    automatic_eligible boolean NOT NULL,
    confidence_floor_bps integer NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT governed_learning_decision_receipts_decision_chk CHECK (((outcome = ANY (ARRAY['off'::text, 'suggest'::text, 'automatic'::text, 'confidence'::text, 'conflict'::text, 'stale'::text, 'revoked'::text])) AND opengeni_private.governed_learning_reason_codes_valid(reason_codes) AND (automatic_eligible = (outcome = 'automatic'::text)))),
    CONSTRAINT governed_learning_decision_receipts_facts_chk CHECK (((review_state = ANY (ARRAY['proposed'::text, 'approved'::text, 'rejected'::text, 'revoked'::text])) AND (effective_mode = ANY (ARRAY['off'::text, 'suggest'::text, 'automatic'::text])) AND ((confidence_bps >= 0) AND (confidence_bps <= 10000)) AND ((conflict_count >= 0) AND (conflict_count <= 1000)) AND (confidence_floor_bps = 8500))),
    CONSTRAINT governed_learning_decision_receipts_hashes_chk CHECK (((input_hash ~ '^[0-9a-f]{64}$'::text) AND (policy_snapshot_hash ~ '^[0-9a-f]{64}$'::text) AND (proposal_input_hash ~ '^[0-9a-f]{64}$'::text) AND (proposal_content_hash ~ '^[0-9a-f]{64}$'::text) AND (claim_input_hash ~ '^[0-9a-f]{64}$'::text) AND (evidence_input_hash ~ '^[0-9a-f]{64}$'::text) AND (evidence_content_hash ~ '^[0-9a-f]{64}$'::text) AND (evidence_authority_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT governed_learning_decision_receipts_identity_chk CHECK (((execution_generation > 0) AND ((length(btrim(initiating_human_subject_id)) >= 1) AND (length(btrim(initiating_human_subject_id)) <= 1024)) AND (octet_length(convert_to(initiating_human_subject_id, 'UTF8'::name)) <= 4096) AND (policy_activation_version >= 0) AND (review_revision > 0))),
    CONSTRAINT governed_learning_decision_receipts_source_chk CHECK (((source_kind = ANY (ARRAY['scoped-knowledge-evidence'::text, 'task-note'::text])) AND ((source_kind <> 'scoped-knowledge-evidence'::text) OR (source_id = evidence_id))))
);

ALTER TABLE ONLY governed_learning_decision_receipts FORCE ROW LEVEL SECURITY;

CREATE FUNCTION inspect_governed_learning_decisions(p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_limit integer DEFAULT 50) RETURNS SETOF governed_learning_decision_receipts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS NULL
    OR p_workspace_id IS NULL
    OR p_subject_id IS NULL
    OR p_subject_id = ''
    OR pg_catalog.octet_length(pg_catalog.convert_to(p_subject_id, 'UTF8')) > 1024
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR p_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR pg_catalog.current_setting('opengeni.principal_kind', true) IS DISTINCT FROM 'human_session'
  THEN
    RAISE EXCEPTION 'governed-learning inspection requires exact human tenant authority'
      USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 101 THEN
    RAISE EXCEPTION 'governed-learning inspection has invalid bounds'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT receipt.*
  FROM governed_learning_decision_receipts receipt
  WHERE receipt.account_id = p_account_id
    AND receipt.workspace_id = p_workspace_id
    AND receipt.initiating_human_subject_id = p_subject_id
    AND session_reference_visible(
      receipt.account_id, receipt.workspace_id, receipt.session_id
    )
  ORDER BY receipt.created_at DESC, receipt.id DESC
  LIMIT p_limit;
END;
$$;

CREATE FUNCTION inspect_organization_connection_authority_convergence(p_account_id uuid, p_limit integer DEFAULT 100, p_after_connection_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    SET statement_timeout TO '1min'
    AS $$
DECLARE
  audit_capability_id uuid := pg_catalog.gen_random_uuid();
  previous_audit_token text := pg_catalog.current_setting(
    'opengeni.connection_authority_convergence_audit_token', true
  );
  report jsonb;
BEGIN
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION 'connection convergence inspection requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_account_id IS DISTINCT FROM nullif(
    pg_catalog.current_setting('opengeni.account_id', true), ''
  )::uuid THEN
    RAISE EXCEPTION 'connection convergence inspection scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'connection convergence inspection limit must be 1..100'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO connection_authority_convergence_audit_capabilities (
    capability_id, backend_pid, transaction_id, account_id
  ) VALUES (
    audit_capability_id, pg_catalog.pg_backend_pid(),
    pg_catalog.pg_current_xact_id(), p_account_id
  );
  PERFORM pg_catalog.set_config(
    'opengeni.connection_authority_convergence_audit_token',
    audit_capability_id::text,
    true
  );

  -- A cursor is an organization-scoped persisted identifier, not an arbitrary
  -- UUID that may be used as a cross-tenant ordering oracle.
  IF p_after_connection_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM connections connection_row
    WHERE connection_row.account_id = p_account_id
      AND connection_row.id = p_after_connection_id
  ) THEN
    RAISE EXCEPTION 'connection convergence inspection cursor is invalid'
      USING ERRCODE = '22023';
  END IF;

  WITH classified AS MATERIALIZED (
    SELECT
      connection_row.id AS connection_id,
      connection_row.subject_id,
      CASE
        -- These are migration 0340's two terminal shapes. Exact terminal rows
        -- never appear in residual evidence.
        WHEN connection_row.authority_scope = 'workspace'
          AND connection_row.subject_id IS NULL
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND connection_row.origin_workspace_id = connection_row.workspace_id
          THEN NULL
        WHEN connection_row.authority_scope = 'user'
          AND connection_row.subject_id IS NOT NULL
          AND authority.id = connection_row.authority_id
          AND authority.resource_kind = 'connection'
          AND authority.resource_id = connection_row.id
          AND authority.organization_membership_id
            = connection_row.owner_organization_membership_id
          AND authority.origin_workspace_id = connection_row.origin_workspace_id
          AND authority.status = 'active'
          AND authority.revoked_at IS NULL
          AND owner_membership.id = connection_row.owner_organization_membership_id
          AND owner_membership.subject_id = connection_row.subject_id
          AND owner_membership.status = 'active'
          AND owner_membership.revoked_at IS NULL
          THEN NULL

        -- Only the exact legacy shape is eligible for an automated 0340
        -- transition. Malformed user or legacy rows need incident repair.
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND live_membership.id IS NOT NULL
          THEN 'connection_backfill_ready'
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND terminal_membership.id IS NOT NULL
          THEN 'membership_lifecycle_review_required'
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND (connection_row.subject_id IS NULL
            OR connection_row.subject_id NOT LIKE 'user:%')
          THEN 'external_subject_requires_classification'
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND login.id IS NULL
          THEN 'missing_login_identity'
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND (
            account.external_source IS DISTINCT FROM 'better-auth:user'
            OR account.external_id IS DISTINCT FROM substring(
              connection_row.subject_id FROM 6
            )
          )
          THEN 'organization_identity_mismatch'
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          AND owner_access.id IS NULL
          THEN 'missing_owner_workspace_membership'
        WHEN connection_row.authority_scope = 'legacy_user'
          AND connection_row.authority_id IS NULL
          AND connection_row.owner_organization_membership_id IS NULL
          THEN 'membership_backfill_eligible'
        WHEN connection_row.authority_scope = 'user'
          THEN 'conflicting_authority_rows'
        ELSE 'legacy_shape_unrecognized'
      END AS classification
    FROM connections connection_row
    JOIN managed_accounts account ON account.id = connection_row.account_id
    LEFT JOIN organization_memberships live_membership
      ON live_membership.account_id = connection_row.account_id
     AND live_membership.subject_id = connection_row.subject_id
     AND live_membership.status = 'active'
     AND live_membership.revoked_at IS NULL
    LEFT JOIN organization_memberships owner_membership
      ON owner_membership.id = connection_row.owner_organization_membership_id
     AND owner_membership.account_id = connection_row.account_id
    LEFT JOIN LATERAL (
      SELECT membership.id
      FROM organization_memberships membership
      WHERE membership.account_id = connection_row.account_id
        AND membership.subject_id = connection_row.subject_id
        AND (
          membership.status IN ('suspended', 'revoked')
          OR membership.revoked_at IS NOT NULL
        )
      ORDER BY membership.id
      LIMIT 1
    ) terminal_membership ON true
    LEFT JOIN organization_user_resource_authorities authority
      ON authority.id = connection_row.authority_id
     AND authority.account_id = connection_row.account_id
    LEFT JOIN auth_users login
      ON connection_row.subject_id LIKE 'user:%'
     AND login.id = substring(connection_row.subject_id FROM 6)
    LEFT JOIN LATERAL (
      SELECT access.id
      FROM workspace_memberships access
      JOIN workspaces workspace
        ON workspace.id = access.workspace_id
       AND workspace.account_id = access.account_id
      WHERE access.account_id = connection_row.account_id
        AND access.subject_id = connection_row.subject_id
        AND access.role = 'owner'
      ORDER BY access.id
      LIMIT 1
    ) owner_access ON true
    WHERE connection_row.account_id = p_account_id
  ), residual AS MATERIALIZED (
    SELECT
      connection_id,
      subject_id,
      classification,
      CASE classification
        WHEN 'connection_backfill_ready'
          THEN 'run_connection_backfill'
        WHEN 'membership_backfill_eligible'
          THEN 'run_membership_backfill_then_connection_backfill'
        WHEN 'membership_lifecycle_review_required'
          THEN 'review_membership_lifecycle_do_not_reactivate_automatically'
        WHEN 'external_subject_requires_classification'
          THEN 'classify_external_subject_then_migrate_via_authorized_connection_lifecycle'
        WHEN 'missing_login_identity'
          THEN 'restore_login_identity_then_recheck'
        WHEN 'organization_identity_mismatch'
          THEN 'correct_organization_identity_through_supported_account_lifecycle_then_recheck'
        WHEN 'missing_owner_workspace_membership'
          THEN 'establish_owner_workspace_membership_through_supported_membership_lifecycle_then_recheck'
        WHEN 'conflicting_authority_rows'
          THEN 'repair_conflicting_connection_authority_rows_under_incident_procedure'
        ELSE 'repair_unrecognized_connection_authority_shape_under_incident_procedure'
      END AS action
    FROM classified
    WHERE classification IS NOT NULL
  ), page_candidates AS MATERIALIZED (
    SELECT *
    FROM residual
    WHERE p_after_connection_id IS NULL
      OR connection_id > p_after_connection_id
    ORDER BY connection_id
    LIMIT p_limit + 1
  ), page AS MATERIALIZED (
    SELECT * FROM page_candidates ORDER BY connection_id LIMIT p_limit
  ), aggregate AS (
    SELECT
      (SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'connectionId', page.connection_id,
          'subjectId', page.subject_id,
          'classification', page.classification,
          'action', page.action
        ) ORDER BY page.connection_id), '[]'::jsonb) FROM page) AS items,
      (SELECT count(*)::int FROM page) AS returned,
      (SELECT count(*) > p_limit FROM page_candidates) AS has_more,
      (SELECT connection_id FROM page ORDER BY connection_id DESC LIMIT 1) AS next_id,
      count(*)::int AS remaining_total,
      count(*) FILTER (WHERE classification IN (
        'connection_backfill_ready', 'membership_backfill_eligible'
      ))::int AS auto_remediable,
      count(*) FILTER (WHERE classification NOT IN (
        'connection_backfill_ready', 'membership_backfill_eligible'
      ))::int AS manual_review,
      pg_catalog.jsonb_build_object(
        'connectionBackfillReady', count(*) FILTER (
          WHERE classification = 'connection_backfill_ready'
        )::int,
        'membershipBackfillEligible', count(*) FILTER (
          WHERE classification = 'membership_backfill_eligible'
        )::int,
        'membershipLifecycleReviewRequired', count(*) FILTER (
          WHERE classification = 'membership_lifecycle_review_required'
        )::int,
        'externalSubjectRequiresClassification', count(*) FILTER (
          WHERE classification = 'external_subject_requires_classification'
        )::int,
        'missingLoginIdentity', count(*) FILTER (
          WHERE classification = 'missing_login_identity'
        )::int,
        'organizationIdentityMismatch', count(*) FILTER (
          WHERE classification = 'organization_identity_mismatch'
        )::int,
        'missingOwnerWorkspaceMembership', count(*) FILTER (
          WHERE classification = 'missing_owner_workspace_membership'
        )::int,
        'conflictingAuthorityRows', count(*) FILTER (
          WHERE classification = 'conflicting_authority_rows'
        )::int,
        'legacyShapeUnrecognized', count(*) FILTER (
          WHERE classification = 'legacy_shape_unrecognized'
        )::int
      ) AS by_classification
    FROM residual
  )
  SELECT pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'organizationId', p_account_id,
    'limit', p_limit,
    'afterConnectionId', p_after_connection_id,
    'items', aggregate.items,
    'returned', aggregate.returned,
    'hasMore', aggregate.has_more,
    'nextCursor', CASE WHEN aggregate.has_more THEN aggregate.next_id ELSE NULL END,
    'remaining', pg_catalog.jsonb_build_object(
      'total', aggregate.remaining_total,
      'autoRemediable', aggregate.auto_remediable,
      'manualReview', aggregate.manual_review,
      'byClassification', aggregate.by_classification
    )
  ) INTO report
  FROM aggregate;

  DELETE FROM connection_authority_convergence_audit_capabilities
  WHERE capability_id = audit_capability_id;
  PERFORM pg_catalog.set_config(
    'opengeni.connection_authority_convergence_audit_token',
    coalesce(previous_audit_token, ''),
    true
  );
  RETURN report;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM connection_authority_convergence_audit_capabilities
  WHERE capability_id = audit_capability_id;
  PERFORM pg_catalog.set_config(
    'opengeni.connection_authority_convergence_audit_token',
    coalesce(previous_audit_token, ''),
    true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION inspect_organization_connection_authority_convergence(p_account_id uuid, p_limit integer, p_after_connection_id uuid) IS 'Bounded tenant-fenced residual connection evidence with global remaining counts and fixed remediation actions. Never writes authority.';

CREATE FUNCTION invalidate_unclaimed_scheduled_agent_runs_on_task_inactive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  run_row record;
  invalidation_error text;
BEGIN
  invalidation_error := CASE
    -- 0275 introduced deleted_at. JSON row introspection keeps this rolling
    -- trigger installable in legacy-upgrade fixtures that intentionally replay
    -- 0275 after the current tail, while current schemas still classify delete.
    WHEN pg_catalog.to_jsonb(OLD) ->> 'deleted_at' IS NULL
      AND pg_catalog.to_jsonb(NEW) ->> 'deleted_at' IS NOT NULL
      THEN 'scheduled_task_deleted_before_claim'
    ELSE 'scheduled_task_paused_before_claim'
  END;

  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (
    pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'run_lifecycle'
  )
  ON CONFLICT DO NOTHING;

  -- Run admission takes the task row first. Deposit and claim both lock the run
  -- before they can publish an occurrence or a scheduler-owned turn. Once this
  -- loop owns a run, a fresh turn lookup therefore decides the race exactly:
  -- no turn means no claim crossed the lifecycle boundary.
  FOR run_row IN
    SELECT run.id
    FROM scheduled_task_runs run
    WHERE run.account_id = NEW.account_id
      AND run.workspace_id = NEW.workspace_id
      AND run.task_id = NEW.id
      AND run.action_kind = 'agent_turn'
      AND run.status IN ('queued', 'dispatched')
    ORDER BY run.id
    FOR UPDATE
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM session_turns turn_value
      WHERE turn_value.account_id = NEW.account_id
        AND turn_value.workspace_id = NEW.workspace_id
        AND turn_value.scheduled_task_run_id = run_row.id
    ) THEN
      UPDATE scheduled_task_runs run
      SET status = 'skipped',
        error = invalidation_error,
        completed_at = pg_catalog.clock_timestamp(),
        updated_at = pg_catalog.clock_timestamp()
      WHERE run.id = run_row.id
        AND run.account_id = NEW.account_id
        AND run.workspace_id = NEW.workspace_id
        AND run.status IN ('queued', 'dispatched');
    END IF;
  END LOOP;

  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_lifecycle';
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_lifecycle';
  RAISE;
END
$$;

CREATE FUNCTION inventory_organization_tenancy(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'tenancy inventory requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_organization_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'tenancy inventory scope mismatch'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO opengeni_private.organization_tenancy_inventory_capabilities (
    backend_pid, transaction_id
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id())
  ON CONFLICT DO NOTHING;

  SELECT pg_catalog.jsonb_build_object(
    'schemaVersion', 2,
    'organizationId', p_organization_id,
    'workspaces', (
      SELECT count(*)::int FROM workspaces w WHERE w.account_id = p_organization_id
    ),
    'organizationMemberships', (
      SELECT pg_catalog.jsonb_build_object(
        'byStatus', coalesce(
          (SELECT pg_catalog.jsonb_object_agg(m.status, m.n)
           FROM (
             SELECT om.status, count(*)::int AS n
             FROM organization_memberships om
             WHERE om.account_id = p_organization_id
             GROUP BY om.status
           ) m),
          '{}'::jsonb
        ),
        'activeWithoutPersonalWorkspace', (
          SELECT count(*)::int FROM organization_memberships om
          WHERE om.account_id = p_organization_id
            AND om.status = 'active'
            AND om.personal_workspace_id IS NULL
        )
      )
    ),
    -- Humans with persisted workspace access in this organization but no
    -- organization-membership anchor: nothing exists yet for a backfill to
    -- attach canonical ownership to (they never re-authenticated post-0219).
    'workspaceMemberSubjectsWithoutMembershipAnchor', (
      SELECT count(DISTINCT wm.subject_id)::int
      FROM workspace_memberships wm
      JOIN workspaces w ON w.id = wm.workspace_id
      WHERE w.account_id = p_organization_id
        AND wm.subject_id LIKE 'user:%'
        AND NOT EXISTS (
          SELECT 1 FROM organization_memberships om
          WHERE om.account_id = p_organization_id
            AND om.subject_id = wm.subject_id
        )
    ),
    'sessions', (
      SELECT pg_catalog.jsonb_build_object(
        'total', count(*)::int,
        'ownerless', count(*) FILTER (
          WHERE s.owner_organization_membership_id IS NULL
        )::int,
        'userPrivate', count(*) FILTER (
          WHERE s.visibility = 'user_private'
        )::int,
        'advancedAuthorityEpoch', count(*) FILTER (
          WHERE s.authority_epoch > 1
        )::int
      )
      FROM sessions s WHERE s.account_id = p_organization_id
    ),
    -- Variable Sets, Rigs, and Connected Machines report ONLY the authority
    -- lane breakdown. An `unclassified` counter is deliberately absent: the
    -- shape checks REQUIRE a NULL authority_id for organization/workspace
    -- rows, `authority_scope` DEFAULTS to 'workspace', and no column records
    -- that a classification decision was ever made - see this migration's
    -- header for the per-family analysis.
    'variableSets', (
      SELECT pg_catalog.jsonb_build_object(
        'byScope', coalesce(
          (SELECT pg_catalog.jsonb_object_agg(v.authority_scope, v.n)
           FROM (
             SELECT vs.authority_scope, count(*)::int AS n
             FROM workspace_variable_sets vs
             WHERE vs.account_id = p_organization_id
             GROUP BY vs.authority_scope
           ) v),
          '{}'::jsonb
        )
      )
    ),
    'rigs', (
      SELECT pg_catalog.jsonb_build_object(
        'byScope', coalesce(
          (SELECT pg_catalog.jsonb_object_agg(r.authority_scope, r.n)
           FROM (
             SELECT rr.authority_scope, count(*)::int AS n
             FROM rigs rr WHERE rr.account_id = p_organization_id
             GROUP BY rr.authority_scope
           ) r),
          '{}'::jsonb
        )
      )
    ),
    'machines', (
      SELECT pg_catalog.jsonb_build_object(
        'byScope', coalesce(
          (SELECT pg_catalog.jsonb_object_agg(e.authority_scope, e.n)
           FROM (
             SELECT en.authority_scope, count(*)::int AS n
             FROM enrollments en WHERE en.account_id = p_organization_id
             GROUP BY en.authority_scope
           ) e),
          '{}'::jsonb
        )
      )
    ),
    'connections', (
      SELECT coalesce(
        (SELECT pg_catalog.jsonb_object_agg(c.authority_scope, c.n)
         FROM (
           SELECT cn.authority_scope, count(*)::int AS n
           FROM connections cn WHERE cn.account_id = p_organization_id
           GROUP BY cn.authority_scope
         ) c),
        '{}'::jsonb
      )
    ),
    -- Linked-input gate (documents-internal migration is owned elsewhere and
    -- never written by this program; the count is the cutover gate input).
    'documents', (
      SELECT pg_catalog.jsonb_build_object(
        'total', count(*)::int,
        -- The gate population is a LEGACY personal Document with no common
        -- authority - organization/workspace documents are REQUIRED to have
        -- a NULL authority_id forever (documents_authority_chk, 0258) and
        -- must never be counted as unmigrated.
        'legacyPersonalNullAuthority', count(*) FILTER (
          WHERE d.authority_kind = 'personal' AND d.authority_id IS NULL
        )::int
      )
      FROM documents d WHERE d.account_id = p_organization_id
    ),
    -- Linked-input gate (ownership repair is owned elsewhere; never backfilled
    -- heuristically; the count is the cutover gate input).
    'codexCredentials', (
      SELECT pg_catalog.jsonb_build_object(
        'total', count(*)::int,
        'unattributedConnector', count(*) FILTER (
          WHERE cc.connected_by_subject_id IS NULL
        )::int
      )
      FROM codex_subscription_credentials cc
      WHERE cc.account_id = p_organization_id
    ),
    'workspaceWriters', (
      SELECT pg_catalog.jsonb_build_object(
        'admissions', (
          SELECT pg_catalog.jsonb_build_object(
            'total', count(*)::int,
            'legacyUnattributed', count(*) FILTER (
              WHERE a.initiator_kind = 'legacy_unattributed'
            )::int
          )
          FROM sandbox_workspace_mutation_admissions a
          WHERE a.account_id = p_organization_id
        ),
        'retainedProcesses', (
          SELECT pg_catalog.jsonb_build_object(
            'total', count(*)::int,
            'legacyUnattributed', count(*) FILTER (
              WHERE p.initiator_kind = 'legacy_unattributed'
            )::int
          )
          FROM sandbox_retained_processes p
          WHERE p.account_id = p_organization_id
        )
      )
    )
  ) INTO result;

  DELETE FROM opengeni_private.organization_tenancy_inventory_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.organization_tenancy_inventory_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION issue_self_user_resource_grant(p_account_id uuid, p_authority_id uuid, p_workspace_id uuid, p_action text, p_mode text, p_context text, p_session_id uuid DEFAULT NULL::uuid, p_workspace_shared_acknowledged boolean DEFAULT false) RETURNS TABLE(grant_id uuid, target_workspace_id uuid, target_session_id uuid, action text, grant_mode text, grant_context text, grant_generation bigint, grant_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  owner_membership_id uuid;
  target_epoch integer;
  target_visibility text;
  normalized_action text := lower(btrim(p_action));
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR caller_subject IS NULL
  THEN
    RAISE EXCEPTION 'user-resource grant scope mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_mode NOT IN ('once', 'session', 'always')
    OR p_context NOT IN ('user_private', 'workspace_shared')
    OR normalized_action = 'connection.use' OR normalized_action = '' OR length(normalized_action) > 64
    OR normalized_action !~ '^[a-z0-9](?:[a-z0-9._:-]*[a-z0-9])?$'
  THEN
    RAISE EXCEPTION 'invalid user-resource grant request' USING ERRCODE = '22023';
  END IF;
  IF p_context = 'workspace_shared' AND NOT p_workspace_shared_acknowledged THEN
    RAISE EXCEPTION 'workspace_shared requires durable shared-output acknowledgement'
      USING ERRCODE = '42501';
  END IF;
  IF (p_mode = 'always' AND p_session_id IS NOT NULL)
    OR (p_mode IN ('once', 'session') AND p_session_id IS NULL)
  THEN
    RAISE EXCEPTION 'user-resource grant session fence is invalid' USING ERRCODE = '22023';
  END IF;

  SELECT membership.id INTO STRICT owner_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  FOR SHARE;

  PERFORM 1 FROM organization_user_resource_authorities authority
  WHERE authority.id = p_authority_id
    AND authority.account_id = p_account_id
    AND authority.organization_membership_id = owner_membership_id
    AND authority.status = 'active'
    AND authority.revoked_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'active self-owned user-resource authority required' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace_value
  WHERE workspace_value.id = p_workspace_id AND workspace_value.account_id = p_account_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target workspace is outside the organization' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM organization_memberships membership
  WHERE membership.id = owner_membership_id
    AND (membership.personal_workspace_id = p_workspace_id OR EXISTS (
      SELECT 1 FROM workspace_memberships workspace_membership
      WHERE workspace_membership.account_id = p_account_id
        AND workspace_membership.workspace_id = p_workspace_id
        AND workspace_membership.subject_id = caller_subject
    ));
  IF NOT FOUND THEN
    RAISE EXCEPTION 'owner lacks current target-workspace access' USING ERRCODE = '42501';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT session_value.authority_epoch, session_value.visibility
      INTO STRICT target_epoch, target_visibility
    FROM sessions session_value
    WHERE session_value.id = p_session_id
      AND session_value.account_id = p_account_id
      AND session_value.workspace_id = p_workspace_id
      AND session_value.status <> 'cancelled'
    FOR SHARE;
    IF target_visibility IS DISTINCT FROM p_context THEN
      RAISE EXCEPTION 'grant context does not match current session visibility'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO organization_user_resource_grants (
    account_id, authority_id, owner_organization_membership_id, workspace_id,
    session_id, action, mode, context, authority_epoch, generation, status
  ) VALUES (
    p_account_id, p_authority_id, owner_membership_id, p_workspace_id,
    p_session_id, normalized_action, p_mode, p_context, target_epoch, 1, 'active'
  )
  ON CONFLICT (account_id, authority_id, workspace_id, action, mode, context,
    (coalesce(session_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(authority_epoch, 0))) WHERE status = 'active'
  DO UPDATE SET updated_at = organization_user_resource_grants.updated_at
  RETURNING id, workspace_id, session_id, organization_user_resource_grants.action,
    mode, context, generation, status, organization_user_resource_grants.expires_at
  INTO grant_id, target_workspace_id, target_session_id, action, grant_mode,
    grant_context, grant_generation, grant_status, expires_at;
  RETURN NEXT;
END
$_$;

COMMENT ON FUNCTION issue_self_user_resource_grant(p_account_id uuid, p_authority_id uuid, p_workspace_id uuid, p_action text, p_mode text, p_context text, p_session_id uuid, p_workspace_shared_acknowledged boolean) IS 'Owner-only idempotent user-resource grant issue with server-derived owner/session fences.';

CREATE FUNCTION issue_self_user_resource_grant(p_account_id uuid, p_authority_id uuid, p_workspace_id uuid, p_resource_kind text, p_mode text, p_context text, p_session_id uuid DEFAULT NULL::uuid, p_expected_authority_epoch integer DEFAULT NULL::integer, p_workspace_shared_acknowledged boolean DEFAULT false) RETURNS TABLE(grant_id uuid, organization_id uuid, authority_generation bigint, target_workspace_id uuid, target_session_id uuid, action text, grant_mode text, grant_context text, authority_epoch integer, grant_generation bigint, grant_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  owner_membership_id uuid;
  target_epoch integer;
  target_visibility text;
  canonical_action text;
BEGIN
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true
  );
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
    OR caller_subject IS NULL
  THEN
    RAISE EXCEPTION 'user-resource grant scope mismatch' USING ERRCODE = '42501';
  END IF;
  canonical_action := CASE p_resource_kind
    WHEN 'document' THEN 'document.read'
    WHEN 'variable_set' THEN 'variable_set.use'
    WHEN 'rig' THEN 'rig.use'
    WHEN 'connected_machine' THEN 'connected_machine.use'
    ELSE NULL
  END;
  IF p_resource_kind IS NULL OR canonical_action IS NULL
    OR p_mode IS NULL OR p_mode NOT IN ('session', 'always')
    OR p_context IS NULL OR p_context NOT IN ('user_private', 'workspace_shared')
    OR (p_mode = 'always' AND (p_session_id IS NOT NULL OR p_expected_authority_epoch IS NOT NULL))
    OR (p_mode = 'session' AND (p_session_id IS NULL OR p_expected_authority_epoch IS NULL))
    OR coalesce(p_expected_authority_epoch, 1) <= 0
  THEN
    RAISE EXCEPTION 'invalid user-resource grant request' USING ERRCODE = '22023';
  END IF;
  IF p_context = 'workspace_shared' AND p_workspace_shared_acknowledged IS NOT TRUE THEN
    RAISE EXCEPTION 'workspace_shared requires durable shared-output acknowledgement'
      USING ERRCODE = '42501';
  END IF;
  -- 0611: every organization is session-tenancy activated.

  SELECT membership.id INTO owner_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'owner membership not found or access denied' USING ERRCODE = '42501';
  END IF;

  SELECT authority.generation INTO authority_generation
  FROM organization_user_resource_authorities authority
  WHERE authority.id = p_authority_id
    AND authority.account_id = p_account_id
    AND authority.organization_membership_id = owner_membership_id
    AND authority.resource_kind = p_resource_kind
    AND authority.status = 'active'
    AND authority.revoked_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'user-resource authority not found or access denied' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace_value
  WHERE workspace_value.id = p_workspace_id AND workspace_value.account_id = p_account_id
  FOR SHARE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM organization_memberships membership
    WHERE membership.id = owner_membership_id
      AND (
        membership.personal_workspace_id = p_workspace_id
        OR EXISTS (
          SELECT 1 FROM workspace_memberships workspace_membership
          WHERE workspace_membership.account_id = p_account_id
            AND workspace_membership.workspace_id = p_workspace_id
            AND workspace_membership.subject_id = caller_subject
        )
      )
  ) THEN
    RAISE EXCEPTION 'owner lacks current target-workspace access' USING ERRCODE = '42501';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT session_value.authority_epoch, session_value.visibility
      INTO target_epoch, target_visibility
    FROM sessions session_value
    WHERE session_value.id = p_session_id
      AND session_value.account_id = p_account_id
      AND session_value.workspace_id = p_workspace_id
      AND session_value.status <> 'cancelled'
    FOR SHARE;
    IF NOT FOUND
      OR target_visibility IS DISTINCT FROM p_context
      OR target_epoch IS DISTINCT FROM p_expected_authority_epoch
    THEN
      RAISE EXCEPTION 'target session not found or access denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE organization_user_resource_grants grant_value
  SET status = 'expired', updated_at = clock_timestamp()
  WHERE grant_value.account_id = p_account_id
    AND grant_value.authority_id = p_authority_id
    AND grant_value.status = 'active'
    AND grant_value.expires_at IS NOT NULL
    AND grant_value.expires_at <= clock_timestamp();

  INSERT INTO organization_user_resource_grants (
    account_id, authority_id, owner_organization_membership_id, workspace_id,
    session_id, action, mode, context, authority_epoch, generation, status
  ) VALUES (
    p_account_id, p_authority_id, owner_membership_id, p_workspace_id,
    p_session_id, canonical_action, p_mode, p_context, target_epoch, 1, 'active'
  )
  ON CONFLICT (account_id, authority_id, workspace_id, action, mode, context,
    (coalesce(session_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(authority_epoch, 0))) WHERE status = 'active'
  DO UPDATE SET updated_at = organization_user_resource_grants.updated_at
  RETURNING id, workspace_id, session_id, organization_user_resource_grants.action,
    mode, context, organization_user_resource_grants.authority_epoch, generation,
    status, organization_user_resource_grants.expires_at
  INTO grant_id, target_workspace_id, target_session_id, action, grant_mode,
    grant_context, authority_epoch, grant_generation, grant_status, expires_at;
  organization_id := p_account_id;
  RETURN NEXT;
END
$$;

COMMENT ON FUNCTION issue_self_user_resource_grant(p_account_id uuid, p_authority_id uuid, p_workspace_id uuid, p_resource_kind text, p_mode text, p_context text, p_session_id uuid, p_expected_authority_epoch integer, p_workspace_shared_acknowledged boolean) IS 'Issues server-action-derived session/always grants after exact owner and tenancy fences.';

CREATE FUNCTION knowledge_document_prepare(p_account uuid, p_workspace uuid, p_document uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE document documents%ROWTYPE; entry knowledge_entries%ROWTYPE; original files%ROWTYPE;
  obligation knowledge_source_sync_index_obligations%ROWTYPE; scheduled scheduled_task_runs%ROWTYPE;
  prior knowledge_entry_revisions%ROWTYPE; lease uuid; policy jsonb; body jsonb; result jsonb; actor jsonb;
  operation text:=p_request->>'operation'; accepted_at timestamptz; fingerprint text;
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR operation IS NULL OR operation NOT IN ('claim','complete') THEN
    RAISE EXCEPTION 'Invalid document preparation authority' USING ERRCODE='42501'; END IF;
  -- Same publication lock order as ordinary Knowledge writes.
  PERFORM pg_advisory_xact_lock(hashtextextended('knowledge-publication:'||p_account,0));
  SELECT * INTO document FROM documents d WHERE d.account_id=p_account AND d.workspace_id=p_workspace
    AND d.id=p_document FOR UPDATE;
  IF NOT FOUND OR document.status NOT IN ('indexing','ready') OR document.file_id IS DISTINCT FROM (p_request->>'fileId')::uuid THEN
    RAISE EXCEPTION 'Document original changed or is unavailable' USING ERRCODE='42501'; END IF;
  PERFORM set_config('opengeni.subject_id',coalesce(document.authority_subject_id,document.created_by,''),true);
  PERFORM set_config('opengeni.private_file_owner',coalesce(document.authority_subject_id,''),true);
  SELECT * INTO original FROM files f WHERE f.account_id=p_account AND f.id=document.file_id AND f.status='ready';
  IF NOT FOUND THEN RAISE EXCEPTION 'Document original unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO entry FROM knowledge_entries e WHERE e.account_id=p_account AND (e.legacy_document_id=p_document
    OR e.legacy_document_version_id IN (SELECT v.id FROM knowledge_document_versions v WHERE v.account_id=p_account AND v.document_id=p_document))
    ORDER BY (e.legacy_document_id=p_document) DESC NULLS LAST,e.created_at DESC LIMIT 1 FOR UPDATE;
  SELECT * INTO obligation FROM knowledge_source_sync_index_obligations o
    WHERE o.account_id=p_account AND o.workspace_id=p_workspace AND o.document_id=p_document
    ORDER BY o.object_version_generation DESC,o.created_at DESC LIMIT 1;
  IF obligation.id IS NOT NULL AND (obligation.status='invalidated' OR NOT EXISTS(
    SELECT 1 FROM knowledge_document_versions v
    JOIN knowledge_source_objects o ON o.account_id=v.account_id AND o.id=v.object_id AND o.lifecycle_state='active'
      AND o.current_version_id=v.id AND o.version_generation=obligation.object_version_generation
      AND o.lifecycle_generation=obligation.object_lifecycle_generation
    JOIN knowledge_sources s ON s.account_id=v.account_id AND s.id=v.source_id AND s.lifecycle_state='active'
      AND s.lifecycle_generation=obligation.source_lifecycle_generation AND s.current_acl_generation=v.acl_generation
    JOIN knowledge_providers p ON p.account_id=s.account_id AND p.id=s.provider_id AND p.lifecycle_state='active'
    WHERE v.account_id=p_account AND v.id=obligation.knowledge_document_version_id
      AND (v.document_id IS NULL OR v.document_id=p_document) AND (v.file_id IS NULL OR v.file_id=document.file_id)
  )) THEN RAISE EXCEPTION 'Source observation changed before preparation' USING ERRCODE='42501'; END IF;
  IF obligation.id IS NULL AND NOT google_drive_file_authorized(p_account,p_workspace,coalesce(document.authority_subject_id,document.created_by),document.file_id) THEN
    -- A normal upload cannot borrow a source-sync processing obligation.
    RAISE EXCEPTION 'Document original is no longer authorized' USING ERRCODE='42501'; END IF;
  IF operation='claim' THEN
    IF obligation.id IS NOT NULL THEN
      SELECT * INTO scheduled FROM scheduled_task_runs r WHERE r.account_id=p_account AND r.workspace_id=p_workspace
        AND r.id=obligation.scheduled_task_run_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Source indexing run is no longer available' USING ERRCODE='42501'; END IF;
      accepted_at:=scheduled.created_at;
      SELECT snapshot.snapshot INTO policy FROM agent_learning_snapshots snapshot
        JOIN session_turns t ON t.account_id=snapshot.account_id AND t.id=snapshot.turn_id
        WHERE t.account_id=p_account AND t.workspace_id=p_workspace AND t.scheduled_task_run_id=scheduled.id
        ORDER BY t.created_at LIMIT 1;
      IF scheduled.action_kind<>'agent_turn' OR policy IS NULL THEN
        RAISE EXCEPTION 'Source preparation requires an accepted agent learning snapshot' USING ERRCODE='42501'; END IF;
    ELSE
      -- An explicit old Document upload is human/service-authored source input,
      -- not an automatic finding. Its source copy keeps that existing authority.
      policy:=jsonb_build_object('effective',jsonb_build_object('knowledge','automatic'));
      accepted_at:=document.created_at;
    END IF;
    IF policy#>>'{effective,knowledge}'='off' THEN
      RETURN jsonb_build_object('status','disabled','fileId',document.file_id);
    END IF;
    IF entry.id IS NULL THEN
      INSERT INTO knowledge_entries(account_id,origin_workspace_id,scope,scope_workspace_id,scope_subject_id,
        legacy_document_id,legacy_document_version_id,access_document_id)
      VALUES(p_account,p_workspace,document.authority_kind,
        CASE WHEN document.authority_kind='workspace' THEN document.authority_workspace_id END,
        CASE WHEN document.authority_kind='personal' THEN document.authority_subject_id END,
        p_document,obligation.knowledge_document_version_id,p_document) RETURNING * INTO entry;
    END IF;
    IF entry.scope IS DISTINCT FROM document.authority_kind
      OR entry.scope_subject_id IS DISTINCT FROM document.authority_subject_id
      OR (entry.scope='workspace' AND entry.scope_workspace_id IS DISTINCT FROM document.authority_workspace_id) THEN
      RAISE EXCEPTION 'Document ownership differs from retained Knowledge' USING ERRCODE='42501'; END IF;
    lease:=gen_random_uuid();
    UPDATE knowledge_entries SET legacy_document_id=p_document,document_preparation=jsonb_build_object('leaseId',lease,
      'leaseUntil',clock_timestamp()+interval '15 minutes','expectedVersion',entry.version,
      'fileId',document.file_id,'policy',policy,'acceptedAt',accepted_at,'scheduledTaskRunId',scheduled.id)
      WHERE id=entry.id;
    RETURN jsonb_build_object('status','prepare','entryId',entry.id,'leaseId',lease,'fileId',document.file_id,'file',to_jsonb(original));
  END IF;
  IF entry.id IS NULL OR entry.document_preparation->>'leaseId' IS DISTINCT FROM p_request->>'leaseId'
    OR entry.document_preparation->>'fileId' IS DISTINCT FROM document.file_id::text THEN
    RAISE EXCEPTION 'Document preparation lease changed' USING ERRCODE='40001'; END IF;
  fingerprint:=encode(sha256(convert_to(p_request::text,'UTF8')),'hex');
  IF entry.document_preparation ? 'completion' THEN
    IF entry.document_preparation->>'completionHash' IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION 'Document preparation replay differs' USING ERRCODE='23505'; END IF;
    result:=entry.document_preparation->'completion';
    RETURN CASE WHEN result->>'status'='retained' THEN jsonb_set(result,'{receipt,replayed}','true'::jsonb) ELSE result END;
  END IF;
  IF (entry.document_preparation->>'leaseUntil')::timestamptz<=clock_timestamp() THEN
    RAISE EXCEPTION 'Document preparation lease expired' USING ERRCODE='40001'; END IF;
  IF p_request->>'codecVersion' IS DISTINCT FROM '1' OR jsonb_typeof(p_request->'content') IS DISTINCT FROM 'string'
    OR p_request->>'sourceVersion' !~ '^[0-9a-f]{64}$'
    OR (original.sha256 IS NOT NULL AND lower(original.sha256) IS DISTINCT FROM p_request->>'sourceVersion') THEN
    RAISE EXCEPTION 'Document extraction does not match its original' USING ERRCODE='22023'; END IF;
  IF entry.version IS DISTINCT FROM (entry.document_preparation->>'expectedVersion')::integer THEN
    RAISE EXCEPTION 'Knowledge changed during document processing' USING ERRCODE='40001'; END IF;
  SELECT * INTO prior FROM knowledge_entry_revisions r WHERE r.account_id=p_account AND r.id=entry.latest_revision_id;
  -- Re-reading an unchanged, rejected or archived source cannot publish it.
  IF prior.id IS NOT NULL AND (entry.archived OR (prior.body->'content'=p_request->'content'
    AND prior.body_codec_version=1 AND prior.body#>>'{source,version}'=p_request->>'sourceVersion')) THEN
    result:=jsonb_build_object('status','unchanged','entryId',entry.id,'revisionId',prior.id);
    UPDATE knowledge_entries SET document_preparation=document_preparation||jsonb_build_object('completionHash',fingerprint,'completion',result)
      WHERE id=entry.id;
    RETURN result;
  END IF;
  actor:=jsonb_build_object('kind','source_preparation','entryId',entry.id,'leaseId',p_request->'leaseId');
  UPDATE documents SET status='ready' WHERE id=p_document AND account_id=p_account;
  body:=jsonb_build_object('kind','source','title',p_request->'title','content',p_request->'content',
    'groupIds',coalesce(prior.body->'groupIds','[]'::jsonb),'relationships',coalesce(prior.body->'relationships','[]'::jsonb),
    'evidence',coalesce(prior.body->'evidence','[]'::jsonb),
    'source',jsonb_build_object('kind','file','documentId',p_document,'fileId',document.file_id,
      'version',p_request->'sourceVersion','retention','full_text'));
  result:=knowledge_entry_apply(p_account,p_workspace,actor,jsonb_build_object('operation','save',
    'operationId',p_request->'leaseId','entryId',entry.id,'expectedVersion',entry.version,
    'entry',body,'codecVersion',1,'preview',p_request->'preview','searchText',p_request->'searchText'));
  IF NOT knowledge_index_retention_active(p_account,entry.id,(result->>'revisionId')::uuid,p_document) THEN
    RAISE EXCEPTION 'Document source was withdrawn during processing' USING ERRCODE='42501'; END IF;
  result:=jsonb_build_object('status','retained','receipt',result);
  UPDATE knowledge_entries SET document_preparation=document_preparation||jsonb_build_object('completionHash',fingerprint,'completion',result) WHERE id=entry.id;
  RETURN result;
END $_$;

CREATE FUNCTION knowledge_document_visible(p_document uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS(SELECT 1 FROM documents d
    WHERE d.id=p_document AND d.account_id=nullif(current_setting('opengeni.account_id',true),'')::uuid
      AND d.status='ready'
      AND ((current_setting('opengeni.knowledge_actor_kind',true)='human' OR (current_setting('opengeni.knowledge_actor_kind',true)='source_preparation' AND d.id::text=current_setting('opengeni.knowledge_prepared_document',true))) OR d.agent_access)
      AND (d.authority_kind='organization'
        OR (d.authority_kind='workspace' AND d.authority_workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid)
        OR (d.authority_kind='personal' AND d.authority_subject_id=nullif(current_setting('opengeni.subject_id',true),'')
          AND ((d.authority_id IS NULL AND d.authority_workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid)
            OR (d.authority_id IS NOT NULL AND ((current_setting('opengeni.knowledge_actor_kind',true)='human' OR (current_setting('opengeni.knowledge_actor_kind',true)='source_preparation' AND d.id::text=current_setting('opengeni.knowledge_prepared_document',true)))
              OR d.id IN (SELECT resolve_session_attempt_personal_document_reads(d.account_id,
                nullif(current_setting('opengeni.workspace_id',true),'')::uuid,
                nullif(current_setting('opengeni.knowledge_session_id',true),'')::uuid,
                nullif(current_setting('opengeni.knowledge_attempt_id',true),'')::uuid)))))))
      AND ((current_setting('opengeni.knowledge_actor_kind',true)='source_preparation'
        AND d.id::text=current_setting('opengeni.knowledge_prepared_document',true))
        OR google_drive_file_authorized(d.account_id,nullif(current_setting('opengeni.workspace_id',true),'')::uuid,
          nullif(current_setting('opengeni.subject_id',true),''),d.file_id)))
$$;

CREATE FUNCTION knowledge_enqueue_index() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  attribution jsonb := '{"kind":"unknown"}'::jsonb;
  causal_turn opengeni_private.usage_allowance_attribution_receipts%ROWTYPE;
  preparation jsonb;
  accepted jsonb;
  document_attribution jsonb;
  billing_workspace uuid := nullif(current_setting('opengeni.workspace_id',true),'')::uuid;
  opened integer := 0;
  previous text := current_setting('opengeni.knowledge_index_dispatcher',true);
BEGIN
  IF NEW.change_kind='archive' THEN RETURN NEW; END IF;
  -- The accepted actor's publication transaction is trusted; the trigger
  -- needs only the same tenant's immutable initiating facts through FORCE-RLS,
  -- including private turns, without reading their content. Reuse 0547's exact
  -- owner-only SELECT capability over content-free accounting receipts.
  -- Organization publication/indexing has no workspace billing scope. It
  -- needs no workspace receipt authority and must not mint a NULL/synthetic
  -- workspace stamp. Exact turn/schedule attribution still requires one.
  IF billing_workspace IS NOT NULL THEN
    INSERT INTO opengeni_private.usage_allowance_capabilities
      VALUES(pg_backend_pid(),pg_current_xact_id(),TG_TABLE_SCHEMA,NEW.account_id,billing_workspace)
      ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS opened = ROW_COUNT;
  END IF;
  -- knowledge_entry_apply already resolved the trusted actor and held the exact
  -- attempt/publication locks. Do not read a session's latest turn or creator.
  IF NEW.actor->>'kind'='agent' THEN
    SELECT * INTO causal_turn FROM opengeni_private.usage_allowance_attribution_receipts t
      WHERE t.account_id=NEW.account_id AND t.workspace_id=billing_workspace
        AND t.source_kind='turn' AND t.source_id=NEW.created_by_turn_id::text
        AND t.session_id=NEW.created_by_session_id
        AND t.source_id=NEW.actor->>'turnId';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Knowledge initiating turn unavailable' USING ERRCODE='42501';
    END IF;
    attribution:=causal_turn.attribution;
  ELSIF NEW.actor->>'kind'='human' AND NEW.actor->>'principalKind'='human_session'
    AND current_setting('opengeni.knowledge_actor_kind',true)='human'
    AND NEW.actor->>'subjectId'=nullif(current_setting('opengeni.subject_id',true),'') THEN
    attribution:=jsonb_build_object('kind','human',
      'initiatingHumanSubjectId',NEW.actor->>'subjectId');
  ELSIF NEW.actor->>'kind'='service'
    AND current_setting('opengeni.knowledge_actor_kind',true)='service' THEN
    attribution:='{"kind":"service"}'::jsonb;
  ELSIF NEW.actor->>'kind'='source_preparation' THEN
    -- The preparation lease retains the accepted scheduled occurrence, not a
    -- mutable task creator. Older direct uploads have only created_by/ownership
    -- labels and remain unknown rather than falsely becoming service debits.
    SELECT e.document_preparation,d.billing_attribution INTO preparation,document_attribution
      FROM knowledge_entries e LEFT JOIN documents d
        ON d.account_id=e.account_id AND d.id=e.legacy_document_id
      WHERE e.account_id=NEW.account_id AND e.id=NEW.entry_id;
    IF preparation->>'scheduledTaskRunId' IS NOT NULL THEN
      SELECT r.attribution INTO accepted FROM opengeni_private.usage_allowance_attribution_receipts r
        WHERE r.account_id=NEW.account_id AND r.workspace_id=billing_workspace
          AND r.source_kind='schedule'
          AND r.source_id=(preparation->>'scheduledTaskRunId')::uuid::text;
      attribution:=coalesce(accepted,'{"kind":"unknown"}'::jsonb);
    ELSE
      attribution:=coalesce(document_attribution,'{"kind":"unknown"}'::jsonb);
    END IF;
  END IF;
  PERFORM set_config('opengeni.knowledge_index_dispatcher','1',true);
  INSERT INTO knowledge_index_jobs(account_id,entry_id,revision_id,billing_attribution)
    VALUES(NEW.account_id,NEW.entry_id,NEW.id,attribution);
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  IF opened=1 THEN
    DELETE FROM opengeni_private.usage_allowance_capabilities
      WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
        AND data_schema=TG_TABLE_SCHEMA AND account_id=NEW.account_id AND workspace_id=billing_workspace;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_entry_apply(p_account uuid, p_workspace uuid, p_actor jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
<<knowledge_entry_apply>>
DECLARE actor jsonb; e knowledge_entries%ROWTYPE; r knowledge_entry_revisions%ROWTYPE;
  prior knowledge_entry_operations%ROWTYPE; body jsonb; codec integer; scope_value text;
  operation text:=p_request->>'operation'; operation_id uuid:=(p_request->>'operationId')::uuid;
  entry_id uuid:=(p_request->>'entryId')::uuid; revision_id uuid; old_revision uuid;
  batch_id uuid; owner_key text; disposition text; fingerprint text; result jsonb; next_number integer;
  mode text:='automatic'; restored_id uuid; search_text text;
BEGIN
  IF operation IS NULL OR operation NOT IN ('save','promote_note','approve','approve_edit','reject','restore','archive')
    OR operation_id IS NULL OR entry_id IS NULL OR (p_request->>'expectedVersion')::integer<0 THEN
    RAISE EXCEPTION 'Invalid Knowledge operation' USING ERRCODE='22023';
  END IF;
  actor:=knowledge_resolve_actor(p_account,p_workspace,p_actor);
  IF actor->>'kind'='agent' AND operation IN ('approve','approve_edit','reject') THEN
    RAISE EXCEPTION 'Agents cannot approve their own Knowledge' USING ERRCODE='42501';
  END IF;
  IF operation IN ('approve','approve_edit','reject') AND actor->>'review' IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'Knowledge review permission required' USING ERRCODE='42501';
  END IF;
  -- Serialize publications and reference validation within an organization.
  -- No organization row is locked after a workspace: this key has no FK path.
  PERFORM pg_advisory_xact_lock(hashtextextended('knowledge-publication:'||p_account,0));
  -- Authenticate the live attempt above, but bind retries to logical work.
  -- Recovery changes the physical attempt, never the operation's session/turn.
  fingerprint:=encode(sha256(convert_to(jsonb_build_array(
    CASE WHEN p_actor->>'kind'='agent' THEN p_actor-'attemptId'-'executionGeneration' ELSE p_actor END,
    p_request)::text,'UTF8')),'hex');
  SELECT * INTO prior FROM knowledge_entry_operations o WHERE o.account_id=p_account AND o.operation_id=knowledge_entry_apply.operation_id;
  IF FOUND THEN
    IF prior.request_hash<>fingerprint OR prior.origin_workspace_id<>p_workspace THEN
      RAISE EXCEPTION 'Knowledge operation key reused' USING ERRCODE='23505';
    END IF;
    SELECT * INTO e FROM knowledge_entries h WHERE h.account_id=p_account AND h.id=prior.entry_id;
    IF NOT knowledge_scope_visible(e) THEN RAISE EXCEPTION 'Knowledge unavailable' USING ERRCODE='42501'; END IF;
    RETURN prior.receipt||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO e FROM knowledge_entries h WHERE h.account_id=p_account AND h.id=entry_id FOR UPDATE;
  scope_value:=coalesce(e.scope,p_request->>'scope',actor->>'defaultScope');
  IF e.id IS NOT NULL AND (NOT knowledge_scope_visible(e)
    OR (p_request ? 'scope' AND p_request->>'scope'<>e.scope)) THEN
    RAISE EXCEPTION 'Knowledge scope is unavailable or immutable' USING ERRCODE='42501';
  END IF;
  IF actor->>'kind' IN ('agent','source_preparation') THEN
    IF actor->>'kind'='source_preparation' AND (operation<>'save' OR entry_id IS DISTINCT FROM (actor->>'entryId')::uuid
      OR p_request#>>'{entry,kind}' IS DISTINCT FROM 'source' OR p_request#>>'{entry,source,documentId}' IS DISTINCT FROM e.legacy_document_id::text) THEN
      RAISE EXCEPTION 'Source preparation is limited to its retained original' USING ERRCODE='42501'; END IF;
    IF (scope_value IS DISTINCT FROM actor->>'defaultScope'
        AND NOT (actor->>'kind'='agent' AND actor->>'defaultScope'='personal' AND scope_value='workspace'))
      OR (actor->>'retentionScope'='session' AND e.id IS NOT NULL
      AND (e.legacy_scope_type IS DISTINCT FROM 'session' OR e.legacy_scope_session_id IS DISTINCT FROM (actor->>'sessionId')::uuid)) THEN
      RAISE EXCEPTION 'Agent Knowledge stays in its accepted scope' USING ERRCODE='42501';
    END IF;
    mode:=actor#>>'{policy,effective,knowledge}';
    IF actor->>'kind'='agent' AND actor->>'defaultScope'='personal' AND scope_value='workspace'
      AND get_workspace_kind(p_account,p_workspace)<>'personal' THEN
      mode:=(SELECT CASE WHEN 'off' IN (mode,m) OR m IS NULL OR mode IS NULL THEN 'off'
          WHEN 'review_first' IN (mode,m) THEN 'review_first' ELSE 'automatic' END
        FROM (SELECT knowledge_learning_resolve(p_account,p_workspace,NULL,
          coalesce(actor#>>'{policy,contextKey}','defaults'),
          coalesce((actor#>>'{policy,acceptedAt}')::timestamptz,transaction_timestamp()))#>>'{effective,knowledge}' AS m) workspace_policy);
    END IF;
    IF mode IS NULL OR mode NOT IN ('automatic','review_first') THEN
      RAISE EXCEPTION 'Knowledge learning is Off for this task' USING ERRCODE='42501';
    END IF;
  ELSIF NOT coalesce((actor->'writeScopes') ? scope_value,false) THEN
    RAISE EXCEPTION 'Knowledge write permission required for this scope' USING ERRCODE='42501';
  END IF;
  IF e.id IS NULL THEN
    IF operation NOT IN ('save','promote_note') OR (p_request->>'expectedVersion')::integer IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'Knowledge entry changed or unavailable' USING ERRCODE='40001';
    END IF;
    INSERT INTO knowledge_entries(id,account_id,origin_workspace_id,scope,scope_workspace_id,scope_subject_id,legacy_scope_type,legacy_scope_session_id)
      VALUES(entry_id,p_account,p_workspace,scope_value,CASE WHEN scope_value='workspace' THEN p_workspace END,
        CASE WHEN scope_value='personal' THEN actor->>'subjectId' END,
        CASE WHEN actor->>'retentionScope'='session' THEN 'session' END,
        CASE WHEN actor->>'retentionScope'='session' THEN (actor->>'sessionId')::uuid END) RETURNING * INTO e;
  ELSIF e.version IS DISTINCT FROM (p_request->>'expectedVersion')::integer THEN
    RAISE EXCEPTION 'Knowledge entry changed; read its current revision' USING ERRCODE='40001';
  END IF;
  IF e.archived AND operation<>'restore' THEN
    RAISE EXCEPTION 'Restore archived Knowledge before editing it' USING ERRCODE='22023';
  END IF;
  old_revision:=e.published_revision_id;
  disposition:=CASE WHEN mode='review_first' THEN 'pending' ELSE 'published' END;
  IF operation IN ('approve','approve_edit','reject','restore','archive') THEN
    SELECT * INTO r FROM knowledge_entry_revisions v WHERE v.account_id=p_account AND v.entry_id=e.id
      AND v.id=CASE WHEN operation='archive' THEN e.latest_revision_id ELSE (p_request->>'revisionId')::uuid END;
    IF NOT FOUND THEN RAISE EXCEPTION 'Knowledge revision unavailable' USING ERRCODE='42501'; END IF;
    IF operation IN ('approve','approve_edit','reject') AND (r.id IS DISTINCT FROM e.latest_revision_id
      OR NOT EXISTS(SELECT 1 FROM knowledge_entry_decisions d WHERE d.account_id=p_account AND d.entry_id=e.id
        AND d.revision_id=r.id AND d.version=e.version AND d.outcome='pending')) THEN
      RAISE EXCEPTION 'This Knowledge review is no longer current' USING ERRCODE='40001';
    END IF;
    body:=r.body; codec:=r.body_codec_version;
    revision_id:=r.id; batch_id:=r.review_batch_id;
    IF operation IN ('restore','archive') THEN restored_id:=r.id; END IF;
    IF operation='approve_edit' THEN
      IF r.change_kind='archive' THEN RAISE EXCEPTION 'An archive proposal has no editable content' USING ERRCODE='22023'; END IF;
      body:=p_request->'entry'; codec:=(p_request->>'codecVersion')::integer;
    END IF;
  ELSIF operation='save' THEN
    body:=p_request->'entry'; codec:=(p_request->>'codecVersion')::integer;
  ELSIF operation='promote_note' THEN
    body:=knowledge_task_note_source(p_account,p_workspace,p_actor,(p_request->>'noteId')::uuid,
      (p_request->>'expectedNoteVersion')::integer)||jsonb_build_object('kind','note','title',p_request->>'title',
        'evidence','[]'::jsonb,'relationships','[]'::jsonb,'groupIds',p_request->'groupIds');
    codec:=NULL;
  END IF;

  IF operation IN ('save','promote_note','approve_edit','restore','archive') THEN
    IF jsonb_typeof(body) IS DISTINCT FROM 'object' OR jsonb_typeof(body->'title') IS DISTINCT FROM 'string'
      OR jsonb_typeof(body->'content') IS DISTINCT FROM 'string'
      OR body->>'kind' NOT IN ('source','fact','decision','requirement','incident','note','group')
      OR body->>'kind' IS NULL OR length(body->>'title') NOT BETWEEN 1 AND 8192
      OR (body->>'kind' NOT IN ('group','source') AND length(btrim(body->>'content'))=0)
      OR (body->>'kind'='source' AND jsonb_typeof(body->'source') IS DISTINCT FROM 'object')
      OR jsonb_typeof(body->'evidence') IS DISTINCT FROM 'array' OR (operation IN ('save','promote_note','approve_edit') AND jsonb_array_length(body->'evidence')>256)
      OR jsonb_typeof(body->'groupIds') IS DISTINCT FROM 'array' OR (operation IN ('save','promote_note','approve_edit') AND jsonb_array_length(body->'groupIds')>256)
      OR jsonb_typeof(body->'relationships') IS DISTINCT FROM 'array' OR (operation IN ('save','promote_note','approve_edit') AND jsonb_array_length(body->'relationships')>256)
      OR (codec IS NOT NULL AND codec<>1) THEN
      RAISE EXCEPTION 'Invalid Knowledge entry content' USING ERRCODE='22023';
    END IF;
    IF EXISTS(SELECT 1 FROM knowledge_entry_revisions v WHERE v.account_id=p_account AND v.id=e.latest_revision_id
      AND (v.body->>'kind'='group')<>(knowledge_entry_apply.body->>'kind'='group')) THEN
      RAISE EXCEPTION 'A Knowledge group cannot become a content entry' USING ERRCODE='22023';
    END IF;
    IF disposition='pending' THEN
      owner_key:=CASE scope_value WHEN 'personal' THEN 'personal:'||e.scope_subject_id
        WHEN 'organization' THEN 'organization:'||p_account ELSE 'workspace:'||e.scope_workspace_id END;
      SELECT id INTO batch_id FROM knowledge_review_batches b WHERE b.account_id=p_account AND b.owner_key=knowledge_entry_apply.owner_key
        AND ((actor->>'scheduledTaskRunId' IS NOT NULL AND b.scheduled_task_run_id=(actor->>'scheduledTaskRunId')::uuid)
          OR (actor->>'scheduledTaskRunId' IS NULL AND b.turn_id=(actor->>'turnId')::uuid));
      IF batch_id IS NULL THEN
        INSERT INTO knowledge_review_batches(account_id,origin_workspace_id,owner_key,session_id,turn_id,scheduled_task_run_id)
          VALUES(p_account,p_workspace,owner_key,(actor->>'sessionId')::uuid,(actor->>'turnId')::uuid,
            (actor->>'scheduledTaskRunId')::uuid) RETURNING id INTO batch_id;
      END IF;
    ELSE batch_id:=NULL; END IF;
    IF operation<>'archive' THEN
      PERFORM knowledge_validate_source(p_account,e.id,body);
      PERFORM knowledge_validate_links(p_account,e.id,body,batch_id);
    END IF;
    SELECT coalesce(max(v.number),0)+1 INTO next_number FROM knowledge_entry_revisions v WHERE v.account_id=p_account AND v.entry_id=e.id;
    INSERT INTO knowledge_entry_revisions(account_id,entry_id,number,body,body_codec_version,preview,preview_codec_version,
      previous_revision_id,restored_from_revision_id,actor,created_by_session_id,created_by_turn_id,review_batch_id,change_kind)
      VALUES(p_account,e.id,next_number,body,codec,coalesce(p_request->>'preview',r.preview,substring(body->>'content' FROM 1 FOR 512)),
        CASE WHEN p_request ? 'preview' THEN 1 ELSE r.preview_codec_version END,e.latest_revision_id,restored_id,p_actor,
        (actor->>'sessionId')::uuid,(actor->>'turnId')::uuid,batch_id,
        CASE WHEN operation='archive' THEN 'archive' ELSE 'upsert' END) RETURNING id INTO revision_id;
    INSERT INTO knowledge_entry_links(account_id,entry_id,revision_id,ordinal,target_entry_id,target_revision_id,relation)
      SELECT p_account,e.id,revision_id,(row_number() OVER ())::integer-1,links.target,links.rev,links.relation
      FROM (
        SELECT (x->>'entryId')::uuid AS target,(x->>'revisionId')::uuid AS rev,'evidence' AS relation
          FROM jsonb_array_elements(body->'evidence') x
        UNION ALL SELECT x::uuid,NULL,'group' FROM jsonb_array_elements_text(body->'groupIds') x
        UNION ALL SELECT (x->>'entryId')::uuid,NULL,x->>'relation' FROM jsonb_array_elements(body->'relationships') x
      ) links;
    IF operation='archive' AND disposition='published' THEN disposition:='archived'; END IF;
  ELSIF operation='approve' THEN
    IF r.change_kind='archive' THEN disposition:='archived';
    ELSE
      PERFORM knowledge_validate_source(p_account,e.id,body);
      PERFORM knowledge_validate_links(p_account,e.id,body,NULL);
      disposition:='published';
    END IF;
  ELSIF operation='reject' THEN disposition:='rejected';
  END IF;
  UPDATE knowledge_entries h SET version=e.version+1,latest_revision_id=revision_id,
    published_revision_id=CASE WHEN disposition='published' THEN revision_id ELSE h.published_revision_id END,
    archived=CASE WHEN disposition='archived' THEN true WHEN operation='restore' AND disposition='published' THEN false ELSE h.archived END,
    updated_at=clock_timestamp() WHERE h.account_id=p_account AND h.id=e.id;
  INSERT INTO knowledge_entry_decisions(account_id,entry_id,revision_id,version,outcome,actor,policy_snapshot)
    VALUES(p_account,e.id,revision_id,e.version+1,disposition,p_actor,actor->'policy');
  IF operation IN ('save','promote_note','approve_edit','restore','archive') THEN
    -- The adapter supplies a lossless-text search projection; it is not evidence.
    search_text:=coalesce(p_request->>'searchText',(body->>'title')||' '||(body->>'content'));
    IF restored_id IS NOT NULL THEN
      INSERT INTO knowledge_entry_search(account_id,entry_id,revision_id,chunk_index,search_vector)
        SELECT p_account,e.id,knowledge_entry_apply.revision_id,v.chunk_index,v.search_vector FROM knowledge_entry_search v
        WHERE v.account_id=p_account AND v.entry_id=e.id AND v.revision_id=restored_id;
    ELSE
      PERFORM knowledge_index_revision(p_account,e.id,revision_id,search_text);
    END IF;
  END IF;
  result:=jsonb_build_object('operationId',operation_id,'entryId',e.id,'revisionId',revision_id,
    'version',e.version+1,'outcome',disposition,'reviewBatchId',batch_id,'replayed',false);
  INSERT INTO knowledge_entry_operations(account_id,origin_workspace_id,operation_id,entry_id,actor,request_hash,receipt)
    VALUES(p_account,p_workspace,operation_id,e.id,p_actor,fingerprint,result);
  RETURN result;
END $$;

CREATE FUNCTION knowledge_entry_confirm_legacy(p_account uuid, p_workspace uuid, p_actor jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor jsonb; entry knowledge_entries%ROWTYPE; revision knowledge_entry_revisions%ROWTYPE;
  question session_human_input_requests%ROWTYPE; evidence knowledge_claim_evidence%ROWTYPE;
  prior knowledge_entry_operations%ROWTYPE; human_actor jsonb; note jsonb; subject text;
  candidate record; recovered jsonb; native_recovery jsonb; unavailable integer:=0;
  prior_principal text:=current_setting('opengeni.principal_kind',true); result jsonb; exact_text text;
BEGIN
  IF p_actor->>'kind' IS DISTINCT FROM 'agent' THEN
    RAISE EXCEPTION 'Legacy confirmation requires an exact agent attempt' USING ERRCODE='42501'; END IF;
  IF p_request ? 'proposalId' THEN
    RETURN knowledge_instruction_confirm_legacy(p_account,p_workspace,p_actor,p_request);
  END IF;
  IF p_request->>'operation'='recover' THEN
    native_recovery:=knowledge_instruction_confirm_legacy(p_account,p_workspace,p_actor,p_request);
  END IF;
  actor:=knowledge_resolve_actor(p_account,p_workspace,p_actor);
  subject:=nullif(current_setting('opengeni.subject_id',true),'');
  IF p_request->>'operation'='recover' THEN
    result:='[]'::jsonb;
    FOR candidate IN
      SELECT DISTINCT e.legacy_claim_id AS claim_id,q.id AS request_id
      FROM session_human_input_requests q CROSS JOIN LATERAL jsonb_array_elements(q.questions) question_value
      JOIN knowledge_entries e ON e.legacy_claim_id::text=substring(question_value->>'id' FROM 10)
        AND e.account_id=q.account_id AND e.scope_workspace_id=q.workspace_id
      JOIN knowledge_entry_revisions r ON r.id=e.latest_revision_id AND r.account_id=e.account_id
      WHERE q.account_id=p_account AND q.workspace_id=p_workspace AND q.session_id=(p_actor->>'sessionId')::uuid
        AND q.turn_id=(p_actor->>'turnId')::uuid AND q.status='answered' AND q.responded_by=subject
        AND question_value->>'id' LIKE 'remember:%' AND r.number=1 AND r.legacy_snapshot IS NOT NULL
      ORDER BY e.legacy_claim_id,q.id
    LOOP
      BEGIN
        recovered:=knowledge_entry_confirm_legacy(p_account,p_workspace,p_actor,jsonb_build_object(
          'operationId',overlay(overlay(md5('opengeni:legacy-confirmation:'||candidate.request_id||':'||candidate.claim_id) placing '5' from 13 for 1) placing '8' from 17 for 1)::uuid,
          'claimId',candidate.claim_id,'humanInputRequestId',candidate.request_id));
        result:=result||jsonb_build_array(recovered);
      EXCEPTION WHEN insufficient_privilege OR serialization_failure THEN unavailable:=unavailable+1;
      END;
    END LOOP;
    RETURN jsonb_build_object('receipts',result,'instructionReceipts',native_recovery->'receipts',
      'unavailable',unavailable+coalesce((native_recovery->>'unavailable')::integer,0));
  END IF;

  SELECT * INTO entry FROM knowledge_entries e WHERE e.account_id=p_account
    AND e.legacy_claim_id=(p_request->>'claimId')::uuid AND e.scope='workspace' AND e.scope_workspace_id=p_workspace;
  IF NOT FOUND OR NOT knowledge_scope_visible(entry) OR subject IS NULL THEN
    RAISE EXCEPTION 'No migrated Knowledge confirmation matches this claim' USING ERRCODE='42501'; END IF;
  SELECT f.object_value#>>'{}' INTO exact_text FROM knowledge_claims c JOIN knowledge_facts f ON f.id=c.fact_id AND f.account_id=c.account_id
    WHERE c.account_id=p_account AND c.id=entry.legacy_claim_id AND c.scope_kind='workspace'
      AND c.scope_workspace_id=p_workspace AND c.initiating_human_subject_id=subject
      AND c.extraction_method='task-note-promotion-v1' AND f.object_kind='text';
  IF NOT FOUND THEN RAISE EXCEPTION 'Migrated confirmation content unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO question FROM session_human_input_requests q WHERE q.account_id=p_account AND q.workspace_id=p_workspace
    AND q.id=(p_request->>'humanInputRequestId')::uuid AND q.session_id=(p_actor->>'sessionId')::uuid
    AND q.turn_id=(p_actor->>'turnId')::uuid AND q.turn_generation<=(p_actor->>'executionGeneration')::integer
    AND q.status='answered' AND q.responded_by=subject AND q.response->>'outcome'='answered'
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(q.questions) value WHERE value->>'id'='remember:'||entry.legacy_claim_id
      AND value->>'kind'='single_select' AND value->>'prompt'='Save this as workspace knowledge for everyone in this workspace?'
      AND value->>'helpText'=left(exact_text,2000) AND value->'options'='[{"id":"save","label":"Save"},{"id":"skip","label":"Don''t save"}]'::jsonb
      AND coalesce((value->>'allowOther')::boolean,false)=false)
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(q.response->'answers') value
      WHERE value->>'questionId'='remember:'||entry.legacy_claim_id AND value->'values'='["save"]'::jsonb);
  IF NOT FOUND THEN RAISE EXCEPTION 'Exact human confirmation unavailable' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('knowledge-publication:'||p_account,0));
  SELECT * INTO prior FROM knowledge_entry_operations o WHERE o.account_id=p_account AND o.operation_id=(p_request->>'operationId')::uuid;
  IF FOUND THEN
    IF prior.entry_id<>entry.id OR prior.actor->>'legacyHumanInputRequestId' IS DISTINCT FROM question.id::text THEN
      RAISE EXCEPTION 'Legacy confirmation operation conflicts' USING ERRCODE='23505'; END IF;
    RETURN prior.receipt||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO entry FROM knowledge_entries e WHERE e.id=entry.id AND e.account_id=p_account FOR UPDATE;
  SELECT * INTO revision FROM knowledge_entry_revisions r WHERE r.id=entry.latest_revision_id AND r.account_id=p_account;
  IF revision.legacy_snapshot IS NULL OR revision.number<>1 THEN
    RAISE EXCEPTION 'Migrated Knowledge changed; inspect its current review' USING ERRCODE='40001'; END IF;
  IF entry.published_revision_id=revision.id THEN
    RETURN jsonb_build_object('operationId',p_request->>'operationId','entryId',entry.id,'revisionId',revision.id,
      'version',entry.version,'outcome','published','reviewBatchId',NULL,'replayed',true);
  END IF;
  SELECT * INTO evidence FROM knowledge_claim_evidence e WHERE e.account_id=p_account AND e.claim_id=entry.legacy_claim_id
    AND e.scope_kind='workspace' AND e.scope_workspace_id=p_workspace AND e.polarity='supports'
    AND e.task_note_id IS NOT NULL AND e.initiating_human_subject_id=subject ORDER BY e.created_at,e.id LIMIT 1;
  IF NOT FOUND OR EXISTS(SELECT 1 FROM knowledge_claim_evidence e WHERE e.account_id=p_account
    AND e.claim_id=entry.legacy_claim_id AND e.polarity='contradicts') THEN
    RAISE EXCEPTION 'Migrated confirmation evidence unavailable' USING ERRCODE='42501'; END IF;
  note:=knowledge_task_note_source(p_account,p_workspace,p_actor,evidence.task_note_id,evidence.task_note_version);
  IF note->>'content' IS DISTINCT FROM exact_text OR encode(sha256(convert_to(exact_text,'UTF8')),'hex')<>evidence.content_hash THEN
    RAISE EXCEPTION 'Migrated confirmation evidence changed' USING ERRCODE='42501'; END IF;
  human_actor:=jsonb_build_object('kind','human','principalKind','human_session','subjectId',subject,
    'writeScopes',jsonb_build_array('workspace'),'settingsScopes','[]'::jsonb,'review',true,
    'legacyHumanInputRequestId',question.id,'confirmedFromAttempt',p_actor);
  PERFORM set_config('opengeni.principal_kind','human_session',true);
  result:=knowledge_entry_apply(p_account,p_workspace,human_actor,jsonb_build_object('operation','approve',
    'operationId',p_request->>'operationId','entryId',entry.id,'revisionId',revision.id,'expectedVersion',entry.version));
  PERFORM set_config('opengeni.principal_kind',coalesce(prior_principal,''),true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.principal_kind',coalesce(prior_principal,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_entry_prepare_file(p_account uuid, p_workspace uuid, p_actor jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor jsonb; f files%ROWTYPE; e knowledge_entries%ROWTYPE;
  entry_id uuid; identity_hash text; receipt jsonb; operation text:=p_request->>'operation';
  file_id uuid:=(p_request->>'fileId')::uuid; body jsonb;
BEGIN
  actor:=knowledge_resolve_actor(p_account,p_workspace,p_actor);
  IF actor->>'kind' IS DISTINCT FROM 'agent' OR file_id IS NULL OR operation IS NULL
    OR operation NOT IN ('inspect','complete') THEN
    RAISE EXCEPTION 'Source preparation requires an exact agent attempt' USING ERRCODE='42501'; END IF;
  IF actor#>>'{policy,effective,knowledge}'='off' THEN RETURN jsonb_build_object('status','disabled','fileId',file_id); END IF;
  SELECT * INTO f FROM files WHERE account_id=p_account AND id=file_id AND status='ready'
    AND (workspace_id=p_workspace OR (actor->>'defaultScope'='personal' AND actor->>'subjectId'=ANY(private_owner_subject_ids)));
  IF NOT FOUND OR NOT knowledge_source_visible(p_account,jsonb_build_object('source',jsonb_build_object('fileId',file_id))) THEN
    RAISE EXCEPTION 'Source file unavailable' USING ERRCODE='42501'; END IF;
  identity_hash:=md5('prepared-knowledge-file:'||p_account||':'||file_id||':'||
    CASE WHEN actor->>'defaultScope'='personal' THEN 'personal:'||(actor->>'subjectId') ELSE 'workspace:'||p_workspace END||
    CASE WHEN actor->>'retentionScope'='session' THEN ':session:'||(actor->>'sessionId') ELSE '' END);
  entry_id:=(substring(identity_hash,1,8)||'-'||substring(identity_hash,9,4)||'-5'||substring(identity_hash,14,3)||'-a'||substring(identity_hash,18,3)||'-'||substring(identity_hash,21,12))::uuid;
  -- Do not keep a transaction open while a parser or object store is running.
  -- Complete rechecks both authority and identity under the publication lock.
  IF operation='complete' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('knowledge-publication:'||p_account,0));
  END IF;
  SELECT * INTO e FROM knowledge_entries WHERE account_id=p_account AND id=entry_id;
  IF FOUND THEN
    IF e.prepared_file_id IS DISTINCT FROM file_id OR NOT knowledge_scope_visible(e) THEN
      RAISE EXCEPTION 'Prepared source identity is unavailable' USING ERRCODE='42501'; END IF;
    SELECT jsonb_build_object('operationId',o.operation_id,'entryId',e.id,'revisionId',e.latest_revision_id,
      'version',e.version,'outcome',CASE WHEN e.archived THEN 'archived' ELSE d.outcome END,
      'reviewBatchId',r.review_batch_id,'replayed',true) INTO receipt
      FROM knowledge_entry_decisions d JOIN knowledge_entry_revisions r ON r.account_id=d.account_id AND r.id=d.revision_id
      JOIN knowledge_entry_operations o ON o.account_id=d.account_id AND o.entry_id=d.entry_id AND o.receipt->>'revisionId'=d.revision_id::text
      WHERE d.account_id=p_account AND d.entry_id=e.id AND d.version=e.version ORDER BY o.created_at DESC LIMIT 1;
    IF receipt IS NULL THEN RAISE EXCEPTION 'Prepared source receipt unavailable' USING ERRCODE='55000'; END IF;
    RETURN jsonb_build_object('status','retained','fileId',file_id,'filename',f.filename,'receipt',receipt);
  END IF;
  IF operation='inspect' THEN
    RETURN jsonb_build_object('status','prepare','fileId',file_id,'file',to_jsonb(f));
  END IF;
  IF jsonb_typeof(p_request->'content') IS DISTINCT FROM 'string' OR p_request->>'codecVersion' IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'Invalid prepared source content' USING ERRCODE='22023'; END IF;
  IF p_request ? 'purpose' AND (
    jsonb_typeof(p_request->'purpose') IS DISTINCT FROM 'string'
    OR p_request->>'purpose' NOT IN ('evidence','reference')) THEN
    RAISE EXCEPTION 'Invalid source purpose' USING ERRCODE='22023'; END IF;
  body:=jsonb_build_object('title',p_request->'title','kind','source','content',p_request->'content',
    'source',jsonb_build_object('kind','file','fileId',f.id,'version',coalesce(p_request->>'sourceVersion',f.sha256,f.id::text),
      'retention',CASE WHEN p_request->>'content'='' THEN 'reference' ELSE 'full_text' END,
      'purpose',coalesce(p_request->>'purpose','evidence'),'capturedAt',clock_timestamp()),'evidence','[]'::jsonb,'groupIds','[]'::jsonb,'relationships','[]'::jsonb);
  receipt:=knowledge_entry_apply(p_account,p_workspace,p_actor,jsonb_build_object('operation','save','operationId',gen_random_uuid(),
    'entryId',entry_id,'expectedVersion',0,'entry',body,'codecVersion',1,'preview',p_request->'preview','searchText',p_request->'searchText'));
  UPDATE knowledge_entries SET prepared_file_id=file_id WHERE account_id=p_account AND id=entry_id;
  RETURN jsonb_build_object('status','retained','fileId',file_id,'filename',f.filename,'receipt',receipt);
END $$;

CREATE FUNCTION knowledge_entry_read(p_account uuid, p_workspace uuid, p_actor jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
<<knowledge_entry_read>>
DECLARE actor jsonb; result jsonb; pending boolean:=p_request->>'view'='needs_review';
  operation text:=coalesce(p_request->>'operation','list'); take integer:=coalesce((p_request->>'limit')::integer,20);
  query_embedding vector:=CASE WHEN jsonb_typeof(p_request->'embedding')='array' THEN (p_request->'embedding')::text::vector END;
BEGIN
  actor:=knowledge_resolve_actor(p_account,p_workspace,p_actor);
  pending:=coalesce(pending,false);
  IF operation='policy' AND actor->>'kind'='agent' THEN RETURN actor->'policy'; END IF;
  IF take NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Invalid Knowledge page size' USING ERRCODE='22023'; END IF;
  IF operation IN ('source_list','source_read') THEN
    IF actor->>'kind'<>'agent' OR actor#>>'{policy,scheduledTaskRunId}' IS NULL THEN
      RAISE EXCEPTION 'Source content requires its accepted agent run' USING ERRCODE='42501'; END IF;
    SELECT coalesce(jsonb_agg(value ORDER BY id),'[]'::jsonb) INTO result FROM (
      SELECT e.id,jsonb_build_object('entryId',e.id,'revisionId',r.id,'title',r.body->'title',
        'codecVersion',r.body_codec_version,'pending',r.id IS DISTINCT FROM e.published_revision_id)
        || CASE WHEN operation='source_read' THEN jsonb_build_object('content',r.body->'content') ELSE '{}'::jsonb END AS value
      FROM scheduled_task_runs run
      JOIN knowledge_document_versions v ON v.account_id=run.account_id
        AND v.source_id=(run.accepted_execution_snapshot#>>'{task,agentConfig,knowledgeSource,sourceId}')::uuid
      JOIN knowledge_entries e ON e.account_id=v.account_id AND e.legacy_document_version_id=v.id
      JOIN knowledge_entry_revisions r ON r.account_id=e.account_id AND r.entry_id=e.id
        AND r.id=coalesce(CASE WHEN EXISTS(SELECT 1 FROM knowledge_review_batches b
          JOIN knowledge_entry_revisions candidate ON candidate.account_id=b.account_id AND candidate.review_batch_id=b.id
          JOIN knowledge_entry_decisions d ON d.account_id=e.account_id AND d.entry_id=e.id
            AND d.revision_id=candidate.id AND d.version=e.version AND d.outcome='pending'
          WHERE b.account_id=e.account_id AND b.scheduled_task_run_id=run.id AND candidate.id=e.latest_revision_id)
          THEN e.latest_revision_id END,e.published_revision_id)
      WHERE run.account_id=p_account AND run.workspace_id=p_workspace
        AND run.id=(knowledge_entry_read.actor#>>'{policy,scheduledTaskRunId}')::uuid
        AND run.action_kind='agent_turn' AND NOT e.archived AND knowledge_scope_visible(e)
        AND (operation='source_read' OR (r.created_at>=run.created_at
          AND e.document_preparation->>'scheduledTaskRunId'=run.id::text))
        AND knowledge_revision_visible(p_account,e.id,r.id,true)
        AND (NOT(p_request ? 'afterId') OR e.id>(p_request->>'afterId')::uuid)
        AND (operation<>'source_read' OR e.id=(p_request->>'entryId')::uuid)
      ORDER BY e.id LIMIT CASE WHEN operation='source_read' THEN 1 ELSE take+1 END
    ) page;
    RETURN result;
  END IF;

  IF (operation='history' OR p_request->>'view'='rejected')
    AND (actor->>'kind'<>'human' OR actor->>'review' IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION 'Knowledge history requires human review access' USING ERRCODE='42501';
  END IF;
  IF pending AND actor->>'kind'<>'agent'
    AND (actor->>'kind'<>'human' OR actor->>'review' IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION 'Pending Knowledge requires a live agent or human reviewer' USING ERRCODE='42501';
  END IF;
  IF p_request->>'view'='archived' AND actor->>'kind'<>'human' THEN
    RAISE EXCEPTION 'Archived Knowledge is a human management view' USING ERRCODE='42501';
  END IF;
  IF operation='review_batches' THEN
    IF actor->>'kind'<>'human' OR actor->>'review' IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'Knowledge review groups require human review access' USING ERRCODE='42501'; END IF;
    WITH visible AS MATERIALIZED (
      SELECT b.id,e.scope,b.session_id,b.scheduled_task_run_id,b.created_at,e.id AS entry_id
      FROM knowledge_entries e JOIN knowledge_entry_revisions r
        ON r.account_id=e.account_id AND r.entry_id=e.id AND r.id=e.latest_revision_id
      JOIN knowledge_review_batches b ON b.account_id=e.account_id AND b.id=r.review_batch_id
      JOIN LATERAL (SELECT d.outcome FROM knowledge_entry_decisions d WHERE d.account_id=e.account_id
        AND d.entry_id=e.id AND d.revision_id=r.id ORDER BY d.version DESC LIMIT 1) decision ON true
      WHERE e.account_id=p_account AND decision.outcome='pending' AND knowledge_scope_visible(e)
        AND (knowledge_entry_read.actor->'writeScopes') ? e.scope AND knowledge_revision_visible(p_account,e.id,r.id,true)
        AND (NOT(p_request ? 'scope') OR e.scope=p_request->>'scope')
    ), batches AS (
      SELECT id,scope,session_id,scheduled_task_run_id,created_at,count(*) AS pending_count FROM visible
      GROUP BY id,scope,session_id,scheduled_task_run_id,created_at
      HAVING NOT(p_request ? 'afterId') OR id>(p_request->>'afterId')::uuid
      ORDER BY id LIMIT take+1
    ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'scope',b.scope,'pendingCount',b.pending_count,
      'createdAt',b.created_at,'sessionId',s.id,'scheduledTaskId',task.id,'scheduledTaskRunId',run.id,
      'title',coalesce(task.name,s.title)) ORDER BY b.id),'[]'::jsonb) INTO result
      FROM batches b LEFT JOIN sessions s ON s.account_id=p_account AND s.id=b.session_id
      LEFT JOIN scheduled_task_runs run ON run.account_id=p_account AND run.id=b.scheduled_task_run_id
      LEFT JOIN scheduled_tasks task ON task.account_id=p_account AND task.id=run.task_id;
    RETURN result;
  END IF;
  IF operation NOT IN ('list','get','history','file') OR (operation='file' AND NOT(p_request ? 'entryId')) THEN RAISE EXCEPTION 'Invalid Knowledge read' USING ERRCODE='22023'; END IF;
  -- Match keyword candidates, then materialize access-filtered records before ranking or pagination.
  WITH candidate_rows AS MATERIALIZED (
    SELECT e.*,r.id AS revision_id,r.number,r.change_kind,r.body,r.body_codec_version,r.preview,r.preview_codec_version,
      r.previous_revision_id,r.restored_from_revision_id,r.created_by_session_id,r.review_batch_id,r.created_at AS revision_created_at,
      CASE WHEN r.id=e.published_revision_id THEN 'published'
        WHEN d.outcome='pending' AND r.id=e.latest_revision_id THEN 'pending'
        WHEN d.outcome='rejected' THEN 'rejected' ELSE 'superseded' END AS outcome
    FROM knowledge_entries e
    JOIN knowledge_entry_revisions r ON r.account_id=e.account_id AND r.entry_id=e.id
      AND (operation='history' OR r.id=CASE WHEN p_request ? 'revisionId' THEN (p_request->>'revisionId')::uuid
        WHEN pending THEN e.latest_revision_id
        WHEN p_request->>'view'='rejected' THEN e.latest_revision_id
        WHEN p_request->>'view'='archived' THEN coalesce(e.published_revision_id,e.latest_revision_id)
        ELSE e.published_revision_id END)
    LEFT JOIN LATERAL (SELECT outcome FROM knowledge_entry_decisions v WHERE v.account_id=e.account_id
      AND v.entry_id=e.id AND v.revision_id=r.id ORDER BY v.version DESC LIMIT 1) d ON true
    WHERE e.account_id=p_account AND knowledge_scope_visible(e)
      AND (operation='history' OR (p_request ? 'revisionId' AND knowledge_entry_read.actor->>'kind'='human' AND knowledge_entry_read.actor->>'review'='true')
        OR e.archived=coalesce(p_request->>'view'='archived',false))
      AND (NOT pending OR (d.outcome='pending' AND r.id=e.latest_revision_id
        AND (knowledge_entry_read.actor->>'kind'='agent' OR (knowledge_entry_read.actor->'writeScopes') ? e.scope)))
      AND (p_request->>'view' IS DISTINCT FROM 'rejected' OR d.outcome='rejected')
      AND (NOT(p_request ? 'scope') OR e.scope=p_request->>'scope')
      AND (NOT(p_request ? 'entryId') OR e.id=(p_request->>'entryId')::uuid)
      -- Filter the authorized candidate set before keyword/vector ranking and
      -- take+one pagination, consistently for every list view and scope.
      AND (operation<>'list' OR NOT(p_request ? 'createdSince')
        OR e.created_at >= (p_request->>'createdSince')::timestamptz)
      AND (NOT(p_request ? 'kind') OR r.body->>'kind'=p_request->>'kind')
      -- Apply before scoring and pagination. Evidence access and review remain
      -- governed by the unchanged recursive revision/source visibility checks.
      AND (operation<>'list' OR coalesce(p_request->>'view','published')<>'published'
        OR coalesce((p_request->>'includeEvidence')::boolean,false)
        OR r.body->>'kind'<>'source'
        OR coalesce(r.body#>>'{source,purpose}',CASE
          WHEN e.prepared_file_id IS NOT NULL THEN 'evidence'
          WHEN r.body#>>'{source,kind}'='conversation'
            AND e.legacy_memory_id IS NULL AND e.legacy_document_id IS NULL
            AND e.legacy_claim_id IS NULL AND e.legacy_document_version_id IS NULL THEN 'evidence'
          ELSE 'reference' END)<>'evidence')
      AND (NOT(p_request ? 'fileId') OR r.body#>>'{source,fileId}'=p_request->>'fileId'
        OR EXISTS(SELECT 1 FROM knowledge_entry_links l
          JOIN knowledge_entry_revisions source_revision ON source_revision.account_id=l.account_id
            AND source_revision.entry_id=l.target_entry_id AND source_revision.id=l.target_revision_id
          WHERE l.account_id=e.account_id AND l.entry_id=e.id AND l.revision_id=r.id
            AND l.relation='evidence' AND source_revision.body#>>'{source,fileId}'=p_request->>'fileId'))
      AND (NOT(p_request ? 'sessionId') OR r.created_by_session_id=(p_request->>'sessionId')::uuid)
      AND (NOT(p_request ? 'reviewBatchId') OR r.review_batch_id=(p_request->>'reviewBatchId')::uuid)
      AND (NOT(p_request ? 'groupId') OR EXISTS(SELECT 1 FROM knowledge_entry_links l
        WHERE l.account_id=e.account_id AND l.entry_id=e.id AND l.revision_id=r.id
          AND l.relation='group' AND l.target_entry_id=(p_request->>'groupId')::uuid
          AND EXISTS(SELECT 1 FROM knowledge_entries g WHERE g.account_id=p_account AND g.id=l.target_entry_id
            AND NOT g.archived AND knowledge_revision_visible(p_account,g.id,
              CASE WHEN pending THEN g.latest_revision_id ELSE g.published_revision_id END,pending))))
      -- Filter before pagination. A hidden, archived, or out-of-scope parent must
      -- never strand an otherwise readable entry outside the tree.
      AND (NOT coalesce((p_request->>'rootOnly')::boolean,false) OR NOT EXISTS(
        SELECT 1 FROM knowledge_entry_links l
        JOIN knowledge_entries g ON g.account_id=l.account_id AND g.id=l.target_entry_id
        JOIN knowledge_entry_revisions gr ON gr.account_id=g.account_id AND gr.entry_id=g.id
          AND gr.id=CASE WHEN pending THEN g.latest_revision_id ELSE g.published_revision_id END
        WHERE l.account_id=e.account_id AND l.entry_id=e.id AND l.revision_id=r.id AND l.relation='group'
          AND NOT g.archived AND gr.body->>'kind'='group'
          AND (NOT(p_request ? 'scope') OR g.scope=p_request->>'scope')
          AND knowledge_revision_visible(p_account,g.id,gr.id,pending)))
      AND (NOT(p_request ? 'beforeRevision') OR r.number<(p_request->>'beforeRevision')::integer)
      AND (knowledge_entry_read.actor->>'kind'='human' AND knowledge_entry_read.actor->>'review'='true'
        OR (pending AND knowledge_entry_read.actor->>'kind'='agent')
        OR EXISTS(SELECT 1 FROM knowledge_entry_decisions v WHERE v.account_id=e.account_id
          AND v.entry_id=e.id AND v.revision_id=r.id AND v.outcome='published'))

      -- Keyword ranks are per revision, not normalized across the population.
      -- This is the same positive-rank condition as page, before any LIMIT.
      -- Vector/hybrid eligibility is deliberately left unchanged.
      AND (coalesce(p_request->>'mode','hybrid')<>'keyword'
        OR coalesce(p_request->>'query','')=''
        OR EXISTS(SELECT 1 FROM knowledge_entry_search search
          WHERE search.account_id=p_account AND search.entry_id=e.id AND search.revision_id=r.id
            AND ts_rank_cd(search.search_vector,websearch_to_tsquery('simple',p_request->>'query'))>0))
  ), allowed AS MATERIALIZED (
    SELECT v.* FROM (SELECT array_agg(id) ids,array_agg(revision_id) revisions FROM candidate_rows) c
    CROSS JOIN LATERAL knowledge_revisions_visible(p_account,c.ids,c.revisions,
      pending OR (knowledge_entry_read.actor->>'kind'='human' AND knowledge_entry_read.actor->>'review'='true')) v
  ), candidates AS MATERIALIZED (
    SELECT c.* FROM candidate_rows c JOIN allowed a ON a.entry_id=c.id AND a.revision_id=c.revision_id
  ), scored AS (
    SELECT c.*,coalesce(lex.score,0) AS keyword_score,coalesce(semantic.similarity,0) AS similarity,
      CASE WHEN coalesce(p_request->>'query','')='' THEN 0
        WHEN coalesce(p_request->>'mode','hybrid')='vector' THEN coalesce(semantic.similarity,0)
        WHEN coalesce(p_request->>'mode','hybrid')='keyword' THEN coalesce(lex.score/(1+lex.score),0)
        ELSE coalesce(lex.score/(1+lex.score),0)+coalesce(semantic.similarity,0) END AS score,
      CASE WHEN semantic.keyword_match OR semantic.similarity>=0.2 THEN
        jsonb_build_array(jsonb_build_object('field',semantic.field,'start',semantic.start_offset,'end',semantic.end_offset,
          'text',semantic.text,'codecVersion',semantic.text_codec_version)) ELSE '[]'::jsonb END AS excerpts
    FROM candidates c
    LEFT JOIN LATERAL (
      SELECT max(ts_rank_cd(s.search_vector,websearch_to_tsquery('simple',p_request->>'query'))) AS score
      FROM knowledge_entry_search s WHERE s.account_id=p_account AND s.entry_id=c.id AND s.revision_id=c.revision_id
        AND coalesce(p_request->>'query','')<>''
    ) lex ON true
    LEFT JOIN LATERAL (
      SELECT v.field,v.start_offset,v.end_offset,v.text,v.text_codec_version,
        v.keyword_match,max(v.similarity) OVER () AS similarity FROM (
        SELECT cache.*,
          to_tsvector('simple',cache.text)@@websearch_to_tsquery('simple',p_request->>'query') AS keyword_match,
          CASE WHEN query_embedding IS NOT NULL AND cache.dimensions=vector_dims(query_embedding)
            AND cache.model=p_request->>'embeddingModel' AND vector_norm(query_embedding)>0
            THEN greatest(0,least(1,1-(cache.embedding<=>query_embedding))) ELSE 0 END AS similarity
        FROM knowledge_entry_vectors cache JOIN knowledge_index_jobs job ON job.account_id=cache.account_id
          AND job.revision_id=cache.revision_id AND job.completed_generation=cache.generation
        WHERE cache.account_id=p_account AND cache.entry_id=c.id AND cache.revision_id=c.revision_id
          AND coalesce(p_request->>'query','')<>''
      ) v ORDER BY CASE WHEN p_request->>'mode'='vector' THEN false ELSE v.keyword_match END DESC,v.similarity DESC,v.chunk_index LIMIT 1
    ) semantic ON true
  ), page AS (
    SELECT * FROM scored s WHERE (coalesce(p_request->>'query','')=''
      OR (coalesce(p_request->>'mode','hybrid')<>'vector' AND s.keyword_score>0)
      OR (coalesce(p_request->>'mode','hybrid')<>'keyword' AND s.similarity>=0.2))
      AND (NOT(p_request ? 'afterId') OR s.score<(p_request->>'afterScore')::double precision
        OR (s.score=(p_request->>'afterScore')::double precision AND s.id>(p_request->>'afterId')::uuid))
    ORDER BY s.score DESC,s.id,s.number DESC LIMIT take+1
  ) SELECT coalesce(jsonb_agg(jsonb_build_object(
    'score',c.score,'excerpts',c.excerpts,'id',c.id,'scope',c.scope,'version',c.version,'publishedRevisionId',c.published_revision_id,
    'latestRevisionId',c.latest_revision_id,'archived',c.archived,'createdAt',c.created_at,'updatedAt',c.updated_at,
    'revision',jsonb_build_object('id',c.revision_id,'entryId',c.id,'number',c.number,
      'entry',CASE WHEN operation IN ('get','file') THEN knowledge_entry_visible_body(p_account,c.body,pending) ELSE NULL END,'change',c.change_kind,
      'title',c.body->'title','kind',c.body->>'kind','preview',c.preview,'groupIds',knowledge_entry_visible_body(p_account,jsonb_build_object('groupIds',coalesce(c.body->'groupIds','[]'::jsonb)),pending)->'groupIds',
      'sourceKind',c.body#>>'{source,kind}','bodyCodecVersion',c.body_codec_version,'previewCodecVersion',c.preview_codec_version,
      'previousRevisionId',c.previous_revision_id,'restoredFromRevisionId',c.restored_from_revision_id,
      'createdAt',c.revision_created_at,'createdBySessionId',c.created_by_session_id,
      'reviewBatchId',c.review_batch_id,'outcome',c.outcome)
  ) ORDER BY c.score DESC,c.id,c.number DESC),'[]'::jsonb) INTO result FROM page c;
  IF operation='file' THEN
    IF result#>>'{0,revision,entry,source,documentId}' IS NOT NULL THEN
      SELECT to_jsonb(f) INTO result FROM resolve_document_original_file(p_account,p_workspace,
        nullif(current_setting('opengeni.subject_id',true),''),(result#>>'{0,revision,entry,source,documentId}')::uuid) f;
    ELSE
      SELECT to_jsonb(f) INTO result FROM files f WHERE f.account_id=p_account AND f.status='ready'
        AND f.id=(result#>>'{0,revision,entry,source,fileId}')::uuid;
    END IF;
  END IF;
  RETURN result;
END $$;

CREATE FUNCTION knowledge_entry_visible_body(p_account uuid, p_body jsonb, p_pending boolean) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT p_body || jsonb_build_object(
    'groupIds',coalesce((SELECT jsonb_agg(g.value ORDER BY g.ordinality)
      FROM jsonb_array_elements(p_body->'groupIds') WITH ORDINALITY g(value,ordinality)
      WHERE (SELECT NOT e.archived AND knowledge_revision_visible(p_account,e.id,
          coalesce(e.published_revision_id,CASE WHEN p_pending THEN e.latest_revision_id END),p_pending)
        FROM knowledge_entries e
        WHERE e.account_id=p_account AND e.id=(g.value#>>'{}')::uuid)), '[]'::jsonb),
    'relationships',coalesce((SELECT jsonb_agg(l.value ORDER BY l.ordinality)
      FROM jsonb_array_elements(p_body->'relationships') WITH ORDINALITY l(value,ordinality)
      WHERE (SELECT NOT e.archived AND knowledge_revision_visible(p_account,e.id,
          coalesce(e.published_revision_id,CASE WHEN p_pending THEN e.latest_revision_id END),p_pending)
        FROM knowledge_entries e
        WHERE e.account_id=p_account AND e.id=(l.value->>'entryId')::uuid)), '[]'::jsonb))
$$;

CREATE FUNCTION knowledge_file_owner_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor text := nullif(current_setting('opengeni.private_file_owner',true),'');
BEGIN
  IF NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR NEW.account_id IS DISTINCT FROM OLD.account_id THEN
    RAISE EXCEPTION 'File ownership is immutable; share an explicitly authorized copy' USING ERRCODE='55000';
  END IF;
  IF NEW.private_owner_subject_ids IS NOT DISTINCT FROM OLD.private_owner_subject_ids THEN
    IF NEW.owner_subject_id IS DISTINCT FROM OLD.owner_subject_id THEN
      RAISE EXCEPTION 'File ownership is immutable; share an explicitly authorized copy' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;
  IF actor IS NOT NULL AND OLD.status = 'ready' AND NEW.status = 'ready'
    AND OLD.object_key !~ '^workspaces/[^/]+/files/[^/]+/(retained|tool-results)/' THEN
    IF OLD.private_owner_subject_ids IS NOT NULL AND NEW.private_owner_subject_ids IS NULL
      AND actor = ANY(OLD.private_owner_subject_ids)
      AND NEW.owner_subject_id IS NOT DISTINCT FROM coalesce(OLD.owner_subject_id, actor) THEN
      RETURN NEW;
    END IF;
    IF OLD.private_owner_subject_ids IS NULL AND NEW.private_owner_subject_ids = ARRAY[actor]
      AND OLD.owner_subject_id = actor AND NEW.owner_subject_id = actor THEN
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION 'Only a file''s owner can change who can open it' USING ERRCODE='55000';
END $$;

CREATE FUNCTION knowledge_index_attribution_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NEW.billing_attribution IS DISTINCT FROM OLD.billing_attribution THEN
    RAISE EXCEPTION 'Knowledge initiating attribution is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION knowledge_index_billing_policy(p_account uuid, p_revision uuid, p_lease uuid, p_requested text, p_activation_at timestamp with time zone, p_rate bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  job knowledge_index_jobs%ROWTYPE;
  decided text;
  frozen_rate bigint;
  decision_outcome text;
  previous text := current_setting('opengeni.knowledge_index_dispatcher',true);
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id() OR
     p_requested IS NULL OR p_requested NOT IN ('usage_only','shadow','credits') OR
     p_activation_at IS NULL OR p_rate IS NULL OR p_rate < 0 OR
     (p_requested='credits' AND p_rate=0) THEN
    RAISE EXCEPTION 'Knowledge index billing policy unavailable' USING ERRCODE='42501';
  END IF;
  PERFORM set_config('opengeni.knowledge_index_dispatcher','1',true);
  SELECT * INTO job FROM knowledge_index_jobs j WHERE j.account_id=p_account
    AND j.revision_id=p_revision AND j.lease_id=p_lease AND j.state='running'
    AND j.lease_until>clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Knowledge index lease unavailable' USING ERRCODE='40001';
  END IF;
  IF job.billed_generation IS DISTINCT FROM job.generation THEN
    decided:=CASE WHEN job.created_at>=p_activation_at THEN p_requested ELSE 'usage_only' END;
    frozen_rate:=CASE WHEN decided='usage_only' THEN 0 ELSE p_rate END;
  ELSE
    decided:=job.billing_mode;
    frozen_rate:=job.billing_rate_micros_per_million_bytes;
  END IF;
  IF decided='credits' THEN
    SELECT d.outcome INTO decision_outcome FROM knowledge_entry_decisions d
      WHERE d.account_id=p_account AND d.entry_id=job.entry_id AND d.revision_id=p_revision
      ORDER BY d.version DESC LIMIT 1;
    IF decision_outcome='rejected' THEN
      UPDATE knowledge_index_jobs SET state='obsolete',lease_id=NULL,lease_until=NULL
        WHERE revision_id=p_revision;
      DELETE FROM knowledge_entry_vectors WHERE account_id=p_account AND revision_id=p_revision;
      PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
      RETURN jsonb_build_object('mode','obsolete','rateMicrosPerMillionBytes',0);
    END IF;
  END IF;
  -- A review-first draft is not a paid purchase. Keep its lease checkpoint
  -- intact and poll until this exact revision is published; a rejected latest
  -- revision may remain visible for review but must never incur an embedding
  -- charge. Recheck on every batch so a publication change fences work.
  IF decided='credits' AND NOT EXISTS (
    SELECT 1 FROM knowledge_entries e WHERE e.account_id=p_account
      AND e.id=job.entry_id AND e.published_revision_id=p_revision AND NOT e.archived
  ) THEN
    UPDATE knowledge_index_jobs SET state='pending',lease_id=NULL,lease_until=NULL,
      last_failure='waiting_for_review',next_attempt_at=clock_timestamp()+interval '1 minute',
      attempts=0 WHERE revision_id=p_revision;
    PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
    RETURN jsonb_build_object('mode','awaiting_review','rateMicrosPerMillionBytes',0);
  END IF;
  IF job.billed_generation IS DISTINCT FROM job.generation THEN
    UPDATE knowledge_index_jobs SET billing_mode=decided,billed_generation=job.generation,
      billing_rate_micros_per_million_bytes=frozen_rate
      WHERE revision_id=p_revision;
  END IF;
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RETURN jsonb_build_object('mode',decided,
    'rateMicrosPerMillionBytes',coalesce(frozen_rate,0));
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_index_claim(p_model text, p_dimensions integer, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE previous text:=current_setting('opengeni.knowledge_index_dispatcher',true); result jsonb;
BEGIN
  IF p_model IS NULL OR p_dimensions IS NULL OR p_limit IS NULL OR length(p_model) NOT BETWEEN 1 AND 512 OR p_dimensions NOT BETWEEN 1 AND 4096 OR p_limit NOT BETWEEN 1 AND 20 THEN
    RAISE EXCEPTION 'Invalid Knowledge indexing claim' USING ERRCODE='22023'; END IF;
  PERFORM set_config('opengeni.knowledge_index_dispatcher','1',true);
  WITH candidates AS (
    SELECT j.revision_id FROM knowledge_index_jobs j WHERE j.state<>'obsolete' AND j.next_attempt_at<=clock_timestamp()
      AND (j.lease_until IS NULL OR j.lease_until<=clock_timestamp())
      AND (j.state<>'ready' OR j.model IS DISTINCT FROM p_model OR j.dimensions IS DISTINCT FROM p_dimensions)
    ORDER BY j.next_attempt_at,j.revision_id LIMIT p_limit FOR UPDATE SKIP LOCKED
  ), claimed AS (
    UPDATE knowledge_index_jobs j SET state='running',lease_id=gen_random_uuid(),lease_until=clock_timestamp()+interval '5 minutes',
      generation=CASE WHEN j.model IS DISTINCT FROM p_model OR j.dimensions IS DISTINCT FROM p_dimensions THEN j.generation+1 ELSE j.generation END,
      next_index=CASE WHEN j.model IS DISTINCT FROM p_model OR j.dimensions IS DISTINCT FROM p_dimensions THEN 0 ELSE j.next_index END,
      model=p_model,dimensions=p_dimensions,attempts=j.attempts+1
    FROM candidates c WHERE j.revision_id=c.revision_id RETURNING j.*
  ) SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',account_id,'entryId',entry_id,'revisionId',revision_id,
    'leaseId',lease_id,'model',model,'dimensions',dimensions,'generation',generation,'nextIndex',next_index,
    'billingAttribution',billing_attribution)),'[]'::jsonb) INTO result FROM claimed;
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_index_paid_publication_guard(p_account uuid, p_revision uuid, p_lease uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  job knowledge_index_jobs%ROWTYPE;
  entry knowledge_entries%ROWTYPE;
  decision_outcome text;
  previous text := current_setting('opengeni.knowledge_index_dispatcher',true);
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Knowledge index tenant mismatch' USING ERRCODE='42501';
  END IF;
  PERFORM set_config('opengeni.knowledge_index_dispatcher','1',true);
  SELECT * INTO job FROM knowledge_index_jobs j WHERE j.account_id=p_account
    AND j.revision_id=p_revision AND j.lease_id=p_lease AND j.state='running'
    AND j.lease_until>clock_timestamp() AND j.billing_mode='credits' FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Paid Knowledge index lease unavailable' USING ERRCODE='40001';
  END IF;
  SELECT * INTO entry FROM knowledge_entries e WHERE e.account_id=p_account
    AND e.id=job.entry_id FOR SHARE;
  SELECT d.outcome INTO decision_outcome FROM knowledge_entry_decisions d
    WHERE d.account_id=p_account AND d.entry_id=job.entry_id AND d.revision_id=p_revision
    ORDER BY d.version DESC LIMIT 1;
  IF decision_outcome='rejected' THEN
    UPDATE knowledge_index_jobs SET state='obsolete',lease_id=NULL,lease_until=NULL
      WHERE revision_id=p_revision;
    DELETE FROM knowledge_entry_vectors WHERE account_id=p_account AND revision_id=p_revision;
    PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
    RETURN 'obsolete';
  END IF;
  IF entry.id IS NULL OR entry.archived OR entry.published_revision_id IS DISTINCT FROM p_revision THEN
    UPDATE knowledge_index_jobs SET state='pending',lease_id=NULL,lease_until=NULL,
      last_failure='waiting_for_review',next_attempt_at=clock_timestamp()+interval '1 minute',
      attempts=0 WHERE revision_id=p_revision;
    PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
    RETURN 'awaiting_review';
  END IF;
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RETURN 'published';
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_index_retention_active(p_account uuid, p_entry uuid, p_revision uuid, p_preparing_document uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE dep record; document_id uuid; file_id uuid; file_subject text; allowed boolean:=true;
  previous_workspace text:=current_setting('opengeni.workspace_id',true);
  previous_subject text:=current_setting('opengeni.subject_id',true);
  previous_owner text:=current_setting('opengeni.private_file_owner',true);
BEGIN
  FOR dep IN WITH RECURSIVE dependencies(entry_id,revision_id) AS (
    SELECT p_entry,p_revision UNION
    SELECT l.target_entry_id,l.target_revision_id FROM dependencies d JOIN knowledge_entry_links l
      ON l.account_id=p_account AND l.entry_id=d.entry_id AND l.revision_id=d.revision_id AND l.relation='evidence'
  ) SELECT e.*,r.body,r.id AS revision_id FROM dependencies d
    LEFT JOIN knowledge_entries e ON e.account_id=p_account AND e.id=d.entry_id
    LEFT JOIN knowledge_entry_revisions r ON r.account_id=p_account AND r.entry_id=d.entry_id AND r.id=d.revision_id
  LOOP
    IF dep.id IS NULL OR dep.revision_id IS NULL OR dep.archived
      OR dep.valid_from>clock_timestamp() OR dep.valid_until<=clock_timestamp() THEN allowed:=false; EXIT; END IF;
    PERFORM set_config('opengeni.workspace_id',coalesce(dep.scope_workspace_id,dep.origin_workspace_id)::text,true);
    PERFORM set_config('opengeni.subject_id',coalesce(dep.scope_subject_id,''),true);
    PERFORM set_config('opengeni.private_file_owner',coalesce(dep.scope_subject_id,''),true);
    IF dep.legacy_document_version_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM knowledge_document_versions v
      JOIN knowledge_source_objects o ON o.account_id=v.account_id AND o.id=v.object_id AND o.lifecycle_state='active'
      JOIN knowledge_sources s ON s.account_id=v.account_id AND s.id=v.source_id AND s.lifecycle_state='active'
      JOIN knowledge_providers p ON p.account_id=s.account_id AND p.id=s.provider_id AND p.lifecycle_state='active'
      JOIN knowledge_source_acl_versions a ON a.account_id=s.account_id AND a.source_id=s.id AND a.generation=s.current_acl_generation
      WHERE v.account_id=p_account AND v.id=dep.legacy_document_version_id
    ) THEN allowed:=false; EXIT; END IF;
    document_id:=coalesce(dep.access_document_id,dep.legacy_document_id,(dep.body#>>'{source,documentId}')::uuid);
    IF document_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM documents d
      WHERE d.account_id=p_account AND d.id=document_id AND d.status='ready') THEN allowed:=false; EXIT; END IF;
    file_id:=coalesce(dep.access_file_id,(dep.body#>>'{source,fileId}')::uuid);
    -- The retained original's immutable initiator is processing provenance, not
    -- a human grant. Ordinary Knowledge reads still check the current caller.
    file_subject:=dep.scope_subject_id;
    IF document_id IS NOT NULL THEN
      SELECT coalesce(d.authority_subject_id,d.created_by) INTO file_subject FROM documents d
        WHERE d.account_id=p_account AND d.id=document_id;
    END IF;
    PERFORM set_config('opengeni.subject_id',coalesce(file_subject,''),true);
    IF file_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM files f
      WHERE f.account_id=p_account AND f.id=file_id AND f.status='ready')
      OR ((p_preparing_document IS NULL OR document_id IS DISTINCT FROM p_preparing_document) AND NOT google_drive_file_authorized(p_account,coalesce(dep.scope_workspace_id,dep.origin_workspace_id),file_subject,file_id)))
      THEN allowed:=false; EXIT; END IF;
  END LOOP;
  PERFORM set_config('opengeni.workspace_id',coalesce(previous_workspace,''),true);
  PERFORM set_config('opengeni.subject_id',coalesce(previous_subject,''),true);
  PERFORM set_config('opengeni.private_file_owner',coalesce(previous_owner,''),true);
  RETURN allowed;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.workspace_id',coalesce(previous_workspace,''),true);
  PERFORM set_config('opengeni.subject_id',coalesce(previous_subject,''),true);
  PERFORM set_config('opengeni.private_file_owner',coalesce(previous_owner,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_index_revision(p_account uuid, p_entry uuid, p_revision uuid, p_text text) RETURNS void
    LANGUAGE sql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  INSERT INTO knowledge_entry_search(account_id,entry_id,revision_id,chunk_index,search_vector)
  SELECT p_account,p_entry,p_revision,(n/14000)::integer,
    setweight(to_tsvector('simple',r.body->>'title'),'A') ||
      setweight(to_tsvector('simple',substring(p_text FROM n+1 FOR 16000)),'B')
  FROM generate_series(0,greatest(length(p_text)-1,0),14000) n
  JOIN knowledge_entry_revisions r ON r.account_id=p_account AND r.entry_id=p_entry AND r.id=p_revision
$$;

CREATE FUNCTION knowledge_index_wait_for_funding(p_account uuid, p_revision uuid, p_lease uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  job knowledge_index_jobs%ROWTYPE;
  previous text := current_setting('opengeni.knowledge_index_dispatcher',true);
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Knowledge index tenant mismatch' USING ERRCODE='42501';
  END IF;
  -- knowledge_index_jobs is FORCE-RLS and only the owner-definer dispatcher
  -- policy may see the leased job. Restore the transaction-local capability
  -- even if the lease fence fails.
  PERFORM set_config('opengeni.knowledge_index_dispatcher','1',true);
  SELECT * INTO job FROM knowledge_index_jobs j WHERE j.account_id=p_account
    AND j.revision_id=p_revision AND j.lease_id=p_lease AND j.state='running'
    AND j.lease_until>clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Knowledge index lease unavailable' USING ERRCODE='40001';
  END IF;
  UPDATE knowledge_index_jobs SET state='pending',lease_id=NULL,lease_until=NULL,
    last_failure='waiting_for_funding',next_attempt_at=clock_timestamp()+interval '1 minute',
    attempts=0 WHERE revision_id=p_revision;
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RETURN jsonb_build_object('status','pending');
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_index_work(p_account uuid, p_revision uuid, p_lease uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE job knowledge_index_jobs%ROWTYPE; revision knowledge_entry_revisions%ROWTYPE; entry knowledge_entries%ROWTYPE;
  operation text:=p_request->>'operation'; chunk jsonb; ordinal integer:=0; vector_value vector;
BEGIN
  IF p_account IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Knowledge index tenant mismatch' USING ERRCODE='42501'; END IF;
  SELECT * INTO job FROM knowledge_index_jobs j WHERE j.account_id=p_account AND j.revision_id=p_revision
    AND j.lease_id=p_lease AND j.state='running' AND j.lease_until>clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Knowledge index lease unavailable' USING ERRCODE='40001'; END IF;
  SELECT * INTO entry FROM knowledge_entries e WHERE e.account_id=p_account AND e.id=job.entry_id;
  SELECT * INTO revision FROM knowledge_entry_revisions r WHERE r.account_id=p_account AND r.id=p_revision;
  IF entry.id IS NULL OR revision.id IS NULL OR entry.archived OR revision.change_kind='archive'
    OR (p_revision IS DISTINCT FROM entry.latest_revision_id AND p_revision IS DISTINCT FROM entry.published_revision_id) THEN
    UPDATE knowledge_index_jobs SET state='obsolete',lease_id=NULL,lease_until=NULL WHERE revision_id=p_revision;
    DELETE FROM knowledge_entry_vectors WHERE account_id=p_account AND revision_id=p_revision;
    RETURN jsonb_build_object('status','obsolete');
  END IF;
  IF operation NOT IN ('fail','continue') AND NOT knowledge_index_retention_active(p_account,entry.id,p_revision) THEN
    UPDATE knowledge_index_jobs SET state='pending',lease_id=NULL,lease_until=NULL,last_failure='source_unavailable',
      next_attempt_at=clock_timestamp()+interval '1 hour' WHERE revision_id=p_revision;
    RETURN jsonb_build_object('status','pending');
  END IF;
  IF operation='read' THEN
    UPDATE knowledge_index_jobs SET lease_until=clock_timestamp()+interval '5 minutes' WHERE revision_id=p_revision;
    RETURN jsonb_build_object('status','running','body',revision.body,'codecVersion',revision.body_codec_version,
      'originWorkspaceId',entry.origin_workspace_id,'scope',entry.scope,'subjectId',entry.scope_subject_id,
      'nextIndex',job.next_index,'generation',job.generation);
  ELSIF operation='append' THEN
    IF jsonb_typeof(p_request->'chunks') IS DISTINCT FROM 'array' OR jsonb_array_length(p_request->'chunks') NOT BETWEEN 1 AND 64
      OR (p_request->>'expectedNextIndex')::integer IS DISTINCT FROM job.next_index THEN
      RAISE EXCEPTION 'Knowledge index checkpoint changed' USING ERRCODE='40001'; END IF;
    FOR chunk IN SELECT value FROM jsonb_array_elements(p_request->'chunks') LOOP
      IF (chunk->>'index')::integer IS DISTINCT FROM job.next_index+ordinal
        OR jsonb_typeof(chunk->'text') IS DISTINCT FROM 'string' OR length(chunk->>'text')>16384
        OR jsonb_typeof(chunk->'embedding') IS DISTINCT FROM 'array' OR jsonb_array_length(chunk->'embedding')<>job.dimensions THEN
        RAISE EXCEPTION 'Invalid Knowledge index chunk' USING ERRCODE='22023'; END IF;
      vector_value:=(chunk->'embedding')::text::vector;
      INSERT INTO knowledge_entry_vectors(account_id,entry_id,revision_id,generation,chunk_index,model,dimensions,
        field,start_offset,end_offset,text,text_codec_version,embedding)
      VALUES(p_account,job.entry_id,p_revision,job.generation,job.next_index+ordinal,job.model,job.dimensions,
        chunk->>'field',(chunk->>'start')::integer,(chunk->>'end')::integer,chunk->>'text',1,vector_value);
      ordinal:=ordinal+1;
    END LOOP;
    UPDATE knowledge_index_jobs SET next_index=next_index+ordinal,lease_until=clock_timestamp()+interval '5 minutes' WHERE revision_id=p_revision;
    RETURN jsonb_build_object('status','running','nextIndex',job.next_index+ordinal);
  ELSIF operation='complete' THEN
    IF (p_request->>'expectedNextIndex')::integer IS DISTINCT FROM job.next_index OR job.next_index<1 THEN
      RAISE EXCEPTION 'Knowledge index checkpoint changed' USING ERRCODE='40001'; END IF;
    UPDATE knowledge_index_jobs SET state='ready',completed_generation=generation,lease_id=NULL,lease_until=NULL,last_failure=NULL WHERE revision_id=p_revision;
    DELETE FROM knowledge_entry_vectors WHERE account_id=p_account AND revision_id=p_revision AND generation<>job.generation;
    RETURN jsonb_build_object('status','ready');
  ELSIF operation='continue' THEN
    UPDATE knowledge_index_jobs SET state='pending',lease_id=NULL,lease_until=NULL,next_attempt_at=clock_timestamp(),attempts=0
      WHERE revision_id=p_revision;
    RETURN jsonb_build_object('status','pending');
  ELSIF operation='fail' THEN
    UPDATE knowledge_index_jobs SET state='pending',lease_id=NULL,lease_until=NULL,last_failure='embedding_unavailable',
      next_attempt_at=clock_timestamp()+least(3600,power(2,least(attempts,10))*5)*interval '1 second' WHERE revision_id=p_revision;
    RETURN jsonb_build_object('status','pending');
  END IF;
  RAISE EXCEPTION 'Unknown Knowledge index operation' USING ERRCODE='22023';
END $$;

CREATE FUNCTION knowledge_instruction_confirm_legacy(p_account uuid, p_workspace uuid, p_actor jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor jsonb; subject text; candidate record; result jsonb; recovered jsonb;
  revision workspace_instruction_policy_revisions%ROWTYPE; prior agent_instruction_operations%ROWTYPE;
  activation governed_learning_activation_receipts%ROWTYPE; unavailable integer:=0; receipts jsonb:='[]'::jsonb;
  legacy_operation_id uuid; fingerprint text; note_capability uuid:=gen_random_uuid();
  previous_note_capability text:=current_setting('opengeni.task_note_write_capability',true);
  previous_legacy_claim text:=current_setting('opengeni.knowledge_legacy_lock_claim',true);
BEGIN
  IF p_actor->>'kind' IS DISTINCT FROM 'agent'
    OR p_account IS DISTINCT FROM nullif(current_setting('opengeni.account_id',true),'')::uuid
    OR p_workspace IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Legacy instruction confirmation requires exact tenant and agent authority' USING ERRCODE='42501'; END IF;
  IF p_request->>'operation'='recover' THEN
    FOR candidate IN
      SELECT DISTINCT d.proposal_id,d.id AS decision_id,q.id AS request_id
      FROM agent_instruction_operations imported
      JOIN governed_learning_decision_receipts d ON d.account_id=imported.account_id AND d.workspace_id=imported.origin_workspace_id
        AND d.proposal_id::text=imported.actor#>>'{legacyInstructionContext,legacyProposalId}'
      JOIN session_human_input_requests q ON q.account_id=d.account_id AND q.workspace_id=d.workspace_id
        AND q.session_id=d.session_id AND q.turn_id=d.turn_id AND q.status='answered'
      WHERE imported.account_id=p_account AND imported.origin_workspace_id=p_workspace
        AND imported.request_hash='migration:0461:instruction-review' AND imported.actor->>'kind'='migration'
        AND d.session_id=(p_actor->>'sessionId')::uuid AND d.turn_id=(p_actor->>'turnId')::uuid
        AND q.responded_by=d.initiating_human_subject_id
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(q.response->'answers') a
          WHERE a->>'questionId'='remember:'||d.proposal_id AND a->'values'='["save"]'::jsonb)
      ORDER BY d.proposal_id,d.id,q.id
    LOOP
      BEGIN
        recovered:=knowledge_instruction_confirm_legacy(p_account,p_workspace,p_actor,jsonb_build_object(
          'operationId',overlay(overlay(md5('0461:instruction-confirm:'||candidate.request_id||':'||candidate.decision_id) placing '5' from 13 for 1) placing '8' from 17 for 1)::uuid,
          'proposalId',candidate.proposal_id,'decisionReceiptId',candidate.decision_id,'humanInputRequestId',candidate.request_id));
        receipts:=receipts||jsonb_build_array(recovered);
      EXCEPTION WHEN insufficient_privilege OR serialization_failure OR unique_violation OR check_violation THEN unavailable:=unavailable+1;
      END;
    END LOOP;
    RETURN jsonb_build_object('receipts',receipts,'unavailable',unavailable);
  END IF;
  -- Match the native activation lock prefix before validating the live attempt.
  PERFORM 1 FROM workspaces WHERE account_id=p_account AND id=p_workspace FOR UPDATE;
  actor:=knowledge_resolve_actor(p_account,p_workspace,p_actor);
  subject:=nullif(current_setting('opengeni.subject_id',true),'');
  SELECT r.* INTO revision FROM workspace_instruction_policy_revisions r
    JOIN agent_instruction_operations imported ON imported.account_id=r.account_id AND imported.revision_id=r.id
    JOIN governed_learning_decision_receipts d ON d.account_id=r.account_id AND d.workspace_id=r.workspace_id
      AND d.proposal_id::text=imported.actor#>>'{legacyInstructionContext,legacyProposalId}'
    WHERE r.account_id=p_account AND r.workspace_id=p_workspace
      AND imported.request_hash='migration:0461:instruction-review' AND imported.actor->>'kind'='migration'
      AND d.id=(p_request->>'decisionReceiptId')::uuid AND d.proposal_id=(p_request->>'proposalId')::uuid
      AND d.initiating_human_subject_id=subject AND d.session_id=(p_actor->>'sessionId')::uuid
      AND d.turn_id=(p_actor->>'turnId')::uuid
    ORDER BY r.revision DESC,r.created_at DESC,r.id DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No imported instruction matches this confirmation' USING ERRCODE='42501'; END IF;
  legacy_operation_id:=(p_request->>'operationId')::uuid;
  fingerprint:=encode(sha256(convert_to(jsonb_build_array('legacy-instruction-confirmation',p_request,subject)::text,'UTF8')),'hex');
  SELECT * INTO prior FROM agent_instruction_operations op WHERE op.account_id=p_account AND op.operation_id=legacy_operation_id;
  IF FOUND THEN
    IF prior.request_hash IS DISTINCT FROM fingerprint OR prior.revision_id<>revision.id OR prior.origin_workspace_id<>p_workspace THEN
      RAISE EXCEPTION 'Legacy instruction confirmation operation conflicts' USING ERRCODE='23505'; END IF;
    RETURN prior.receipt||jsonb_build_object('replayed',true);
  END IF;
  IF EXISTS(SELECT 1 FROM agent_instruction_operations op WHERE op.account_id=p_account AND op.revision_id=revision.id
      AND op.receipt->>'outcome' IN ('published','rejected'))
    OR EXISTS(SELECT 1 FROM workspace_instruction_policy_revisions newer WHERE newer.account_id=p_account AND newer.workspace_id=p_workspace
      AND newer.kind=revision.kind AND newer.scope=revision.scope AND newer.role_key IS NOT DISTINCT FROM revision.role_key
      AND newer.revision>revision.revision) THEN
    RAISE EXCEPTION 'Imported instruction review is no longer current' USING ERRCODE='40001'; END IF;
  PERFORM set_config('opengeni.knowledge_legacy_lock_claim',(SELECT d.claim_id::text FROM governed_learning_decision_receipts d
    WHERE d.account_id=p_account AND d.id=(p_request->>'decisionReceiptId')::uuid),true);
  -- The exact attempt was validated above. The existing native confirmation
  -- checks the bound note/root/version/hash; its read needs the note lifecycle lease.
  INSERT INTO task_note_write_capabilities(backend_pid,transaction_id,capability_id)
    VALUES(pg_backend_pid(),pg_current_xact_id(),note_capability);
  PERFORM set_config('opengeni.task_note_write_capability',note_capability::text,true);
  SELECT * INTO activation FROM activate_human_confirmed_learning_decision(p_account,p_workspace,
    legacy_operation_id,(p_request->>'decisionReceiptId')::uuid,(p_request->>'humanInputRequestId')::uuid);
  DELETE FROM task_note_write_capabilities WHERE backend_pid=pg_backend_pid()
    AND transaction_id=pg_current_xact_id() AND capability_id=note_capability;
  PERFORM set_config('opengeni.task_note_write_capability',coalesce(previous_note_capability,''),true);
  PERFORM set_config('opengeni.knowledge_legacy_lock_claim',coalesce(previous_legacy_claim,''),true);
  IF activation.id IS NULL OR activation.destination_revision_id IS DISTINCT FROM revision.id THEN
    RAISE EXCEPTION 'Confirmation must activate the exact imported instruction' USING ERRCODE='40001'; END IF;
  result:=jsonb_build_object('operationId',legacy_operation_id,'revisionId',revision.id,'outcome','published','reviewBatchId',NULL,'replayed',false);
  INSERT INTO agent_instruction_operations(account_id,origin_workspace_id,operation_id,revision_id,request_hash,actor,receipt)
    VALUES(p_account,p_workspace,legacy_operation_id,revision.id,fingerprint,p_actor||jsonb_build_object(
      'legacyHumanInputRequestId',p_request->'humanInputRequestId','activationReceiptId',activation.id,'initiatingHumanSubjectId',subject),result);
  RETURN result;
END $$;

CREATE SEQUENCE workspace_instruction_policy_revision_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE workspace_instruction_policy_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    revision bigint DEFAULT nextval('workspace_instruction_policy_revision_seq'::regclass) NOT NULL,
    kind text NOT NULL,
    scope text NOT NULL,
    role_key text,
    content text NOT NULL,
    content_hash text NOT NULL,
    provenance_source text NOT NULL,
    provenance_source_id text,
    supersedes_revision_id uuid,
    created_by_subject_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    operation_id uuid,
    request_fingerprint text,
    agent_learning_context jsonb,
    CONSTRAINT workspace_instruction_policy_revisions_actor_chk CHECK (((length(btrim(created_by_subject_id)) >= 1) AND (length(btrim(created_by_subject_id)) <= 1024))),
    CONSTRAINT workspace_instruction_policy_revisions_content_chk CHECK (((length(btrim(content)) > 0) AND (octet_length(content) <= 1048576))),
    CONSTRAINT workspace_instruction_policy_revisions_hash_chk CHECK (((content_hash ~ '^[0-9a-f]{64}$'::text) AND (content_hash = encode(sha256(convert_to(content, 'UTF8'::name)), 'hex'::text)))),
    CONSTRAINT workspace_instruction_policy_revisions_operation_receipt_chk CHECK ((((operation_id IS NULL) AND (request_fingerprint IS NULL)) OR ((operation_id IS NOT NULL) AND (request_fingerprint ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT workspace_instruction_policy_revisions_provenance_chk CHECK (((provenance_source = ANY (ARRAY['human'::text, 'onboarding'::text, 'knowledge_proposal'::text, 'legacy_import'::text, 'agent_learning'::text])) AND ((provenance_source_id IS NULL) OR ((length(provenance_source_id) >= 1) AND (length(provenance_source_id) <= 512))) AND ((provenance_source = 'agent_learning'::text) = (agent_learning_context IS NOT NULL)))),
    CONSTRAINT workspace_instruction_policy_revisions_revision_chk CHECK ((revision > 0)),
    CONSTRAINT workspace_instruction_policy_revisions_role_key_chk CHECK (((role_key IS NULL) OR ((role_key = lower(btrim(role_key))) AND ((length(role_key) >= 1) AND (length(role_key) <= 64)) AND (role_key ~ '^[a-z0-9](?:[a-z0-9._-]*[a-z0-9])?$'::text) AND (role_key !~ '--'::text)))),
    CONSTRAINT workspace_instruction_policy_revisions_target_chk CHECK ((((kind = 'charter'::text) AND (scope = 'global'::text) AND (role_key IS NULL)) OR ((kind = 'policy'::text) AND (scope = 'global'::text) AND (role_key IS NULL)) OR ((kind = 'policy'::text) AND (scope = 'role'::text) AND (role_key IS NOT NULL))))
);

ALTER TABLE ONLY workspace_instruction_policy_revisions FORCE ROW LEVEL SECURITY;

CREATE FUNCTION knowledge_instruction_context(p_revision workspace_instruction_policy_revisions) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT coalesce(p_revision.agent_learning_context,(SELECT op.actor->'legacyInstructionContext'
    FROM agent_instruction_operations op WHERE op.account_id=p_revision.account_id AND op.revision_id=p_revision.id
      AND op.request_hash='migration:0461:instruction-review' AND op.actor->>'kind'='migration' LIMIT 1))
$$;

CREATE FUNCTION knowledge_learning_context_visible(p_account uuid, p_workspace uuid, p_subject text, p_scope text, p_context text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE session sessions%ROWTYPE; task scheduled_tasks%ROWTYPE; target uuid;
BEGIN
  IF p_context ~ '^chat:[0-9a-f-]{36}$' THEN
    SELECT * INTO session FROM sessions WHERE account_id=p_account AND workspace_id=p_workspace AND id=substring(p_context FROM 6)::uuid;
    IF NOT FOUND THEN RETURN false; END IF;
    IF get_workspace_kind(p_account,p_workspace)='personal' THEN RETURN p_scope='personal' AND p_subject IS NOT NULL; END IF;
    IF session.visibility='user_private' THEN RETURN coalesce(p_scope='personal' AND session.owner_subject_id=p_subject,false); END IF;
    IF session.memory_scope='user' THEN RETURN coalesce(p_scope='personal' AND session.scope_subject_id=p_subject,false); END IF;
    RETURN p_scope='workspace';
  ELSIF p_context ~ '^scheduled_task:[0-9a-f-]{36}$' THEN
    SELECT * INTO task FROM scheduled_tasks WHERE account_id=p_account AND workspace_id=p_workspace AND id=substring(p_context FROM 16)::uuid AND deleted_at IS NULL;
    IF NOT FOUND THEN RETURN false; END IF;
    IF task.agent_config#>>'{knowledgeSource,destination,kind}'='personal' THEN
      RETURN coalesce(p_scope='personal' AND p_subject=task.agent_config#>>'{knowledgeSource,destination,subjectId}',false); END IF;
    IF get_workspace_kind(p_account,p_workspace)='personal' THEN RETURN p_scope='personal' AND p_subject IS NOT NULL; END IF;
    target:=CASE WHEN task.run_mode IN ('existing_session','reusable_session') THEN task.reusable_session_id END;
    IF target IS NOT NULL THEN RETURN knowledge_learning_context_visible(p_account,p_workspace,p_subject,p_scope,'chat:'||target); END IF;
    IF task.run_mode='existing_session' THEN RETURN false; END IF;
    IF task.creator_session_policy->>'memoryScope'='user' THEN RETURN coalesce(p_scope='personal' AND task.creator_session_policy->>'scopeSubjectId'=p_subject,false); END IF;
    RETURN p_scope='workspace';
  END IF;
  RETURN false;
END $_$;

CREATE FUNCTION knowledge_learning_for_turn(p_account uuid, p_workspace uuid, p_turn uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE t session_turns%ROWTYPE; s sessions%ROWTYPE; run scheduled_task_runs%ROWTYPE;
  result jsonb; inherited jsonb; current_policy jsonb; subject text; destination text;
  producer uuid; source_context text; accepted_at timestamptz;
BEGIN
  SELECT snapshot INTO result FROM agent_learning_snapshots WHERE account_id=p_account AND turn_id=p_turn;
  IF result IS NOT NULL THEN RETURN result; END IF;
  SELECT * INTO t FROM session_turns WHERE account_id=p_account AND workspace_id=p_workspace AND id=p_turn;
  IF NOT FOUND THEN RAISE EXCEPTION 'Learning accepted turn unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO s FROM sessions WHERE account_id=p_account AND workspace_id=p_workspace AND id=t.session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Learning session unavailable' USING ERRCODE='42501'; END IF;
  subject:=coalesce(t.initiating_human_subject_id,CASE WHEN t.initiator_kind='subject' THEN t.initiator_subject_id END);
  -- The accepted initiating-human field is authority; subject spelling is not.
  -- Opaque authenticated host/local subjects retain the same personal layer.
  destination:=CASE WHEN s.visibility='user_private' OR s.memory_scope='user'
    OR (subject IS NOT NULL AND get_workspace_kind(p_account,p_workspace)='personal') THEN 'personal' ELSE 'workspace' END;
  IF destination='personal' AND (subject IS NULL OR (s.visibility='user_private' AND s.owner_subject_id IS DISTINCT FROM subject)) THEN
    RAISE EXCEPTION 'Personal learning requires an initiating owner' USING ERRCODE='42501';
  END IF;
  IF destination='workspace' THEN subject:=NULL; END IF;
  source_context:='chat:'||s.id; accepted_at:=t.created_at;
  IF t.scheduled_task_run_id IS NOT NULL THEN
    SELECT * INTO run FROM scheduled_task_runs WHERE id=t.scheduled_task_run_id AND account_id=p_account AND workspace_id=p_workspace;
    IF NOT FOUND THEN RAISE EXCEPTION 'Learning scheduled run unavailable' USING ERRCODE='42501'; END IF;
    source_context:='scheduled_task:'||run.task_id; accepted_at:=run.created_at;
  ELSE
    IF t.source IN ('goal','system') THEN
      SELECT prior.id INTO producer FROM session_system_updates u
        JOIN session_turns prior ON prior.id=CASE WHEN u.kind IN ('goal_continuation','background_command_result','session_wait_timeout')
          THEN (u.lineage->>'causalTurnId')::uuid ELSE (u.lineage->>'parentTurnId')::uuid END
          AND prior.account_id=p_account AND prior.workspace_id=p_workspace AND prior.session_id=s.id
        WHERE u.account_id=p_account AND u.workspace_id=p_workspace AND u.session_id=s.id
          AND u.delivered_turn_id=t.id AND u.state='delivered' AND u.delivered_history_item_id IS NOT NULL
          AND u.kind IN ('goal_continuation','background_command_result','session_wait_timeout','child_terminal_result','child_requires_action','child_requires_action_resolved',
            'child_paused','child_waiting_capacity','child_progress')
          AND prior.created_at<t.created_at
        ORDER BY prior.position DESC LIMIT 1;
    ELSIF s.parent_turn_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM session_turns other
      WHERE other.account_id=p_account AND other.session_id=s.id AND other.position<t.position) THEN
      SELECT prior.id INTO producer FROM session_turns prior JOIN sessions parent ON parent.id=prior.session_id
        AND parent.account_id=prior.account_id AND parent.workspace_id=prior.workspace_id
        WHERE prior.account_id=p_account AND prior.workspace_id=p_workspace AND prior.id=s.parent_turn_id
          AND prior.session_id=s.parent_session_id AND prior.created_at<t.created_at AND parent.visibility=s.visibility
          AND prior.initiating_human_subject_id IS NOT DISTINCT FROM t.initiating_human_subject_id;
    END IF;
  END IF;
  current_policy:=knowledge_learning_resolve(p_account,p_workspace,subject,source_context,accepted_at);
  -- Old clients may still create a session with memoryScope=off. Preserve that
  -- accepted opt-out as a sparse context setting, rather than silently enabling
  -- writes after cutover. A later explicit context revision (including an empty
  -- Use-default reset) owns future turns. Never backfill over such a revision.
  IF s.memory_scope='off' AND (current_policy->>'contextVersion')::integer=0 THEN
    INSERT INTO agent_learning_revisions(account_id,origin_workspace_id,owner_key,subject_id,context_key,
      version,settings,operation_id,request_hash,actor_subject_id,created_at)
    SELECT p_account,p_workspace,current_policy->>'ownerKey',subject,source_context,1,'{"knowledge":"off"}'::jsonb,
      gen_random_uuid(),'legacy-session-off:'||s.id,'service:knowledge-compatibility',accepted_at
    WHERE NOT EXISTS(SELECT 1 FROM agent_learning_revisions r WHERE r.account_id=p_account
      AND r.owner_key=current_policy->>'ownerKey' AND r.context_key=source_context)
    ON CONFLICT DO NOTHING;
    current_policy:=knowledge_learning_resolve(p_account,p_workspace,subject,source_context,accepted_at);
    -- A setting can have been edited after this work was accepted. It must not
    -- alter the accepted opt-out, even when that later row prevented the seed.
    current_policy:=jsonb_set(jsonb_set(current_policy,'{effective,knowledge}','"off"'::jsonb),
      '{overrides}',(current_policy->'overrides')||'{"knowledge":"off"}'::jsonb);
  END IF;
  IF producer IS NOT NULL THEN
    inherited:=knowledge_learning_for_turn(p_account,p_workspace,producer);
    -- A child may deliberately narrow workspace learning to personal or Off.
    -- Keep its independently resolved owner and destination while inheriting
    -- only accepted policy modes and scheduled-run provenance. An explicit
    -- child/chat override still wins.
    result:=current_policy||jsonb_build_object('effective',(inherited->'effective')||(current_policy->'overrides'),
      'producerTurnId',producer,'scheduledTaskRunId',inherited->'scheduledTaskRunId');
  ELSE
    result:=current_policy||jsonb_build_object('scheduledTaskRunId',t.scheduled_task_run_id);
  END IF;
  -- Human-less work in a personal workspace reads but never saves (0868).
  IF destination='workspace' AND get_workspace_kind(p_account,p_workspace)='personal' THEN
    result:=jsonb_set(result,'{effective}','{"knowledge":"off","instructions":"off","skills":"off"}'::jsonb);
  END IF;
  result:=result||jsonb_build_object('defaultScope',destination,'subjectId',subject,'acceptedAt',accepted_at);
  INSERT INTO agent_learning_snapshots(account_id,workspace_id,session_id,turn_id,snapshot)
    VALUES(p_account,p_workspace,s.id,t.id,result) ON CONFLICT(account_id,turn_id) DO NOTHING;
  SELECT snapshot INTO result FROM agent_learning_snapshots WHERE account_id=p_account AND turn_id=t.id;
  RETURN result;
END $$;

CREATE FUNCTION knowledge_learning_resolve(p_account uuid, p_workspace uuid, p_subject text, p_context text, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE base jsonb; overrides jsonb; base_version integer; context_version integer;
  owner text:=CASE WHEN p_subject IS NULL THEN 'workspace:'||p_workspace ELSE 'personal:'||p_subject END;
BEGIN
  SELECT settings,version INTO base,base_version FROM agent_learning_revisions
    WHERE account_id=p_account AND owner_key=owner AND context_key='defaults' AND created_at<=p_at
    ORDER BY version DESC LIMIT 1;
  base:=coalesce(base,CASE WHEN p_at < '{{migrated_at}}'::timestamptz THEN '{"knowledge":"automatic","instructions":"review_first","skills":"review_first"}'::jsonb ELSE '{"knowledge":"automatic","instructions":"automatic","skills":"automatic"}'::jsonb END);
  SELECT settings,version INTO overrides,context_version FROM agent_learning_revisions
    WHERE account_id=p_account AND owner_key=owner AND context_key=p_context AND created_at<=p_at
    ORDER BY version DESC LIMIT 1;
  RETURN jsonb_build_object('ownerKey',owner,'defaultsVersion',coalesce(base_version,0),
    'contextKey',p_context,'contextVersion',coalesce(context_version,0),
    'defaults',base,'overrides',coalesce(overrides,'{}'::jsonb),'effective',base||coalesce(overrides,'{}'::jsonb));
END $$;

CREATE FUNCTION knowledge_learning_settings_valid(value jsonb, complete boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT coalesce(jsonb_typeof(value)='object'
    AND value-'knowledge'-'instructions'-'skills'='{}'::jsonb
    AND (NOT complete OR value ?& ARRAY['knowledge','instructions','skills'])
    AND NOT EXISTS(SELECT 1 FROM jsonb_each(value) p
      WHERE jsonb_typeof(p.value)<>'string' OR p.value#>>'{}' NOT IN ('automatic','review_first','off')),false)
$$;

CREATE FUNCTION knowledge_legacy_memory_setting_retired() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.settings->'memoryEnabled' IS DISTINCT FROM OLD.settings->'memoryEnabled' THEN
    RAISE EXCEPTION 'Memory settings moved to Agent learning' USING ERRCODE='0A000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION knowledge_legacy_version_visible(p_account uuid, p_version uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS(SELECT 1 FROM knowledge_document_versions v
    JOIN knowledge_source_objects o ON o.account_id=v.account_id AND o.id=v.object_id AND o.lifecycle_state='active'
    JOIN knowledge_sources s ON s.account_id=v.account_id AND s.id=v.source_id AND s.lifecycle_state='active'
    JOIN knowledge_providers p ON p.account_id=s.account_id AND p.id=s.provider_id AND p.lifecycle_state='active'
    JOIN knowledge_source_acl_versions captured ON captured.account_id=v.account_id AND captured.id=v.acl_version_id
      AND captured.source_id=v.source_id AND captured.generation=v.acl_generation
    JOIN knowledge_source_acl_versions current_acl ON current_acl.account_id=s.account_id AND current_acl.source_id=s.id
      AND current_acl.generation=s.current_acl_generation
    WHERE v.account_id=p_account AND v.id=p_version
      AND (current_setting('opengeni.knowledge_actor_kind',true)='human' OR (captured.agent_access AND current_acl.agent_access))
      AND (v.document_id IS NULL OR knowledge_document_visible(v.document_id))
      AND (v.file_id IS NULL OR google_drive_file_authorized(p_account,
        nullif(current_setting('opengeni.workspace_id',true),'')::uuid,nullif(current_setting('opengeni.subject_id',true),''),v.file_id)))
$$;

CREATE FUNCTION knowledge_media_file_owner_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.private_file_owner_subject_id IS DISTINCT FROM OLD.private_file_owner_subject_id THEN
    RAISE EXCEPTION 'An operation retains its accepted original-file owner' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION knowledge_memory_apply_operation(p_plan jsonb, p_plan_hash text, p_actor_kind text, p_actor_subject_id text, p_actor_session_id uuid, p_actor_turn_id uuid, p_actor_attempt_id uuid, p_actor_execution_generation integer) RETURNS TABLE(event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $_$
    DECLARE
      context_account_id uuid := nullif(current_setting('opengeni.account_id', true), '')::uuid;
      context_workspace_id uuid := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
      v_operation_id uuid;
      operation_type text;
      target_id uuid;
      related_id uuid;
      expected_target_version integer;
      expected_related_version integer;
      v_relationship_type text;
      relationship_id uuid;
      new_scope jsonb;
      new_scope_type text;
      new_scope_subject_id text;
      new_scope_role_key text;
      new_scope_session_id uuid;
      new_valid_until timestamptz;
      new_namespace text;
      new_labels text[];
      target record;
      related record;
      relationship record;
      before_state jsonb;
      after_state jsonb;
      new_event_id uuid := gen_random_uuid();
      authority_role_key text;
      existing_event record;
    BEGIN
      IF jsonb_typeof(p_plan) IS DISTINCT FROM 'object'
        OR p_plan_hash !~ '^[a-f0-9]{64}$'
        OR p_plan_hash IS DISTINCT FROM knowledge_memory_plan_hash(p_plan)
        OR p_actor_kind NOT IN ('subject', 'service')
        OR length(btrim(p_actor_subject_id)) NOT BETWEEN 1 AND 1024
      THEN
        RAISE EXCEPTION 'memory operation plan or actor is invalid' USING ERRCODE = '22023';
      END IF;
      IF context_account_id IS NULL OR context_workspace_id IS NULL
        OR opengeni_private.current_memory_actor_kind() IS DISTINCT FROM p_actor_kind
        OR opengeni_private.current_memory_actor_id() IS DISTINCT FROM p_actor_subject_id
        OR (p_actor_kind = 'subject'
          AND opengeni_private.current_subject_id() IS DISTINCT FROM p_actor_subject_id)
        OR (p_actor_kind = 'service' AND opengeni_private.current_subject_id() IS NOT NULL)
      THEN
        RAISE EXCEPTION 'memory operation requires exact transaction-local actor authority'
          USING ERRCODE = '42501';
      END IF;

      IF (p_actor_session_id IS NULL) <> (p_actor_turn_id IS NULL)
        OR (p_actor_session_id IS NULL) <> (p_actor_attempt_id IS NULL)
        OR (p_actor_session_id IS NULL) <> (p_actor_execution_generation IS NULL)
      THEN
        RAISE EXCEPTION 'memory operation attempt provenance is partial' USING ERRCODE = '22023';
      END IF;
      IF p_actor_session_id IS NOT NULL THEN
        SELECT session.metadata ->> 'memoryRoleKey' INTO authority_role_key
        FROM workspaces workspace
        JOIN sessions session
          ON session.account_id = workspace.account_id
         AND session.workspace_id = workspace.id
        JOIN session_turns turn
          ON turn.account_id = session.account_id
         AND turn.workspace_id = session.workspace_id
         AND turn.session_id = session.id
        JOIN session_turn_attempts attempt
          ON attempt.account_id = turn.account_id
         AND attempt.workspace_id = turn.workspace_id
         AND attempt.session_id = turn.session_id
         AND attempt.turn_id = turn.id
        WHERE workspace.account_id = context_account_id
          AND workspace.id = context_workspace_id
          AND session.id = p_actor_session_id
          AND session.active_turn_id = p_actor_turn_id
          AND turn.id = p_actor_turn_id
          AND turn.active_attempt_id = p_actor_attempt_id
          AND turn.execution_generation = p_actor_execution_generation
          AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
          AND turn.initiator_kind = p_actor_kind
          AND turn.initiator_subject_id = p_actor_subject_id
          AND attempt.id = p_actor_attempt_id
          AND attempt.execution_generation = p_actor_execution_generation
          AND attempt.state IN ('claimed', 'running')
          AND NOT EXISTS (
            SELECT 1 FROM session_attempt_interruptions interruption
            WHERE interruption.workspace_id = attempt.workspace_id
              AND interruption.attempt_id = attempt.id
              AND interruption.state IN ('pending', 'delivered', 'acknowledged')
          )
        FOR KEY SHARE OF workspace
        FOR SHARE OF session, turn
        FOR UPDATE OF attempt;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'memory operation attempt authority is stale or invalid'
            USING ERRCODE = '42501';
        END IF;
        IF authority_role_key IS NOT NULL AND (
          authority_role_key IS DISTINCT FROM lower(btrim(authority_role_key))
          OR length(authority_role_key) NOT BETWEEN 1 AND 64
          OR authority_role_key !~ '^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$'
        ) THEN
          RAISE EXCEPTION 'persisted memory role authority is invalid' USING ERRCODE = '42501';
        END IF;
        IF opengeni_private.current_memory_session_id() IS DISTINCT FROM p_actor_session_id
          OR opengeni_private.current_memory_role_key() IS DISTINCT FROM authority_role_key
        THEN
          RAISE EXCEPTION 'memory operation session or role context is not exact'
            USING ERRCODE = '42501';
        END IF;
      ELSIF opengeni_private.current_memory_session_id() IS NOT NULL
        OR opengeni_private.current_memory_role_key() IS NOT NULL
      THEN
        RAISE EXCEPTION 'direct memory authority cannot carry session or role context'
          USING ERRCODE = '42501';
      END IF;
      IF p_actor_session_id IS NOT NULL AND p_actor_execution_generation < 1 THEN
        RAISE EXCEPTION 'memory operation attempt generation is invalid' USING ERRCODE = '22023';
      END IF;
      IF p_actor_session_id IS NULL AND (
        p_actor_turn_id IS NOT NULL OR p_actor_attempt_id IS NOT NULL
        OR p_actor_execution_generation IS NOT NULL
      ) THEN
        RAISE EXCEPTION 'memory operation direct authority has attempt provenance'
          USING ERRCODE = '22023';
      END IF;
      IF p_actor_session_id IS NULL AND p_actor_kind = 'service'
        AND opengeni_private.current_subject_id() IS NOT NULL
      THEN
        RAISE EXCEPTION 'service memory authority cannot carry human subject context'
          USING ERRCODE = '42501';
      END IF;
      IF p_actor_session_id IS NULL AND p_actor_kind = 'subject'
        AND opengeni_private.current_subject_id() IS DISTINCT FROM p_actor_subject_id
      THEN
        RAISE EXCEPTION 'subject memory authority is not exact' USING ERRCODE = '42501';
      END IF;

      v_operation_id := (p_plan->>'operationId')::uuid;
      operation_type := p_plan->>'operationType';
      target_id := (p_plan->>'targetMemoryId')::uuid;
      expected_target_version := (p_plan->>'expectedTargetVersion')::integer;
      IF operation_type NOT IN (
        'reclassify', 'archive', 'relationship_add', 'relationship_remove',
        'supersede', 'correct'
      ) OR expected_target_version < 1 THEN
        RAISE EXCEPTION 'memory operation type or target version is invalid'
          USING ERRCODE = '22023';
      END IF;

      SELECT event.* INTO existing_event
      FROM knowledge_memory_lifecycle_events event
      WHERE event.workspace_id = context_workspace_id
        AND event.operation_id = v_operation_id
        AND event.action = 'apply';
      IF FOUND THEN
        IF existing_event.plan_hash IS DISTINCT FROM p_plan_hash
          OR existing_event.actor_kind IS DISTINCT FROM p_actor_kind
          OR existing_event.actor_subject_id IS DISTINCT FROM p_actor_subject_id
          OR existing_event.actor_session_id IS DISTINCT FROM p_actor_session_id
          OR existing_event.actor_turn_id IS DISTINCT FROM p_actor_turn_id
          OR existing_event.actor_attempt_id IS DISTINCT FROM p_actor_attempt_id
          OR existing_event.actor_execution_generation
            IS DISTINCT FROM p_actor_execution_generation
        THEN
          RAISE EXCEPTION 'memory operation id already identifies different immutable evidence'
            USING ERRCODE = '23505';
        END IF;
        RETURN QUERY SELECT existing_event.id;
        RETURN;
      END IF;

      IF operation_type IN ('relationship_add', 'relationship_remove', 'supersede', 'correct') THEN
        related_id := (p_plan->>'relatedMemoryId')::uuid;
        expected_related_version := (p_plan->>'expectedRelatedVersion')::integer;
        IF related_id IS NULL OR related_id = target_id OR expected_related_version < 1 THEN
          RAISE EXCEPTION 'memory relationship operation requires a distinct related memory'
            USING ERRCODE = '22023';
        END IF;
        PERFORM 1 FROM knowledge_memories candidate
        WHERE candidate.id IN (target_id, related_id)
          AND candidate.account_id = context_account_id
          AND candidate.workspace_id = context_workspace_id
        ORDER BY candidate.id FOR UPDATE;
      ELSE
        PERFORM 1 FROM knowledge_memories candidate
        WHERE candidate.id = target_id
          AND candidate.account_id = context_account_id
          AND candidate.workspace_id = context_workspace_id
        FOR UPDATE;
      END IF;

      SELECT * INTO target FROM knowledge_memories
      WHERE account_id = context_account_id AND workspace_id = context_workspace_id AND id = target_id;
      IF NOT FOUND OR NOT opengeni_private.memory_scope_visible(
        target.scope_type, target.scope_subject_id, target.scope_role_key, target.scope_session_id,
        target.valid_from, target.valid_until
      ) THEN
        RAISE EXCEPTION 'target memory is not visible to this authority' USING ERRCODE = '42501';
      END IF;
      IF target.memory_version <> expected_target_version THEN
        RAISE EXCEPTION 'target memory version changed' USING ERRCODE = '40001';
      END IF;

      IF related_id IS NOT NULL THEN
        SELECT * INTO related FROM knowledge_memories
        WHERE account_id = context_account_id AND workspace_id = context_workspace_id AND id = related_id;
        IF NOT FOUND OR NOT opengeni_private.memory_scope_visible(
          related.scope_type, related.scope_subject_id, related.scope_role_key,
          related.scope_session_id, related.valid_from, related.valid_until
        ) THEN
          RAISE EXCEPTION 'related memory is not visible to this authority' USING ERRCODE = '42501';
        END IF;
        IF related.memory_version <> expected_related_version THEN
          RAISE EXCEPTION 'related memory version changed' USING ERRCODE = '40001';
        END IF;
      END IF;

      before_state := jsonb_build_object(
        'memoryVersion', target.memory_version,
        'status', target.status,
        'scopeType', target.scope_type,
        'scopeSubjectId', target.scope_subject_id,
        'scopeRoleKey', target.scope_role_key,
        'scopeSessionId', target.scope_session_id,
        'namespace', target.namespace_key,
        'labels', to_jsonb(target.labels),
        'validUntil', target.valid_until,
        'supersedesId', target.supersedes_id,
        'supersededById', target.superseded_by_id
      );

      PERFORM set_config('opengeni.memory_lifecycle_operation', '1', true);

      IF operation_type = 'reclassify' THEN
        new_scope := p_plan->'scope';
        new_scope_type := new_scope->>'type';
        new_scope_subject_id := nullif(new_scope->>'subjectId', '');
        new_scope_role_key := nullif(new_scope->>'roleKey', '');
        new_scope_session_id := nullif(new_scope->>'sessionId', '')::uuid;
        new_valid_until := nullif(new_scope->>'validUntil', '')::timestamptz;
        new_namespace := p_plan->>'namespace';
        SELECT coalesce(array_agg(label ORDER BY label), '{}'::text[]) INTO new_labels
        FROM jsonb_array_elements_text(coalesce(p_plan->'labels', '[]'::jsonb)) AS label;
        IF new_scope_type = 'legacy' OR NOT coalesce((CASE new_scope_type
          WHEN 'workspace' THEN true
          WHEN 'user' THEN new_scope_subject_id = opengeni_private.current_subject_id()
          WHEN 'role' THEN new_scope_role_key = opengeni_private.current_memory_role_key()
          WHEN 'session' THEN new_scope_session_id = opengeni_private.current_memory_session_id()
          WHEN 'ephemeral' THEN
            new_scope_session_id = opengeni_private.current_memory_session_id()
            AND new_valid_until > transaction_timestamp()
          ELSE false
        END), false)
        THEN
          RAISE EXCEPTION 'new memory scope is not writable by this authority'
            USING ERRCODE = '42501';
        END IF;
        UPDATE knowledge_memories SET
          scope = new_scope_type,
          scope_type = new_scope_type,
          scope_subject_id = new_scope_subject_id,
          scope_role_key = new_scope_role_key,
          scope_session_id = new_scope_session_id,
          namespace_key = new_namespace,
          labels = new_labels,
          valid_until = CASE WHEN new_scope_type = 'ephemeral' THEN new_valid_until ELSE NULL END,
          updated_at = transaction_timestamp()
        WHERE id = target_id;
      ELSIF operation_type = 'archive' THEN
        IF target.status NOT IN ('proposed', 'approved', 'active') THEN
          RAISE EXCEPTION 'only a live memory may be archived' USING ERRCODE = '22023';
        END IF;
        UPDATE knowledge_memories SET
          status = 'archived',
          valid_until = coalesce(valid_until, transaction_timestamp()),
          updated_at = transaction_timestamp()
        WHERE id = target_id;
      ELSIF operation_type IN ('relationship_add', 'relationship_remove') THEN
        v_relationship_type := p_plan->>'relationshipType';
        IF v_relationship_type NOT IN (
          'derived_from', 'supersedes', 'corrects', 'conflicts_with',
          'related_to', 'depends_on', 'applies_to'
        ) THEN
          RAISE EXCEPTION 'memory relationship type is invalid' USING ERRCODE = '22023';
        END IF;
        IF v_relationship_type IN ('conflicts_with', 'related_to') AND related_id < target_id THEN
          RAISE EXCEPTION 'symmetric memory relationship endpoints are not canonical'
            USING ERRCODE = '22023';
        END IF;
        IF operation_type = 'relationship_add' THEN
          relationship_id := gen_random_uuid();
          INSERT INTO knowledge_memory_relationships (
            id, account_id, workspace_id, source_memory_id, target_memory_id,
            relationship_type, created_by_event_id
          ) VALUES (
            relationship_id, context_account_id, context_workspace_id, target_id, related_id,
            v_relationship_type, new_event_id
          );
          before_state := jsonb_build_object(
            'active', false, 'relationshipId', relationship_id,
            'targetMemoryVersion', target.memory_version,
            'relatedMemoryVersion', related.memory_version
          );
          after_state := jsonb_build_object(
            'active', true, 'relationshipId', relationship_id, 'relationshipVersion', 1,
            'targetMemoryVersion', target.memory_version,
            'relatedMemoryVersion', related.memory_version
          );
        ELSE
          SELECT * INTO relationship
          FROM knowledge_memory_relationships edge
          WHERE edge.workspace_id = context_workspace_id
            AND edge.source_memory_id = target_id
            AND edge.target_memory_id = related_id
            AND edge.relationship_type = v_relationship_type
            AND edge.removed_by_event_id IS NULL
          FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'active memory relationship was not found' USING ERRCODE = '02000';
          END IF;
          relationship_id := relationship.id;
          before_state := jsonb_build_object(
            'active', true, 'relationshipId', relationship.id,
            'relationshipVersion', relationship.version,
            'targetMemoryVersion', target.memory_version,
            'relatedMemoryVersion', related.memory_version
          );
          UPDATE knowledge_memory_relationships SET
            removed_by_event_id = new_event_id,
            removed_at = transaction_timestamp()
          WHERE id = relationship.id
          RETURNING * INTO relationship;
          after_state := jsonb_build_object(
            'active', false, 'relationshipId', relationship.id,
            'relationshipVersion', relationship.version,
            'targetMemoryVersion', target.memory_version,
            'relatedMemoryVersion', related.memory_version
          );
        END IF;
      ELSE
        v_relationship_type := CASE
          WHEN operation_type = 'correct' THEN 'corrects'
          ELSE 'supersedes'
        END;
        IF target.status NOT IN ('proposed', 'approved', 'active')
          OR related.status NOT IN ('approved', 'active')
        THEN
          RAISE EXCEPTION 'supersession requires a live source and visible replacement'
            USING ERRCODE = '22023';
        END IF;
        IF ROW(target.scope_type, target.scope_subject_id, target.scope_role_key, target.scope_session_id)
          IS DISTINCT FROM ROW(
            related.scope_type, related.scope_subject_id, related.scope_role_key, related.scope_session_id
          )
        THEN
          RAISE EXCEPTION 'supersession cannot widen or change memory scope'
            USING ERRCODE = '42501';
        END IF;
        before_state := jsonb_build_object(
          'target', before_state,
          'related', jsonb_build_object(
            'memoryVersion', related.memory_version,
            'status', related.status,
            'scopeType', related.scope_type,
            'scopeSubjectId', related.scope_subject_id,
            'scopeRoleKey', related.scope_role_key,
            'scopeSessionId', related.scope_session_id,
            'namespace', related.namespace_key,
            'labels', to_jsonb(related.labels),
            'validUntil', related.valid_until,
            'supersedesId', related.supersedes_id,
            'supersededById', related.superseded_by_id
          )
        );
        UPDATE knowledge_memories SET
          status = 'superseded',
          superseded_by_id = related_id,
          valid_until = coalesce(valid_until, transaction_timestamp()),
          updated_at = transaction_timestamp()
        WHERE id = target_id;
        UPDATE knowledge_memories SET
          supersedes_id = target_id,
          updated_at = transaction_timestamp()
        WHERE id = related_id;
        relationship_id := gen_random_uuid();
        INSERT INTO knowledge_memory_relationships (
          id, account_id, workspace_id, source_memory_id, target_memory_id,
          relationship_type, created_by_event_id
        ) VALUES (
          relationship_id, context_account_id, context_workspace_id, related_id, target_id,
          v_relationship_type, new_event_id
        );
      END IF;

      IF operation_type NOT IN ('relationship_add', 'relationship_remove') THEN
        SELECT * INTO target FROM knowledge_memories WHERE id = target_id;
        after_state := jsonb_build_object(
          'memoryVersion', target.memory_version,
          'status', target.status,
          'scopeType', target.scope_type,
          'scopeSubjectId', target.scope_subject_id,
          'scopeRoleKey', target.scope_role_key,
          'scopeSessionId', target.scope_session_id,
          'namespace', target.namespace_key,
          'labels', to_jsonb(target.labels),
          'validUntil', target.valid_until,
          'supersedesId', target.supersedes_id,
          'supersededById', target.superseded_by_id
        );
        IF operation_type IN ('supersede', 'correct') THEN
          SELECT * INTO related FROM knowledge_memories WHERE id = related_id;
          after_state := jsonb_build_object(
            'target', after_state,
            'related', jsonb_build_object(
              'memoryVersion', related.memory_version,
              'status', related.status,
              'scopeType', related.scope_type,
              'scopeSubjectId', related.scope_subject_id,
              'scopeRoleKey', related.scope_role_key,
              'scopeSessionId', related.scope_session_id,
              'namespace', related.namespace_key,
              'labels', to_jsonb(related.labels),
              'validUntil', related.valid_until,
              'supersedesId', related.supersedes_id,
              'supersededById', related.superseded_by_id
            ),
            'relationship', jsonb_build_object(
              'active', true, 'relationshipId', relationship_id, 'relationshipVersion', 1
            )
          );
          before_state := before_state || jsonb_build_object('relationship', NULL);
        END IF;
      END IF;

      INSERT INTO knowledge_memory_lifecycle_events (
        id, account_id, workspace_id, operation_id, action, operation_type,
        target_memory_id, related_memory_id, relationship_id, relationship_type,
        actor_kind, actor_subject_id, actor_session_id, actor_turn_id,
        actor_attempt_id, actor_execution_generation, plan_hash, before_state, after_state
      ) VALUES (
        new_event_id, context_account_id, context_workspace_id, v_operation_id, 'apply', operation_type,
        target_id, related_id, relationship_id, v_relationship_type,
        p_actor_kind, p_actor_subject_id, p_actor_session_id, p_actor_turn_id,
        p_actor_attempt_id, p_actor_execution_generation, p_plan_hash, before_state, after_state
      );

      PERFORM set_config('opengeni.memory_lifecycle_operation', '', true);
      RETURN QUERY SELECT new_event_id;
    END;
    $_$;

CREATE FUNCTION knowledge_memory_plan_hash(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT encode(sha256(convert_to(
        {{schema}}.knowledge_memory_stable_jsonb(p_value), 'UTF8'
      )), 'hex');
    $$;

CREATE FUNCTION knowledge_memory_revert_operation(p_operation_id uuid, p_applied_operation_id uuid, p_plan_hash text, p_actor_kind text, p_actor_subject_id text, p_actor_session_id uuid, p_actor_turn_id uuid, p_actor_attempt_id uuid, p_actor_execution_generation integer) RETURNS TABLE(event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $_$
    DECLARE
      context_account_id uuid := nullif(current_setting('opengeni.account_id', true), '')::uuid;
      context_workspace_id uuid := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
      applied record;
      existing_event record;
      target record;
      related record;
      relationship record;
      restored jsonb;
      revert_before jsonb;
      revert_after jsonb;
      new_event_id uuid := gen_random_uuid();
      authority_role_key text;
    BEGIN
      IF p_operation_id IS NULL OR p_applied_operation_id IS NULL
        OR p_plan_hash !~ '^[a-f0-9]{64}$'
        OR p_plan_hash IS DISTINCT FROM knowledge_memory_plan_hash(jsonb_build_object(
          'operationId', p_operation_id,
          'appliedOperationId', p_applied_operation_id
        ))
      THEN
        RAISE EXCEPTION 'memory revert plan or hash is invalid' USING ERRCODE = '22023';
      END IF;
      IF context_account_id IS NULL OR context_workspace_id IS NULL
        OR p_actor_kind NOT IN ('subject', 'service')
        OR length(btrim(p_actor_subject_id)) NOT BETWEEN 1 AND 1024
        OR opengeni_private.current_memory_actor_kind() IS DISTINCT FROM p_actor_kind
        OR opengeni_private.current_memory_actor_id() IS DISTINCT FROM p_actor_subject_id
        OR (p_actor_kind = 'subject'
          AND opengeni_private.current_subject_id() IS DISTINCT FROM p_actor_subject_id)
        OR (p_actor_kind = 'service' AND opengeni_private.current_subject_id() IS NOT NULL)
      THEN
        RAISE EXCEPTION 'memory revert requires exact transaction-local actor authority'
          USING ERRCODE = '42501';
      END IF;

      IF (p_actor_session_id IS NULL) <> (p_actor_turn_id IS NULL)
        OR (p_actor_session_id IS NULL) <> (p_actor_attempt_id IS NULL)
        OR (p_actor_session_id IS NULL) <> (p_actor_execution_generation IS NULL)
      THEN
        RAISE EXCEPTION 'memory revert attempt provenance is partial' USING ERRCODE = '22023';
      END IF;
      IF p_actor_session_id IS NOT NULL THEN
        SELECT session.metadata ->> 'memoryRoleKey' INTO authority_role_key
        FROM workspaces workspace
        JOIN sessions session
          ON session.account_id = workspace.account_id
         AND session.workspace_id = workspace.id
        JOIN session_turns turn
          ON turn.account_id = session.account_id
         AND turn.workspace_id = session.workspace_id
         AND turn.session_id = session.id
        JOIN session_turn_attempts attempt
          ON attempt.account_id = turn.account_id
         AND attempt.workspace_id = turn.workspace_id
         AND attempt.session_id = turn.session_id
         AND attempt.turn_id = turn.id
        WHERE workspace.account_id = context_account_id
          AND workspace.id = context_workspace_id
          AND session.id = p_actor_session_id
          AND session.active_turn_id = p_actor_turn_id
          AND turn.id = p_actor_turn_id
          AND turn.active_attempt_id = p_actor_attempt_id
          AND turn.execution_generation = p_actor_execution_generation
          AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
          AND turn.initiator_kind = p_actor_kind
          AND turn.initiator_subject_id = p_actor_subject_id
          AND attempt.id = p_actor_attempt_id
          AND attempt.execution_generation = p_actor_execution_generation
          AND attempt.state IN ('claimed', 'running')
          AND NOT EXISTS (
            SELECT 1 FROM session_attempt_interruptions interruption
            WHERE interruption.workspace_id = attempt.workspace_id
              AND interruption.attempt_id = attempt.id
              AND interruption.state IN ('pending', 'delivered', 'acknowledged')
          )
        FOR KEY SHARE OF workspace
        FOR SHARE OF session, turn
        FOR UPDATE OF attempt;
        IF NOT FOUND OR p_actor_execution_generation < 1 THEN
          RAISE EXCEPTION 'memory revert attempt authority is stale or invalid'
            USING ERRCODE = '42501';
        END IF;
        IF authority_role_key IS NOT NULL AND (
          authority_role_key IS DISTINCT FROM lower(btrim(authority_role_key))
          OR length(authority_role_key) NOT BETWEEN 1 AND 64
          OR authority_role_key !~ '^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$'
        ) THEN
          RAISE EXCEPTION 'persisted memory role authority is invalid' USING ERRCODE = '42501';
        END IF;
        IF opengeni_private.current_memory_session_id() IS DISTINCT FROM p_actor_session_id
          OR opengeni_private.current_memory_role_key() IS DISTINCT FROM authority_role_key
        THEN
          RAISE EXCEPTION 'memory revert session or role context is not exact'
            USING ERRCODE = '42501';
        END IF;
      ELSIF opengeni_private.current_memory_session_id() IS NOT NULL
        OR opengeni_private.current_memory_role_key() IS NOT NULL
      THEN
        RAISE EXCEPTION 'direct memory revert authority cannot carry session or role context'
          USING ERRCODE = '42501';
      END IF;

      SELECT event.* INTO existing_event
      FROM knowledge_memory_lifecycle_events event
      WHERE event.workspace_id = context_workspace_id
        AND event.operation_id = p_operation_id
        AND event.action = 'revert';
      IF FOUND THEN
        IF existing_event.plan_hash IS DISTINCT FROM p_plan_hash
          OR existing_event.actor_kind IS DISTINCT FROM p_actor_kind
          OR existing_event.actor_subject_id IS DISTINCT FROM p_actor_subject_id
          OR existing_event.actor_session_id IS DISTINCT FROM p_actor_session_id
          OR existing_event.actor_turn_id IS DISTINCT FROM p_actor_turn_id
          OR existing_event.actor_attempt_id IS DISTINCT FROM p_actor_attempt_id
          OR existing_event.actor_execution_generation
            IS DISTINCT FROM p_actor_execution_generation
          OR existing_event.reverts_event_id IS DISTINCT FROM (
            SELECT event.id FROM knowledge_memory_lifecycle_events event
            WHERE event.workspace_id = context_workspace_id
              AND event.operation_id = p_applied_operation_id
              AND event.action = 'apply'
          )
        THEN
          RAISE EXCEPTION 'memory revert id already identifies different immutable evidence'
            USING ERRCODE = '23505';
        END IF;
        RETURN QUERY SELECT existing_event.id;
        RETURN;
      END IF;

      SELECT event.* INTO applied
      FROM knowledge_memory_lifecycle_events event
      WHERE event.account_id = context_account_id
        AND event.workspace_id = context_workspace_id
        AND event.operation_id = p_applied_operation_id
        AND event.action = 'apply'
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'applied memory operation was not found' USING ERRCODE = '02000';
      END IF;
      IF applied.actor_kind IS DISTINCT FROM p_actor_kind
        OR applied.actor_subject_id IS DISTINCT FROM p_actor_subject_id
      THEN
        RAISE EXCEPTION 'memory revert requires the same immutable actor authority'
          USING ERRCODE = '42501';
      END IF;
      IF EXISTS (
        SELECT 1 FROM knowledge_memory_lifecycle_events event
        WHERE event.reverts_event_id = applied.id
      ) THEN
        RAISE EXCEPTION 'memory operation was already reverted' USING ERRCODE = '23505';
      END IF;

      SELECT * INTO target FROM knowledge_memories
      WHERE id = applied.target_memory_id
        AND account_id = context_account_id
        AND workspace_id = context_workspace_id;
      IF NOT FOUND OR NOT opengeni_private.memory_scope_authorized(
        target.scope_type, target.scope_subject_id, target.scope_role_key, target.scope_session_id
      ) THEN
        RAISE EXCEPTION 'reverted target memory is not authorized for this actor'
          USING ERRCODE = '42501';
      END IF;
      IF applied.related_memory_id IS NOT NULL THEN
        SELECT * INTO related FROM knowledge_memories
        WHERE id = applied.related_memory_id
          AND account_id = context_account_id
          AND workspace_id = context_workspace_id;
        IF NOT FOUND OR NOT opengeni_private.memory_scope_authorized(
          related.scope_type, related.scope_subject_id,
          related.scope_role_key, related.scope_session_id
        ) THEN
          RAISE EXCEPTION 'reverted related memory is not authorized for this actor'
            USING ERRCODE = '42501';
        END IF;
      END IF;

      PERFORM set_config('opengeni.memory_lifecycle_operation', '1', true);

      IF applied.operation_type IN ('reclassify', 'archive') THEN
        SELECT * INTO target FROM knowledge_memories
        WHERE id = applied.target_memory_id AND account_id = context_account_id
          AND workspace_id = context_workspace_id FOR UPDATE;
        IF target.memory_version <> (applied.after_state->>'memoryVersion')::integer THEN
          RAISE EXCEPTION 'memory changed after the applied operation' USING ERRCODE = '40001';
        END IF;
        revert_before := applied.after_state;
        restored := applied.before_state;
        UPDATE knowledge_memories SET
          status = restored->>'status',
          scope = restored->>'scopeType',
          scope_type = restored->>'scopeType',
          scope_subject_id = nullif(restored->>'scopeSubjectId', ''),
          scope_role_key = nullif(restored->>'scopeRoleKey', ''),
          scope_session_id = nullif(restored->>'scopeSessionId', '')::uuid,
          namespace_key = restored->>'namespace',
          labels = ARRAY(SELECT jsonb_array_elements_text(restored->'labels')),
          valid_until = nullif(restored->>'validUntil', '')::timestamptz,
          supersedes_id = nullif(restored->>'supersedesId', '')::uuid,
          superseded_by_id = nullif(restored->>'supersededById', '')::uuid,
          updated_at = transaction_timestamp()
        WHERE id = target.id
        RETURNING * INTO target;
        revert_after := jsonb_build_object(
          'memoryVersion', target.memory_version,
          'status', target.status,
          'scopeType', target.scope_type,
          'scopeSubjectId', target.scope_subject_id,
          'scopeRoleKey', target.scope_role_key,
          'scopeSessionId', target.scope_session_id,
          'namespace', target.namespace_key,
          'labels', to_jsonb(target.labels),
          'validUntil', target.valid_until,
          'supersedesId', target.supersedes_id,
          'supersededById', target.superseded_by_id
        );
      ELSIF applied.operation_type IN ('relationship_add', 'relationship_remove') THEN
        PERFORM 1 FROM knowledge_memories candidate
        WHERE candidate.id IN (applied.target_memory_id, applied.related_memory_id)
          AND candidate.account_id = context_account_id
          AND candidate.workspace_id = context_workspace_id
        ORDER BY candidate.id FOR UPDATE;
        SELECT * INTO target FROM knowledge_memories
        WHERE id = applied.target_memory_id
          AND account_id = context_account_id
          AND workspace_id = context_workspace_id;
        SELECT * INTO related FROM knowledge_memories
        WHERE id = applied.related_memory_id
          AND account_id = context_account_id
          AND workspace_id = context_workspace_id;
        IF target.memory_version <>
            (applied.after_state->>'targetMemoryVersion')::integer
          OR related.memory_version <>
            (applied.after_state->>'relatedMemoryVersion')::integer
        THEN
          RAISE EXCEPTION 'relationship endpoints changed after apply'
            USING ERRCODE = '40001';
        END IF;
        SELECT * INTO relationship FROM knowledge_memory_relationships
        WHERE id = applied.relationship_id AND workspace_id = context_workspace_id FOR UPDATE;
        revert_before := jsonb_build_object(
          'active', relationship.removed_by_event_id IS NULL,
          'relationshipId', relationship.id,
          'relationshipVersion', relationship.version,
          'targetMemoryVersion', target.memory_version,
          'relatedMemoryVersion', related.memory_version
        );
        IF applied.operation_type = 'relationship_add' THEN
          IF relationship.created_by_event_id <> applied.id
            OR relationship.removed_by_event_id IS NOT NULL
            OR relationship.version <> (applied.after_state->>'relationshipVersion')::integer
          THEN
            RAISE EXCEPTION 'relationship add can no longer be reverted' USING ERRCODE = '40001';
          END IF;
          UPDATE knowledge_memory_relationships SET
            removed_by_event_id = new_event_id,
            removed_at = transaction_timestamp()
          WHERE id = relationship.id RETURNING * INTO relationship;
        ELSE
          IF relationship.removed_by_event_id <> applied.id
            OR relationship.version <> (applied.after_state->>'relationshipVersion')::integer
          THEN
            RAISE EXCEPTION 'relationship removal can no longer be reverted' USING ERRCODE = '40001';
          END IF;
          UPDATE knowledge_memory_relationships SET
            removed_by_event_id = NULL,
            removed_at = NULL
          WHERE id = relationship.id RETURNING * INTO relationship;
        END IF;
        revert_after := jsonb_build_object(
          'active', relationship.removed_by_event_id IS NULL,
          'relationshipId', relationship.id,
          'relationshipVersion', relationship.version,
          'targetMemoryVersion', target.memory_version,
          'relatedMemoryVersion', related.memory_version
        );
      ELSE
        PERFORM 1 FROM knowledge_memories candidate
        WHERE candidate.id IN (applied.target_memory_id, applied.related_memory_id)
          AND candidate.account_id = context_account_id
          AND candidate.workspace_id = context_workspace_id
        ORDER BY candidate.id FOR UPDATE;
        SELECT * INTO target FROM knowledge_memories WHERE id = applied.target_memory_id;
        SELECT * INTO related FROM knowledge_memories WHERE id = applied.related_memory_id;
        IF target.memory_version <> (applied.after_state#>>'{target,memoryVersion}')::integer
          OR related.memory_version <> (applied.after_state#>>'{related,memoryVersion}')::integer
        THEN
          RAISE EXCEPTION 'supersession participants changed after apply' USING ERRCODE = '40001';
        END IF;
        revert_before := applied.after_state;
        restored := applied.before_state->'target';
        UPDATE knowledge_memories SET
          status = restored->>'status',
          valid_until = nullif(restored->>'validUntil', '')::timestamptz,
          supersedes_id = nullif(restored->>'supersedesId', '')::uuid,
          superseded_by_id = nullif(restored->>'supersededById', '')::uuid,
          updated_at = transaction_timestamp()
        WHERE id = target.id RETURNING * INTO target;
        restored := applied.before_state->'related';
        UPDATE knowledge_memories SET
          status = restored->>'status',
          valid_until = nullif(restored->>'validUntil', '')::timestamptz,
          supersedes_id = nullif(restored->>'supersedesId', '')::uuid,
          superseded_by_id = nullif(restored->>'supersededById', '')::uuid,
          updated_at = transaction_timestamp()
        WHERE id = related.id RETURNING * INTO related;
        SELECT * INTO relationship FROM knowledge_memory_relationships
        WHERE id = applied.relationship_id AND removed_by_event_id IS NULL FOR UPDATE;
        IF NOT FOUND OR relationship.version <>
          (applied.after_state#>>'{relationship,relationshipVersion}')::integer
        THEN
          RAISE EXCEPTION 'supersession relationship changed after apply' USING ERRCODE = '40001';
        END IF;
        UPDATE knowledge_memory_relationships SET
          removed_by_event_id = new_event_id,
          removed_at = transaction_timestamp()
        WHERE id = relationship.id RETURNING * INTO relationship;
        revert_after := jsonb_build_object(
          'target', jsonb_build_object(
            'memoryVersion', target.memory_version, 'status', target.status,
            'scopeType', target.scope_type, 'scopeSubjectId', target.scope_subject_id,
            'scopeRoleKey', target.scope_role_key, 'scopeSessionId', target.scope_session_id,
            'namespace', target.namespace_key, 'labels', to_jsonb(target.labels),
            'validUntil', target.valid_until, 'supersedesId', target.supersedes_id,
            'supersededById', target.superseded_by_id
          ),
          'related', jsonb_build_object(
            'memoryVersion', related.memory_version, 'status', related.status,
            'scopeType', related.scope_type, 'scopeSubjectId', related.scope_subject_id,
            'scopeRoleKey', related.scope_role_key, 'scopeSessionId', related.scope_session_id,
            'namespace', related.namespace_key, 'labels', to_jsonb(related.labels),
            'validUntil', related.valid_until, 'supersedesId', related.supersedes_id,
            'supersededById', related.superseded_by_id
          ),
          'relationship', jsonb_build_object(
            'active', false, 'relationshipId', relationship.id,
            'relationshipVersion', relationship.version
          )
        );
      END IF;

      INSERT INTO knowledge_memory_lifecycle_events (
        id, account_id, workspace_id, operation_id, action, operation_type,
        target_memory_id, related_memory_id, relationship_id, relationship_type,
        actor_kind, actor_subject_id, actor_session_id, actor_turn_id,
        actor_attempt_id, actor_execution_generation, plan_hash,
        before_state, after_state, reverts_event_id
      ) VALUES (
        new_event_id, context_account_id, context_workspace_id, p_operation_id, 'revert',
        applied.operation_type, applied.target_memory_id, applied.related_memory_id,
        applied.relationship_id, applied.relationship_type, p_actor_kind, p_actor_subject_id,
        p_actor_session_id, p_actor_turn_id, p_actor_attempt_id,
        p_actor_execution_generation, p_plan_hash, revert_before, revert_after, applied.id
      );
      PERFORM set_config('opengeni.memory_lifecycle_operation', '', true);
      RETURN QUERY SELECT new_event_id;
    END;
    $_$;

CREATE FUNCTION knowledge_memory_stable_jsonb(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE rendered text;
    BEGIN
      CASE jsonb_typeof(p_value)
        WHEN 'object' THEN
          SELECT '{' || coalesce(string_agg(
            to_jsonb(entry.key)::text || ':' || {{schema}}.knowledge_memory_stable_jsonb(entry.value),
            ',' ORDER BY entry.key COLLATE "C"
          ), '') || '}'
          INTO rendered
          FROM jsonb_each(p_value) AS entry;
        WHEN 'array' THEN
          SELECT '[' || coalesce(string_agg(
            {{schema}}.knowledge_memory_stable_jsonb(entry.value),
            ',' ORDER BY entry.ordinality
          ), '') || ']'
          INTO rendered
          FROM jsonb_array_elements(p_value) WITH ORDINALITY AS entry(value, ordinality);
        ELSE
          rendered := p_value::text;
      END CASE;
      RETURN rendered;
    END;
    $$;

CREATE FUNCTION knowledge_query_billing_receipt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF OLD.source_resource_type='knowledge_query'
    AND OLD.event_type='document.query_embedding_cost'
    AND OLD.initiator_context ? 'creditDebitAttribution'
    AND (NEW.account_id IS DISTINCT FROM OLD.account_id
      OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
      OR NEW.source_resource_type IS DISTINCT FROM OLD.source_resource_type
      OR NEW.source_resource_id IS DISTINCT FROM OLD.source_resource_id
      OR NEW.event_type IS DISTINCT FROM OLD.event_type
      OR NEW.quantity IS DISTINCT FROM OLD.quantity
      OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
      OR NEW.initiator_context->'creditDebitAttribution' IS DISTINCT FROM
        OLD.initiator_context->'creditDebitAttribution') THEN
    RAISE EXCEPTION 'Knowledge query billing receipt is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION knowledge_reject_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' AND pg_trigger_depth()>1 THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Knowledge history is immutable' USING ERRCODE='55000';
END $$;

CREATE FUNCTION knowledge_resolve_actor(p_account uuid, p_workspace uuid, p_actor jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE prepared knowledge_entries%ROWTYPE; s sessions%ROWTYPE; t session_turns%ROWTYPE; a session_turn_attempts%ROWTYPE;
  subject text; destination text; policy jsonb; run scheduled_task_runs%ROWTYPE;
  context_key text; resolved_actor jsonb;
BEGIN
  IF p_account IS DISTINCT FROM nullif(current_setting('opengeni.account_id',true),'')::uuid
    OR p_workspace IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Knowledge requires exact workspace authority' USING ERRCODE='42501';
  END IF;
  PERFORM 1 FROM workspaces WHERE id=p_workspace AND account_id=p_account FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Knowledge workspace unavailable' USING ERRCODE='42501'; END IF;
  IF p_actor->>'kind'='source_preparation' THEN
    SELECT * INTO prepared FROM knowledge_entries e WHERE e.account_id=p_account
      AND e.id=(p_actor->>'entryId')::uuid AND e.origin_workspace_id=p_workspace FOR SHARE;
    IF NOT FOUND OR prepared.legacy_document_id IS NULL
      OR prepared.document_preparation ? 'completion'
      OR prepared.document_preparation->>'leaseId' IS DISTINCT FROM p_actor->>'leaseId'
      OR (prepared.document_preparation->>'leaseUntil')::timestamptz<=clock_timestamp() THEN
      RAISE EXCEPTION 'Document preparation lease unavailable' USING ERRCODE='42501'; END IF;
    PERFORM set_config('opengeni.subject_id',coalesce(prepared.scope_subject_id,''),true);
    PERFORM set_config('opengeni.private_file_owner',coalesce(prepared.scope_subject_id,''),true);
    PERFORM set_config('opengeni.knowledge_default_scope',prepared.scope,true);
    PERFORM set_config('opengeni.knowledge_actor_kind','source_preparation',true);
    PERFORM set_config('opengeni.knowledge_prepared_document',prepared.legacy_document_id::text,true);
    RETURN jsonb_build_object('kind','source_preparation','entryId',prepared.id,'defaultScope',prepared.scope,
      'subjectId',prepared.scope_subject_id,'review',false,'policy',prepared.document_preparation->'policy',
      'scheduledTaskRunId',prepared.document_preparation->'scheduledTaskRunId');
  END IF;
  IF p_actor->>'kind'='service' THEN
    IF p_actor->>'principalKind' NOT IN ('service','api_key','configured_key','mcp_gateway')
      OR p_actor->>'principalKind' IS DISTINCT FROM nullif(current_setting('opengeni.principal_kind',true),'')
      OR p_actor->>'subjectId' IS DISTINCT FROM nullif(current_setting('opengeni.subject_id',true),'') THEN
      RAISE EXCEPTION 'Knowledge service authority unavailable' USING ERRCODE='42501'; END IF;
    PERFORM set_config('opengeni.subject_id','',true);
    PERFORM set_config('opengeni.knowledge_actor_kind','service',true);
    PERFORM set_config('opengeni.private_file_owner','',true);
    RETURN jsonb_build_object('kind','service','defaultScope','workspace','review',false,
      'writeScopes',CASE WHEN p_actor->>'principalKind'='mcp_gateway' THEN '[]'::jsonb
        ELSE coalesce(p_actor->'writeScopes','[]'::jsonb)-'personal' END);
  END IF;
  IF p_actor->>'kind'='human' THEN
    subject:=p_actor->>'subjectId';
    IF subject IS NULL OR length(subject) NOT BETWEEN 1 AND 1024
      OR subject IS DISTINCT FROM nullif(current_setting('opengeni.subject_id',true),'')
      OR p_actor->>'principalKind' IS DISTINCT FROM 'human_session'
      OR nullif(current_setting('opengeni.principal_kind',true),'') IS DISTINCT FROM 'human_session' THEN
      RAISE EXCEPTION 'Knowledge human authority unavailable' USING ERRCODE='42501';
    END IF;
    PERFORM set_config('opengeni.knowledge_actor_kind','human',true);
    PERFORM set_config('opengeni.private_file_owner',subject,true);
    RETURN jsonb_build_object('kind','human','subjectId',subject,'defaultScope','workspace',
      'writeScopes',coalesce(p_actor->'writeScopes','[]'::jsonb),'review',coalesce((p_actor->>'review')::boolean,false));
  END IF;
  IF p_actor->>'kind' IS DISTINCT FROM 'agent' THEN
    RAISE EXCEPTION 'Knowledge requires a human or exact agent attempt' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM sessions WHERE id=(p_actor->>'sessionId')::uuid
    AND workspace_id=p_workspace AND account_id=p_account FOR SHARE;
  IF NOT FOUND OR s.active_turn_id IS DISTINCT FROM (p_actor->>'turnId')::uuid THEN
    RAISE EXCEPTION 'Knowledge session attempt is stale' USING ERRCODE='42501';
  END IF;
  SELECT * INTO t FROM session_turns WHERE id=s.active_turn_id AND session_id=s.id
    AND workspace_id=p_workspace AND account_id=p_account FOR SHARE;
  IF NOT FOUND OR t.active_attempt_id IS DISTINCT FROM (p_actor->>'attemptId')::uuid
    OR t.execution_generation IS DISTINCT FROM (p_actor->>'executionGeneration')::integer
    OR t.status NOT IN ('running','requires_action','recovering','waiting_capacity') THEN
    RAISE EXCEPTION 'Knowledge turn attempt is stale' USING ERRCODE='42501';
  END IF;
  SELECT * INTO a FROM session_turn_attempts WHERE id=t.active_attempt_id AND turn_id=t.id
    AND session_id=s.id AND account_id=p_account AND workspace_id=p_workspace FOR SHARE;
  IF NOT FOUND OR a.state NOT IN ('claimed','running') OR a.execution_generation<>t.execution_generation THEN
    RAISE EXCEPTION 'Knowledge attempt is stale' USING ERRCODE='42501';
  END IF;
  -- Fresh read after locks: interruption writers acquire the attempt FOR UPDATE.
  IF EXISTS(SELECT 1 FROM session_attempt_interruptions WHERE workspace_id=p_workspace
    AND attempt_id=a.id AND state IN ('pending','delivered','acknowledged')) THEN
    RAISE EXCEPTION 'Knowledge attempt is interrupted' USING ERRCODE='42501';
  END IF;
  subject:=coalesce(t.initiating_human_subject_id,CASE WHEN t.initiator_kind='subject' THEN t.initiator_subject_id END);
  -- The accepted initiating-human field is authority; subject spelling is not.
  -- Opaque authenticated host/local subjects retain the same personal layer.
  destination:=CASE WHEN s.visibility='user_private' OR s.memory_scope='user'
    OR (subject IS NOT NULL AND get_workspace_kind(p_account,p_workspace)='personal')
    THEN 'personal' ELSE 'workspace' END;
  IF destination='personal' AND (subject IS NULL
    OR (s.visibility='user_private' AND s.owner_subject_id IS DISTINCT FROM subject)) THEN
    RAISE EXCEPTION 'Personal Knowledge requires the verified initiating owner' USING ERRCODE='42501';
  END IF;
  -- Keep the verified subject for provider ACL checks. The independent Knowledge
  -- scope selector prevents a shared agent from ambient-reading personal entries.
  PERFORM set_config('opengeni.subject_id',coalesce(subject,''),true);
  PERFORM set_config('opengeni.knowledge_default_scope',destination,true);
  PERFORM set_config('opengeni.knowledge_actor_kind','agent',true);
  PERFORM set_config('opengeni.private_file_owner',CASE WHEN destination='personal' THEN coalesce(subject,'') ELSE '' END,true);
  PERFORM set_config('opengeni.knowledge_session_id',s.id::text,true);
  PERFORM set_config('opengeni.knowledge_attempt_id',a.id::text,true);
  PERFORM set_config('opengeni.memory_session_id',s.id::text,true);
  PERFORM set_config('opengeni.memory_role_key',coalesce(s.metadata->>'memoryRoleKey',''),true);
  policy:=knowledge_learning_for_turn(p_account,p_workspace,t.id);
  -- Only the same accepted human can retain Personal authority after sharing.
  -- The exact live attempt and interruption fences above still apply. Never
  -- rewrite the snapshot, widen Personal writes, or adopt another human's scope.
  IF destination='workspace' AND s.visibility='workspace_shared'
    AND policy->>'defaultScope'='personal' AND subject IS NOT NULL
    AND policy->>'subjectId'=subject THEN
    destination:='personal';
    PERFORM set_config('opengeni.knowledge_default_scope',destination,true);
    PERFORM set_config('opengeni.private_file_owner',subject,true);
  END IF;
  IF policy->>'defaultScope' IS DISTINCT FROM destination OR (destination='personal' AND policy->>'subjectId' IS DISTINCT FROM subject) THEN
    RAISE EXCEPTION 'Learning scope changed after acceptance' USING ERRCODE='42501';
  END IF;
  resolved_actor:=jsonb_build_object('kind','agent','subjectId',subject,'defaultScope',destination,
    'sessionId',s.id,'turnId',t.id,'attemptId',a.id,'executionGeneration',a.execution_generation,
    'scheduledTaskRunId',policy->'scheduledTaskRunId','retentionScope',CASE WHEN s.memory_scope='session' THEN 'session' ELSE 'normal' END,'policy',policy);
  RETURN resolved_actor;
END $$;

CREATE FUNCTION knowledge_retired_learning_read_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' AND pg_trigger_depth()>1 AND (
    NOT EXISTS(SELECT 1 FROM workspaces WHERE id=OLD.workspace_id AND account_id=OLD.account_id)
    OR NOT EXISTS(SELECT 1 FROM managed_accounts WHERE id=OLD.account_id)) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Learning settings moved to Agent learning' USING ERRCODE='55000';
END $$;

CREATE FUNCTION knowledge_retired_memory_read_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' AND pg_trigger_depth()>1 AND (
    NOT EXISTS(SELECT 1 FROM workspaces WHERE id=OLD.workspace_id AND account_id=OLD.account_id)
    OR NOT EXISTS(SELECT 1 FROM managed_accounts WHERE id=OLD.account_id)) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'Memory was replaced by Knowledge; historical Memory is read-only' USING ERRCODE='55000';
END $$;

CREATE FUNCTION knowledge_review_batch_for_actor(p_account uuid, p_workspace uuid, p_actor jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE batch uuid; owner text:=CASE WHEN p_actor->>'defaultScope'='personal'
  THEN 'personal:'||(p_actor->>'subjectId') ELSE 'workspace:'||p_workspace END;
BEGIN
  SELECT b.id INTO batch FROM knowledge_review_batches b WHERE b.account_id=p_account AND b.owner_key=owner
    AND ((p_actor->>'scheduledTaskRunId' IS NOT NULL AND b.scheduled_task_run_id=(p_actor->>'scheduledTaskRunId')::uuid)
      OR (p_actor->>'scheduledTaskRunId' IS NULL AND b.turn_id=(p_actor->>'turnId')::uuid));
  IF batch IS NULL THEN
    INSERT INTO knowledge_review_batches(account_id,origin_workspace_id,owner_key,session_id,turn_id,scheduled_task_run_id)
      VALUES(p_account,p_workspace,owner,(p_actor->>'sessionId')::uuid,(p_actor->>'turnId')::uuid,
        (p_actor->>'scheduledTaskRunId')::uuid) RETURNING id INTO batch;
  END IF;
  RETURN batch;
END $$;

CREATE FUNCTION knowledge_revision_visible(p_account uuid, p_entry uuid, p_revision uuid, p_pending boolean) RETURNS boolean
    LANGUAGE sql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS(SELECT 1 FROM knowledge_revisions_visible(
    p_account,ARRAY[p_entry],ARRAY[p_revision],p_pending))
$$;

CREATE FUNCTION knowledge_revisions_visible(p_account uuid, p_entries uuid[], p_revisions uuid[], p_pending boolean) RETURNS TABLE(entry_id uuid, revision_id uuid)
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    SET plan_cache_mode TO 'force_generic_plan'
    AS $$
BEGIN
RETURN QUERY

  WITH RECURSIVE roots AS MATERIALIZED (
    SELECT DISTINCT x.entry_id,x.revision_id
    FROM unnest(p_entries,p_revisions) AS x(entry_id,revision_id)
  ), dependencies(root_entry_id,root_revision_id,entry_id,revision_id) AS (
    SELECT r.entry_id,r.revision_id,r.entry_id,r.revision_id FROM roots r
    UNION
    SELECT d.root_entry_id,d.root_revision_id,l.target_entry_id,l.target_revision_id
    FROM dependencies d
    CROSS JOIN LATERAL (
      SELECT l.target_entry_id,l.target_revision_id FROM knowledge_entry_links l
      WHERE l.account_id=p_account AND l.entry_id=d.entry_id
        AND l.revision_id=d.revision_id AND l.relation='evidence' OFFSET 0
    ) l
  ), identities AS MATERIALIZED (
    SELECT DISTINCT d.entry_id,d.revision_id FROM dependencies d
  ), visibility AS MATERIALIZED (
    SELECT d.entry_id,d.revision_id,e.archived,
      e.id IS NOT NULL AND knowledge_scope_visible(e::knowledge_entries)
        AND (p_pending OR EXISTS(SELECT 1 FROM knowledge_entry_decisions v
          WHERE v.account_id=p_account AND v.entry_id=d.entry_id
            AND v.revision_id=d.revision_id AND v.outcome='published' OFFSET 0))
        AND (e.legacy_document_version_id IS NULL OR knowledge_legacy_version_visible(p_account,e.legacy_document_version_id))
        AND (e.legacy_document_id IS NULL OR knowledge_document_visible(e.legacy_document_id))
        AND (e.access_document_id IS NULL OR knowledge_document_visible(e.access_document_id))
        AND (e.access_file_id IS NULL OR google_drive_file_authorized(p_account,
          nullif(current_setting('opengeni.workspace_id',true),'')::uuid,
          nullif(current_setting('opengeni.subject_id',true),''),e.access_file_id))
        AND r.id IS NOT NULL AND knowledge_source_visible(p_account,r.body) AS visible
    FROM identities d
    LEFT JOIN LATERAL (SELECT e.* FROM knowledge_entries e
      WHERE e.account_id=p_account AND e.id=d.entry_id OFFSET 0) e ON true
    LEFT JOIN LATERAL (SELECT r.* FROM knowledge_entry_revisions r
      WHERE r.account_id=p_account AND r.entry_id=d.entry_id AND r.id=d.revision_id OFFSET 0) r ON true
  ), root_visibility AS MATERIALIZED (
    SELECT d.root_entry_id,d.root_revision_id,
      bool_or(NOT v.visible OR (v.archived AND d.entry_id<>d.root_entry_id)) AS denied
    FROM dependencies d JOIN visibility v USING(entry_id,revision_id)
    GROUP BY d.root_entry_id,d.root_revision_id
  )
  SELECT root.entry_id,root.revision_id FROM roots root
  JOIN root_visibility checked ON checked.root_entry_id=root.entry_id
    AND checked.root_revision_id=root.revision_id
  WHERE EXISTS(SELECT 1 FROM knowledge_entry_revisions r WHERE r.account_id=p_account
    AND r.entry_id=root.entry_id AND r.id=root.revision_id)
    AND checked.denied IS NOT TRUE;
END;
$$;

CREATE TABLE knowledge_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    origin_workspace_id uuid NOT NULL,
    scope text NOT NULL,
    scope_workspace_id uuid,
    scope_subject_id text,
    version integer DEFAULT 0 NOT NULL,
    published_revision_id uuid,
    latest_revision_id uuid,
    archived boolean DEFAULT false NOT NULL,
    legacy_memory_id uuid,
    legacy_document_id uuid,
    legacy_claim_id uuid,
    prepared_file_id uuid,
    document_preparation jsonb,
    legacy_document_version_id uuid,
    legacy_scope_workspace_id uuid,
    access_document_id uuid,
    access_file_id uuid,
    legacy_scope_type text,
    legacy_scope_role_key text,
    legacy_scope_session_id uuid,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT knowledge_entries_check CHECK ((((scope = 'organization'::text) AND (scope_workspace_id IS NULL) AND (scope_subject_id IS NULL)) OR ((scope = 'workspace'::text) AND (scope_workspace_id IS NOT NULL) AND (scope_subject_id IS NULL)) OR ((scope = 'personal'::text) AND (scope_workspace_id IS NULL) AND ((length(scope_subject_id) >= 1) AND (length(scope_subject_id) <= 1024))))),
    CONSTRAINT knowledge_entries_scope_check CHECK ((scope = ANY (ARRAY['organization'::text, 'workspace'::text, 'personal'::text]))),
    CONSTRAINT knowledge_entries_version_check CHECK ((version >= 0))
);

ALTER TABLE ONLY knowledge_entries FORCE ROW LEVEL SECURITY;

CREATE FUNCTION knowledge_scope_visible(e knowledge_entries) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  RETURN coalesce(e.account_id=nullif(current_setting('opengeni.account_id',true),'')::uuid
    AND (e.scope='organization'
      OR (e.scope='workspace' AND e.scope_workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid)
      OR (e.scope='personal' AND e.scope_subject_id=nullif(current_setting('opengeni.subject_id',true),'')
        AND (current_setting('opengeni.knowledge_actor_kind',true)='human'
          OR current_setting('opengeni.knowledge_default_scope',true)='personal')))
    AND (e.legacy_scope_workspace_id IS NULL OR e.legacy_scope_workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid)
    AND e.valid_from<=transaction_timestamp() AND (e.valid_until IS NULL OR e.valid_until>transaction_timestamp())
    AND (e.legacy_memory_id IS NULL OR e.origin_workspace_id=nullif(current_setting('opengeni.workspace_id',true),'')::uuid)
    AND (e.legacy_scope_type IS NULL OR opengeni_private.memory_scope_visible(
      e.legacy_scope_type,e.scope_subject_id,e.legacy_scope_role_key,e.legacy_scope_session_id,e.valid_from,e.valid_until)),false);
END
$$;

CREATE FUNCTION knowledge_source_index_wake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF NEW.status='indexed' AND NEW.acl_eligibility='eligible' THEN
    UPDATE knowledge_index_jobs j SET next_attempt_at=clock_timestamp()
      FROM knowledge_entries e WHERE e.account_id=NEW.account_id AND j.account_id=e.account_id
        AND j.entry_id=e.id AND j.state='pending'
        AND (e.legacy_document_id=NEW.document_id OR e.legacy_document_version_id=NEW.knowledge_document_version_id);
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION knowledge_source_sync_lock_authority(p_account_id uuid, p_source_id uuid, p_object_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE object_found boolean := false;
    DECLARE source_found boolean := false;
    BEGIN
      IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
        RAISE EXCEPTION 'knowledge source sync account authority is invalid'
          USING ERRCODE = '42501';
      END IF;
      IF p_object_id IS NOT NULL THEN
        SELECT true INTO object_found
        FROM knowledge_source_objects object_row
        WHERE object_row.account_id = p_account_id
          AND object_row.id = p_object_id
          AND object_row.source_id = p_source_id
          AND opengeni_private.scoped_knowledge_scope_visible(
            object_row.account_id,
            object_row.scope_kind,
            object_row.scope_workspace_id,
            object_row.scope_subject_id
          )
        FOR UPDATE;
        IF NOT coalesce(object_found, false) THEN
          RAISE EXCEPTION 'knowledge source sync object authority was not found'
            USING ERRCODE = 'P0002';
        END IF;
      END IF;
      SELECT true INTO source_found
      FROM knowledge_sources source_row
      WHERE source_row.account_id = p_account_id
        AND source_row.id = p_source_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          source_row.account_id,
          source_row.scope_kind,
          source_row.scope_workspace_id,
          source_row.scope_subject_id
        )
      FOR UPDATE;
      IF NOT coalesce(source_found, false) THEN
        RAISE EXCEPTION 'knowledge source sync source authority was not found'
          USING ERRCODE = 'P0002';
      END IF;
    END;
    $$;

CREATE FUNCTION knowledge_source_visible(p_account uuid, p_body jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
<<knowledge_source_visible>>
DECLARE document_id uuid:=(p_body#>>'{source,documentId}')::uuid;
  file_id uuid:=(p_body#>>'{source,fileId}')::uuid;
BEGIN
  IF document_id IS NOT NULL THEN
    RETURN knowledge_document_visible(document_id) AND (file_id IS NULL OR EXISTS(
      SELECT 1 FROM documents d WHERE d.account_id=p_account AND d.id=document_id AND d.file_id=knowledge_source_visible.file_id));
  END IF;
  IF file_id IS NOT NULL THEN
    RETURN EXISTS(SELECT 1 FROM files f WHERE f.account_id=p_account AND f.id=knowledge_source_visible.file_id
      AND f.status='ready') AND google_drive_file_authorized(p_account,nullif(current_setting('opengeni.workspace_id',true),'')::uuid,
      nullif(current_setting('opengeni.subject_id',true),''),file_id);
  END IF;
  RETURN true;
END $$;

CREATE FUNCTION knowledge_task_note_source(p_account uuid, p_workspace uuid, p_actor jsonb, p_note uuid, p_version integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE authority record; note task_notes%ROWTYPE; capability uuid:=gen_random_uuid();
  previous text:=current_setting('opengeni.task_note_write_capability',true);
BEGIN
  IF p_actor->>'kind'<>'agent' OR p_version IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'Task-note promotion requires an exact agent and note version' USING ERRCODE='42501'; END IF;
  SELECT * INTO STRICT authority FROM resolve_task_note_attempt_authority(p_account,p_workspace,
    (p_actor->>'sessionId')::uuid,(p_actor->>'turnId')::uuid,(p_actor->>'attemptId')::uuid,(p_actor->>'executionGeneration')::integer);
  INSERT INTO task_note_write_capabilities(backend_pid,transaction_id,capability_id)
    VALUES(pg_backend_pid(),pg_current_xact_id(),capability);
  PERFORM set_config('opengeni.task_note_write_capability',capability::text,true);
  SELECT * INTO note FROM task_notes n WHERE n.account_id=p_account AND n.workspace_id=p_workspace
    AND n.root_session_id=authority.root_session_id AND n.id=p_note AND n.version=p_version
    AND n.status='active' AND n.expires_at>statement_timestamp() FOR SHARE;
  DELETE FROM task_note_write_capabilities c WHERE c.backend_pid=pg_backend_pid() AND c.transaction_id=pg_current_xact_id()
    AND c.capability_id=capability;
  PERFORM set_config('opengeni.task_note_write_capability',coalesce(previous,''),true);
  IF note.id IS NULL THEN RAISE EXCEPTION 'Task note is expired, archived or outside this task tree' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('content',note.text,'source',jsonb_build_object('kind','task_note','noteId',note.id,
    'sessionId',note.created_by_session_id,'version',note.version::text));
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.task_note_write_capability',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION knowledge_validate_links(p_account uuid, p_entry uuid, p_body jsonb, p_batch uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE source knowledge_entries%ROWTYPE; target knowledge_entries%ROWTYPE; link record; target_revision uuid;
BEGIN
  SELECT * INTO source FROM knowledge_entries WHERE account_id=p_account AND id=p_entry;
  FOR link IN
    SELECT (x->>'entryId')::uuid AS id,(x->>'revisionId')::uuid AS revision,'evidence' AS relation
      FROM jsonb_array_elements(coalesce(p_body->'evidence','[]'::jsonb)) x
    UNION ALL SELECT x::uuid,NULL,'group' FROM jsonb_array_elements_text(coalesce(p_body->'groupIds','[]'::jsonb)) x
    UNION ALL SELECT (x->>'entryId')::uuid,NULL,x->>'relation'
      FROM jsonb_array_elements(coalesce(p_body->'relationships','[]'::jsonb)) x
    ORDER BY id,relation
  LOOP
    SELECT * INTO target FROM knowledge_entries WHERE account_id=p_account AND id=link.id;
    IF NOT FOUND OR target.id=source.id OR target.archived OR NOT knowledge_scope_visible(target) THEN
      RAISE EXCEPTION 'Knowledge reference unavailable' USING ERRCODE='42501';
    END IF;
    -- The destination's readers must all be eligible to see linked identities.
    IF NOT ((target.scope='organization')
      OR (target.scope='workspace' AND source.scope IN ('workspace','personal')
        AND target.scope_workspace_id=source.origin_workspace_id)
      OR (target.scope='personal' AND source.scope='personal' AND target.scope_subject_id=source.scope_subject_id))
      OR (target.legacy_scope_type IS NOT NULL AND (source.legacy_scope_type IS DISTINCT FROM target.legacy_scope_type
        OR source.legacy_scope_role_key IS DISTINCT FROM target.legacy_scope_role_key
        OR source.legacy_scope_session_id IS DISTINCT FROM target.legacy_scope_session_id)) THEN
      RAISE EXCEPTION 'Knowledge reference would widen source access' USING ERRCODE='42501';
    END IF;
    target_revision:=coalesce(link.revision,target.published_revision_id);
    IF target_revision IS NULL AND p_batch IS NOT NULL THEN
      SELECT id INTO target_revision FROM knowledge_entry_revisions r WHERE r.account_id=p_account
        AND r.entry_id=target.id AND r.id=target.latest_revision_id;
    END IF;
    IF NOT knowledge_revision_visible(p_account,target.id,target_revision,false) AND NOT (
      p_batch IS NOT NULL AND target_revision=target.latest_revision_id
      AND EXISTS(SELECT 1 FROM knowledge_entry_revisions r WHERE r.account_id=p_account
        AND r.entry_id=target.id AND r.id=target_revision)
      AND EXISTS(SELECT 1 FROM knowledge_entry_decisions d WHERE d.account_id=p_account
        AND d.entry_id=target.id AND d.revision_id=target_revision AND d.version=target.version AND d.outcome='pending')
      AND knowledge_revision_visible(p_account,target.id,target_revision,true)) THEN
      RAISE EXCEPTION 'Knowledge evidence has not been published' USING ERRCODE='42501';
    END IF;
    IF link.relation='group' AND NOT EXISTS(SELECT 1 FROM knowledge_entry_revisions r
      WHERE r.account_id=p_account AND r.entry_id=target.id AND r.id=target_revision AND r.body->>'kind'='group') THEN
      RAISE EXCEPTION 'Knowledge membership requires a group' USING ERRCODE='22023';
    END IF;
    -- Membership follows collection identities, not the revision originally
    -- linked. Check both published and outstanding proposed parents so that
    -- independently reviewed moves cannot later close a cycle. Publication
    -- and proposals share the account publication lock.
    IF link.relation='group' AND p_body->>'kind'='group' AND EXISTS(
      WITH RECURSIVE parents(id) AS (
        SELECT target.id UNION SELECT l.target_entry_id FROM parents
        JOIN knowledge_entries g ON g.account_id=p_account AND g.id=parents.id AND NOT g.archived
        JOIN knowledge_entry_links l ON l.account_id=g.account_id AND l.entry_id=g.id AND l.relation='group'
          AND (l.revision_id=g.published_revision_id OR (l.revision_id=g.latest_revision_id AND EXISTS(
            SELECT 1 FROM knowledge_entry_decisions d WHERE d.account_id=g.account_id AND d.entry_id=g.id
              AND d.revision_id=g.latest_revision_id AND d.version=g.version AND d.outcome='pending')))
      ) SELECT 1 FROM parents WHERE id=source.id
    ) THEN RAISE EXCEPTION 'Knowledge collections cannot contain a cycle' USING ERRCODE='22023'; END IF;
    IF link.relation='evidence' AND EXISTS(
      WITH RECURSIVE refs(id,rev) AS (
        SELECT target.id,target_revision UNION SELECT l.target_entry_id,l.target_revision_id FROM refs
        JOIN knowledge_entry_links l ON l.account_id=p_account AND l.entry_id=refs.id AND l.revision_id=refs.rev AND l.relation='evidence'
      ) SELECT 1 FROM refs WHERE id=source.id
    ) THEN RAISE EXCEPTION 'Knowledge evidence cannot contain a cycle' USING ERRCODE='22023'; END IF;
  END LOOP;
END $$;

CREATE FUNCTION knowledge_validate_source(p_account uuid, p_entry uuid, p_body jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE e knowledge_entries%ROWTYPE; d documents%ROWTYPE;
BEGIN
  IF (p_body->'source') ? 'purpose' AND (
    jsonb_typeof(p_body#>'{source,purpose}') IS DISTINCT FROM 'string'
    OR p_body#>>'{source,purpose}' NOT IN ('evidence','reference')) THEN
    RAISE EXCEPTION 'Invalid source purpose' USING ERRCODE='22023'; END IF;
  IF NOT knowledge_source_visible(p_account,p_body) THEN
    RAISE EXCEPTION 'Knowledge source unavailable' USING ERRCODE='42501'; END IF;
  SELECT * INTO STRICT e FROM knowledge_entries WHERE account_id=p_account AND id=p_entry;
  IF (e.access_document_id IS NOT NULL AND (p_body#>>'{source,documentId}')::uuid IS DISTINCT FROM e.access_document_id)
    OR (e.access_file_id IS NOT NULL AND (p_body#>>'{source,fileId}')::uuid IS DISTINCT FROM e.access_file_id) THEN
    RAISE EXCEPTION 'A source identity is immutable; retain a different source as a new entry' USING ERRCODE='22023'; END IF;
  IF p_body#>>'{source,documentId}' IS NOT NULL THEN
    SELECT * INTO STRICT d FROM documents WHERE account_id=p_account AND id=(p_body#>>'{source,documentId}')::uuid;
    IF NOT (d.authority_kind='organization'
      OR (d.authority_kind='workspace' AND e.scope IN ('workspace','personal') AND d.authority_workspace_id=e.origin_workspace_id)
      OR (d.authority_kind='personal' AND e.scope='personal' AND d.authority_subject_id=e.scope_subject_id)) THEN
      RAISE EXCEPTION 'Knowledge source would widen document access' USING ERRCODE='42501'; END IF;
  ELSIF p_body#>>'{source,fileId}' IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM files f WHERE f.account_id=p_account
      AND (f.workspace_id=e.origin_workspace_id OR (e.scope='personal' AND e.scope_subject_id=ANY(f.private_owner_subject_ids)))
      AND f.id=(p_body#>>'{source,fileId}')::uuid AND f.status='ready'
      AND (f.private_owner_subject_ids IS NULL OR (e.scope='personal' AND e.scope_subject_id=ANY(f.private_owner_subject_ids)))) OR e.scope='organization' THEN
      RAISE EXCEPTION 'File source requires its authorized scope' USING ERRCODE='42501'; END IF;
  END IF;
  IF e.access_document_id IS NULL AND e.access_file_id IS NULL THEN
    UPDATE knowledge_entries SET access_document_id=(p_body#>>'{source,documentId}')::uuid,
      access_file_id=CASE WHEN p_body#>>'{source,documentId}' IS NULL THEN (p_body#>>'{source,fileId}')::uuid END
      WHERE account_id=p_account AND id=p_entry;
  END IF;
END $$;

CREATE FUNCTION knowledge_visible_index_status(p_account uuid, p_workspace uuid, p_actor jsonb, p_items jsonb, p_view text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE item jsonb; visible jsonb; result jsonb := '[]'::jsonb;
  job knowledge_index_jobs%ROWTYPE;
  previous text := current_setting('opengeni.knowledge_index_dispatcher',true);
  status text;
BEGIN
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)>50
    OR p_view IS NULL OR p_view NOT IN ('published','needs_review','archived','rejected') THEN
    RAISE EXCEPTION 'Invalid Knowledge index status request' USING ERRCODE='22023';
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (item->>'entryId') IS NULL
      OR (item->>'revisionId') IS NULL THEN
      RAISE EXCEPTION 'Invalid Knowledge index status item' USING ERRCODE='22023';
    END IF;
    visible := knowledge_entry_read(p_account,p_workspace,p_actor,
      jsonb_build_object('operation','get','entryId',item->>'entryId','view',p_view,'limit',1));
    IF visible#>>'{0,revision,id}' IS DISTINCT FROM item->>'revisionId'
      OR visible#>>'{0,revision,kind}' IS DISTINCT FROM 'source' THEN
      CONTINUE;
    END IF;
    PERFORM set_config('opengeni.knowledge_index_dispatcher','1',true);
    SELECT * INTO job FROM knowledge_index_jobs j WHERE j.account_id=p_account
      AND j.entry_id=(item->>'entryId')::uuid AND j.revision_id=(item->>'revisionId')::uuid;
    PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
    status := CASE
      WHEN job.revision_id IS NULL THEN 'saved'
      WHEN job.state='ready' AND job.completed_generation=job.generation THEN 'indexed'
      WHEN job.state='running' THEN 'indexing'
      WHEN job.state='pending' AND job.last_failure='waiting_for_funding' THEN 'awaiting_funding'
      WHEN job.state='pending' AND job.last_failure='source_unavailable' THEN 'source_unavailable'
      WHEN job.state='pending' AND job.last_failure='embedding_unavailable' THEN 'provider_failed'
      ELSE 'queued' END;
    result := result || jsonb_build_array(jsonb_build_object(
      'entryId',item->>'entryId','revisionId',item->>'revisionId','status',status));
  END LOOP;
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.knowledge_index_dispatcher',coalesce(previous,''),true);
  RAISE;
END $$;

CREATE FUNCTION lease_vault_passkeys(p_principal jsonb, p_holder text, p_ttl_seconds integer) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  IF nullif(pg_catalog.btrim(p_holder), '') IS NULL OR coalesce(p_ttl_seconds, 0) <= 0 THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'a holder and a positive TTL are required');
  END IF;
  RETURN QUERY
    INSERT INTO vault_passkey_leases (item_id, account_id, holder, expires_at)
    SELECT item.id, item.account_id, p_holder,
      pg_catalog.now() + pg_catalog.make_interval(secs => least(p_ttl_seconds, 86400))
    FROM vault_items item
    WHERE item.type = 'passkey' AND item.archived_at IS NULL
      AND item.account_id = (context ->> 'accountId')::uuid
      AND item.vault_id IN (SELECT reach.vault_id FROM opengeni_private.vault_reach(context) reach)
    ON CONFLICT (item_id) DO UPDATE
      SET holder = EXCLUDED.holder, expires_at = EXCLUDED.expires_at
    RETURNING vault_passkey_leases.item_id;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION link_provider_vault(p jsonb, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  owner_kind text := p ->> 'ownerKind';
  link_source text := p ->> 'source';
  link_mode text := coalesce(p ->> 'mode', 'read_only');
  connection_ref uuid := nullif(p ->> 'providerConnectionId', '')::uuid;
  vault_ref text := nullif(pg_catalog.btrim(p ->> 'providerVaultRef'), '');
  connection_row record;
  connection_ownership text;
  provider_label text;
  existing uuid;
  vault_row vaults;
  allowed uuid[];
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  IF context ->> 'kind' = 'site_viewer' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'Sites cannot link vaults');
  END IF;
  IF owner_kind NOT IN ('user', 'workspace', 'organization') OR owner_kind IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'vaults are linked for "user", "workspace" or "organization"');
  END IF;
  IF owner_kind = 'organization' AND NOT coalesce((p ->> 'allowOrganization')::boolean, false) THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'organization vaults need account:admin');
  END IF;
  IF owner_kind = 'user' AND NOT coalesce((context ->> 'includeUser')::boolean, false) THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'this caller cannot own Only-me vaults');
  END IF;
  IF link_source NOT IN ('onepassword', 'host', 'external', 'protonpass', 'keeper', 'bitwarden')
    OR link_source IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'only connected vault providers are linked');
  END IF;
  IF link_mode NOT IN ('read_write', 'read_only') THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'mode is read_write or read_only');
  END IF;
  IF vault_ref IS NULL OR pg_catalog.char_length(vault_ref) > 300 THEN
    PERFORM opengeni_private.vault_raise('vault_not_found', 'a provider vault reference is required');
  END IF;
  IF link_source <> 'host' THEN
    provider_label := CASE link_source
      WHEN 'onepassword' THEN '1Password'
      WHEN 'protonpass' THEN 'Proton Pass'
      WHEN 'keeper' THEN 'Keeper'
      WHEN 'bitwarden' THEN 'Bitwarden'
      ELSE 'vault provider' END;
    SELECT connection.id, connection.subject_id, connection.status, connection.metadata
    INTO connection_row
    FROM connections connection
    WHERE connection.id = connection_ref
      AND connection.account_id = (context ->> 'accountId')::uuid
      AND connection.workspace_id = (context ->> 'workspaceId')::uuid
      AND connection.kind = 'api_key'
      AND CASE WHEN link_source = 'onepassword' THEN
          pg_catalog.lower(connection.provider_domain) = '1password.com'
          AND connection.metadata ->> 'credentialRole' = 'onepassword_service_account'
        ELSE
          connection.provider_domain = 'vault:' || link_source
          AND connection.metadata ->> 'credentialRole' = 'external_vault_provider'
          AND connection.metadata #>> '{vaultProvider,provider}' = link_source
          AND connection.metadata #>> '{vaultProvider,version}' = '1'
        END;
    IF connection_row.id IS NULL OR connection_row.status = 'revoked' THEN
      PERFORM opengeni_private.vault_raise('vault_not_found', provider_label || ' connection not found');
    END IF;
    IF connection_row.status <> 'active'
      OR coalesce(connection_row.metadata #>> '{vaultProvider,verificationStatus}', 'ready') <> 'ready' THEN
      PERFORM opengeni_private.vault_raise('provider_auth_expired',
        'the ' || provider_label || ' connection must be verified again before its vaults are linked',
        pg_catalog.jsonb_build_object('connectionId', connection_row.id));
    END IF;
    connection_ownership := CASE
      WHEN link_source <> 'onepassword' THEN connection_row.metadata #>> '{vaultProvider,ownership}'
      WHEN connection_row.subject_id IS NOT NULL THEN 'user'
      WHEN connection_row.metadata ->> 'ownership' = 'organization' THEN 'organization'
      WHEN connection_row.metadata ->> 'ownership' = 'user' THEN NULL
      ELSE 'workspace' END;
    IF connection_ownership IS NULL
      OR connection_ownership NOT IN ('user', 'workspace', 'organization')
      OR (connection_ownership = 'user') <> (connection_row.subject_id IS NOT NULL) THEN
      PERFORM opengeni_private.vault_raise('vault_permission_denied',
        'the ' || provider_label || ' connection has no consistent owner',
        pg_catalog.jsonb_build_object('connectionId', connection_row.id));
    END IF;
    IF connection_ownership = 'user' AND (
      owner_kind <> 'user' OR connection_row.subject_id IS DISTINCT FROM context ->> 'subjectId'
    ) THEN
      PERFORM opengeni_private.vault_raise('vault_permission_denied',
        'a personal ' || provider_label || ' connection backs only its owner''s Only-me vaults');
    END IF;
    IF connection_ownership <> owner_kind THEN
      PERFORM opengeni_private.vault_raise('vault_permission_denied',
        'a ' || connection_ownership || ' ' || provider_label || ' connection backs only '
          || connection_ownership || ' vaults',
        pg_catalog.jsonb_build_object('connectionId', connection_row.id,
          'connectionOwnership', connection_ownership, 'ownerKind', owner_kind));
    END IF;
  ELSE
    connection_ref := NULL;
  END IF;
  SELECT vault.id INTO existing FROM vaults vault
  WHERE vault.account_id = (context ->> 'accountId')::uuid
    AND vault.source = link_source
    AND vault.provider_vault_ref = vault_ref
    AND vault.provider_connection_id IS NOT DISTINCT FROM connection_ref
  LIMIT 1;
  IF existing IS NOT NULL THEN
    PERFORM opengeni_private.vault_raise('vault_name_conflict', 'this provider vault is already linked',
      pg_catalog.jsonb_build_object('providerVaultRef', vault_ref));
  END IF;
  IF pg_catalog.jsonb_typeof(p #> '{availability,allowedWorkspaceIds}') = 'array' THEN
    allowed := ARRAY(SELECT pg_catalog.jsonb_array_elements_text(p #> '{availability,allowedWorkspaceIds}')::uuid);
  END IF;
  IF owner_kind = 'user' AND NOT p ? 'availability' THEN
    allowed := ARRAY[(context ->> 'workspaceId')::uuid];
  END IF;
  vault_row := opengeni_private.vault_insert(context, owner_kind, p ->> 'name', p ->> 'description',
    allowed, coalesce((p #>> '{availability,allowPersonalWorkspaces}')::boolean, true), false, NULL);
  UPDATE vaults SET source = link_source, mode = link_mode, provider_connection_id = connection_ref,
    provider_vault_ref = vault_ref, sync_status = 'syncing', updated_at = pg_catalog.now()
  WHERE id = vault_row.id RETURNING * INTO vault_row;
  PERFORM opengeni_private.vault_audit(vault_row.account_id, (context ->> 'workspaceId')::uuid,
    context ->> 'subjectId', 'vault.provider.linked', 'vault', vault_row.id::text,
    pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'source', link_source, 'mode', link_mode,
      'providerConnectionId', connection_ref, 'ownerKind', owner_kind));
  result := opengeni_private.vault_summary_json(vault_row, context) || pg_catalog.jsonb_build_object(
    'tier', CASE vault_row.owner_kind WHEN 'user' THEN 1 WHEN 'workspace' THEN 2 ELSE 3 END);
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION list_document_authority_reclassifications(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text, p_document_id uuid, p_limit integer, p_before_created_at timestamp with time zone, p_before_operation_id uuid) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT receipt.result
  FROM document_authority_reclassifications receipt
  WHERE receipt.account_id = p_account_id
    AND receipt.request_workspace_id = p_workspace_id
    AND receipt.actor_subject_id = p_actor_subject_id
    AND receipt.document_id = p_document_id
    AND p_account_id = nullif(current_setting('opengeni.account_id', true), '')::uuid
    AND p_workspace_id = nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    AND p_actor_subject_id = nullif(current_setting('opengeni.subject_id', true), '')
    AND (
      p_before_created_at IS NULL
      OR receipt.created_at < p_before_created_at
      OR (
        receipt.created_at = p_before_created_at
        AND receipt.operation_id < p_before_operation_id
      )
    )
  ORDER BY receipt.created_at DESC, receipt.operation_id DESC
  LIMIT least(greatest(coalesce(p_limit, 1), 1), 101)
$$;

CREATE FUNCTION list_document_default_collection_backfill_runs(p_command jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'accountId', '')::uuid;
  limit_value integer := coalesce((p_command ->> 'limit')::integer, 50);
  before_started_at timestamptz := nullif(p_command ->> 'beforeStartedAt', '')::timestamptz;
  before_run_id uuid := nullif(p_command ->> 'beforeRunId', '')::uuid;
  audit_capability_id uuid := gen_random_uuid();
  previous_audit_token text := current_setting(
    'opengeni.document_migration_audit_token', true
  );
  row_value jsonb;
BEGIN
  PERFORM assert_document_migration_audit_authority(p_command);
  IF limit_value NOT BETWEEN 1 AND 101 THEN
    RAISE EXCEPTION 'document migration audit limit is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (before_started_at IS NULL) IS DISTINCT FROM (before_run_id IS NULL) THEN
    RAISE EXCEPTION 'document migration audit cursor is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO document_migration_audit_capabilities (
    capability_id, backend_pid, transaction_id, capability_kind
  ) VALUES (
    audit_capability_id, pg_backend_pid(), pg_current_xact_id(),
    'default_backfill_audit'
  );
  PERFORM set_config(
    'opengeni.document_migration_audit_token', audit_capability_id::text, true
  );

  FOR row_value IN
    SELECT jsonb_build_object(
      'runId', run.run_id,
      'actorSubjectId', run.actor_subject_id,
      'status', run.status,
      'lastWorkspaceId', run.last_workspace_id,
      'processedCount', run.processed_count,
      'createdCount', run.created_count,
      'adoptedCount', run.adopted_count,
      'startedAt', run.started_at,
      'updatedAt', run.updated_at,
      'completedAt', run.completed_at
    )
    FROM document_default_collection_backfill_runs run
    WHERE run.account_id = account_id_value
      AND (
        before_started_at IS NULL
        OR (run.started_at, run.run_id) < (before_started_at, before_run_id)
      )
    ORDER BY run.started_at DESC, run.run_id DESC
    LIMIT limit_value
  LOOP
    RETURN NEXT row_value;
  END LOOP;

  DELETE FROM document_migration_audit_capabilities
  WHERE capability_id = audit_capability_id;
  PERFORM set_config(
    'opengeni.document_migration_audit_token', coalesce(previous_audit_token, ''), true
  );
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM document_migration_audit_capabilities
  WHERE capability_id = audit_capability_id;
  PERFORM set_config(
    'opengeni.document_migration_audit_token', coalesce(previous_audit_token, ''), true
  );
  RAISE;
END;
$$;

CREATE FUNCTION list_organization_administration_members(p_account_id uuid, p_actor_subject_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  actor organization_memberships%ROWTYPE;
  result jsonb;
BEGIN
  IF p_account_id IS NULL
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization member authority required' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  IF (SELECT count(*) FROM organization_memberships WHERE account_id = p_account_id) > 1000 THEN
    RAISE EXCEPTION 'organization member inventory exceeds the bounded projection'
      USING ERRCODE = '54000';
  END IF;
  SELECT coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'id', membership.id,
      'organizationId', membership.account_id,
      'subjectId', membership.subject_id,
      'name', auth_user.name,
      'email', auth_user.email,
      'role', membership.role,
      'status', membership.status,
      'authorizationRevision', membership.authorization_revision,
      'sharedWorkspaceAccess', coalesce((
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'workspaceId', workspace.id,
          'workspaceName', workspace.name,
          'membershipId', access.id,
          'role', opengeni_private.workspace_member_role(access.role, access.permissions),
          'updatedAt', access.updated_at
        ) ORDER BY lower(workspace.name), workspace.id)
        FROM workspace_memberships access
        JOIN workspaces workspace ON workspace.id = access.workspace_id
        WHERE access.account_id = p_account_id
          AND access.subject_id = membership.subject_id
          AND NOT EXISTS (
            SELECT 1 FROM organization_memberships personal_owner
            WHERE personal_owner.account_id = p_account_id
              AND personal_owner.personal_workspace_id = workspace.id
          )
      ), '[]'::jsonb),
      'revokedAt', membership.revoked_at,
      'createdAt', membership.created_at,
      'updatedAt', membership.updated_at
    ) ORDER BY lower(coalesce(auth_user.name, auth_user.email, membership.subject_id)), membership.id
  ), '[]'::jsonb) INTO result
  FROM organization_memberships membership
  LEFT JOIN auth_users auth_user
    ON membership.subject_id = 'user:' || auth_user.id
  WHERE membership.account_id = p_account_id;
  RETURN result;
END
$$;

COMMENT ON FUNCTION list_organization_administration_members(p_account_id uuid, p_actor_subject_id text) IS 'Safe organization-admin member projection with shared-workspace access and no personal-workspace metadata. The legacy list_organization_members projection remains unchanged for rolling compatibility.';

CREATE FUNCTION list_organization_codex_workspace_ids(p_account_id uuid) RETURNS TABLE(workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  previous_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF p_account_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR opengeni_private.current_workspace_id() IS NOT NULL
  THEN
    RAISE EXCEPTION 'organization Codex workspace inventory authority required'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );

  RETURN QUERY
  SELECT workspace.id
  FROM workspaces workspace
  WHERE workspace.account_id = p_account_id;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RETURN;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION list_organization_codex_workspace_ids(p_account_id uuid) IS 'Content-free same-organization workspace IDs, including Personal, for Codex source fences and capacity wakes only. Grants no workspace access.';

CREATE FUNCTION list_organization_document_authority_reclassifications(p_command jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'accountId', '')::uuid;
  limit_value integer := coalesce((p_command ->> 'limit')::integer, 50);
  before_created_at timestamptz := nullif(p_command ->> 'beforeCreatedAt', '')::timestamptz;
  before_operation_id uuid := nullif(p_command ->> 'beforeOperationId', '')::uuid;
  audit_capability_id uuid := gen_random_uuid();
  previous_audit_token text := current_setting(
    'opengeni.document_migration_audit_token', true
  );
  row_value jsonb;
BEGIN
  PERFORM assert_document_migration_audit_authority(p_command);
  IF limit_value NOT BETWEEN 1 AND 101 THEN
    RAISE EXCEPTION 'document migration audit limit is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF (before_created_at IS NULL) IS DISTINCT FROM (before_operation_id IS NULL) THEN
    RAISE EXCEPTION 'document migration audit cursor is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO document_migration_audit_capabilities (
    capability_id, backend_pid, transaction_id, capability_kind
  ) VALUES (
    audit_capability_id, pg_backend_pid(), pg_current_xact_id(),
    'reclassification_audit'
  );
  PERFORM set_config(
    'opengeni.document_migration_audit_token', audit_capability_id::text, true
  );

  FOR row_value IN
    SELECT receipt.result || jsonb_build_object(
      'actorSubjectId', receipt.actor_subject_id,
      'requestWorkspaceId', receipt.request_workspace_id
    )
    FROM document_authority_reclassifications receipt
    WHERE receipt.account_id = account_id_value
      AND (
        before_created_at IS NULL
        OR (receipt.created_at, receipt.operation_id)
          < (before_created_at, before_operation_id)
      )
    ORDER BY receipt.created_at DESC, receipt.operation_id DESC
    LIMIT limit_value
  LOOP
    RETURN NEXT row_value;
  END LOOP;

  DELETE FROM document_migration_audit_capabilities
  WHERE capability_id = audit_capability_id;
  PERFORM set_config(
    'opengeni.document_migration_audit_token', coalesce(previous_audit_token, ''), true
  );
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM document_migration_audit_capabilities
  WHERE capability_id = audit_capability_id;
  PERFORM set_config(
    'opengeni.document_migration_audit_token', coalesce(previous_audit_token, ''), true
  );
  RAISE;
END;
$$;

CREATE FUNCTION list_organization_invitations(p_account_id uuid, p_actor_subject_id text, p_cursor_id uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  actor organization_memberships%ROWTYPE;
  cursor_created_at timestamptz;
  result jsonb;
BEGIN
  IF p_account_id IS NULL
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
  THEN
    RAISE EXCEPTION 'organization invitation page authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  IF p_cursor_id IS NOT NULL THEN
    SELECT invitation.created_at INTO cursor_created_at
    FROM organization_membership_invitations invitation
    WHERE invitation.account_id = p_account_id AND invitation.id = p_cursor_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'organization invitation cursor not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;
  SELECT coalesce(
    pg_catalog.jsonb_agg(
      opengeni_private.organization_invitation_row_json(candidate)
      ORDER BY candidate.created_at DESC, candidate.id DESC
    ), '[]'::jsonb
  ) INTO result
  FROM (
    SELECT invitation.*
    FROM organization_membership_invitations invitation
    WHERE invitation.account_id = p_account_id
      AND (
        p_cursor_id IS NULL
        OR (invitation.created_at, invitation.id) < (cursor_created_at, p_cursor_id)
      )
    ORDER BY invitation.created_at DESC, invitation.id DESC
    LIMIT p_limit + 1
  ) candidate;
  RETURN result;
END
$$;

CREATE FUNCTION list_organization_members(p_account_id uuid, p_actor_subject_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE actor organization_memberships%ROWTYPE; result jsonb;
BEGIN
  IF p_account_id IS NULL
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization member authority required' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT coalesce(
    pg_catalog.jsonb_agg(
      opengeni_private.organization_membership_row_json(membership)
      ORDER BY membership.created_at, membership.id
    ), '[]'::jsonb
  ) INTO result
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id;
  RETURN result;
END
$$;

CREATE FUNCTION list_organization_membership_backfill_anchors(p_organization_id uuid, p_subject_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  result jsonb;
  subject_id_value text;
  previous_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'membership backfill requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_organization_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'membership backfill scope mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_subject_ids IS NULL
    OR pg_catalog.array_length(p_subject_ids, 1) IS NULL
    OR pg_catalog.array_length(p_subject_ids, 1) > 500
  THEN
    RAISE EXCEPTION 'membership backfill requires 1..500 subjects'
      USING ERRCODE = '22023';
  END IF;
  FOREACH subject_id_value IN ARRAY p_subject_ids LOOP
    IF subject_id_value IS NULL
      OR subject_id_value <> pg_catalog.btrim(subject_id_value)
      OR pg_catalog.length(subject_id_value) NOT BETWEEN 1 AND 1024
      OR subject_id_value NOT LIKE 'user:%'
    THEN
      RAISE EXCEPTION 'membership backfill subject is invalid'
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_backfill',
    true
  );
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'subjectId', anchor.subject_id,
    'membershipId', anchor.id,
    'status', anchor.status,
    'personalWorkspaceId', anchor.personal_workspace_id
  ) ORDER BY anchor.subject_id), '[]'::jsonb)
  INTO result
  FROM organization_memberships anchor
  WHERE anchor.account_id = p_organization_id
    AND anchor.subject_id = ANY (p_subject_ids);

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    COALESCE(previous_marker, ''),
    true
  );
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    COALESCE(previous_marker, ''),
    true
  );
  RAISE;
END
$$;

CREATE FUNCTION list_organization_memberships_without_personal_workspace(p_organization_id uuid, p_limit integer DEFAULT 25, p_after_subject_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    SET statement_timeout TO '30s'
    AS $$
DECLARE
  result jsonb;
  previous_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'membership backfill requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_organization_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'membership backfill scope mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'membership backfill limit must be 1..100'
      USING ERRCODE = '22023';
  END IF;
  IF p_after_subject_id IS NOT NULL
    AND (
      p_after_subject_id <> pg_catalog.btrim(p_after_subject_id)
      OR pg_catalog.length(p_after_subject_id) NOT BETWEEN 1 AND 1024
      OR p_after_subject_id NOT LIKE 'user:%'
    )
  THEN
    RAISE EXCEPTION 'membership backfill cursor is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_backfill',
    true
  );
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'subjectId', pending.subject_id,
    'membershipId', pending.id,
    'status', pending.status,
    'personalWorkspaceId', NULL
  ) ORDER BY pending.subject_id COLLATE "C"), '[]'::jsonb)
  INTO result
  FROM (
    -- `COLLATE "C"` is load-bearing, not cosmetic. The driver merges this page
    -- with its own workspace-access page in JavaScript and re-sorts the union
    -- with the default comparator, which is code-unit (byte) order. The
    -- database's default collation is locale-aware (`en_US.utf8` in practice),
    -- where `_` is ignorable and case is secondary, so `user:Alpha_two` sorts
    -- BEFORE `user:a_b` in JavaScript and AFTER it in the database. A keyset
    -- cursor taken from the JavaScript order would then skip every subject the
    -- database considers already behind it - a silent, permanent drop that
    -- still reports `drained: true`. Pinning both sides to `C` makes the two
    -- orders identical.
    SELECT candidate.id, candidate.subject_id, candidate.status
    FROM organization_memberships candidate
    WHERE candidate.account_id = p_organization_id
      AND candidate.personal_workspace_id IS NULL
      AND candidate.status IN ('active', 'provisioning')
      AND (
        p_after_subject_id IS NULL
        OR candidate.subject_id COLLATE "C" > p_after_subject_id COLLATE "C"
      )
    ORDER BY candidate.subject_id COLLATE "C"
    LIMIT p_limit
  ) pending;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    COALESCE(previous_marker, ''),
    true
  );
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    COALESCE(previous_marker, ''),
    true
  );
  RAISE;
END
$$;

CREATE FUNCTION list_organization_retention_deletion_objects(p_account_id uuid, p_membership_id uuid, p_operation_id uuid, p_object_bucket text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  IF nullif(p_object_bucket, '') IS NULL
    OR octet_length(convert_to(p_object_bucket, 'UTF8')) > 1024
  THEN
    RAISE EXCEPTION 'invalid retention object bucket' USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'invalid retention object page size' USING ERRCODE = '22023';
  END IF;
  PERFORM opengeni_private.assert_organization_retention_account(p_account_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  UPDATE organization_user_retention_deletions deletion
  SET claim_expires_at = clock_timestamp() + interval '15 minutes', updated_at = clock_timestamp()
  WHERE deletion.account_id = p_account_id
    AND deletion.membership_id = p_membership_id
    AND deletion.claim_operation_id = p_operation_id
    AND deletion.state = 'claimed'
    AND deletion.claim_expires_at > clock_timestamp()
    AND deletion.database_finalized_at IS NOT NULL
    AND deletion.database_result ->> 'objectBucket' = p_object_bucket;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention deletion claim is stale' USING ERRCODE = '40001';
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'objectKind', candidate.object_kind,
    'sourceId', candidate.source_id,
    'objectBucket', candidate.object_bucket,
    'objectKey', candidate.object_key
  ) ORDER BY candidate.object_kind, candidate.source_id), '[]'::jsonb)
  INTO result
  FROM (
    SELECT receipt.object_kind, receipt.source_id, receipt.object_bucket, receipt.object_key
    FROM organization_user_retention_object_obligations receipt
    WHERE receipt.account_id = p_account_id
      AND receipt.membership_id = p_membership_id
      AND NOT EXISTS (
        SELECT 1
        FROM organization_user_retention_object_deletion_receipts deleted
        WHERE deleted.account_id = receipt.account_id
          AND deleted.membership_id = receipt.membership_id
          AND deleted.object_kind = receipt.object_kind
          AND deleted.source_id = receipt.source_id
          AND deleted.object_bucket = receipt.object_bucket
      )
    ORDER BY receipt.object_kind, receipt.source_id
    LIMIT p_limit
  ) candidate;
  RETURN result;
END
$$;

CREATE FUNCTION list_organization_subscription_workspace_ids(p_account_id uuid) RETURNS TABLE(workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
    DECLARE
      previous_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
    BEGIN
      IF p_account_id IS NULL
        OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR opengeni_private.current_workspace_id() IS NOT NULL
      THEN
        RAISE EXCEPTION 'organization subscription workspace inventory authority required'
          USING ERRCODE = '42501';
      END IF;

      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        'organization_membership_lifecycle', true
      );

      RETURN QUERY
      SELECT workspace.id
      FROM workspaces workspace
      WHERE workspace.account_id = p_account_id;

      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
      );
      RETURN;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
      );
      RAISE;
    END
    $$;

COMMENT ON FUNCTION list_organization_subscription_workspace_ids(p_account_id uuid) IS 'Content-free same-organization workspace IDs, including Personal, for subscription source fences and capacity wakes only. Grants no workspace access.';

CREATE FUNCTION list_organization_workspace_ids(p_account_id uuid) RETURNS TABLE(workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  previous_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF p_account_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR opengeni_private.current_workspace_id() IS NOT NULL
  THEN
    RAISE EXCEPTION 'organization workspace inventory authority required'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );

  RETURN QUERY
  SELECT workspace.id
  FROM workspaces workspace
  WHERE workspace.account_id = p_account_id
    AND NOT EXISTS (
      SELECT 1
      FROM organization_memberships membership
      WHERE membership.account_id = p_account_id
        AND membership.personal_workspace_id = workspace.id
    );

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RETURN;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION list_organization_workspace_ids(p_account_id uuid) IS 'Complete content-free organization workspace inventory. Canonical personal-workspace pointers are excluded under exact account scope.';

CREATE FUNCTION list_owned_connection_accounts(p_account_id uuid, p_workspace_id uuid) RETURNS TABLE(connection_id uuid, origin_workspace_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  sender_prior_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
BEGIN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true);
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    OR caller_subject IS NULL
  THEN RAISE EXCEPTION 'connection account scope mismatch' USING ERRCODE = '42501'; END IF;
  RETURN QUERY
  SELECT a.resource_id, a.origin_workspace_id
  FROM organization_user_resource_authorities a
  JOIN organization_memberships m ON m.id = a.organization_membership_id AND m.account_id = a.account_id
  WHERE a.account_id = p_account_id AND a.resource_kind = 'connection'
    AND m.subject_id = caller_subject AND m.status = 'active' AND m.revoked_at IS NULL
    AND a.status = 'active' AND a.revoked_at IS NULL
    AND EXISTS (SELECT 1 FROM workspaces w WHERE w.id = p_workspace_id AND w.account_id = p_account_id
      AND (m.personal_workspace_id = w.id OR EXISTS (
        SELECT 1 FROM workspace_memberships wm WHERE wm.account_id = p_account_id
          AND wm.workspace_id = w.id AND wm.subject_id = caller_subject)))
  ORDER BY a.resource_id;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true);
EXCEPTION WHEN OTHERS THEN RAISE;
END
$$;

CREATE FUNCTION list_scoped_enrollments(p_account_id uuid, p_workspace_id uuid, p_enrollment_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'active'::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE actor_membership_id uuid; enrollment_row record;
BEGIN
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
  ON CONFLICT DO NOTHING;
  actor_membership_id := scoped_compute_actor_membership(p_account_id, p_workspace_id);
  IF p_status NOT IN ('active', 'revoked') THEN
    RAISE EXCEPTION 'invalid enrollment status' USING ERRCODE = '22023';
  END IF;
  FOR enrollment_row IN
    SELECT enrollment.*, sandbox.id AS sandbox_id, sandbox.name AS sandbox_name
    FROM enrollments enrollment
    LEFT JOIN LATERAL (
      SELECT value.id, value.name FROM sandboxes value
      WHERE value.enrollment_id = enrollment.id AND value.account_id = enrollment.account_id
      ORDER BY value.created_at LIMIT 1
    ) sandbox ON true
    WHERE enrollment.account_id = p_account_id AND enrollment.status = p_status
      AND enrollment.kind = 'machine'
      AND (p_enrollment_id IS NULL OR enrollment.id = p_enrollment_id)
      AND (enrollment.authority_scope = 'organization'
        OR (enrollment.authority_scope = 'workspace'
          AND enrollment.workspace_id = p_workspace_id)
        OR (enrollment.authority_scope = 'user'
          AND enrollment.owner_organization_membership_id = actor_membership_id))
    ORDER BY enrollment.created_at DESC, enrollment.id
  LOOP
    RETURN NEXT pg_catalog.jsonb_build_object(
      'id', enrollment_row.id, 'accountId', enrollment_row.account_id,
      'workspaceId', enrollment_row.workspace_id, 'scope', enrollment_row.authority_scope,
      'generation', enrollment_row.generation, 'pubkey', enrollment_row.pubkey,
      'exposure', enrollment_row.exposure, 'hasDisplay', enrollment_row.has_display,
      'opStream', enrollment_row.op_stream,
      'desktopUnavailableReason', enrollment_row.desktop_unavailable_reason,
      'allowScreenControl', enrollment_row.allow_screen_control,
      'operationPolicy', pg_catalog.jsonb_build_object(
        'memoryMaxBytes', enrollment_row.operation_memory_max_bytes,
        'memoryHighBytes', enrollment_row.operation_memory_high_bytes,
        'cpuMaxMillicores', enrollment_row.operation_cpu_max_millicores,
        'revision', enrollment_row.operation_policy_revision,
        'updatedAt', enrollment_row.operation_policy_updated_at
      ),
      'status', enrollment_row.status,
      'credentialGeneration', enrollment_row.credential_generation,
      'connectionInstanceId', enrollment_row.connection_instance_id,
      'connectionGeneration', enrollment_row.connection_generation,
      'connectionLeaseExpiresAt', enrollment_row.connection_lease_expires_at,
      'connectionDuplicateDeniedCount', enrollment_row.connection_duplicate_denied_count,
      'connectionDuplicateDeniedAt', enrollment_row.connection_duplicate_denied_at,
      'os', enrollment_row.os, 'arch', enrollment_row.arch,
      'workspaceRoot', enrollment_row.workspace_root,
      'lastSeenAt', enrollment_row.last_seen_at,
      'wentOfflineAt', enrollment_row.went_offline_at,
      'wentOfflineReason', enrollment_row.went_offline_reason,
      'agentVersion', enrollment_row.agent_version,
      'agentBinarySha256', enrollment_row.agent_binary_sha256,
      'agentUpdateChannel', enrollment_row.agent_update_channel,
      'agentCapabilities', enrollment_row.agent_capabilities,
      'agentUpdate', CASE WHEN enrollment_row.agent_update_operation_id IS NOT NULL
        AND enrollment_row.agent_update_status IS NOT NULL
        AND length(enrollment_row.agent_update_target_version) > 0
        AND enrollment_row.agent_update_connection_instance_id IS NOT NULL
        AND enrollment_row.agent_update_connection_generation IS NOT NULL
        AND enrollment_row.agent_update_requested_at IS NOT NULL
        AND enrollment_row.agent_update_updated_at IS NOT NULL
        THEN pg_catalog.jsonb_build_object(
          'operationId', enrollment_row.agent_update_operation_id,
          'status', enrollment_row.agent_update_status,
          'targetVersion', enrollment_row.agent_update_target_version,
          'expectedBinarySha256', enrollment_row.agent_update_expected_binary_sha256,
          'errorCode', enrollment_row.agent_update_error_code,
          'retryable', enrollment_row.agent_update_retryable,
          'rolledBack', enrollment_row.agent_update_rolled_back,
          'connectionInstanceId', enrollment_row.agent_update_connection_instance_id,
          'connectionGeneration', enrollment_row.agent_update_connection_generation,
          'requestedAt', enrollment_row.agent_update_requested_at,
          'updatedAt', enrollment_row.agent_update_updated_at,
          'completedAt', enrollment_row.agent_update_completed_at
        ) ELSE NULL END, 'sandboxId', enrollment_row.sandbox_id,
      'sandboxName', enrollment_row.sandbox_name,
      'createdAt', enrollment_row.created_at, 'revokedAt', enrollment_row.revoked_at,
      'updatedAt', enrollment_row.updated_at
    );
  END LOOP;
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'read';
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION list_scoped_machine_dependent_sessions(p_account_id uuid, p_origin_workspace_id uuid, p_sandbox_id uuid) RETURNS TABLE(session_id uuid, title text, active_turn_id uuid, sandbox_backend text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), '')::uuid
    OR p_origin_workspace_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.workspace_id', true), '')::uuid
  THEN RAISE EXCEPTION 'machine removal scope mismatch' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM sandboxes sandbox
    WHERE sandbox.id = p_sandbox_id AND sandbox.account_id = p_account_id
      AND sandbox.workspace_id = p_origin_workspace_id
      AND sandbox.kind = 'selfhosted' AND sandbox.enrollment_id IS NOT NULL
  ) THEN RAISE EXCEPTION 'machine sandbox not found' USING ERRCODE = '42501'; END IF;
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
  ON CONFLICT DO NOTHING;
  RETURN QUERY
    SELECT session.id, session.title, session.active_turn_id, session.sandbox_backend
    FROM sessions session
    WHERE session.account_id = p_account_id
      AND (session.active_sandbox_id = p_sandbox_id
        OR session.sandbox_group_id = p_sandbox_id)
    ORDER BY session.created_at, session.id
    FOR NO KEY UPDATE;
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'read';
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION list_scoped_rigs(p_account_id uuid, p_workspace_id uuid, p_rig_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_scope text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  actor_membership_id uuid;
  rig_row record;
BEGIN
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
  ON CONFLICT DO NOTHING;
  actor_membership_id := scoped_compute_actor_membership(p_account_id, p_workspace_id);
  IF p_scope IS NOT NULL AND p_scope NOT IN ('organization', 'workspace', 'user') THEN
    RAISE EXCEPTION 'invalid rig scope' USING ERRCODE = '22023';
  END IF;
  FOR rig_row IN
    SELECT rig.id FROM rigs rig
    WHERE rig.account_id = p_account_id AND rig.status = 'active'
      AND (p_rig_id IS NULL OR rig.id = p_rig_id)
      AND (p_name IS NULL OR rig.name = p_name)
      AND (p_scope IS NULL OR rig.authority_scope = p_scope)
      AND (
        rig.authority_scope = 'organization'
        OR (rig.authority_scope = 'workspace' AND rig.workspace_id = p_workspace_id)
        OR (rig.authority_scope = 'user'
          AND rig.owner_organization_membership_id = actor_membership_id)
      )
    ORDER BY CASE rig.authority_scope WHEN 'user' THEN 1 WHEN 'workspace' THEN 2 ELSE 3 END,
      rig.created_at, rig.id
  LOOP
    RETURN NEXT scoped_rig_json(rig_row.id);
  END LOOP;
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'read';
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'read';
  RAISE;
END
$$;

CREATE FUNCTION list_scoped_variable_sets(p_account_id uuid, p_workspace_id uuid, p_variable_set_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_scope text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      actor_membership_id uuid;
      variable_set_row record;
    BEGIN
      INSERT INTO opengeni_private.variable_set_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
      ON CONFLICT DO NOTHING;
      actor_membership_id := scoped_variable_set_actor_membership(
        p_account_id, p_workspace_id
      );
      IF p_scope IS NOT NULL AND p_scope NOT IN ('organization', 'workspace', 'user') THEN
        RAISE EXCEPTION 'invalid variable-set scope' USING ERRCODE = '22023';
      END IF;

      FOR variable_set_row IN
        SELECT variable_set.id
        FROM workspace_variable_sets variable_set
        WHERE variable_set.account_id = p_account_id
          AND variable_set.status = 'active'
          AND (p_variable_set_id IS NULL OR variable_set.id = p_variable_set_id)
          AND (p_name IS NULL OR variable_set.name = p_name)
          AND (p_scope IS NULL OR variable_set.authority_scope = p_scope)
          AND (
            variable_set.authority_scope = 'organization'
            OR (
              variable_set.authority_scope = 'workspace'
              AND variable_set.workspace_id = p_workspace_id
            )
            OR (
              variable_set.authority_scope = 'user'
              AND variable_set.owner_organization_membership_id = actor_membership_id
            )
          )
        ORDER BY
          CASE variable_set.authority_scope
            WHEN 'user' THEN 1 WHEN 'workspace' THEN 2 ELSE 3
          END,
          variable_set.created_at,
          variable_set.id
      LOOP
        RETURN NEXT scoped_variable_set_json(variable_set_row.id);
      END LOOP;

      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'read';
      RETURN;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'read';
      RAISE;
    END
    $$;

CREATE FUNCTION list_self_organization_invitations(p_subject_id text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT list_self_organization_invitations(p_subject_id, NULL::uuid, 100)
$$;

CREATE FUNCTION list_self_organization_invitations(p_subject_id text, p_cursor_id uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  cursor_created_at timestamptz;
  result jsonb;
BEGIN
  IF p_subject_id IS NULL
    OR p_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_subject_id NOT LIKE 'user:%'
    OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
  THEN
    RAISE EXCEPTION 'managed human subject authority required' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  IF p_cursor_id IS NOT NULL THEN
    SELECT invitation.created_at INTO cursor_created_at
    FROM organization_membership_invitations invitation
    WHERE invitation.target_subject_id = p_subject_id
      AND invitation.id = p_cursor_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'organization invitation cursor not found' USING ERRCODE = 'P0002';
    END IF;
  END IF;
  SELECT coalesce(
    pg_catalog.jsonb_agg(
      opengeni_private.organization_invitation_row_json(candidate.invitation)
        || pg_catalog.jsonb_build_object('organizationName', candidate.organization_name)
      ORDER BY candidate.created_at DESC, candidate.id DESC
    ), '[]'::jsonb
  ) INTO result
  FROM (
    SELECT invitation AS invitation, account.name AS organization_name,
      invitation.created_at, invitation.id
    FROM organization_membership_invitations invitation
    JOIN managed_accounts account ON account.id = invitation.account_id
    WHERE invitation.target_subject_id = p_subject_id
      AND (
        p_cursor_id IS NULL
        OR (invitation.created_at, invitation.id) < (cursor_created_at, p_cursor_id)
      )
    ORDER BY invitation.created_at DESC, invitation.id DESC
    LIMIT p_limit + 1
  ) candidate;
  RETURN result;
END
$$;

CREATE FUNCTION list_self_organization_memberships(p_subject_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  IF p_subject_id IS NULL
    OR p_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR (p_subject_id NOT LIKE 'user:%' AND NOT opengeni_private.active_external_owning_subject(opengeni_private.current_account_id(), p_subject_id))
  THEN
    RAISE EXCEPTION 'managed human subject authority required' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT coalesce(
    pg_catalog.jsonb_agg(
      opengeni_private.organization_membership_row_json(membership)
      ORDER BY membership.created_at, membership.id
    ), '[]'::jsonb
  ) INTO result
  FROM organization_memberships membership
  WHERE membership.subject_id = p_subject_id AND (p_subject_id LIKE 'user:%' OR membership.account_id = opengeni_private.current_account_id());
  RETURN result;
END
$$;

CREATE FUNCTION list_self_user_resource_authorities(p_account_id uuid) RETURNS TABLE(authority_id uuid, resource_kind text, authority_generation bigint, authority_status text, grant_id uuid, target_workspace_id uuid, target_session_id uuid, action text, grant_mode text, grant_context text, grant_generation bigint, grant_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  owner_membership_id uuid;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR caller_subject IS NULL
  THEN
    RAISE EXCEPTION 'user-resource authority scope mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT membership.id INTO STRICT owner_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  FOR SHARE;

  RETURN QUERY
  SELECT authority.id, authority.resource_kind, authority.generation, authority.status,
    grant_value.id, grant_value.workspace_id, grant_value.session_id,
    grant_value.action, grant_value.mode, grant_value.context,
    grant_value.generation, grant_value.status, grant_value.expires_at
  FROM organization_user_resource_authorities authority
  LEFT JOIN organization_user_resource_grants grant_value
    ON grant_value.account_id = authority.account_id
   AND grant_value.authority_id = authority.id
   AND grant_value.owner_organization_membership_id = owner_membership_id
  WHERE authority.account_id = p_account_id
    AND authority.organization_membership_id = owner_membership_id
  ORDER BY authority.created_at, authority.id, grant_value.created_at, grant_value.id;
END
$$;

COMMENT ON FUNCTION list_self_user_resource_authorities(p_account_id uuid) IS 'Owner-only opaque generic user-resource authority/grant lifecycle listing.';

CREATE FUNCTION list_self_user_resource_authorities(p_account_id uuid, p_workspace_id uuid, p_resource_kind text, p_after_authority_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS TABLE(authority_id uuid, organization_id uuid, resource_kind text, resource_id uuid, origin_workspace_id uuid, authority_generation bigint, authority_status text, grant_id uuid, target_workspace_id uuid, target_session_id uuid, action text, grant_mode text, grant_context text, authority_epoch integer, grant_generation bigint, grant_status text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  owner_membership_id uuid;
  cursor_created_at timestamptz;
  cursor_id uuid;
BEGIN
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true
  );
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
    OR caller_subject IS NULL
  THEN
    RAISE EXCEPTION 'user-resource authority scope mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_resource_kind IS NULL OR p_resource_kind NOT IN (
    'connection', 'document', 'variable_set', 'rig', 'connected_machine'
  ) OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 101 THEN
    RAISE EXCEPTION 'invalid user-resource authority page' USING ERRCODE = '22023';
  END IF;
  -- 0611: every organization is session-tenancy activated.

  SELECT membership.id INTO owner_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'owner membership not found or access denied' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace_value
  WHERE workspace_value.id = p_workspace_id
    AND workspace_value.account_id = p_account_id
    AND EXISTS (
      SELECT 1 FROM organization_memberships membership
      WHERE membership.id = owner_membership_id
        AND (
          membership.personal_workspace_id = p_workspace_id
          OR EXISTS (
            SELECT 1 FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = p_account_id
              AND workspace_membership.workspace_id = p_workspace_id
              AND workspace_membership.subject_id = caller_subject
          )
        )
    )
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'owner lacks current route-workspace access' USING ERRCODE = '42501';
  END IF;

  IF p_after_authority_id IS NOT NULL THEN
    SELECT authority.created_at, authority.id
      INTO cursor_created_at, cursor_id
    FROM organization_user_resource_authorities authority
    WHERE authority.id = p_after_authority_id
      AND authority.account_id = p_account_id
      AND authority.organization_membership_id = owner_membership_id
      AND authority.resource_kind = p_resource_kind;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid user-resource authority cursor' USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN QUERY
  WITH authority_page AS MATERIALIZED (
    SELECT authority.*
    FROM organization_user_resource_authorities authority
    WHERE authority.account_id = p_account_id
      AND authority.organization_membership_id = owner_membership_id
      AND authority.resource_kind = p_resource_kind
      AND (
        p_after_authority_id IS NULL
        OR (authority.created_at, authority.id) > (cursor_created_at, cursor_id)
      )
    ORDER BY authority.created_at, authority.id
    LIMIT p_limit
  )
  SELECT authority.id, authority.account_id, authority.resource_kind,
    authority.resource_id, authority.origin_workspace_id, authority.generation,
    authority.status, grant_value.id, grant_value.workspace_id,
    grant_value.session_id, grant_value.action, grant_value.mode,
    grant_value.context, grant_value.authority_epoch, grant_value.generation,
    CASE
      WHEN grant_value.status = 'active'
        AND grant_value.expires_at IS NOT NULL
        AND grant_value.expires_at <= clock_timestamp()
      THEN 'expired'
      ELSE grant_value.status
    END,
    grant_value.expires_at
  FROM authority_page authority
  LEFT JOIN organization_user_resource_grants grant_value
    ON grant_value.account_id = authority.account_id
   AND grant_value.authority_id = authority.id
   AND grant_value.owner_organization_membership_id = owner_membership_id
   AND grant_value.workspace_id = p_workspace_id
   AND grant_value.action = CASE authority.resource_kind
     WHEN 'connection' THEN 'connection.use'
     WHEN 'document' THEN 'document.read'
     WHEN 'variable_set' THEN 'variable_set.use'
     WHEN 'rig' THEN 'rig.use'
     WHEN 'connected_machine' THEN 'connected_machine.use'
     ELSE NULL
   END
  ORDER BY authority.created_at, authority.id, grant_value.created_at, grant_value.id;
END
$$;

COMMENT ON FUNCTION list_self_user_resource_authorities(p_account_id uuid, p_workspace_id uuid, p_resource_kind text, p_after_authority_id uuid, p_limit integer) IS 'Bounded owner-only personal-resource page filtered to one kind and route workspace.';

CREATE FUNCTION list_task_notes_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_include_archived boolean DEFAULT false, p_limit integer DEFAULT 10) RETURNS TABLE(note_id uuid, root_session_id uuid, kind text, note_text text, status text, version integer, expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, archived_at timestamp with time zone, actor_kind text, source_session_id uuid, source_turn_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  authority record;
  write_capability_id uuid := gen_random_uuid();
  previous_capability text := current_setting('opengeni.task_note_write_capability', true);
BEGIN
  SELECT * INTO STRICT authority FROM resolve_task_note_attempt_authority(
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_attempt_id, p_execution_generation
  );
  IF p_include_archived IS NULL OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20 THEN
    RAISE EXCEPTION 'task note list input is invalid' USING ERRCODE = '22023';
  END IF;
  INSERT INTO task_note_write_capabilities (backend_pid, transaction_id, capability_id)
  VALUES (pg_backend_pid(), pg_current_xact_id(), write_capability_id);
  PERFORM set_config('opengeni.task_note_write_capability', write_capability_id::text, true);
  RETURN QUERY
    SELECT note.id, note.root_session_id, note.kind, note.text, note.status,
      note.version, note.expires_at, note.created_at, note.updated_at,
      note.archived_at, note.created_by_actor_kind, note.created_by_session_id,
      note.created_by_turn_id
    FROM task_notes note
    WHERE note.account_id = p_account_id
      AND note.workspace_id = p_workspace_id
      AND note.root_session_id = authority.root_session_id
      AND note.expires_at > transaction_timestamp()
      AND (p_include_archived OR note.status = 'active')
    ORDER BY note.updated_at DESC, note.id DESC
    LIMIT p_limit;
  DELETE FROM task_note_write_capabilities capability
  WHERE capability.backend_pid = pg_backend_pid()
    AND capability.transaction_id = pg_current_xact_id()
    AND capability.capability_id = write_capability_id;
  PERFORM set_config('opengeni.task_note_write_capability', coalesce(previous_capability, ''), true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.task_note_write_capability', coalesce(previous_capability, ''), true);
  RAISE;
END;
$$;

COMMENT ON FUNCTION list_task_notes_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_include_archived boolean, p_limit integer) IS 'Explicit bounded task-tree note retrieval under exact current-attempt and root-session visibility authority.';

CREATE FUNCTION list_vault_field_versions(p_field uuid, p_principal jsonb DEFAULT NULL::jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  field_row vault_item_fields;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  SELECT field.* INTO field_row FROM vault_item_fields field
  WHERE field.id = p_field AND field.account_id = (context ->> 'accountId')::uuid;
  IF NOT FOUND THEN
    PERFORM opengeni_private.vault_raise('vault_field_not_found', 'field not found',
      pg_catalog.jsonb_build_object('fieldId', p_field));
  END IF;
  PERFORM opengeni_private.vault_reachable_item(context, field_row.item_id);
  RETURN QUERY
    SELECT pg_catalog.jsonb_build_object(
      'version', version.version,
      'current', version.version = field_row.current_version,
      'createdAt', version.created_at,
      'createdByKind', version.created_by_kind,
      'createdBySubjectId', version.created_by_subject_id
    )
    FROM vault_field_versions version
    WHERE version.field_id = field_row.id
    ORDER BY version.version DESC;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION list_vault_items(p_vault uuid, p_query text, p_type text, p_include_archived boolean, p_cursor text, p_limit integer, p_principal jsonb DEFAULT NULL::jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  vault_row vaults;
  page_size integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  query_key text := nullif(vault_name_key(coalesce(p_query, '')), '');
  cursor_key text;
  cursor_id uuid;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  vault_row := opengeni_private.vault_reachable_row(context, p_vault);
  IF nullif(p_cursor, '') IS NOT NULL THEN
    cursor_key := pg_catalog.left(p_cursor, pg_catalog.length(p_cursor) - 37);
    BEGIN
      cursor_id := pg_catalog.right(p_cursor, 36)::uuid;
    EXCEPTION WHEN OTHERS THEN
      PERFORM opengeni_private.vault_raise('vault_item_not_found', 'invalid cursor');
    END;
  END IF;
  RETURN QUERY
    SELECT opengeni_private.vault_item_json(item, false)
    FROM vault_items item
    WHERE item.vault_id = vault_row.id
      AND (coalesce(p_include_archived, false) OR item.archived_at IS NULL)
      AND (p_type IS NULL OR item.type = p_type)
      AND (query_key IS NULL
        OR pg_catalog.strpos(item.name_key, query_key) > 0
        OR EXISTS (SELECT 1 FROM pg_catalog.unnest(item.websites) website
          WHERE pg_catalog.strpos(pg_catalog.lower(website), query_key) > 0))
      AND (cursor_id IS NULL OR (item.name_key, item.id) > (cursor_key, cursor_id))
    ORDER BY item.name_key, item.id
    LIMIT page_size + 1;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION list_vaults_for_subject(p_workspace uuid, p_principal jsonb DEFAULT NULL::jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal, p_workspace);
  RETURN QUERY
    SELECT opengeni_private.vault_summary_json(vault, context)
      || pg_catalog.jsonb_build_object('tier', reach.tier)
    FROM opengeni_private.vault_reach(context) reach
    JOIN vaults vault ON vault.id = reach.vault_id
    ORDER BY reach.tier, vault.name_key, vault.id;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION list_workspace_member_management_candidates(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  previous_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  result jsonb;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL
    OR nullif(pg_catalog.btrim(p_actor_subject_id), '') IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
  THEN
    RAISE EXCEPTION 'workspace member management authority required' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );

  IF NOT EXISTS (
    SELECT 1 FROM workspaces workspace
    WHERE workspace.id = p_workspace_id AND workspace.account_id = p_account_id
  ) THEN
    RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM organization_memberships membership
    WHERE membership.account_id = p_account_id
      AND membership.personal_workspace_id = p_workspace_id
  ) THEN
    RAISE EXCEPTION 'Personal workspace membership is owner-only' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM organization_memberships organization_administrator
    WHERE organization_administrator.account_id = p_account_id
      AND organization_administrator.subject_id = p_actor_subject_id
      AND organization_administrator.subject_id LIKE 'user:%'
      AND organization_administrator.status = 'active'
      AND organization_administrator.role IN ('owner', 'admin')
  ) AND NOT EXISTS (
    SELECT 1
    FROM organization_memberships organization_membership
    JOIN workspace_memberships workspace_membership
      ON workspace_membership.account_id = organization_membership.account_id
     AND workspace_membership.subject_id = organization_membership.subject_id
     AND workspace_membership.workspace_id = p_workspace_id
    WHERE organization_membership.account_id = p_account_id
      AND organization_membership.subject_id = p_actor_subject_id
      AND organization_membership.status = 'active'
      AND (
        workspace_membership.permissions ? 'members:manage'
        OR workspace_membership.permissions ? 'workspace:admin'
      )
  ) THEN
    RAISE EXCEPTION 'workspace member management authority required' USING ERRCODE = '42501';
  END IF;

  IF (
    SELECT count(*)
    FROM organization_memberships membership
    WHERE membership.account_id = p_account_id
      AND membership.status = 'active'
      AND membership.subject_id LIKE 'user:%'
      AND NOT EXISTS (
        SELECT 1 FROM workspace_memberships access
        WHERE access.account_id = p_account_id
          AND access.workspace_id = p_workspace_id
          AND access.subject_id = membership.subject_id
      )
  ) > 1000 THEN
    RAISE EXCEPTION 'workspace member candidate inventory exceeds the bounded projection'
      USING ERRCODE = '54000';
  END IF;

  SELECT coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'organizationMembershipId', membership.id,
      'subjectId', membership.subject_id,
      'name', auth_user.name,
      'email', auth_user.email,
      'organizationRole', membership.role
    ) ORDER BY lower(coalesce(auth_user.name, auth_user.email, membership.subject_id)), membership.id
  ), '[]'::jsonb) INTO result
  FROM organization_memberships membership
  LEFT JOIN auth_users auth_user
    ON membership.subject_id = 'user:' || auth_user.id
  WHERE membership.account_id = p_account_id
    AND membership.status = 'active'
    AND membership.subject_id LIKE 'user:%'
    AND NOT EXISTS (
      SELECT 1 FROM workspace_memberships access
      WHERE access.account_id = p_account_id
        AND access.workspace_id = p_workspace_id
        AND access.subject_id = membership.subject_id
    );

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', COALESCE(previous_lifecycle, ''), true
  );
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', COALESCE(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

CREATE FUNCTION live_session_turn_machine_consent(p_consent_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM session_turn_machine_consents consent
    JOIN sessions session ON session.id = consent.session_id
      AND session.account_id = consent.account_id AND session.workspace_id = consent.workspace_id
    JOIN organization_memberships owner ON owner.id = consent.owner_organization_membership_id
      AND owner.account_id = consent.account_id AND owner.subject_id = consent.consenting_subject_id
      AND owner.status = 'active' AND owner.revoked_at IS NULL
      AND owner.authorization_revision = consent.membership_authorization_revision
    JOIN enrollments enrollment ON enrollment.id = consent.enrollment_id
      AND enrollment.account_id = consent.account_id AND enrollment.authority_scope = 'user'
      AND enrollment.owner_organization_membership_id = owner.id
      AND enrollment.generation = consent.enrollment_generation
      AND enrollment.authority_id = consent.authority_id
      AND enrollment.status = 'active' AND enrollment.revoked_at IS NULL
    JOIN organization_user_resource_authorities authority ON authority.id = consent.authority_id
      AND authority.account_id = consent.account_id AND authority.organization_membership_id = owner.id
      AND authority.resource_kind = 'connected_machine' AND authority.resource_id = enrollment.id
      AND authority.generation = consent.authority_generation
      AND authority.status = 'active' AND authority.revoked_at IS NULL
    JOIN sandboxes sandbox ON sandbox.id = consent.sandbox_id
      AND sandbox.account_id = consent.account_id AND sandbox.enrollment_id = enrollment.id
    WHERE consent.id = p_consent_id
      AND consent.session_authority_epoch BETWEEN session.execution_authority_epoch AND session.authority_epoch
      AND (owner.personal_workspace_id = consent.workspace_id OR EXISTS (
        SELECT 1 FROM workspace_memberships membership
        WHERE membership.account_id = consent.account_id AND membership.workspace_id = consent.workspace_id
          AND membership.subject_id = owner.subject_id
      ))
  )
$$;

CREATE FUNCTION lock_live_native_original_origin_v2(p_scope jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      s sessions%ROWTYPE; t session_turns%ROWTYPE; a session_turn_attempts%ROWTYPE;
      m organization_memberships%ROWTYPE; control workspace_inference_controls%ROWTYPE;
      ancestor sessions%ROWTYPE;
      account_value uuid; workspace_value uuid; session_value uuid; turn_value uuid; attempt_value uuid;
      generation_value integer; route_value integer; member_key bigint; tenancy_key bigint;
      fenced_cap uuid; member_cap uuid; parent_value uuid; visited uuid[]; override_value bigint:=0;
      count_value integer:=0; count_json jsonb; basis text; key_name text;
      result jsonb:='{"kind":"fenced"}'::jsonb;
      keys constant text[]:=ARRAY['version','declarationId','planId','creatorId','accountId','workspaceId',
        'sessionId','turnId','attemptId','executionGeneration','triggerEventId','sandboxGroupId',
        'routeKind','routeTargetId','routeEpoch'];
    BEGIN
      IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object' OR NOT p_scope ?& keys
        OR p_scope-keys<>'{}'::jsonb OR p_scope->'version'<>'2'::jsonb
        OR p_scope->'routeKind'<>'"home"'::jsonb OR p_scope->'routeTargetId'<>'null'::jsonb
      THEN RETURN '{"kind":"unsupported","reason":"invalid_scope"}'::jsonb; END IF;
      FOREACH key_name IN ARRAY ARRAY['declarationId','planId','creatorId','accountId','workspaceId',
        'sessionId','turnId','attemptId','triggerEventId','sandboxGroupId'] LOOP
        IF jsonb_typeof(p_scope->key_name)<>'string' OR (p_scope->>key_name) !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN RETURN '{"kind":"unsupported","reason":"invalid_scope"}'::jsonb; END IF;
      END LOOP;
      FOREACH key_name IN ARRAY ARRAY['executionGeneration','routeEpoch'] LOOP
        IF jsonb_typeof(p_scope->key_name)<>'number' OR
          (p_scope->>key_name)::numeric<>trunc((p_scope->>key_name)::numeric) OR
          (p_scope->>key_name)::numeric NOT BETWEEN 0 AND 2147483647
        THEN RETURN '{"kind":"unsupported","reason":"invalid_scope"}'::jsonb; END IF;
      END LOOP;
      IF (p_scope->>'executionGeneration')::integer=0 OR p_scope->>'creatorId'=p_scope->>'attemptId'
        OR p_scope->>'creatorId'=p_scope->>'planId'
      THEN RETURN '{"kind":"unsupported","reason":"invalid_scope"}'::jsonb; END IF;
      account_value:=(p_scope->>'accountId')::uuid; workspace_value:=(p_scope->>'workspaceId')::uuid;
      session_value:=(p_scope->>'sessionId')::uuid; turn_value:=(p_scope->>'turnId')::uuid;
      attempt_value:=(p_scope->>'attemptId')::uuid;
      generation_value:=(p_scope->>'executionGeneration')::integer; route_value:=(p_scope->>'routeEpoch')::integer;
      IF account_value IS DISTINCT FROM opengeni_private.current_account_id()
        OR workspace_value IS DISTINCT FROM opengeni_private.current_workspace_id()
        OR nullif(current_setting('opengeni.subject_id',true),'') IS NULL
      THEN RETURN result; END IF;
      member_key:=hashtextextended('organization-membership:'||account_value::text,0);
      tenancy_key:=hashtextextended('session-tenancy:'||workspace_value::text,0);
      IF EXISTS (SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory'
        AND l.granted AND l.classid=((tenancy_key>>32)&4294967295)::oid
        AND l.objid=(tenancy_key&4294967295)::oid AND l.objsubid=1)
        AND NOT EXISTS (SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory'
          AND l.granted AND l.mode='ExclusiveLock' AND l.classid=((member_key>>32)&4294967295)::oid
          AND l.objid=(member_key&4294967295)::oid AND l.objsubid=1)
      THEN RAISE EXCEPTION 'native origin requires membership-before-tenancy entry' USING ERRCODE='25001'; END IF;
      PERFORM pg_advisory_xact_lock(member_key);
      PERFORM acquire_session_tenancy_fence(workspace_value);
      fenced_cap:=opengeni_private.open_session_tenancy_fenced_access({{schema_oid}}::oid);
      <<projection>>
      BEGIN
        PERFORM pg_advisory_xact_lock_shared(hashtextextended('workspace-control:'||workspace_value::text,0));
        SELECT * INTO control FROM workspace_inference_controls WHERE workspace_id=workspace_value
          AND account_id=account_value FOR SHARE;
        IF NOT FOUND THEN EXIT projection; END IF;
        PERFORM 1 FROM workspaces WHERE id=workspace_value AND account_id=account_value FOR KEY SHARE;
        IF NOT FOUND THEN EXIT projection; END IF;
        SELECT * INTO s FROM sessions WHERE id=session_value AND workspace_id=workspace_value
          AND account_id=account_value FOR NO KEY UPDATE;
        IF NOT FOUND THEN EXIT projection; END IF;
        PERFORM 1 FROM session_event_cursors WHERE workspace_id=workspace_value AND session_id=session_value FOR UPDATE;
        IF NOT FOUND THEN EXIT projection; END IF;
        SELECT * INTO t FROM session_turns WHERE id=turn_value AND workspace_id=workspace_value
          AND account_id=account_value AND session_id=session_value FOR UPDATE;
        IF NOT FOUND THEN EXIT projection; END IF;
        SELECT * INTO a FROM session_turn_attempts WHERE id=attempt_value AND workspace_id=workspace_value
          AND account_id=account_value AND session_id=session_value AND turn_id=turn_value FOR UPDATE;
        IF NOT FOUND THEN EXIT projection; END IF;
        IF s.status<>'running' OR s.admission_block IS NOT NULL OR s.active_turn_id IS DISTINCT FROM turn_value
          OR t.status<>'running' OR t.active_attempt_id IS DISTINCT FROM attempt_value
          OR t.execution_generation<>generation_value OR a.execution_generation<>generation_value
          OR t.trigger_event_id<>(p_scope->>'triggerEventId')::uuid
          OR s.sandbox_group_id<>(p_scope->>'sandboxGroupId')::uuid
          OR s.active_sandbox_id IS NOT NULL OR s.active_epoch<>route_value
          OR a.state NOT IN ('claimed','running') OR a.outcome IS NOT NULL
          OR a.closed_at IS NOT NULL OR a.quiesced_at IS NOT NULL
          OR a.authority_epoch IS NULL OR a.authority_visibility IS NULL
          OR a.authority_epoch NOT BETWEEN s.execution_authority_epoch AND s.authority_epoch
          OR NOT (a.authority_visibility=s.visibility OR (a.authority_visibility='user_private'
            AND s.visibility='workspace_shared' AND a.authority_epoch<s.authority_epoch))
          OR a.authority_owner_organization_membership_id IS DISTINCT FROM s.owner_organization_membership_id
          OR (a.authority_visibility='user_private' AND a.authority_owner_organization_membership_id IS NULL)
          OR EXISTS (SELECT 1 FROM session_attempt_interruptions i WHERE i.workspace_id=workspace_value
            AND i.session_id=session_value AND i.attempt_id=attempt_value AND i.state IN ('pending','delivered','acknowledged'))
        THEN EXIT projection; END IF;
        -- Same override ordering as projectEffectiveControl; control SHARE
        -- serializes all ancestry control writes, including Pause/Resume/Cancel.
        ancestor:=s; visited:=ARRAY[]::uuid[];
        LOOP
          IF ancestor.id=ANY(visited) OR cardinality(visited)>10000 THEN EXIT projection; END IF;
          visited:=array_append(visited,ancestor.id);
          IF ancestor.direct_control_state='paused' AND
            (ancestor.direct_pause_revision IS NULL OR override_value<=ancestor.direct_pause_revision)
          THEN EXIT projection; END IF;
          override_value:=greatest(override_value,coalesce(ancestor.subtree_run_override_revision,0));
          parent_value:=ancestor.parent_session_id;
          EXIT WHEN parent_value IS NULL;
          SELECT * INTO ancestor FROM sessions WHERE id=parent_value AND workspace_id=workspace_value AND account_id=account_value;
          IF NOT FOUND THEN EXIT projection; END IF;
        END LOOP;
        IF control.workspace_state='paused' AND
          (control.workspace_pause_revision IS NULL OR override_value<=control.workspace_pause_revision)
        THEN EXIT projection; END IF;
        IF EXISTS (SELECT 1 FROM session_pending_tool_calls WHERE workspace_id=workspace_value AND session_id=session_value)
          OR EXISTS (SELECT 1 FROM agent_run_states WHERE workspace_id=workspace_value AND session_id=session_value AND turn_id=turn_value)
          -- claimTurnAttempt publishes turn.started before establishTurnSandbox.
          -- It is lifecycle truth, not evidence that a model was dispatched.
          OR EXISTS (SELECT 1 FROM session_events WHERE workspace_id=workspace_value AND session_id=session_value
            AND turn_id=turn_value AND type='agent.model.request')
        THEN result:='{"kind":"unsupported","reason":"not_premodel"}'::jsonb; EXIT projection; END IF;
        IF t.initiating_human_subject_id IS NULL OR t.initiator_subject_id='unattributed-legacy'
          OR t.initiating_human_subject_id NOT LIKE 'user:%'
        THEN result:='{"kind":"unsupported","reason":"human_unavailable"}'::jsonb; EXIT projection; END IF;
        IF EXISTS (SELECT 1 FROM external_link_turn_authorities WHERE account_id=account_value
          AND workspace_id=workspace_value AND turn_id=turn_value)
        THEN result:='{"kind":"unsupported","reason":"external_authority"}'::jsonb; EXIT projection; END IF;
        IF jsonb_typeof(t.metadata) IS DISTINCT FROM 'object' THEN EXIT projection; END IF;
        IF t.metadata ? 'providerRecoveryCount' THEN
          count_json:=t.metadata->'providerRecoveryCount';
          IF jsonb_typeof(count_json) IS DISTINCT FROM 'number' THEN EXIT projection; END IF;
          IF count_json::numeric<>trunc(count_json::numeric) OR count_json::numeric NOT BETWEEN 0 AND 5
          THEN EXIT projection; END IF;
          count_value:=count_json::integer;
        END IF;
        member_cap:=gen_random_uuid();
        INSERT INTO opengeni_private.modal_native_origin_read_capabilities VALUES
          (member_cap,{{schema_oid}}::oid,pg_backend_pid(),pg_current_xact_id(),account_value,workspace_value,
           session_value,turn_value,attempt_value,generation_value,t.initiating_human_subject_id);
        SELECT * INTO m FROM organization_memberships WHERE account_id=account_value
          AND subject_id=t.initiating_human_subject_id AND status='active' AND revoked_at IS NULL;
        IF NOT FOUND THEN EXIT projection; END IF;
        IF m.personal_workspace_id=workspace_value THEN basis:='personal_workspace';
        ELSIF EXISTS (SELECT 1 FROM workspace_memberships WHERE account_id=account_value
          AND workspace_id=workspace_value AND subject_id=t.initiating_human_subject_id)
        THEN basis:='workspace_membership'; ELSE EXIT projection; END IF;
        IF s.visibility='user_private' AND (s.owner_subject_id IS DISTINCT FROM t.initiating_human_subject_id
          OR s.owner_organization_membership_id IS DISTINCT FROM m.id) THEN EXIT projection; END IF;
        result:=jsonb_build_object('kind','live','projection',jsonb_build_object(
          'version',1,'scope',p_scope,
          'initiator',jsonb_build_object('kind',t.initiator_kind,'subjectId',t.initiator_subject_id,
            'initiatingHumanSubjectId',t.initiating_human_subject_id),
          'membership',jsonb_build_object('id',m.id,'authorizationRevision',m.authorization_revision::text,'basis',basis),
          'acceptedAuthority',jsonb_build_object('epoch',a.authority_epoch,'visibility',a.authority_visibility,
            'ownerOrganizationMembershipId',a.authority_owner_organization_membership_id),
          'currentAuthority',jsonb_build_object('epoch',s.authority_epoch,'executionEpoch',s.execution_authority_epoch,
            'visibility',s.visibility,'ownerSubjectId',s.owner_subject_id,'ownerOrganizationMembershipId',s.owner_organization_membership_id),
          'control',jsonb_build_object('workspaceRevision',control.revision::text,'sessionVersion',s.control_version::text),
          'execution',jsonb_build_object('workflowId',a.temporal_workflow_id,'workflowRunId',a.temporal_workflow_run_id,
            'activityId',a.temporal_activity_id),
          'providerRecoveryCount',count_value,'checkedAt',clock_timestamp()));
      END projection;
      DELETE FROM opengeni_private.modal_native_origin_read_capabilities WHERE capability_id=member_cap;
      PERFORM opengeni_private.close_session_tenancy_fenced_access(fenced_cap);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      -- The function's exception subtransaction rolls back its own capabilities
      -- and locks. Preserve any earlier caller capability; propagate uncertainty.
      RAISE;
    END
    $_$;

CREATE FUNCTION lock_nested_agent_depth_configuration() RETURNS TABLE(max_nested_agent_depth integer, policy_source text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
      SELECT "max_nested_agent_depth", "policy_source"
      FROM {{schema}}."nested_agent_depth_configuration"
      WHERE "singleton" FOR SHARE
    $$;

CREATE FUNCTION lock_session_tenancy_activation_boundary() RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'session-tenancy-canonical-boundary:v1', 0
  ))
$$;

COMMENT ON FUNCTION lock_session_tenancy_activation_boundary() IS 'Owner-only deployment boundary fence shared by operator activation and atomic greenfield activation.';

CREATE FUNCTION lookup_external_identity(p_account uuid, p_actor text, p_source text, p_external_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE result jsonb; previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  PERFORM opengeni_private.external_workspace_service_permissions(p_account, p_actor);
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'external_identity_provisioning', true);
  SELECT jsonb_build_object('found', true, 'subjectId', i.subject_id,
    'organizationMembershipId', m.id, 'identityStatus', i.status,
    'identityAuthorizationRevision', i.authorization_revision,
    'membershipStatus', m.status, 'membershipAuthorizationRevision', m.authorization_revision)
  INTO result FROM external_identities i JOIN organization_memberships m
    ON m.account_id = i.account_id AND m.id = i.organization_membership_id AND m.subject_id = i.subject_id
  WHERE i.account_id = p_account AND i.source = p_source AND i.external_id = p_external_id;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  RETURN coalesce(result, '{"found":false}'::jsonb);
END $$;

CREATE FUNCTION maintain_session_usage_limits(p_limit integer, p_budget integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  target record; opened integer; tenant_opened integer; processed integer := 0;
  failed integer := 0; resolved integer := 0; v_limit integer := greatest(1, least(coalesce(p_limit, 20), 100));
  previous_account text := current_setting('opengeni.account_id', true);
  previous_workspace text := current_setting('opengeni.workspace_id', true);
  previous_subject text := current_setting('opengeni.subject_id', true);
  v_data_schema text := (SELECT n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE c.oid='workspaces'::regclass);
  error_codes jsonb := '{}'::jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM opengeni_private.usage_maintenance_due
    WHERE data_schema=v_data_schema AND kind IN ('session_import','session_receipt')
      AND due_at<=clock_timestamp()) THEN
    RETURN jsonb_build_object('processed',0,'failed',0,'errors','{}'::jsonb,'resolvedLost',0);
  END IF;
  INSERT INTO opengeni_private.session_usage_limit_capabilities VALUES(pg_backend_pid(),pg_current_xact_id(),
    v_data_schema,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000')
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS opened = ROW_COUNT;
  -- Private-session visibility does not restrict this content-free work.
  PERFORM set_config('opengeni.subject_id', '', true);
  FOR target IN SELECT account_id, workspace_id, root_session_id
    FROM opengeni_private.session_usage_limit_roots
    WHERE history_state = 'preparing' AND import_next_at <= clock_timestamp()
    ORDER BY import_next_at, workspace_id, root_session_id
    LIMIT v_limit
  LOOP
    PERFORM set_config('opengeni.account_id', target.account_id::text, true);
    PERFORM set_config('opengeni.workspace_id', target.workspace_id::text, true);
    INSERT INTO opengeni_private.session_usage_limit_capabilities VALUES(pg_backend_pid(),pg_current_xact_id(),
      v_data_schema,target.account_id,target.workspace_id) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS tenant_opened = ROW_COUNT;
    BEGIN
      PERFORM 1 FROM opengeni_private.session_usage_limit_roots
        WHERE workspace_id = target.workspace_id AND root_session_id = target.root_session_id
          AND history_state = 'preparing'
        FOR NO KEY UPDATE SKIP LOCKED;
      IF FOUND THEN
        PERFORM session_usage_limit_import_step(target.account_id, target.workspace_id,
          target.root_session_id, p_budget);
        processed := processed + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      failed := failed + 1;
      error_codes := jsonb_set(error_codes, ARRAY[SQLSTATE],
        to_jsonb(coalesce((error_codes->>SQLSTATE)::integer, 0) + 1));
      UPDATE opengeni_private.session_usage_limit_roots SET
        import_attempts = import_attempts + 1,
        import_next_at = clock_timestamp()
          + least(interval '1 hour', interval '1 minute' * power(2, least(import_attempts, 6))),
        import_error = SQLSTATE
      WHERE workspace_id = target.workspace_id AND root_session_id = target.root_session_id
        AND history_state = 'preparing';
    END;
    IF tenant_opened = 1 THEN DELETE FROM opengeni_private.session_usage_limit_capabilities
      WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
        AND data_schema=v_data_schema AND workspace_id=target.workspace_id; END IF;
  END LOOP;
  FOR target IN SELECT account_id, workspace_id, root_session_id, source_id
    FROM opengeni_private.session_usage_limit_receipts
    WHERE status = 'pending' AND recorded_at < clock_timestamp() - interval '30 minutes'
    ORDER BY recorded_at LIMIT v_limit
  LOOP
    PERFORM set_config('opengeni.account_id', target.account_id::text, true);
    PERFORM set_config('opengeni.workspace_id', target.workspace_id::text, true);
    INSERT INTO opengeni_private.session_usage_limit_capabilities VALUES(pg_backend_pid(),pg_current_xact_id(),
      v_data_schema,target.account_id,target.workspace_id) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS tenant_opened = ROW_COUNT;
    PERFORM 1 FROM opengeni_private.session_usage_limit_roots
      WHERE workspace_id = target.workspace_id AND root_session_id = target.root_session_id
      FOR NO KEY UPDATE SKIP LOCKED;
    IF FOUND THEN
      UPDATE opengeni_private.session_usage_limit_receipts SET status = 'unpriced', fenced = false
        WHERE workspace_id = target.workspace_id AND source_id = target.source_id
          AND status = 'pending';
      IF FOUND THEN
        UPDATE opengeni_private.session_usage_limit_roots SET unpriced_calls = unpriced_calls + 1,
          usage_revision = usage_revision + 1, updated_at = clock_timestamp()
        WHERE workspace_id = target.workspace_id AND root_session_id = target.root_session_id;
        resolved := resolved + 1;
      END IF;
    END IF;
    IF tenant_opened = 1 THEN DELETE FROM opengeni_private.session_usage_limit_capabilities
      WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
        AND data_schema=v_data_schema AND workspace_id=target.workspace_id; END IF;
  END LOOP;
  IF opened = 1 THEN DELETE FROM opengeni_private.session_usage_limit_capabilities
    WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
      AND data_schema=v_data_schema
      AND workspace_id='00000000-0000-0000-0000-000000000000'::uuid; END IF;
  PERFORM set_config('opengeni.account_id', coalesce(previous_account, ''), true);
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace, ''), true);
  PERFORM set_config('opengeni.subject_id', coalesce(previous_subject, ''), true);
  RETURN jsonb_build_object('processed', processed, 'failed', failed, 'errors', error_codes,
    'resolvedLost', resolved);
END $$;

CREATE FUNCTION maintain_usage_allowances(p_limit integer, p_member_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  target record; saved opengeni_private.workspace_usage_allowances%ROWTYPE; p record; member_row record;
  opened integer; tenant_opened integer; processed integer:=0; seen integer;
  last_subject text; previous_account text:=current_setting('opengeni.account_id',true);
  previous_workspace text:=current_setting('opengeni.workspace_id',true);
  v_data_schema text:=(SELECT n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE c.oid='workspaces'::regclass);
  member_limit integer:=greatest(1,least(coalesce(p_member_limit,100),200));
BEGIN
  IF NOT EXISTS (SELECT 1 FROM opengeni_private.usage_maintenance_due
    WHERE data_schema=v_data_schema AND kind='allowance' AND due_at<=clock_timestamp())
    AND NOT EXISTS (SELECT 1 FROM opengeni_private.usage_maintenance_due projection
      JOIN opengeni_private.usage_allowance_membership_changes changes
        ON changes.data_schema=projection.data_schema AND changes.account_id=projection.account_id
      WHERE projection.data_schema=v_data_schema AND projection.kind='allowance'
        AND projection.membership_ready AND changes.revision>projection.seen_membership_revision) THEN
    RETURN 0;
  END IF;
  INSERT INTO opengeni_private.usage_allowance_capabilities VALUES(pg_backend_pid(),pg_current_xact_id(),
    v_data_schema,'00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000000000')
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS opened=ROW_COUNT;
  FOR target IN SELECT policy.account_id,policy.workspace_id,
      coalesce(changes.revision,0) AS membership_target_revision
    FROM opengeni_private.workspace_usage_allowances policy
    LEFT JOIN opengeni_private.usage_allowance_membership_changes changes
      ON changes.data_schema=v_data_schema AND changes.account_id=policy.account_id
    WHERE policy.config IS NOT NULL AND (policy.maintenance_next_at<=clock_timestamp()
      OR (policy.maintenance_error IS NULL AND policy.maintenance_membership_revision<coalesce(changes.revision,0)))
    ORDER BY least(policy.maintenance_next_at,CASE WHEN policy.maintenance_error IS NULL
      AND policy.maintenance_membership_revision<coalesce(changes.revision,0) THEN changes.changed_at END),
      policy.workspace_id LIMIT greatest(1,least(coalesce(p_limit,20),100))
  LOOP
    PERFORM set_config('opengeni.account_id',target.account_id::text,true);
    PERFORM set_config('opengeni.workspace_id',target.workspace_id::text,true);
    PERFORM 1 FROM workspaces WHERE id=target.workspace_id AND account_id=target.account_id FOR KEY SHARE;
    IF NOT FOUND THEN CONTINUE; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('usage-allowance:'||target.workspace_id::text,0));
    INSERT INTO opengeni_private.usage_allowance_capabilities VALUES(pg_backend_pid(),pg_current_xact_id(),
      v_data_schema,target.account_id,target.workspace_id) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS tenant_opened=ROW_COUNT;
    BEGIN
      SELECT * INTO saved FROM opengeni_private.workspace_usage_allowances WHERE workspace_id=target.workspace_id;
      IF saved.config IS NOT NULL AND (saved.maintenance_next_at<=clock_timestamp()
        OR (saved.maintenance_error IS NULL AND saved.maintenance_membership_revision<target.membership_target_revision)) THEN
        IF saved.maintenance_membership_revision<target.membership_target_revision THEN
          saved.maintenance_cursor:=NULL;
        END IF;
        SELECT * INTO p FROM usage_allowance_effective_period(target.workspace_id,saved.config,clock_timestamp());
        IF saved.active_period_key IS DISTINCT FROM p.period_key THEN
          UPDATE opengeni_private.workspace_allowance_periods SET closed_at=coalesce(saved.active_end_at,clock_timestamp())
            WHERE workspace_id=target.workspace_id AND period_key=saved.active_period_key AND closed_at IS NULL;
          saved.maintenance_cursor:=NULL;
        END IF;
        UPDATE opengeni_private.workspace_usage_allowances SET active_period_key=p.period_key,active_start_at=p.start_at,
          active_end_at=p.end_at WHERE workspace_id=target.workspace_id;
        PERFORM capture_usage_allowance_period(target.account_id,target.workspace_id,saved.config,clock_timestamp());
        INSERT INTO opengeni_private.workspace_allowance_counters(account_id,workspace_id,period_key,subject_id)
          VALUES(target.account_id,target.workspace_id,p.period_key,'') ON CONFLICT DO NOTHING;
        PERFORM emit_usage_allowance_notifications(target.account_id,target.workspace_id,saved.config,p.period_key,p.end_at,NULL);
        seen:=0; last_subject:=NULL;
        FOR member_row IN SELECT subject_id FROM usage_allowance_members(target.account_id,target.workspace_id)
          WHERE saved.maintenance_cursor IS NULL OR subject_id>saved.maintenance_cursor
          ORDER BY subject_id LIMIT member_limit+1
        LOOP
          seen:=seen+1;
          EXIT WHEN seen>member_limit;
          INSERT INTO opengeni_private.workspace_allowance_counters(account_id,workspace_id,period_key,subject_id)
            VALUES(target.account_id,target.workspace_id,p.period_key,member_row.subject_id) ON CONFLICT DO NOTHING;
          PERFORM emit_usage_allowance_notifications(target.account_id,target.workspace_id,saved.config,
            p.period_key,p.end_at,member_row.subject_id);
          last_subject:=member_row.subject_id;
        END LOOP;
        UPDATE opengeni_private.workspace_usage_allowances SET membership_revision=CASE WHEN seen>member_limit THEN saved.membership_revision ELSE greatest(saved.membership_revision,target.membership_target_revision) END,
          maintenance_membership_revision=greatest(saved.maintenance_membership_revision,target.membership_target_revision),
          maintenance_cursor=CASE WHEN seen>member_limit THEN last_subject END,
          maintenance_next_at=CASE WHEN seen>member_limit
            THEN clock_timestamp()+interval '1 second'
            ELSE least(p.end_at,(SELECT min(expires_at)
              FROM opengeni_private.workspace_allowance_grants
              WHERE workspace_id=target.workspace_id AND remaining>0 AND expires_at>clock_timestamp())) END,
          maintenance_error=NULL WHERE workspace_id=target.workspace_id;
        processed:=processed+1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      UPDATE opengeni_private.workspace_usage_allowances SET maintenance_next_at=clock_timestamp()+interval '1 minute',
        maintenance_error=SQLSTATE WHERE workspace_id=target.workspace_id;
    END;
    IF tenant_opened=1 THEN DELETE FROM opengeni_private.usage_allowance_capabilities
      WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
        AND usage_allowance_capabilities.data_schema=v_data_schema
        AND workspace_id=target.workspace_id; END IF;
  END LOOP;
  IF opened=1 THEN DELETE FROM opengeni_private.usage_allowance_capabilities
    WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
      AND usage_allowance_capabilities.data_schema=v_data_schema
      AND workspace_id='00000000-0000-0000-0000-000000000000'::uuid; END IF;
  PERFORM set_config('opengeni.account_id',coalesce(previous_account,''),true);
  PERFORM set_config('opengeni.workspace_id',coalesce(previous_workspace,''),true);
  RETURN processed;
END $$;

CREATE FUNCTION managed_auth_actor_mutation_fence(p_authority_hash text, p_actor_epoch bigint, p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_actor_epoch < 1 OR p_request_id IS NULL
      THEN RAISE EXCEPTION 'managed auth mutation fence is invalid' USING ERRCODE = '22023'; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT * INTO set_row FROM managed_auth_session_sets
      WHERE authority_hash = p_authority_hash AND revoked_at IS NULL FOR UPDATE;
      IF NOT FOUND OR set_row.actor_epoch <> p_actor_epoch OR NOT EXISTS (
        SELECT 1 FROM managed_auth_actor_mutation_leases lease
        WHERE lease.session_set_id = set_row.id AND lease.request_id = p_request_id
          AND lease.actor_epoch = p_actor_epoch AND lease.expires_at > pg_catalog.clock_timestamp()
      ) THEN
        RAISE EXCEPTION 'managed auth actor changed before fenced mutation' USING ERRCODE = '40001';
      END IF;
      DELETE FROM managed_auth_actor_mutation_leases
      WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
      IF EXISTS (
        SELECT 1 FROM managed_auth_actor_mutation_leases lease
        WHERE lease.session_set_id = set_row.id AND lease.actor_epoch = p_actor_epoch
          AND lease.request_id <> p_request_id
      ) THEN
        RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.managed_auth_actor_mutation_request_id', p_request_id::text, true
      );
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN true;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_actor_mutation_lease_acquire(p_authority_hash text, p_actor_epoch bigint, p_request_id uuid, p_lease_seconds integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      lease_expiry timestamptz;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_actor_epoch < 1
        OR p_request_id IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 900
      THEN RAISE EXCEPTION 'managed auth mutation lease is invalid' USING ERRCODE = '22023'; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT session_set.* INTO set_row
      FROM managed_auth_session_sets session_set
      INNER JOIN managed_auth_browser_installations installation
        ON installation.id = session_set.installation_id
      WHERE session_set.authority_hash = p_authority_hash
        AND session_set.revoked_at IS NULL AND installation.revoked_at IS NULL
        AND session_set.idle_expires_at > pg_catalog.clock_timestamp()
        AND session_set.absolute_expires_at > pg_catalog.clock_timestamp()
        AND installation.idle_expires_at > pg_catalog.clock_timestamp()
        AND installation.absolute_expires_at > pg_catalog.clock_timestamp()
      FOR UPDATE OF session_set, installation;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501';
      END IF;
      IF set_row.actor_epoch <> p_actor_epoch THEN
        RAISE EXCEPTION 'managed auth actor changed before mutation lease'
          USING ERRCODE = '40001';
      END IF;
      IF set_row.selected_slot_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM managed_auth_login_slots slot
        WHERE slot.id = set_row.selected_slot_id AND slot.session_set_id = set_row.id
          AND slot.status = 'active' AND slot.auth_session_id IS NOT NULL
      ) THEN
        RAISE EXCEPTION 'managed auth selected actor is unavailable' USING ERRCODE = '42501';
      END IF;
      DELETE FROM managed_auth_actor_mutation_leases
      WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
      lease_expiry := pg_catalog.clock_timestamp() + pg_catalog.make_interval(secs => p_lease_seconds);
      INSERT INTO managed_auth_actor_mutation_leases (
        session_set_id, request_id, actor_epoch, acquired_at, expires_at
      ) VALUES (
        set_row.id, p_request_id, p_actor_epoch, pg_catalog.clock_timestamp(), lease_expiry
      )
      ON CONFLICT (session_set_id, request_id) DO UPDATE SET
        actor_epoch = EXCLUDED.actor_epoch,
        acquired_at = EXCLUDED.acquired_at,
        expires_at = EXCLUDED.expires_at
      WHERE managed_auth_actor_mutation_leases.actor_epoch = EXCLUDED.actor_epoch;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'managed auth mutation lease identity changed' USING ERRCODE = '40001';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN lease_expiry;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_actor_mutation_lease_release(p_authority_hash text, p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      released boolean;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_request_id IS NULL THEN RETURN false; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      DELETE FROM managed_auth_actor_mutation_leases lease
      USING managed_auth_session_sets session_set
      WHERE lease.session_set_id = session_set.id
        AND session_set.authority_hash = p_authority_hash
        AND lease.request_id = p_request_id;
      released := FOUND;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN released;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_actor_mutation_lease_validate(p_authority_hash text, p_actor_epoch bigint, p_request_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      valid boolean := false;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_actor_epoch < 1 OR p_request_id IS NULL
      THEN RETURN false; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT session_set.* INTO set_row
      FROM managed_auth_session_sets session_set
      INNER JOIN managed_auth_browser_installations installation
        ON installation.id = session_set.installation_id
      WHERE session_set.authority_hash = p_authority_hash
      FOR UPDATE OF session_set, installation;
      IF FOUND THEN
        SELECT set_row.revoked_at IS NULL
          AND set_row.actor_epoch = p_actor_epoch
          AND set_row.idle_expires_at > pg_catalog.clock_timestamp()
          AND set_row.absolute_expires_at > pg_catalog.clock_timestamp()
          AND installation.revoked_at IS NULL
          AND installation.idle_expires_at > pg_catalog.clock_timestamp()
          AND installation.absolute_expires_at > pg_catalog.clock_timestamp()
          AND EXISTS (
            SELECT 1 FROM managed_auth_actor_mutation_leases lease
            WHERE lease.session_set_id = set_row.id
              AND lease.request_id = p_request_id
              AND lease.actor_epoch = p_actor_epoch
              AND lease.expires_at > pg_catalog.clock_timestamp()
          )
        INTO valid
        FROM managed_auth_browser_installations installation
        WHERE installation.id = set_row.installation_id;
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN coalesce(valid, false);
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_adopted_session_snapshot(p_auth_session_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      snapshot jsonb;
      selected jsonb;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_auth_session_id IS NULL OR pg_catalog.length(p_auth_session_id) NOT BETWEEN 1 AND 255
      THEN RETURN NULL; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT session_set.* INTO set_row
      FROM managed_auth_login_slots slot
      INNER JOIN managed_auth_session_sets session_set ON session_set.id = slot.session_set_id
      WHERE slot.auth_session_id = p_auth_session_id AND slot.status <> 'revoked';
      IF NOT FOUND THEN
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        RETURN NULL;
      END IF;
      snapshot := managed_auth_session_set_snapshot(
        set_row.authority_hash, 'dual', true, false, true
      );
      selected := CASE
        WHEN snapshot->'selected'->>'authSessionId' = p_auth_session_id
        THEN snapshot->'selected' ELSE NULL END;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN pg_catalog.jsonb_build_object(
        'authorityHash', set_row.authority_hash,
        'actorEpoch', coalesce(snapshot->'projection'->>'actorEpoch', set_row.actor_epoch::text),
        'selected', selected
      );
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $$;

CREATE FUNCTION managed_auth_expired_session_set_reap(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      retired integer := 0;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
      previous_canonical_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
      previous_purge_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_purge', true
      );
    BEGIN
      IF p_limit NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION 'managed auth expired-set reap limit is invalid' USING ERRCODE = '22023';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
      FOR set_row IN
        SELECT session_set.*
        FROM managed_auth_session_sets session_set
        INNER JOIN managed_auth_browser_installations installation
          ON installation.id = session_set.installation_id
        WHERE session_set.revoked_at IS NULL
          AND (
            session_set.idle_expires_at <= pg_catalog.clock_timestamp()
            OR session_set.absolute_expires_at <= pg_catalog.clock_timestamp()
            OR installation.revoked_at IS NOT NULL
            OR installation.idle_expires_at <= pg_catalog.clock_timestamp()
            OR installation.absolute_expires_at <= pg_catalog.clock_timestamp()
          )
        ORDER BY session_set.absolute_expires_at, session_set.id
        FOR UPDATE OF session_set, installation SKIP LOCKED
        LIMIT p_limit
      LOOP
        DELETE FROM managed_auth_actor_mutation_leases
        WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
        IF EXISTS (
          SELECT 1 FROM managed_auth_actor_mutation_leases lease
          WHERE lease.session_set_id = set_row.id AND lease.expires_at > pg_catalog.clock_timestamp()
        ) THEN CONTINUE; END IF;
        IF NOT EXISTS (
          SELECT 1 FROM managed_auth_login_slots slot WHERE slot.session_set_id = set_row.id
        ) THEN
          UPDATE managed_auth_login_transactions SET
            status = 'cancelled', consumed_at = coalesce(
              consumed_at, pg_catalog.clock_timestamp()
            )
          WHERE session_set_id = set_row.id AND status = 'pending'
            AND expires_at <= pg_catalog.clock_timestamp();
          IF NOT EXISTS (
            SELECT 1 FROM managed_auth_login_transactions
            WHERE session_set_id = set_row.id AND status = 'pending'
          ) THEN
            PERFORM pg_catalog.set_config(
              'opengeni.managed_auth_session_set_purge', 'active', true
            );
            DELETE FROM auth_sessions auth_session
            USING managed_auth_login_transactions login_transaction
            WHERE login_transaction.session_set_id = set_row.id
              AND auth_session.managed_auth_login_transaction_id = login_transaction.id;
            DELETE FROM managed_auth_login_transactions WHERE session_set_id = set_row.id;
            DELETE FROM managed_auth_login_return_intents WHERE session_set_id = set_row.id;
            DELETE FROM managed_auth_session_set_operations WHERE session_set_id = set_row.id;
            DELETE FROM managed_auth_session_sets WHERE id = set_row.id;
            DELETE FROM managed_auth_browser_installations WHERE id = set_row.installation_id;
            PERFORM pg_catalog.set_config(
              'opengeni.managed_auth_session_set_purge',
              CASE WHEN previous_purge_marker IS NULL THEN '' ELSE previous_purge_marker END, true
            );
            retired := retired + 1;
            CONTINUE;
          END IF;
        END IF;
        DELETE FROM auth_sessions auth_session USING managed_auth_login_slots slot
        WHERE slot.session_set_id = set_row.id AND slot.status <> 'revoked'
          AND auth_session.id = slot.auth_session_id;
        UPDATE managed_auth_login_slots SET
          auth_session_id = NULL, status = 'revoked',
          revoked_at = coalesce(revoked_at, pg_catalog.clock_timestamp()),
          updated_at = pg_catalog.clock_timestamp()
        WHERE session_set_id = set_row.id AND status <> 'revoked';
        UPDATE managed_auth_session_sets SET
          revoked_at = coalesce(revoked_at, pg_catalog.clock_timestamp()),
          selected_slot_id = NULL, state = 'actor_change_required',
          updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id;
        UPDATE managed_auth_browser_installations SET
          revoked_at = coalesce(revoked_at, pg_catalog.clock_timestamp()),
          last_seen_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.installation_id;
        retired := retired + 1;
      END LOOP;
      -- Begin-transaction locks a retained set before the global/client/set
      -- admission rows. Keep reaping in that same direction: never retain a
      -- rate-row lock while attempting to acquire a session-set lock.
      WITH victims AS (
        SELECT scope_kind, scope_hash FROM managed_auth_login_transaction_rate_limits
        WHERE expires_at <= pg_catalog.clock_timestamp()
        ORDER BY expires_at, scope_kind, scope_hash
        FOR UPDATE SKIP LOCKED LIMIT p_limit
      )
      DELETE FROM managed_auth_login_transaction_rate_limits rate_limit USING victims
      WHERE rate_limit.scope_kind = victims.scope_kind
        AND rate_limit.scope_hash = victims.scope_hash;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_purge', CASE WHEN previous_purge_marker IS NULL THEN '' ELSE previous_purge_marker END, true);
      RETURN retired;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_purge', CASE WHEN previous_purge_marker IS NULL THEN '' ELSE previous_purge_marker END, true);
      RAISE;
    END;
    $$;

CREATE FUNCTION managed_auth_isolated_session_reap(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      reaped integer := 0;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
      previous_canonical_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
    BEGIN
      IF p_limit NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION 'managed auth orphan reap limit is invalid' USING ERRCODE = '22023';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
      WITH victims AS (
        SELECT auth_session.id
        FROM auth_sessions auth_session
        LEFT JOIN managed_auth_login_transactions login_transaction
          ON login_transaction.id = auth_session.managed_auth_login_transaction_id
        WHERE NOT EXISTS (
            SELECT 1 FROM managed_auth_login_slots slot
            WHERE slot.auth_session_id = auth_session.id AND slot.status <> 'revoked'
          )
          AND (
            auth_session.expires_at <= pg_catalog.clock_timestamp()
            OR (
              auth_session.managed_auth_login_transaction_id IS NOT NULL
              AND (
                login_transaction.id IS NULL OR login_transaction.status <> 'pending'
                OR login_transaction.expires_at <= pg_catalog.clock_timestamp()
              )
            )
          )
        ORDER BY auth_session.created_at, auth_session.id
        FOR UPDATE OF auth_session SKIP LOCKED
        LIMIT p_limit
      ), deleted AS (
        DELETE FROM auth_sessions auth_session USING victims
        WHERE auth_session.id = victims.id
        RETURNING auth_session.id
      )
      SELECT count(*)::integer INTO reaped FROM deleted;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RETURN reaped;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RAISE;
    END;
    $$;

CREATE FUNCTION managed_auth_login_transaction_rate_limit_take(p_client_scope_hash text, p_set_scope_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      rate_window timestamptz;
      set_rate_window timestamptz;
      global_attempts integer;
      client_attempts integer;
      set_attempts integer;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_client_scope_hash !~ '^[0-9a-f]{64}$'
        OR p_set_scope_hash !~ '^[0-9a-f]{64}$'
      THEN
        RAISE EXCEPTION 'managed auth login-transaction rate scope is invalid'
          USING ERRCODE = '22023';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      rate_window := pg_catalog.date_bin(
        interval '10 minutes', pg_catalog.clock_timestamp(),
        timestamptz '2001-01-01 00:00:00+00'
      );
      set_rate_window := pg_catalog.date_bin(
        interval '1 day', pg_catalog.clock_timestamp(),
        timestamptz '2001-01-01 00:00:00+00'
      );
      INSERT INTO managed_auth_login_transaction_rate_limits (
        scope_kind, scope_hash, window_started_at, attempt_count, expires_at
      ) VALUES (
        'global', pg_catalog.repeat('0', 64), rate_window, 1,
        rate_window + interval '20 minutes'
      )
      ON CONFLICT (scope_kind, scope_hash) DO UPDATE SET
        window_started_at = EXCLUDED.window_started_at,
        attempt_count = CASE
          WHEN managed_auth_login_transaction_rate_limits.window_started_at = EXCLUDED.window_started_at
          THEN managed_auth_login_transaction_rate_limits.attempt_count + 1 ELSE 1 END,
        expires_at = EXCLUDED.expires_at
      RETURNING attempt_count INTO global_attempts;
      IF global_attempts > 500 THEN
        RAISE EXCEPTION 'managed auth global login-transaction rate limit exceeded'
          USING ERRCODE = 'P0004';
      END IF;

      INSERT INTO managed_auth_login_transaction_rate_limits (
        scope_kind, scope_hash, window_started_at, attempt_count, expires_at
      ) VALUES (
        'client', p_client_scope_hash, rate_window, 1, rate_window + interval '20 minutes'
      )
      ON CONFLICT (scope_kind, scope_hash) DO UPDATE SET
        window_started_at = EXCLUDED.window_started_at,
        attempt_count = CASE
          WHEN managed_auth_login_transaction_rate_limits.window_started_at = EXCLUDED.window_started_at
          THEN managed_auth_login_transaction_rate_limits.attempt_count + 1 ELSE 1 END,
        expires_at = EXCLUDED.expires_at
      RETURNING attempt_count INTO client_attempts;
      IF client_attempts > 8 THEN
        RAISE EXCEPTION 'managed auth client login-transaction rate limit exceeded'
          USING ERRCODE = 'P0004';
      END IF;

      INSERT INTO managed_auth_login_transaction_rate_limits (
        scope_kind, scope_hash, window_started_at, attempt_count, expires_at
      ) VALUES (
        'set', p_set_scope_hash, set_rate_window, 1, set_rate_window + interval '2 days'
      )
      ON CONFLICT (scope_kind, scope_hash) DO UPDATE SET
        window_started_at = EXCLUDED.window_started_at,
        attempt_count = CASE
          WHEN managed_auth_login_transaction_rate_limits.window_started_at = EXCLUDED.window_started_at
          THEN managed_auth_login_transaction_rate_limits.attempt_count + 1 ELSE 1 END,
        expires_at = EXCLUDED.expires_at
      RETURNING attempt_count INTO set_attempts;
      IF set_attempts > 16 THEN
        RAISE EXCEPTION 'managed auth session-set login-transaction rate limit exceeded'
          USING ERRCODE = 'P0004';
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.managed_auth_session_set_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
      );
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.managed_auth_session_set_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
      );
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_exact_binding_stamp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      exact_binding_id uuid;
      exact_binding_revision bigint;
      binding_count integer;
      previous_canonical_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
    BEGIN
      PERFORM pg_catalog.set_config(
        'opengeni.canonical_human_identity_lifecycle', 'active', true
      );
      IF NEW.login_binding_id IS NULL THEN
        SELECT min(binding.id::text)::uuid, min(binding.revision), count(*)::integer
        INTO exact_binding_id, exact_binding_revision, binding_count
        FROM auth_identities auth_identity
        INNER JOIN canonical_human_login_bindings binding
          ON binding.identity_id = NEW.identity_id
         AND binding.provider_id = lower(auth_identity.provider_id)
         AND binding.provider_account_id = auth_identity.account_id
         AND binding.status IN ('active', 'recovery_pending')
        WHERE auth_identity.user_id = NEW.user_id
          AND lower(auth_identity.provider_id) = 'credential';
      ELSE
        SELECT min(binding.id::text)::uuid, min(binding.revision), count(*)::integer
        INTO exact_binding_id, exact_binding_revision, binding_count
        FROM auth_identities auth_identity
        INNER JOIN canonical_human_login_bindings binding
          ON binding.id = NEW.login_binding_id
         AND binding.identity_id = NEW.identity_id
         AND binding.provider_id = lower(auth_identity.provider_id)
         AND binding.provider_account_id = auth_identity.account_id
         AND binding.status IN ('active', 'recovery_pending')
        WHERE auth_identity.user_id = NEW.user_id;
      END IF;
      IF binding_count <> 1 OR exact_binding_id IS NULL OR exact_binding_revision IS NULL THEN
        RAISE EXCEPTION 'auth session must prove exactly one login binding'
          USING ERRCODE = '42501';
      END IF;
      IF NEW.login_binding_id IS NOT NULL AND NEW.login_binding_id <> exact_binding_id THEN
        RAISE EXCEPTION 'auth session login binding does not match the authenticated credential'
          USING ERRCODE = '42501';
      END IF;
      IF NEW.login_binding_revision IS NOT NULL
        AND NEW.login_binding_revision <> exact_binding_revision
      THEN
        RAISE EXCEPTION 'auth session login binding revision is stale' USING ERRCODE = '42501';
      END IF;
      NEW.login_binding_id := exact_binding_id;
      NEW.login_binding_revision := exact_binding_revision;
      PERFORM pg_catalog.set_config(
        'opengeni.canonical_human_identity_lifecycle',
        CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END,
        true
      );
      RETURN NEW;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.canonical_human_identity_lifecycle',
        CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END,
        true
      );
      RAISE;
    END;
    $$;

CREATE FUNCTION managed_auth_session_set_authority_state(p_authority_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      authority_state text;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_authority_hash IS NULL OR p_authority_hash !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'managed auth session-set authority is invalid' USING ERRCODE = '22023';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT CASE
        WHEN session_set.id IS NULL AND installation.id IS NULL THEN 'absent'
        WHEN session_set.revoked_at IS NULL AND installation.revoked_at IS NULL
          AND session_set.idle_expires_at > pg_catalog.clock_timestamp()
          AND session_set.absolute_expires_at > pg_catalog.clock_timestamp()
          AND installation.idle_expires_at > pg_catalog.clock_timestamp()
          AND installation.absolute_expires_at > pg_catalog.clock_timestamp()
        THEN 'active' ELSE 'retired' END
      INTO authority_state
      FROM (SELECT p_authority_hash AS authority_hash) input
      LEFT JOIN managed_auth_browser_installations installation
        ON installation.authority_hash = input.authority_hash
      LEFT JOIN managed_auth_session_sets session_set
        ON session_set.authority_hash = input.authority_hash;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN coalesce(authority_state, 'absent');
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_set_begin_transaction(p_authority_hash text, p_csrf_hash text, p_rate_scope_hash text, p_operation_id uuid, p_request_digest text, p_expected_generation bigint, p_transaction_id uuid, p_expected_actor_epoch bigint, p_transaction_secret_hash text, p_kind text, p_target_slot_id uuid, p_return_intent_id uuid, p_return_path text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      slot_row managed_auth_login_slots%ROWTYPE;
      prior_operation managed_auth_session_set_operations%ROWTYPE;
      installation_uuid uuid;
      result jsonb;
      is_preauth boolean;
      transaction_rate_taken boolean := false;
      previous_marker text := pg_catalog.current_setting('opengeni.managed_auth_session_set_lifecycle', true);
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_csrf_hash !~ '^[0-9a-f]{64}$'
        OR p_rate_scope_hash !~ '^[0-9a-f]{64}$'
        OR p_request_digest !~ '^[0-9a-f]{64}$' OR p_transaction_secret_hash !~ '^[0-9a-f]{64}$'
        OR p_operation_id IS NULL
        OR p_kind NOT IN ('add', 'reauth') OR p_expected_generation < 1 OR p_expected_actor_epoch < 1
        OR p_expires_at <= pg_catalog.clock_timestamp() OR p_expires_at > pg_catalog.clock_timestamp() + interval '10 minutes'
        OR ((p_kind = 'reauth') <> (p_target_slot_id IS NOT NULL))
        OR ((p_return_intent_id IS NULL) <> (p_return_path IS NULL))
      THEN RAISE EXCEPTION 'managed auth login transaction is invalid' USING ERRCODE = '22023'; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT * INTO set_row FROM managed_auth_session_sets
      WHERE authority_hash = p_authority_hash FOR UPDATE;
      IF NOT FOUND THEN
        IF p_kind <> 'add' OR p_expected_generation <> 1 OR p_expected_actor_epoch <> 1
        THEN RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501'; END IF;
        PERFORM managed_auth_login_transaction_rate_limit_take(
          p_rate_scope_hash, p_authority_hash
        );
        transaction_rate_taken := true;
        INSERT INTO managed_auth_browser_installations (authority_hash)
        VALUES (p_authority_hash)
        ON CONFLICT (authority_hash) DO NOTHING;
        SELECT id INTO installation_uuid FROM managed_auth_browser_installations
        WHERE authority_hash = p_authority_hash AND revoked_at IS NULL FOR UPDATE;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'managed auth browser installation is unavailable' USING ERRCODE = '42501';
        END IF;
        INSERT INTO managed_auth_session_sets (installation_id, authority_hash, csrf_hash)
        VALUES (installation_uuid, p_authority_hash, p_csrf_hash)
        ON CONFLICT (authority_hash) DO NOTHING;
        SELECT * INTO set_row FROM managed_auth_session_sets
        WHERE authority_hash = p_authority_hash AND revoked_at IS NULL FOR UPDATE;
        UPDATE managed_auth_browser_installations SET
          idle_expires_at = least(p_expires_at, absolute_expires_at),
          last_seen_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.installation_id;
        UPDATE managed_auth_session_sets SET
          idle_expires_at = least(p_expires_at, absolute_expires_at),
          updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id RETURNING * INTO set_row;
      END IF;
      IF NOT FOUND OR set_row.csrf_hash <> p_csrf_hash THEN
        RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501';
      END IF;
      SELECT * INTO prior_operation FROM managed_auth_session_set_operations WHERE operation_id = p_operation_id;
      IF FOUND THEN
        IF prior_operation.session_set_id <> set_row.id OR prior_operation.request_digest <> p_request_digest
          OR prior_operation.operation_type <> 'begin_' || p_kind
        THEN RAISE EXCEPTION 'managed auth operation id was reused' USING ERRCODE = '23505'; END IF;
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        RETURN prior_operation.result;
      END IF;
      SELECT NOT EXISTS (
        SELECT 1 FROM managed_auth_login_slots slot WHERE slot.session_set_id = set_row.id
      ) INTO is_preauth;
      IF NOT transaction_rate_taken THEN
        PERFORM managed_auth_login_transaction_rate_limit_take(
          p_rate_scope_hash, p_authority_hash
        );
      END IF;
      UPDATE managed_auth_login_transactions SET
        status = 'cancelled', consumed_at = pg_catalog.clock_timestamp()
      WHERE session_set_id = set_row.id AND status = 'pending'
        AND expires_at <= pg_catalog.clock_timestamp();
      IF EXISTS (
        SELECT 1 FROM managed_auth_login_transactions
        WHERE session_set_id = set_row.id AND status = 'pending'
          AND expires_at > pg_catalog.clock_timestamp()
      ) THEN
        RAISE EXCEPTION 'managed auth login transaction is already pending'
          USING ERRCODE = 'P0004';
      END IF;
      IF is_preauth THEN
        UPDATE managed_auth_browser_installations SET
          idle_expires_at = least(
            greatest(idle_expires_at, p_expires_at), absolute_expires_at
          ), last_seen_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.installation_id;
        UPDATE managed_auth_session_sets SET
          idle_expires_at = least(
            greatest(idle_expires_at, p_expires_at), absolute_expires_at
          ), updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id RETURNING * INTO set_row;
      END IF;
      IF set_row.revoked_at IS NOT NULL
        OR managed_auth_session_set_snapshot(
          p_authority_hash, 'dual', false, false, is_preauth
        ) IS NULL
      THEN RAISE EXCEPTION 'managed auth session-set authority expired' USING ERRCODE = '42501'; END IF;
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      IF set_row.generation <> p_expected_generation OR set_row.actor_epoch <> p_expected_actor_epoch
      THEN RAISE EXCEPTION 'managed auth session-set generation conflict' USING ERRCODE = '40001'; END IF;
      IF p_kind = 'reauth' THEN
        SELECT * INTO slot_row FROM managed_auth_login_slots
        WHERE id = p_target_slot_id AND session_set_id = set_row.id AND status <> 'revoked' FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'managed auth login slot is unavailable' USING ERRCODE = 'P0002'; END IF;
      END IF;
      IF p_return_intent_id IS NOT NULL THEN
        INSERT INTO managed_auth_login_return_intents (id, session_set_id, path, expires_at)
        VALUES (p_return_intent_id, set_row.id, p_return_path, p_expires_at);
      END IF;
      INSERT INTO managed_auth_login_transactions (
        id, session_set_id, secret_hash, kind, target_slot_id,
        expected_identity_id, expected_login_binding_id,
        expected_identity_revision, expected_auth_revision, expected_login_binding_revision,
        expected_generation,
        return_intent_id, expires_at
      ) VALUES (
        p_transaction_id, set_row.id, p_transaction_secret_hash, p_kind, p_target_slot_id,
        CASE WHEN p_kind = 'reauth' THEN slot_row.identity_id ELSE NULL END,
        CASE WHEN p_kind = 'reauth' THEN slot_row.login_binding_id ELSE NULL END,
        CASE WHEN p_kind = 'reauth' THEN slot_row.identity_revision ELSE NULL END,
        CASE WHEN p_kind = 'reauth' THEN slot_row.auth_revision ELSE NULL END,
        CASE WHEN p_kind = 'reauth' THEN slot_row.login_binding_revision ELSE NULL END,
        p_expected_generation, p_return_intent_id, p_expires_at
      );
      result := pg_catalog.jsonb_build_object(
        'id', p_transaction_id, 'kind', p_kind,
        'expiresAt', p_expires_at, 'returnIntentId', p_return_intent_id
      );
      INSERT INTO managed_auth_session_set_operations (
        operation_id, session_set_id, operation_type, request_digest,
        expected_generation, result_generation, result_actor_epoch, target_slot_id, outcome, result
      ) VALUES (
        p_operation_id, set_row.id, 'begin_' || p_kind, p_request_digest,
        set_row.generation, set_row.generation, set_row.actor_epoch, p_target_slot_id, 'applied', result
      );
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_set_bootstrap(p_authority_hash text, p_csrf_hash text, p_auth_session_id text, p_mode text, p_operation_id uuid, p_request_digest text, p_expected_generation bigint, p_expected_actor_epoch bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      session_row record;
      slot_id uuid;
      installation_uuid uuid;
      result jsonb;
      prior_operation managed_auth_session_set_operations%ROWTYPE;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
      previous_canonical_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_csrf_hash !~ '^[0-9a-f]{64}$'
        OR p_request_digest !~ '^[0-9a-f]{64}$' OR p_operation_id IS NULL
        OR p_expected_generation < 1 OR p_expected_actor_epoch < 1
        OR p_mode NOT IN ('legacy', 'dual', 'broker')
      THEN RAISE EXCEPTION 'managed auth session-set bootstrap is invalid' USING ERRCODE = '22023';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
      IF p_auth_session_id IS NOT NULL THEN
        -- All first-adoption contenders for one provider session take the same
        -- transaction-scoped fence before reading operation or slot ownership.
        -- This leaves the ordinary session_set -> slot -> auth_session lock order
        -- untouched while making a concurrent loser observe the winner's receipt.
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          'managed-auth-bootstrap:' || p_auth_session_id, 0
        ));
      END IF;
      SELECT * INTO prior_operation FROM managed_auth_session_set_operations
      WHERE operation_id = p_operation_id;
      IF FOUND THEN
        IF prior_operation.operation_type <> 'bootstrap'
          OR prior_operation.request_digest <> p_request_digest
        THEN RAISE EXCEPTION 'managed auth operation id was reused' USING ERRCODE = '23505'; END IF;
        SELECT session_set.* INTO set_row FROM managed_auth_session_sets session_set
        INNER JOIN managed_auth_browser_installations installation
          ON installation.id = session_set.installation_id
        WHERE session_set.id = prior_operation.session_set_id
          AND session_set.authority_hash = p_authority_hash
          AND session_set.csrf_hash = p_csrf_hash
          AND session_set.revoked_at IS NULL AND installation.revoked_at IS NULL
        FOR UPDATE OF session_set, installation;
        IF NOT FOUND THEN RAISE EXCEPTION 'managed auth operation authority mismatch' USING ERRCODE = '42501'; END IF;
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
        RETURN prior_operation.result;
      END IF;
      IF p_auth_session_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM managed_auth_login_slots slot
        WHERE slot.auth_session_id = p_auth_session_id AND slot.status <> 'revoked'
      ) THEN
        RAISE EXCEPTION 'managed auth bootstrap session is already adopted'
          USING ERRCODE = '42501';
      END IF;
      INSERT INTO managed_auth_browser_installations (authority_hash)
      VALUES (p_authority_hash)
      ON CONFLICT (authority_hash) DO NOTHING;
      SELECT id INTO installation_uuid FROM managed_auth_browser_installations
      WHERE authority_hash = p_authority_hash AND revoked_at IS NULL FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'managed auth browser installation is unavailable' USING ERRCODE = '42501'; END IF;
      INSERT INTO managed_auth_session_sets (installation_id, authority_hash, csrf_hash)
      VALUES (installation_uuid, p_authority_hash, p_csrf_hash)
      ON CONFLICT (authority_hash) DO NOTHING;
      SELECT * INTO set_row FROM managed_auth_session_sets
      WHERE authority_hash = p_authority_hash AND revoked_at IS NULL FOR UPDATE;
      IF NOT FOUND OR set_row.csrf_hash <> p_csrf_hash THEN
        RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501';
      END IF;
      SELECT * INTO prior_operation FROM managed_auth_session_set_operations
      WHERE operation_id = p_operation_id;
      IF FOUND THEN
        IF prior_operation.session_set_id <> set_row.id
          OR prior_operation.operation_type <> 'bootstrap'
          OR prior_operation.request_digest <> p_request_digest
        THEN RAISE EXCEPTION 'managed auth operation id was reused' USING ERRCODE = '23505'; END IF;
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
        RETURN prior_operation.result;
      END IF;
      IF managed_auth_session_set_snapshot(p_authority_hash, p_mode, false, false) IS NULL THEN
        RAISE EXCEPTION 'managed auth session-set authority expired' USING ERRCODE = '42501';
      END IF;
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      IF set_row.generation <> p_expected_generation
        OR set_row.actor_epoch <> p_expected_actor_epoch
      THEN RAISE EXCEPTION 'managed auth session-set generation conflict' USING ERRCODE = '40001'; END IF;
      IF p_auth_session_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM managed_auth_login_slots WHERE session_set_id = set_row.id
      ) THEN
        SELECT auth_session.id, auth_session.user_id, auth_session.identity_id,
          auth_session.identity_revision, auth_session.auth_revision,
          auth_session.login_binding_id,
          auth_session.login_binding_revision, identity_row.display_name,
          auth_user.email
        INTO session_row
        FROM auth_sessions auth_session
        INNER JOIN auth_users auth_user ON auth_user.id = auth_session.user_id
        INNER JOIN canonical_human_identities identity_row
          ON identity_row.id = auth_session.identity_id
        INNER JOIN canonical_human_login_bindings binding
          ON binding.id = auth_session.login_binding_id
         AND binding.identity_id = auth_session.identity_id
        INNER JOIN canonical_human_identity_subjects subject_row
          ON subject_row.auth_user_id = auth_session.user_id
         AND subject_row.identity_id = auth_session.identity_id
        WHERE auth_session.id = p_auth_session_id
          AND auth_session.expires_at > pg_catalog.clock_timestamp()
          AND auth_session.identity_revision = identity_row.identity_revision
          AND auth_session.auth_revision = identity_row.auth_revision
          AND auth_session.login_binding_revision = binding.revision
          AND identity_row.status = 'active' AND binding.status = 'active'
          AND subject_row.status = 'active';
        IF NOT FOUND THEN RAISE EXCEPTION 'managed auth bootstrap session is unavailable' USING ERRCODE = '42501'; END IF;
        INSERT INTO managed_auth_login_slots (
          session_set_id, auth_session_id, auth_user_id, identity_id, login_binding_id,
          identity_revision, auth_revision, login_binding_revision, display_name, verified_email
        ) VALUES (
          set_row.id, session_row.id, session_row.user_id, session_row.identity_id,
          session_row.login_binding_id, session_row.identity_revision, session_row.auth_revision,
          session_row.login_binding_revision, session_row.display_name, session_row.email
        ) RETURNING id INTO slot_id;
        UPDATE managed_auth_session_sets SET selected_slot_id = slot_id, updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id RETURNING * INTO set_row;
      END IF;
      result := managed_auth_session_set_snapshot(p_authority_hash, p_mode, false, false);
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      INSERT INTO managed_auth_session_set_operations (
        operation_id, session_set_id, operation_type, request_digest,
        expected_generation, result_generation, result_actor_epoch, outcome, result
      ) VALUES (
        p_operation_id, set_row.id, 'bootstrap', p_request_digest,
        p_expected_generation, set_row.generation, set_row.actor_epoch, 'applied', result
      );
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_set_complete_transaction(p_authority_hash text, p_csrf_hash text, p_operation_id uuid, p_request_digest text, p_expected_generation bigint, p_expected_actor_epoch bigint, p_transaction_id uuid, p_transaction_secret_hash text, p_auth_session_id text, p_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      tx_row managed_auth_login_transactions%ROWTYPE;
      session_row record;
      slot_row managed_auth_login_slots%ROWTYPE;
      prior_operation managed_auth_session_set_operations%ROWTYPE;
      old_auth_session_id text;
      slot_id uuid;
      selected_rebound boolean := false;
      return_path text;
      result jsonb;
      previous_marker text := pg_catalog.current_setting('opengeni.managed_auth_session_set_lifecycle', true);
      previous_canonical_marker text := pg_catalog.current_setting('opengeni.canonical_human_identity_lifecycle', true);
    BEGIN
      IF p_request_digest !~ '^[0-9a-f]{64}$' OR p_transaction_secret_hash !~ '^[0-9a-f]{64}$'
        OR p_expected_generation < 1 OR p_expected_actor_epoch < 1
        OR p_mode NOT IN ('legacy', 'dual', 'broker')
      THEN RAISE EXCEPTION 'managed auth transaction completion is invalid' USING ERRCODE = '22023'; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
      SELECT * INTO set_row FROM managed_auth_session_sets
      WHERE authority_hash = p_authority_hash FOR UPDATE;
      IF NOT FOUND OR set_row.csrf_hash <> p_csrf_hash THEN RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501'; END IF;
      SELECT * INTO prior_operation FROM managed_auth_session_set_operations WHERE operation_id = p_operation_id;
      IF FOUND THEN
        IF prior_operation.session_set_id <> set_row.id OR prior_operation.request_digest <> p_request_digest
          OR prior_operation.operation_type NOT IN ('complete_add', 'complete_reauth')
        THEN RAISE EXCEPTION 'managed auth operation id was reused' USING ERRCODE = '23505'; END IF;
        DELETE FROM auth_sessions replay_session
        WHERE replay_session.id = p_auth_session_id
          AND NOT EXISTS (
            SELECT 1 FROM managed_auth_login_slots slot
            WHERE slot.id = prior_operation.target_slot_id
              AND slot.auth_session_id = replay_session.id
          );
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
        RETURN prior_operation.result;
      END IF;
      IF set_row.revoked_at IS NOT NULL
        OR managed_auth_session_set_snapshot(p_authority_hash, p_mode, false, false) IS NULL
      THEN RAISE EXCEPTION 'managed auth session-set authority expired' USING ERRCODE = '42501'; END IF;
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      IF set_row.generation <> p_expected_generation OR set_row.actor_epoch <> p_expected_actor_epoch
      THEN RAISE EXCEPTION 'managed auth session-set generation conflict' USING ERRCODE = '40001'; END IF;
      SELECT * INTO tx_row FROM managed_auth_login_transactions
      WHERE id = p_transaction_id AND session_set_id = set_row.id FOR UPDATE;
      IF NOT FOUND OR tx_row.secret_hash <> p_transaction_secret_hash OR tx_row.status <> 'pending'
        OR tx_row.expires_at <= pg_catalog.clock_timestamp() OR tx_row.expected_generation <> p_expected_generation
      THEN RAISE EXCEPTION 'managed auth login transaction is unavailable' USING ERRCODE = '42501'; END IF;
      SELECT auth_session.id, auth_session.user_id, auth_session.identity_id,
        auth_session.identity_revision, auth_session.auth_revision,
        auth_session.login_binding_id,
        auth_session.login_binding_revision, identity_row.display_name, auth_user.email
      INTO session_row
      FROM auth_sessions auth_session
      INNER JOIN auth_users auth_user ON auth_user.id = auth_session.user_id
      INNER JOIN canonical_human_identities identity_row ON identity_row.id = auth_session.identity_id
      INNER JOIN canonical_human_login_bindings binding
        ON binding.id = auth_session.login_binding_id
       AND binding.identity_id = auth_session.identity_id
      INNER JOIN canonical_human_identity_subjects subject_row
        ON subject_row.auth_user_id = auth_session.user_id AND subject_row.identity_id = auth_session.identity_id
      WHERE auth_session.id = p_auth_session_id AND auth_session.expires_at > pg_catalog.clock_timestamp()
        AND auth_session.identity_revision = identity_row.identity_revision
        AND auth_session.auth_revision = identity_row.auth_revision
        AND auth_session.login_binding_revision = binding.revision
        AND subject_row.status = 'active'
        AND (
          (identity_row.status = 'active' AND binding.status = 'active')
          OR (
            tx_row.kind = 'reauth'
            AND auth_session.identity_id = tx_row.expected_identity_id
            AND auth_session.login_binding_id = tx_row.expected_login_binding_id
            AND identity_row.status = 'recovery_required'
            AND binding.status = 'recovery_pending'
          )
        );
      IF NOT FOUND THEN RAISE EXCEPTION 'managed auth provider session is unavailable' USING ERRCODE = '42501'; END IF;
      IF tx_row.kind = 'reauth' THEN
        IF session_row.identity_id <> tx_row.expected_identity_id
          OR session_row.login_binding_id <> tx_row.expected_login_binding_id
          OR session_row.identity_revision <> tx_row.expected_identity_revision
          OR session_row.auth_revision <> tx_row.expected_auth_revision
          OR session_row.login_binding_revision <> tx_row.expected_login_binding_revision
        THEN RAISE EXCEPTION 'managed auth reauthentication binding mismatch' USING ERRCODE = '42501'; END IF;
        SELECT * INTO slot_row FROM managed_auth_login_slots
        WHERE id = tx_row.target_slot_id AND session_set_id = set_row.id AND status <> 'revoked' FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'managed auth login slot is unavailable' USING ERRCODE = 'P0002'; END IF;
      ELSE
        SELECT * INTO slot_row FROM managed_auth_login_slots
        WHERE session_set_id = set_row.id
          AND login_binding_id = session_row.login_binding_id
          AND status <> 'revoked' FOR UPDATE;
        IF FOUND THEN
          RAISE EXCEPTION 'managed auth login binding already has a slot' USING ERRCODE = 'P0003';
        END IF;
        IF (
          SELECT count(*) FROM managed_auth_login_slots WHERE session_set_id = set_row.id AND status <> 'revoked'
        ) >= 8 THEN RAISE EXCEPTION 'managed auth login slot limit reached' USING ERRCODE = '54000'; END IF;
      END IF;
      IF tx_row.kind = 'reauth' THEN
        old_auth_session_id := slot_row.auth_session_id;
        slot_id := slot_row.id;
        selected_rebound := slot_row.id = set_row.selected_slot_id;
        IF selected_rebound THEN
          DELETE FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
          IF EXISTS (
            SELECT 1 FROM managed_auth_actor_mutation_leases
            WHERE session_set_id = set_row.id AND actor_epoch = set_row.actor_epoch
          ) THEN
            RAISE EXCEPTION 'managed auth actor has an in-flight mutation'
              USING ERRCODE = '55P03';
          END IF;
        END IF;
        UPDATE managed_auth_login_slots SET
          auth_session_id = session_row.id, auth_user_id = session_row.user_id,
          identity_id = session_row.identity_id, login_binding_id = session_row.login_binding_id,
          identity_revision = session_row.identity_revision, auth_revision = session_row.auth_revision,
          login_binding_revision = session_row.login_binding_revision,
          display_name = session_row.display_name, verified_email = session_row.email,
          status = 'active', revoked_at = NULL, updated_at = pg_catalog.clock_timestamp()
        WHERE id = slot_row.id;
      ELSE
        INSERT INTO managed_auth_login_slots (
          session_set_id, auth_session_id, auth_user_id, identity_id, login_binding_id,
          identity_revision, auth_revision, login_binding_revision, display_name, verified_email
        ) VALUES (
          set_row.id, session_row.id, session_row.user_id, session_row.identity_id,
          session_row.login_binding_id, session_row.identity_revision, session_row.auth_revision,
          session_row.login_binding_revision, session_row.display_name, session_row.email
        ) RETURNING id INTO slot_id;
      END IF;
      UPDATE managed_auth_login_transactions SET status = 'consumed', consumed_at = pg_catalog.clock_timestamp()
      WHERE id = tx_row.id;
      IF tx_row.return_intent_id IS NOT NULL THEN
        UPDATE managed_auth_login_return_intents SET consumed_at = pg_catalog.clock_timestamp()
        WHERE id = tx_row.return_intent_id AND consumed_at IS NULL AND expires_at > pg_catalog.clock_timestamp()
        RETURNING path INTO return_path;
      END IF;
      UPDATE managed_auth_session_sets changed_set SET
        generation = changed_set.generation + 1,
        actor_epoch = changed_set.actor_epoch + CASE WHEN selected_rebound THEN 1 ELSE 0 END,
        state = CASE WHEN selected_rebound THEN 'ready' ELSE changed_set.state END,
        updated_at = pg_catalog.clock_timestamp()
      WHERE changed_set.id = set_row.id RETURNING * INTO set_row;
      IF old_auth_session_id IS NOT NULL AND old_auth_session_id <> session_row.id THEN
        DELETE FROM auth_sessions WHERE id = old_auth_session_id;
      END IF;
      result := managed_auth_session_set_snapshot(p_authority_hash, p_mode, false, false)
        || pg_catalog.jsonb_build_object('returnIntent', return_path);
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      INSERT INTO managed_auth_session_set_operations (
        operation_id, session_set_id, operation_type, request_digest,
        expected_generation, result_generation, result_actor_epoch, target_slot_id, outcome, result
      ) VALUES (
        p_operation_id, set_row.id, 'complete_' || tx_row.kind, p_request_digest,
        p_expected_generation, set_row.generation, set_row.actor_epoch, slot_id, 'applied', result
      );
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_set_mutate(p_authority_hash text, p_csrf_hash text, p_operation_id uuid, p_request_digest text, p_expected_generation bigint, p_expected_actor_epoch bigint, p_operation_type text, p_target_slot_id uuid, p_replacement_slot_id uuid, p_transaction_id uuid, p_transaction_secret_hash text, p_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      target_slot managed_auth_login_slots%ROWTYPE;
      replacement_slot managed_auth_login_slots%ROWTYPE;
      tx_row managed_auth_login_transactions%ROWTYPE;
      prior_operation managed_auth_session_set_operations%ROWTYPE;
      was_selected boolean := false;
      result jsonb;
      previous_marker text := pg_catalog.current_setting('opengeni.managed_auth_session_set_lifecycle', true);
    BEGIN
      IF p_request_digest !~ '^[0-9a-f]{64}$' OR p_expected_generation < 1
        OR p_expected_actor_epoch < 1
        OR p_operation_type NOT IN ('cancel_transaction', 'select', 'logout_one', 'logout_all')
        OR p_mode NOT IN ('legacy', 'dual', 'broker')
      THEN RAISE EXCEPTION 'managed auth session-set mutation is invalid' USING ERRCODE = '22023'; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT * INTO set_row FROM managed_auth_session_sets
      WHERE authority_hash = p_authority_hash FOR UPDATE;
      IF NOT FOUND OR set_row.csrf_hash <> p_csrf_hash THEN RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501'; END IF;
      SELECT * INTO prior_operation FROM managed_auth_session_set_operations WHERE operation_id = p_operation_id;
      IF FOUND THEN
        IF prior_operation.session_set_id <> set_row.id OR prior_operation.request_digest <> p_request_digest
          OR prior_operation.operation_type <> p_operation_type
        THEN RAISE EXCEPTION 'managed auth operation id was reused' USING ERRCODE = '23505'; END IF;
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        RETURN prior_operation.result;
      END IF;
      IF set_row.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'managed auth session-set authority denied' USING ERRCODE = '42501'; END IF;
      IF managed_auth_session_set_snapshot(p_authority_hash, p_mode, false, false) IS NULL THEN
        RAISE EXCEPTION 'managed auth session-set authority expired' USING ERRCODE = '42501';
      END IF;
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      IF set_row.generation <> p_expected_generation OR set_row.actor_epoch <> p_expected_actor_epoch
      THEN RAISE EXCEPTION 'managed auth session-set generation conflict' USING ERRCODE = '40001'; END IF;
      IF p_operation_type = 'cancel_transaction' THEN
        IF p_transaction_secret_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'managed auth transaction secret is invalid' USING ERRCODE = '22023'; END IF;
        SELECT * INTO tx_row FROM managed_auth_login_transactions
        WHERE id = p_transaction_id AND session_set_id = set_row.id FOR UPDATE;
        IF NOT FOUND OR tx_row.secret_hash <> p_transaction_secret_hash OR tx_row.status <> 'pending'
        THEN RAISE EXCEPTION 'managed auth login transaction is unavailable' USING ERRCODE = '42501'; END IF;
        UPDATE managed_auth_login_transactions SET status = 'cancelled', consumed_at = pg_catalog.clock_timestamp()
        WHERE id = tx_row.id;
        UPDATE managed_auth_login_return_intents SET consumed_at = pg_catalog.clock_timestamp()
        WHERE id = tx_row.return_intent_id AND consumed_at IS NULL;
      ELSIF p_operation_type = 'select' THEN
        SELECT * INTO target_slot FROM managed_auth_login_slots
        WHERE id = p_target_slot_id AND session_set_id = set_row.id AND status = 'active'
          AND auth_session_id IS NOT NULL FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'managed auth login slot is unavailable' USING ERRCODE = 'P0002'; END IF;
        DELETE FROM managed_auth_actor_mutation_leases
        WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
        IF EXISTS (
          SELECT 1 FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND actor_epoch = set_row.actor_epoch
        ) THEN
          RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
        END IF;
        UPDATE managed_auth_session_sets SET selected_slot_id = target_slot.id,
          generation = generation + 1, actor_epoch = actor_epoch + 1,
          state = 'ready', updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id RETURNING * INTO set_row;
      ELSIF p_operation_type = 'logout_one' THEN
        SELECT * INTO target_slot FROM managed_auth_login_slots
        WHERE id = p_target_slot_id AND session_set_id = set_row.id AND status <> 'revoked' FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'managed auth login slot is unavailable' USING ERRCODE = 'P0002'; END IF;
        was_selected := target_slot.id = set_row.selected_slot_id;
        IF NOT was_selected AND p_replacement_slot_id IS NOT NULL THEN
          RAISE EXCEPTION 'replacement is valid only for the selected slot' USING ERRCODE = '22023';
        END IF;
        IF p_replacement_slot_id IS NOT NULL THEN
          SELECT * INTO replacement_slot FROM managed_auth_login_slots
          WHERE id = p_replacement_slot_id AND session_set_id = set_row.id
            AND id <> target_slot.id AND status = 'active' AND auth_session_id IS NOT NULL FOR UPDATE;
          IF NOT FOUND THEN RAISE EXCEPTION 'managed auth replacement slot is unavailable' USING ERRCODE = 'P0002'; END IF;
        END IF;
        IF was_selected THEN
          DELETE FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
          IF EXISTS (
            SELECT 1 FROM managed_auth_actor_mutation_leases
            WHERE session_set_id = set_row.id AND actor_epoch = set_row.actor_epoch
          ) THEN
            RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
          END IF;
        END IF;
        UPDATE managed_auth_login_slots SET status = 'revoked', auth_session_id = NULL,
          revoked_at = pg_catalog.clock_timestamp(), updated_at = pg_catalog.clock_timestamp()
        WHERE id = target_slot.id;
        IF target_slot.auth_session_id IS NOT NULL THEN DELETE FROM auth_sessions WHERE id = target_slot.auth_session_id; END IF;
        UPDATE managed_auth_session_sets SET
          selected_slot_id = CASE WHEN was_selected THEN p_replacement_slot_id ELSE selected_slot_id END,
          generation = generation + 1,
          actor_epoch = actor_epoch + CASE WHEN was_selected THEN 1 ELSE 0 END,
          state = CASE
            WHEN was_selected AND p_replacement_slot_id IS NULL THEN 'actor_change_required'
            WHEN was_selected THEN 'ready'
            ELSE state
          END,
          updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id RETURNING * INTO set_row;
      ELSE
        DELETE FROM managed_auth_actor_mutation_leases
        WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
        IF EXISTS (
          SELECT 1 FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND actor_epoch = set_row.actor_epoch
        ) THEN
          RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
        END IF;
        DELETE FROM auth_sessions auth_session USING managed_auth_login_slots slot
        WHERE slot.session_set_id = set_row.id AND slot.status <> 'revoked'
          AND auth_session.id = slot.auth_session_id;
        UPDATE managed_auth_login_slots SET status = 'revoked', auth_session_id = NULL,
          revoked_at = pg_catalog.clock_timestamp(), updated_at = pg_catalog.clock_timestamp()
        WHERE session_set_id = set_row.id AND status <> 'revoked';
        UPDATE managed_auth_session_sets SET selected_slot_id = NULL,
          generation = generation + 1, actor_epoch = actor_epoch + 1,
          state = 'actor_change_required', revoked_at = pg_catalog.clock_timestamp(),
          updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id RETURNING * INTO set_row;
        UPDATE managed_auth_browser_installations SET revoked_at = pg_catalog.clock_timestamp(),
          last_seen_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.installation_id AND revoked_at IS NULL;
      END IF;
      result := CASE WHEN p_operation_type = 'logout_all' THEN
        pg_catalog.jsonb_build_object(
          'generation', set_row.generation::text,
          'actorEpoch', set_row.actor_epoch::text,
          'state', 'logged_out'
        )
      ELSE managed_auth_session_set_snapshot(p_authority_hash, p_mode, false, false) END;
      SELECT * INTO set_row FROM managed_auth_session_sets WHERE id = set_row.id FOR UPDATE;
      INSERT INTO managed_auth_session_set_operations (
        operation_id, session_set_id, operation_type, request_digest,
        expected_generation, result_generation, result_actor_epoch,
        target_slot_id, replacement_slot_id, outcome, result
      ) VALUES (
        p_operation_id, set_row.id, p_operation_type, p_request_digest,
        p_expected_generation, set_row.generation, set_row.actor_epoch,
        p_target_slot_id, p_replacement_slot_id, 'applied', result
      );
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_set_operation_receipt(p_authority_hash text, p_operation_id uuid, p_request_digest text, p_operation_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      operation_row managed_auth_session_set_operations%ROWTYPE;
      set_row managed_auth_session_sets%ROWTYPE;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
    BEGIN
      IF p_authority_hash !~ '^[0-9a-f]{64}$' OR p_operation_id IS NULL
        OR p_request_digest !~ '^[0-9a-f]{64}$' OR p_operation_kind <> 'complete'
      THEN RETURN NULL; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      SELECT operation.* INTO operation_row FROM managed_auth_session_set_operations operation
      WHERE operation.operation_id = p_operation_id
        AND operation.request_digest = p_request_digest
        AND operation.operation_type IN ('complete_add', 'complete_reauth');
      IF NOT FOUND THEN
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        RETURN NULL;
      END IF;
      SELECT session_set.* INTO set_row FROM managed_auth_session_sets session_set
      INNER JOIN managed_auth_browser_installations installation
        ON installation.id = session_set.installation_id
      WHERE session_set.id = operation_row.session_set_id
        AND session_set.authority_hash = p_authority_hash
      FOR UPDATE OF session_set, installation;
      IF NOT FOUND THEN
        PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
        RETURN NULL;
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN operation_row.result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_set_operations_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    AND pg_catalog.current_setting('opengeni.managed_auth_session_set_purge', true) = 'active'
    AND NOT EXISTS (
      SELECT 1 FROM managed_auth_login_slots slot
      WHERE slot.session_set_id = OLD.session_set_id
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'managed auth session-set operations are append-only' USING ERRCODE = '42501';
END
$$;

CREATE FUNCTION managed_auth_session_set_snapshot(p_authority_hash text, p_mode text DEFAULT 'legacy'::text, p_include_internal boolean DEFAULT false, p_allow_recovery boolean DEFAULT false, p_read_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      set_row managed_auth_session_sets%ROWTYPE;
      changed_count integer := 0;
      selected_lost boolean := false;
      result jsonb;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
      previous_canonical_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
    BEGIN
      IF p_authority_hash IS NULL OR p_authority_hash !~ '^[0-9a-f]{64}$'
        OR p_mode NOT IN ('legacy', 'dual', 'broker')
      THEN
        RAISE EXCEPTION 'managed auth session-set authority is invalid' USING ERRCODE = '22023';
      END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
      SELECT session_set.* INTO set_row
      FROM managed_auth_session_sets session_set
      INNER JOIN managed_auth_browser_installations installation
        ON installation.id = session_set.installation_id
      WHERE session_set.authority_hash = p_authority_hash
      FOR UPDATE OF session_set, installation;
      IF NOT FOUND THEN
        PERFORM pg_catalog.set_config(
          'opengeni.managed_auth_session_set_lifecycle',
          CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
        );
        PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
        RETURN NULL;
      END IF;
      IF set_row.revoked_at IS NOT NULL OR EXISTS (
        SELECT 1 FROM managed_auth_browser_installations installation
        WHERE installation.id = set_row.installation_id AND installation.revoked_at IS NOT NULL
      ) THEN
        PERFORM pg_catalog.set_config(
          'opengeni.managed_auth_session_set_lifecycle',
          CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
        );
        PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
        RETURN NULL;
      END IF;
      IF set_row.idle_expires_at <= pg_catalog.clock_timestamp()
        OR set_row.absolute_expires_at <= pg_catalog.clock_timestamp()
        OR EXISTS (
          SELECT 1 FROM managed_auth_browser_installations installation
          WHERE installation.id = set_row.installation_id
            AND (installation.idle_expires_at <= pg_catalog.clock_timestamp()
              OR installation.absolute_expires_at <= pg_catalog.clock_timestamp())
        )
      THEN
        IF p_read_only THEN
          PERFORM pg_catalog.set_config(
            'opengeni.managed_auth_session_set_lifecycle',
            CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
          );
          PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
          RETURN NULL;
        END IF;
        DELETE FROM managed_auth_actor_mutation_leases
        WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
        IF EXISTS (
          SELECT 1 FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND actor_epoch = set_row.actor_epoch
        ) THEN
          RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
        END IF;
        DELETE FROM auth_sessions auth_session USING managed_auth_login_slots slot
        WHERE slot.session_set_id = set_row.id AND slot.status <> 'revoked'
          AND auth_session.id = slot.auth_session_id;
        UPDATE managed_auth_login_slots SET status = 'revoked', auth_session_id = NULL,
          revoked_at = pg_catalog.clock_timestamp(), updated_at = pg_catalog.clock_timestamp()
        WHERE session_set_id = set_row.id AND status <> 'revoked';
        UPDATE managed_auth_session_sets SET revoked_at = pg_catalog.clock_timestamp(),
          state = 'actor_change_required', updated_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.id;
        UPDATE managed_auth_browser_installations SET revoked_at = pg_catalog.clock_timestamp(),
          last_seen_at = pg_catalog.clock_timestamp()
        WHERE id = set_row.installation_id;
        PERFORM pg_catalog.set_config(
          'opengeni.managed_auth_session_set_lifecycle',
          CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
        );
        PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
        RETURN NULL;
      END IF;
      IF NOT p_read_only THEN
        UPDATE managed_auth_browser_installations installation SET
          last_seen_at = pg_catalog.clock_timestamp(),
          idle_expires_at = least(pg_catalog.clock_timestamp() + interval '30 days', installation.absolute_expires_at)
        WHERE installation.id = set_row.installation_id;
        UPDATE managed_auth_session_sets session_set SET
          idle_expires_at = least(pg_catalog.clock_timestamp() + interval '30 days', session_set.absolute_expires_at),
          updated_at = pg_catalog.clock_timestamp()
        WHERE session_set.id = set_row.id RETURNING * INTO set_row;
      END IF;

      SELECT EXISTS (
        SELECT 1
        FROM managed_auth_login_slots slot
        LEFT JOIN auth_sessions auth_session ON auth_session.id = slot.auth_session_id
        LEFT JOIN canonical_human_identities identity_row ON identity_row.id = slot.identity_id
        LEFT JOIN canonical_human_login_bindings binding ON binding.id = slot.login_binding_id
        LEFT JOIN canonical_human_identity_subjects subject_row
          ON subject_row.auth_user_id = slot.auth_user_id
         AND subject_row.identity_id = slot.identity_id
        WHERE slot.id = set_row.selected_slot_id AND slot.status = 'active'
          AND NOT (
            auth_session.id IS NOT NULL
            AND auth_session.user_id = slot.auth_user_id
            AND auth_session.expires_at > pg_catalog.clock_timestamp()
            AND auth_session.identity_id = slot.identity_id
            AND auth_session.identity_revision = slot.identity_revision
            AND auth_session.auth_revision = slot.auth_revision
            AND auth_session.login_binding_id = slot.login_binding_id
            AND auth_session.login_binding_revision = slot.login_binding_revision
            AND identity_row.identity_revision = slot.identity_revision
            AND identity_row.auth_revision = slot.auth_revision
            AND binding.identity_id = slot.identity_id
            AND binding.revision = slot.login_binding_revision
            AND subject_row.status = 'active'
            AND (
              (identity_row.status = 'active' AND binding.status = 'active')
              OR (
                p_allow_recovery
                AND identity_row.status = 'recovery_required'
                AND binding.status = 'recovery_pending'
              )
            )
          )
      ) INTO selected_lost;

      IF NOT p_read_only AND selected_lost THEN
        DELETE FROM managed_auth_actor_mutation_leases
        WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
        IF EXISTS (
          SELECT 1 FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND actor_epoch = set_row.actor_epoch
        ) THEN
          RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
        END IF;
      END IF;

      IF NOT p_read_only THEN
      WITH invalid AS (
        SELECT slot.id, slot.auth_session_id, slot.id = set_row.selected_slot_id AS was_selected
        FROM managed_auth_login_slots slot
        LEFT JOIN auth_sessions auth_session ON auth_session.id = slot.auth_session_id
        LEFT JOIN canonical_human_identities identity_row ON identity_row.id = slot.identity_id
        LEFT JOIN canonical_human_login_bindings binding ON binding.id = slot.login_binding_id
        LEFT JOIN canonical_human_identity_subjects subject_row
          ON subject_row.auth_user_id = slot.auth_user_id
         AND subject_row.identity_id = slot.identity_id
        WHERE slot.session_set_id = set_row.id AND slot.status = 'active'
          AND NOT (
            slot.id = set_row.selected_slot_id
            AND identity_row.status = 'recovery_required'
            AND binding.id = slot.login_binding_id
            AND binding.identity_id = slot.identity_id
            AND binding.status = 'recovery_pending'
            AND subject_row.status = 'active'
          )
          AND NOT (
            auth_session.id IS NOT NULL
            AND auth_session.user_id = slot.auth_user_id
            AND auth_session.expires_at > pg_catalog.clock_timestamp()
            AND auth_session.identity_id = slot.identity_id
            AND auth_session.identity_revision = slot.identity_revision
            AND auth_session.auth_revision = slot.auth_revision
            AND auth_session.login_binding_id = slot.login_binding_id
            AND auth_session.login_binding_revision = slot.login_binding_revision
            AND (
              identity_row.status = 'active'
              OR (
                p_allow_recovery
                AND slot.id = set_row.selected_slot_id
                AND identity_row.status = 'recovery_required'
              )
            )
            AND identity_row.identity_revision = slot.identity_revision
            AND identity_row.auth_revision = slot.auth_revision
            AND binding.identity_id = slot.identity_id
            AND (
              binding.status = 'active'
              OR (
                p_allow_recovery
                AND slot.id = set_row.selected_slot_id
                AND identity_row.status = 'recovery_required'
                AND binding.status = 'recovery_pending'
              )
            )
            AND binding.revision = slot.login_binding_revision
            AND subject_row.status = 'active'
          )
      ), stale AS (
        UPDATE managed_auth_login_slots slot
        SET status = 'reauth_required', auth_session_id = NULL,
            updated_at = pg_catalog.clock_timestamp()
        FROM invalid
        WHERE slot.id = invalid.id
        RETURNING invalid.was_selected, invalid.auth_session_id
      ), deleted_sessions AS (
        DELETE FROM auth_sessions auth_session USING stale
        WHERE auth_session.id = stale.auth_session_id
        RETURNING auth_session.id
      )
      SELECT count(*)::integer, coalesce(bool_or(was_selected), false)
      INTO changed_count, selected_lost FROM stale;

      IF changed_count > 0 THEN
        UPDATE managed_auth_session_sets changed_set
        SET generation = changed_set.generation + 1,
            actor_epoch = changed_set.actor_epoch + CASE WHEN selected_lost THEN 1 ELSE 0 END,
            selected_slot_id = CASE WHEN selected_lost THEN NULL ELSE changed_set.selected_slot_id END,
            state = CASE WHEN selected_lost THEN 'actor_change_required' ELSE changed_set.state END,
            updated_at = pg_catalog.clock_timestamp()
        WHERE changed_set.id = set_row.id RETURNING * INTO set_row;
      END IF;
      END IF;

      SELECT pg_catalog.jsonb_build_object(
        'projection', pg_catalog.jsonb_build_object(
          'mode', p_mode,
          'generation', set_row.generation::text,
          'actorEpoch', set_row.actor_epoch::text,
          'selectedSlotId', CASE
            WHEN selected_lost AND NOT p_allow_recovery THEN NULL
            ELSE set_row.selected_slot_id
          END,
          'state', CASE WHEN selected_lost THEN 'actor_change_required' ELSE set_row.state END,
          'slots', coalesce((
            SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'id', slot.id,
              'displayName', slot.display_name,
              'verifiedClaim', pg_catalog.jsonb_build_object(
                'kind', 'email', 'value', slot.verified_email
              ),
              'state', CASE
                WHEN slot.status = 'active'
                  AND auth_session.id IS NOT NULL
                  AND auth_session.user_id = slot.auth_user_id
                  AND auth_session.expires_at > pg_catalog.clock_timestamp()
                  AND auth_session.identity_id = slot.identity_id
                  AND auth_session.identity_revision = slot.identity_revision
                  AND auth_session.auth_revision = slot.auth_revision
                  AND auth_session.login_binding_id = slot.login_binding_id
                  AND auth_session.login_binding_revision = slot.login_binding_revision
                  AND identity_row.status = 'active'
                  AND binding.status = 'active'
                  AND identity_row.identity_revision = slot.identity_revision
                  AND identity_row.auth_revision = slot.auth_revision
                  AND binding.identity_id = slot.identity_id
                  AND binding.revision = slot.login_binding_revision
                  AND subject_row.status = 'active'
                THEN 'active' ELSE 'reauth_required' END
            ) ORDER BY slot.created_at, slot.id)
            FROM managed_auth_login_slots slot
            LEFT JOIN auth_sessions auth_session ON auth_session.id = slot.auth_session_id
            LEFT JOIN canonical_human_identities identity_row ON identity_row.id = slot.identity_id
            LEFT JOIN canonical_human_login_bindings binding ON binding.id = slot.login_binding_id
            LEFT JOIN canonical_human_identity_subjects subject_row
              ON subject_row.auth_user_id = slot.auth_user_id
             AND subject_row.identity_id = slot.identity_id
            WHERE slot.session_set_id = set_row.id AND slot.status <> 'revoked'
          ), '[]'::jsonb)
        ),
        'selected', CASE WHEN p_include_internal THEN (
          SELECT pg_catalog.jsonb_build_object(
            'slotId', slot.id, 'authSessionId', auth_session.id,
            'authUserId', slot.auth_user_id, 'token', auth_session.token,
            'email', auth_user.email, 'name', auth_user.name,
            'emailVerified', auth_user.email_verified
          )
          FROM managed_auth_login_slots slot
          INNER JOIN auth_sessions auth_session ON auth_session.id = slot.auth_session_id
          INNER JOIN auth_users auth_user ON auth_user.id = slot.auth_user_id
          INNER JOIN canonical_human_identities identity_row ON identity_row.id = slot.identity_id
          INNER JOIN canonical_human_login_bindings binding ON binding.id = slot.login_binding_id
          INNER JOIN canonical_human_identity_subjects subject_row
            ON subject_row.auth_user_id = slot.auth_user_id
           AND subject_row.identity_id = slot.identity_id
          WHERE slot.id = set_row.selected_slot_id AND slot.status = 'active'
            AND auth_session.user_id = slot.auth_user_id
            AND auth_session.expires_at > pg_catalog.clock_timestamp()
            AND auth_session.identity_id = slot.identity_id
            AND auth_session.identity_revision = slot.identity_revision
            AND auth_session.auth_revision = slot.auth_revision
            AND auth_session.login_binding_id = slot.login_binding_id
            AND auth_session.login_binding_revision = slot.login_binding_revision
            AND identity_row.identity_revision = slot.identity_revision
            AND identity_row.auth_revision = slot.auth_revision
            AND binding.identity_id = slot.identity_id
            AND binding.revision = slot.login_binding_revision
            AND subject_row.status = 'active'
            AND (
              (identity_row.status = 'active' AND binding.status = 'active')
              OR (
                p_allow_recovery
                AND identity_row.status = 'recovery_required'
                AND binding.status = 'recovery_pending'
              )
            )
        ) ELSE NULL END,
        'internalSlots', CASE WHEN p_include_internal THEN coalesce((
          SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'slotId', slot.id, 'authSessionId', auth_session.id,
            'authUserId', slot.auth_user_id, 'token', auth_session.token,
            'email', auth_user.email, 'name', auth_user.name,
            'emailVerified', auth_user.email_verified
          ) ORDER BY slot.created_at, slot.id)
          FROM managed_auth_login_slots slot
          INNER JOIN auth_sessions auth_session ON auth_session.id = slot.auth_session_id
          INNER JOIN auth_users auth_user ON auth_user.id = slot.auth_user_id
          INNER JOIN canonical_human_identities identity_row ON identity_row.id = slot.identity_id
          INNER JOIN canonical_human_login_bindings binding ON binding.id = slot.login_binding_id
          INNER JOIN canonical_human_identity_subjects subject_row
            ON subject_row.auth_user_id = slot.auth_user_id
           AND subject_row.identity_id = slot.identity_id
          WHERE slot.session_set_id = set_row.id AND slot.status = 'active'
            AND auth_session.user_id = slot.auth_user_id
            AND auth_session.expires_at > pg_catalog.clock_timestamp()
            AND auth_session.identity_id = slot.identity_id
            AND auth_session.identity_revision = slot.identity_revision
            AND auth_session.auth_revision = slot.auth_revision
            AND auth_session.login_binding_id = slot.login_binding_id
            AND auth_session.login_binding_revision = slot.login_binding_revision
            AND identity_row.identity_revision = slot.identity_revision
            AND identity_row.auth_revision = slot.auth_revision
            AND binding.identity_id = slot.identity_id
            AND binding.revision = slot.login_binding_revision
            AND subject_row.status = 'active'
            AND (
              (identity_row.status = 'active' AND binding.status = 'active')
              OR (
                p_allow_recovery
                AND slot.id = set_row.selected_slot_id
                AND identity_row.status = 'recovery_required'
                AND binding.status = 'recovery_pending'
              )
            )
        ), '[]'::jsonb) ELSE '[]'::jsonb END
      ) INTO result;
      PERFORM pg_catalog.set_config(
        'opengeni.managed_auth_session_set_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
      );
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.managed_auth_session_set_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true
      );
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_auth_session_slot_invalidation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
    DECLARE
      slot_row managed_auth_login_slots%ROWTYPE;
      set_row managed_auth_session_sets%ROWTYPE;
      identity_status text;
      binding_status text;
      current_identity_revision bigint;
      current_auth_revision bigint;
      current_binding_revision bigint;
      recovery_transition boolean;
      own_request_text text := pg_catalog.current_setting(
        'opengeni.managed_auth_actor_mutation_request_id', true
      );
      own_request_id uuid;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.managed_auth_session_set_lifecycle', true
      );
      previous_canonical_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
    BEGIN
      IF own_request_text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      THEN own_request_id := own_request_text::uuid; END IF;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
      FOR slot_row IN
        SELECT * FROM managed_auth_login_slots
        WHERE auth_session_id = OLD.id AND status <> 'revoked'
        ORDER BY session_set_id, id
      LOOP
        SELECT * INTO set_row FROM managed_auth_session_sets
        WHERE id = slot_row.session_set_id FOR UPDATE;
        DELETE FROM managed_auth_actor_mutation_leases
        WHERE session_set_id = set_row.id AND expires_at <= pg_catalog.clock_timestamp();
        IF EXISTS (
          SELECT 1 FROM managed_auth_actor_mutation_leases lease
          WHERE lease.session_set_id = set_row.id AND lease.actor_epoch = set_row.actor_epoch
            AND (own_request_id IS NULL OR lease.request_id <> own_request_id)
        ) THEN
          RAISE EXCEPTION 'managed auth actor has an in-flight mutation' USING ERRCODE = '55P03';
        END IF;
        IF own_request_id IS NOT NULL THEN
          DELETE FROM managed_auth_actor_mutation_leases
          WHERE session_set_id = set_row.id AND request_id = own_request_id
            AND actor_epoch = set_row.actor_epoch;
        END IF;
        SELECT identity_row.status, binding.status, identity_row.identity_revision,
          identity_row.auth_revision, binding.revision
        INTO identity_status, binding_status, current_identity_revision,
          current_auth_revision, current_binding_revision
        FROM canonical_human_identities identity_row
        INNER JOIN canonical_human_login_bindings binding
          ON binding.id = slot_row.login_binding_id
         AND binding.identity_id = identity_row.id
        WHERE identity_row.id = slot_row.identity_id;
        recovery_transition := slot_row.id = set_row.selected_slot_id
          AND identity_status = 'recovery_required' AND binding_status = 'recovery_pending';
        UPDATE managed_auth_login_slots SET
          auth_session_id = NULL,
          status = CASE WHEN recovery_transition THEN 'active' ELSE 'reauth_required' END,
          identity_revision = CASE WHEN recovery_transition THEN current_identity_revision ELSE identity_revision END,
          auth_revision = CASE WHEN recovery_transition THEN current_auth_revision ELSE auth_revision END,
          login_binding_revision = CASE WHEN recovery_transition THEN current_binding_revision ELSE login_binding_revision END,
          updated_at = pg_catalog.clock_timestamp()
        WHERE id = slot_row.id;
        UPDATE managed_auth_session_sets changed_set SET
          generation = changed_set.generation + 1,
          actor_epoch = changed_set.actor_epoch
            + CASE WHEN slot_row.id = set_row.selected_slot_id THEN 1 ELSE 0 END,
          selected_slot_id = CASE
            WHEN slot_row.id = set_row.selected_slot_id AND NOT recovery_transition THEN NULL
            ELSE changed_set.selected_slot_id END,
          state = CASE
            WHEN slot_row.id = set_row.selected_slot_id THEN 'actor_change_required'
            ELSE changed_set.state END,
          updated_at = pg_catalog.clock_timestamp()
        WHERE changed_set.id = set_row.id;
      END LOOP;
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RETURN OLD;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
      RAISE;
    END;
    $_$;

CREATE FUNCTION managed_sign_in_method_authority(p_user text, p_session text, p_request jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE identity_row canonical_human_identities%ROWTYPE; stamp jsonb := p_request->'actorFence';
BEGIN
  IF stamp IS NOT NULL AND stamp <> 'null'::jsonb THEN
    IF coalesce((p_request->>'callback')::boolean, false) THEN
      PERFORM managed_auth_actor_mutation_lease_acquire(stamp->>'authorityHash', (stamp->>'actorEpoch')::bigint, (stamp->>'requestId')::uuid, 30);
    END IF;
    PERFORM managed_auth_actor_mutation_fence(stamp->>'authorityHash', (stamp->>'actorEpoch')::bigint, (stamp->>'requestId')::uuid);
  END IF;
  PERFORM set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  SELECT i.* INTO identity_row FROM canonical_human_identities i
    JOIN canonical_human_identity_subjects s ON s.identity_id = i.id
    WHERE s.auth_user_id = p_user AND s.status = 'active' FOR UPDATE OF i;
  IF NOT FOUND OR identity_row.status <> 'active'
    OR NOT validate_canonical_human_session(p_session, p_user, false) THEN
    RAISE EXCEPTION 'SIGN_IN_METHOD_AUTHENTICATION_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF identity_row.id IS DISTINCT FROM (p_request->>'expectedIdentityId')::uuid THEN
    RAISE EXCEPTION 'SIGN_IN_METHOD_IDENTITY_CHANGED' USING ERRCODE='40001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth_users WHERE id = p_user AND email_verified) THEN
    RAISE EXCEPTION 'SIGN_IN_METHOD_EMAIL_NOT_VERIFIED' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth_sessions WHERE id = p_session AND user_id = p_user
    AND created_at > clock_timestamp() - interval '5 minutes' AND created_at <= clock_timestamp()) THEN
    RAISE EXCEPTION 'SIGN_IN_METHOD_REAUTHENTICATION_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF identity_row.identity_revision IS DISTINCT FROM (p_request->>'expectedIdentityRevision')::bigint THEN
    RAISE EXCEPTION 'SIGN_IN_METHOD_REVISION_CONFLICT' USING ERRCODE = '40001';
  END IF;
  RETURN identity_row.identity_revision;
END $$;

CREATE TABLE remember_knowledge_memory_materializations (
    confirmation_receipt_id uuid NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    memory_id uuid NOT NULL,
    task_note_text_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT remember_knowledge_memory_materializations_hash_chk CHECK ((task_note_text_hash ~ '^[0-9a-f]{64}$'::text))
);

ALTER TABLE ONLY remember_knowledge_memory_materializations FORCE ROW LEVEL SECURITY;

CREATE FUNCTION materialize_remember_knowledge_memory(p_account_id uuid, p_workspace_id uuid, p_confirmation_receipt_id uuid) RETURNS SETOF remember_knowledge_memory_materializations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  caller_subject_id text := nullif(current_setting('opengeni.subject_id', true), '');
  receipt_row remember_knowledge_confirmation_receipts%ROWTYPE;
  result_row remember_knowledge_memory_materializations%ROWTYPE;
  source_text text;
  memory_id_value uuid;
  normalized_text text;
  normalized_text_hash text;
  visible_count integer;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_confirmation_receipt_id IS NULL
    OR caller_subject_id IS NULL OR length(btrim(caller_subject_id)) NOT BETWEEN 1 AND 1024
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN
    RAISE EXCEPTION 'remember Knowledge Memory materialization requires exact tenant authority'
      USING ERRCODE = '42501';
  END IF;

  -- Serialize every first materialization/replay on the immutable confirmation
  -- identity. The Memory row may later become archived; the mapping remains the
  -- stable answer and is deliberately not foreign-keyed to mutable Memory state.
  SELECT * INTO receipt_row
  FROM remember_knowledge_confirmation_receipts receipt
  WHERE receipt.id = p_confirmation_receipt_id
    AND receipt.account_id = p_account_id
    AND receipt.workspace_id = p_workspace_id
    AND receipt.initiating_human_subject_id = caller_subject_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'remember Knowledge confirmation is unavailable'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO result_row
  FROM remember_knowledge_memory_materializations materialization
  WHERE materialization.confirmation_receipt_id = p_confirmation_receipt_id;
  IF FOUND THEN
    IF result_row.account_id <> p_account_id
      OR result_row.workspace_id <> p_workspace_id
      OR result_row.session_id <> receipt_row.session_id
      OR result_row.task_note_text_hash <> receipt_row.task_note_text_hash
    THEN
      RAISE EXCEPTION 'remember Knowledge Memory materialization conflicts with immutable receipt'
        USING ERRCODE = '23505';
    END IF;
    RETURN NEXT result_row;
    RETURN;
  END IF;

  SELECT fact.object_value #>> '{}'
  INTO source_text
  FROM knowledge_claims claim
  JOIN knowledge_facts fact
    ON fact.account_id = claim.account_id
   AND fact.scope_key = claim.scope_key
   AND fact.id = claim.fact_id
  JOIN knowledge_claim_evidence evidence
    ON evidence.account_id = claim.account_id
   AND evidence.scope_key = claim.scope_key
   AND evidence.claim_id = claim.id
  JOIN knowledge_claim_reviews review
    ON review.account_id = claim.account_id
   AND review.scope_key = claim.scope_key
   AND review.claim_id = claim.id
  WHERE claim.account_id = p_account_id
    AND claim.scope_kind = 'workspace'
    AND claim.scope_workspace_id = p_workspace_id
    AND claim.scope_subject_id IS NULL
    AND claim.id = receipt_row.claim_id
    AND claim.extraction_method = 'task-note-promotion-v1'
    AND claim.initiating_human_subject_id = caller_subject_id
    AND fact.object_kind = 'text'
    AND evidence.id = receipt_row.evidence_id
    AND evidence.task_note_id = receipt_row.task_note_id
    AND evidence.task_note_version = 1
    AND evidence.content_hash = receipt_row.task_note_text_hash
    AND review.id = receipt_row.approval_review_id
    AND review.review_revision = receipt_row.approval_review_revision
    AND review.state = 'approved'
  LIMIT 1;

  normalized_text := lower(btrim(regexp_replace(source_text, '\s+', ' ', 'g')));
  IF source_text IS NULL OR normalized_text = '' OR length(source_text) > 4000
    OR encode(sha256(convert_to(source_text, 'UTF8')), 'hex')
      <> receipt_row.task_note_text_hash
  THEN
    RAISE EXCEPTION 'remember Knowledge confirmation no longer resolves to its exact approved text'
      USING ERRCODE = '23514';
  END IF;
  normalized_text_hash := encode(sha256(convert_to(normalized_text, 'UTF8')), 'hex');

  SELECT count(*)::integer INTO visible_count
  FROM knowledge_memories memory
  WHERE memory.account_id = p_account_id
    AND memory.workspace_id = p_workspace_id
    AND memory.status IN ('active', 'approved');
  IF visible_count >= 2000 THEN
    RAISE EXCEPTION 'Workspace visible Memory is full (2000 visible records)'
      USING ERRCODE = '54000';
  END IF;

  memory_id_value := gen_random_uuid();
  PERFORM set_config('opengeni.memory_actor_kind', 'subject', true);
  PERFORM set_config('opengeni.memory_actor_id', caller_subject_id, true);
  PERFORM set_config('opengeni.memory_session_id', receipt_row.session_id::text, true);

  INSERT INTO knowledge_memories (
    id, account_id, workspace_id, status, kind, scope, text, text_codec_version,
    source_refs, confidence, metadata, created_by_session_id, pinned,
    scope_type, scope_subject_id, scope_role_key, scope_session_id,
    namespace_key, labels, text_hash
  ) VALUES (
    memory_id_value, p_account_id, p_workspace_id, 'active', 'semantic', 'workspace',
    source_text, NULL,
    jsonb_build_array(jsonb_build_object(
      'kind', 'session_event', 'id', receipt_row.session_id, 'metadata', '{}'::jsonb
    )),
    100,
    jsonb_build_object(
      'origin', 'human',
      'source', 'remember_confirmation',
      'confirmationReceiptId', receipt_row.id,
      'claimId', receipt_row.claim_id,
      'evidenceId', receipt_row.evidence_id,
      'taskNoteId', receipt_row.task_note_id
    ),
    receipt_row.session_id, false,
    'workspace', NULL, NULL, NULL,
    'remember/' || receipt_row.id::text, '{}'::text[], normalized_text_hash
  );

  INSERT INTO remember_knowledge_memory_materializations (
    confirmation_receipt_id, account_id, workspace_id, session_id,
    memory_id, task_note_text_hash
  ) VALUES (
    receipt_row.id, p_account_id, p_workspace_id, receipt_row.session_id,
    memory_id_value, receipt_row.task_note_text_hash
  ) RETURNING * INTO result_row;

  RETURN NEXT result_row;
END
$$;

CREATE FUNCTION materialize_scheduled_task_reusable_session_from_run(p_account_id uuid, p_workspace_id uuid, p_task_id uuid, p_run_id uuid, p_session_id uuid, p_source_revision bigint, p_source_digest text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $_$
DECLARE
  task_row record;
  run_row record;
  admission_row record;
  target_revision bigint;
  target_digest text;
  copied_count integer;
  affected integer;
  session_row record;
  snapshot_row record;
  canonical jsonb;
  existing_receipt record;
  has_connection_authority boolean;
  installs_current_head boolean;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
    current_setting('opengeni.account_id', true), ''
  )::uuid OR p_workspace_id IS DISTINCT FROM nullif(
    current_setting('opengeni.workspace_id', true), ''
  )::uuid THEN
    RAISE EXCEPTION 'scheduled reusable-session materialization scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  PERFORM acquire_session_tenancy_fence(p_workspace_id);

  IF p_source_revision <= 0 OR p_source_digest !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'scheduled reusable-session source binding is invalid'
      USING ERRCODE = '22023';
  END IF;
  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_admit')
  ON CONFLICT DO NOTHING;

  -- Serialize first materialization and every concurrent adopter on the task.
  -- The durable receipt, rather than the mutable task head, is authoritative
  -- once one occurrence has materialized the reusable session.
  SELECT task.* INTO STRICT task_row FROM scheduled_tasks task
  WHERE task.id = p_task_id AND task.account_id = p_account_id
    AND task.workspace_id = p_workspace_id
  FOR UPDATE;
  SELECT session_value.* INTO STRICT session_row FROM sessions session_value
  WHERE session_value.id = p_session_id
    AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND (session_value.visibility = 'workspace_shared'
      OR (task_row.visibility = 'user_private' AND session_value.visibility = 'user_private'
        AND session_value.owner_subject_id IS NOT DISTINCT FROM task_row.owner_subject_id))
    AND session_value.status <> 'cancelled'
  FOR NO KEY UPDATE;
  SELECT receipt.* INTO existing_receipt
  FROM scheduled_task_reusable_connection_materializations receipt
  WHERE receipt.task_id = p_task_id
    AND receipt.session_id = p_session_id
    AND (
      (receipt.source_task_authority_revision = p_source_revision
        AND receipt.source_execution_digest = p_source_digest)
      OR (receipt.target_task_authority_revision = p_source_revision
        AND receipt.target_execution_digest = p_source_digest)
    )
  FOR UPDATE;
  IF FOUND THEN
    IF existing_receipt.account_id IS DISTINCT FROM p_account_id
      OR existing_receipt.workspace_id IS DISTINCT FROM p_workspace_id
      OR existing_receipt.session_id IS DISTINCT FROM p_session_id
      OR NOT (
        (existing_receipt.source_task_authority_revision = p_source_revision
          AND existing_receipt.source_execution_digest = p_source_digest)
        OR
        (existing_receipt.target_task_authority_revision = p_source_revision
          AND existing_receipt.target_execution_digest = p_source_digest)
      )
    THEN RAISE EXCEPTION 'scheduled reusable connection materialization changed'
      USING ERRCODE = '23505';
    END IF;
    target_revision := existing_receipt.target_task_authority_revision;
    target_digest := existing_receipt.target_execution_digest;

    SELECT run.* INTO STRICT run_row FROM scheduled_task_runs run
    WHERE run.id = p_run_id AND run.task_id = p_task_id
      AND run.account_id = p_account_id AND run.workspace_id = p_workspace_id
      AND run.status = 'queued' AND run.session_id = p_session_id
      AND (
        (run.task_authority_revision = existing_receipt.source_task_authority_revision
          AND run.task_execution_digest = existing_receipt.source_execution_digest)
        OR
        (run.task_authority_revision = target_revision
          AND run.task_execution_digest = target_digest)
      )
    FOR UPDATE;

    SELECT admission.* INTO admission_row
    FROM scheduled_task_run_personal_resource_admissions admission
    WHERE admission.run_id = p_run_id
    FOR UPDATE;
    IF FOUND AND admission_row.task_authority_revision = existing_receipt.source_task_authority_revision
      AND admission_row.execution_digest = existing_receipt.source_execution_digest
    THEN
      UPDATE scheduled_task_run_personal_resource_snapshots snapshot
      SET task_authority_revision = target_revision
      WHERE snapshot.run_id = p_run_id
        AND snapshot.task_id = p_task_id
        AND snapshot.task_authority_revision = existing_receipt.source_task_authority_revision;
      GET DIAGNOSTICS affected = ROW_COUNT;
      IF affected <> admission_row.resource_count THEN RAISE EXCEPTION
        'scheduled reusable-session adopted resource snapshot is incomplete'
        USING ERRCODE = '42501'; END IF;
      UPDATE scheduled_task_run_personal_resource_admissions admission
      SET task_authority_revision = target_revision,
        execution_digest = target_digest
      WHERE admission.run_id = p_run_id
        AND admission.task_authority_revision = existing_receipt.source_task_authority_revision
        AND admission.execution_digest = existing_receipt.source_execution_digest;
      GET DIAGNOSTICS affected = ROW_COUNT;
      IF affected <> 1 THEN RAISE EXCEPTION
        'scheduled reusable-session adopted resource admission changed'
        USING ERRCODE = '42501'; END IF;
    ELSIF FOUND AND (
      admission_row.task_authority_revision IS DISTINCT FROM target_revision
      OR admission_row.execution_digest IS DISTINCT FROM target_digest
    ) THEN RAISE EXCEPTION 'scheduled reusable-session adopted resource admission changed'
      USING ERRCODE = '42501';
    END IF;

    FOR snapshot_row IN SELECT snapshot.*
      FROM scheduled_task_run_connection_authority_snapshots snapshot
      WHERE snapshot.run_id = p_run_id
      ORDER BY snapshot.server_id
      FOR UPDATE
    LOOP
      IF snapshot_row.task_id IS DISTINCT FROM p_task_id THEN
        RAISE EXCEPTION 'scheduled reusable connection run binding changed'
          USING ERRCODE = '42501';
      END IF;
      IF snapshot_row.task_authority_revision = existing_receipt.source_task_authority_revision
        AND snapshot_row.execution_digest = existing_receipt.source_execution_digest
      THEN
        IF snapshot_row.target_session_id IS DISTINCT FROM p_session_id
          OR NOT (snapshot_row.session_authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
          OR snapshot_row.grant_mode <> 'always'
          OR snapshot_row.grant_context <> 'workspace_shared'
        THEN RAISE EXCEPTION 'scheduled reusable connection run cannot be adopted'
          USING ERRCODE = '42501'; END IF;
        canonical := snapshot_row.canonical_snapshot || jsonb_build_object(
          'taskAuthorityRevision', target_revision,
          'executionDigest', target_digest,
          'targetSessionId', p_session_id,
          'sessionVisibility', session_row.visibility,
          'sessionAuthorityEpoch', session_row.authority_epoch
        );
        UPDATE scheduled_task_run_connection_authority_snapshots snapshot
        SET task_authority_revision = target_revision,
          execution_digest = target_digest,
          target_session_id = p_session_id,
          session_visibility = session_row.visibility,
          session_authority_epoch = session_row.authority_epoch,
          canonical_snapshot = canonical,
          snapshot_digest = digest(convert_to(canonical::text, 'UTF8'), 'sha256'),
          bound_at = clock_timestamp()
        WHERE snapshot.run_id = p_run_id
          AND snapshot.server_id = snapshot_row.server_id;
      ELSIF snapshot_row.task_authority_revision IS DISTINCT FROM target_revision
        OR snapshot_row.execution_digest IS DISTINCT FROM target_digest
        OR snapshot_row.target_session_id IS DISTINCT FROM p_session_id
        OR NOT (snapshot_row.session_authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
      THEN RAISE EXCEPTION 'scheduled reusable connection adopted binding changed'
        USING ERRCODE = '42501';
      END IF;
    END LOOP;

    IF run_row.task_authority_revision = existing_receipt.source_task_authority_revision THEN
      UPDATE scheduled_task_runs run
      SET task_authority_revision = target_revision,
        task_execution_digest = target_digest,
        updated_at = clock_timestamp()
      WHERE run.id = p_run_id
        AND run.task_authority_revision = existing_receipt.source_task_authority_revision
        AND run.task_execution_digest = existing_receipt.source_execution_digest;
      GET DIAGNOSTICS affected = ROW_COUNT;
      IF affected <> 1 THEN RAISE EXCEPTION
        'scheduled reusable connection adopted run changed'
        USING ERRCODE = '42501'; END IF;
    END IF;
    DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
    WHERE backend_pid = pg_backend_pid()
      AND transaction_id = pg_current_xact_id_if_assigned()
      AND capability_kind = 'run_admit';
    RETURN target_revision;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM scheduled_task_run_connection_authority_snapshots snapshot
    WHERE snapshot.run_id = p_run_id
  ) INTO has_connection_authority;
  PERFORM 1 FROM scheduled_task_runs run
  WHERE run.id = p_run_id AND run.task_id = p_task_id
    AND run.account_id = p_account_id AND run.workspace_id = p_workspace_id
    AND run.status = 'queued' AND run.session_id = p_session_id
    AND run.task_authority_revision = p_source_revision
    AND run.task_execution_digest = p_source_digest
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION
    'scheduled reusable run session binding changed'
    USING ERRCODE = '40001'; END IF;
  PERFORM 1 FROM sessions session_value
  WHERE session_value.id = p_session_id AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND (session_value.visibility = 'workspace_shared'
      OR (task_row.visibility = 'user_private' AND session_value.visibility = 'user_private'
        AND session_value.owner_subject_id IS NOT DISTINCT FROM task_row.owner_subject_id))
    AND session_value.status <> 'cancelled'
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION
    'scheduled reusable session must be workspace-shared'
    USING ERRCODE = '42501'; END IF;
  installs_current_head := task_row.status = 'active'
    AND task_row.run_mode = 'reusable_session'
    AND task_row.reusable_session_id IS NULL
    AND task_row.authority_revision = p_source_revision
    AND task_row.execution_digest = p_source_digest;

  IF installs_current_head AND EXISTS (
    SELECT 1 FROM scheduled_task_run_personal_resource_admissions admission
    WHERE admission.run_id = p_run_id
      AND admission.task_id = p_task_id
      AND admission.account_id = p_account_id
      AND admission.workspace_id = p_workspace_id
      AND admission.task_authority_revision = p_source_revision
      AND admission.execution_digest = p_source_digest
  ) THEN
    SELECT materialize_scheduled_task_reusable_session_from_run_0252(
      p_account_id, p_workspace_id, p_task_id, p_run_id, p_session_id,
      p_source_revision, p_source_digest
    ) INTO target_revision;
    IF target_revision IS DISTINCT FROM p_source_revision THEN
      PERFORM clone_scheduled_task_revision_authority(
        p_account_id, p_workspace_id, p_task_id, p_source_revision, target_revision
      );
    END IF;
    SELECT run.task_execution_digest INTO STRICT target_digest
    FROM scheduled_task_runs run
    WHERE run.id = p_run_id
      AND run.task_id = p_task_id
      AND run.account_id = p_account_id
      AND run.workspace_id = p_workspace_id
      AND run.task_authority_revision = target_revision
      AND run.session_id = p_session_id;
  ELSIF installs_current_head THEN
    INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
      backend_pid, transaction_id, capability_kind
    ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_admit')
    ON CONFLICT DO NOTHING;
    PERFORM 1 FROM scheduled_task_runs run
    WHERE run.id = p_run_id AND run.task_id = p_task_id
      AND run.account_id = p_account_id AND run.workspace_id = p_workspace_id
      AND run.status = 'queued'
      AND run.session_id = p_session_id
      AND run.task_authority_revision = p_source_revision
      AND run.task_execution_digest = p_source_digest
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'scheduled reusable-session run binding changed'
      USING ERRCODE = '40001'; END IF;
    PERFORM 1 FROM sessions session_value
    WHERE session_value.id = p_session_id AND session_value.account_id = p_account_id
      AND session_value.workspace_id = p_workspace_id
      AND (session_value.visibility = 'workspace_shared'
      OR (task_row.visibility = 'user_private' AND session_value.visibility = 'user_private'
        AND session_value.owner_subject_id IS NOT DISTINCT FROM task_row.owner_subject_id))
      AND session_value.status <> 'cancelled'
    FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'scheduled reusable-session target is unavailable'
      USING ERRCODE = '42501'; END IF;
    PERFORM 1 FROM scheduled_tasks task
    WHERE task.id = p_task_id AND task.account_id = p_account_id
      AND task.workspace_id = p_workspace_id AND task.status = 'active'
      AND task.run_mode = 'reusable_session' AND task.reusable_session_id IS NULL
      AND task.authority_revision = p_source_revision
      AND task.execution_digest = p_source_digest
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION
      'scheduled reusable-session task changed before materialization'
      USING ERRCODE = '40001'; END IF;
    UPDATE scheduled_tasks task
    SET reusable_session_id = p_session_id,
      authority_revision = task.authority_revision + 1,
      updated_at = clock_timestamp()
    WHERE task.id = p_task_id AND task.account_id = p_account_id
      AND task.workspace_id = p_workspace_id
    RETURNING task.authority_revision, task.execution_digest
      INTO STRICT target_revision, target_digest;
    SELECT clone_scheduled_task_personal_resource_authority(
      p_account_id, p_workspace_id, p_task_id, p_source_revision, target_revision
    ) INTO copied_count;
    IF copied_count <> 0 THEN RAISE EXCEPTION
      'unexpected scheduled reusable personal-resource authority appeared'
      USING ERRCODE = '42501'; END IF;
    -- The installed head is a new revision of the same accepted human authority;
    -- clone it so the next occurrence still resolves the exact causal human.
    PERFORM clone_scheduled_task_revision_authority(
      p_account_id, p_workspace_id, p_task_id, p_source_revision, target_revision
    );
    UPDATE scheduled_task_runs run
    SET task_authority_revision = target_revision,
      task_execution_digest = target_digest,
      updated_at = clock_timestamp()
    WHERE run.id = p_run_id AND run.task_authority_revision = p_source_revision
      AND run.task_execution_digest = p_source_digest;
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN RAISE EXCEPTION
      'scheduled reusable connection run row rebind failed'
      USING ERRCODE = '42501'; END IF;
    DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
    WHERE backend_pid = pg_backend_pid()
      AND transaction_id = pg_current_xact_id_if_assigned()
      AND capability_kind = 'run_admit';
  ELSE
    -- The occurrence was admitted before the task head changed or paused. It
    -- still owns its immutable run/session truth, but must not install an old
    -- session pointer into the newer task head. A same-revision receipt makes
    -- this detached materialization durable and adoptable without rewriting
    -- either the task or the already-admitted 0252 authority.
    target_revision := p_source_revision;
    target_digest := p_source_digest;
  END IF;
  SELECT session_value.* INTO STRICT session_row FROM sessions session_value
  WHERE session_value.id = p_session_id AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id AND session_value.status <> 'cancelled'
  FOR SHARE;

  FOR snapshot_row IN SELECT snapshot.*
    FROM scheduled_task_run_connection_authority_snapshots snapshot
    WHERE snapshot.run_id = p_run_id
    ORDER BY snapshot.server_id
    FOR UPDATE
  LOOP
    IF snapshot_row.task_id IS DISTINCT FROM p_task_id
      OR snapshot_row.task_authority_revision IS DISTINCT FROM p_source_revision
      OR snapshot_row.execution_digest IS DISTINCT FROM p_source_digest
      OR snapshot_row.target_session_id IS DISTINCT FROM p_session_id
      OR NOT (snapshot_row.session_authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
      OR snapshot_row.grant_mode <> 'always'
      OR snapshot_row.grant_context <> 'workspace_shared'
    THEN RAISE EXCEPTION 'scheduled reusable connection run binding changed'
      USING ERRCODE = '42501';
    END IF;
    canonical := snapshot_row.canonical_snapshot || jsonb_build_object(
      'taskAuthorityRevision', target_revision,
      'executionDigest', target_digest,
      'targetSessionId', p_session_id,
      'sessionVisibility', session_row.visibility,
      'sessionAuthorityEpoch', session_row.authority_epoch
    );
    UPDATE scheduled_task_run_connection_authority_snapshots snapshot
    SET task_authority_revision = target_revision,
      execution_digest = target_digest,
      target_session_id = p_session_id,
      session_visibility = session_row.visibility,
      session_authority_epoch = session_row.authority_epoch,
      canonical_snapshot = canonical,
      snapshot_digest = digest(convert_to(canonical::text, 'UTF8'), 'sha256'),
      bound_at = clock_timestamp()
    WHERE snapshot.run_id = p_run_id AND snapshot.server_id = snapshot_row.server_id;
  END LOOP;

  SELECT receipt.* INTO existing_receipt
  FROM scheduled_task_reusable_connection_materializations receipt
  WHERE receipt.run_id = p_run_id
    OR (
      receipt.task_id = p_task_id
      AND receipt.session_id = p_session_id
      AND receipt.source_task_authority_revision = p_source_revision
      AND receipt.source_execution_digest = p_source_digest
    );
  IF FOUND THEN
    IF existing_receipt.run_id IS DISTINCT FROM p_run_id
      OR existing_receipt.session_id IS DISTINCT FROM p_session_id
      OR existing_receipt.source_task_authority_revision IS DISTINCT FROM p_source_revision
      OR existing_receipt.target_task_authority_revision IS DISTINCT FROM target_revision
      OR existing_receipt.source_execution_digest IS DISTINCT FROM p_source_digest
      OR existing_receipt.target_execution_digest IS DISTINCT FROM target_digest
    THEN RAISE EXCEPTION 'scheduled reusable connection materialization changed'
      USING ERRCODE = '23505';
    END IF;
  ELSE
    INSERT INTO scheduled_task_reusable_connection_materializations (
      task_id, run_id, account_id, workspace_id, session_id,
      source_task_authority_revision, target_task_authority_revision,
      source_execution_digest, target_execution_digest
    ) VALUES (
      p_task_id, p_run_id, p_account_id, p_workspace_id, p_session_id,
      p_source_revision, target_revision, p_source_digest, target_digest
    );
  END IF;
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_admit';
  RETURN target_revision;
END
$_$;

CREATE FUNCTION materialize_scheduled_task_reusable_session_from_run_0252(p_account_id uuid, p_workspace_id uuid, p_task_id uuid, p_run_id uuid, p_session_id uuid, p_source_task_authority_revision bigint, p_source_execution_digest text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  task_row record;
  admission_row record;
  target_revision bigint;
  target_execution_digest text;
  copied_count integer;
  affected integer;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'scheduled reusable-session materialization scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF p_source_task_authority_revision <= 0
    OR p_source_execution_digest !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'scheduled reusable-session source binding is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_admit')
  ON CONFLICT DO NOTHING;

  SELECT admission.* INTO admission_row
  FROM scheduled_task_run_personal_resource_admissions admission
  WHERE admission.run_id = p_run_id
    AND admission.task_id = p_task_id
    AND admission.account_id = p_account_id
    AND admission.workspace_id = p_workspace_id
    AND admission.task_authority_revision = p_source_task_authority_revision
    AND admission.execution_digest = p_source_execution_digest
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled reusable-session admission binding changed'
      USING ERRCODE = '40001';
  END IF;

  PERFORM 1
  FROM scheduled_task_runs run
  WHERE run.id = p_run_id
    AND run.task_id = p_task_id
    AND run.account_id = p_account_id
    AND run.workspace_id = p_workspace_id
    AND run.status = 'queued'
    AND run.task_authority_revision = p_source_task_authority_revision
    AND run.task_execution_digest = p_source_execution_digest
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled reusable-session run binding changed'
      USING ERRCODE = '40001';
  END IF;

  PERFORM 1
  FROM sessions session_value
  WHERE session_value.id = p_session_id
    AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND session_value.status <> 'cancelled'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled reusable-session target is unavailable'
      USING ERRCODE = '42501';
  END IF;

  SELECT task.* INTO task_row
  FROM scheduled_tasks task
  WHERE task.id = p_task_id
    AND task.account_id = p_account_id
    AND task.workspace_id = p_workspace_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled reusable-session task is unavailable'
      USING ERRCODE = '40001';
  END IF;
  IF task_row.status <> 'active'
    OR task_row.run_mode <> 'reusable_session'
    OR task_row.reusable_session_id IS NOT NULL
    OR task_row.authority_revision IS DISTINCT FROM p_source_task_authority_revision
    OR task_row.execution_digest IS DISTINCT FROM p_source_execution_digest
  THEN
    RAISE EXCEPTION 'scheduled reusable-session task changed before materialization'
      USING ERRCODE = '40001';
  END IF;

  UPDATE scheduled_tasks task
  SET reusable_session_id = p_session_id,
    authority_revision = task.authority_revision + 1,
    updated_at = clock_timestamp()
  WHERE task.id = p_task_id
    AND task.account_id = p_account_id
    AND task.workspace_id = p_workspace_id
  RETURNING task.authority_revision, task.execution_digest
  INTO STRICT target_revision, target_execution_digest;

  SELECT clone_scheduled_task_personal_resource_authority(
    p_account_id,
    p_workspace_id,
    p_task_id,
    p_source_task_authority_revision,
    target_revision
  ) INTO copied_count;
  IF copied_count <> admission_row.resource_count THEN
    RAISE EXCEPTION 'scheduled reusable-session authority clone is incomplete'
      USING ERRCODE = '42501';
  END IF;

  UPDATE scheduled_task_run_personal_resource_snapshots snapshot
  SET task_authority_revision = target_revision
  WHERE snapshot.run_id = p_run_id
    AND snapshot.task_id = p_task_id
    AND snapshot.task_authority_revision = p_source_task_authority_revision;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> admission_row.resource_count THEN
    RAISE EXCEPTION 'scheduled reusable-session run snapshot rebind is incomplete'
      USING ERRCODE = '42501';
  END IF;

  UPDATE scheduled_task_run_personal_resource_admissions admission
  SET task_authority_revision = target_revision,
    execution_digest = target_execution_digest
  WHERE admission.run_id = p_run_id
    AND admission.task_authority_revision = p_source_task_authority_revision
    AND admission.execution_digest = p_source_execution_digest;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'scheduled reusable-session run admission rebind failed'
      USING ERRCODE = '42501';
  END IF;

  UPDATE scheduled_task_runs run
  SET task_authority_revision = target_revision,
    task_execution_digest = target_execution_digest,
    updated_at = clock_timestamp()
  WHERE run.id = p_run_id
    AND run.task_authority_revision = p_source_task_authority_revision
    AND run.task_execution_digest = p_source_execution_digest;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'scheduled reusable-session run row rebind failed'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_admit';
  RETURN target_revision;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_admit';
  RAISE;
END
$_$;

CREATE FUNCTION materialize_scoped_rig_version_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  session_row sessions%ROWTYPE;
  rig_row rigs%ROWTYPE;
  version_row rig_versions%ROWTYPE;
  initiating_subject text;
  resolved_count integer;
  result jsonb;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.workspace_id', true), '')::uuid
  THEN RAISE EXCEPTION 'rig runtime scope mismatch' USING ERRCODE = '42501'; END IF;
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'runtime')
  ON CONFLICT DO NOTHING;
  SELECT session_value.* INTO STRICT session_row
  FROM sessions session_value
  JOIN session_turns turn_value ON turn_value.id = p_turn_id
    AND turn_value.account_id = session_value.account_id
    AND turn_value.workspace_id = session_value.workspace_id
    AND turn_value.session_id = session_value.id
  JOIN session_turn_attempts attempt ON attempt.id = p_attempt_id
    AND attempt.account_id = session_value.account_id
    AND attempt.workspace_id = session_value.workspace_id
    AND attempt.session_id = session_value.id AND attempt.turn_id = turn_value.id
  WHERE session_value.id = p_session_id AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND session_value.active_turn_id = p_turn_id
    AND turn_value.active_attempt_id = p_attempt_id
    AND turn_value.execution_generation = p_execution_generation
    AND turn_value.status = 'running'
    AND attempt.execution_generation = p_execution_generation
    AND attempt.state IN ('claimed','running') AND attempt.closed_at IS NULL
    AND attempt.quiesced_at IS NULL
  FOR SHARE OF session_value, turn_value, attempt;
  initiating_subject := coalesce(
    nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''),
    nullif(pg_catalog.current_setting('opengeni.subject_id', true), '')
  );
  SELECT rig.* INTO STRICT rig_row FROM rigs rig
  WHERE rig.id = session_row.rig_id AND rig.account_id = p_account_id
    AND rig.status = 'active' FOR SHARE;
  SELECT version.* INTO STRICT version_row FROM rig_versions version
  WHERE version.id = session_row.rig_version_id AND version.rig_id = rig_row.id
    AND version.account_id = p_account_id FOR SHARE;
  IF rig_row.authority_scope = 'workspace'
    AND rig_row.workspace_id IS DISTINCT FROM p_workspace_id
  THEN RAISE EXCEPTION 'workspace rig is outside the runtime workspace'
    USING ERRCODE = '42501';
  ELSIF rig_row.authority_scope = 'user' THEN
    SELECT count(*)::integer INTO resolved_count
    FROM resolve_session_attempt_personal_resources(
      p_account_id, p_workspace_id, p_attempt_id
    ) resolved
    WHERE resolved.resource_kind = 'rig' AND resolved.resource_id = rig_row.id
      AND resolved.resource_version_id = version_row.id
      AND resolved.authority_id = rig_row.authority_id
      AND resolved.authority_generation = rig_row.generation;
    IF resolved_count <> 1 THEN
      RAISE EXCEPTION 'personal rig grant is not exact or current'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  result := pg_catalog.jsonb_build_object(
    'rigName', rig_row.name,
    'version', pg_catalog.jsonb_build_object(
      'id', version_row.id, 'rigId', version_row.rig_id,
      'version', version_row.version, 'image', version_row.image,
      'setupScript', version_row.setup_script, 'checks', version_row.checks,
      'credentialHooks', version_row.credential_hooks,
      'defaultVariableSetIds', version_row.default_variable_set_ids,
      'changelog', version_row.changelog, 'providerImages', version_row.provider_images,
      'createdBy', version_row.created_by, 'active', version_row.active,
      'createdAt', version_row.created_at
    )
  );
  INSERT INTO audit_events(
    account_id, workspace_id, subject_id, action, target_type, target_id,
    metadata, metadata_codec_version
  ) VALUES (
    p_account_id, p_workspace_id, initiating_subject, 'rig.materialized', 'rig',
    rig_row.id::text, pg_catalog.jsonb_build_object(
      'scope', rig_row.authority_scope, 'generation', rig_row.generation,
      'versionId', version_row.id, 'sessionId', p_session_id,
      'turnId', p_turn_id, 'attemptId', p_attempt_id,
      'executionGeneration', p_execution_generation
    ), 1
  );
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'runtime';
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION materialize_scoped_variable_set_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_variable_set_id uuid) RETURNS TABLE(variable_set_id uuid, variable_set_name text, variable_set_description text, authority_scope text, variable_set_generation bigint, variable_name text, value_encrypted text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  audit_subject text;
  causal_human text;
  audit_actor_kind text;
  variable_set_row workspace_variable_sets%ROWTYPE;
  resolved_count integer;
  attempt_authority_epoch integer;
  attempt_authority_visibility text;
  attempt_owner_membership uuid;
BEGIN
  INSERT INTO opengeni_private.variable_set_authority_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'materialize')
  ON CONFLICT DO NOTHING;

  SELECT actor_subject, causal_human_subject, actor_kind
  INTO STRICT audit_subject, causal_human, audit_actor_kind
  FROM assert_scoped_variable_set_materialization_attempt(
    p_account_id, p_workspace_id, p_session_id, p_turn_id, p_attempt_id,
    p_execution_generation
  );

  -- Attribution evidence (0280): the exact attempt the assert above already
  -- validated owns the frozen session tenancy authority for this use.
  SELECT attempt.authority_epoch, attempt.authority_visibility,
    attempt.authority_owner_organization_membership_id
  INTO attempt_authority_epoch, attempt_authority_visibility, attempt_owner_membership
  FROM session_turn_attempts attempt
  WHERE attempt.id = p_attempt_id
    AND attempt.account_id = p_account_id
    AND attempt.workspace_id = p_workspace_id;

  SELECT variable_set.* INTO STRICT variable_set_row
  FROM workspace_variable_sets variable_set
  WHERE variable_set.id = p_variable_set_id
    AND variable_set.account_id = p_account_id
    AND variable_set.status = 'active'
  FOR SHARE;

  PERFORM 1 FROM sessions session_value
  LEFT JOIN rig_versions rig_version
    ON rig_version.id = session_value.rig_version_id
   AND rig_version.rig_id = session_value.rig_id
   AND rig_version.account_id = session_value.account_id
  WHERE session_value.id = p_session_id
    AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND (
      coalesce(session_value.variable_set_ids, '[]'::jsonb) ? variable_set_row.id::text
      OR coalesce(rig_version.default_variable_set_ids, '[]'::jsonb)
        ? variable_set_row.id::text
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'runtime variable set was not selected by the exact session'
      USING ERRCODE = '42501';
  END IF;

  IF variable_set_row.authority_scope = 'workspace'
    AND variable_set_row.workspace_id IS DISTINCT FROM p_workspace_id
  THEN
    RAISE EXCEPTION 'workspace variable set is outside the runtime workspace'
      USING ERRCODE = '42501';
  ELSIF variable_set_row.authority_scope = 'user' THEN
    IF causal_human IS NULL THEN
      RAISE EXCEPTION 'personal variable-set materialization requires an initiating human subject'
        USING ERRCODE = '42501';
    END IF;
    SELECT count(*)::integer INTO resolved_count
    FROM resolve_session_attempt_personal_resources(
      p_account_id, p_workspace_id, p_attempt_id
    ) resolved
    WHERE resolved.resource_kind = 'variable_set'
      AND resolved.resource_id = variable_set_row.id
      AND resolved.authority_id = variable_set_row.authority_id
      AND resolved.authority_generation = variable_set_row.generation;
    IF resolved_count <> 1 THEN
      RAISE EXCEPTION 'personal variable-set grant is not exact or current'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO audit_events (
    account_id, workspace_id, subject_id, action, target_type, target_id,
    metadata, metadata_codec_version
  ) VALUES (
    p_account_id, p_workspace_id, audit_subject,
    'variable_set.materialized', 'workspace_variable_set',
    variable_set_row.id::text,
    pg_catalog.jsonb_build_object(
      'variableSetId', variable_set_row.id,
      'scope', variable_set_row.authority_scope,
      'generation', variable_set_row.generation,
      'actorKind', audit_actor_kind,
      'sessionId', p_session_id,
      'turnId', p_turn_id,
      'attemptId', p_attempt_id,
      'executionGeneration', p_execution_generation,
      'causalHumanSubjectId', causal_human,
      'authorityEpoch', attempt_authority_epoch,
      'authorityVisibility', attempt_authority_visibility,
      'authorityOwnerOrganizationMembershipId', attempt_owner_membership,
      'ownerAuthorityId', variable_set_row.authority_id,
      'ownerOrganizationMembershipId', variable_set_row.owner_organization_membership_id,
      'originWorkspaceId', variable_set_row.origin_workspace_id
    ),
    1
  );

  RETURN QUERY
  SELECT selected.id, selected.name, selected.description,
    selected.authority_scope, selected.generation,
    variable.name, variable.value_encrypted
  FROM workspace_variable_sets selected
  LEFT JOIN workspace_variable_set_variables variable
    ON variable.account_id = selected.account_id
   AND variable.variable_set_id = selected.id
  WHERE selected.id = variable_set_row.id
  ORDER BY variable.name;

  DELETE FROM opengeni_private.variable_set_authority_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'materialize';
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.variable_set_authority_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'materialize';
  RAISE;
END
$$;

COMMENT ON FUNCTION materialize_scoped_variable_set_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_variable_set_id uuid) IS 'Only ciphertext egress for runtime injection; exact service attempts may materialize organization/workspace sets, while personal sets require an exact causal-human grant.';

CREATE FUNCTION materialize_scoped_variable_set_for_session(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_variable_set_id uuid) RETURNS TABLE(variable_set_id uuid, variable_set_name text, variable_set_description text, authority_scope text, variable_set_generation bigint, variable_name text, value_encrypted text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  selected_row record;
  variable_set_row workspace_variable_sets%ROWTYPE;
  session_authority_epoch integer;
  session_authority_visibility text;
  session_owner_membership uuid;
  audit_subject text;
  causal_human text;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'variable-set session materialization scope mismatch'
      USING ERRCODE = '42501';
  END IF;

  audit_subject := coalesce(
    nullif(pg_catalog.current_setting('opengeni.subject_id', true), ''),
    'service:session'
  );
  causal_human := coalesce(
    nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''),
    CASE WHEN audit_subject LIKE 'user:%' THEN audit_subject END
  );

  INSERT INTO opengeni_private.variable_set_authority_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'materialize')
  ON CONFLICT DO NOTHING;
  INSERT INTO opengeni_private.personal_resource_delegation_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'resolve')
  ON CONFLICT DO NOTHING;

  SELECT variable_set AS selected_set,
    session_value.authority_epoch AS session_epoch,
    session_value.visibility AS session_visibility,
    session_value.owner_organization_membership_id AS session_owner_membership
  INTO selected_row
  FROM sessions session_value
  LEFT JOIN rig_versions rig_version
    ON rig_version.id = session_value.rig_version_id
   AND rig_version.rig_id = session_value.rig_id
   AND rig_version.account_id = session_value.account_id
  JOIN workspace_variable_sets variable_set
    ON variable_set.id = p_variable_set_id
   AND variable_set.account_id = session_value.account_id
  WHERE session_value.id = p_session_id
    AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
    AND (
      coalesce(session_value.variable_set_ids, '[]'::jsonb) ? p_variable_set_id::text
      OR coalesce(rig_version.default_variable_set_ids, '[]'::jsonb)
        ? p_variable_set_id::text
    )
    AND session_value.status IN (
      'queued', 'running', 'idle', 'requires_action', 'recovering', 'waiting_capacity', 'failed'
    )
    AND variable_set.status = 'active'
    AND (
      variable_set.authority_scope IN ('organization', 'user')
      OR (
        variable_set.authority_scope = 'workspace'
        AND variable_set.workspace_id = p_workspace_id
      )
    )
  FOR SHARE OF session_value, variable_set;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'variable set is not selected by, or not available to, the exact session'
      USING ERRCODE = '42501';
  END IF;
  variable_set_row := selected_row.selected_set;
  session_authority_epoch := selected_row.session_epoch;
  session_authority_visibility := selected_row.session_visibility;
  session_owner_membership := selected_row.session_owner_membership;

  IF variable_set_row.authority_scope = 'user' THEN
    PERFORM 1
    FROM organization_memberships membership
    JOIN organization_user_resource_authorities authority
      ON authority.id = variable_set_row.authority_id
     AND authority.account_id = membership.account_id
     AND authority.organization_membership_id = membership.id
     AND authority.resource_kind = 'variable_set'
     AND authority.resource_id = variable_set_row.id
     AND authority.origin_workspace_id IS NOT DISTINCT FROM variable_set_row.origin_workspace_id
     AND authority.generation = variable_set_row.generation
     AND authority.status = 'active'
     AND authority.revoked_at IS NULL
    JOIN organization_user_resource_grants grant_value
      ON grant_value.account_id = authority.account_id
     AND grant_value.authority_id = authority.id
     AND grant_value.owner_organization_membership_id = membership.id
     AND grant_value.workspace_id = p_workspace_id
     AND grant_value.action = 'variable_set.use'
     AND grant_value.context = session_authority_visibility
     AND grant_value.status = 'active'
     AND (grant_value.expires_at IS NULL OR grant_value.expires_at > clock_timestamp())
     AND (
       (
         grant_value.mode = 'session'
         AND grant_value.session_id = p_session_id
         AND grant_value.authority_epoch = session_authority_epoch
       )
       OR (
         grant_value.mode = 'always'
         AND grant_value.session_id IS NULL
         AND grant_value.authority_epoch IS NULL
       )
     )
    WHERE membership.id = variable_set_row.owner_organization_membership_id
      AND membership.account_id = p_account_id
      AND membership.subject_id = causal_human
      AND membership.status = 'active'
      AND membership.revoked_at IS NULL
      AND membership.authorization_revision > 0
      AND (
        membership.personal_workspace_id = p_workspace_id
        OR EXISTS (
          SELECT 1
          FROM workspace_memberships workspace_membership
          WHERE workspace_membership.account_id = membership.account_id
            AND workspace_membership.workspace_id = p_workspace_id
            AND workspace_membership.subject_id = membership.subject_id
        )
      )
      AND (
        session_authority_visibility = 'workspace_shared'
        OR session_owner_membership = membership.id
      )
    ORDER BY grant_value.id
    FOR SHARE OF membership, authority, grant_value;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'personal variable-set session grant is not exact or current'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO audit_events (
    account_id, workspace_id, subject_id, action, target_type, target_id,
    metadata, metadata_codec_version
  ) VALUES (
    p_account_id, p_workspace_id, audit_subject,
    'variable_set.materialized', 'workspace_variable_set',
    variable_set_row.id::text,
    pg_catalog.jsonb_build_object(
      'variableSetId', variable_set_row.id,
      'scope', variable_set_row.authority_scope,
      'generation', variable_set_row.generation,
      'actorKind', 'session_attach',
      'sessionId', p_session_id,
      'causalHumanSubjectId', causal_human,
      'authorityEpoch', session_authority_epoch,
      'authorityVisibility', session_authority_visibility,
      'authorityOwnerOrganizationMembershipId', session_owner_membership,
      'ownerAuthorityId', variable_set_row.authority_id,
      'ownerOrganizationMembershipId', variable_set_row.owner_organization_membership_id,
      'originWorkspaceId', variable_set_row.origin_workspace_id
    ),
    1
  );

  RETURN QUERY
  SELECT selected.id, selected.name, selected.description,
    selected.authority_scope, selected.generation,
    variable.name, variable.value_encrypted
  FROM workspace_variable_sets selected
  LEFT JOIN workspace_variable_set_variables variable
    ON variable.account_id = selected.account_id
   AND variable.variable_set_id = selected.id
  WHERE selected.id = variable_set_row.id
  ORDER BY variable.name;

  DELETE FROM opengeni_private.personal_resource_delegation_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'resolve';
  DELETE FROM opengeni_private.variable_set_authority_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'materialize';
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.personal_resource_delegation_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'resolve';
  DELETE FROM opengeni_private.variable_set_authority_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'materialize';
  RAISE;
END
$$;

CREATE FUNCTION mcp_operation_command(p_scope jsonb, p_action text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE result jsonb;
      prior_subject text := current_setting('opengeni.subject_id',true);
      prior_human text := current_setting('opengeni.initiating_human_subject_id',true);
      prior_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle',true);
    BEGIN
      result := opengeni_private.mcp_operation_command_scoped(p_scope,p_action,p_payload);
      PERFORM set_config('opengeni.subject_id',coalesce(prior_subject,''),true);
      PERFORM set_config('opengeni.initiating_human_subject_id',coalesce(prior_human,''),true);
      PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);
      RETURN result;
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('opengeni.subject_id',coalesce(prior_subject,''),true);
      PERFORM set_config('opengeni.initiating_human_subject_id',coalesce(prior_human,''),true);
      PERFORM set_config('opengeni.organization_tenancy_lifecycle',coalesce(prior_lifecycle,''),true);
      RAISE;
    END $$;

CREATE FUNCTION meter_session_usage_limit_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE opened integer; v_root uuid; previous_subject text; previous_account text;
  previous_workspace text;
BEGIN
  IF NEW.turn_id IS NULL OR jsonb_typeof(NEW.payload) IS DISTINCT FROM 'object'
    OR jsonb_typeof(NEW.payload->'sourceKey') IS DISTINCT FROM 'string'
    OR octet_length(NEW.payload->>'sourceKey') NOT BETWEEN 1 AND 1024 THEN
    RETURN NULL;
  END IF;
  -- Content-free metering of the inserted row's own tenant, whatever the
  -- writer's context: not restricted by private-session visibility, and an
  -- older writer's transaction need not carry the tenant settings.
  previous_subject := current_setting('opengeni.subject_id', true);
  previous_account := current_setting('opengeni.account_id', true);
  previous_workspace := current_setting('opengeni.workspace_id', true);
  PERFORM set_config('opengeni.subject_id', '', true);
  PERFORM set_config('opengeni.account_id', NEW.account_id::text, true);
  PERFORM set_config('opengeni.workspace_id', NEW.workspace_id::text, true);
  SELECT s.root_session_id INTO v_root FROM sessions s
    WHERE s.id = NEW.session_id AND s.workspace_id = NEW.workspace_id
      AND s.account_id = NEW.account_id;
  IF v_root IS NOT NULL THEN
    INSERT INTO opengeni_private.session_usage_limit_capabilities VALUES
      (pg_backend_pid(),pg_current_xact_id(),TG_TABLE_SCHEMA,NEW.account_id,NEW.workspace_id)
      ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS opened = ROW_COUNT;
    IF EXISTS (SELECT 1 FROM opengeni_private.session_usage_limit_roots r
      WHERE r.workspace_id = NEW.workspace_id AND r.root_session_id = v_root) THEN
      PERFORM session_usage_limit_apply_receipt(NEW.account_id, NEW.workspace_id, v_root,
        NEW.turn_id::text || ':' || (NEW.payload->>'sourceKey'), NEW.session_id, NEW.turn_id,
        session_usage_limit_event_amount(NEW.payload), NEW.payload->>'pricingSource',
        CASE WHEN jsonb_typeof(NEW.payload->'model') = 'string' THEN NEW.payload->>'model' END,
        'live');
    END IF;
    IF opened = 1 THEN
      DELETE FROM opengeni_private.session_usage_limit_capabilities
        WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
          AND data_schema=TG_TABLE_SCHEMA AND account_id=NEW.account_id
          AND workspace_id=NEW.workspace_id;
    END IF;
  END IF;
  PERFORM set_config('opengeni.subject_id', coalesce(previous_subject, ''), true);
  PERFORM set_config('opengeni.account_id', coalesce(previous_account, ''), true);
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace, ''), true);
  RETURN NULL;
END $$;

CREATE FUNCTION modal_inventory_read_capability_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.modal_inventory_read_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.data_schema = '{{schema}}'
      )
    $$;

CREATE FUNCTION modal_native_origin_member_read_active(p_account uuid, p_subject text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (SELECT 1 FROM opengeni_private.modal_native_origin_read_capabilities c
        WHERE c.data_schema={{schema_oid}}::oid AND c.backend_pid=pg_backend_pid()
          AND c.transaction_id=pg_current_xact_id_if_assigned()
          AND c.account_id=p_account AND c.initiating_human_subject_id=p_subject)
    $$;

CREATE FUNCTION model_fact_reconciliation_enqueue() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE ledger record;
BEGIN
  IF TG_TABLE_NAME = 'usage_events' THEN
    IF TG_OP = 'UPDATE' AND
      (OLD.session_id,OLD.turn_id,OLD.source_resource_type,OLD.source_resource_id,OLD.event_type)
      IS NOT DISTINCT FROM
      (NEW.session_id,NEW.turn_id,NEW.source_resource_type,NEW.source_resource_id,NEW.event_type) THEN
      RETURN NEW;
    END IF;
    ledger := NEW;
  ELSE
    IF NEW.turn_association <> 'current' OR NEW.turn_id IS NULL
      OR jsonb_typeof(NEW.payload->'sourceKey') <> 'string' THEN
      RETURN NEW;
    END IF;
    SELECT account_id,workspace_id,session_id,turn_id,source_resource_type,source_resource_id,occurred_at
      INTO ledger FROM usage_events
      WHERE workspace_id=NEW.workspace_id AND event_type='model.cost'
        AND source_resource_id=NEW.turn_id::text||':'||(NEW.payload->>'sourceKey')
        AND source_resource_type='model_response'
      LIMIT 1;
    IF NOT FOUND THEN RETURN NEW; END IF;
  END IF;
  IF ledger.session_id IS NULL OR ledger.turn_id IS NULL
    OR ledger.source_resource_type IS DISTINCT FROM 'model_response'
    OR left(ledger.source_resource_id,37) IS DISTINCT FROM ledger.turn_id::text||':' THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM model_call_facts WHERE workspace_id=ledger.workspace_id
    AND turn_id=ledger.turn_id AND source_key=substr(ledger.source_resource_id,38)) THEN
    RETURN NEW;
  END IF;
  INSERT INTO model_call_fact_reconciliation_candidates
    (account_id,workspace_id,session_id,turn_id,source_key,occurred_at)
    VALUES (ledger.account_id,ledger.workspace_id,ledger.session_id,ledger.turn_id,
      substr(ledger.source_resource_id,38),ledger.occurred_at)
    ON CONFLICT (workspace_id,turn_id,source_key) DO UPDATE SET batch_id=NULL
      WHERE model_call_fact_reconciliation_candidates.batch_id IS NOT NULL;
  RETURN NEW;
END $$;

CREATE FUNCTION move_vault_item(p_item uuid, p_target_vault uuid, p_mode text, p_new_name text, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  item_row vault_items;
  source_vault vaults;
  target_vault vaults;
  new_name text;
  item_count integer;
  copy_row vault_items;
  field_row record;
  new_field_id uuid;
  primary_name_key text;
  result jsonb;
  items_limit integer := opengeni_private.vault_limit('itemsPerVault', 2000);
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  IF p_mode NOT IN ('move', 'copy') OR p_mode IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'mode is "move" or "copy"');
  END IF;
  item_row := opengeni_private.vault_reachable_item(context, p_item);
  source_vault := opengeni_private.vault_reachable_row(context, item_row.vault_id);
  target_vault := opengeni_private.vault_reachable_row(context, p_target_vault);
  IF item_row.archived_at IS NOT NULL THEN
    PERFORM opengeni_private.vault_raise('vault_item_not_found', 'item is archived; restore it first',
      pg_catalog.jsonb_build_object('itemId', item_row.id, 'archived', true));
  END IF;
  IF p_mode = 'move' OR source_vault.source <> 'opengeni' THEN
    PERFORM opengeni_private.vault_assert_writable(context, source_vault);
  END IF;
  PERFORM opengeni_private.vault_assert_writable(context, target_vault);
  new_name := coalesce(p_new_name, item_row.name);
  PERFORM opengeni_private.vault_assert_name(new_name, 'Item');
  IF p_mode = 'move' AND target_vault.id = source_vault.id AND vault_name_key(new_name) = item_row.name_key THEN
    result := opengeni_private.vault_item_json(item_row, true);
    PERFORM opengeni_private.vault_capability_close();
    RETURN result;
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('vault-items:' || target_vault.id::text, 0));
  IF EXISTS (SELECT 1 FROM vault_items item WHERE item.vault_id = target_vault.id
    AND item.archived_at IS NULL AND item.name_key = vault_name_key(new_name)
    AND item.id <> item_row.id) THEN
    PERFORM opengeni_private.vault_raise('vault_item_name_conflict',
      'an item with this name already exists in the target vault',
      pg_catalog.jsonb_build_object('name', new_name, 'vaultId', target_vault.id));
  END IF;
  IF target_vault.id <> source_vault.id OR p_mode = 'copy' THEN
    SELECT pg_catalog.count(*) INTO item_count FROM vault_items item WHERE item.vault_id = target_vault.id;
    IF item_count >= items_limit THEN
      PERFORM opengeni_private.vault_raise('vault_limit_reached',
        'at most ' || items_limit || ' items per vault',
        pg_catalog.jsonb_build_object('limit', items_limit, 'vaultId', target_vault.id));
    END IF;
  END IF;

  IF p_mode = 'move' THEN
    DELETE FROM vault_item_name_aliases alias WHERE alias.item_id = item_row.id;
    DELETE FROM vault_passkey_leases WHERE item_id = item_row.id;
    UPDATE vault_items SET vault_id = target_vault.id, name = new_name,
      generation = generation + 1, updated_at = pg_catalog.now()
    WHERE id = item_row.id RETURNING * INTO item_row;
    PERFORM opengeni_private.vault_audit(item_row.account_id, (context ->> 'workspaceId')::uuid,
      context ->> 'subjectId', 'vault.item.moved', 'vault_item', item_row.id::text,
      pg_catalog.jsonb_build_object('itemId', item_row.id, 'itemName', item_row.name,
        'fromVaultId', source_vault.id, 'toVaultId', target_vault.id));
    result := opengeni_private.vault_item_json(item_row, true);
  ELSE
    SELECT field.name_key INTO primary_name_key FROM vault_item_fields field WHERE field.id = item_row.primary_field_id;
    INSERT INTO vault_items (account_id, vault_id, type, name, websites, expires_at, passkey_sign_count, created_by_subject_id,
      category)
    VALUES (target_vault.account_id, target_vault.id, item_row.type, new_name, item_row.websites,
      item_row.expires_at, item_row.passkey_sign_count, context ->> 'subjectId', item_row.category)
    RETURNING * INTO copy_row;
    FOR field_row IN
      SELECT field.*, version.value_encrypted
      FROM vault_item_fields field
      JOIN vault_field_versions version ON version.field_id = field.id AND version.version = field.current_version
      WHERE field.item_id = item_row.id
      ORDER BY field.position, field.name_key
    LOOP
      INSERT INTO vault_item_fields (account_id, item_id, name, kind, position, current_version, file_name, file_size)
      VALUES (copy_row.account_id, copy_row.id, field_row.name, field_row.kind, field_row.position, 1,
        field_row.file_name, field_row.file_size)
      RETURNING id INTO new_field_id;
      INSERT INTO vault_field_versions (field_id, version, account_id, value_encrypted, created_by_kind, created_by_subject_id)
      VALUES (new_field_id, 1, copy_row.account_id, field_row.value_encrypted,
        CASE context ->> 'kind' WHEN 'attempt' THEN 'agent' ELSE 'human' END, context ->> 'subjectId');
      IF field_row.name_key = primary_name_key THEN
        UPDATE vault_items SET primary_field_id = new_field_id WHERE id = copy_row.id;
      END IF;
    END LOOP;
    SELECT item.* INTO copy_row FROM vault_items item WHERE item.id = copy_row.id;
    PERFORM opengeni_private.vault_audit(copy_row.account_id, (context ->> 'workspaceId')::uuid,
      context ->> 'subjectId', 'vault.item.copied', 'vault_item', copy_row.id::text,
      pg_catalog.jsonb_build_object('itemId', copy_row.id, 'itemName', copy_row.name,
        'sourceItemId', item_row.id, 'fromVaultId', source_vault.id, 'toVaultId', target_vault.id));
    result := opengeni_private.vault_item_json(copy_row, true);
  END IF;
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION mutate_managed_sign_in_method(p_user text, p_session text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE revision_value bigint; identity_value uuid; binding_value uuid; provider_value text := p_request->>'provider';
  operation_value text := p_request->>'kind'; account_value text; stamp jsonb := p_request->'actorFence';
  previous_marker text := current_setting('opengeni.canonical_human_identity_lifecycle',true);
  replay_value jsonb; existing_intent jsonb; intent_expiry timestamptz;
BEGIN
  replay_value := replay_managed_sign_in_method(p_user,p_session,p_request);
  IF replay_value IS NOT NULL THEN RETURN replay_value; END IF;
  revision_value := managed_sign_in_method_authority(p_user, p_session, p_request);
  SELECT identity_id INTO identity_value FROM canonical_human_identity_subjects WHERE auth_user_id = p_user AND status = 'active';
  IF operation_value = 'connect' AND provider_value IN ('google','github') THEN
    IF EXISTS (SELECT 1 FROM auth_identities WHERE user_id = p_user AND provider_id = provider_value) THEN
      RAISE EXCEPTION 'SIGN_IN_METHOD_ALREADY_CONNECTED' USING ERRCODE = '23505';
    END IF;
    INSERT INTO auth_verifications(id, identifier, value, expires_at, created_at, updated_at)
      VALUES (p_request->>'operationId', 'managed-sign-in:' || (p_request->>'operationId'),
        (p_request || jsonb_build_object('authUserId',p_user,'authSessionId',p_session))::text,
        clock_timestamp() + interval '5 minutes', clock_timestamp(), clock_timestamp()) ON CONFLICT(id) DO NOTHING;
    SELECT value::jsonb,expires_at INTO existing_intent,intent_expiry FROM auth_verifications WHERE id=p_request->>'operationId' FOR UPDATE;
    IF existing_intent->>'authUserId' IS DISTINCT FROM p_user OR existing_intent->>'requestDigest' IS DISTINCT FROM p_request->>'requestDigest' THEN
      RAISE EXCEPTION 'SIGN_IN_METHOD_OPERATION_REUSED' USING ERRCODE='23505';
    END IF;
    IF intent_expiry<=clock_timestamp() THEN RAISE EXCEPTION 'SIGN_IN_METHOD_CONNECT_EXPIRED' USING ERRCODE='42501'; END IF;
    PERFORM set_config('opengeni.canonical_human_identity_lifecycle',coalesce(previous_marker,''),true);
    RETURN jsonb_build_object('intentId',p_request->>'operationId');
  ELSIF operation_value = 'disconnect' AND provider_value IN ('google','github') THEN
    SELECT b.id INTO binding_value FROM canonical_human_login_bindings b
      JOIN auth_identities a ON a.provider_id=b.provider_id AND a.account_id=b.provider_account_id AND a.user_id=p_user
      WHERE b.identity_id=identity_value AND b.status='active' AND b.provider_id=provider_value;
    IF binding_value IS NULL THEN RAISE EXCEPTION 'SIGN_IN_METHOD_NOT_CONNECTED' USING ERRCODE='P0002'; END IF;
    IF NOT EXISTS (SELECT 1 FROM canonical_human_login_bindings b JOIN auth_identities a
      ON a.provider_id=b.provider_id AND a.account_id=b.provider_account_id AND a.user_id=p_user
      WHERE b.identity_id=identity_value AND b.status='active' AND b.provider_id<>provider_value
      AND (p_request->'usableProviders') ? a.provider_id
      AND (a.provider_id IN ('google','github') OR (a.provider_id='credential' AND length(a.password)>0))) THEN
      RAISE EXCEPTION 'SIGN_IN_METHOD_LAST_USABLE_METHOD' USING ERRCODE='42501';
    END IF;
    PERFORM apply_canonical_human_identity_operation((p_request->>'operationId')::uuid,p_user,revision_value,'unlink',binding_value,NULL,NULL,'Disconnect personal sign-in method');
  ELSIF operation_value = 'password' THEN
    IF coalesce(length(p_request->>'passwordHash'),0) < 32 THEN RAISE EXCEPTION 'SIGN_IN_METHOD_INVALID_PASSWORD' USING ERRCODE='22023'; END IF;
    SELECT id INTO account_value FROM auth_identities WHERE user_id=p_user AND provider_id='credential' FOR UPDATE;
    IF account_value IS NOT NULL THEN
      -- The API proves the current password, and this comparison fences changes
      -- between that expensive proof and the transaction's credential update.
      IF (SELECT password FROM auth_identities WHERE id=account_value) IS DISTINCT FROM p_request->>'expectedPasswordHash' THEN
        RAISE EXCEPTION 'SIGN_IN_METHOD_PASSWORD_CHANGED' USING ERRCODE='40001';
      END IF;
      UPDATE auth_identities SET password=p_request->>'passwordHash', updated_at=clock_timestamp() WHERE id=account_value;
      UPDATE canonical_human_identities SET identity_revision=identity_revision+1, auth_revision=auth_revision+1, updated_at=clock_timestamp() WHERE id=identity_value;
      DELETE FROM auth_sessions WHERE identity_id=identity_value;
    ELSE
      IF p_request->>'expectedPasswordHash' IS NOT NULL THEN RAISE EXCEPTION 'SIGN_IN_METHOD_PASSWORD_CHANGED' USING ERRCODE='40001'; END IF;
      INSERT INTO auth_identities(id,user_id,provider_id,account_id,password,created_at,updated_at)
        VALUES (gen_random_uuid()::text,p_user,'credential',p_user,p_request->>'passwordHash',clock_timestamp(),clock_timestamp());
      PERFORM apply_canonical_human_identity_operation((p_request->>'operationId')::uuid,p_user,revision_value,'link',NULL,'credential',p_user,'Set personal sign-in password');
    END IF;
  ELSE RAISE EXCEPTION 'SIGN_IN_METHOD_INVALID_REQUEST' USING ERRCODE='22023';
  END IF;
  INSERT INTO managed_sign_in_method_operations(operation_id,auth_user_id,request_digest,kind,provider,notification_email)
    SELECT (p_request->>'operationId')::uuid,p_user,p_request->>'requestDigest',operation_value,
      CASE WHEN operation_value='password' THEN 'password' ELSE provider_value END,email FROM auth_users WHERE id=p_user AND email_verified;
  PERFORM set_config('opengeni.canonical_human_identity_lifecycle',coalesce(previous_marker,''),true);
  RETURN jsonb_build_object('reauthenticationRequired',true);
END $$;

CREATE FUNCTION mutate_scoped_rig(p_account_id uuid, p_workspace_id uuid, p_rig_id uuid, p_operation text, p_name text DEFAULT NULL::text, p_name_present boolean DEFAULT false, p_description text DEFAULT NULL::text, p_description_present boolean DEFAULT false, p_allow_organization boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  actor_membership_id uuid;
  rig_row rigs%ROWTYPE;
  active_sessions integer;
  result jsonb;
BEGIN
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'write')
  ON CONFLICT DO NOTHING;
  actor_membership_id := scoped_compute_actor_membership(p_account_id, p_workspace_id);
  SELECT rig.* INTO STRICT rig_row FROM rigs rig
  WHERE rig.id = p_rig_id AND rig.account_id = p_account_id AND rig.status = 'active'
    AND ((rig.authority_scope = 'organization' AND p_allow_organization)
      OR (rig.authority_scope = 'workspace' AND rig.workspace_id = p_workspace_id)
      OR (rig.authority_scope = 'user'
        AND rig.owner_organization_membership_id = actor_membership_id))
  FOR UPDATE;
  IF p_operation = 'update' THEN
    UPDATE rigs SET name = CASE WHEN p_name_present THEN p_name ELSE name END,
      description = CASE WHEN p_description_present THEN p_description ELSE description END,
      updated_at = clock_timestamp() WHERE id = p_rig_id;
  ELSIF p_operation = 'revoke' THEN
    SELECT count(*)::integer INTO active_sessions FROM sessions session_value
    WHERE session_value.account_id = p_account_id AND session_value.rig_id = p_rig_id
      AND session_value.status IN ('queued','running','requires_action','recovering','waiting_capacity');
    IF active_sessions > 0 THEN
      RAISE EXCEPTION 'rig remains attached to % active sessions', active_sessions
        USING ERRCODE = '23503';
    END IF;
    UPDATE rigs SET status = 'revoked', revoked_at = clock_timestamp(),
      generation = generation + 1, updated_at = clock_timestamp() WHERE id = p_rig_id;
    IF rig_row.authority_scope = 'user' THEN
      UPDATE organization_user_resource_authorities SET status = 'revoked',
        revoked_at = clock_timestamp(), generation = generation + 1,
        updated_at = clock_timestamp()
      WHERE id = rig_row.authority_id AND account_id = p_account_id AND status = 'active';
      UPDATE organization_user_resource_grants SET status = 'revoked',
        revoked_at = clock_timestamp(), generation = generation + 1,
        updated_at = clock_timestamp()
      WHERE authority_id = rig_row.authority_id AND account_id = p_account_id
        AND status = 'active';
    END IF;
  ELSE RAISE EXCEPTION 'invalid rig mutation' USING ERRCODE = '22023'; END IF;
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'write';
  IF p_operation = 'revoke' THEN RETURN NULL; END IF;
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
  ON CONFLICT DO NOTHING;
  result := scoped_rig_json(p_rig_id);
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'read';
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION mutate_scoped_variable_set(p_account_id uuid, p_workspace_id uuid, p_variable_set_id uuid, p_operation text, p_name text DEFAULT NULL::text, p_name_present boolean DEFAULT false, p_description text DEFAULT NULL::text, p_description_present boolean DEFAULT false, p_variable_name text DEFAULT NULL::text, p_value_encrypted text DEFAULT NULL::text, p_allow_organization boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      actor_membership_id uuid;
      variable_set_row workspace_variable_sets%ROWTYPE;
      deleted_variable boolean := false;
      attached_sessions integer;
      attached_tasks integer;
      mutation_result jsonb;
    BEGIN
      INSERT INTO opengeni_private.variable_set_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'write')
      ON CONFLICT DO NOTHING;
      actor_membership_id := scoped_variable_set_actor_membership(
        p_account_id, p_workspace_id
      );
      IF p_operation NOT IN ('update', 'set_variable', 'delete_variable', 'revoke') THEN
        RAISE EXCEPTION 'invalid variable-set mutation' USING ERRCODE = '22023';
      END IF;

      SELECT variable_set.* INTO STRICT variable_set_row
      FROM workspace_variable_sets variable_set
      WHERE variable_set.id = p_variable_set_id
        AND variable_set.account_id = p_account_id
        AND variable_set.status = 'active'
        AND (
          (
            variable_set.authority_scope = 'organization'
            AND p_allow_organization
          )
          OR (
            variable_set.authority_scope = 'workspace'
            AND variable_set.workspace_id = p_workspace_id
          )
          OR (
            variable_set.authority_scope = 'user'
            AND variable_set.owner_organization_membership_id = actor_membership_id
          )
        )
      FOR UPDATE;

      IF variable_set_row.authority_scope = 'organization' AND NOT p_allow_organization THEN
        RAISE EXCEPTION 'organization variable-set mutation requires account authority'
          USING ERRCODE = '42501';
      END IF;

      IF p_operation = 'update' THEN
        IF p_name_present AND (nullif(btrim(p_name), '') IS NULL OR length(p_name) > 120) THEN
          RAISE EXCEPTION 'invalid variable-set name' USING ERRCODE = '22023';
        END IF;
        IF p_description_present AND p_description IS NOT NULL
          AND length(p_description) > 2000
        THEN
          RAISE EXCEPTION 'invalid variable-set description' USING ERRCODE = '22023';
        END IF;
        UPDATE workspace_variable_sets
        SET name = CASE WHEN p_name_present THEN p_name ELSE name END,
            description = CASE
              WHEN p_description_present THEN p_description ELSE description
            END,
            updated_at = clock_timestamp()
        WHERE id = variable_set_row.id;
      ELSIF p_operation = 'set_variable' THEN
        IF p_variable_name IS NULL OR p_value_encrypted IS NULL THEN
          RAISE EXCEPTION 'variable name and encrypted value are required'
            USING ERRCODE = '22023';
        END IF;
        INSERT INTO workspace_variable_set_variables (
          account_id, workspace_id, variable_set_id, name, value_encrypted
        ) VALUES (
          p_account_id, variable_set_row.workspace_id, variable_set_row.id,
          p_variable_name, p_value_encrypted
        )
        ON CONFLICT (workspace_id, variable_set_id, name)
        DO UPDATE SET value_encrypted = excluded.value_encrypted,
          version = workspace_variable_set_variables.version + 1,
          updated_at = clock_timestamp();
        UPDATE workspace_variable_sets
        SET generation = generation + 1, updated_at = clock_timestamp()
        WHERE id = variable_set_row.id;
        IF variable_set_row.authority_scope = 'user' THEN
          UPDATE organization_user_resource_authorities
          SET generation = generation + 1, updated_at = clock_timestamp()
          WHERE id = variable_set_row.authority_id
            AND account_id = p_account_id
            AND status = 'active';
        END IF;
      ELSIF p_operation = 'delete_variable' THEN
        DELETE FROM workspace_variable_set_variables
        WHERE account_id = p_account_id
          AND variable_set_id = variable_set_row.id
          AND name = p_variable_name;
        GET DIAGNOSTICS attached_sessions = ROW_COUNT;
        deleted_variable := attached_sessions = 1;
        IF deleted_variable THEN
          UPDATE workspace_variable_sets
          SET generation = generation + 1, updated_at = clock_timestamp()
          WHERE id = variable_set_row.id;
          IF variable_set_row.authority_scope = 'user' THEN
            UPDATE organization_user_resource_authorities
            SET generation = generation + 1, updated_at = clock_timestamp()
            WHERE id = variable_set_row.authority_id
              AND account_id = p_account_id
              AND status = 'active';
          END IF;
        END IF;
      ELSE
        SELECT count(*)::integer INTO attached_tasks
        FROM scheduled_tasks task
        WHERE task.account_id = p_account_id
          AND task.variable_set_id = variable_set_row.id;
        SELECT count(*)::integer INTO attached_sessions
        FROM sessions session_value
        WHERE session_value.account_id = p_account_id
          AND session_value.variable_set_id = variable_set_row.id
          AND session_value.status IN (
            'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
          );
        IF attached_tasks > 0 OR attached_sessions > 0 THEN
          RAISE EXCEPTION 'variable set remains attached to % scheduled tasks and % sessions',
            attached_tasks, attached_sessions USING ERRCODE = '23503';
        END IF;
        IF variable_set_row.authority_scope = 'user' THEN
          UPDATE organization_user_resource_authorities
          SET status = 'revoked', revoked_at = clock_timestamp(),
              generation = generation + 1, updated_at = clock_timestamp()
          WHERE id = variable_set_row.authority_id
            AND account_id = p_account_id
            AND status = 'active';
          UPDATE organization_user_resource_grants
          SET status = 'revoked', revoked_at = clock_timestamp(),
              generation = generation + 1, updated_at = clock_timestamp()
          WHERE account_id = p_account_id
            AND authority_id = variable_set_row.authority_id
            AND status = 'active';
        END IF;
        DELETE FROM workspace_variable_sets
        WHERE id = variable_set_row.id;
      END IF;

      variable_set_row.id := p_variable_set_id;
      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'write';
      INSERT INTO opengeni_private.variable_set_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
      ON CONFLICT DO NOTHING;
      mutation_result := pg_catalog.jsonb_build_object(
        'variableSet', scoped_variable_set_json(variable_set_row.id),
        'deletedVariable', deleted_variable
      );
      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'read';
      RETURN mutation_result;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind IN ('write', 'read');
      RAISE;
    END
    $$;

CREATE FUNCTION mutate_self_personal_github_repository_selection(p_account_id uuid, p_origin_workspace_id uuid, p_owner_subject_id text, p_connection_id uuid, p_expected_connection_authority_generation bigint, p_expected_selection_generation bigint, p_idempotency_key text, p_repositories jsonb, p_verify_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $_$
    DECLARE
      connection_row connections%ROWTYPE;
      head_row personal_github_repository_selection_heads%ROWTYPE;
      receipt_row personal_github_repository_selection_operations%ROWTYPE;
      item jsonb;
      request_digest bytea;
      current_generation bigint;
      next_generation bigint;
      authority_changed boolean;
    BEGIN
      IF p_account_id IS DISTINCT FROM
          nullif(current_setting('opengeni.account_id', true), '')::uuid
        OR p_origin_workspace_id IS DISTINCT FROM
          nullif(current_setting('opengeni.workspace_id', true), '')::uuid
        OR p_owner_subject_id IS DISTINCT FROM
          nullif(current_setting('opengeni.subject_id', true), '')
      THEN RAISE EXCEPTION 'personal GitHub repository selection is unavailable'
        USING ERRCODE = '42501';
      END IF;
      IF p_expected_connection_authority_generation <= 0
        OR p_expected_selection_generation < 0
        OR octet_length(p_idempotency_key) NOT BETWEEN 1 AND 200
        OR jsonb_typeof(p_repositories) <> 'array'
        OR jsonb_array_length(p_repositories) > 100
      THEN RAISE EXCEPTION 'invalid personal GitHub repository selection'
        USING ERRCODE = '22023';
      END IF;
      IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_repositories) selected(value)
        WHERE jsonb_typeof(value) <> 'object'
          OR value - ARRAY[
            'repositoryId','fullName','canonicalUrl','defaultBranch','visibility',
            'private','archived','disabled','permissions','selectedAccess','lastVerifiedAt'
          ]::text[] <> '{}'::jsonb
          OR NOT (value ?& ARRAY[
            'repositoryId','fullName','canonicalUrl','defaultBranch','visibility',
            'private','archived','disabled','permissions','selectedAccess','lastVerifiedAt'
          ])
          OR value ->> 'repositoryId' !~ '^[0-9]+$'
          OR (value ->> 'repositoryId')::numeric <= 0
          OR value ->> 'fullName'
            !~ '^[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]{1,100}$'
          OR value ->> 'canonicalUrl' IS DISTINCT FROM
            'https://github.com/' || (value ->> 'fullName')
          OR octet_length(value ->> 'defaultBranch') NOT BETWEEN 1 AND 255
          OR value ->> 'visibility' NOT IN ('public','private','internal')
          OR jsonb_typeof(value -> 'private') <> 'boolean'
          OR jsonb_typeof(value -> 'archived') <> 'boolean'
          OR jsonb_typeof(value -> 'disabled') <> 'boolean'
          OR value -> 'private' IS DISTINCT FROM
            to_jsonb((value ->> 'visibility') = 'private')
          OR value ->> 'selectedAccess' NOT IN ('read','write')
          OR jsonb_typeof(value -> 'permissions') <> 'object'
          OR NOT (value -> 'permissions' ?& ARRAY['pull','push','admin','maintain','triage'])
          OR EXISTS (
            SELECT 1 FROM jsonb_each(value -> 'permissions') permission(key, permission_value)
            WHERE key NOT IN ('pull','push','admin','maintain','triage')
              OR jsonb_typeof(permission_value) <> 'boolean'
          )
          OR NOT (
            value -> 'permissions' -> 'pull' = 'true'::jsonb
            OR value -> 'permissions' -> 'push' = 'true'::jsonb
            OR value -> 'permissions' -> 'admin' = 'true'::jsonb
            OR value -> 'permissions' -> 'maintain' = 'true'::jsonb
            OR value -> 'permissions' -> 'triage' = 'true'::jsonb
          )
          OR (
            value ->> 'selectedAccess' = 'write'
            AND (
              value -> 'archived' = 'true'::jsonb
              OR value -> 'disabled' = 'true'::jsonb
              OR NOT (
                value -> 'permissions' -> 'push' = 'true'::jsonb
                OR value -> 'permissions' -> 'admin' = 'true'::jsonb
                OR value -> 'permissions' -> 'maintain' = 'true'::jsonb
              )
            )
          )
          OR (value ->> 'lastVerifiedAt')::timestamptz IS NULL
      ) OR (
        SELECT count(*) FROM jsonb_array_elements(p_repositories)
      ) <> (
        SELECT count(DISTINCT value ->> 'repositoryId')
        FROM jsonb_array_elements(p_repositories) selected(value)
      ) OR (
        SELECT count(*) FROM jsonb_array_elements(p_repositories)
      ) <> (
        SELECT count(DISTINCT lower(value ->> 'fullName'))
        FROM jsonb_array_elements(p_repositories) selected(value)
      )
      THEN RAISE EXCEPTION 'invalid personal GitHub repository selection'
        USING ERRCODE = '22023';
      END IF;

      PERFORM pg_advisory_xact_lock(hashtextextended(
        'personal-github-repositories:' || p_connection_id::text, 0
      ));
      SELECT connection_value.* INTO connection_row
      FROM connections connection_value
      WHERE connection_value.id = p_connection_id
        AND connection_value.account_id = p_account_id
        AND connection_value.origin_workspace_id = p_origin_workspace_id
        AND connection_value.workspace_id = p_origin_workspace_id
        AND connection_value.subject_id = p_owner_subject_id
        AND connection_value.status = 'active'
        AND connection_value.authority_scope = 'user'
        AND connection_value.provider_domain = 'github.com'
        AND connection_value.kind = 'oauth2'
        AND connection_value.granted_scopes = '["repo"]'::jsonb
        AND connection_value.authority_generation = p_expected_connection_authority_generation
        AND connection_value.metadata ->> 'credentialRole' = 'opengeni_github_personal'
        AND connection_value.metadata ->> 'providerFamily' = 'github'
        AND connection_value.metadata ->> 'providerPrincipalId' ~ '^[1-9][0-9]*$'
        AND connection_value.metadata ->> 'credentialBindingId'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      FOR SHARE;
      IF NOT FOUND THEN RAISE EXCEPTION 'personal GitHub repository selection is unavailable'
        USING ERRCODE = '42501'; END IF;

      SELECT head.* INTO head_row
      FROM personal_github_repository_selection_heads head
      WHERE head.connection_id = p_connection_id
      FOR UPDATE;
      current_generation := CASE WHEN FOUND THEN head_row.generation ELSE 0 END;
      request_digest := digest(convert_to(jsonb_build_object(
        'expectedConnectionAuthorityGeneration', p_expected_connection_authority_generation,
        'expectedSelectionGeneration', p_expected_selection_generation,
        'verifyOnly', p_verify_only,
        'repositories', coalesce((
          SELECT jsonb_agg(
            jsonb_build_array(
              value ->> 'repositoryId',
              lower(value ->> 'fullName'),
              value ->> 'selectedAccess'
            ) ORDER BY (value ->> 'repositoryId')::numeric
          )
          FROM jsonb_array_elements(p_repositories) incoming(value)
        ), '[]'::jsonb)
      )::text, 'UTF8'), 'sha256');
      IF FOUND THEN
        SELECT operation.* INTO receipt_row
        FROM personal_github_repository_selection_operations operation
        WHERE operation.connection_id = p_connection_id
          AND operation.idempotency_key = p_idempotency_key;
        IF FOUND THEN
          IF receipt_row.request_digest IS DISTINCT FROM request_digest THEN
            RAISE EXCEPTION 'personal GitHub repository idempotency key was reused'
              USING ERRCODE = '23505';
          END IF;
          IF current_generation IS DISTINCT FROM receipt_row.resulting_generation THEN
            RAISE EXCEPTION 'personal GitHub repository selection changed'
              USING ERRCODE = '40001';
          END IF;
          RETURN get_self_personal_github_repository_selection(
            p_account_id, p_origin_workspace_id, p_owner_subject_id, p_connection_id
          );
        END IF;
      END IF;
      IF current_generation IS DISTINCT FROM p_expected_selection_generation THEN
        RAISE EXCEPTION 'personal GitHub repository selection changed'
          USING ERRCODE = '40001';
      END IF;
      IF p_verify_only AND current_generation = 0
        AND jsonb_array_length(p_repositories) = 0
      THEN
        RETURN get_self_personal_github_repository_selection(
          p_account_id, p_origin_workspace_id, p_owner_subject_id, p_connection_id
        );
      END IF;
      IF p_verify_only AND (
        (SELECT count(*) FROM personal_github_repository_selections selected
          WHERE selected.connection_id = p_connection_id)
          <> jsonb_array_length(p_repositories)
        OR EXISTS (
          SELECT 1 FROM personal_github_repository_selections selected
          WHERE selected.connection_id = p_connection_id
            AND NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(p_repositories) incoming(value)
              WHERE incoming.value ->> 'repositoryId' = selected.repository_id::text
                AND incoming.value ->> 'selectedAccess' = selected.selected_access
            )
        )
      ) THEN RAISE EXCEPTION 'personal GitHub verify set changed'
        USING ERRCODE = '40001'; END IF;

      SELECT current_generation = 0 OR EXISTS (
        (SELECT selected.repository_id::text, selected.canonical_https_uri,
                selected.selected_access
         FROM personal_github_repository_selections selected
         WHERE selected.connection_id = p_connection_id
         EXCEPT
         SELECT value ->> 'repositoryId', value ->> 'canonicalUrl', value ->> 'selectedAccess'
         FROM jsonb_array_elements(p_repositories) incoming(value))
        UNION ALL
        (SELECT value ->> 'repositoryId', value ->> 'canonicalUrl', value ->> 'selectedAccess'
         FROM jsonb_array_elements(p_repositories) incoming(value)
         EXCEPT
         SELECT selected.repository_id::text, selected.canonical_https_uri,
                selected.selected_access
         FROM personal_github_repository_selections selected
         WHERE selected.connection_id = p_connection_id)
      ) INTO authority_changed;
      next_generation := CASE
        WHEN authority_changed THEN current_generation + 1 ELSE current_generation END;

      INSERT INTO personal_github_repository_selection_heads (
        connection_id, account_id, origin_workspace_id, owner_subject_id,
        provider_principal_id, credential_binding_id,
        connection_authority_generation, generation, updated_by_subject_id
      ) VALUES (
        p_connection_id, p_account_id, p_origin_workspace_id, p_owner_subject_id,
        connection_row.metadata ->> 'providerPrincipalId',
        (connection_row.metadata ->> 'credentialBindingId')::uuid,
        connection_row.authority_generation, next_generation, p_owner_subject_id
      ) ON CONFLICT (connection_id) DO UPDATE SET
        provider_principal_id = EXCLUDED.provider_principal_id,
        credential_binding_id = EXCLUDED.credential_binding_id,
        connection_authority_generation = EXCLUDED.connection_authority_generation,
        generation = EXCLUDED.generation,
        updated_by_subject_id = EXCLUDED.updated_by_subject_id,
        updated_at = clock_timestamp();

      FOR item IN SELECT value FROM jsonb_array_elements(p_repositories) incoming(value)
      LOOP
        INSERT INTO personal_github_repository_selections (
          connection_id, repository_id, account_id, origin_workspace_id,
          owner_subject_id, canonical_full_name, canonical_https_uri,
          default_branch, visibility, private, archived, disabled, permissions,
          selected_access, selection_generation, selected_by_subject_id,
          selected_at, verified_at, updated_at
        ) VALUES (
          p_connection_id, (item ->> 'repositoryId')::bigint, p_account_id,
          p_origin_workspace_id, p_owner_subject_id, item ->> 'fullName',
          item ->> 'canonicalUrl', item ->> 'defaultBranch', item ->> 'visibility',
          (item ->> 'private')::boolean, (item ->> 'archived')::boolean,
          (item ->> 'disabled')::boolean, item -> 'permissions',
          item ->> 'selectedAccess', next_generation, p_owner_subject_id,
          clock_timestamp(), (item ->> 'lastVerifiedAt')::timestamptz, clock_timestamp()
        ) ON CONFLICT (connection_id, repository_id) DO UPDATE SET
          canonical_full_name = EXCLUDED.canonical_full_name,
          canonical_https_uri = EXCLUDED.canonical_https_uri,
          default_branch = EXCLUDED.default_branch,
          visibility = EXCLUDED.visibility,
          private = EXCLUDED.private,
          archived = EXCLUDED.archived,
          disabled = EXCLUDED.disabled,
          permissions = EXCLUDED.permissions,
          selected_access = EXCLUDED.selected_access,
          selection_generation = CASE
            WHEN personal_github_repository_selections.canonical_https_uri
                  IS DISTINCT FROM EXCLUDED.canonical_https_uri
              OR personal_github_repository_selections.selected_access
                  IS DISTINCT FROM EXCLUDED.selected_access
            THEN next_generation
            ELSE personal_github_repository_selections.selection_generation
          END,
          selected_at = CASE
            WHEN personal_github_repository_selections.canonical_https_uri
                  IS DISTINCT FROM EXCLUDED.canonical_https_uri
              OR personal_github_repository_selections.selected_access
                  IS DISTINCT FROM EXCLUDED.selected_access
            THEN EXCLUDED.selected_at
            ELSE personal_github_repository_selections.selected_at
          END,
          verified_at = EXCLUDED.verified_at,
          updated_at = clock_timestamp();
      END LOOP;
      IF NOT p_verify_only THEN
        DELETE FROM personal_github_repository_selections selected
        WHERE selected.connection_id = p_connection_id
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p_repositories) incoming(value)
            WHERE incoming.value ->> 'repositoryId' = selected.repository_id::text
          );
      END IF;
      INSERT INTO personal_github_repository_selection_operations (
        connection_id, idempotency_key, account_id, origin_workspace_id,
        owner_subject_id, request_digest, resulting_generation
      ) VALUES (
        p_connection_id, p_idempotency_key, p_account_id, p_origin_workspace_id,
        p_owner_subject_id, request_digest, next_generation
      );
      RETURN get_self_personal_github_repository_selection(
        p_account_id, p_origin_workspace_id, p_owner_subject_id, p_connection_id
      );
    END
    $_$;

CREATE FUNCTION normalize_legacy_session_event_sequence_from_cursor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  fenced_access_capability_id uuid;
  current_sequence integer;
  raw_range jsonb;
BEGIN
  raw_range := nullif(
    pg_catalog.current_setting('opengeni.session_event_raw_cursor_range_v1', true),
    ''
  )::jsonb;
  IF NEW.type IN (
      'agent.message.delta',
      'agent.reasoning.delta',
      'sandbox.command.output.delta',
      'terminal.pty.output.delta'
    )
    AND raw_range ->> 'accountId' = NEW.account_id::text
    AND raw_range ->> 'workspaceId' = NEW.workspace_id::text
    AND raw_range ->> 'sessionId' = NEW.session_id::text
    AND NEW.sequence BETWEEN
      (raw_range ->> 'firstSequence')::integer
      AND (raw_range ->> 'lastSequence')::integer
  THEN
    RETURN NEW;
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.session_variable_set_attachments_v1',
    '1',
    true
  );
  fenced_access_capability_id :=
    opengeni_private.open_session_tenancy_fenced_access(
      session_tenancy_fence_target_schema()
    );
  SELECT cursor.last_sequence
  INTO current_sequence
  FROM session_event_cursors cursor
  WHERE cursor.account_id = NEW.account_id
    AND cursor.workspace_id = NEW.workspace_id
    AND cursor.session_id = NEW.session_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'session event cursor is missing for a legacy event writer';
  END IF;

  -- New cursor writers submit the complete contiguous range and are validated
  -- by the AFTER STATEMENT trigger. A legacy writer can submit the stale
  -- sessions.last_sequence + 1 after raw traffic; rebase only that already-
  -- consumed value. Multi-row gaps still fail closed in the statement trigger.
  IF NEW.sequence <= current_sequence THEN
    NEW.sequence := current_sequence + 1;
  END IF;
  PERFORM opengeni_private.close_session_tenancy_fenced_access(
    fenced_access_capability_id
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  IF fenced_access_capability_id IS NOT NULL THEN
    PERFORM opengeni_private.close_session_tenancy_fenced_access(
      fenced_access_capability_id
    );
  END IF;
  RAISE;
END
$$;

CREATE FUNCTION normalize_session_variable_set_selection() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  selected_count integer;
  distinct_count integer;
  last_id uuid;
BEGIN
  IF TG_OP = 'INSERT'
    AND NEW.variable_set_ids = '[]'::jsonb
    AND NEW.variable_set_id IS NOT NULL
  THEN
    NEW.variable_set_ids := jsonb_build_array(NEW.variable_set_id::text);
  ELSIF TG_OP = 'UPDATE'
    AND NEW.variable_set_ids IS NOT DISTINCT FROM OLD.variable_set_ids
    AND NEW.variable_set_id IS DISTINCT FROM OLD.variable_set_id
  THEN
    NEW.variable_set_ids := CASE
      WHEN NEW.variable_set_id IS NULL THEN '[]'::jsonb
      ELSE jsonb_build_array(NEW.variable_set_id::text)
    END;
  END IF;

  IF jsonb_typeof(NEW.variable_set_ids) <> 'array' THEN
    RAISE EXCEPTION 'variable_set_ids must be a JSON array' USING ERRCODE = '23514';
  END IF;
  selected_count := jsonb_array_length(NEW.variable_set_ids);
  IF selected_count > 25 THEN
    RAISE EXCEPTION 'variable_set_ids exceeds 25 entries' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(NEW.variable_set_ids) item(value)
    WHERE jsonb_typeof(item.value) <> 'string'
      OR (item.value #>> '{}') !~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) THEN
    RAISE EXCEPTION 'variable_set_ids must contain UUID strings' USING ERRCODE = '23514';
  END IF;
  SELECT count(DISTINCT value) INTO distinct_count
  FROM jsonb_array_elements_text(NEW.variable_set_ids) selected(value);
  IF distinct_count <> selected_count THEN
    RAISE EXCEPTION 'variable_set_ids must not contain duplicates' USING ERRCODE = '23514';
  END IF;
  SELECT value::uuid INTO last_id
  FROM jsonb_array_elements_text(NEW.variable_set_ids) WITH ORDINALITY selected(value, position)
  ORDER BY position DESC
  LIMIT 1;
  IF NEW.variable_set_id IS DISTINCT FROM last_id THEN
    RAISE EXCEPTION 'variable_set_id must match the last variable_set_ids entry'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$_$;

CREATE FUNCTION notify_session_list_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  workspace uuid;
  session uuid;
  subject text;
  all_scopes boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'sessions' THEN
    IF TG_OP = 'DELETE' THEN
      workspace := OLD.workspace_id;
      all_scopes := true;
    ELSE
      workspace := NEW.workspace_id;
      session := NEW.id;
      IF TG_OP = 'UPDATE' THEN
        -- The former audience cannot resolve a revoked row. A workspace-only
        -- reconciliation hint removes it without disclosing the private ID.
        all_scopes := ROW(OLD.visibility, OLD.owner_subject_id, OLD.channel_id,
          OLD.parent_session_id, OLD.root_session_id, OLD.site_access_root_id,
          OLD.scope_subject_id, OLD.created_by_kind, OLD.created_by_subject_id, OLD.site_id)
          IS DISTINCT FROM ROW(NEW.visibility, NEW.owner_subject_id, NEW.channel_id,
          NEW.parent_session_id, NEW.root_session_id, NEW.site_access_root_id,
          NEW.scope_subject_id, NEW.created_by_kind, NEW.created_by_subject_id, NEW.site_id);
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'session_pins' THEN
    IF TG_OP = 'DELETE' THEN
      workspace := OLD.workspace_id; subject := OLD.subject_id; session := OLD.session_id;
    ELSE
      workspace := NEW.workspace_id; subject := NEW.subject_id; session := NEW.session_id;
    END IF;
  ELSIF TG_TABLE_NAME IN ('session_background_commands', 'sandbox_retained_processes', 'session_turns') THEN
    IF TG_OP = 'DELETE' THEN
      workspace := OLD.workspace_id; session := OLD.session_id;
    ELSE
      workspace := NEW.workspace_id; session := NEW.session_id;
    END IF;
  ELSE
    IF TG_OP = 'DELETE' THEN workspace := OLD.workspace_id;
    ELSE workspace := NEW.workspace_id;
    END IF;
    all_scopes := true;
  END IF;
  IF workspace IS NOT NULL THEN
    PERFORM pg_notify('opengeni_session_lists', json_build_object(
      'schema', TG_TABLE_SCHEMA, 'workspaceId', workspace,
      'sessionId', CASE WHEN all_scopes THEN NULL ELSE session END,
      'subjectId', subject, 'all', all_scopes OR session IS NULL)::text);
  END IF;
  RETURN NULL;
END
$$;

CREATE FUNCTION open_organization_shared_workspace_administration_capability(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  capability_id_value uuid := pg_catalog.gen_random_uuid();
BEGIN
  PERFORM opengeni_private.assert_organization_shared_workspace_administrator(
    p_account_id, p_workspace_id, p_actor_subject_id
  );
  INSERT INTO organization_shared_workspace_administration_capabilities (
    backend_pid, transaction_id, capability_id,
    account_id, workspace_id, actor_subject_id
  ) VALUES (
    pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), capability_id_value,
    p_account_id, p_workspace_id, p_actor_subject_id
  );
  PERFORM pg_catalog.set_config(
    'opengeni.organization_shared_workspace_administration_capability',
    capability_id_value::text,
    true
  );
  RETURN capability_id_value;
END
$$;

CREATE FUNCTION open_private_child_session_create_capability(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_parent_session_id uuid, p_actor_turn_id uuid, p_actor_attempt_id uuid, p_actor_execution_generation integer) RETURNS TABLE(capability_id uuid, owner_membership_id uuid, owner_subject_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  new_capability_id uuid := gen_random_uuid();
  parent_row sessions%ROWTYPE;
  owner_membership organization_memberships%ROWTYPE;
  owner_workspace_access_id uuid;
  actor_human_subject_id text;
  actor_interrupted boolean;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_parent_session_id IS NULL OR p_actor_turn_id IS NULL
    OR p_actor_attempt_id IS NULL OR p_actor_execution_generation IS NULL
    OR p_actor_execution_generation < 1
    OR p_session_id = p_parent_session_id
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NOT session_tenancy_product_activated(p_account_id, 1)
  THEN
    RAISE EXCEPTION 'private child session create authority required'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspace_inference_controls control
  WHERE control.account_id = p_account_id AND control.workspace_id = p_workspace_id
  FOR SHARE;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR KEY SHARE;

  SELECT parent.* INTO parent_row
  FROM sessions parent
  WHERE parent.account_id = p_account_id
    AND parent.workspace_id = p_workspace_id
    AND parent.id = p_parent_session_id
  FOR NO KEY UPDATE;
  IF NOT FOUND
    OR parent_row.visibility <> 'user_private'
    OR parent_row.owner_organization_membership_id IS NULL
    OR parent_row.owner_subject_id IS NULL
    OR parent_row.active_turn_id IS DISTINCT FROM p_actor_turn_id
  THEN
    RAISE EXCEPTION 'private child session create authority required'
      USING ERRCODE = '42501';
  END IF;

  SELECT membership.* INTO owner_membership
  FROM organization_memberships membership
  WHERE membership.id = parent_row.owner_organization_membership_id
    AND membership.account_id = p_account_id
    AND membership.subject_id = parent_row.owner_subject_id
    AND membership.status = 'active'
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'private child session owner authority is no longer active'
      USING ERRCODE = '42501';
  END IF;
  IF NOT (
    owner_membership.subject_id LIKE 'user:%'
    AND owner_membership.personal_workspace_id = p_workspace_id
  ) THEN
    -- Match the top-level private-create lock prefix: in an ordinary shared
    -- workspace the exact access row is authority, so hold it through INSERT.
    SELECT access.id INTO owner_workspace_access_id
    FROM workspace_memberships access
    WHERE access.account_id = p_account_id
      AND access.workspace_id = p_workspace_id
      AND access.subject_id = owner_membership.subject_id
    FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'private child session owner authority is no longer active'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT
    coalesce(
      turn_row.initiating_human_subject_id,
      CASE WHEN turn_row.initiator_kind = 'subject'
        THEN turn_row.initiator_subject_id ELSE NULL END
    ),
    EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = p_workspace_id
        AND interruption.attempt_id = p_actor_attempt_id
        AND interruption.state IN ('pending', 'delivered', 'acknowledged')
    )
  INTO actor_human_subject_id, actor_interrupted
  FROM session_turns turn_row
  JOIN session_turn_attempts attempt
    ON attempt.workspace_id = turn_row.workspace_id
    AND attempt.session_id = turn_row.session_id
    AND attempt.turn_id = turn_row.id
  WHERE turn_row.account_id = p_account_id
    AND turn_row.workspace_id = p_workspace_id
    AND turn_row.session_id = p_parent_session_id
    AND turn_row.id = p_actor_turn_id
    AND turn_row.active_attempt_id = p_actor_attempt_id
    AND turn_row.execution_generation = p_actor_execution_generation
    AND turn_row.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
    AND attempt.id = p_actor_attempt_id
    AND attempt.execution_generation = p_actor_execution_generation
    AND attempt.state IN ('claimed', 'running')
  FOR UPDATE OF turn_row, attempt;
  IF NOT FOUND OR actor_interrupted
    OR actor_human_subject_id IS DISTINCT FROM parent_row.owner_subject_id
  THEN
    RAISE EXCEPTION 'private child session create attempt is stale or unauthorized'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.private_session_create_lifecycle', 'private_session_create', true
  );
  INSERT INTO private_session_create_capabilities (
    backend_pid, transaction_id, capability_id, account_id, workspace_id,
    session_id, actor_subject_id, owner_membership_id, parent_session_id,
    actor_turn_id, actor_attempt_id, actor_execution_generation
  ) VALUES (
    pg_backend_pid(), pg_current_xact_id(), new_capability_id, p_account_id,
    p_workspace_id, p_session_id, parent_row.owner_subject_id,
    parent_row.owner_organization_membership_id, p_parent_session_id,
    p_actor_turn_id, p_actor_attempt_id, p_actor_execution_generation
  );
  INSERT INTO session_visibility_write_capabilities (
    backend_pid, transaction_id, capability_id
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), new_capability_id);
  PERFORM pg_catalog.set_config(
    'opengeni.private_child_session_create_capability', new_capability_id::text, true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_visibility_write_capability', new_capability_id::text, true
  );
  capability_id := new_capability_id;
  owner_membership_id := parent_row.owner_organization_membership_id;
  owner_subject_id := parent_row.owner_subject_id;
  RETURN NEXT;
END
$$;

COMMENT ON FUNCTION open_private_child_session_create_capability(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_parent_session_id uuid, p_actor_turn_id uuid, p_actor_attempt_id uuid, p_actor_execution_generation integer) IS 'One exact live private-parent attempt may insert one same-owner private child.';

CREATE FUNCTION open_private_session_create_capability(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_actor_subject_id text) RETURNS TABLE(capability_id uuid, owner_membership_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  new_capability_id uuid := pg_catalog.gen_random_uuid();
  actor_membership_id uuid;
  actor_personal_workspace boolean;
  workspace_access_id uuid;
  previous_lifecycle text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_actor_subject_id IS NULL OR (p_actor_subject_id NOT LIKE 'user:%' AND NOT opengeni_private.active_external_owning_subject(p_account_id, p_actor_subject_id))
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR NOT session_tenancy_product_activated(p_account_id, 1)
  THEN
    RAISE EXCEPTION 'private session create authority required' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || p_account_id::text, 0
  ));
  PERFORM 1 FROM workspace_inference_controls control
  WHERE control.account_id = p_account_id AND control.workspace_id = p_workspace_id
  FOR SHARE;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR KEY SHARE;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'private_session_create_authority', true
  );
  SELECT membership.id, membership.personal_workspace_id = p_workspace_id
  INTO actor_membership_id, actor_personal_workspace
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id
    AND membership.status = 'active'
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'private session create authority required' USING ERRCODE = '42501';
  END IF;
  IF NOT actor_personal_workspace THEN
    SELECT access.id INTO workspace_access_id
    FROM workspace_memberships access
    WHERE access.account_id = p_account_id
      AND access.workspace_id = p_workspace_id
      AND access.subject_id = p_actor_subject_id
    FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'private session create authority required' USING ERRCODE = '42501';
    END IF;
    IF NOT organization_private_sessions_enabled(p_account_id) THEN
      RAISE EXCEPTION
        'private sessions are not enabled for this organization''s shared workspaces'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.private_session_create_lifecycle', 'private_session_create', true
  );
  INSERT INTO private_session_create_capabilities (
    backend_pid, transaction_id, capability_id, account_id, workspace_id,
    session_id, actor_subject_id, owner_membership_id
  ) VALUES (
    pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
    new_capability_id, p_account_id, p_workspace_id, p_session_id,
    p_actor_subject_id, actor_membership_id
  );
  PERFORM pg_catalog.set_config(
    'opengeni.private_session_create_capability', new_capability_id::text, true
  );
  capability_id := new_capability_id;
  owner_membership_id := actor_membership_id;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION open_private_session_create_capability(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_actor_subject_id text) IS 'Opens the exact transaction-local private-create capability (0311). Since 0323 a shared-workspace create additionally requires the enabled organization_private_session_settings row, read under the organization advisory fence when the caller already holds it (repaired TypeScript order) and otherwise unfenced after a non-blocking try so pre-0323 callers cannot deadlock; SQLSTATE 55000 means the owner/admin setting is disabled, every authority failure stays 42501.';

CREATE FUNCTION open_tenancy_backfill_receipt(p_account_id uuid, p_resource_family text, p_run_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  previous_lifecycle_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
  receipt_id uuid;
  receipt_status text;
BEGIN
  IF p_account_id IS NULL OR p_resource_family IS NULL OR p_run_key IS NULL THEN
    RAISE EXCEPTION 'tenancy backfill receipt requires organization, family, and run key'
      USING ERRCODE = '22004';
  END IF;

  IF p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'tenancy backfill ledger scope mismatch'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'tenancy_backfill_ledger', true
  );

  SELECT existing.id, existing.status INTO receipt_id, receipt_status
  FROM tenancy_backfill_receipts existing
  WHERE existing.account_id = p_account_id
    AND existing.resource_family = p_resource_family
    AND existing.run_key = p_run_key
  FOR UPDATE;

  IF receipt_id IS NULL THEN
    INSERT INTO tenancy_backfill_receipts (account_id, resource_family, run_key)
    VALUES (p_account_id, p_resource_family, p_run_key)
    ON CONFLICT ("account_id", "resource_family", "run_key") DO NOTHING
    RETURNING id, status INTO receipt_id, receipt_status;

    IF receipt_id IS NULL THEN
      -- A concurrent opener committed the same run key first: adopt its row.
      SELECT existing.id, existing.status INTO receipt_id, receipt_status
      FROM tenancy_backfill_receipts existing
      WHERE existing.account_id = p_account_id
        AND existing.resource_family = p_resource_family
        AND existing.run_key = p_run_key
      FOR UPDATE;

      IF receipt_id IS NULL THEN
        RAISE EXCEPTION 'tenancy backfill receipt for run key % could not be opened or adopted',
          p_run_key
          USING ERRCODE = '40001';
      END IF;
    END IF;
  END IF;

  IF receipt_status <> 'open' THEN
    RAISE EXCEPTION 'tenancy backfill receipt % is already settled', receipt_id
      USING ERRCODE = '55000';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    coalesce(previous_lifecycle_marker, ''), true
  );
  RETURN receipt_id;
END;
$$;

CREATE FUNCTION organization_membership_command(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  action_name text := p_command ->> 'action';
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  target_id uuid;
  target_subject text;
  workspace_id_value uuid;
BEGIN
  IF action_name NOT IN ('suspend', 'offboard') THEN
    RETURN organization_membership_command_0263(p_command);
  END IF;
  IF p_command IS NULL
    OR account_id_value IS NULL
    OR actor_subject IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization membership command authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  target_id := nullif(p_command ->> 'membershipId', '')::uuid;
  IF target_id IS NULL THEN
    RAISE EXCEPTION 'organization membership target is invalid'
      USING ERRCODE = '22023';
  END IF;

  -- The application settles the target's pending protocol state first and
  -- finalizes that workspace activity gate, which leaves the session commit
  -- guards IMMEDIATE for the rest of the transaction. The wrapped command then
  -- opens the gate again per workspace and stamps its own writes through the
  -- same finalization protocol, so its guards must start DEFERRED exactly as
  -- they were when 0263 shipped; otherwise a target with live turns in a
  -- workspace-shared session fails at its first gated session write.
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard DEFERRED;

  -- The organization advisory fence is the organization-lifecycle prefix. It
  -- makes the following non-locking identity reads stable against another
  -- membership command without conflicting with the FK `FOR KEY SHARE` that
  -- every ordinary workspace writer takes on this same row.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  ));
  PERFORM acquire_organization_session_tenancy_fences(
    account_id_value
  );
  PERFORM 1 FROM managed_accounts account
  WHERE account.id = account_id_value
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT membership.subject_id INTO target_subject
  FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.id = target_id;
  IF target_subject IS NULL THEN
    RAISE EXCEPTION 'organization membership not found' USING ERRCODE = 'P0002';
  END IF;

  -- Match the command's existing account-wide workspace prefix before the new
  -- task/session suffix. The wrapped implementation re-locks these rows
  -- reentrantly and then continues with its canonical turn/attempt mutations.
  FOR workspace_id_value IN
    SELECT workspace.id
    FROM workspaces workspace
    WHERE workspace.account_id = account_id_value
    ORDER BY workspace.id
  LOOP
    PERFORM pg_catalog.set_config(
      'opengeni.workspace_id', workspace_id_value::text, true
    );
    PERFORM 1 FROM workspace_inference_controls control
    WHERE control.account_id = account_id_value
      AND control.workspace_id = workspace_id_value
    FOR SHARE;
    PERFORM 1 FROM workspaces workspace
    WHERE workspace.account_id = account_id_value
      AND workspace.id = workspace_id_value
    FOR KEY SHARE;

    -- Task/session prefix per workspace: FORCE-RLS on both tables resolves the
    -- exact opengeni.workspace_id GUC, so a non-BYPASSRLS definer owner would
    -- otherwise lock and pause only the last workspace's rows.
    PERFORM 1 FROM scheduled_tasks task
    WHERE task.account_id = account_id_value
      AND task.workspace_id = workspace_id_value
      AND task.deleted_at IS NULL
      AND task.status = 'active'
      AND (
        (task.created_by_kind = 'subject' AND task.created_by_subject_id = target_subject)
        OR EXISTS (
          SELECT 1 FROM scheduled_task_revision_authorities authority
          WHERE authority.task_id = task.id
            AND authority.task_authority_revision = task.authority_revision
            AND authority.subject_id = target_subject
        )
        OR EXISTS (
          SELECT 1 FROM scheduled_task_personal_resource_authorities authority
          WHERE authority.task_id = task.id
            AND authority.task_authority_revision = task.authority_revision
            AND authority.initiating_human_subject_id = target_subject
        )
        OR EXISTS (
          SELECT 1 FROM scheduled_task_connection_authority_snapshots snapshot
          WHERE snapshot.task_id = task.id
            AND snapshot.task_authority_revision = task.authority_revision
            AND snapshot.owner_subject_id = target_subject
        )
      )
    ORDER BY task.id
    FOR UPDATE;

    PERFORM 1 FROM sessions session_row
    WHERE session_row.account_id = account_id_value
      AND session_row.workspace_id = workspace_id_value
      AND (
        session_row.owner_organization_membership_id = target_id
        OR EXISTS (
          SELECT 1 FROM session_turns initiated
          WHERE initiated.account_id = account_id_value
            AND initiated.session_id = session_row.id
            AND initiated.initiating_human_subject_id = target_subject
        )
        OR EXISTS (
          SELECT 1 FROM scheduled_tasks task
          WHERE task.account_id = account_id_value
            AND task.workspace_id = workspace_id_value
            AND task.deleted_at IS NULL
            AND task.status = 'active'
            AND (
              (task.created_by_kind = 'subject' AND task.created_by_subject_id = target_subject)
              OR EXISTS (
                SELECT 1 FROM scheduled_task_revision_authorities authority
                WHERE authority.task_id = task.id
                  AND authority.task_authority_revision = task.authority_revision
                  AND authority.subject_id = target_subject
              )
              OR EXISTS (
                SELECT 1 FROM scheduled_task_personal_resource_authorities authority
                WHERE authority.task_id = task.id
                  AND authority.task_authority_revision = task.authority_revision
                  AND authority.initiating_human_subject_id = target_subject
              )
              OR EXISTS (
                SELECT 1 FROM scheduled_task_connection_authority_snapshots snapshot
                WHERE snapshot.task_id = task.id
                  AND snapshot.task_authority_revision = task.authority_revision
                  AND snapshot.owner_subject_id = target_subject
              )
            )
            AND task.reusable_session_id = session_row.id
        )
      )
    ORDER BY session_row.id
    FOR NO KEY UPDATE;



    -- Pause every task whose current frozen execution authority belongs to the
    -- target, including A-created tasks explicitly reauthorized by B. Doing this
    -- while the target membership is still live preserves task -> session ->
    -- membership order; the wrapped command then performs the revocation.
    UPDATE scheduled_tasks task
    SET status = 'paused', personal_connection_delegations = '[]'::jsonb,
      authority_revision = task.authority_revision + 1,
      updated_at = clock_timestamp()
    WHERE task.account_id = account_id_value
      AND task.workspace_id = workspace_id_value
      AND task.deleted_at IS NULL
      AND task.status = 'active'
      AND (
        (task.created_by_kind = 'subject' AND task.created_by_subject_id = target_subject)
        OR EXISTS (
          SELECT 1 FROM scheduled_task_revision_authorities authority
          WHERE authority.task_id = task.id
            AND authority.task_authority_revision = task.authority_revision
            AND authority.subject_id = target_subject
        )
        OR EXISTS (
          SELECT 1 FROM scheduled_task_personal_resource_authorities authority
          WHERE authority.task_id = task.id
            AND authority.task_authority_revision = task.authority_revision
            AND authority.initiating_human_subject_id = target_subject
        )
        OR EXISTS (
          SELECT 1 FROM scheduled_task_connection_authority_snapshots snapshot
          WHERE snapshot.task_id = task.id
            AND snapshot.task_authority_revision = task.authority_revision
            AND snapshot.owner_subject_id = target_subject
        )
      );
  END LOOP;

  PERFORM 1 FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.id IN (
      target_id,
      (
        SELECT actor.id FROM organization_memberships actor
        WHERE actor.account_id = account_id_value
          AND actor.subject_id = actor_subject
      )
    )
  ORDER BY membership.id
  FOR UPDATE;

  RETURN organization_membership_command_0263(p_command);
END
$$;

COMMENT ON FUNCTION organization_membership_command(p_command jsonb) IS 'Organization membership lifecycle command (invite, accept, revoke_invitation, change_role, suspend, reactivate, offboard, retention). Mutual exclusion between concurrent commands for one organization is the advisory fence hashtextextended(''organization-membership:<organization id>''), not a managed_accounts row lock. CAS on organization_memberships.authorization_revision and the operation-receipt idempotency are unchanged.';

CREATE FUNCTION organization_membership_command_0263(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  action_name text := p_command ->> 'action';
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  input_hash_value text;
  service_authorized boolean := false;
  receipt_row organization_membership_operation_receipts%ROWTYPE;
  actor organization_memberships%ROWTYPE;
  target organization_memberships%ROWTYPE;
  invitation organization_membership_invitations%ROWTYPE;
  policy organization_user_retention_policies%ROWTYPE;
  result jsonb;
  now_value timestamptz := pg_catalog.clock_timestamp();
  target_subject text;
  target_email text;
  requested_role text;
  target_id uuid;
  expected_revision bigint;
  workspace_id_value uuid;
  reason_value text;
  retention_days_value integer;
  previous_workspace text := pg_catalog.current_setting('opengeni.workspace_id', true);
  previous_visibility_capability text := pg_catalog.current_setting(
    'opengeni.session_visibility_write_capability', true
  );
  previous_activity_gate_state text := pg_catalog.current_setting(
    'opengeni.session_activity_gate_state', true
  );
  previous_activity_gate_workspace text := pg_catalog.current_setting(
    'opengeni.session_activity_gate_workspace_id', true
  );
  visibility_capability_id uuid;
  interruption_operation_id uuid;
  affected_session_ids uuid[];
  affected_realtime_ids uuid[];
  cancelled_turn_ids uuid[];
  cancelled_turn record;
  cancelled_request record;
  cancelled_sequence bigint;
  cancelled_association text;
  settled_update_ids uuid[];
  settled_history_item_id uuid;
  activity_revision_value bigint;
BEGIN
  IF p_command IS NULL
    OR action_name NOT IN ('invite', 'accept', 'revoke_invitation', 'change_role', 'suspend', 'reactivate', 'offboard', 'retention')
    OR account_id_value IS NULL
    OR operation_id_value IS NULL
    OR actor_subject IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization membership command authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  service_authorized := opengeni_private.external_membership_service_authority(p_command);
  input_hash_value := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(p_command::text, 'UTF8')), 'hex'
  );
  -- Lock-order repair: advisory organization fence plus a non-conflicting row lock
  -- (see the header: `FOR UPDATE` here inverted the canonical order).
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  ));
  PERFORM acquire_organization_session_tenancy_fences(
    account_id_value
  );
  PERFORM 1 FROM managed_accounts account WHERE account.id = account_id_value FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );

  SELECT * INTO receipt_row
  FROM organization_membership_operation_receipts receipt
  WHERE receipt.account_id = account_id_value
    AND receipt.operation_id = operation_id_value
  FOR UPDATE;
  IF FOUND THEN
    IF receipt_row.action IS DISTINCT FROM action_name
      OR receipt_row.input_hash IS DISTINCT FROM input_hash_value
    THEN
      RAISE EXCEPTION 'organization operation id was reused with different input'
        USING ERRCODE = '23505';
    END IF;
    RETURN receipt_row.result;
  END IF;

  IF action_name = 'accept' THEN
    target_id := nullif(p_command ->> 'invitationId', '')::uuid;
    expected_revision := nullif(p_command ->> 'expectedRevision', '')::bigint;
    SELECT * INTO invitation
    FROM organization_membership_invitations candidate
    WHERE candidate.id = target_id AND candidate.account_id = account_id_value
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'invitation not found' USING ERRCODE = 'P0002'; END IF;
    IF invitation.target_subject_id IS DISTINCT FROM actor_subject THEN
      RAISE EXCEPTION 'invitation belongs to another subject' USING ERRCODE = '42501';
    END IF;
    IF invitation.status <> 'pending' OR invitation.expires_at <= now_value THEN
      RAISE EXCEPTION 'invitation is not active' USING ERRCODE = '55000';
    END IF;
    IF invitation.revision IS DISTINCT FROM expected_revision THEN
      RAISE EXCEPTION 'invitation revision is stale' USING ERRCODE = '40001';
    END IF;
    SELECT * INTO target FROM organization_memberships membership
    WHERE membership.account_id = account_id_value
      AND membership.subject_id = actor_subject
    FOR UPDATE;
    IF NOT FOUND THEN
      workspace_id_value := gen_random_uuid();
      PERFORM pg_catalog.set_config('opengeni.workspace_id', workspace_id_value::text, true);
      INSERT INTO workspaces (
        id, account_id, name, slug, external_source, external_id
      ) VALUES (
        workspace_id_value, account_id_value, 'Personal workspace', NULL,
        'opengeni:organization-membership', account_id_value::text || ':' || actor_subject
      ) ON CONFLICT (account_id, external_source, external_id) DO UPDATE
        SET updated_at = workspaces.updated_at
      RETURNING id INTO workspace_id_value;
      INSERT INTO workspace_inference_controls (workspace_id, account_id)
      VALUES (workspace_id_value, account_id_value) ON CONFLICT DO NOTHING;
      INSERT INTO organization_memberships (
        account_id, subject_id, role, status, personal_workspace_id
      ) VALUES (
        account_id_value, actor_subject, invitation.role, 'active', workspace_id_value
      ) RETURNING * INTO target;
    ELSE
      IF target.status = 'active' THEN
        RAISE EXCEPTION 'organization membership is already active' USING ERRCODE = '55000';
      END IF;
      RAISE EXCEPTION 'inactive organization membership requires explicit owner lifecycle action'
        USING ERRCODE = '55000';
    END IF;
    UPDATE organization_membership_invitations SET
      status = 'accepted', revision = revision + 1,
      accepted_membership_id = target.id, updated_at = now_value
    WHERE id = invitation.id RETURNING * INTO invitation;
    result := pg_catalog.jsonb_build_object(
      'invitation', opengeni_private.organization_invitation_row_json(invitation),
      'membership', opengeni_private.organization_membership_row_json(target)
    );
    actor := target;
  ELSE
    -- Existing session-visibility activation serializes workspace -> member ->
    -- session. Offboarding spans every owned workspace, so pre-lock that exact
    -- workspace prefix in UUID order before locking either actor or target
    -- membership. This prevents member/workspace lock inversion while the
    -- later per-workspace pass takes the canonical session/turn/attempt suffix.
    IF action_name IN ('suspend', 'offboard') THEN
      target_id := nullif(p_command ->> 'membershipId', '')::uuid;
      expected_revision := nullif(
        p_command ->> 'expectedAuthorizationRevision', ''
      )::bigint;
      FOR workspace_id_value IN
        SELECT workspace.id
        FROM workspaces workspace
        WHERE workspace.account_id = account_id_value
        ORDER BY workspace.id
      LOOP
        PERFORM pg_catalog.set_config(
          'opengeni.workspace_id', workspace_id_value::text, true
        );
        PERFORM 1 FROM workspace_inference_controls control
        WHERE control.account_id = account_id_value
          AND control.workspace_id = workspace_id_value
        FOR SHARE;
        PERFORM 1 FROM workspaces workspace
        WHERE workspace.account_id = account_id_value
          AND workspace.id = workspace_id_value
        FOR KEY SHARE;
      END LOOP;
      PERFORM 1 FROM organization_memberships membership
      WHERE membership.account_id = account_id_value
        AND membership.id IN (
          target_id,
          (
            SELECT candidate.id FROM organization_memberships candidate
            WHERE candidate.account_id = account_id_value
              AND candidate.subject_id = actor_subject
          )
        )
      ORDER BY membership.id
      FOR UPDATE;
      SELECT * INTO actor FROM organization_memberships membership
      WHERE membership.account_id = account_id_value
        AND membership.subject_id = actor_subject;
    ELSE
      SELECT * INTO actor FROM organization_memberships membership
      WHERE membership.account_id = account_id_value
        AND membership.subject_id = actor_subject
      FOR UPDATE;
    END IF;
    IF NOT service_authorized AND (NOT FOUND OR actor.status <> 'active') THEN
      RAISE EXCEPTION 'active organization membership required' USING ERRCODE = '42501';
    END IF;

    IF action_name = 'invite' THEN
      IF NOT service_authorized AND actor.role NOT IN ('owner', 'admin') THEN
        RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
      END IF;
      target_subject := p_command ->> 'targetSubjectId';
      target_email := lower(btrim(p_command ->> 'targetEmail'));
      requested_role := p_command ->> 'role';
      IF target_subject IS NULL OR target_subject NOT LIKE 'user:%'
        OR requested_role NOT IN ('owner', 'admin', 'member')
        OR (actor.role = 'admin' AND requested_role <> 'member')
        OR nullif(p_command ->> 'expiresAt', '')::timestamptz <= now_value
        OR nullif(p_command ->> 'expiresAt', '')::timestamptz > now_value + interval '30 days'
      THEN
        RAISE EXCEPTION 'invitation input is invalid' USING ERRCODE = '22023';
      END IF;
      IF EXISTS (
        SELECT 1 FROM organization_memberships membership
        WHERE membership.account_id = account_id_value
          AND membership.subject_id = target_subject
          AND membership.status = 'active'
      ) THEN
        RAISE EXCEPTION 'subject is already an active organization member' USING ERRCODE = '55000';
      END IF;
      IF EXISTS (
        SELECT 1 FROM organization_memberships membership
        WHERE membership.account_id = account_id_value
          AND membership.subject_id = target_subject
          AND membership.status IN ('suspended', 'revoked')
      ) THEN
        RAISE EXCEPTION 'inactive organization membership cannot be re-invited'
          USING ERRCODE = '55000';
      END IF;
      UPDATE organization_membership_invitations SET
        status = 'revoked', revision = revision + 1, updated_at = now_value
      WHERE account_id = account_id_value
        AND target_subject_id = target_subject AND status = 'pending';
      INSERT INTO organization_membership_invitations (
        account_id, target_subject_id, target_email, role,
        created_by_membership_id, expires_at
      ) VALUES (
        account_id_value, target_subject, target_email, requested_role,
        actor.id, nullif(p_command ->> 'expiresAt', '')::timestamptz
      ) RETURNING * INTO invitation;
      result := opengeni_private.organization_invitation_row_json(invitation);
      target := NULL;
    ELSIF action_name = 'revoke_invitation' THEN
      IF NOT service_authorized AND actor.role NOT IN ('owner', 'admin') THEN
        RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
      END IF;
      target_id := nullif(p_command ->> 'invitationId', '')::uuid;
      expected_revision := nullif(p_command ->> 'expectedRevision', '')::bigint;
      SELECT * INTO invitation
      FROM organization_membership_invitations candidate
      WHERE candidate.id = target_id AND candidate.account_id = account_id_value
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'invitation not found' USING ERRCODE = 'P0002'; END IF;
      IF invitation.revision IS DISTINCT FROM expected_revision THEN
        RAISE EXCEPTION 'invitation revision is stale' USING ERRCODE = '40001';
      END IF;
      IF invitation.status <> 'pending' THEN
        RAISE EXCEPTION 'only a pending invitation can be revoked' USING ERRCODE = '55000';
      END IF;
      IF actor.role = 'admin' AND invitation.role <> 'member' THEN
        RAISE EXCEPTION 'administrators may revoke member invitations only' USING ERRCODE = '42501';
      END IF;
      UPDATE organization_membership_invitations SET
        status = 'revoked', revision = revision + 1, updated_at = now_value
      WHERE id = invitation.id RETURNING * INTO invitation;
      result := opengeni_private.organization_invitation_row_json(invitation);
      target := NULL;
    ELSIF action_name = 'retention' THEN
      IF actor.role <> 'owner' THEN
        RAISE EXCEPTION 'organization owner required' USING ERRCODE = '42501';
      END IF;
      expected_revision := nullif(p_command ->> 'expectedVersion', '')::bigint;
      requested_role := p_command ->> 'mode';
      retention_days_value := nullif(p_command ->> 'retentionDays', '')::integer;
      IF requested_role NOT IN ('retain', 'delete_after')
        OR (requested_role = 'retain' AND retention_days_value IS NOT NULL)
        OR (requested_role = 'delete_after' AND retention_days_value NOT BETWEEN 30 AND 90)
      THEN
        RAISE EXCEPTION 'retention policy input is invalid' USING ERRCODE = '22023';
      END IF;
      SELECT * INTO policy FROM organization_user_retention_policies candidate
      WHERE candidate.account_id = account_id_value FOR UPDATE;
      IF NOT FOUND THEN
        INSERT INTO organization_user_retention_policies (
          account_id, mode, retention_days, version, updated_by_membership_id
        ) VALUES (account_id_value, 'retain', NULL, 1, actor.id)
        RETURNING * INTO policy;
      END IF;
      IF policy.version IS DISTINCT FROM expected_revision THEN
        RAISE EXCEPTION 'retention policy version is stale' USING ERRCODE = '40001';
      END IF;
      UPDATE organization_user_retention_policies SET
        mode = requested_role, retention_days = retention_days_value,
        version = version + 1, updated_by_membership_id = actor.id,
        updated_at = now_value
      WHERE account_id = account_id_value RETURNING * INTO policy;
      result := pg_catalog.jsonb_build_object(
        'organizationId', policy.account_id, 'mode', policy.mode,
        'retentionDays', policy.retention_days, 'version', policy.version,
        'updatedAt', policy.updated_at
      );
      target := NULL;
    ELSE
      IF NOT service_authorized AND actor.role NOT IN ('owner', 'admin') THEN
        RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
      END IF;
      target_id := nullif(p_command ->> 'membershipId', '')::uuid;
      expected_revision := nullif(p_command ->> 'expectedAuthorizationRevision', '')::bigint;
      requested_role := p_command ->> 'role';
      reason_value := nullif(btrim(p_command ->> 'reason'), '');
      IF reason_value IS NOT NULL
        AND octet_length(convert_to(reason_value, 'UTF8')) > 512
      THEN RAISE EXCEPTION 'reason is too large' USING ERRCODE = '22023'; END IF;
      PERFORM 1 FROM organization_memberships membership
      WHERE membership.account_id = account_id_value
        AND membership.id IN (actor.id, target_id)
      ORDER BY membership.id FOR UPDATE;
      SELECT * INTO target FROM organization_memberships membership
      WHERE membership.account_id = account_id_value AND membership.id = target_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'organization member not found' USING ERRCODE = 'P0002'; END IF;
      IF target.authorization_revision IS DISTINCT FROM expected_revision THEN
        RAISE EXCEPTION 'organization membership revision is stale' USING ERRCODE = '40001';
      END IF;
      IF actor.role = 'admin' AND target.role <> 'member' THEN
        RAISE EXCEPTION 'administrators may manage members only' USING ERRCODE = '42501';
      END IF;
      IF target.role = 'owner' AND (
        action_name IN ('suspend', 'offboard')
        OR (action_name = 'change_role' AND requested_role <> 'owner')
      ) AND NOT EXISTS (
        SELECT 1 FROM organization_memberships other
        WHERE other.account_id = account_id_value AND other.id <> target.id
          AND other.status = 'active' AND other.role = 'owner'
      ) THEN
        RAISE EXCEPTION 'cannot remove the last active organization owner'
          USING ERRCODE = '55000';
      END IF;
      IF action_name = 'change_role' THEN
        IF target.status <> 'active' OR requested_role NOT IN ('owner', 'admin', 'member')
          OR (actor.role = 'admin' AND requested_role <> 'member')
        THEN RAISE EXCEPTION 'role transition is invalid' USING ERRCODE = '55000'; END IF;
        UPDATE organization_memberships SET role = requested_role,
          authorization_revision = authorization_revision + 1, updated_at = now_value
        WHERE id = target.id RETURNING * INTO target;
      ELSIF action_name = 'reactivate' THEN
        IF target.status <> 'suspended' THEN
          RAISE EXCEPTION 'only a suspended member can be reactivated' USING ERRCODE = '55000';
        END IF;
        UPDATE organization_memberships SET status = 'active',
          authorization_revision = authorization_revision + 1, updated_at = now_value
        WHERE id = target.id RETURNING * INTO target;
      ELSIF action_name IN ('suspend', 'offboard') THEN
        IF action_name = 'suspend' AND target.status <> 'active' THEN
          RAISE EXCEPTION 'only an active member can be suspended' USING ERRCODE = '55000';
        ELSIF action_name = 'offboard' AND target.status NOT IN ('active', 'suspended') THEN
          RAISE EXCEPTION 'only an active or suspended member can be offboarded'
            USING ERRCODE = '55000';
        END IF;
        SELECT * INTO policy FROM organization_user_retention_policies candidate
        WHERE candidate.account_id = account_id_value;
        UPDATE organization_user_resource_grants SET
          status = 'revoked', generation = generation + 1,
          revoked_at = now_value, updated_at = now_value
        WHERE account_id = account_id_value
          AND owner_organization_membership_id = target.id AND status = 'active';
        UPDATE organization_user_resource_authorities SET
          status = 'retained', generation = generation + 1, updated_at = now_value
        WHERE account_id = account_id_value
          AND organization_membership_id = target.id AND status = 'active'
          AND action_name = 'offboard';
        DELETE FROM workspace_memberships
        WHERE account_id = account_id_value AND subject_id = target.subject_id;
        -- Private-session attempts carry the exact authority epoch. Advance it
        -- under each workspace's FORCE-RLS context without touching updated_at
        -- (the session activity commit gate owns that separate concern).
        visibility_capability_id := pg_catalog.gen_random_uuid();
        INSERT INTO session_visibility_write_capabilities (
          backend_pid, transaction_id, capability_id
        ) VALUES (
          pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
          visibility_capability_id
        );
        PERFORM pg_catalog.set_config(
          'opengeni.session_visibility_write_capability',
          visibility_capability_id::text, true
        );
        FOR workspace_id_value IN
          SELECT workspace.id
          FROM workspaces workspace
          WHERE workspace.account_id = account_id_value
          ORDER BY workspace.id
        LOOP
          PERFORM pg_catalog.set_config(
            'opengeni.workspace_id', workspace_id_value::text, true
          );
          PERFORM pg_catalog.set_config(
            'opengeni.session_activity_gate_state', 'open', true
          );
          PERFORM pg_catalog.set_config(
            'opengeni.session_activity_gate_workspace_id', workspace_id_value::text, true
          );
          PERFORM 1 FROM workspace_inference_controls control
          WHERE control.account_id = account_id_value
            AND control.workspace_id = workspace_id_value
          FOR SHARE;
          PERFORM 1 FROM workspaces workspace
          WHERE workspace.account_id = account_id_value
            AND workspace.id = workspace_id_value
          FOR KEY SHARE;
          PERFORM 1 FROM sessions affected
          WHERE affected.account_id = account_id_value
            AND affected.workspace_id = workspace_id_value
            AND (
              affected.owner_organization_membership_id = target.id
              OR EXISTS (
                SELECT 1 FROM session_turns initiated
                WHERE initiated.session_id = affected.id
                  AND initiated.initiating_human_subject_id = target.subject_id
              )
            )
          ORDER BY affected.id
          FOR NO KEY UPDATE;
          PERFORM 1 FROM session_turns turn_row
          WHERE turn_row.account_id = account_id_value
            AND turn_row.workspace_id = workspace_id_value
            AND EXISTS (
              SELECT 1 FROM sessions owned
              WHERE owned.id = turn_row.session_id
                AND (
                  owned.owner_organization_membership_id = target.id
                  OR turn_row.initiating_human_subject_id = target.subject_id
                )
            )
          ORDER BY turn_row.id
          FOR UPDATE;
          PERFORM 1 FROM session_turn_attempts attempt
          WHERE attempt.account_id = account_id_value
            AND attempt.workspace_id = workspace_id_value
            AND EXISTS (
              SELECT 1 FROM sessions owned
              WHERE owned.id = attempt.session_id
                AND (
                  owned.owner_organization_membership_id = target.id
                  OR EXISTS (
                    SELECT 1 FROM session_turns initiated
                    WHERE initiated.id = attempt.turn_id
                      AND initiated.initiating_human_subject_id = target.subject_id
                  )
                )
            )
          ORDER BY attempt.id
          FOR UPDATE;
          PERFORM 1 FROM session_realtime_modes realtime
          WHERE realtime.account_id = account_id_value
            AND realtime.workspace_id = workspace_id_value
            AND realtime.owner_subject_id = target.subject_id
            AND realtime.state = 'active'
          ORDER BY realtime.id
          FOR UPDATE;
          SELECT COALESCE(pg_catalog.array_agg(realtime.id ORDER BY realtime.id), ARRAY[]::uuid[])
          INTO affected_realtime_ids
          FROM session_realtime_modes realtime
          WHERE realtime.account_id = account_id_value
            AND realtime.workspace_id = workspace_id_value
            AND realtime.owner_subject_id = target.subject_id
            AND realtime.state = 'active';
          PERFORM 1 FROM session_realtime_connections connection
          WHERE connection.account_id = account_id_value
            AND connection.workspace_id = workspace_id_value
            AND connection.realtime_id = ANY(affected_realtime_ids)
            AND connection.state IN ('negotiating', 'ready', 'active')
          ORDER BY connection.id
          FOR UPDATE;
          IF EXISTS (
            SELECT 1
            FROM session_turns turn_row
            JOIN sessions owned ON owned.id = turn_row.session_id
            WHERE turn_row.account_id = account_id_value
              AND turn_row.workspace_id = workspace_id_value
              AND turn_row.status IN (
                'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
              )
              AND (
                owned.owner_organization_membership_id = target.id
                OR turn_row.initiating_human_subject_id = target.subject_id
              )
              AND EXISTS (
                SELECT 1 FROM session_pending_tool_calls pending
                WHERE pending.account_id = turn_row.account_id
                  AND pending.workspace_id = turn_row.workspace_id
                  AND pending.session_id = turn_row.session_id
                  AND pending.turn_id = turn_row.id
              )
              AND NOT EXISTS (
                SELECT 1 FROM session_turn_attempts live_attempt
                WHERE live_attempt.account_id = turn_row.account_id
                  AND live_attempt.workspace_id = turn_row.workspace_id
                  AND live_attempt.session_id = turn_row.session_id
                  AND live_attempt.turn_id = turn_row.id
                  AND live_attempt.id = turn_row.active_attempt_id
                  AND live_attempt.state IN ('claimed', 'running')
              )
          ) THEN
            RAISE EXCEPTION 'pending tool calls require canonical protocol settlement'
              USING ERRCODE = '55000';
          END IF;
          SELECT COALESCE(pg_catalog.array_agg(DISTINCT turn_row.session_id), ARRAY[]::uuid[])
          INTO affected_session_ids
          FROM session_turns turn_row
          JOIN sessions owned
            ON owned.account_id = turn_row.account_id
           AND owned.workspace_id = turn_row.workspace_id
           AND owned.id = turn_row.session_id
          WHERE turn_row.account_id = account_id_value
            AND turn_row.workspace_id = workspace_id_value
            AND turn_row.status IN (
              'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
            )
            AND (
              owned.owner_organization_membership_id = target.id
              OR turn_row.initiating_human_subject_id = target.subject_id
            );
          affected_session_ids := ARRAY(
            SELECT DISTINCT candidate.session_id
            FROM (
              SELECT unnest(affected_session_ids) AS session_id
              UNION ALL
              SELECT realtime.session_id
              FROM session_realtime_modes realtime
              WHERE realtime.id = ANY(affected_realtime_ids)
            ) candidate
            ORDER BY candidate.session_id
          );
          interruption_operation_id := pg_catalog.gen_random_uuid();
          INSERT INTO session_command_receipts (
            id, account_id, workspace_id, actor_type, actor_subject_id,
            action, operation_key, canonical_request_hash, result
          ) VALUES (
            interruption_operation_id, account_id_value, workspace_id_value,
            CASE WHEN service_authorized THEN 'service' ELSE 'human' END, actor_subject, 'organization.membership.' || action_name,
            'organization-membership:' || operation_id_value::text,
            input_hash_value,
            pg_catalog.jsonb_build_object(
              'organizationMembershipOperationId', operation_id_value,
              'organizationMembershipId', target.id
            )
          );
          INSERT INTO session_attempt_interruptions (
            account_id, workspace_id, session_id, operation_id, attempt_id,
            kind, control_revision
          )
          SELECT attempt.account_id, attempt.workspace_id, attempt.session_id,
            interruption_operation_id, attempt.id, 'organization_membership_revoked',
            CASE WHEN owned.owner_organization_membership_id = target.id
              THEN owned.authority_epoch + 1 ELSE owned.authority_epoch END
          FROM session_turn_attempts attempt
          JOIN sessions owned ON owned.id = attempt.session_id
          JOIN session_turns initiated ON initiated.id = attempt.turn_id
          WHERE attempt.account_id = account_id_value
            AND attempt.workspace_id = workspace_id_value
            AND (
              owned.owner_organization_membership_id = target.id
              OR initiated.initiating_human_subject_id = target.subject_id
            )
            AND attempt.state IN ('claimed', 'running')
          ON CONFLICT ON CONSTRAINT session_attempt_interruptions_operation_attempt_uq
          DO NOTHING;
          WITH cancelled AS (
            UPDATE session_turns turn_row
            SET status = 'cancelled', active_attempt_id = NULL,
              cancelled_by = actor_subject, cancel_reason = 'authority_changed',
              finished_at = now_value, updated_at = now_value,
              version = turn_row.version + 1
            WHERE turn_row.account_id = account_id_value
              AND turn_row.workspace_id = workspace_id_value
              AND turn_row.status IN (
                'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
              )
              AND EXISTS (
                SELECT 1 FROM sessions owned
                WHERE owned.account_id = turn_row.account_id
                  AND owned.workspace_id = turn_row.workspace_id
                  AND owned.id = turn_row.session_id
                  AND (
                    owned.owner_organization_membership_id = target.id
                    OR turn_row.initiating_human_subject_id = target.subject_id
                  )
              )
              AND NOT EXISTS (
                SELECT 1 FROM session_turn_attempts live_attempt
                WHERE live_attempt.account_id = turn_row.account_id
                  AND live_attempt.workspace_id = turn_row.workspace_id
                  AND live_attempt.session_id = turn_row.session_id
                  AND live_attempt.turn_id = turn_row.id
                  AND live_attempt.id = turn_row.active_attempt_id
                  AND live_attempt.state IN ('claimed', 'running')
              )
            RETURNING turn_row.id
          )
          SELECT COALESCE(pg_catalog.array_agg(cancelled.id ORDER BY cancelled.id), ARRAY[]::uuid[])
          INTO cancelled_turn_ids
          FROM cancelled;
          FOR cancelled_turn IN
            SELECT turn_row.id, turn_row.session_id, turn_row.execution_generation
            FROM session_turns turn_row
            WHERE turn_row.account_id = account_id_value
              AND turn_row.workspace_id = workspace_id_value
              AND turn_row.id = ANY(cancelled_turn_ids)
            ORDER BY turn_row.session_id, turn_row.id
          LOOP
            SELECT affected.last_sequence,
              CASE WHEN affected.active_turn_id = cancelled_turn.id
                THEN 'current' ELSE NULL END
            INTO cancelled_sequence, cancelled_association
            FROM sessions affected
            WHERE affected.account_id = account_id_value
              AND affected.workspace_id = workspace_id_value
              AND affected.id = cancelled_turn.session_id;
            FOR cancelled_request IN
              UPDATE session_human_input_requests request_row
              SET status = 'cancelled', response = '{"outcome":"cancelled"}'::jsonb,
                responded_by = actor_subject, responded_at = now_value,
                updated_at = now_value
              WHERE request_row.account_id = account_id_value
                AND request_row.workspace_id = workspace_id_value
                AND request_row.session_id = cancelled_turn.session_id
                AND request_row.turn_id = cancelled_turn.id
                AND request_row.status = 'pending'
              RETURNING request_row.id, request_row.creation_attempt_id
            LOOP
              cancelled_sequence := cancelled_sequence + 1;
              INSERT INTO session_events (
                account_id, workspace_id, session_id, sequence, type, payload,
                payload_codec_version, turn_id, turn_generation,
                turn_attempt_id, turn_association, occurred_at
              ) VALUES (
                account_id_value, workspace_id_value, cancelled_turn.session_id,
                cancelled_sequence, 'user.humanInputResponse',
                pg_catalog.jsonb_build_object(
                  'requestId', cancelled_request.id,
                  'response', pg_catalog.jsonb_build_object('outcome', 'cancelled')
                ), 1, cancelled_turn.id, cancelled_turn.execution_generation,
                cancelled_request.creation_attempt_id, cancelled_association, now_value
              );
            END LOOP;
            SELECT
              pg_catalog.array_agg(
                update_row.id ORDER BY update_row.created_at, update_row.id
              ),
              (pg_catalog.array_agg(
                update_row.delivered_history_item_id
                ORDER BY update_row.created_at, update_row.id
              ))[1]
            INTO settled_update_ids, settled_history_item_id
            FROM session_system_updates update_row
            WHERE update_row.account_id = account_id_value
              AND update_row.workspace_id = workspace_id_value
              AND update_row.session_id = cancelled_turn.session_id
              AND update_row.delivered_turn_id = cancelled_turn.id
              AND update_row.state = 'delivered';
            IF COALESCE(pg_catalog.array_length(settled_update_ids, 1), 0) > 0
              AND NOT EXISTS (
                SELECT 1 FROM session_events prior_settlement
                WHERE prior_settlement.account_id = account_id_value
                  AND prior_settlement.workspace_id = workspace_id_value
                  AND prior_settlement.session_id = cancelled_turn.session_id
                  AND prior_settlement.turn_id = cancelled_turn.id
                  AND prior_settlement.type = 'system.update.settled'
              )
            THEN
              cancelled_sequence := cancelled_sequence + 1;
              INSERT INTO session_events (
                account_id, workspace_id, session_id, sequence, type, payload,
                payload_codec_version, turn_id, turn_generation,
                turn_association, occurred_at
              ) VALUES (
                account_id_value, workspace_id_value, cancelled_turn.session_id,
                cancelled_sequence, 'system.update.settled',
                pg_catalog.jsonb_build_object(
                  'updateIds', pg_catalog.to_jsonb(settled_update_ids),
                  'count', pg_catalog.array_length(settled_update_ids, 1),
                  'historyItemId', settled_history_item_id,
                  'outcome', 'cancelled'
                ), 1, cancelled_turn.id, cancelled_turn.execution_generation,
                cancelled_association, now_value
              );
            END IF;
            IF NOT EXISTS (
              SELECT 1 FROM session_events prior_cancel
              WHERE prior_cancel.account_id = account_id_value
                AND prior_cancel.workspace_id = workspace_id_value
                AND prior_cancel.session_id = cancelled_turn.session_id
                AND prior_cancel.turn_id = cancelled_turn.id
                AND prior_cancel.type = 'turn.cancelled'
            ) THEN
              cancelled_sequence := cancelled_sequence + 1;
              INSERT INTO session_events (
                account_id, workspace_id, session_id, sequence, type, payload,
                payload_codec_version, turn_id, turn_generation,
                turn_association, occurred_at
              ) VALUES (
                account_id_value, workspace_id_value, cancelled_turn.session_id,
                cancelled_sequence, 'turn.cancelled',
                pg_catalog.jsonb_build_object('reason', 'authority_changed'),
                1, cancelled_turn.id, cancelled_turn.execution_generation,
                cancelled_association, now_value
              );
            END IF;
            UPDATE sessions affected
            SET last_sequence = cancelled_sequence, updated_at = now_value
            WHERE affected.account_id = account_id_value
              AND affected.workspace_id = workspace_id_value
              AND affected.id = cancelled_turn.session_id;
          END LOOP;
          UPDATE interaction_interventions intervention
          SET status = 'cancelled', response_actor_subject_id = actor_subject,
            version = intervention.version + 1, settled_at = now_value,
            updated_at = now_value
          WHERE intervention.account_id = account_id_value
            AND intervention.workspace_id = workspace_id_value
            AND intervention.originating_turn_id = ANY(cancelled_turn_ids)
            AND intervention.status = 'open';
          DELETE FROM agent_run_states run_state
          WHERE run_state.account_id = account_id_value
            AND run_state.workspace_id = workspace_id_value
            AND run_state.turn_id = ANY(cancelled_turn_ids);
          UPDATE codex_capacity_waiters waiter
          SET status = 'superseded', observed_wake_revision = waiter.wake_revision,
            last_wake_reason = 'organization_membership_' || action_name,
            updated_at = now_value
          WHERE waiter.account_id = account_id_value
            AND waiter.workspace_id = workspace_id_value
            AND waiter.blocked_turn_id = ANY(cancelled_turn_ids)
            AND waiter.status = 'waiting';
          UPDATE xai_capacity_waiters waiter
          SET status = 'superseded', observed_wake_revision = waiter.wake_revision,
            last_wake_reason = 'organization_membership_' || action_name,
            updated_at = now_value
          WHERE waiter.account_id = account_id_value
            AND waiter.workspace_id = workspace_id_value
            AND waiter.blocked_turn_id = ANY(cancelled_turn_ids)
            AND waiter.status = 'waiting';
          UPDATE session_realtime_connections connection
          SET state = 'closed', closed_at = now_value, updated_at = now_value
          WHERE connection.account_id = account_id_value
            AND connection.workspace_id = workspace_id_value
            AND connection.realtime_id = ANY(affected_realtime_ids)
            AND connection.state IN ('negotiating', 'ready', 'active');
          WITH ended AS (
            UPDATE session_realtime_modes realtime
            SET state = 'ended', version = realtime.version + 1,
              ended_at = now_value, end_reason = 'authority_revoked',
              updated_at = now_value
            WHERE realtime.account_id = account_id_value
              AND realtime.workspace_id = workspace_id_value
              AND realtime.id = ANY(affected_realtime_ids)
              AND realtime.state = 'active'
            RETURNING realtime.id, realtime.session_id, realtime.operation_id,
              realtime.version, realtime.connection_epoch
          ), advanced AS (
            UPDATE sessions affected
            SET last_sequence = affected.last_sequence + 1, updated_at = now_value
            FROM ended
            WHERE affected.account_id = account_id_value
              AND affected.workspace_id = workspace_id_value
              AND affected.id = ended.session_id
            RETURNING affected.id AS session_id, affected.last_sequence,
              ended.id AS realtime_id, ended.operation_id,
              ended.version, ended.connection_epoch
          )
          INSERT INTO session_events (
            account_id, workspace_id, session_id, sequence, type, payload, occurred_at
          )
          SELECT account_id_value, workspace_id_value, advanced.session_id,
            advanced.last_sequence, 'session.realtime.ended',
            pg_catalog.jsonb_build_object(
              'realtimeId', advanced.realtime_id,
              'operationId', advanced.operation_id,
              'reason', 'authority_revoked',
              'version', advanced.version,
              'connectionEpoch', advanced.connection_epoch
            ), now_value
          FROM advanced;
          UPDATE sessions affected
          SET active_turn_id = CASE
                WHEN affected.active_turn_id = ANY(cancelled_turn_ids) THEN NULL
                ELSE affected.active_turn_id
              END,
            status = CASE
              WHEN affected.active_turn_id = ANY(cancelled_turn_ids) THEN
                CASE WHEN EXISTS (
                  SELECT 1 FROM session_turns queued
                  WHERE queued.account_id = affected.account_id
                    AND queued.workspace_id = affected.workspace_id
                    AND queued.session_id = affected.id
                    AND queued.status = 'queued'
                ) THEN 'queued' ELSE 'idle' END
              ELSE affected.status
            END,
            queue_head_position = COALESCE((
              SELECT min(queued.position)::bigint FROM session_turns queued
              WHERE queued.account_id = affected.account_id
                AND queued.workspace_id = affected.workspace_id
                AND queued.session_id = affected.id
                AND queued.status = 'queued'
            ), 0),
            queue_tail_position = COALESCE((
              SELECT max(queued.position)::bigint FROM session_turns queued
              WHERE queued.account_id = affected.account_id
                AND queued.workspace_id = affected.workspace_id
                AND queued.session_id = affected.id
                AND queued.status = 'queued'
            ), 0),
            queue_version = affected.queue_version + 1,
            updated_at = now_value
          WHERE affected.account_id = account_id_value
            AND affected.workspace_id = workspace_id_value
            AND EXISTS (
              SELECT 1 FROM session_turns cancelled
              WHERE cancelled.account_id = affected.account_id
                AND cancelled.workspace_id = affected.workspace_id
                AND cancelled.session_id = affected.id
                AND cancelled.id = ANY(cancelled_turn_ids)
            );
          UPDATE session_system_updates update_row SET state = 'cancelled'
          WHERE update_row.account_id = account_id_value
            AND update_row.workspace_id = workspace_id_value
            AND update_row.state = 'pending'
            AND EXISTS (
              SELECT 1 FROM sessions owned
              WHERE owned.id = update_row.session_id
                AND owned.owner_organization_membership_id = target.id
            );
          UPDATE session_system_update_outbox outbox
          SET status = 'failed', last_error = 'organization_membership_' || action_name,
            updated_at = now_value
          WHERE outbox.account_id = account_id_value
            AND outbox.workspace_id = workspace_id_value
            AND outbox.status = 'pending'
            AND EXISTS (
              SELECT 1 FROM sessions source_session
              WHERE source_session.id = outbox.source_session_id
                AND source_session.owner_organization_membership_id = target.id
            );
          UPDATE session_goals goal_row
          SET status = 'paused', paused_reason = 'api',
            rationale = CASE WHEN action_name = 'suspend'
              THEN 'Organization membership was suspended; explicit reauthorization is required.'
              ELSE 'Organization membership was revoked; explicit reauthorization is required.' END,
            version = goal_row.version + 1, updated_at = now_value
          WHERE goal_row.account_id = account_id_value
            AND goal_row.workspace_id = workspace_id_value
            AND goal_row.status = 'active'
            AND EXISTS (
              SELECT 1 FROM sessions owned
              WHERE owned.id = goal_row.session_id
                AND owned.owner_organization_membership_id = target.id
            );
          UPDATE scheduled_tasks task
          SET status = 'paused', personal_connection_delegations = '[]'::jsonb,
            authority_revision = task.authority_revision + 1,
            updated_at = now_value
          WHERE task.account_id = account_id_value
            AND task.workspace_id = workspace_id_value
            AND task.status = 'active'
            AND task.created_by_kind = 'subject'
            AND task.created_by_subject_id = target.subject_id;
          UPDATE organization_user_resource_grants grant_row
          SET status = 'revoked', revoked_at = now_value,
            generation = grant_row.generation + 1, updated_at = now_value
          WHERE grant_row.account_id = account_id_value
            AND grant_row.workspace_id = workspace_id_value
            AND grant_row.status = 'active'
            AND EXISTS (
              SELECT 1 FROM sessions owned
              WHERE owned.id = grant_row.session_id
                AND owned.owner_organization_membership_id = target.id
                AND owned.authority_epoch = grant_row.authority_epoch
            );
          WITH advanced AS (
            UPDATE sessions owned SET
              authority_epoch = owned.authority_epoch + 1,
              initial_personal_connection_delegations = '[]'::jsonb,
              last_sequence = owned.last_sequence + 1
            WHERE owned.account_id = account_id_value
              AND owned.workspace_id = workspace_id_value
              AND owned.owner_organization_membership_id = target.id
            RETURNING owned.id, owned.workspace_id, owned.last_sequence,
              owned.authority_epoch
          )
          INSERT INTO session_events (
            account_id, workspace_id, session_id, sequence, type, payload, occurred_at
          )
          SELECT account_id_value, advanced.workspace_id, advanced.id,
            advanced.last_sequence,
            CASE WHEN action_name = 'suspend'
              THEN 'session.authority.suspended' ELSE 'session.authority.revoked' END,
            pg_catalog.jsonb_build_object(
              'operationId', operation_id_value,
              'organizationMembershipId', target.id,
              'previousAuthorityEpoch', advanced.authority_epoch - 1,
              'authorityEpoch', advanced.authority_epoch
            ), now_value
          FROM advanced;
          INSERT INTO session_workflow_wake_outbox (
            session_id, account_id, workspace_id, temporal_workflow_id,
            reason, control_revision
          )
          SELECT affected.id, affected.account_id, affected.workspace_id,
            COALESCE(affected.temporal_workflow_id, 'session-' || affected.id::text),
            'organization_membership_' || action_name, 1
          FROM sessions affected
          WHERE affected.account_id = account_id_value
            AND affected.workspace_id = workspace_id_value
            AND affected.id = ANY(affected_session_ids)
          ON CONFLICT (session_id) DO UPDATE SET
            wake_revision = session_workflow_wake_outbox.wake_revision + 1,
            control_revision = session_workflow_wake_outbox.wake_revision + 1,
            temporal_workflow_id = EXCLUDED.temporal_workflow_id,
            reason = EXCLUDED.reason, attempts = 0,
            next_attempt_at = now_value, last_error = NULL,
            updated_at = now_value;
          PERFORM pg_catalog.set_config(
            'opengeni.session_activity_gate_state', 'preparing', true
          );
          SET CONSTRAINTS ALL IMMEDIATE;
          SET CONSTRAINTS sessions_activity_insert_commit_guard,
            sessions_activity_update_commit_guard DEFERRED;
          PERFORM pg_catalog.set_config(
            'opengeni.session_activity_gate_state', 'finalizing', true
          );
          UPDATE workspace_session_activity_revisions counter
          SET revision = counter.revision + 1
          WHERE counter.workspace_id = workspace_id_value
          RETURNING counter.revision INTO activity_revision_value;
          IF activity_revision_value IS NULL THEN
            RAISE EXCEPTION 'organization membership session activity counter is unavailable'
              USING ERRCODE = '55000';
          END IF;
          UPDATE sessions affected
          SET activity_revision = activity_revision_value,
            activity_revision_pending_xid = NULL
          WHERE affected.account_id = account_id_value
            AND affected.workspace_id = workspace_id_value
            AND affected.activity_revision_pending_xid
              = pg_catalog.pg_current_xact_id()::text::bigint;
          SET CONSTRAINTS sessions_activity_insert_commit_guard,
            sessions_activity_update_commit_guard IMMEDIATE;
          SET CONSTRAINTS sessions_activity_insert_commit_guard,
            sessions_activity_update_commit_guard DEFERRED;
          PERFORM pg_catalog.set_config(
            'opengeni.session_activity_gate_state',
            COALESCE(previous_activity_gate_state, ''), true
          );
          PERFORM pg_catalog.set_config(
            'opengeni.session_activity_gate_workspace_id',
            COALESCE(previous_activity_gate_workspace, ''), true
          );
        END LOOP;
        DELETE FROM session_visibility_write_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id()
          AND capability.capability_id = visibility_capability_id;
        PERFORM pg_catalog.set_config(
          'opengeni.session_visibility_write_capability',
          coalesce(previous_visibility_capability, ''), true
        );
        UPDATE organization_memberships SET
          status = CASE WHEN action_name = 'suspend' THEN 'suspended' ELSE 'revoked' END,
          authorization_revision = authorization_revision + 1,
          revoked_at = CASE WHEN action_name = 'offboard' THEN now_value ELSE NULL END,
          personal_retention_until = CASE
            WHEN action_name = 'offboard' AND policy.mode = 'delete_after'
              THEN now_value + pg_catalog.make_interval(days => policy.retention_days)
            ELSE NULL
          END,
          updated_at = now_value
        WHERE id = target.id RETURNING * INTO target;
      END IF;
      result := opengeni_private.organization_membership_row_json(target);
    END IF;
  END IF;

  INSERT INTO organization_membership_operation_receipts (
    account_id, operation_id, action, input_hash, result
  ) VALUES (
    account_id_value, operation_id_value, action_name, input_hash_value, result
  );
  INSERT INTO organization_membership_lifecycle_events (
    account_id, operation_id, actor_membership_id, actor_service_subject, target_membership_id, kind,
    prior_authorization_revision, resulting_authorization_revision, reason
  ) VALUES (
    account_id_value, operation_id_value, actor.id, CASE WHEN service_authorized THEN actor_subject ELSE NULL END,
    CASE WHEN target.id IS NULL THEN NULL ELSE target.id END,
    action_name, expected_revision,
    CASE WHEN target.id IS NULL THEN NULL ELSE target.authorization_revision END,
    reason_value
  );
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', coalesce(previous_workspace, ''), true
  );
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', coalesce(previous_workspace, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_visibility_write_capability',
    coalesce(previous_visibility_capability, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_state',
    coalesce(previous_activity_gate_state, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_workspace_id',
    coalesce(previous_activity_gate_workspace, ''), true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION organization_membership_command_0263(p_command jsonb) IS 'Migration 0263 organization membership lifecycle body, wrapped by organization_membership_command since migration 0275. Takes the same advisory organization fence and managed_accounts FOR KEY SHARE as its wrapper; the advisory lock is transaction-scoped and re-grantable, so the nested acquisition is a no-op within one command transaction.';

CREATE FUNCTION organization_plan_seats_used(p_account_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE seats integer; previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Plan account scope mismatch' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  SELECT (SELECT count(*) FROM organization_memberships WHERE account_id = p_account_id
    AND subject_id LIKE 'user:%' AND status IN ('active','provisioning')) +
    (SELECT count(*) FROM organization_membership_invitations invitation
      WHERE invitation.account_id = p_account_id AND invitation.status = 'pending'
        AND invitation.expires_at > clock_timestamp()
        AND NOT EXISTS (SELECT 1 FROM organization_memberships membership
          WHERE membership.account_id = p_account_id AND membership.subject_id = invitation.target_subject_id
            AND membership.subject_id LIKE 'user:%' AND membership.status IN ('active','provisioning'))) INTO seats;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  RETURN seats;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  RAISE;
END $$;

CREATE FUNCTION organization_private_sessions_enabled(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT p_account_id IS NOT DISTINCT FROM
      nullif(current_setting('opengeni.account_id', true), '')::uuid
    AND NOT EXISTS (
      SELECT 1 FROM organization_private_session_settings setting
      WHERE setting.account_id = p_account_id AND NOT setting.enabled
    )
$$;

CREATE FUNCTION organization_recovery_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'organization recovery evidence is append-only' USING ERRCODE = '42501';
END
$$;

CREATE FUNCTION organization_recovery_assert_recent_reauth(p_fence jsonb, p_actor_subject text, p_auth_session_id text, p_auth_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  result := organization_recovery_resolve_recent_reauth(
    p_fence, p_actor_subject, p_auth_session_id, p_auth_user_id
  );
  IF result IS NULL THEN
    RAISE EXCEPTION 'recent reauthentication is required' USING ERRCODE = '42501';
  END IF;
  RETURN result;
END
$$;

CREATE FUNCTION organization_recovery_command(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  action_name text := p_command ->> 'action';
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  actor_auth_user_id text := p_command ->> 'actorAuthUserId';
  actor_auth_session_id text := p_command ->> 'actorAuthSessionId';
  command_operation_id uuid := nullif(p_command ->> 'operationId', '')::uuid;
  recovery_operation_id uuid := nullif(p_command ->> 'recoveryOperationId', '')::uuid;
  expected_policy_revision bigint := nullif(p_command ->> 'expectedPolicyRevision', '')::bigint;
  expected_operation_revision bigint := nullif(p_command ->> 'expectedOperationRevision', '')::bigint;
  fence jsonb := p_command -> 'actorFence';
  input_hash_value text;
  now_value timestamptz := pg_catalog.clock_timestamp();
  actor organization_memberships%ROWTYPE;
  actor_identity canonical_human_identities%ROWTYPE;
  actor_subject_row canonical_human_identity_subjects%ROWTYPE;
  receipt organization_recovery_command_receipts%ROWTYPE;
  head_row organization_recovery_policy_heads%ROWTYPE;
  policy_row organization_recovery_policies%ROWTYPE;
  operation_row organization_recovery_operations%ROWTYPE;
  target organization_memberships%ROWTYPE;
  target_identity canonical_human_identities%ROWTYPE;
  target_subject_row canonical_human_identity_subjects%ROWTYPE;
  custodian_row organization_recovery_custodians%ROWTYPE;
  current_acceptance_id uuid;
  recent_proof jsonb;
  custodian_ids uuid[];
  custodian_count integer;
  valid_acceptance_count integer;
  approvals_before integer;
  approvals_after integer;
  new_policy_id uuid;
  new_policy_revision bigint;
  target_membership_id uuid;
  batch_id_value uuid;
  journal_count integer;
  journal_digest text;
  result jsonb;
  item record;
  candidate_identity_id uuid;
  candidate_auth_user_id text;
  candidate_membership organization_memberships%ROWTYPE;
  previous_recovery_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
  previous_organization_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
  previous_canonical_marker text := pg_catalog.current_setting(
    'opengeni.canonical_human_identity_lifecycle', true
  );
BEGIN
  IF p_command IS NULL OR pg_catalog.jsonb_typeof(p_command) <> 'object'
    OR action_name NOT IN ('configure_policy', 'accept_custody', 'disable_policy',
      'start_operation', 'approve_operation', 'cancel_operation', 'execute_operation')
    OR account_id_value IS NULL OR actor_subject IS NULL OR actor_auth_user_id IS NULL
    OR actor_auth_session_id IS NULL
    OR actor_subject <> 'user:' || actor_auth_user_id OR command_operation_id IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
    OR fence IS NULL OR pg_catalog.jsonb_typeof(fence) <> 'object'
  THEN
    RAISE EXCEPTION 'organization recovery command authority is invalid'
      USING ERRCODE = '42501';
  END IF;

  -- First lock is always the selected browser actor's exact lease. The request id is
  -- deliberately excluded from the semantic receipt digest because a retry is
  -- served by a fresh request lease.
  PERFORM managed_auth_actor_mutation_fence(
    fence ->> 'authorityHash', nullif(fence ->> 'actorEpoch', '')::bigint,
    nullif(fence ->> 'requestId', '')::uuid
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  ));
  PERFORM 1 FROM managed_accounts account
  WHERE account.id = account_id_value FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = account_id_value AND membership.subject_id = actor_subject
  FOR UPDATE;
  IF NOT FOUND OR actor.status <> 'active' OR actor_subject NOT LIKE 'user:%' THEN
    RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO actor_subject_row FROM canonical_human_identity_subjects subject_row
  WHERE subject_row.auth_user_id = actor_auth_user_id AND subject_row.status = 'active'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO actor_identity FROM canonical_human_identities identity_row
  WHERE identity_row.id = actor_subject_row.identity_id FOR UPDATE;
  IF NOT FOUND OR actor_identity.status <> 'active' OR actor_identity.recovery_state <> 'ready' THEN
    RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
  END IF;

  input_hash_value := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
    (p_command - 'actorFence' - 'actorAuthSessionId')::text, 'UTF8'
  )), 'hex');
  SELECT * INTO receipt FROM organization_recovery_command_receipts candidate
  WHERE candidate.account_id = account_id_value
    AND candidate.operation_id = command_operation_id
  FOR UPDATE;
  IF FOUND THEN
    IF receipt.action IS DISTINCT FROM action_name
      OR receipt.input_hash IS DISTINCT FROM input_hash_value
    THEN
      RAISE EXCEPTION 'organization recovery operation id was reused with different input'
        USING ERRCODE = '23505';
    END IF;
    PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
      CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
    PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
      CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
    PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
      CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
    RETURN pg_catalog.jsonb_build_object('replay', true, 'overview', receipt.result);
  END IF;

  recent_proof := organization_recovery_assert_recent_reauth(
    fence, actor_subject, actor_auth_session_id, actor_auth_user_id
  );
  IF (recent_proof ->> 'canonicalIdentityId')::uuid <> actor_identity.id
    OR (recent_proof ->> 'identityRevision')::bigint <> actor_identity.identity_revision
    OR (recent_proof ->> 'authRevision')::bigint <> actor_identity.auth_revision
    OR (recent_proof ->> 'subjectRevision')::bigint <> actor_subject_row.revision
  THEN
    RAISE EXCEPTION 'recent reauthentication actor is stale' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO head_row FROM organization_recovery_policy_heads head
  WHERE head.account_id = account_id_value FOR UPDATE;

  IF action_name = 'configure_policy' THEN
    IF actor.role <> 'owner' THEN
      RAISE EXCEPTION 'active organization owner required' USING ERRCODE = '42501';
    END IF;
    IF (head_row.account_id IS NULL
      AND coalesce(expected_policy_revision, 0::bigint) <> 0::bigint)
      OR (head_row.account_id IS NOT NULL AND head_row.revision <> expected_policy_revision)
    THEN
      RAISE EXCEPTION 'organization recovery policy revision is stale' USING ERRCODE = '40001';
    END IF;
    IF pg_catalog.jsonb_typeof(p_command -> 'custodianMembershipIds') <> 'array' THEN
      RAISE EXCEPTION 'exactly three custodians are required' USING ERRCODE = '22023';
    END IF;
    SELECT pg_catalog.array_agg(value::uuid ORDER BY ordinality),
      pg_catalog.count(*)::integer
    INTO custodian_ids, custodian_count
    FROM pg_catalog.jsonb_array_elements_text(p_command -> 'custodianMembershipIds')
      WITH ORDINALITY candidate(value, ordinality);
    IF custodian_count <> 3
      OR (SELECT pg_catalog.count(DISTINCT id) FROM pg_catalog.unnest(custodian_ids) id) <> 3
      OR actor.id = ANY(custodian_ids)
    THEN
      RAISE EXCEPTION 'exactly three distinct non-owner custodians are required'
        USING ERRCODE = '22023';
    END IF;
    PERFORM 1 FROM organization_memberships membership
    WHERE membership.account_id = account_id_value AND membership.id = ANY(custodian_ids)
    ORDER BY membership.id FOR UPDATE;
    SELECT pg_catalog.count(*)::integer, pg_catalog.count(DISTINCT subject_row.identity_id)::integer
    INTO custodian_count, valid_acceptance_count
    FROM organization_memberships membership
    INNER JOIN canonical_human_identity_subjects subject_row
      ON membership.subject_id = 'user:' || subject_row.auth_user_id
     AND subject_row.status = 'active'
    INNER JOIN canonical_human_identities identity_row
      ON identity_row.id = subject_row.identity_id
     AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
    WHERE membership.account_id = account_id_value AND membership.id = ANY(custodian_ids)
      AND membership.status = 'active' AND membership.role <> 'owner';
    IF custodian_count <> 3 OR valid_acceptance_count <> 3 THEN
      RAISE EXCEPTION 'custodians must be distinct active non-owner canonical humans'
        USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM canonical_human_identities identity_row
    WHERE identity_row.id IN (
      SELECT subject_row.identity_id
      FROM organization_memberships membership
      INNER JOIN canonical_human_identity_subjects subject_row
        ON membership.subject_id = 'user:' || subject_row.auth_user_id
      WHERE membership.account_id = account_id_value AND membership.id = ANY(custodian_ids)
    ) ORDER BY identity_row.id FOR UPDATE;

    new_policy_id := gen_random_uuid();
    new_policy_revision := coalesce(head_row.revision, 0::bigint) + 1::bigint;
    INSERT INTO organization_recovery_policies (
      id, account_id, revision, configured_by_membership_id, configured_by_identity_id
    ) VALUES (
      new_policy_id, account_id_value, new_policy_revision, actor.id, actor_identity.id
    );
    FOR item IN
      SELECT id, ordinality::integer AS ordinal
      FROM pg_catalog.unnest(custodian_ids) WITH ORDINALITY candidate(id, ordinality)
      ORDER BY ordinality
    LOOP
      SELECT * INTO candidate_membership
      FROM organization_memberships membership
      WHERE membership.account_id = account_id_value AND membership.id = item.id;
      SELECT subject_row.identity_id, subject_row.auth_user_id
      INTO candidate_identity_id, candidate_auth_user_id
      FROM canonical_human_identity_subjects subject_row
      WHERE candidate_membership.subject_id = 'user:' || subject_row.auth_user_id
        AND subject_row.status = 'active';
      INSERT INTO organization_recovery_custodians (
        account_id, policy_id, ordinal, membership_id, canonical_identity_id
      ) VALUES (
        account_id_value, new_policy_id, item.ordinal,
        candidate_membership.id, candidate_identity_id
      );
    END LOOP;
    WITH superseded AS (
      UPDATE organization_recovery_operations SET
        state = 'superseded', superseded_at = now_value,
        revision = revision + 1, updated_at = now_value
      WHERE account_id = account_id_value AND state IN ('collecting', 'cooling')
      RETURNING account_id, policy_id, id, revision
    )
    INSERT INTO organization_recovery_events (
      account_id, policy_id, operation_id, command_operation_id, event_type,
      actor_membership_id, actor_identity_id, event_revision, evidence
    ) SELECT
      superseded.account_id, superseded.policy_id, superseded.id, command_operation_id,
      'operation_superseded', actor.id, actor_identity.id, superseded.revision,
      pg_catalog.jsonb_build_object('reason', 'policy_rotated')
    FROM superseded;
    INSERT INTO organization_recovery_policy_heads (
      account_id, current_policy_id, revision, enabled, activated_at, updated_at
    ) VALUES (
      account_id_value, new_policy_id, new_policy_revision, true, NULL, now_value
    ) ON CONFLICT (account_id) DO UPDATE SET
      current_policy_id = EXCLUDED.current_policy_id,
      revision = EXCLUDED.revision, enabled = true,
      activated_at = NULL, updated_at = EXCLUDED.updated_at;
    INSERT INTO organization_recovery_events (
      account_id, policy_id, command_operation_id, event_type,
      actor_membership_id, actor_identity_id, event_revision,
      evidence
    ) VALUES (
      account_id_value, new_policy_id, command_operation_id, 'policy_configured',
      actor.id, actor_identity.id, new_policy_revision,
      pg_catalog.jsonb_build_object('custodianCount', 3, 'priorPolicyId', head_row.current_policy_id)
    );

  ELSIF action_name = 'accept_custody' THEN
    IF head_row.account_id IS NULL OR NOT head_row.enabled THEN
      RAISE EXCEPTION 'organization recovery is unavailable' USING ERRCODE = '55000';
    END IF;
    SELECT * INTO policy_row FROM organization_recovery_policies policy
    WHERE policy.id = head_row.current_policy_id AND policy.account_id = account_id_value;
    IF policy_row.revision <> expected_policy_revision THEN
      RAISE EXCEPTION 'organization recovery policy revision is stale' USING ERRCODE = '40001';
    END IF;
    PERFORM organization_recovery_lock_policy_evidence(policy_row.id, NULL);
    SELECT * INTO custodian_row FROM organization_recovery_custodians custodian
    WHERE custodian.policy_id = policy_row.id
      AND custodian.membership_id = actor.id
      AND custodian.canonical_identity_id = actor_identity.id
    FOR UPDATE;
    IF NOT FOUND OR actor.role = 'owner' THEN
      RAISE EXCEPTION 'organization recovery is unavailable' USING ERRCODE = '42501';
    END IF;
    current_acceptance_id := organization_recovery_valid_acceptance_id(
      policy_row.id, actor_identity.id
    );
    IF current_acceptance_id IS NULL THEN
      INSERT INTO organization_recovery_custodian_acceptances (
        account_id, policy_id, custodian_id, membership_id, canonical_identity_id,
        auth_user_id, login_binding_id, membership_authorization_revision,
        identity_revision, auth_revision, subject_revision, login_binding_revision,
        reauth_operation_id, accepted_at
      ) VALUES (
        account_id_value, policy_row.id, custodian_row.id, actor.id, actor_identity.id,
        actor_auth_user_id, (recent_proof ->> 'loginBindingId')::uuid,
        actor.authorization_revision, actor_identity.identity_revision,
        actor_identity.auth_revision, actor_subject_row.revision,
        (recent_proof ->> 'loginBindingRevision')::bigint,
        (recent_proof ->> 'reauthOperationId')::uuid, now_value
      ) RETURNING id INTO current_acceptance_id;
      INSERT INTO organization_recovery_events (
        account_id, policy_id, command_operation_id, event_type,
        actor_membership_id, actor_identity_id, event_revision
      ) VALUES (
        account_id_value, policy_row.id, command_operation_id, 'custody_accepted',
        actor.id, actor_identity.id, policy_row.revision
      );
    END IF;
    SELECT pg_catalog.count(*)::integer INTO valid_acceptance_count
    FROM organization_recovery_custodians custodian
    WHERE custodian.policy_id = policy_row.id
      AND organization_recovery_valid_acceptance_id(
        custodian.policy_id, custodian.canonical_identity_id
      ) IS NOT NULL;
    IF valid_acceptance_count = 3 AND head_row.activated_at IS NULL THEN
      UPDATE organization_recovery_policy_heads SET
        activated_at = now_value, updated_at = now_value
      WHERE account_id = account_id_value AND current_policy_id = policy_row.id;
      INSERT INTO organization_recovery_events (
        account_id, policy_id, command_operation_id, event_type,
        actor_membership_id, actor_identity_id, event_revision
      ) VALUES (
        account_id_value, policy_row.id, command_operation_id, 'policy_activated',
        actor.id, actor_identity.id, policy_row.revision
      );
    END IF;

  ELSIF action_name = 'disable_policy' THEN
    IF actor.role <> 'owner' OR head_row.account_id IS NULL OR NOT head_row.enabled THEN
      RAISE EXCEPTION 'active organization owner required' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO policy_row FROM organization_recovery_policies policy
    WHERE policy.id = head_row.current_policy_id AND policy.account_id = account_id_value;
    IF head_row.revision <> expected_policy_revision THEN
      RAISE EXCEPTION 'organization recovery policy revision is stale' USING ERRCODE = '40001';
    END IF;
    UPDATE organization_recovery_policy_heads SET
      enabled = false, revision = revision + 1, updated_at = now_value
    WHERE account_id = account_id_value;
    WITH superseded AS (
      UPDATE organization_recovery_operations SET
        state = 'superseded', superseded_at = now_value,
        revision = revision + 1, updated_at = now_value
      WHERE account_id = account_id_value AND state IN ('collecting', 'cooling')
      RETURNING account_id, policy_id, id, revision
    )
    INSERT INTO organization_recovery_events (
      account_id, policy_id, operation_id, command_operation_id, event_type,
      actor_membership_id, actor_identity_id, event_revision, evidence
    ) SELECT
      superseded.account_id, superseded.policy_id, superseded.id, command_operation_id,
      'operation_superseded', actor.id, actor_identity.id, superseded.revision,
      pg_catalog.jsonb_build_object('reason', 'policy_disabled')
    FROM superseded;
    INSERT INTO organization_recovery_events (
      account_id, policy_id, command_operation_id, event_type,
      actor_membership_id, actor_identity_id, event_revision
    ) VALUES (
      account_id_value, policy_row.id, command_operation_id, 'policy_disabled',
      actor.id, actor_identity.id, policy_row.revision
    );

  ELSIF action_name = 'start_operation' THEN
    IF head_row.account_id IS NULL OR NOT head_row.enabled THEN
      RAISE EXCEPTION 'organization recovery is unavailable' USING ERRCODE = '55000';
    END IF;
    recovery_operation_id := coalesce(recovery_operation_id, gen_random_uuid());
    SELECT * INTO policy_row FROM organization_recovery_policies policy
    WHERE policy.id = head_row.current_policy_id AND policy.account_id = account_id_value;
    IF policy_row.revision <> expected_policy_revision THEN
      RAISE EXCEPTION 'organization recovery policy revision is stale' USING ERRCODE = '40001';
    END IF;
    PERFORM organization_recovery_lock_policy_evidence(policy_row.id, NULL);
    SELECT pg_catalog.count(*)::integer INTO valid_acceptance_count
    FROM organization_recovery_custodians custodian
    WHERE custodian.policy_id = policy_row.id
      AND organization_recovery_valid_acceptance_id(
        custodian.policy_id, custodian.canonical_identity_id
      ) IS NOT NULL;
    SELECT * INTO custodian_row FROM organization_recovery_custodians custodian
    WHERE custodian.policy_id = policy_row.id
      AND custodian.membership_id = actor.id
      AND custodian.canonical_identity_id = actor_identity.id
    FOR UPDATE;
    current_acceptance_id := organization_recovery_valid_acceptance_id(
      policy_row.id, actor_identity.id
    );
    IF valid_acceptance_count <> 3 OR custodian_row.id IS NULL OR current_acceptance_id IS NULL THEN
      RAISE EXCEPTION 'organization recovery is unavailable' USING ERRCODE = '55000';
    END IF;
    WITH expired AS (
      UPDATE organization_recovery_operations SET
        state = 'expired', revision = revision + 1, updated_at = now_value
      WHERE account_id = account_id_value AND state IN ('collecting', 'cooling')
        AND expires_at <= now_value
      RETURNING account_id, policy_id, id, revision
    )
    INSERT INTO organization_recovery_events (
      account_id, policy_id, operation_id, command_operation_id, event_type,
      actor_membership_id, actor_identity_id, event_revision
    ) SELECT
      expired.account_id, expired.policy_id, expired.id, command_operation_id,
      'operation_expired', actor.id, actor_identity.id, expired.revision
    FROM expired;
    IF EXISTS (
      SELECT 1 FROM organization_recovery_operations operation
      WHERE operation.account_id = account_id_value
        AND operation.state IN ('collecting', 'cooling')
    ) THEN
      RAISE EXCEPTION 'an organization recovery operation is already active'
        USING ERRCODE = '55000';
    END IF;
    target_membership_id := nullif(p_command ->> 'targetMembershipId', '')::uuid;
    SELECT * INTO target FROM organization_memberships membership
    WHERE membership.account_id = account_id_value AND membership.id = target_membership_id
    FOR UPDATE;
    IF NOT FOUND OR target.status <> 'active' OR target.role = 'owner'
      OR target.subject_id NOT LIKE 'user:%'
    THEN
      RAISE EXCEPTION 'organization recovery target is unavailable' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO target_subject_row FROM canonical_human_identity_subjects subject_row
    WHERE subject_row.auth_user_id = pg_catalog.substr(target.subject_id, 6)
      AND subject_row.status = 'active' FOR UPDATE;
    SELECT * INTO target_identity FROM canonical_human_identities identity_row
    WHERE identity_row.id = target_subject_row.identity_id FOR UPDATE;
    IF target_subject_row.identity_id IS NULL OR target_identity.status <> 'active'
      OR target_identity.recovery_state <> 'ready'
    THEN
      RAISE EXCEPTION 'organization recovery target is unavailable' USING ERRCODE = '42501';
    END IF;
    INSERT INTO organization_recovery_operations (
      id, account_id, policy_id, policy_revision, target_membership_id,
      target_identity_id, target_auth_user_id, target_membership_authorization_revision,
      target_identity_revision, target_auth_revision, target_subject_revision,
      started_by_custodian_id, started_by_identity_id, expires_at, created_at, updated_at
    ) VALUES (
      recovery_operation_id, account_id_value, policy_row.id, policy_row.revision,
      target.id, target_identity.id, target_subject_row.auth_user_id,
      target.authorization_revision, target_identity.identity_revision,
      target_identity.auth_revision, target_subject_row.revision,
      custodian_row.id, actor_identity.id, now_value + interval '30 days', now_value, now_value
    ) RETURNING * INTO operation_row;
    INSERT INTO organization_recovery_events (
      account_id, policy_id, operation_id, command_operation_id, event_type,
      actor_membership_id, actor_identity_id, event_revision,
      evidence
    ) VALUES (
      account_id_value, policy_row.id, operation_row.id, command_operation_id,
      'operation_started', actor.id, actor_identity.id, operation_row.revision,
      pg_catalog.jsonb_build_object('targetMembershipId', target.id::text)
    );

  ELSIF action_name IN ('approve_operation', 'cancel_operation', 'execute_operation') THEN
    IF recovery_operation_id IS NULL THEN
      RAISE EXCEPTION 'organization recovery operation is unavailable' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO operation_row FROM organization_recovery_operations operation
    WHERE operation.id = recovery_operation_id AND operation.account_id = account_id_value
    FOR UPDATE;
    IF NOT FOUND OR operation_row.revision <> expected_operation_revision THEN
      RAISE EXCEPTION 'organization recovery operation revision is stale' USING ERRCODE = '40001';
    END IF;
    IF operation_row.state NOT IN ('collecting', 'cooling')
      OR operation_row.expires_at <= now_value
    THEN
      RAISE EXCEPTION 'organization recovery operation is unavailable' USING ERRCODE = '55000';
    END IF;
    IF head_row.account_id IS NULL OR NOT head_row.enabled
      OR head_row.current_policy_id <> operation_row.policy_id
    THEN
      RAISE EXCEPTION 'organization recovery is unavailable' USING ERRCODE = '55000';
    END IF;
    SELECT * INTO policy_row FROM organization_recovery_policies policy
    WHERE policy.id = operation_row.policy_id AND policy.account_id = account_id_value;

    IF action_name = 'cancel_operation' THEN
      IF actor.role <> 'owner' THEN
        RAISE EXCEPTION 'active organization owner required' USING ERRCODE = '42501';
      END IF;
      UPDATE organization_recovery_operations SET
        state = 'cancelled', cancelled_at = now_value,
        revision = revision + 1, updated_at = now_value
      WHERE id = operation_row.id RETURNING * INTO operation_row;
      INSERT INTO organization_recovery_events (
        account_id, policy_id, operation_id, command_operation_id, event_type,
        actor_membership_id, actor_identity_id, event_revision
      ) VALUES (
        account_id_value, policy_row.id, operation_row.id, command_operation_id,
        'operation_cancelled', actor.id, actor_identity.id, operation_row.revision
      );

    ELSE
      PERFORM organization_recovery_lock_policy_evidence(
        policy_row.id, operation_row.id
      );
      SELECT pg_catalog.count(*)::integer INTO valid_acceptance_count
      FROM organization_recovery_custodians custodian
      WHERE custodian.policy_id = policy_row.id
        AND organization_recovery_valid_acceptance_id(
          custodian.policy_id, custodian.canonical_identity_id
        ) IS NOT NULL;
      IF valid_acceptance_count <> 3 THEN
        RAISE EXCEPTION 'organization recovery is unavailable' USING ERRCODE = '55000';
      END IF;
      SELECT * INTO custodian_row FROM organization_recovery_custodians custodian
      WHERE custodian.policy_id = policy_row.id
        AND custodian.membership_id = actor.id
        AND custodian.canonical_identity_id = actor_identity.id
      FOR UPDATE;
      current_acceptance_id := organization_recovery_valid_acceptance_id(
        policy_row.id, actor_identity.id
      );
      IF custodian_row.id IS NULL OR current_acceptance_id IS NULL
        OR operation_row.target_identity_id = actor_identity.id OR actor.role = 'owner'
      THEN
        RAISE EXCEPTION 'organization recovery approval authority is invalid'
          USING ERRCODE = '42501';
      END IF;

      IF action_name = 'approve_operation' THEN
        approvals_before := organization_recovery_valid_approval_count(operation_row.id);
        IF NOT EXISTS (
          SELECT 1 FROM organization_recovery_approvals approval
          WHERE approval.operation_id = operation_row.id
            AND approval.canonical_identity_id = actor_identity.id
            AND approval.membership_authorization_revision = actor.authorization_revision
            AND approval.identity_revision = actor_identity.identity_revision
            AND approval.auth_revision = actor_identity.auth_revision
            AND approval.subject_revision = actor_subject_row.revision
            AND approval.custodian_acceptance_id = current_acceptance_id
        ) THEN
          INSERT INTO organization_recovery_approvals (
            account_id, operation_id, operation_revision, policy_id, custodian_id,
            membership_id, canonical_identity_id, auth_user_id, login_binding_id,
            membership_authorization_revision, identity_revision, auth_revision,
            subject_revision, login_binding_revision, custodian_acceptance_id,
            reauth_operation_id, approved_at
          ) VALUES (
            account_id_value, operation_row.id, operation_row.revision,
            policy_row.id, custodian_row.id, actor.id, actor_identity.id,
            actor_auth_user_id, (recent_proof ->> 'loginBindingId')::uuid,
            actor.authorization_revision, actor_identity.identity_revision,
            actor_identity.auth_revision, actor_subject_row.revision,
            (recent_proof ->> 'loginBindingRevision')::bigint,
            current_acceptance_id, (recent_proof ->> 'reauthOperationId')::uuid, now_value
          );
          approvals_after := organization_recovery_valid_approval_count(operation_row.id);
          UPDATE organization_recovery_operations SET
            revision = revision + 1, updated_at = now_value
          WHERE id = operation_row.id RETURNING * INTO operation_row;
          INSERT INTO organization_recovery_events (
            account_id, policy_id, operation_id, command_operation_id, event_type,
            actor_membership_id, actor_identity_id, event_revision
          ) VALUES (
            account_id_value, policy_row.id, operation_row.id, command_operation_id,
            'operation_approved', actor.id, actor_identity.id, operation_row.revision
          );

          IF approvals_before < 2 AND approvals_after >= 2 THEN
            batch_id_value := gen_random_uuid();
            WITH raw_recipients AS (
              SELECT membership.id AS membership_id, subject_row.identity_id, 'owner'::text AS audience
              FROM organization_memberships membership
              INNER JOIN canonical_human_identity_subjects subject_row
                ON membership.subject_id = 'user:' || subject_row.auth_user_id
               AND subject_row.status = 'active'
              INNER JOIN canonical_human_identities identity_row
                ON identity_row.id = subject_row.identity_id
               AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
              WHERE membership.account_id = account_id_value
                AND membership.status = 'active' AND membership.role = 'owner'
              UNION ALL
              SELECT custodian.membership_id, custodian.canonical_identity_id, 'custodian'::text
              FROM organization_recovery_custodians custodian
              WHERE custodian.policy_id = policy_row.id
              UNION ALL
              SELECT operation_row.target_membership_id, operation_row.target_identity_id,
                'target'::text
            ), recipients AS (
              SELECT pg_catalog.min(membership_id::text)::uuid AS membership_id,
                identity_id,
                pg_catalog.string_agg(DISTINCT audience, ',' ORDER BY audience) AS audience
              FROM raw_recipients GROUP BY identity_id
            ), payloads AS (
              SELECT recipient.*,
                pg_catalog.jsonb_build_object(
                  'organizationId', account_id_value::text,
                  'operationId', operation_row.id::text,
                  'targetMembershipId', operation_row.target_membership_id::text,
                  'quorumAt', now_value,
                  'cooldownEndsAt', now_value + interval '7 days',
                  'authorityGained', 'organization_owner',
                  'existingOwnersPreserved', true,
                  'personalContentTransferred', false,
                  'workspaceTransferred', false,
                  'billingTransferred', false
                ) AS payload
              FROM recipients recipient
            )
            INSERT INTO organization_recovery_notification_outbox (
              account_id, policy_id, operation_id, batch_id,
              recipient_membership_id, recipient_identity_id, audience,
              notification_type, idempotency_key, payload_digest, payload, created_at
            ) SELECT
              account_id_value, policy_row.id, operation_row.id, batch_id_value,
              payload.membership_id, payload.identity_id, payload.audience,
              'recovery_quorum_started',
              'organization-recovery:' || operation_row.id::text || ':'
                || batch_id_value::text || ':' || payload.identity_id::text,
              pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                payload.payload::text, 'UTF8'
              )), 'hex'), payload.payload, now_value
            FROM payloads payload;
            SELECT pg_catalog.count(*)::integer,
              pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.string_agg(
                  outbox.id::text || ':' || outbox.payload_digest, ',' ORDER BY outbox.id
                ), 'UTF8'
              )), 'hex')
            INTO journal_count, journal_digest
            FROM organization_recovery_notification_outbox outbox
            WHERE outbox.operation_id = operation_row.id AND outbox.batch_id = batch_id_value;
            IF journal_count < 1 OR journal_digest IS NULL THEN
              RAISE EXCEPTION 'organization recovery notification journal is unavailable'
                USING ERRCODE = '55000';
            END IF;
            UPDATE organization_recovery_operations SET
              state = 'cooling', quorum_at = now_value,
              executable_at = now_value + interval '7 days',
              notification_batch_id = batch_id_value,
              notification_count = journal_count,
              notification_digest = journal_digest,
              revision = revision + 1, updated_at = now_value
            WHERE id = operation_row.id RETURNING * INTO operation_row;
            INSERT INTO organization_recovery_events (
              account_id, policy_id, operation_id, command_operation_id, event_type,
              actor_membership_id, actor_identity_id, event_revision,
              evidence
            ) VALUES (
              account_id_value, policy_row.id, operation_row.id, command_operation_id,
              'quorum_started', actor.id, actor_identity.id, operation_row.revision,
              pg_catalog.jsonb_build_object(
                'notificationBatchId', batch_id_value::text,
                'notificationCount', journal_count,
                'notificationDigest', journal_digest,
                'cooldownDays', 7
              )
            );
          END IF;
        END IF;

      ELSE
        -- Execute revalidates the complete policy, target, quorum, cooldown and
        -- exact immutable notification journal before the sole role update.
        approvals_after := organization_recovery_valid_approval_count(operation_row.id);
        IF valid_acceptance_count <> 3 OR approvals_after < 2
          OR operation_row.quorum_at IS NULL OR operation_row.executable_at > now_value
          OR NOT EXISTS (
            SELECT 1 FROM organization_recovery_approvals approval
            WHERE approval.operation_id = operation_row.id
              AND approval.canonical_identity_id = actor_identity.id
              AND approval.custodian_acceptance_id = current_acceptance_id
              AND approval.membership_authorization_revision = actor.authorization_revision
              AND approval.identity_revision = actor_identity.identity_revision
              AND approval.auth_revision = actor_identity.auth_revision
              AND approval.subject_revision = actor_subject_row.revision
          )
        THEN
          RAISE EXCEPTION 'organization recovery execution is unavailable'
            USING ERRCODE = '55000';
        END IF;
        SELECT * INTO target FROM organization_memberships membership
        WHERE membership.account_id = account_id_value
          AND membership.id = operation_row.target_membership_id
        FOR UPDATE;
        SELECT * INTO target_subject_row FROM canonical_human_identity_subjects subject_row
        WHERE subject_row.auth_user_id = operation_row.target_auth_user_id FOR UPDATE;
        SELECT * INTO target_identity FROM canonical_human_identities identity_row
        WHERE identity_row.id = operation_row.target_identity_id FOR UPDATE;
        IF target.id IS NULL OR target.status <> 'active' OR target.role = 'owner'
          OR target.authorization_revision <> operation_row.target_membership_authorization_revision
          OR target_subject_row.identity_id <> operation_row.target_identity_id
          OR target_subject_row.status <> 'active'
          OR target_subject_row.revision <> operation_row.target_subject_revision
          OR target_identity.status <> 'active' OR target_identity.recovery_state <> 'ready'
          OR target_identity.identity_revision <> operation_row.target_identity_revision
          OR target_identity.auth_revision <> operation_row.target_auth_revision
        THEN
          RAISE EXCEPTION 'organization recovery target is unavailable' USING ERRCODE = '55000';
        END IF;
        SELECT pg_catalog.count(*)::integer,
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            pg_catalog.string_agg(
              outbox.id::text || ':' || outbox.payload_digest, ',' ORDER BY outbox.id
            ), 'UTF8'
          )), 'hex')
        INTO journal_count, journal_digest
        FROM organization_recovery_notification_outbox outbox
        WHERE outbox.operation_id = operation_row.id
          AND outbox.batch_id = operation_row.notification_batch_id;
        IF journal_count IS DISTINCT FROM operation_row.notification_count
          OR journal_digest IS DISTINCT FROM operation_row.notification_digest
        THEN
          RAISE EXCEPTION 'organization recovery notification journal is invalid'
            USING ERRCODE = '55000';
        END IF;
        UPDATE organization_memberships SET
          role = 'owner', authorization_revision = authorization_revision + 1,
          updated_at = now_value
        WHERE id = target.id AND account_id = account_id_value
          AND authorization_revision = operation_row.target_membership_authorization_revision;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'organization recovery target revision is stale' USING ERRCODE = '40001';
        END IF;
        UPDATE organization_recovery_operations SET
          state = 'executed', executed_at = now_value,
          revision = revision + 1, updated_at = now_value
        WHERE id = operation_row.id AND state = 'cooling'
        RETURNING * INTO operation_row;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'organization recovery execution is unavailable'
            USING ERRCODE = '55000';
        END IF;
        INSERT INTO organization_recovery_events (
          account_id, policy_id, operation_id, command_operation_id, event_type,
          actor_membership_id, actor_identity_id, event_revision,
          evidence
        ) VALUES (
          account_id_value, policy_row.id, operation_row.id, command_operation_id,
          'operation_executed', actor.id, actor_identity.id, operation_row.revision,
          pg_catalog.jsonb_build_object(
            'promotedMembershipId', target.id::text,
            'authorityGained', 'organization_owner',
            'existingOwnersPreserved', true,
            'personalContentTransferred', false,
            'workspaceTransferred', false,
            'billingTransferred', false
          )
        );
      END IF;
    END IF;
  END IF;

  result := organization_recovery_overview_json(
    account_id_value, actor_subject,
    (recent_proof ->> 'reauthenticatedAt')::timestamptz
  );
  INSERT INTO organization_recovery_command_receipts (
    account_id, operation_id, action, actor_membership_id,
    actor_identity_id, input_hash, result, created_at
  ) VALUES (
    account_id_value, command_operation_id, action_name, actor.id,
    actor_identity.id, input_hash_value, result, now_value
  );
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  RETURN pg_catalog.jsonb_build_object('replay', false, 'overview', result);
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION organization_recovery_exactly_three_custodians() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  policy_id_value uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  previous_marker text := pg_catalog.current_setting('opengeni.organization_recovery_lifecycle', true);
BEGIN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  IF (SELECT pg_catalog.count(*) FROM organization_recovery_custodians custodian
      WHERE custodian.policy_id = policy_id_value) <> 3 THEN
    RAISE EXCEPTION 'an organization recovery policy must contain exactly three custodians'
      USING ERRCODE = '23514';
  END IF;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION organization_recovery_lock_policy_evidence(p_policy_id uuid, p_operation_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_policy_id IS NULL THEN
    RAISE EXCEPTION 'organization recovery policy is unavailable' USING ERRCODE = '55000';
  END IF;

  PERFORM 1
  FROM organization_memberships membership
  INNER JOIN organization_recovery_custodians custodian
    ON custodian.membership_id = membership.id
   AND custodian.account_id = membership.account_id
  WHERE custodian.policy_id = p_policy_id
  ORDER BY membership.id
  FOR UPDATE OF membership;

  PERFORM 1
  FROM canonical_human_identity_subjects subject_row
  INNER JOIN organization_memberships membership
    ON membership.subject_id = 'user:' || subject_row.auth_user_id
  INNER JOIN organization_recovery_custodians custodian
    ON custodian.membership_id = membership.id
   AND custodian.account_id = membership.account_id
   AND custodian.canonical_identity_id = subject_row.identity_id
  WHERE custodian.policy_id = p_policy_id
  ORDER BY subject_row.auth_user_id
  FOR UPDATE OF subject_row;

  PERFORM 1
  FROM canonical_human_identities identity_row
  INNER JOIN organization_recovery_custodians custodian
    ON custodian.canonical_identity_id = identity_row.id
  WHERE custodian.policy_id = p_policy_id
  ORDER BY identity_row.id
  FOR UPDATE OF identity_row;

  PERFORM 1
  FROM canonical_human_login_bindings binding
  WHERE binding.id IN (
    SELECT acceptance.login_binding_id
    FROM organization_recovery_custodian_acceptances acceptance
    WHERE acceptance.policy_id = p_policy_id
    UNION
    SELECT approval.login_binding_id
    FROM organization_recovery_approvals approval
    WHERE p_operation_id IS NOT NULL AND approval.operation_id = p_operation_id
  )
  ORDER BY binding.id
  FOR UPDATE OF binding;
END
$$;

CREATE FUNCTION organization_recovery_overview_json(p_account_id uuid, p_actor_subject text, p_recent_reauthentication_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  head_row organization_recovery_policy_heads%ROWTYPE;
  policy_row organization_recovery_policies%ROWTYPE;
  operation_row organization_recovery_operations%ROWTYPE;
  custodian_rows jsonb := '[]'::jsonb;
  eligible_member_rows jsonb := '[]'::jsonb;
  eligible_member_count integer := 0;
  valid_acceptances integer := 0;
  valid_approvals integer := 0;
  policy_state text;
  operation_state text;
  target_current boolean := false;
  target_name text;
  target_email text;
  approvals_rows jsonb := '[]'::jsonb;
  actor_membership organization_memberships%ROWTYPE;
  actor_subject_row canonical_human_identity_subjects%ROWTYPE;
  actor_identity canonical_human_identities%ROWTYPE;
  actor_is_custodian boolean := false;
  actor_has_acceptance boolean := false;
  actor_has_approval boolean := false;
  notification_journaled boolean := false;
  actual_notification_count integer := 0;
  actual_notification_digest text;
  capability_configure boolean := false;
  capability_accept boolean := false;
  capability_disable boolean := false;
  capability_start boolean := false;
  capability_approve boolean := false;
  capability_cancel boolean := false;
  capability_execute boolean := false;
  has_recent_reauthentication boolean := p_recent_reauthentication_at IS NOT NULL;
  now_value timestamptz := pg_catalog.clock_timestamp();
  previous_recovery_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
  previous_canonical_marker text := pg_catalog.current_setting(
    'opengeni.canonical_human_identity_lifecycle', true
  );
  previous_organization_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT * INTO actor_membership FROM organization_memberships membership
  WHERE membership.account_id = p_account_id AND membership.subject_id = p_actor_subject
    AND membership.status = 'active' FOR KEY SHARE;
  IF actor_membership.id IS NULL OR p_actor_subject NOT LIKE 'user:%' THEN
    RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
  END IF;
  IF p_actor_subject LIKE 'user:%' THEN
    SELECT * INTO actor_subject_row FROM canonical_human_identity_subjects subject_row
    WHERE subject_row.auth_user_id = pg_catalog.substr(p_actor_subject, 6)
      AND subject_row.status = 'active' FOR KEY SHARE;
    IF actor_subject_row.identity_id IS NOT NULL THEN
      SELECT * INTO actor_identity FROM canonical_human_identities identity_row
      WHERE identity_row.id = actor_subject_row.identity_id
        AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
      FOR KEY SHARE;
    END IF;
  END IF;
  capability_configure := has_recent_reauthentication
    AND actor_membership.role = 'owner' AND actor_identity.id IS NOT NULL;
  SELECT pg_catalog.count(*)::integer,
    coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'membershipId', membership.id::text,
        'name', auth_user.name,
        'email', auth_user.email
      ) ORDER BY lower(coalesce(auth_user.name, auth_user.email, membership.subject_id)),
        membership.id
    ), '[]'::jsonb)
  INTO eligible_member_count, eligible_member_rows
  FROM organization_memberships membership
  INNER JOIN canonical_human_identity_subjects subject_row
    ON membership.subject_id = 'user:' || subject_row.auth_user_id
   AND subject_row.status = 'active'
  INNER JOIN canonical_human_identities identity_row
    ON identity_row.id = subject_row.identity_id
   AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
  INNER JOIN auth_users auth_user ON auth_user.id = subject_row.auth_user_id
  WHERE membership.account_id = p_account_id
    AND membership.status = 'active' AND membership.role <> 'owner';
  IF eligible_member_count > 1000 THEN
    RAISE EXCEPTION 'organization recovery target inventory exceeds the bounded projection'
      USING ERRCODE = '54000';
  END IF;
  SELECT * INTO head_row FROM organization_recovery_policy_heads head
  WHERE head.account_id = p_account_id;
  IF NOT FOUND THEN
    IF actor_membership.role <> 'owner' THEN
      RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
      CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
    PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
      CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
    PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
      CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
    RETURN pg_catalog.jsonb_build_object(
      'organizationId', p_account_id::text, 'policy', NULL, 'operation', NULL,
      'availability', 'recovery_unavailable', 'unavailableReason', 'no_policy',
      'recentReauthenticationAt', p_recent_reauthentication_at,
      'eligibleMembers', eligible_member_rows,
      'capabilities', pg_catalog.jsonb_build_object(
        'configure', capability_configure, 'accept', false, 'disable', false,
        'start', false, 'approve', false, 'cancel', false, 'execute', false
      )
    );
  END IF;
  SELECT * INTO policy_row FROM organization_recovery_policies policy
  WHERE policy.id = head_row.current_policy_id AND policy.account_id = p_account_id;
  SELECT pg_catalog.count(*) FILTER (WHERE current_acceptance.id IS NOT NULL)::integer,
    coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'ordinal', custodian.ordinal,
        'membershipId', custodian.membership_id::text,
        'name', auth_user.name,
        'email', auth_user.email,
        'enrollmentState', CASE
          WHEN current_acceptance.id IS NOT NULL THEN 'accepted'
          WHEN current_eligibility.eligible THEN 'pending_acceptance'
          ELSE 'ineligible'
        END,
        'acceptedAt', current_acceptance.accepted_at
      ) ORDER BY custodian.ordinal
    ), '[]'::jsonb)
  INTO valid_acceptances, custodian_rows
  FROM organization_recovery_custodians custodian
  INNER JOIN organization_memberships membership
    ON membership.id = custodian.membership_id AND membership.account_id = custodian.account_id
  LEFT JOIN auth_users auth_user ON membership.subject_id = 'user:' || auth_user.id
  LEFT JOIN LATERAL (
    SELECT acceptance.id, acceptance.accepted_at
    FROM organization_recovery_custodian_acceptances acceptance
    WHERE acceptance.id = organization_recovery_valid_acceptance_id(
      custodian.policy_id, custodian.canonical_identity_id
    )
  ) current_acceptance ON true
  LEFT JOIN LATERAL (
    SELECT EXISTS (
      SELECT 1
      FROM canonical_human_identity_subjects subject_row
      INNER JOIN canonical_human_identities identity_row
        ON identity_row.id = subject_row.identity_id
      WHERE membership.subject_id = 'user:' || subject_row.auth_user_id
        AND subject_row.identity_id = custodian.canonical_identity_id
        AND subject_row.status = 'active'
        AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
        AND membership.status = 'active' AND membership.role <> 'owner'
    ) AS eligible
  ) current_eligibility ON true
  WHERE custodian.policy_id = policy_row.id;
  policy_state := CASE
    WHEN NOT head_row.enabled THEN 'disabled'
    WHEN valid_acceptances = 3 THEN 'active'
    WHEN head_row.activated_at IS NULL THEN 'pending_acceptance'
    ELSE 'degraded'
  END;
  SELECT * INTO operation_row FROM organization_recovery_operations operation
  WHERE operation.account_id = p_account_id
  ORDER BY operation.created_at DESC, operation.id DESC LIMIT 1;
  IF FOUND THEN
    valid_approvals := organization_recovery_valid_approval_count(operation_row.id);
    approvals_rows := organization_recovery_valid_approvals_json(operation_row.id);
    SELECT auth_user.name, auth_user.email INTO target_name, target_email
    FROM auth_users auth_user WHERE auth_user.id = operation_row.target_auth_user_id;
    SELECT EXISTS (
      SELECT 1
      FROM organization_memberships membership
      INNER JOIN canonical_human_identity_subjects subject_row
        ON membership.subject_id = 'user:' || subject_row.auth_user_id
      INNER JOIN canonical_human_identities identity_row
        ON identity_row.id = subject_row.identity_id
      WHERE membership.id = operation_row.target_membership_id
        AND membership.account_id = operation_row.account_id
        AND membership.status = 'active' AND membership.role <> 'owner'
        AND membership.authorization_revision = operation_row.target_membership_authorization_revision
        AND subject_row.auth_user_id = operation_row.target_auth_user_id
        AND subject_row.identity_id = operation_row.target_identity_id
        AND subject_row.status = 'active'
        AND subject_row.revision = operation_row.target_subject_revision
        AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
        AND identity_row.identity_revision = operation_row.target_identity_revision
        AND identity_row.auth_revision = operation_row.target_auth_revision
    ) INTO target_current;
    operation_state := CASE
      WHEN operation_row.state IN ('executed', 'cancelled', 'superseded') THEN operation_row.state
      WHEN operation_row.expires_at <= now_value THEN 'expired'
      WHEN operation_row.policy_id <> head_row.current_policy_id OR NOT head_row.enabled
        THEN 'superseded'
      WHEN policy_state <> 'active' OR valid_approvals < 2 OR NOT target_current THEN 'collecting'
      ELSE 'cooling'
    END;
    IF operation_row.notification_batch_id IS NOT NULL THEN
      SELECT pg_catalog.count(*)::integer,
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
          pg_catalog.string_agg(
            outbox.id::text || ':' || outbox.payload_digest, ',' ORDER BY outbox.id
          ), 'UTF8'
        )), 'hex')
      INTO actual_notification_count, actual_notification_digest
      FROM organization_recovery_notification_outbox outbox
      WHERE outbox.operation_id = operation_row.id
        AND outbox.batch_id = operation_row.notification_batch_id;
      notification_journaled := actual_notification_count > 0
        AND actual_notification_count IS NOT DISTINCT FROM operation_row.notification_count
        AND actual_notification_digest IS NOT DISTINCT FROM operation_row.notification_digest;
    END IF;
  END IF;
  IF actor_identity.id IS NOT NULL THEN
    actor_is_custodian := EXISTS (
      SELECT 1 FROM organization_recovery_custodians custodian
      WHERE custodian.policy_id = policy_row.id
        AND custodian.membership_id = actor_membership.id
        AND custodian.canonical_identity_id = actor_identity.id
    );
    actor_has_acceptance := actor_is_custodian AND
      organization_recovery_valid_acceptance_id(policy_row.id, actor_identity.id) IS NOT NULL;
    actor_has_approval := operation_row.id IS NOT NULL AND EXISTS (
      SELECT 1 FROM pg_catalog.jsonb_array_elements(approvals_rows) approval
      WHERE approval ->> 'membershipId' = actor_membership.id::text
    );
  END IF;
  IF actor_membership.role <> 'owner' AND NOT actor_is_custodian THEN
    RAISE EXCEPTION 'organization recovery authority is invalid' USING ERRCODE = '42501';
  END IF;

  capability_accept := has_recent_reauthentication AND head_row.enabled AND actor_is_custodian
    AND actor_membership.role <> 'owner' AND actor_identity.id IS NOT NULL
    AND NOT actor_has_acceptance;
  capability_disable := has_recent_reauthentication
    AND actor_membership.role = 'owner' AND actor_identity.id IS NOT NULL
    AND head_row.enabled;
  capability_start := has_recent_reauthentication AND head_row.enabled AND policy_state = 'active'
    AND actor_is_custodian AND actor_has_acceptance
    AND actor_membership.role <> 'owner' AND actor_identity.id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM organization_recovery_operations live_operation
      WHERE live_operation.account_id = p_account_id
        AND live_operation.state IN ('collecting', 'cooling')
        AND live_operation.expires_at > now_value
    );
  capability_approve := has_recent_reauthentication AND operation_row.id IS NOT NULL
    AND operation_row.state IN ('collecting', 'cooling')
    AND operation_row.expires_at > now_value
    AND head_row.enabled AND policy_state = 'active' AND valid_acceptances = 3
    AND operation_row.policy_id = head_row.current_policy_id
    AND actor_is_custodian AND actor_has_acceptance
    AND actor_membership.role <> 'owner' AND actor_identity.id IS NOT NULL
    AND operation_row.target_identity_id <> actor_identity.id
    AND NOT actor_has_approval;
  capability_cancel := has_recent_reauthentication AND operation_row.id IS NOT NULL
    AND operation_row.state IN ('collecting', 'cooling')
    AND operation_row.expires_at > now_value
    AND head_row.enabled AND operation_row.policy_id = head_row.current_policy_id
    AND actor_membership.role = 'owner' AND actor_identity.id IS NOT NULL;
  capability_execute := has_recent_reauthentication AND operation_row.id IS NOT NULL
    AND operation_row.state = 'cooling' AND operation_state = 'cooling'
    AND operation_row.executable_at <= now_value AND operation_row.expires_at > now_value
    AND policy_state = 'active' AND valid_acceptances = 3 AND valid_approvals >= 2
    AND target_current AND notification_journaled
    AND actor_is_custodian AND actor_has_acceptance AND actor_has_approval
    AND actor_membership.role <> 'owner' AND actor_identity.id IS NOT NULL
    AND operation_row.target_identity_id <> actor_identity.id;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RETURN pg_catalog.jsonb_build_object(
    'organizationId', p_account_id::text,
    'availability', CASE
      WHEN policy_state = 'active' AND actor_identity.id IS NOT NULL
      THEN 'available' ELSE 'recovery_unavailable' END,
    'unavailableReason', CASE
      WHEN actor_identity.id IS NULL THEN 'identity_unavailable'
      WHEN policy_state = 'pending_acceptance' THEN 'pending_acceptance'
      WHEN policy_state = 'degraded' THEN 'degraded'
      WHEN policy_state = 'disabled' THEN 'disabled'
      ELSE NULL END,
    'recentReauthenticationAt', p_recent_reauthentication_at,
    'eligibleMembers', eligible_member_rows,
    'policy', pg_catalog.jsonb_build_object(
      'id', policy_row.id::text, 'organizationId', p_account_id::text,
      'revision', head_row.revision, 'state', policy_state,
      'custodians', custodian_rows
      , 'createdAt', policy_row.configured_at, 'updatedAt', head_row.updated_at
    ),
    'operation', CASE WHEN operation_row.id IS NULL THEN NULL ELSE pg_catalog.jsonb_build_object(
      'id', operation_row.id::text, 'organizationId', p_account_id::text,
      'policyId', operation_row.policy_id::text,
      'policyRevision', operation_row.policy_revision,
      'revision', operation_row.revision,
      'state', operation_state,
      'target', pg_catalog.jsonb_build_object(
        'membershipId', operation_row.target_membership_id::text,
        'name', target_name, 'email', target_email
      ),
      'approvalCount', valid_approvals,
      'approvals', approvals_rows,
      'quorumAt', operation_row.quorum_at,
      'executableAt', operation_row.executable_at,
      'expiresAt', operation_row.expires_at,
      'notificationJournaled', notification_journaled,
      'executedAt', operation_row.executed_at,
      'cancelledAt', operation_row.cancelled_at,
      'createdAt', operation_row.created_at,
      'updatedAt', operation_row.updated_at
    ) END,
    'capabilities', pg_catalog.jsonb_build_object(
      'configure', capability_configure, 'accept', capability_accept,
      'disable', capability_disable, 'start', capability_start,
      'approve', capability_approve, 'cancel', capability_cancel,
      'execute', capability_execute
    )
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION organization_recovery_resolve_recent_reauth(p_fence jsonb, p_actor_subject text, p_auth_session_id text, p_auth_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  authority_hash_value text := p_fence ->> 'authorityHash';
  actor_epoch_value bigint := nullif(p_fence ->> 'actorEpoch', '')::bigint;
  result jsonb;
  previous_managed_marker text := pg_catalog.current_setting(
    'opengeni.managed_auth_session_set_lifecycle', true
  );
  previous_canonical_marker text := pg_catalog.current_setting(
    'opengeni.canonical_human_identity_lifecycle', true
  );
BEGIN
  IF p_fence IS NULL OR pg_catalog.jsonb_typeof(p_fence) <> 'object'
    OR authority_hash_value !~ '^[0-9a-f]{64}$' OR actor_epoch_value < 1
    OR p_auth_session_id IS NULL OR p_auth_user_id IS NULL
    OR p_actor_subject <> 'user:' || p_auth_user_id
  THEN
    RETURN NULL;
  END IF;
  PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  SELECT pg_catalog.jsonb_build_object(
    'sessionSetId', session_set.id::text,
    'generation', session_set.generation::text,
    'actorEpoch', session_set.actor_epoch::text,
    'slotId', slot.id::text,
    'authSessionId', auth_session.id,
    'authUserId', auth_session.user_id,
    'canonicalIdentityId', identity_row.id::text,
    'identityRevision', identity_row.identity_revision::text,
    'authRevision', identity_row.auth_revision::text,
    'subjectRevision', subject_row.revision::text,
    'loginBindingId', binding.id::text,
    'loginBindingRevision', binding.revision::text,
    'reauthOperationId', operation.operation_id::text,
    'reauthenticatedAt', operation.created_at
  ) INTO result
  FROM managed_auth_session_sets session_set
  INNER JOIN managed_auth_browser_installations installation
    ON installation.id = session_set.installation_id
  INNER JOIN managed_auth_login_slots slot
    ON slot.id = session_set.selected_slot_id
   AND slot.session_set_id = session_set.id
  INNER JOIN auth_sessions auth_session
    ON auth_session.id = slot.auth_session_id
  INNER JOIN canonical_human_identity_subjects subject_row
    ON subject_row.auth_user_id = auth_session.user_id
   AND subject_row.identity_id = slot.identity_id
  INNER JOIN canonical_human_identities identity_row
    ON identity_row.id = slot.identity_id
  INNER JOIN canonical_human_login_bindings binding
    ON binding.id = slot.login_binding_id
   AND binding.identity_id = slot.identity_id
  INNER JOIN managed_auth_session_set_operations operation
    ON operation.session_set_id = session_set.id
  WHERE session_set.authority_hash = authority_hash_value
    AND session_set.actor_epoch = actor_epoch_value
    AND session_set.state = 'ready' AND session_set.revoked_at IS NULL
    AND session_set.idle_expires_at > pg_catalog.clock_timestamp()
    AND session_set.absolute_expires_at > pg_catalog.clock_timestamp()
    AND installation.revoked_at IS NULL
    AND installation.idle_expires_at > pg_catalog.clock_timestamp()
    AND installation.absolute_expires_at > pg_catalog.clock_timestamp()
    AND slot.status = 'active' AND slot.auth_session_id = p_auth_session_id
    AND slot.auth_user_id = p_auth_user_id
    AND auth_session.user_id = p_auth_user_id
    AND auth_session.expires_at > pg_catalog.clock_timestamp()
    AND auth_session.identity_id = slot.identity_id
    AND auth_session.identity_revision = slot.identity_revision
    AND auth_session.auth_revision = slot.auth_revision
    AND auth_session.login_binding_id = slot.login_binding_id
    AND auth_session.login_binding_revision = slot.login_binding_revision
    AND subject_row.status = 'active'
    AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
    AND identity_row.identity_revision = slot.identity_revision
    AND identity_row.auth_revision = slot.auth_revision
    AND binding.status = 'active' AND binding.revision = slot.login_binding_revision
    AND operation.operation_type = 'complete_reauth'
    AND operation.target_slot_id = session_set.selected_slot_id
    AND operation.result_generation = session_set.generation
    AND operation.result_actor_epoch = session_set.actor_epoch
    AND operation.outcome IN ('applied', 'converged')
    AND operation.created_at >= pg_catalog.clock_timestamp() - interval '10 minutes'
    AND operation.created_at <= pg_catalog.clock_timestamp()
  ORDER BY operation.created_at DESC, operation.operation_id DESC
  LIMIT 1;
  PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle',
    CASE WHEN previous_managed_marker IS NULL THEN '' ELSE previous_managed_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.managed_auth_session_set_lifecycle',
    CASE WHEN previous_managed_marker IS NULL THEN '' ELSE previous_managed_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  RAISE;
END
$_$;

CREATE FUNCTION organization_recovery_valid_acceptance_id(p_policy_id uuid, p_identity_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  acceptance_id_value uuid;
  previous_recovery_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
  previous_canonical_marker text := pg_catalog.current_setting(
    'opengeni.canonical_human_identity_lifecycle', true
  );
  previous_organization_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT acceptance.id INTO acceptance_id_value
  FROM organization_recovery_custodian_acceptances acceptance
  INNER JOIN organization_recovery_custodians custodian
    ON custodian.id = acceptance.custodian_id
   AND custodian.policy_id = acceptance.policy_id
   AND custodian.membership_id = acceptance.membership_id
   AND custodian.canonical_identity_id = acceptance.canonical_identity_id
  INNER JOIN organization_memberships membership
    ON membership.id = acceptance.membership_id
   AND membership.account_id = acceptance.account_id
  INNER JOIN canonical_human_identity_subjects subject_row
    ON subject_row.auth_user_id = acceptance.auth_user_id
   AND subject_row.identity_id = acceptance.canonical_identity_id
  INNER JOIN canonical_human_identities identity_row
    ON identity_row.id = acceptance.canonical_identity_id
  INNER JOIN canonical_human_login_bindings binding
    ON binding.id = acceptance.login_binding_id
   AND binding.identity_id = acceptance.canonical_identity_id
  WHERE acceptance.policy_id = p_policy_id
    AND acceptance.canonical_identity_id = p_identity_id
    AND membership.subject_id = 'user:' || acceptance.auth_user_id
    AND membership.status = 'active' AND membership.role <> 'owner'
    AND membership.authorization_revision = acceptance.membership_authorization_revision
    AND subject_row.status = 'active' AND subject_row.revision = acceptance.subject_revision
    AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
    AND identity_row.identity_revision = acceptance.identity_revision
    AND identity_row.auth_revision = acceptance.auth_revision
    AND binding.status = 'active' AND binding.revision = acceptance.login_binding_revision
  ORDER BY acceptance.accepted_at DESC, acceptance.id DESC
  LIMIT 1;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RETURN acceptance_id_value;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION organization_recovery_valid_approval_count(p_operation_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  approval_count integer;
  previous_recovery_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
  previous_canonical_marker text := pg_catalog.current_setting(
    'opengeni.canonical_human_identity_lifecycle', true
  );
  previous_organization_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT pg_catalog.count(DISTINCT approval.canonical_identity_id)::integer
  INTO approval_count
  FROM organization_recovery_approvals approval
  INNER JOIN organization_recovery_operations operation
    ON operation.id = approval.operation_id
   AND operation.account_id = approval.account_id
   AND operation.policy_id = approval.policy_id
  INNER JOIN organization_recovery_custodians custodian
    ON custodian.id = approval.custodian_id
   AND custodian.policy_id = approval.policy_id
   AND custodian.membership_id = approval.membership_id
   AND custodian.canonical_identity_id = approval.canonical_identity_id
  INNER JOIN organization_memberships membership
    ON membership.id = approval.membership_id
   AND membership.account_id = approval.account_id
  INNER JOIN canonical_human_identity_subjects subject_row
    ON subject_row.auth_user_id = approval.auth_user_id
   AND subject_row.identity_id = approval.canonical_identity_id
  INNER JOIN canonical_human_identities identity_row
    ON identity_row.id = approval.canonical_identity_id
  INNER JOIN canonical_human_login_bindings binding
    ON binding.id = approval.login_binding_id
   AND binding.identity_id = approval.canonical_identity_id
  WHERE approval.operation_id = p_operation_id
    AND approval.canonical_identity_id <> operation.target_identity_id
    AND membership.subject_id = 'user:' || approval.auth_user_id
    AND membership.status = 'active' AND membership.role <> 'owner'
    AND membership.authorization_revision = approval.membership_authorization_revision
    AND subject_row.status = 'active' AND subject_row.revision = approval.subject_revision
    AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
    AND identity_row.identity_revision = approval.identity_revision
    AND identity_row.auth_revision = approval.auth_revision
    AND binding.status = 'active' AND binding.revision = approval.login_binding_revision
    AND organization_recovery_valid_acceptance_id(
      approval.policy_id, approval.canonical_identity_id
    ) = approval.custodian_acceptance_id;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RETURN coalesce(approval_count, 0);
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION organization_recovery_valid_approvals_json(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  previous_recovery_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
  previous_canonical_marker text := pg_catalog.current_setting(
    'opengeni.canonical_human_identity_lifecycle', true
  );
  previous_organization_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
BEGIN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle', 'active', true);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  WITH current_approvals AS (
    SELECT DISTINCT ON (approval.canonical_identity_id)
      approval.membership_id, approval.canonical_identity_id, approval.approved_at, approval.id,
      auth_user.name, auth_user.email
    FROM organization_recovery_approvals approval
    INNER JOIN organization_recovery_operations operation
      ON operation.id = approval.operation_id
     AND operation.account_id = approval.account_id
     AND operation.policy_id = approval.policy_id
    INNER JOIN organization_recovery_custodians custodian
      ON custodian.id = approval.custodian_id
     AND custodian.policy_id = approval.policy_id
     AND custodian.membership_id = approval.membership_id
     AND custodian.canonical_identity_id = approval.canonical_identity_id
    INNER JOIN organization_memberships membership
      ON membership.id = approval.membership_id
     AND membership.account_id = approval.account_id
    INNER JOIN canonical_human_identity_subjects subject_row
      ON subject_row.auth_user_id = approval.auth_user_id
     AND subject_row.identity_id = approval.canonical_identity_id
    INNER JOIN canonical_human_identities identity_row
      ON identity_row.id = approval.canonical_identity_id
    INNER JOIN canonical_human_login_bindings binding
      ON binding.id = approval.login_binding_id
     AND binding.identity_id = approval.canonical_identity_id
    INNER JOIN auth_users auth_user ON auth_user.id = approval.auth_user_id
    WHERE approval.operation_id = p_operation_id
      AND approval.canonical_identity_id <> operation.target_identity_id
      AND membership.subject_id = 'user:' || approval.auth_user_id
      AND membership.status = 'active' AND membership.role <> 'owner'
      AND membership.authorization_revision = approval.membership_authorization_revision
      AND subject_row.status = 'active' AND subject_row.revision = approval.subject_revision
      AND identity_row.status = 'active' AND identity_row.recovery_state = 'ready'
      AND identity_row.identity_revision = approval.identity_revision
      AND identity_row.auth_revision = approval.auth_revision
      AND binding.status = 'active' AND binding.revision = approval.login_binding_revision
      AND organization_recovery_valid_acceptance_id(
        approval.policy_id, approval.canonical_identity_id
      ) = approval.custodian_acceptance_id
    ORDER BY approval.canonical_identity_id, approval.approved_at DESC, approval.id DESC
  )
  SELECT coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'membershipId', approval.membership_id::text,
      'name', approval.name,
      'email', approval.email,
      'approvedAt', approval.approved_at
    ) ORDER BY approval.approved_at, approval.id
  ), '[]'::jsonb) INTO result
  FROM current_approvals approval;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_recovery_marker IS NULL THEN '' ELSE previous_recovery_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.canonical_human_identity_lifecycle',
    CASE WHEN previous_canonical_marker IS NULL THEN '' ELSE previous_canonical_marker END, true);
  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_organization_marker IS NULL THEN '' ELSE previous_organization_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION organization_usage_policy_capability_active(p_actor text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT p_actor = pg_catalog.pg_get_userbyid((
        SELECT relowner FROM pg_catalog.pg_class
        WHERE oid = '{{schema}}.usage_events'::pg_catalog.regclass
      )) AND nullif(pg_catalog.current_setting('opengeni.workspace_id', true), '') IS NULL
      AND EXISTS (
        SELECT 1 FROM opengeni_private.organization_usage_read_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.account_id::text IS NOT DISTINCT FROM nullif(pg_catalog.current_setting('opengeni.account_id', true), '')
          AND capability.subject_id IS NOT DISTINCT FROM nullif(pg_catalog.current_setting('opengeni.subject_id', true), '')
          AND capability.initiating_human_subject_id IS NOT DISTINCT FROM nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), '')
      )
    $$;

CREATE FUNCTION organization_workspace_command(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  actor_membership_id uuid;
  creator_grant_operation_id uuid;
  creator_grant_operation_hash text;
BEGIN
  result := organization_workspace_command_without_creator_access(p_command);
  IF p_command ->> 'action' IS DISTINCT FROM 'create' THEN
    RETURN result;
  END IF;
  -- A create receipt written before this migration has no child grant receipt.
  -- Preserve that historical outcome instead of turning a retry into a new
  -- privilege grant after rollout.
  IF coalesce((result ->> 'replay')::boolean, false) THEN
    RETURN result;
  END IF;

  SELECT membership.id INTO actor_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = nullif(p_command ->> 'organizationId', '')::uuid
    AND membership.subject_id = p_command ->> 'actorSubjectId'
    AND membership.status = 'active'
    AND membership.role IN ('owner', 'admin');
  IF actor_membership_id IS NULL THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;

  -- Derive one stable, private follow-up operation from the public create key.
  -- A committed create can therefore be retried safely after a lost response,
  -- without ever re-elevating a creator who was deliberately demoted later.
  creator_grant_operation_hash := pg_catalog.md5(
    'organization-workspace-creator-admin:' || (p_command ->> 'operationId')
  );
  creator_grant_operation_id := (
    pg_catalog.substr(creator_grant_operation_hash, 1, 12)
    || '5'
    || pg_catalog.substr(creator_grant_operation_hash, 14, 3)
    || '8'
    || pg_catalog.substr(creator_grant_operation_hash, 18)
  )::uuid;

  result := result || organization_workspace_command_without_creator_access(
    pg_catalog.jsonb_build_object(
      'action', 'grant',
      'organizationId', p_command ->> 'organizationId',
      'actorSubjectId', p_command ->> 'actorSubjectId',
      'workspaceId', result ->> 'workspaceId',
      'targetOrganizationMembershipId', actor_membership_id,
      'role', 'admin',
      'operationId', creator_grant_operation_id
    )
  );
  RETURN result;
END
$$;

COMMENT ON FUNCTION organization_workspace_command(p_command jsonb) IS 'Idempotent organization-admin shared-workspace command. A create atomically materializes an explicit named admin grant for its creator.';

CREATE FUNCTION organization_workspace_command_without_creator_access(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  action_value text := p_command ->> 'action';
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  target_membership_id_value uuid := nullif(
    p_command ->> 'targetOrganizationMembershipId', ''
  )::uuid;
  role_value text := p_command ->> 'role';
  permissions_value jsonb := p_command -> 'permissions';
  resolved_permissions jsonb;
  name_value text := nullif(btrim(p_command ->> 'name'), '');
  expected_updated_at_value timestamptz := nullif(
    p_command ->> 'expectedUpdatedAt', ''
  )::timestamptz;
  input_hash_value text;
  actor organization_memberships%ROWTYPE;
  target organization_memberships%ROWTYPE;
  workspace workspaces%ROWTYPE;
  access workspace_memberships%ROWTYPE;
  prior organization_workspace_operation_receipts%ROWTYPE;
  result jsonb;
BEGIN
  IF p_command IS NULL OR account_id_value IS NULL OR actor_subject IS NULL
    OR action_value NOT IN ('create', 'rename', 'grant')
    OR operation_id_value IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization workspace command is invalid' USING ERRCODE = '22023';
  END IF;
  input_hash_value := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(p_command::text, 'UTF8')), 'hex'
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('organization-membership:' || account_id_value::text, 0)
  );
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  PERFORM 1 FROM managed_accounts account
  WHERE account.id = account_id_value FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.subject_id = actor_subject
  FOR SHARE;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO prior FROM organization_workspace_operation_receipts receipt
  WHERE receipt.account_id = account_id_value
    AND receipt.operation_id = operation_id_value;
  IF FOUND THEN
    IF prior.action IS DISTINCT FROM action_value
      OR prior.input_hash IS DISTINCT FROM input_hash_value
    THEN
      RAISE EXCEPTION 'organization workspace operation key was reused'
        USING ERRCODE = '23505';
    END IF;
    RETURN prior.result || pg_catalog.jsonb_build_object('replay', true);
  END IF;

  IF action_value = 'create' THEN
    IF name_value IS NULL
      OR char_length(name_value) > 120
      OR octet_length(convert_to(name_value, 'UTF8')) > 480
      OR workspace_id_value IS NOT NULL
      OR target_membership_id_value IS NOT NULL
      OR role_value IS NOT NULL
      OR permissions_value IS NOT NULL
      OR expected_updated_at_value IS NOT NULL
    THEN
      RAISE EXCEPTION 'shared workspace create input is invalid' USING ERRCODE = '22023';
    END IF;
    workspace_id_value := pg_catalog.gen_random_uuid();
    PERFORM pg_catalog.set_config('opengeni.workspace_id', workspace_id_value::text, true);
    INSERT INTO workspaces (id, account_id, name)
    VALUES (workspace_id_value, account_id_value, name_value)
    RETURNING * INTO workspace;
    INSERT INTO workspace_inference_controls (workspace_id, account_id)
    VALUES (workspace_id_value, account_id_value);
  ELSE
    IF workspace_id_value IS NULL THEN
      RAISE EXCEPTION 'shared workspace id is required' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_catalog.set_config('opengeni.workspace_id', workspace_id_value::text, true);
    PERFORM 1 FROM workspace_inference_controls control
    WHERE control.account_id = account_id_value
      AND control.workspace_id = workspace_id_value
    FOR SHARE;
    SELECT * INTO workspace FROM workspaces candidate
    WHERE candidate.account_id = account_id_value
      AND candidate.id = workspace_id_value
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
    END IF;
    IF EXISTS (
      SELECT 1 FROM organization_memberships personal_owner
      WHERE personal_owner.account_id = account_id_value
        AND personal_owner.personal_workspace_id = workspace_id_value
    ) THEN
      RAISE EXCEPTION 'personal workspaces are not administrable'
        USING ERRCODE = '42501';
    END IF;
    IF action_value = 'rename' THEN
      IF name_value IS NULL
        OR char_length(name_value) > 120
        OR octet_length(convert_to(name_value, 'UTF8')) > 480
        OR expected_updated_at_value IS NULL
        OR target_membership_id_value IS NOT NULL
        OR role_value IS NOT NULL
        OR permissions_value IS NOT NULL
      THEN
        RAISE EXCEPTION 'shared workspace rename input is invalid' USING ERRCODE = '22023';
      END IF;
      IF workspace.updated_at IS DISTINCT FROM expected_updated_at_value THEN
        RAISE EXCEPTION 'shared workspace changed before rename' USING ERRCODE = '40001';
      END IF;
      UPDATE workspaces SET name = name_value, updated_at = clock_timestamp()
      WHERE id = workspace_id_value RETURNING * INTO workspace;
    ELSE
      IF target_membership_id_value IS NULL
        OR role_value NOT IN ('viewer', 'member', 'admin', 'custom')
        OR name_value IS NOT NULL
        OR (role_value = 'custom'
          AND opengeni_private.workspace_member_custom_permissions_valid(permissions_value)
            IS DISTINCT FROM true)
        OR (role_value <> 'custom' AND permissions_value IS NOT NULL)
      THEN
        RAISE EXCEPTION 'shared workspace grant input is invalid' USING ERRCODE = '22023';
      END IF;
      resolved_permissions := CASE
        WHEN role_value = 'custom' THEN permissions_value
        ELSE opengeni_private.workspace_member_role_permissions(role_value)
      END;
      SELECT * INTO target FROM organization_memberships membership
      WHERE membership.account_id = account_id_value
        AND membership.id = target_membership_id_value
      FOR SHARE;
      IF NOT FOUND OR target.status <> 'active' OR target.subject_id NOT LIKE 'user:%' THEN
        RAISE EXCEPTION 'active organization member not found' USING ERRCODE = 'P0002';
      END IF;
      SELECT * INTO access FROM workspace_memberships membership
      WHERE membership.account_id = account_id_value
        AND membership.workspace_id = workspace_id_value
        AND membership.subject_id = target.subject_id
      FOR UPDATE;
      IF FOUND THEN
        IF expected_updated_at_value IS NULL
          OR access.updated_at IS DISTINCT FROM expected_updated_at_value
        THEN
          RAISE EXCEPTION 'workspace access changed before grant' USING ERRCODE = '40001';
        END IF;
        UPDATE workspace_memberships SET
          role = role_value,
          permissions = resolved_permissions,
          subject_label = NULL,
          updated_at = clock_timestamp()
        WHERE id = access.id RETURNING * INTO access;
      ELSE
        IF expected_updated_at_value IS NOT NULL THEN
          RAISE EXCEPTION 'workspace access changed before grant' USING ERRCODE = '40001';
        END IF;
        INSERT INTO workspace_memberships (
          account_id, workspace_id, subject_id, subject_label, role, permissions
        ) VALUES (
          account_id_value, workspace_id_value, target.subject_id, NULL,
          role_value, resolved_permissions
        ) RETURNING * INTO access;
      END IF;
    END IF;
  END IF;

  result := pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
    'workspaceId', workspace_id_value,
    'organizationMembershipId', target_membership_id_value,
    'workspaceMembershipId', access.id,
    'updatedAt', coalesce(access.updated_at, workspace.updated_at),
    'replay', false
  ));
  INSERT INTO organization_workspace_operation_receipts (
    account_id, operation_id, action, input_hash, result
  ) VALUES (
    account_id_value, operation_id_value, action_value, input_hash_value, result
  );
  INSERT INTO organization_workspace_lifecycle_events (
    account_id, operation_id, actor_membership_id, workspace_id,
    target_organization_membership_id, target_workspace_membership_id, kind, role
  ) VALUES (
    account_id_value, operation_id_value, actor.id, workspace_id_value,
    target_membership_id_value, access.id, action_value,
    CASE WHEN action_value = 'grant' THEN role_value ELSE NULL END
  );
  RETURN result;
END
$$;

COMMENT ON FUNCTION organization_workspace_command_without_creator_access(p_command jsonb) IS 'Idempotent and CAS-fenced organization-admin create, rename, and named-role shared workspace grant command. Personal workspaces are excluded by canonical membership pointers.';

CREATE FUNCTION personal_machine_grant_covers_descendant(p_grant_id uuid, p_session_id uuid, p_turn_id uuid, p_enrollment_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  grant_row organization_user_resource_grants%ROWTYPE;
  owner_row organization_memberships%ROWTYPE;
  enrollment_row enrollments%ROWTYPE;
  child_row sessions%ROWTYPE;
  parent_row sessions%ROWTYPE;
  visited uuid[] := ARRAY[]::uuid[];
BEGIN
  -- Only the existing machine admission/dispatch helpers open this capability.
  IF NOT opengeni_private.scoped_compute_capability_active() THEN RETURN false; END IF;
  SELECT * INTO grant_row FROM organization_user_resource_grants
  WHERE id = p_grant_id
    AND account_id = nullif(current_setting('opengeni.account_id', true), '')::uuid
    AND workspace_id = nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    AND action = 'connected_machine.use' AND revoked_at IS NULL
    AND ((mode = 'session' AND status = 'active') OR (mode = 'once' AND status = 'consumed'))
    AND (expires_at IS NULL OR expires_at > clock_timestamp());
  IF grant_row.id IS NULL OR grant_row.session_id = p_session_id THEN RETURN false; END IF;

  SELECT * INTO owner_row FROM organization_memberships
  WHERE id = grant_row.owner_organization_membership_id AND account_id = grant_row.account_id
    AND status = 'active' AND revoked_at IS NULL;
  IF owner_row.id IS NULL OR NOT (owner_row.personal_workspace_id = grant_row.workspace_id
    OR EXISTS (SELECT 1 FROM workspace_memberships membership
      WHERE membership.account_id = grant_row.account_id
        AND membership.workspace_id = grant_row.workspace_id
        AND membership.subject_id = owner_row.subject_id)) THEN RETURN false; END IF;

  SELECT enrollment.* INTO enrollment_row FROM enrollments enrollment
  JOIN organization_user_resource_authorities authority ON authority.id = enrollment.authority_id
    AND authority.account_id = enrollment.account_id
    AND authority.organization_membership_id = enrollment.owner_organization_membership_id
    AND authority.resource_kind = 'connected_machine' AND authority.resource_id = enrollment.id
    AND authority.generation = enrollment.generation
    AND authority.status = 'active' AND authority.revoked_at IS NULL
  WHERE enrollment.id = p_enrollment_id AND enrollment.account_id = grant_row.account_id
    AND enrollment.authority_scope = 'user' AND enrollment.authority_id = grant_row.authority_id
    AND enrollment.owner_organization_membership_id = owner_row.id
    AND enrollment.status = 'active' AND enrollment.revoked_at IS NULL;
  IF enrollment_row.id IS NULL THEN RETURN false; END IF;

  SELECT session.* INTO child_row FROM sessions session
  JOIN session_turns turn_value ON turn_value.session_id = session.id
    AND turn_value.account_id = session.account_id AND turn_value.workspace_id = session.workspace_id
  WHERE session.id = p_session_id AND session.account_id = grant_row.account_id
    AND session.workspace_id = grant_row.workspace_id AND turn_value.id = p_turn_id
    AND session.owner_organization_membership_id = owner_row.id
    AND session.owner_subject_id = owner_row.subject_id
    AND session.visibility = grant_row.context
    AND coalesce(nullif(btrim(turn_value.initiating_human_subject_id), ''),
      CASE WHEN turn_value.initiator_kind = 'subject'
        THEN nullif(btrim(turn_value.initiator_subject_id), '') END) = owner_row.subject_id;
  IF child_row.id IS NULL THEN RETURN false; END IF;

  LOOP
    IF child_row.id = ANY(visited) OR child_row.parent_session_id IS NULL
      OR child_row.parent_turn_id IS NULL OR child_row.agent_creation_attempt_id IS NULL THEN RETURN false; END IF;
    visited := array_append(visited, child_row.id);
    -- Parent IDs need a protected creation witness, not just immutable values.
    SELECT parent.* INTO parent_row FROM sessions parent
    JOIN session_turns causal ON causal.id = child_row.parent_turn_id
      AND causal.session_id = parent.id AND causal.account_id = parent.account_id
      AND causal.workspace_id = parent.workspace_id
    WHERE parent.id = child_row.parent_session_id AND parent.account_id = grant_row.account_id
      AND parent.workspace_id = grant_row.workspace_id
      AND parent.owner_organization_membership_id = owner_row.id
      AND parent.owner_subject_id = owner_row.subject_id
      AND coalesce(nullif(btrim(causal.initiating_human_subject_id), ''),
        CASE WHEN causal.initiator_kind = 'subject'
          THEN nullif(btrim(causal.initiator_subject_id), '') END) = owner_row.subject_id;
    IF parent_row.id IS NULL THEN RETURN false; END IF;

    IF NOT EXISTS (
      SELECT 1 FROM session_attempt_connected_machine_authorizations snapshot
      JOIN sandboxes sandbox ON sandbox.id = snapshot.sandbox_id
        AND sandbox.account_id = grant_row.account_id AND sandbox.enrollment_id = p_enrollment_id
      WHERE snapshot.account_id = grant_row.account_id AND snapshot.workspace_id = grant_row.workspace_id
        AND snapshot.session_id = parent_row.id AND snapshot.turn_id = child_row.parent_turn_id
        AND snapshot.attempt_id = child_row.agent_creation_attempt_id
        AND snapshot.enrollment_id = p_enrollment_id
        AND snapshot.initiating_human_subject_id = owner_row.subject_id
        AND snapshot.owner_organization_membership_id = owner_row.id
        AND snapshot.membership_authorization_revision = owner_row.authorization_revision
        AND snapshot.authority_id = grant_row.authority_id
        AND snapshot.authority_generation = enrollment_row.generation
        AND snapshot.enrollment_generation = enrollment_row.generation
        AND snapshot.session_authority_epoch BETWEEN parent_row.execution_authority_epoch AND parent_row.authority_epoch
        AND snapshot.grant_id = grant_row.id AND snapshot.grant_generation = grant_row.generation
        AND snapshot.grant_mode = grant_row.mode
    ) THEN RETURN false; END IF;

    IF parent_row.id = grant_row.session_id THEN
      RETURN grant_row.authority_epoch BETWEEN parent_row.execution_authority_epoch AND parent_row.authority_epoch;
    END IF;
    child_row := parent_row;
  END LOOP;
END
$$;

CREATE FUNCTION personal_machine_turn_consent_covers_descendant(p_consent_id uuid, p_session_id uuid, p_turn_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  consent_row session_turn_machine_consents%ROWTYPE;
  child_row sessions%ROWTYPE;
  parent_row sessions%ROWTYPE;
  visited uuid[] := ARRAY[]::uuid[];
BEGIN
  IF NOT opengeni_private.scoped_compute_capability_active() THEN RETURN false; END IF;
  SELECT * INTO consent_row FROM session_turn_machine_consents
  WHERE id = p_consent_id
    AND account_id = nullif(current_setting('opengeni.account_id', true), '')::uuid
    AND workspace_id = nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
  IF consent_row.id IS NULL OR consent_row.session_id = p_session_id
    OR NOT live_session_turn_machine_consent(consent_row.id) THEN RETURN false; END IF;
  -- If this source also has an exact-session grant, its tree is grant-derived.
  -- Do not use a turn-local move receipt to bypass that grant's revocation or
  -- expiry. This includes terminal grant rows: only an explicit new grant or a
  -- new execution-authority epoch can restore tree coverage in that case.
  IF EXISTS (
    SELECT 1 FROM organization_user_resource_grants grant_value
    JOIN sessions source ON source.id = consent_row.session_id
      AND source.account_id = consent_row.account_id AND source.workspace_id = consent_row.workspace_id
    WHERE grant_value.account_id = consent_row.account_id AND grant_value.workspace_id = consent_row.workspace_id
      AND grant_value.session_id = consent_row.session_id AND grant_value.authority_id = consent_row.authority_id
      AND grant_value.owner_organization_membership_id = consent_row.owner_organization_membership_id
      AND grant_value.action = 'connected_machine.use' AND grant_value.mode IN ('once','session')
      AND grant_value.authority_epoch BETWEEN source.execution_authority_epoch AND source.authority_epoch
  ) THEN RETURN false; END IF;
  SELECT session.* INTO child_row FROM sessions session
  JOIN session_turns turn_value ON turn_value.session_id = session.id
    AND turn_value.account_id = session.account_id AND turn_value.workspace_id = session.workspace_id
  WHERE session.id = p_session_id AND session.account_id = consent_row.account_id
    AND session.workspace_id = consent_row.workspace_id AND turn_value.id = p_turn_id
    AND session.owner_organization_membership_id = consent_row.owner_organization_membership_id
    AND session.owner_subject_id = consent_row.consenting_subject_id
    AND coalesce(nullif(btrim(turn_value.initiating_human_subject_id), ''),
      CASE WHEN turn_value.initiator_kind = 'subject'
        THEN nullif(btrim(turn_value.initiator_subject_id), '') END) = consent_row.consenting_subject_id;
  IF child_row.id IS NULL THEN RETURN false; END IF;
  LOOP
    IF child_row.id = ANY(visited) OR child_row.parent_session_id IS NULL
      OR child_row.parent_turn_id IS NULL OR child_row.agent_creation_attempt_id IS NULL THEN RETURN false; END IF;
    visited := array_append(visited, child_row.id);
    SELECT parent.* INTO parent_row FROM sessions parent
    JOIN session_turns causal ON causal.id = child_row.parent_turn_id
      AND causal.session_id = parent.id AND causal.account_id = parent.account_id
      AND causal.workspace_id = parent.workspace_id
    WHERE parent.id = child_row.parent_session_id AND parent.account_id = consent_row.account_id
      AND parent.workspace_id = consent_row.workspace_id
      AND parent.owner_organization_membership_id = consent_row.owner_organization_membership_id
      AND parent.owner_subject_id = consent_row.consenting_subject_id
      AND coalesce(nullif(btrim(causal.initiating_human_subject_id), ''),
        CASE WHEN causal.initiator_kind = 'subject'
          THEN nullif(btrim(causal.initiator_subject_id), '') END) = consent_row.consenting_subject_id;
    IF parent_row.id IS NULL OR NOT EXISTS (
      SELECT 1 FROM session_attempt_machine_consents binding
      JOIN session_turn_attempts snapshot ON snapshot.id = binding.attempt_id
      WHERE binding.consent_id = consent_row.id AND snapshot.account_id = consent_row.account_id
        AND snapshot.workspace_id = consent_row.workspace_id AND snapshot.session_id = parent_row.id
        AND snapshot.turn_id = child_row.parent_turn_id
        AND snapshot.id = child_row.agent_creation_attempt_id
        AND snapshot.authority_epoch BETWEEN parent_row.execution_authority_epoch AND parent_row.authority_epoch
    ) THEN RETURN false; END IF;
    IF parent_row.id = consent_row.session_id THEN
      RETURN child_row.parent_turn_id = consent_row.turn_id;
    END IF;
    child_row := parent_row;
  END LOOP;
END
$$;

CREATE FUNCTION preference_registry_accepted_snapshot_for_recovery(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_execution_generation integer, p_initiating_human_subject_id text, p_accepted_at timestamp with time zone) RETURNS TABLE(canonical_descriptors jsonb, canonical_truncated boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  frozen preference_registry_snapshots%ROWTYPE;
BEGIN
  SELECT snapshot.* INTO frozen
  FROM session_turn_attempts accepted_attempt
  JOIN preference_registry_snapshots snapshot
    ON snapshot.account_id = accepted_attempt.account_id
    AND snapshot.workspace_id = accepted_attempt.workspace_id
    AND snapshot.session_id = accepted_attempt.session_id
    AND snapshot.turn_id = accepted_attempt.turn_id
    AND snapshot.attempt_id = accepted_attempt.id
    AND snapshot.execution_generation = accepted_attempt.execution_generation
  WHERE snapshot.account_id = p_account_id
    AND snapshot.workspace_id = p_workspace_id
    AND snapshot.session_id = p_session_id
    AND snapshot.turn_id = p_turn_id
    AND snapshot.execution_generation < p_execution_generation
    AND snapshot.initiating_human_subject_id = p_initiating_human_subject_id
  ORDER BY snapshot.execution_generation, snapshot.created_at, snapshot.id
  LIMIT 1;

  IF FOUND THEN
    IF frozen.created_at > transaction_timestamp()
      OR jsonb_typeof(frozen.descriptors) <> 'array'
      OR jsonb_array_length(frozen.descriptors) > 64
      OR octet_length(convert_to(frozen.descriptors::text, 'UTF8')) > 16384
      OR frozen.descriptor_hash IS DISTINCT FROM encode(
        sha256(convert_to(frozen.descriptors::text, 'UTF8')), 'hex'
      )
      OR (
        SELECT count(*) <> count(DISTINCT descriptor->>'id')
        FROM jsonb_array_elements(frozen.descriptors) descriptor
      )
    THEN
      RAISE EXCEPTION 'accepted preference snapshot failed canonical integrity checks'
        USING ERRCODE = '23514';
    END IF;
    canonical_descriptors := frozen.descriptors;
    canonical_truncated := frozen.truncated;
    RETURN NEXT;
    RETURN;
  END IF;

  RETURN QUERY SELECT result.canonical_descriptors, result.canonical_truncated
  FROM preference_registry_canonical_snapshot_at(
    p_account_id, p_workspace_id, p_initiating_human_subject_id, p_accepted_at
  ) result;
END;
$$;

CREATE FUNCTION preference_registry_activation_authority(p_workspace_id uuid, p_revision_ids uuid[]) RETURNS TABLE(revision_id uuid, authority_kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  WITH candidates AS (
    SELECT revision.id AS revision_id,skill_revision_activation_authority(revision.id,transaction_timestamp()) AS authority_kind,1 AS priority
    FROM preference_registry_revisions revision
    JOIN preference_registry_preferences h ON h.id=revision.preference_id AND h.account_id=revision.account_id
    WHERE revision.id=ANY(p_revision_ids)
      AND opengeni_private.workspace_rls_visible(revision.account_id,p_workspace_id)
      AND opengeni_private.preference_registry_scope_visible(h.account_id,h.scope,h.scope_workspace_id,h.scope_subject_id)
    UNION ALL
    (SELECT DISTINCT ON (receipt.destination_revision_id) receipt.destination_revision_id,receipt.authority_kind,2
    FROM governed_learning_activation_receipts receipt
    WHERE receipt.workspace_id=p_workspace_id AND receipt.destination='preference'
      AND receipt.destination_revision_id=ANY(p_revision_ids)
      AND opengeni_private.workspace_rls_visible(receipt.account_id,receipt.workspace_id)
      AND NOT EXISTS(SELECT 1 FROM governed_learning_activation_undo_receipts undo WHERE undo.account_id=receipt.account_id AND undo.activation_receipt_id=receipt.id)
    ORDER BY receipt.destination_revision_id,receipt.created_at DESC,receipt.id DESC)
  ) SELECT DISTINCT ON (revision_id) revision_id,authority_kind FROM candidates
    WHERE authority_kind IS NOT NULL ORDER BY revision_id,priority
$$;

CREATE FUNCTION preference_registry_apply_lifecycle(p_operation text, p_preference_id uuid, p_expected_scope_version integer, p_expected_revision_id uuid, p_revision_id uuid, p_new_scope text, p_related_preference_id uuid, p_actor_subject_id text, p_reason text) RETURNS TABLE(event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      preference record;
      replacement record;
      replacement_revision record;
      revision record;
      context_account_id uuid;
      context_workspace_id uuid;
      context_subject_id text;
      context_principal_kind text;
      next_event_version integer;
      event_type text;
      old_revision_id uuid;
      new_revision_id uuid;
      old_scope text;
      old_workspace_id uuid;
      old_subject_id text;
      new_scope text;
      new_workspace_id uuid;
      new_subject_id text;
      related_preference_id uuid;
      lifecycle_lock_count integer;
    BEGIN
      context_account_id := NULLIF(
        current_setting('opengeni.account_id', true), ''
      )::uuid;
      context_workspace_id := NULLIF(
        current_setting('opengeni.workspace_id', true), ''
      )::uuid;
      context_subject_id := NULLIF(
        current_setting('opengeni.subject_id', true), ''
      );
      context_principal_kind := NULLIF(
        current_setting('opengeni.principal_kind', true), ''
      );
      IF context_account_id IS NULL OR context_workspace_id IS NULL
        OR context_subject_id IS NULL
        OR context_principal_kind IS DISTINCT FROM 'human_session'
        OR p_actor_subject_id IS DISTINCT FROM context_subject_id
      THEN
        RAISE EXCEPTION 'preference lifecycle requires exact transaction-local actor authority'
          USING ERRCODE = '42501';
      END IF;
      IF length(btrim(p_actor_subject_id)) NOT BETWEEN 1 AND 1024
        OR length(btrim(p_reason)) NOT BETWEEN 1 AND 4096
      THEN
        RAISE EXCEPTION 'preference lifecycle actor and reason are invalid'
          USING ERRCODE = '22023';
      END IF;

      IF p_operation = 'supersede' THEN
        IF p_related_preference_id IS NULL OR p_related_preference_id = p_preference_id THEN
          RAISE EXCEPTION 'preference supersession requires a distinct replacement'
            USING ERRCODE = '22023';
        END IF;
        PERFORM 1
        FROM preference_registry_preferences candidate
        WHERE candidate.id IN (p_preference_id, p_related_preference_id)
          AND candidate.account_id = context_account_id
          AND opengeni_private.preference_registry_scope_visible(
            candidate.account_id,
            candidate.scope,
            candidate.scope_workspace_id,
            candidate.scope_subject_id
          )
        ORDER BY candidate.id
        FOR UPDATE;
        GET DIAGNOSTICS lifecycle_lock_count = ROW_COUNT;
        IF lifecycle_lock_count <> 2 THEN
          RAISE EXCEPTION 'preference supersession heads were not found in the authorized scope'
            USING ERRCODE = '42501';
        END IF;
      ELSE
        PERFORM 1
        FROM preference_registry_preferences candidate
        WHERE candidate.id = p_preference_id
          AND candidate.account_id = context_account_id
          AND opengeni_private.preference_registry_scope_visible(
            candidate.account_id,
            candidate.scope,
            candidate.scope_workspace_id,
            candidate.scope_subject_id
          )
        FOR UPDATE;
        GET DIAGNOSTICS lifecycle_lock_count = ROW_COUNT;
        IF lifecycle_lock_count <> 1 THEN
          RAISE EXCEPTION 'preference lifecycle head was not found in the authorized scope'
            USING ERRCODE = '42501';
        END IF;
      END IF;

      SELECT * INTO preference
      FROM preference_registry_preferences candidate
      WHERE candidate.id = p_preference_id
        AND candidate.account_id = context_account_id;
      IF NOT FOUND OR NOT opengeni_private.preference_registry_scope_visible(
        preference.account_id,
        preference.scope,
        preference.scope_workspace_id,
        preference.scope_subject_id
      ) THEN
        RAISE EXCEPTION 'preference was not found in the authorized scope'
          USING ERRCODE = '42501';
      END IF;
      IF preference.scope_version IS DISTINCT FROM p_expected_scope_version THEN
        RAISE EXCEPTION 'preference scope version changed'
          USING ERRCODE = '40001';
      END IF;
      IF preference.active_revision_id IS DISTINCT FROM p_expected_revision_id THEN
        RAISE EXCEPTION 'preference active revision changed'
          USING ERRCODE = '40001';
      END IF;
      PERFORM set_config(
        'opengeni.preference_lifecycle_head_id', preference.id::text, true
      );
      PERFORM set_config(
        'opengeni.preference_lifecycle_operation', p_operation, true
      );

      IF p_operation IN ('proposal_created', 'activate', 'correct', 'reject') THEN
        SELECT * INTO revision
        FROM preference_registry_revisions candidate
        WHERE candidate.id = p_revision_id
          AND candidate.preference_id = preference.id
          AND candidate.account_id = preference.account_id;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'preference lifecycle revision was not found'
            USING ERRCODE = '23503';
        END IF;
      END IF;

      IF p_operation = 'proposal_created' THEN
        IF preference.status <> 'proposed'
          OR preference.active_revision_id IS NOT NULL
          OR EXISTS (
            SELECT 1 FROM preference_registry_events event
            WHERE event.preference_id = preference.id
          )
        THEN
          RAISE EXCEPTION 'proposal creation event requires a new inactive proposal'
            USING ERRCODE = '23514';
        END IF;
        event_type := 'proposal_created';
        new_revision_id := revision.id;
        new_scope := preference.scope;
        new_workspace_id := preference.scope_workspace_id;
        new_subject_id := preference.scope_subject_id;
      ELSIF p_operation = 'activate' THEN
        IF preference.status IN ('rejected', 'superseded')
          OR revision.id IS NOT DISTINCT FROM preference.active_revision_id
        THEN
          RAISE EXCEPTION 'preference cannot activate the requested revision'
            USING ERRCODE = '23514';
        END IF;
        UPDATE preference_registry_preferences
        SET status = 'active',
          active_revision_id = revision.id,
          active_revision = revision.revision,
          active_content_hash = revision.content_hash,
          activation_version = activation_version + 1,
          updated_at = clock_timestamp()
        WHERE id = preference.id;
        event_type := 'activated';
        old_revision_id := preference.active_revision_id;
        new_revision_id := revision.id;
      ELSIF p_operation = 'correct' THEN
        IF preference.status IN ('rejected', 'superseded')
          OR preference.active_revision_id IS NULL
          OR revision.corrects_revision_id IS DISTINCT FROM preference.active_revision_id
          OR revision.provenance_source <> 'human'
        THEN
          RAISE EXCEPTION 'preference correction does not identify the active immutable revision'
            USING ERRCODE = '23514';
        END IF;
        UPDATE preference_registry_preferences
        SET status = 'active',
          active_revision_id = revision.id,
          active_revision = revision.revision,
          active_content_hash = revision.content_hash,
          activation_version = activation_version + 1,
          updated_at = clock_timestamp()
        WHERE id = preference.id;
        event_type := 'corrected';
        old_revision_id := preference.active_revision_id;
        new_revision_id := revision.id;
      ELSIF p_operation = 'reject' THEN
        IF preference.status <> 'proposed' OR preference.active_revision_id IS NOT NULL THEN
          RAISE EXCEPTION 'only an inactive proposal can be rejected'
            USING ERRCODE = '23514';
        END IF;
        UPDATE preference_registry_preferences
        SET status = 'rejected', updated_at = clock_timestamp()
        WHERE id = preference.id;
        event_type := 'rejected';
        new_revision_id := revision.id;
      ELSIF p_operation = 'deactivate' THEN
        IF preference.status <> 'active' OR preference.active_revision_id IS NULL THEN
          RAISE EXCEPTION 'only an active preference can be deactivated'
            USING ERRCODE = '23514';
        END IF;
        UPDATE preference_registry_preferences
        SET status = 'inactive', active_revision_id = NULL,
          active_revision = NULL, active_content_hash = NULL,
          activation_version = activation_version + 1,
          updated_at = clock_timestamp()
        WHERE id = preference.id;
        event_type := 'deactivated';
        old_revision_id := preference.active_revision_id;
      ELSIF p_operation = 'scope' THEN
        IF preference.status IN ('rejected', 'superseded')
          OR p_new_scope NOT IN ('organization', 'workspace', 'user')
          OR p_new_scope = preference.scope
        THEN
          RAISE EXCEPTION 'preference cannot change to the requested scope'
            USING ERRCODE = '23514';
        END IF;
        old_scope := preference.scope;
        old_workspace_id := preference.scope_workspace_id;
        old_subject_id := preference.scope_subject_id;
        new_scope := p_new_scope;
        new_workspace_id := CASE WHEN p_new_scope = 'workspace'
          THEN context_workspace_id ELSE NULL END;
        new_subject_id := CASE WHEN p_new_scope = 'user'
          THEN context_subject_id ELSE NULL END;
        UPDATE preference_registry_preferences
        SET scope = new_scope,
          scope_workspace_id = new_workspace_id,
          scope_subject_id = new_subject_id,
          scope_version = scope_version + 1,
          updated_at = clock_timestamp()
        WHERE id = preference.id;
        event_type := 'scope_changed';
      ELSIF p_operation = 'supersede' THEN
        SELECT * INTO replacement
        FROM preference_registry_preferences candidate
        WHERE candidate.id = p_related_preference_id
          AND candidate.account_id = preference.account_id;
        IF NOT FOUND
          OR replacement.status <> 'active'
          OR replacement.active_revision_id IS NULL
          OR replacement.scope IS DISTINCT FROM preference.scope
          OR replacement.scope_workspace_id IS DISTINCT FROM preference.scope_workspace_id
          OR replacement.scope_subject_id IS DISTINCT FROM preference.scope_subject_id
          OR NOT opengeni_private.preference_registry_scope_visible(
            replacement.account_id,
            replacement.scope,
            replacement.scope_workspace_id,
            replacement.scope_subject_id
          )
          OR preference.status <> 'active'
          OR preference.active_revision_id IS NULL
        THEN
          RAISE EXCEPTION 'replacement preference is not active in the exact same target'
            USING ERRCODE = '23514';
        END IF;
        SELECT * INTO replacement_revision
        FROM preference_registry_revisions candidate
        WHERE candidate.id = replacement.active_revision_id
          AND candidate.preference_id = replacement.id
          AND candidate.account_id = replacement.account_id
          AND (candidate.expires_at IS NULL OR candidate.expires_at > transaction_timestamp());
        IF NOT FOUND THEN
          RAISE EXCEPTION 'replacement preference active revision is expired'
            USING ERRCODE = '23514';
        END IF;
        UPDATE preference_registry_preferences
        SET status = 'superseded',
          superseded_by_preference_id = replacement.id,
          updated_at = clock_timestamp()
        WHERE id = preference.id;
        event_type := 'superseded';
        old_revision_id := preference.active_revision_id;
        related_preference_id := replacement.id;
      ELSE
        RAISE EXCEPTION 'unsupported preference lifecycle operation'
          USING ERRCODE = '22023';
      END IF;

      PERFORM set_config('opengeni.preference_lifecycle_head_id', '', true);
      PERFORM set_config('opengeni.preference_lifecycle_operation', '', true);

      SELECT COALESCE(max(event.version), 0) + 1 INTO next_event_version
      FROM preference_registry_events event
      WHERE event.preference_id = preference.id;
      INSERT INTO preference_registry_events (
        account_id, preference_id, type, version,
        old_revision_id, new_revision_id,
        old_scope, old_workspace_id, old_subject_id,
        new_scope, new_workspace_id, new_subject_id,
        related_preference_id, actor_subject_id, reason
      ) VALUES (
        preference.account_id, preference.id, event_type, next_event_version,
        old_revision_id, new_revision_id,
        old_scope, old_workspace_id, old_subject_id,
        new_scope, new_workspace_id, new_subject_id,
        related_preference_id, p_actor_subject_id, p_reason
      ) RETURNING id INTO event_id;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION preference_registry_canonical_snapshot_at(p_account_id uuid, p_workspace_id uuid, p_initiating_human_subject_id text, p_accepted_at timestamp with time zone) RETURNS TABLE(canonical_descriptors jsonb, canonical_truncated boolean)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  canonical_descriptor jsonb;
  candidate_descriptors jsonb;
BEGIN
  canonical_descriptors := '[]'::jsonb;
  canonical_truncated := false;

  FOR canonical_descriptor IN
    WITH state_event AS (
      SELECT DISTINCT ON (event.preference_id)
        event.preference_id,
        event.type,
        event.new_revision_id
      FROM preference_registry_events event
      WHERE event.account_id = p_account_id
        AND event.created_at <= p_accepted_at
        AND event.type IN (
          'proposal_created',
          'activated',
          'corrected',
          'rejected',
          'deactivated',
          'superseded'
        )
      ORDER BY
        event.preference_id,
        event.created_at DESC,
        event.version DESC,
        event.id DESC
    ), scope_event AS (
      SELECT DISTINCT ON (event.preference_id)
        event.preference_id,
        event.new_scope AS scope,
        event.new_workspace_id AS scope_workspace_id,
        event.new_subject_id AS scope_subject_id
      FROM preference_registry_events event
      WHERE event.account_id = p_account_id
        AND event.created_at <= p_accepted_at
        AND event.new_scope IS NOT NULL
      ORDER BY
        event.preference_id,
        event.created_at DESC,
        event.version DESC,
        event.id DESC
    ), activation_version AS (
      SELECT
        event.preference_id,
        count(*)::integer AS value
      FROM preference_registry_events event
      WHERE event.account_id = p_account_id
        AND event.created_at <= p_accepted_at
        AND event.type IN ('activated', 'corrected', 'deactivated')
      GROUP BY event.preference_id
    )
    SELECT jsonb_build_object(
      'id', preference.id::text,
      'stableKey', preference.stable_key,
      'title', revision.title,
      'description', revision.description,
      'scope', scope.scope,
      'activeVersion', coalesce(activation.value, 0),
      'revisionId', revision.id::text,
      'contentHash', revision.content_hash,
      'precedence', jsonb_build_object(
        'tier', scope.scope,
        'rank', revision.precedence_rank,
        'conflictStrategy', revision.conflict_strategy,
        'conflictsWith', revision.conflicts_with
      ),
      'provenance', jsonb_build_object(
        'source', revision.provenance_source,
        'sourceIdHash', CASE
          WHEN revision.provenance_source_id IS NULL THEN NULL
          ELSE encode(
            sha256(convert_to(revision.provenance_source_id, 'UTF8')),
            'hex'
          )
        END,
        'trust', revision.trust
      ),
      -- How this exact revision became active. `trust` above stays the frozen
      -- creation-time fact; this is the separate activation question, read from
      -- the governed-learning receipt that activated this revision. NULL when
      -- the revision became active outside governed learning.
      'activationAuthority', coalesce(skill_revision_activation_authority(revision.id, p_accepted_at), (
        SELECT receipt.authority_kind
        FROM governed_learning_activation_receipts receipt
        WHERE receipt.account_id = p_account_id
          AND receipt.workspace_id = p_workspace_id
          AND receipt.destination = 'preference'
          AND receipt.destination_revision_id = revision.id
          AND NOT EXISTS (
            SELECT 1 FROM governed_learning_activation_undo_receipts undo
            WHERE undo.account_id = receipt.account_id
              AND undo.activation_receipt_id = receipt.id
          )
        ORDER BY receipt.created_at DESC, receipt.id DESC
        LIMIT 1
      )),
      'expiresAt', CASE
        WHEN revision.expires_at IS NULL THEN NULL
        ELSE to_char(
          revision.expires_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
        )
      END,
      'retrievalHandle',
        'preference://' || preference.id::text || '/revisions/' || revision.id::text ||
        '?sha256=' || revision.content_hash
    )
    FROM state_event state
    JOIN scope_event scope ON scope.preference_id = state.preference_id
    JOIN preference_registry_preferences preference
      ON preference.account_id = p_account_id
      AND preference.id = state.preference_id
    JOIN preference_registry_revisions revision
      ON revision.account_id = preference.account_id
      AND revision.preference_id = preference.id
      AND revision.id = state.new_revision_id
    LEFT JOIN activation_version activation
      ON activation.preference_id = preference.id
    WHERE state.type IN ('activated', 'corrected') AND coalesce(revision.skill_activation_mode,'workspace_managed')='workspace_managed'
      AND (revision.expires_at IS NULL OR revision.expires_at > p_accepted_at)
      AND (
        scope.scope = 'organization'
        OR (
          scope.scope = 'workspace'
          AND scope.scope_workspace_id = p_workspace_id
          AND scope.scope_subject_id IS NULL
        )
        OR (
          scope.scope = 'user'
          AND scope.scope_workspace_id IS NULL
          AND scope.scope_subject_id = p_initiating_human_subject_id
        )
      )
    ORDER BY CASE scope.scope
        WHEN 'organization' THEN 0
        WHEN 'workspace' THEN 1
        WHEN 'user' THEN 2
        ELSE 3
      END,
      revision.precedence_rank DESC,
      preference.stable_key,
      preference.id
  LOOP
    IF jsonb_array_length(canonical_descriptors) >= 64 THEN
      canonical_truncated := true;
      EXIT;
    END IF;
    candidate_descriptors := canonical_descriptors || jsonb_build_array(canonical_descriptor);
    IF octet_length(convert_to(candidate_descriptors::text, 'UTF8')) > 16384 THEN
      canonical_truncated := true;
      EXIT;
    END IF;
    canonical_descriptors := candidate_descriptors;
  END LOOP;

  RETURN NEXT;
END;
$$;

CREATE FUNCTION preference_registry_create_knowledge_proposal_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_operation_id uuid, p_input_hash text, p_knowledge_proposal_id uuid, p_stable_key text, p_title text, p_description text, p_content text, p_precedence_rank integer, p_conflict_strategy text, p_conflicts_with jsonb, p_expires_at timestamp with time zone, p_reason text) RETURNS TABLE(preference_id uuid, revision_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'Knowledge-backed Skill proposals are retired; use the unified Skill lifecycle (skill_save)'
    USING ERRCODE='55000';
END $$;

CREATE TABLE preference_registry_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    execution_generation integer NOT NULL,
    initiating_human_subject_id text NOT NULL,
    descriptors jsonb NOT NULL,
    descriptor_hash text NOT NULL,
    truncated boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT preference_registry_snapshots_descriptor_bytes_chk CHECK ((octet_length(convert_to((descriptors)::text, 'UTF8'::name)) <= 16384)),
    CONSTRAINT preference_registry_snapshots_descriptors_chk CHECK (((jsonb_typeof(descriptors) = 'array'::text) AND (jsonb_array_length(descriptors) <= 64))),
    CONSTRAINT preference_registry_snapshots_hash_chk CHECK (((descriptor_hash ~ '^[0-9a-f]{64}$'::text) AND (descriptor_hash = encode(sha256(convert_to((descriptors)::text, 'UTF8'::name)), 'hex'::text)))),
    CONSTRAINT preference_registry_snapshots_human_chk CHECK ((((length(btrim(initiating_human_subject_id)) >= 1) AND (length(btrim(initiating_human_subject_id)) <= 1024)) AND (execution_generation > 0)))
);

ALTER TABLE ONLY preference_registry_snapshots FORCE ROW LEVEL SECURITY;

CREATE FUNCTION preference_registry_get_or_create_snapshot(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS SETOF preference_registry_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      context_account_id uuid;
      context_workspace_id uuid;
      authority_subject_id text;
      turn_accepted_at timestamptz;
      canonical_descriptors jsonb;
      canonical_truncated boolean;
      canonical_hash text;
      snapshot_time timestamptz := transaction_timestamp();
      winner_id uuid;
    BEGIN
      context_account_id := NULLIF(
        current_setting('opengeni.account_id', true), ''
      )::uuid;
      context_workspace_id := NULLIF(
        current_setting('opengeni.workspace_id', true), ''
      )::uuid;
      IF context_account_id IS DISTINCT FROM p_account_id
        OR context_workspace_id IS DISTINCT FROM p_workspace_id
        OR p_execution_generation < 1
      THEN
        RAISE EXCEPTION 'preference snapshot requires exact transaction-local tenant authority'
          USING ERRCODE = '42501';
      END IF;

      SELECT
        coalesce(
          turn.initiating_human_subject_id,
          CASE WHEN turn.initiator_kind = 'subject' THEN turn.initiator_subject_id END
        ),
        turn.created_at
        INTO authority_subject_id, turn_accepted_at
      FROM workspaces workspace
      JOIN sessions session
        ON session.account_id = workspace.account_id
        AND session.workspace_id = workspace.id
      JOIN session_turns turn
        ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id
        AND turn.session_id = session.id
      JOIN session_turn_attempts attempt
        ON attempt.account_id = turn.account_id
        AND attempt.workspace_id = turn.workspace_id
        AND attempt.session_id = turn.session_id
        AND attempt.turn_id = turn.id
      WHERE workspace.id = p_workspace_id
        AND workspace.account_id = p_account_id
        AND session.id = p_session_id
        AND session.active_turn_id = p_turn_id
        AND turn.id = p_turn_id
        AND turn.active_attempt_id = p_attempt_id
        AND turn.execution_generation = p_execution_generation
        AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
        AND attempt.id = p_attempt_id
        AND attempt.execution_generation = p_execution_generation
        AND attempt.state IN ('claimed', 'running')
        AND NOT EXISTS (
          SELECT 1
          FROM session_attempt_interruptions interruption
          WHERE interruption.workspace_id = attempt.workspace_id
            AND interruption.attempt_id = attempt.id
            AND interruption.state IN ('pending', 'delivered', 'acknowledged')
        )
      FOR KEY SHARE OF workspace
      FOR SHARE OF session, turn
      FOR UPDATE OF attempt;
      IF authority_subject_id IS NULL
        OR length(btrim(authority_subject_id)) NOT BETWEEN 1 AND 1024
      THEN
        RAISE EXCEPTION 'preference snapshot requires an immutable initiating human'
          USING ERRCODE = '42501';
      END IF;

      PERFORM set_config('opengeni.subject_id', authority_subject_id, true);
      IF NULLIF(current_setting('opengeni.subject_id', true), '')
        IS DISTINCT FROM authority_subject_id
      THEN
        RAISE EXCEPTION 'preference snapshot human authority was not applied'
          USING ERRCODE = '42501';
      END IF;

      SELECT snapshot.id INTO winner_id
      FROM preference_registry_snapshots snapshot
      WHERE snapshot.account_id = p_account_id
        AND snapshot.workspace_id = p_workspace_id
        AND snapshot.session_id = p_session_id
        AND snapshot.turn_id = p_turn_id
        AND snapshot.attempt_id = p_attempt_id
        AND snapshot.execution_generation = p_execution_generation
        AND snapshot.initiating_human_subject_id = authority_subject_id
      FOR SHARE;
      IF winner_id IS NOT NULL THEN
        IF EXISTS (
          SELECT 1
          FROM preference_registry_snapshots snapshot
          WHERE snapshot.id = winner_id
            AND (
              snapshot.created_at > transaction_timestamp()
              OR jsonb_typeof(snapshot.descriptors) <> 'array'
              OR jsonb_array_length(snapshot.descriptors) > 64
              OR octet_length(convert_to(snapshot.descriptors::text, 'UTF8')) > 16384
              OR snapshot.descriptor_hash IS DISTINCT FROM encode(
                sha256(convert_to(snapshot.descriptors::text, 'UTF8')),
                'hex'
              )
            )
        ) THEN
          RAISE EXCEPTION 'existing preference snapshot failed canonical integrity checks'
            USING ERRCODE = '23514';
        END IF;
        RETURN QUERY
        SELECT snapshot.*
        FROM preference_registry_snapshots snapshot
        WHERE snapshot.id = winner_id;
        RETURN;
      END IF;

      SELECT result.canonical_descriptors, result.canonical_truncated
        INTO canonical_descriptors, canonical_truncated
      FROM preference_registry_accepted_snapshot_for_recovery(
        p_account_id,
        p_workspace_id,
        p_session_id,
        p_turn_id,
        p_execution_generation,
        authority_subject_id,
        turn_accepted_at
      ) result;
      canonical_hash := encode(
        sha256(convert_to(canonical_descriptors::text, 'UTF8')),
        'hex'
      );

      INSERT INTO preference_registry_snapshots (
        account_id,
        workspace_id,
        session_id,
        turn_id,
        attempt_id,
        execution_generation,
        initiating_human_subject_id,
        descriptors,
        descriptor_hash,
        truncated,
        created_at
      ) VALUES (
        p_account_id,
        p_workspace_id,
        p_session_id,
        p_turn_id,
        p_attempt_id,
        p_execution_generation,
        authority_subject_id,
        canonical_descriptors,
        canonical_hash,
        canonical_truncated,
        snapshot_time
      )
      ON CONFLICT (account_id, workspace_id, attempt_id) DO NOTHING
      RETURNING id INTO winner_id;
      IF winner_id IS NULL THEN
        SELECT snapshot.id INTO winner_id
        FROM preference_registry_snapshots snapshot
        WHERE snapshot.account_id = p_account_id
          AND snapshot.workspace_id = p_workspace_id
          AND snapshot.session_id = p_session_id
          AND snapshot.turn_id = p_turn_id
          AND snapshot.attempt_id = p_attempt_id
          AND snapshot.execution_generation = p_execution_generation
          AND snapshot.initiating_human_subject_id = authority_subject_id
        FOR SHARE;
      END IF;
      IF winner_id IS NULL THEN
        RAISE EXCEPTION 'preference snapshot winner conflicts with exact attempt authority'
          USING ERRCODE = '40001';
      END IF;
      IF EXISTS (
        SELECT 1
        FROM preference_registry_snapshots snapshot
        WHERE snapshot.id = winner_id
          AND (
            snapshot.descriptors IS DISTINCT FROM canonical_descriptors
            OR snapshot.descriptor_hash IS DISTINCT FROM canonical_hash
            OR snapshot.truncated IS DISTINCT FROM canonical_truncated
            OR snapshot.created_at IS DISTINCT FROM snapshot_time
          )
      ) THEN
        RAISE EXCEPTION 'preference snapshot winner is not the canonical accepted-turn snapshot'
          USING ERRCODE = '40001';
      END IF;
      RETURN QUERY
      SELECT snapshot.*
      FROM preference_registry_snapshots snapshot
      WHERE snapshot.id = winner_id;
    END
    $$;

CREATE FUNCTION preference_registry_guard_head_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE lifecycle_operation text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'preference registry heads cannot be deleted'
      USING ERRCODE = '55000';
  END IF;
  IF current_setting('opengeni.preference_lifecycle_head_id', true)
      IS DISTINCT FROM NEW.id::text THEN
    RAISE EXCEPTION 'preference registry heads change only through the lifecycle function'
      USING ERRCODE = '55000';
  END IF;
  lifecycle_operation := current_setting('opengeni.preference_lifecycle_operation', true);
  IF NEW.id IS DISTINCT FROM OLD.id
    OR NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.stable_key IS DISTINCT FROM OLD.stable_key
    OR NEW.created_by_subject_id IS DISTINCT FROM OLD.created_by_subject_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'preference registry stable identity is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF lifecycle_operation IN ('activate', 'correct') THEN
    IF NEW.status <> 'active'
      OR NEW.active_revision_id IS NULL
      OR NEW.activation_version <> OLD.activation_version + 1
      OR NEW.scope_version <> OLD.scope_version
      OR ROW(NEW.scope, NEW.scope_workspace_id, NEW.scope_subject_id)
        IS DISTINCT FROM ROW(OLD.scope, OLD.scope_workspace_id, OLD.scope_subject_id)
      OR NEW.superseded_by_preference_id IS DISTINCT FROM OLD.superseded_by_preference_id
    THEN
      RAISE EXCEPTION 'invalid preference activation transition'
        USING ERRCODE = '23514';
    END IF;
  ELSIF lifecycle_operation = 'reject' THEN
    IF OLD.status <> 'proposed' OR NEW.status <> 'rejected'
      OR NEW.scope_version <> OLD.scope_version
      OR NEW.activation_version <> OLD.activation_version
      OR ROW(NEW.scope, NEW.scope_workspace_id, NEW.scope_subject_id)
        IS DISTINCT FROM ROW(OLD.scope, OLD.scope_workspace_id, OLD.scope_subject_id)
      OR ROW(NEW.active_revision_id, NEW.active_revision, NEW.active_content_hash)
        IS DISTINCT FROM ROW(OLD.active_revision_id, OLD.active_revision, OLD.active_content_hash)
      OR NEW.superseded_by_preference_id IS DISTINCT FROM OLD.superseded_by_preference_id
    THEN
      RAISE EXCEPTION 'invalid preference rejection transition'
        USING ERRCODE = '23514';
    END IF;
  ELSIF lifecycle_operation = 'deactivate' THEN
    IF OLD.status <> 'active' OR NEW.status <> 'inactive'
      OR OLD.active_revision_id IS NULL OR NEW.active_revision_id IS NOT NULL
      OR NEW.active_revision IS NOT NULL OR NEW.active_content_hash IS NOT NULL
      OR NEW.activation_version <> OLD.activation_version + 1
      OR NEW.scope_version <> OLD.scope_version
      OR ROW(NEW.scope, NEW.scope_workspace_id, NEW.scope_subject_id)
        IS DISTINCT FROM ROW(OLD.scope, OLD.scope_workspace_id, OLD.scope_subject_id)
      OR NEW.superseded_by_preference_id IS DISTINCT FROM OLD.superseded_by_preference_id
    THEN
      RAISE EXCEPTION 'invalid preference deactivation transition'
        USING ERRCODE = '23514';
    END IF;
  ELSIF lifecycle_operation = 'scope' THEN
    IF NEW.status IS DISTINCT FROM OLD.status
      OR NEW.scope = OLD.scope
      OR NEW.scope_version <> OLD.scope_version + 1
      OR NEW.activation_version <> OLD.activation_version
      OR ROW(NEW.active_revision_id, NEW.active_revision, NEW.active_content_hash)
        IS DISTINCT FROM ROW(OLD.active_revision_id, OLD.active_revision, OLD.active_content_hash)
      OR NEW.superseded_by_preference_id IS DISTINCT FROM OLD.superseded_by_preference_id
    THEN
      RAISE EXCEPTION 'invalid preference scope transition'
        USING ERRCODE = '23514';
    END IF;
  ELSIF lifecycle_operation = 'supersede' THEN
    IF OLD.status <> 'active' OR NEW.status <> 'superseded'
      OR NEW.superseded_by_preference_id IS NULL
      OR NEW.superseded_by_preference_id = OLD.id
      OR NEW.scope_version <> OLD.scope_version
      OR NEW.activation_version <> OLD.activation_version
      OR ROW(NEW.scope, NEW.scope_workspace_id, NEW.scope_subject_id)
        IS DISTINCT FROM ROW(OLD.scope, OLD.scope_workspace_id, OLD.scope_subject_id)
      OR ROW(NEW.active_revision_id, NEW.active_revision, NEW.active_content_hash)
        IS DISTINCT FROM ROW(OLD.active_revision_id, OLD.active_revision, OLD.active_content_hash)
    THEN
      RAISE EXCEPTION 'invalid preference supersession transition'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'preference registry lifecycle operation is invalid'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION preference_registry_lock_heads(p_preference_ids uuid[]) RETURNS TABLE(preference_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      context_account_id uuid;
      context_workspace_id uuid;
      context_subject_id text;
      requested_count integer;
      locked_count integer;
    BEGIN
      context_account_id := NULLIF(
        current_setting('opengeni.account_id', true), ''
      )::uuid;
      context_workspace_id := NULLIF(
        current_setting('opengeni.workspace_id', true), ''
      )::uuid;
      context_subject_id := NULLIF(
        current_setting('opengeni.subject_id', true), ''
      );
      SELECT count(DISTINCT requested_id) INTO requested_count
      FROM unnest(p_preference_ids) requested_id;
      IF context_account_id IS NULL OR context_workspace_id IS NULL
        OR context_subject_id IS NULL
        OR requested_count < 1 OR requested_count > 2
        OR requested_count <> cardinality(p_preference_ids)
      THEN
        RAISE EXCEPTION 'preference head lock requires exact transaction-local scope'
          USING ERRCODE = '42501';
      END IF;
      PERFORM 1
      FROM preference_registry_preferences candidate
      WHERE candidate.id = ANY(p_preference_ids)
        AND candidate.account_id = context_account_id
        AND opengeni_private.preference_registry_scope_visible(
          candidate.account_id,
          candidate.scope,
          candidate.scope_workspace_id,
          candidate.scope_subject_id
        )
      ORDER BY candidate.id
      FOR UPDATE;
      GET DIAGNOSTICS locked_count = ROW_COUNT;
      IF locked_count <> requested_count THEN
        RAISE EXCEPTION 'preference head was not found in the authorized scope'
          USING ERRCODE = '42501';
      END IF;
      RETURN QUERY
      SELECT candidate.id
      FROM preference_registry_preferences candidate
      WHERE candidate.id = ANY(p_preference_ids)
      ORDER BY candidate.id;
    END
    $$;

CREATE FUNCTION preference_registry_reject_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'preference registry history is immutable' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION preference_registry_require_proposal_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM preference_registry_events event
    WHERE event.account_id = NEW.account_id
      AND event.preference_id = NEW.id
      AND event.type = 'proposal_created'
      AND event.version = 1
      AND event.old_revision_id IS NULL
      AND event.new_revision_id IS NOT NULL
      AND event.old_scope IS NULL
      AND event.new_scope = NEW.scope
      AND event.new_workspace_id IS NOT DISTINCT FROM NEW.scope_workspace_id
      AND event.new_subject_id IS NOT DISTINCT FROM NEW.scope_subject_id
  ) THEN
    RAISE EXCEPTION 'preference proposal requires an exact immutable creation event'
      USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;

CREATE FUNCTION preference_registry_validate_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.active_revision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM preference_registry_revisions revision
    WHERE revision.id = NEW.active_revision_id
      AND revision.preference_id = NEW.id
      AND revision.account_id = NEW.account_id
      AND revision.revision = NEW.active_revision
      AND revision.content_hash = NEW.active_content_hash
  ) THEN
    RAISE EXCEPTION 'preference registry head must identify an exact immutable revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION preference_registry_validate_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  authority_subject_id text;
  turn_accepted_at timestamptz;
  expected_descriptors jsonb;
  expected_truncated boolean;
BEGIN
  SELECT
    coalesce(
      turn.initiating_human_subject_id,
      CASE WHEN turn.initiator_kind = 'subject' THEN turn.initiator_subject_id END
    ),
    turn.created_at
    INTO authority_subject_id, turn_accepted_at
  FROM session_turn_attempts attempt
  JOIN session_turns turn
    ON turn.account_id = attempt.account_id
    AND turn.workspace_id = attempt.workspace_id
    AND turn.session_id = attempt.session_id
    AND turn.id = attempt.turn_id
  JOIN sessions session
    ON session.account_id = attempt.account_id
    AND session.workspace_id = attempt.workspace_id
    AND session.id = attempt.session_id
  WHERE attempt.id = NEW.attempt_id
    AND attempt.account_id = NEW.account_id
    AND attempt.workspace_id = NEW.workspace_id
    AND attempt.session_id = NEW.session_id
    AND attempt.turn_id = NEW.turn_id
    AND attempt.execution_generation = NEW.execution_generation
    AND turn.execution_generation = NEW.execution_generation
    AND attempt.state IN ('claimed', 'running')
    AND turn.active_attempt_id = attempt.id
    AND session.active_turn_id = turn.id
    AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
    AND NOT EXISTS (
      SELECT 1
      FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = NEW.workspace_id
        AND interruption.attempt_id = NEW.attempt_id
        AND interruption.state IN ('pending', 'delivered', 'acknowledged')
    );
  IF authority_subject_id IS NULL
    OR length(btrim(authority_subject_id)) NOT BETWEEN 1 AND 1024
    OR NEW.initiating_human_subject_id IS DISTINCT FROM authority_subject_id
  THEN
    RAISE EXCEPTION 'preference snapshot requires exact immutable initiating-human authority'
      USING ERRCODE = '23514';
  END IF;

  SELECT result.canonical_descriptors, result.canonical_truncated
    INTO expected_descriptors, expected_truncated
  FROM preference_registry_accepted_snapshot_for_recovery(
    NEW.account_id,
    NEW.workspace_id,
    NEW.session_id,
    NEW.turn_id,
    NEW.execution_generation,
    authority_subject_id,
    turn_accepted_at
  ) result;

  IF NEW.descriptors IS DISTINCT FROM expected_descriptors
    OR NEW.truncated IS DISTINCT FROM expected_truncated
    OR NEW.descriptor_hash IS DISTINCT FROM encode(
      sha256(convert_to(expected_descriptors::text, 'UTF8')),
      'hex'
    )
  THEN
    RAISE EXCEPTION 'preference snapshot is not the canonical accepted-turn descriptor set'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION preflight_organization_user_setup(p_token_digest text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  setup organization_user_setup_intents%ROWTYPE;
  invitation organization_membership_invitations%ROWTYPE;
  normalized_email text;
BEGIN
  -- This is deliberately a cheap, non-consuming eligibility read. The final
  -- lifecycle repeats every check under the canonical email/organization
  -- locks and remains the only authority that creates or consumes anything.
  IF p_token_digest IS NULL OR p_token_digest !~ '^[0-9a-f]{64}$' THEN
    RETURN 'unavailable';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO setup FROM organization_user_setup_intents candidate
  WHERE candidate.token_digest = p_token_digest;
  IF NOT FOUND THEN
    RETURN 'unavailable';
  END IF;
  IF setup.status = 'completed' THEN
    RETURN 'completed';
  END IF;
  SELECT * INTO invitation FROM organization_membership_invitations candidate
  WHERE candidate.account_id = setup.account_id
    AND candidate.id = setup.invitation_id;
  IF NOT FOUND
    OR invitation.status <> 'pending'
    OR invitation.expires_at <= pg_catalog.clock_timestamp()
    OR setup.expires_at <= pg_catalog.clock_timestamp()
    OR invitation.expires_at IS DISTINCT FROM setup.expires_at
  THEN
    RETURN 'unavailable';
  END IF;
  normalized_email := lower(btrim(invitation.target_email));
  IF EXISTS (
    SELECT 1 FROM auth_users auth_user
    WHERE lower(btrim(auth_user.email)) = normalized_email
  ) THEN
    RETURN 'unavailable';
  END IF;
  RETURN 'pending';
END
$_$;

COMMENT ON FUNCTION preflight_organization_user_setup(p_token_digest text) IS 'Performs a cheap non-consuming setup-bearer eligibility read before password hashing; final completion revalidates atomically.';

CREATE FUNCTION prepare_external_workspace_membership_operation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  account_value uuid := (p_command ->> 'organizationId')::uuid;
  workspace_value uuid := (p_command ->> 'workspaceId')::uuid;
  operation_value uuid := (p_command ->> 'operationId')::uuid;
  actor_value text := p_command ->> 'actorSubjectId';
  action_value text := p_command ->> 'action';
  cancelled_value uuid := (p_command ->> 'cancelGrantOperationId')::uuid;
  service_permissions jsonb; identity_value jsonb; prior record; cancellation record;
  hash_value text; previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
BEGIN
  IF account_value IS NULL OR workspace_value IS NULL OR operation_value IS NULL
    OR action_value IS NULL OR action_value NOT IN ('grant','revoke','update')
    OR (action_value = 'revoke' AND (cancelled_value IS NULL OR cancelled_value = operation_value))
    OR (action_value IN ('grant','update') AND cancelled_value IS NOT NULL)
    OR (action_value = 'update' AND (p_command ->> 'membershipId') IS NULL)
  THEN RAISE EXCEPTION 'invalid external workspace operation' USING ERRCODE = '22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || account_value::text, 0));
  service_permissions := opengeni_private.external_workspace_service_permissions(account_value, actor_value);
  IF action_value IN ('grant','update') AND (jsonb_typeof(p_command -> 'permissions') IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_command -> 'permissions') = 0
    OR ((p_command -> 'permissions') ? 'secrets:read' AND NOT service_permissions ? 'secrets:read')
    OR (NOT service_permissions ? 'workspace:admin' AND NOT (p_command -> 'permissions') <@ service_permissions))
  THEN RAISE EXCEPTION 'external grant exceeds service authority' USING ERRCODE = '42501'; END IF;
  PERFORM 1 FROM workspaces w WHERE w.account_id = account_value AND w.id = workspace_value FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  IF EXISTS (SELECT 1 FROM organization_memberships m WHERE m.account_id = account_value AND m.personal_workspace_id = workspace_value)
  THEN RAISE EXCEPTION 'personal workspace is not administrable' USING ERRCODE = '42501'; END IF;
  -- Credential identity is audit attribution, not the operation's semantic
  -- identity: an authorized replacement organization key may reconcile it.
  hash_value := encode(sha256(convert_to((p_command - 'actorSubjectId')::text, 'UTF8')), 'hex');
  SELECT * INTO prior FROM organization_workspace_operation_receipts
    WHERE account_id = account_value AND operation_id = operation_value;
  IF FOUND AND (prior.action <> action_value OR prior.input_hash <> hash_value)
  THEN RAISE EXCEPTION 'operation identity reused' USING ERRCODE = '23505'; END IF;
  IF action_value = 'grant' THEN
    SELECT * INTO cancellation FROM organization_workspace_operation_receipts
      WHERE account_id = account_value AND action = 'revoke'
        AND result ->> 'fencedGrantOperationId' = operation_value::text LIMIT 1;
    IF FOUND THEN RAISE EXCEPTION 'external membership grant cancelled' USING ERRCODE = '55000'; END IF;
  END IF;
  IF prior.operation_id IS NOT NULL THEN
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
    RETURN jsonb_build_object('replay', true, 'result', prior.result);
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'external_identity_provisioning', true);
  IF action_value = 'grant' THEN
    identity_value := ensure_external_identity(account_value, p_command #>> '{identity,source}', p_command #>> '{identity,externalId}');
  ELSE
    SELECT jsonb_build_object('subjectId', i.subject_id, 'organizationMembershipId', i.organization_membership_id)
      INTO identity_value FROM external_identities i
      WHERE i.account_id = account_value AND i.organization_membership_id = (p_command ->> 'membershipId')::uuid;
    IF identity_value IS NULL THEN RAISE EXCEPTION 'external member not found' USING ERRCODE = 'P0002'; END IF;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
    IF action_value = 'revoke' THEN
      SELECT * INTO prior FROM organization_workspace_operation_receipts
        WHERE account_id = account_value AND operation_id = cancelled_value;
      IF FOUND AND (prior.action <> 'grant' OR prior.result ->> 'workspaceId' IS DISTINCT FROM workspace_value::text
        OR prior.result #>> '{identity,organizationMembershipId}' IS DISTINCT FROM identity_value ->> 'organizationMembershipId')
      THEN RAISE EXCEPTION 'cancelled operation target mismatch' USING ERRCODE = '23505'; END IF;
    END IF;
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  RETURN jsonb_build_object('replay', false, 'identity', identity_value);
END $$;

CREATE FUNCTION prepare_organization_membership_protocol_settlements(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  action_name text := p_command ->> 'action';
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  target_id uuid := nullif(p_command ->> 'membershipId', '')::uuid;
  expected_revision bigint := nullif(
    p_command ->> 'expectedAuthorizationRevision', ''
  )::bigint;
  input_hash_value text;
  service_authorized boolean := false;
  receipt_row organization_membership_operation_receipts%ROWTYPE;
  actor organization_memberships%ROWTYPE;
  target organization_memberships%ROWTYPE;
  workspace_id_value uuid;
  result jsonb := '[]'::jsonb;
  previous_workspace text := pg_catalog.current_setting('opengeni.workspace_id', true);
BEGIN
  IF p_command IS NULL
    OR action_name NOT IN ('suspend', 'offboard')
    OR account_id_value IS NULL
    OR operation_id_value IS NULL
    OR target_id IS NULL
    OR expected_revision IS NULL
    OR actor_subject IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization membership protocol preparation authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  service_authorized := opengeni_private.external_membership_service_authority(p_command);
  input_hash_value := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(p_command::text, 'UTF8')), 'hex'
  );
  -- Lock-order repair: the organization fence is an advisory lock, not a row lock.
  -- `FOR UPDATE` on managed_accounts conflicts with the FK `FOR KEY SHARE`
  -- every ordinary workspace writer takes, and this seam reaches for
  -- `workspaces` afterwards, so holding it inverted the canonical order.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  ));
  PERFORM acquire_organization_session_tenancy_fences(
    account_id_value
  );
  PERFORM 1 FROM managed_accounts account
  WHERE account.id = account_id_value FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO receipt_row
  FROM organization_membership_operation_receipts receipt
  WHERE receipt.account_id = account_id_value
    AND receipt.operation_id = operation_id_value
  FOR UPDATE;
  IF FOUND THEN
    IF receipt_row.action IS DISTINCT FROM action_name
      OR receipt_row.input_hash IS DISTINCT FROM input_hash_value
    THEN
      RAISE EXCEPTION 'organization operation id was reused with different input'
        USING ERRCODE = '23505';
    END IF;
    RETURN result;
  END IF;
  FOR workspace_id_value IN
    SELECT workspace.id FROM workspaces workspace
    WHERE workspace.account_id = account_id_value ORDER BY workspace.id
  LOOP
    PERFORM pg_catalog.set_config(
      'opengeni.workspace_id', workspace_id_value::text, true
    );
    PERFORM 1 FROM workspace_inference_controls control
    WHERE control.account_id = account_id_value
      AND control.workspace_id = workspace_id_value
    FOR SHARE;
    PERFORM 1 FROM workspaces workspace
    WHERE workspace.account_id = account_id_value
      AND workspace.id = workspace_id_value
    FOR KEY SHARE;
  END LOOP;
  PERFORM 1 FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.id IN (
      target_id,
      (
        SELECT candidate.id FROM organization_memberships candidate
        WHERE candidate.account_id = account_id_value
          AND candidate.subject_id = actor_subject
      )
    )
  ORDER BY membership.id
  FOR UPDATE;
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.subject_id = actor_subject;
  SELECT * INTO target FROM organization_memberships membership
  WHERE membership.account_id = account_id_value AND membership.id = target_id;
  IF NOT service_authorized AND (actor.id IS NULL OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin')) THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  IF target.id IS NULL THEN
    RAISE EXCEPTION 'organization member not found' USING ERRCODE = 'P0002';
  END IF;
  IF target.authorization_revision IS DISTINCT FROM expected_revision THEN
    RAISE EXCEPTION 'organization membership revision is stale' USING ERRCODE = '40001';
  END IF;
  IF actor.role = 'admin' AND target.role <> 'member' THEN
    RAISE EXCEPTION 'administrators may manage members only' USING ERRCODE = '42501';
  END IF;
  IF action_name = 'suspend' AND target.status <> 'active' THEN
    RAISE EXCEPTION 'only an active member can be suspended' USING ERRCODE = '55000';
  ELSIF action_name = 'offboard' AND target.status NOT IN ('active', 'suspended') THEN
    RAISE EXCEPTION 'only an active or suspended member can be offboarded'
      USING ERRCODE = '55000';
  END IF;
  IF target.role = 'owner' AND NOT EXISTS (
    SELECT 1 FROM organization_memberships other
    WHERE other.account_id = account_id_value AND other.id <> target.id
      AND other.status = 'active' AND other.role = 'owner'
  ) THEN
    RAISE EXCEPTION 'cannot remove the last active organization owner'
      USING ERRCODE = '55000';
  END IF;
  FOR workspace_id_value IN
    SELECT workspace.id FROM workspaces workspace
    WHERE workspace.account_id = account_id_value ORDER BY workspace.id
  LOOP
    PERFORM pg_catalog.set_config(
      'opengeni.workspace_id', workspace_id_value::text, true
    );
    PERFORM 1 FROM sessions affected
    WHERE affected.account_id = account_id_value
      AND affected.workspace_id = workspace_id_value
      AND (
        affected.owner_organization_membership_id = target.id
        OR EXISTS (
          SELECT 1 FROM session_turns initiated
          WHERE initiated.session_id = affected.id
            AND initiated.initiating_human_subject_id = target.subject_id
        )
      )
    ORDER BY affected.id
    FOR NO KEY UPDATE;
    PERFORM 1 FROM session_turns turn_row
    WHERE turn_row.account_id = account_id_value
      AND turn_row.workspace_id = workspace_id_value
      AND EXISTS (
        SELECT 1 FROM sessions owned
        WHERE owned.id = turn_row.session_id
          AND (
            owned.owner_organization_membership_id = target.id
            OR turn_row.initiating_human_subject_id = target.subject_id
          )
      )
    ORDER BY turn_row.id
    FOR UPDATE;
    PERFORM 1 FROM session_turn_attempts attempt
    WHERE attempt.account_id = account_id_value
      AND attempt.workspace_id = workspace_id_value
      AND EXISTS (
        SELECT 1 FROM sessions owned
        WHERE owned.id = attempt.session_id
          AND (
            owned.owner_organization_membership_id = target.id
            OR EXISTS (
              SELECT 1 FROM session_turns initiated
              WHERE initiated.id = attempt.turn_id
                AND initiated.initiating_human_subject_id = target.subject_id
            )
          )
      )
    ORDER BY attempt.id
    FOR UPDATE;
    SELECT result || COALESCE(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'accountId', turn_row.account_id,
          'workspaceId', turn_row.workspace_id,
          'sessionId', turn_row.session_id,
          'turnId', turn_row.id,
          'executionGeneration', turn_row.execution_generation,
          'turnAssociation', CASE WHEN owned.active_turn_id = turn_row.id
            THEN 'current' ELSE NULL END
        ) ORDER BY turn_row.session_id, turn_row.id
      ), '[]'::jsonb
    ) INTO result
    FROM session_turns turn_row
    JOIN sessions owned ON owned.id = turn_row.session_id
    WHERE turn_row.account_id = account_id_value
      AND turn_row.workspace_id = workspace_id_value
      AND turn_row.status IN (
        'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
      )
      AND (
        owned.owner_organization_membership_id = target.id
        OR turn_row.initiating_human_subject_id = target.subject_id
      )
      AND EXISTS (
        SELECT 1 FROM session_pending_tool_calls pending
        WHERE pending.account_id = turn_row.account_id
          AND pending.workspace_id = turn_row.workspace_id
          AND pending.session_id = turn_row.session_id
          AND pending.turn_id = turn_row.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM session_turn_attempts live_attempt
        WHERE live_attempt.account_id = turn_row.account_id
          AND live_attempt.workspace_id = turn_row.workspace_id
          AND live_attempt.session_id = turn_row.session_id
          AND live_attempt.turn_id = turn_row.id
          AND live_attempt.id = turn_row.active_attempt_id
          AND live_attempt.state IN ('claimed', 'running')
      );
  END LOOP;
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', COALESCE(previous_workspace, ''), true
  );
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', COALESCE(previous_workspace, ''), true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION prepare_organization_membership_protocol_settlements(p_command jsonb) IS 'Locks the exact turns whose pending protocol state a suspend/offboard must settle. Lock order: advisory organization fence (hashtextextended(''organization-membership:<organization id>'')) -> managed_accounts FOR KEY SHARE -> per-workspace workspace_inference_controls FOR SHARE + workspaces FOR KEY SHARE -> organization_memberships FOR UPDATE -> sessions FOR NO KEY UPDATE -> session_turns FOR UPDATE -> session_turn_attempts FOR UPDATE. Never take a conflicting row lock on managed_accounts here: ordinary workspace writers reach that row through an FK FOR KEY SHARE check while already holding their workspaces row.';

CREATE FUNCTION prepare_organization_recovery_notifications(p_provider text, p_claim_owner text, p_limit integer, p_lease_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  stale_ids uuid[];
  candidate_ids uuid[];
  now_value timestamptz := pg_catalog.clock_timestamp();
  previous_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
BEGIN
  -- The next statement must observe a claimant or settler that committed before
  -- this transaction acquired the immutable outbox row. Snapshot-isolated
  -- transactions cannot refresh that evidence and must not dispatch a payload.
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'organization recovery notification claims require READ COMMITTED isolation'
      USING ERRCODE = '25001';
  END IF;
  IF p_provider IS NULL OR p_provider <> lower(btrim(p_provider))
    OR length(p_provider) NOT BETWEEN 1 AND 64
    OR p_claim_owner IS NULL OR length(btrim(p_claim_owner)) NOT BETWEEN 1 AND 256
    OR p_limit NOT BETWEEN 1 AND 100
    OR p_lease_seconds NOT BETWEEN 15 AND 300
  THEN
    RAISE EXCEPTION 'organization recovery notification claim is invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);

  -- A provider_started lease is not silently forgotten. Its expiry is immutable
  -- evidence that the payload was handed to a dispatcher but was not recorded
  -- as called; the stable provider idempotency key remains unchanged on reclaim.
  -- Retain row custody before consulting delivery evidence with a fresh snapshot.
  WITH stale AS (
    SELECT outbox.id, started.delivery_id, started.provider, started.claim_owner,
      started.attempt_number, started.lease_expires_at
    FROM organization_recovery_notification_outbox outbox
    INNER JOIN LATERAL (
      SELECT attempt.*
      FROM organization_recovery_notification_attempts attempt
      WHERE attempt.outbox_id = outbox.id AND attempt.phase = 'provider_started'
      ORDER BY attempt.attempt_number DESC, attempt.created_at DESC, attempt.id DESC
      LIMIT 1
    ) started ON true
    WHERE started.lease_expires_at <= now_value
      AND NOT EXISTS (
        SELECT 1 FROM organization_recovery_notification_attempts terminal
        WHERE terminal.outbox_id = outbox.id
          AND terminal.delivery_id = started.delivery_id
          AND terminal.phase IN ('sent', 'failed', 'outcome_unknown', 'claim_expired')
      )
    ORDER BY outbox.created_at, outbox.id
    LIMIT p_limit
    FOR UPDATE OF outbox SKIP LOCKED
  )
  SELECT coalesce(pg_catalog.array_agg(id), ARRAY[]::uuid[]) INTO stale_ids
  FROM stale;

  WITH stale AS (
    SELECT outbox.id, started.delivery_id, started.provider, started.claim_owner,
      started.attempt_number, started.lease_expires_at
    FROM organization_recovery_notification_outbox outbox
    INNER JOIN LATERAL (
      SELECT attempt.*
      FROM organization_recovery_notification_attempts attempt
      WHERE attempt.outbox_id = outbox.id AND attempt.phase = 'provider_started'
      ORDER BY attempt.attempt_number DESC, attempt.created_at DESC, attempt.id DESC
      LIMIT 1
    ) started ON true
    WHERE outbox.id = ANY(stale_ids)
      AND started.lease_expires_at <= now_value
      AND NOT EXISTS (
        SELECT 1 FROM organization_recovery_notification_attempts terminal
        WHERE terminal.outbox_id = outbox.id
          AND terminal.delivery_id = started.delivery_id
          AND terminal.phase IN ('sent', 'failed', 'outcome_unknown', 'claim_expired')
      )
    ORDER BY outbox.created_at, outbox.id
    LIMIT p_limit
    FOR UPDATE OF outbox SKIP LOCKED
  )
  INSERT INTO organization_recovery_notification_attempts (
    outbox_id, delivery_id, provider, claim_owner, attempt_number,
    lease_expires_at, phase, created_at
  ) SELECT
    stale.id, stale.delivery_id, stale.provider, stale.claim_owner,
    stale.attempt_number, stale.lease_expires_at, 'claim_expired', now_value
  FROM stale
  ON CONFLICT (outbox_id, delivery_id, phase) DO NOTHING;

  -- An unchanged outbox row does not cause PostgreSQL to refresh an old
  -- statement snapshot after its previous lock holder commits. Lock first.
  WITH candidates AS (
    SELECT outbox.id
    FROM organization_recovery_notification_outbox outbox
    LEFT JOIN LATERAL (
      SELECT attempt.phase, attempt.attempt_number, attempt.created_at
      FROM organization_recovery_notification_attempts attempt
      WHERE attempt.outbox_id = outbox.id
      ORDER BY attempt.created_at DESC, attempt.id DESC
      LIMIT 1
    ) latest ON true
    WHERE NOT EXISTS (
      SELECT 1 FROM organization_recovery_notification_attempts attempt
      WHERE attempt.outbox_id = outbox.id
        AND attempt.phase IN ('sent', 'reconciled_sent')
    )
      AND NOT EXISTS (
        SELECT 1 FROM organization_recovery_notification_attempts ambiguous
        WHERE ambiguous.outbox_id = outbox.id AND ambiguous.phase = 'outcome_unknown'
          AND NOT EXISTS (
            SELECT 1 FROM organization_recovery_notification_attempts reconciliation
            WHERE reconciliation.outbox_id = ambiguous.outbox_id
              AND reconciliation.delivery_id = ambiguous.delivery_id
              AND reconciliation.phase IN ('reconciled_sent', 'reconciled_retry')
          )
      )
      AND NOT EXISTS (
        SELECT 1 FROM organization_recovery_notification_attempts started
        WHERE started.outbox_id = outbox.id AND started.phase = 'provider_started'
          AND NOT EXISTS (
            SELECT 1 FROM organization_recovery_notification_attempts terminal
            WHERE terminal.outbox_id = started.outbox_id
              AND terminal.delivery_id = started.delivery_id
              AND terminal.phase IN ('sent', 'failed', 'outcome_unknown', 'claim_expired')
          )
      )
      AND (
        SELECT pg_catalog.count(*)
        FROM organization_recovery_notification_attempts started
        WHERE started.outbox_id = outbox.id AND started.phase = 'provider_started'
      ) < 5
      AND (
        latest.phase IS NULL
        OR latest.phase IN ('claim_expired', 'reconciled_retry')
        OR (
          latest.phase = 'failed'
          AND latest.created_at + pg_catalog.make_interval(
            secs => least(900, 60 * (2 ^ greatest(0, latest.attempt_number - 1))::integer)
          ) <= now_value
        )
      )
    ORDER BY outbox.created_at, outbox.id
    LIMIT p_limit FOR UPDATE OF outbox SKIP LOCKED
  )
  SELECT coalesce(pg_catalog.array_agg(id), ARRAY[]::uuid[]) INTO candidate_ids
  FROM candidates;

  WITH candidates AS (
    SELECT outbox.id
    FROM organization_recovery_notification_outbox outbox
    LEFT JOIN LATERAL (
      SELECT attempt.phase, attempt.attempt_number, attempt.created_at
      FROM organization_recovery_notification_attempts attempt
      WHERE attempt.outbox_id = outbox.id
      ORDER BY attempt.created_at DESC, attempt.id DESC
      LIMIT 1
    ) latest ON true
    WHERE outbox.id = ANY(candidate_ids)
      AND NOT EXISTS (
      SELECT 1 FROM organization_recovery_notification_attempts attempt
      WHERE attempt.outbox_id = outbox.id
        AND attempt.phase IN ('sent', 'reconciled_sent')
    )
      AND NOT EXISTS (
        SELECT 1 FROM organization_recovery_notification_attempts ambiguous
        WHERE ambiguous.outbox_id = outbox.id AND ambiguous.phase = 'outcome_unknown'
          AND NOT EXISTS (
            SELECT 1 FROM organization_recovery_notification_attempts reconciliation
            WHERE reconciliation.outbox_id = ambiguous.outbox_id
              AND reconciliation.delivery_id = ambiguous.delivery_id
              AND reconciliation.phase IN ('reconciled_sent', 'reconciled_retry')
          )
      )
      AND NOT EXISTS (
        SELECT 1 FROM organization_recovery_notification_attempts started
        WHERE started.outbox_id = outbox.id AND started.phase = 'provider_started'
          AND NOT EXISTS (
            SELECT 1 FROM organization_recovery_notification_attempts terminal
            WHERE terminal.outbox_id = started.outbox_id
              AND terminal.delivery_id = started.delivery_id
              AND terminal.phase IN ('sent', 'failed', 'outcome_unknown', 'claim_expired')
          )
      )
      AND (
        SELECT pg_catalog.count(*)
        FROM organization_recovery_notification_attempts started
        WHERE started.outbox_id = outbox.id AND started.phase = 'provider_started'
      ) < 5
      AND (
        latest.phase IS NULL
        OR latest.phase IN ('claim_expired', 'reconciled_retry')
        OR (
          latest.phase = 'failed'
          AND latest.created_at + pg_catalog.make_interval(
            secs => least(900, 60 * (2 ^ greatest(0, latest.attempt_number - 1))::integer)
          ) <= now_value
        )
      )
    ORDER BY outbox.created_at, outbox.id
    LIMIT p_limit FOR UPDATE OF outbox SKIP LOCKED
  ), started AS (
    INSERT INTO organization_recovery_notification_attempts (
      outbox_id, delivery_id, provider, claim_owner, attempt_number,
      lease_expires_at, phase, created_at
    )
    SELECT candidate.id, gen_random_uuid(), p_provider, p_claim_owner,
      1 + (
        SELECT pg_catalog.count(*)::integer
        FROM organization_recovery_notification_attempts prior
        WHERE prior.outbox_id = candidate.id AND prior.phase = 'provider_started'
      ), now_value + pg_catalog.make_interval(secs => p_lease_seconds),
      'provider_started', now_value
    FROM candidates candidate
    RETURNING id, outbox_id, delivery_id, provider, claim_owner,
      attempt_number, lease_expires_at, created_at
  )
  SELECT coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'attemptId', started.id::text,
      'outboxId', outbox.id::text,
      'deliveryId', started.delivery_id::text,
      'provider', started.provider,
      'claimOwner', started.claim_owner,
      'attemptNumber', started.attempt_number,
      'leaseExpiresAt', started.lease_expires_at,
      'idempotencyKey', outbox.idempotency_key,
      'recipientCanonicalIdentityId', outbox.recipient_identity_id::text,
      'notificationType', outbox.notification_type,
      'payloadDigest', outbox.payload_digest,
      'payload', outbox.payload
    ) ORDER BY outbox.created_at, outbox.id
  ), '[]'::jsonb) INTO result
  FROM started
  INNER JOIN organization_recovery_notification_outbox outbox
    ON outbox.id = started.outbox_id;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION prepare_organization_user_setup_delivery(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  delivery_id_value uuid := nullif(p_command ->> 'deliveryId', '')::uuid;
  attempt_id_value uuid := nullif(p_command ->> 'attemptId', '')::uuid;
  claim_holder_id_value uuid := nullif(p_command ->> 'claimHolderId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  token_digest_value text := p_command ->> 'tokenDigest';
  payload_digest_value text := p_command ->> 'payloadDigest';
  provider_idempotency_scope_value text := btrim(p_command ->> 'providerIdempotencyScope');
  provider_idempotency_retention_seconds_value integer :=
    nullif(p_command ->> 'providerIdempotencyRetentionSeconds', '')::integer;
  delivery organization_user_setup_deliveries%ROWTYPE;
  invitation organization_membership_invitations%ROWTYPE;
  setup organization_user_setup_intents%ROWTYPE;
  normalized_email text;
  account_id_value uuid;
  invitation_id_value uuid;
  now_value timestamptz := clock_timestamp();
BEGIN
  IF delivery_id_value IS NULL OR attempt_id_value IS NULL OR claim_holder_id_value IS NULL
    OR actor_subject IS NULL OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR token_digest_value !~ '^[0-9a-f]{64}$'
    OR payload_digest_value !~ '^[0-9a-f]{64}$'
    OR provider_idempotency_scope_value IS NULL
    OR provider_idempotency_scope_value !~ '^[a-z0-9][a-z0-9:._-]*$'
    OR octet_length(convert_to(provider_idempotency_scope_value, 'UTF8')) > 200
    OR provider_idempotency_retention_seconds_value IS NULL
    OR provider_idempotency_retention_seconds_value NOT BETWEEN 0 AND 31536000
  THEN
    RAISE EXCEPTION 'organization setup delivery preparation is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT recipient_email, account_id, invitation_id
  INTO normalized_email, account_id_value, invitation_id_value
  FROM organization_user_setup_deliveries WHERE id = delivery_id_value;
  IF normalized_email IS NULL THEN
    RAISE EXCEPTION 'organization setup delivery is unavailable' USING ERRCODE = 'P0002';
  END IF;
  IF account_id_value IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'organization setup delivery authority is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'organization-invitation-email:' || normalized_email, 0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  ));
  PERFORM 1 FROM managed_accounts account WHERE account.id = account_id_value FOR KEY SHARE;
  PERFORM 1 FROM organization_memberships membership
  WHERE membership.account_id = account_id_value AND membership.subject_id = actor_subject
    AND membership.status = 'active' AND membership.role IN ('owner', 'admin') FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO invitation FROM organization_membership_invitations candidate
  WHERE candidate.account_id = account_id_value AND candidate.id = invitation_id_value
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization invitation is unavailable' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO delivery FROM organization_user_setup_deliveries candidate
  WHERE candidate.account_id = account_id_value
    AND candidate.id = delivery_id_value
    AND candidate.invitation_id = invitation.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization setup delivery is unavailable' USING ERRCODE = 'P0002';
  END IF;
  IF delivery.state <> 'pending'
    OR delivery.claim_holder_id IS DISTINCT FROM claim_holder_id_value
    OR delivery.claim_expires_at <= now_value
    OR invitation.status <> 'pending'
    OR invitation.expires_at <= now_value
  THEN
    RAISE EXCEPTION 'organization setup delivery claim is unavailable' USING ERRCODE = '55000';
  END IF;
  PERFORM 1 FROM organization_user_setup_delivery_attempts attempt
  WHERE attempt.id = attempt_id_value AND attempt.delivery_id = delivery.id
    AND attempt.claim_holder_id = claim_holder_id_value AND attempt.result IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization setup delivery attempt is unavailable' USING ERRCODE = '55000';
  END IF;
  IF delivery.token_digest IS NOT NULL
    AND delivery.token_digest IS DISTINCT FROM token_digest_value
  THEN
    RAISE EXCEPTION 'organization setup bearer changed under retry' USING ERRCODE = '23505';
  END IF;
  IF delivery.provider_idempotency_scope IS NOT NULL
    AND delivery.provider_idempotency_scope IS DISTINCT FROM provider_idempotency_scope_value
  THEN
    RAISE EXCEPTION 'organization setup provider scope changed under retry'
      USING ERRCODE = '23505';
  END IF;
  IF delivery.payload_digest IS NOT NULL
    AND delivery.payload_digest IS DISTINCT FROM payload_digest_value
  THEN
    RAISE EXCEPTION 'organization setup payload changed under retry' USING ERRCODE = '23505';
  END IF;
  IF delivery.unresolved_provider_outcome_at IS NOT NULL
    AND (
      delivery.provider_retry_safe_until IS NULL
      OR delivery.provider_retry_safe_until <= now_value
    )
  THEN
    RAISE EXCEPTION 'organization setup delivery requires provider reconciliation'
      USING ERRCODE = '55000';
  END IF;
  -- The public 0348 seam remains creator-bound. A later active administrator
  -- may retry this creator-bound durable delivery, so create its immutable
  -- setup intent only after the invitation -> delivery -> attempt locks above.
  INSERT INTO organization_user_setup_intents (
    account_id, invitation_id, token_digest, expires_at
  ) VALUES (
    delivery.account_id, delivery.invitation_id, token_digest_value, invitation.expires_at
  ) ON CONFLICT (account_id, invitation_id) DO NOTHING;
  SELECT * INTO setup FROM organization_user_setup_intents candidate
  WHERE candidate.account_id = delivery.account_id
    AND candidate.invitation_id = delivery.invitation_id;
  IF NOT FOUND
    OR setup.token_digest IS DISTINCT FROM token_digest_value
    OR setup.expires_at IS DISTINCT FROM invitation.expires_at
  THEN
    RAISE EXCEPTION 'organization user setup intent changed under retry'
      USING ERRCODE = '23505';
  END IF;
  UPDATE organization_user_setup_deliveries SET
    setup_intent_id = setup.id,
    token_digest = token_digest_value,
    payload_digest = payload_digest_value,
    provider_idempotency_scope = coalesce(
      provider_idempotency_scope, provider_idempotency_scope_value
    ),
    provider_retry_safe_until = CASE
      WHEN unresolved_provider_outcome_at IS NULL
      THEN now_value + make_interval(secs => provider_idempotency_retention_seconds_value)
      ELSE provider_retry_safe_until
    END,
    provider_retry_window_started_at = CASE
      WHEN unresolved_provider_outcome_at IS NULL THEN now_value
      ELSE coalesce(provider_retry_window_started_at, now_value)
    END,
    provider_started_at = now_value,
    revision = revision + 1,
    updated_at = now_value
  WHERE id = delivery.id RETURNING * INTO delivery;
  UPDATE organization_user_setup_delivery_attempts SET provider_started_at = now_value
  WHERE id = attempt_id_value;
  RETURN jsonb_build_object(
    'providerKey', delivery.provider_key,
    'recipientEmail', delivery.recipient_email,
    'recipientName', delivery.recipient_name,
    'organizationName', delivery.organization_name,
    'organizationRole', delivery.organization_role,
    'sharedWorkspaceAccess', delivery.shared_workspace_access
  );
END
$_$;

CREATE FUNCTION prepare_organization_user_setup_delivery_v2(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  delivery_id_value uuid := nullif(p_command ->> 'deliveryId', '')::uuid;
  setup_token_transport_value text := p_command ->> 'setupTokenTransport';
  result jsonb;
  frozen_transport text;
BEGIN
  IF delivery_id_value IS NULL
    OR setup_token_transport_value IS NULL
    OR setup_token_transport_value NOT IN ('fragment', 'query')
  THEN
    RAISE EXCEPTION 'organization setup delivery transport preparation is invalid'
      USING ERRCODE = '42501';
  END IF;
  result := prepare_organization_user_setup_delivery(p_command);
  UPDATE organization_user_setup_deliveries SET
    setup_token_transport = coalesce(setup_token_transport, setup_token_transport_value)
  WHERE id = delivery_id_value
    AND (
      setup_token_transport IS NULL
      OR setup_token_transport = setup_token_transport_value
    )
  RETURNING setup_token_transport INTO frozen_transport;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization setup delivery transport changed under retry'
      USING ERRCODE = '23505';
  END IF;
  RETURN result || jsonb_build_object('setupTokenTransport', frozen_transport);
END
$$;

COMMENT ON FUNCTION prepare_organization_user_setup_delivery_v2(p_command jsonb) IS 'Prepares provider delivery and atomically freezes the setup-link transport.';

CREATE FUNCTION prepare_organization_workspace_member_removal(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  target_membership_id_value uuid := nullif(
    p_command ->> 'targetOrganizationMembershipId', ''
  )::uuid;
  target_subject text := p_command ->> 'targetSubjectId';
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  expected_updated_at_value timestamptz := nullif(
    p_command ->> 'expectedUpdatedAt', ''
  )::timestamptz;
  input_hash_value text;
  actor organization_memberships%ROWTYPE;
  target organization_memberships%ROWTYPE;
  access workspace_memberships%ROWTYPE;
  prior organization_workspace_operation_receipts%ROWTYPE;
BEGIN
  IF p_command IS NULL OR (p_command ->> 'action') IS DISTINCT FROM 'revoke'
    OR account_id_value IS NULL OR workspace_id_value IS NULL
    OR actor_subject IS NULL OR target_membership_id_value IS NULL
    OR target_subject IS NULL OR operation_id_value IS NULL
    OR expected_updated_at_value IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization workspace removal request is invalid'
      USING ERRCODE = '22023';
  END IF;
  input_hash_value := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(p_command::text, 'UTF8')), 'hex'
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('organization-membership:' || account_id_value::text, 0)
  );
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  PERFORM 1 FROM managed_accounts account
  WHERE account.id = account_id_value FOR KEY SHARE;
  PERFORM pg_catalog.set_config('opengeni.workspace_id', workspace_id_value::text, true);
  PERFORM 1 FROM workspace_inference_controls control
  WHERE control.account_id = account_id_value AND control.workspace_id = workspace_id_value
  FOR SHARE;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = account_id_value AND workspace.id = workspace_id_value
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM organization_memberships personal_owner
    WHERE personal_owner.account_id = account_id_value
      AND personal_owner.personal_workspace_id = workspace_id_value
  ) THEN
    RAISE EXCEPTION 'personal workspaces are not administrable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.subject_id = actor_subject
  FOR SHARE;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO prior FROM organization_workspace_operation_receipts receipt
  WHERE receipt.account_id = account_id_value
    AND receipt.operation_id = operation_id_value;
  IF FOUND THEN
    IF prior.action <> 'revoke' OR prior.input_hash IS DISTINCT FROM input_hash_value THEN
      RAISE EXCEPTION 'organization workspace operation key was reused'
        USING ERRCODE = '23505';
    END IF;
    RETURN prior.result || pg_catalog.jsonb_build_object('replay', true);
  END IF;
  SELECT * INTO target FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.id = target_membership_id_value
    AND membership.subject_id = target_subject
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization member not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO access FROM workspace_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.workspace_id = workspace_id_value
    AND membership.subject_id = target_subject
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'workspace access not found' USING ERRCODE = 'P0002';
  END IF;
  IF access.updated_at IS DISTINCT FROM expected_updated_at_value THEN
    RAISE EXCEPTION 'workspace access changed before removal' USING ERRCODE = '40001';
  END IF;
  RETURN pg_catalog.jsonb_build_object(
    'removed', false,
    'replay', false,
    'workspaceMembershipId', access.id,
    'actorMembershipId', actor.id
  );
END
$$;

CREATE FUNCTION prepare_scheduled_task_attempt_once_grants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  scheduled_run_id uuid;
  run_count integer;
  receipt_row record;
  prior_attempt_run_id uuid;
  affected integer;
BEGIN
  SELECT count(DISTINCT update_row.scheduled_task_run_id)::integer,
    min(update_row.scheduled_task_run_id::text)::uuid
  INTO run_count, scheduled_run_id
  FROM session_system_updates update_row
  WHERE update_row.workspace_id = NEW.workspace_id
    AND update_row.session_id = NEW.session_id
    AND update_row.delivered_turn_id = NEW.turn_id
    AND update_row.kind = 'scheduled_occurrence'
    AND update_row.scheduled_task_run_id IS NOT NULL;
  IF run_count = 0 THEN RETURN NEW; END IF;
  IF run_count <> 1 THEN
    RAISE EXCEPTION 'scheduled once-grant attempt requires one occurrence snapshot'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'attempt_match')
  ON CONFLICT DO NOTHING;

  FOR receipt_row IN
    SELECT receipt.*
    FROM scheduled_task_run_personal_resource_once_receipts receipt
    WHERE receipt.run_id = scheduled_run_id
    ORDER BY receipt.grant_id
    FOR UPDATE
  LOOP
    SELECT update_row.scheduled_task_run_id INTO prior_attempt_run_id
    FROM personal_resource_once_consumption_receipts attempt_receipt
    JOIN session_system_updates update_row
      ON update_row.workspace_id = attempt_receipt.workspace_id
     AND update_row.session_id = attempt_receipt.session_id
     AND update_row.delivered_turn_id = attempt_receipt.turn_id
     AND update_row.kind = 'scheduled_occurrence'
     AND update_row.scheduled_task_run_id IS NOT NULL
    WHERE attempt_receipt.grant_id = receipt_row.grant_id
      AND attempt_receipt.account_id = receipt_row.account_id
    LIMIT 1;
    IF FOUND AND prior_attempt_run_id IS DISTINCT FROM scheduled_run_id THEN
      RAISE EXCEPTION 'once grant is owned by another scheduled occurrence'
        USING ERRCODE = '42501';
    END IF;
    IF FOUND THEN
      DELETE FROM personal_resource_once_consumption_receipts
      WHERE grant_id = receipt_row.grant_id
        AND account_id = receipt_row.account_id;
    END IF;

    UPDATE organization_user_resource_grants grant_value
    SET status = 'active', updated_at = clock_timestamp()
    WHERE grant_value.id = receipt_row.grant_id
      AND grant_value.account_id = receipt_row.account_id
      AND grant_value.authority_id = receipt_row.authority_id
      AND grant_value.generation = receipt_row.grant_generation
      AND grant_value.status = 'consumed';
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected <> 1 THEN
      RAISE EXCEPTION 'scheduled occurrence once grant is no longer owned'
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'attempt_match';
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'attempt_match';
  RAISE;
END
$$;

CREATE FUNCTION prepare_session_attempt_personal_document_reads(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_attempt_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      session_row sessions%ROWTYPE;
      turn_row session_turns%ROWTYPE;
      attempt_row session_turn_attempts%ROWTYPE;
      member_row organization_memberships%ROWTYPE;
      document_row record;
      grant_row organization_user_resource_grants%ROWTYPE;
      existing_count integer;
      admitted_count integer := 0;
      initiating_subject text;
      affected integer;
    BEGIN
      INSERT INTO opengeni_private.personal_document_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'admit')
      ON CONFLICT DO NOTHING;

      SELECT attempt.* INTO STRICT attempt_row
      FROM session_turn_attempts attempt
      WHERE attempt.id = p_attempt_id
        AND attempt.account_id = p_account_id
        AND attempt.workspace_id = p_workspace_id
        AND attempt.session_id = p_session_id
      FOR UPDATE;
      SELECT session_value.* INTO STRICT session_row
      FROM sessions session_value
      WHERE session_value.id = attempt_row.session_id
        AND session_value.account_id = attempt_row.account_id
        AND session_value.workspace_id = attempt_row.workspace_id
      FOR SHARE;
      SELECT turn_value.* INTO STRICT turn_row
      FROM session_turns turn_value
      WHERE turn_value.id = attempt_row.turn_id
        AND turn_value.account_id = attempt_row.account_id
        AND turn_value.workspace_id = attempt_row.workspace_id
        AND turn_value.session_id = attempt_row.session_id
      FOR SHARE;

      IF attempt_row.execution_generation <= 0
        OR attempt_row.state NOT IN ('claimed', 'running')
        OR attempt_row.closed_at IS NOT NULL
        OR attempt_row.quiesced_at IS NOT NULL
        OR session_row.active_turn_id IS DISTINCT FROM attempt_row.turn_id
        OR turn_row.active_attempt_id IS DISTINCT FROM attempt_row.id
        OR turn_row.execution_generation IS DISTINCT FROM attempt_row.execution_generation
        OR turn_row.status <> 'running'
        OR NOT (attempt_row.authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
        OR EXISTS (
          SELECT 1 FROM session_attempt_interruptions interruption
          WHERE interruption.account_id = p_account_id
            AND interruption.workspace_id = p_workspace_id
            AND interruption.session_id = p_session_id
            AND interruption.attempt_id = p_attempt_id
            AND interruption.state IN ('pending', 'delivered', 'acknowledged')
        )
      THEN
        RAISE EXCEPTION 'personal document admission requires the exact current uninterrupted attempt'
          USING ERRCODE = '42501';
      END IF;

      initiating_subject := coalesce(
        nullif(btrim(turn_row.initiating_human_subject_id), ''),
        CASE WHEN turn_row.initiator_kind = 'subject'
          THEN nullif(btrim(turn_row.initiator_subject_id), '') END
      );
      IF initiating_subject IS NULL THEN
        DELETE FROM opengeni_private.personal_document_authority_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'admit';
        RETURN 0;
      END IF;

      SELECT membership.* INTO member_row
      FROM organization_memberships membership
      WHERE membership.account_id = p_account_id
        AND membership.subject_id = initiating_subject
        AND membership.status = 'active'
        AND membership.revoked_at IS NULL;

      IF NOT FOUND AND EXISTS (
        SELECT 1
        FROM organization_memberships membership
        WHERE membership.account_id = p_account_id
          AND membership.subject_id = initiating_subject
          AND membership.status = 'active'
          AND membership.revoked_at IS NULL
      ) THEN
        RAISE EXCEPTION 'personal document admission membership read was RLS-blinded'
          USING ERRCODE = '55000';
      END IF;
      IF NOT FOUND THEN
        DELETE FROM opengeni_private.personal_document_authority_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'admit';
        RETURN 0;
      END IF;
      IF member_row.personal_workspace_id IS DISTINCT FROM p_workspace_id THEN
        PERFORM 1 FROM workspace_memberships workspace_membership
        WHERE workspace_membership.account_id = p_account_id
          AND workspace_membership.workspace_id = p_workspace_id
          AND workspace_membership.subject_id = initiating_subject
        FOR KEY SHARE;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'initiating human lacks target-workspace membership'
            USING ERRCODE = '42501';
        END IF;
      END IF;

      SELECT admission.document_count INTO existing_count
      FROM session_attempt_personal_document_admissions admission
      WHERE admission.attempt_id = p_attempt_id;
      IF FOUND THEN
        DELETE FROM opengeni_private.personal_document_authority_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'admit';
        RETURN existing_count;
      END IF;

      INSERT INTO session_attempt_personal_document_admissions (
        attempt_id, account_id, workspace_id, session_id, turn_id,
        execution_generation, initiating_human_subject_id,
        owner_organization_membership_id, membership_authorization_revision,
        session_visibility, session_authority_epoch, document_count
      ) VALUES (
        p_attempt_id, p_account_id, p_workspace_id, p_session_id, attempt_row.turn_id,
        attempt_row.execution_generation, initiating_subject, member_row.id,
        member_row.authorization_revision, session_row.visibility,
        session_row.authority_epoch, 0
      ) ON CONFLICT (attempt_id) DO NOTHING;
      IF NOT FOUND THEN
        SELECT admission.document_count INTO STRICT existing_count
        FROM session_attempt_personal_document_admissions admission
        WHERE admission.attempt_id = p_attempt_id;
        DELETE FROM opengeni_private.personal_document_authority_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'admit';
        RETURN existing_count;
      END IF;

      FOR document_row IN
        SELECT document_value.id, document_value.authority_id,
          authority.generation AS authority_generation
        FROM documents document_value
        JOIN organization_user_resource_authorities authority
          ON authority.id = document_value.authority_id
         AND authority.account_id = document_value.account_id
         AND authority.organization_membership_id
           = document_value.owner_organization_membership_id
         AND authority.resource_kind = 'document'
         AND authority.resource_id = document_value.id
         AND authority.status = 'active'
         AND authority.revoked_at IS NULL
        WHERE document_value.account_id = p_account_id
          AND document_value.authority_kind = 'personal'
          AND document_value.authority_workspace_id IS NULL
          AND document_value.authority_subject_id = initiating_subject
          AND document_value.owner_organization_membership_id = member_row.id
          AND document_value.status = 'ready'
          AND document_value.agent_access = true
        ORDER BY document_value.id
      LOOP
        SELECT grant_value.* INTO grant_row
        FROM organization_user_resource_grants grant_value
        WHERE grant_value.account_id = p_account_id
          AND grant_value.authority_id = document_row.authority_id
          AND grant_value.owner_organization_membership_id = member_row.id
          AND grant_value.workspace_id = p_workspace_id
          AND grant_value.action = 'document.read'
          AND (grant_value.context = session_row.visibility OR (
      grant_value.context = 'user_private' AND session_row.visibility = 'workspace_shared'
      AND grant_value.mode IN ('once','session') AND grant_value.session_id = session_row.id
      AND (grant_value.authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)))
          AND grant_value.status = 'active'
          AND (grant_value.expires_at IS NULL OR grant_value.expires_at > clock_timestamp())
          AND (
            (
              grant_value.mode IN ('once', 'session')
              AND grant_value.session_id = p_session_id
              AND (grant_value.authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
            ) OR (
              grant_value.mode = 'always'
              AND grant_value.session_id IS NULL
              AND grant_value.authority_epoch IS NULL
            )
          )
        ORDER BY CASE grant_value.mode WHEN 'once' THEN 1 WHEN 'session' THEN 2 ELSE 3 END,
          grant_value.generation DESC, grant_value.id
        LIMIT 1
        FOR UPDATE;
        IF NOT FOUND THEN CONTINUE; END IF;

        INSERT INTO session_attempt_personal_document_snapshots (
          attempt_id, document_id, account_id, workspace_id, session_id, turn_id,
          execution_generation, owner_organization_membership_id,
          membership_authorization_revision, authority_id, authority_generation,
          target_workspace_id, session_visibility, session_authority_epoch,
          grant_id, grant_generation, grant_mode, grant_context,
          grant_session_id, grant_authority_epoch
        ) VALUES (
          p_attempt_id, document_row.id, p_account_id, p_workspace_id, p_session_id,
          attempt_row.turn_id, attempt_row.execution_generation, member_row.id,
          member_row.authorization_revision, document_row.authority_id,
          document_row.authority_generation, p_workspace_id, session_row.visibility,
          session_row.authority_epoch, grant_row.id, grant_row.generation,
          grant_row.mode, grant_row.context, grant_row.session_id,
          grant_row.authority_epoch
        );

        IF grant_row.mode = 'once' THEN
          UPDATE organization_user_resource_grants
          SET status = 'consumed', updated_at = clock_timestamp()
          WHERE id = grant_row.id AND account_id = p_account_id
            AND generation = grant_row.generation AND status = 'active';
          GET DIAGNOSTICS affected = ROW_COUNT;
          IF affected <> 1 THEN
            RAISE EXCEPTION 'once document grant lost its first-use race'
              USING ERRCODE = '40001';
          END IF;
          INSERT INTO personal_document_once_consumption_receipts (
            grant_id, account_id, attempt_id, document_id, authority_id,
            authority_generation, grant_generation
          ) VALUES (
            grant_row.id, p_account_id, p_attempt_id, document_row.id,
            document_row.authority_id, document_row.authority_generation,
            grant_row.generation
          );
        END IF;
        admitted_count := admitted_count + 1;
      END LOOP;

      UPDATE session_attempt_personal_document_admissions
      SET document_count = admitted_count
      WHERE attempt_id = p_attempt_id;

      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'admit';
      RETURN admitted_count;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'admit';
      RAISE;
    END
    $$;

COMMENT ON FUNCTION prepare_session_attempt_personal_document_reads(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_attempt_id uuid) IS 'Freezes exact-attempt personal Document reads; 0343 removes RLS-blind membership and portable-document row locks and fails loudly on definition or visibility drift.';

CREATE FUNCTION prepare_workspace_membership_removal_settlements(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE

  previous_membership_lifecycle text := pg_catalog.current_setting('opengeni.organization_tenancy_lifecycle', true);
  removal_fenced_access_id uuid;
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  target_subject text := p_command ->> 'targetSubjectId';
  target_membership_id uuid;
  result jsonb := '[]'::jsonb;
  previous_workspace text := pg_catalog.current_setting('opengeni.workspace_id', true);
BEGIN

  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  removal_fenced_access_id := opengeni_private.open_session_tenancy_fenced_access(session_tenancy_fence_target_schema());
  IF p_command IS NULL
    OR (p_command ->> 'action') IS DISTINCT FROM 'remove'
    OR account_id_value IS NULL
    OR workspace_id_value IS NULL
    OR actor_subject IS NULL
    OR target_subject IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'workspace membership removal preparation authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  )) THEN
    RAISE EXCEPTION 'workspace membership is changing; retry the transaction'
      USING ERRCODE = '55P03';
  END IF;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = account_id_value AND workspace.id = workspace_id_value;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM opengeni_private.assert_workspace_membership_removal_actor(
    account_id_value, workspace_id_value, actor_subject, target_subject
  );
  SELECT membership.id INTO target_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.subject_id = target_subject;

  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', workspace_id_value::text, true
  );
  PERFORM 1 FROM workspace_inference_controls control
  WHERE control.account_id = account_id_value
    AND control.workspace_id = workspace_id_value
  FOR SHARE;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = account_id_value
    AND workspace.id = workspace_id_value
  FOR KEY SHARE;
  -- Scheduled-task rows before session rows, exactly the 0275 wrapper's
  -- per-workspace task/session prefix: the scheduled-task writers lock
  -- task -> session -> membership, so removal must never hold the membership
  -- (or session) rows while waiting on a task row.
  PERFORM 1 FROM scheduled_tasks task
  WHERE task.account_id = account_id_value
    AND task.workspace_id = workspace_id_value
    AND task.deleted_at IS NULL
    AND task.status = 'active'
    AND (
      (task.created_by_kind = 'subject' AND task.created_by_subject_id = target_subject)
      OR EXISTS (
        SELECT 1 FROM scheduled_task_revision_authorities authority
        WHERE authority.task_id = task.id
          AND authority.task_authority_revision = task.authority_revision
          AND authority.subject_id = target_subject
      )
      OR EXISTS (
        SELECT 1 FROM scheduled_task_personal_resource_authorities authority
        WHERE authority.task_id = task.id
          AND authority.task_authority_revision = task.authority_revision
          AND authority.initiating_human_subject_id = target_subject
      )
      OR EXISTS (
        SELECT 1 FROM scheduled_task_connection_authority_snapshots snapshot
        WHERE snapshot.task_id = task.id
          AND snapshot.task_authority_revision = task.authority_revision
          AND snapshot.owner_subject_id = target_subject
      )
    )
  ORDER BY task.id
  FOR UPDATE;
  PERFORM 1 FROM sessions affected
  WHERE affected.account_id = account_id_value
    AND affected.workspace_id = workspace_id_value
    AND (
      (target_membership_id IS NOT NULL
        AND affected.owner_organization_membership_id = target_membership_id)
      OR EXISTS (
        SELECT 1 FROM session_turns initiated
        WHERE initiated.session_id = affected.id
          AND initiated.initiating_human_subject_id = target_subject
      )
    )
  ORDER BY affected.id
  FOR NO KEY UPDATE;
  PERFORM 1 FROM session_turns turn_row
  WHERE turn_row.account_id = account_id_value
    AND turn_row.workspace_id = workspace_id_value
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = turn_row.session_id
        AND (
          (target_membership_id IS NOT NULL
            AND owned.owner_organization_membership_id = target_membership_id)
          OR turn_row.initiating_human_subject_id = target_subject
        )
    )
  ORDER BY turn_row.id
  FOR UPDATE;
  PERFORM 1 FROM session_turn_attempts attempt
  WHERE attempt.account_id = account_id_value
    AND attempt.workspace_id = workspace_id_value
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = attempt.session_id
        AND (
          (target_membership_id IS NOT NULL
            AND owned.owner_organization_membership_id = target_membership_id)
          OR EXISTS (
            SELECT 1 FROM session_turns initiated
            WHERE initiated.id = attempt.turn_id
              AND initiated.initiating_human_subject_id = target_subject
          )
        )
    )
  ORDER BY attempt.id
  FOR UPDATE;
  SELECT result || COALESCE(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'accountId', turn_row.account_id,
        'workspaceId', turn_row.workspace_id,
        'sessionId', turn_row.session_id,
        'turnId', turn_row.id,
        'executionGeneration', turn_row.execution_generation,
        'turnAssociation', CASE WHEN owned.active_turn_id = turn_row.id
          THEN 'current' ELSE NULL END
      ) ORDER BY turn_row.session_id, turn_row.id
    ), '[]'::jsonb
  ) INTO result
  FROM session_turns turn_row
  JOIN sessions owned ON owned.id = turn_row.session_id
  WHERE turn_row.account_id = account_id_value
    AND turn_row.workspace_id = workspace_id_value
    AND turn_row.status IN (
      'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
    )
    AND (
      (target_membership_id IS NOT NULL
        AND owned.owner_organization_membership_id = target_membership_id)
      OR turn_row.initiating_human_subject_id = target_subject
    )
    AND EXISTS (
      SELECT 1 FROM session_pending_tool_calls pending
      WHERE pending.account_id = turn_row.account_id
        AND pending.workspace_id = turn_row.workspace_id
        AND pending.session_id = turn_row.session_id
        AND pending.turn_id = turn_row.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM session_turn_attempts live_attempt
      WHERE live_attempt.account_id = turn_row.account_id
        AND live_attempt.workspace_id = turn_row.workspace_id
        AND live_attempt.session_id = turn_row.session_id
        AND live_attempt.turn_id = turn_row.id
        AND live_attempt.id = turn_row.active_attempt_id
        AND live_attempt.state IN ('claimed', 'running')
    );
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', COALESCE(previous_workspace, ''), true
  );
  PERFORM opengeni_private.close_session_tenancy_fenced_access(removal_fenced_access_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_membership_lifecycle, ''), true
  );
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', COALESCE(previous_workspace, ''), true
  );
  PERFORM opengeni_private.close_session_tenancy_fenced_access(removal_fenced_access_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_membership_lifecycle, ''), true
  );
  RAISE;
END
$$;

CREATE FUNCTION prevent_claude_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF TG_TABLE_NAME = 'sessions' THEN
        IF NEW.initial_claude_provider_account_authority_snapshot
          IS DISTINCT FROM OLD.initial_claude_provider_account_authority_snapshot
        THEN
          RAISE EXCEPTION 'session initial Claude provider-account authority snapshot is immutable'
            USING ERRCODE = '23514';
        END IF;
      ELSIF NEW.claude_provider_account_authority_snapshot
        IS DISTINCT FROM OLD.claude_provider_account_authority_snapshot
      THEN
        RAISE EXCEPTION '% Claude provider-account authority snapshot is immutable', TG_TABLE_NAME
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION prevent_codex_provider_account_authority_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF NEW.codex_provider_account_authority_snapshot
        IS DISTINCT FROM OLD.codex_provider_account_authority_snapshot
      THEN
        RAISE EXCEPTION '% Codex provider-account authority snapshot is immutable', TG_TABLE_NAME
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END;
    $$;

CREATE FUNCTION prevent_session_event_projection_regression() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  fenced_access_capability_id uuid;
  current_sequence integer;
BEGIN
  IF NEW.last_sequence IS NOT DISTINCT FROM OLD.last_sequence THEN
    RETURN NEW;
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.session_variable_set_attachments_v1',
    '1',
    true
  );
  fenced_access_capability_id :=
    opengeni_private.open_session_tenancy_fenced_access(
      session_tenancy_fence_target_schema()
    );
  SELECT cursor.last_sequence
  INTO current_sequence
  FROM session_event_cursors cursor
  WHERE cursor.account_id = NEW.account_id
    AND cursor.workspace_id = NEW.workspace_id
    AND cursor.session_id = NEW.id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'session event cursor is missing for a session projection update';
  END IF;
  -- Event insertion is the only cursor advance. A semantic writer that updates
  -- session state before its event is snapped to the current cursor, and the
  -- validated AFTER INSERT trigger advances the compatibility projection once
  -- the event exists. No direct/manual update may lead or regress authority.
  NEW.last_sequence := current_sequence;
  PERFORM opengeni_private.close_session_tenancy_fenced_access(
    fenced_access_capability_id
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  IF fenced_access_capability_id IS NOT NULL THEN
    PERFORM opengeni_private.close_session_tenancy_fenced_access(
      fenced_access_capability_id
    );
  END IF;
  RAISE;
END
$$;

CREATE FUNCTION prevent_subscription_authority_v2_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
    DECLARE table_owner name;
    BEGIN
      IF NEW.subscription_authority IS DISTINCT FROM OLD.subscription_authority THEN
        SELECT pg_catalog.pg_get_userbyid(relation.relowner) INTO table_owner
        FROM pg_catalog.pg_class relation
        WHERE relation.oid = TG_RELID;
        IF session_user IS DISTINCT FROM table_owner THEN
          RAISE EXCEPTION 'session turn subscription authority is immutable'
            USING ERRCODE = '23514';
        END IF;
      END IF;
      RETURN NEW;
    END;
    $$;

CREATE FUNCTION prevent_xai_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF TG_TABLE_NAME = 'sessions' THEN
        IF NEW.initial_xai_provider_account_authority_snapshot
          IS DISTINCT FROM OLD.initial_xai_provider_account_authority_snapshot
        THEN
          RAISE EXCEPTION 'session initial xAI provider-account authority snapshot is immutable'
            USING ERRCODE = '23514';
        END IF;
      ELSIF NEW.xai_provider_account_authority_snapshot
        IS DISTINCT FROM OLD.xai_provider_account_authority_snapshot
      THEN
        RAISE EXCEPTION '% xAI provider-account authority snapshot is immutable', TG_TABLE_NAME
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END
    $$;

CREATE FUNCTION preview_connected_machine_audience_change(p_account_id uuid, p_workspace_id uuid, p_enrollment_id uuid, p_target_scope text, p_owner_subject_id text, p_schedules_may_be_only_me boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.workspace_id', true), '')::uuid
    OR nullif(pg_catalog.current_setting('opengeni.subject_id', true), '') IS NULL
  THEN RAISE EXCEPTION 'machine audience scope mismatch' USING ERRCODE = '42501'; END IF;
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'read')
  ON CONFLICT DO NOTHING;
  result := connected_machine_audience_inventory(
    p_account_id, p_workspace_id, p_enrollment_id, p_target_scope,
    p_owner_subject_id, p_schedules_may_be_only_me
  );
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
    AND capability_kind = 'read';
  RETURN result - 'ownerMembershipId' - 'ownerAuthorizationRevision' - 'notices';
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scoped_compute_capabilities
  WHERE backend_pid = pg_catalog.pg_backend_pid()
    AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  RAISE;
END
$$;

CREATE FUNCTION preview_organization_retention_deletions(p_account_id uuid, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  IF p_account_id IS NULL OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'invalid retention preview input' USING ERRCODE = '22023';
  END IF;
  PERFORM opengeni_private.assert_organization_retention_account(p_account_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'membershipId', candidate.id,
    'retentionUntil', candidate.personal_retention_until,
    'personalWorkspaceId', candidate.personal_workspace_id,
    'resourceCount', candidate.resource_count,
    'objectCount', candidate.object_count
  ) ORDER BY candidate.personal_retention_until, candidate.id), '[]'::jsonb)
  INTO result
  FROM (
    SELECT membership.id, membership.personal_retention_until,
      membership.personal_workspace_id,
      (SELECT count(*)::integer FROM organization_user_resource_authorities authority
       WHERE authority.account_id = p_account_id
         AND authority.organization_membership_id = membership.id) AS resource_count,
      CASE WHEN deletion.database_finalized_at IS NOT NULL THEN
        (SELECT count(*)::integer
         FROM organization_user_retention_object_obligations receipt
         WHERE receipt.account_id = p_account_id
           AND receipt.membership_id = membership.id
           AND NOT EXISTS (
             SELECT 1
             FROM organization_user_retention_object_deletion_receipts deleted
             WHERE deleted.account_id = receipt.account_id
               AND deleted.membership_id = receipt.membership_id
               AND deleted.object_kind = receipt.object_kind
               AND deleted.source_id = receipt.source_id
               AND deleted.object_bucket = receipt.object_bucket
           ))
      ELSE
        (SELECT count(*)::integer
         FROM opengeni_private.organization_retention_object_candidates(
           p_account_id, membership.id
         ))
      END AS object_count
    FROM organization_memberships membership
    LEFT JOIN organization_user_retention_deletions deletion
      ON deletion.account_id = membership.account_id
     AND deletion.membership_id = membership.id
    WHERE membership.account_id = p_account_id
      AND membership.status = 'revoked'
      AND membership.personal_retention_until IS NOT NULL
      AND membership.personal_retention_until <= clock_timestamp()
      AND (deletion.state IS NULL OR deletion.state <> 'completed')
    ORDER BY membership.personal_retention_until, membership.id
    LIMIT p_limit
  ) candidate;
  RETURN result;
END
$$;

CREATE FUNCTION preview_organization_user_setup(p_token_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  delivery organization_user_setup_deliveries%ROWTYPE;
  invitation organization_membership_invitations%ROWTYPE;
  setup organization_user_setup_intents%ROWTYPE;
BEGIN
  IF p_token_digest IS NULL OR p_token_digest !~ '^[0-9a-f]{64}$' THEN
    RETURN jsonb_build_object('state', 'unavailable');
  END IF;
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT * INTO delivery FROM organization_user_setup_deliveries candidate
  WHERE candidate.token_digest = p_token_digest;
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'unavailable'); END IF;
  SELECT * INTO setup FROM organization_user_setup_intents candidate
  WHERE candidate.id = delivery.setup_intent_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'unavailable'); END IF;
  IF setup.status = 'completed' THEN
    RETURN jsonb_build_object('state', 'completed');
  END IF;
  SELECT * INTO invitation FROM organization_membership_invitations candidate
  WHERE candidate.account_id = delivery.account_id AND candidate.id = delivery.invitation_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('state', 'unavailable'); END IF;
  IF invitation.status = 'revoked' OR delivery.state = 'revoked' THEN
    RETURN jsonb_build_object('state', 'revoked');
  END IF;
  IF invitation.status = 'accepted' THEN RETURN jsonb_build_object('state', 'completed'); END IF;
  IF invitation.status <> 'pending' THEN RETURN jsonb_build_object('state', 'unavailable'); END IF;
  IF invitation.expires_at <= clock_timestamp() OR setup.expires_at <= clock_timestamp() THEN
    RETURN jsonb_build_object('state', 'expired');
  END IF;
  RETURN jsonb_build_object(
    'state', 'pending',
    'organizationId', delivery.account_id,
    'organizationName', delivery.organization_name,
    'targetEmail', delivery.recipient_email,
    'targetName', delivery.recipient_name,
    'organizationRole', delivery.organization_role,
    'sharedWorkspaceAccess', delivery.shared_workspace_access,
    'expiresAt', invitation.expires_at
  );
END
$_$;

CREATE FUNCTION private_session_cancels_foreign_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  target_visibility text;
  target_owner_subject_id text;
  target_owner_membership_id uuid;
BEGIN
  IF NEW.state <> 'pending' OR NEW.kind = 'scheduled_occurrence' THEN
    RETURN NEW;
  END IF;
  SELECT session.visibility, session.owner_subject_id, session.owner_organization_membership_id
  INTO target_visibility, target_owner_subject_id, target_owner_membership_id
  FROM sessions session
  WHERE session.workspace_id = NEW.workspace_id AND session.id = NEW.session_id;
  IF target_visibility = 'user_private'
    AND session_system_update_carries_foreign_authority(NEW,
      target_owner_subject_id, target_owner_membership_id)
  THEN
    NEW.state := 'cancelled';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION propose_company_profile_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_operation_id uuid, p_content_json text, p_content_hash text, p_reason text) RETURNS TABLE(receipt_id uuid, revision_id uuid, human_input jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  context_account_id uuid := nullif(current_setting('opengeni.account_id', true), '')::uuid;
  context_workspace_id uuid := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
  context_subject_id text := nullif(current_setting('opengeni.subject_id', true), '');
  context_principal_kind text := nullif(current_setting('opengeni.principal_kind', true), '');
  initiating_subject text;
  actor_membership organization_memberships%ROWTYPE;
  active_head company_profile_heads%ROWTYPE;
  policy organization_company_profile_agent_policies%ROWTYPE;
  prior company_profile_agent_proposal_receipts%ROWTYPE;
  inserted_revision company_profile_revisions%ROWTYPE;
  input_hash_value text;
  new_receipt_id uuid := gen_random_uuid();
  new_revision_id uuid := gen_random_uuid();
  normalized_reason text := btrim(p_reason);
  prompt jsonb;
BEGIN
  IF context_account_id IS DISTINCT FROM p_account_id
    OR context_workspace_id IS DISTINCT FROM p_workspace_id
    OR context_subject_id IS NULL
    OR context_principal_kind IS DISTINCT FROM 'agent_attempt'
    OR p_execution_generation < 1
    OR p_operation_id IS NULL
    OR p_content_json IS NULL
    OR p_content_hash !~ '^[0-9a-f]{64}$'
    OR p_content_hash IS DISTINCT FROM encode(sha256(convert_to(p_content_json, 'UTF8')), 'hex')
    OR octet_length(convert_to(p_content_json, 'UTF8')) NOT BETWEEN 1 AND 28672
    OR octet_length(convert_to(normalized_reason, 'UTF8')) NOT BETWEEN 1 AND 16384
  THEN
    RAISE EXCEPTION 'company-profile agent proposal is invalid' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(
    turn.initiating_human_subject_id,
    CASE WHEN turn.initiator_kind = 'subject' THEN turn.initiator_subject_id END
  ) INTO initiating_subject
  FROM session_turns turn
  WHERE turn.account_id = p_account_id
    AND turn.workspace_id = p_workspace_id
    AND turn.session_id = p_session_id
    AND turn.id = p_turn_id;
  IF initiating_subject IS NULL THEN
    RAISE EXCEPTION
      'company-profile agent proposals require the exact live turn of the active organization owner'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization workspace is unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT membership.* INTO actor_membership
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = initiating_subject
    AND membership.status = 'active'
    AND membership.role = 'owner'
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'company-profile agent proposals require the exact live turn of the active organization owner'
      USING ERRCODE = '42501';
  END IF;
  PERFORM 1
  FROM sessions session
  JOIN session_turns turn
    ON turn.account_id = session.account_id
    AND turn.workspace_id = session.workspace_id
    AND turn.session_id = session.id
  JOIN session_turn_attempts attempt
    ON attempt.account_id = turn.account_id
    AND attempt.workspace_id = turn.workspace_id
    AND attempt.session_id = turn.session_id
    AND attempt.turn_id = turn.id
  WHERE session.account_id = p_account_id
    AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id
    AND session.active_turn_id = p_turn_id
    AND turn.id = p_turn_id
    AND turn.active_attempt_id = p_attempt_id
    AND turn.execution_generation = p_execution_generation
    AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
    AND coalesce(
      turn.initiating_human_subject_id,
      CASE WHEN turn.initiator_kind = 'subject' THEN turn.initiator_subject_id END
    ) = actor_membership.subject_id
    AND attempt.id = p_attempt_id
    AND attempt.execution_generation = p_execution_generation
    AND attempt.state IN ('claimed', 'running')
    AND NOT EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = attempt.workspace_id
        AND interruption.attempt_id = attempt.id
        AND interruption.state IN ('pending', 'delivered', 'acknowledged')
    )
  FOR SHARE OF session, turn, attempt;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'company-profile agent proposals require the exact live turn of the active organization owner'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM managed_accounts account
  WHERE account.id = p_account_id FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization account is unavailable' USING ERRCODE = '42501';
  END IF;

  input_hash_value := encode(sha256(convert_to(jsonb_build_array(
    'company-profile-agent-proposal', 1, p_account_id, p_workspace_id,
    p_session_id, p_turn_id, p_operation_id, p_content_hash, normalized_reason,
    actor_membership.id, actor_membership.subject_id
  )::text, 'UTF8')), 'hex');
  PERFORM set_config(
    'opengeni.company_profile_agent_admin_lifecycle',
    'company_profile_agent_admin', true
  );
  SELECT * INTO prior FROM company_profile_agent_proposal_receipts receipt
  WHERE receipt.account_id = p_account_id AND receipt.operation_id = p_operation_id;
  IF FOUND THEN
    IF prior.input_hash IS DISTINCT FROM input_hash_value THEN
      RAISE EXCEPTION 'company-profile agent proposal operation id was reused'
        USING ERRCODE = 'P1851';
    END IF;
    receipt_id := prior.id;
    revision_id := prior.revision_id;
    human_input := prior.human_input;
    replayed := true;
    RETURN NEXT;
    RETURN;
  END IF;
  IF EXISTS (
    SELECT 1 FROM company_profile_revisions revision
    WHERE revision.account_id = p_account_id AND revision.operation_id = p_operation_id
  ) THEN
    RAISE EXCEPTION 'company-profile agent proposal operation id was reused'
      USING ERRCODE = 'P1851';
  END IF;

  PERFORM set_config(
    'opengeni.company_profile_agent_policy_lifecycle',
    'company_profile_agent_policy', true
  );
  SELECT * INTO policy FROM organization_company_profile_agent_policies candidate
  WHERE candidate.account_id = p_account_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'company-profile agent policy is unavailable' USING ERRCODE = '55000';
  END IF;
  IF policy.mode = 'off' THEN
    RAISE EXCEPTION 'company-profile agent changes are disabled by organization policy'
      USING ERRCODE = 'P1852';
  END IF;

  SELECT * INTO active_head FROM company_profile_heads head
  WHERE head.account_id = p_account_id;
  INSERT INTO company_profile_revisions (
    id, operation_id, request_fingerprint, account_id, intent,
    content_json, content_hash, provenance_source, provenance_source_id,
    supersedes_revision_id, created_by_subject_id
  ) VALUES (
    new_revision_id, p_operation_id, input_hash_value, p_account_id, 'proposal',
    p_content_json, p_content_hash, 'agent_admin',
    'agent-admin-proposal:' || new_receipt_id::text,
    active_head.revision_id, context_subject_id
  ) RETURNING * INTO inserted_revision;
  prompt := company_profile_agent_confirmation_prompt(
    inserted_revision.id, inserted_revision.revision,
    inserted_revision.content_hash, inserted_revision.content_json
  );
  INSERT INTO company_profile_agent_proposal_receipts (
    id, operation_id, input_hash, account_id, workspace_id, session_id,
    turn_id, creation_attempt_id, execution_generation,
    initiating_human_subject_id, initiating_membership_id, revision_id,
    expected_current_revision_id, expected_activation_version,
    policy_mode, policy_version, reason, human_input
  ) VALUES (
    new_receipt_id, p_operation_id, input_hash_value, p_account_id, p_workspace_id,
    p_session_id, p_turn_id, p_attempt_id, p_execution_generation,
    actor_membership.subject_id, actor_membership.id, inserted_revision.id,
    active_head.revision_id, coalesce(active_head.activation_version, 0),
    policy.mode, policy.version, normalized_reason, prompt
  );
  receipt_id := new_receipt_id;
  revision_id := inserted_revision.id;
  human_input := prompt;
  replayed := false;
  RETURN NEXT;
END
$_$;

CREATE FUNCTION propose_company_profile_for_attempt_v2(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_operation_id uuid, p_automatic_activation_operation_id uuid, p_content_json text, p_content_hash text, p_reason text) RETURNS TABLE(receipt_id uuid, revision_id uuid, human_input jsonb, policy_mode text, automatic_activation_receipt_id uuid, activation_event_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  context_subject_id text := nullif(current_setting('opengeni.subject_id', true), '');
  context_principal_kind text := nullif(current_setting('opengeni.principal_kind', true), '');
  base record;
  proposal company_profile_agent_proposal_receipts%ROWTYPE;
  proposal_revision company_profile_revisions%ROWTYPE;
  prior company_profile_agent_automatic_activation_receipts%ROWTYPE;
  input_hash_value text;
  event_id_value uuid;
  new_receipt_id uuid := gen_random_uuid();
  service_actor text := 'service:company-profile-autonomy';
BEGIN
  IF context_subject_id IS NULL
    OR context_principal_kind IS DISTINCT FROM 'agent_attempt'
    OR p_automatic_activation_operation_id IS NULL
    OR p_automatic_activation_operation_id IS NOT DISTINCT FROM p_operation_id
  THEN
    RAISE EXCEPTION 'company-profile automatic activation operation is invalid'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO base FROM propose_company_profile_for_attempt(
    p_account_id, p_workspace_id, p_session_id, p_turn_id, p_attempt_id,
    p_execution_generation, p_operation_id, p_content_json, p_content_hash, p_reason
  );
  IF base.receipt_id IS NULL THEN
    RAISE EXCEPTION 'company-profile proposal returned no receipt' USING ERRCODE = '55000';
  END IF;
  PERFORM set_config(
    'opengeni.company_profile_agent_admin_lifecycle',
    'company_profile_agent_admin', true
  );
  SELECT * INTO proposal FROM company_profile_agent_proposal_receipts receipt
  WHERE receipt.account_id = p_account_id AND receipt.id = base.receipt_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'company-profile proposal receipt is unavailable' USING ERRCODE = '55000';
  END IF;

  receipt_id := proposal.id;
  revision_id := proposal.revision_id;
  human_input := proposal.human_input;
  policy_mode := proposal.policy_mode;
  IF proposal.policy_mode = 'suggest' THEN
    automatic_activation_receipt_id := NULL;
    activation_event_id := NULL;
    replayed := base.replayed;
    RETURN NEXT;
    RETURN;
  END IF;
  IF proposal.policy_mode IS DISTINCT FROM 'automatic' THEN
    RAISE EXCEPTION 'company-profile proposal policy is invalid' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO prior FROM company_profile_agent_automatic_activation_receipts receipt
  WHERE receipt.account_id = p_account_id AND receipt.proposal_receipt_id = proposal.id;
  IF FOUND THEN
    IF prior.operation_id IS DISTINCT FROM p_automatic_activation_operation_id THEN
      RAISE EXCEPTION 'company-profile automatic activation operation id was reused'
        USING ERRCODE = 'P1851';
    END IF;
    automatic_activation_receipt_id := prior.id;
    activation_event_id := prior.activation_event_id;
    replayed := true;
    RETURN NEXT;
    RETURN;
  END IF;
  SELECT * INTO prior FROM company_profile_agent_automatic_activation_receipts receipt
  WHERE receipt.account_id = p_account_id
    AND receipt.operation_id = p_automatic_activation_operation_id;
  IF FOUND THEN
    RAISE EXCEPTION 'company-profile automatic activation operation id was reused'
      USING ERRCODE = 'P1851';
  END IF;

  SELECT * INTO proposal_revision FROM company_profile_revisions revision
  WHERE revision.account_id = p_account_id
    AND revision.id = proposal.revision_id
    AND revision.intent = 'proposal'
    AND revision.provenance_source = 'agent_admin'
    AND revision.provenance_source_id = 'agent-admin-proposal:' || proposal.id::text
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'company-profile proposal revision is unavailable'
      USING ERRCODE = '42501';
  END IF;

  input_hash_value := encode(sha256(convert_to(jsonb_build_array(
    'company-profile-agent-automatic-activation', 1,
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_automatic_activation_operation_id, proposal.id, proposal.revision_id,
    proposal.policy_version, proposal.initiating_membership_id,
    proposal.initiating_human_subject_id
  )::text, 'UTF8')), 'hex');

  PERFORM set_config('opengeni.subject_id', service_actor, true);
  PERFORM set_config('opengeni.principal_kind', 'service', true);
  SELECT activation.event_id INTO event_id_value
  FROM company_profile_apply_activation(
    p_automatic_activation_operation_id, input_hash_value,
    p_account_id, p_workspace_id, proposal_revision.id,
    proposal.expected_current_revision_id, proposal.expected_activation_version,
    'activate', service_actor, 'service',
    'Automatically activated under the organization company-profile agent policy'
  ) activation;
  IF event_id_value IS NULL THEN
    RAISE EXCEPTION 'company-profile automatic activation returned no event'
      USING ERRCODE = '55000';
  END IF;
  PERFORM set_config('opengeni.subject_id', context_subject_id, true);
  PERFORM set_config('opengeni.principal_kind', context_principal_kind, true);

  INSERT INTO company_profile_agent_automatic_activation_receipts (
    id, operation_id, input_hash, account_id, workspace_id, session_id, turn_id,
    activation_attempt_id, execution_generation, proposal_receipt_id,
    proposal_revision_id, initiating_human_subject_id, initiating_membership_id,
    policy_version, activation_event_id
  ) VALUES (
    new_receipt_id, p_automatic_activation_operation_id, input_hash_value,
    p_account_id, p_workspace_id, p_session_id, p_turn_id, p_attempt_id,
    p_execution_generation, proposal.id, proposal.revision_id,
    proposal.initiating_human_subject_id, proposal.initiating_membership_id,
    proposal.policy_version, event_id_value
  );
  automatic_activation_receipt_id := new_receipt_id;
  activation_event_id := event_id_value;
  replayed := false;
  RETURN NEXT;
END
$$;

CREATE FUNCTION provider_connection_home_workspace(p_connection uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
  SELECT connection.workspace_id
  FROM connections connection
  WHERE connection.id = p_connection
    AND connection.account_id = nullif(pg_catalog.current_setting('opengeni.account_id', true), '')::uuid
    AND connection.status <> 'revoked'
    AND (
      (connection.subject_id IS NOT NULL
        AND connection.subject_id = nullif(pg_catalog.current_setting('opengeni.subject_id', true), '')
        AND vault_actor_membership(connection.account_id, connection.subject_id) IS NOT NULL)
      OR (connection.subject_id IS NULL AND EXISTS (
        SELECT 1 FROM vaults vault
        WHERE vault.account_id = connection.account_id
          AND vault.owner_kind = 'organization'
          AND vault.provider_connection_id = connection.id))
    )
$$;

CREATE FUNCTION provider_vault_item_ref(p_vault uuid, p_item uuid, p_provider_item_ref text, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  vault_row vaults;
  item_row vault_items;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  vault_row := opengeni_private.vault_reachable_row(context, p_vault);
  IF vault_row.source = 'opengeni' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'only connected vaults have provider items');
  END IF;
  SELECT item.* INTO item_row FROM vault_items item
  WHERE item.vault_id = vault_row.id AND item.provider_item_ref IS NOT NULL
    AND ((p_item IS NOT NULL AND item.id = p_item)
      OR (p_item IS NULL AND item.provider_item_ref = p_provider_item_ref));
  IF item_row.id IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_item_not_found', 'item not found',
      pg_catalog.jsonb_build_object('vaultId', vault_row.id));
  END IF;
  PERFORM opengeni_private.vault_capability_close();
  RETURN pg_catalog.jsonb_build_object(
    'itemId', item_row.id,
    'providerItemRef', item_row.provider_item_ref,
    'providerVersion', item_row.provider_version,
    'generation', item_row.generation);
END
$$;

CREATE FUNCTION provider_vault_sync_target(p_vault uuid, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  vault_row vaults;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  vault_row := opengeni_private.vault_reachable_row(context, p_vault);
  IF vault_row.source = 'opengeni' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'only connected vaults sync');
  END IF;
  PERFORM opengeni_private.vault_capability_close();
  RETURN pg_catalog.jsonb_build_object(
    'vaultId', vault_row.id,
    'workspaceId', vault_row.workspace_id,
    'source', vault_row.source,
    'mode', vault_row.mode,
    'providerConnectionId', vault_row.provider_connection_id,
    'providerVaultRef', vault_row.provider_vault_ref,
    'providerContentVersion', vault_row.provider_content_version,
    'providerCacheEpoch', vault_row.provider_cache_epoch::text,
    'rateLimitedUntil', vault_row.rate_limited_until);
END
$$;

CREATE FUNCTION read_organization_plan_balance(p_account_id uuid, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE state organization_plans%ROWTYPE; definition jsonb; period plan_credit_periods%ROWTYPE;
  remaining bigint := 0; pending bigint := 0; as_of timestamptz := coalesce(p_as_of, clock_timestamp()); scoped boolean := false;
BEGIN
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Plan account scope mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO state FROM organization_plans WHERE account_id = p_account_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  definition := opengeni_private.subscription_plan_definition(state.plan_key);
  SELECT * INTO period FROM plan_credit_periods WHERE account_id = p_account_id
    AND (expired_at IS NULL OR (plan_key = state.plan_key AND period_start = state.current_period_start))
    ORDER BY expired_at DESC NULLS FIRST, granted_at DESC LIMIT 1;
  SELECT eligible_model_ids IS NOT NULL INTO scoped FROM credit_ledger_entries WHERE id = period.grant_entry_id;
  IF period.id IS NOT NULL AND period.expired_at IS NULL AND period.period_end > as_of THEN
    remaining := greatest(0, period.granted_micros - period.opening_debt_micros - opengeni_private.plan_period_usage(period, as_of));
  END IF;
  SELECT least(greatest(0, ended.granted_micros - ended.opening_debt_micros
      - opengeni_private.plan_period_usage(ended, as_of)),
    CASE WHEN grant_row.eligible_model_ids IS NOT NULL THEN ended.granted_micros
      ELSE greatest(0, opengeni_private.plan_general_balance(p_account_id)) END) INTO pending
    FROM plan_credit_periods ended JOIN credit_ledger_entries grant_row ON grant_row.id = ended.grant_entry_id
    WHERE ended.account_id = p_account_id AND ended.expired_at IS NULL AND ended.period_end <= as_of;
  RETURN jsonb_build_object('key',state.plan_key,'label',coalesce(definition->>'label',state.plan_key),'status',state.status,
    'creditGrantedMicros',coalesce(period.granted_micros,0),'creditRemainingMicros',remaining,
    'creditPendingExpiryMicros',coalesce(pending,0),'creditScoped',coalesce(scoped,false),
    'periodResetAt',coalesce(period.period_end,state.current_period_end),'seatLimit',definition->'seatLimit','seatsUsed',organization_plan_seats_used(p_account_id),
    'cancelAtPeriodEnd',state.cancel_at_period_end);
END $$;

CREATE FUNCTION read_scoped_variable_set_secret(p_account_id uuid, p_workspace_id uuid, p_variable_set_id uuid, p_variable_set_name text, p_variable_name text, p_actor_kind text, p_session_id uuid DEFAULT NULL::uuid, p_turn_id uuid DEFAULT NULL::uuid, p_attempt_id uuid DEFAULT NULL::uuid, p_execution_generation integer DEFAULT NULL::integer) RETURNS TABLE(variable_set_id uuid, variable_name text, variable_version integer, value_encrypted text, authority_scope text, variable_set_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      actor_membership_id uuid;
      variable_set_row workspace_variable_sets%ROWTYPE;
      resolved_count integer;
      attempt_authority_epoch integer;
      attempt_authority_visibility text;
      attempt_owner_membership uuid;
      audit_subject text := coalesce(
        nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''),
        nullif(pg_catalog.current_setting('opengeni.subject_id', true), '')
      );
    BEGIN
      IF (p_variable_set_id IS NULL) = (p_variable_set_name IS NULL)
        OR p_actor_kind NOT IN ('subject', 'agent_attempt')
      THEN
        RAISE EXCEPTION 'invalid exact variable-set read request' USING ERRCODE = '22023';
      END IF;
      INSERT INTO opengeni_private.variable_set_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'materialize')
      ON CONFLICT DO NOTHING;

      IF p_actor_kind = 'subject' THEN
        actor_membership_id := scoped_variable_set_actor_membership(
          p_account_id, p_workspace_id
        );
      ELSE
        audit_subject := assert_scoped_variable_set_attempt(
          p_account_id, p_workspace_id, p_session_id, p_turn_id, p_attempt_id,
          p_execution_generation
        );
        -- Attribution evidence (0280): the exact attempt the assert above
        -- already validated owns the frozen session tenancy authority.
        SELECT attempt.authority_epoch, attempt.authority_visibility,
          attempt.authority_owner_organization_membership_id
        INTO attempt_authority_epoch, attempt_authority_visibility,
          attempt_owner_membership
        FROM session_turn_attempts attempt
        WHERE attempt.id = p_attempt_id
          AND attempt.account_id = p_account_id
          AND attempt.workspace_id = p_workspace_id;
      END IF;

      SELECT variable_set.* INTO STRICT variable_set_row
      FROM workspace_variable_sets variable_set
      WHERE variable_set.account_id = p_account_id
        AND variable_set.status = 'active'
        AND (
          (p_variable_set_id IS NOT NULL AND variable_set.id = p_variable_set_id)
          OR (p_variable_set_name IS NOT NULL AND variable_set.name = p_variable_set_name)
        )
        AND (
          variable_set.authority_scope = 'organization'
          OR (
            variable_set.authority_scope = 'workspace'
            AND variable_set.workspace_id = p_workspace_id
          )
          OR (
            variable_set.authority_scope = 'user'
            AND (
              (p_actor_kind = 'subject'
                AND variable_set.owner_organization_membership_id = actor_membership_id)
              OR p_actor_kind = 'agent_attempt'
            )
          )
        )
      ORDER BY CASE variable_set.authority_scope
        WHEN 'user' THEN 1 WHEN 'workspace' THEN 2 ELSE 3 END
      LIMIT 1
      FOR SHARE;

      IF p_actor_kind = 'agent_attempt' THEN
        PERFORM 1 FROM sessions session_value
        LEFT JOIN rig_versions rig_version
          ON rig_version.id = session_value.rig_version_id
         AND rig_version.rig_id = session_value.rig_id
         AND rig_version.account_id = session_value.account_id
        WHERE session_value.id = p_session_id
          AND session_value.account_id = p_account_id
          AND session_value.workspace_id = p_workspace_id
          AND (
            coalesce(session_value.variable_set_ids, '[]'::jsonb) ? variable_set_row.id::text
            OR coalesce(rig_version.default_variable_set_ids, '[]'::jsonb)
              ? variable_set_row.id::text
          );
        IF NOT FOUND THEN
          RAISE EXCEPTION 'exact variable-set resource was not admitted for this attempt'
            USING ERRCODE = '42501';
        END IF;
        IF variable_set_row.authority_scope = 'user' THEN
          SELECT count(*)::integer INTO resolved_count
          FROM resolve_session_attempt_personal_resources(
            p_account_id, p_workspace_id, p_attempt_id
          ) resolved
          WHERE resolved.resource_kind = 'variable_set'
            AND resolved.resource_id = variable_set_row.id
            AND resolved.authority_id = variable_set_row.authority_id
            AND resolved.authority_generation = variable_set_row.generation;
          IF resolved_count <> 1 THEN
            RAISE EXCEPTION 'personal variable-set grant is not exact or current'
              USING ERRCODE = '42501';
          END IF;
        END IF;
      END IF;

      RETURN QUERY
      SELECT variable_set_row.id, variable.name, variable.version,
        variable.value_encrypted, variable_set_row.authority_scope,
        variable_set_row.generation
      FROM workspace_variable_set_variables variable
      WHERE variable.account_id = p_account_id
        AND variable.variable_set_id = variable_set_row.id
        AND variable.name = p_variable_name;
      IF FOUND THEN
        INSERT INTO audit_events (
          account_id, workspace_id, subject_id, action, target_type, target_id,
          metadata, metadata_codec_version
        ) VALUES (
          p_account_id, p_workspace_id, audit_subject,
          'variable_set.variable.read', 'workspace_variable_set',
          variable_set_row.id::text,
          pg_catalog.jsonb_build_object(
            'variableSetId', variable_set_row.id,
            'name', p_variable_name,
            'actorKind', p_actor_kind,
            'scope', variable_set_row.authority_scope,
            'generation', variable_set_row.generation,
            'sessionId', p_session_id,
            'turnId', p_turn_id,
            'attemptId', p_attempt_id,
            'executionGeneration', p_execution_generation,
            'actorMembershipId', actor_membership_id,
            'authorityEpoch', attempt_authority_epoch,
            'authorityVisibility', attempt_authority_visibility,
            'authorityOwnerOrganizationMembershipId', attempt_owner_membership,
            'ownerAuthorityId', variable_set_row.authority_id,
            'ownerOrganizationMembershipId', variable_set_row.owner_organization_membership_id,
            'originWorkspaceId', variable_set_row.origin_workspace_id
          ),
          1
        );
      END IF;
      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'materialize';
      RETURN;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.variable_set_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'materialize';
      RAISE;
    END
    $$;

COMMENT ON FUNCTION read_scoped_variable_set_secret(p_account_id uuid, p_workspace_id uuid, p_variable_set_id uuid, p_variable_set_name text, p_variable_name text, p_actor_kind text, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) IS 'Only ciphertext egress for exact plaintext reads; commits value-free audit metadata before application decryption.';

CREATE FUNCTION read_vault_field_ciphertext(p_field uuid, p_version integer, p_purpose text, p_principal jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  field_row vault_item_fields;
  item_row vault_items;
  vault_row vaults;
  wanted integer;
  cipher text;
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  IF p_purpose NOT IN ('reveal', 'agent_read', 'internal') OR p_purpose IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'unknown read purpose');
  END IF;
  SELECT field.* INTO field_row FROM vault_item_fields field
  WHERE field.id = p_field AND field.account_id = (context ->> 'accountId')::uuid;
  IF NOT FOUND THEN
    PERFORM opengeni_private.vault_raise('vault_field_not_found', 'field not found',
      pg_catalog.jsonb_build_object('fieldId', p_field));
  END IF;
  item_row := opengeni_private.vault_reachable_item(context, field_row.item_id);
  SELECT vault.* INTO vault_row FROM vaults vault WHERE vault.id = item_row.vault_id;
  IF field_row.current_version IS NOT NULL THEN
    wanted := coalesce(p_version, field_row.current_version);
    SELECT version.value_encrypted INTO cipher FROM vault_field_versions version
    WHERE version.field_id = field_row.id AND version.version = wanted;
    IF cipher IS NULL THEN
      PERFORM opengeni_private.vault_raise('vault_field_not_found', 'version not found',
        pg_catalog.jsonb_build_object('fieldId', p_field, 'version', wanted));
    END IF;
  ELSIF p_version IS NOT NULL THEN
    PERFORM opengeni_private.vault_raise('vault_field_not_found', 'connected fields have no stored versions',
      pg_catalog.jsonb_build_object('fieldId', p_field));
  END IF;
  IF p_purpose <> 'internal' THEN
    PERFORM opengeni_private.vault_audit(item_row.account_id, (context ->> 'workspaceId')::uuid,
      context ->> 'subjectId',
      CASE p_purpose WHEN 'reveal' THEN 'vault.field.revealed' ELSE 'vault.secret.read' END,
      'vault_item', item_row.id::text,
      coalesce(p_metadata, '{}'::jsonb) || pg_catalog.jsonb_build_object(
        'vaultId', vault_row.id, 'itemId', item_row.id, 'itemName', item_row.name,
        'fieldId', field_row.id, 'fieldName', field_row.name, 'version', wanted,
        'sessionId', context ->> 'sessionId'));
  END IF;
  result := pg_catalog.jsonb_build_object(
    'valueEncrypted', cipher,
    'version', wanted,
    'currentVersion', field_row.current_version,
    'kind', field_row.kind,
    'fieldId', field_row.id,
    'fieldName', field_row.name,
    'fileName', field_row.file_name,
    'itemId', item_row.id,
    'itemName', item_row.name,
    'itemType', item_row.type,
    'vaultId', vault_row.id,
    'vaultName', vault_row.name,
    'vaultOwnerKind', vault_row.owner_kind,
    'source', vault_row.source,
    'providerConnectionId', vault_row.provider_connection_id,
    'providerVaultRef', vault_row.provider_vault_ref,
    'providerCacheEpoch', vault_row.provider_cache_epoch::text,
    'providerItemRef', item_row.provider_item_ref,
    'providerFieldRef', field_row.provider_field_ref
  );
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION reclassify_document_authority(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'accountId', '')::uuid;
  request_workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  document_id_value uuid := nullif(p_command ->> 'documentId', '')::uuid;
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  actor_subject text := nullif(p_command ->> 'actorSubjectId', '');
  expected_kind text := p_command #>> '{expectedAuthority,kind}';
  expected_workspace_id uuid := nullif(
    p_command #>> '{expectedAuthority,workspaceId}', ''
  )::uuid;
  expected_subject_id text := nullif(
    p_command #>> '{expectedAuthority,subjectId}', ''
  );
  expected_authority_id uuid := nullif(
    p_command #>> '{expectedAuthority,authorityId}', ''
  )::uuid;
  target_kind text := p_command ->> 'targetAuthorityKind';
  account_admin_authorization jsonb := p_command -> 'accountAdminAuthorization';
  account_admin_authorized boolean := false;
  input_hash_value text;
  existing_receipt document_authority_reclassifications%ROWTYPE;
  document_row documents%ROWTYPE;
  owner_member organization_memberships%ROWTYPE;
  target_workspace_id uuid;
  target_subject_id text;
  target_authority_id uuid;
  target_owner_membership_id uuid;
  old_authority_id uuid;
  receipt_created_at timestamptz;
  result_value jsonb;
BEGIN
  IF p_command IS NULL THEN
    RAISE EXCEPTION 'document reclassification command is required' USING ERRCODE = '22023';
  ELSIF account_id_value IS NULL THEN
    RAISE EXCEPTION 'document reclassification account id is required' USING ERRCODE = '22023';
  ELSIF request_workspace_id_value IS NULL THEN
    RAISE EXCEPTION 'document reclassification workspace id is required' USING ERRCODE = '22023';
  ELSIF document_id_value IS NULL THEN
    RAISE EXCEPTION 'document reclassification document id is required' USING ERRCODE = '22023';
  ELSIF operation_id_value IS NULL THEN
    RAISE EXCEPTION 'document reclassification operation id is required' USING ERRCODE = '22023';
  ELSIF actor_subject IS NULL THEN
    RAISE EXCEPTION 'document reclassification actor is required' USING ERRCODE = '22023';
  END IF;
  IF actor_subject IS DISTINCT FROM nullif(current_setting('opengeni.subject_id', true), '') THEN
    RAISE EXCEPTION 'document reclassification actor authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF account_id_value IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'document reclassification account authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF request_workspace_id_value IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'document reclassification workspace authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  -- `NULL NOT IN (...)` is NULL, not TRUE, so an ABSENT kind would slip past
  -- this guard and only surface much later as the compare-and-set 40001 the API
  -- renders as a 409 conflict. A missing kind is malformed input: reject it here
  -- with 22023 so the caller gets a 400.
  IF expected_kind IS NULL
    OR target_kind IS NULL
    OR expected_kind NOT IN ('organization', 'workspace', 'personal')
    OR target_kind NOT IN ('organization', 'workspace', 'personal')
    OR octet_length(convert_to(actor_subject, 'UTF8')) NOT BETWEEN 1 AND 1024
  THEN
    RAISE EXCEPTION 'document reclassification input is invalid'
      USING ERRCODE = '22023';
  END IF;

  IF account_admin_authorization IS NOT NULL
    AND account_admin_authorization <> 'null'::jsonb
  THEN
    account_admin_authorized :=
      jsonb_typeof(account_admin_authorization) = 'object'
      AND coalesce(account_admin_authorization ->> 'permission', '') = 'account:admin'
      AND nullif(account_admin_authorization ->> 'accountId', '')::uuid
        IS NOT DISTINCT FROM account_id_value
      AND nullif(account_admin_authorization ->> 'actorSubjectId', '')
        IS NOT DISTINCT FROM actor_subject
      AND coalesce(account_admin_authorization ->> 'authorizationId', '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  END IF;

  -- The authorization stamp is fresh request provenance, not logical input.
  -- Excluding it lets a later exactly-authorized HTTP retry converge on the
  -- immutable operation receipt while changed business input still conflicts.
  input_hash_value := encode(
    sha256(convert_to((p_command - 'accountAdminAuthorization')::text, 'UTF8')),
    'hex'
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('document-authority-reclassification:' || operation_id_value::text, 0)
  );
  INSERT INTO opengeni_private.document_migration_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'reclassify')
  ON CONFLICT DO NOTHING;
  SELECT * INTO existing_receipt
  FROM document_authority_reclassifications receipt
  WHERE receipt.operation_id = operation_id_value
  FOR UPDATE;
  IF FOUND THEN
    IF existing_receipt.account_id IS DISTINCT FROM account_id_value
      OR existing_receipt.input_hash IS DISTINCT FROM input_hash_value
    THEN
      RAISE EXCEPTION 'document reclassification operation id was reused with different input'
        USING ERRCODE = '23505';
    END IF;
    IF (
      existing_receipt.previous_authority_kind = 'organization'
      OR existing_receipt.resulting_authority_kind = 'organization'
    ) AND NOT account_admin_authorized
    THEN
      RAISE EXCEPTION 'organization document reclassification requires exact account authority'
        USING ERRCODE = '42501';
    END IF;
    DELETE FROM opengeni_private.document_migration_capabilities
    WHERE backend_pid = pg_backend_pid()
      AND transaction_id = pg_current_xact_id_if_assigned()
      AND capability_kind = 'reclassify';
    RETURN existing_receipt.result;
  END IF;
  DELETE FROM opengeni_private.document_migration_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'reclassify';

  SELECT * INTO document_row
  FROM documents document_value
  WHERE document_value.id = document_id_value
    AND document_value.account_id = account_id_value
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'document not found' USING ERRCODE = 'P0002';
  END IF;
  IF document_row.authority_kind IS DISTINCT FROM expected_kind
    OR document_row.authority_workspace_id IS DISTINCT FROM expected_workspace_id
    OR document_row.authority_subject_id IS DISTINCT FROM expected_subject_id
    OR document_row.authority_id IS DISTINCT FROM expected_authority_id
  THEN
    RAISE EXCEPTION 'document authority changed before reclassification'
      USING ERRCODE = '40001';
  END IF;
  IF (document_row.authority_kind = 'organization' OR target_kind = 'organization')
    AND NOT account_admin_authorized
  THEN
    RAISE EXCEPTION 'organization document reclassification requires exact account authority'
      USING ERRCODE = '42501';
  END IF;
  IF target_kind = 'workspace'
    AND request_workspace_id_value IS DISTINCT FROM document_row.workspace_id
  THEN
    RAISE EXCEPTION 'workspace document target requires the immutable origin workspace route'
      USING ERRCODE = '42501';
  END IF;
  IF target_kind = 'personal'
    AND document_row.created_by IS DISTINCT FROM actor_subject
  THEN
    RAISE EXCEPTION 'personal document reclassification requires the original creating subject'
      USING ERRCODE = '42501';
  END IF;

  old_authority_id := document_row.authority_id;
  target_subject_id := CASE WHEN target_kind = 'personal' THEN actor_subject ELSE NULL END;
  target_authority_id := CASE WHEN target_kind = 'personal' THEN document_row.authority_id ELSE NULL END;
  target_owner_membership_id := CASE
    WHEN target_kind = 'personal' THEN document_row.owner_organization_membership_id
    ELSE NULL
  END;

  IF target_kind = 'personal' AND target_authority_id IS NULL THEN
    -- The capability window MUST be open before the membership read, not after
    -- it. `organization_memberships` is FORCE ROW LEVEL SECURITY and carries no
    -- GUC-only read policy: every branch is capability- or lifecycle-gated. This
    -- routine is SECURITY DEFINER, so it runs as the schema OWNER, and `FORCE`
    -- binds the owner too on the documented deployment posture (a NOSUPERUSER,
    -- NOBYPASSRLS migration login). Reading first would match zero rows, leave
    -- `IF FOUND` false, and silently skip this entire portable-authority
    -- activation - see `docs/force-rls-migration-backfills.md`.
    INSERT INTO opengeni_private.personal_document_authority_capabilities (
      backend_pid, transaction_id, capability_kind
    ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'write')
    ON CONFLICT DO NOTHING;
    -- Fail loudly rather than fall through to the legacy lane if the window is
    -- ever not established: a blinded read here is indistinguishable from
    -- "this subject holds no organization membership", and the difference is
    -- whether a personal Document is portable or permanently workspace-pinned.
    IF NOT opengeni_private.personal_document_authority_capability_active('write') THEN
      RAISE EXCEPTION 'document reclassification personal authority window is unavailable'
        USING ERRCODE = '55000';
    END IF;
    -- Deliberately NOT `FOR SHARE`. PostgreSQL applies a relation's UPDATE
    -- policies to any SELECT that carries a locking clause, and every read
    -- policy on `organization_memberships` is `FOR SELECT` only, so `FOR SHARE`
    -- / `FOR KEY SHARE` / `FOR UPDATE` all return ZERO ROWS here without
    -- raising - the same silent-blinding class as the FORCE-RLS backfill no-op.
    -- The membership still cannot be deleted or re-keyed under us, by one of
    -- two mechanisms depending on which arm the write below takes. On the
    -- fresh-insert arm the RI check for
    -- `organization_user_resource_authorities_membership_fk` bypasses row
    -- security and takes `FOR KEY SHARE` on the exact membership row. On the
    -- ON CONFLICT DO UPDATE arm no row is inserted and the FK columns are
    -- unchanged, so PostgreSQL skips the RI check entirely - but the row it is
    -- reactivating already references that membership under ON DELETE RESTRICT,
    -- so the DELETE is refused by that reference instead. Either way a
    -- concurrent non-key `UPDATE` of the membership is NOT blocked; that
    -- narrower write-skew window is documented as a known residual.
    SELECT membership.* INTO owner_member
    FROM organization_memberships membership
    WHERE membership.account_id = account_id_value
      AND membership.subject_id = actor_subject
      AND membership.status = 'active'
      AND membership.revoked_at IS NULL;
    IF FOUND THEN
      -- Reactivate rather than insert blind. The rollback direction below only
      -- marks the prior authority `revoked`; it never deletes the row, and
      -- `organization_user_resource_authorities_resource_identity_idx` is
      -- UNIQUE (account_id, organization_membership_id, resource_kind,
      -- resource_id) with NO status predicate. A plain INSERT therefore made
      -- the documented `personal -> workspace -> personal` round trip fail
      -- permanently with 23505, which the route surfaces as an untyped 500.
      -- `origin_workspace_id` is deliberately preserved on reactivation: it is
      -- privacy-safe provenance of where the authority first originated, never
      -- an ownership or authorization anchor, so it must not be rewritten to
      -- wherever the Document happens to sit now.
      INSERT INTO organization_user_resource_authorities (
        id, account_id, organization_membership_id, resource_kind,
        resource_id, origin_workspace_id, generation, status
      ) VALUES (
        gen_random_uuid(), account_id_value, owner_member.id, 'document',
        document_row.id, document_row.workspace_id, 1, 'active'
      )
      ON CONFLICT (account_id, organization_membership_id, resource_kind, resource_id)
      DO UPDATE SET
        status = 'active',
        generation = organization_user_resource_authorities.generation + 1,
        revoked_at = NULL,
        updated_at = clock_timestamp()
      RETURNING id, organization_membership_id
      INTO target_authority_id, target_owner_membership_id;
    ELSE
      -- Configured/local and rolling-legacy subjects have no organization
      -- membership and keep the pre-organization workspace-anchored personal
      -- lane. Close the window immediately so nothing after this point runs
      -- with a capability it did not earn.
      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_backend_pid()
        AND transaction_id = pg_current_xact_id_if_assigned()
        AND capability_kind = 'write';
    END IF;
  END IF;

  -- Derived AFTER the authority decision, and never before it. The receipt and
  -- the API response must state the tuple `apply_document_authority` actually
  -- stores, and that trigger normalizes `authority_workspace_id` to NULL for
  -- every personal row with a non-null `authority_id` (a portable personal
  -- Document is anchored by its authority row, never by a workspace). Computing
  -- this up front made a `personal(portable) -> personal` receipt claim an
  -- anchoring that does not exist, and the trigger's receipt match compares the
  -- PRE-normalization NEW row, so nothing caught it.
  target_workspace_id := CASE
    WHEN target_kind = 'workspace' THEN document_row.workspace_id
    WHEN target_kind = 'personal' AND target_authority_id IS NULL
      THEN document_row.workspace_id
    ELSE NULL
  END;
  IF target_authority_id IS NULL THEN
    target_owner_membership_id := NULL;
  END IF;

  -- The receipt column and the receipt's own `createdAt` must be the SAME
  -- instant. Two `clock_timestamp()` calls drift by microseconds, which makes
  -- the `created_at = cursor` tie-break in
  -- `list_document_authority_reclassifications` unreachable and can silently
  -- skip a receipt whose stored `created_at` sorts before the cursor the client
  -- echoed back from `result.createdAt`.
  receipt_created_at := clock_timestamp();
  result_value := jsonb_build_object(
    'operationId', operation_id_value,
    'documentId', document_row.id,
    'previousAuthority', jsonb_build_object(
      'kind', document_row.authority_kind,
      'workspaceId', document_row.authority_workspace_id,
      'subjectId', document_row.authority_subject_id,
      'authorityId', document_row.authority_id
    ),
    'authority', jsonb_build_object(
      'kind', target_kind,
      'workspaceId', target_workspace_id,
      'subjectId', target_subject_id,
      'authorityId', target_authority_id
    ),
    'createdAt', receipt_created_at
  );

  INSERT INTO opengeni_private.document_migration_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'reclassify')
  ON CONFLICT DO NOTHING;
  INSERT INTO document_authority_reclassifications (
    operation_id, input_hash, account_id, request_workspace_id, document_id,
    actor_subject_id,
    previous_authority_kind, previous_authority_workspace_id,
    previous_authority_subject_id, previous_authority_id,
    previous_owner_organization_membership_id,
    resulting_authority_kind, resulting_authority_workspace_id,
    resulting_authority_subject_id, resulting_authority_id,
    resulting_owner_organization_membership_id, result, created_at
  ) VALUES (
    operation_id_value, input_hash_value, account_id_value,
    request_workspace_id_value, document_row.id, actor_subject,
    document_row.authority_kind, document_row.authority_workspace_id,
    document_row.authority_subject_id, document_row.authority_id,
    document_row.owner_organization_membership_id,
    target_kind, target_workspace_id, target_subject_id, target_authority_id,
    target_owner_membership_id, result_value, receipt_created_at
  );

  UPDATE documents SET
    authority_kind = target_kind,
    authority_workspace_id = target_workspace_id,
    authority_subject_id = target_subject_id,
    authority_id = target_authority_id,
    owner_organization_membership_id = target_owner_membership_id,
    visibility = CASE WHEN target_kind = 'personal' THEN 'private' ELSE 'workspace' END,
    updated_at = clock_timestamp()
  WHERE id = document_row.id;
  UPDATE document_chunks SET
    authority_kind = target_kind,
    authority_workspace_id = target_workspace_id,
    authority_subject_id = target_subject_id,
    authority_id = target_authority_id,
    owner_organization_membership_id = target_owner_membership_id
  WHERE document_id = document_row.id;

  IF old_authority_id IS NOT NULL AND old_authority_id IS DISTINCT FROM target_authority_id THEN
    UPDATE organization_user_resource_grants SET
      status = 'revoked', generation = generation + 1,
      revoked_at = coalesce(revoked_at, clock_timestamp()),
      updated_at = clock_timestamp()
    WHERE authority_id = old_authority_id
      AND account_id = account_id_value
      AND status IN ('active', 'consumed');
    UPDATE organization_user_resource_authorities SET
      status = 'revoked', generation = generation + 1,
      revoked_at = coalesce(revoked_at, clock_timestamp()),
      updated_at = clock_timestamp()
    WHERE id = old_authority_id
      AND account_id = account_id_value
      AND status <> 'revoked';
  END IF;
  DELETE FROM opengeni_private.personal_document_authority_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'write';
  DELETE FROM opengeni_private.document_migration_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'reclassify';
  RETURN result_value;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.personal_document_authority_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'write';
  DELETE FROM opengeni_private.document_migration_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'reclassify';
  RAISE;
END
$_$;

CREATE FUNCTION reconcile_organization_recovery_notification(p_outbox_id uuid, p_delivery_id uuid, p_reconciliation_owner text, p_resolution text, p_provider_message_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  ambiguous organization_recovery_notification_attempts%ROWTYPE;
  existing organization_recovery_notification_attempts%ROWTYPE;
  resolved_phase text;
  result jsonb;
  previous_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
BEGIN
  IF p_outbox_id IS NULL OR p_delivery_id IS NULL
    OR p_reconciliation_owner IS NULL
    OR length(btrim(p_reconciliation_owner)) NOT BETWEEN 1 AND 256
    OR p_resolution NOT IN ('sent', 'retry')
    OR (p_resolution = 'retry' AND p_provider_message_id IS NOT NULL)
    OR (p_provider_message_id IS NOT NULL AND octet_length(p_provider_message_id) > 1024)
  THEN
    RAISE EXCEPTION 'organization recovery notification reconciliation is invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM 1 FROM organization_recovery_notification_outbox outbox
  WHERE outbox.id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization recovery notification delivery is unavailable'
      USING ERRCODE = '42501';
  END IF;
  SELECT * INTO ambiguous FROM organization_recovery_notification_attempts attempt
  WHERE attempt.outbox_id = p_outbox_id AND attempt.delivery_id = p_delivery_id
    AND attempt.phase = 'outcome_unknown';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'only an ambiguous notification delivery may be reconciled'
      USING ERRCODE = '42501';
  END IF;
  resolved_phase := CASE WHEN p_resolution = 'sent'
    THEN 'reconciled_sent' ELSE 'reconciled_retry' END;
  SELECT * INTO existing FROM organization_recovery_notification_attempts attempt
  WHERE attempt.outbox_id = p_outbox_id AND attempt.delivery_id = p_delivery_id
    AND attempt.phase IN ('reconciled_sent', 'reconciled_retry')
  ORDER BY attempt.created_at DESC, attempt.id DESC LIMIT 1;
  IF FOUND THEN
    IF existing.phase <> resolved_phase
      OR existing.provider_message_id IS DISTINCT FROM p_provider_message_id
    THEN
      RAISE EXCEPTION 'organization recovery notification reconciliation conflicts'
        USING ERRCODE = '23505';
    END IF;
    result := pg_catalog.jsonb_build_object(
      'outboxId', p_outbox_id::text, 'deliveryId', p_delivery_id::text,
      'reconciliationOwner', existing.claim_owner,
      'attemptNumber', existing.attempt_number,
      'resolution', p_resolution, 'providerMessageId', existing.provider_message_id,
      'reconciledAt', existing.created_at, 'replay', true
    );
    PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
      CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
    RETURN result;
  END IF;
  INSERT INTO organization_recovery_notification_attempts (
    outbox_id, delivery_id, provider, claim_owner, attempt_number,
    lease_expires_at, phase, provider_message_id
  ) VALUES (
    p_outbox_id, p_delivery_id, ambiguous.provider, p_reconciliation_owner,
    ambiguous.attempt_number, ambiguous.lease_expires_at,
    resolved_phase, p_provider_message_id
  ) RETURNING pg_catalog.jsonb_build_object(
    'outboxId', outbox_id::text, 'deliveryId', delivery_id::text,
    'reconciliationOwner', claim_owner, 'attemptNumber', attempt_number,
    'resolution', p_resolution, 'providerMessageId', provider_message_id,
    'reconciledAt', created_at, 'replay', false
  ) INTO result;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION record_external_workspace_membership_operation(p_command jsonb, p_result jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE prepared jsonb; subject_value text; member_value uuid; hash_value text;
  account_value uuid := (p_command ->> 'organizationId')::uuid;
  workspace_value uuid := (p_command ->> 'workspaceId')::uuid;
  action_value text := p_command ->> 'action';
  previous_marker text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  current_permissions jsonb; requested_permissions jsonb; narrowed_value boolean;
  membership_status_value text;
BEGIN
  prepared := prepare_external_workspace_membership_operation(p_command);
  IF (prepared ->> 'replay')::boolean THEN RAISE EXCEPTION 'operation already recorded' USING ERRCODE = '23505'; END IF;
  subject_value := prepared #>> '{identity,subjectId}';
  IF action_value = 'grant' AND p_result -> 'identity' IS DISTINCT FROM prepared -> 'identity'
  THEN RAISE EXCEPTION 'grant receipt identity mismatch' USING ERRCODE = '55000'; END IF;
  IF p_result ->> 'workspaceId' IS DISTINCT FROM workspace_value::text
    OR (action_value = 'revoke' AND p_result ->> 'fencedGrantOperationId' IS DISTINCT FROM p_command ->> 'cancelGrantOperationId')
  THEN RAISE EXCEPTION 'operation receipt scope mismatch' USING ERRCODE = '55000'; END IF;
  IF action_value = 'update' THEN
    IF p_result -> 'identity' IS DISTINCT FROM prepared -> 'identity'
    THEN RAISE EXCEPTION 'update receipt identity mismatch' USING ERRCODE = '55000'; END IF;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'external_identity_provisioning', true);
    SELECT m.status INTO membership_status_value FROM organization_memberships m
      WHERE m.account_id = account_value AND m.id = (prepared #>> '{identity,organizationMembershipId}')::uuid
        AND m.subject_id = subject_value
      FOR UPDATE;
    IF membership_status_value IS DISTINCT FROM 'active'
    THEN RAISE EXCEPTION 'external member is not active' USING ERRCODE = '55000'; END IF;
    SELECT id, permissions INTO member_value, current_permissions FROM workspace_memberships
      WHERE account_id = account_value AND workspace_id = workspace_value AND subject_id = subject_value
      FOR UPDATE;
    IF member_value IS NULL THEN RAISE EXCEPTION 'external workspace member not found' USING ERRCODE = 'P0002'; END IF;
    requested_permissions := p_command -> 'permissions';
    narrowed_value := EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(coalesce(current_permissions, '[]'::jsonb)) permission
      WHERE NOT requested_permissions ? permission
    );
    IF jsonb_typeof(p_result -> 'permissions') IS DISTINCT FROM 'array'
      OR NOT (p_result -> 'permissions') @> requested_permissions
      OR NOT requested_permissions @> (p_result -> 'permissions')
      OR (p_result ->> 'narrowed')::boolean IS DISTINCT FROM narrowed_value
    THEN RAISE EXCEPTION 'update receipt effect mismatch' USING ERRCODE = '55000'; END IF;
    UPDATE workspace_memberships SET permissions = requested_permissions, updated_at = clock_timestamp()
      WHERE id = member_value;
    IF narrowed_value THEN
      -- The existing lifecycle revision (also advanced by an organization role
      -- change). Its trigger mirrors the advance onto the external identity.
      UPDATE organization_memberships SET authorization_revision = authorization_revision + 1,
        updated_at = clock_timestamp()
      WHERE account_id = account_value AND id = (prepared #>> '{identity,organizationMembershipId}')::uuid;
    END IF;
  END IF;
  SELECT id INTO member_value FROM workspace_memberships
    WHERE account_id = account_value AND workspace_id = workspace_value AND subject_id = subject_value;
  IF (action_value IN ('grant','update') AND member_value IS NULL) OR (action_value = 'revoke' AND member_value IS NOT NULL)
  THEN RAISE EXCEPTION 'operation effects not settled' USING ERRCODE = '55000'; END IF;
  hash_value := encode(sha256(convert_to((p_command - 'actorSubjectId')::text, 'UTF8')), 'hex');
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  INSERT INTO organization_workspace_operation_receipts (account_id, operation_id, action, input_hash, result)
    VALUES (account_value, (p_command ->> 'operationId')::uuid, action_value, hash_value, p_result);
  INSERT INTO organization_workspace_lifecycle_events (account_id, operation_id, actor_service_subject,
    workspace_id, target_organization_membership_id, target_workspace_membership_id, kind, role)
    VALUES (account_value, (p_command ->> 'operationId')::uuid, p_command ->> 'actorSubjectId', workspace_value,
      (prepared #>> '{identity,organizationMembershipId}')::uuid, member_value, action_value,
      CASE WHEN action_value = 'grant' THEN 'member' ELSE NULL END);
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(previous_marker,''), true);
  RAISE;
END $$;

CREATE FUNCTION record_organization_retention_object_deleted(p_account_id uuid, p_membership_id uuid, p_operation_id uuid, p_object_kind text, p_source_id text, p_object_bucket text, p_object_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE obligation organization_user_retention_object_obligations%ROWTYPE;
BEGIN
  IF p_object_kind NOT IN (
      'file', 'session_recording', 'browser_state_artifact', 'browser_state_upload',
      'transcription_recording_object', 'video_staging_reference',
      'workspace_artifact_version', 'editable_artifact_blob',
      'workspace_capture_manifest', 'workspace_capture_tree_index',
      'workspace_capture_blob'
    )
    OR nullif(p_source_id, '') IS NULL
    OR octet_length(convert_to(p_source_id, 'UTF8')) > 2048
    OR nullif(p_object_bucket, '') IS NULL
    OR octet_length(convert_to(p_object_bucket, 'UTF8')) > 1024
    OR nullif(p_object_key, '') IS NULL
    OR octet_length(convert_to(p_object_key, 'UTF8')) > 4096
  THEN RAISE EXCEPTION 'invalid retention object key' USING ERRCODE = '22023'; END IF;
  PERFORM opengeni_private.assert_organization_retention_account(p_account_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  UPDATE organization_user_retention_deletions deletion
  SET claim_expires_at = clock_timestamp() + interval '15 minutes', updated_at = clock_timestamp()
  WHERE deletion.account_id = p_account_id
    AND deletion.membership_id = p_membership_id
    AND deletion.claim_operation_id = p_operation_id
    AND deletion.state = 'claimed'
    AND deletion.claim_expires_at > clock_timestamp()
    AND deletion.database_finalized_at IS NOT NULL
    AND deletion.database_result ->> 'objectBucket' = p_object_bucket;
  IF NOT FOUND THEN RAISE EXCEPTION 'retention deletion claim is stale' USING ERRCODE = '40001'; END IF;
  SELECT * INTO obligation
  FROM organization_user_retention_object_obligations receipt
  WHERE receipt.account_id = p_account_id
    AND receipt.membership_id = p_membership_id
    AND receipt.object_kind = p_object_kind
    AND receipt.source_id = p_source_id
    AND receipt.object_bucket = p_object_bucket
  FOR UPDATE;
  IF NOT FOUND OR obligation.object_key IS DISTINCT FROM p_object_key
    OR obligation.object_key_hash <> encode(digest(p_object_key, 'sha256'), 'hex')
  THEN
    RAISE EXCEPTION 'retention object is outside the exact claim' USING ERRCODE = '42501';
  END IF;
  INSERT INTO organization_user_retention_object_deletion_receipts (
    account_id, membership_id, object_kind, source_id, object_bucket, operation_id
  ) VALUES (
    p_account_id, p_membership_id, p_object_kind, p_source_id, p_object_bucket, p_operation_id
  ) ON CONFLICT (account_id, membership_id, object_kind, source_id, object_bucket) DO NOTHING;
  RETURN FOUND;
END
$$;

CREATE FUNCTION record_organization_workspace_member_removal(p_command jsonb, p_workspace_membership_id uuid, p_actor_membership_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  target_membership_id_value uuid := nullif(
    p_command ->> 'targetOrganizationMembershipId', ''
  )::uuid;
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  input_hash_value text;
  result jsonb;
BEGIN
  IF p_command IS NULL OR (p_command ->> 'action') IS DISTINCT FROM 'revoke'
    OR account_id_value IS NULL OR workspace_id_value IS NULL
    OR target_membership_id_value IS NULL OR operation_id_value IS NULL
    OR p_workspace_membership_id IS NULL OR p_actor_membership_id IS NULL
    OR (p_command ->> 'actorSubjectId') IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
    OR NOT EXISTS (
      SELECT 1 FROM organization_memberships actor
      WHERE actor.account_id = account_id_value
        AND actor.id = p_actor_membership_id
        AND actor.subject_id = p_command ->> 'actorSubjectId'
        AND actor.status = 'active'
        AND actor.role IN ('owner', 'admin')
    )
    OR NOT EXISTS (
      SELECT 1 FROM organization_memberships target
      WHERE target.account_id = account_id_value
        AND target.id = target_membership_id_value
        AND target.subject_id = p_command ->> 'targetSubjectId'
    )
    OR EXISTS (
      SELECT 1 FROM workspace_memberships membership
      WHERE membership.id = p_workspace_membership_id
        OR (
          membership.account_id = account_id_value
          AND membership.workspace_id = workspace_id_value
          AND membership.subject_id = p_command ->> 'targetSubjectId'
        )
    )
  THEN
    RAISE EXCEPTION 'organization workspace removal receipt is invalid'
      USING ERRCODE = '55000';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  input_hash_value := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(p_command::text, 'UTF8')), 'hex'
  );
  result := pg_catalog.jsonb_build_object('removed', true, 'replay', false);
  INSERT INTO organization_workspace_operation_receipts (
    account_id, operation_id, action, input_hash, result
  ) VALUES (account_id_value, operation_id_value, 'revoke', input_hash_value, result);
  INSERT INTO organization_workspace_lifecycle_events (
    account_id, operation_id, actor_membership_id, workspace_id,
    target_organization_membership_id, target_workspace_membership_id, kind
  ) VALUES (
    account_id_value, operation_id_value, p_actor_membership_id, workspace_id_value,
    target_membership_id_value, p_workspace_membership_id, 'revoke'
  );
  RETURN result;
END
$$;

CREATE FUNCTION record_scheduled_task_revision_authority(p_account_id uuid, p_workspace_id uuid, p_task_id uuid, p_task_authority_revision bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  sender_prior_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  subject_value text := nullif(btrim(
    current_setting('opengeni.initiating_human_subject_id', true)
  ), '');
  task_row record;
  membership_row record;
  resource_bearing boolean;
BEGIN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true);
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN RAISE EXCEPTION 'scheduled revision authority scope mismatch'
    USING ERRCODE = '42501'; END IF;
  SELECT task.* INTO STRICT task_row
  FROM scheduled_tasks task
  WHERE task.id = p_task_id
    AND task.account_id = p_account_id
    AND task.workspace_id = p_workspace_id
    AND task.authority_revision = p_task_authority_revision
  FOR SHARE;
  IF task_row.action ->> 'kind' <> 'agent_turn' THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN NULL; END IF;
  -- Connection identity is the immutable task owner and is resolved per run.
  -- This revision receipt belongs only to retained native personal resources;
  -- verified host identities need not have a native organization membership.
  resource_bearing := EXISTS (
      SELECT 1 FROM workspace_variable_sets variable_set
      WHERE variable_set.id = task_row.variable_set_id
        AND variable_set.account_id = task_row.account_id
        AND variable_set.authority_scope = 'user'
    )
    OR EXISTS (
      SELECT 1 FROM rigs rig
      WHERE rig.id = task_row.rig_id
        AND rig.account_id = task_row.account_id
        AND rig.authority_scope = 'user'
    )
    OR task_row.xai_provider_account_authority_snapshot ->> 'scope' = 'user'
    OR EXISTS (
      SELECT 1 FROM scheduled_task_personal_resource_authorities authority
      WHERE authority.task_id = task_row.id
        AND authority.task_authority_revision = task_row.authority_revision
    );
  -- A service/API-key/delegated writer is not a managed human and cannot be a
  -- revision authorizer. That is allowed for a task that delegates no personal
  -- authority (workspace/organization Variable Sets and Rigs use ordinary
  -- workspace authority); a personal-resource task fails closed instead of
  -- running without a causal human.
  IF subject_value IS NULL OR NOT EXISTS (
    SELECT 1 FROM organization_memberships membership
    WHERE membership.account_id = p_account_id
      AND membership.subject_id = subject_value
  ) THEN
    IF resource_bearing THEN
      RAISE EXCEPTION
        'scheduled personal-resource agent task requires an exact human revision authorizer'
        USING ERRCODE = '42501';
    END IF;
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN NULL;
  END IF;
  SELECT membership.* INTO membership_row
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = subject_value
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
    AND (
      membership.personal_workspace_id = p_workspace_id
      OR EXISTS (
        SELECT 1 FROM workspace_memberships workspace_membership
        WHERE workspace_membership.account_id = p_account_id
          AND workspace_membership.workspace_id = p_workspace_id
          AND workspace_membership.subject_id = subject_value
      )
    )
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled revision authorizer lacks active workspace membership'
      USING ERRCODE = '42501';
  END IF;
  INSERT INTO scheduled_task_revision_authorities (
    task_id, task_authority_revision, account_id, workspace_id, subject_id,
    organization_membership_id, membership_authorization_revision, execution_digest
  ) VALUES (
    task_row.id, task_row.authority_revision, task_row.account_id,
    task_row.workspace_id, subject_value, membership_row.id,
    membership_row.authorization_revision, task_row.execution_digest
  );
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN subject_value;
EXCEPTION WHEN OTHERS THEN RAISE;
END
$$;

CREATE FUNCTION record_tenancy_backfill_unresolved(p_receipt_id uuid, p_resource_id uuid, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  previous_lifecycle_marker text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
  receipt_row record;
  inserted_count integer;
BEGIN
  IF p_receipt_id IS NULL OR p_resource_id IS NULL OR p_reason_code IS NULL THEN
    RAISE EXCEPTION 'tenancy backfill unresolved row requires receipt, resource, and reason'
      USING ERRCODE = '22004';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', 'tenancy_backfill_ledger', true
  );

  SELECT receipt.id, receipt.account_id, receipt.resource_family, receipt.status
    INTO receipt_row
  FROM tenancy_backfill_receipts receipt
  WHERE receipt.id = p_receipt_id
  FOR UPDATE;

  IF receipt_row.id IS NULL THEN
    RAISE EXCEPTION 'tenancy backfill receipt % does not exist', p_receipt_id
      USING ERRCODE = '23503';
  END IF;
  IF receipt_row.account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'tenancy backfill ledger scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF receipt_row.status <> 'open' THEN
    RAISE EXCEPTION 'tenancy backfill receipt % is already settled', p_receipt_id
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO tenancy_backfill_unresolved_rows (
    receipt_id, account_id, resource_family, resource_id, reason_code
  )
  VALUES (
    receipt_row.id, receipt_row.account_id, receipt_row.resource_family,
    p_resource_id, p_reason_code
  )
  ON CONFLICT ("receipt_id", "resource_family", "resource_id") DO NOTHING;

  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  IF inserted_count > 0 THEN
    UPDATE tenancy_backfill_receipts
    SET unresolved_count = unresolved_count + 1, updated_at = now()
    WHERE id = receipt_row.id;
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    coalesce(previous_lifecycle_marker, ''), true
  );
END;
$$;

CREATE FUNCTION record_vault_secret_use(p_principal jsonb, p_use jsonb, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  touched integer;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  UPDATE vault_items item SET last_used_at = pg_catalog.now()
  WHERE item.id IN (
      SELECT (element ->> 'itemId')::uuid FROM pg_catalog.jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) element
    )
    AND item.account_id = (context ->> 'accountId')::uuid
    AND item.vault_id IN (SELECT reach.vault_id FROM opengeni_private.vault_reach(context) reach);
  GET DIAGNOSTICS touched = ROW_COUNT;
  PERFORM opengeni_private.vault_audit((context ->> 'accountId')::uuid, (context ->> 'workspaceId')::uuid,
    context ->> 'subjectId', 'vault.secret.used', 'vault_item', NULL,
    coalesce(p_use, '{}'::jsonb) || pg_catalog.jsonb_build_object(
      'principalKind', context ->> 'kind',
      'sessionId', coalesce(context ->> 'sessionId', p_principal ->> 'sessionId'),
      'turnId', p_principal ->> 'turnId',
      'attemptId', p_principal ->> 'attemptId',
      'siteId', p_principal ->> 'siteId',
      'count', pg_catalog.jsonb_array_length(coalesce(p_items, '[]'::jsonb)),
      'itemsTouched', touched,
      'items', coalesce(p_items, '[]'::jsonb)));
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION refuse_imported_archive_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  archive_id text;
  archive_state text;
BEGIN
  SELECT imported_archive_import_id, content_archive_state INTO archive_id, archive_state
  FROM sessions
  WHERE workspace_id = NEW.workspace_id AND id = NEW.session_id FOR NO KEY UPDATE;
  IF archive_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'OG002', MESSAGE = 'SESSION_IMPORTED_READ_ONLY';
  END IF;
  IF archive_state IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'OG002', MESSAGE = 'SESSION_ARCHIVED_READ_ONLY';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION reject_governed_learning_decision_receipt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    AND pg_catalog.pg_trigger_depth() > 1
    AND (
      NOT EXISTS (SELECT 1 FROM workspaces WHERE id = OLD.workspace_id)
      OR NOT EXISTS (
        SELECT 1 FROM sessions
        WHERE workspace_id = OLD.workspace_id AND id = OLD.session_id
      )
      OR NOT EXISTS (
        SELECT 1 FROM session_turns
        WHERE workspace_id = OLD.workspace_id AND id = OLD.turn_id
      )
      OR NOT EXISTS (
        SELECT 1 FROM session_turn_attempts
        WHERE workspace_id = OLD.workspace_id AND id = OLD.attempt_id
      )
      OR NOT EXISTS (
        SELECT 1 FROM workspace_learning_policy_snapshots WHERE id = OLD.policy_snapshot_id
      )
      OR NOT EXISTS (SELECT 1 FROM knowledge_change_proposals WHERE id = OLD.proposal_id)
      OR NOT EXISTS (SELECT 1 FROM knowledge_claims WHERE id = OLD.claim_id)
      OR NOT EXISTS (SELECT 1 FROM knowledge_claim_evidence WHERE id = OLD.evidence_id)
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'Governed-learning decision receipts are immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION reject_legacy_claude_subscription_credentials() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'connections' THEN
    IF NEW.metadata->>'credentialRole' = 'claude_subscription'
      OR (TG_OP = 'UPDATE' AND OLD.metadata->>'credentialRole' = 'claude_subscription') THEN
      IF NEW.status <> 'revoked' OR NEW.credential_encrypted <> ''
        OR NEW.metadata->>'credentialRole' IS DISTINCT FROM 'claude_subscription' THEN
        RAISE EXCEPTION 'Claude subscriptions use individual accounts' USING ERRCODE = '0A000';
      END IF;
    END IF;
  ELSIF NEW.provider_kind = 'claude_subscription'
    OR (TG_OP = 'UPDATE' AND OLD.provider_kind = 'claude_subscription') THEN
    IF NEW.status <> 'revoked' OR NEW.credential_encrypted <> '' OR NEW.provider_kind <> 'claude_subscription' THEN
      RAISE EXCEPTION 'Claude subscriptions use individual accounts' USING ERRCODE = '0A000';
    END IF;
  END IF;
  RETURN NEW;
END $$;

