CREATE FUNCTION release_session_work_claim_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_operation_id uuid, p_claim_id uuid, p_expected_revision integer, p_reason text) RETURNS TABLE(claim_id uuid, session_id uuid, root_session_id uuid, subject_namespace text, subject_type text, canonical_key text, display_label text, role text, state text, revision integer, provenance text, version_kind text, version_value text, observed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, settled_at timestamp with time zone, mutation_kind text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
DECLARE
  authority record;
  existing_revision session_work_claim_revisions%ROWTYPE;
  claim_row session_work_claims%ROWTYPE;
  calculated_input_hash text;
  now_value timestamptz := clock_timestamp();
  write_capability_id uuid := gen_random_uuid();
  previous_capability text := current_setting(
    'opengeni.session_work_claim_write_capability', true
  );
BEGIN
  PERFORM acquire_session_tenancy_fence(p_workspace_id);
  SELECT * INTO STRICT authority FROM resolve_session_work_claim_attempt_authority(
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_attempt_id, p_execution_generation
  );
  IF p_operation_id IS NULL OR p_claim_id IS NULL
    OR p_expected_revision IS NULL OR p_expected_revision < 1
    OR p_reason NOT IN (
      'completed','cancelled','failed','superseded','no_longer_active',
      'corrected','external_state_changed','other'
    )
  THEN
    RAISE EXCEPTION 'work claim release input is invalid' USING ERRCODE = '22023';
  END IF;
  calculated_input_hash := encode(sha256(convert_to(jsonb_build_object(
    'accountId', p_account_id,
    'workspaceId', p_workspace_id,
    'sessionId', p_session_id,
    'turnId', p_turn_id,
    'claimId', p_claim_id,
    'expectedRevision', p_expected_revision,
    'reason', p_reason
  )::text, 'UTF8')), 'hex');

  INSERT INTO session_work_claim_write_capabilities (
    backend_pid, transaction_id, capability_id
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), write_capability_id);
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', write_capability_id::text, true
  );

  SELECT * INTO existing_revision FROM session_work_claim_revisions revision_row
  WHERE revision_row.workspace_id = p_workspace_id
    AND revision_row.operation_id = p_operation_id
  FOR SHARE;
  IF FOUND THEN
    IF existing_revision.input_hash <> calculated_input_hash
      OR existing_revision.session_id <> p_session_id
      OR existing_revision.actor_turn_id <> p_turn_id
      OR existing_revision.mutation_kind <> 'released'
    THEN
      RAISE EXCEPTION 'work claim release conflicts with another input or logical turn'
        USING ERRCODE = '23505';
    END IF;
    claim_row.id := existing_revision.claim_id;
    claim_row.session_id := existing_revision.session_id;
    claim_row.root_session_id := existing_revision.root_session_id;
    claim_row.subject_namespace := existing_revision.subject_namespace;
    claim_row.subject_type := existing_revision.subject_type;
    claim_row.canonical_key := existing_revision.canonical_key;
    claim_row.display_label := existing_revision.display_label;
    claim_row.role := existing_revision.role;
    claim_row.state := existing_revision.state;
    claim_row.revision := existing_revision.resulting_revision;
    claim_row.provenance := existing_revision.provenance;
    claim_row.version_kind := existing_revision.version_kind;
    claim_row.version_value := existing_revision.version_value;
    claim_row.observed_at := existing_revision.observed_at;
    claim_row.created_at := existing_revision.claim_created_at;
    claim_row.updated_at := existing_revision.claim_updated_at;
    claim_row.settled_at := existing_revision.settled_at;
    replayed := true;
  ELSE
    SELECT * INTO claim_row FROM session_work_claims claim
    WHERE claim.workspace_id = p_workspace_id
      AND claim.session_id = p_session_id
      AND claim.id = p_claim_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'work claim is unavailable' USING ERRCODE = 'P0002';
    END IF;
    IF claim_row.state <> 'active' OR claim_row.revision <> p_expected_revision THEN
      RAISE EXCEPTION 'work claim release revision conflict' USING ERRCODE = '40001';
    END IF;
    UPDATE session_work_claims claim SET
      state = 'released',
      revision = claim.revision + 1,
      settled_at = now_value,
      updated_at = now_value
    WHERE claim.workspace_id = p_workspace_id
      AND claim.id = p_claim_id
      AND claim.state = 'active'
      AND claim.revision = p_expected_revision
    RETURNING * INTO STRICT claim_row;
    INSERT INTO session_work_claim_revisions (
      account_id, workspace_id, claim_id, session_id, root_session_id,
      operation_id, input_hash, mutation_kind, prior_revision, resulting_revision,
      subject_namespace, subject_type, canonical_key, subject_digest, display_label,
      role, state, provenance, version_kind, version_value, observed_at,
      claim_created_at, claim_updated_at, settled_at, actor_kind, actor_subject_id,
      actor_session_id, actor_turn_id, actor_attempt_id, actor_execution_generation, reason
    ) VALUES (
      p_account_id, p_workspace_id, claim_row.id, p_session_id, claim_row.root_session_id,
      p_operation_id, calculated_input_hash, 'released', p_expected_revision,
      claim_row.revision, claim_row.subject_namespace, claim_row.subject_type,
      claim_row.canonical_key, claim_row.subject_digest, claim_row.display_label,
      claim_row.role, claim_row.state, claim_row.provenance, claim_row.version_kind,
      claim_row.version_value, claim_row.observed_at, claim_row.created_at,
      claim_row.updated_at, claim_row.settled_at, 'agent_attempt', authority.actor_subject_id,
      p_session_id, p_turn_id, p_attempt_id, p_execution_generation, p_reason
    );
    UPDATE sessions session SET updated_at = now_value
    WHERE session.workspace_id = p_workspace_id AND session.id = p_session_id;
    replayed := false;
  END IF;

  claim_id := claim_row.id;
  session_id := claim_row.session_id;
  root_session_id := claim_row.root_session_id;
  subject_namespace := claim_row.subject_namespace;
  subject_type := claim_row.subject_type;
  canonical_key := claim_row.canonical_key;
  display_label := claim_row.display_label;
  role := claim_row.role;
  state := claim_row.state;
  revision := claim_row.revision;
  provenance := claim_row.provenance;
  version_kind := claim_row.version_kind;
  version_value := claim_row.version_value;
  observed_at := claim_row.observed_at;
  created_at := claim_row.created_at;
  updated_at := claim_row.updated_at;
  settled_at := claim_row.settled_at;
  mutation_kind := 'released';
  DELETE FROM session_work_claim_write_capabilities capability
  WHERE capability.backend_pid = pg_backend_pid()
    AND capability.transaction_id = pg_current_xact_id()
    AND capability.capability_id = write_capability_id;
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', coalesce(previous_capability, ''), true
  );
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', coalesce(previous_capability, ''), true
  );
  RAISE;
END;
$$;

CREATE FUNCTION release_vault_passkey_leases(p_holder text, p_principal jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_principal_context(p_principal);
  DELETE FROM vault_passkey_leases lease
  WHERE lease.holder = p_holder AND lease.account_id = (context ->> 'accountId')::uuid;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION replace_plan_credit_period(p_account_id uuid, p_plan_key text, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_stripe_subscription_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE previous plan_credit_periods%ROWTYPE;
BEGIN
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Plan account scope mismatch' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext(p_account_id::text));
  -- Replay BEFORE touching the successor: a duplicated upgrade must not expire
  -- its own allowance (or a newer period that has already replaced it).
  IF EXISTS (SELECT 1 FROM plan_credit_periods WHERE account_id = p_account_id AND plan_key = p_plan_key
    AND period_start = p_period_start AND stripe_subscription_id IS NOT DISTINCT FROM p_stripe_subscription_id) THEN
    RETURN grant_plan_credit_period(p_account_id, p_plan_key, p_period_start, p_period_end, p_stripe_subscription_id);
  END IF;
  FOR previous IN SELECT * FROM plan_credit_periods WHERE account_id = p_account_id AND expired_at IS NULL LOOP
    -- Free maintenance can run while a paid invoice is delayed or an unpaid
    -- subscription is reactivated. Its anniversary may be newer than the paid
    -- period's anchor; it must not prevent replacing Free with paid funding.
    -- Keep the chronology guard between paid periods and replay check above.
    IF NOT (previous.stripe_subscription_id IS NULL AND p_stripe_subscription_id IS NOT NULL)
      AND (previous.period_start > p_period_start OR
        (previous.period_start = p_period_start AND previous.plan_key = p_plan_key)) THEN
      RAISE EXCEPTION 'Upgrade cannot replace a newer plan period' USING ERRCODE = '55000';
    END IF;
    PERFORM expire_plan_credit_period(p_account_id, previous.id, true);
  END LOOP;
  RETURN grant_plan_credit_period(p_account_id, p_plan_key, p_period_start, p_period_end, p_stripe_subscription_id);
END $$;

CREATE FUNCTION replace_task_note_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_operation_id uuid, p_archive_operation_id uuid, p_create_operation_id uuid, p_replaced_note_id uuid, p_expected_replaced_version integer, p_replacement_kind text, p_replacement_text text, p_replacement_expires_in_days integer, p_reason text) RETURNS TABLE(operation_id uuid, input_hash text, replaced_note_id uuid, replaced_note_version integer, replacement_note_id uuid, root_session_id uuid, replacement_kind text, replacement_text text, replacement_status text, replacement_version integer, replacement_expires_at timestamp with time zone, replacement_created_at timestamp with time zone, replacement_updated_at timestamp with time zone, replacement_archived_at timestamp with time zone, replacement_actor_kind text, replacement_source_session_id uuid, replacement_source_turn_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  authority record;
  receipt_row task_note_replacement_receipts%ROWTYPE;
  replaced_row task_notes%ROWTYPE;
  replacement_row task_notes%ROWTYPE;
  archived_result record;
  created_result record;
  calculated_replacement_text_hash text;
  calculated_input_hash text;
BEGIN
  SELECT * INTO STRICT authority FROM resolve_task_note_attempt_authority(
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_attempt_id, p_execution_generation
  );
  IF p_operation_id IS NULL
    OR p_archive_operation_id IS NULL
    OR p_create_operation_id IS NULL
    OR p_operation_id = p_archive_operation_id
    OR p_operation_id = p_create_operation_id
    OR p_archive_operation_id = p_create_operation_id
    OR p_replaced_note_id IS NULL
    OR p_expected_replaced_version IS DISTINCT FROM 1
    OR p_replacement_kind NOT IN ('finding','decision','blocker','ownership','artifact','handoff')
    OR p_replacement_text IS NULL
    OR octet_length(p_replacement_text) NOT BETWEEN 1 AND 4096
    OR p_replacement_text <> btrim(p_replacement_text)
    OR p_replacement_expires_in_days IS NULL
    OR p_replacement_expires_in_days NOT BETWEEN 1 AND 90
    OR p_reason IS NULL
    OR octet_length(p_reason) NOT BETWEEN 1 AND 2048
    OR p_reason <> btrim(p_reason)
  THEN
    RAISE EXCEPTION 'Task-note replacement input is invalid' USING ERRCODE = '22023';
  END IF;

  calculated_replacement_text_hash := encode(
    sha256(convert_to(p_replacement_text, 'UTF8')), 'hex'
  );
  calculated_input_hash := encode(sha256(convert_to(jsonb_build_object(
    'accountId', p_account_id,
    'workspaceId', p_workspace_id,
    'rootSessionId', authority.root_session_id,
    'sessionId', p_session_id,
    'turnId', p_turn_id,
    'attemptId', p_attempt_id,
    'executionGeneration', p_execution_generation,
    'operationId', p_operation_id,
    'archiveOperationId', p_archive_operation_id,
    'createOperationId', p_create_operation_id,
    'replacedNoteId', p_replaced_note_id,
    'expectedReplacedVersion', p_expected_replaced_version,
    'replacementKind', p_replacement_kind,
    'replacementTextHash', calculated_replacement_text_hash,
    'replacementExpiresInDays', p_replacement_expires_in_days,
    'reason', p_reason
  )::text, 'UTF8')), 'hex');

  SELECT receipt.* INTO receipt_row
  FROM task_note_replacement_receipts receipt
  WHERE receipt.workspace_id = p_workspace_id
    AND receipt.operation_id = p_operation_id
  FOR SHARE;
  IF FOUND THEN
    IF receipt_row.account_id IS DISTINCT FROM p_account_id
      OR receipt_row.root_session_id IS DISTINCT FROM authority.root_session_id
      OR receipt_row.input_hash IS DISTINCT FROM calculated_input_hash
      OR receipt_row.replaced_note_id IS DISTINCT FROM p_replaced_note_id
      OR receipt_row.archive_operation_id IS DISTINCT FROM p_archive_operation_id
      OR receipt_row.create_operation_id IS DISTINCT FROM p_create_operation_id
      OR receipt_row.actor_session_id IS DISTINCT FROM p_session_id
      OR receipt_row.actor_turn_id IS DISTINCT FROM p_turn_id
      OR receipt_row.actor_attempt_id IS DISTINCT FROM p_attempt_id
      OR receipt_row.actor_execution_generation IS DISTINCT FROM p_execution_generation
      OR receipt_row.actor_kind IS DISTINCT FROM authority.actor_kind
      OR receipt_row.actor_subject_id IS DISTINCT FROM authority.actor_subject_id
      OR receipt_row.initiating_human_subject_id
        IS DISTINCT FROM authority.initiating_human_subject_id
    THEN
      RAISE EXCEPTION 'Task-note replacement operation conflicts with another input or attempt'
        USING ERRCODE = '23505';
    END IF;
    SELECT note.* INTO STRICT replacement_row
    FROM task_notes note
    WHERE note.workspace_id = p_workspace_id
      AND note.root_session_id = authority.root_session_id
      AND note.id = receipt_row.replacement_note_id;
    replayed := true;
  ELSE
    SELECT note.* INTO replaced_row
    FROM task_notes note
    WHERE note.workspace_id = p_workspace_id
      AND note.root_session_id = authority.root_session_id
      AND note.id = p_replaced_note_id
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Task note is unavailable for replacement' USING ERRCODE = 'P0002';
    END IF;
    IF replaced_row.status <> 'active'
      OR replaced_row.version <> p_expected_replaced_version
      OR replaced_row.expires_at <= transaction_timestamp()
    THEN
      RAISE EXCEPTION 'Task-note replacement version or lifecycle conflict'
        USING ERRCODE = '40001';
    END IF;

    SELECT * INTO STRICT archived_result FROM archive_task_note_for_attempt(
      p_account_id, p_workspace_id, p_session_id, p_turn_id,
      p_attempt_id, p_execution_generation, p_archive_operation_id,
      p_replaced_note_id, p_expected_replaced_version, p_reason
    );
    SELECT * INTO STRICT created_result FROM create_task_note_for_attempt(
      p_account_id, p_workspace_id, p_session_id, p_turn_id,
      p_attempt_id, p_execution_generation, p_create_operation_id,
      p_replacement_kind, p_replacement_text, p_replacement_expires_in_days
    );
    IF archived_result.note_id IS DISTINCT FROM p_replaced_note_id
      OR archived_result.status IS DISTINCT FROM 'archived'
      OR archived_result.version IS DISTINCT FROM 2
      OR created_result.status IS DISTINCT FROM 'active'
      OR created_result.version IS DISTINCT FROM 1
      OR created_result.root_session_id IS DISTINCT FROM authority.root_session_id
    THEN
      RAISE EXCEPTION 'Task-note replacement lifecycle returned an invalid projection'
        USING ERRCODE = '23514';
    END IF;
    SELECT note.* INTO STRICT replacement_row
    FROM task_notes note
    WHERE note.workspace_id = p_workspace_id
      AND note.root_session_id = authority.root_session_id
      AND note.id = created_result.note_id;

    INSERT INTO task_note_replacement_receipts (
      account_id, workspace_id, root_session_id, operation_id, input_hash,
      replaced_note_id, replaced_note_version, replacement_note_id,
      replacement_note_version, archive_operation_id, create_operation_id,
      actor_kind, actor_subject_id, initiating_human_subject_id,
      actor_session_id, actor_turn_id, actor_attempt_id, actor_execution_generation
    ) VALUES (
      p_account_id, p_workspace_id, authority.root_session_id,
      p_operation_id, calculated_input_hash, p_replaced_note_id, 2,
      replacement_row.id, 1, p_archive_operation_id, p_create_operation_id,
      authority.actor_kind, authority.actor_subject_id,
      authority.initiating_human_subject_id, p_session_id, p_turn_id,
      p_attempt_id, p_execution_generation
    ) RETURNING * INTO STRICT receipt_row;
    replayed := false;
  END IF;

  operation_id := receipt_row.operation_id;
  input_hash := receipt_row.input_hash;
  replaced_note_id := receipt_row.replaced_note_id;
  replaced_note_version := receipt_row.replaced_note_version;
  replacement_note_id := replacement_row.id;
  root_session_id := replacement_row.root_session_id;
  replacement_kind := replacement_row.kind;
  replacement_text := replacement_row.text;
  replacement_status := replacement_row.status;
  replacement_version := replacement_row.version;
  replacement_expires_at := replacement_row.expires_at;
  replacement_created_at := replacement_row.created_at;
  replacement_updated_at := replacement_row.updated_at;
  replacement_archived_at := replacement_row.archived_at;
  replacement_actor_kind := replacement_row.created_by_actor_kind;
  replacement_source_session_id := replacement_row.created_by_session_id;
  replacement_source_turn_id := replacement_row.created_by_turn_id;
  RETURN NEXT;
END;
$$;

CREATE FUNCTION replay_applied_session_fork(p_account_id uuid, p_source_workspace_id uuid, p_source_session_id uuid, p_actor_subject_id text, p_destination_workspace_id uuid, p_destination_visibility text, p_workspace_shared_acknowledged boolean, p_operation_key text, p_canonical_request_hash text, p_activation_version integer) RETURNS TABLE(operation_id uuid, event_id uuid, event_sequence integer, session_id uuid, workspace_id uuid, visibility text, authority_epoch integer, copied_history_item_count integer, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  actor_membership organization_memberships%ROWTYPE;
  receipt_row session_command_receipts%ROWTYPE;
BEGIN
  IF p_account_id IS NULL OR p_source_workspace_id IS NULL
    OR p_source_session_id IS NULL OR p_actor_subject_id IS NULL
    OR p_destination_workspace_id IS NULL OR p_destination_visibility IS NULL
    OR p_workspace_shared_acknowledged IS NULL
    OR p_operation_key IS NULL OR p_canonical_request_hash IS NULL
    OR p_activation_version IS NULL
  THEN RAISE EXCEPTION 'session fork replay requires complete authority'
    USING ERRCODE = '42501'; END IF;
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_source_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
  THEN RAISE EXCEPTION 'session fork replay authority is invalid'
    USING ERRCODE = '42501'; END IF;
  IF p_destination_workspace_id IS DISTINCT FROM p_source_workspace_id
    OR p_destination_visibility NOT IN ('user_private', 'workspace_shared')
    OR (p_destination_visibility = 'user_private' AND p_workspace_shared_acknowledged)
    OR p_actor_subject_id <> btrim(p_actor_subject_id)
    OR length(p_actor_subject_id) NOT BETWEEN 1 AND 1024
    OR p_operation_key <> btrim(p_operation_key)
    OR length(p_operation_key) NOT BETWEEN 1 AND 1024
    OR p_canonical_request_hash !~ '^[0-9a-f]{64}$'
    OR p_activation_version <> 1
  THEN RAISE EXCEPTION 'session fork replay request is invalid'
    USING ERRCODE = '22023'; END IF;
  IF NOT session_tenancy_product_activated(p_account_id, p_activation_version) THEN
    RAISE EXCEPTION 'session tenancy product surface is not activated for this organization'
      USING ERRCODE = '55000';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || p_account_id::text, 0
  ));
  PERFORM 1 FROM workspaces workspace_row
  WHERE workspace_row.account_id = p_account_id
    AND workspace_row.id = p_source_workspace_id
  FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'session fork replay workspace is unavailable'
    USING ERRCODE = '42501'; END IF;

  SELECT membership.* INTO actor_membership
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id
    AND membership.status = 'active'
  FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'session fork replay requires active workspace authority'
    USING ERRCODE = '42501'; END IF;
  IF actor_membership.personal_workspace_id IS DISTINCT FROM p_source_workspace_id THEN
    PERFORM 1 FROM workspace_memberships workspace_membership
    WHERE workspace_membership.account_id = p_account_id
      AND workspace_membership.workspace_id = p_source_workspace_id
      AND workspace_membership.subject_id = p_actor_subject_id
    FOR KEY SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'session fork replay requires active workspace authority'
      USING ERRCODE = '42501'; END IF;
  END IF;

  SELECT receipt.* INTO receipt_row FROM session_command_receipts receipt
  WHERE receipt.account_id = p_account_id
    AND receipt.workspace_id = p_source_workspace_id
    AND receipt.actor_type = 'human' AND receipt.actor_subject_id = p_actor_subject_id
    AND receipt.actor_attempt_id IS NULL AND receipt.action = 'session.fork'
    AND receipt.target_session_id = p_source_session_id
    AND receipt.target_turn_id IS NULL AND receipt.operation_key = p_operation_key;
  IF NOT FOUND OR receipt_row.result ->> 'status' <> 'applied' THEN RETURN; END IF;
  IF receipt_row.canonical_request_hash <> p_canonical_request_hash THEN
    RAISE EXCEPTION 'session fork idempotency conflict' USING ERRCODE = '23505';
  END IF;

  operation_id := receipt_row.id;
  event_id := nullif(receipt_row.result ->> 'eventId', '')::uuid;
  event_sequence := (receipt_row.result ->> 'eventSequence')::integer;
  session_id := (receipt_row.result ->> 'sessionId')::uuid;
  workspace_id := (receipt_row.result ->> 'workspaceId')::uuid;
  visibility := receipt_row.result ->> 'visibility';
  authority_epoch := 1;
  copied_history_item_count :=
    (receipt_row.result ->> 'copiedHistoryItemCount')::integer;
  replay := true;
  RETURN NEXT;
END
$_$;

COMMENT ON FUNCTION replay_applied_session_fork(p_account_id uuid, p_source_workspace_id uuid, p_source_session_id uuid, p_actor_subject_id text, p_destination_workspace_id uuid, p_destination_visibility text, p_workspace_shared_acknowledged boolean, p_operation_key text, p_canonical_request_hash text, p_activation_version integer) IS 'Exact actor/workspace/source/key/hash-bound recovery of one already-applied fork receipt; fresh keys return no row and mutable source authority is not consulted.';

CREATE FUNCTION replay_applied_session_fork_with_runtime(p_account_id uuid, p_source_workspace_id uuid, p_source_session_id uuid, p_actor_subject_id text, p_destination_workspace_id uuid, p_destination_visibility text, p_workspace_shared_acknowledged boolean, p_operation_key text, p_canonical_request_hash text, p_activation_version integer, p_configuration_digest text) RETURNS TABLE(operation_id uuid, event_id uuid, event_sequence integer, session_id uuid, workspace_id uuid, visibility text, authority_epoch integer, copied_history_item_count integer, replay boolean, runtime_event_id uuid, runtime_event_sequence integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  SELECT fork_result.operation_id, fork_result.event_id, fork_result.event_sequence,
    fork_result.session_id, fork_result.workspace_id, fork_result.visibility,
    fork_result.authority_epoch, fork_result.copied_history_item_count, fork_result.replay
  INTO operation_id, event_id, event_sequence, session_id, workspace_id, visibility,
    authority_epoch, copied_history_item_count, replay
  FROM replay_applied_session_fork(
    p_account_id, p_source_workspace_id, p_source_session_id, p_actor_subject_id,
    p_destination_workspace_id, p_destination_visibility,
    p_workspace_shared_acknowledged, p_operation_key, p_canonical_request_hash,
    p_activation_version
  ) fork_result;
  IF session_id IS NULL THEN
    RETURN;
  END IF;
  SELECT configured.runtime_event_id, configured.runtime_event_sequence
  INTO runtime_event_id, runtime_event_sequence
  FROM opengeni_private.read_fork_session_runtime(
    p_account_id, p_source_workspace_id, p_source_session_id, session_id,
    p_actor_subject_id, p_configuration_digest
  ) configured;
  RETURN NEXT;
END
$$;

CREATE FUNCTION replay_managed_sign_in_method(p_user text, p_session text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE prior managed_sign_in_method_operations%ROWTYPE; revision_value bigint;
  previous_marker text := current_setting('opengeni.canonical_human_identity_lifecycle',true);
BEGIN
  PERFORM set_config('opengeni.canonical_human_identity_lifecycle','active',true);
  SELECT * INTO prior FROM managed_sign_in_method_operations WHERE operation_id=(p_request->>'operationId')::uuid;
  IF NOT FOUND THEN
    PERFORM set_config('opengeni.canonical_human_identity_lifecycle',coalesce(previous_marker,''),true);
    RETURN NULL;
  END IF;
  IF prior.auth_user_id IS DISTINCT FROM p_user OR prior.request_digest IS DISTINCT FROM p_request->>'requestDigest' THEN
    RAISE EXCEPTION 'SIGN_IN_METHOD_OPERATION_REUSED' USING ERRCODE='23505';
  END IF;
  SELECT i.identity_revision INTO revision_value FROM canonical_human_identities i
    JOIN canonical_human_identity_subjects s ON s.identity_id=i.id WHERE s.auth_user_id=p_user AND s.status='active';
  PERFORM managed_sign_in_method_authority(p_user,p_session,p_request || jsonb_build_object('expectedIdentityRevision',revision_value));
  PERFORM set_config('opengeni.canonical_human_identity_lifecycle',coalesce(previous_marker,''),true);
  RETURN jsonb_build_object('reauthenticationRequired',true,'notification',CASE WHEN prior.notification_status='pending' THEN 'outcome_unknown' ELSE prior.notification_status END);
END $$;

CREATE FUNCTION resolve_accepted_connection_use(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_physical_request_id uuid, p_use_phase text, p_server_id text, p_connection_id uuid, p_provider_domain text, p_connection_kind text, p_subject_scope text, p_owner_subject_id text DEFAULT NULL::text) RETURNS TABLE(authorization_status text, denial_reason text, resolved_connection_id uuid, connection_generation bigint, origin_workspace_id uuid, resolved_connection_kind text, authority_scope text, owner_subject_id text, authority_id uuid, grant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
#variable_conflict use_column
DECLARE
  sender_prior_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  prior record;
  connection_row record;
  snapshot record;
  session_row record;
  turn_row record;
  audit_initiator_kind text;
  audit_initiator_subject text;
  audit_initiating_human text;
  audit_authority_epoch integer;
  audit_authority_visibility text;
  audit_owner_membership uuid;
  request_digest bytea;
  has_prior boolean := false;
  reason text;
  scheduled_run_id uuid;
  exact_binding jsonb;
BEGIN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true);
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id', true), '')::uuid
    OR p_execution_generation <= 0
    OR p_use_phase NOT IN ('credential_resolution', 'provider_request')
    OR nullif(btrim(p_server_id), '') IS NULL OR octet_length(p_server_id) > 256
  THEN RAISE EXCEPTION 'connection use scope mismatch' USING ERRCODE = '42501';
  END IF;
  request_digest := digest(convert_to(jsonb_build_object(
    'accountId', p_account_id, 'workspaceId', p_workspace_id,
    'sessionId', p_session_id, 'turnId', p_turn_id, 'attemptId', p_attempt_id,
    'executionGeneration', p_execution_generation, 'usePhase', p_use_phase,
    'serverId', p_server_id, 'connectionId', p_connection_id,
    'providerDomain', lower(p_provider_domain), 'connectionKind', p_connection_kind,
    'subjectScope', p_subject_scope, 'ownerSubjectId', p_owner_subject_id
  )::text, 'UTF8'), 'sha256');

  -- Canonical lifecycle lock prefix: control -> workspace -> session -> turn -> attempt.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('workspace-control:' || p_workspace_id::text, 0));
  PERFORM 1 FROM workspace_inference_controls control_row
  WHERE control_row.account_id = p_account_id AND control_row.workspace_id = p_workspace_id
  FOR SHARE;
  IF NOT FOUND THEN reason := 'session_identity_changed'; END IF;
  IF reason IS NULL THEN
    PERFORM 1 FROM workspaces workspace_value
    WHERE workspace_value.account_id = p_account_id AND workspace_value.id = p_workspace_id
    FOR KEY SHARE;
    IF NOT FOUND THEN reason := 'session_identity_changed'; END IF;
  END IF;
  IF reason IS NULL THEN
    SELECT session_value.* INTO session_row FROM sessions session_value
    WHERE session_value.id = p_session_id AND session_value.account_id = p_account_id
      AND session_value.workspace_id = p_workspace_id
    FOR SHARE;
    IF NOT FOUND OR session_row.active_turn_id IS DISTINCT FROM p_turn_id
      OR session_row.status = 'cancelled'
    THEN reason := 'session_identity_changed'; END IF;
    -- Attribution evidence (0280): captured from the row this same
    -- transaction locked, NULL when the fence never loaded it.
    audit_authority_epoch := session_row.authority_epoch;
    audit_authority_visibility := session_row.visibility;
    audit_owner_membership := session_row.owner_organization_membership_id;
  END IF;
  IF reason IS NULL THEN
    SELECT turn_value.* INTO turn_row FROM session_turns turn_value
    WHERE turn_value.id = p_turn_id AND turn_value.account_id = p_account_id
      AND turn_value.workspace_id = p_workspace_id AND turn_value.session_id = p_session_id
      AND turn_value.active_attempt_id = p_attempt_id
      AND turn_value.execution_generation = p_execution_generation
      AND turn_value.status = 'running'
    FOR SHARE;
    IF NOT FOUND THEN reason := 'session_identity_changed'; END IF;
    -- Causal-initiator evidence (0280): the frozen turn identity, recorded
    -- verbatim (a pre-0096 sentinel stays the sentinel), NULL when the turn
    -- fence never matched a row.
    audit_initiator_kind := turn_row.initiator_kind;
    audit_initiator_subject := turn_row.initiator_subject_id;
    audit_initiating_human := turn_row.initiating_human_subject_id;
  END IF;
  IF reason IS NULL THEN
    PERFORM 1 FROM session_turn_attempts attempt
    WHERE attempt.id = p_attempt_id AND attempt.account_id = p_account_id
      AND attempt.workspace_id = p_workspace_id AND attempt.session_id = p_session_id
      AND attempt.turn_id = p_turn_id
      AND attempt.execution_generation = p_execution_generation
      AND attempt.state IN ('claimed', 'running')
      AND attempt.closed_at IS NULL AND attempt.quiesced_at IS NULL
      AND (attempt.authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
      AND attempt.authority_owner_organization_membership_id
        IS NOT DISTINCT FROM session_row.owner_organization_membership_id
    FOR SHARE;
    IF NOT FOUND OR EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.account_id = p_account_id
        AND interruption.workspace_id = p_workspace_id
        AND interruption.session_id = p_session_id
        AND interruption.attempt_id = p_attempt_id
        AND interruption.state IN ('pending', 'delivered', 'acknowledged')
    ) THEN reason := 'session_identity_changed'; END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_physical_request_id::text, 0));
  SELECT EXISTS (SELECT 1 FROM connection_use_audit_facts audit
    WHERE audit.physical_request_id = p_physical_request_id) INTO has_prior;
  -- Only dereference `prior` inside the guarded branch: PL/pgSQL evaluates
  -- both operands of `has_prior AND prior.<field>`, and an unassigned record
  -- raises instead of yielding NULL.
  IF has_prior THEN
    SELECT audit.* INTO STRICT prior FROM connection_use_audit_facts audit
    WHERE audit.physical_request_id = p_physical_request_id;
    IF prior.request_digest IS DISTINCT FROM request_digest THEN
      RAISE EXCEPTION 'physical connection request id was reused for different work'
        USING ERRCODE = '23505';
    END IF;
    IF reason IS NULL AND prior.outcome = 'denied' THEN
      authorization_status := prior.outcome; denial_reason := prior.denial_reason;
      RETURN NEXT; PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN;
    END IF;
  END IF;


  -- 0494 exact accepted account gate, inside the canonical lifecycle locks.
  IF reason IS NULL THEN
    SELECT value INTO exact_binding FROM jsonb_array_elements(turn_row.mcp_account_bindings)
    WHERE value ->> 'serverId' = p_server_id;
    IF FOUND THEN
      IF p_connection_id IS DISTINCT FROM (exact_binding ->> 'connectionId')::uuid
        OR p_subject_scope IS DISTINCT FROM exact_binding ->> 'subjectScope'
        OR p_owner_subject_id IS DISTINCT FROM exact_binding ->> 'ownerSubjectId'
        OR lower(p_provider_domain) IS DISTINCT FROM lower(exact_binding ->> 'providerDomain')
        OR p_connection_kind IS DISTINCT FROM exact_binding ->> 'kind'
      THEN reason := 'accepted_account_binding_changed';
      ELSE
        SELECT c.* INTO connection_row FROM opengeni_private.read_sender_connection(
          p_account_id, (exact_binding ->> 'originWorkspaceId')::uuid, p_connection_id,
          exact_binding ->> 'ownerSubjectId') c;
        IF NOT FOUND THEN reason := 'connection_missing';
        ELSIF connection_row.status IS DISTINCT FROM 'active' THEN reason := 'connection_status_inactive';
        ELSIF exact_binding ? 'connectionAuthorityGeneration' AND connection_row.authority_generation
          IS DISTINCT FROM (exact_binding ->> 'connectionAuthorityGeneration')::bigint
        THEN reason := 'connection_generation_changed';
        ELSIF p_subject_scope = 'workspace' AND (
          NOT exact_binding ? 'connectionAuthorityGeneration'
          OR exact_binding ->> 'originWorkspaceId' IS DISTINCT FROM p_workspace_id::text)
        THEN reason := 'accepted_account_binding_changed';
        END IF;
      END IF;
    ELSIF p_server_id = 'github:personal' AND p_subject_scope = 'subject'
      AND lower(p_provider_domain) = 'github.com' AND p_connection_kind = 'oauth2'
      AND EXISTS (
        SELECT 1 FROM turn_connection_authority_snapshots specialized
        WHERE specialized.account_id = p_account_id AND specialized.workspace_id = p_workspace_id
          AND specialized.session_id = p_session_id AND specialized.turn_id = p_turn_id
          AND specialized.server_id = p_server_id AND specialized.connection_id = p_connection_id
          AND specialized.authority_source = 'sender' AND specialized.authority_scope = 'user'
          AND specialized.owner_subject_id = p_owner_subject_id
      ) AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(turn_row.personal_connection_delegations) selected
        WHERE selected ->> 'connectionType' = 'github_personal'
          AND selected ->> 'serverId' = p_server_id
          AND selected ->> 'connectionId' = p_connection_id::text
          AND selected ->> 'ownerSubjectId' = p_owner_subject_id
      ) THEN
      -- Git broker and GitHub REST use a separate repository-selection receipt,
      -- not a generic MCP alias. Continue into the existing snapshot-only lane
      -- below, including its digest, sender, membership and revocation checks.
      NULL;
    ELSIF turn_row.mcp_account_bindings IS NOT NULL OR p_server_id ~ '^account-[0-9a-f]{64}$' THEN
      reason := 'accepted_account_binding_required';
    END IF;
  END IF;
  IF reason IS NULL THEN
    SELECT authority_snapshot.* INTO snapshot
    FROM turn_connection_authority_snapshots authority_snapshot
    WHERE authority_snapshot.turn_id = p_turn_id
      AND authority_snapshot.server_id = p_server_id
      AND authority_snapshot.account_id = p_account_id
      AND authority_snapshot.workspace_id = p_workspace_id
      AND authority_snapshot.session_id = p_session_id;
    IF FOUND THEN
      scheduled_run_id := CASE
        WHEN snapshot.canonical_snapshot -> 'acceptedWork' ->> 'kind' = 'scheduled_task'
        THEN nullif(snapshot.canonical_snapshot -> 'acceptedWork' ->> 'runId', '')::uuid
        ELSE NULL END;
      SELECT connection_value.* INTO connection_row
      FROM opengeni_private.read_sender_connection(
        p_account_id, snapshot.origin_workspace_id, snapshot.connection_id, snapshot.owner_subject_id
      ) connection_value;
      IF snapshot.snapshot_digest IS DISTINCT FROM digest(
        convert_to(snapshot.canonical_snapshot::text, 'UTF8'), 'sha256'
      ) THEN reason := 'accepted_snapshot_digest_changed';
      ELSIF NOT FOUND THEN reason := 'connection_missing';
      ELSIF snapshot.authority_source IS DISTINCT FROM 'sender'
        OR snapshot.authority_scope IS DISTINCT FROM 'user'
        OR p_subject_scope IS DISTINCT FROM 'subject'
        OR p_connection_id IS DISTINCT FROM snapshot.connection_id
        OR lower(p_provider_domain) IS DISTINCT FROM snapshot.provider_domain
        OR (p_connection_kind IS NOT NULL
          AND p_connection_kind IS DISTINCT FROM snapshot.connection_kind)
      THEN reason := 'connection_identity_changed';
      ELSIF connection_row.status <> 'active' THEN reason := 'connection_status_inactive';
      ELSIF connection_row.authority_scope IS DISTINCT FROM 'user'
        OR connection_row.subject_id IS DISTINCT FROM snapshot.owner_subject_id
        OR connection_row.owner_organization_membership_id
          IS DISTINCT FROM snapshot.owner_organization_membership_id
        OR connection_row.origin_workspace_id IS DISTINCT FROM snapshot.origin_workspace_id
      THEN reason := 'connection_owner_changed';
      ELSIF connection_row.authority_generation IS DISTINCT FROM snapshot.connection_generation
      THEN reason := 'connection_generation_changed';
      ELSIF NOT (snapshot.session_authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch)
      THEN reason := 'session_authority_epoch_changed';
      ELSIF NOT EXISTS (
        SELECT 1 FROM organization_memberships membership
        WHERE membership.id = snapshot.owner_organization_membership_id
          AND membership.account_id = p_account_id
          AND membership.subject_id = snapshot.owner_subject_id
          AND membership.status = 'active' AND membership.revoked_at IS NULL
          AND membership.authorization_revision = snapshot.membership_authorization_revision
          AND (membership.personal_workspace_id = p_workspace_id OR EXISTS (
            SELECT 1 FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = p_account_id
              AND workspace_membership.workspace_id = p_workspace_id
              AND workspace_membership.subject_id = snapshot.owner_subject_id
          ))
      ) THEN reason := 'owner_membership_inactive';
      ELSIF NOT EXISTS (
        SELECT 1 FROM organization_user_resource_authorities authority
        WHERE authority.id = snapshot.authority_id AND authority.account_id = p_account_id
          AND authority.organization_membership_id = snapshot.owner_organization_membership_id
          AND authority.resource_kind = 'connection'
          AND authority.resource_id = snapshot.connection_id
          AND authority.origin_workspace_id = snapshot.origin_workspace_id
          AND authority.generation = snapshot.authority_generation
          AND authority.status = 'active' AND authority.revoked_at IS NULL
      ) THEN reason := 'authority_status_inactive';
      END IF;
      resolved_connection_id := snapshot.connection_id;
      connection_generation := snapshot.connection_generation;
      origin_workspace_id := snapshot.origin_workspace_id;
      resolved_connection_kind := snapshot.connection_kind;
      authority_scope := snapshot.authority_scope;
      owner_subject_id := snapshot.owner_subject_id;
      authority_id := snapshot.authority_id;
      grant_id := snapshot.grant_id;
    ELSIF p_subject_scope = 'workspace' THEN
      -- Workspace lane (0279): a workspace-owned connection is ambient shared
      -- workspace capability, never frozen on the turn, so it is validated
      -- against the live row inside the same canonical lifecycle fences and
      -- recorded in the same idempotent audit facts. A frozen per-turn
      -- personal snapshot for this server takes the snapshot lane above and
      -- therefore denies a workspace-scope request outright (fail closed).
      SELECT connection_value.* INTO connection_row
      FROM opengeni_private.read_sender_connection(p_account_id, p_workspace_id, p_connection_id, NULL) connection_value;
      IF p_connection_id IS NULL OR NOT FOUND THEN reason := 'connection_missing';
      ELSIF connection_row.authority_scope IS DISTINCT FROM 'workspace'
        OR p_owner_subject_id IS NOT NULL
        OR connection_row.workspace_id IS DISTINCT FROM p_workspace_id
        OR connection_row.origin_workspace_id IS DISTINCT FROM p_workspace_id
        OR lower(connection_row.provider_domain) IS DISTINCT FROM lower(p_provider_domain)
        OR (p_connection_kind IS NOT NULL
          AND connection_row.kind IS DISTINCT FROM p_connection_kind)
      THEN reason := 'connection_identity_changed';
      ELSIF connection_row.status <> 'active' THEN reason := 'connection_status_inactive';
      ELSE
        resolved_connection_id := connection_row.id;
        connection_generation := connection_row.authority_generation;
        origin_workspace_id := connection_row.origin_workspace_id;
        resolved_connection_kind := connection_row.kind;
        authority_scope := 'workspace';
      END IF;
    ELSE
      reason := 'accepted_attempt_authority_required';
    END IF;
  END IF;

  authorization_status := CASE WHEN reason IS NULL THEN 'authorized' ELSE 'denied' END;
  denial_reason := reason;
  IF NOT has_prior THEN
    INSERT INTO connection_use_audit_facts (
      physical_request_id, use_phase, request_digest, account_id, workspace_id,
      session_id, turn_id, attempt_id, execution_generation, server_id,
      connection_id, connection_generation, authority_scope, owner_subject_id,
      authority_id, grant_id, outcome, denial_reason,
      initiator_kind, initiator_subject_id, initiating_human_subject_id,
      authority_epoch, authority_visibility,
      authority_owner_organization_membership_id
    ) VALUES (
      p_physical_request_id, p_use_phase, request_digest, p_account_id,
      p_workspace_id, p_session_id, p_turn_id, p_attempt_id,
      p_execution_generation, p_server_id, resolved_connection_id,
      connection_generation, authority_scope, owner_subject_id, authority_id,
      grant_id, authorization_status, denial_reason,
      audit_initiator_kind, audit_initiator_subject, audit_initiating_human,
      audit_authority_epoch, audit_authority_visibility, audit_owner_membership
    ) ON CONFLICT (physical_request_id) DO NOTHING;
  END IF;
  RETURN NEXT;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true);
EXCEPTION WHEN OTHERS THEN RAISE;
END
$_$;

CREATE FUNCTION resolve_connection_use_authority_legacy_0256(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_snapshot jsonb) RETURNS TABLE(authorization_status text, denial_reason text, connection_id uuid, connection_generation bigint, authority_scope text, owner_subject_id text, authority_id uuid, grant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  session_row record;
  connection_row record;
  membership_row record;
  authority_row record;
  grant_row record;
  receipt_row record;
  accepted_kind text := p_snapshot #>> '{acceptedWork,kind}';
  accepted_id uuid := coalesce(
    nullif(p_snapshot #>> '{acceptedWork,turnId}', '')::uuid,
    nullif(p_snapshot #>> '{acceptedWork,taskId}', '')::uuid
  );
  snapshot_scope text := p_snapshot ->> 'scope';
  snapshot_owner text := nullif(p_snapshot ->> 'ownerSubjectId', '');
  snapshot_membership uuid := nullif(
    p_snapshot ->> 'ownerOrganizationMembershipId', ''
  )::uuid;
  snapshot_authority uuid := nullif(
    p_snapshot #>> '{userDelegation,authorityId}', ''
  )::uuid;
  snapshot_grant uuid := nullif(p_snapshot #>> '{userDelegation,grantId}', '')::uuid;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
    OR p_snapshot ->> 'organizationId' IS DISTINCT FROM p_account_id::text
    OR p_snapshot ->> 'targetWorkspaceId' IS DISTINCT FROM p_workspace_id::text
    OR p_snapshot ->> 'targetSessionId' IS DISTINCT FROM p_session_id::text
  THEN
    RAISE EXCEPTION 'connection use scope mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT session_value.id, session_value.account_id, session_value.workspace_id,
    session_value.visibility, session_value.authority_epoch, session_value.status
  INTO session_row
  FROM sessions session_value
  WHERE session_value.id = p_session_id
    AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id;
  IF NOT FOUND OR session_row.status = 'cancelled' THEN
    authorization_status := 'denied'; denial_reason := 'session_inactive';
    RETURN NEXT; RETURN;
  END IF;
  IF session_row.visibility IS DISTINCT FROM p_snapshot ->> 'targetSessionVisibility' THEN
    authorization_status := 'denied'; denial_reason := 'session_visibility_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF session_row.authority_epoch IS DISTINCT FROM (
    p_snapshot ->> 'targetSessionAuthorityEpoch'
  )::integer THEN
    authorization_status := 'denied'; denial_reason := 'session_authority_epoch_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF accepted_kind = 'turn' AND NOT EXISTS (
    SELECT 1 FROM session_turns turn_value
    WHERE turn_value.id = accepted_id
      AND turn_value.account_id = p_account_id
      AND turn_value.workspace_id = p_workspace_id
      AND turn_value.session_id = p_session_id
      AND turn_value.status <> 'cancelled'
  ) THEN
    authorization_status := 'denied'; denial_reason := 'session_identity_changed';
    RETURN NEXT; RETURN;
  ELSIF accepted_kind = 'scheduled_task' AND NOT EXISTS (
    SELECT 1 FROM scheduled_tasks task
    WHERE task.id = accepted_id
      AND task.account_id = p_account_id
      AND task.workspace_id = p_workspace_id
      AND task.authority_revision = (
        p_snapshot #>> '{acceptedWork,taskAuthorityRevision}'
      )::bigint
      AND task.status = 'active'
  ) THEN
    authorization_status := 'denied'; denial_reason := 'session_identity_changed';
    RETURN NEXT; RETURN;
  END IF;

  SELECT connection_value.id, connection_value.account_id,
    connection_value.workspace_id, connection_value.origin_workspace_id,
    connection_value.subject_id, connection_value.provider_domain,
    connection_value.kind, connection_value.status,
    connection_value.authority_scope, connection_value.authority_id,
    connection_value.owner_organization_membership_id,
    connection_value.authority_generation
  INTO connection_row
  FROM connections connection_value
  WHERE connection_value.id = (p_snapshot ->> 'connectionId')::uuid
    AND connection_value.account_id = p_account_id;
  IF NOT FOUND THEN
    authorization_status := 'denied'; denial_reason := 'connection_missing';
    RETURN NEXT; RETURN;
  END IF;
  IF connection_row.origin_workspace_id::text IS DISTINCT FROM
      p_snapshot ->> 'originWorkspaceId'
    OR lower(connection_row.provider_domain) IS DISTINCT FROM lower(
      p_snapshot ->> 'providerDomain'
    )
    OR connection_row.kind IS DISTINCT FROM p_snapshot ->> 'connectionKind'
    OR connection_row.authority_scope IS DISTINCT FROM snapshot_scope
  THEN
    authorization_status := 'denied'; denial_reason := 'connection_identity_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF connection_row.authority_generation IS DISTINCT FROM (
    p_snapshot ->> 'connectionGeneration'
  )::bigint THEN
    authorization_status := 'denied'; denial_reason := 'connection_generation_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF connection_row.status <> 'active' THEN
    authorization_status := 'denied'; denial_reason := 'connection_status_inactive';
    RETURN NEXT; RETURN;
  END IF;
  IF connection_row.subject_id IS DISTINCT FROM snapshot_owner
    OR connection_row.owner_organization_membership_id
      IS DISTINCT FROM snapshot_membership
  THEN
    authorization_status := 'denied'; denial_reason := 'connection_owner_changed';
    RETURN NEXT; RETURN;
  END IF;

  connection_id := connection_row.id;
  connection_generation := connection_row.authority_generation;
  authority_scope := snapshot_scope;
  owner_subject_id := snapshot_owner;
  authority_id := snapshot_authority;
  grant_id := snapshot_grant;

  IF snapshot_scope = 'workspace' THEN
    IF connection_row.workspace_id <> p_workspace_id
      OR connection_row.origin_workspace_id <> p_workspace_id
      OR connection_row.subject_id IS NOT NULL
      OR snapshot_authority IS NOT NULL
      OR snapshot_grant IS NOT NULL
    THEN
      authorization_status := 'denied'; denial_reason := 'connection_owner_changed';
      RETURN NEXT; RETURN;
    END IF;
    authorization_status := 'authorized'; denial_reason := NULL;
    RETURN NEXT; RETURN;
  END IF;

  SELECT membership.id, membership.account_id, membership.subject_id,
    membership.status, membership.revoked_at
  INTO membership_row
  FROM organization_memberships membership
  WHERE membership.id = snapshot_membership
    AND membership.account_id = p_account_id
    AND membership.subject_id = snapshot_owner;
  IF NOT FOUND OR membership_row.status <> 'active' OR membership_row.revoked_at IS NOT NULL
    OR NOT EXISTS (
      SELECT 1 FROM organization_memberships membership
      WHERE membership.id = snapshot_membership
        AND (
          membership.personal_workspace_id = p_workspace_id
          OR EXISTS (
            SELECT 1 FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = p_account_id
              AND workspace_membership.workspace_id = p_workspace_id
              AND workspace_membership.subject_id = snapshot_owner
          )
        )
    )
  THEN
    authorization_status := 'denied'; denial_reason := 'owner_membership_inactive';
    RETURN NEXT; RETURN;
  END IF;

  SELECT authority.id, authority.account_id, authority.organization_membership_id,
    authority.resource_kind, authority.resource_id, authority.origin_workspace_id,
    authority.generation, authority.status, authority.revoked_at
  INTO authority_row
  FROM organization_user_resource_authorities authority
  WHERE authority.id = snapshot_authority
    AND authority.account_id = p_account_id;
  IF NOT FOUND THEN
    authorization_status := 'denied'; denial_reason := 'authority_missing';
    RETURN NEXT; RETURN;
  END IF;
  IF authority_row.organization_membership_id <> snapshot_membership
    OR authority_row.resource_kind <> 'connection'
    OR authority_row.resource_id <> connection_row.id
    OR authority_row.origin_workspace_id <> connection_row.origin_workspace_id
  THEN
    authorization_status := 'denied'; denial_reason := 'authority_identity_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF authority_row.generation IS DISTINCT FROM (
    p_snapshot #>> '{userDelegation,authorityGeneration}'
  )::bigint THEN
    authorization_status := 'denied'; denial_reason := 'authority_generation_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF authority_row.status <> 'active' OR authority_row.revoked_at IS NOT NULL THEN
    authorization_status := 'denied'; denial_reason := 'authority_status_inactive';
    RETURN NEXT; RETURN;
  END IF;

  SELECT grant_value.id, grant_value.account_id, grant_value.authority_id,
    grant_value.owner_organization_membership_id, grant_value.workspace_id,
    grant_value.session_id, grant_value.action, grant_value.mode,
    grant_value.context, grant_value.authority_epoch, grant_value.generation,
    grant_value.status, grant_value.expires_at
  INTO grant_row
  FROM organization_user_resource_grants grant_value
  WHERE grant_value.id = snapshot_grant
    AND grant_value.account_id = p_account_id
  FOR UPDATE;
  IF NOT FOUND THEN
    authorization_status := 'denied'; denial_reason := 'grant_missing';
    RETURN NEXT; RETURN;
  END IF;
  IF grant_row.authority_id <> snapshot_authority
    OR grant_row.owner_organization_membership_id <> snapshot_membership
    OR grant_row.workspace_id <> p_workspace_id
    OR grant_row.action <> 'connection.use'
    OR grant_row.mode IS DISTINCT FROM p_snapshot #>> '{userDelegation,mode}'
    OR grant_row.context IS DISTINCT FROM p_snapshot ->> 'targetSessionVisibility'
    OR grant_row.session_id IS DISTINCT FROM nullif(
      p_snapshot #>> '{userDelegation,sessionId}', ''
    )::uuid
    OR grant_row.authority_epoch IS DISTINCT FROM nullif(
      p_snapshot #>> '{userDelegation,authorityEpoch}', ''
    )::integer
  THEN
    authorization_status := 'denied'; denial_reason := 'grant_identity_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF grant_row.generation IS DISTINCT FROM (
    p_snapshot #>> '{userDelegation,grantGeneration}'
  )::bigint THEN
    authorization_status := 'denied'; denial_reason := 'grant_generation_changed';
    RETURN NEXT; RETURN;
  END IF;
  IF grant_row.expires_at IS NOT NULL AND grant_row.expires_at <= clock_timestamp() THEN
    authorization_status := 'denied'; denial_reason := 'grant_expired';
    RETURN NEXT; RETURN;
  END IF;

  IF grant_row.mode = 'once' THEN
    SELECT receipt.accepted_work_kind, receipt.accepted_work_id
    INTO receipt_row
    FROM connection_use_once_consumption_receipts receipt
    WHERE receipt.grant_id = grant_row.id;
    IF FOUND THEN
      IF receipt_row.accepted_work_kind IS DISTINCT FROM accepted_kind
        OR receipt_row.accepted_work_id IS DISTINCT FROM accepted_id
      THEN
        authorization_status := 'denied'; denial_reason := 'grant_already_consumed';
        RETURN NEXT; RETURN;
      END IF;
    ELSIF grant_row.status = 'active' THEN
      UPDATE organization_user_resource_grants
      SET status = 'consumed', updated_at = clock_timestamp()
      WHERE id = grant_row.id AND account_id = p_account_id
        AND generation = grant_row.generation AND status = 'active';
      IF NOT FOUND THEN
        authorization_status := 'denied'; denial_reason := 'grant_already_consumed';
        RETURN NEXT; RETURN;
      END IF;
      INSERT INTO connection_use_once_consumption_receipts (
        grant_id, account_id, authority_id, authority_generation,
        grant_generation, accepted_work_kind, accepted_work_id
      ) VALUES (
        grant_row.id, p_account_id, snapshot_authority, authority_row.generation,
        grant_row.generation, accepted_kind, accepted_id
      );
    ELSE
      authorization_status := 'denied'; denial_reason := 'grant_status_inactive';
      RETURN NEXT; RETURN;
    END IF;
  ELSIF grant_row.status <> 'active' THEN
    authorization_status := 'denied'; denial_reason := 'grant_status_inactive';
    RETURN NEXT; RETURN;
  END IF;

  authorization_status := 'authorized'; denial_reason := NULL;
  RETURN NEXT;
END
$$;

CREATE FUNCTION resolve_document_original_file(p_account_id uuid, p_request_workspace_id uuid, p_actor_id text, p_document_id uuid) RETURNS SETOF files
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      document_row {{schema}}.documents%ROWTYPE;
      authority_row {{schema}}.organization_user_resource_authorities%ROWTYPE;
      owner_membership_row {{schema}}.organization_memberships%ROWTYPE;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.account_id', true), ''
        )::uuid
        OR p_request_workspace_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.workspace_id', true), ''
        )::uuid
        OR p_actor_id IS NULL
        OR p_actor_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.subject_id', true), ''
        )
        OR p_document_id IS NULL
      THEN
        RAISE EXCEPTION 'document original-file scope mismatch' USING ERRCODE = '42501';
      END IF;

      INSERT INTO opengeni_private.personal_document_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'resolve')
      ON CONFLICT DO NOTHING;

      SELECT document_value.* INTO document_row
      FROM {{schema}}.documents document_value
      WHERE document_value.id = p_document_id
        AND document_value.account_id = p_account_id
        AND (
          (
            document_value.authority_kind = 'organization'
            AND document_value.authority_workspace_id IS NULL
            AND document_value.authority_subject_id IS NULL
          ) OR (
            document_value.authority_kind = 'workspace'
            AND document_value.authority_workspace_id = p_request_workspace_id
            AND document_value.authority_subject_id IS NULL
          ) OR (
            document_value.authority_kind = 'personal'
            AND document_value.authority_subject_id = p_actor_id
            AND (
              (
                document_value.authority_id IS NULL
                AND document_value.owner_organization_membership_id IS NULL
                AND document_value.authority_workspace_id = p_request_workspace_id
              ) OR (
                document_value.authority_id IS NOT NULL
                AND document_value.owner_organization_membership_id IS NOT NULL
                AND document_value.authority_workspace_id IS NULL
              )
            )
          )
        )
      FOR SHARE;
      IF NOT FOUND THEN
        DELETE FROM opengeni_private.personal_document_authority_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'resolve';
        RETURN;
      END IF;

      IF document_row.authority_kind = 'personal' AND document_row.authority_id IS NOT NULL THEN
        SELECT authority.* INTO authority_row
        FROM {{schema}}.organization_user_resource_authorities authority
        WHERE authority.id = document_row.authority_id
          AND authority.account_id = document_row.account_id
          AND authority.organization_membership_id
            = document_row.owner_organization_membership_id
          AND authority.resource_kind = 'document'
          AND authority.resource_id = document_row.id
          AND authority.status = 'active'
          AND authority.revoked_at IS NULL
        FOR SHARE;
        IF NOT FOUND THEN
          DELETE FROM opengeni_private.personal_document_authority_capabilities
          WHERE backend_pid = pg_catalog.pg_backend_pid()
            AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
            AND capability_kind = 'resolve';
          RETURN;
        END IF;

        SELECT membership.* INTO owner_membership_row
        FROM {{schema}}.organization_memberships membership
        WHERE membership.id = authority_row.organization_membership_id
          AND membership.account_id = authority_row.account_id
          AND membership.subject_id = p_actor_id
          AND membership.status = 'active'
          AND membership.revoked_at IS NULL
        FOR SHARE;
        IF NOT FOUND THEN
          DELETE FROM opengeni_private.personal_document_authority_capabilities
          WHERE backend_pid = pg_catalog.pg_backend_pid()
            AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
            AND capability_kind = 'resolve';
          RETURN;
        END IF;

        IF owner_membership_row.personal_workspace_id IS DISTINCT FROM p_request_workspace_id THEN
          PERFORM 1
          FROM {{schema}}.workspace_memberships workspace_membership
          WHERE workspace_membership.account_id = p_account_id
            AND workspace_membership.workspace_id = p_request_workspace_id
            AND workspace_membership.subject_id = p_actor_id
          FOR SHARE;
          IF NOT FOUND THEN
            DELETE FROM opengeni_private.personal_document_authority_capabilities
            WHERE backend_pid = pg_catalog.pg_backend_pid()
              AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
              AND capability_kind = 'resolve';
            RETURN;
          END IF;
        END IF;
      END IF;

      RETURN QUERY
      SELECT file_value.*
      FROM {{schema}}.files file_value
      WHERE file_value.id = document_row.file_id
        AND file_value.account_id = document_row.account_id
        AND file_value.workspace_id = document_row.origin_workspace_id
        AND {{schema}}.google_drive_file_authorized(
          p_account_id, p_request_workspace_id, p_actor_id, file_value.id
        )
      FOR SHARE;

      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'resolve';
      RETURN;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'resolve';
      RAISE;
    END
    $$;

CREATE FUNCTION resolve_organization_workspace_removal_subject(p_account_id uuid, p_actor_subject_id text, p_target_organization_membership_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  actor organization_memberships%ROWTYPE;
  target organization_memberships%ROWTYPE;
BEGIN
  IF p_account_id IS NULL OR p_target_organization_membership_id IS NULL
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization workspace removal authority required'
      USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('organization-membership:' || p_account_id::text, 0)
  );
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO target FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.id = p_target_organization_membership_id;
  IF NOT FOUND OR target.subject_id NOT LIKE 'user:%' THEN
    RAISE EXCEPTION 'organization member not found' USING ERRCODE = 'P0002';
  END IF;
  RETURN target.subject_id;
END
$$;

CREATE FUNCTION resolve_secret_reference_candidates(p_principal jsonb, p_refs jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  reach_ids uuid[];
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  IF pg_catalog.jsonb_typeof(p_refs) IS DISTINCT FROM 'array' OR pg_catalog.jsonb_array_length(p_refs) > 500 THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'p_refs must be an array of at most 500 references');
  END IF;
  SELECT coalesce(pg_catalog.array_agg(reach.vault_id), '{}') INTO reach_ids
  FROM opengeni_private.vault_reach(context) reach;
  RETURN NEXT pg_catalog.jsonb_build_object(
    'meta', true,
    'kind', context ->> 'kind',
    'subjectId', context ->> 'subjectId',
    'humanExpected', (context ->> 'humanExpected')::boolean,
    'humanValid', (context ->> 'humanValid')::boolean,
    'hasSecretsUse', (context ->> 'hasSecretsUse')::boolean,
    'agentAllowed', (context ->> 'agentAllowed')::boolean,
    'includeUser', (context ->> 'includeUser')::boolean,
    'includeShared', (context ->> 'includeShared')::boolean,
    'policyVaultIds', context -> 'policyVaultIds',
    'reachableVaultCount', pg_catalog.cardinality(reach_ids)
  );
  RETURN QUERY
  WITH refs AS (
    SELECT (ref ->> 'index')::integer AS ref_index,
      ref ->> 'form' AS form,
      CASE WHEN ref ->> 'form' = 'id' THEN (ref ->> 'itemId')::uuid END AS item_id,
      CASE WHEN pg_catalog.jsonb_typeof(ref -> 'segments') = 'array' THEN ref -> 'segments'
        ELSE '[]'::jsonb END AS segments,
      nullif(ref ->> 'field', '') AS field,
      coalesce((ref ->> 'otp')::boolean, false) AS otp,
      coalesce((ref ->> 'previous')::boolean, false) AS previous
    FROM pg_catalog.jsonb_array_elements(p_refs) ref
  ), shaped AS (
    SELECT refs.*, pg_catalog.jsonb_array_length(refs.segments) AS segment_count FROM refs
  ), base AS (
    SELECT shaped.ref_index, 'item'::text AS interpretation, match.vault_id, match.item_id,
      match.matched_by, NULL::text AS field_name, false AS require_field, shaped.otp, shaped.previous
    FROM shaped
    CROSS JOIN LATERAL opengeni_private.vault_items_by_key(reach_ids, vault_name_key(shaped.segments ->> 0)) match
    WHERE shaped.form = 'path' AND shaped.segment_count = 1
    UNION ALL
    SELECT shaped.ref_index, 'item_field', match.vault_id, match.item_id, match.matched_by,
      shaped.segments ->> 1, true, shaped.otp, shaped.previous
    FROM shaped
    CROSS JOIN LATERAL opengeni_private.vault_items_by_key(reach_ids, vault_name_key(shaped.segments ->> 0)) match
    WHERE shaped.form = 'path' AND shaped.segment_count = 2
    UNION ALL
    SELECT shaped.ref_index, 'vault_item', vault_match.vault_id, match.item_id,
      CASE WHEN vault_match.matched_by = 'name' AND match.matched_by = 'name' THEN 'name' ELSE 'alias' END,
      NULL::text, false, shaped.otp, shaped.previous
    FROM shaped
    CROSS JOIN LATERAL opengeni_private.vault_vaults_by_key(reach_ids, vault_name_key(shaped.segments ->> 0)) vault_match
    CROSS JOIN LATERAL opengeni_private.vault_items_by_key(ARRAY[vault_match.vault_id], vault_name_key(shaped.segments ->> 1)) match
    WHERE shaped.form = 'path' AND shaped.segment_count = 2
    UNION ALL
    SELECT shaped.ref_index, 'vault_item_field', vault_match.vault_id, match.item_id,
      CASE WHEN vault_match.matched_by = 'name' AND match.matched_by = 'name' THEN 'name' ELSE 'alias' END,
      shaped.segments ->> 2, true, shaped.otp, shaped.previous
    FROM shaped
    CROSS JOIN LATERAL opengeni_private.vault_vaults_by_key(reach_ids, vault_name_key(shaped.segments ->> 0)) vault_match
    CROSS JOIN LATERAL opengeni_private.vault_items_by_key(ARRAY[vault_match.vault_id], vault_name_key(shaped.segments ->> 1)) match
    WHERE shaped.form = 'path' AND shaped.segment_count = 3
    UNION ALL
    SELECT shaped.ref_index, 'id', item.vault_id, item.id, 'id', shaped.field, shaped.field IS NOT NULL,
      shaped.otp, shaped.previous
    FROM shaped
    JOIN vault_items item ON item.id = shaped.item_id AND item.vault_id = ANY (reach_ids)
    WHERE shaped.form = 'id'
  )
  SELECT pg_catalog.jsonb_build_object(
    'refIndex', base.ref_index,
    'interpretation', base.interpretation,
    'tier', CASE vault.owner_kind WHEN 'task' THEN 0 WHEN 'user' THEN 1 WHEN 'workspace' THEN 2 ELSE 3 END,
    'matchedBy', base.matched_by,
    'vaultId', vault.id,
    'vaultName', vault.name,
    'vaultOwnerKind', vault.owner_kind,
    'source', vault.source,
    'providerConnectionId', vault.provider_connection_id,
    'providerVaultRef', vault.provider_vault_ref,
    'providerCacheEpoch', vault.provider_cache_epoch::text,
    'itemId', item.id,
    'itemName', item.name,
    'itemType', item.type,
    'archived', item.archived_at IS NOT NULL,
    'providerItemRef', item.provider_item_ref,
    'fieldId', field.id,
    'fieldName', field.name,
    'fieldKind', field.kind,
    'fileName', field.file_name,
    'providerFieldRef', field.provider_field_ref,
    'currentVersion', field.current_version,
    'version', version.version,
    'valueEncrypted', version.value_encrypted,
    'missing', CASE
      WHEN field.id IS NULL THEN CASE
        WHEN base.field_name IS NOT NULL THEN 'field'
        WHEN base.otp THEN 'totp_field'
        ELSE 'primary_field' END
      WHEN field.current_version IS NOT NULL AND version.version IS NULL THEN
        CASE WHEN base.previous THEN 'previous_version' ELSE 'value' END
    END
  )
  FROM base
  JOIN vault_items item ON item.id = base.item_id
  JOIN vaults vault ON vault.id = base.vault_id
  LEFT JOIN LATERAL (
    SELECT candidate_field.* FROM vault_item_fields candidate_field
    WHERE candidate_field.item_id = item.id AND (
      (base.field_name IS NOT NULL AND candidate_field.name_key = vault_name_key(base.field_name))
      OR (base.field_name IS NULL AND base.otp AND candidate_field.kind = 'totp')
      OR (base.field_name IS NULL AND NOT base.otp AND candidate_field.id = item.primary_field_id)
    )
    ORDER BY candidate_field.position, candidate_field.name_key
    LIMIT 1
  ) field ON true
  LEFT JOIN LATERAL (
    SELECT candidate_version.version, candidate_version.value_encrypted
    FROM vault_field_versions candidate_version
    WHERE candidate_version.field_id = field.id
      AND CASE WHEN base.previous THEN candidate_version.version < field.current_version
        ELSE candidate_version.version = field.current_version END
    ORDER BY candidate_version.version DESC
    LIMIT 1
  ) version ON true
  WHERE NOT base.require_field OR field.id IS NOT NULL
  ORDER BY base.ref_index, base.interpretation, vault.id, item.id;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION resolve_session_attempt_personal_document_reads(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_attempt_id uuid) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      admission_row session_attempt_personal_document_admissions%ROWTYPE;
      invalid_count integer;
      actual_count integer;
      caller_subject text := coalesce(
        nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''),
        nullif(pg_catalog.current_setting('opengeni.subject_id', true), '')
      );
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.account_id', true), ''
        )::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.workspace_id', true), ''
        )::uuid
      THEN
        RAISE EXCEPTION 'personal document resolve scope mismatch' USING ERRCODE = '42501';
      END IF;

      INSERT INTO opengeni_private.personal_document_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'resolve')
      ON CONFLICT DO NOTHING;

      SELECT admission.* INTO admission_row
      FROM session_attempt_personal_document_admissions admission
      WHERE admission.attempt_id = p_attempt_id
        AND admission.account_id = p_account_id
        AND admission.workspace_id = p_workspace_id
        AND admission.session_id = p_session_id;
      IF NOT FOUND THEN
        DELETE FROM opengeni_private.personal_document_authority_capabilities
        WHERE backend_pid = pg_catalog.pg_backend_pid()
          AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability_kind = 'resolve';
        RETURN;
      END IF;

      IF caller_subject IS DISTINCT FROM admission_row.initiating_human_subject_id THEN
        RAISE EXCEPTION 'personal document resolve initiating human mismatch'
          USING ERRCODE = '42501';
      END IF;

      SELECT count(*)::integer INTO invalid_count
      FROM session_attempt_personal_document_snapshots snapshot
      WHERE snapshot.attempt_id = p_attempt_id
        AND NOT (
          EXISTS (
            SELECT 1
            FROM session_turn_attempts attempt
            JOIN sessions session_value
              ON session_value.id = attempt.session_id
             AND session_value.account_id = attempt.account_id
             AND session_value.workspace_id = attempt.workspace_id
            JOIN session_turns turn_value
              ON turn_value.id = attempt.turn_id
             AND turn_value.account_id = attempt.account_id
             AND turn_value.workspace_id = attempt.workspace_id
             AND turn_value.session_id = attempt.session_id
            WHERE attempt.id = snapshot.attempt_id
              AND attempt.account_id = snapshot.account_id
              AND attempt.workspace_id = snapshot.workspace_id
              AND attempt.session_id = snapshot.session_id
              AND attempt.turn_id = snapshot.turn_id
              AND attempt.execution_generation = snapshot.execution_generation
              AND attempt.state IN ('claimed', 'running')
              AND attempt.closed_at IS NULL
              AND attempt.quiesced_at IS NULL
              AND session_value.active_turn_id = snapshot.turn_id
              AND turn_value.active_attempt_id = snapshot.attempt_id
              AND turn_value.execution_generation = snapshot.execution_generation
              AND turn_value.status = 'running'
              AND (snapshot.session_authority_epoch BETWEEN session_value.execution_authority_epoch AND session_value.authority_epoch)
          )
          AND NOT EXISTS (
            SELECT 1 FROM session_attempt_interruptions interruption
            WHERE interruption.account_id = snapshot.account_id
              AND interruption.workspace_id = snapshot.workspace_id
              AND interruption.session_id = snapshot.session_id
              AND interruption.attempt_id = snapshot.attempt_id
              AND interruption.state IN ('pending', 'delivered', 'acknowledged')
          )
          AND EXISTS (
            SELECT 1 FROM organization_memberships membership
            WHERE membership.id = snapshot.owner_organization_membership_id
              AND membership.account_id = snapshot.account_id
              AND membership.subject_id = admission_row.initiating_human_subject_id
              AND membership.status = 'active'
              AND membership.revoked_at IS NULL
              AND membership.authorization_revision
                = snapshot.membership_authorization_revision
              AND (
                membership.personal_workspace_id = snapshot.workspace_id
                OR EXISTS (
                  SELECT 1 FROM workspace_memberships workspace_membership
                  WHERE workspace_membership.account_id = membership.account_id
                    AND workspace_membership.workspace_id = snapshot.workspace_id
                    AND workspace_membership.subject_id = membership.subject_id
                )
              )
          )
          AND EXISTS (
            SELECT 1
            FROM documents document_value
            JOIN organization_user_resource_authorities authority
              ON authority.id = document_value.authority_id
             AND authority.account_id = document_value.account_id
             AND authority.organization_membership_id
               = document_value.owner_organization_membership_id
            WHERE document_value.id = snapshot.document_id
              AND document_value.account_id = snapshot.account_id
              AND document_value.authority_kind = 'personal'
              AND document_value.authority_workspace_id IS NULL
              AND document_value.authority_subject_id
                = admission_row.initiating_human_subject_id
              AND document_value.owner_organization_membership_id
                = snapshot.owner_organization_membership_id
              AND document_value.authority_id = snapshot.authority_id
              AND document_value.status = 'ready'
              AND document_value.agent_access = true
              AND authority.resource_kind = 'document'
              AND authority.resource_id = document_value.id
              AND authority.generation = snapshot.authority_generation
              AND authority.status = 'active'
              AND authority.revoked_at IS NULL
          )
          AND EXISTS (
            SELECT 1 FROM organization_user_resource_grants grant_value
            WHERE grant_value.id = snapshot.grant_id
              AND grant_value.account_id = snapshot.account_id
              AND grant_value.authority_id = snapshot.authority_id
              AND grant_value.owner_organization_membership_id
                = snapshot.owner_organization_membership_id
              AND grant_value.workspace_id = snapshot.target_workspace_id
              AND grant_value.action = 'document.read'
              AND grant_value.mode = snapshot.grant_mode
              AND grant_value.context = snapshot.grant_context
              AND grant_value.generation = snapshot.grant_generation
              AND grant_value.session_id IS NOT DISTINCT FROM snapshot.grant_session_id
              AND grant_value.authority_epoch
                IS NOT DISTINCT FROM snapshot.grant_authority_epoch
              AND (grant_value.expires_at IS NULL OR grant_value.expires_at > clock_timestamp())
              AND (
                (
                  snapshot.grant_mode = 'once'
                  AND grant_value.status = 'consumed'
                  AND EXISTS (
                    SELECT 1 FROM personal_document_once_consumption_receipts receipt
                    WHERE receipt.grant_id = snapshot.grant_id
                      AND receipt.account_id = snapshot.account_id
                      AND receipt.attempt_id = snapshot.attempt_id
                      AND receipt.document_id = snapshot.document_id
                      AND receipt.authority_id = snapshot.authority_id
                      AND receipt.authority_generation = snapshot.authority_generation
                      AND receipt.grant_generation = snapshot.grant_generation
                  )
                ) OR (
                  snapshot.grant_mode IN ('session', 'always')
                  AND grant_value.status = 'active'
                )
              )
          )
        );
      IF invalid_count <> 0 THEN
        RAISE EXCEPTION 'personal document authority snapshot is no longer live'
          USING ERRCODE = '42501';
      END IF;

      SELECT count(*)::integer INTO actual_count
      FROM session_attempt_personal_document_snapshots snapshot
      WHERE snapshot.attempt_id = p_attempt_id;
      IF actual_count <> admission_row.document_count THEN
        RAISE EXCEPTION 'personal document snapshot collection is incomplete'
          USING ERRCODE = '42501';
      END IF;

      RETURN QUERY
      SELECT snapshot.document_id
      FROM session_attempt_personal_document_snapshots snapshot
      WHERE snapshot.attempt_id = p_attempt_id
      ORDER BY snapshot.document_id;

      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'resolve';
      RETURN;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'resolve';
      RAISE;
    END
    $$;

CREATE FUNCTION resolve_session_attempt_personal_resources(p_account_id uuid, p_workspace_id uuid, p_attempt_id uuid) RETURNS TABLE(resource_kind text, resource_id uuid, resource_version_id uuid, selection_sources text[], action text, authority_id uuid, authority_generation bigint, grant_id uuid, grant_generation bigint, grant_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  attempt_protocol integer;
  admission_row session_attempt_personal_resource_admissions%ROWTYPE;
  invalid_count integer;
  caller_subject text := coalesce(
    nullif(current_setting('opengeni.initiating_human_subject_id', true), ''),
    nullif(current_setting('opengeni.subject_id', true), '')
  );
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'personal-resource resolve scope mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT attempt.personal_resource_protocol_version INTO STRICT attempt_protocol
  FROM session_turn_attempts attempt
  WHERE attempt.id = p_attempt_id
    AND attempt.account_id = p_account_id
    AND attempt.workspace_id = p_workspace_id;
  IF attempt_protocol = 0 THEN
    RETURN QUERY SELECT * FROM resolve_session_attempt_personal_resources_legacy_0305(
      p_account_id, p_workspace_id, p_attempt_id
    );
    RETURN;
  ELSIF attempt_protocol <> 1 THEN
    RAISE EXCEPTION 'unsupported personal-resource protocol version'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO opengeni_private.personal_resource_delegation_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'resolve')
  ON CONFLICT DO NOTHING;
  SELECT admission.* INTO STRICT admission_row
  FROM session_attempt_personal_resource_admissions admission
  WHERE admission.attempt_id = p_attempt_id
    AND admission.account_id = p_account_id
    AND admission.workspace_id = p_workspace_id;
  IF caller_subject IS DISTINCT FROM admission_row.initiating_human_subject_id THEN
    RAISE EXCEPTION 'personal-resource resolve initiating human mismatch'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM session_turn_attempts attempt
  JOIN sessions session_value
    ON session_value.id = attempt.session_id
   AND session_value.account_id = attempt.account_id
   AND session_value.workspace_id = attempt.workspace_id
  JOIN session_turns turn_value
    ON turn_value.id = attempt.turn_id
   AND turn_value.account_id = attempt.account_id
   AND turn_value.workspace_id = attempt.workspace_id
   AND turn_value.session_id = attempt.session_id
  WHERE attempt.id = admission_row.attempt_id
    AND session_value.active_turn_id = admission_row.turn_id
    AND turn_value.active_attempt_id = admission_row.attempt_id
    AND turn_value.execution_generation = admission_row.execution_generation
    AND turn_value.personal_resource_protocol_version = 1
    AND turn_value.status = 'running'
    AND attempt.execution_generation = admission_row.execution_generation
    AND attempt.personal_resource_protocol_version = 1
    AND attempt.state IN ('claimed', 'running')
    AND attempt.closed_at IS NULL AND attempt.quiesced_at IS NULL
    AND (attempt.authority_epoch BETWEEN session_value.execution_authority_epoch AND session_value.authority_epoch)
    AND (admission_row.session_authority_epoch BETWEEN session_value.execution_authority_epoch AND session_value.authority_epoch)
    AND NOT EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.account_id = attempt.account_id
        AND interruption.workspace_id = attempt.workspace_id
        AND interruption.session_id = attempt.session_id
        AND interruption.attempt_id = attempt.id
        AND interruption.state IN ('pending', 'delivered', 'acknowledged')
    )
  FOR SHARE OF session_value, turn_value
  FOR UPDATE OF attempt;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'personal-resource resolve requires the exact current uninterrupted attempt'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer INTO invalid_count
  FROM session_attempt_personal_resource_snapshots snapshot
  JOIN turn_personal_resource_snapshots accepted
    ON accepted.turn_id = snapshot.turn_id
   AND accepted.resource_kind = snapshot.resource_kind
   AND accepted.resource_id = snapshot.resource_id
  WHERE snapshot.attempt_id = admission_row.attempt_id
    AND NOT (
      snapshot.account_id = accepted.account_id
      AND snapshot.workspace_id = accepted.workspace_id
      AND snapshot.session_id = accepted.session_id
      AND snapshot.resource_version_id IS NOT DISTINCT FROM accepted.resource_version_id
      AND snapshot.selection_sources = accepted.selection_sources
      AND snapshot.action = accepted.action
      AND snapshot.origin_workspace_id = accepted.origin_workspace_id
      AND snapshot.owner_organization_membership_id
        = accepted.owner_organization_membership_id
      AND snapshot.membership_authorization_revision
        = accepted.membership_authorization_revision
      AND snapshot.authority_id = accepted.authority_id
      AND snapshot.authority_generation = accepted.authority_generation
      AND snapshot.grant_id = accepted.grant_id
      AND snapshot.grant_generation = accepted.grant_generation
      AND snapshot.grant_mode = accepted.grant_mode
      AND snapshot.grant_context = accepted.grant_context
      AND snapshot.grant_session_id IS NOT DISTINCT FROM accepted.grant_session_id
      AND snapshot.grant_authority_epoch IS NOT DISTINCT FROM accepted.grant_authority_epoch
      AND accepted.snapshot_digest = digest_turn_personal_resource_snapshot(accepted)
      AND EXISTS (
        SELECT 1 FROM organization_memberships membership
        WHERE membership.id = accepted.owner_organization_membership_id
          AND membership.account_id = accepted.account_id
          AND membership.subject_id = admission_row.initiating_human_subject_id
          AND membership.status = 'active' AND membership.revoked_at IS NULL
          AND membership.authorization_revision = accepted.membership_authorization_revision
          AND (membership.personal_workspace_id = accepted.workspace_id OR EXISTS (
            SELECT 1 FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = membership.account_id
              AND workspace_membership.workspace_id = accepted.workspace_id
              AND workspace_membership.subject_id = membership.subject_id
          ))
      )
      AND EXISTS (
        SELECT 1 FROM organization_user_resource_authorities authority
        WHERE authority.id = accepted.authority_id
          AND authority.account_id = accepted.account_id
          AND authority.organization_membership_id = accepted.owner_organization_membership_id
          AND authority.resource_kind = accepted.resource_kind
          AND authority.resource_id = accepted.resource_id
          AND authority.generation = accepted.authority_generation
          AND authority.status = 'active' AND authority.revoked_at IS NULL
      )
      AND EXISTS (
        SELECT 1 FROM organization_user_resource_grants grant_value
        WHERE grant_value.id = accepted.grant_id
          AND grant_value.account_id = accepted.account_id
          AND grant_value.authority_id = accepted.authority_id
          AND grant_value.owner_organization_membership_id
            = accepted.owner_organization_membership_id
          AND grant_value.workspace_id = accepted.workspace_id
          AND grant_value.action = accepted.action
          AND grant_value.mode = accepted.grant_mode
          AND grant_value.context = accepted.grant_context
          AND grant_value.generation = accepted.grant_generation
          AND grant_value.session_id IS NOT DISTINCT FROM accepted.grant_session_id
          AND grant_value.authority_epoch IS NOT DISTINCT FROM accepted.grant_authority_epoch
          AND (grant_value.expires_at IS NULL OR grant_value.expires_at > clock_timestamp())
          AND ((accepted.grant_mode = 'once' AND grant_value.status = 'consumed'
            AND EXISTS (
              SELECT 1 FROM turn_personal_resource_once_receipts once_receipt
              WHERE once_receipt.grant_id = accepted.grant_id
                AND once_receipt.turn_id = accepted.turn_id
                AND once_receipt.account_id = accepted.account_id
                AND once_receipt.authority_id = accepted.authority_id
                AND once_receipt.authority_generation = accepted.authority_generation
                AND once_receipt.grant_generation = accepted.grant_generation
            )) OR (accepted.grant_mode IN ('session', 'always')
              AND grant_value.status = 'active'))
      )
    );
  IF invalid_count <> 0 THEN
    RAISE EXCEPTION 'personal-resource authority snapshot is no longer live'
      USING ERRCODE = '42501';
  END IF;
  SELECT count(*)::integer INTO invalid_count
  FROM session_attempt_personal_resource_snapshots snapshot
  WHERE snapshot.attempt_id = admission_row.attempt_id;
  IF invalid_count <> admission_row.resource_count THEN
    RAISE EXCEPTION 'personal-resource snapshot collection is incomplete'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT snapshot.resource_kind, snapshot.resource_id, snapshot.resource_version_id,
    snapshot.selection_sources, snapshot.action, snapshot.authority_id,
    snapshot.authority_generation, snapshot.grant_id,
    snapshot.grant_generation, snapshot.grant_mode
  FROM session_attempt_personal_resource_snapshots snapshot
  WHERE snapshot.attempt_id = admission_row.attempt_id
  ORDER BY snapshot.resource_kind, snapshot.resource_id;

  DELETE FROM opengeni_private.personal_resource_delegation_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'resolve';
  RETURN;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.personal_resource_delegation_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'resolve';
  RAISE;
END
$$;

CREATE FUNCTION resolve_session_attempt_personal_resources_legacy_0305(p_account_id uuid, p_workspace_id uuid, p_attempt_id uuid) RETURNS TABLE(resource_kind text, resource_id uuid, resource_version_id uuid, selection_sources text[], action text, authority_id uuid, authority_generation bigint, grant_id uuid, grant_generation bigint, grant_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      admission_row session_attempt_personal_resource_admissions%ROWTYPE;
      invalid_count integer;
      caller_subject text := coalesce(
        nullif(pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''),
        nullif(pg_catalog.current_setting('opengeni.subject_id', true), '')
      );
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.account_id', true), ''
        )::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.workspace_id', true), ''
        )::uuid
      THEN
        RAISE EXCEPTION 'personal-resource resolve scope mismatch'
          USING ERRCODE = '42501';
      END IF;

      INSERT INTO opengeni_private.personal_resource_delegation_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'resolve')
      ON CONFLICT DO NOTHING;

      SELECT admission.* INTO STRICT admission_row
      FROM session_attempt_personal_resource_admissions admission
      WHERE admission.attempt_id = p_attempt_id
        AND admission.account_id = p_account_id
        AND admission.workspace_id = p_workspace_id;

      IF caller_subject IS DISTINCT FROM admission_row.initiating_human_subject_id THEN
        RAISE EXCEPTION 'personal-resource resolve initiating human mismatch'
          USING ERRCODE = '42501';
      END IF;

      PERFORM 1
      FROM sessions session_value
      JOIN session_turns turn_value
        ON turn_value.account_id = session_value.account_id
       AND turn_value.workspace_id = session_value.workspace_id
       AND turn_value.session_id = session_value.id
      JOIN session_turn_attempts attempt
        ON attempt.account_id = turn_value.account_id
       AND attempt.workspace_id = turn_value.workspace_id
       AND attempt.session_id = turn_value.session_id
       AND attempt.turn_id = turn_value.id
      WHERE session_value.id = admission_row.session_id
        AND session_value.account_id = admission_row.account_id
        AND session_value.workspace_id = admission_row.workspace_id
        AND session_value.active_turn_id = admission_row.turn_id
        AND turn_value.id = admission_row.turn_id
        AND turn_value.active_attempt_id = admission_row.attempt_id
        AND turn_value.execution_generation = admission_row.execution_generation
        AND turn_value.status = 'running'
        AND attempt.id = admission_row.attempt_id
        AND attempt.execution_generation = admission_row.execution_generation
        AND attempt.state IN ('claimed', 'running')
        AND attempt.closed_at IS NULL
        AND attempt.quiesced_at IS NULL
      FOR SHARE OF session_value, turn_value
      FOR UPDATE OF attempt;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'personal-resource resolve requires the exact current uninterrupted attempt'
          USING ERRCODE = '42501';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM session_attempt_interruptions interruption
        WHERE interruption.account_id = admission_row.account_id
          AND interruption.workspace_id = admission_row.workspace_id
          AND interruption.session_id = admission_row.session_id
          AND interruption.attempt_id = admission_row.attempt_id
          AND interruption.state IN ('pending', 'delivered', 'acknowledged')
      )
      THEN
        RAISE EXCEPTION 'personal-resource resolve requires the exact current uninterrupted attempt'
          USING ERRCODE = '42501';
      END IF;

      SELECT count(*)::integer INTO invalid_count
      FROM session_attempt_personal_resource_snapshots snapshot
      WHERE snapshot.attempt_id = admission_row.attempt_id
        AND NOT (
          EXISTS (
            SELECT 1
            FROM session_turn_attempts attempt
            JOIN sessions session_value
              ON session_value.id = attempt.session_id
             AND session_value.account_id = attempt.account_id
             AND session_value.workspace_id = attempt.workspace_id
            JOIN session_turns turn_value
              ON turn_value.id = attempt.turn_id
             AND turn_value.account_id = attempt.account_id
             AND turn_value.workspace_id = attempt.workspace_id
             AND turn_value.session_id = attempt.session_id
            WHERE attempt.id = snapshot.attempt_id
              AND attempt.account_id = snapshot.account_id
              AND attempt.workspace_id = snapshot.workspace_id
              AND attempt.session_id = snapshot.session_id
              AND attempt.turn_id = snapshot.turn_id
              AND attempt.execution_generation = snapshot.execution_generation
              AND attempt.state IN ('claimed', 'running')
              AND attempt.quiesced_at IS NULL
              AND (attempt.authority_epoch BETWEEN session_value.execution_authority_epoch AND session_value.authority_epoch)
              AND (snapshot.session_authority_epoch BETWEEN session_value.execution_authority_epoch AND session_value.authority_epoch)
              AND coalesce(
                nullif(btrim(turn_value.initiating_human_subject_id), ''),
                CASE WHEN turn_value.initiator_kind = 'subject'
                  THEN nullif(btrim(turn_value.initiator_subject_id), '') END
              ) = admission_row.initiating_human_subject_id
          )
          AND EXISTS (
            SELECT 1
            FROM organization_memberships membership
            WHERE membership.id = snapshot.owner_organization_membership_id
              AND membership.account_id = snapshot.account_id
              AND membership.subject_id = admission_row.initiating_human_subject_id
              AND membership.status = 'active'
              AND membership.revoked_at IS NULL
              AND membership.authorization_revision
                = snapshot.membership_authorization_revision
              AND (
                membership.personal_workspace_id = snapshot.workspace_id
                OR EXISTS (
                  SELECT 1
                  FROM workspace_memberships workspace_membership
                  WHERE workspace_membership.account_id = membership.account_id
                    AND workspace_membership.workspace_id = snapshot.workspace_id
                    AND workspace_membership.subject_id = membership.subject_id
                )
              )
          )
          AND EXISTS (
            SELECT 1
            FROM organization_user_resource_authorities authority
            WHERE authority.id = snapshot.authority_id
              AND authority.account_id = snapshot.account_id
              AND authority.organization_membership_id
                = snapshot.owner_organization_membership_id
              AND authority.resource_kind = snapshot.resource_kind
              AND authority.resource_id = snapshot.resource_id
              AND authority.generation = snapshot.authority_generation
              AND authority.status = 'active'
              AND authority.revoked_at IS NULL
          )
          AND (
            (
              snapshot.resource_kind = 'variable_set'
              AND EXISTS (
                SELECT 1 FROM workspace_variable_sets variable_set
                WHERE variable_set.id = snapshot.resource_id
                  AND variable_set.account_id = snapshot.account_id
                  AND variable_set.authority_scope = 'user'
                  AND variable_set.authority_id = snapshot.authority_id
                  AND variable_set.owner_organization_membership_id
                    = snapshot.owner_organization_membership_id
              )
            ) OR (
              snapshot.resource_kind = 'rig'
              AND EXISTS (
                SELECT 1 FROM rigs rig
                JOIN rig_versions rig_version
                  ON rig_version.id = snapshot.resource_version_id
                 AND rig_version.rig_id = rig.id
                 AND rig_version.account_id = rig.account_id
                WHERE rig.id = snapshot.resource_id
                  AND rig.account_id = snapshot.account_id
                  AND rig.authority_scope = 'user'
                  AND rig.authority_id = snapshot.authority_id
                  AND rig.owner_organization_membership_id
                    = snapshot.owner_organization_membership_id
              )
            )
          )
          AND EXISTS (
            SELECT 1
            FROM organization_user_resource_grants grant_value
            WHERE grant_value.id = snapshot.grant_id
              AND grant_value.account_id = snapshot.account_id
              AND grant_value.authority_id = snapshot.authority_id
              AND grant_value.owner_organization_membership_id
                = snapshot.owner_organization_membership_id
              AND grant_value.workspace_id = snapshot.target_workspace_id
              AND grant_value.action = snapshot.action
              AND grant_value.mode = snapshot.grant_mode
              AND grant_value.context = snapshot.grant_context
              AND grant_value.generation = snapshot.grant_generation
              AND grant_value.session_id IS NOT DISTINCT FROM snapshot.grant_session_id
              AND grant_value.authority_epoch
                IS NOT DISTINCT FROM snapshot.grant_authority_epoch
              AND (grant_value.expires_at IS NULL OR grant_value.expires_at > clock_timestamp())
              AND (
                (
                  snapshot.grant_mode = 'once'
                  AND grant_value.status = 'consumed'
                  AND EXISTS (
                    SELECT 1 FROM personal_resource_once_consumption_receipts receipt
                    WHERE receipt.grant_id = snapshot.grant_id
                      AND receipt.account_id = snapshot.account_id
                      AND receipt.attempt_id = snapshot.attempt_id
                      AND receipt.authority_id = snapshot.authority_id
                      AND receipt.authority_generation = snapshot.authority_generation
                      AND receipt.grant_generation = snapshot.grant_generation
                  )
                ) OR (
                  snapshot.grant_mode IN ('session', 'always')
                  AND grant_value.status = 'active'
                )
              )
          )
        );

      IF invalid_count <> 0 THEN
        RAISE EXCEPTION 'personal-resource authority snapshot is no longer live'
          USING ERRCODE = '42501';
      END IF;

      SELECT count(*)::integer INTO invalid_count
      FROM session_attempt_personal_resource_snapshots snapshot
      WHERE snapshot.attempt_id = admission_row.attempt_id;
      IF invalid_count <> admission_row.resource_count THEN
        RAISE EXCEPTION 'personal-resource snapshot collection is incomplete'
          USING ERRCODE = '42501';
      END IF;

      RETURN QUERY
      SELECT snapshot.resource_kind, snapshot.resource_id,
        snapshot.resource_version_id, snapshot.selection_sources, snapshot.action,
        snapshot.authority_id, snapshot.authority_generation, snapshot.grant_id,
        snapshot.grant_generation, snapshot.grant_mode
      FROM session_attempt_personal_resource_snapshots snapshot
      WHERE snapshot.attempt_id = admission_row.attempt_id
      ORDER BY snapshot.resource_kind, snapshot.resource_id;

      DELETE FROM opengeni_private.personal_resource_delegation_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'resolve';
      RETURN;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.personal_resource_delegation_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'resolve';
      RAISE;
    END;
    $$;

COMMENT ON FUNCTION resolve_session_attempt_personal_resources_legacy_0305(p_account_id uuid, p_workspace_id uuid, p_attempt_id uuid) IS 'Fail-closed exact-attempt authority revalidation and identifier-only personal-resource collection read.';

CREATE FUNCTION resolve_session_work_claim_attempt_authority(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS TABLE(root_session_id uuid, actor_subject_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
DECLARE
  session_row sessions%ROWTYPE;
  turn_row session_turns%ROWTYPE;
  previous_subject_id text := current_setting('opengeni.subject_id', true);
  previous_initiating_human_subject_id text := current_setting(
    'opengeni.initiating_human_subject_id', true
  );
  visibility_context_set boolean := false;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_turn_id IS NULL OR p_attempt_id IS NULL
    OR p_execution_generation IS NULL OR p_execution_generation < 1
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN
    RAISE EXCEPTION 'work claims require exact tenant and attempt authority'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work claim workspace is unavailable' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO session_row FROM sessions session
  WHERE session.account_id = p_account_id
    AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id
  FOR NO KEY UPDATE;
  IF NOT FOUND OR session_row.status IN ('failed','cancelled') THEN
    RAISE EXCEPTION 'work claim session is unavailable' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM session_goals goal
    WHERE goal.account_id = p_account_id
      AND goal.workspace_id = p_workspace_id
      AND goal.session_id = p_session_id
      AND goal.status = 'completed'
  ) THEN
    RAISE EXCEPTION 'completed session goals cannot create or mutate work claims'
      USING ERRCODE = '42501';
  END IF;

  SELECT turn.* INTO turn_row FROM session_turns turn
  WHERE turn.account_id = p_account_id
    AND turn.workspace_id = p_workspace_id
    AND turn.session_id = p_session_id
    AND turn.id = p_turn_id
    AND turn.active_attempt_id = p_attempt_id
    AND session_row.active_turn_id = p_turn_id
    AND turn.execution_generation = p_execution_generation
    AND turn.status IN ('running','requires_action','recovering','waiting_capacity')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work claims require the exact current turn' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM session_turn_attempts attempt
  WHERE attempt.account_id = p_account_id
    AND attempt.workspace_id = p_workspace_id
    AND attempt.session_id = p_session_id
    AND attempt.turn_id = p_turn_id
    AND attempt.id = p_attempt_id
    AND attempt.execution_generation = p_execution_generation
    AND attempt.state IN ('claimed','running')
    AND NOT EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = attempt.workspace_id
        AND interruption.attempt_id = attempt.id
        AND interruption.state IN ('pending','delivered','acknowledged')
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'work claims require the exact current attempt' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config(
    'opengeni.subject_id',
    CASE WHEN turn_row.initiator_kind = 'subject' THEN turn_row.initiator_subject_id ELSE '' END,
    true
  );
  PERFORM set_config(
    'opengeni.initiating_human_subject_id',
    coalesce(turn_row.initiating_human_subject_id, ''),
    true
  );
  visibility_context_set := true;
  IF NOT (
    session_row.visibility = 'workspace_shared'
    OR session_private_actor_visible(
      session_row.account_id,
      session_row.workspace_id,
      session_row.owner_organization_membership_id,
      session_row.owner_subject_id
    )
  ) THEN
    RAISE EXCEPTION 'work claim session is not visible to this actor'
      USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('opengeni.subject_id', coalesce(previous_subject_id, ''), true);
  PERFORM set_config(
    'opengeni.initiating_human_subject_id',
    coalesce(previous_initiating_human_subject_id, ''),
    true
  );
  visibility_context_set := false;

  root_session_id := session_row.root_session_id;
  actor_subject_id := turn_row.initiator_subject_id;
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  IF visibility_context_set THEN
    PERFORM set_config('opengeni.subject_id', coalesce(previous_subject_id, ''), true);
    PERFORM set_config(
      'opengeni.initiating_human_subject_id',
      coalesce(previous_initiating_human_subject_id, ''),
      true
    );
  END IF;
  RAISE;
END;
$$;

CREATE FUNCTION resolve_task_note_attempt_authority(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS TABLE(root_session_id uuid, actor_kind text, actor_subject_id text, initiating_human_subject_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  resolved_root_id uuid;
  turn_row session_turns%ROWTYPE;
  previous_subject_id text := pg_catalog.current_setting('opengeni.subject_id', true);
  previous_initiating_human_subject_id text := pg_catalog.current_setting(
    'opengeni.initiating_human_subject_id', true
  );
  visibility_context_set boolean := false;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_turn_id IS NULL OR p_attempt_id IS NULL
    OR p_execution_generation IS NULL OR p_execution_generation < 1
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN
    RAISE EXCEPTION 'task notes require exact tenant and attempt authority'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'task note workspace is unavailable' USING ERRCODE = '42501';
  END IF;

  SELECT session.root_session_id INTO resolved_root_id
  FROM sessions session
  WHERE session.account_id = p_account_id
    AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id;
  IF resolved_root_id IS NULL THEN
    RAISE EXCEPTION 'task note session is unavailable' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM sessions session
  WHERE session.account_id = p_account_id
    AND session.workspace_id = p_workspace_id
    AND session.id IN (p_session_id, resolved_root_id)
  ORDER BY session.id
  -- Root authority serializes sibling mutations, including the active-record
  -- cap check. UUID order preserves the canonical multi-session lock order.
  -- Session keys are unchanged: permit concurrent root-session FK checks.
  FOR NO KEY UPDATE;
  IF (SELECT count(*) FROM sessions session
      WHERE session.account_id = p_account_id
        AND session.workspace_id = p_workspace_id
        AND session.id IN (p_session_id, resolved_root_id))
      <> (CASE WHEN p_session_id = resolved_root_id THEN 1 ELSE 2 END)
  THEN
    RAISE EXCEPTION 'task note root session is unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT turn.* INTO turn_row
  FROM session_turns turn
  JOIN sessions session ON session.account_id = turn.account_id
    AND session.workspace_id = turn.workspace_id
    AND session.id = turn.session_id
  WHERE turn.account_id = p_account_id
    AND turn.workspace_id = p_workspace_id
    AND turn.session_id = p_session_id
    AND turn.id = p_turn_id
    AND turn.active_attempt_id = p_attempt_id
    AND session.active_turn_id = p_turn_id
    AND turn.execution_generation = p_execution_generation
    AND turn.status IN ('running','requires_action','recovering','waiting_capacity')
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'task notes require the exact current turn' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM session_turn_attempts attempt
  WHERE attempt.account_id = p_account_id
    AND attempt.workspace_id = p_workspace_id
    AND attempt.session_id = p_session_id
    AND attempt.turn_id = p_turn_id
    AND attempt.id = p_attempt_id
    AND attempt.execution_generation = p_execution_generation
    AND attempt.state IN ('claimed','running')
    AND NOT EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = attempt.workspace_id
        AND interruption.attempt_id = attempt.id
        AND interruption.state IN ('pending','delivered','acknowledged')
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'task notes require the exact current attempt' USING ERRCODE = '42501';
  END IF;

  -- A worker connection is transport, not session-visibility authority. Recheck
  -- the private root and addressed session under the immutable human authority
  -- frozen on the accepted logical turn, then restore the caller's GUCs. Pure
  -- service work deliberately supplies no manufactured human identity.
  PERFORM pg_catalog.set_config(
    'opengeni.subject_id',
    CASE WHEN turn_row.initiator_kind = 'subject'
      THEN turn_row.initiator_subject_id ELSE '' END,
    true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id',
    COALESCE(turn_row.initiating_human_subject_id, ''),
    true
  );
  visibility_context_set := true;
  IF (SELECT count(*) FROM sessions session
      WHERE session.account_id = p_account_id
        AND session.workspace_id = p_workspace_id
        AND session.id IN (p_session_id, resolved_root_id)
        AND (
          session.visibility = 'workspace_shared'
          OR session_private_actor_visible(
            session.account_id,
            session.workspace_id,
            session.owner_organization_membership_id,
            session.owner_subject_id
          )
        )) <> (CASE WHEN p_session_id = resolved_root_id THEN 1 ELSE 2 END)
  THEN
    RAISE EXCEPTION 'task note session tree is not visible to this actor'
      USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.subject_id', COALESCE(previous_subject_id, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id',
    COALESCE(previous_initiating_human_subject_id, ''),
    true
  );
  visibility_context_set := false;

  root_session_id := resolved_root_id;
  actor_kind := CASE turn_row.initiator_kind WHEN 'subject' THEN 'human' ELSE 'service' END;
  actor_subject_id := turn_row.initiator_subject_id;
  initiating_human_subject_id := turn_row.initiating_human_subject_id;
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  IF visibility_context_set THEN
    PERFORM pg_catalog.set_config(
      'opengeni.subject_id', COALESCE(previous_subject_id, ''), true
    );
    PERFORM pg_catalog.set_config(
      'opengeni.initiating_human_subject_id',
      COALESCE(previous_initiating_human_subject_id, ''),
      true
    );
  END IF;
  RAISE;
END;
$$;

CREATE FUNCTION resolve_task_note_knowledge_promotion_source(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_note_id uuid, p_expected_note_version integer, p_evidence_operation_id text, p_claim_operation_id text, p_actor_subject_id text) RETURNS TABLE(note_id uuid, root_session_id uuid, note_version integer, note_text text, note_text_hash text, note_created_at timestamp with time zone, initiating_human_subject_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  authority record;
  note_row task_notes%ROWTYPE;
  learning_policy_snapshot_id uuid;
  effective_learning_mode text;
  previous_subject_id text := pg_catalog.current_setting('opengeni.subject_id', true);
  previous_initiating_human_subject_id text := pg_catalog.current_setting(
    'opengeni.initiating_human_subject_id', true
  );
  write_capability_id uuid := pg_catalog.gen_random_uuid();
  previous_write_capability text := pg_catalog.current_setting(
    'opengeni.task_note_knowledge_promotion_capability', true
  );
BEGIN
  IF p_note_id IS NULL
    OR p_expected_note_version IS DISTINCT FROM 1
    OR p_evidence_operation_id IS NULL
    OR p_claim_operation_id IS NULL
    OR length(btrim(coalesce(p_actor_subject_id, ''))) NOT BETWEEN 1 AND 1024
  THEN
    RAISE EXCEPTION 'Task-note promotion requires exact active version one'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO authority
  FROM resolve_task_note_attempt_authority(
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_attempt_id, p_execution_generation
  );
  IF authority.initiating_human_subject_id IS NULL THEN
    RAISE EXCEPTION 'Task-note promotion requires an immutable initiating human'
      USING ERRCODE = '42501';
  END IF;

  SELECT snapshot.id,
    coalesce(
      (
        SELECT override.value->>'mode'
        FROM pg_catalog.jsonb_array_elements(snapshot.source_overrides) override(value)
        WHERE override.value->>'kind' = 'task-note'
          AND override.value->>'id' = p_note_id::text
        LIMIT 1
      ),
      snapshot.workspace_mode
    )
  INTO learning_policy_snapshot_id, effective_learning_mode
  FROM workspace_learning_policy_snapshots snapshot
  WHERE snapshot.account_id = p_account_id
    AND snapshot.workspace_id = p_workspace_id
    AND snapshot.session_id = p_session_id
    AND snapshot.turn_id = p_turn_id
    AND snapshot.attempt_id = p_attempt_id
    AND snapshot.execution_generation = p_execution_generation;
  IF learning_policy_snapshot_id IS NULL
    OR effective_learning_mode NOT IN ('suggest', 'automatic')
  THEN
    RAISE EXCEPTION 'Task-note promotion is disabled by the exact learning-policy snapshot'
      USING ERRCODE = '42501';
  END IF;

  PERFORM pg_catalog.set_config(
    'opengeni.subject_id', authority.initiating_human_subject_id, true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id', authority.initiating_human_subject_id, true
  );
  SELECT note.* INTO note_row
  FROM task_notes note
  WHERE note.account_id = p_account_id
    AND note.workspace_id = p_workspace_id
    AND note.root_session_id = authority.root_session_id
    AND note.id = p_note_id
    AND note.status = 'active'
    AND note.version = p_expected_note_version
    AND note.expires_at > statement_timestamp()
  FOR SHARE;

  PERFORM pg_catalog.set_config(
    'opengeni.subject_id', coalesce(previous_subject_id, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id',
    coalesce(previous_initiating_human_subject_id, ''), true
  );
  IF note_row.id IS NULL THEN
    RAISE EXCEPTION 'Task note is unavailable, archived, expired, or outside this root tree'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO task_note_knowledge_promotion_capabilities (
    backend_pid, transaction_id, capability_id,
    account_id, workspace_id, note_id, root_session_id, note_version,
    note_text_hash, evidence_operation_id, claim_operation_id,
    actor_subject_id, initiating_human_subject_id, learning_policy_snapshot_id
  ) VALUES (
    pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), write_capability_id,
    p_account_id, p_workspace_id, note_row.id, note_row.root_session_id, note_row.version,
    note_row.text_hash, p_evidence_operation_id, p_claim_operation_id,
    p_actor_subject_id, authority.initiating_human_subject_id, learning_policy_snapshot_id
  );
  PERFORM pg_catalog.set_config(
    'opengeni.task_note_knowledge_promotion_capability', write_capability_id::text, true
  );

  RETURN QUERY SELECT
    note_row.id,
    note_row.root_session_id,
    note_row.version,
    note_row.text,
    note_row.text_hash,
    note_row.created_at,
    authority.initiating_human_subject_id;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM task_note_knowledge_promotion_capabilities capability
  WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
    AND capability.transaction_id = pg_catalog.pg_current_xact_id()
    AND capability.capability_id = write_capability_id;
  PERFORM pg_catalog.set_config(
    'opengeni.task_note_knowledge_promotion_capability',
    coalesce(previous_write_capability, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.subject_id', coalesce(previous_subject_id, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id',
    coalesce(previous_initiating_human_subject_id, ''), true
  );
  RAISE;
END;
$$;

CREATE FUNCTION resolve_turn_context_attempt_authority(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS TABLE(root_session_id uuid, actor_kind text, actor_subject_id text, initiating_human_subject_id text)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  resolved_root_id uuid;
  turn_row session_turns%ROWTYPE;
  previous_subject_id text := pg_catalog.current_setting('opengeni.subject_id', true);
  previous_initiating_human_subject_id text := pg_catalog.current_setting(
    'opengeni.initiating_human_subject_id', true
  );
  visibility_context_set boolean := false;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_turn_id IS NULL OR p_attempt_id IS NULL
    OR p_execution_generation IS NULL OR p_execution_generation < 1
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN
    RAISE EXCEPTION 'turn context requires exact tenant and attempt authority'
      USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR KEY SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'turn context workspace is unavailable' USING ERRCODE = '42501';
  END IF;

  SELECT session.root_session_id INTO resolved_root_id
  FROM sessions session
  WHERE session.account_id = p_account_id
    AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id;
  IF resolved_root_id IS NULL THEN
    RAISE EXCEPTION 'turn context session is unavailable' USING ERRCODE = '42501';
  END IF;

  SELECT turn.* INTO turn_row
  FROM session_turns turn
  JOIN sessions session ON session.account_id = turn.account_id
    AND session.workspace_id = turn.workspace_id
    AND session.id = turn.session_id
  WHERE turn.account_id = p_account_id
    AND turn.workspace_id = p_workspace_id
    AND turn.session_id = p_session_id
    AND turn.id = p_turn_id
    AND turn.active_attempt_id = p_attempt_id
    AND session.active_turn_id = p_turn_id
    AND turn.execution_generation = p_execution_generation
    AND turn.status IN ('running','requires_action','recovering','waiting_capacity')
  FOR SHARE OF turn;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'turn context requires the exact current turn' USING ERRCODE = '42501';
  END IF;

  PERFORM 1 FROM session_turn_attempts attempt
  WHERE attempt.account_id = p_account_id
    AND attempt.workspace_id = p_workspace_id
    AND attempt.session_id = p_session_id
    AND attempt.turn_id = p_turn_id
    AND attempt.id = p_attempt_id
    AND attempt.execution_generation = p_execution_generation
    AND attempt.state IN ('claimed','running')
    AND NOT EXISTS (
      SELECT 1 FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = attempt.workspace_id
        AND interruption.attempt_id = attempt.id
        AND interruption.state IN ('pending','delivered','acknowledged')
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'turn context requires the exact current attempt' USING ERRCODE = '42501';
  END IF;

  -- A worker connection is transport, not session-visibility authority. Check
  -- the addressed chat under the human authority frozen on the accepted turn,
  -- then restore the caller's GUCs. Pure service work supplies no human.
  PERFORM pg_catalog.set_config(
    'opengeni.subject_id',
    CASE WHEN turn_row.initiator_kind = 'subject'
      THEN turn_row.initiator_subject_id ELSE '' END,
    true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id',
    COALESCE(turn_row.initiating_human_subject_id, ''),
    true
  );
  visibility_context_set := true;
  IF NOT EXISTS (
    SELECT 1 FROM sessions session
    WHERE session.account_id = p_account_id
      AND session.workspace_id = p_workspace_id
      AND session.id = p_session_id
      AND (
        session.visibility = 'workspace_shared'
        OR session_private_actor_visible(
          session.account_id,
          session.workspace_id,
          session.owner_organization_membership_id,
          session.owner_subject_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'turn context session is not visible to this actor'
      USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.subject_id', COALESCE(previous_subject_id, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.initiating_human_subject_id',
    COALESCE(previous_initiating_human_subject_id, ''),
    true
  );
  visibility_context_set := false;

  root_session_id := resolved_root_id;
  actor_kind := CASE turn_row.initiator_kind WHEN 'subject' THEN 'human' ELSE 'service' END;
  actor_subject_id := turn_row.initiator_subject_id;
  initiating_human_subject_id := turn_row.initiating_human_subject_id;
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  IF visibility_context_set THEN
    PERFORM pg_catalog.set_config(
      'opengeni.subject_id', COALESCE(previous_subject_id, ''), true
    );
    PERFORM pg_catalog.set_config(
      'opengeni.initiating_human_subject_id',
      COALESCE(previous_initiating_human_subject_id, ''),
      true
    );
  END IF;
  RAISE;
END;
$$;

CREATE FUNCTION resolve_workspace_codex_subscription_source(p_account_id uuid, p_workspace_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  mode_value text := 'automatic';
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN
    RAISE EXCEPTION 'Codex workspace source authority required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM workspaces workspace
    WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  ) THEN
    RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
  END IF;
  SELECT preference.mode INTO mode_value
  FROM workspace_codex_subscription_preferences preference
  WHERE preference.account_id = p_account_id
    AND preference.workspace_id = p_workspace_id;
  mode_value := coalesce(mode_value, 'automatic');
  IF mode_value <> 'automatic' THEN
    RETURN mode_value;
  END IF;
  IF EXISTS (
    SELECT 1 FROM codex_subscription_credentials credential
    WHERE credential.account_id = p_account_id
      AND credential.workspace_id = p_workspace_id
      AND credential.authority_scope IN ('workspace', 'user')
  ) THEN
    RETURN 'workspace';
  END IF;
  IF EXISTS (
    SELECT 1 FROM codex_subscription_credentials credential
    WHERE credential.account_id = p_account_id
      AND credential.organization_id = p_account_id
      AND credential.authority_scope = 'organization'
  ) THEN
    RETURN 'organization';
  END IF;
  RETURN 'workspace';
END
$$;

CREATE FUNCTION resolve_workspace_writer_grant_identity(p_account_id uuid, p_subject_id text) RETURNS TABLE(membership_id uuid, membership_status text, authorization_revision bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT membership.id, membership.status, membership.authorization_revision
  FROM organization_memberships membership
  WHERE p_account_id IS NOT NULL
    AND p_subject_id IS NOT NULL
    AND membership.account_id = p_account_id
    -- Tenant fence: a caller can only resolve grants inside the organization
    -- its own RLS context already establishes.
    AND membership.account_id = opengeni_private.current_account_id()
    AND membership.subject_id = p_subject_id
$$;

CREATE FUNCTION restore_vault_item(p_item uuid, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  item_row vault_items;
  vault_row vaults;
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  item_row := opengeni_private.vault_reachable_item(context, p_item);
  vault_row := opengeni_private.vault_reachable_row(context, item_row.vault_id);
  PERFORM opengeni_private.vault_assert_writable(context, vault_row);
  IF item_row.archived_at IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM vault_items item WHERE item.vault_id = vault_row.id
      AND item.archived_at IS NULL AND item.name_key = item_row.name_key) THEN
      PERFORM opengeni_private.vault_raise('vault_item_name_conflict',
        'another item now has this name; rename one of them first',
        pg_catalog.jsonb_build_object('name', item_row.name, 'vaultId', vault_row.id));
    END IF;
    UPDATE vault_items SET archived_at = NULL, generation = generation + 1, updated_at = pg_catalog.now()
    WHERE id = item_row.id RETURNING * INTO item_row;
    PERFORM opengeni_private.vault_audit(item_row.account_id, (context ->> 'workspaceId')::uuid,
      context ->> 'subjectId', 'vault.item.restored', 'vault_item', item_row.id::text,
      pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'itemId', item_row.id, 'itemName', item_row.name));
  END IF;
  result := opengeni_private.vault_item_json(item_row, true);
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION retire_terminal_turn_run_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM agent_run_states
  WHERE account_id = NEW.account_id AND workspace_id = NEW.workspace_id
    AND session_id = NEW.session_id AND turn_id = NEW.id;
  RETURN NEW;
END;
$$;

CREATE FUNCTION reverse_video_allowance_refund() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  allocation opengeni_private.workspace_video_allowance_allocations%ROWTYPE;
  debit credit_ledger_entries%ROWTYPE;
  grant_allocation jsonb;
  restored bigint:=0;
  affected integer;
  opened integer;
  cfg jsonb;
  grant_expiry timestamptz;
  snapshot_boundary timestamptz;
BEGIN
  IF NEW.workspace_id IS NULL OR NEW.type<>'video_generation_refund'
    OR NEW.source_type IS DISTINCT FROM 'video_generation_operation' OR NEW.amount_micros<=0
    OR NEW.source_id IS NULL
    OR NEW.idempotency_key IS DISTINCT FROM 'credit:video_generation_refund:'||NEW.source_id THEN
    RETURN NULL;
  END IF;
  -- Match the debit writer's workspace prefix and serialize against admission,
  -- grants, policy edits, rollover snapshots, and another refund.
  PERFORM 1 FROM workspaces WHERE id=NEW.workspace_id AND account_id=NEW.account_id FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Video allowance refund workspace mismatch' USING ERRCODE='23503'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('usage-allowance:'||NEW.workspace_id::text,0));
  INSERT INTO opengeni_private.usage_allowance_capabilities VALUES
    (pg_backend_pid(),pg_current_xact_id(),TG_TABLE_SCHEMA,NEW.account_id,NEW.workspace_id)
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS opened=ROW_COUNT;
  SELECT * INTO allocation FROM opengeni_private.workspace_video_allowance_allocations
    WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id
      AND operation_id::text=NEW.source_id FOR UPDATE;
  IF FOUND THEN
    SELECT * INTO debit FROM credit_ledger_entries WHERE id=allocation.ledger_id;
    IF NOT FOUND OR debit.account_id IS DISTINCT FROM NEW.account_id
      OR debit.workspace_id IS DISTINCT FROM NEW.workspace_id
      OR debit.type IS DISTINCT FROM 'video_generation_debit'
      OR debit.source_type IS DISTINCT FROM 'video_generation_operation'
      OR debit.source_id IS DISTINCT FROM NEW.source_id
      OR debit.idempotency_key IS DISTINCT FROM 'credit:video_generation_debit:'||NEW.source_id
      OR debit.amount_micros IS DISTINCT FROM -allocation.amount
      OR NEW.amount_micros IS DISTINCT FROM allocation.amount THEN
      RAISE EXCEPTION 'Video allowance refund does not match its original debit' USING ERRCODE='23514';
    END IF;
    IF allocation.reversed_by_ledger_id IS NOT NULL THEN
      IF allocation.reversed_by_ledger_id IS DISTINCT FROM NEW.id THEN
        RAISE EXCEPTION 'Video allowance debit already reversed by another refund' USING ERRCODE='23514';
      END IF;
      -- Same committed ledger replay has no second accounting effect.
    ELSE
      UPDATE opengeni_private.workspace_allowance_counters SET used=used-allocation.amount,
        included_used=included_used-allocation.included_used,
        grants_used=grants_used-allocation.grants_used
      WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id
        AND period_key=allocation.period_key AND subject_id='';
      GET DIAGNOSTICS affected=ROW_COUNT;
      IF affected<>1 THEN
        RAISE EXCEPTION 'Video allowance refund counter unavailable' USING ERRCODE='23514';
      END IF;
      IF allocation.human_subject_id IS NOT NULL THEN
        UPDATE opengeni_private.workspace_allowance_counters SET used=used-allocation.amount
        WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id
          AND period_key=allocation.period_key AND subject_id=allocation.human_subject_id;
        GET DIAGNOSTICS affected=ROW_COUNT;
        IF affected<>1 THEN
          RAISE EXCEPTION 'Video allowance refund member counter unavailable' USING ERRCODE='23514';
        END IF;
      END IF;
      SELECT coalesce(end_at,updated_at) INTO snapshot_boundary FROM opengeni_private.workspace_allowance_periods
        WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id AND period_key=allocation.period_key;
      FOR grant_allocation IN SELECT value FROM jsonb_array_elements(allocation.grant_allocations) LOOP
        UPDATE opengeni_private.workspace_allowance_grants SET remaining=remaining+(grant_allocation->>'credits')::bigint
          WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id
            AND operation_id=grant_allocation->>'operationId'
          RETURNING expires_at INTO grant_expiry;
        GET DIAGNOSTICS affected=ROW_COUNT;
        IF affected<>1 THEN
          RAISE EXCEPTION 'Video allowance refund grant unavailable' USING ERRCODE='23514';
        END IF;
        restored:=restored+(grant_allocation->>'credits')::bigint;
        -- Historical snapshots are observed facts, not today's grant pool.
        -- Append just this restored portion using the original period's
        -- historical expiry boundary, without changing its policy/member facts.
        IF snapshot_boundary IS NOT NULL THEN
          UPDATE opengeni_private.workspace_allowance_periods SET
            grants_remaining=grants_remaining+CASE WHEN grant_expiry IS NULL
              OR grant_expiry>snapshot_boundary THEN (grant_allocation->>'credits')::bigint ELSE 0 END,
            grants_snapshot=grants_snapshot||jsonb_build_array(jsonb_build_object(
              'remaining',(grant_allocation->>'credits')::bigint,'expiresAt',grant_expiry))
          WHERE account_id=NEW.account_id AND workspace_id=NEW.workspace_id AND period_key=allocation.period_key;
        END IF;
      END LOOP;
      IF restored<>allocation.grants_used THEN
        RAISE EXCEPTION 'Video allowance refund allocation mismatch' USING ERRCODE='23514';
      END IF;
      UPDATE opengeni_private.workspace_video_allowance_allocations SET reversed_by_ledger_id=NEW.id
        WHERE ledger_id=allocation.ledger_id;
      -- Current admission excludes expired grants even after their remaining
      -- balance is restored. Original-period counters are never moved forward.
      SELECT config INTO cfg FROM opengeni_private.workspace_usage_allowances WHERE workspace_id=NEW.workspace_id;
      PERFORM capture_usage_allowance_period(NEW.account_id,NEW.workspace_id,cfg,clock_timestamp());
    END IF;
  END IF;
  -- No receipt means a pre-recording debit. Never fabricate allocations from
  -- usage-event totals or reverse another period's counters.
  IF opened=1 THEN
    DELETE FROM opengeni_private.usage_allowance_capabilities
      WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
        AND data_schema=TG_TABLE_SCHEMA AND workspace_id=NEW.workspace_id;
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION revoke_personal_document_authority_after_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    BEGIN
      IF OLD.authority_kind <> 'personal' OR OLD.authority_id IS NULL THEN
        RETURN OLD;
      END IF;
      INSERT INTO opengeni_private.personal_document_authority_capabilities (
        backend_pid, transaction_id, capability_kind
      ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'write')
      ON CONFLICT DO NOTHING;
      UPDATE organization_user_resource_grants
      SET status = 'revoked', generation = generation + 1,
        revoked_at = coalesce(revoked_at, clock_timestamp()),
        updated_at = clock_timestamp()
      WHERE authority_id = OLD.authority_id AND account_id = OLD.account_id
        AND status IN ('active', 'consumed');
      UPDATE organization_user_resource_authorities
      SET status = 'revoked', generation = generation + 1,
        revoked_at = clock_timestamp(), updated_at = clock_timestamp()
      WHERE id = OLD.authority_id AND account_id = OLD.account_id
        AND status <> 'revoked';
      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'write';
      RETURN OLD;
    EXCEPTION WHEN OTHERS THEN
      DELETE FROM opengeni_private.personal_document_authority_capabilities
      WHERE backend_pid = pg_catalog.pg_backend_pid()
        AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
        AND capability_kind = 'write';
      RAISE;
    END
    $$;

CREATE FUNCTION revoke_self_user_resource_grant(p_account_id uuid, p_grant_id uuid) RETURNS TABLE(grant_id uuid, grant_generation bigint, grant_status text, revoked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  owner_membership_id uuid;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR caller_subject IS NULL
  THEN
    RAISE EXCEPTION 'user-resource revoke scope mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT membership.id INTO STRICT owner_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  FOR SHARE;

  UPDATE organization_user_resource_grants grant_value
  SET status = 'revoked', revoked_at = clock_timestamp(),
      generation = grant_value.generation + 1, updated_at = clock_timestamp()
  FROM organization_user_resource_authorities authority
  WHERE grant_value.id = p_grant_id
    AND grant_value.account_id = p_account_id
    AND authority.id = grant_value.authority_id
    AND authority.account_id = grant_value.account_id
    AND authority.organization_membership_id = owner_membership_id
    AND grant_value.owner_organization_membership_id = owner_membership_id
    AND grant_value.status <> 'revoked'
  RETURNING grant_value.id, grant_value.generation, grant_value.status, grant_value.revoked_at
  INTO grant_id, grant_generation, grant_status, revoked_at;
  IF FOUND THEN RETURN NEXT; RETURN; END IF;

  SELECT grant_value.id, grant_value.generation, grant_value.status, grant_value.revoked_at
    INTO grant_id, grant_generation, grant_status, revoked_at
  FROM organization_user_resource_grants grant_value
  JOIN organization_user_resource_authorities authority
    ON authority.id = grant_value.authority_id AND authority.account_id = grant_value.account_id
  WHERE grant_value.id = p_grant_id
    AND grant_value.account_id = p_account_id
    AND authority.organization_membership_id = owner_membership_id
    AND grant_value.owner_organization_membership_id = owner_membership_id
    AND grant_value.status = 'revoked';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'self-owned user-resource grant not found' USING ERRCODE = '42501';
  END IF;
  RETURN NEXT;
END
$$;

COMMENT ON FUNCTION revoke_self_user_resource_grant(p_account_id uuid, p_grant_id uuid) IS 'Owner-only immediate idempotent user-resource grant revocation.';

CREATE FUNCTION revoke_self_user_resource_grant(p_account_id uuid, p_workspace_id uuid, p_grant_id uuid) RETURNS TABLE(grant_id uuid, grant_generation bigint, grant_status text, revoked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  caller_subject text := nullif(current_setting('opengeni.subject_id', true), '');
  owner_membership_id uuid;
BEGIN
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true
  );
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
    OR caller_subject IS NULL
  THEN
    RAISE EXCEPTION 'user-resource revoke scope mismatch' USING ERRCODE = '42501';
  END IF;
  -- 0611: every organization is session-tenancy activated.
  SELECT membership.id INTO owner_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'owner membership not found or access denied' USING ERRCODE = '42501';
  END IF;

  UPDATE organization_user_resource_grants grant_value
  SET status = 'revoked', revoked_at = clock_timestamp(),
      generation = grant_value.generation + 1, updated_at = clock_timestamp()
  FROM organization_user_resource_authorities authority
  WHERE grant_value.id = p_grant_id
    AND grant_value.account_id = p_account_id
    AND grant_value.workspace_id = p_workspace_id
    AND authority.id = grant_value.authority_id
    AND authority.account_id = grant_value.account_id
    AND authority.organization_membership_id = owner_membership_id
    AND grant_value.owner_organization_membership_id = owner_membership_id
    AND grant_value.status <> 'revoked'
  RETURNING grant_value.id, grant_value.generation, grant_value.status, grant_value.revoked_at
  INTO grant_id, grant_generation, grant_status, revoked_at;
  IF FOUND THEN RETURN NEXT; RETURN; END IF;

  SELECT grant_value.id, grant_value.generation, grant_value.status, grant_value.revoked_at
    INTO grant_id, grant_generation, grant_status, revoked_at
  FROM organization_user_resource_grants grant_value
  JOIN organization_user_resource_authorities authority
    ON authority.id = grant_value.authority_id AND authority.account_id = grant_value.account_id
  WHERE grant_value.id = p_grant_id
    AND grant_value.account_id = p_account_id
    AND grant_value.workspace_id = p_workspace_id
    AND authority.organization_membership_id = owner_membership_id
    AND grant_value.owner_organization_membership_id = owner_membership_id
    AND grant_value.status = 'revoked';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'self-owned user-resource grant not found' USING ERRCODE = '42501';
  END IF;
  RETURN NEXT;
END
$$;

COMMENT ON FUNCTION revoke_self_user_resource_grant(p_account_id uuid, p_workspace_id uuid, p_grant_id uuid) IS 'Idempotently revokes an exact owner grant only through its route workspace.';

CREATE FUNCTION run_document_default_collection_backfill(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  account_id_value uuid := nullif(p_command ->> 'accountId', '')::uuid;
  request_workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  actor_subject text := nullif(p_command ->> 'actorSubjectId', '');
  run_id_value uuid := nullif(p_command ->> 'runId', '')::uuid;
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  batch_size integer := coalesce((p_command ->> 'batchSize')::integer, 50);
  account_admin_authorization jsonb := p_command -> 'accountAdminAuthorization';
  account_admin_authorized boolean := false;
  input_hash_value text;
  existing_operation document_default_collection_backfill_operations%ROWTYPE;
  run_row document_default_collection_backfill_runs%ROWTYPE;
  workspace_row workspaces%ROWTYPE;
  base_row document_bases%ROWTYPE;
  outcome_value text;
  batch_processed integer := 0;
  batch_created integer := 0;
  batch_adopted integer := 0;
  has_more boolean;
  result_value jsonb;
BEGIN
  IF p_command IS NULL THEN
    RAISE EXCEPTION 'document Default collection backfill command is required'
      USING ERRCODE = '22023';
  ELSIF account_id_value IS NULL THEN
    RAISE EXCEPTION 'document Default collection backfill account id is required'
      USING ERRCODE = '22023';
  ELSIF request_workspace_id_value IS NULL THEN
    RAISE EXCEPTION 'document Default collection backfill workspace id is required'
      USING ERRCODE = '22023';
  ELSIF actor_subject IS NULL THEN
    RAISE EXCEPTION 'document Default collection backfill actor is required'
      USING ERRCODE = '22023';
  ELSIF run_id_value IS NULL THEN
    RAISE EXCEPTION 'document Default collection backfill run id is required'
      USING ERRCODE = '22023';
  ELSIF operation_id_value IS NULL THEN
    RAISE EXCEPTION 'document Default collection backfill operation id is required'
      USING ERRCODE = '22023';
  ELSIF batch_size NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'document Default collection backfill batch size is invalid'
      USING ERRCODE = '22023';
  END IF;
  IF account_id_value IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'document Default collection backfill account authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF request_workspace_id_value IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'document Default collection backfill workspace authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF actor_subject IS DISTINCT FROM nullif(
      current_setting('opengeni.subject_id', true), ''
    )
  THEN
    RAISE EXCEPTION 'document Default collection backfill actor authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  IF account_admin_authorization IS NOT NULL
    AND account_admin_authorization <> 'null'::jsonb
  THEN
    account_admin_authorized :=
      jsonb_typeof(account_admin_authorization) = 'object'
      AND coalesce(account_admin_authorization ->> 'permission', '') = 'account:admin'
      AND nullif(account_admin_authorization ->> 'accountId', '')::uuid
        IS NOT DISTINCT FROM account_id_value
      AND nullif(account_admin_authorization ->> 'actorSubjectId', '')
        IS NOT DISTINCT FROM actor_subject
      AND coalesce(account_admin_authorization ->> 'authorizationId', '')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
  END IF;
  IF NOT account_admin_authorized THEN
    RAISE EXCEPTION 'document Default collection backfill requires organization administration'
      USING ERRCODE = '42501';
  END IF;

  input_hash_value := encode(
    sha256(convert_to((p_command - 'accountAdminAuthorization')::text, 'UTF8')),
    'hex'
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('document-default-collection-backfill:' || run_id_value::text, 0)
  );
  INSERT INTO opengeni_private.document_migration_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'default_backfill')
  ON CONFLICT DO NOTHING;

  SELECT * INTO existing_operation
  FROM document_default_collection_backfill_operations operation
  WHERE operation.operation_id = operation_id_value
  FOR UPDATE;
  IF FOUND THEN
    IF existing_operation.account_id IS DISTINCT FROM account_id_value
      OR existing_operation.run_id IS DISTINCT FROM run_id_value
      OR existing_operation.input_hash IS DISTINCT FROM input_hash_value
    THEN
      RAISE EXCEPTION 'document Default backfill operation id was reused with different input'
        USING ERRCODE = '23505';
    END IF;
    DELETE FROM opengeni_private.document_migration_capabilities
    WHERE backend_pid = pg_backend_pid()
      AND transaction_id = pg_current_xact_id_if_assigned()
      AND capability_kind = 'default_backfill';
    RETURN existing_operation.result;
  END IF;

  SELECT * INTO run_row
  FROM document_default_collection_backfill_runs run
  WHERE run.run_id = run_id_value
  FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO document_default_collection_backfill_runs (
      run_id, account_id, actor_subject_id
    ) VALUES (run_id_value, account_id_value, actor_subject)
    RETURNING * INTO run_row;
  ELSIF run_row.account_id IS DISTINCT FROM account_id_value
    OR run_row.actor_subject_id IS DISTINCT FROM actor_subject
  THEN
    RAISE EXCEPTION 'document Default backfill run identity mismatch'
      USING ERRCODE = '23505';
  END IF;

  IF run_row.status = 'running' THEN
    FOR workspace_row IN
      SELECT workspace.* FROM workspaces workspace
      WHERE workspace.account_id = account_id_value
        AND (run_row.last_workspace_id IS NULL OR workspace.id > run_row.last_workspace_id)
      ORDER BY workspace.id
      LIMIT batch_size
      FOR UPDATE
    LOOP
      SELECT * INTO base_row
      FROM document_bases base
      WHERE base.workspace_id = workspace_row.id
        AND lower(btrim(base.name)) = 'default'
      ORDER BY base.id
      LIMIT 1
      FOR UPDATE;
      IF FOUND THEN
        outcome_value := 'adopted';
        batch_adopted := batch_adopted + 1;
      ELSE
        INSERT INTO document_bases (
          account_id, workspace_id, name, description
        ) VALUES (
          account_id_value, workspace_row.id, 'Default',
          'Default base for dropped files and notes.'
        )
        ON CONFLICT DO NOTHING
        RETURNING * INTO base_row;
        IF FOUND THEN
          outcome_value := 'created';
          batch_created := batch_created + 1;
        ELSE
          SELECT * INTO STRICT base_row FROM document_bases base
          WHERE base.workspace_id = workspace_row.id
            AND lower(btrim(base.name)) = 'default'
          ORDER BY base.id LIMIT 1;
          outcome_value := 'adopted';
          batch_adopted := batch_adopted + 1;
        END IF;
      END IF;
      INSERT INTO document_default_collection_backfill_receipts (
        run_id, account_id, workspace_id, base_id, outcome
      ) VALUES (
        run_id_value, account_id_value, workspace_row.id, base_row.id, outcome_value
      ) ON CONFLICT (run_id, workspace_id) DO NOTHING;
      run_row.last_workspace_id := workspace_row.id;
      batch_processed := batch_processed + 1;
    END LOOP;

    SELECT EXISTS (
      SELECT 1 FROM workspaces workspace
      WHERE workspace.account_id = account_id_value
        AND (run_row.last_workspace_id IS NULL OR workspace.id > run_row.last_workspace_id)
    ) INTO has_more;
    UPDATE document_default_collection_backfill_runs SET
      last_workspace_id = run_row.last_workspace_id,
      processed_count = processed_count + batch_processed,
      created_count = created_count + batch_created,
      adopted_count = adopted_count + batch_adopted,
      status = CASE WHEN has_more THEN 'running' ELSE 'completed' END,
      updated_at = clock_timestamp(),
      completed_at = CASE WHEN has_more THEN NULL ELSE clock_timestamp() END
    WHERE run_id = run_id_value
    RETURNING * INTO run_row;
  END IF;

  result_value := jsonb_build_object(
    'runId', run_row.run_id,
    'operationId', operation_id_value,
    'status', run_row.status,
    'lastWorkspaceId', run_row.last_workspace_id,
    'processedCount', run_row.processed_count,
    'createdCount', run_row.created_count,
    'adoptedCount', run_row.adopted_count,
    'completedAt', run_row.completed_at
  );
  INSERT INTO document_default_collection_backfill_operations (
    operation_id, run_id, account_id, input_hash, result
  ) VALUES (
    operation_id_value, run_id_value, account_id_value, input_hash_value, result_value
  );
  DELETE FROM opengeni_private.document_migration_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'default_backfill';
  RETURN result_value;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.document_migration_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'default_backfill';
  RAISE;
END
$_$;

CREATE FUNCTION sandbox_warm_attribution_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF OLD.liveness<>'cold' AND NEW.liveness<>'cold'
    AND OLD.resume_state#>>'{opengeniWarmBilling,mode}'='credits'
    AND NEW.resume_state#>'{opengeniWarmBilling,attribution}' IS DISTINCT FROM
      OLD.resume_state#>'{opengeniWarmBilling,attribution}' THEN
    RAISE EXCEPTION 'Sandbox initiating attribution is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION scheduled_scoped_rig_version_metadata(p_account_id uuid, p_workspace_id uuid, p_subject_id text, p_rig_id uuid, p_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE
  accessible_rig jsonb;
  result_value jsonb;
  health_value jsonb;
  health_row record;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
    OR p_subject_id IS NULL
    OR p_subject_id IS DISTINCT FROM nullif(
      current_setting('opengeni.subject_id', true), ''
    )
  THEN RAISE EXCEPTION 'scheduled scoped Rig metadata authority changed'
    USING ERRCODE = '42501'; END IF;

  SELECT value INTO accessible_rig
  FROM list_scoped_rigs(p_account_id, p_workspace_id, p_rig_id, null, null) value;
  IF accessible_rig IS NULL THEN RETURN NULL; END IF;

  SELECT candidate.check_health, candidate.verified_at INTO health_row
  FROM (
      SELECT CASE change.verification ->> 'passed'
          WHEN 'true' THEN 'passing' WHEN 'false' THEN 'failing' END AS check_health,
        coalesce(
          nullif(change.verification ->> 'finishedAt', '')::timestamptz,
          change.updated_at
        ) AS verified_at
      FROM rig_changes change
      WHERE change.account_id = p_account_id
        AND change.result_version_id = p_version_id
        AND change.verification ->> 'passed' IN ('true', 'false')
      UNION ALL
      SELECT CASE event.action WHEN 'rig.verification.passed' THEN 'passing'
          ELSE 'failing' END,
        event.occurred_at
      FROM audit_events event
      WHERE event.account_id = p_account_id
        AND event.target_type = 'rig'
        AND event.action IN ('rig.verification.passed', 'rig.verification.failed')
        AND event.metadata ->> 'versionId' = p_version_id::text
  ) candidate
  ORDER BY candidate.verified_at DESC
  LIMIT 1;
  health_value := jsonb_build_object(
    'checkHealth', coalesce(health_row.check_health, 'unknown'),
    'lastVerifiedAt', health_row.verified_at
  );

  SELECT jsonb_build_object(
      'name', rig.name,
      'version', jsonb_build_object(
        'id', version_value.id,
        'rigId', version_value.rig_id,
        'version', version_value.version,
        'image', version_value.image,
        'setupScript', version_value.setup_script,
        'checks', version_value.checks,
        'credentialHooks', version_value.credential_hooks,
        'defaultVariableSetIds', version_value.default_variable_set_ids,
        'changelog', version_value.changelog,
        'providerImages', version_value.provider_images,
        'createdBy', version_value.created_by,
        'active', version_value.active,
        'createdAt', version_value.created_at
      ),
      'health', health_value
    ) INTO result_value
  FROM rigs rig
  JOIN rig_versions version_value
    ON version_value.rig_id = rig.id
   AND version_value.account_id = rig.account_id
  WHERE rig.id = p_rig_id
    AND rig.account_id = p_account_id
    AND rig.status = 'active'
    AND version_value.id = p_version_id;
  RETURN result_value;
END
$$;

CREATE FUNCTION subscription_personal_authority_v2_valid(snapshot jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE entry jsonb; restriction jsonb; providers text[] := '{}';
  uuid_pattern text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
BEGIN
  IF jsonb_typeof(snapshot) IS DISTINCT FROM 'object'
    OR NOT snapshot ?& ARRAY['version', 'personal']
    OR snapshot - ARRAY['version', 'personal']::text[] <> '{}'::jsonb
    OR snapshot->'version' IS DISTINCT FROM '2'::jsonb
    OR jsonb_typeof(snapshot->'personal') IS DISTINCT FROM 'array'
  THEN RETURN false; END IF;
  IF jsonb_array_length(snapshot->'personal') > 3 THEN RETURN false; END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(snapshot->'personal') LOOP
    IF jsonb_typeof(entry) IS DISTINCT FROM 'object'
      OR NOT entry ?& ARRAY['provider', 'ownerMembershipId', 'authorityGeneration']
      OR entry - ARRAY['provider', 'ownerMembershipId', 'authorityGeneration', 'sharedSessionChoice']::text[] <> '{}'::jsonb
      OR jsonb_typeof(entry->'provider') IS DISTINCT FROM 'string'
      OR NOT coalesce(entry->>'provider' IN ('codex', 'claude', 'xai'), false)
      OR entry->>'provider' = ANY(providers)
      OR jsonb_typeof(entry->'ownerMembershipId') IS DISTINCT FROM 'string'
      OR NOT coalesce(entry->>'ownerMembershipId' ~ uuid_pattern, false)
      OR jsonb_typeof(entry->'authorityGeneration') IS DISTINCT FROM 'number'
      OR NOT coalesce(entry->>'authorityGeneration' ~ '^[1-9][0-9]*$', false)
    THEN RETURN false; END IF;
    IF (entry->>'authorityGeneration')::numeric > 9007199254740991 THEN RETURN false; END IF;
    providers := array_append(providers, entry->>'provider');
    IF entry ? 'sharedSessionChoice' THEN
      restriction := entry->'sharedSessionChoice';
      IF jsonb_typeof(restriction) IS DISTINCT FROM 'object'
        OR NOT restriction ?& ARRAY['sessionId', 'connectionId']
        OR restriction - ARRAY['sessionId', 'connectionId']::text[] <> '{}'::jsonb
        OR jsonb_typeof(restriction->'sessionId') IS DISTINCT FROM 'string'
        OR jsonb_typeof(restriction->'connectionId') IS DISTINCT FROM 'string'
        OR NOT coalesce(restriction->>'sessionId' ~ uuid_pattern, false)
        OR NOT coalesce(restriction->>'connectionId' ~ uuid_pattern, false)
      THEN RETURN false; END IF;
    END IF;
  END LOOP;
  RETURN true;
END
$_$;

CREATE FUNCTION xai_provider_account_authority_snapshot_v1_valid(snapshot jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
      SELECT snapshot = '{"version":1,"scope":"organization"}'::jsonb OR snapshot = '{"version":1,"scope":"workspace"}'::jsonb
        OR (
          jsonb_typeof(snapshot) = 'object'
          AND (SELECT count(*) FROM jsonb_object_keys(snapshot)) = 3
          AND snapshot ?& ARRAY['version', 'scope', 'authorityGeneration']
          AND snapshot -> 'version' = '1'::jsonb
          AND snapshot ->> 'scope' = 'user'
          AND jsonb_typeof(snapshot -> 'authorityGeneration') = 'number'
          AND snapshot ->> 'authorityGeneration' ~ '^[1-9][0-9]*$'
          AND (snapshot ->> 'authorityGeneration')::numeric <= 9007199254740991
        )
    $_$;

CREATE TABLE scheduled_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    schedule jsonb NOT NULL,
    temporal_schedule_id text NOT NULL,
    run_mode text DEFAULT 'new_session_per_run'::text NOT NULL,
    overlap_policy text DEFAULT 'allow_concurrent'::text NOT NULL,
    agent_config jsonb NOT NULL,
    reusable_session_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    variable_set_id uuid,
    rig_id uuid,
    created_by_kind text DEFAULT 'service'::text NOT NULL,
    created_by_subject_id text DEFAULT 'unattributed-legacy'::text NOT NULL,
    created_by_context jsonb DEFAULT '{"backfill": true}'::jsonb NOT NULL,
    personal_connection_delegations jsonb DEFAULT '[]'::jsonb NOT NULL,
    action jsonb DEFAULT '{"kind": "agent_turn"}'::jsonb NOT NULL,
    codex_provider_account_authority_snapshot jsonb DEFAULT '{"scope": "workspace", "version": 1}'::jsonb NOT NULL,
    xai_provider_account_authority_snapshot jsonb DEFAULT '{"scope": "workspace", "version": 1}'::jsonb NOT NULL,
    authority_revision bigint DEFAULT 1 NOT NULL,
    execution_digest text NOT NULL,
    deleted_at timestamp with time zone,
    creator_first_party_mcp_tools jsonb,
    creator_first_party_mcp_permissions jsonb,
    creator_session_policy jsonb,
    owner_subject_id text,
    claude_provider_account_authority_snapshot jsonb DEFAULT '{"scope": "workspace", "version": 1}'::jsonb NOT NULL,
    subscription_authority jsonb,
    authority_inserted_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    visibility text DEFAULT 'workspace_shared'::text NOT NULL,
    vault_policy jsonb DEFAULT '{"mode": "all"}'::jsonb NOT NULL,
    CONSTRAINT scheduled_tasks_action_chk CHECK (((jsonb_typeof(action) = 'object'::text) AND ((action ->> 'kind'::text) = ANY (ARRAY['agent_turn'::text, 'knowledge_source_sync'::text])) AND (octet_length(convert_to((action)::text, 'UTF8'::name)) <= 32768) AND (((action ->> 'kind'::text) = 'agent_turn'::text) OR ((run_mode = 'new_session_per_run'::text) AND (reusable_session_id IS NULL) AND (variable_set_id IS NULL) AND (rig_id IS NULL) AND (overlap_policy = ANY (ARRAY['skip'::text, 'buffer_one'::text])))))),
    CONSTRAINT scheduled_tasks_authority_revision_chk CHECK ((authority_revision > 0)),
    CONSTRAINT scheduled_tasks_claude_authority_snapshot_chk CHECK (claude_provider_account_authority_snapshot_v1_valid(claude_provider_account_authority_snapshot)),
    CONSTRAINT scheduled_tasks_codex_authority_snapshot_chk CHECK (codex_provider_account_authority_snapshot_v1_valid(codex_provider_account_authority_snapshot)),
    CONSTRAINT scheduled_tasks_created_by_context_object_check CHECK ((jsonb_typeof(created_by_context) = 'object'::text)),
    CONSTRAINT scheduled_tasks_created_by_kind_check CHECK ((created_by_kind = ANY (ARRAY['subject'::text, 'service'::text]))),
    CONSTRAINT scheduled_tasks_created_by_subject_nonempty_check CHECK (((octet_length(btrim(created_by_subject_id)) >= 1) AND (octet_length(btrim(created_by_subject_id)) <= 512))),
    CONSTRAINT scheduled_tasks_creator_first_party_mcp_permissions_chk CHECK (((creator_first_party_mcp_permissions IS NULL) OR ((jsonb_typeof(creator_first_party_mcp_permissions) = 'array'::text) AND (octet_length((creator_first_party_mcp_permissions)::text) <= 4096)))),
    CONSTRAINT scheduled_tasks_creator_first_party_mcp_tools_chk CHECK (((creator_first_party_mcp_tools IS NULL) OR ((jsonb_typeof(creator_first_party_mcp_tools) = 'array'::text) AND (octet_length((creator_first_party_mcp_tools)::text) <= 16384)))),
    CONSTRAINT scheduled_tasks_creator_session_policy_chk CHECK (((creator_session_policy IS NULL) OR ((jsonb_typeof(creator_session_policy) = 'object'::text) AND (octet_length((creator_session_policy)::text) <= 4096)))),
    CONSTRAINT scheduled_tasks_execution_digest_chk CHECK ((execution_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT scheduled_tasks_owner_subject_id_check CHECK (((owner_subject_id IS NULL) OR ((length(btrim(owner_subject_id)) >= 1) AND (length(btrim(owner_subject_id)) <= 1024)))),
    CONSTRAINT scheduled_tasks_personal_delegations_array_chk CHECK (((jsonb_typeof(personal_connection_delegations) = 'array'::text) AND (jsonb_array_length(personal_connection_delegations) <= 128))),
    CONSTRAINT scheduled_tasks_subscription_authority_v2_chk CHECK (((subscription_authority IS NULL) OR subscription_personal_authority_v2_valid(subscription_authority))),
    CONSTRAINT scheduled_tasks_tombstone_chk CHECK (((deleted_at IS NULL) OR (status = 'paused'::text))),
    CONSTRAINT scheduled_tasks_vault_policy_check CHECK (opengeni_private.vault_policy_is_valid(vault_policy)),
    CONSTRAINT scheduled_tasks_visibility_check CHECK (((visibility = ANY (ARRAY['workspace_shared'::text, 'user_private'::text])) AND ((visibility = 'workspace_shared'::text) OR (owner_subject_id IS NOT NULL)))),
    CONSTRAINT scheduled_tasks_xai_authority_snapshot_chk CHECK (xai_provider_account_authority_snapshot_v1_valid(xai_provider_account_authority_snapshot))
);

ALTER TABLE ONLY scheduled_tasks FORCE ROW LEVEL SECURITY;

COMMENT ON COLUMN scheduled_tasks.personal_connection_delegations IS 'Historical account/grant selections. Never read or written by current execution; current account choices live in agent_config.';

COMMENT ON COLUMN scheduled_tasks.codex_provider_account_authority_snapshot IS 'Opaque identifier-free Codex provider-account authority snapshot; legacy and current writers default workspace.';

COMMENT ON COLUMN scheduled_tasks.xai_provider_account_authority_snapshot IS 'Immutable identifier-free xAI provider-account authority snapshot for accepted schedule work.';

CREATE FUNCTION scheduled_task_execution_digest(p_task scheduled_tasks) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      (
        ((pg_catalog.to_jsonb(p_task) - 'subscription_authority') - 'authority_inserted_at')
          - ARRAY[
            'name',
            'status',
            'updated_at',
            'authority_revision',
            'execution_digest', 'owner_subject_id', 'visibility'
          ]::text[]
          - (CASE WHEN p_task.creator_first_party_mcp_tools IS NULL
              THEN ARRAY['creator_first_party_mcp_tools'] ELSE ARRAY[]::text[] END)
          - (CASE WHEN p_task.creator_first_party_mcp_permissions IS NULL
              THEN ARRAY['creator_first_party_mcp_permissions'] ELSE ARRAY[]::text[] END)
          - (CASE WHEN p_task.creator_session_policy IS NULL
              THEN ARRAY['creator_session_policy'] ELSE ARRAY[]::text[] END)
          - (CASE WHEN p_task.vault_policy = '{"mode":"all"}'::jsonb
              THEN ARRAY['vault_policy'] ELSE ARRAY[]::text[] END)
      )::text,
      'UTF8'
    )),
    'hex'
  )
$$;

CREATE FUNCTION scheduled_task_execution_state(p_task scheduled_tasks) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT pg_catalog.to_jsonb(p_task) - ARRAY[
    'name', 'status', 'deleted_at', 'updated_at', 'authority_revision', 'execution_digest', 'owner_subject_id', 'visibility'
  ]::text[]
$$;

CREATE FUNCTION scheduled_task_is_exhausted(p_task_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce((SELECT
    NOT EXISTS (SELECT 1 FROM scheduled_task_runs pending
      WHERE pending.task_id = task.id AND pending.account_id = task.account_id
        AND pending.workspace_id = task.workspace_id
        AND pending.status IN ('queued', 'dispatched', 'running'))
    AND ((CASE
      WHEN task.schedule->>'type' = 'interval'
        AND pg_input_is_valid(task.schedule->>'endAt', 'timestamptz')
      THEN (task.schedule->>'endAt')::timestamptz + interval '24 hours' < now()
      WHEN task.schedule->>'type' = 'once'
        AND pg_input_is_valid(task.schedule->>'runAt', 'timestamptz')
      THEN (task.schedule->>'runAt')::timestamptz < now() AND (
        (task.schedule->>'runAt')::timestamptz + interval '24 hours' < now()
        OR EXISTS (SELECT 1 FROM scheduled_task_runs consumed
          WHERE consumed.task_id = task.id AND consumed.account_id = task.account_id
            AND consumed.workspace_id = task.workspace_id
            AND consumed.trigger_type = 'scheduled'
            AND consumed.status IN ('succeeded', 'failed', 'skipped')
            AND (consumed.accepted_execution_snapshot->'task'->'schedule' = task.schedule
              OR (consumed.task_authority_revision = task.authority_revision
                AND consumed.task_execution_digest = task.execution_digest))))
      ELSE false
    END
    AND NOT EXISTS (SELECT 1 FROM scheduled_task_event_settings repeating
      WHERE repeating.task_id = task.id AND repeating.account_id = task.account_id
        AND repeating.workspace_id = task.workspace_id AND NOT repeating.once))
    OR EXISTS (SELECT 1 FROM scheduled_task_event_settings settings
      WHERE settings.task_id = task.id AND settings.account_id = task.account_id
        AND settings.workspace_id = task.workspace_id
        AND settings.once AND settings.completed_at IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM scheduled_task_event_occurrences occurrence
          WHERE occurrence.task_id = task.id AND occurrence.workspace_id = task.workspace_id
            AND (occurrence.status = 'pending'
              OR (occurrence.started_at > now() - interval '1 hour'
                AND NOT EXISTS (SELECT 1 FROM scheduled_task_runs run
                  WHERE run.workspace_id = task.workspace_id AND run.task_id = task.id
                    AND run.producer_key = 'scheduled-task-event:' || occurrence.id::text))))))
    FROM scheduled_tasks task WHERE task.id = p_task_id), false)
$$;

CREATE FUNCTION scheduled_task_personal_resource_authority_subject(p_account_id uuid, p_workspace_id uuid, p_task_id uuid, p_task_authority_revision bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE
  owner_subject text;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
    current_setting('opengeni.account_id', true), ''
  )::uuid OR p_workspace_id IS DISTINCT FROM nullif(
    current_setting('opengeni.workspace_id', true), ''
  )::uuid THEN
    RAISE EXCEPTION 'scheduled personal-resource authority subject scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  SELECT authority.initiating_human_subject_id INTO owner_subject
  FROM scheduled_task_personal_resource_authorities authority
  WHERE authority.task_id = p_task_id
    AND authority.task_authority_revision = p_task_authority_revision
    AND authority.account_id = p_account_id
    AND authority.workspace_id = p_workspace_id;
  RETURN owner_subject;
END
$$;

CREATE FUNCTION scheduled_task_revision_authority_snapshot(p_account_id uuid, p_workspace_id uuid, p_task_id uuid, p_task_authority_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE authority_value jsonb;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN RAISE EXCEPTION 'scheduled revision authority read scope mismatch'
    USING ERRCODE = '42501'; END IF;
  SELECT jsonb_build_object(
    'subjectId', authority.subject_id,
    'organizationMembershipId', authority.organization_membership_id,
    'membershipAuthorizationRevision', authority.membership_authorization_revision
  ) INTO authority_value
  FROM scheduled_task_revision_authorities authority
  WHERE authority.task_id = p_task_id
    AND authority.task_authority_revision = p_task_authority_revision
    AND authority.account_id = p_account_id
    AND authority.workspace_id = p_workspace_id;
  RETURN authority_value;
END
$$;

CREATE FUNCTION scheduled_task_revision_authority_subject(p_account_id uuid, p_workspace_id uuid, p_task_id uuid, p_task_authority_revision bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE subject_value text;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN RAISE EXCEPTION 'scheduled revision authority read scope mismatch'
    USING ERRCODE = '42501'; END IF;
  SELECT authority.subject_id INTO subject_value
  FROM scheduled_task_revision_authorities authority
  WHERE authority.task_id = p_task_id
    AND authority.task_authority_revision = p_task_authority_revision
    AND authority.account_id = p_account_id
    AND authority.workspace_id = p_workspace_id;
  RETURN subject_value;
END
$$;

CREATE FUNCTION scheduled_task_run_connection_authority_subject(p_account_id uuid, p_workspace_id uuid, p_run_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE
  owner_subject text;
  owner_count integer;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
    current_setting('opengeni.account_id', true), ''
  )::uuid OR p_workspace_id IS DISTINCT FROM nullif(
    current_setting('opengeni.workspace_id', true), ''
  )::uuid THEN
    RAISE EXCEPTION 'scheduled connection authority subject scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  SELECT min(snapshot.owner_subject_id), count(DISTINCT snapshot.owner_subject_id)::integer
    INTO owner_subject, owner_count
  FROM scheduled_task_run_connection_authority_snapshots snapshot
  JOIN scheduled_task_runs run ON run.id = snapshot.run_id
    AND run.account_id = snapshot.account_id
    AND run.workspace_id = snapshot.workspace_id
    AND run.task_id = snapshot.task_id
    AND run.task_authority_revision = snapshot.task_authority_revision
    AND run.task_execution_digest = snapshot.execution_digest
  WHERE snapshot.run_id = p_run_id AND snapshot.account_id = p_account_id
    AND snapshot.workspace_id = p_workspace_id;
  IF owner_count > 1 THEN
    RAISE EXCEPTION 'scheduled connection authority has multiple causal humans'
      USING ERRCODE = '42501';
  END IF;
  RETURN owner_subject;
END
$$;

CREATE FUNCTION scheduled_task_run_personal_resource_authority(p_account_id uuid, p_workspace_id uuid, p_run_id uuid) RETURNS TABLE(task_id uuid, task_authority_revision bigint, execution_digest text, initiating_human_subject_id text, resource_kind text, resource_id uuid, resource_version_id uuid, selection_sources text[], authority_id uuid, authority_generation bigint, grant_id uuid, grant_generation bigint, grant_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'scheduled run personal-resource scope mismatch' USING ERRCODE = '42501';
  END IF;
  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_admit')
  ON CONFLICT DO NOTHING;
  RETURN QUERY
  SELECT admission.task_id, admission.task_authority_revision,
    admission.execution_digest, admission.initiating_human_subject_id, snapshot.resource_kind,
    snapshot.resource_id, snapshot.resource_version_id, snapshot.selection_sources,
    snapshot.authority_id, snapshot.authority_generation, snapshot.grant_id,
    snapshot.grant_generation, snapshot.grant_mode
  FROM scheduled_task_run_personal_resource_admissions admission
  JOIN scheduled_task_run_personal_resource_snapshots snapshot
    ON snapshot.run_id = admission.run_id
  WHERE admission.run_id = p_run_id
    AND admission.account_id = p_account_id
    AND admission.workspace_id = p_workspace_id
  ORDER BY snapshot.resource_kind, snapshot.resource_id;
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_admit';
END
$$;

CREATE FUNCTION scheduled_variable_set_expected_generation_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_variable_set_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  run_snapshot jsonb;
  expected_generation bigint;
  expected_count integer;
  session_row record;
  turn_row record;
  attempt_row record;
  variable_set_row record;
  resolved_count integer;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN RAISE EXCEPTION 'scheduled Variable Set attempt scope changed'
    USING ERRCODE = '42501'; END IF;
  -- Runtime materialization admission (0273): organization/workspace sets may
  -- be materialized by an exact pure-service attempt; user-scoped sets still
  -- resolve through the causal human and the personal-resource ledger below.
  PERFORM assert_scoped_variable_set_materialization_attempt(
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_attempt_id, p_execution_generation
  );
  SELECT session_value.id, session_value.active_turn_id,
      session_value.variable_set_ids, session_value.variable_set_id, session_value.rig_id,
      session_value.rig_version_id
    INTO session_row
  FROM sessions session_value
  WHERE session_value.id = p_session_id
    AND session_value.account_id = p_account_id
    AND session_value.workspace_id = p_workspace_id
  FOR SHARE;
  IF NOT FOUND OR session_row.active_turn_id IS DISTINCT FROM p_turn_id THEN
    RAISE EXCEPTION 'scheduled Variable Set attempt is not exact-current'
      USING ERRCODE = '42501';
  END IF;

  SELECT turn_value.id, turn_value.execution_generation,
      turn_value.active_attempt_id, turn_value.scheduled_task_run_id
    INTO turn_row
  FROM session_turns turn_value
  WHERE turn_value.id = p_turn_id
    AND turn_value.account_id = p_account_id
    AND turn_value.workspace_id = p_workspace_id
    AND turn_value.session_id = p_session_id
  FOR SHARE;
  IF NOT FOUND
    OR turn_row.execution_generation IS DISTINCT FROM p_execution_generation
    OR turn_row.active_attempt_id IS DISTINCT FROM p_attempt_id
  THEN RAISE EXCEPTION 'scheduled Variable Set attempt is not exact-current'
    USING ERRCODE = '42501'; END IF;

  SELECT attempt.id, attempt.execution_generation, attempt.state INTO attempt_row
  FROM session_turn_attempts attempt
  WHERE attempt.id = p_attempt_id
    AND attempt.account_id = p_account_id
    AND attempt.workspace_id = p_workspace_id
    AND attempt.session_id = p_session_id
    AND attempt.turn_id = p_turn_id
  FOR SHARE;
  IF NOT FOUND
    OR attempt_row.execution_generation IS DISTINCT FROM p_execution_generation
    OR attempt_row.state NOT IN ('claimed','running')
  THEN RAISE EXCEPTION 'scheduled Variable Set attempt is not exact-current'
    USING ERRCODE = '42501'; END IF;

  IF turn_row.scheduled_task_run_id IS NULL THEN RETURN NULL; END IF;
  SELECT run.accepted_execution_snapshot INTO run_snapshot
  FROM scheduled_task_runs run
  WHERE run.id = turn_row.scheduled_task_run_id
    AND run.account_id = p_account_id
    AND run.workspace_id = p_workspace_id
    AND run.session_id = p_session_id
  FOR SHARE;
  IF NOT FOUND OR run_snapshot IS NULL THEN
    RAISE EXCEPTION 'scheduled Variable Set run binding changed'
      USING ERRCODE = '42501';
  END IF;
  SELECT min(candidate.generation), count(DISTINCT candidate.generation)::integer
    INTO expected_generation, expected_count
  FROM (
    SELECT (run_snapshot -> 'resolvedVariableSet' ->> 'generation')::bigint AS generation
    WHERE run_snapshot -> 'targetSessionExecution' = 'null'::jsonb
      AND run_snapshot -> 'resolvedVariableSet' ->> 'id' = p_variable_set_id::text
    UNION ALL
    SELECT (item ->> 'generation')::bigint
    FROM jsonb_array_elements(
      coalesce(run_snapshot -> 'resolvedRig' -> 'defaultVariableSets', '[]'::jsonb)
    ) item
    WHERE item ->> 'id' = p_variable_set_id::text
    UNION ALL
    SELECT (item ->> 'generation')::bigint
    FROM jsonb_array_elements(coalesce(
      run_snapshot -> 'targetSessionExecution' -> 'variableSets', '[]'::jsonb
    )) item
    WHERE item ->> 'id' = p_variable_set_id::text
    UNION ALL
    SELECT (run_snapshot -> 'targetSessionExecution' ->> 'variableSetGeneration')::bigint
    WHERE run_snapshot -> 'targetSessionExecution' <> 'null'::jsonb
      AND jsonb_array_length(coalesce(
        run_snapshot -> 'targetSessionExecution' -> 'variableSets', '[]'::jsonb
      )) = 0
      AND run_snapshot -> 'targetSessionExecution' ->> 'variableSetId' = p_variable_set_id::text
    UNION ALL
    SELECT (item ->> 'generation')::bigint
    FROM jsonb_array_elements(coalesce(
      run_snapshot -> 'targetSessionExecution' -> 'rigDefaultVariableSets',
      '[]'::jsonb
    )) item
    WHERE item ->> 'id' = p_variable_set_id::text
  ) candidate;
  IF expected_count <> 1 OR expected_generation IS NULL THEN
    RAISE EXCEPTION 'scheduled Variable Set has no exact accepted generation'
      USING ERRCODE = '42501';
  END IF;
  SELECT variable_set.id, variable_set.generation, variable_set.status,
      variable_set.authority_scope, variable_set.workspace_id,
      variable_set.authority_id
    INTO variable_set_row
  FROM workspace_variable_sets variable_set
  WHERE variable_set.id = p_variable_set_id
    AND variable_set.account_id = p_account_id
  FOR SHARE;
  IF NOT FOUND OR variable_set_row.status <> 'active'
    OR variable_set_row.generation IS DISTINCT FROM expected_generation
  THEN RAISE EXCEPTION 'scheduled Variable Set generation changed after claim'
    USING ERRCODE = '42501'; END IF;
  IF NOT coalesce(session_row.variable_set_ids, '[]'::jsonb) ? p_variable_set_id::text
    AND NOT EXISTS (
      SELECT 1 FROM rig_versions version_value
      WHERE version_value.id = session_row.rig_version_id
        AND version_value.rig_id = session_row.rig_id
        AND version_value.account_id = p_account_id
        AND coalesce(version_value.default_variable_set_ids, '[]'::jsonb)
          ? p_variable_set_id::text
      FOR SHARE
    )
  THEN RAISE EXCEPTION 'runtime Variable Set was not selected by the exact session'
    USING ERRCODE = '42501'; END IF;
  IF variable_set_row.authority_scope = 'workspace'
    AND variable_set_row.workspace_id IS DISTINCT FROM p_workspace_id
  THEN RAISE EXCEPTION 'workspace Variable Set is outside the runtime workspace'
    USING ERRCODE = '42501';
  ELSIF variable_set_row.authority_scope = 'user' THEN
    SELECT count(*)::integer INTO resolved_count
    FROM resolve_session_attempt_personal_resources(
      p_account_id, p_workspace_id, p_attempt_id
    ) resolved
    WHERE resolved.resource_kind = 'variable_set'
      AND resolved.resource_id = variable_set_row.id
      AND resolved.authority_id = variable_set_row.authority_id
      AND resolved.authority_generation = variable_set_row.generation;
    IF resolved_count <> 1 THEN
      RAISE EXCEPTION 'personal Variable Set grant is not exact or current'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN expected_generation;
END
$$;

CREATE FUNCTION scoped_compute_actor_membership(p_account_id uuid, p_workspace_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  caller_subject text := nullif(pg_catalog.current_setting('opengeni.subject_id', true), '');
  membership_id uuid;
  personal_workspace_id uuid;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.workspace_id', true), '')::uuid
  THEN
    RAISE EXCEPTION 'scoped compute actor scope mismatch' USING ERRCODE = '42501';
  END IF;
  SELECT membership.id, membership.personal_workspace_id
    INTO membership_id, personal_workspace_id
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = caller_subject
    AND membership.status = 'active' AND membership.revoked_at IS NULL
  FOR SHARE;
  IF membership_id IS NULL THEN RETURN NULL; END IF;
  IF personal_workspace_id IS DISTINCT FROM p_workspace_id THEN
    PERFORM 1 FROM workspace_memberships workspace_membership
    WHERE workspace_membership.account_id = p_account_id
      AND workspace_membership.workspace_id = p_workspace_id
      AND workspace_membership.subject_id = caller_subject
    FOR KEY SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'scoped compute actor lacks current workspace access'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN membership_id;
END
$$;

CREATE FUNCTION scoped_compute_policy_capability_active(p_actor text, p_expected_owner text, p_capability_kind text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT p_actor = p_expected_owner
    AND opengeni_private.scoped_compute_capability_active(p_capability_kind)
$$;

CREATE FUNCTION scoped_knowledge_advance_object_version(p_account_id uuid, p_object_id uuid, p_expected_lifecycle_generation bigint, p_expected_version_generation bigint, p_version_id uuid, p_operation_id text, p_input_hash text, p_reason_code text, p_actor_kind text, p_actor_subject_id text, p_initiating_human_subject_id text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE object_row knowledge_source_objects%ROWTYPE;
    DECLARE version_row knowledge_document_versions%ROWTYPE;
    DECLARE source_row knowledge_sources%ROWTYPE;
    BEGIN
      IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR NOT opengeni_private.scoped_knowledge_actor_authorized(
          p_actor_kind, p_actor_subject_id, p_initiating_human_subject_id
        )
      THEN
        RAISE EXCEPTION 'knowledge object version account authority is invalid'
          USING ERRCODE = '42501';
      END IF;
      SELECT * INTO object_row FROM knowledge_source_objects row
      WHERE row.id = p_object_id AND row.account_id = p_account_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'knowledge source object was not found' USING ERRCODE = 'P0002'; END IF;
      SELECT * INTO version_row FROM knowledge_document_versions row
      WHERE row.id = p_version_id AND row.account_id = p_account_id
        AND row.object_id = p_object_id AND row.operation_id = p_operation_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        );
      IF NOT FOUND THEN RAISE EXCEPTION 'knowledge document version was not found' USING ERRCODE = 'P0002'; END IF;
      IF object_row.current_version_id = version_row.id THEN
        IF version_row.input_hash <> p_input_hash THEN
          RAISE EXCEPTION 'knowledge document version operation was replayed with different input'
            USING ERRCODE = '23505';
        END IF;
        RETURN version_row.version_generation;
      END IF;
      SELECT * INTO source_row FROM knowledge_sources row
      WHERE row.id = version_row.source_id AND row.account_id = p_account_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge document version source was not found'
          USING ERRCODE = 'P0002';
      END IF;
      IF object_row.lifecycle_state <> 'active'
        OR object_row.lifecycle_generation <> p_expected_lifecycle_generation
        OR object_row.version_generation <> p_expected_version_generation
        OR source_row.lifecycle_state <> 'active'
        OR source_row.current_acl_generation IS DISTINCT FROM version_row.acl_generation
        OR version_row.version_generation <> p_expected_version_generation + 1
        OR version_row.input_hash <> p_input_hash
        OR version_row.actor_kind IS DISTINCT FROM p_actor_kind
        OR version_row.actor_subject_id IS DISTINCT FROM p_actor_subject_id
        OR version_row.initiating_human_subject_id IS DISTINCT FROM p_initiating_human_subject_id
      THEN
        RAISE EXCEPTION 'knowledge object version or lifecycle fence changed'
          USING ERRCODE = '40001';
      END IF;
      PERFORM set_config('opengeni.knowledge_mutation_kind', 'version', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', p_object_id::text, true);
      UPDATE knowledge_source_objects SET current_version_id = version_row.id,
        version_generation = version_row.version_generation, updated_at = clock_timestamp()
      WHERE id = p_object_id;
      PERFORM set_config('opengeni.knowledge_mutation_kind', '', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', '', true);
      INSERT INTO knowledge_lifecycle_events (
        account_id, scope_kind, scope_workspace_id, scope_subject_id, scope_key,
        target_kind, object_id, event_type, old_state, new_state,
        old_generation, new_generation, operation_id, input_hash, reason_code,
        actor_kind, actor_subject_id, initiating_human_subject_id
      ) VALUES (
        p_account_id, object_row.scope_kind, object_row.scope_workspace_id,
        object_row.scope_subject_id, object_row.scope_key, 'object', p_object_id,
        'object_version_added', object_row.lifecycle_state, object_row.lifecycle_state,
        object_row.lifecycle_generation, object_row.lifecycle_generation,
        p_operation_id, p_input_hash, p_reason_code, p_actor_kind,
        p_actor_subject_id, p_initiating_human_subject_id
      );
      RETURN version_row.version_generation;
    END;
    $$;

CREATE FUNCTION scoped_knowledge_advance_source_acl(p_account_id uuid, p_source_id uuid, p_expected_lifecycle_generation bigint, p_expected_acl_generation bigint, p_acl_version_id uuid, p_operation_id text, p_input_hash text, p_reason_code text, p_actor_kind text, p_actor_subject_id text, p_initiating_human_subject_id text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE source_row knowledge_sources%ROWTYPE;
    DECLARE acl_row knowledge_source_acl_versions%ROWTYPE;
    BEGIN
      IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR NOT opengeni_private.scoped_knowledge_actor_authorized(
          p_actor_kind, p_actor_subject_id, p_initiating_human_subject_id
        )
      THEN
        RAISE EXCEPTION 'knowledge ACL account authority is invalid' USING ERRCODE = '42501';
      END IF;
      SELECT * INTO source_row FROM knowledge_sources row
      WHERE row.id = p_source_id AND row.account_id = p_account_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'knowledge source was not found' USING ERRCODE = 'P0002'; END IF;
      SELECT * INTO acl_row FROM knowledge_source_acl_versions row
      WHERE row.id = p_acl_version_id AND row.account_id = p_account_id
        AND row.source_id = p_source_id AND row.operation_id = p_operation_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        );
      IF NOT FOUND THEN RAISE EXCEPTION 'knowledge ACL version was not found' USING ERRCODE = 'P0002'; END IF;
      IF source_row.current_acl_generation = acl_row.generation THEN
        IF acl_row.input_hash <> p_input_hash THEN
          RAISE EXCEPTION 'knowledge ACL operation id was replayed with different input'
            USING ERRCODE = '23505';
        END IF;
        RETURN acl_row.generation;
      END IF;
      IF source_row.lifecycle_state <> 'active'
        OR source_row.lifecycle_generation <> p_expected_lifecycle_generation
        OR coalesce(source_row.current_acl_generation, 0) <> p_expected_acl_generation
        OR acl_row.generation <> p_expected_acl_generation + 1
        OR acl_row.input_hash <> p_input_hash
        OR acl_row.actor_kind IS DISTINCT FROM p_actor_kind
        OR acl_row.actor_subject_id IS DISTINCT FROM p_actor_subject_id
        OR acl_row.initiating_human_subject_id IS DISTINCT FROM p_initiating_human_subject_id
      THEN
        RAISE EXCEPTION 'knowledge ACL generation or lifecycle fence changed'
          USING ERRCODE = '40001';
      END IF;
      PERFORM set_config('opengeni.knowledge_mutation_kind', 'acl', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', p_source_id::text, true);
      UPDATE knowledge_sources SET current_acl_generation = acl_row.generation,
        updated_at = clock_timestamp() WHERE id = p_source_id;
      PERFORM set_config('opengeni.knowledge_mutation_kind', '', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', '', true);
      INSERT INTO knowledge_lifecycle_events (
        account_id, scope_kind, scope_workspace_id, scope_subject_id, scope_key,
        target_kind, source_id, event_type, old_state, new_state,
        old_generation, new_generation, operation_id, input_hash, reason_code,
        actor_kind, actor_subject_id, initiating_human_subject_id
      ) VALUES (
        p_account_id, source_row.scope_kind, source_row.scope_workspace_id,
        source_row.scope_subject_id, source_row.scope_key, 'source', p_source_id,
        'acl_changed', source_row.lifecycle_state, source_row.lifecycle_state,
        source_row.lifecycle_generation, source_row.lifecycle_generation,
        p_operation_id, p_input_hash, p_reason_code, p_actor_kind,
        p_actor_subject_id, p_initiating_human_subject_id
      );
      RETURN acl_row.generation;
    END;
    $$;

CREATE FUNCTION scoped_knowledge_apply_lifecycle(p_account_id uuid, p_target_kind text, p_target_id uuid, p_event_type text, p_expected_generation bigint, p_operation_id text, p_input_hash text, p_reason_code text, p_actor_kind text, p_actor_subject_id text, p_initiating_human_subject_id text) RETURNS TABLE(target_id uuid, lifecycle_state text, lifecycle_generation bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE target_row record;
    DECLARE prior_event knowledge_lifecycle_events%ROWTYPE;
    DECLARE next_state text;
    DECLARE provider_ref uuid;
    DECLARE source_ref uuid;
    DECLARE object_ref uuid;
    BEGIN
      IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR p_target_kind NOT IN ('provider', 'source', 'object')
        OR p_event_type NOT IN ('deleted', 'revoked', 'restored')
        OR NOT opengeni_private.scoped_knowledge_actor_authorized(
          p_actor_kind, p_actor_subject_id, p_initiating_human_subject_id
        )
      THEN
        RAISE EXCEPTION 'scoped knowledge lifecycle authority is invalid'
          USING ERRCODE = '42501';
      END IF;

      SELECT * INTO prior_event
      FROM knowledge_lifecycle_events event
      WHERE event.account_id = p_account_id
        AND event.target_kind = p_target_kind
        AND opengeni_private.scoped_knowledge_scope_visible(
          event.account_id, event.scope_kind, event.scope_workspace_id, event.scope_subject_id
        )
        AND event.provider_id IS NOT DISTINCT FROM
          CASE WHEN p_target_kind = 'provider' THEN p_target_id ELSE NULL END
        AND event.source_id IS NOT DISTINCT FROM
          CASE WHEN p_target_kind = 'source' THEN p_target_id ELSE NULL END
        AND event.object_id IS NOT DISTINCT FROM
          CASE WHEN p_target_kind = 'object' THEN p_target_id ELSE NULL END
        AND event.operation_id = p_operation_id;
      IF FOUND THEN
        IF prior_event.input_hash <> p_input_hash OR prior_event.event_type <> p_event_type THEN
          RAISE EXCEPTION 'knowledge lifecycle operation id was replayed with different input'
            USING ERRCODE = '23505';
        END IF;
        RETURN QUERY SELECT p_target_id, prior_event.new_state,
          prior_event.new_generation, true;
        RETURN;
      END IF;

      IF p_target_kind = 'provider' THEN
        SELECT * INTO target_row FROM knowledge_providers row
        WHERE row.id = p_target_id AND row.account_id = p_account_id
          AND opengeni_private.scoped_knowledge_scope_visible(
            row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
          )
        FOR UPDATE;
        provider_ref := p_target_id;
      ELSIF p_target_kind = 'source' THEN
        SELECT * INTO target_row FROM knowledge_sources row
        WHERE row.id = p_target_id AND row.account_id = p_account_id
          AND opengeni_private.scoped_knowledge_scope_visible(
            row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
          )
        FOR UPDATE;
        source_ref := p_target_id;
      ELSE
        SELECT * INTO target_row FROM knowledge_source_objects row
        WHERE row.id = p_target_id AND row.account_id = p_account_id
          AND opengeni_private.scoped_knowledge_scope_visible(
            row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
          )
        FOR UPDATE;
        object_ref := p_target_id;
      END IF;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge lifecycle target was not found' USING ERRCODE = 'P0002';
      END IF;
      IF target_row.lifecycle_generation <> p_expected_generation THEN
        RAISE EXCEPTION 'knowledge lifecycle generation changed' USING ERRCODE = '40001';
      END IF;
      IF p_event_type = 'restored' THEN
        IF target_row.lifecycle_state NOT IN ('deleted', 'revoked') THEN
          RAISE EXCEPTION 'only a tombstoned knowledge target can be restored'
            USING ERRCODE = '23514';
        END IF;
        next_state := 'active';
      ELSE
        IF target_row.lifecycle_state <> 'active' THEN
          RAISE EXCEPTION 'ordinary lifecycle mutation cannot resurrect a knowledge tombstone'
            USING ERRCODE = '23514';
        END IF;
        next_state := CASE p_event_type WHEN 'deleted' THEN 'deleted' ELSE 'revoked' END;
      END IF;

      PERFORM set_config('opengeni.knowledge_mutation_kind', 'lifecycle', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', p_target_id::text, true);
      IF p_target_kind = 'provider' THEN
        UPDATE knowledge_providers target_provider SET lifecycle_state = next_state,
          lifecycle_generation = target_provider.lifecycle_generation + 1,
          updated_at = clock_timestamp()
        WHERE target_provider.id = p_target_id;
      ELSIF p_target_kind = 'source' THEN
        UPDATE knowledge_sources target_source SET lifecycle_state = next_state,
          lifecycle_generation = target_source.lifecycle_generation + 1,
          updated_at = clock_timestamp()
        WHERE target_source.id = p_target_id;
      ELSE
        UPDATE knowledge_source_objects target_object SET lifecycle_state = next_state,
          lifecycle_generation = target_object.lifecycle_generation + 1,
          updated_at = clock_timestamp()
        WHERE target_object.id = p_target_id;
      END IF;
      PERFORM set_config('opengeni.knowledge_mutation_kind', '', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', '', true);

      INSERT INTO knowledge_lifecycle_events (
        account_id, scope_kind, scope_workspace_id, scope_subject_id, scope_key,
        target_kind, provider_id, source_id, object_id, event_type,
        old_state, new_state, old_generation, new_generation,
        operation_id, input_hash, reason_code, actor_kind, actor_subject_id,
        initiating_human_subject_id
      ) VALUES (
        p_account_id, target_row.scope_kind, target_row.scope_workspace_id,
        target_row.scope_subject_id, target_row.scope_key,
        p_target_kind, provider_ref, source_ref, object_ref, p_event_type,
        target_row.lifecycle_state, next_state, target_row.lifecycle_generation,
        target_row.lifecycle_generation + 1, p_operation_id, p_input_hash,
        p_reason_code, p_actor_kind, p_actor_subject_id, p_initiating_human_subject_id
      );
      RETURN QUERY SELECT p_target_id, next_state,
        target_row.lifecycle_generation + 1, false;
    END;
    $$;

CREATE TABLE knowledge_sync_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    scope_kind text NOT NULL,
    scope_workspace_id uuid,
    scope_subject_id text,
    scope_key text NOT NULL,
    source_id uuid NOT NULL,
    input_sync_generation bigint NOT NULL,
    input_lifecycle_generation bigint NOT NULL,
    input_cursor text,
    input_hash text NOT NULL,
    operation_id text NOT NULL,
    state text DEFAULT 'started'::text NOT NULL,
    output_cursor text,
    watermark timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_code text,
    completion_hash text,
    actor_kind text NOT NULL,
    actor_subject_id text NOT NULL,
    initiating_human_subject_id text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT knowledge_sync_runs_actor_chk CHECK (opengeni_private.scoped_knowledge_actor_valid(actor_kind, actor_subject_id, initiating_human_subject_id)),
    CONSTRAINT knowledge_sync_runs_input_chk CHECK (((input_sync_generation >= 0) AND (input_lifecycle_generation > 0) AND (input_hash ~ '^[0-9a-f]{64}$'::text) AND ((length(btrim(operation_id)) >= 1) AND (length(btrim(operation_id)) <= 256)) AND ((input_cursor IS NULL) OR (length(input_cursor) <= 4096)))),
    CONSTRAINT knowledge_sync_runs_metadata_chk CHECK (((jsonb_typeof(metadata) = 'object'::text) AND (octet_length(convert_to((metadata)::text, 'UTF8'::name)) <= 16384) AND ((output_cursor IS NULL) OR (length(output_cursor) <= 4096)))),
    CONSTRAINT knowledge_sync_runs_scope_chk CHECK ((opengeni_private.scoped_knowledge_scope_valid(scope_kind, scope_workspace_id, scope_subject_id) AND (scope_key = opengeni_private.scoped_knowledge_scope_key(scope_kind, scope_workspace_id, scope_subject_id)))),
    CONSTRAINT knowledge_sync_runs_state_chk CHECK ((((state = 'started'::text) AND (completed_at IS NULL) AND (completion_hash IS NULL) AND (output_cursor IS NULL) AND (error_code IS NULL)) OR ((state = 'succeeded'::text) AND (completed_at IS NOT NULL) AND (completion_hash ~ '^[0-9a-f]{64}$'::text) AND (error_code IS NULL)) OR ((state = 'failed'::text) AND (completed_at IS NOT NULL) AND (completion_hash ~ '^[0-9a-f]{64}$'::text) AND ((length(btrim(error_code)) >= 1) AND (length(btrim(error_code)) <= 128)) AND (output_cursor IS NULL))))
);

ALTER TABLE ONLY knowledge_sync_runs FORCE ROW LEVEL SECURITY;

CREATE FUNCTION scoped_knowledge_complete_sync(p_account_id uuid, p_run_id uuid, p_state text, p_output_cursor text, p_watermark timestamp with time zone, p_metadata jsonb, p_error_code text, p_completion_hash text, p_reason_code text) RETURNS SETOF knowledge_sync_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE run_row knowledge_sync_runs%ROWTYPE;
    DECLARE source_row knowledge_sources%ROWTYPE;
    BEGIN
      IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR p_state NOT IN ('succeeded', 'failed')
      THEN
        RAISE EXCEPTION 'knowledge sync completion authority is invalid' USING ERRCODE = '42501';
      END IF;
      SELECT * INTO run_row FROM knowledge_sync_runs row
      WHERE row.id = p_run_id AND row.account_id = p_account_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'knowledge sync run was not found' USING ERRCODE = 'P0002'; END IF;
      IF NOT opengeni_private.scoped_knowledge_actor_authorized(
        run_row.actor_kind, run_row.actor_subject_id, run_row.initiating_human_subject_id
      ) THEN
        RAISE EXCEPTION 'knowledge sync completion actor authority changed'
          USING ERRCODE = '42501';
      END IF;
      IF run_row.state <> 'started' THEN
        IF run_row.state <> p_state OR run_row.completion_hash <> p_completion_hash THEN
          RAISE EXCEPTION 'knowledge sync completion was replayed with different input'
            USING ERRCODE = '23505';
        END IF;
        RETURN NEXT run_row;
        RETURN;
      END IF;
      SELECT * INTO source_row FROM knowledge_sources row
      WHERE row.id = run_row.source_id AND row.account_id = p_account_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          row.account_id, row.scope_kind, row.scope_workspace_id, row.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND OR source_row.lifecycle_state <> 'active'
        OR source_row.lifecycle_generation <> run_row.input_lifecycle_generation
        OR source_row.sync_generation <> run_row.input_sync_generation
      THEN
        RAISE EXCEPTION 'knowledge sync generation or lifecycle fence changed'
          USING ERRCODE = '40001';
      END IF;
      IF p_state = 'succeeded' THEN
        PERFORM set_config('opengeni.knowledge_mutation_kind', 'sync', true);
        PERFORM set_config('opengeni.knowledge_mutation_target', source_row.id::text, true);
        UPDATE knowledge_sources SET sync_generation = sync_generation + 1,
          sync_cursor = p_output_cursor, updated_at = clock_timestamp()
        WHERE id = source_row.id;
      END IF;
      PERFORM set_config('opengeni.knowledge_mutation_kind', 'sync_complete', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', run_row.id::text, true);
      UPDATE knowledge_sync_runs SET state = p_state,
        output_cursor = CASE WHEN p_state = 'succeeded' THEN p_output_cursor ELSE NULL END,
        watermark = p_watermark, metadata = p_metadata,
        error_code = CASE WHEN p_state = 'failed' THEN p_error_code ELSE NULL END,
        completion_hash = p_completion_hash, completed_at = clock_timestamp()
      WHERE id = run_row.id RETURNING * INTO run_row;
      PERFORM set_config('opengeni.knowledge_mutation_kind', '', true);
      PERFORM set_config('opengeni.knowledge_mutation_target', '', true);
      INSERT INTO knowledge_lifecycle_events (
        account_id, scope_kind, scope_workspace_id, scope_subject_id, scope_key,
        target_kind, source_id, event_type, old_state, new_state,
        old_generation, new_generation, operation_id, input_hash, reason_code,
        actor_kind, actor_subject_id, initiating_human_subject_id
      ) VALUES (
        p_account_id, source_row.scope_kind, source_row.scope_workspace_id,
        source_row.scope_subject_id, source_row.scope_key, 'source', source_row.id,
        CASE WHEN p_state = 'succeeded' THEN 'sync_succeeded' ELSE 'sync_failed' END,
        source_row.lifecycle_state, source_row.lifecycle_state,
        source_row.lifecycle_generation, source_row.lifecycle_generation,
        run_row.operation_id, p_completion_hash, p_reason_code,
        run_row.actor_kind, run_row.actor_subject_id, run_row.initiating_human_subject_id
      );
      RETURN NEXT run_row;
    END;
    $$;

CREATE FUNCTION scoped_knowledge_guard_acl_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE source_row knowledge_sources%ROWTYPE;
    BEGIN
      IF NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR NOT opengeni_private.scoped_knowledge_scope_visible(
          NEW.account_id, NEW.scope_kind, NEW.scope_workspace_id, NEW.scope_subject_id
        )
        OR NOT opengeni_private.scoped_knowledge_actor_authorized(
          NEW.actor_kind, NEW.actor_subject_id, NEW.initiating_human_subject_id
        )
      THEN
        RAISE EXCEPTION 'knowledge ACL insert authority is invalid'
          USING ERRCODE = '42501';
      END IF;
      SELECT * INTO source_row
      FROM knowledge_sources source
      WHERE source.id = NEW.source_id
        AND source.account_id = NEW.account_id
        AND source.scope_key = NEW.source_scope_key
        AND opengeni_private.scoped_knowledge_scope_visible(
          source.account_id, source.scope_kind,
          source.scope_workspace_id, source.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND
        OR NEW.generation > coalesce(source_row.current_acl_generation, 0) + 1
        OR (
          NEW.generation = coalesce(source_row.current_acl_generation, 0) + 1
          AND source_row.lifecycle_state <> 'active'
        )
      THEN
        RAISE EXCEPTION 'knowledge ACL insert is outside the current source generation fence'
          USING ERRCODE = '40001';
      END IF;
      RETURN NEW;
    END;
    $$;

CREATE FUNCTION scoped_knowledge_guard_head_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE row_value jsonb := to_jsonb(NEW);
BEGIN
  IF TG_TABLE_NAME = 'knowledge_providers' THEN
    IF row_value->>'lifecycle_state' <> 'active'
      OR (row_value->>'lifecycle_generation')::bigint <> 1
    THEN
      RAISE EXCEPTION 'knowledge provider must start active at generation one'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'knowledge_sources' THEN
    IF row_value->>'lifecycle_state' <> 'active'
      OR (row_value->>'lifecycle_generation')::bigint <> 1
      OR (row_value->>'sync_generation')::bigint <> 0
      OR row_value->'current_acl_generation' <> 'null'::jsonb
      OR row_value->'sync_cursor' <> 'null'::jsonb
    THEN
      RAISE EXCEPTION 'knowledge source initial lifecycle, ACL, and sync state is invalid'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'knowledge_source_objects' THEN
    IF row_value->>'lifecycle_state' <> 'active'
      OR (row_value->>'lifecycle_generation')::bigint <> 1
      OR (row_value->>'version_generation')::bigint <> 0
      OR row_value->'current_version_id' <> 'null'::jsonb
    THEN
      RAISE EXCEPTION 'knowledge source object must start active without a current version'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_knowledge_guard_object_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE mutation_kind text := current_setting('opengeni.knowledge_mutation_kind', true);
DECLARE mutation_writer boolean;
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.scope_workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.scope_workspace_id)
  THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'knowledge source object tombstones are not deleted' USING ERRCODE = '55000';
  END IF;
  SELECT current_user = pg_get_userbyid(procedure_row.proowner)
  INTO mutation_writer
  FROM pg_proc procedure_row
  WHERE procedure_row.oid = CASE mutation_kind
    WHEN 'lifecycle' THEN to_regprocedure(format(
      '%I.scoped_knowledge_apply_lifecycle(uuid,text,uuid,text,bigint,text,text,text,text,text,text)',
      TG_TABLE_SCHEMA
    ))
    WHEN 'version' THEN to_regprocedure(format(
      '%I.scoped_knowledge_advance_object_version(uuid,uuid,bigint,bigint,uuid,text,text,text,text,text,text)',
      TG_TABLE_SCHEMA
    ))
    ELSE NULL
  END;
  IF NOT coalesce(mutation_writer, false)
    OR current_setting('opengeni.knowledge_mutation_target', true) <> OLD.id::text
  THEN
    RAISE EXCEPTION 'knowledge source object mutation target is not fenced' USING ERRCODE = '55000';
  END IF;
  IF mutation_kind = 'lifecycle' THEN
    IF (to_jsonb(NEW) - ARRAY['lifecycle_state', 'lifecycle_generation', 'updated_at'])
        IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['lifecycle_state', 'lifecycle_generation', 'updated_at'])
      OR NEW.lifecycle_generation <> OLD.lifecycle_generation + 1
      OR NOT (
        (OLD.lifecycle_state = 'active' AND NEW.lifecycle_state IN ('deleted', 'revoked'))
        OR (OLD.lifecycle_state IN ('deleted', 'revoked') AND NEW.lifecycle_state = 'active')
      )
    THEN
      RAISE EXCEPTION 'invalid knowledge source object lifecycle mutation'
        USING ERRCODE = '23514';
    END IF;
  ELSIF mutation_kind = 'version' THEN
    IF (to_jsonb(NEW) - ARRAY['version_generation', 'current_version_id', 'updated_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['version_generation', 'current_version_id', 'updated_at'])
      OR NEW.lifecycle_state <> 'active'
      OR NEW.current_version_id IS NULL
      OR NEW.version_generation <> OLD.version_generation + 1
    THEN
      RAISE EXCEPTION 'invalid knowledge source object version mutation'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'knowledge source object mutation kind is invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_knowledge_guard_provider_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE mutation_writer boolean;
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.scope_workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.scope_workspace_id)
  THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'knowledge provider tombstones are not deleted' USING ERRCODE = '55000';
  END IF;
  SELECT current_user = pg_get_userbyid(procedure_row.proowner)
  INTO mutation_writer
  FROM pg_proc procedure_row
  WHERE procedure_row.oid = to_regprocedure(format(
    '%I.scoped_knowledge_apply_lifecycle(uuid,text,uuid,text,bigint,text,text,text,text,text,text)',
    TG_TABLE_SCHEMA
  ));
  IF NOT coalesce(mutation_writer, false)
    OR current_setting('opengeni.knowledge_mutation_kind', true) <> 'lifecycle'
    OR current_setting('opengeni.knowledge_mutation_target', true) <> OLD.id::text
    OR (to_jsonb(NEW) - ARRAY['lifecycle_state', 'lifecycle_generation', 'updated_at'])
      IS DISTINCT FROM
      (to_jsonb(OLD) - ARRAY['lifecycle_state', 'lifecycle_generation', 'updated_at'])
    OR NEW.lifecycle_generation <> OLD.lifecycle_generation + 1
    OR NOT (
      (OLD.lifecycle_state = 'active' AND NEW.lifecycle_state IN ('deleted', 'revoked'))
      OR (OLD.lifecycle_state IN ('deleted', 'revoked') AND NEW.lifecycle_state = 'active')
    )
  THEN
    RAISE EXCEPTION 'invalid knowledge provider lifecycle mutation' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_knowledge_guard_source_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE mutation_kind text := current_setting('opengeni.knowledge_mutation_kind', true);
DECLARE mutation_writer boolean;
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.scope_workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.scope_workspace_id)
  THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'knowledge source tombstones are not deleted' USING ERRCODE = '55000';
  END IF;
  SELECT current_user = pg_get_userbyid(procedure_row.proowner)
  INTO mutation_writer
  FROM pg_proc procedure_row
  WHERE procedure_row.oid = CASE mutation_kind
    WHEN 'lifecycle' THEN to_regprocedure(format(
      '%I.scoped_knowledge_apply_lifecycle(uuid,text,uuid,text,bigint,text,text,text,text,text,text)',
      TG_TABLE_SCHEMA
    ))
    WHEN 'acl' THEN to_regprocedure(format(
      '%I.scoped_knowledge_advance_source_acl(uuid,uuid,bigint,bigint,uuid,text,text,text,text,text,text)',
      TG_TABLE_SCHEMA
    ))
    WHEN 'sync' THEN to_regprocedure(format(
      '%I.scoped_knowledge_complete_sync(uuid,uuid,text,text,timestamptz,jsonb,text,text,text)',
      TG_TABLE_SCHEMA
    ))
    ELSE NULL
  END;
  IF NOT coalesce(mutation_writer, false)
    OR current_setting('opengeni.knowledge_mutation_target', true) <> OLD.id::text
  THEN
    RAISE EXCEPTION 'knowledge source mutation target is not fenced' USING ERRCODE = '55000';
  END IF;
  IF mutation_kind = 'lifecycle' THEN
    IF (to_jsonb(NEW) - ARRAY['lifecycle_state', 'lifecycle_generation', 'updated_at'])
        IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['lifecycle_state', 'lifecycle_generation', 'updated_at'])
      OR NEW.lifecycle_generation <> OLD.lifecycle_generation + 1
      OR NOT (
        (OLD.lifecycle_state = 'active' AND NEW.lifecycle_state IN ('deleted', 'revoked'))
        OR (OLD.lifecycle_state IN ('deleted', 'revoked') AND NEW.lifecycle_state = 'active')
      )
    THEN
      RAISE EXCEPTION 'invalid knowledge source lifecycle mutation' USING ERRCODE = '23514';
    END IF;
  ELSIF mutation_kind = 'acl' THEN
    IF (to_jsonb(NEW) - ARRAY['current_acl_generation', 'updated_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['current_acl_generation', 'updated_at'])
      OR NEW.lifecycle_state <> 'active'
      OR NEW.current_acl_generation IS NULL
      OR NEW.current_acl_generation <> coalesce(OLD.current_acl_generation, 0) + 1
    THEN
      RAISE EXCEPTION 'invalid knowledge source ACL mutation' USING ERRCODE = '23514';
    END IF;
  ELSIF mutation_kind = 'sync' THEN
    IF (to_jsonb(NEW) - ARRAY['sync_generation', 'sync_cursor', 'updated_at'])
        IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['sync_generation', 'sync_cursor', 'updated_at'])
      OR NEW.lifecycle_state <> 'active'
      OR NEW.sync_generation <> OLD.sync_generation + 1
    THEN
      RAISE EXCEPTION 'invalid knowledge source sync mutation' USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'knowledge source mutation kind is invalid' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_knowledge_guard_sync_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE source_row knowledge_sources%ROWTYPE;
    BEGIN
      IF NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR NOT opengeni_private.scoped_knowledge_scope_visible(
          NEW.account_id, NEW.scope_kind, NEW.scope_workspace_id, NEW.scope_subject_id
        )
        OR NOT opengeni_private.scoped_knowledge_actor_authorized(
          NEW.actor_kind, NEW.actor_subject_id, NEW.initiating_human_subject_id
        )
      THEN
        RAISE EXCEPTION 'knowledge sync insert authority is invalid'
          USING ERRCODE = '42501';
      END IF;
      SELECT * INTO source_row
      FROM knowledge_sources source
      WHERE source.id = NEW.source_id
        AND source.account_id = NEW.account_id
        AND source.scope_key = NEW.scope_key
        AND source.scope_kind = NEW.scope_kind
        AND source.scope_workspace_id IS NOT DISTINCT FROM NEW.scope_workspace_id
        AND source.scope_subject_id IS NOT DISTINCT FROM NEW.scope_subject_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          source.account_id, source.scope_kind,
          source.scope_workspace_id, source.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND
        OR source_row.lifecycle_state <> 'active'
        OR NEW.state <> 'started'
        OR NEW.input_lifecycle_generation <> source_row.lifecycle_generation
        OR NEW.input_sync_generation <> source_row.sync_generation
        OR NEW.input_cursor IS DISTINCT FROM source_row.sync_cursor
      THEN
        RAISE EXCEPTION 'knowledge sync insert is outside the current source generation fence'
          USING ERRCODE = '40001';
      END IF;
      RETURN NEW;
    END;
    $$;

CREATE FUNCTION scoped_knowledge_guard_sync_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE mutation_writer boolean;
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.scope_workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.scope_workspace_id)
  THEN
    RETURN OLD;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'knowledge sync runs are not deleted' USING ERRCODE = '55000';
  END IF;
  SELECT current_user = pg_get_userbyid(procedure_row.proowner)
  INTO mutation_writer
  FROM pg_proc procedure_row
  WHERE procedure_row.oid = to_regprocedure(format(
    '%I.scoped_knowledge_complete_sync(uuid,uuid,text,text,timestamptz,jsonb,text,text,text)',
    TG_TABLE_SCHEMA
  ));
  IF NOT coalesce(mutation_writer, false)
    OR current_setting('opengeni.knowledge_mutation_kind', true) <> 'sync_complete'
    OR current_setting('opengeni.knowledge_mutation_target', true) <> OLD.id::text
    OR (to_jsonb(NEW) - ARRAY[
      'state', 'output_cursor', 'watermark', 'metadata', 'error_code',
      'completion_hash', 'completed_at'
    ]) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY[
      'state', 'output_cursor', 'watermark', 'metadata', 'error_code',
      'completion_hash', 'completed_at'
    ])
    OR OLD.state <> 'started'
    OR NEW.state NOT IN ('succeeded', 'failed')
  THEN
    RAISE EXCEPTION 'invalid knowledge sync completion mutation' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_knowledge_guard_version_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE object_row knowledge_source_objects%ROWTYPE;
    DECLARE source_row knowledge_sources%ROWTYPE;
    BEGIN
      IF NEW.account_id IS DISTINCT FROM opengeni_private.current_account_id()
        OR NOT opengeni_private.scoped_knowledge_scope_visible(
          NEW.account_id, NEW.scope_kind, NEW.scope_workspace_id, NEW.scope_subject_id
        )
        OR NOT opengeni_private.scoped_knowledge_actor_authorized(
          NEW.actor_kind, NEW.actor_subject_id, NEW.initiating_human_subject_id
        )
      THEN
        RAISE EXCEPTION 'knowledge document version insert authority is invalid'
          USING ERRCODE = '42501';
      END IF;
      SELECT * INTO object_row
      FROM knowledge_source_objects object
      WHERE object.id = NEW.object_id
        AND object.account_id = NEW.account_id
        AND object.source_id = NEW.source_id
        AND object.scope_key = NEW.scope_key
        AND object.scope_kind = NEW.scope_kind
        AND object.scope_workspace_id IS NOT DISTINCT FROM NEW.scope_workspace_id
        AND object.scope_subject_id IS NOT DISTINCT FROM NEW.scope_subject_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          object.account_id, object.scope_kind,
          object.scope_workspace_id, object.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge document version object is outside the exact scope'
          USING ERRCODE = '23514';
      END IF;
      SELECT * INTO source_row
      FROM knowledge_sources source
      WHERE source.id = NEW.source_id
        AND source.account_id = NEW.account_id
        AND source.scope_key = NEW.scope_key
        AND source.scope_kind = NEW.scope_kind
        AND source.scope_workspace_id IS NOT DISTINCT FROM NEW.scope_workspace_id
        AND source.scope_subject_id IS NOT DISTINCT FROM NEW.scope_subject_id
        AND opengeni_private.scoped_knowledge_scope_visible(
          source.account_id, source.scope_kind,
          source.scope_workspace_id, source.scope_subject_id
        )
      FOR UPDATE;
      IF NOT FOUND
        OR NEW.version_generation > object_row.version_generation + 1
        OR (
          NEW.version_generation = object_row.version_generation + 1
          AND (
            object_row.lifecycle_state <> 'active'
            OR source_row.lifecycle_state <> 'active'
            OR NEW.acl_generation IS DISTINCT FROM source_row.current_acl_generation
          )
        )
      THEN
        RAISE EXCEPTION 'knowledge document version is outside the current object/source fence'
          USING ERRCODE = '40001';
      END IF;
      RETURN NEW;
    END;
    $$;

CREATE FUNCTION scoped_knowledge_reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- The owning workspace is being deleted: admit only its cascade.
  IF TG_OP = 'DELETE' AND pg_catalog.pg_trigger_depth() > 1
    AND OLD.scope_workspace_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM {{schema}}.workspaces w WHERE w.id = OLD.scope_workspace_id)
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'scoped knowledge provenance is immutable' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION scoped_knowledge_validate_bridge() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE version_document_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'knowledge_source_objects' THEN
    IF NEW.document_id IS NOT NULL THEN
      IF NEW.scope_workspace_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM documents document
        WHERE document.id = NEW.document_id
          AND document.account_id = NEW.account_id
          AND document.workspace_id = NEW.scope_workspace_id
      ) THEN
        RAISE EXCEPTION 'knowledge source object document bridge is outside its exact account/workspace'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'knowledge_document_versions' THEN
    IF NOT EXISTS (
      SELECT 1 FROM knowledge_source_acl_versions acl
      WHERE acl.id = NEW.acl_version_id
        AND acl.account_id = NEW.account_id
        AND acl.source_id = NEW.source_id
        AND acl.generation = NEW.acl_generation
    ) THEN
      RAISE EXCEPTION 'knowledge document version ACL reference is not exact'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.document_id IS NULL AND NEW.file_id IS NOT NULL THEN
      RAISE EXCEPTION 'knowledge document version file bridge requires a document bridge'
        USING ERRCODE = '23514';
    END IF;
    IF NEW.document_id IS NOT NULL AND (
      NEW.scope_workspace_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM documents document
        WHERE document.id = NEW.document_id
          AND document.account_id = NEW.account_id
          AND document.workspace_id = NEW.scope_workspace_id
          AND (NEW.file_id IS NULL OR document.file_id = NEW.file_id)
      )
    ) THEN
      RAISE EXCEPTION 'knowledge document version bridge is outside its exact account/workspace/file'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'knowledge_claim_evidence' THEN
    IF NEW.document_chunk_id IS NOT NULL THEN
      SELECT document_id INTO version_document_id
      FROM knowledge_document_versions
      WHERE id = NEW.document_version_id;
      IF version_document_id IS NULL OR NEW.scope_workspace_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM document_chunks chunk
        WHERE chunk.id = NEW.document_chunk_id
          AND chunk.account_id = NEW.account_id
          AND chunk.workspace_id = NEW.scope_workspace_id
          AND chunk.document_id = version_document_id
          AND (NEW.chunk_index IS NULL OR chunk.chunk_index = NEW.chunk_index)
      ) THEN
        RAISE EXCEPTION 'knowledge claim evidence chunk bridge is not exact'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_knowledge_validate_claim_relation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(NEW.account_id::text || ':' || NEW.scope_key, 0)
  );
  IF NEW.relation_type = 'supersedes' AND EXISTS (
    WITH RECURSIVE path(claim_id) AS (
      SELECT relation.to_claim_id
      FROM knowledge_claim_relations relation
      WHERE relation.account_id = NEW.account_id
        AND relation.scope_key = NEW.scope_key
        AND relation.relation_type = 'supersedes'
        AND relation.from_claim_id = NEW.to_claim_id
      UNION
      SELECT relation.to_claim_id
      FROM knowledge_claim_relations relation
      JOIN path ON relation.from_claim_id = path.claim_id
      WHERE relation.account_id = NEW.account_id
        AND relation.scope_key = NEW.scope_key
        AND relation.relation_type = 'supersedes'
    )
    SELECT 1 FROM path WHERE claim_id = NEW.from_claim_id
  ) THEN
    RAISE EXCEPTION 'knowledge claim supersession cannot create a cycle'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION scoped_rig_json(p_rig_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  SELECT pg_catalog.jsonb_build_object(
    'id', rig.id, 'accountId', rig.account_id, 'workspaceId', rig.workspace_id,
    'scope', rig.authority_scope, 'generation', rig.generation, 'status', rig.status,
    'name', rig.name, 'description', rig.description, 'createdBy', rig.created_by,
    'activeVersion', (
      SELECT pg_catalog.jsonb_build_object(
        'id', version.id, 'rigId', version.rig_id, 'version', version.version,
        'image', version.image, 'setupScript', version.setup_script,
        'checks', version.checks, 'credentialHooks', version.credential_hooks,
        'defaultVariableSetIds', version.default_variable_set_ids,
        'changelog', version.changelog, 'providerImages', version.provider_images,
        'createdBy', version.created_by, 'active', version.active,
        'createdAt', version.created_at
      ) FROM rig_versions version
      WHERE version.rig_id = rig.id AND version.account_id = rig.account_id
        AND version.active = true LIMIT 1
    ),
    'activeVersionHealth', (
      SELECT pg_catalog.jsonb_build_object(
        'checkHealth', coalesce(health.check_health, 'unknown'),
        'lastVerifiedAt', health.verified_at
      )
      FROM rig_versions active_version
      LEFT JOIN LATERAL (
        SELECT candidate.check_health, candidate.verified_at
        FROM (
          SELECT CASE change.verification ->> 'passed'
              WHEN 'true' THEN 'passing' WHEN 'false' THEN 'failing' END AS check_health,
            coalesce(
              nullif(change.verification ->> 'finishedAt', '')::timestamptz,
              change.updated_at
            ) AS verified_at
          FROM rig_changes change
          WHERE change.account_id = active_version.account_id
            AND change.workspace_id = active_version.workspace_id
            AND change.result_version_id = active_version.id
            AND change.verification ->> 'passed' IN ('true', 'false')
          UNION ALL
          SELECT CASE event.action WHEN 'rig.verification.passed' THEN 'passing'
              ELSE 'failing' END,
            event.occurred_at
          FROM audit_events event
          WHERE event.account_id = active_version.account_id
            AND event.workspace_id = active_version.workspace_id
            AND event.target_type = 'rig'
            AND event.target_id = rig.id::text
            AND event.action IN ('rig.verification.passed', 'rig.verification.failed')
            AND event.metadata ->> 'versionId' = active_version.id::text
        ) candidate
        ORDER BY candidate.verified_at DESC
        LIMIT 1
      ) health ON true
      WHERE active_version.rig_id = rig.id
        AND active_version.account_id = rig.account_id
        AND active_version.active = true
      LIMIT 1
    ),
    'versionCount', (SELECT count(*)::integer FROM rig_versions version
      WHERE version.rig_id = rig.id AND version.account_id = rig.account_id),
    'createdAt', rig.created_at, 'updatedAt', rig.updated_at
  ) FROM rigs rig WHERE rig.id = p_rig_id
$$;

COMMENT ON FUNCTION scoped_rig_json(p_rig_id uuid) IS 'Access-controlled Rig projection with active-version health from terminal evidence and trusted audit occurrence timestamps.';

CREATE FUNCTION scoped_variable_set_actor_membership(p_account_id uuid, p_workspace_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      caller_subject text := nullif(pg_catalog.current_setting('opengeni.subject_id', true), '');
      membership_id uuid;
      personal_workspace_id uuid;
    BEGIN
      IF p_account_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.account_id', true), ''
        )::uuid
        OR p_workspace_id IS DISTINCT FROM nullif(
          pg_catalog.current_setting('opengeni.workspace_id', true), ''
        )::uuid
      THEN
        RAISE EXCEPTION 'variable-set actor scope mismatch' USING ERRCODE = '42501';
      END IF;

      SELECT membership.id, membership.personal_workspace_id
        INTO membership_id, personal_workspace_id
      FROM organization_memberships membership
      WHERE membership.account_id = p_account_id
        AND membership.subject_id = caller_subject
        AND membership.status = 'active'
        AND membership.revoked_at IS NULL
      FOR SHARE;

      -- Configured-key, delegated API-grant, and legacy internal callers may
      -- predate organization memberships. They may operate on organization or
      -- workspace sets only: a NULL membership id can never match a user-owned
      -- set. Exact runtime materialization separately validates its canonical
      -- session, turn, attempt, generation, and selected variable set.
      IF membership_id IS NULL THEN
        RETURN NULL;
      END IF;

      IF personal_workspace_id IS DISTINCT FROM p_workspace_id THEN
        PERFORM 1
        FROM workspace_memberships workspace_membership
        WHERE workspace_membership.account_id = p_account_id
          AND workspace_membership.workspace_id = p_workspace_id
          AND workspace_membership.subject_id = caller_subject
        FOR KEY SHARE;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'variable-set actor lacks current workspace access'
            USING ERRCODE = '42501';
        END IF;
      END IF;
      RETURN membership_id;
    END
    $$;

CREATE FUNCTION scoped_variable_set_json(p_variable_set_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
      SELECT pg_catalog.jsonb_build_object(
        'id', variable_set.id,
        'accountId', variable_set.account_id,
        'workspaceId', variable_set.workspace_id,
        'scope', variable_set.authority_scope,
        'generation', variable_set.generation,
        'status', variable_set.status,
        'name', variable_set.name,
        'description', variable_set.description,
        'variables', coalesce((
          SELECT pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'name', variable.name,
              'version', variable.version,
              'createdAt', variable.created_at,
              'updatedAt', variable.updated_at
            ) ORDER BY variable.name
          )
          FROM workspace_variable_set_variables variable
          WHERE variable.variable_set_id = variable_set.id
            AND variable.account_id = variable_set.account_id
        ), '[]'::jsonb),
        'createdAt', variable_set.created_at,
        'updatedAt', variable_set.updated_at
      )
      FROM workspace_variable_sets variable_set
      WHERE variable_set.id = p_variable_set_id
    $$;

CREATE FUNCTION seed_session_usage_limit_root() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE tenant record; opened integer;
BEGIN
  FOR tenant IN
    SELECT DISTINCT s.account_id, s.workspace_id FROM inserted_sessions s
    WHERE s.id = s.root_session_id
  LOOP
    INSERT INTO opengeni_private.session_usage_limit_capabilities VALUES
      (pg_backend_pid(),pg_current_xact_id(),TG_TABLE_SCHEMA,tenant.account_id,tenant.workspace_id)
      ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS opened = ROW_COUNT;
    INSERT INTO opengeni_private.session_usage_limit_roots(account_id,workspace_id,root_session_id,history_state)
      SELECT s.account_id, s.workspace_id, s.id, 'complete' FROM inserted_sessions s
      WHERE s.id = s.root_session_id
        AND s.account_id = tenant.account_id AND s.workspace_id = tenant.workspace_id
      ON CONFLICT (workspace_id, root_session_id) DO NOTHING;
    IF opened = 1 THEN
      DELETE FROM opengeni_private.session_usage_limit_capabilities
        WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
          AND data_schema=TG_TABLE_SCHEMA AND account_id=tenant.account_id
          AND workspace_id=tenant.workspace_id;
    END IF;
  END LOOP;
  RETURN NULL;
END $$;

CREATE FUNCTION session_attempt_interruption_fill_quiescence_hint() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  NEW.attempt_quiesced := coalesce((
    SELECT attempt.quiesced_at IS NOT NULL
    FROM session_turn_attempts attempt
    WHERE attempt.workspace_id = NEW.workspace_id
      AND attempt.id = NEW.attempt_id
  ), false);
  RETURN NEW;
END
$$;

CREATE FUNCTION session_document_inspection_receipt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (OLD.action = 'artifact.document.inspect' OR NEW.action = 'artifact.document.inspect') AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'Native document inspection receipts are immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_document_inspection_receipt_retained() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Keep proof while its session exists. FK retention cascades remove the
  -- session first and must remain able to delete its receipts. Checking parent
  -- existence also prevents using an unrelated nested trigger to bypass this.
  IF OLD.action = 'artifact.document.inspect' AND EXISTS (
    SELECT 1 FROM sessions WHERE account_id = OLD.account_id
      AND workspace_id = OLD.workspace_id AND id = OLD.target_session_id
  ) THEN
    RAISE EXCEPTION 'Native document inspection receipts are retained with their session' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
END;
$$;

CREATE FUNCTION session_events_fill_tool_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  NEW.tool_name := CASE WHEN NEW.type = 'agent.toolCall.created'
    THEN NEW.payload ->> 'name' ELSE NULL END;
  NEW.tool_call_id := CASE WHEN NEW.type IN ('agent.toolCall.created', 'agent.toolCall.output')
    THEN coalesce(NEW.payload ->> 'callId', NEW.payload ->> 'call_id', NEW.payload ->> 'id')
    ELSE NULL END;
  RETURN NEW;
END
$$;

CREATE FUNCTION session_events_fill_usage_source_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  NEW.usage_source_key := NULLIF(NEW.payload ->> 'sourceKey', '');
  RETURN NEW;
END
$$;

CREATE FUNCTION session_foreign_subscription_binding_count(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_owner_subject_id text) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  RETURN (SELECT count(*)::integer FROM subscription_session_bindings binding
    WHERE binding.account_id = p_account_id AND binding.workspace_id = p_workspace_id
      AND binding.session_id = p_session_id AND binding.connection_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM subscription_connections connection
        WHERE connection.account_id = binding.account_id
          AND connection.id = binding.connection_id
          AND (connection.ownership <> 'personal'
            OR connection.owner_subject_id = p_owner_subject_id)));
END
$$;

CREATE FUNCTION session_goal_freeze_report_requirements() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE requirements jsonb;
BEGIN
  IF NEW.goal_snapshot ->> 'state' <> 'none' THEN
    SELECT coalesce(metadata -> 'reportRequirementsV1', '[]'::jsonb) INTO requirements
      FROM session_goals WHERE workspace_id = NEW.workspace_id AND session_id = NEW.session_id;
    NEW.goal_snapshot := NEW.goal_snapshot || jsonb_build_object('reportRequirements', coalesce(requirements, '[]'::jsonb));
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_freeze_turn_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  goal_row "session_goals"%ROWTYPE;
BEGIN
  SELECT * INTO goal_row
  FROM "session_goals"
  WHERE "workspace_id" = NEW."workspace_id"
    AND "session_id" = NEW."session_id";

  IF FOUND THEN
    NEW."goal_snapshot" := jsonb_build_object(
      'state', goal_row."status",
      'goalId', goal_row."id"::text,
      'objectiveRevision', goal_row."objective_revision",
      'text', session_goal_prompt_projection(goal_row."text", 8192),
      'successCriteria', to_jsonb(
        session_goal_prompt_projection(goal_row."success_criteria", 8192)
      ),
      'rootConstraints', goal_row."root_constraints",
      'mutationPolicy', goal_row."mutation_policy",
      'capturedAt', to_char(
        NEW."created_at" AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
      )
    );
  ELSE
    NEW."goal_snapshot" := jsonb_build_object(
      'state', 'none',
      'capturedAt', to_char(
        NEW."created_at" AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
      )
    );
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_normalize_root_constraints(value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  item jsonb;
  normalized jsonb;
  normalized_count integer;
  aggregate_bytes integer;
BEGIN
  IF value IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;
  IF jsonb_typeof(value) <> 'array' THEN
    RAISE EXCEPTION 'goal root constraints must be a JSON array'
      USING ERRCODE = '23514';
  END IF;
  FOR item IN SELECT value_item FROM jsonb_array_elements(value) AS items(value_item)
  LOOP
    IF jsonb_typeof(item) <> 'string' THEN
      RAISE EXCEPTION 'goal root constraints must contain only strings'
        USING ERRCODE = '23514';
    END IF;
    IF btrim(item #>> '{}') = '' THEN
      RAISE EXCEPTION 'goal root constraints must not be blank'
        USING ERRCODE = '23514';
    END IF;
    IF octet_length(btrim(item #>> '{}')) > 512 THEN
      RAISE EXCEPTION 'goal root constraint exceeds 512 UTF-8 bytes'
        USING ERRCODE = '22001';
    END IF;
  END LOOP;

  SELECT
    coalesce(jsonb_agg(to_jsonb(candidate) ORDER BY convert_to(candidate, 'UTF8')), '[]'::jsonb),
    count(*)::integer,
    coalesce(sum(octet_length(candidate)), 0)::integer
  INTO normalized, normalized_count, aggregate_bytes
  FROM (
    SELECT DISTINCT btrim(value_item #>> '{}') AS candidate
    FROM jsonb_array_elements(value) AS items(value_item)
  ) normalized_items;

  IF normalized_count > 16 THEN
    RAISE EXCEPTION 'goal root constraints exceed 16 items'
      USING ERRCODE = '22001';
  END IF;
  IF aggregate_bytes > 4096 THEN
    RAISE EXCEPTION 'goal root constraints exceed 4096 aggregate UTF-8 bytes'
      USING ERRCODE = '22001';
  END IF;
  RETURN normalized;
END;
$$;

CREATE FUNCTION session_goal_normalize_root_constraints_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW."root_constraints" := session_goal_normalize_root_constraints(
    NEW."root_constraints"
  );
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_prompt_projection(value text, max_bytes integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
DECLARE
  original_bytes integer := octet_length(value);
  marker text;
  budget integer;
  lower_chars integer := 0;
  upper_chars integer := length(value);
  midpoint integer;
BEGIN
  IF original_bytes <= max_bytes THEN
    RETURN value;
  END IF;
  marker := E'\n[truncated; original UTF-8 bytes=' || original_bytes::text || ']';
  budget := greatest(0, max_bytes - octet_length(marker));
  WHILE lower_chars < upper_chars LOOP
    midpoint := (lower_chars + upper_chars + 1) / 2;
    IF octet_length(left(value, midpoint)) <= budget THEN
      lower_chars := midpoint;
    ELSE
      upper_chars := midpoint - 1;
    END IF;
  END LOOP;
  RETURN left(value, lower_chars) || marker;
END;
$$;

CREATE FUNCTION session_goal_reject_turn_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD."goal_snapshot" IS NOT NULL
    AND NEW."goal_snapshot" IS DISTINCT FROM OLD."goal_snapshot" THEN
    RAISE EXCEPTION 'turn goal snapshot is immutable after acceptance'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_report_requirements_before_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Parent session/workspace deletion remains cancellation, not completion.
  -- Ordinary goal clearing must carry the exact trusted API cancellation stamp.
  IF pg_trigger_depth() = 1 AND OLD.status <> 'completed'
    AND jsonb_array_length(coalesce(OLD.metadata -> 'reportRequirementsV1', '[]'::jsonb)) > 0
    AND current_setting('opengeni.goal_report_clear_id', true) IS DISTINCT FROM OLD.id::text
  THEN
    RAISE EXCEPTION 'Pending report requirements require explicit API cancellation' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
END;
$$;

CREATE FUNCTION session_goal_report_requirements_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE requirements jsonb := coalesce(NEW.metadata -> 'reportRequirementsV1', '[]'::jsonb);
DECLARE previous_requirements jsonb;
DECLARE deliveries jsonb;
DECLARE requirement jsonb;
DECLARE delivery jsonb;
DECLARE artifact record;
BEGIN
  IF jsonb_typeof(requirements) <> 'array' OR jsonb_array_length(requirements) > 16 THEN
    RAISE EXCEPTION 'Invalid goal report requirements' USING ERRCODE = '23514';
  END IF;
  FOR requirement IN SELECT value FROM jsonb_array_elements(requirements) LOOP
    IF jsonb_typeof(requirement) <> 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(requirement)) <> 2
      OR jsonb_typeof(requirement -> 'id') IS DISTINCT FROM 'string'
      OR (requirement ->> 'id') !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$'
      OR jsonb_typeof(requirement -> 'title') IS DISTINCT FROM 'string'
      OR octet_length(requirement ->> 'title') NOT BETWEEN 1 AND 512
      OR btrim(requirement ->> 'title') = ''
    THEN RAISE EXCEPTION 'Invalid goal report requirement' USING ERRCODE = '23514'; END IF;
  END LOOP;
  IF (SELECT count(DISTINCT value ->> 'id') FROM jsonb_array_elements(requirements)) <> jsonb_array_length(requirements) THEN
    RAISE EXCEPTION 'Duplicate goal report requirement IDs' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND NOT (OLD.status = 'completed' AND NEW.status = 'active') THEN
    previous_requirements := coalesce(OLD.metadata -> 'reportRequirementsV1', '[]'::jsonb);
    IF NOT requirements @> previous_requirements THEN
      RAISE EXCEPTION 'Goal report requirements are append-only until completed-goal replacement' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'completed' AND (requirements <> previous_requirements OR NEW.metadata -> 'reportDeliveriesV1' IS DISTINCT FROM OLD.metadata -> 'reportDeliveriesV1') THEN
      RAISE EXCEPTION 'Completed report requirements and deliveries are immutable' USING ERRCODE = '23514';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'completed' AND NEW.status = 'active' THEN
    -- Old rolling writers retain metadata on replacement. They must never
    -- reuse a previous goal's verified delivery to complete the new goal.
    NEW.metadata := jsonb_set(NEW.metadata, '{reportDeliveriesV1}', '[]'::jsonb);
  END IF;
  IF NEW.status = 'completed' AND (TG_OP = 'INSERT' OR OLD.status <> 'completed') AND jsonb_array_length(requirements) > 0 THEN
    deliveries := coalesce(NEW.metadata -> 'reportDeliveriesV1', '[]'::jsonb);
    IF jsonb_typeof(deliveries) <> 'array' OR jsonb_array_length(deliveries) <> jsonb_array_length(requirements)
      OR (SELECT count(DISTINCT value ->> 'requirementId') FROM jsonb_array_elements(deliveries)) <> jsonb_array_length(requirements)
    THEN RAISE EXCEPTION 'Missing report deliveries' USING ERRCODE = '23514'; END IF;
    -- Same no-wait lock policy as the application: artifact writers already
    -- lock the aggregate before checking their actor's session authority.
    FOR delivery IN SELECT value FROM jsonb_array_elements(deliveries) ORDER BY value ->> 'artifactId' LOOP
      IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(requirements) r WHERE r ->> 'id' = delivery ->> 'requirementId') THEN
        RAISE EXCEPTION 'Unknown report requirement' USING ERRCODE = '23514';
      END IF;
      SELECT head_sequence, state_hash, authorization_revision INTO artifact FROM editable_artifacts
        WHERE account_id = NEW.account_id AND workspace_id = NEW.workspace_id
          AND id = delivery ->> 'artifactId' AND modality = 'document' AND lifecycle_state = 'active'
        FOR SHARE NOWAIT;
      IF NOT FOUND THEN RAISE EXCEPTION 'Report document unavailable' USING ERRCODE = '23514'; END IF;
      IF NOT EXISTS (
        SELECT 1 FROM session_command_receipts receipt
        WHERE receipt.id::text = delivery ->> 'inspectionReceiptId'
          AND receipt.account_id = NEW.account_id AND receipt.workspace_id = NEW.workspace_id
          AND receipt.target_session_id = NEW.session_id
          AND receipt.actor_type = 'agent_attempt' AND receipt.action = 'artifact.document.inspect'
          AND receipt.result ->> 'version' = 'native-document-inspection.v1'
          AND receipt.result ->> 'queryKind' = 'body'
          AND receipt.result ->> 'artifactId' = delivery ->> 'artifactId'
          AND receipt.result ->> 'headSequence' = artifact.head_sequence::text
          AND receipt.result ->> 'stateHash' = artifact.state_hash
          AND receipt.result ->> 'authorizationRevision' = artifact.authorization_revision::text
      ) THEN RAISE EXCEPTION 'Missing or stale document inspection proof' USING ERRCODE = '23514'; END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$_$;

CREATE FUNCTION session_goal_revision_after_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  semantic_change boolean := TG_OP = 'INSERT';
  base_revision integer := 0;
  change_kind text := 'replacement';
  change_rationale text := 'Goal created';
  change_actor text;
  change_turn_id uuid;
  change_attempt_id uuid;
  source_proposal_id uuid;
  rollback_revision_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    semantic_change :=
      NEW."text" IS DISTINCT FROM OLD."text"
      OR NEW."success_criteria" IS DISTINCT FROM OLD."success_criteria"
      OR NEW."root_constraints" IS DISTINCT FROM OLD."root_constraints"
      OR NEW."mutation_policy" IS DISTINCT FROM OLD."mutation_policy";
    base_revision := OLD."objective_revision";
    change_rationale := 'Goal changed by a rolling-compatible writer';
  END IF;
  IF NOT semantic_change THEN
    RETURN NEW;
  END IF;

  change_kind := COALESCE(
    NULLIF(current_setting('opengeni.goal_change_kind', true), ''),
    change_kind
  );
  change_rationale := COALESCE(
    NULLIF(current_setting('opengeni.goal_change_rationale', true), ''),
    change_rationale
  );
  change_actor := COALESCE(
    NULLIF(current_setting('opengeni.goal_change_actor', true), ''),
    CASE
      WHEN NEW."created_by" = 'scheduled_task' THEN 'scheduled_task'
      WHEN NEW."created_by" = 'agent' THEN 'agent'
      ELSE 'api'
    END
  );
  change_turn_id := NULLIF(
    current_setting('opengeni.goal_change_turn_id', true), ''
  )::uuid;
  change_attempt_id := NULLIF(
    current_setting('opengeni.goal_change_attempt_id', true), ''
  )::uuid;
  source_proposal_id := NULLIF(
    current_setting('opengeni.goal_change_proposal_id', true), ''
  )::uuid;
  rollback_revision_id := NULLIF(
    current_setting('opengeni.goal_change_rollback_of_revision_id', true), ''
  )::uuid;

  INSERT INTO "session_goal_revisions" (
    "account_id", "workspace_id", "session_id", "goal_id", "disposition",
    "change_kind", "base_objective_revision", "result_objective_revision",
    "text", "success_criteria", "root_constraints", "mutation_policy",
    "rationale", "actor", "actor_turn_id", "actor_attempt_id", "proposal_id",
    "rollback_of_revision_id", "created_at"
  ) VALUES (
    NEW."account_id", NEW."workspace_id", NEW."session_id", NEW."id",
    'applied', change_kind, base_revision, NEW."objective_revision", NEW."text",
    NEW."success_criteria", NEW."root_constraints", NEW."mutation_policy",
    change_rationale, change_actor, change_turn_id, change_attempt_id,
    source_proposal_id, rollback_revision_id, now()
  )
  ON CONFLICT ("workspace_id", "goal_id", "result_objective_revision")
    WHERE "disposition" = 'applied'
    DO NOTHING;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_revision_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  semantic_change boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF octet_length(NEW."text") > 8192 THEN
      RAISE EXCEPTION 'goal text exceeds 8192 UTF-8 bytes'
        USING ERRCODE = '22001';
    END IF;
    IF NEW."success_criteria" IS NOT NULL
      AND octet_length(NEW."success_criteria") > 8192 THEN
      RAISE EXCEPTION 'goal success criteria exceeds 8192 UTF-8 bytes'
        USING ERRCODE = '22001';
    END IF;
    IF NEW."objective_revision" <> 1 THEN
      RAISE EXCEPTION 'a new goal must start at objective revision 1'
        USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  semantic_change :=
    NEW."text" IS DISTINCT FROM OLD."text"
    OR NEW."success_criteria" IS DISTINCT FROM OLD."success_criteria"
    OR NEW."root_constraints" IS DISTINCT FROM OLD."root_constraints"
    OR NEW."mutation_policy" IS DISTINCT FROM OLD."mutation_policy";

  IF semantic_change THEN
    IF octet_length(NEW."text") > 8192 THEN
      RAISE EXCEPTION 'goal text exceeds 8192 UTF-8 bytes'
        USING ERRCODE = '22001';
    END IF;
    IF NEW."success_criteria" IS NOT NULL
      AND octet_length(NEW."success_criteria") > 8192 THEN
      RAISE EXCEPTION 'goal success criteria exceeds 8192 UTF-8 bytes'
        USING ERRCODE = '22001';
    END IF;
    IF NEW."objective_revision" = OLD."objective_revision" THEN
      NEW."objective_revision" := OLD."objective_revision" + 1;
    ELSIF NEW."objective_revision" <> OLD."objective_revision" + 1 THEN
      RAISE EXCEPTION 'goal objective revision must advance exactly once'
        USING ERRCODE = '40001';
    END IF;
  ELSIF NEW."objective_revision" <> OLD."objective_revision" THEN
    RAISE EXCEPTION 'goal objective revision changed without semantic content'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_revision_bound_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF octet_length(NEW."text") > 8192 THEN
    RAISE EXCEPTION 'goal text exceeds 8192 UTF-8 bytes'
      USING ERRCODE = '22001';
  END IF;
  IF NEW."success_criteria" IS NOT NULL
    AND octet_length(NEW."success_criteria") > 8192 THEN
    RAISE EXCEPTION 'goal success criteria exceeds 8192 UTF-8 bytes'
      USING ERRCODE = '22001';
  END IF;
  IF octet_length(NEW."rationale") > 2048 THEN
    RAISE EXCEPTION 'goal rationale exceeds 2048 UTF-8 bytes'
      USING ERRCODE = '22001';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION session_goal_revision_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Parent lifecycle deletion is the sole mutation exception. PostgreSQL's
  -- cascading constraint trigger runs only after its parent row is absent;
  -- require both nested trigger context and one missing ownership edge so
  -- direct or unrelated-trigger deletes remain fail-closed.
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND (
      NOT EXISTS (SELECT 1 FROM "managed_accounts" WHERE "id" = OLD."account_id")
      OR NOT EXISTS (SELECT 1 FROM "workspaces" WHERE "id" = OLD."workspace_id")
      OR NOT EXISTS (SELECT 1 FROM "sessions" WHERE "id" = OLD."session_id")
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'session goal revisions are immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION session_private_actor_visible(p_account_id uuid, p_workspace_id uuid, p_owner_organization_membership_id uuid, p_owner_subject_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      actor_subject_id text := nullif(
        pg_catalog.current_setting('opengeni.subject_id', true), ''
      );
      initiating_human_subject_id text := nullif(
        pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''
      );
      previous_lifecycle_marker text := pg_catalog.current_setting(
        'opengeni.organization_tenancy_lifecycle', true
      );
      visible boolean := false;
    BEGIN
      IF p_account_id IS NULL
        OR p_workspace_id IS NULL
        OR p_owner_organization_membership_id IS NULL
        OR p_owner_subject_id IS NULL
        OR (
          actor_subject_id IS DISTINCT FROM p_owner_subject_id
          AND initiating_human_subject_id IS DISTINCT FROM p_owner_subject_id
        )
      THEN
        RETURN false;
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        'session_visibility_activation',
        true
      );
      SELECT EXISTS (
        SELECT 1
        FROM organization_memberships membership
        WHERE membership.account_id = p_account_id
          AND membership.id = p_owner_organization_membership_id
          AND membership.subject_id = p_owner_subject_id
          AND membership.status = 'active'
          AND (
            membership.personal_workspace_id = p_workspace_id
            OR EXISTS (
              SELECT 1
              FROM workspace_memberships workspace_membership
              WHERE workspace_membership.account_id = p_account_id
                AND workspace_membership.workspace_id = p_workspace_id
                AND workspace_membership.subject_id = p_owner_subject_id
            )
          )
      ) INTO visible;
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        CASE WHEN previous_lifecycle_marker IS NULL THEN '' ELSE previous_lifecycle_marker END,
        true
      );
      RETURN visible;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        CASE WHEN previous_lifecycle_marker IS NULL THEN '' ELSE previous_lifecycle_marker END,
        true
      );
      RAISE;
    END;
    $$;

CREATE FUNCTION session_private_actor_visible_keys() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
    DECLARE
      actor_subject_id text := nullif(
        pg_catalog.current_setting('opengeni.subject_id', true), ''
      );
      initiating_human_subject_id text := nullif(
        pg_catalog.current_setting('opengeni.initiating_human_subject_id', true), ''
      );
      current_account_id uuid := nullif(
        pg_catalog.current_setting('opengeni.account_id', true), ''
      )::uuid;
      current_workspace_id uuid := nullif(
        pg_catalog.current_setting('opengeni.workspace_id', true), ''
      )::uuid;
      previous_lifecycle_marker text := pg_catalog.current_setting(
        'opengeni.organization_tenancy_lifecycle', true
      );
      keys text[];
    BEGIN
      IF current_account_id IS NULL
        OR current_workspace_id IS NULL
        OR (actor_subject_id IS NULL AND initiating_human_subject_id IS NULL)
      THEN
        RETURN '{}'::text[];
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        'session_visibility_activation',
        true
      );
      SELECT coalesce(
        pg_catalog.array_agg(membership.id::text || ':' || membership.subject_id),
        '{}'::text[]
      )
      INTO keys
      FROM organization_memberships membership
      WHERE membership.account_id = current_account_id
        AND membership.subject_id IN (actor_subject_id, initiating_human_subject_id)
        AND membership.status = 'active'
        AND (
          membership.personal_workspace_id = current_workspace_id
          OR EXISTS (
            SELECT 1
            FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = current_account_id
              AND workspace_membership.workspace_id = current_workspace_id
              AND workspace_membership.subject_id = membership.subject_id
          )
        );
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        CASE WHEN previous_lifecycle_marker IS NULL THEN '' ELSE previous_lifecycle_marker END,
        true
      );
      RETURN keys;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.organization_tenancy_lifecycle',
        CASE WHEN previous_lifecycle_marker IS NULL THEN '' ELSE previous_lifecycle_marker END,
        true
      );
      RAISE;
    END;
    $$;

CREATE FUNCTION session_private_transition_blocker(p_account_id uuid, p_workspace_id uuid, p_session_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM session_turns WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id
      AND status IN ('queued','running','requires_action','recovering','waiting_capacity'))
  THEN RETURN 'nonterminal_turn';
  ELSIF EXISTS (SELECT 1 FROM session_turn_attempts WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id AND state <> 'closed')
  THEN RETURN 'nonterminal_attempt';
  ELSIF EXISTS (SELECT 1 FROM session_attempt_interruptions WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id AND state IN ('pending','delivered','acknowledged'))
  THEN RETURN 'unsettled_interruption';
  ELSIF EXISTS (SELECT 1 FROM session_system_updates pending_update
      JOIN sessions update_owner ON update_owner.id = pending_update.session_id
      WHERE pending_update.workspace_id = p_workspace_id
        AND pending_update.session_id = p_session_id AND pending_update.state = 'pending'
        AND session_system_update_carries_foreign_authority(pending_update,
          update_owner.owner_subject_id, update_owner.owner_organization_membership_id))
  THEN RETURN 'pending_system_update';
  ELSIF EXISTS (SELECT 1 FROM session_human_input_requests request
      WHERE request.workspace_id = p_workspace_id
        AND request.session_id = p_session_id AND request.status = 'pending'
        AND NOT EXISTS (SELECT 1 FROM session_turns request_turn
          WHERE request_turn.workspace_id = request.workspace_id
            AND request_turn.id = request.turn_id
            AND request_turn.status IN (
              'completed','failed','cancelled','superseded','withdrawn_for_edit')))
  THEN RETURN 'pending_human_input';
  ELSIF EXISTS (SELECT 1 FROM session_pending_tool_calls pending
      WHERE pending.workspace_id = p_workspace_id
        AND pending.session_id = p_session_id
        AND (EXISTS (SELECT 1 FROM session_turns owner_turn
            WHERE owner_turn.workspace_id = pending.workspace_id
              AND owner_turn.id = pending.turn_id
              AND owner_turn.status NOT IN (
                'completed','failed','cancelled','superseded','withdrawn_for_edit'))
          OR EXISTS (SELECT 1 FROM session_turn_attempts owner_attempt
            WHERE owner_attempt.workspace_id = pending.workspace_id
              AND owner_attempt.id = pending.attempt_id
              AND owner_attempt.state <> 'closed')))
  THEN RETURN 'pending_tool_receipt';
  ELSIF EXISTS (SELECT 1 FROM agent_run_states run_state
      WHERE run_state.workspace_id = p_workspace_id
        AND run_state.session_id = p_session_id
        AND NOT EXISTS (SELECT 1 FROM session_turns state_turn
          WHERE state_turn.workspace_id = run_state.workspace_id
            AND state_turn.id = run_state.turn_id
            AND state_turn.status IN (
              'completed','failed','cancelled','superseded','withdrawn_for_edit')))
  THEN RETURN 'run_state';
  ELSIF EXISTS (SELECT 1 FROM session_goals WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id AND status = 'active')
  THEN RETURN 'active_goal';
  ELSIF EXISTS (SELECT 1 FROM session_realtime_modes WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id AND state = 'active')
    OR EXISTS (SELECT 1 FROM session_realtime_connections WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id
      AND state IN ('negotiating','ready','active'))
  THEN RETURN 'active_realtime';
  END IF;
  RETURN NULL;
END
$$;

CREATE FUNCTION session_reference_visible(p_account_id uuid, p_workspace_id uuid, p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
      SELECT p_session_id IS NULL OR EXISTS (
        SELECT 1
        FROM sessions session_row
        WHERE session_row.account_id = p_account_id
          AND session_row.workspace_id = p_workspace_id
          AND session_row.id = p_session_id
      )
    $$;

CREATE FUNCTION session_secrets_view(p_session uuid, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('read');
  context := opengeni_private.vault_context(p_principal);
  result := opengeni_private.vault_session_view_json(context, p_session);
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION session_site_actor_visible(p_site uuid, p_access_root uuid, p_root uuid, p_viewer text, p_owner text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT p_access_root IS NULL
    OR nullif(current_setting('opengeni.subject_id',true),'') IS NULL
    OR p_owner=nullif(current_setting('opengeni.subject_id',true),'')
    OR p_owner=nullif(current_setting('opengeni.initiating_human_subject_id',true),'')
    OR (p_root::text=nullif(current_setting('opengeni.agent_root_session_id',true),'')
      AND (p_access_root=p_root OR p_owner=nullif(current_setting('opengeni.initiating_human_subject_id',true),'')))
    OR (current_setting('opengeni.subject_id',true)='site:'||p_site::text
      AND p_site::text=current_setting('opengeni.site_id',true)
      AND p_viewer=current_setting('opengeni.site_viewer_principal',true))
$$;

CREATE TABLE session_system_updates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    kind text NOT NULL,
    classification text DEFAULT 'info'::text NOT NULL,
    source_id text NOT NULL,
    dedupe_key text NOT NULL,
    summary text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    lineage jsonb DEFAULT '{}'::jsonb NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    delivered_turn_id uuid,
    delivered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    delivered_history_item_id uuid,
    personal_connection_delegations jsonb DEFAULT '[]'::jsonb NOT NULL,
    summary_codec_version integer,
    payload_codec_version integer,
    codex_provider_account_authority_snapshot jsonb DEFAULT '{"scope": "workspace", "version": 1}'::jsonb NOT NULL,
    xai_provider_account_authority_snapshot jsonb DEFAULT '{"scope": "workspace", "version": 1}'::jsonb NOT NULL,
    scheduled_task_run_id uuid,
    mcp_account_bindings jsonb,
    claude_provider_account_authority_snapshot jsonb DEFAULT '{"scope": "workspace", "version": 1}'::jsonb NOT NULL,
    subscription_authority jsonb,
    authority_inserted_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    continued_by_subject_id text,
    continued_at timestamp with time zone,
    CONSTRAINT session_system_updates_claude_authority_snapshot_chk CHECK (claude_provider_account_authority_snapshot_v1_valid(claude_provider_account_authority_snapshot)),
    CONSTRAINT session_system_updates_delivery_history_check CHECK ((((state = 'delivered'::text) AND (delivered_history_item_id IS NOT NULL)) OR ((state <> 'delivered'::text) AND (delivered_history_item_id IS NULL)))),
    CONSTRAINT session_system_updates_mcp_account_bindings_check CHECK (((mcp_account_bindings IS NULL) OR (jsonb_typeof(mcp_account_bindings) = 'array'::text))),
    CONSTRAINT session_system_updates_subscription_authority_v2_chk CHECK (((subscription_authority IS NULL) OR subscription_personal_authority_v2_valid(subscription_authority))),
    CONSTRAINT session_system_updates_xai_authority_snapshot_chk CHECK (xai_provider_account_authority_snapshot_v1_valid(xai_provider_account_authority_snapshot)),
    CONSTRAINT session_updates_codex_authority_snapshot_chk CHECK (codex_provider_account_authority_snapshot_v1_valid(codex_provider_account_authority_snapshot)),
    CONSTRAINT session_updates_personal_delegations_array_chk CHECK (((jsonb_typeof(personal_connection_delegations) = 'array'::text) AND (jsonb_array_length(personal_connection_delegations) <= 128))),
    CONSTRAINT system_updates_classification_check CHECK ((classification = ANY (ARRAY['success'::text, 'failure'::text, 'action_required'::text, 'info'::text]))),
    CONSTRAINT system_updates_kind_check CHECK ((kind = ANY (ARRAY['scheduled_occurrence'::text, 'goal_continuation'::text, 'agent_message'::text, 'agent_steer_instruction'::text, 'session_wait_timeout'::text, 'background_command_result'::text, 'child_terminal_result'::text, 'media_generation_result'::text, 'child_requires_action'::text, 'child_requires_action_resolved'::text, 'child_paused'::text, 'child_waiting_capacity'::text, 'child_progress'::text, 'secret_use_approval_decided'::text, 'capability_setup_completed'::text]))),
    CONSTRAINT system_updates_payload_kind_check CHECK (((payload ->> 'type'::text) = kind)),
    CONSTRAINT system_updates_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'delivered'::text, 'cancelled'::text, 'superseded'::text, 'failed'::text])))
);

ALTER TABLE ONLY session_system_updates FORCE ROW LEVEL SECURITY;

COMMENT ON COLUMN session_system_updates.payload IS 'Canonical machine-input payload; public monitoring projections are separate.';

COMMENT ON COLUMN session_system_updates.codex_provider_account_authority_snapshot IS 'Opaque identifier-free Codex provider-account authority snapshot for an accepted internal update.';

COMMENT ON COLUMN session_system_updates.xai_provider_account_authority_snapshot IS 'Immutable identifier-free xAI provider-account authority snapshot for accepted internal input.';

CREATE FUNCTION session_system_update_carries_foreign_authority(p_update session_system_updates, p_owner_subject_id text, p_owner_membership_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
  SELECT
    -- Personal connection delegations must all be the owner's.
    CASE WHEN jsonb_typeof(p_update.personal_connection_delegations) = 'array'
      THEN EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_update.personal_connection_delegations) delegation
        WHERE delegation ->> 'ownerSubjectId' IS DISTINCT FROM p_owner_subject_id)
      ELSE true END
    -- Account bindings are workspace-scoped or the owner's own.
    OR CASE WHEN p_update.mcp_account_bindings IS NULL THEN false
      WHEN jsonb_typeof(p_update.mcp_account_bindings) = 'array' THEN EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_update.mcp_account_bindings) binding
        WHERE NOT (
          (binding ->> 'subjectScope' = 'workspace' AND binding ->> 'ownerSubjectId' IS NULL)
          OR binding ->> 'ownerSubjectId' = p_owner_subject_id))
      ELSE true END
    -- Personal subscription authority belongs to the owner's membership.
    OR CASE WHEN p_update.subscription_authority IS NULL THEN false
      WHEN jsonb_typeof(p_update.subscription_authority -> 'personal') = 'array' THEN EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_update.subscription_authority -> 'personal') personal
        WHERE personal ->> 'ownerMembershipId' IS DISTINCT FROM p_owner_membership_id::text)
      ELSE true END
    -- Causal authority subjects recorded in the lineage are the owner.
    OR EXISTS (
      SELECT 1 FROM unnest(ARRAY[
        'connectionAuthoritySubjectId', 'xaiAuthoritySubjectId', 'claudeAuthoritySubjectId'
      ]) subject_key
      WHERE p_update.lineage ->> subject_key IS NOT NULL
        AND p_update.lineage ->> subject_key IS DISTINCT FROM p_owner_subject_id)
    -- A user-scoped provider snapshot needs its owner-matching causal subject.
    OR (p_update.xai_provider_account_authority_snapshot ->> 'scope' = 'user'
      AND p_update.lineage ->> 'xaiAuthoritySubjectId' IS NULL)
    OR (p_update.claude_provider_account_authority_snapshot ->> 'scope' = 'user'
      AND p_update.lineage ->> 'claudeAuthoritySubjectId' IS NULL)
    -- The causal human turn the runtime attributes the update to (the same
    -- lineage keys the delivering turn reads) was the owner's or no human's.
    -- A recorded causal turn that cannot be read counts as foreign.
    OR COALESCE((
      SELECT CASE WHEN causal.turn_id !~ '^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$'
          THEN true
        ELSE NOT EXISTS (
          SELECT 1 FROM session_turns causal_turn
          WHERE causal_turn.id = causal.turn_id::uuid
            AND COALESCE(causal_turn.initiating_human_subject_id,
              CASE WHEN causal_turn.initiator_kind = 'subject'
                THEN causal_turn.initiator_subject_id END,
              p_owner_subject_id) = p_owner_subject_id)
        END
      FROM (SELECT CASE
          WHEN p_update.kind IN ('child_terminal_result', 'child_requires_action',
              'child_requires_action_resolved', 'child_paused', 'child_waiting_capacity',
              'child_progress')
            THEN p_update.lineage ->> 'parentTurnId'
          WHEN p_update.kind IN ('goal_continuation', 'background_command_result',
              'session_wait_timeout', 'capability_setup_completed')
            THEN p_update.lineage ->> 'causalTurnId'
          WHEN p_update.kind IN ('agent_message', 'agent_steer_instruction')
            THEN p_update.lineage ->> 'callerTurnId'
        END AS turn_id) causal
      WHERE causal.turn_id IS NOT NULL), false)
$_$;

CREATE FUNCTION session_tenancy_any_product_activation() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  previous_lifecycle text := pg_catalog.current_setting(
    'opengeni.organization_tenancy_lifecycle', true
  );
  activated boolean;
BEGIN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'session_tenancy_greenfield_activation', true
  );
  activated := false;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RETURN activated;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_lifecycle, ''), true
  );
  RAISE;
END
$$;

COMMENT ON FUNCTION session_tenancy_any_product_activation() IS 'Retired by 0611 with OPENGENI_ORGANIZATION_TENANCY_CANONICAL_ACTIVATION_ENABLED. Always false so no binary enforces the removed startup interlock.';

CREATE FUNCTION session_tenancy_fence_owner_policy_active(p_actor text, p_expected_owner text, p_target_schema oid, p_workspace_id uuid, p_inventory boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  lock_key bigint;
BEGIN
  IF p_actor IS DISTINCT FROM p_expected_owner THEN
    RETURN false;
  END IF;
  IF p_inventory THEN
    RETURN opengeni_private.session_tenancy_fence_inventory_capability_active(
      p_target_schema
    );
  END IF;
  IF p_workspace_id IS NULL THEN
    RETURN false;
  END IF;
  IF NOT opengeni_private.session_tenancy_fenced_access_capability_active(
    p_target_schema
  ) THEN
    RETURN false;
  END IF;
  lock_key := pg_catalog.hashtextextended(
    'session-tenancy:' || p_workspace_id::text,
    0
  );
  RETURN EXISTS (
    SELECT 1 FROM pg_catalog.pg_locks held
    WHERE held.locktype = 'advisory'
      AND held.pid = pg_catalog.pg_backend_pid()
      AND held.granted
      AND held.classid = (((lock_key >> 32) & 4294967295)::bigint)::oid
      AND held.objid = ((lock_key & 4294967295)::bigint)::oid
      AND held.objsubid = 1
      AND held.mode IN ('ShareLock', 'ExclusiveLock')
  );
END
$$;

CREATE FUNCTION session_tenancy_fence_target_schema() RETURNS oid
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ SELECT {{schema_oid}}::oid $$;

CREATE FUNCTION session_tenancy_product_activated(p_account_id uuid, p_activation_version integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
  SELECT p_account_id IS NOT DISTINCT FROM
      nullif(current_setting('opengeni.account_id', true), '')::uuid
    AND p_account_id IS NOT NULL
    AND p_activation_version IS NOT DISTINCT FROM 1
$$;

COMMENT ON FUNCTION session_tenancy_product_activated(p_account_id uuid, p_activation_version integer) IS 'Universal since 0611: true for the transaction''s own organization at activation version 1. No per-organization receipt is required.';

CREATE FUNCTION session_tenancy_standing_blocker(p_account_id uuid, p_workspace_id uuid, p_session_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  session_group_id uuid;
BEGIN
  SELECT sandbox_group_id INTO session_group_id FROM sessions
  WHERE account_id = p_account_id AND workspace_id = p_workspace_id
    AND id = p_session_id;

  IF EXISTS (SELECT 1 FROM session_realtime_modes WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id AND state = 'active')
    OR EXISTS (SELECT 1 FROM session_realtime_connections WHERE workspace_id = p_workspace_id
      AND session_id = p_session_id
      AND state IN ('negotiating','ready','active'))
  THEN RETURN 'active_realtime';
  ELSIF EXISTS (SELECT 1 FROM scheduled_tasks task WHERE task.workspace_id = p_workspace_id
      AND task.reusable_session_id = p_session_id AND task.status = 'active'
      AND task.deleted_at IS NULL
      AND NOT scheduled_task_is_exhausted(task.id))
  THEN RETURN 'active_scheduled_task';
  ELSIF EXISTS (SELECT 1 FROM sandbox_workspace_mutation_admissions
      WHERE workspace_id = p_workspace_id AND session_id = p_session_id
        AND settled_at IS NULL)
  THEN RETURN 'workspace_mutation_admission';
  ELSIF EXISTS (SELECT 1 FROM sandbox_retained_processes
      WHERE workspace_id = p_workspace_id AND session_id = p_session_id
        AND state = 'active')
  THEN RETURN 'retained_process';
  ELSIF EXISTS (
      SELECT 1 FROM sandbox_lease_holders holder
      JOIN sandbox_leases lease ON lease.id = holder.lease_id
      WHERE lease.workspace_id = p_workspace_id
        AND lease.sandbox_group_id = session_group_id
        AND holder.kind IN ('viewer', 'interaction')
        AND (holder.subject_id IS NULL OR holder.subject_id = p_session_id)
    )
  THEN RETURN 'active_sandbox_access';
  END IF;
  RETURN NULL;
END
$$;

CREATE FUNCTION session_turn_attempt_propagate_quiescence_hint() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  UPDATE session_attempt_interruptions interruption
  SET attempt_quiesced = true
  WHERE interruption.workspace_id = NEW.workspace_id
    AND interruption.attempt_id = NEW.id
    AND NOT interruption.attempt_quiesced;
  RETURN NULL;
END
$$;

CREATE FUNCTION session_turn_attempts_fill_authority_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      workspace_marker boolean;
      source_epoch integer;
      source_visibility text;
      source_owner uuid;
    BEGIN
      SELECT true
      INTO STRICT workspace_marker
      FROM {{schema}}.workspaces workspace_row
      WHERE workspace_row.id = NEW.workspace_id
        AND workspace_row.account_id = NEW.account_id
      FOR KEY SHARE;

      SELECT
        source.authority_epoch,
        source.visibility,
        source.owner_organization_membership_id
      INTO STRICT source_epoch, source_visibility, source_owner
      FROM {{schema}}.sessions source
      WHERE source.workspace_id = NEW.workspace_id
        AND source.account_id = NEW.account_id
        AND source.id = NEW.session_id
      FOR UPDATE;

      NEW.authority_epoch := source_epoch;
      NEW.authority_visibility := source_visibility;
      NEW.authority_owner_organization_membership_id := source_owner;
      RETURN NEW;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        RAISE EXCEPTION 'session authority snapshot source workspace/session not found: %/%',
          NEW.workspace_id, NEW.session_id
          USING ERRCODE = '23503';
    END;
    $$;

CREATE FUNCTION session_turn_attempts_guard_authority_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF NEW.authority_epoch IS DISTINCT FROM OLD.authority_epoch
        OR NEW.authority_visibility IS DISTINCT FROM OLD.authority_visibility
        OR NEW.authority_owner_organization_membership_id IS DISTINCT FROM OLD.authority_owner_organization_membership_id
      THEN
        RAISE EXCEPTION 'session turn attempt authority snapshot is immutable'
          USING ERRCODE = '23514';
      END IF;
      RETURN NEW;
    END;
    $$;

CREATE FUNCTION session_usage_limit_apply_receipt(p_account uuid, p_workspace uuid, p_root uuid, p_source_id text, p_source_session uuid, p_turn uuid, p_amount bigint, p_pricing_source text, p_model text, p_origin text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  v_status text;
  v_pricing text := CASE WHEN p_pricing_source IN ('configured_list_price','gateway_reported')
    THEN p_pricing_source END;
  v_amount bigint := CASE WHEN p_amount BETWEEN 0 AND 9007199254740991 THEN p_amount END;
  v_model text := CASE WHEN octet_length(p_model) BETWEEN 1 AND 512 THEN p_model END;
  existing opengeni_private.session_usage_limit_receipts%ROWTYPE;
BEGIN
  IF p_source_id IS NULL OR octet_length(p_source_id) NOT BETWEEN 1 AND 1100 THEN
    RAISE EXCEPTION 'invalid session usage source' USING ERRCODE='22023';
  END IF;
  v_status := CASE WHEN v_amount IS NULL OR v_pricing IS NULL THEN 'unpriced'
    WHEN v_amount = 0 THEN 'free' ELSE 'priced' END;
  INSERT INTO opengeni_private.session_usage_limit_receipts(account_id,workspace_id,root_session_id,
    source_id,source_session_id,turn_id,status,amount_micros,pricing_source,model,origin)
  VALUES (p_account,p_workspace,p_root,p_source_id,p_source_session,p_turn,v_status,
    CASE WHEN v_status='unpriced' THEN NULL ELSE v_amount END,
    CASE WHEN v_status='unpriced' THEN NULL ELSE v_pricing END,
    v_model,p_origin)
  ON CONFLICT (workspace_id, source_id) DO NOTHING;
  IF FOUND THEN
    UPDATE opengeni_private.session_usage_limit_roots SET
      known_micros = known_micros + coalesce(CASE WHEN v_status='unpriced' THEN 0 ELSE v_amount END,0),
      priced_calls = priced_calls + (v_status='priced')::int,
      free_calls = free_calls + (v_status='free')::int,
      unpriced_calls = unpriced_calls + (v_status='unpriced')::int,
      usage_revision = usage_revision + 1, updated_at = clock_timestamp()
    WHERE workspace_id = p_workspace AND root_session_id = p_root;
    RETURN 'recorded';
  END IF;
  SELECT * INTO existing FROM opengeni_private.session_usage_limit_receipts
    WHERE workspace_id = p_workspace AND source_id = p_source_id;
  IF existing.root_session_id IS DISTINCT FROM p_root THEN
    -- Root lineage is immutable; a different root for one producer identity
    -- is never redirected or double-counted.
    UPDATE opengeni_private.session_usage_limit_roots SET conflict_count = conflict_count + 1
      WHERE workspace_id = p_workspace AND root_session_id = p_root;
    RETURN 'conflict';
  END IF;
  IF existing.status = 'pending' THEN
    -- The custody marker opened before dispatch: fill it exactly once.
    UPDATE opengeni_private.session_usage_limit_receipts SET status = v_status,
      amount_micros = CASE WHEN v_status='unpriced' THEN NULL ELSE v_amount END,
      pricing_source = CASE WHEN v_status='unpriced' THEN NULL ELSE v_pricing END,
      model = coalesce(v_model, existing.model), turn_id = coalesce(p_turn, existing.turn_id),
      origin = p_origin, fenced = false, recorded_at = clock_timestamp()
    WHERE workspace_id = p_workspace AND source_id = p_source_id;
    UPDATE opengeni_private.session_usage_limit_roots SET
      known_micros = known_micros + coalesce(CASE WHEN v_status='unpriced' THEN 0 ELSE v_amount END,0),
      priced_calls = priced_calls + (v_status='priced')::int,
      free_calls = free_calls + (v_status='free')::int,
      unpriced_calls = unpriced_calls + (v_status='unpriced')::int,
      usage_revision = usage_revision + 1, updated_at = clock_timestamp()
    WHERE workspace_id = p_workspace AND root_session_id = p_root;
    RETURN 'recorded';
  END IF;
  IF existing.status = v_status AND existing.amount_micros IS NOT DISTINCT FROM
    (CASE WHEN v_status='unpriced' THEN NULL ELSE v_amount END) THEN
    RETURN 'duplicate';
  END IF;
  IF v_status = 'unpriced' THEN
    -- A known amount is never replaced by a later unknown observation.
    RETURN 'duplicate';
  END IF;
  IF existing.status = 'unpriced' THEN
    UPDATE opengeni_private.session_usage_limit_receipts SET status = v_status,
      amount_micros = v_amount, pricing_source = v_pricing
    WHERE workspace_id = p_workspace AND source_id = p_source_id;
    UPDATE opengeni_private.session_usage_limit_roots SET
      known_micros = known_micros + v_amount,
      priced_calls = priced_calls + (v_status='priced')::int,
      free_calls = free_calls + (v_status='free')::int,
      unpriced_calls = unpriced_calls - 1,
      usage_revision = usage_revision + 1, updated_at = clock_timestamp()
    WHERE workspace_id = p_workspace AND root_session_id = p_root;
    RETURN 'filled';
  END IF;
  UPDATE opengeni_private.session_usage_limit_roots SET conflict_count = conflict_count + 1
    WHERE workspace_id = p_workspace AND root_session_id = p_root;
  RETURN 'conflict';
END $$;

CREATE FUNCTION session_usage_limit_capability_active(p_account uuid, p_workspace uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM opengeni_private.session_usage_limit_capabilities c
    WHERE c.backend_pid = pg_backend_pid()
      AND c.transaction_id = pg_current_xact_id_if_assigned()
      AND c.data_schema = (SELECT n.nspname FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace
        WHERE t.oid='workspaces'::regclass)
      AND ((c.account_id = p_account AND c.workspace_id = p_workspace)
        OR (p_account IS NULL AND p_workspace IS NULL
          AND c.account_id='00000000-0000-0000-0000-000000000000'::uuid
          AND c.workspace_id='00000000-0000-0000-0000-000000000000'::uuid)))
$$;

CREATE FUNCTION session_usage_limit_command(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  a uuid := (p_input->>'accountId')::uuid;
  w uuid := (p_input->>'workspaceId')::uuid;
  action text := p_input->>'action';
  v_session uuid := (p_input->>'sessionId')::uuid;
  v_root uuid;
  root_row opengeni_private.session_usage_limit_roots%ROWTYPE;
  prior_receipt opengeni_private.session_usage_limit_config_receipts%ROWTYPE;
  opened integer;
  v_limit bigint;
  v_previous bigint;
  v_expected bigint;
  v_outcome text;
  previous_subject text;
  v_runtime boolean;
  v_fenced boolean := false;
  v_opened boolean := false;
  v_state jsonb;
  result jsonb;
  v_data_schema text := (SELECT n.nspname FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace
    WHERE t.oid='workspaces'::regclass);
BEGIN
  IF a IS NULL OR w IS NULL OR v_session IS NULL
    OR opengeni_private.workspace_rls_visible(a, w) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'session usage limit scope denied' USING ERRCODE = '42501';
  END IF;
  IF action NOT IN ('read','set','settle','fence','release') THEN
    RAISE EXCEPTION 'unknown session usage limit action' USING ERRCODE = '22023';
  END IF;
  v_runtime := action IN ('settle','fence','release')
    OR (action = 'read' AND coalesce((p_input->>'runtime')::boolean, false));
  -- People: visibility under the caller's own policies (workspace and
  -- private-session). Runtime: tenant-bounded, private visibility cleared.
  IF v_runtime THEN
    previous_subject := current_setting('opengeni.subject_id', true);
    PERFORM set_config('opengeni.subject_id', '', true);
  END IF;
  SELECT s.root_session_id INTO v_root FROM sessions s
    WHERE s.id = v_session AND s.workspace_id = w AND s.account_id = a;
  IF v_runtime THEN
    PERFORM set_config('opengeni.subject_id', coalesce(previous_subject, ''), true);
  END IF;
  IF v_root IS NULL THEN
    RETURN jsonb_build_object('outcome', CASE WHEN action IN ('settle','fence','release') THEN 'source_gone'
      ELSE 'not_found' END);
  END IF;
  IF action = 'set' AND v_root <> v_session THEN
    RETURN jsonb_build_object('outcome','not_root','rootSessionId',v_root);
  END IF;
  opened := 0;
  IF action <> 'read' OR coalesce((p_input->>'prepare')::boolean,false)
    OR p_input ? 'openSourceId' THEN
  INSERT INTO opengeni_private.session_usage_limit_capabilities
    VALUES (pg_backend_pid(), pg_current_xact_id(), v_data_schema, a, w)
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS opened = ROW_COUNT;
  END IF;
  IF action = 'fence' THEN
    -- The owner of a custody marker could not fill it: block the task tree
    -- now instead of only after the overdue window.
    UPDATE opengeni_private.session_usage_limit_receipts SET fenced = true
      WHERE workspace_id = w AND root_session_id = v_root AND source_id = p_input->>'sourceId'
        AND status = 'pending';
    result := jsonb_build_object('outcome', CASE WHEN FOUND THEN 'fenced' ELSE 'not_pending' END);
    IF opened = 1 THEN
      DELETE FROM opengeni_private.session_usage_limit_capabilities WHERE backend_pid=pg_backend_pid()
        AND transaction_id=pg_current_xact_id_if_assigned() AND data_schema=v_data_schema
        AND workspace_id=w;
    END IF;
    RETURN result;
  END IF;
  IF action = 'release' THEN
    DELETE FROM opengeni_private.session_usage_limit_receipts
      WHERE workspace_id = w AND root_session_id = v_root AND source_id = p_input->>'sourceId'
        AND status = 'pending' AND NOT fenced;
    result := jsonb_build_object('outcome', CASE WHEN FOUND THEN 'released' ELSE 'not_pending' END);
    IF opened = 1 THEN
      DELETE FROM opengeni_private.session_usage_limit_capabilities WHERE backend_pid=pg_backend_pid()
        AND transaction_id=pg_current_xact_id_if_assigned() AND data_schema=v_data_schema
        AND workspace_id=w;
    END IF;
    RETURN result;
  END IF;
  IF action = 'read' AND NOT coalesce((p_input->>'prepare')::boolean, false) THEN
    -- Hot admission read: one indexed row, no lock, no event scan.
    SELECT * INTO root_row FROM opengeni_private.session_usage_limit_roots
      WHERE workspace_id = w AND root_session_id = v_root;
  END IF;
  IF root_row.root_session_id IS NULL THEN
    IF opened=0 THEN
  INSERT INTO opengeni_private.session_usage_limit_capabilities
    VALUES (pg_backend_pid(), pg_current_xact_id(), v_data_schema, a, w)
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS opened = ROW_COUNT;
    END IF;
    -- Roots created before this feature are initialized lazily and imported.
    INSERT INTO opengeni_private.session_usage_limit_roots(account_id,workspace_id,root_session_id,
      history_state,import_next_at)
    SELECT a, w, v_root, 'preparing', clock_timestamp()
    WHERE EXISTS (SELECT 1 FROM sessions s WHERE s.id = v_root AND s.workspace_id = w)
    ON CONFLICT (workspace_id, root_session_id) DO NOTHING;
    SELECT * INTO root_row FROM opengeni_private.session_usage_limit_roots
      WHERE workspace_id = w AND root_session_id = v_root FOR NO KEY UPDATE;
    IF root_row.root_session_id IS NULL THEN
      IF opened = 1 THEN
        DELETE FROM opengeni_private.session_usage_limit_capabilities WHERE backend_pid=pg_backend_pid()
          AND transaction_id=pg_current_xact_id_if_assigned() AND data_schema=v_data_schema
          AND workspace_id=w;
      END IF;
      RETURN jsonb_build_object('outcome', CASE WHEN action='settle' THEN 'source_gone' ELSE 'not_found' END);
    END IF;
    IF root_row.history_state = 'preparing' AND coalesce((p_input->>'prepare')::boolean, false) THEN
      -- The content-free import counts every tree session, including private
      -- sessions the caller cannot open; the caller only ever sees the total.
      previous_subject := current_setting('opengeni.subject_id', true);
      PERFORM set_config('opengeni.subject_id', '', true);
      PERFORM session_usage_limit_import_step(a, w, v_root, 500);
      PERFORM set_config('opengeni.subject_id', coalesce(previous_subject, ''), true);
      SELECT * INTO root_row FROM opengeni_private.session_usage_limit_roots
        WHERE workspace_id = w AND root_session_id = v_root;
    END IF;
  END IF;

  IF action = 'read' THEN
    v_fenced := EXISTS (SELECT 1 FROM opengeni_private.session_usage_limit_receipts r
      WHERE r.workspace_id = w AND r.root_session_id = v_root AND r.status = 'pending'
        AND (r.fenced OR r.recorded_at < clock_timestamp() - interval '15 minutes'));
    v_state := session_usage_limit_state(to_jsonb(root_row), v_root <> v_session);
    IF v_fenced THEN v_state := v_state || jsonb_build_object('coverage','partial'); END IF;
    IF p_input ? 'openSourceId' AND v_runtime AND NOT v_fenced
      AND (root_row.limit_micros IS NULL OR root_row.history_state = 'preparing'
        OR root_row.known_micros < root_row.limit_micros) THEN
      IF octet_length(coalesce(p_input->>'openSourceId','')) NOT BETWEEN 1 AND 1100 THEN
        RAISE EXCEPTION 'invalid session usage source' USING ERRCODE = '22023';
      END IF;
      INSERT INTO opengeni_private.session_usage_limit_receipts(account_id,workspace_id,
        root_session_id,source_id,source_session_id,status,origin)
      VALUES (a, w, v_root, p_input->>'openSourceId', v_session, 'pending', 'live')
      ON CONFLICT (workspace_id, source_id) DO NOTHING;
      v_opened := true;
    END IF;
    result := jsonb_build_object('outcome','ok','state', v_state,'fenced', v_fenced,
      'opened', v_opened);
  ELSIF action = 'settle' THEN
    v_outcome := session_usage_limit_apply_receipt(a, w, v_root,
      p_input->>'sourceId', v_session, nullif(p_input->>'turnId','')::uuid,
      CASE WHEN jsonb_typeof(p_input->'amountMicros') = 'number'
        THEN (p_input->>'amountMicros')::bigint END,
      p_input->>'pricingSource', p_input->>'model', 'live');
    SELECT * INTO root_row FROM opengeni_private.session_usage_limit_roots
      WHERE workspace_id = w AND root_session_id = v_root;
    result := jsonb_build_object('outcome', v_outcome,
      'state', session_usage_limit_state(to_jsonb(root_row), v_root <> v_session));
  ELSE
    IF p_input->>'actorType' NOT IN ('human','host')
      OR octet_length(coalesce(p_input->>'actorSubjectId','')) NOT BETWEEN 1 AND 1024
      OR octet_length(coalesce(p_input->>'operationId','')) NOT BETWEEN 1 AND 256
      OR jsonb_typeof(p_input->'expectedVersion') <> 'number'
      OR (p_input->'limitMicros' <> 'null'::jsonb AND jsonb_typeof(p_input->'limitMicros') <> 'number') THEN
      RAISE EXCEPTION 'invalid session usage limit write' USING ERRCODE = '22023';
    END IF;
    v_limit := CASE WHEN p_input->'limitMicros' = 'null'::jsonb THEN NULL
      ELSE (p_input->>'limitMicros')::bigint END;
    v_expected := (p_input->>'expectedVersion')::bigint;
    IF v_limit IS NOT NULL AND (v_limit < 0 OR v_limit > 10000000000000) THEN
      RAISE EXCEPTION 'invalid session usage limit' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO root_row FROM opengeni_private.session_usage_limit_roots
      WHERE workspace_id = w AND root_session_id = v_root FOR NO KEY UPDATE;
    SELECT * INTO prior_receipt FROM opengeni_private.session_usage_limit_config_receipts
      WHERE workspace_id = w AND root_session_id = v_root AND operation_id = p_input->>'operationId';
    IF FOUND THEN
      IF prior_receipt.expected_version <> v_expected
        OR prior_receipt.limit_micros IS DISTINCT FROM v_limit THEN
        result := jsonb_build_object('outcome','operation_conflict',
          'state', session_usage_limit_state(to_jsonb(root_row), false));
      ELSE
        -- An exact replay returns the operation's committed configuration
        -- (its limit and resulting version), not a later change; usage stays
        -- live and separately versioned by usageRevision.
        root_row.limit_micros := prior_receipt.limit_micros;
        root_row.config_version := prior_receipt.result_version;
        result := jsonb_build_object('outcome','replayed','resultVersion',prior_receipt.result_version,
          'previousLimitMicros', prior_receipt.previous_limit_micros,
          'state', session_usage_limit_state(to_jsonb(root_row), false));
      END IF;
    ELSIF root_row.config_version <> v_expected THEN
      result := jsonb_build_object('outcome','conflict','state', session_usage_limit_state(to_jsonb(root_row), false));
    ELSIF v_limit IS NOT NULL AND root_row.history_state = 'preparing' THEN
      result := jsonb_build_object('outcome','preparing','state', session_usage_limit_state(to_jsonb(root_row), false));
    ELSIF v_limit IS NOT NULL AND coalesce((p_input->>'producerEnabled')::boolean, false) IS NOT TRUE THEN
      result := jsonb_build_object('outcome','disabled','state', session_usage_limit_state(to_jsonb(root_row), false));
    ELSE
      v_previous := root_row.limit_micros;
      UPDATE opengeni_private.session_usage_limit_roots SET limit_micros = v_limit,
        config_version = config_version + 1, updated_at = clock_timestamp()
      WHERE workspace_id = w AND root_session_id = v_root
      RETURNING * INTO root_row;
      INSERT INTO opengeni_private.session_usage_limit_config_receipts(account_id,workspace_id,
        root_session_id,operation_id,expected_version,previous_limit_micros,limit_micros,result_version,
        actor_subject_id,actor_type)
      VALUES (a, w, v_root, p_input->>'operationId', v_expected,
        v_previous, v_limit,
        root_row.config_version, p_input->>'actorSubjectId', p_input->>'actorType');
      result := jsonb_build_object('outcome','ok','previousLimitMicros', v_previous,
        'state', session_usage_limit_state(to_jsonb(root_row), false));
    END IF;
    result := result || jsonb_build_object('rootSessionId', v_root);
  END IF;
  IF opened = 1 THEN
    DELETE FROM opengeni_private.session_usage_limit_capabilities WHERE backend_pid=pg_backend_pid()
      AND transaction_id=pg_current_xact_id_if_assigned() AND data_schema=v_data_schema
      AND workspace_id=w;
  END IF;
  RETURN result;
END $$;

CREATE FUNCTION session_usage_limit_event_amount(p_payload jsonb) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
  SELECT session_usage_limit_meter_amount(
    CASE WHEN jsonb_typeof(p_payload->'estimatedProviderCostMicros') = 'number'
      AND (p_payload->>'estimatedProviderCostMicros') ~ '^[0-9]{1,16}$'
      THEN (p_payload->>'estimatedProviderCostMicros')::numeric END,
    p_payload->>'pricingSource',
    CASE WHEN jsonb_typeof(p_payload->'inputTokens') = 'number'
      AND (p_payload->>'inputTokens') ~ '^[0-9]{1,15}$' THEN (p_payload->>'inputTokens')::numeric END,
    CASE WHEN jsonb_typeof(p_payload->'outputTokens') = 'number'
      AND (p_payload->>'outputTokens') ~ '^[0-9]{1,15}$' THEN (p_payload->>'outputTokens')::numeric END)
$_$;

CREATE FUNCTION session_usage_limit_import_page(p_account uuid, p_workspace uuid, p_root uuid, p_budget integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  cur jsonb; v_session uuid; v_after uuid; v_phase text; v_fact_at timestamptz; v_fact_id uuid;
  v_seq bigint; budget integer := greatest(1, least(coalesce(p_budget, 500), 2000));
  fetched integer; row_fact record; row_event record; imported integer := 0; v_amount bigint;
  v_pricing text; v_outcome text;
BEGIN
  SELECT import_cursor INTO cur FROM opengeni_private.session_usage_limit_roots
    WHERE workspace_id = p_workspace AND root_session_id = p_root;
  cur := coalesce(cur, '{}'::jsonb);
  v_session := nullif(cur->>'session','')::uuid;
  v_after := nullif(cur->>'after','')::uuid;
  v_phase := coalesce(cur->>'phase','facts');
  v_fact_at := coalesce(nullif(cur->>'factAt','')::timestamptz, '-infinity'::timestamptz);
  v_fact_id := coalesce(nullif(cur->>'factId','')::uuid, '00000000-0000-0000-0000-000000000000'::uuid);
  v_seq := coalesce(nullif(cur->>'seq','')::bigint, 0);
  LOOP
    IF v_session IS NULL THEN
      SELECT s.id INTO v_session FROM sessions s
        WHERE s.workspace_id = p_workspace AND s.account_id = p_account AND s.root_session_id = p_root
          AND (v_after IS NULL OR s.id > v_after)
        ORDER BY s.id LIMIT 1;
      IF v_session IS NULL THEN
        UPDATE opengeni_private.session_usage_limit_roots SET import_cursor = NULL,
          import_imported = import_imported + imported
        WHERE workspace_id = p_workspace AND root_session_id = p_root;
        RETURN true;
      END IF;
      v_phase := 'facts'; v_fact_at := '-infinity'; v_fact_id := '00000000-0000-0000-0000-000000000000';
      v_seq := 0;
    END IF;
    IF v_phase = 'facts' THEN
      fetched := 0;
      FOR row_fact IN SELECT f.id, f.occurred_at, f.turn_id, f.source_key, f.model,
          f.estimated_provider_cost_micros, f.pricing_source, f.input_tokens, f.output_tokens
        FROM model_call_facts f
        WHERE f.workspace_id = p_workspace AND f.session_id = v_session
          AND (f.occurred_at, f.id) > (v_fact_at, v_fact_id)
        ORDER BY f.occurred_at, f.id LIMIT budget
      LOOP
        fetched := fetched + 1;
        v_outcome := session_usage_limit_apply_receipt(p_account, p_workspace, p_root,
          CASE WHEN row_fact.turn_id IS NOT NULL
              AND octet_length(row_fact.source_key) BETWEEN 1 AND 1024
            THEN row_fact.turn_id::text || ':' || row_fact.source_key
            ELSE 'fact:' || row_fact.id::text END,
          v_session, row_fact.turn_id,
          session_usage_limit_meter_amount(row_fact.estimated_provider_cost_micros,
            row_fact.pricing_source, row_fact.input_tokens, row_fact.output_tokens),
          row_fact.pricing_source, row_fact.model, 'legacy');
        IF v_outcome IN ('recorded','filled') THEN imported := imported + 1; END IF;
        v_fact_at := row_fact.occurred_at; v_fact_id := row_fact.id;
      END LOOP;
      budget := budget - fetched;
      IF budget > 0 THEN v_phase := 'events'; v_seq := 0; END IF;
    END IF;
    IF v_phase = 'events' AND budget > 0 THEN
      fetched := 0;
      FOR row_event IN SELECT e.sequence, e.turn_id, e.payload
        FROM session_events e
        WHERE e.workspace_id = p_workspace AND e.session_id = v_session
          AND e.type = 'agent.model.usage' AND e.sequence > v_seq
        ORDER BY e.sequence LIMIT budget
      LOOP
        fetched := fetched + 1;
        v_seq := row_event.sequence;
        -- Malformed or unattributable events are skipped, never valued.
        CONTINUE WHEN row_event.turn_id IS NULL
          OR jsonb_typeof(row_event.payload) IS DISTINCT FROM 'object'
          OR jsonb_typeof(row_event.payload->'sourceKey') IS DISTINCT FROM 'string'
          OR octet_length(row_event.payload->>'sourceKey') NOT BETWEEN 1 AND 1024;
        v_pricing := row_event.payload->>'pricingSource';
        v_amount := session_usage_limit_event_amount(row_event.payload);
        v_outcome := session_usage_limit_apply_receipt(p_account, p_workspace, p_root,
          row_event.turn_id::text || ':' || (row_event.payload->>'sourceKey'), v_session,
          row_event.turn_id, v_amount, v_pricing,
          CASE WHEN jsonb_typeof(row_event.payload->'model') = 'string'
            THEN row_event.payload->>'model' END, 'legacy');
        IF v_outcome IN ('recorded','filled') THEN imported := imported + 1; END IF;
      END LOOP;
      budget := budget - fetched;
      IF budget > 0 THEN v_after := v_session; v_session := NULL; END IF;
    END IF;
    EXIT WHEN budget <= 0;
  END LOOP;
  UPDATE opengeni_private.session_usage_limit_roots SET
    import_cursor = jsonb_build_object('session', v_session, 'after', v_after, 'phase', v_phase,
      'factAt', v_fact_at, 'factId', v_fact_id, 'seq', v_seq),
    import_imported = import_imported + imported
  WHERE workspace_id = p_workspace AND root_session_id = p_root;
  RETURN false;
END $$;

CREATE FUNCTION session_usage_limit_import_step(p_account uuid, p_workspace uuid, p_root uuid, p_budget integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF session_usage_limit_import_page(p_account, p_workspace, p_root, p_budget) THEN
    -- Absence of an older record is not proof of no usage: stay partial.
    UPDATE opengeni_private.session_usage_limit_roots SET history_state = 'legacy_partial',
      import_next_at = NULL, import_error = NULL, import_attempts = 0,
      usage_revision = usage_revision + 1,
      updated_at = clock_timestamp()
    WHERE workspace_id = p_workspace AND root_session_id = p_root;
    RETURN true;
  END IF;
  UPDATE opengeni_private.session_usage_limit_roots SET import_next_at = clock_timestamp(),
    import_error = NULL, import_attempts = 0
  WHERE workspace_id = p_workspace AND root_session_id = p_root;
  RETURN false;
END $$;

CREATE FUNCTION session_usage_limit_meter_amount(p_amount numeric, p_pricing text, p_input numeric, p_output numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT CASE WHEN p_amount BETWEEN 0 AND 9007199254740991
      AND p_pricing IN ('configured_list_price','gateway_reported')
      AND (p_pricing = 'gateway_reported' OR coalesce(p_input,0) + coalesce(p_output,0) > 0)
    THEN p_amount::bigint END
$$;

CREATE FUNCTION session_usage_limit_state(p_root_json jsonb, p_inherited boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'basis','model_api_equivalent_v1',
    'rootSessionId',p_root.root_session_id,
    'inherited',p_inherited,
    'status',CASE WHEN p_root.history_state='preparing' THEN 'preparing'
      WHEN p_root.limit_micros IS NULL THEN 'unlimited'
      WHEN p_root.known_micros >= p_root.limit_micros THEN 'reached'
      ELSE 'within' END,
    'limitMicros',p_root.limit_micros,
    'usedMicros',CASE WHEN p_root.history_state='preparing' THEN NULL ELSE p_root.known_micros END,
    'version',p_root.config_version,
    'usageRevision',p_root.usage_revision,
    'history',p_root.history_state,
    'coverage',CASE WHEN p_root.history_state='complete' AND p_root.unpriced_calls=0
      THEN 'complete' ELSE 'partial' END,
    'pricedCalls',p_root.priced_calls,
    'freeCalls',p_root.free_calls,
    'unpricedCalls',p_root.unpriced_calls,
    'conflicts',p_root.conflict_count,
    'updatedAt',to_char(p_root.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  FROM jsonb_populate_record(NULL::opengeni_private.session_usage_limit_roots, p_root_json) AS p_root
$$;

CREATE FUNCTION session_visibility_change_blocker(p_account_id uuid, p_workspace_id uuid, p_session_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  session_row sessions%ROWTYPE;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'session visibility preview authority is invalid'
    USING ERRCODE = '42501'; END IF;
  SELECT session.* INTO session_row FROM sessions session
  WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session visibility preview session is unavailable'
    USING ERRCODE = 'P0002'; END IF;
  IF session_row.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'session visibility preview is owner-only' USING ERRCODE = '42501';
  END IF;
  RETURN NULL;
END
$$;

CREATE FUNCTION session_visibility_foreign_authority_items(p_account_id uuid, p_workspace_id uuid, p_session_id uuid) RETURNS TABLE(pending_update_count integer, account_choice_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  session_row sessions%ROWTYPE;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN RAISE EXCEPTION 'session visibility preview authority is invalid'
    USING ERRCODE = '42501'; END IF;
  SELECT session.* INTO session_row FROM sessions session
  WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'session visibility preview session is unavailable'
    USING ERRCODE = 'P0002'; END IF;
  IF session_row.owner_subject_id IS DISTINCT FROM opengeni_private.current_subject_id() THEN
    RAISE EXCEPTION 'session visibility preview is owner-only' USING ERRCODE = '42501';
  END IF;
  SELECT count(*)::integer INTO pending_update_count FROM session_system_updates pending_update
  WHERE pending_update.workspace_id = p_workspace_id
    AND pending_update.session_id = p_session_id AND pending_update.state = 'pending'
    AND pending_update.kind <> 'background_command_result'
    AND session_system_update_carries_foreign_authority(pending_update,
      session_row.owner_subject_id, session_row.owner_organization_membership_id);
  account_choice_count := session_foreign_subscription_binding_count(
    p_account_id, p_workspace_id, p_session_id, session_row.owner_subject_id);
  RETURN NEXT;
END
$$;

CREATE FUNCTION session_visibility_lifecycle_capability_held() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1
        FROM session_visibility_write_capabilities capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
          AND capability.capability_id = nullif(
            pg_catalog.current_setting(
              'opengeni.session_visibility_write_capability', true
            ),
            ''
          )::uuid
      )
    $$;

COMMENT ON FUNCTION session_visibility_lifecycle_capability_held() IS 'True only inside a transaction holding an owner-minted session-visibility write capability; the runtime role cannot mint one.';

CREATE FUNCTION session_work_claim_subject_digest(p_namespace text, p_type text, p_canonical_key text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
  SELECT encode(sha256(convert_to(
    p_namespace || chr(31) || p_type || chr(31) || p_canonical_key,
    'UTF8'
  )), 'hex')
$$;

CREATE FUNCTION set_credit_promotion_policy(p_policy jsonb, p_operator text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  -- ECMAScript String.trim whitespace; PostgreSQL btrim defaults to ASCII space.
  trim_chars CONSTANT text := U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
  model_list jsonb;
  model_id text;
  offer_id text;
  offer jsonb;
  offer_label text;
  written_revision bigint;
BEGIN
  IF p_policy IS NULL OR jsonb_typeof(p_policy) <> 'object'
    OR NOT p_policy ? 'defaultModelIds'
    OR p_policy - ARRAY['defaultModelIds', 'signupModelIds', 'offers'] <> '{}'::jsonb
    OR (p_policy ? 'offers' AND jsonb_typeof(p_policy->'offers') <> 'object') THEN
    RAISE EXCEPTION 'Policy requires defaultModelIds and optional signupModelIds/offers' USING ERRCODE = '22023';
  END IF;
  FOR offer_id, offer IN SELECT key, value FROM jsonb_each(coalesce(p_policy->'offers', '{}'::jsonb)) LOOP
    IF offer_id = '' OR jsonb_typeof(offer) <> 'object'
      OR offer - ARRAY['label', 'eligibleModelIds'] <> '{}'::jsonb
      OR jsonb_typeof(offer->'label') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'Invalid credit offer' USING ERRCODE = '22023';
    END IF;
    offer_label := btrim(offer->>'label', trim_chars);
    -- JavaScript string limits count UTF-16 units: supplementary characters use two.
    IF length(regexp_replace(offer_label, U&'[\+010000-\+10FFFF]', 'xx', 'g')) NOT BETWEEN 1 AND 120 THEN
      RAISE EXCEPTION 'Invalid credit offer label' USING ERRCODE = '22023';
    END IF;
  END LOOP;
  FOR model_list IN
    SELECT p_policy->'defaultModelIds'
    UNION ALL SELECT p_policy->'signupModelIds' WHERE p_policy ? 'signupModelIds'
    UNION ALL SELECT value->'eligibleModelIds'
      FROM jsonb_each(coalesce(p_policy->'offers', '{}'::jsonb)) WHERE value ? 'eligibleModelIds'
  LOOP
    IF jsonb_typeof(model_list) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'Model list must be an array' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(model_list) NOT BETWEEN 1 AND 40 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(model_list) id WHERE jsonb_typeof(id) <> 'string'
    ) THEN
      RAISE EXCEPTION 'Model list requires 1-40 canonical model IDs' USING ERRCODE = '22023';
    END IF;
    FOR model_id IN SELECT jsonb_array_elements_text(model_list) LOOP
      IF model_id <> btrim(model_id, trim_chars)
        OR length(regexp_replace(model_id, U&'[\+010000-\+10FFFF]', 'xx', 'g')) NOT BETWEEN 1 AND 200 THEN
        RAISE EXCEPTION 'Model list requires 1-40 canonical model IDs' USING ERRCODE = '22023';
      END IF;
    END LOOP;
  END LOOP;
  -- Serializes revision order across simultaneous operator updates.
  PERFORM pg_advisory_xact_lock(hashtextextended('credit-promotion-policy', 0));
  INSERT INTO opengeni_private.credit_promotion_policy_revisions (policy, operator, reason)
    VALUES (p_policy, p_operator, p_reason) RETURNING revision INTO written_revision;
  RETURN written_revision;
END $$;

CREATE FUNCTION set_managed_auth_new_signups_enabled(p_enabled boolean, p_operator text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    SET lock_timeout TO '10s'
    AS $$
DECLARE
  previous_enabled boolean;
  written opengeni_private.managed_auth_new_signups_switch_revisions%ROWTYPE;
BEGIN
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'managed auth new signups switch requires an explicit enabled value'
      USING ERRCODE = '22023';
  END IF;
  IF p_operator IS NULL OR p_operator <> pg_catalog.btrim(p_operator)
    OR pg_catalog.char_length(p_operator) NOT BETWEEN 1 AND 200
  THEN
    RAISE EXCEPTION 'managed auth new signups switch operator must be 1-200 trimmed characters'
      USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR p_reason <> pg_catalog.btrim(p_reason)
    OR pg_catalog.char_length(p_reason) NOT BETWEEN 6 AND 1000
  THEN
    RAISE EXCEPTION 'managed auth new signups switch reason must be 6-1000 trimmed characters'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('managed-auth-new-signups-switch', 0)
  );
  SELECT revision.signups_enabled
  INTO previous_enabled
  FROM opengeni_private.managed_auth_new_signups_switch_revisions revision
  ORDER BY revision.revision DESC
  LIMIT 1;

  INSERT INTO opengeni_private.managed_auth_new_signups_switch_revisions (
    signups_enabled, previous_signups_enabled, operator, reason, database_role
  ) VALUES (
    p_enabled, previous_enabled, p_operator, p_reason, session_user
  )
  RETURNING * INTO written;

  RETURN pg_catalog.jsonb_build_object(
    'revision', written.revision,
    'signupsEnabled', written.signups_enabled,
    'previousSignupsEnabled', written.previous_signups_enabled,
    'changed', written.previous_signups_enabled IS DISTINCT FROM written.signups_enabled,
    'operator', written.operator,
    'reason', written.reason,
    'databaseRole', written.database_role,
    'changedAt', written.changed_at
  );
END
$$;

CREATE FUNCTION set_scheduled_task_execution_digest() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  NEW.execution_digest := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      (
        ((pg_catalog.to_jsonb(NEW) - 'subscription_authority') - 'authority_inserted_at')
          - ARRAY[
            'name',
            'status',
            'updated_at',
            'authority_revision',
            'execution_digest', 'owner_subject_id', 'visibility'
          ]::text[]
          - (CASE WHEN NEW.creator_first_party_mcp_tools IS NULL
              THEN ARRAY['creator_first_party_mcp_tools'] ELSE ARRAY[]::text[] END)
          - (CASE WHEN NEW.creator_first_party_mcp_permissions IS NULL
              THEN ARRAY['creator_first_party_mcp_permissions'] ELSE ARRAY[]::text[] END)
          - (CASE WHEN NEW.creator_session_policy IS NULL
              THEN ARRAY['creator_session_policy'] ELSE ARRAY[]::text[] END)
          - (CASE WHEN NEW.vault_policy = '{"mode":"all"}'::jsonb
              THEN ARRAY['vault_policy'] ELSE ARRAY[]::text[] END)
      )::text,
      'UTF8'
    )),
    'hex'
  );
  RETURN NEW;
END
$$;

CREATE FUNCTION set_session_vault_policy(p_session uuid, p_policy jsonb, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  account uuid;
  workspace uuid;
  parent_ids jsonb;
  parent_narrowed uuid;
  normalized jsonb;
  outside jsonb;
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  account := (context ->> 'accountId')::uuid;
  workspace := (context ->> 'workspaceId')::uuid;
  -- sessions is a session-tenancy hot table: take the workspace fence (shared)
  -- before reading the policy chain or updating the row (0345 protocol).
  PERFORM acquire_session_tenancy_fence(workspace);
  IF NOT opengeni_private.vault_policy_is_valid(p_policy) THEN
    PERFORM opengeni_private.vault_raise('vault_policy_outside_parent',
      'policy is {"mode":"all"} or {"mode":"selected","vaultIds":[...]} with at most 200 IDs');
  END IF;
  normalized := CASE WHEN p_policy ->> 'mode' = 'all' THEN '{"mode":"all"}'::jsonb
    ELSE pg_catalog.jsonb_build_object('mode', 'selected', 'vaultIds', coalesce((
      SELECT pg_catalog.jsonb_agg(DISTINCT pg_catalog.lower(element #>> '{}'))
      FROM pg_catalog.jsonb_array_elements(p_policy -> 'vaultIds') element
    ), '[]'::jsonb)) END;
  IF NOT EXISTS (SELECT 1 FROM sessions session_value WHERE session_value.id = p_session
    AND session_value.account_id = account AND session_value.workspace_id = workspace) THEN
    PERFORM opengeni_private.vault_raise('vault_not_found', 'session not found',
      pg_catalog.jsonb_build_object('sessionId', p_session));
  END IF;
  SELECT chain.vault_ids, chain.narrowed_by INTO parent_ids, parent_narrowed
  FROM opengeni_private.vault_session_policy_chain(account, workspace, p_session, false) chain;
  IF parent_ids IS NOT NULL THEN
    IF normalized ->> 'mode' = 'all' THEN
      PERFORM opengeni_private.vault_raise('vault_policy_outside_parent',
        'a parent session narrows vault access; choose a subset of its vaults',
        pg_catalog.jsonb_build_object('narrowedBySessionId', parent_narrowed, 'allowedVaultIds', parent_ids));
    END IF;
    SELECT coalesce(pg_catalog.jsonb_agg(element), '[]'::jsonb) INTO outside
    FROM pg_catalog.jsonb_array_elements(normalized -> 'vaultIds') element
    WHERE NOT parent_ids @> pg_catalog.jsonb_build_array(element);
    IF pg_catalog.jsonb_array_length(outside) > 0 THEN
      PERFORM opengeni_private.vault_raise('vault_policy_outside_parent',
        'these vaults are outside the parent session''s vaults',
        pg_catalog.jsonb_build_object('narrowedBySessionId', parent_narrowed,
          'outsideVaultIds', outside, 'allowedVaultIds', parent_ids));
    END IF;
  END IF;
  UPDATE sessions SET vault_policy = normalized
  WHERE id = p_session AND account_id = account AND workspace_id = workspace;
  PERFORM opengeni_private.vault_audit(account, workspace, context ->> 'subjectId', 'vault.policy.updated',
    'session', p_session::text, pg_catalog.jsonb_build_object('sessionId', p_session, 'policy', normalized));
  result := opengeni_private.vault_session_view_json(context, p_session);
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION set_subscription_plan_catalog(p_catalog jsonb, p_operator text, p_reason text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $_$
DECLARE entry jsonb; legacy_price jsonb; written bigint;
BEGIN
  IF jsonb_typeof(p_catalog) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Plan catalog must be an array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_catalog) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'Plan catalog requires 1-100 plans' USING ERRCODE = '22023';
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(p_catalog) LOOP
    IF jsonb_typeof(entry) IS DISTINCT FROM 'object'
      OR NOT entry ?& ARRAY['key','label','stripePriceId','monthlyPriceMicros','monthlyCreditMicros','seatLimit','freeCredit']
      OR entry - ARRAY['key','label','stripePriceId','legacyStripePriceIds','monthlyPriceMicros','monthlyCreditMicros','seatLimit','freeCredit'] <> '{}'::jsonb
      OR coalesce(entry->>'key', '') !~ '^[a-z][a-z0-9_-]{0,39}$'
      OR jsonb_typeof(entry->'label') IS DISTINCT FROM 'string'
      OR length(btrim(entry->>'label')) NOT BETWEEN 1 AND 120
      OR (entry->'stripePriceId' <> 'null'::jsonb AND
        (jsonb_typeof(entry->'stripePriceId') <> 'string' OR length(btrim(entry->>'stripePriceId')) NOT BETWEEN 1 AND 200
          OR entry->>'stripePriceId' <> btrim(entry->>'stripePriceId')))
      OR jsonb_typeof(entry->'monthlyCreditMicros') IS DISTINCT FROM 'number'
      OR (entry->>'monthlyCreditMicros')::numeric NOT BETWEEN 0 AND 9007199254740991
      OR (entry->>'monthlyCreditMicros')::numeric <> trunc((entry->>'monthlyCreditMicros')::numeric)
      OR (entry->'monthlyPriceMicros' <> 'null'::jsonb AND
        (jsonb_typeof(entry->'monthlyPriceMicros') <> 'number'
          OR (entry->>'monthlyPriceMicros')::numeric NOT BETWEEN 0 AND 9007199254740991
          OR (entry->>'monthlyPriceMicros')::numeric <> trunc((entry->>'monthlyPriceMicros')::numeric)))
      OR (entry->'seatLimit' <> 'null'::jsonb AND
        (jsonb_typeof(entry->'seatLimit') <> 'number' OR (entry->>'seatLimit')::numeric NOT BETWEEN 1 AND 1000000
          OR (entry->>'seatLimit')::numeric <> trunc((entry->>'seatLimit')::numeric)))
      OR jsonb_typeof(entry->'freeCredit') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'Invalid plan catalog entry' USING ERRCODE = '22023';
    END IF;
    IF entry ? 'legacyStripePriceIds' THEN
      IF jsonb_typeof(entry->'legacyStripePriceIds') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Legacy Stripe price IDs must be an array' USING ERRCODE = '22023';
      END IF;
      IF jsonb_array_length(entry->'legacyStripePriceIds') > 100 THEN
        RAISE EXCEPTION 'At most 100 legacy Stripe price IDs are allowed per plan' USING ERRCODE = '22023';
      END IF;
      FOR legacy_price IN SELECT value FROM jsonb_array_elements(entry->'legacyStripePriceIds') LOOP
        IF jsonb_typeof(legacy_price) IS DISTINCT FROM 'string'
          OR length(btrim(legacy_price #>> '{}')) NOT BETWEEN 1 AND 200
          OR legacy_price #>> '{}' <> btrim(legacy_price #>> '{}') THEN
          RAISE EXCEPTION 'Invalid legacy Stripe price ID' USING ERRCODE = '22023';
        END IF;
      END LOOP;
    END IF;
  END LOOP;
  IF (SELECT count(*) <> count(DISTINCT value->>'key') FROM jsonb_array_elements(p_catalog))
    OR (SELECT count(price) <> count(DISTINCT price) FROM (
      SELECT value->>'stripePriceId' AS price FROM jsonb_array_elements(p_catalog)
      UNION ALL
      SELECT legacy.value FROM jsonb_array_elements(p_catalog) plan,
        LATERAL jsonb_array_elements_text(coalesce(plan.value->'legacyStripePriceIds', '[]'::jsonb)) legacy
    ) prices) THEN
    RAISE EXCEPTION 'Plan keys and current or legacy Stripe prices must be unique' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('subscription-plan-catalog', 0));
  IF EXISTS (SELECT 1 FROM opengeni_private.subscription_plan_catalog_revisions revision,
    LATERAL jsonb_array_elements(revision.catalog) old_entry
    WHERE revision.revision = (SELECT max(revision) FROM opengeni_private.subscription_plan_catalog_revisions)
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_catalog) candidate WHERE candidate->>'key' = old_entry->>'key')) THEN
    RAISE EXCEPTION 'Existing plan keys cannot be removed from the catalog' USING ERRCODE = '22023';
  END IF;
  INSERT INTO opengeni_private.subscription_plan_catalog_revisions(catalog, operator, reason)
    VALUES (p_catalog, p_operator, p_reason) RETURNING revision INTO written;
  RETURN written;
END $_$;

CREATE FUNCTION set_vault_sync_status(p_vault uuid, p jsonb, p_principal jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  vault_row vaults;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  vault_row := opengeni_private.vault_reachable_row(context, p_vault);
  IF vault_row.source = 'opengeni' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'only connected vaults sync');
  END IF;
  SELECT locked.* INTO vault_row FROM vaults locked
  WHERE locked.id = vault_row.id FOR NO KEY UPDATE OF locked;
  IF vault_row.id IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_not_found', 'vault not found');
  END IF;
  IF p ? 'expectedCacheEpoch'
    AND (p ->> 'expectedCacheEpoch')::bigint IS DISTINCT FROM vault_row.provider_cache_epoch THEN
    PERFORM opengeni_private.vault_raise('provider_conflict',
      'another refresh settled first; this late inventory was not applied',
      pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'superseded', true));
  END IF;
  IF p ? 'operations' AND (
    pg_catalog.jsonb_typeof(p -> 'operations') NOT IN ('object', 'null')
    OR pg_catalog.octet_length((p -> 'operations')::text) > 4096) THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied',
      'provider operations must be a small JSON object');
  END IF;
  IF p ? 'freshness' AND (
    pg_catalog.jsonb_typeof(p -> 'freshness') NOT IN ('object', 'null')
    OR pg_catalog.octet_length((p -> 'freshness')::text) > 1024) THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied',
      'provider freshness must be a small JSON object');
  END IF;
  IF p ? 'mirror' THEN
    IF NOT (p ? 'expectedCacheEpoch') THEN
      PERFORM opengeni_private.vault_raise('provider_conflict',
        'atomic refresh settlement requires its pre-I/O cache epoch');
    END IF;
    IF p ->> 'status' IS DISTINCT FROM 'ok' OR pg_catalog.jsonb_typeof(p -> 'mirror') <> 'object' THEN
      PERFORM opengeni_private.vault_raise('provider_inventory_incomplete',
        'only a successful refresh may replace the inventory');
    END IF;
    PERFORM upsert_provider_vault_items(p_vault, p #>> '{mirror,contentVersion}',
      p #> '{mirror,items}', p_principal);
    PERFORM opengeni_private.vault_capability_open('write');
  END IF;
  UPDATE vaults SET
    provider_cache_epoch = provider_cache_epoch + CASE WHEN p ? 'mirror' THEN 0 ELSE 1 END,
    sync_status = p ->> 'status',
    sync_error_code = p ->> 'errorCode',
    sync_error_message = pg_catalog.left(p ->> 'errorMessage', 2000),
    rate_limited_until = nullif(p ->> 'rateLimitedUntil', '')::timestamptz,
    last_synced_at = CASE WHEN p ->> 'status' = 'ok' THEN pg_catalog.now() ELSE last_synced_at END,
    provider_operations = CASE WHEN p ? 'operations'
      THEN nullif(p -> 'operations', 'null'::jsonb) ELSE provider_operations END,
    provider_freshness = CASE WHEN p ? 'freshness'
      THEN nullif(p -> 'freshness', 'null'::jsonb) ELSE provider_freshness END,
    updated_at = pg_catalog.now()
  WHERE id = vault_row.id;
  IF p ->> 'status' IN ('error', 'auth_expired') THEN
    PERFORM opengeni_private.vault_audit(vault_row.account_id, (context ->> 'workspaceId')::uuid,
      context ->> 'subjectId', 'vault.provider.error', 'vault', vault_row.id::text,
      pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'status', p ->> 'status',
        'errorCode', p ->> 'errorCode'));
  END IF;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION set_verified_signup_trial_credits_enabled(p_enabled boolean, p_operator text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    SET lock_timeout TO '10s'
    AS $$
DECLARE
  previous_enabled boolean;
  written opengeni_private.verified_signup_trial_switch_revisions%ROWTYPE;
BEGIN
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'verified signup trial switch requires an explicit enabled value'
      USING ERRCODE = '22023';
  END IF;
  IF p_operator IS NULL OR p_operator <> pg_catalog.btrim(p_operator)
    OR pg_catalog.char_length(p_operator) NOT BETWEEN 1 AND 200
  THEN
    RAISE EXCEPTION 'verified signup trial switch operator must be 1-200 trimmed characters'
      USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR p_reason <> pg_catalog.btrim(p_reason)
    OR pg_catalog.char_length(p_reason) NOT BETWEEN 6 AND 1000
  THEN
    RAISE EXCEPTION 'verified signup trial switch reason must be 6-1000 trimmed characters'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('verified-signup-trial-switch', 0)
  );
  SELECT revision.grants_enabled
  INTO previous_enabled
  FROM opengeni_private.verified_signup_trial_switch_revisions revision
  ORDER BY revision.revision DESC
  LIMIT 1;

  INSERT INTO opengeni_private.verified_signup_trial_switch_revisions (
    grants_enabled, previous_grants_enabled, operator, reason, database_role
  ) VALUES (
    p_enabled, previous_enabled, p_operator, p_reason, session_user
  )
  RETURNING * INTO written;

  RETURN pg_catalog.jsonb_build_object(
    'revision', written.revision,
    'grantsEnabled', written.grants_enabled,
    'previousGrantsEnabled', written.previous_grants_enabled,
    'changed', written.previous_grants_enabled IS DISTINCT FROM written.grants_enabled,
    'operator', written.operator,
    'reason', written.reason,
    'databaseRole', written.database_role,
    'changedAt', written.changed_at
  );
END
$$;

CREATE FUNCTION settle_active_session_work_claims(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_state text, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
DECLARE
  claim_row session_work_claims%ROWTYPE;
  now_value timestamptz := clock_timestamp();
  settled_count integer := 0;
  write_capability_id uuid := gen_random_uuid();
  previous_account_id text := current_setting('opengeni.account_id', true);
  previous_workspace_id text := current_setting('opengeni.workspace_id', true);
  previous_capability text := current_setting(
    'opengeni.session_work_claim_write_capability', true
  );
BEGIN
  IF p_state NOT IN ('released','superseded','stale')
    OR p_reason NOT IN ('completed','cancelled','failed','superseded')
  THEN
    RAISE EXCEPTION 'work claim lifecycle settlement is invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM set_config('opengeni.account_id', p_account_id::text, true);
  PERFORM set_config('opengeni.workspace_id', p_workspace_id::text, true);
  INSERT INTO session_work_claim_write_capabilities (
    backend_pid, transaction_id, capability_id
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), write_capability_id);
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', write_capability_id::text, true
  );
  FOR claim_row IN
    SELECT * FROM session_work_claims claim
    WHERE claim.account_id = p_account_id
      AND claim.workspace_id = p_workspace_id
      AND claim.session_id = p_session_id
      AND claim.state = 'active'
    ORDER BY claim.id
    FOR UPDATE
  LOOP
    UPDATE session_work_claims claim SET
      state = p_state,
      revision = claim.revision + 1,
      settled_at = now_value,
      updated_at = now_value
    WHERE claim.workspace_id = p_workspace_id
      AND claim.id = claim_row.id
      AND claim.state = 'active'
      AND claim.revision = claim_row.revision
    RETURNING * INTO STRICT claim_row;
    INSERT INTO session_work_claim_revisions (
      account_id, workspace_id, claim_id, session_id, root_session_id,
      operation_id, input_hash, mutation_kind, prior_revision, resulting_revision,
      subject_namespace, subject_type, canonical_key, subject_digest, display_label,
      role, state, provenance, version_kind, version_value, observed_at,
      claim_created_at, claim_updated_at, settled_at, actor_kind, actor_subject_id,
      reason
    ) VALUES (
      claim_row.account_id, claim_row.workspace_id, claim_row.id,
      claim_row.session_id, claim_row.root_session_id, gen_random_uuid(),
      encode(sha256(convert_to(jsonb_build_object(
        'claimId', claim_row.id,
        'priorRevision', claim_row.revision - 1,
        'state', p_state,
        'reason', p_reason
      )::text, 'UTF8')), 'hex'),
      p_state, claim_row.revision - 1, claim_row.revision,
      claim_row.subject_namespace, claim_row.subject_type, claim_row.canonical_key,
      claim_row.subject_digest, claim_row.display_label, claim_row.role, claim_row.state,
      claim_row.provenance, claim_row.version_kind, claim_row.version_value,
      claim_row.observed_at, claim_row.created_at, claim_row.updated_at,
      claim_row.settled_at, 'system', 'system:lifecycle', p_reason
    );
    settled_count := settled_count + 1;
  END LOOP;
  DELETE FROM session_work_claim_write_capabilities capability
  WHERE capability.backend_pid = pg_backend_pid()
    AND capability.transaction_id = pg_current_xact_id()
    AND capability.capability_id = write_capability_id;
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', coalesce(previous_capability, ''), true
  );
  PERFORM set_config('opengeni.account_id', coalesce(previous_account_id, ''), true);
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace_id, ''), true);
  RETURN settled_count;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', coalesce(previous_capability, ''), true
  );
  PERFORM set_config('opengeni.account_id', coalesce(previous_account_id, ''), true);
  PERFORM set_config('opengeni.workspace_id', coalesce(previous_workspace_id, ''), true);
  RAISE;
END;
$$;

CREATE FUNCTION settle_managed_sign_in_notification(p_operation uuid, p_lease uuid, p_status text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE applied boolean; previous_marker text := current_setting('opengeni.canonical_human_identity_lifecycle',true);
BEGIN
  IF p_status NOT IN ('sent','failed','outcome_unknown') THEN RETURN false; END IF;
  PERFORM set_config('opengeni.canonical_human_identity_lifecycle','active',true);
  UPDATE managed_sign_in_method_operations SET notification_status=p_status,lease_id=NULL,lease_until=NULL,
    available_at=clock_timestamp()+interval '1 minute' WHERE operation_id=p_operation AND lease_id=p_lease;
  applied := FOUND;
  PERFORM set_config('opengeni.canonical_human_identity_lifecycle',coalesce(previous_marker,''),true);
  RETURN applied;
END $$;

CREATE FUNCTION settle_organization_recovery_notification(p_outbox_id uuid, p_delivery_id uuid, p_claim_owner text, p_phase text, p_provider_message_id text, p_error_class text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  prior organization_recovery_notification_attempts%ROWTYPE;
  existing organization_recovery_notification_attempts%ROWTYPE;
  result jsonb;
  previous_marker text := pg_catalog.current_setting(
    'opengeni.organization_recovery_lifecycle', true
  );
BEGIN
  IF p_outbox_id IS NULL OR p_delivery_id IS NULL
    OR p_claim_owner IS NULL OR length(btrim(p_claim_owner)) NOT BETWEEN 1 AND 256
    OR p_phase NOT IN ('sent', 'failed', 'outcome_unknown')
    OR (p_phase = 'failed' AND nullif(btrim(p_error_class), '') IS NULL)
    OR (p_phase <> 'failed' AND p_error_class IS NOT NULL)
    OR (p_provider_message_id IS NOT NULL AND octet_length(p_provider_message_id) > 1024)
    OR (p_error_class IS NOT NULL AND octet_length(p_error_class) > 256)
  THEN
    RAISE EXCEPTION 'organization recovery notification settlement is invalid'
      USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle', 'active', true);
  PERFORM 1 FROM organization_recovery_notification_outbox outbox
  WHERE outbox.id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization recovery notification delivery is unavailable'
      USING ERRCODE = '42501';
  END IF;
  SELECT * INTO prior FROM organization_recovery_notification_attempts attempt
  WHERE attempt.outbox_id = p_outbox_id AND attempt.delivery_id = p_delivery_id
    AND attempt.phase = 'provider_started' AND attempt.claim_owner = p_claim_owner;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization recovery notification delivery is unavailable'
      USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM organization_recovery_notification_attempts attempt
    WHERE attempt.outbox_id = p_outbox_id AND attempt.delivery_id = p_delivery_id
      AND attempt.phase = 'claim_expired'
  ) THEN
    RAISE EXCEPTION 'organization recovery notification claim is stale'
      USING ERRCODE = '40001';
  END IF;
  SELECT * INTO existing FROM organization_recovery_notification_attempts attempt
  WHERE attempt.outbox_id = p_outbox_id AND attempt.delivery_id = p_delivery_id
    AND attempt.phase IN ('sent', 'failed', 'outcome_unknown')
  ORDER BY attempt.created_at DESC, attempt.id DESC LIMIT 1;
  IF FOUND THEN
    IF existing.phase = p_phase
      AND existing.provider_message_id IS NOT DISTINCT FROM p_provider_message_id
      AND existing.error_class IS NOT DISTINCT FROM p_error_class
    THEN
      result := pg_catalog.jsonb_build_object(
        'outboxId', p_outbox_id::text, 'deliveryId', p_delivery_id::text,
        'claimOwner', prior.claim_owner, 'attemptNumber', prior.attempt_number,
        'phase', existing.phase, 'providerMessageId', existing.provider_message_id,
        'errorClass', existing.error_class, 'settledAt', existing.created_at,
        'replay', true
      );
      PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
      RETURN result;
    END IF;
    RAISE EXCEPTION 'organization recovery notification settlement conflicts'
      USING ERRCODE = '23505';
  END IF;
  INSERT INTO organization_recovery_notification_attempts (
    outbox_id, delivery_id, provider, claim_owner, attempt_number,
    lease_expires_at, phase, provider_message_id, error_class
  ) VALUES (
    p_outbox_id, p_delivery_id, prior.provider, prior.claim_owner,
    prior.attempt_number, prior.lease_expires_at, p_phase,
    p_provider_message_id, p_error_class
  ) RETURNING pg_catalog.jsonb_build_object(
    'outboxId', outbox_id::text, 'deliveryId', delivery_id::text,
    'claimOwner', claim_owner, 'attemptNumber', attempt_number,
    'phase', phase, 'providerMessageId', provider_message_id,
    'errorClass', error_class, 'settledAt', created_at, 'replay', false
  ) INTO result;
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('opengeni.organization_recovery_lifecycle',
    CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END, true);
  RAISE;
END
$$;

CREATE FUNCTION settle_organization_user_setup_delivery(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  delivery_id_value uuid := nullif(p_command ->> 'deliveryId', '')::uuid;
  attempt_id_value uuid := nullif(p_command ->> 'attemptId', '')::uuid;
  claim_holder_id_value uuid := nullif(p_command ->> 'claimHolderId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  outcome_value text := p_command ->> 'outcome';
  error_class_value text := nullif(btrim(p_command ->> 'errorClass'), '');
  provider_message_id_value text := nullif(btrim(p_command ->> 'providerMessageId'), '');
  delivery organization_user_setup_deliveries%ROWTYPE;
  invitation organization_membership_invitations%ROWTYPE;
  now_value timestamptz := clock_timestamp();
BEGIN
  IF delivery_id_value IS NULL OR attempt_id_value IS NULL OR claim_holder_id_value IS NULL
    OR actor_subject IS NULL OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR outcome_value NOT IN ('sent', 'failed', 'outcome_unknown')
    OR (outcome_value <> 'sent' AND (
      error_class_value IS NULL OR octet_length(convert_to(error_class_value, 'UTF8')) > 64
    ))
    OR (provider_message_id_value IS NOT NULL
      AND octet_length(convert_to(provider_message_id_value, 'UTF8')) > 255)
  THEN
    RAISE EXCEPTION 'organization setup delivery settlement is invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM set_config(
    'opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true
  );
  SELECT * INTO delivery FROM organization_user_setup_deliveries candidate
  WHERE candidate.id = delivery_id_value;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization setup delivery is unavailable' USING ERRCODE = 'P0002';
  END IF;
  IF delivery.account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'organization setup delivery authority is invalid' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'organization-invitation-email:' || delivery.recipient_email, 0
  ));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'organization-membership:' || delivery.account_id::text, 0
  ));
  PERFORM 1 FROM managed_accounts account WHERE account.id = delivery.account_id FOR KEY SHARE;
  PERFORM 1 FROM organization_memberships membership
  WHERE membership.account_id = delivery.account_id AND membership.subject_id = actor_subject
    AND membership.status = 'active' AND membership.role IN ('owner', 'admin') FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO invitation FROM organization_membership_invitations candidate
  WHERE candidate.account_id = delivery.account_id AND candidate.id = delivery.invitation_id
  FOR UPDATE;
  SELECT * INTO delivery FROM organization_user_setup_deliveries candidate
  WHERE candidate.id = delivery_id_value FOR UPDATE;
  IF delivery.state = 'revoked' AND delivery.claim_holder_id IS NULL THEN
    PERFORM 1 FROM organization_user_setup_delivery_attempts attempt
    WHERE attempt.id = attempt_id_value AND attempt.delivery_id = delivery.id
      AND attempt.claim_holder_id = claim_holder_id_value AND attempt.result = 'revoked';
    IF FOUND THEN
      RETURN opengeni_private.organization_user_setup_delivery_json(delivery);
    END IF;
  END IF;
  IF delivery.claim_holder_id IS DISTINCT FROM claim_holder_id_value THEN
    RAISE EXCEPTION 'organization setup delivery claim changed' USING ERRCODE = '40001';
  END IF;
  PERFORM 1 FROM organization_user_setup_delivery_attempts attempt
  WHERE attempt.id = attempt_id_value AND attempt.delivery_id = delivery.id
    AND attempt.claim_holder_id = claim_holder_id_value AND attempt.result IS NULL
    AND attempt.provider_started_at IS NOT NULL
  FOR UPDATE;
  IF NOT FOUND OR delivery.provider_started_at IS NULL THEN
    RAISE EXCEPTION 'organization setup delivery attempt changed' USING ERRCODE = '40001';
  END IF;
  UPDATE organization_user_setup_delivery_attempts SET
    result = CASE WHEN invitation.status = 'pending' THEN outcome_value ELSE 'revoked' END,
    error_class = error_class_value,
    provider_message_id = provider_message_id_value,
    settled_at = now_value
  WHERE id = attempt_id_value;
  IF invitation.status <> 'pending' OR delivery.state = 'revoked' THEN
    UPDATE organization_user_setup_deliveries SET
      state = 'revoked', revoked_at = coalesce(revoked_at, now_value),
      unresolved_provider_outcome_at = NULL,
      claim_holder_id = NULL, claim_expires_at = NULL,
      revision = revision + 1, updated_at = now_value
    WHERE id = delivery.id RETURNING * INTO delivery;
  ELSE
    UPDATE organization_user_setup_deliveries SET
      state = outcome_value,
      error_class = CASE WHEN outcome_value = 'sent' THEN NULL ELSE error_class_value END,
      provider_message_id = provider_message_id_value,
      sent_at = CASE WHEN outcome_value = 'sent' THEN now_value ELSE NULL END,
      failed_at = CASE WHEN outcome_value = 'failed' THEN now_value ELSE NULL END,
      outcome_unknown_at = CASE WHEN outcome_value = 'outcome_unknown' THEN now_value ELSE NULL END,
      unresolved_provider_outcome_at = CASE
        WHEN outcome_value = 'outcome_unknown'
        THEN coalesce(unresolved_provider_outcome_at, now_value)
        ELSE NULL
      END,
      revoked_at = NULL,
      claim_holder_id = NULL, claim_expires_at = NULL,
      revision = revision + 1, updated_at = now_value
    WHERE id = delivery.id RETURNING * INTO delivery;
  END IF;
  RETURN opengeni_private.organization_user_setup_delivery_json(delivery);
END
$$;

CREATE FUNCTION settle_scheduled_run_from_terminal_turn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE affected integer;
BEGIN
  IF NEW.scheduled_task_run_id IS NULL
    OR NEW.status NOT IN ('completed','failed','cancelled','superseded','withdrawn_for_edit')
    OR NEW.status IS NOT DISTINCT FROM OLD.status
  THEN RETURN NEW; END IF;
  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_lifecycle')
  ON CONFLICT DO NOTHING;
  UPDATE scheduled_task_runs run
  SET status = CASE WHEN NEW.status = 'completed' THEN 'succeeded'
    WHEN NEW.status = 'failed' THEN 'failed' ELSE 'skipped' END,
    error = CASE WHEN NEW.status = 'completed' THEN NULL
      ELSE 'scheduled_turn_' || NEW.status END,
    completed_at = clock_timestamp(), updated_at = clock_timestamp()
  WHERE run.id = NEW.scheduled_task_run_id
    AND run.account_id = NEW.account_id
    AND run.workspace_id = NEW.workspace_id
    AND run.session_id = NEW.session_id
    AND run.status = 'dispatched';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    PERFORM 1 FROM scheduled_task_runs run
    WHERE run.id = NEW.scheduled_task_run_id
      AND run.account_id = NEW.account_id
      AND run.workspace_id = NEW.workspace_id
      AND run.session_id = NEW.session_id
      AND run.status IN ('succeeded','failed','skipped');
    IF NOT FOUND THEN RAISE EXCEPTION 'scheduled run terminal turn settlement changed'
      USING ERRCODE = '42501'; END IF;
  END IF;
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_lifecycle';
  RETURN NEW;
END
$$;

CREATE FUNCTION settle_scheduled_run_from_terminal_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.scheduled_task_run_id IS NULL
    OR OLD.state <> 'pending'
    OR NEW.state NOT IN ('cancelled','superseded','failed')
    OR NEW.delivered_turn_id IS NOT NULL
  THEN RETURN NEW; END IF;
  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_lifecycle')
  ON CONFLICT DO NOTHING;
  UPDATE scheduled_task_runs run
  SET status = CASE WHEN NEW.state = 'failed' THEN 'failed' ELSE 'skipped' END,
    error = 'scheduled_update_' || NEW.state,
    completed_at = clock_timestamp(), updated_at = clock_timestamp()
  WHERE run.id = NEW.scheduled_task_run_id
    AND run.account_id = NEW.account_id
    AND run.workspace_id = NEW.workspace_id
    AND run.session_id = NEW.session_id
    AND run.status IN ('queued','dispatched');
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_lifecycle';
  RETURN NEW;
END
$$;

CREATE FUNCTION settle_session_work_claims_on_goal_completion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'completed' THEN
    PERFORM settle_active_session_work_claims(
      NEW.account_id, NEW.workspace_id, NEW.session_id, 'released', 'completed'
    );
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION settle_session_work_claims_on_session_terminal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'cancelled' THEN
    PERFORM settle_active_session_work_claims(
      NEW.account_id, NEW.workspace_id, NEW.id, 'released', 'cancelled'
    );
  ELSIF NEW.status IS DISTINCT FROM OLD.status AND NEW.status = 'failed' THEN
    PERFORM settle_active_session_work_claims(
      NEW.account_id, NEW.workspace_id, NEW.id, 'stale', 'failed'
    );
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION site_session_cancellation_capability_active(a uuid, w uuid, site uuid, root uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
      SELECT EXISTS (
        SELECT 1 FROM opengeni_private.site_session_cancellation_capabilities c
        WHERE c.target_schema={{schema_oid}}::oid AND c.backend_pid=pg_backend_pid()
          AND c.transaction_id=pg_current_xact_id_if_assigned()
          AND c.account_id=a AND c.workspace_id=w AND c.site_id=site AND c.root_session_id=root
          AND a=nullif(current_setting('opengeni.account_id',true),'')::uuid
          AND w=nullif(current_setting('opengeni.workspace_id',true),'')::uuid
          AND c.subject_id IS NOT DISTINCT FROM nullif(current_setting('opengeni.subject_id',true),'')
          AND c.initiating_human_subject_id IS NOT DISTINCT FROM nullif(current_setting('opengeni.initiating_human_subject_id',true),'')
      )
    $$;

CREATE FUNCTION skill_apply_lifecycle(p_account_id uuid, p_workspace_id uuid, p_actor jsonb, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
<<lifecycle>>
DECLARE
  actor_subject text; mode text := 'automatic'; operation text := p_request->>'operation';
  operation_id uuid := (p_request->>'operationId')::uuid;
  skill_id uuid := (p_request->>'skillId')::uuid;
  revision_id uuid; activation_event_id uuid; files jsonb := p_request->'files'; main_content text;
  head preference_registry_preferences%ROWTYPE; rev preference_registry_revisions%ROWTYPE;
  source record; binding skill_source_bindings%ROWTYPE;
  prior skill_write_receipts%ROWTYPE; result jsonb; fingerprint text;
  scope text := coalesce(p_request->>'scope','workspace'); next_event integer;
  title text := p_request->>'title'; description text := p_request->>'description';
  stable_key text := p_request->>'stableKey'; outcome text; source_id text;
  activation_mode text := 'workspace_managed';
  deferred_publication jsonb; source_effective boolean := true;
  confirmation_source skill_write_receipts%ROWTYPE;
  skill_review jsonb; initiating_human text; confirmation_generation integer;
  human_choice text; learning_actor jsonb; learning_policy jsonb;
  original_operation text := p_request->>'operation';
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id',true),'')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(current_setting('opengeni.workspace_id',true),'')::uuid
    OR p_account_id IS NULL OR p_workspace_id IS NULL OR operation_id IS NULL
    OR operation NOT IN ('save','install','approve','reject','restore','confirm_response','remove') OR operation IS NULL
  THEN RAISE EXCEPTION 'Skill lifecycle requires exact tenant context' USING ERRCODE='42501'; END IF;
  IF operation='confirm_response' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:'||p_account_id,0));
  END IF;
  PERFORM 1 FROM workspaces WHERE id=p_workspace_id AND account_id=p_account_id FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Skill workspace unavailable' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('skill-publication:'||p_workspace_id,0));
  IF p_actor->>'kind' = 'agent' THEN
    learning_actor:=knowledge_resolve_actor(p_account_id,p_workspace_id,p_actor);
    learning_policy:=learning_actor->'policy';
    scope:=CASE WHEN learning_actor->>'defaultScope'='personal' THEN 'user' ELSE 'workspace' END;
    -- A personal-learning agent may explicitly choose the workspace. No other
    -- destination is selectable: a shared chat has no person to save for.
    IF p_request ? 'scope' AND p_request->>'scope' IS DISTINCT FROM scope THEN
      IF NOT ((scope='user' AND p_request->>'scope'='workspace')
        OR (scope='workspace' AND p_request->>'scope'='user' AND learning_actor->>'subjectId' IS NOT NULL)) THEN
        RAISE EXCEPTION 'Skill scope is not available to this chat' USING ERRCODE='42501'; END IF;
      scope:=p_request->>'scope';
    END IF;
    IF operation IN ('approve','reject') OR (learning_actor->>'defaultScope'='personal' AND operation='install') THEN
      RAISE EXCEPTION 'Agents cannot review Skills or install workspace plugins from personal learning' USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM sessions s JOIN session_turns t ON t.id=s.active_turn_id AND t.session_id=s.id
      JOIN session_turn_attempts a ON a.id=t.active_attempt_id AND a.turn_id=t.id
      WHERE s.id=(p_actor->>'sessionId')::uuid AND s.account_id=p_account_id AND s.workspace_id=p_workspace_id
        AND t.id=(p_actor->>'turnId')::uuid AND t.account_id=p_account_id AND t.workspace_id=p_workspace_id
        AND t.status IN ('running','requires_action','recovering','waiting_capacity')
        AND a.id=(p_actor->>'attemptId')::uuid AND a.account_id=p_account_id AND a.workspace_id=p_workspace_id
        AND a.session_id=s.id AND a.execution_generation=(p_actor->>'executionGeneration')::integer
        AND t.execution_generation=a.execution_generation AND a.state IN ('claimed','running')
        AND NOT EXISTS (SELECT 1 FROM session_attempt_interruptions i WHERE i.workspace_id=p_workspace_id
          AND i.attempt_id=a.id AND i.state IN ('pending','delivered','acknowledged'))
      FOR SHARE OF s,t,a;
    IF NOT FOUND THEN RAISE EXCEPTION 'Skill write requires exact live attempt' USING ERRCODE='42501'; END IF;
    actor_subject := 'service:skill-attempt:' || (p_actor->>'attemptId');
  ELSIF p_actor->>'kind' = 'human' AND p_actor->>'principalKind' = 'human_session'
    AND p_actor->>'subjectId' = nullif(current_setting('opengeni.subject_id',true),'')
    AND current_setting('opengeni.principal_kind',true) = 'human_session' THEN
    actor_subject := p_actor->>'subjectId';
  ELSIF p_actor->>'kind' = 'service' AND operation = 'install' AND scope = 'workspace'
    AND p_actor->>'principalKind' IN ('service','api_key','configured_key')
    AND p_actor->>'subjectId' = nullif(current_setting('opengeni.subject_id',true),'')
    AND p_actor->>'principalKind' = current_setting('opengeni.principal_kind',true) THEN
    actor_subject := p_actor->>'subjectId';
  ELSE RAISE EXCEPTION 'Skill lifecycle actor is not authorized' USING ERRCODE='42501'; END IF;

  IF operation='confirm_response' THEN
    IF p_actor->>'kind' <> 'human' THEN
      RAISE EXCEPTION 'Skill chat confirmation requires verified human response admission' USING ERRCODE='42501';
    END IF;
    SELECT * INTO confirmation_source FROM skill_write_receipts r
      WHERE r.account_id=p_account_id AND r.workspace_id=p_workspace_id
        AND r.operation_id=(p_request->>'sourceOperationId')::uuid;
    skill_review := confirmation_source.receipt->'skillReview';
    IF NOT FOUND OR skill_review IS NULL OR confirmation_source.actor->>'kind'<>'agent'
 THEN
      RAISE EXCEPTION 'Skill confirmation source unavailable' USING ERRCODE='42501';
    END IF;
    SELECT coalesce(t.initiating_human_subject_id, CASE WHEN t.initiator_kind='subject' THEN t.initiator_subject_id END),
      t.execution_generation INTO initiating_human,confirmation_generation
      FROM session_turns t JOIN sessions session ON session.active_turn_id=t.id AND session.id=t.session_id
      JOIN session_human_input_requests response_request ON response_request.session_id=t.session_id
        AND response_request.turn_id=t.id AND response_request.account_id=p_account_id
        AND response_request.workspace_id=p_workspace_id
        AND response_request.id=(p_request->>'humanInputRequestId')::uuid
      WHERE t.id=(confirmation_source.actor->>'turnId')::uuid
        AND t.session_id=(confirmation_source.actor->>'sessionId')::uuid AND t.workspace_id=p_workspace_id
        AND t.account_id=p_account_id AND session.workspace_id=p_workspace_id AND session.account_id=p_account_id
        AND t.status IN ('running','requires_action','recovering','waiting_capacity')
      FOR SHARE OF t,session;
    IF initiating_human IS NULL OR initiating_human IS DISTINCT FROM p_actor->>'subjectId' OR NOT (
      EXISTS(SELECT 1 FROM workspace_memberships m WHERE m.workspace_id=p_workspace_id AND m.subject_id=initiating_human)
      OR EXISTS(SELECT 1 FROM organization_memberships m WHERE m.account_id=p_account_id
        AND m.subject_id=initiating_human AND m.status='active' AND m.personal_workspace_id=p_workspace_id)
    ) OR EXISTS(SELECT 1 FROM organization_memberships m WHERE m.account_id=p_account_id
      AND m.subject_id=initiating_human AND m.status<>'active') THEN
      RAISE EXCEPTION 'Skill confirming human no longer has workspace authority' USING ERRCODE='42501';
    END IF;
    SELECT answer->'values'->>0 INTO human_choice
      FROM session_human_input_requests h
      CROSS JOIN LATERAL jsonb_array_elements(h.response->'answers') answer
      WHERE h.id=(p_request->>'humanInputRequestId')::uuid AND h.account_id=p_account_id AND h.workspace_id=p_workspace_id
        AND h.session_id=(confirmation_source.actor->>'sessionId')::uuid AND h.turn_id=(confirmation_source.actor->>'turnId')::uuid
        AND h.turn_generation >= (confirmation_source.actor->>'executionGeneration')::integer
        AND h.turn_generation <= confirmation_generation AND h.status='answered' AND h.responded_by=initiating_human
        AND h.skill_review_human_authorized AND h.allow_skip=false
        AND h.response->>'outcome'='answered'
        AND jsonb_array_length(h.questions)=1 AND jsonb_array_length(h.response->'answers')=1
        AND h.questions->0->>'id'='skill:'||(skill_review->>'revisionId')
        AND h.questions->0->>'kind'='single_select'
        AND h.questions->0->>'label'=CASE WHEN skill_review ? 'removalOperationId' THEN 'Permanently delete this Skill?' ELSE 'Save this Skill?' END
        AND h.questions->0->>'helpText'=CASE WHEN skill_review ? 'removalOperationId' THEN 'This cannot be undone. All stored Skill revisions will be deleted; conversations remain unchanged.' ELSE 'Review the complete files before saving. Saving activates this revision immediately.' END
        AND h.questions->0->'required'='true'::jsonb
        AND coalesce(h.questions->0->'allowOther','false'::jsonb) IN ('false'::jsonb,'true'::jsonb)
        AND (answer->'other' IS NULL OR answer->'other'='null'::jsonb OR answer->'other'='""'::jsonb)
        AND h.responded_at IS NOT NULL AND h.created_at >= confirmation_source.created_at
        AND (h.expires_at IS NULL OR h.responded_at <= h.expires_at)
        AND h.questions->0->>'prompt'=CASE WHEN skill_review ? 'removalOperationId' THEN 'Permanently delete this Skill and all its stored revisions?' ELSE 'Save this exact Skill revision for this workspace?' END
        AND h.questions->0->'skillReview'=skill_review
        AND jsonb_array_length(h.questions->0->'options')=2
        AND ((h.questions->0->'options'->0) - 'description')=CASE WHEN skill_review ? 'removalOperationId' THEN '{"id":"save","label":"Permanently delete"}'::jsonb ELSE '{"id":"save","label":"Save"}'::jsonb END
        AND ((h.questions->0->'options'->1) - 'description')=CASE WHEN skill_review ? 'removalOperationId' THEN '{"id":"skip","label":"Keep Skill"}'::jsonb ELSE '{"id":"skip","label":"Don''t save"}'::jsonb END
        AND coalesce(h.questions->0->'options'->0->'description','null'::jsonb)='null'::jsonb
        AND coalesce(h.questions->0->'options'->1->'description','null'::jsonb)='null'::jsonb
        AND answer->>'questionId'='skill:'||(skill_review->>'revisionId')
        AND answer->'values' IN ('["save"]'::jsonb,'["skip"]'::jsonb)
      FOR SHARE OF h;
    IF NOT FOUND THEN RAISE EXCEPTION 'Exact human Skill confirmation unavailable' USING ERRCODE='42501'; END IF;
    skill_id := (skill_review->>'skillId')::uuid;
    p_request := p_request || skill_review || jsonb_build_object('operationId',operation_id,
      'reason','Approved once by the initiating human in chat');
    operation := CASE WHEN human_choice='skip' THEN 'reject' ELSE 'approve' END;
    actor_subject := initiating_human;
  END IF;
  fingerprint := encode(sha256(convert_to(jsonb_build_array(p_actor,p_request)::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('skill-operation:'||p_workspace_id||':'||operation_id,0));
  SELECT * INTO prior FROM skill_write_receipts r WHERE r.workspace_id=p_workspace_id AND r.operation_id=lifecycle.operation_id;
  IF FOUND THEN
    IF prior.fingerprint <> fingerprint OR prior.account_id <> p_account_id THEN
      RAISE EXCEPTION 'Skill operation key reused with different input' USING ERRCODE='23505'; END IF;
    RETURN (prior.receipt - 'portableInstall' - 'deferredPublication') || jsonb_build_object('replayed',true);
  END IF;
  IF p_actor->>'kind' IN ('agent','service') THEN
    learning_policy:=coalesce(learning_policy,knowledge_learning_resolve(p_account_id,p_workspace_id,NULL,'defaults',transaction_timestamp()));
    mode:=learning_policy#>>'{effective,skills}';
    IF mode='review_first' THEN mode:='suggest'; END IF;
    IF mode = 'off' THEN RAISE EXCEPTION 'Learning is Off; durable Skill changes are refused' USING ERRCODE='42501'; END IF;
  END IF;

  IF original_operation='confirm_response' THEN mode := 'automatic'; END IF;

  IF operation = 'install' THEN
    SELECT f.facet_key, f.activation_mode, v.plugin_id, sf.*, coalesce(jsonb_agg(jsonb_build_object('path',ff.path,'content',ff.content) ORDER BY ff.path COLLATE "C")
      FILTER (WHERE ff.id IS NOT NULL),'[]'::jsonb) AS files INTO source
      FROM capability_skill_facets sf JOIN capability_facets f ON f.id=sf.facet_id
      JOIN capability_plugin_versions v ON v.id=f.plugin_version_id
      JOIN capability_plugin_installations i ON i.plugin_version_id=v.id AND i.plugin_id=v.plugin_id
      JOIN capability_facet_installations fi ON fi.plugin_installation_id=i.id AND fi.facet_id=f.id AND fi.status='active'
      LEFT JOIN capability_skill_files ff ON ff.skill_facet_id=sf.facet_id
      WHERE sf.facet_id=(p_request->>'skillFacetId')::uuid AND i.account_id=p_account_id
        AND i.workspace_id=p_workspace_id AND i.status='active'
      GROUP BY f.facet_key,f.activation_mode,v.plugin_id,sf.facet_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Skill source is not installed in this workspace' USING ERRCODE='42501'; END IF;
    source_effective := skill_source_has_effective_owner(p_account_id,p_workspace_id,source.facet_id);
    PERFORM pg_advisory_xact_lock(hashtextextended('skill-source:'||p_workspace_id||':'||source.plugin_id||':'||source.facet_key,0));
    SELECT * INTO binding FROM skill_source_bindings b WHERE b.workspace_id=p_workspace_id
      AND b.plugin_id=source.plugin_id AND b.facet_key=source.facet_key;
    skill_id := coalesce(binding.preference_id,gen_random_uuid());
    files := source.files; title := p_request->>'title'; description := p_request->>'description';
    stable_key := 'installed-'||replace(skill_id::text,'-',''); source_id := source.facet_id::text;
    activation_mode := source.activation_mode;
  END IF;
  -- Distribution removals acquire facet/owner rows before the Skill head.
  -- NOWAIT also prevents a publication-lock/facet-lock cycle with installation.
  -- Contention aborts atomically; the caller can retry the same operation.
  IF operation='remove' OR p_request ? 'removalOperationId' THEN
    PERFORM fi.id FROM capability_facet_installations fi JOIN skill_source_bindings b
      ON b.skill_facet_id=fi.facet_id AND b.workspace_id=fi.workspace_id
      WHERE b.preference_id=skill_id AND b.account_id=p_account_id AND b.workspace_id=p_workspace_id
      ORDER BY fi.id FOR UPDATE OF fi NOWAIT;
    PERFORM o.id FROM capability_component_owners o JOIN capability_facet_installations fi ON fi.id=o.facet_installation_id
      JOIN skill_source_bindings b ON b.skill_facet_id=fi.facet_id AND b.workspace_id=fi.workspace_id
      WHERE b.preference_id=skill_id AND b.account_id=p_account_id AND b.workspace_id=p_workspace_id
      ORDER BY o.id FOR UPDATE OF o NOWAIT;
  END IF;
  SELECT * INTO head FROM preference_registry_preferences h WHERE h.id=skill_id AND h.account_id=p_account_id FOR UPDATE;
  IF FOUND THEN
    IF p_actor->>'kind'='agent' AND head.scope<>scope THEN
      IF p_request ? 'scope' THEN
        RAISE EXCEPTION 'Skill scope differs from the requested scope' USING ERRCODE='42501'; END IF;
      -- A personal Skill stays out of reach of a chat that does not learn for
      -- its owner; the head check below still fences another person's Skill.
      IF operation='remove' OR NOT ((head.scope='workspace' AND scope='user')
        OR (head.scope='user' AND scope='workspace' AND learning_actor->>'subjectId' IS NOT NULL)) THEN
        RAISE EXCEPTION 'Skill outside accepted learning scope' USING ERRCODE='42501'; END IF;
      -- The head check below still refuses another person's personal Skill.
      scope:=head.scope;
    END IF;
    scope := head.scope;
    IF operation <> 'install' THEN
      SELECT coalesce(r.skill_activation_mode,'workspace_managed') INTO activation_mode
        FROM preference_registry_revisions r WHERE r.preference_id=head.id
        ORDER BY (r.id=head.active_revision_id) DESC NULLS LAST,r.revision DESC LIMIT 1;
    END IF;
    IF (p_actor->>'kind'='service' AND (head.scope<>'workspace' OR head.scope_workspace_id<>p_workspace_id))
      OR (p_actor->>'kind'='agent' AND ((head.scope='workspace' AND head.scope_workspace_id<>p_workspace_id)
        OR (head.scope='user' AND head.scope_subject_id IS DISTINCT FROM learning_actor->>'subjectId')))
      OR (p_actor->>'kind' = 'human' AND NOT opengeni_private.preference_registry_scope_visible(
        head.account_id,head.scope,head.scope_workspace_id,head.scope_subject_id)) THEN
      RAISE EXCEPTION 'Skill is outside authorized scope' USING ERRCODE='42501'; END IF;
    IF operation = 'install' THEN
      SELECT * INTO rev FROM preference_registry_revisions WHERE id=head.active_revision_id;
      IF head.active_revision_id IS NOT NULL AND (rev.provenance_source <> 'portable_skill' OR rev.provenance_source_id=source_id) THEN
        revision_id := head.active_revision_id; outcome := 'preserved';
      END IF;
    ELSIF head.active_revision_id IS DISTINCT FROM (p_request->>'expectedRevisionId')::uuid
      OR head.scope_version IS DISTINCT FROM (p_request->>'expectedScopeVersion')::integer THEN
      RAISE EXCEPTION 'Skill head changed' USING ERRCODE='40001';
    END IF;
    IF head.status IN ('rejected','superseded') THEN RAISE EXCEPTION 'Skill head is retired' USING ERRCODE='23514'; END IF;
  ELSE
    IF operation NOT IN ('save','install') OR (p_request->>'expectedRevisionId') IS NOT NULL
      OR (operation='save' AND (p_request->>'expectedScopeVersion')::integer IS DISTINCT FROM 1) THEN
      RAISE EXCEPTION 'Skill head missing or changed' USING ERRCODE='40001'; END IF;
    INSERT INTO preference_registry_preferences(id,account_id,stable_key,scope,scope_workspace_id,scope_subject_id,created_by_subject_id)
      VALUES(skill_id,p_account_id,stable_key,scope,CASE WHEN scope='workspace' THEN p_workspace_id END,
        CASE WHEN scope='user' THEN coalesce(learning_actor->>'subjectId',actor_subject) END,actor_subject) RETURNING * INTO head;
  END IF;
  IF p_actor->>'kind'='agent' AND learning_actor->>'defaultScope'='personal' AND scope='workspace'
    AND get_workspace_kind(p_account_id,p_workspace_id)<>'personal' THEN
    mode:=CASE WHEN mode='suggest' THEN 'review_first' ELSE mode END;
    mode:=(SELECT CASE WHEN 'off' IN (mode,m) OR m IS NULL THEN 'off'
        WHEN 'review_first' IN (mode,m) THEN 'review_first' ELSE 'automatic' END
      FROM (SELECT knowledge_learning_resolve(p_account_id,p_workspace_id,NULL,
        coalesce(learning_policy->>'contextKey','defaults'),
        coalesce((learning_policy->>'acceptedAt')::timestamptz,transaction_timestamp()))#>>'{effective,skills}' AS m) workspace_policy);
    IF mode='off' THEN RAISE EXCEPTION 'Learning is Off; durable Skill changes are refused' USING ERRCODE='42501'; END IF;
    IF mode='review_first' THEN mode:='suggest'; END IF;
  END IF;
  IF p_actor->>'kind'='agent' AND learning_actor->>'defaultScope'='workspace' AND scope='user' THEN
    mode:=CASE WHEN mode='suggest' THEN 'review_first' ELSE mode END;
    mode:=(SELECT CASE WHEN 'off' IN (mode,m) OR m IS NULL THEN 'off'
        WHEN 'review_first' IN (mode,m) THEN 'review_first' ELSE 'automatic' END
      FROM (SELECT knowledge_learning_resolve(p_account_id,p_workspace_id,learning_actor->>'subjectId',
        coalesce(learning_policy->>'contextKey','defaults'),
        coalesce((learning_policy->>'acceptedAt')::timestamptz,transaction_timestamp()))#>>'{effective,skills}' AS m) personal_policy);
    IF mode='off' THEN RAISE EXCEPTION 'Learning is Off; durable Skill changes are refused' USING ERRCODE='42501'; END IF;
    IF mode='review_first' THEN mode:='suggest'; END IF;
  END IF;

  -- Marked proposals are never ordinary approvals/restores. The reviewer must
  -- explicitly supply the immutable removal operation id displayed by the UI.
  SELECT * INTO rev FROM preference_registry_revisions r
    WHERE r.account_id=p_account_id AND r.preference_id=skill_id
      AND r.id=(p_request->>'revisionId')::uuid;
  IF rev.skill_removal_operation_id IS NOT NULL AND operation<>'remove' THEN
    IF operation NOT IN ('approve','reject')
      OR rev.skill_removal_operation_id IS DISTINCT FROM (p_request->>'removalOperationId')::uuid THEN
      RAISE EXCEPTION 'Removal requires explicit exact deletion approval' USING ERRCODE='42501'; END IF;
    SELECT * INTO confirmation_source FROM skill_write_receipts r
      WHERE r.account_id=p_account_id AND r.workspace_id=p_workspace_id
        AND r.operation_id=rev.skill_removal_operation_id;
    IF NOT FOUND OR confirmation_source.receipt->>'outcome'<>'pending'
      OR confirmation_source.receipt#>>'{skillReview,revisionId}' IS DISTINCT FROM rev.id::text
      OR (confirmation_source.receipt#>>'{skillReview,expectedRevisionId}')::uuid IS DISTINCT FROM head.active_revision_id
      OR (confirmation_source.receipt#>>'{skillReview,expectedScopeVersion}')::integer IS DISTINCT FROM head.scope_version
      OR EXISTS(SELECT 1 FROM preference_registry_revisions r WHERE r.preference_id=skill_id AND r.revision>rev.revision)
      OR EXISTS(SELECT 1 FROM preference_registry_events e WHERE e.preference_id=skill_id AND e.new_revision_id=rev.id AND e.type='rejected')
    THEN RAISE EXCEPTION 'Skill removal proposal changed or settled' USING ERRCODE='40001'; END IF;
  ELSIF p_request ? 'removalOperationId' THEN
    RAISE EXCEPTION 'Removal approval does not match a removal proposal' USING ERRCODE='42501';
  END IF;
  IF operation='remove' OR rev.skill_removal_operation_id IS NOT NULL THEN
    IF head.scope NOT IN ('workspace','user') THEN
      RAISE EXCEPTION 'Permanent removal does not manage organization Skills' USING ERRCODE='42501'; END IF;
    IF operation='remove' THEN
      SELECT * INTO rev FROM preference_registry_revisions r WHERE r.preference_id=skill_id AND r.account_id=p_account_id
        ORDER BY r.revision DESC LIMIT 1;
      IF NOT FOUND THEN RAISE EXCEPTION 'Skill revision unavailable' USING ERRCODE='40001'; END IF;
    END IF;
    revision_id:=rev.id;
    IF operation='remove' AND mode<>'automatic' THEN
      -- A distinct immutable proposal binds the complete revision inventory.
      INSERT INTO preference_registry_revisions(account_id,preference_id,title,description,content,content_hash,
        conflict_strategy,provenance_source,provenance_source_id,trust,created_by_subject_id,
        corrects_revision_id,skill_files,skill_activation_mode,skill_removal_operation_id)
      VALUES(p_account_id,skill_id,rev.title,rev.description,rev.content,rev.content_hash,
        'override','agent',p_actor->>'attemptId','untrusted_proposal',actor_subject,
        head.active_revision_id,rev.skill_files,rev.skill_activation_mode,operation_id) RETURNING id INTO revision_id;
      outcome:='pending';
    ELSIF operation='reject' THEN
      SELECT coalesce(max(e.version),0)+1 INTO next_event FROM preference_registry_events e WHERE e.preference_id=skill_id;
      INSERT INTO preference_registry_events(account_id,preference_id,type,version,new_revision_id,actor_subject_id,reason)
        VALUES(p_account_id,skill_id,'rejected',next_event,revision_id,actor_subject,p_request->>'reason');
      outcome:='preserved';
    ELSE
      -- Shared/composite distribution cannot be silently dismantled. Direct
      -- installations are scoped to this one facet; other facets remain intact.
      IF EXISTS(SELECT 1 FROM skill_source_bindings b JOIN capability_facet_installations fi
        ON fi.facet_id=b.skill_facet_id AND fi.workspace_id=b.workspace_id
        JOIN capability_component_owners o ON o.facet_installation_id=fi.id
        WHERE b.preference_id=skill_id AND (o.owner_kind<>'direct' OR NOT o.removable)) THEN
        RAISE EXCEPTION 'Skill has another distribution owner; release it before permanent removal' USING ERRCODE='42501'; END IF;
      DELETE FROM capability_facet_installations fi USING skill_source_bindings b
        WHERE b.preference_id=skill_id AND b.account_id=p_account_id AND b.workspace_id=p_workspace_id
          AND fi.facet_id=b.skill_facet_id AND fi.account_id=p_account_id AND fi.workspace_id=p_workspace_id;
      PERFORM set_config('opengeni.skill_remove_head',skill_id::text,true);
      DELETE FROM company_brain_preference_proposal_receipts r
        WHERE r.account_id=p_account_id AND r.workspace_id=p_workspace_id AND r.preference_id=skill_id;
      DELETE FROM preference_registry_preferences WHERE id=skill_id AND account_id=p_account_id;
      PERFORM set_config('opengeni.skill_remove_head','',true);
      outcome:='applied';
    END IF;
    result:=jsonb_build_object('operationId',operation_id,'skillId',skill_id,'revisionId',revision_id,
      'outcome',outcome,'removed',outcome='applied','removedScope',head.scope,'replayed',false);
    IF outcome='pending' THEN result:=result||jsonb_build_object('pendingReason','approval','skillReview',
      jsonb_build_object('sourceOperationId',operation_id,'removalOperationId',operation_id,'skillId',skill_id,
        'revisionId',revision_id,'expectedRevisionId',head.active_revision_id,'expectedScopeVersion',head.scope_version)); END IF;
    IF operation='reject' THEN result:=result||jsonb_build_object('decision','rejected'); END IF;
    INSERT INTO skill_write_receipts(account_id,workspace_id,operation_id,fingerprint,actor,receipt)
      VALUES(p_account_id,p_workspace_id,operation_id,fingerprint,p_actor,result);
    RETURN result;
  END IF;

  IF outcome IS NULL THEN
    IF operation IN ('approve','restore','reject') THEN
      SELECT * INTO rev FROM preference_registry_revisions r WHERE r.id=(p_request->>'revisionId')::uuid
        AND r.account_id=p_account_id AND r.preference_id=skill_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Skill revision unavailable' USING ERRCODE='42501'; END IF;
      IF operation IN ('approve','reject') AND EXISTS(SELECT 1 FROM preference_registry_revisions newer
        WHERE newer.preference_id=skill_id AND newer.revision>rev.revision) THEN
        RAISE EXCEPTION 'Skill changed after chat proposal' USING ERRCODE='40001';
      END IF;
      IF operation IN ('approve','reject') AND (
        (operation='reject' AND rev.id=head.active_revision_id)
        OR EXISTS(SELECT 1 FROM preference_registry_events event
          WHERE event.preference_id=skill_id AND event.new_revision_id=rev.id AND event.type='rejected')
      ) THEN RAISE EXCEPTION 'Skill proposal was already settled' USING ERRCODE='40001'; END IF;
      files := coalesce(rev.skill_files,jsonb_build_array(jsonb_build_object('path','SKILL.md','content',rev.content)));
      title := p_request->>'title'; description := p_request->>'description';
      activation_mode := coalesce(rev.skill_activation_mode,'workspace_managed');
      IF operation='approve' AND rev.provenance_source='portable_skill' AND EXISTS(
        SELECT 1 FROM skill_source_bindings b WHERE b.preference_id=skill_id AND b.account_id=p_account_id
          AND NOT skill_source_has_effective_owner(p_account_id,b.workspace_id,rev.provenance_source_id::uuid)) THEN
        RAISE EXCEPTION 'Skill approval requires a finalized source owner' USING ERRCODE='42501';
      END IF;
    END IF;
    IF NOT skill_files_valid(files) THEN RAISE EXCEPTION 'Invalid Skill text folder' USING ERRCODE='22023'; END IF;
    SELECT f->>'content' INTO main_content FROM jsonb_array_elements(files) f WHERE f->>'path'='SKILL.md';
    IF operation IN ('approve','reject') THEN revision_id := rev.id;
    ELSE
      INSERT INTO preference_registry_revisions(account_id,preference_id,title,description,content,content_hash,
        conflict_strategy,provenance_source,provenance_source_id,trust,created_by_subject_id,corrects_revision_id,skill_files,skill_activation_mode)
      VALUES(p_account_id,skill_id,title,description,main_content,encode(sha256(convert_to(main_content,'UTF8')),'hex'),
        'override',CASE WHEN operation='install' THEN 'portable_skill' WHEN p_actor->>'kind'='agent' THEN 'agent' ELSE 'human' END,
        CASE WHEN operation='install' THEN source_id WHEN p_actor->>'kind'='agent' THEN p_actor->>'attemptId' END,
        CASE WHEN p_actor->>'kind' IN ('agent','service') THEN 'untrusted_proposal' WHEN scope='user' THEN 'personal'
          WHEN scope='organization' THEN 'organization_managed' ELSE 'workspace_managed' END,
        actor_subject,head.active_revision_id,files,activation_mode) RETURNING id INTO revision_id;
    END IF;
    SELECT coalesce(max(e.version),0)+1 INTO next_event FROM preference_registry_events e WHERE e.preference_id=skill_id;
    IF next_event=1 THEN
      INSERT INTO preference_registry_events(account_id,preference_id,type,version,new_revision_id,new_scope,new_workspace_id,new_subject_id,actor_subject_id,reason)
      VALUES(p_account_id,skill_id,'proposal_created',next_event,revision_id,head.scope,head.scope_workspace_id,head.scope_subject_id,actor_subject,p_request->>'reason');
      next_event := next_event+1;
    END IF;
    IF mode='automatic' AND operation='install' AND NOT source_effective THEN
      deferred_publication := jsonb_build_object('expectedRevisionId',head.active_revision_id,
        'expectedScopeVersion',head.scope_version,'sourceFacetId',source.facet_id);
    END IF;
    IF operation='reject' THEN
      INSERT INTO preference_registry_events(account_id,preference_id,type,version,new_revision_id,actor_subject_id,reason)
        VALUES(p_account_id,skill_id,'rejected',next_event,revision_id,actor_subject,coalesce(p_request->>'reason','Declined during review'));
      outcome := 'preserved';
    ELSIF mode='automatic' AND deferred_publication IS NULL THEN
      PERFORM set_config('opengeni.preference_lifecycle_head_id',skill_id::text,true);
      PERFORM set_config('opengeni.preference_lifecycle_operation','activate',true);
      UPDATE preference_registry_preferences h SET status='active',active_revision_id=revision_id,
        active_revision=r.revision,active_content_hash=r.content_hash,activation_version=h.activation_version+1,updated_at=clock_timestamp()
        FROM preference_registry_revisions r WHERE h.id=skill_id AND r.id=revision_id;
      INSERT INTO preference_registry_events(account_id,preference_id,type,version,old_revision_id,new_revision_id,actor_subject_id,reason)
        VALUES(p_account_id,skill_id,'activated',next_event,head.active_revision_id,revision_id,actor_subject,p_request->>'reason') RETURNING id INTO activation_event_id;
      outcome := 'applied';
    ELSE outcome := 'pending'; END IF;
    IF operation='install' THEN
      INSERT INTO skill_source_bindings VALUES(p_account_id,p_workspace_id,source.plugin_id,source.facet_key,skill_id,source.facet_id)
      ON CONFLICT(workspace_id,plugin_id,facet_key) DO UPDATE SET skill_facet_id=excluded.skill_facet_id;
    END IF;
  END IF;
  IF operation='install' AND outcome='preserved' THEN
    UPDATE skill_source_bindings b SET skill_facet_id=source.facet_id
      WHERE b.workspace_id=p_workspace_id AND b.plugin_id=source.plugin_id AND b.facet_key=source.facet_key;
  END IF;
  result := jsonb_build_object('operationId',operation_id,'skillId',skill_id,'revisionId',revision_id,'outcome',outcome,'replayed',false);
  IF operation='reject' THEN result := result || jsonb_build_object('decision','rejected'); END IF;
  IF outcome='pending' AND deferred_publication IS NULL AND p_actor->>'kind'='agent' THEN
    result := result || jsonb_build_object('pendingReason','approval','skillReview',
      jsonb_build_object('sourceOperationId',operation_id,'skillId',skill_id,'revisionId',revision_id,
        'expectedRevisionId',head.active_revision_id,'expectedScopeVersion',head.scope_version));
  END IF;
  IF deferred_publication IS NOT NULL THEN result := result || jsonb_build_object('pendingReason','source_finalization'); END IF;
  IF learning_policy IS NOT NULL THEN result:=result||jsonb_build_object('learningPolicy',learning_policy); END IF;
  INSERT INTO skill_write_receipts(account_id,workspace_id,operation_id,fingerprint,actor,receipt,activation_event_id)
    VALUES(p_account_id,p_workspace_id,operation_id,fingerprint,p_actor,
      (CASE WHEN operation='install' AND p_request ? 'portableInstall'
        THEN result || jsonb_build_object('portableInstall',p_request->'portableInstall') ELSE result END)
      || CASE WHEN deferred_publication IS NOT NULL THEN jsonb_build_object('deferredPublication',deferred_publication) ELSE '{}'::jsonb END,
      activation_event_id);
  RETURN result;
END $$;

CREATE FUNCTION skill_files_valid(files jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE f jsonb; paths text[] := '{}'; total integer := 0; bytes integer;
BEGIN
  IF files IS NULL OR jsonb_typeof(files) <> 'array' OR jsonb_array_length(files) NOT BETWEEN 1 AND 1024 THEN RETURN false; END IF;
  FOR f IN SELECT value FROM jsonb_array_elements(files) LOOP
    IF jsonb_typeof(f) <> 'object' OR jsonb_typeof(f->'path') IS DISTINCT FROM 'string'
      OR (f - 'path' - 'content') <> '{}'::jsonb
      OR jsonb_typeof(f->'content') IS DISTINCT FROM 'string' OR length(f->>'path') NOT BETWEEN 1 AND 512
      OR f->>'path' ~ '(^/|\\|(^|/)\.\.?(/|$)|//|/$|[[:cntrl:]]|:)'
      OR f->>'path' = ANY(paths)
      OR EXISTS (SELECT 1 FROM unnest(paths) existing WHERE starts_with(f->>'path', existing||'/') OR starts_with(existing, (f->>'path')||'/'))
      THEN RETURN false; END IF;
    bytes := octet_length(convert_to(f->>'content', 'UTF8'));
    IF bytes > 2097152 THEN RETURN false; END IF;
    total := total + bytes; paths := array_append(paths, f->>'path');
  END LOOP;
  RETURN total <= 8388608 AND 'SKILL.md' = ANY(paths)
    AND EXISTS (SELECT 1 FROM jsonb_array_elements(files) entry WHERE entry->>'path' = 'SKILL.md' AND length(btrim(entry->>'content')) > 0);
END $_$;

CREATE FUNCTION skill_guard_legacy_activation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF NEW.active_revision_id IS NOT NULL THEN
    IF (TG_OP='INSERT' OR NEW.active_revision_id IS DISTINCT FROM OLD.active_revision_id)
      AND EXISTS(SELECT 1 FROM preference_registry_revisions target JOIN skill_source_bindings binding
        ON binding.preference_id=target.preference_id AND binding.account_id=target.account_id
        WHERE target.id=NEW.active_revision_id AND target.provenance_source='portable_skill'
          AND NOT skill_source_has_effective_owner(binding.account_id,binding.workspace_id,target.provenance_source_id::uuid)) THEN
      RAISE EXCEPTION 'Skill activation requires a finalized source owner' USING ERRCODE='42501';
    END IF;
    IF EXISTS(SELECT 1 FROM preference_registry_revisions target
      WHERE target.account_id=NEW.account_id AND target.preference_id=NEW.id
        AND target.id=NEW.active_revision_id AND target.skill_files IS NULL) THEN
      RAISE EXCEPTION 'Skill folder activation requires a files-bearing revision; use unified restore' USING ERRCODE='55000';
    END IF;
  END IF;
  IF NEW.active_revision_id IS NOT NULL AND EXISTS(
    SELECT 1 FROM preference_registry_revisions WHERE id=NEW.active_revision_id AND skill_removal_operation_id IS NOT NULL)
  THEN RAISE EXCEPTION 'A removal proposal cannot be activated as Skill content' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION skill_guard_legacy_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF NEW.skill_files IS NULL THEN
    RAISE EXCEPTION 'Skill folder saves require the unified file lifecycle' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION skill_publish_finalized_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  publication_owner_kind text := 'plugin';
  pending record; head preference_registry_preferences%ROWTYPE; revision preference_registry_revisions%ROWTYPE;
  publication_id uuid; publication_hash text; publication_operation uuid; expected_fingerprint text; event_id uuid;
  next_event integer; result jsonb; disposition text; current_mode text; parent_target text;
  publication_actor jsonb := jsonb_build_object('kind','service','subjectId','service:skill-publication','principalKind','service');
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('skill-publication:'||NEW.workspace_id,0));
  FOR pending IN
    SELECT DISTINCT receipt.* FROM skill_write_receipts receipt
    JOIN skill_source_bindings binding ON binding.preference_id=(receipt.receipt->>'skillId')::uuid
      AND binding.account_id=receipt.account_id AND binding.workspace_id=receipt.workspace_id
    JOIN capability_facet_installations fi ON fi.facet_id=binding.skill_facet_id
      AND fi.account_id=binding.account_id AND fi.workspace_id=binding.workspace_id
    JOIN capability_component_owners owner ON owner.facet_installation_id=fi.id
      AND owner.account_id=fi.account_id AND owner.workspace_id=fi.workspace_id
    WHERE receipt.account_id=NEW.account_id AND receipt.workspace_id=NEW.workspace_id
      AND receipt.receipt ? 'deferredPublication' AND owner.owner_kind=publication_owner_kind AND owner.owner_id=NEW.id::text
    ORDER BY receipt.created_at,receipt.operation_id
  LOOP
    publication_hash := md5('skill-publication:'||pending.operation_id);
    publication_id := (substr(publication_hash,1,12)||'5'||substr(publication_hash,14,3)||'a'||substr(publication_hash,18,15))::uuid;
    expected_fingerprint := encode(sha256(convert_to('skill-publication:'||pending.fingerprint,'UTF8')),'hex');
    IF EXISTS(SELECT 1 FROM skill_write_receipts existing WHERE existing.workspace_id=NEW.workspace_id AND existing.operation_id=publication_id) THEN
      IF NOT EXISTS(SELECT 1 FROM skill_write_receipts existing WHERE existing.workspace_id=NEW.workspace_id AND existing.operation_id=publication_id
        AND existing.fingerprint=expected_fingerprint AND existing.receipt->>'sourceOperationId'=pending.operation_id::text) THEN
        RAISE EXCEPTION 'Skill publication operation identity collision' USING ERRCODE='23505';
      END IF;
      CONTINUE;
    END IF;
    publication_operation := nullif(current_setting('opengeni.skill_publication_operation_id',true),'')::uuid;
    SELECT plugin_key INTO parent_target FROM capability_plugins WHERE id=NEW.plugin_id;
    IF publication_operation IS NULL OR NOT EXISTS(SELECT 1 FROM capability_operations operation
      WHERE operation.id=publication_operation AND operation.account_id=NEW.account_id AND operation.workspace_id=NEW.workspace_id
        AND operation.target_kind=publication_owner_kind AND operation.target_id=parent_target AND operation.status='running') THEN
      RAISE EXCEPTION 'Skill publication requires a claimed parent finalization' USING ERRCODE='42501';
    END IF;
    SELECT * INTO head FROM preference_registry_preferences WHERE id=(pending.receipt->>'skillId')::uuid AND account_id=NEW.account_id FOR UPDATE;
    SELECT * INTO revision FROM preference_registry_revisions WHERE id=(pending.receipt->>'revisionId')::uuid AND account_id=NEW.account_id;
    disposition := 'preserved'; event_id := NULL; current_mode := 'automatic';
    IF pending.actor->>'kind' <> 'human' THEN
      -- Deferred publication uses its original accepted policy. Historical
      -- receipts receive no new automatic authority during migration.
      current_mode:=coalesce(pending.receipt#>>'{learningPolicy,effective,skills}','review_first');
      IF current_mode='review_first' THEN current_mode:='suggest'; END IF;
    END IF;
    IF pending.actor->>'kind'='agent' THEN
      PERFORM 1 FROM sessions session JOIN session_turns turn ON turn.id=session.active_turn_id AND turn.session_id=session.id
        JOIN session_turn_attempts attempt ON attempt.id=turn.active_attempt_id AND attempt.turn_id=turn.id
      WHERE session.id=(pending.actor->>'sessionId')::uuid AND session.account_id=NEW.account_id AND session.workspace_id=NEW.workspace_id
        AND turn.id=(pending.actor->>'turnId')::uuid AND turn.account_id=NEW.account_id AND turn.workspace_id=NEW.workspace_id
        AND turn.status IN ('running','requires_action','recovering','waiting_capacity')
        AND attempt.id=(pending.actor->>'attemptId')::uuid AND attempt.account_id=NEW.account_id AND attempt.workspace_id=NEW.workspace_id
        AND attempt.session_id=session.id AND attempt.execution_generation=(pending.actor->>'executionGeneration')::integer
        AND turn.execution_generation=attempt.execution_generation AND attempt.state IN ('claimed','running')
        AND NOT EXISTS(SELECT 1 FROM session_attempt_interruptions interruption WHERE interruption.workspace_id=NEW.workspace_id
          AND interruption.attempt_id=attempt.id AND interruption.state IN ('pending','delivered','acknowledged'))
      FOR SHARE OF session,turn,attempt;
      IF NOT FOUND THEN current_mode := 'suggest'; END IF;
    END IF;
    IF head.status NOT IN ('rejected','superseded') AND head.scope='workspace' AND head.scope_workspace_id=NEW.workspace_id
      AND head.scope_version=(pending.receipt->'deferredPublication'->>'expectedScopeVersion')::integer
      AND head.active_revision_id IS NOT DISTINCT FROM (pending.receipt->'deferredPublication'->>'expectedRevisionId')::uuid
      AND revision.revision=(SELECT max(r.revision) FROM preference_registry_revisions r WHERE r.preference_id=head.id)
      AND (revision.expires_at IS NULL OR revision.expires_at>clock_timestamp())
      AND EXISTS(SELECT 1 FROM skill_source_bindings binding WHERE binding.preference_id=head.id
        AND binding.skill_facet_id=(pending.receipt->'deferredPublication'->>'sourceFacetId')::uuid)
      AND skill_source_has_effective_owner(NEW.account_id,NEW.workspace_id,(pending.receipt->'deferredPublication'->>'sourceFacetId')::uuid)
    THEN
      IF current_mode='automatic' THEN
        PERFORM set_config('opengeni.preference_lifecycle_head_id',head.id::text,true);
        PERFORM set_config('opengeni.preference_lifecycle_operation','activate',true);
        UPDATE preference_registry_preferences SET status='active',active_revision_id=revision.id,
          active_revision=revision.revision,active_content_hash=revision.content_hash,activation_version=activation_version+1,updated_at=clock_timestamp()
          WHERE id=head.id;
        SELECT coalesce(max(version),0)+1 INTO next_event FROM preference_registry_events WHERE preference_id=head.id;
        INSERT INTO preference_registry_events(account_id,preference_id,type,version,old_revision_id,new_revision_id,actor_subject_id,reason)
          VALUES(NEW.account_id,head.id,'activated',next_event,head.active_revision_id,revision.id,'service:skill-publication',
            'Publish previously authorized Skill after composite owner finalization') RETURNING id INTO event_id;
        disposition := 'applied';
      ELSE disposition := 'pending'; END IF;
    END IF;
    result := jsonb_build_object('operationId',publication_id,'sourceOperationId',pending.operation_id,
      'skillId',pending.receipt->>'skillId','revisionId',pending.receipt->>'revisionId','outcome',disposition,
      'activationEventId',event_id,'replayed',false,'publicationOperationId',publication_operation);
    IF disposition='pending' THEN result := result || jsonb_build_object('pendingReason','approval'); END IF;
    INSERT INTO skill_write_receipts(account_id,workspace_id,operation_id,fingerprint,actor,receipt,activation_event_id)
      VALUES(NEW.account_id,NEW.workspace_id,publication_id,expected_fingerprint,publication_actor,result,event_id);
  END LOOP;
  RETURN NEW;
END $$;

CREATE FUNCTION skill_revision_activation_authority(p_revision_id uuid, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT CASE WHEN r.actor->>'kind'='human' OR EXISTS(
    SELECT 1 FROM skill_write_receipts original WHERE original.account_id=r.account_id AND original.workspace_id=r.workspace_id
      AND original.operation_id::text=r.receipt->>'sourceOperationId' AND original.actor->>'kind'='human'
      AND original.receipt ? 'deferredPublication' AND original.receipt->>'revisionId'=revision.id::text
  ) THEN 'human_confirmed' ELSE 'automatic' END
  FROM preference_registry_revisions revision
  JOIN LATERAL (
    SELECT e.id,e.new_revision_id FROM preference_registry_events e
    WHERE e.preference_id=revision.preference_id AND e.account_id=revision.account_id AND e.created_at<=p_at
      AND e.type IN ('proposal_created','activated','corrected','rejected','deactivated','superseded')
    ORDER BY e.created_at DESC,e.version DESC,e.id DESC LIMIT 1
  ) latest ON latest.new_revision_id=revision.id
  JOIN skill_write_receipts r ON r.activation_event_id=latest.id AND r.account_id=revision.account_id
  WHERE revision.id=p_revision_id
$$;

CREATE FUNCTION skill_source_has_effective_owner(p_account_id uuid, p_workspace_id uuid, p_facet_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM capability_facet_installations fi
    JOIN capability_plugin_installations child ON child.id=fi.plugin_installation_id
    JOIN capability_component_owners owner ON owner.facet_installation_id=fi.id
      AND owner.account_id=fi.account_id AND owner.workspace_id=fi.workspace_id
    WHERE fi.account_id=p_account_id AND fi.workspace_id=p_workspace_id AND fi.facet_id=p_facet_id
      AND fi.status='active' AND child.status='active'
      AND (owner.owner_kind IN ('direct','migration')
        OR (owner.owner_kind='plugin' AND EXISTS(SELECT 1 FROM capability_plugin_installations parent
          WHERE parent.id::text=owner.owner_id AND parent.account_id=p_account_id AND parent.workspace_id=p_workspace_id AND parent.status='active')))
  )
$$;

CREATE FUNCTION slack_shared_task_origin_forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Slack shared task origin is immutable' USING ERRCODE = '42501';
END;
$$;

CREATE FUNCTION slack_task_policy_forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Slack task policy history is immutable' USING ERRCODE = '42501';
END;
$$;

CREATE FUNCTION slack_task_policy_guard_head_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected_workspace_id text;
BEGIN
  expected_workspace_id := current_setting('opengeni.slack_task_policy_lifecycle_workspace_id', true);
  IF expected_workspace_id IS NULL OR expected_workspace_id = ''
    OR expected_workspace_id IS DISTINCT FROM coalesce(NEW.workspace_id, OLD.workspace_id)::text
  THEN
    RAISE EXCEPTION 'Slack task policy head mutation is lifecycle-only' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION slack_task_policy_hash(policy jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT encode(sha256(convert_to(jsonb_build_array('slack_task_policy', 1, policy)::text, 'UTF8')), 'hex');
$$;

CREATE FUNCTION slack_task_policy_update(p_operation_id uuid, p_request_fingerprint text, p_account_id uuid, p_workspace_id uuid, p_policy jsonb, p_expected_current_revision_id uuid, p_expected_activation_version bigint, p_actor_subject_id text, p_reason text) RETURNS TABLE(revision_id uuid, event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $_$
DECLARE
  current_head slack_task_policy_heads%ROWTYPE;
  existing_revision slack_task_policy_revisions%ROWTYPE;
  existing_event slack_task_policy_activation_events%ROWTYPE;
  created_revision slack_task_policy_revisions%ROWTYPE;
  next_version bigint;
  accepted_at timestamptz;
BEGIN
  IF NULLIF(current_setting('opengeni.account_id', true), '')::uuid IS DISTINCT FROM p_account_id
    OR NULLIF(current_setting('opengeni.workspace_id', true), '')::uuid IS DISTINCT FROM p_workspace_id
    OR NULLIF(current_setting('opengeni.subject_id', true), '') IS DISTINCT FROM p_actor_subject_id
    OR NULLIF(current_setting('opengeni.principal_kind', true), '') IS DISTINCT FROM 'human_session'
  THEN
    RAISE EXCEPTION 'Slack task policy update requires exact human workspace authority'
      USING ERRCODE = '42501';
  END IF;
  IF p_request_fingerprint !~ '^[0-9a-f]{64}$'
    OR p_expected_activation_version < 0
    OR NOT slack_task_policy_valid(p_policy)
    OR length(btrim(p_actor_subject_id)) NOT BETWEEN 1 AND 1024
    OR length(btrim(p_reason)) NOT BETWEEN 1 AND 4096
  THEN
    RAISE EXCEPTION 'Slack task policy update input is invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM workspaces
  WHERE id = p_workspace_id AND account_id = p_account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'workspace was not found' USING ERRCODE = '42501'; END IF;

  SELECT * INTO existing_revision FROM slack_task_policy_revisions
  WHERE workspace_id = p_workspace_id AND operation_id = p_operation_id;
  SELECT * INTO existing_event FROM slack_task_policy_activation_events
  WHERE workspace_id = p_workspace_id AND operation_id = p_operation_id;
  IF existing_revision.id IS NOT NULL OR existing_event.id IS NOT NULL THEN
    IF existing_revision.id IS NULL OR existing_event.id IS NULL
      OR existing_revision.request_fingerprint IS DISTINCT FROM p_request_fingerprint
      OR existing_event.request_fingerprint IS DISTINCT FROM p_request_fingerprint
    THEN
      RAISE EXCEPTION 'Slack task policy operation id was reused' USING ERRCODE = 'P1471';
    END IF;
    revision_id := existing_revision.id;
    event_id := existing_event.id;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO current_head FROM slack_task_policy_heads
  WHERE workspace_id = p_workspace_id FOR UPDATE;
  IF coalesce(current_head.activation_version, 0) IS DISTINCT FROM p_expected_activation_version
    OR current_head.revision_id IS DISTINCT FROM p_expected_current_revision_id
  THEN
    RAISE EXCEPTION 'Slack task policy active revision changed' USING ERRCODE = '40001';
  END IF;

  accepted_at := clock_timestamp();
  INSERT INTO slack_task_policy_revisions (
    operation_id, request_fingerprint, account_id, workspace_id, policy, policy_hash,
    supersedes_revision_id, created_by_subject_id, created_at
  ) VALUES (
    p_operation_id, p_request_fingerprint, p_account_id, p_workspace_id, p_policy,
    slack_task_policy_hash(p_policy), current_head.revision_id, p_actor_subject_id, accepted_at
  ) RETURNING * INTO created_revision;

  next_version := coalesce(current_head.activation_version, 0) + 1;
  PERFORM set_config('opengeni.slack_task_policy_lifecycle_workspace_id', p_workspace_id::text, true);
  INSERT INTO slack_task_policy_heads (
    account_id, workspace_id, revision_id, revision, policy_hash, activation_version, activated_at
  ) VALUES (
    p_account_id, p_workspace_id, created_revision.id, created_revision.revision,
    created_revision.policy_hash, next_version, accepted_at
  ) ON CONFLICT (workspace_id) DO UPDATE SET
    revision_id = excluded.revision_id,
    revision = excluded.revision,
    policy_hash = excluded.policy_hash,
    activation_version = excluded.activation_version,
    activated_at = excluded.activated_at;
  PERFORM set_config('opengeni.slack_task_policy_lifecycle_workspace_id', '', true);

  INSERT INTO slack_task_policy_activation_events (
    operation_id, request_fingerprint, account_id, workspace_id, activation_version,
    old_revision_id, old_revision, old_policy_hash,
    new_revision_id, new_revision, new_policy_hash,
    actor_subject_id, reason, created_at
  ) VALUES (
    p_operation_id, p_request_fingerprint, p_account_id, p_workspace_id, next_version,
    current_head.revision_id, current_head.revision, current_head.policy_hash,
    created_revision.id, created_revision.revision, created_revision.policy_hash,
    p_actor_subject_id, p_reason, accepted_at
  ) RETURNING id INTO event_id;
  revision_id := created_revision.id;
  RETURN NEXT;
END;
$_$;

CREATE FUNCTION slack_task_policy_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  key text;
  ids jsonb;
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'object'
    OR (SELECT count(*) FROM jsonb_object_keys(value)) <> 7
    OR NOT (
      value ? 'allowedTeamIds'
      AND value ? 'allowedConversationIds'
      AND value ? 'allowGuestInitiators'
      AND value ? 'allowExternalInitiators'
      AND value ? 'allowMpim'
      AND value ? 'sharedConversationMode'
      AND value ? 'resultPublicationMode'
    )
    OR jsonb_typeof(value->'allowedTeamIds') IS DISTINCT FROM 'array'
    OR jsonb_typeof(value->'allowedConversationIds') IS DISTINCT FROM 'array'
    OR jsonb_array_length(value->'allowedTeamIds') > 256
    OR jsonb_array_length(value->'allowedConversationIds') > 256
    OR jsonb_typeof(value->'allowGuestInitiators') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(value->'allowExternalInitiators') IS DISTINCT FROM 'boolean'
    OR jsonb_typeof(value->'allowMpim') IS DISTINCT FROM 'boolean'
    OR value->>'sharedConversationMode' NOT IN ('deny', 'private_handoff')
    OR value->>'resultPublicationMode' NOT IN ('never', 'approval_required', 'allow')
    OR octet_length(convert_to(value::text, 'UTF8')) > 65536
  THEN
    RETURN false;
  END IF;

  FOREACH key IN ARRAY ARRAY['allowedTeamIds', 'allowedConversationIds'] LOOP
    ids := value->key;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(ids) item
      WHERE jsonb_typeof(item) IS DISTINCT FROM 'string'
        OR length(btrim(item #>> '{}')) NOT BETWEEN 1 AND 128
        OR item #>> '{}' IS DISTINCT FROM btrim(item #>> '{}')
    ) OR (
      SELECT count(DISTINCT item #>> '{}') FROM jsonb_array_elements(ids) item
    ) <> jsonb_array_length(ids) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$$;

CREATE FUNCTION stamp_model_call_site() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    SELECT s.site_id INTO NEW.site_id FROM sessions s
      WHERE s.account_id=NEW.account_id AND s.workspace_id=NEW.workspace_id AND s.id=NEW.session_id;
  ELSIF NEW.site_id IS DISTINCT FROM OLD.site_id THEN
    RAISE EXCEPTION 'Model call Site attribution is immutable' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION stamp_model_debit_site() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    NEW.site_id:=NULL;
    IF NEW.type='model_usage_debit' AND NEW.source_type='model_response' THEN
      SELECT s.site_id INTO NEW.site_id FROM sessions s
        WHERE s.account_id=NEW.account_id AND s.workspace_id=NEW.workspace_id
          AND s.id::text=NEW.metadata->>'sessionId';
    END IF;
  ELSIF NEW.site_id IS DISTINCT FROM OLD.site_id THEN
    RAISE EXCEPTION 'Model debit Site attribution is immutable' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION stamp_session_activity_xid() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  NEW.activity_xid := pg_current_xact_id();
  RETURN NEW;
END
$$;

CREATE FUNCTION stamp_turn_personal_resource_snapshot_digest() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  NEW.snapshot_digest := digest_turn_personal_resource_snapshot(NEW);
  RETURN NEW;
END
$$;

CREATE FUNCTION strip_private_session_list_snapshots() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    BEGIN
      -- Every authorized visibility transition already holds the 0225 write
      -- capability (its own `sessions` UPDATE is impossible without it), so the
      -- strip rides on the exact same authority in the exact same transaction.
      -- The owner's own cached pages stay intact: the session remains visible to
      -- them, so their snapshot is not stale.
      UPDATE session_list_snapshots snapshot
      SET ordinary_session_ids = coalesce((
        SELECT pg_catalog.array_agg(
          CASE WHEN entry.element = NEW.id
            THEN '00000000-0000-0000-0000-000000000000'::uuid
            ELSE entry.element
          END
          ORDER BY entry.ordinality
        )
        FROM pg_catalog.unnest(snapshot.ordinary_session_ids)
          WITH ORDINALITY AS entry(element, ordinality)
      ), '{}'::uuid[])
      WHERE snapshot.account_id = NEW.account_id
        AND snapshot.workspace_id = NEW.workspace_id
        AND snapshot.subject_id IS DISTINCT FROM NEW.owner_subject_id
        AND NEW.id = ANY(snapshot.ordinary_session_ids);
      RETURN NULL;
    END;
    $$;

COMMENT ON FUNCTION strip_private_session_list_snapshots() IS 'Strips a session identity from every other subject''s cached list page when that session becomes user_private, under the 0225 visibility write capability.';

CREATE FUNCTION subscription_effective_settings(p_account_id uuid, p_workspace_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
  WITH org AS (
    SELECT * FROM subscription_settings WHERE account_id = p_account_id AND workspace_id IS NULL
  ), ws AS (
    SELECT * FROM subscription_settings WHERE account_id = p_account_id AND workspace_id = p_workspace_id
  ), keys AS (
  SELECT entry.key FROM org, LATERAL jsonb_object_keys(org.rotation) AS entry(key)
    UNION SELECT entry.key FROM ws CROSS JOIN org,
      LATERAL jsonb_object_keys(ws.rotation) AS entry(key)
      WHERE NOT ('rotation' = ANY(coalesce(org.locked_settings, '{}')))
  ), rotation_entries AS (
    SELECT keys.key,
      CASE WHEN ws.rotation ? keys.key AND NOT ('rotation' = ANY(coalesce(org.locked_settings, '{}')))
        THEN ws.rotation->keys.key ELSE org.rotation->keys.key END AS setting,
      CASE WHEN ws.rotation ? keys.key AND NOT ('rotation' = ANY(coalesce(org.locked_settings, '{}')))
        THEN CASE keys.key WHEN 'codex' THEN ws.codex_primary_connection_id
          WHEN 'claude' THEN ws.claude_primary_connection_id
          WHEN 'xai' THEN ws.xai_primary_connection_id END
        ELSE CASE keys.key WHEN 'codex' THEN org.codex_primary_connection_id
          WHEN 'claude' THEN org.claude_primary_connection_id
          WHEN 'xai' THEN org.xai_primary_connection_id END END AS primary_connection_id,
      CASE WHEN ws.rotation ? keys.key AND NOT ('rotation' = ANY(coalesce(org.locked_settings, '{}')))
        THEN 'workspace' ELSE 'organization' END AS source
    FROM keys CROSS JOIN org LEFT JOIN ws ON true
  ), rot AS (
    SELECT coalesce(jsonb_object_agg(key,
      CASE WHEN setting->>'mode' = 'primary_first'
        THEN setting || jsonb_build_object('primaryConnectionId', primary_connection_id::text)
        ELSE setting END), '{}'::jsonb) AS value,
      coalesce(jsonb_object_agg(key, source), '{}'::jsonb) AS sources
    FROM rotation_entries
  ), provider_keys AS (
    SELECT entry.key FROM org, LATERAL jsonb_object_keys(org.providers) AS entry(key)
    UNION SELECT entry.key FROM ws CROSS JOIN org,
      LATERAL jsonb_object_keys(ws.providers) AS entry(key)
      WHERE NOT ('providers' = ANY(coalesce(org.locked_settings, '{}')))
  ), provider_entries AS (
    SELECT provider_keys.key,
      coalesce(org.providers->provider_keys.key, '{}'::jsonb) AS organization_setting,
      CASE WHEN ws.providers ? provider_keys.key
        AND NOT ('providers' = ANY(coalesce(org.locked_settings, '{}')))
        THEN ws.providers->provider_keys.key ELSE '{}'::jsonb END AS workspace_setting,
      (ws.providers ? provider_keys.key
        AND NOT ('providers' = ANY(coalesce(org.locked_settings, '{}')))) AS has_workspace_override
    FROM provider_keys CROSS JOIN org LEFT JOIN ws ON true
  ), provider_resolved AS (
    SELECT key,
      CASE
        WHEN workspace_setting ? 'inferenceSource' THEN workspace_setting->>'inferenceSource'
        WHEN workspace_setting ? 'useOrganizationAccounts'
          THEN CASE WHEN workspace_setting->>'useOrganizationAccounts' = 'false'
            THEN 'workspace' ELSE 'automatic' END
        WHEN organization_setting ? 'inferenceSource' THEN organization_setting->>'inferenceSource'
        WHEN organization_setting ? 'useOrganizationAccounts'
          THEN CASE WHEN organization_setting->>'useOrganizationAccounts' = 'false'
            THEN 'workspace' ELSE 'automatic' END
        ELSE 'automatic'
      END AS inference_source,
      (organization_setting ? 'inferenceSource' OR workspace_setting ? 'inferenceSource') AS has_explicit_source,
      has_workspace_override,
      '{"useOrganizationAccounts":true,"enabled":true}'::jsonb
        || organization_setting || workspace_setting AS merged_setting
    FROM provider_entries
  ), prov AS (
    SELECT coalesce(jsonb_object_agg(key,
      (merged_setting - 'useOrganizationAccounts' - 'inferenceSource')
        || jsonb_build_object('useOrganizationAccounts', inference_source <> 'workspace')
        || CASE WHEN has_explicit_source
          THEN jsonb_build_object('inferenceSource', inference_source) ELSE '{}'::jsonb END), '{}'::jsonb) value,
      coalesce(jsonb_object_agg(key,
        CASE WHEN has_workspace_override THEN 'workspace' ELSE 'organization' END), '{}'::jsonb) sources
    FROM provider_resolved
  ), fallback_keys AS (
    SELECT entry.key FROM org, LATERAL jsonb_object_keys(org.fallback_order) AS entry(key)
    UNION SELECT entry.key FROM ws CROSS JOIN org,
      LATERAL jsonb_object_keys(ws.fallback_order) AS entry(key)
      WHERE NOT ('fallbackOrder' = ANY(coalesce(org.locked_settings, '{}')))
  ), fallback AS (
    SELECT coalesce(jsonb_object_agg(fallback_keys.key,
      CASE WHEN ws.fallback_order ? fallback_keys.key
        AND NOT ('fallbackOrder' = ANY(coalesce(org.locked_settings, '{}')))
        THEN ws.fallback_order->fallback_keys.key ELSE org.fallback_order->fallback_keys.key END), '{}'::jsonb) value,
      coalesce(jsonb_object_agg(fallback_keys.key,
      CASE WHEN ws.fallback_order ? fallback_keys.key
        AND NOT ('fallbackOrder' = ANY(coalesce(org.locked_settings, '{}')))
        THEN 'workspace' ELSE 'organization' END), '{}'::jsonb) sources
    FROM fallback_keys CROSS JOIN org LEFT JOIN ws ON true
  )
  SELECT jsonb_build_object(
    'values', jsonb_build_object(
    'rotation', rot.value, 'providers', prov.value,
    'crossProviderFailover', CASE WHEN ws.cross_provider_failover IS NOT NULL
      AND NOT ('crossProviderFailover' = ANY(coalesce(org.locked_settings, '{}')))
      THEN ws.cross_provider_failover ELSE coalesce(org.cross_provider_failover, false) END,
    'fallbackOrder', fallback.value,
    'personalConnectionsAllowed', CASE WHEN ws.personal_connections_allowed IS NOT NULL
      AND NOT ('personalConnectionsAllowed' = ANY(coalesce(org.locked_settings, '{}')))
      THEN ws.personal_connections_allowed ELSE coalesce(org.personal_connections_allowed, true) END,
    'personalFallbackAllowed', CASE WHEN ws.personal_fallback_allowed IS NOT NULL
      AND NOT ('personalFallbackAllowed' = ANY(coalesce(org.locked_settings, '{}')))
      THEN ws.personal_fallback_allowed ELSE coalesce(org.personal_fallback_allowed, false) END
    ),
    'sources', jsonb_build_object(
      'rotation', rot.sources, 'providers', prov.sources,
      'crossProviderFailover', CASE WHEN ws.cross_provider_failover IS NOT NULL AND NOT ('crossProviderFailover' = ANY(coalesce(org.locked_settings, '{}'))) THEN 'workspace' ELSE 'organization' END,
      'fallbackOrder', fallback.sources,
      'personalConnectionsAllowed', CASE WHEN ws.personal_connections_allowed IS NOT NULL AND NOT ('personalConnectionsAllowed' = ANY(coalesce(org.locked_settings, '{}'))) THEN 'workspace' ELSE 'organization' END,
      'personalFallbackAllowed', CASE WHEN ws.personal_fallback_allowed IS NOT NULL AND NOT ('personalFallbackAllowed' = ANY(coalesce(org.locked_settings, '{}'))) THEN 'workspace' ELSE 'organization' END)
  ) FROM org CROSS JOIN rot CROSS JOIN prov CROSS JOIN fallback LEFT JOIN ws ON true
$$;

CREATE FUNCTION sync_organization_user_setup_delivery_revocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  delivery organization_user_setup_deliveries%ROWTYPE;
  now_value timestamptz := clock_timestamp();
BEGIN
  IF NEW.status = 'revoked' AND OLD.status IS DISTINCT FROM NEW.status THEN
    SELECT * INTO delivery FROM organization_user_setup_deliveries candidate
    WHERE candidate.account_id = NEW.account_id AND candidate.invitation_id = NEW.id
    FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    UPDATE organization_user_setup_delivery_attempts SET
      result = 'revoked', settled_at = now_value
    WHERE delivery_id = delivery.id
      AND claim_holder_id = delivery.claim_holder_id
      AND result IS NULL;
    UPDATE organization_user_setup_deliveries SET
      state = 'revoked', revoked_at = coalesce(revoked_at, now_value),
      claim_holder_id = NULL, claim_expires_at = NULL,
      unresolved_provider_outcome_at = NULL,
      error_class = NULL, revision = revision + 1, updated_at = now_value
    WHERE id = delivery.id AND state <> 'revoked';
  END IF;
  RETURN NULL;
END
$$;

CREATE FUNCTION sync_personal_enrollment_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE capability_added boolean := false;
BEGIN
  IF NEW.authority_scope <> 'user' OR (
    NEW.generation = OLD.generation AND NEW.status = OLD.status
  ) THEN
    RETURN NEW;
  END IF;
  INSERT INTO opengeni_private.scoped_compute_capabilities(
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(), 'write')
  ON CONFLICT DO NOTHING;
  capability_added := FOUND;
  UPDATE organization_user_resource_authorities
  SET generation = NEW.generation, status = NEW.status,
    revoked_at = CASE WHEN NEW.status = 'revoked' THEN coalesce(NEW.revoked_at, clock_timestamp())
      ELSE NULL END,
    updated_at = clock_timestamp()
  WHERE id = NEW.authority_id AND account_id = NEW.account_id
    AND organization_membership_id = NEW.owner_organization_membership_id
    AND resource_kind = 'connected_machine' AND resource_id = NEW.id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'personal machine authority is missing' USING ERRCODE = '42501';
  END IF;
  UPDATE organization_user_resource_grants
  SET status = 'revoked', revoked_at = clock_timestamp(),
    generation = generation + 1, updated_at = clock_timestamp()
  WHERE authority_id = NEW.authority_id AND account_id = NEW.account_id
    AND status = 'active';
  IF capability_added THEN
    DELETE FROM opengeni_private.scoped_compute_capabilities
    WHERE backend_pid = pg_catalog.pg_backend_pid()
      AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned()
      AND capability_kind = 'write';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION sync_session_history_items_ordered() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.item_ordered IS NULL THEN
      NEW.item_ordered := NEW.item::json;
    ELSE
      NEW.item := NEW.item_ordered::jsonb;
    END IF;
  ELSIF NEW.item_ordered::text IS DISTINCT FROM OLD.item_ordered::text THEN
    NEW.item := NEW.item_ordered::jsonb;
  ELSIF NEW.item IS DISTINCT FROM OLD.item THEN
    NEW.item_ordered := NEW.item::json;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION sync_session_pending_tool_calls_ordered() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.call_item_ordered IS NULL THEN
      NEW.call_item_ordered := NEW.call_item::json;
    ELSE
      NEW.call_item := NEW.call_item_ordered::jsonb;
    END IF;
  ELSIF NEW.call_item_ordered::text IS DISTINCT FROM OLD.call_item_ordered::text THEN
    NEW.call_item := NEW.call_item_ordered::jsonb;
  ELSIF NEW.call_item IS DISTINCT FROM OLD.call_item THEN
    NEW.call_item_ordered := NEW.call_item::json;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.result_item_ordered IS NULL THEN
      NEW.result_item_ordered := NEW.result_item::json;
    ELSE
      NEW.result_item := NEW.result_item_ordered::jsonb;
    END IF;
  ELSIF NEW.result_item_ordered::text IS DISTINCT FROM OLD.result_item_ordered::text THEN
    NEW.result_item := NEW.result_item_ordered::jsonb;
  ELSIF NEW.result_item IS DISTINCT FROM OLD.result_item THEN
    NEW.result_item_ordered := NEW.result_item::json;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.tied_reasoning_items_ordered IS NULL THEN
      NEW.tied_reasoning_items_ordered := NEW.tied_reasoning_items::json;
    ELSE
      NEW.tied_reasoning_items := NEW.tied_reasoning_items_ordered::jsonb;
    END IF;
  ELSIF NEW.tied_reasoning_items_ordered::text IS DISTINCT FROM OLD.tied_reasoning_items_ordered::text THEN
    NEW.tied_reasoning_items := NEW.tied_reasoning_items_ordered::jsonb;
  ELSIF NEW.tied_reasoning_items IS DISTINCT FROM OLD.tied_reasoning_items THEN
    NEW.tied_reasoning_items_ordered := NEW.tied_reasoning_items::json;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION sync_session_variable_set_attachment_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  EXECUTE pg_catalog.format(
    'UPDATE %I.session_variable_set_attachments
     SET session_status = $1
     WHERE workspace_id = $2 AND session_id = $3
       AND session_status IS DISTINCT FROM $1',
    TG_TABLE_SCHEMA
  ) USING NEW.status, NEW.workspace_id, NEW.id;
  RETURN NEW;
END
$_$;

CREATE FUNCTION sync_session_variable_set_attachments() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;
  EXECUTE pg_catalog.format(
    'DELETE FROM %I.session_variable_set_attachments
     WHERE workspace_id = $1 AND session_id = $2',
    TG_TABLE_SCHEMA
  ) USING NEW.workspace_id, NEW.id;
  EXECUTE pg_catalog.format(
    'INSERT INTO %I.session_variable_set_attachments (
       account_id, workspace_id, session_id, variable_set_id, position, session_status
     )
     SELECT $1, $2, $3, selected.value::uuid,
       selected.position::integer - 1, $5
     FROM pg_catalog.jsonb_array_elements_text($4)
       WITH ORDINALITY selected(value, position)',
    TG_TABLE_SCHEMA
  ) USING NEW.account_id, NEW.workspace_id, NEW.id, NEW.variable_set_ids, NEW.status;
  RETURN NEW;
END
$_$;

CREATE FUNCTION transition_scheduled_agent_run(p_account_id uuid, p_workspace_id uuid, p_run_id uuid, p_session_id uuid, p_trigger_event_id uuid, p_status text, p_error text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE run_row record;
BEGIN
  IF p_account_id IS DISTINCT FROM nullif(current_setting('opengeni.account_id', true), '')::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
    OR p_status NOT IN ('dispatched','failed','skipped')
  THEN RAISE EXCEPTION 'scheduled run transition scope or status mismatch'
    USING ERRCODE = '42501'; END IF;
  IF p_session_id IS NOT NULL THEN
    PERFORM 1 FROM sessions session_value
    WHERE session_value.id = p_session_id AND session_value.account_id = p_account_id
      AND session_value.workspace_id = p_workspace_id
    FOR NO KEY UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'scheduled run transition session unavailable'
      USING ERRCODE = '42501'; END IF;
  END IF;
  SELECT run.* INTO STRICT run_row FROM scheduled_task_runs run
  WHERE run.id = p_run_id AND run.account_id = p_account_id
    AND run.workspace_id = p_workspace_id AND run.action_kind = 'agent_turn'
  FOR UPDATE;
  IF run_row.status IN ('succeeded','failed','skipped') THEN RETURN; END IF;
  IF run_row.status NOT IN ('queued','dispatched')
    OR (p_session_id IS NOT NULL AND run_row.session_id IS NOT NULL
      AND run_row.session_id IS DISTINCT FROM p_session_id)
    OR (p_status = 'dispatched' AND (p_session_id IS NULL OR p_trigger_event_id IS NULL))
    OR (p_status IN ('failed','skipped') AND p_error IS NULL)
  THEN RAISE EXCEPTION 'scheduled run transition identity changed'
    USING ERRCODE = '42501'; END IF;
  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'run_lifecycle')
  ON CONFLICT DO NOTHING;
  UPDATE scheduled_task_runs run
  SET status = p_status,
    session_id = coalesce(p_session_id, run.session_id),
    trigger_event_id = CASE WHEN p_status = 'dispatched' THEN p_trigger_event_id
      ELSE run.trigger_event_id END,
    error = p_error,
    completed_at = CASE WHEN p_status IN ('failed','skipped')
      THEN clock_timestamp() ELSE NULL END,
    updated_at = clock_timestamp()
  WHERE run.id = p_run_id AND run.account_id = p_account_id
    AND run.workspace_id = p_workspace_id;
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'run_lifecycle';
END
$$;

CREATE FUNCTION transition_session_visibility(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_actor_subject_id text, p_target_visibility text, p_expected_authority_epoch integer, p_operation_key text, p_canonical_request_hash text, p_activation_version integer) RETURNS TABLE(operation_id uuid, event_id uuid, event_sequence integer, visibility text, authority_epoch integer, owner_organization_membership_id uuid, changed boolean, replay boolean, interrupted_attempt_count integer, cancelled_turn_count integer, cancelled_update_count integer, paused_goal_count integer, revoked_grant_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  actor_membership organization_memberships%ROWTYPE;
  session_row sessions%ROWTYPE;
  receipt_row session_command_receipts%ROWTYPE;
  new_epoch integer;
  grant_count integer := 0;
  event_row_id uuid;
  event_row_sequence integer;
  visibility_write_capability_id uuid := gen_random_uuid();
  previous_visibility_capability text := current_setting(
    'opengeni.session_visibility_write_capability', true
  );
  previous_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  cancelled_update_ids uuid[] := ARRAY[]::uuid[];
  cancelled_update_id uuid;
  private_blocker text;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_session_id IS NULL
    OR p_actor_subject_id IS NULL OR p_target_visibility IS NULL
    OR p_expected_authority_epoch IS NULL OR p_operation_key IS NULL
    OR p_canonical_request_hash IS NULL OR p_activation_version IS NULL
  THEN RAISE EXCEPTION 'session visibility transition requires complete authority'
    USING ERRCODE = '42501'; END IF;
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
  THEN RAISE EXCEPTION 'session visibility transition authority is invalid'
    USING ERRCODE = '42501'; END IF;
  IF p_target_visibility NOT IN ('user_private', 'workspace_shared')
    OR p_expected_authority_epoch < 1
    OR p_actor_subject_id <> btrim(p_actor_subject_id)
    OR length(p_actor_subject_id) NOT BETWEEN 1 AND 1024
    OR p_operation_key <> btrim(p_operation_key)
    OR length(p_operation_key) NOT BETWEEN 1 AND 1024
    OR p_canonical_request_hash !~ '^[0-9a-f]{64}$'
    OR p_activation_version <> 1
  THEN RAISE EXCEPTION 'session visibility transition request is invalid'
    USING ERRCODE = '22023'; END IF;
  IF NOT session_tenancy_product_activated(p_account_id, p_activation_version) THEN
    RAISE EXCEPTION 'session tenancy product surface is not activated for this organization'
      USING ERRCODE = '55000';
  END IF;

  -- Match the canonical organization-membership lifecycle prefix before any
  -- table/row lock. This keeps visibility changes from reintroducing the
  -- workspace/account lock cycle repaired by migration 0299.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || p_account_id::text, 0
  ));

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'session-tenancy:' || p_workspace_id::text, 0
  ));


  PERFORM set_config('opengeni.organization_tenancy_lifecycle',
    'session_visibility_activation', true);
  PERFORM 1 FROM workspaces workspace_row
  WHERE workspace_row.id = p_workspace_id AND workspace_row.account_id = p_account_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'session visibility transition workspace is unavailable'
    USING ERRCODE = '42501'; END IF;

  SELECT membership.* INTO actor_membership
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id
    AND membership.status = 'active'
  FOR NO KEY UPDATE;
  IF NOT FOUND OR NOT (
    actor_membership.personal_workspace_id = p_workspace_id
    OR EXISTS (
      SELECT 1 FROM workspace_memberships workspace_membership
      WHERE workspace_membership.account_id = p_account_id
        AND workspace_membership.workspace_id = p_workspace_id
        AND workspace_membership.subject_id = p_actor_subject_id
    )
  ) THEN RAISE EXCEPTION 'session visibility transition requires active membership'
    USING ERRCODE = '42501'; END IF;

  SELECT session.* INTO session_row FROM sessions session
  WHERE session.account_id = p_account_id AND session.workspace_id = p_workspace_id
    AND session.id = p_session_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'session visibility transition session is unavailable'
    USING ERRCODE = 'P0002'; END IF;
  IF session_row.owner_organization_membership_id IS DISTINCT FROM actor_membership.id
    OR session_row.owner_subject_id IS DISTINCT FROM actor_membership.subject_id
  THEN RAISE EXCEPTION 'session visibility transition is owner-only'
    USING ERRCODE = '42501'; END IF;

  INSERT INTO session_command_receipts (
    account_id, workspace_id, actor_type, actor_subject_id, action,
    target_session_id, operation_key, canonical_request_hash
  ) VALUES (
    p_account_id, p_workspace_id, 'human', p_actor_subject_id,
    'session.visibility.change', p_session_id, p_operation_key, p_canonical_request_hash
  ) ON CONFLICT DO NOTHING;
  SELECT receipt.* INTO receipt_row FROM session_command_receipts receipt
  WHERE receipt.workspace_id = p_workspace_id AND receipt.actor_type = 'human'
    AND receipt.actor_subject_id = p_actor_subject_id
    AND receipt.actor_attempt_id IS NULL
    AND receipt.action = 'session.visibility.change'
    AND receipt.target_session_id = p_session_id AND receipt.target_turn_id IS NULL
    AND receipt.operation_key = p_operation_key
  FOR UPDATE;
  IF receipt_row.canonical_request_hash <> p_canonical_request_hash THEN
    RAISE EXCEPTION 'session visibility transition idempotency conflict'
      USING ERRCODE = '23505';
  END IF;
  IF receipt_row.result ->> 'status' = 'applied' THEN
    operation_id := receipt_row.id;
    event_id := nullif(receipt_row.result ->> 'eventId', '')::uuid;
    event_sequence := nullif(receipt_row.result ->> 'eventSequence', '')::integer;
    visibility := receipt_row.result ->> 'visibility';
    authority_epoch := (receipt_row.result ->> 'authorityEpoch')::integer;
    owner_organization_membership_id := actor_membership.id;
    changed := (receipt_row.result ->> 'changed')::boolean;
    replay := true;
    interrupted_attempt_count := 0; cancelled_turn_count := 0;
    cancelled_update_count := 0; paused_goal_count := 0;
    revoked_grant_count := (receipt_row.result ->> 'revokedGrantCount')::integer;
    RETURN NEXT; RETURN;
  END IF;
  IF session_row.authority_epoch <> p_expected_authority_epoch THEN
    RAISE EXCEPTION 'session visibility transition authority epoch conflict'
      USING ERRCODE = '40001';
  END IF;

  new_epoch := session_row.authority_epoch;
  IF session_row.visibility <> p_target_visibility THEN
    IF p_target_visibility = 'user_private' THEN
      -- A private chat accepts no one else's authority. Pending machine input
      -- that carries another person's frozen authority is cancelled as part
      -- of this change instead of refusing it.
      WITH cancelled AS (
        UPDATE session_system_updates pending_update SET state = 'cancelled'
        WHERE pending_update.workspace_id = p_workspace_id
          AND pending_update.session_id = p_session_id
          AND pending_update.state = 'pending'
          AND session_system_update_carries_foreign_authority(pending_update,
            session_row.owner_subject_id, session_row.owner_organization_membership_id)
        RETURNING pending_update.id, pending_update.created_at
      )
      SELECT COALESCE(array_agg(cancelled.id ORDER BY cancelled.created_at, cancelled.id),
        ARRAY[]::uuid[])
      INTO cancelled_update_ids FROM cancelled;
      FOREACH cancelled_update_id IN ARRAY cancelled_update_ids LOOP
        session_row.last_sequence := session_row.last_sequence + 1;
        INSERT INTO session_events (
          account_id, workspace_id, session_id, sequence, type, payload, occurred_at
        ) VALUES (
          p_account_id, p_workspace_id, p_session_id, session_row.last_sequence,
          'system.update.cancelled',
          jsonb_build_object('updateId', cancelled_update_id, 'reason', 'authority_changed'),
          clock_timestamp()
        );
      END LOOP;
      -- A subscription account choice the owner cannot use is removed; the
      -- next response is placed automatically.
      DELETE FROM subscription_session_bindings binding
      WHERE binding.account_id = p_account_id AND binding.workspace_id = p_workspace_id
        AND binding.session_id = p_session_id AND binding.connection_id IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM subscription_connections connection
          WHERE connection.account_id = binding.account_id
            AND connection.id = binding.connection_id
            AND (connection.ownership <> 'personal'
              OR connection.owner_subject_id = session_row.owner_subject_id));
      -- The application settled the chat's own work under this transaction's
      -- tenancy fence; only what a private chat cannot keep is checked here.
      private_blocker := session_private_transition_blocker(
        p_account_id, p_workspace_id, p_session_id);
      IF private_blocker IS NOT NULL THEN
        RAISE EXCEPTION 'session tenancy mutation requires a quiescent session'
          USING ERRCODE = '55P03', DETAIL = private_blocker;
      END IF;
    END IF;
    new_epoch := session_row.authority_epoch + 1;
    IF new_epoch < 2 THEN RAISE EXCEPTION 'session authority epoch exhausted'
      USING ERRCODE = '22003'; END IF;

    IF p_target_visibility = 'user_private' THEN
      UPDATE organization_user_resource_grants grant_row
      SET status = 'revoked', revoked_at = clock_timestamp(),
        generation = grant_row.generation + 1, updated_at = clock_timestamp()
      WHERE grant_row.account_id = p_account_id
        AND grant_row.workspace_id = p_workspace_id
        AND grant_row.session_id = p_session_id
        AND grant_row.authority_epoch BETWEEN session_row.execution_authority_epoch AND session_row.authority_epoch
        AND grant_row.status = 'active';
      GET DIAGNOSTICS grant_count = ROW_COUNT;
    END IF;

    INSERT INTO session_visibility_write_capabilities (
      backend_pid, transaction_id, capability_id
    ) VALUES (pg_backend_pid(), pg_current_xact_id(), visibility_write_capability_id);
    PERFORM set_config('opengeni.session_visibility_write_capability',
      visibility_write_capability_id::text, true);
    UPDATE sessions transition_target SET
      visibility = p_target_visibility,
      authority_epoch = new_epoch,
      initial_personal_connection_delegations = CASE WHEN p_target_visibility = 'user_private'
        THEN '[]'::jsonb ELSE transition_target.initial_personal_connection_delegations END,
      last_sequence = session_row.last_sequence + 1,
      updated_at = clock_timestamp()
    WHERE transition_target.id = p_session_id
      AND transition_target.authority_epoch = session_row.authority_epoch;
    IF NOT FOUND THEN RAISE EXCEPTION 'session visibility transition lost authority epoch CAS'
      USING ERRCODE = '40001'; END IF;

    INSERT INTO session_events (
      account_id, workspace_id, session_id, sequence, type, payload, occurred_at
    ) VALUES (
      p_account_id, p_workspace_id, p_session_id, session_row.last_sequence + 1,
      'session.visibility.changed',
      jsonb_build_object(
        'operationId', receipt_row.id,
        'fromVisibility', CASE session_row.visibility WHEN 'user_private' THEN 'private' ELSE 'workspace' END,
        'toVisibility', CASE p_target_visibility WHEN 'user_private' THEN 'private' ELSE 'workspace' END,
        'previousAuthorityEpoch', session_row.authority_epoch,
        'authorityEpoch', new_epoch,
        'interruptedAttemptCount', 0, 'cancelledTurnCount', 0,
        'cancelledUpdateCount', cardinality(cancelled_update_ids), 'pausedGoalCount', 0,
        'revokedGrantCount', grant_count
      ), clock_timestamp()
    ) RETURNING id, sequence INTO event_row_id, event_row_sequence;
    DELETE FROM session_visibility_write_capabilities capability
    WHERE capability.backend_pid = pg_backend_pid()
      AND capability.transaction_id = pg_current_xact_id()
      AND capability.capability_id = visibility_write_capability_id;
    PERFORM set_config('opengeni.session_visibility_write_capability',
      CASE WHEN previous_visibility_capability IS NULL THEN '' ELSE previous_visibility_capability END,
      true);
  END IF;

  UPDATE session_command_receipts SET result = jsonb_build_object(
    'status', 'applied', 'eventId', event_row_id,
    'eventSequence', event_row_sequence, 'visibility', p_target_visibility,
    'authorityEpoch', new_epoch, 'changed', session_row.visibility <> p_target_visibility,
    'revokedGrantCount', grant_count
  ), updated_at = clock_timestamp() WHERE id = receipt_row.id;

  operation_id := receipt_row.id; event_id := event_row_id;
  event_sequence := event_row_sequence; visibility := p_target_visibility;
  authority_epoch := new_epoch;
  owner_organization_membership_id := actor_membership.id;
  changed := session_row.visibility <> p_target_visibility; replay := false;
  interrupted_attempt_count := 0; cancelled_turn_count := 0;
  cancelled_update_count := cardinality(cancelled_update_ids); paused_goal_count := 0;
  revoked_grant_count := grant_count;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_lifecycle IS NULL THEN '' ELSE previous_lifecycle END, true);
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle',
    CASE WHEN previous_lifecycle IS NULL THEN '' ELSE previous_lifecycle END, true);
  PERFORM set_config('opengeni.session_visibility_write_capability',
    CASE WHEN previous_visibility_capability IS NULL THEN '' ELSE previous_visibility_capability END,
    true);
  RAISE;
END
$_$;

COMMENT ON FUNCTION transition_session_visibility(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_actor_subject_id text, p_target_visibility text, p_expected_authority_epoch integer, p_operation_key text, p_canonical_request_hash text, p_activation_version integer) IS 'Activated owner-only, proven-quiescent visibility transition. It never cancels accepted work or wakes a workflow.';

CREATE FUNCTION undo_governed_learning_activation(p_account_id uuid, p_workspace_id uuid, p_operation_id uuid, p_activation_receipt_id uuid) RETURNS SETOF governed_learning_activation_undo_receipts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  caller_subject_id text := nullif(current_setting('opengeni.subject_id', true), '');
  activation_row governed_learning_activation_receipts%ROWTYPE;
  decision_row governed_learning_decision_receipts%ROWTYPE;
  result_row governed_learning_activation_undo_receipts%ROWTYPE;
  latest_review knowledge_claim_reviews%ROWTYPE;
  revocation_row knowledge_claim_reviews%ROWTYPE;
  instruction_head workspace_instruction_policy_heads%ROWTYPE;
  instruction_event workspace_instruction_policy_activation_events%ROWTYPE;
  instruction_deactivation workspace_instruction_policy_deactivation_events%ROWTYPE;
  preference_row preference_registry_preferences%ROWTYPE;
  preference_event preference_registry_events%ROWTYPE;
  input_hash_value text;
  service_actor text;
  review_operation_id uuid;
  destination_operation_id uuid;
  destination_new_version_value bigint;
  destination_event_id_value uuid;
  effective_at_value timestamptz;
BEGIN
  IF p_account_id IS NULL OR p_workspace_id IS NULL OR p_operation_id IS NULL
    OR p_activation_receipt_id IS NULL OR caller_subject_id IS NULL
    OR length(btrim(caller_subject_id)) NOT BETWEEN 1 AND 1024
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR p_workspace_id IS DISTINCT FROM opengeni_private.current_workspace_id()
  THEN
    RAISE EXCEPTION 'governed-learning undo requires exact tenant authority'
      USING ERRCODE = '42501';
  END IF;
  input_hash_value := encode(sha256(convert_to(jsonb_build_array(
    'governed-learning-activation-undo', 1, p_account_id, p_workspace_id,
    p_operation_id, p_activation_receipt_id
  )::text, 'UTF8')), 'hex');
  SELECT * INTO result_row FROM governed_learning_activation_undo_receipts receipt
  WHERE receipt.workspace_id = p_workspace_id AND receipt.operation_id = p_operation_id
  FOR SHARE;
  IF FOUND THEN
    IF result_row.account_id <> p_account_id OR result_row.input_hash <> input_hash_value
      OR result_row.activation_receipt_id <> p_activation_receipt_id
      OR result_row.initiating_human_subject_id <> caller_subject_id
    THEN
      RAISE EXCEPTION 'governed-learning undo operation conflicts with immutable receipt'
        USING ERRCODE = '23505';
    END IF;
    RETURN NEXT result_row;
    RETURN;
  END IF;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'governed-learning workspace is unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO result_row FROM governed_learning_activation_undo_receipts receipt
  WHERE receipt.workspace_id = p_workspace_id AND receipt.operation_id = p_operation_id
  FOR SHARE;
  IF FOUND THEN
    IF result_row.account_id <> p_account_id OR result_row.input_hash <> input_hash_value
      OR result_row.activation_receipt_id <> p_activation_receipt_id
      OR result_row.initiating_human_subject_id <> caller_subject_id
    THEN
      RAISE EXCEPTION 'governed-learning undo operation conflicts with immutable receipt'
        USING ERRCODE = '23505';
    END IF;
    RETURN NEXT result_row;
    RETURN;
  END IF;
  SELECT * INTO activation_row FROM governed_learning_activation_receipts receipt
  WHERE receipt.id = p_activation_receipt_id AND receipt.account_id = p_account_id
    AND receipt.workspace_id = p_workspace_id
    AND receipt.initiating_human_subject_id = caller_subject_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'governed-learning activation receipt is unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO decision_row FROM governed_learning_decision_receipts receipt
  WHERE receipt.id = activation_row.decision_receipt_id
    AND receipt.account_id = p_account_id AND receipt.workspace_id = p_workspace_id
    AND receipt.initiating_human_subject_id = caller_subject_id FOR SHARE;
  IF NOT FOUND OR NOT session_reference_visible(
    decision_row.account_id, decision_row.workspace_id, decision_row.session_id
  ) THEN
    RAISE EXCEPTION 'governed-learning undo source is unavailable' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM governed_learning_activation_undo_receipts receipt
    WHERE receipt.activation_receipt_id = p_activation_receipt_id
  ) THEN
    RAISE EXCEPTION 'governed-learning activation was undone by another operation'
      USING ERRCODE = '23505';
  END IF;
  SELECT * INTO latest_review FROM knowledge_claim_reviews review
  WHERE review.account_id = p_account_id AND review.claim_id = activation_row.claim_id
  ORDER BY review.review_revision DESC LIMIT 1 FOR UPDATE;
  IF latest_review.id IS DISTINCT FROM activation_row.knowledge_approval_review_id
    OR latest_review.review_revision IS DISTINCT FROM activation_row.knowledge_approval_review_revision
    OR latest_review.state <> 'approved'
  THEN
    RAISE EXCEPTION 'automatic Knowledge activation was superseded' USING ERRCODE = '40001';
  END IF;
  service_actor := 'service:governed-learning-activation:' || input_hash_value;
  review_operation_id := opengeni_private.governed_learning_derived_uuid(
    p_operation_id, 'knowledge-revoke'
  );
  destination_operation_id := opengeni_private.governed_learning_derived_uuid(
    p_operation_id, 'destination-undo'
  );

  IF activation_row.destination = 'instruction_policy' THEN
    SELECT head.* INTO instruction_head FROM workspace_instruction_policy_heads head
    JOIN workspace_instruction_policy_onboarding_proposals proposal
      ON proposal.account_id = head.account_id AND proposal.workspace_id = head.workspace_id
      AND proposal.id = activation_row.destination_proposal_id
      AND proposal.kind = head.kind AND proposal.scope = head.scope
      AND proposal.role_key IS NOT DISTINCT FROM head.role_key
    WHERE head.account_id = p_account_id AND head.workspace_id = p_workspace_id
      AND head.revision_id = activation_row.destination_revision_id
      AND head.content_hash = activation_row.destination_new_content_hash
      AND head.activation_version = activation_row.destination_new_version
    FOR UPDATE OF head;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'automatic instruction-policy activation was superseded'
        USING ERRCODE = '40001';
    END IF;
    IF activation_row.destination_old_revision_id IS NULL THEN
      SELECT * INTO instruction_deactivation
      FROM governed_learning_deactivate_instruction_policy(
        p_account_id, p_workspace_id, destination_operation_id,
        activation_row.destination_proposal_id, activation_row.destination_revision_id,
        activation_row.destination_new_version, service_actor
      );
      destination_new_version_value := instruction_deactivation.activation_version;
      destination_event_id_value := instruction_deactivation.id;
      effective_at_value := instruction_deactivation.created_at;
    ELSE
      SELECT * INTO instruction_event FROM governed_learning_apply_instruction_policy(
        'undo', p_account_id, p_workspace_id, destination_operation_id,
        activation_row.destination_proposal_id, activation_row.destination_revision_id,
        activation_row.destination_new_version, activation_row.destination_old_revision_id,
        service_actor
      );
      destination_new_version_value := instruction_event.activation_version;
      destination_event_id_value := instruction_event.id;
      effective_at_value := instruction_event.created_at;
    END IF;
  ELSIF activation_row.destination = 'preference' THEN
    SELECT * INTO preference_row FROM preference_registry_preferences preference
    WHERE preference.account_id = p_account_id AND preference.id = activation_row.destination_proposal_id
      AND preference.scope = 'workspace' AND preference.scope_workspace_id = p_workspace_id
      AND preference.status = 'active'
      AND preference.active_revision_id = activation_row.destination_revision_id
      AND preference.active_content_hash = activation_row.destination_new_content_hash
      AND preference.activation_version = activation_row.destination_new_version
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'automatic preference activation was superseded' USING ERRCODE = '40001';
    END IF;
    SELECT * INTO preference_event FROM governed_learning_apply_preference(
      'undo', p_account_id, p_workspace_id, destination_operation_id,
      activation_row.proposal_id, activation_row.destination_proposal_id,
      activation_row.destination_revision_id, activation_row.destination_revision_id,
      activation_row.destination_new_version::integer, service_actor
    );
    SELECT activation_version INTO destination_new_version_value
    FROM preference_registry_preferences WHERE id = activation_row.destination_proposal_id;
    destination_event_id_value := preference_event.id;
    effective_at_value := preference_event.created_at;
  ELSE
    RAISE EXCEPTION 'governed-learning activation destination is invalid' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO revocation_row FROM governed_learning_apply_knowledge_review(
    p_account_id, p_workspace_id, review_operation_id, activation_row.claim_id,
    latest_review.id, latest_review.review_revision, 'revoked', service_actor,
    caller_subject_id
  );
  INSERT INTO governed_learning_activation_undo_receipts (
    account_id, workspace_id, operation_id, input_hash, activation_receipt_id,
    initiating_human_subject_id, service_actor_subject_id, destination,
    knowledge_approval_review_id, knowledge_revocation_review_id,
    knowledge_revocation_review_revision, knowledge_revocation_input_hash,
    destination_activated_revision_id, destination_restored_revision_id,
    destination_activated_content_hash, destination_restored_content_hash,
    destination_old_version, destination_new_version, destination_event_id,
    effective_at
  ) VALUES (
    p_account_id, p_workspace_id, p_operation_id, input_hash_value,
    activation_row.id, caller_subject_id, service_actor, activation_row.destination,
    activation_row.knowledge_approval_review_id, revocation_row.id,
    revocation_row.review_revision, revocation_row.input_hash,
    activation_row.destination_revision_id, activation_row.destination_old_revision_id,
    activation_row.destination_new_content_hash, activation_row.destination_old_content_hash,
    activation_row.destination_new_version, destination_new_version_value,
    destination_event_id_value, effective_at_value
  ) RETURNING * INTO result_row;
  RETURN NEXT result_row;
END;
$$;

CREATE FUNCTION update_company_profile_agent_policy(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text, p_mode text, p_expected_version bigint, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  context_account_id uuid := nullif(current_setting('opengeni.account_id', true), '')::uuid;
  context_workspace_id uuid := nullif(current_setting('opengeni.workspace_id', true), '')::uuid;
  context_subject_id text := nullif(current_setting('opengeni.subject_id', true), '');
  context_principal_kind text := nullif(current_setting('opengeni.principal_kind', true), '');
  actor organization_memberships%ROWTYPE;
  policy organization_company_profile_agent_policies%ROWTYPE;
  prior organization_company_profile_agent_policy_events%ROWTYPE;
  next_version bigint;
  did_change boolean;
BEGIN
  IF context_account_id IS DISTINCT FROM p_account_id
    OR context_workspace_id IS DISTINCT FROM p_workspace_id
    OR context_subject_id IS DISTINCT FROM p_actor_subject_id
    OR context_principal_kind IS DISTINCT FROM 'human_session'
    OR p_mode NOT IN ('off', 'suggest', 'automatic')
    OR p_expected_version IS NULL OR p_expected_version < 0
    OR p_operation_id IS NULL
  THEN
    RAISE EXCEPTION 'company-profile agent policy request is invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || p_account_id::text, 0
  ));
  PERFORM pg_catalog.set_config(
    'opengeni.company_profile_agent_policy_lifecycle',
    'company_profile_agent_policy', true
  );
  PERFORM 1 FROM managed_accounts account WHERE account.id = p_account_id FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = p_account_id AND workspace.id = p_workspace_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization workspace is unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT membership.* INTO actor FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id
    AND membership.status = 'active'
    AND membership.role = 'owner'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization owner authority required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO prior FROM organization_company_profile_agent_policy_events event
  WHERE event.id = p_operation_id;
  IF FOUND THEN
    IF prior.account_id IS DISTINCT FROM p_account_id
      OR prior.actor_membership_id IS DISTINCT FROM actor.id
      OR prior.requested_mode IS DISTINCT FROM p_mode
      OR prior.expected_version IS DISTINCT FROM p_expected_version
    THEN
      RAISE EXCEPTION 'company-profile agent policy operation id was reused'
        USING ERRCODE = 'P1851';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
      'organizationId', p_account_id,
      'mode', prior.result_mode,
      'version', prior.result_version,
      'updatedAt', prior.result_updated_at,
      'changed', prior.changed
    );
  END IF;
  SELECT * INTO policy FROM organization_company_profile_agent_policies candidate
  WHERE candidate.account_id = p_account_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'company-profile agent policy is unavailable' USING ERRCODE = '55000';
  END IF;
  IF policy.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'company-profile agent policy changed before update'
      USING ERRCODE = '40001';
  END IF;
  did_change := policy.mode IS DISTINCT FROM p_mode;
  next_version := policy.version + 1;
  UPDATE organization_company_profile_agent_policies SET
    mode = p_mode,
    version = next_version,
    updated_by_membership_id = actor.id,
    updated_at = clock_timestamp()
  WHERE account_id = p_account_id
  RETURNING * INTO policy;
  INSERT INTO organization_company_profile_agent_policy_events (
    id, account_id, actor_membership_id, requested_mode, expected_version,
    result_mode, result_version, result_updated_at, changed
  ) VALUES (
    p_operation_id, p_account_id, actor.id, p_mode, p_expected_version,
    policy.mode, policy.version, policy.updated_at, did_change
  );
  RETURN pg_catalog.jsonb_build_object(
    'organizationId', p_account_id,
    'mode', policy.mode,
    'version', policy.version,
    'updatedAt', policy.updated_at,
    'changed', did_change
  );
END
$$;

CREATE FUNCTION update_organization_name(p_account_id uuid, p_actor_subject_id text, p_name text, p_expected_updated_at timestamp with time zone, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  actor organization_memberships%ROWTYPE;
  account managed_accounts%ROWTYPE;
  prior organization_profile_events%ROWTYPE;
  normalized_name text := btrim(p_name);
  previous_name_value text;
BEGIN
  IF p_account_id IS NULL OR p_name IS NULL OR p_operation_id IS NULL
    OR p_expected_updated_at IS NULL
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
    OR char_length(normalized_name) NOT BETWEEN 1 AND 120
    OR octet_length(normalized_name) > 480
  THEN
    RAISE EXCEPTION 'organization name request is invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle',
    'organization_membership_lifecycle', true
  );
  SELECT * INTO account FROM managed_accounts candidate
  WHERE candidate.id = p_account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO actor FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.subject_id = p_actor_subject_id
  FOR SHARE;
  IF NOT FOUND OR actor.status <> 'active' OR actor.role NOT IN ('owner', 'admin') THEN
    RAISE EXCEPTION 'organization administration required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO prior FROM organization_profile_events event
  WHERE event.id = p_operation_id;
  IF FOUND THEN
    IF prior.account_id IS DISTINCT FROM p_account_id
      OR prior.requested_name IS DISTINCT FROM normalized_name
      OR prior.expected_updated_at IS DISTINCT FROM p_expected_updated_at
    THEN
      RAISE EXCEPTION 'organization name operation key was reused'
        USING ERRCODE = '23505';
    END IF;
    account.name := prior.requested_name;
    account.updated_at := prior.result_updated_at;
  ELSE
    IF account.updated_at IS DISTINCT FROM p_expected_updated_at THEN
      RAISE EXCEPTION 'organization changed before rename' USING ERRCODE = '40001';
    END IF;
    previous_name_value := account.name;
    UPDATE managed_accounts SET name = normalized_name, updated_at = clock_timestamp()
    WHERE id = p_account_id RETURNING * INTO account;
    INSERT INTO organization_profile_events (
      id, account_id, actor_membership_id, previous_name, requested_name,
      expected_updated_at, result_updated_at
    ) VALUES (
      p_operation_id, p_account_id, actor.id, previous_name_value, normalized_name,
      p_expected_updated_at, account.updated_at
    );
  END IF;
  RETURN pg_catalog.jsonb_build_object(
    'id', account.id,
    'name', account.name,
    'createdAt', account.created_at,
    'updatedAt', account.updated_at
  );
END
$$;

CREATE FUNCTION update_organization_private_session_settings(p_account_id uuid, p_actor_subject_id text, p_enabled boolean, p_expected_version bigint, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  actor_id uuid;
  setting organization_private_session_settings%ROWTYPE;
  prior organization_private_session_setting_events%ROWTYPE;
  next_version bigint;
  did_change boolean;
BEGIN
  IF p_account_id IS NULL OR p_enabled IS NULL OR p_operation_id IS NULL
    OR p_expected_version IS NULL OR p_expected_version < 0
    OR p_actor_subject_id IS DISTINCT FROM opengeni_private.current_subject_id()
    OR p_account_id IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'organization private-session settings request is invalid' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || p_account_id::text, 0));
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'organization_private_session_settings', true);
  PERFORM 1 FROM managed_accounts WHERE id = p_account_id FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002'; END IF;
  -- Revoked/expired keys cannot replay old successful commands.
  PERFORM opengeni_private.assert_organization_administrator(p_account_id, p_actor_subject_id);
  SELECT id INTO actor_id FROM organization_memberships
    WHERE account_id = p_account_id AND subject_id = p_actor_subject_id;
  SELECT * INTO prior FROM organization_private_session_setting_events WHERE id = p_operation_id;
  IF FOUND THEN
    IF prior.account_id IS DISTINCT FROM p_account_id
      OR prior.actor_membership_id IS DISTINCT FROM actor_id
      OR (prior.actor_subject_id IS NOT NULL AND prior.actor_subject_id IS DISTINCT FROM p_actor_subject_id)
      OR prior.requested_enabled IS DISTINCT FROM p_enabled
      OR prior.expected_version IS DISTINCT FROM p_expected_version
    THEN
      RAISE EXCEPTION 'organization private-session operation key was reused' USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'organizationId', p_account_id, 'enabled', prior.result_enabled,
      'available', session_tenancy_product_activated(p_account_id, 1),
      'version', prior.result_version, 'updatedAt', prior.result_updated_at, 'changed', prior.changed
    );
  END IF;
  SELECT * INTO setting FROM organization_private_session_settings WHERE account_id = p_account_id FOR UPDATE;
  IF coalesce(setting.version, 0) IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'organization private-session settings changed before update' USING ERRCODE = '40001';
  END IF;
  did_change := coalesce(setting.enabled, true) IS DISTINCT FROM p_enabled;
  next_version := CASE WHEN setting.account_id IS NULL THEN 1 ELSE setting.version + 1 END;
  INSERT INTO organization_private_session_settings (
    account_id, enabled, version, updated_by_membership_id, updated_at
  ) VALUES (p_account_id, p_enabled, next_version, actor_id, clock_timestamp())
  ON CONFLICT (account_id) DO UPDATE SET
    enabled = excluded.enabled, version = excluded.version,
    updated_by_membership_id = excluded.updated_by_membership_id, updated_at = excluded.updated_at
  RETURNING * INTO setting;
  INSERT INTO organization_private_session_setting_events (
    id, account_id, actor_membership_id, actor_subject_id, requested_enabled,
    expected_version, result_enabled, result_version, result_updated_at, changed
  ) VALUES (
    p_operation_id, p_account_id, actor_id, p_actor_subject_id, p_enabled,
    p_expected_version, setting.enabled, setting.version, setting.updated_at, did_change
  );
  RETURN jsonb_build_object(
    'organizationId', p_account_id, 'enabled', setting.enabled,
    'available', session_tenancy_product_activated(p_account_id, 1),
    'version', setting.version, 'updatedAt', setting.updated_at, 'changed', did_change
  );
END $$;

CREATE FUNCTION update_passkey_sign_count(p_item uuid, p_count bigint, p_principal jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  item_row vault_items;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  item_row := opengeni_private.vault_reachable_item(context, p_item);
  IF item_row.type <> 'passkey' THEN
    PERFORM opengeni_private.vault_raise('vault_item_not_found', 'item is not a passkey',
      pg_catalog.jsonb_build_object('itemId', p_item));
  END IF;
  UPDATE vault_items SET
    passkey_sign_count = greatest(passkey_sign_count, coalesce(p_count, 0)),
    last_used_at = pg_catalog.now()
  WHERE id = item_row.id;
  PERFORM opengeni_private.vault_capability_close();
END
$$;

CREATE FUNCTION update_vault(p_id uuid, p_expected_generation bigint, p jsonb, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  vault_row vaults;
  new_name text;
  allowed uuid[];
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  vault_row := opengeni_private.vault_reachable_row(context, p_id);
  IF vault_row.owner_kind = 'task' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'task vaults cannot be changed');
  END IF;
  IF vault_row.owner_kind = 'organization' AND NOT coalesce((p ->> 'allowOrganization')::boolean, false) THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'organization vaults need account:admin');
  END IF;
  IF p_expected_generation IS DISTINCT FROM vault_row.generation THEN
    PERFORM opengeni_private.vault_raise('vault_generation_conflict', 'vault changed since it was read',
      pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'generation', vault_row.generation));
  END IF;
  new_name := coalesce(p ->> 'name', vault_row.name);
  IF new_name IS DISTINCT FROM vault_row.name THEN
    PERFORM opengeni_private.vault_assert_name(new_name, 'Vault');
  END IF;
  IF vault_name_key(new_name) <> vault_row.name_key THEN
    IF EXISTS (
      SELECT 1 FROM vaults vault
      WHERE vault.account_id = vault_row.account_id AND vault.owner_kind = vault_row.owner_kind
        AND vault.id <> vault_row.id AND vault.name_key = vault_name_key(new_name)
        AND (vault_row.owner_kind = 'organization'
          OR (vault_row.owner_kind = 'workspace' AND vault.workspace_id = vault_row.workspace_id)
          OR (vault_row.owner_kind = 'user'
            AND vault.owner_organization_membership_id = vault_row.owner_organization_membership_id))
    ) THEN
      PERFORM opengeni_private.vault_raise('vault_name_conflict', 'a vault with this name already exists',
        pg_catalog.jsonb_build_object('name', new_name));
    END IF;
    INSERT INTO vault_name_aliases (account_id, scope_key, name_key, vault_id)
    VALUES (vault_row.account_id, opengeni_private.vault_owner_scope_key(vault_row), vault_row.name_key, vault_row.id)
    ON CONFLICT (account_id, scope_key, name_key) DO UPDATE
      SET vault_id = EXCLUDED.vault_id, created_at = pg_catalog.now();
    DELETE FROM vault_name_aliases alias
    WHERE alias.vault_id = vault_row.id AND alias.name_key = vault_name_key(new_name);
  END IF;
  IF p ? 'description' AND p ->> 'description' IS NOT NULL
    AND pg_catalog.char_length(p ->> 'description') > 2000 THEN
    PERFORM opengeni_private.vault_raise('invalid_secret_name', 'vault descriptions are at most 2000 characters');
  END IF;
  IF vault_row.owner_kind = 'user' AND vault_row.is_default AND p ? 'availability'
    AND pg_catalog.jsonb_typeof(p #> '{availability,allowedWorkspaceIds}') = 'array' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied',
      'the default Only-me vault is available in every workspace',
      pg_catalog.jsonb_build_object('vaultId', vault_row.id));
  END IF;
  IF vault_row.owner_kind IN ('organization', 'user') AND p ? 'availability' THEN
    IF pg_catalog.jsonb_typeof(p #> '{availability,allowedWorkspaceIds}') = 'array' THEN
      allowed := ARRAY(SELECT pg_catalog.jsonb_array_elements_text(p #> '{availability,allowedWorkspaceIds}')::uuid);
    END IF;
  END IF;
  UPDATE vaults SET
    name = new_name,
    description = CASE WHEN p ? 'description' THEN p ->> 'description' ELSE description END,
    allowed_workspace_ids = CASE
      WHEN owner_kind = 'organization' AND p ? 'availability' THEN allowed
      WHEN owner_kind = 'user' AND p ? 'availability'
        THEN opengeni_private.vault_workspace_set(allowed)
      ELSE allowed_workspace_ids END,
    allow_personal_workspaces = CASE WHEN owner_kind = 'organization' AND p ? 'availability'
      THEN coalesce((p #>> '{availability,allowPersonalWorkspaces}')::boolean, true)
      ELSE allow_personal_workspaces END,
    generation = generation + 1,
    updated_at = pg_catalog.now()
  WHERE id = vault_row.id
  RETURNING * INTO vault_row;
  PERFORM opengeni_private.vault_audit(vault_row.account_id, (context ->> 'workspaceId')::uuid,
    context ->> 'subjectId', 'vault.updated', 'vault', vault_row.id::text,
    pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'name', vault_row.name,
      'changed', (SELECT coalesce(pg_catalog.jsonb_agg(key), '[]'::jsonb)
        FROM pg_catalog.jsonb_object_keys(p - 'allowOrganization') key)));
  result := opengeni_private.vault_summary_json(vault_row, context) || pg_catalog.jsonb_build_object(
    'tier', CASE vault_row.owner_kind WHEN 'user' THEN 1 WHEN 'workspace' THEN 2 ELSE 3 END);
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION upsert_organization_plan(p_account_id uuid, p_plan_key text, p_status text, p_stripe_subscription_id text, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_cancel_at_period_end boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE state organization_plans%ROWTYPE;
BEGIN
  IF p_account_id IS DISTINCT FROM opengeni_private.current_account_id() THEN
    RAISE EXCEPTION 'Plan account scope mismatch' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:' || p_account_id::text, 0));
  IF opengeni_private.subscription_plan_definition(p_plan_key) IS NULL THEN
    RAISE EXCEPTION 'Unknown subscription plan' USING ERRCODE = '22023';
  END IF;
  INSERT INTO organization_plans(account_id, plan_key, status, stripe_subscription_id,
    current_period_start, current_period_end, cancel_at_period_end)
  VALUES (p_account_id, p_plan_key, p_status, p_stripe_subscription_id, p_period_start, p_period_end, p_cancel_at_period_end)
  ON CONFLICT (account_id) DO UPDATE SET plan_key = excluded.plan_key, status = excluded.status,
    stripe_subscription_id = excluded.stripe_subscription_id, current_period_start = excluded.current_period_start,
    current_period_end = excluded.current_period_end, cancel_at_period_end = excluded.cancel_at_period_end,
    updated_at = CASE WHEN (organization_plans.plan_key, organization_plans.status, organization_plans.stripe_subscription_id,
      organization_plans.current_period_start, organization_plans.current_period_end, organization_plans.cancel_at_period_end)
      IS DISTINCT FROM (excluded.plan_key, excluded.status, excluded.stripe_subscription_id, excluded.current_period_start,
        excluded.current_period_end, excluded.cancel_at_period_end) THEN clock_timestamp() ELSE organization_plans.updated_at END
  RETURNING * INTO state;
  RETURN to_jsonb(state);
END $$;

CREATE FUNCTION upsert_organization_shared_workspace_member(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text, p_target_membership_id uuid, p_subject_label text, p_role text, p_permissions jsonb, p_require_existing boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  target organization_memberships%ROWTYPE;
  access workspace_memberships%ROWTYPE;
  normalized_role text;
  existing_role text;
BEGIN
  IF p_target_membership_id IS NULL
    OR p_require_existing IS NULL
    OR p_permissions IS NULL
    OR pg_catalog.jsonb_typeof(p_permissions) <> 'array'
    OR pg_catalog.jsonb_array_length(p_permissions) > 128
    OR EXISTS (
      SELECT 1 FROM pg_catalog.jsonb_array_elements(p_permissions) item(value)
      WHERE pg_catalog.jsonb_typeof(item.value) <> 'string'
        OR char_length(item.value #>> '{}') NOT BETWEEN 1 AND 128
    )
  THEN
    RAISE EXCEPTION 'organization shared-workspace member request is invalid'
      USING ERRCODE = '22023';
  END IF;

  PERFORM opengeni_private.assert_organization_shared_workspace_administrator(
    p_account_id, p_workspace_id, p_actor_subject_id
  );

  SELECT * INTO target
  FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.id = p_target_membership_id
    AND membership.status = 'active'
    AND membership.subject_id LIKE 'user:%'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'active organization member not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT membership.role INTO existing_role
  FROM workspace_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.workspace_id = p_workspace_id
    AND membership.subject_id = target.subject_id;
  IF p_require_existing AND existing_role IS NULL THEN
    RAISE EXCEPTION 'workspace member not found' USING ERRCODE = 'P0002';
  END IF;
  normalized_role := coalesce(nullif(btrim(p_role), ''), existing_role, 'member');
  IF char_length(normalized_role) NOT BETWEEN 1 AND 64 THEN
    RAISE EXCEPTION 'organization shared-workspace member role is invalid'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO workspace_memberships (
    account_id, workspace_id, subject_id, subject_label, role, permissions
  ) VALUES (
    p_account_id, p_workspace_id, target.subject_id,
    nullif(btrim(p_subject_label), ''), normalized_role, p_permissions
  )
  ON CONFLICT (subject_id, workspace_id) DO UPDATE SET
    subject_label = coalesce(EXCLUDED.subject_label, workspace_memberships.subject_label),
    role = EXCLUDED.role,
    permissions = EXCLUDED.permissions,
    updated_at = pg_catalog.clock_timestamp()
  RETURNING * INTO access;

  RETURN pg_catalog.jsonb_build_object(
    'subjectId', access.subject_id,
    'subjectLabel', access.subject_label,
    'role', access.role,
    'permissions', access.permissions,
    'createdAt', access.created_at
  );
END
$$;

COMMENT ON FUNCTION upsert_organization_shared_workspace_member(p_account_id uuid, p_workspace_id uuid, p_actor_subject_id text, p_target_membership_id uuid, p_subject_label text, p_role text, p_permissions jsonb, p_require_existing boolean) IS 'Assigns or updates one active organization member in a shared workspace without granting the actor operational access.';

CREATE FUNCTION upsert_provider_vault_items(p_vault uuid, p_content_version text, p_items jsonb, p_principal jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $_$
DECLARE
  context jsonb;
  vault_row vaults;
  item_input jsonb;
  field_input jsonb;
  item_row vault_items;
  base_name text;
  candidate text;
  suffix integer;
  item_type text;
  item_category text;
  field_name text;
  field_position integer;
  kept_refs text[] := '{}';
  kept_fields text[];
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  vault_row := opengeni_private.vault_reachable_row(context, p_vault);
  IF vault_row.source = 'opengeni' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'only connected vaults have a provider mirror');
  END IF;
  SELECT locked.* INTO vault_row FROM vaults locked
  WHERE locked.id = vault_row.id
  FOR NO KEY UPDATE OF locked;
  IF vault_row.id IS NULL THEN
    PERFORM opengeni_private.vault_raise('vault_not_found', 'vault not found');
  ELSIF vault_row.source = 'opengeni' THEN
    PERFORM opengeni_private.vault_raise('vault_permission_denied', 'only connected vaults have a provider mirror');
  END IF;
  IF pg_catalog.jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' THEN
    PERFORM opengeni_private.vault_raise('provider_inventory_incomplete',
      'the provider inventory is malformed; the previous inventory was kept');
  ELSIF pg_catalog.jsonb_array_length(p_items) > 2000 THEN
    PERFORM opengeni_private.vault_raise('provider_inventory_incomplete',
      'a connected vault mirrors at most 2000 items; the previous inventory was kept',
      pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'limit', 2000));
  END IF;
  kept_refs := ARRAY(SELECT element ->> 'providerItemRef'
    FROM pg_catalog.jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) element);
  -- Items gone from the provider free their names before anything is renamed.
  DELETE FROM vault_items item
  WHERE item.vault_id = vault_row.id AND item.provider_item_ref IS NOT NULL
    AND NOT (item.provider_item_ref = ANY (kept_refs));
  -- Names are sticky (references keep working): items already mirrored keep
  -- their "Name" or "Name (n)" first, then new items take the next free suffix.
  FOR item_input IN
    SELECT element FROM pg_catalog.jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
      WITH ORDINALITY AS input(element, ordinal)
    ORDER BY nullif(input.element ->> 'archivedAt', '') IS NOT NULL DESC,
      EXISTS (SELECT 1 FROM vault_items mirrored WHERE mirrored.vault_id = vault_row.id
      AND mirrored.provider_item_ref = input.element ->> 'providerItemRef') DESC, input.ordinal
  LOOP
    item_type := CASE WHEN item_input ->> 'type' IN ('login', 'api_key', 'note', 'file', 'card', 'identity',
        'ssh_key') THEN item_input ->> 'type' ELSE 'login' END;
    item_category := CASE WHEN item_input ->> 'category' ~ '^[a-z][a-z0-9_]{0,63}$'
      THEN item_input ->> 'category' END;
    item_row := NULL;
    SELECT item.* INTO item_row FROM vault_items item
    WHERE item.vault_id = vault_row.id AND item.provider_item_ref = item_input ->> 'providerItemRef';
    base_name := opengeni_private.vault_sanitize_legacy_name(item_input ->> 'name');
    IF item_row.id IS NOT NULL
      AND (item_row.name_key = vault_name_key(base_name)
        OR (pg_catalog.left(item_row.name_key, pg_catalog.length(vault_name_key(base_name)) + 2)
              = vault_name_key(base_name) || ' ('
          AND pg_catalog.substr(item_row.name_key, pg_catalog.length(vault_name_key(base_name)) + 3)
              ~ '^[0-9]+\)$'))
      AND (nullif(item_input ->> 'archivedAt', '') IS NOT NULL
        OR NOT EXISTS (SELECT 1 FROM vault_items other WHERE other.vault_id = vault_row.id
        AND other.archived_at IS NULL AND other.name_key = item_row.name_key
        AND other.id <> item_row.id)) THEN
      candidate := item_row.name;
    ELSE
      candidate := base_name;
      suffix := 1;
      WHILE nullif(item_input ->> 'archivedAt', '') IS NULL
        AND EXISTS (SELECT 1 FROM vault_items other WHERE other.vault_id = vault_row.id
        AND other.archived_at IS NULL AND other.name_key = vault_name_key(candidate)
        AND other.id IS DISTINCT FROM item_row.id) LOOP
        suffix := suffix + 1;
        candidate := base_name || ' (' || suffix || ')';
      END LOOP;
    END IF;
    IF item_row.id IS NULL THEN
      INSERT INTO vault_items (account_id, vault_id, type, name, websites, provider_item_ref, provider_version, username_hint_encrypted,
        archived_at, category)
      VALUES (vault_row.account_id, vault_row.id, item_type, candidate,
        coalesce(ARRAY(SELECT pg_catalog.jsonb_array_elements_text(coalesce(item_input -> 'websites', '[]'::jsonb))), '{}'),
        item_input ->> 'providerItemRef', item_input ->> 'providerVersion', item_input ->> 'usernameHintEncrypted',
        nullif(item_input ->> 'archivedAt', '')::timestamptz, item_category)
      RETURNING * INTO item_row;
    ELSE
      UPDATE vault_items SET type = item_type, category = item_category, name = candidate,
        websites = coalesce(ARRAY(SELECT pg_catalog.jsonb_array_elements_text(coalesce(item_input -> 'websites', '[]'::jsonb))), '{}'),
        provider_version = item_input ->> 'providerVersion',
        archived_at = CASE WHEN nullif(item_input ->> 'archivedAt', '') IS NULL THEN NULL
          ELSE coalesce(archived_at, (item_input ->> 'archivedAt')::timestamptz) END,
        username_hint_encrypted = item_input ->> 'usernameHintEncrypted',
        generation = CASE WHEN provider_version IS DISTINCT FROM item_input ->> 'providerVersion'
          OR (archived_at IS NULL) <> (nullif(item_input ->> 'archivedAt', '') IS NULL)
          THEN generation + 1 ELSE generation END,
        updated_at = pg_catalog.now()
      WHERE id = item_row.id RETURNING * INTO item_row;
    END IF;
    kept_fields := '{}';
    field_position := 0;
    FOR field_input IN SELECT element FROM pg_catalog.jsonb_array_elements(coalesce(item_input -> 'fields', '[]'::jsonb)) element LOOP
      field_name := opengeni_private.vault_sanitize_legacy_name(field_input ->> 'name');
      IF vault_name_key(field_name) = 'otp' THEN
        field_name := 'otp code';
      END IF;
      CONTINUE WHEN vault_name_key(field_name) = ANY (kept_fields);
      kept_fields := kept_fields || vault_name_key(field_name);
      INSERT INTO vault_item_fields (account_id, item_id, name, kind, position, current_version, provider_field_ref)
      VALUES (item_row.account_id, item_row.id, field_name,
        CASE WHEN field_input ->> 'kind' IN ('text', 'concealed', 'totp', 'file') THEN field_input ->> 'kind' ELSE 'concealed' END,
        field_position, NULL, field_input ->> 'providerFieldRef')
      ON CONFLICT (item_id, name_key) DO UPDATE SET
        name = EXCLUDED.name, kind = EXCLUDED.kind, position = EXCLUDED.position,
        provider_field_ref = EXCLUDED.provider_field_ref, updated_at = pg_catalog.now();
      field_position := field_position + 1;
    END LOOP;
    DELETE FROM vault_item_fields field WHERE field.item_id = item_row.id AND NOT (field.name_key = ANY (kept_fields));
    UPDATE vault_items SET primary_field_id = (
      SELECT field.id FROM vault_item_fields field WHERE field.item_id = item_row.id
      ORDER BY (field.provider_field_ref = item_input ->> 'primaryFieldRef') DESC NULLS LAST,
        (field.name_key = CASE item_type WHEN 'login' THEN 'password' WHEN 'api_key' THEN 'value'
          WHEN 'note' THEN 'note' WHEN 'card' THEN 'number' WHEN 'ssh_key' THEN 'private key'
          WHEN 'identity' THEN NULL ELSE 'file' END) DESC NULLS LAST,
        (field.kind <> 'text') DESC, field.position
      LIMIT 1)
    WHERE id = item_row.id;
  END LOOP;
  UPDATE vaults SET provider_content_version = p_content_version, last_synced_at = pg_catalog.now(),
    provider_cache_epoch = provider_cache_epoch + 1,
    sync_status = 'ok', sync_error_code = NULL, sync_error_message = NULL, rate_limited_until = NULL,
    updated_at = pg_catalog.now()
  WHERE id = vault_row.id;
  PERFORM opengeni_private.vault_audit(vault_row.account_id, (context ->> 'workspaceId')::uuid,
    context ->> 'subjectId', 'vault.provider.synced', 'vault', vault_row.id::text,
    pg_catalog.jsonb_build_object('vaultId', vault_row.id, 'items', pg_catalog.cardinality(kept_refs),
      'contentVersion', p_content_version));
  PERFORM opengeni_private.vault_capability_close();
END
$_$;

CREATE FUNCTION upsert_session_work_claim_for_attempt(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer, p_operation_id uuid, p_expected_revision integer, p_subject_namespace text, p_subject_type text, p_canonical_key text, p_display_label text, p_role text, p_version_kind text, p_version_value text) RETURNS TABLE(claim_id uuid, session_id uuid, root_session_id uuid, subject_namespace text, subject_type text, canonical_key text, display_label text, role text, state text, revision integer, provenance text, version_kind text, version_value text, observed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, settled_at timestamp with time zone, mutation_kind text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $_$
DECLARE
  authority record;
  existing_revision session_work_claim_revisions%ROWTYPE;
  claim_row session_work_claims%ROWTYPE;
  calculated_digest text;
  calculated_input_hash text;
  mutation_value text;
  now_value timestamptz := clock_timestamp();
  write_capability_id uuid := gen_random_uuid();
  previous_capability text := current_setting(
    'opengeni.session_work_claim_write_capability', true
  );
BEGIN
  PERFORM acquire_session_tenancy_fence(p_workspace_id);
  SELECT * INTO STRICT authority FROM resolve_session_work_claim_attempt_authority(
    p_account_id, p_workspace_id, p_session_id, p_turn_id,
    p_attempt_id, p_execution_generation
  );
  IF p_operation_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision < 0
    OR p_subject_namespace IS NULL
    OR p_subject_namespace <> lower(btrim(p_subject_namespace))
    OR octet_length(p_subject_namespace) NOT BETWEEN 1 AND 64
    OR p_subject_namespace !~ '^[a-z0-9]([a-z0-9._:-]{0,62}[a-z0-9])?$'
    OR p_subject_type NOT IN (
      'repository','branch','pull_request','issue','artifact','release','ci_run','other'
    )
    OR p_canonical_key IS NULL OR p_canonical_key <> btrim(p_canonical_key)
    OR p_canonical_key <> normalize(p_canonical_key, NFKC)
    OR octet_length(p_canonical_key) NOT BETWEEN 1 AND 512
    OR p_canonical_key ~ '[[:cntrl:]]'
    OR (p_display_label IS NOT NULL AND (
      p_display_label <> btrim(p_display_label)
      OR p_display_label <> normalize(p_display_label, NFKC)
      OR octet_length(p_display_label) NOT BETWEEN 1 AND 256
      OR p_display_label ~ '[[:cntrl:]]'
    ))
    OR p_role NOT IN ('working','reviewing','monitoring','delivering')
    OR ((p_version_kind IS NULL) <> (p_version_value IS NULL))
    OR (p_version_kind IS NOT NULL AND (
      p_version_kind NOT IN (
        'git_commit','branch_head','pull_request_head','artifact_version',
        'release_version','ci_run','other'
      )
      OR p_version_value <> btrim(p_version_value)
      OR p_version_value <> normalize(p_version_value, NFKC)
      OR octet_length(p_version_value) NOT BETWEEN 1 AND 256
      OR p_version_value ~ '[[:cntrl:]]'
    ))
  THEN
    RAISE EXCEPTION 'work claim upsert input is invalid' USING ERRCODE = '22023';
  END IF;

  calculated_digest := session_work_claim_subject_digest(
    p_subject_namespace, p_subject_type, p_canonical_key
  );
  calculated_input_hash := encode(sha256(convert_to(jsonb_build_object(
    'accountId', p_account_id,
    'workspaceId', p_workspace_id,
    'sessionId', p_session_id,
    'turnId', p_turn_id,
    'expectedRevision', p_expected_revision,
    'subjectNamespace', p_subject_namespace,
    'subjectType', p_subject_type,
    'canonicalKey', p_canonical_key,
    'displayLabel', p_display_label,
    'role', p_role,
    'versionKind', p_version_kind,
    'versionValue', p_version_value
  )::text, 'UTF8')), 'hex');

  INSERT INTO session_work_claim_write_capabilities (
    backend_pid, transaction_id, capability_id
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), write_capability_id);
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', write_capability_id::text, true
  );

  SELECT * INTO existing_revision FROM session_work_claim_revisions revision_row
  WHERE revision_row.workspace_id = p_workspace_id
    AND revision_row.operation_id = p_operation_id
  FOR SHARE;
  IF FOUND THEN
    IF existing_revision.input_hash <> calculated_input_hash
      OR existing_revision.session_id <> p_session_id
      OR existing_revision.actor_turn_id <> p_turn_id
      OR existing_revision.mutation_kind NOT IN ('created','updated')
    THEN
      RAISE EXCEPTION 'work claim operation conflicts with another input or logical turn'
        USING ERRCODE = '23505';
    END IF;
    claim_row.id := existing_revision.claim_id;
    claim_row.session_id := existing_revision.session_id;
    claim_row.root_session_id := existing_revision.root_session_id;
    claim_row.subject_namespace := existing_revision.subject_namespace;
    claim_row.subject_type := existing_revision.subject_type;
    claim_row.canonical_key := existing_revision.canonical_key;
    claim_row.display_label := existing_revision.display_label;
    claim_row.role := existing_revision.role;
    claim_row.state := existing_revision.state;
    claim_row.revision := existing_revision.resulting_revision;
    claim_row.provenance := existing_revision.provenance;
    claim_row.version_kind := existing_revision.version_kind;
    claim_row.version_value := existing_revision.version_value;
    claim_row.observed_at := existing_revision.observed_at;
    claim_row.created_at := existing_revision.claim_created_at;
    claim_row.updated_at := existing_revision.claim_updated_at;
    claim_row.settled_at := existing_revision.settled_at;
    mutation_value := existing_revision.mutation_kind;
    replayed := true;
  ELSE
    SELECT * INTO claim_row FROM session_work_claims claim
    WHERE claim.workspace_id = p_workspace_id
      AND claim.session_id = p_session_id
      AND claim.subject_namespace = p_subject_namespace
      AND claim.subject_type = p_subject_type
      AND claim.subject_digest = calculated_digest
      AND claim.role = p_role
      AND claim.state = 'active'
    FOR UPDATE;
    IF FOUND THEN
      IF claim_row.revision <> p_expected_revision THEN
        RAISE EXCEPTION 'work claim upsert revision conflict' USING ERRCODE = '40001';
      END IF;
      UPDATE session_work_claims claim SET
        display_label = p_display_label,
        version_kind = p_version_kind,
        version_value = p_version_value,
        observed_at = now_value,
        revision = claim.revision + 1,
        updated_at = now_value
      WHERE claim.workspace_id = p_workspace_id
        AND claim.id = claim_row.id
        AND claim.state = 'active'
        AND claim.revision = p_expected_revision
      RETURNING * INTO STRICT claim_row;
      mutation_value := 'updated';
    ELSE
      IF p_expected_revision <> 0 THEN
        RAISE EXCEPTION 'work claim create revision conflict' USING ERRCODE = '40001';
      END IF;
      IF (SELECT count(*) FROM session_work_claims claim
          WHERE claim.workspace_id = p_workspace_id
            AND claim.session_id = p_session_id
            AND claim.state = 'active') >= 64
      THEN
        RAISE EXCEPTION 'work claim active-record limit reached' USING ERRCODE = '54000';
      END IF;
      INSERT INTO session_work_claims (
        account_id, workspace_id, session_id, root_session_id,
        subject_namespace, subject_type, canonical_key, subject_digest,
        display_label, role, provenance, version_kind, version_value,
        observed_at, created_at, updated_at
      ) VALUES (
        p_account_id, p_workspace_id, p_session_id, authority.root_session_id,
        p_subject_namespace, p_subject_type, p_canonical_key, calculated_digest,
        p_display_label, p_role, 'explicit_agent', p_version_kind, p_version_value,
        now_value, now_value, now_value
      ) RETURNING * INTO claim_row;
      mutation_value := 'created';
    END IF;

    INSERT INTO session_work_claim_revisions (
      account_id, workspace_id, claim_id, session_id, root_session_id,
      operation_id, input_hash, mutation_kind, prior_revision, resulting_revision,
      subject_namespace, subject_type, canonical_key, subject_digest, display_label,
      role, state, provenance, version_kind, version_value, observed_at,
      claim_created_at, claim_updated_at, settled_at, actor_kind, actor_subject_id,
      actor_session_id, actor_turn_id, actor_attempt_id, actor_execution_generation
    ) VALUES (
      p_account_id, p_workspace_id, claim_row.id, p_session_id, claim_row.root_session_id,
      p_operation_id, calculated_input_hash, mutation_value,
      CASE WHEN mutation_value = 'created' THEN NULL ELSE p_expected_revision END,
      claim_row.revision, claim_row.subject_namespace, claim_row.subject_type,
      claim_row.canonical_key, claim_row.subject_digest, claim_row.display_label,
      claim_row.role, claim_row.state, claim_row.provenance, claim_row.version_kind,
      claim_row.version_value, claim_row.observed_at, claim_row.created_at,
      claim_row.updated_at, claim_row.settled_at, 'agent_attempt', authority.actor_subject_id,
      p_session_id, p_turn_id, p_attempt_id, p_execution_generation
    );
    UPDATE sessions session SET updated_at = now_value
    WHERE session.workspace_id = p_workspace_id AND session.id = p_session_id;
    replayed := false;
  END IF;

  claim_id := claim_row.id;
  session_id := claim_row.session_id;
  root_session_id := claim_row.root_session_id;
  subject_namespace := claim_row.subject_namespace;
  subject_type := claim_row.subject_type;
  canonical_key := claim_row.canonical_key;
  display_label := claim_row.display_label;
  role := claim_row.role;
  state := claim_row.state;
  revision := claim_row.revision;
  provenance := claim_row.provenance;
  version_kind := claim_row.version_kind;
  version_value := claim_row.version_value;
  observed_at := claim_row.observed_at;
  created_at := claim_row.created_at;
  updated_at := claim_row.updated_at;
  settled_at := claim_row.settled_at;
  mutation_kind := mutation_value;
  DELETE FROM session_work_claim_write_capabilities capability
  WHERE capability.backend_pid = pg_backend_pid()
    AND capability.transaction_id = pg_current_xact_id()
    AND capability.capability_id = write_capability_id;
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', coalesce(previous_capability, ''), true
  );
  RETURN NEXT;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'opengeni.session_work_claim_write_capability', coalesce(previous_capability, ''), true
  );
  RAISE;
END;
$_$;

CREATE FUNCTION upsert_vault_item(p jsonb, p_principal jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
DECLARE
  context jsonb;
  vault_row vaults;
  existing vault_items;
  item_row vault_items;
  result jsonb;
BEGIN
  PERFORM opengeni_private.vault_capability_open('write');
  context := opengeni_private.vault_context(p_principal);
  IF p ->> 'itemId' IS NOT NULL THEN
    existing := opengeni_private.vault_reachable_item(context, (p ->> 'itemId')::uuid);
    vault_row := opengeni_private.vault_reachable_row(context, existing.vault_id);
  ELSE
    vault_row := opengeni_private.vault_reachable_row(context, (p ->> 'vaultId')::uuid);
    IF p ->> 'mode' = 'upsert' THEN
      SELECT item.* INTO existing FROM vault_items item
      WHERE item.vault_id = vault_row.id AND item.archived_at IS NULL
        AND item.name_key = vault_name_key(p ->> 'name');
    END IF;
  END IF;
  PERFORM opengeni_private.vault_assert_writable(context, vault_row);
  item_row := opengeni_private.vault_write_item(context, vault_row, existing, p);
  result := opengeni_private.vault_item_json(item_row, true)
    || pg_catalog.jsonb_build_object('created', existing.id IS NULL);
  PERFORM opengeni_private.vault_capability_close();
  RETURN result;
END
$$;

CREATE FUNCTION usage_allowance_capability_active(p_account uuid, p_workspace uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM opengeni_private.usage_allowance_capabilities c
    WHERE c.backend_pid = pg_backend_pid()
      AND c.transaction_id = pg_current_xact_id_if_assigned()
      AND c.data_schema = (SELECT n.nspname FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace
        WHERE t.oid='workspaces'::regclass)
      AND ((c.account_id = p_account AND (p_workspace IS NULL OR c.workspace_id = p_workspace))
        OR (p_account IS NULL AND p_workspace IS NULL
          AND c.account_id='00000000-0000-0000-0000-000000000000'::uuid
          AND c.workspace_id='00000000-0000-0000-0000-000000000000'::uuid)))
$$;

CREATE FUNCTION usage_allowance_command(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $_$
DECLARE
  a uuid := (p_input->>'accountId')::uuid;
  w uuid := (p_input->>'workspaceId')::uuid;
  action text := p_input->>'action';
  subject text := p_input->>'subjectId';
  expected bigint := (p_input->>'expectedVersion')::bigint;
  prior opengeni_private.workspace_usage_allowances%ROWTYPE;
  member_prior opengeni_private.workspace_member_allowances%ROWTYPE;
  grant_prior opengeni_private.workspace_allowance_grants%ROWTYPE;
  clear_prior opengeni_private.workspace_allowance_clear_receipts%ROWTYPE;
  clear_request jsonb;
  v bigint;
  opened integer;
  result jsonb;
  period_row record;
  as_of timestamptz := clock_timestamp();
  read_config jsonb; historical opengeni_private.workspace_allowance_periods%ROWTYPE;
  historical_read boolean:=false;
  v_data_schema text := (SELECT n.nspname FROM pg_class t JOIN pg_namespace n ON n.oid=t.relnamespace
    WHERE t.oid='workspaces'::regclass);
BEGIN
  IF opengeni_private.workspace_rls_visible(a, w) IS DISTINCT FROM true OR a IS NULL OR w IS NULL THEN
    RAISE EXCEPTION 'allowance workspace scope denied' USING ERRCODE = '42501';
  END IF;
  IF action IN ('set','clear','member','grant') THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('organization-membership:'||a::text,0));
    IF p_input->>'actorType' NOT IN ('subject','human_session','api_key')
      OR p_input->>'actorSubjectId' IS DISTINCT FROM opengeni_private.current_subject_id() THEN
      RAISE EXCEPTION 'allowance actor scope denied' USING ERRCODE='42501';
    END IF;
    IF (action<>'member' OR p_input->>'actorSubjectId' LIKE 'api_key:%') AND NOT
      (p_input->>'actorSubjectId'='dev' AND p_input->>'actorType' IN ('subject','human_session')
        AND EXISTS (SELECT 1 FROM managed_accounts local_account WHERE local_account.id=a
          AND local_account.external_source='opengeni:local' AND local_account.external_id='default')) THEN
      PERFORM opengeni_private.assert_organization_administrator(a,p_input->>'actorSubjectId');
      IF p_input->>'actorSubjectId' LIKE 'api_key:%' AND NOT EXISTS (
        SELECT 1 FROM api_keys k WHERE k.account_id=a AND 'api_key:'||k.id::text=p_input->>'actorSubjectId'
          AND k.credential_kind='organization' AND k.workspace_id IS NULL AND k.revoked_at IS NULL
          AND (k.expires_at IS NULL OR k.expires_at>clock_timestamp())
          AND k.permissions ? 'workspace:admin' AND k.permissions ? 'api_keys:manage'
      ) THEN RAISE EXCEPTION 'full organization key required' USING ERRCODE='42501'; END IF;
    END IF;
  END IF;
  -- Preserve the canonical workspace-prefix order before the FK pins taken
  -- by counter/policy inserts. Otherwise a workspace writer waiting for this
  -- fence can deadlock with a policy writer waiting for its workspace pin.
  IF action IN ('get','state') THEN
    PERFORM 1 FROM workspaces WHERE id=w AND account_id=a;
  ELSE
    PERFORM 1 FROM workspaces WHERE id=w AND account_id=a FOR KEY SHARE;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'allowance workspace not found' USING ERRCODE='23503'; END IF;
  -- One fence shared by policy mutations, reads and ledger counters.
  PERFORM pg_advisory_xact_lock(hashtextextended('usage-allowance:' || w::text, 0));
  opened := 0;
  IF action NOT IN ('get','state') THEN
  INSERT INTO opengeni_private.usage_allowance_capabilities
    VALUES (pg_backend_pid(), pg_current_xact_id(), v_data_schema, a, w)
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS opened = ROW_COUNT;
  END IF;
  SELECT * INTO prior FROM opengeni_private.workspace_usage_allowances WHERE workspace_id = w AND account_id = a;
  IF action='member' AND p_input->>'actorSubjectId' NOT LIKE 'api_key:%'
    AND NOT (p_input->>'actorSubjectId'='dev' AND EXISTS (SELECT 1 FROM managed_accounts local_account
      WHERE local_account.id=a AND local_account.external_source='opengeni:local' AND local_account.external_id='default'))
    AND NOT EXISTS (SELECT 1 FROM organization_memberships personal_owner
      WHERE personal_owner.account_id=a AND personal_owner.status='active'
        AND personal_owner.subject_id=p_input->>'actorSubjectId' AND personal_owner.personal_workspace_id=w)
    AND NOT EXISTS (
    SELECT 1 FROM workspace_memberships m JOIN organization_memberships om
      ON om.account_id=m.account_id AND om.subject_id=m.subject_id AND om.status='active'
    WHERE m.workspace_id=w AND m.subject_id=p_input->>'actorSubjectId'
      AND (m.role IN ('owner','admin') OR m.permissions ? 'workspace:admin')
  ) THEN RAISE EXCEPTION 'workspace administrator required' USING ERRCODE='42501'; END IF;
  IF action='clear' AND p_input ? 'operationId' THEN
    IF octet_length(coalesce(p_input->>'operationId','')) NOT BETWEEN 1 AND 256 THEN
      RAISE EXCEPTION 'invalid allowance clear operation' USING ERRCODE='22023';
    END IF;
    clear_request:=jsonb_build_object('expectedVersion',expected,
      'actorSubjectId',p_input->>'actorSubjectId','actorType',p_input->>'actorType');
    SELECT * INTO clear_prior FROM opengeni_private.workspace_allowance_clear_receipts
      WHERE workspace_id=w AND account_id=a AND operation_id=p_input->>'operationId';
    IF FOUND THEN
      IF clear_prior.request IS DISTINCT FROM clear_request THEN
        RAISE EXCEPTION 'allowance clear operation conflict' USING ERRCODE='23505';
      END IF;
      IF prior.config IS NOT NULL OR prior.version IS DISTINCT FROM
        (clear_prior.result->>'version')::bigint THEN
        RAISE EXCEPTION 'allowance clear replay superseded' USING ERRCODE='40001';
      END IF;
      IF opened=1 THEN
        DELETE FROM opengeni_private.usage_allowance_capabilities
          WHERE backend_pid=pg_backend_pid() AND transaction_id=pg_current_xact_id_if_assigned()
            AND data_schema=v_data_schema AND workspace_id=w;
      END IF;
      RETURN clear_prior.result;
    END IF;
  END IF;
  -- Settle the pre-edit active window BEFORE switching period mode. In
  -- particular monthly -> none retains this window's settled counters, never
  -- a stale window's counters when no maintenance/read ran during rollover.
  IF action IN ('set','clear','member','grant') AND prior.config IS NOT NULL THEN
    SELECT * INTO period_row FROM usage_allowance_effective_period(w,prior.config,as_of);
    IF prior.active_period_key IS DISTINCT FROM period_row.period_key THEN
      UPDATE opengeni_private.workspace_allowance_periods
        SET closed_at=coalesce(prior.active_end_at,as_of)
        WHERE workspace_id=w AND period_key=prior.active_period_key AND closed_at IS NULL;
    END IF;
    UPDATE opengeni_private.workspace_usage_allowances SET active_period_key=period_row.period_key,
      active_start_at=period_row.start_at,active_end_at=period_row.end_at WHERE workspace_id=w
      RETURNING * INTO prior;
    PERFORM capture_usage_allowance_period(a,w,prior.config,as_of);
  END IF;
  IF action IN ('set','clear','member','grant') THEN
    IF octet_length(coalesce(p_input->>'actorSubjectId','')) NOT BETWEEN 1 AND 1024
      OR octet_length(coalesce(p_input->>'actorType','')) NOT BETWEEN 1 AND 128 THEN
      RAISE EXCEPTION 'allowance actor required' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM workspaces WHERE id = w AND account_id = a) THEN
      RAISE EXCEPTION 'allowance workspace not found' USING ERRCODE = '23503';
    END IF;
  END IF;
  IF action IN ('set','clear') THEN
    IF action='set' AND validate_usage_allowance_config(p_input->'config') IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'invalid allowance config' USING ERRCODE='22023';
    END IF;
    IF expected IS NULL OR expected < 0 OR
      (action='clear' AND expected=0) OR
      (expected = 0 AND prior.version IS NOT NULL) OR
      (expected <> 0 AND expected <> coalesce(prior.version, 0)) THEN
      RAISE EXCEPTION 'allowance version conflict' USING ERRCODE = '40001';
    END IF;
    v := coalesce(prior.version, 0) + 1;
    INSERT INTO opengeni_private.workspace_usage_allowances
      (workspace_id, account_id, config, version, actor_subject_id, actor_type)
    VALUES (w, a, CASE WHEN action = 'set' THEN p_input->'config' END, v,
      p_input->>'actorSubjectId', p_input->>'actorType')
    ON CONFLICT (workspace_id) DO UPDATE SET config = excluded.config,
      version = excluded.version, actor_subject_id = excluded.actor_subject_id,
      actor_type = excluded.actor_type, updated_at = now();
    result := CASE WHEN action = 'set'
      THEN (p_input->'config') || jsonb_build_object('version', v)
      ELSE jsonb_build_object('version', v) END;
    IF action='clear' AND p_input ? 'operationId' THEN
      INSERT INTO opengeni_private.workspace_allowance_clear_receipts
        (workspace_id,account_id,operation_id,request,result)
        VALUES(w,a,p_input->>'operationId',clear_request,result);
    END IF;
  ELSIF action = 'member' THEN
    IF p_input ? 'externalIdentity' THEN
      IF subject IS NOT NULL OR jsonb_typeof(p_input->'externalIdentity') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'ambiguous allowance member identity' USING ERRCODE='22023';
      END IF;
      SELECT identity.subject_id INTO subject FROM external_identities identity
        JOIN usage_allowance_members(a,w) eligible ON eligible.subject_id=identity.subject_id
      WHERE identity.account_id=a AND identity.source=p_input#>>'{externalIdentity,source}'
        AND identity.external_id=p_input#>>'{externalIdentity,externalId}'
        AND identity.status='active';
      IF NOT FOUND THEN RAISE EXCEPTION 'active allowance member not found' USING ERRCODE='23503'; END IF;
    END IF;
    IF validate_usage_allowance_rule(p_input->'rule') IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'invalid member allowance rule' USING ERRCODE='22023';
    END IF;
    IF octet_length(coalesce(subject,'')) NOT BETWEEN 1 AND 1024 THEN
      RAISE EXCEPTION 'allowance subject required' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM usage_allowance_members(a,w) eligible WHERE eligible.subject_id=subject)
    THEN RAISE EXCEPTION 'active allowance member required' USING ERRCODE='23503'; END IF;
    SELECT * INTO member_prior FROM opengeni_private.workspace_member_allowances WHERE workspace_id = w AND subject_id = subject;
    IF expected IS NULL OR expected <> coalesce(member_prior.version, 0) THEN
      RAISE EXCEPTION 'member allowance version conflict' USING ERRCODE = '40001';
    END IF;
    v := coalesce(member_prior.version, 0) + 1;
    INSERT INTO opengeni_private.workspace_member_allowances
      (workspace_id, account_id, subject_id, rule, version, actor_subject_id, actor_type)
    VALUES (w, a, subject, nullif(p_input->'rule','null'::jsonb), v,
      p_input->>'actorSubjectId', p_input->>'actorType')
    ON CONFLICT (workspace_id, subject_id) DO UPDATE SET rule = excluded.rule,
      version = excluded.version, actor_subject_id = excluded.actor_subject_id,
      actor_type = excluded.actor_type, updated_at = now();
    result := jsonb_build_object('subjectId', subject, 'rule', p_input->'rule', 'version', v);
  ELSIF action = 'grant' THEN
    IF coalesce(p_input->>'operationId','')='' OR
      validate_usage_allowance_rule(jsonb_build_object('credits',p_input->'credits')) IS DISTINCT FROM true
      OR (p_input->>'credits')::numeric<=0 THEN
      RAISE EXCEPTION 'invalid allowance grant' USING ERRCODE='22023';
    END IF;
    SELECT * INTO grant_prior FROM opengeni_private.workspace_allowance_grants
      WHERE workspace_id = w AND operation_id = p_input->>'operationId';
    IF FOUND THEN
      IF grant_prior.credits <> (p_input->>'credits')::bigint
        OR grant_prior.expires_at IS DISTINCT FROM (p_input->>'expiresAt')::timestamptz THEN
        RAISE EXCEPTION 'allowance grant operation conflict' USING ERRCODE = '23505';
      END IF;
    ELSE
      INSERT INTO opengeni_private.workspace_allowance_grants
        (workspace_id, account_id, operation_id, credits, remaining, expires_at, actor_subject_id, actor_type)
      VALUES (w, a, p_input->>'operationId', (p_input->>'credits')::bigint,
        (p_input->>'credits')::bigint, (p_input->>'expiresAt')::timestamptz,
        p_input->>'actorSubjectId', p_input->>'actorType')
      RETURNING * INTO grant_prior;
    END IF;
    result := jsonb_build_object('operationId', grant_prior.operation_id,
      'credits', grant_prior.credits, 'remaining', grant_prior.remaining, 'expiresAt', grant_prior.expires_at);
  ELSIF action = 'get' THEN
    result := CASE WHEN prior.config IS NULL THEN NULL ELSE prior.config || jsonb_build_object('version', prior.version) END;
  ELSIF action = 'state' THEN
    result := jsonb_build_object('version',coalesce(prior.version,0),'config',
      CASE WHEN prior.config IS NULL THEN NULL ELSE prior.config || jsonb_build_object('version',prior.version) END);
  ELSIF action IN ('usage','check') THEN
    read_config:=prior.config;
    historical_read:=coalesce(p_input->>'period','current')<>'current' AND
      p_input->>'period' IS DISTINCT FROM (SELECT period_key FROM usage_allowance_effective_period(w,prior.config,clock_timestamp()));
    IF coalesce(p_input->>'period','current') <> 'current' THEN
      IF p_input->>'period' !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
        RAISE EXCEPTION 'invalid allowance period' USING ERRCODE = '22023';
      END IF;
      IF historical_read THEN
        as_of := ((p_input->>'period') || '-01')::timestamp AT TIME ZONE 'UTC'
          + make_interval(days => least(coalesce((prior.config->>'anchorDay')::integer,1),
            extract(day FROM ((p_input->>'period') || '-01')::timestamp + interval '1 month - 1 day')::integer) - 1);
      END IF;
    END IF;
    SELECT * INTO period_row FROM usage_allowance_effective_period(w,prior.config, as_of);
    IF historical_read THEN
      SELECT * INTO historical FROM opengeni_private.workspace_allowance_periods WHERE workspace_id=w
        AND period_key=p_input->>'period';
      read_config:=historical.config;
      IF FOUND THEN
        period_row.start_at:=historical.start_at; period_row.end_at:=historical.end_at;
        period_row.period_key:=historical.period_key;
      ELSE
        read_config:=NULL;
        -- Missing history is unknown, never the active accounting window.
        -- In particular a current nonrenewing pot must not answer an old
        -- YYYY-MM request with today's counters.
        period_row.period_key:=p_input->>'period';
        period_row.start_at:=NULL;
        period_row.end_at:=NULL;
      END IF;
    END IF;
    SELECT jsonb_build_object(
      'config', read_config, 'period', jsonb_build_object('start',period_row.start_at,'end',period_row.end_at),
      'used', coalesce((SELECT used FROM opengeni_private.workspace_allowance_counters WHERE workspace_id=w AND period_key=period_row.period_key AND subject_id=''),0),
      'includedUsed', coalesce((SELECT included_used FROM opengeni_private.workspace_allowance_counters WHERE workspace_id=w AND period_key=period_row.period_key AND subject_id=''),0),
      'grantsUsed', coalesce((SELECT grants_used FROM opengeni_private.workspace_allowance_counters WHERE workspace_id=w AND period_key=period_row.period_key AND subject_id=''),0),
      'grantsRemaining', CASE WHEN historical_read THEN coalesce((SELECT sum((g->>'remaining')::bigint)
        FROM jsonb_array_elements(historical.grants_snapshot) g WHERE g->>'expiresAt' IS NULL
          OR (g->>'expiresAt')::timestamptz>coalesce(historical.end_at,historical.updated_at)),0)
        ELSE coalesce((SELECT sum(remaining) FROM opengeni_private.workspace_allowance_grants WHERE workspace_id=w AND (expires_at IS NULL OR expires_at > clock_timestamp())),0) END,
      'memberCount', CASE WHEN historical_read THEN coalesce(historical.member_count,0)
        ELSE (SELECT count(*) FROM usage_allowance_members(a,w)) END,
      'members', coalesce((SELECT jsonb_agg(row_data ORDER BY row_data->>'subjectId') FROM (
        SELECT jsonb_build_object('subjectId', subjects.subject_id,
          'rule', CASE WHEN historical_read THEN historical.member_rules#>ARRAY[subjects.subject_id,'rule'] ELSE rules.rule END,
          'version', CASE WHEN historical_read THEN coalesce((historical.member_rules#>>ARRAY[subjects.subject_id,'version'])::bigint,0)
            ELSE coalesce(rules.version,0) END, 'used',coalesce(counter.used,0),
          'externalIdentity', CASE WHEN action='check' THEN NULL ELSE (SELECT jsonb_build_object('source',e.source,'externalId',e.external_id)
            FROM external_identities e WHERE e.account_id=a AND e.subject_id=subjects.subject_id) END) row_data
        FROM (
          SELECT eligible.subject_id FROM usage_allowance_members(a,w) eligible WHERE action<>'check' AND NOT historical_read
          UNION SELECT subject WHERE subject IS NOT NULL AND EXISTS (
            SELECT 1 FROM usage_allowance_members(a,w) eligible WHERE eligible.subject_id=subject)
          UNION SELECT jsonb_object_keys(CASE WHEN jsonb_typeof(historical.member_rules)='object'
            THEN historical.member_rules ELSE '{}'::jsonb END) WHERE historical_read AND action<>'check'
          UNION SELECT subject_id FROM opengeni_private.workspace_allowance_counters WHERE workspace_id=w
            AND period_key=period_row.period_key AND subject_id<>'' AND historical_read AND action<>'check'
        ) subjects
        LEFT JOIN opengeni_private.workspace_member_allowances rules ON rules.workspace_id=w AND rules.subject_id=subjects.subject_id
        LEFT JOIN opengeni_private.workspace_allowance_counters counter ON counter.workspace_id=w AND counter.period_key=period_row.period_key AND counter.subject_id=subjects.subject_id
        WHERE (subject IS NULL OR subjects.subject_id=subject)
          AND (p_input->>'cursor' IS NULL OR subjects.subject_id > p_input->>'cursor')
        ORDER BY subjects.subject_id LIMIT least(greatest(coalesce((p_input->>'limit')::integer,100),1),500)+1
      ) page), '[]'::jsonb)
    ) INTO result;
  ELSE
    RAISE EXCEPTION 'invalid allowance action' USING ERRCODE = '22023';
  END IF;
  IF action IN ('set','grant','member') THEN
    SELECT config INTO read_config FROM opengeni_private.workspace_usage_allowances WHERE workspace_id=w;
    IF read_config IS NOT NULL THEN
      SELECT * INTO period_row FROM usage_allowance_effective_period(w,read_config,clock_timestamp());
      IF prior.active_period_key IS NOT NULL AND prior.active_period_key IS DISTINCT FROM period_row.period_key THEN
        UPDATE opengeni_private.workspace_allowance_periods SET closed_at=coalesce(prior.active_end_at,clock_timestamp())
          WHERE workspace_id=w AND period_key=prior.active_period_key AND closed_at IS NULL;
      END IF;
      UPDATE opengeni_private.workspace_usage_allowances SET
        active_period_key=period_row.period_key,active_start_at=period_row.start_at,active_end_at=period_row.end_at,
        maintenance_next_at=clock_timestamp(),maintenance_cursor=NULL WHERE workspace_id=w;
      PERFORM capture_usage_allowance_period(a,w,read_config,clock_timestamp());
    END IF;
  END IF;
  IF opened = 1 THEN
    DELETE FROM opengeni_private.usage_allowance_capabilities WHERE backend_pid=pg_backend_pid()
      AND transaction_id=pg_current_xact_id_if_assigned()
      AND usage_allowance_capabilities.data_schema=v_data_schema AND workspace_id=w;
  END IF;
  RETURN result;
END $_$;

CREATE FUNCTION usage_allowance_effective_period(p_workspace uuid, p_config jsonb, p_at timestamp with time zone) RETURNS TABLE(period_key text, start_at timestamp with time zone, end_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE saved opengeni_private.workspace_usage_allowances%ROWTYPE; calculated record;
BEGIN
  SELECT * INTO saved FROM opengeni_private.workspace_usage_allowances WHERE workspace_id=p_workspace;
  IF saved.active_period_key IS NOT NULL AND p_config->>'period'='none' THEN
    RETURN QUERY SELECT saved.active_period_key,saved.active_start_at,NULL::timestamptz;
    RETURN;
  END IF;
  IF saved.active_period_key IS NOT NULL AND saved.active_end_at IS NULL AND p_config->>'period'='monthly' THEN
    SELECT * INTO calculated FROM usage_allowance_period(p_config,p_at);
    RETURN QUERY SELECT saved.active_period_key,saved.active_start_at,calculated.end_at;
    RETURN;
  END IF;
  IF saved.active_period_key IS NOT NULL AND (saved.active_end_at IS NULL OR p_at<saved.active_end_at) THEN
    RETURN QUERY SELECT saved.active_period_key,saved.active_start_at,saved.active_end_at;
  ELSE
    SELECT * INTO calculated FROM usage_allowance_period(p_config,p_at);
    -- An anchor edit can make the next calculated month overlap the current
    -- accounting key. Extend that window instead of clearing its counters.
    RETURN QUERY SELECT calculated.period_key,
      CASE WHEN calculated.period_key=saved.active_period_key THEN saved.active_start_at ELSE calculated.start_at END,
      calculated.end_at;
  END IF;
END $$;

CREATE FUNCTION usage_allowance_members(p_account uuid, p_workspace uuid) RETURNS TABLE(subject_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT om.subject_id FROM organization_memberships om
  WHERE om.account_id=p_account AND om.status='active'
    AND om.subject_id !~ '^(service:|agent:|api[_-]?key:)'
    AND (om.subject_id LIKE 'user:%' OR EXISTS (
      SELECT 1 FROM external_identities e WHERE e.account_id=om.account_id
        AND e.subject_id=om.subject_id AND e.status='active'))
    AND (om.personal_workspace_id=p_workspace OR EXISTS (
      SELECT 1 FROM workspace_memberships m WHERE m.account_id=p_account
        AND m.workspace_id=p_workspace AND m.subject_id=om.subject_id))
  UNION SELECT 'dev' WHERE EXISTS (SELECT 1 FROM managed_accounts a
    JOIN workspace_memberships m ON m.account_id=a.id AND m.workspace_id=p_workspace AND m.subject_id='dev'
    WHERE a.id=p_account AND a.external_source='opengeni:local' AND a.external_id='default')
$$;

CREATE FUNCTION usage_allowance_period(p_config jsonb, p_at timestamp with time zone) RETURNS TABLE(period_key text, start_at timestamp with time zone, end_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  month_start timestamp := date_trunc('month', p_at AT TIME ZONE 'UTC');
  anchor integer := coalesce((p_config->>'anchorDay')::integer, 1);
  first_start timestamp;
BEGIN
  IF p_config->>'period' = 'none' THEN
    RETURN QUERY SELECT '*', NULL::timestamptz, NULL::timestamptz;
    RETURN;
  END IF;
  first_start := month_start + make_interval(days => least(anchor,
    extract(day FROM month_start + interval '1 month - 1 day')::integer) - 1);
  IF p_at AT TIME ZONE 'UTC' < first_start THEN
    month_start := month_start - interval '1 month';
  END IF;
  RETURN QUERY SELECT to_char(month_start, 'YYYY-MM'),
    (month_start + make_interval(days => least(anchor,
      extract(day FROM month_start + interval '1 month - 1 day')::integer) - 1)) AT TIME ZONE 'UTC',
    (month_start + interval '1 month' + make_interval(days => least(anchor,
      extract(day FROM month_start + interval '2 months - 1 day')::integer) - 1)) AT TIME ZONE 'UTC';
END $$;

CREATE FUNCTION validate_canonical_human_session(p_auth_session_id text, p_auth_user_id text, p_allow_recovery boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      valid boolean;
      revisions_match boolean;
      current_status text;
      previous_marker text := pg_catalog.current_setting(
        'opengeni.canonical_human_identity_lifecycle', true
      );
    BEGIN
      PERFORM pg_catalog.set_config(
        'opengeni.canonical_human_identity_lifecycle', 'active', true
      );
      SELECT
        session_row.identity_revision = identity_row.identity_revision
          AND session_row.auth_revision = identity_row.auth_revision,
        identity_row.status
      INTO revisions_match, current_status
        FROM auth_sessions session_row
        INNER JOIN canonical_human_identity_subjects subject_row
          ON subject_row.auth_user_id = session_row.user_id
         AND subject_row.identity_id = session_row.identity_id
         AND subject_row.status = 'active'
        INNER JOIN canonical_human_identities identity_row
          ON identity_row.id = session_row.identity_id
        WHERE session_row.id = p_auth_session_id
          AND session_row.user_id = p_auth_user_id
          AND subject_row.status = 'active';
      valid := coalesce(revisions_match, false) AND (
        current_status = 'active'
        OR (p_allow_recovery AND current_status = 'recovery_required')
      );
      IF NOT valid AND (
        revisions_match IS DISTINCT FROM true
        OR current_status IS NULL
        OR current_status IN ('disputed', 'disabled')
      ) THEN
        DELETE FROM auth_sessions
        WHERE id = p_auth_session_id AND user_id = p_auth_user_id;
      END IF;
      PERFORM pg_catalog.set_config(
        'opengeni.canonical_human_identity_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END,
        true
      );
      RETURN valid;
    EXCEPTION WHEN OTHERS THEN
      PERFORM pg_catalog.set_config(
        'opengeni.canonical_human_identity_lifecycle',
        CASE WHEN previous_marker IS NULL THEN '' ELSE previous_marker END,
        true
      );
      RAISE;
    END;
    $$;

CREATE FUNCTION validate_personal_codex_credential_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE exact_authority boolean;
BEGIN
  IF NEW.authority_scope IN ('workspace', 'organization') THEN
    RETURN NEW;
  END IF;
  SELECT true INTO exact_authority
  FROM organization_memberships membership
  INNER JOIN organization_user_resource_authorities authority
    ON authority.id = NEW.organization_user_resource_authority_id
   AND authority.account_id = membership.account_id
   AND authority.organization_membership_id = membership.id
  WHERE membership.id = NEW.owner_organization_membership_id
    AND membership.account_id = NEW.account_id
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
    AND authority.resource_kind = 'codex_subscription'
    AND authority.resource_id = NEW.id
    AND authority.generation = NEW.organization_user_resource_authority_generation
    AND authority.status = 'active'
    AND authority.revoked_at IS NULL
  FOR KEY SHARE OF membership, authority;
  IF exact_authority IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'personal Codex credential authority tuple is invalid'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION validate_scheduled_agent_run_live_authority(p_account_id uuid, p_workspace_id uuid, p_run_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  sender_prior_lifecycle text := current_setting('opengeni.organization_tenancy_lifecycle', true);
  run_row record;
  accepted jsonb;
  causal jsonb;
  snapshot record;
  receipt_providers text[] := opengeni_private.subscription_authority_compat_providers();
  core_entries jsonb := '[]'::jsonb;
  core_entry jsonb;
BEGIN
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', 'personal_resource_grant_management', true);
  IF p_account_id IS DISTINCT FROM nullif(
      current_setting('opengeni.account_id', true), ''
    )::uuid
    OR p_workspace_id IS DISTINCT FROM nullif(
      current_setting('opengeni.workspace_id', true), ''
    )::uuid
  THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_authority_scope_changed'; END IF;
  SELECT run.* INTO run_row
  FROM scheduled_task_runs run
  WHERE run.id = p_run_id
    AND run.account_id = p_account_id
    AND run.workspace_id = p_workspace_id
  FOR UPDATE;
  IF NOT FOUND OR run_row.accepted_execution_snapshot IS NULL THEN
    PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_authority_snapshot_missing';
  END IF;
  accepted := run_row.accepted_execution_snapshot;
  causal := accepted -> 'causalHumanAuthority';
  IF cardinality(receipt_providers) > 0 THEN
    core_entries := opengeni_subscription_internal.subscription_scheduled_run_personal_entries(
      p_account_id, p_workspace_id, p_run_id);
  END IF;

  -- Match task admission and organization lifecycle lock order. Claim must
  -- linearize before delivery: a concurrent suspension/revocation either
  -- completes first and is observed below, or waits until this claim commits.
  PERFORM 1 FROM organization_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.id IN (
      SELECT (causal ->> 'organizationMembershipId')::uuid
      WHERE causal IS NOT NULL AND causal <> 'null'::jsonb
      UNION
      SELECT frozen.owner_organization_membership_id
      FROM scheduled_task_run_connection_authority_snapshots frozen
      WHERE frozen.run_id = p_run_id
    )
  ORDER BY membership.id
  FOR SHARE;
  PERFORM 1 FROM workspace_memberships membership
  WHERE membership.account_id = p_account_id
    AND membership.workspace_id = p_workspace_id
    AND membership.subject_id IN (
      SELECT causal ->> 'subjectId'
      WHERE causal IS NOT NULL AND causal <> 'null'::jsonb
      UNION
      SELECT frozen.owner_subject_id
      FROM scheduled_task_run_connection_authority_snapshots frozen
      WHERE frozen.run_id = p_run_id
    )
  ORDER BY membership.subject_id
  FOR SHARE;
  PERFORM 1 FROM connections connection_value
  WHERE connection_value.account_id = p_account_id
    AND connection_value.id IN (
      SELECT frozen.connection_id
      FROM scheduled_task_run_connection_authority_snapshots frozen
      WHERE frozen.run_id = p_run_id
      UNION
      SELECT (accepted -> 'resolvedSlackBotConnection' ->> 'id')::uuid
      WHERE accepted -> 'resolvedSlackBotConnection' <> 'null'::jsonb
    )
  ORDER BY connection_value.id
  FOR SHARE;
  IF accepted -> 'resolvedSlackBotConnection' <> 'null'::jsonb THEN
    DECLARE
      bot_snapshot jsonb := (accepted -> 'resolvedSlackBotConnection');
      bot_account uuid := p_account_id;
      bot_target uuid := p_workspace_id;
      bot_home uuid := p_workspace_id;
      bot_generation bigint := ((accepted -> 'resolvedSlackBotConnection') -> 'metadata' ->> 'organizationSharingGeneration')::bigint;
      bot_prior_workspace text := current_setting('opengeni.workspace_id', true);
      bot_connection record;
      bot_valid boolean := false;
    BEGIN
      -- Discovery determines the home, never authority. Lock the connection before
      -- sharing, matching connection deletion and its access-row cascade.
      IF bot_generation IS NOT NULL THEN
        SELECT access.home_workspace_id INTO bot_home
        FROM opengeni_private.organization_slack_bot_access access
        WHERE access.connection_id = (bot_snapshot ->> 'id')::uuid
          AND access.account_id = bot_account
          AND access.home_workspace_id <> bot_target;
      END IF;
      IF bot_home IS NOT NULL THEN
        PERFORM set_config('opengeni.workspace_id', bot_home::text, true);
        SELECT connection_value.id, connection_value.status, connection_value.subject_id,
            connection_value.provider_domain, connection_value.kind, connection_value.metadata,
            connection_value.verified_install_at, connection_value.version,
            connection_value.verified_install_version INTO bot_connection
        FROM connections connection_value
        WHERE connection_value.id = (bot_snapshot ->> 'id')::uuid
          AND connection_value.account_id = bot_account
          AND connection_value.workspace_id = bot_home
        FOR SHARE;
        PERFORM set_config('opengeni.workspace_id', coalesce(bot_prior_workspace, ''), true);
        bot_valid := bot_connection.id IS NOT NULL
          AND bot_connection.status = 'active'
          AND bot_connection.subject_id IS NULL
          AND bot_connection.provider_domain = 'slack.com'
          AND bot_connection.kind = 'app_install'
          AND bot_connection.metadata ->> 'credentialRole' = 'opengeni_slack_bot'
          AND bot_connection.verified_install_at IS NOT NULL
          AND bot_connection.verified_install_version = bot_connection.version
          AND bot_connection.version = (bot_snapshot ->> 'version')::integer
          AND bot_connection.verified_install_version = (bot_snapshot ->> 'verifiedInstallVersion')::integer
          AND (bot_connection.metadata || CASE WHEN bot_generation IS NULL THEN '{}'::jsonb
            ELSE jsonb_build_object('organizationSharingGeneration', bot_generation) END)
            IS NOT DISTINCT FROM bot_snapshot -> 'metadata';
        IF bot_generation IS NOT NULL THEN
          -- Recheck the frozen generation and target after taking the connection
          -- lock. A concurrent narrowing/revocation must win or wait for admission.
          PERFORM 1 FROM opengeni_private.organization_slack_bot_access access
          WHERE access.connection_id = bot_connection.id
            AND access.account_id = bot_account AND access.home_workspace_id = bot_home
            AND access.enabled AND access.generation = bot_generation
            AND (access.workspace_ids IS NULL OR bot_target = ANY(access.workspace_ids))
          FOR SHARE;
          bot_valid := bot_valid AND FOUND;
        END IF;
      END IF;
      IF bot_valid IS NOT TRUE THEN
        PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true);
        RETURN 'scheduled_slack_bot_changed';
      END IF;
    END;
  END IF;

  PERFORM 1 FROM organization_user_resource_authorities authority
  WHERE authority.account_id = p_account_id
    AND authority.id IN (
      SELECT frozen.authority_id
      FROM scheduled_task_run_connection_authority_snapshots frozen
      WHERE frozen.run_id = p_run_id
      UNION
      SELECT xai_authority.id
      FROM organization_user_resource_authorities xai_authority
      WHERE accepted -> 'xaiProviderAccountAuthoritySnapshot' ->> 'scope' = 'user'
        AND causal IS NOT NULL AND causal <> 'null'::jsonb
        AND xai_authority.account_id = p_account_id
        AND xai_authority.organization_membership_id =
          (causal ->> 'organizationMembershipId')::uuid
        AND xai_authority.resource_kind = 'xai_subscription'
        AND xai_authority.generation =
          (accepted -> 'xaiProviderAccountAuthoritySnapshot'
            ->> 'authorityGeneration')::bigint
      UNION
      SELECT claude_authority.id
      FROM organization_user_resource_authorities claude_authority
      WHERE accepted -> 'claudeProviderAccountAuthoritySnapshot' ->> 'scope' = 'user'
        AND causal IS NOT NULL AND causal <> 'null'::jsonb
        AND claude_authority.account_id = p_account_id
        AND claude_authority.organization_membership_id =
          (causal ->> 'organizationMembershipId')::uuid
        AND claude_authority.resource_kind = 'claude_subscription'
        AND claude_authority.generation =
          (accepted -> 'claudeProviderAccountAuthoritySnapshot'
            ->> 'authorityGeneration')::bigint
      UNION
      SELECT core_authority.id
      FROM organization_user_resource_authorities core_authority
      JOIN jsonb_array_elements(core_entries) core(entry)
        ON core_authority.organization_membership_id::text = core.entry ->> 'ownerMembershipId'
      WHERE core_authority.account_id = p_account_id
        AND core_authority.resource_kind = 'subscription_connection'
        AND core_authority.generation::text = core.entry ->> 'authorityGeneration'
    )
  ORDER BY authority.id
  FOR SHARE;

  PERFORM 1 FROM rigs rig
  WHERE rig.account_id = p_account_id
    AND rig.id IN (
      SELECT (accepted -> 'resolvedRig' ->> 'id')::uuid
      WHERE accepted -> 'targetSessionExecution' = 'null'::jsonb
        AND accepted -> 'resolvedRig' <> 'null'::jsonb
      UNION
      SELECT (accepted -> 'targetSessionExecution' ->> 'rigId')::uuid
      WHERE accepted -> 'targetSessionExecution' <> 'null'::jsonb
        AND accepted -> 'targetSessionExecution' ->> 'rigId' IS NOT NULL
    )
  ORDER BY rig.id
  FOR SHARE;
  PERFORM 1 FROM rig_versions version_value
  WHERE version_value.account_id = p_account_id
    AND version_value.id IN (
      SELECT (accepted -> 'resolvedRig' ->> 'versionId')::uuid
      WHERE accepted -> 'targetSessionExecution' = 'null'::jsonb
        AND accepted -> 'resolvedRig' <> 'null'::jsonb
      UNION
      SELECT (accepted -> 'targetSessionExecution' ->> 'rigVersionId')::uuid
      WHERE accepted -> 'targetSessionExecution' <> 'null'::jsonb
        AND accepted -> 'targetSessionExecution' ->> 'rigVersionId' IS NOT NULL
    )
  ORDER BY version_value.id
  FOR SHARE;

  IF causal IS NOT NULL AND causal <> 'null'::jsonb AND NOT EXISTS (
    SELECT 1 FROM organization_memberships membership
    WHERE membership.id = (causal ->> 'organizationMembershipId')::uuid
      AND membership.account_id = p_account_id
      AND membership.subject_id = causal ->> 'subjectId'
      AND membership.status = 'active'
      AND membership.revoked_at IS NULL
      AND membership.authorization_revision =
        (causal ->> 'membershipAuthorizationRevision')::bigint
      AND (
        membership.personal_workspace_id = p_workspace_id
        OR EXISTS (
          SELECT 1 FROM workspace_memberships workspace_membership
          WHERE workspace_membership.account_id = p_account_id
            AND workspace_membership.workspace_id = p_workspace_id
            AND workspace_membership.subject_id = causal ->> 'subjectId'
        )
      )
  ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_causal_membership_changed'; END IF;
  IF accepted -> 'xaiProviderAccountAuthoritySnapshot' ->> 'scope' = 'user'
    AND NOT 'xai' = ANY(receipt_providers)
    AND NOT EXISTS (
      SELECT 1 FROM organization_user_resource_authorities authority
      WHERE authority.account_id = p_account_id
        AND authority.organization_membership_id =
          (causal ->> 'organizationMembershipId')::uuid
        AND authority.resource_kind = 'xai_subscription'
        AND authority.generation =
          (accepted -> 'xaiProviderAccountAuthoritySnapshot'
            ->> 'authorityGeneration')::bigint
        AND authority.status = 'active'
        AND authority.revoked_at IS NULL
    )
  THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_xai_authority_changed'; END IF;
  IF accepted -> 'claudeProviderAccountAuthoritySnapshot' ->> 'scope' = 'user'
    AND NOT 'claude' = ANY(receipt_providers)
    AND NOT EXISTS (
      SELECT 1 FROM organization_user_resource_authorities authority
      WHERE authority.account_id = p_account_id
        AND authority.organization_membership_id =
          (causal ->> 'organizationMembershipId')::uuid
        AND authority.resource_kind = 'claude_subscription'
        AND authority.generation =
          (accepted -> 'claudeProviderAccountAuthoritySnapshot'
            ->> 'authorityGeneration')::bigint
        AND authority.status = 'active'
        AND authority.revoked_at IS NULL
    )
  THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_claude_authority_changed'; END IF;
  FOR core_entry IN SELECT listed.value FROM jsonb_array_elements(core_entries) listed(value) LOOP
    IF NOT opengeni_subscription_internal.subscription_personal_entry_serviceable(p_account_id, core_entry)
    THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_' || (core_entry ->> 'provider') || '_authority_changed'; END IF;
  END LOOP;


  FOR snapshot IN
    SELECT value.* FROM scheduled_task_run_connection_authority_snapshots value
    WHERE value.run_id = p_run_id
    ORDER BY value.server_id
  LOOP
    IF snapshot.canonical_snapshot ->> 'authoritySource' IS DISTINCT FROM 'sender'
    THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_connection_authority_changed'; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM organization_memberships membership
      WHERE membership.id = snapshot.owner_organization_membership_id
        AND membership.account_id = p_account_id
        AND membership.subject_id = snapshot.owner_subject_id
        AND membership.status = 'active'
        AND membership.revoked_at IS NULL
        AND membership.authorization_revision = snapshot.membership_authorization_revision
        AND (
          membership.personal_workspace_id = p_workspace_id
          OR EXISTS (
            SELECT 1 FROM workspace_memberships workspace_membership
            WHERE workspace_membership.account_id = p_account_id
              AND workspace_membership.workspace_id = p_workspace_id
              AND workspace_membership.subject_id = snapshot.owner_subject_id
          )
        )
    ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_connection_membership_changed'; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM opengeni_private.read_sender_connection(
        p_account_id, snapshot.origin_workspace_id, snapshot.connection_id, snapshot.owner_subject_id
      ) connection_value
      WHERE connection_value.id = snapshot.connection_id
        AND connection_value.account_id = p_account_id
        AND connection_value.workspace_id = snapshot.origin_workspace_id
        AND connection_value.subject_id = snapshot.owner_subject_id
        AND connection_value.owner_organization_membership_id =
          snapshot.owner_organization_membership_id
        AND connection_value.authority_scope = 'user'
        AND connection_value.authority_generation = snapshot.connection_generation
        AND connection_value.status = 'active'
        AND lower(connection_value.provider_domain) = snapshot.provider_domain
        AND connection_value.kind = snapshot.connection_kind
    ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_connection_changed'; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM organization_user_resource_authorities authority
      WHERE authority.id = snapshot.authority_id
        AND authority.account_id = p_account_id
        AND authority.organization_membership_id =
          snapshot.owner_organization_membership_id
        AND authority.resource_kind = 'connection'
        AND authority.resource_id = snapshot.connection_id
        AND authority.origin_workspace_id = snapshot.origin_workspace_id
        AND authority.generation = snapshot.authority_generation
        AND authority.status = 'active'
        AND authority.revoked_at IS NULL
    ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_connection_authority_changed'; END IF;
  END LOOP;

  IF accepted -> 'targetSessionExecution' = 'null'::jsonb THEN
    IF accepted -> 'resolvedVariableSet' <> 'null'::jsonb AND NOT EXISTS (
      SELECT 1 FROM workspace_variable_sets variable_set
      WHERE variable_set.id = (accepted -> 'resolvedVariableSet' ->> 'id')::uuid
        AND variable_set.account_id = p_account_id
        AND variable_set.status = 'active'
        AND variable_set.generation =
          (accepted -> 'resolvedVariableSet' ->> 'generation')::bigint
    ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_variable_set_changed'; END IF;
    IF accepted -> 'resolvedRig' <> 'null'::jsonb AND NOT EXISTS (
      SELECT 1 FROM rigs rig
      JOIN rig_versions version_value
        ON version_value.id = (accepted -> 'resolvedRig' ->> 'versionId')::uuid
       AND version_value.rig_id = rig.id
       AND version_value.account_id = rig.account_id
      WHERE rig.id = (accepted -> 'resolvedRig' ->> 'id')::uuid
        AND rig.account_id = p_account_id
        AND rig.status = 'active'
    ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_rig_changed'; END IF;
    IF accepted -> 'resolvedRig' <> 'null'::jsonb AND (
      accepted -> 'resolvedRig' -> 'defaultVariableSets' IS DISTINCT FROM (
        SELECT coalesce(
          jsonb_agg(
            jsonb_build_object('id', variable_set.id, 'generation', variable_set.generation)
            ORDER BY selected.ordinality
          ),
          '[]'::jsonb
        )
        FROM rig_versions version_value
        CROSS JOIN LATERAL jsonb_array_elements_text(
          coalesce(version_value.default_variable_set_ids, '[]'::jsonb)
        ) WITH ORDINALITY selected(id, ordinality)
        JOIN workspace_variable_sets variable_set
          ON variable_set.id = selected.id::uuid
         AND variable_set.account_id = p_account_id
         AND variable_set.status = 'active'
        WHERE version_value.id = (accepted -> 'resolvedRig' ->> 'versionId')::uuid
          AND version_value.rig_id = (accepted -> 'resolvedRig' ->> 'id')::uuid
          AND version_value.account_id = p_account_id
      )
    ) THEN PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN 'scheduled_rig_default_variable_set_changed'; END IF;
  END IF;
  PERFORM set_config('opengeni.organization_tenancy_lifecycle', coalesce(sender_prior_lifecycle, ''), true); RETURN NULL;
EXCEPTION WHEN OTHERS THEN RAISE;
END
$$;

CREATE FUNCTION validate_scheduled_occurrence_accepted_execution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE
  run_row record;
  accepted jsonb;
  task_snapshot jsonb;
  expected_payload jsonb;
BEGIN
  IF NEW.kind <> 'scheduled_occurrence' THEN RETURN NEW; END IF;
  IF NEW.scheduled_task_run_id IS NULL THEN
    RAISE EXCEPTION 'scheduled occurrence requires an accepted run'
      USING ERRCODE = '42501';
  END IF;
  SELECT run.* INTO STRICT run_row FROM scheduled_task_runs run
  WHERE run.id = NEW.scheduled_task_run_id
    AND run.account_id = NEW.account_id
    AND run.workspace_id = NEW.workspace_id
    AND run.session_id = NEW.session_id
    AND run.status IN ('queued', 'dispatched')
  FOR UPDATE;
  accepted := run_row.accepted_execution_snapshot;
  task_snapshot := accepted -> 'task';
  IF accepted IS NULL
    OR run_row.accepted_execution_digest IS DISTINCT FROM encode(
      digest(convert_to(accepted::text, 'UTF8'), 'sha256'), 'hex'
    )
    OR NOT (
      ((task_snapshot ->> 'authorityRevision')::bigint = run_row.task_authority_revision
        AND task_snapshot ->> 'executionDigest' = run_row.task_execution_digest)
      OR EXISTS (
        SELECT 1 FROM scheduled_task_reusable_connection_materializations receipt
        WHERE receipt.task_id = run_row.task_id
          AND receipt.account_id = run_row.account_id
          AND receipt.workspace_id = run_row.workspace_id
          AND receipt.session_id = run_row.session_id
          AND receipt.source_task_authority_revision =
            (task_snapshot ->> 'authorityRevision')::bigint
          AND receipt.source_execution_digest = task_snapshot ->> 'executionDigest'
          AND receipt.target_task_authority_revision = run_row.task_authority_revision
          AND receipt.target_execution_digest = run_row.task_execution_digest
      )
    )
  THEN
    RAISE EXCEPTION 'scheduled occurrence accepted execution binding changed'
      USING ERRCODE = '42501';
  END IF;

  expected_payload := jsonb_build_object(
    'type', 'scheduled_occurrence',
    'text', task_snapshot -> 'agentConfig' ->> 'prompt',
    'scheduledTaskId', run_row.task_id,
    'scheduledTaskRunId', run_row.id
  );
  IF jsonb_array_length(task_snapshot -> 'agentConfig' -> 'resources') > 0 THEN
    expected_payload := expected_payload || jsonb_build_object(
      'resources', task_snapshot -> 'agentConfig' -> 'resources'
    );
  END IF;
  IF jsonb_array_length(accepted -> 'resolvedTools') > 0 THEN
    expected_payload := expected_payload || jsonb_build_object(
      'tools', accepted -> 'resolvedTools'
    );
  END IF;
  expected_payload := expected_payload || coalesce((
    SELECT jsonb_build_object('unavailableConnectors',
      jsonb_agg(degraded.server_id ORDER BY degraded.server_id COLLATE "C"))
    FROM (
      SELECT DISTINCT account ->> 'serverId' AS server_id
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(accepted -> 'degradedAccounts') = 'array'
        THEN accepted -> 'degradedAccounts' ELSE '[]'::jsonb END) account
    ) degraded
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(accepted -> 'resolvedTools') = 'array'
        THEN accepted -> 'resolvedTools' ELSE '[]'::jsonb END) tool
      WHERE tool ->> 'kind' = 'mcp' AND tool ->> 'id' = degraded.server_id
    )
    HAVING count(*) > 0
  ), '{}'::jsonb);
  IF run_row.trigger_type = 'event' AND NEW.payload ? 'events' THEN
    IF NOT coalesce((
      SELECT jsonb_typeof(carried.events) = 'object'
        AND carried.events ?& ARRAY['occurrenceId', 'eventCount', 'events', 'gapBefore']
        AND (SELECT count(*) FROM jsonb_object_keys(carried.events)) = 4
        AND carried.events ->> 'occurrenceId' = occurrence.id::text
        AND carried.events -> 'eventCount' = to_jsonb(occurrence.event_count)
        AND carried.events -> 'gapBefore' = to_jsonb(occurrence.gap_before)
        AND jsonb_typeof(carried.events -> 'events') = 'array'
        AND jsonb_array_length(carried.events -> 'events') <= jsonb_array_length(occurrence.events)
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(carried.events -> 'events') WITH ORDINALITY AS item(event, position)
          WHERE jsonb_typeof(item.event) IS DISTINCT FROM 'object'
            OR jsonb_typeof(item.event -> 'data') IS DISTINCT FROM 'object'
            OR jsonb_typeof(item.event -> 'dataTruncated') IS DISTINCT FROM 'boolean'
            OR (item.event - 'data' - 'dataTruncated')
              IS DISTINCT FROM occurrence.events -> (item.position::integer - 1))
      FROM (SELECT NEW.payload -> 'events' AS events) carried
      JOIN scheduled_task_event_occurrences occurrence
        ON run_row.producer_key = 'scheduled-task-event:' || occurrence.id::text
      WHERE occurrence.task_id = run_row.task_id
        AND occurrence.account_id = run_row.account_id
        AND occurrence.workspace_id = run_row.workspace_id
    ), false) THEN
      RAISE EXCEPTION 'scheduled occurrence events differ from the run''s occurrence'
        USING ERRCODE = '42501';
    END IF;
    expected_payload := expected_payload || jsonb_build_object('events', NEW.payload -> 'events');
  END IF;
  IF NEW.source_id IS DISTINCT FROM run_row.id::text
    OR NEW.dedupe_key IS DISTINCT FROM 'scheduled-task-run:' || run_row.id::text
    OR NEW.summary IS DISTINCT FROM task_snapshot -> 'agentConfig' ->> 'prompt'
    OR NEW.payload IS DISTINCT FROM expected_payload
    OR NEW.personal_connection_delegations
      IS DISTINCT FROM accepted -> 'personalConnectionDelegations'
    OR NEW.xai_provider_account_authority_snapshot
      IS DISTINCT FROM accepted -> 'xaiProviderAccountAuthoritySnapshot'
    OR NEW.claude_provider_account_authority_snapshot
      IS DISTINCT FROM coalesce(accepted -> 'claudeProviderAccountAuthoritySnapshot',
        '{"version":1,"scope":"workspace"}'::jsonb)
    OR NEW.lineage ->> 'claudeAuthoritySubjectId'
      IS DISTINCT FROM accepted ->> 'claudeAuthoritySubjectId'
    OR NOT (
      opengeni_subscription_internal.subscription_v2_copy_matches(NEW.subscription_authority,
        opengeni_subscription_internal.subscription_scheduled_firing_v2(NEW.account_id,
          NEW.workspace_id, run_row.task_id, (task_snapshot ->> 'authorityRevision')::bigint))
      OR opengeni_subscription_internal.subscription_v2_copy_matches(NEW.subscription_authority,
        opengeni_subscription_internal.subscription_scheduled_firing_v2(NEW.account_id,
          NEW.workspace_id, run_row.task_id, run_row.task_authority_revision)))
    OR NEW.lineage ->> 'scheduledTaskId' IS DISTINCT FROM run_row.task_id::text
    OR NEW.lineage ->> 'scheduledTaskRunId' IS DISTINCT FROM run_row.id::text
    OR NEW.lineage ->> 'causalHumanSubjectId'
      IS DISTINCT FROM accepted ->> 'causalHumanSubjectId'
    OR NEW.lineage ->> 'connectionAuthoritySubjectId'
      IS DISTINCT FROM accepted ->> 'connectionAuthoritySubjectId'
    OR NEW.lineage ->> 'xaiAuthoritySubjectId'
      IS DISTINCT FROM accepted ->> 'xaiAuthoritySubjectId'
    OR (accepted ->> 'incidentPreflightRequired')::boolean
      IS DISTINCT FROM (NEW.lineage ? 'incidentTelemetryAuthorityFence')
  THEN
    RAISE EXCEPTION 'scheduled occurrence differs from accepted execution'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION validate_scheduled_task_attempt_personal_resources() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'public', 'pg_temp'
    AS $$
DECLARE
  scheduled_run_id uuid;
  run_count integer;
  admission_row record;
  turn_subject text;
  mismatch_count integer;
BEGIN
  SELECT count(DISTINCT update_row.scheduled_task_run_id)::integer,
    min(update_row.scheduled_task_run_id::text)::uuid
  INTO run_count, scheduled_run_id
  FROM session_system_updates update_row
  WHERE update_row.workspace_id = NEW.workspace_id
    AND update_row.session_id = NEW.session_id
    AND update_row.delivered_turn_id = NEW.turn_id
    AND update_row.kind = 'scheduled_occurrence'
    AND update_row.scheduled_task_run_id IS NOT NULL;
  IF run_count = 0 THEN RETURN NEW; END IF;
  IF run_count <> 1 THEN
    RAISE EXCEPTION 'scheduled personal-resource attempt requires one occurrence snapshot'
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO opengeni_private.scheduled_personal_resource_capabilities (
    backend_pid, transaction_id, capability_kind
  ) VALUES (pg_backend_pid(), pg_current_xact_id(), 'attempt_match')
  ON CONFLICT DO NOTHING;

  SELECT admission.* INTO admission_row
  FROM scheduled_task_run_personal_resource_admissions admission
  WHERE admission.run_id = scheduled_run_id;
  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1 FROM session_attempt_personal_resource_snapshots snapshot
      WHERE snapshot.attempt_id = NEW.id
    ) THEN
      RAISE EXCEPTION 'scheduled occurrence has no admitted personal-resource snapshot'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  SELECT coalesce(
    nullif(btrim(turn_value.initiating_human_subject_id), ''),
    CASE WHEN turn_value.initiator_kind = 'subject'
      THEN nullif(btrim(turn_value.initiator_subject_id), '') END
  ) INTO turn_subject
  FROM session_turns turn_value
  WHERE turn_value.id = NEW.turn_id
    AND turn_value.account_id = NEW.account_id
    AND turn_value.workspace_id = NEW.workspace_id
    AND turn_value.session_id = NEW.session_id;
  IF turn_subject IS DISTINCT FROM admission_row.initiating_human_subject_id THEN
    RAISE EXCEPTION 'scheduled occurrence causal human mismatch' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM scheduled_task_runs run
  JOIN session_turns turn_value
    ON turn_value.id = NEW.turn_id
   AND turn_value.account_id = run.account_id
   AND turn_value.workspace_id = run.workspace_id
   AND turn_value.session_id = run.session_id
   AND turn_value.scheduled_task_run_id = run.id
  WHERE run.id = scheduled_run_id
    AND run.task_id = admission_row.task_id
    AND run.account_id = admission_row.account_id
    AND run.workspace_id = admission_row.workspace_id
    AND run.session_id = NEW.session_id
    AND run.status IN ('queued', 'dispatched')
    AND run.task_authority_revision = admission_row.task_authority_revision
    AND run.task_execution_digest = admission_row.execution_digest
  FOR SHARE OF run, turn_value;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scheduled run authority changed before attempt admission'
      USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer INTO mismatch_count
  FROM scheduled_task_run_personal_resource_snapshots run_snapshot
  FULL JOIN session_attempt_personal_resource_snapshots attempt_snapshot
    ON attempt_snapshot.attempt_id = NEW.id
   AND attempt_snapshot.resource_kind = run_snapshot.resource_kind
   AND attempt_snapshot.resource_id = run_snapshot.resource_id
  WHERE run_snapshot.run_id = scheduled_run_id
    AND (
      attempt_snapshot.attempt_id IS NULL
      OR attempt_snapshot.resource_version_id IS DISTINCT FROM run_snapshot.resource_version_id
      OR attempt_snapshot.selection_sources IS DISTINCT FROM run_snapshot.selection_sources
      OR attempt_snapshot.authority_id IS DISTINCT FROM run_snapshot.authority_id
      OR attempt_snapshot.authority_generation IS DISTINCT FROM run_snapshot.authority_generation
      OR attempt_snapshot.grant_id IS DISTINCT FROM run_snapshot.grant_id
      OR attempt_snapshot.grant_generation IS DISTINCT FROM run_snapshot.grant_generation
      OR attempt_snapshot.grant_mode IS DISTINCT FROM run_snapshot.grant_mode
    );
  IF mismatch_count <> 0 OR (
    SELECT count(*) FROM session_attempt_personal_resource_snapshots snapshot
    WHERE snapshot.attempt_id = NEW.id
  ) <> admission_row.resource_count THEN
    RAISE EXCEPTION 'scheduled occurrence personal-resource snapshot widened or changed'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'attempt_match';
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  DELETE FROM opengeni_private.scheduled_personal_resource_capabilities
  WHERE backend_pid = pg_backend_pid()
    AND transaction_id = pg_current_xact_id_if_assigned()
    AND capability_kind = 'attempt_match';
  RAISE;
END
$$;

CREATE FUNCTION validate_task_note_knowledge_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE
  note_row task_notes%ROWTYPE;
  capability_row task_note_knowledge_promotion_capabilities%ROWTYPE;
BEGIN
  IF NEW.task_note_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT capability.* INTO capability_row
  FROM task_note_knowledge_promotion_capabilities capability
  WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
    AND capability.transaction_id = pg_catalog.pg_current_xact_id()
    AND capability.capability_id = nullif(
      pg_catalog.current_setting('opengeni.task_note_knowledge_promotion_capability', true), ''
    )::uuid
    AND capability.account_id = NEW.account_id
    AND capability.workspace_id = NEW.scope_workspace_id
    AND capability.note_id = NEW.task_note_id
    AND capability.root_session_id = NEW.task_note_root_session_id
    AND capability.note_version = NEW.task_note_version
    AND capability.note_text_hash = NEW.content_hash
    AND capability.evidence_operation_id = NEW.operation_id
    AND capability.actor_subject_id = NEW.actor_subject_id
    AND capability.initiating_human_subject_id = NEW.initiating_human_subject_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task-note Knowledge evidence requires exact promotion capability'
      USING ERRCODE = '42501';
  END IF;

  SELECT note.* INTO note_row
  FROM task_notes note
  WHERE note.id = NEW.task_note_id
    AND note.account_id = NEW.account_id
    AND note.workspace_id = NEW.scope_workspace_id;
  IF NOT FOUND
    OR NEW.task_note_root_session_id IS DISTINCT FROM note_row.root_session_id
    OR NEW.task_note_version IS DISTINCT FROM note_row.version
    OR NEW.content_hash IS DISTINCT FROM note_row.text_hash
  THEN
    RAISE EXCEPTION 'Knowledge evidence does not match the exact Task-note source receipt'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM knowledge_claims claim
    JOIN knowledge_facts fact
      ON fact.account_id = claim.account_id
      AND fact.id = claim.fact_id
      AND fact.scope_key = claim.scope_key
    WHERE claim.id = NEW.claim_id
      AND claim.account_id = NEW.account_id
      AND claim.scope_kind = 'workspace'
      AND claim.scope_workspace_id = NEW.scope_workspace_id
      AND claim.scope_subject_id IS NULL
      AND claim.operation_id = capability_row.claim_operation_id
      AND claim.actor_kind = NEW.actor_kind
      AND claim.actor_subject_id = capability_row.actor_subject_id
      AND claim.initiating_human_subject_id = capability_row.initiating_human_subject_id
      AND claim.extraction_method = 'task-note-promotion-v1'
      AND claim.extraction_metadata = pg_catalog.jsonb_build_object(
        'taskNoteId', note_row.id,
        'taskNoteRootSessionId', note_row.root_session_id,
        'taskNoteVersion', note_row.version,
        'taskNoteTextHash', note_row.text_hash
      )
      AND fact.scope_kind = 'workspace'
      AND fact.scope_workspace_id = NEW.scope_workspace_id
      AND fact.scope_subject_id IS NULL
      AND fact.object_kind = 'text'
      AND fact.object_entity_id IS NULL
      AND fact.object_value = pg_catalog.to_jsonb(note_row.text)
      AND fact.actor_kind = NEW.actor_kind
      AND fact.actor_subject_id = capability_row.actor_subject_id
      AND fact.initiating_human_subject_id = capability_row.initiating_human_subject_id
  ) THEN
    RAISE EXCEPTION 'Task-note Knowledge evidence claim/fact is outside the admitted promotion lineage'
      USING ERRCODE = '42501';
  END IF;
  DELETE FROM task_note_knowledge_promotion_capabilities capability
  WHERE capability.backend_pid = capability_row.backend_pid
    AND capability.transaction_id = capability_row.transaction_id
    AND capability.capability_id = capability_row.capability_id;
  PERFORM pg_catalog.set_config('opengeni.task_note_knowledge_promotion_capability', '', true);
  RETURN NEW;
END;
$$;

CREATE FUNCTION validate_usage_allowance_config(p_config jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE thresholds jsonb; threshold_item jsonb; default_rule jsonb;
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object' OR octet_length(p_config::text)>8192
    OR jsonb_typeof(p_config->'includedCredits') IS DISTINCT FROM 'number'
    OR coalesce(p_config->>'period','') NOT IN ('monthly','none') THEN RETURN false; END IF;
  IF NOT validate_usage_allowance_rule(jsonb_build_object('credits',p_config->'includedCredits')) THEN RETURN false; END IF;
  IF p_config ? 'anchorDay' AND (jsonb_typeof(p_config->'anchorDay')<>'number'
    OR (p_config->>'anchorDay')::numeric NOT BETWEEN 1 AND 31
    OR trunc((p_config->>'anchorDay')::numeric)<>(p_config->>'anchorDay')::numeric) THEN RETURN false; END IF;
  IF p_config ? 'unbilledUsage' AND (jsonb_typeof(p_config->'unbilledUsage') IS DISTINCT FROM 'string'
    OR p_config->>'unbilledUsage' NOT IN ('ignore','list_price')) THEN RETURN false; END IF;
  default_rule:=p_config->'memberDefault';
  IF default_rule IS NOT NULL AND default_rule NOT IN ('"none"'::jsonb,'"equal_share"'::jsonb)
    AND (default_rule='null'::jsonb OR NOT validate_usage_allowance_rule(default_rule)) THEN RETURN false; END IF;
  IF p_config ? 'thresholds' THEN
    IF jsonb_typeof(p_config->'thresholds')<>'object' THEN RETURN false; END IF;
    FOR thresholds IN SELECT item.value FROM jsonb_each(p_config->'thresholds') item LOOP
      IF jsonb_typeof(thresholds)<>'array' OR jsonb_array_length(thresholds)>16 THEN RETURN false; END IF;
      FOR threshold_item IN SELECT jsonb_array_elements(thresholds) LOOP
        IF jsonb_typeof(threshold_item)<>'number' OR (threshold_item#>>'{}')::numeric<=0 OR (threshold_item#>>'{}')::numeric>1 THEN RETURN false; END IF;
      END LOOP;
    END LOOP;
  END IF;
  RETURN true;
END $$;

CREATE FUNCTION validate_usage_allowance_rule(p_rule jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF p_rule IS NULL OR p_rule='null'::jsonb THEN RETURN true; END IF;
  IF jsonb_typeof(p_rule)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(p_rule))<>1 THEN RETURN false; END IF;
  IF p_rule ? 'credits' THEN
    RETURN jsonb_typeof(p_rule->'credits')='number' AND (p_rule->>'credits')::numeric BETWEEN 0 AND 9007199254740991
      AND trunc((p_rule->>'credits')::numeric)=(p_rule->>'credits')::numeric;
  END IF;
  RETURN coalesce(p_rule ? 'share' AND jsonb_typeof(p_rule->'share')='number' AND (p_rule->>'share')::numeric>=0,false);
END $$;

CREATE FUNCTION vault_actor_membership(p_account uuid, p_subject text) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'opengeni_private', 'pg_temp'
    AS $$
  SELECT membership.id FROM organization_memberships membership
  WHERE membership.account_id = p_account
    AND membership.subject_id = p_subject
    AND membership.status = 'active'
    AND membership.revoked_at IS NULL
  LIMIT 1
$$;

CREATE FUNCTION verify_organization_resource_classification(p_organization_id uuid, p_run_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    SET statement_timeout TO '5min'
    AS $_$
DECLARE
  -- family label (0286 vocabulary), resource table, authority resource_kind
  families constant text[][] := ARRAY[
    ARRAY['variable_sets', 'workspace_variable_sets', 'variable_set'],
    ARRAY['rigs', 'rigs', 'rig'],
    ARRAY['machines', 'enrollments', 'connected_machine']
  ];
  family text[];
  claimed_rows integer := 0;
  claimed boolean := false;
  ledger_available boolean;
  classification_sql text;
  family_result jsonb;
  families_result jsonb := '{}'::jsonb;
  receipt_id uuid;
  unresolved_row record;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'resource classification requires an organization id'
      USING ERRCODE = '22004';
  END IF;
  IF p_organization_id IS DISTINCT FROM nullif(
      pg_catalog.current_setting('opengeni.account_id', true), ''
    )::uuid
  THEN
    RAISE EXCEPTION 'resource classification scope mismatch'
      USING ERRCODE = '42501';
  END IF;
  IF p_run_key IS NOT NULL AND length(btrim(p_run_key)) = 0 THEN
    RAISE EXCEPTION 'resource classification run key must not be blank'
      USING ERRCODE = '22023';
  END IF;

  -- The ledger lives in its own migration. Probe rather than assume, so this
  -- seam neither hard-fails nor silently drops the obligation when the two
  -- land in either order.
  ledger_available := p_run_key IS NOT NULL
    AND to_regprocedure('open_tenancy_backfill_receipt(uuid, text, text)') IS NOT NULL
    AND to_regprocedure('record_tenancy_backfill_unresolved(uuid, uuid, text)') IS NOT NULL
    AND to_regprocedure(
      'complete_tenancy_backfill_receipt(uuid, bigint, bigint, text)'
    ) IS NOT NULL;

  INSERT INTO opengeni_private.resource_classification_capabilities (
    backend_pid, transaction_id
  ) VALUES (pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id())
  ON CONFLICT DO NOTHING;
  -- Only release what this call claimed, so a nested or enclosing holder of
  -- the same transaction-scoped capability is never revoked underneath.
  GET DIAGNOSTICS claimed_rows = ROW_COUNT;
  claimed := claimed_rows > 0;

  FOREACH family SLICE 1 IN ARRAY families LOOP
    -- One verdict per row. The first two branches are the phase D terminal
    -- states; every other branch is an explicit refusal to classify, carrying
    -- a fixed 0286 reason code and never a proposed owner.
    classification_sql := format($classification$
      SELECT resource.id AS resource_id,
        CASE
          WHEN resource.authority_scope = 'workspace'
            AND resource.authority_id IS NULL
            AND resource.owner_organization_membership_id IS NULL
            THEN 'workspace_owned'
          -- Organization scope is a deliberate lifecycle choice (0254/0262),
          -- never a legacy default, so it is reported separately rather than
          -- folded into the workspace population it is not part of.
          WHEN resource.authority_scope = 'organization'
            AND resource.authority_id IS NULL
            AND resource.owner_organization_membership_id IS NULL
            THEN 'organization_owned'
          WHEN resource.authority_scope <> 'user'
            OR resource.authority_id IS NULL
            OR resource.owner_organization_membership_id IS NULL
            THEN 'legacy_shape_unrecognized'
          WHEN authority.id IS NULL
            OR authority.resource_kind <> %2$L
            OR authority.resource_id <> resource.id
            OR authority.organization_membership_id
               <> resource.owner_organization_membership_id
            THEN 'conflicting_authority_rows'
          WHEN membership.id IS NULL
            OR membership.status <> 'active'
            OR membership.revoked_at IS NOT NULL
            THEN 'missing_organization_membership'
          WHEN authority.status <> 'active' OR authority.revoked_at IS NOT NULL
            THEN 'ambiguous_candidate_authority'
          WHEN resource.origin_workspace_id IS NULL
            THEN 'no_deterministic_evidence'
          ELSE 'user_owned'
        END AS verdict
      FROM %1$I resource
      LEFT JOIN organization_user_resource_authorities authority
        ON authority.id = resource.authority_id
       AND authority.account_id = resource.account_id
      LEFT JOIN organization_memberships membership
        ON membership.id = resource.owner_organization_membership_id
       AND membership.account_id = resource.account_id
      WHERE resource.account_id = $1
    $classification$, family[2], family[3]);

    EXECUTE format($summary$
      WITH classified AS (%1$s)
      SELECT pg_catalog.jsonb_build_object(
        'total', count(*)::int,
        'workspaceOwned', count(*) FILTER (WHERE verdict = 'workspace_owned')::int,
        'organizationOwned', count(*) FILTER (
          WHERE verdict = 'organization_owned'
        )::int,
        'userOwned', count(*) FILTER (WHERE verdict = 'user_owned')::int,
        'unresolved', count(*) FILTER (
          WHERE verdict NOT IN ('workspace_owned', 'organization_owned', 'user_owned')
        )::int,
        'unresolvedRows', coalesce((
          SELECT pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'resourceId', bounded.resource_id, 'reasonCode', bounded.verdict
            ) ORDER BY bounded.resource_id
          )
          FROM (
            SELECT resource_id, verdict FROM classified
            WHERE verdict NOT IN (
              'workspace_owned', 'organization_owned', 'user_owned'
            )
            ORDER BY resource_id LIMIT 1000
          ) bounded
        ), '[]'::jsonb),
        'unresolvedTruncated', count(*) FILTER (
          WHERE verdict NOT IN ('workspace_owned', 'organization_owned', 'user_owned')
        ) > 1000
      )
      FROM classified
    $summary$, classification_sql)
    USING p_organization_id
    INTO family_result;

    IF ledger_available THEN
      EXECUTE 'SELECT open_tenancy_backfill_receipt($1, $2, $3)'
        USING p_organization_id, family[1], p_run_key
        INTO receipt_id;
      FOR unresolved_row IN EXECUTE format(
        'SELECT resource_id, verdict FROM (%1$s) classified '
          || 'WHERE verdict NOT IN '
          || '(''workspace_owned'', ''organization_owned'', ''user_owned'') '
          || 'ORDER BY resource_id',
        classification_sql
      ) USING p_organization_id LOOP
        EXECUTE 'SELECT record_tenancy_backfill_unresolved($1, $2, $3)'
          USING receipt_id, unresolved_row.resource_id, unresolved_row.verdict;
      END LOOP;
      -- `classified_count` is the population this run PROVED already carries a
      -- terminal non-user classification; `skipped_count` is the reviewed
      -- user-owned population the backfill must not touch. Neither reflects a
      -- rewrite: this run changes no resource row.
      EXECUTE 'SELECT complete_tenancy_backfill_receipt($1, $2, $3, $4)'
        USING receipt_id,
          (family_result ->> 'workspaceOwned')::bigint
            + (family_result ->> 'organizationOwned')::bigint,
          (family_result ->> 'userOwned')::bigint,
          'completed';
      family_result := family_result
        || pg_catalog.jsonb_build_object('receiptId', receipt_id);
    END IF;

    families_result := families_result
      || pg_catalog.jsonb_build_object(family[1], family_result);
  END LOOP;

  IF claimed THEN
    DELETE FROM opengeni_private.resource_classification_capabilities
    WHERE backend_pid = pg_catalog.pg_backend_pid()
      AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'schemaVersion', 1,
    'organizationId', p_organization_id,
    'runKey', p_run_key,
    'ledgerAvailable', ledger_available,
    'rewroteResourceRows', false,
    'families', families_result
  );
EXCEPTION WHEN OTHERS THEN
  IF claimed THEN
    DELETE FROM opengeni_private.resource_classification_capabilities
    WHERE backend_pid = pg_catalog.pg_backend_pid()
      AND transaction_id = pg_catalog.pg_current_xact_id_if_assigned();
  END IF;
  RAISE;
END
$_$;

COMMENT ON FUNCTION verify_organization_resource_classification(p_organization_id uuid, p_run_key text) IS 'Organization-tenancy phase D assertion seam for Variable Sets, Rigs, and Connected Machines. Read-only over every resource table: it proves each row already carries an explicit terminal authority classification and records what it cannot prove through the 0286 ledger. It never rewrites a resource row and never infers user ownership.';

CREATE FUNCTION workspace_artifact_reject_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 AND NOT EXISTS (
    SELECT 1 FROM "workspaces" workspace WHERE workspace."id" = OLD."workspace_id"
  ) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'workspace artifact history is immutable' USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION workspace_artifact_validate_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW."current_version_id" IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM "workspace_artifact_versions" version
      WHERE version."workspace_id" = NEW."workspace_id"
        AND version."artifact_id" = NEW."id"
        AND version."id" = NEW."current_version_id"
    ) THEN
      RAISE EXCEPTION 'artifact current version must belong to the artifact' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_artifact_validate_event_links() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "workspace_artifact_versions" version
    WHERE version."workspace_id" = NEW."workspace_id"
      AND version."artifact_id" = NEW."artifact_id"
      AND version."id" = NEW."to_version_id"
  ) OR (NEW."from_version_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM "workspace_artifact_versions" version
    WHERE version."workspace_id" = NEW."workspace_id"
      AND version."artifact_id" = NEW."artifact_id"
      AND version."id" = NEW."from_version_id"
  )) THEN
    RAISE EXCEPTION 'artifact event versions must belong to the artifact' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_governance_reject_turn_human_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW."initiating_human_subject_id" IS DISTINCT FROM OLD."initiating_human_subject_id" THEN
    RAISE EXCEPTION 'turn initiating human is immutable after acceptance'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_governance_snapshot_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Parent lifecycle deletion is the sole mutation exception. PostgreSQL's
  -- cascading constraint trigger runs only after its parent row is absent;
  -- require both that nested trigger context and one missing ownership edge so
  -- direct or unrelated-trigger deletes remain fail-closed.
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND (
      NOT EXISTS (SELECT 1 FROM "managed_accounts" WHERE "id" = OLD."account_id")
      OR NOT EXISTS (SELECT 1 FROM "workspaces" WHERE "id" = OLD."workspace_id")
      OR NOT EXISTS (SELECT 1 FROM "sessions" WHERE "id" = OLD."session_id")
      OR NOT EXISTS (SELECT 1 FROM "session_turns" WHERE "id" = OLD."turn_id")
      OR NOT EXISTS (SELECT 1 FROM "session_turn_attempts" WHERE "id" = OLD."attempt_id")
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'accepted-turn governance snapshots are immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION workspace_instruction_policy_canonical_snapshot_entries(p_account_id uuid, p_workspace_id uuid, p_policy_role text, p_accepted_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
  SELECT coalesce(jsonb_agg(candidate.entry ORDER BY candidate.ordinal), '[]'::jsonb)
  FROM (
    SELECT
      CASE
        WHEN event.kind = 'charter' THEN 0
        WHEN event.scope = 'global' THEN 1
        ELSE 2
      END AS ordinal,
      jsonb_build_object(
        'kind', event.kind,
        'scope', event.scope,
        'roleKey', event.role_key,
        'revisionId', revision.id::text,
        'revision', revision.revision,
        'contentHash', revision.content_hash,
        'activationVersion', event.activation_version,
        'activatedAt', to_char(
          event.created_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
        ),
        'provenance', jsonb_build_object(
          'source', revision.provenance_source,
          'sourceIdHash', CASE
            WHEN revision.provenance_source_id IS NULL THEN NULL
            ELSE encode(sha256(convert_to(revision.provenance_source_id, 'UTF8')), 'hex')
          END
        )
      ) AS entry
    FROM (
      SELECT DISTINCT ON (lifecycle.kind, lifecycle.scope, coalesce(lifecycle.role_key, ''))
        lifecycle.*
      FROM (
        SELECT
          activation.id, activation.account_id, activation.workspace_id,
          activation.kind, activation.scope, activation.role_key,
          activation.activation_version, activation.new_revision_id,
          activation.new_revision, activation.new_content_hash,
          activation.created_at
        FROM workspace_instruction_policy_activation_events activation
        UNION ALL
        SELECT
          deactivation.id, deactivation.account_id, deactivation.workspace_id,
          deactivation.kind, deactivation.scope, deactivation.role_key,
          deactivation.activation_version, NULL::uuid, NULL::bigint, NULL::text,
          deactivation.created_at
        FROM workspace_instruction_policy_deactivation_events deactivation
      ) lifecycle
      WHERE lifecycle.account_id = p_account_id
        AND lifecycle.workspace_id = p_workspace_id
        AND lifecycle.created_at <= p_accepted_at
        AND (
          (lifecycle.kind = 'charter' AND lifecycle.scope = 'global')
          OR (lifecycle.kind = 'policy' AND lifecycle.scope = 'global')
          OR (
            p_policy_role IS NOT NULL
            AND lifecycle.kind = 'policy'
            AND lifecycle.scope = 'role'
            AND lifecycle.role_key = p_policy_role
          )
        )
      ORDER BY
        lifecycle.kind,
        lifecycle.scope,
        coalesce(lifecycle.role_key, ''),
        lifecycle.activation_version DESC,
        lifecycle.created_at DESC,
        lifecycle.id DESC
    ) event
    JOIN workspace_instruction_policy_revisions revision
      ON revision.account_id = event.account_id
      AND revision.workspace_id = event.workspace_id
      AND revision.id = event.new_revision_id
      AND revision.revision = event.new_revision
      AND revision.content_hash = event.new_content_hash
  ) candidate;
$$;

CREATE TABLE workspace_instruction_policy_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    execution_generation integer NOT NULL,
    policy_role text,
    role_source text NOT NULL,
    entries jsonb NOT NULL,
    entry_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_instruction_policy_snapshots_entries_chk CHECK (((jsonb_typeof(entries) = 'array'::text) AND (jsonb_array_length(entries) <= 3))),
    CONSTRAINT workspace_instruction_policy_snapshots_generation_chk CHECK ((execution_generation > 0)),
    CONSTRAINT workspace_instruction_policy_snapshots_hash_chk CHECK (((entry_hash ~ '^[0-9a-f]{64}$'::text) AND (entry_hash = encode(sha256(convert_to((entries)::text, 'UTF8'::name)), 'hex'::text)))),
    CONSTRAINT workspace_instruction_policy_snapshots_role_shape_chk CHECK ((((role_source = ANY (ARRAY['session_binding'::text, 'metadata_fallback'::text])) AND (policy_role IS NOT NULL) AND (policy_role = lower(btrim(policy_role))) AND ((length(policy_role) >= 1) AND (length(policy_role) <= 64)) AND (policy_role ~ '^[a-z0-9](?:[a-z0-9._-]*[a-z0-9])?$'::text) AND (policy_role !~ '--'::text)) OR ((role_source = ANY (ARRAY['none'::text, 'invalid_metadata_fallback'::text])) AND (policy_role IS NULL)))),
    CONSTRAINT workspace_instruction_policy_snapshots_role_source_chk CHECK ((role_source = ANY (ARRAY['session_binding'::text, 'metadata_fallback'::text, 'none'::text, 'invalid_metadata_fallback'::text])))
);

ALTER TABLE ONLY workspace_instruction_policy_snapshots FORCE ROW LEVEL SECURITY;

CREATE FUNCTION workspace_instruction_policy_get_or_create_snapshot(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS SETOF workspace_instruction_policy_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $_$
    DECLARE
      context_account_id uuid;
      context_workspace_id uuid;
      session_policy_role text;
      session_metadata jsonb;
      metadata_role_present boolean;
      metadata_role_candidate text;
      canonical_policy_role text;
      canonical_role_source text;
      canonical_entries jsonb;
      canonical_hash text;
      turn_accepted_at timestamptz;
      snapshot_time timestamptz := transaction_timestamp();
      winner_id uuid;
    BEGIN
      context_account_id := NULLIF(
        current_setting('opengeni.account_id', true), ''
      )::uuid;
      context_workspace_id := NULLIF(
        current_setting('opengeni.workspace_id', true), ''
      )::uuid;
      IF context_account_id IS DISTINCT FROM p_account_id
        OR context_workspace_id IS DISTINCT FROM p_workspace_id
        OR p_execution_generation < 1
      THEN
        RAISE EXCEPTION 'instruction-policy snapshot requires exact transaction-local tenant authority'
          USING ERRCODE = '42501';
      END IF;

      SELECT session.policy_role, session.metadata, turn.created_at
        INTO session_policy_role, session_metadata, turn_accepted_at
      FROM workspaces workspace
      JOIN sessions session
        ON session.account_id = workspace.account_id
        AND session.workspace_id = workspace.id
      JOIN session_turns turn
        ON turn.account_id = session.account_id
        AND turn.workspace_id = session.workspace_id
        AND turn.session_id = session.id
      JOIN session_turn_attempts attempt
        ON attempt.account_id = turn.account_id
        AND attempt.workspace_id = turn.workspace_id
        AND attempt.session_id = turn.session_id
        AND attempt.turn_id = turn.id
      WHERE workspace.id = p_workspace_id
        AND workspace.account_id = p_account_id
        AND session.id = p_session_id
        AND session.active_turn_id = p_turn_id
        AND turn.id = p_turn_id
        AND turn.active_attempt_id = p_attempt_id
        AND turn.execution_generation = p_execution_generation
        AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
        AND attempt.id = p_attempt_id
        AND attempt.execution_generation = p_execution_generation
        AND attempt.state IN ('claimed', 'running')
        AND NOT EXISTS (
          SELECT 1
          FROM session_attempt_interruptions interruption
          WHERE interruption.workspace_id = attempt.workspace_id
            AND interruption.attempt_id = attempt.id
            AND interruption.state IN ('pending', 'delivered', 'acknowledged')
        )
      FOR KEY SHARE OF workspace
      FOR SHARE OF session, turn
      FOR UPDATE OF attempt;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'instruction-policy snapshot requires the exact current attempt'
          USING ERRCODE = '42501';
      END IF;

      SELECT snapshot.id INTO winner_id
      FROM workspace_instruction_policy_snapshots snapshot
      WHERE snapshot.account_id = p_account_id
        AND snapshot.workspace_id = p_workspace_id
        AND snapshot.session_id = p_session_id
        AND snapshot.turn_id = p_turn_id
        AND snapshot.attempt_id = p_attempt_id
        AND snapshot.execution_generation = p_execution_generation
      FOR SHARE;
      IF winner_id IS NOT NULL THEN
        IF EXISTS (
          SELECT 1
          FROM workspace_instruction_policy_snapshots snapshot
          WHERE snapshot.id = winner_id
            AND (
              snapshot.created_at > transaction_timestamp()
              OR jsonb_typeof(snapshot.entries) <> 'array'
              OR jsonb_array_length(snapshot.entries) > 3
              OR snapshot.entry_hash IS DISTINCT FROM encode(
                sha256(convert_to(snapshot.entries::text, 'UTF8')),
                'hex'
              )
              OR (
                snapshot.role_source IN ('session_binding', 'metadata_fallback')
                AND snapshot.policy_role IS NULL
              )
              OR (
                snapshot.role_source IN ('none', 'invalid_metadata_fallback')
                AND snapshot.policy_role IS NOT NULL
              )
            )
        ) THEN
          RAISE EXCEPTION 'existing instruction-policy snapshot failed canonical integrity checks'
            USING ERRCODE = '23514';
        END IF;
        RETURN QUERY
        SELECT snapshot.*
        FROM workspace_instruction_policy_snapshots snapshot
        WHERE snapshot.id = winner_id;
        RETURN;
      END IF;

      IF session_policy_role IS NOT NULL THEN
        canonical_policy_role := session_policy_role;
        canonical_role_source := 'session_binding';
      ELSE
        metadata_role_present := coalesce(session_metadata ? 'role', false);
        IF metadata_role_present AND jsonb_typeof(session_metadata->'role') = 'string' THEN
          metadata_role_candidate := workspace_instruction_policy_normalize_role_key(
            session_metadata->>'role'
          );
        END IF;
        IF metadata_role_candidate IS NOT NULL
          AND length(metadata_role_candidate) BETWEEN 1 AND 64
          AND metadata_role_candidate ~ '^[a-z0-9](?:[a-z0-9._-]*[a-z0-9])?$'
          AND metadata_role_candidate !~ '--'
        THEN
          canonical_policy_role := metadata_role_candidate;
          canonical_role_source := 'metadata_fallback';
        ELSIF metadata_role_present THEN
          canonical_policy_role := NULL;
          canonical_role_source := 'invalid_metadata_fallback';
        ELSE
          canonical_policy_role := NULL;
          canonical_role_source := 'none';
        END IF;
      END IF;

      PERFORM 1
      FROM workspace_instruction_policy_activation_events event
      WHERE event.account_id = p_account_id
        AND event.workspace_id = p_workspace_id
        AND event.created_at <= turn_accepted_at
        AND (
          (event.kind = 'charter' AND event.scope = 'global')
          OR (event.kind = 'policy' AND event.scope = 'global')
          OR (
            canonical_policy_role IS NOT NULL
            AND event.kind = 'policy'
            AND event.scope = 'role'
            AND event.role_key = canonical_policy_role
          )
        )
      ORDER BY CASE
        WHEN event.kind = 'charter' THEN 0
        WHEN event.scope = 'global' THEN 1
        ELSE 2
      END,
      event.created_at,
      event.activation_version
      FOR SHARE OF event;

      canonical_entries := workspace_instruction_policy_canonical_snapshot_entries(
        p_account_id,
        p_workspace_id,
        canonical_policy_role,
        turn_accepted_at
      );
      canonical_hash := encode(
        sha256(convert_to(canonical_entries::text, 'UTF8')),
        'hex'
      );

      INSERT INTO workspace_instruction_policy_snapshots (
        account_id,
        workspace_id,
        session_id,
        turn_id,
        attempt_id,
        execution_generation,
        policy_role,
        role_source,
        entries,
        entry_hash,
        created_at
      ) VALUES (
        p_account_id,
        p_workspace_id,
        p_session_id,
        p_turn_id,
        p_attempt_id,
        p_execution_generation,
        canonical_policy_role,
        canonical_role_source,
        canonical_entries,
        canonical_hash,
        snapshot_time
      )
      ON CONFLICT (account_id, workspace_id, attempt_id) DO NOTHING
      RETURNING id INTO winner_id;
      IF winner_id IS NULL THEN
        SELECT snapshot.id INTO winner_id
        FROM workspace_instruction_policy_snapshots snapshot
        WHERE snapshot.account_id = p_account_id
          AND snapshot.workspace_id = p_workspace_id
          AND snapshot.session_id = p_session_id
          AND snapshot.turn_id = p_turn_id
          AND snapshot.attempt_id = p_attempt_id
          AND snapshot.execution_generation = p_execution_generation
        FOR SHARE;
      END IF;
      IF winner_id IS NULL THEN
        RAISE EXCEPTION 'instruction-policy snapshot winner conflicts with exact attempt authority'
          USING ERRCODE = '40001';
      END IF;
      IF EXISTS (
        SELECT 1
        FROM workspace_instruction_policy_snapshots snapshot
        WHERE snapshot.id = winner_id
          AND (
            snapshot.policy_role IS DISTINCT FROM canonical_policy_role
            OR snapshot.role_source IS DISTINCT FROM canonical_role_source
            OR snapshot.entries IS DISTINCT FROM canonical_entries
            OR snapshot.entry_hash IS DISTINCT FROM canonical_hash
            OR snapshot.created_at IS DISTINCT FROM snapshot_time
          )
      ) THEN
        RAISE EXCEPTION 'instruction-policy snapshot winner is not the canonical locked snapshot'
          USING ERRCODE = '40001';
      END IF;
      RETURN QUERY
      SELECT snapshot.*
      FROM workspace_instruction_policy_snapshots snapshot
      WHERE snapshot.id = winner_id;
    END
    $_$;

CREATE FUNCTION workspace_instruction_policy_guard_head_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE capability_writer boolean;
BEGIN
  IF pg_trigger_depth() > 1 AND NOT EXISTS (
    SELECT 1 FROM workspaces workspace WHERE workspace.id = OLD.workspace_id
  ) THEN
    RETURN OLD;
  END IF;
  SELECT current_user = pg_catalog.pg_get_userbyid(procedure_row.proowner)
  INTO capability_writer
  FROM pg_catalog.pg_proc procedure_row
  WHERE procedure_row.oid = pg_catalog.to_regprocedure(pg_catalog.format(
    '%I.governed_learning_deactivate_instruction_policy(uuid,uuid,uuid,uuid,uuid,bigint,text)',
    TG_TABLE_SCHEMA
  ));
  IF NOT coalesce(capability_writer, false)
    OR current_setting('opengeni.governed_learning_deactivation_operation', true) IS NULL
    OR current_setting('opengeni.governed_learning_deactivation_operation', true) = ''
  THEN
    RAISE EXCEPTION 'instruction-policy head deletion requires governed-learning capability'
      USING ERRCODE = '42501';
  END IF;
  RETURN OLD;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_guard_lifecycle_operation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'workspace_instruction_policy_deactivation_events' THEN
    IF EXISTS (
      SELECT 1 FROM workspace_instruction_policy_activation_events event
      WHERE event.workspace_id = NEW.workspace_id
        AND event.operation_id = NEW.operation_id
    ) THEN
      RAISE EXCEPTION 'instruction-policy lifecycle operation was already used'
        USING ERRCODE = '23505';
    END IF;
  ELSIF NEW.operation_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM workspace_instruction_policy_deactivation_events event
    WHERE event.workspace_id = NEW.workspace_id
      AND event.operation_id = NEW.operation_id
  ) THEN
    RAISE EXCEPTION 'instruction-policy lifecycle operation was already used'
      USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_normalize_role_key(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT lower(
    regexp_replace(
      regexp_replace(btrim(normalize(value, NFKC)), '[[:space:]]+', '-', 'g'),
      '-+',
      '-',
      'g'
    )
  );
$$;

CREATE FUNCTION workspace_instruction_policy_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  -- PostgreSQL implements ON DELETE CASCADE with a parent constraint trigger.
  -- By the time that trigger deletes child rows, the workspace is absent and
  -- this child trigger is nested. Require both facts so direct history deletes
  -- and deletes issued by unrelated triggers remain fail-closed.
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND NOT EXISTS (
      SELECT 1
      FROM "workspaces" workspace
      WHERE workspace."id" = OLD."workspace_id"
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'workspace instruction-policy history is immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION workspace_instruction_policy_reject_session_role_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW."policy_role" IS DISTINCT FROM OLD."policy_role" THEN
    RAISE EXCEPTION 'session policy role is immutable after creation'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_validate_deactivation_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM workspace_instruction_policy_revisions revision
    WHERE revision.id = NEW.old_revision_id
      AND revision.account_id = NEW.account_id
      AND revision.workspace_id = NEW.workspace_id
      AND revision.kind = NEW.kind
      AND revision.scope = NEW.scope
      AND revision.role_key IS NOT DISTINCT FROM NEW.role_key
      AND revision.revision = NEW.old_revision
      AND revision.content_hash = NEW.old_content_hash
  ) THEN
    RAISE EXCEPTION 'instruction-policy deactivation event has an invalid old revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_validate_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM "workspace_instruction_policy_revisions" revision
    WHERE revision."id" = NEW."new_revision_id"
      AND revision."account_id" = NEW."account_id"
      AND revision."workspace_id" = NEW."workspace_id"
      AND revision."kind" = NEW."kind"
      AND revision."scope" = NEW."scope"
      AND revision."role_key" IS NOT DISTINCT FROM NEW."role_key"
      AND revision."revision" = NEW."new_revision"
      AND revision."content_hash" = NEW."new_content_hash"
  ) THEN
    RAISE EXCEPTION 'instruction-policy activation event has an invalid new revision'
      USING ERRCODE = '23514';
  END IF;
  IF NEW."old_revision_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM "workspace_instruction_policy_revisions" revision
    WHERE revision."id" = NEW."old_revision_id"
      AND revision."account_id" = NEW."account_id"
      AND revision."workspace_id" = NEW."workspace_id"
      AND revision."kind" = NEW."kind"
      AND revision."scope" = NEW."scope"
      AND revision."role_key" IS NOT DISTINCT FROM NEW."role_key"
      AND revision."revision" = NEW."old_revision"
      AND revision."content_hash" = NEW."old_content_hash"
  ) THEN
    RAISE EXCEPTION 'instruction-policy activation event has an invalid old revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_validate_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM "workspace_instruction_policy_revisions" revision
    WHERE revision."id" = NEW."revision_id"
      AND revision."account_id" = NEW."account_id"
      AND revision."workspace_id" = NEW."workspace_id"
      AND revision."kind" = NEW."kind"
      AND revision."scope" = NEW."scope"
      AND revision."role_key" IS NOT DISTINCT FROM NEW."role_key"
      AND revision."revision" = NEW."revision"
      AND revision."content_hash" = NEW."content_hash"
  ) THEN
    RAISE EXCEPTION 'instruction-policy head must identify an exact target revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_validate_onboarding_proposal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
BEGIN
  IF NEW.baseline_revision_id IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM workspace_instruction_policy_heads head
      WHERE head.account_id = NEW.account_id
        AND head.workspace_id = NEW.workspace_id
        AND head.kind = NEW.kind
        AND head.scope = NEW.scope
        AND head.role_key IS NOT DISTINCT FROM NEW.role_key
    ) THEN
      RAISE EXCEPTION 'instruction-policy proposal must capture the exact active head baseline'
        USING ERRCODE = '23514';
    END IF;
    IF NOT (
      (
        NEW.baseline_activation_version = 0
        AND NOT EXISTS (
          SELECT 1 FROM workspace_instruction_policy_heads head
          WHERE head.account_id = NEW.account_id
            AND head.workspace_id = NEW.workspace_id
            AND head.kind = NEW.kind
            AND head.scope = NEW.scope
            AND head.role_key IS NOT DISTINCT FROM NEW.role_key
        )
        AND NOT EXISTS (
          SELECT 1 FROM workspace_instruction_policy_deactivation_events event
          WHERE event.account_id = NEW.account_id
            AND event.workspace_id = NEW.workspace_id
            AND event.kind = NEW.kind
            AND event.scope = NEW.scope
            AND event.role_key IS NOT DISTINCT FROM NEW.role_key
        )
      ) OR (
        NEW.baseline_activation_version > 0
        AND NOT EXISTS (
          SELECT 1 FROM workspace_instruction_policy_heads head
          WHERE head.account_id = NEW.account_id
            AND head.workspace_id = NEW.workspace_id
            AND head.kind = NEW.kind
            AND head.scope = NEW.scope
            AND head.role_key IS NOT DISTINCT FROM NEW.role_key
        )
        AND EXISTS (
          SELECT 1 FROM workspace_instruction_policy_deactivation_events event
          WHERE event.account_id = NEW.account_id
            AND event.workspace_id = NEW.workspace_id
            AND event.kind = NEW.kind
            AND event.scope = NEW.scope
            AND event.role_key IS NOT DISTINCT FROM NEW.role_key
            AND event.activation_version = NEW.baseline_activation_version
            AND NOT EXISTS (
              SELECT 1 FROM workspace_instruction_policy_deactivation_events newer
              WHERE newer.account_id = event.account_id
                AND newer.workspace_id = event.workspace_id
                AND newer.kind = event.kind
                AND newer.scope = event.scope
                AND newer.role_key IS NOT DISTINCT FROM event.role_key
                AND newer.activation_version > event.activation_version
            )
        )
      )
    ) THEN
      RAISE EXCEPTION 'instruction-policy proposal must capture the exact inactive boundary'
        USING ERRCODE = '23514';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM workspace_instruction_policy_heads head
    WHERE head.account_id = NEW.account_id
      AND head.workspace_id = NEW.workspace_id
      AND head.kind = NEW.kind
      AND head.scope = NEW.scope
      AND head.role_key IS NOT DISTINCT FROM NEW.role_key
      AND head.revision_id = NEW.baseline_revision_id
      AND head.revision = NEW.baseline_revision
      AND head.content_hash = NEW.baseline_content_hash
      AND head.activation_version = NEW.baseline_activation_version
      AND head.activated_at = NEW.baseline_activated_at
  ) THEN
    RAISE EXCEPTION 'instruction-policy proposal must capture the exact active head baseline'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.baseline_revision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM workspace_instruction_policy_revisions revision
    WHERE revision.id = NEW.baseline_revision_id
      AND revision.account_id = NEW.account_id
      AND revision.workspace_id = NEW.workspace_id
      AND revision.kind = NEW.kind
      AND revision.scope = NEW.scope
      AND revision.role_key IS NOT DISTINCT FROM NEW.role_key
      AND revision.revision = NEW.baseline_revision
      AND revision.content_hash = NEW.baseline_content_hash
  ) THEN
    RAISE EXCEPTION 'instruction-policy proposal has an invalid baseline revision'
      USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM workspace_instruction_policy_revisions revision
    WHERE revision.id = NEW.draft_revision_id
      AND revision.operation_id = NEW.operation_id
      AND revision.request_fingerprint = NEW.request_fingerprint
      AND revision.account_id = NEW.account_id
      AND revision.workspace_id = NEW.workspace_id
      AND revision.kind = NEW.kind
      AND revision.scope = NEW.scope
      AND revision.role_key IS NOT DISTINCT FROM NEW.role_key
      AND revision.revision = NEW.draft_revision
      AND revision.content_hash = NEW.draft_content_hash
      AND revision.supersedes_revision_id IS NOT DISTINCT FROM NEW.baseline_revision_id
      AND revision.created_by_subject_id = NEW.created_by_subject_id
      AND (
        (
          revision.provenance_source = 'onboarding'
          AND revision.provenance_source_id = NEW.id::text
        ) OR (
          revision.provenance_source = 'knowledge_proposal'
          AND revision.provenance_source_id = NEW.source_id
          AND NEW.source_version = NEW.draft_content_hash
          AND EXISTS (
            SELECT 1 FROM knowledge_change_proposals proposal
            WHERE proposal.id::text = NEW.source_id
              AND proposal.account_id = NEW.account_id
              AND proposal.scope_kind = 'workspace'
              AND proposal.scope_workspace_id = NEW.workspace_id
              AND proposal.scope_subject_id IS NULL
              AND proposal.target_kind = 'instruction_policy'
              AND proposal.target_scope = NEW.scope
              AND proposal.target_key IS NOT DISTINCT FROM CASE
                WHEN NEW.scope = 'role' THEN NEW.role_key
                ELSE NULL
              END
              AND proposal.content_hash = NEW.source_version
              AND proposal.actor_kind = 'service'
              AND proposal.actor_subject_id = NEW.created_by_subject_id
              AND proposal.initiating_human_subject_id = COALESCE(
                NULLIF(current_setting('opengeni.initiating_human_subject_id', true), ''),
                current_setting('opengeni.subject_id', true)
              )
              AND proposal.claim_id IS NOT NULL
              AND proposal.evidence_id IS NOT NULL
              AND proposal.status = 'proposed'
          )
        )
      )
  ) THEN
    RAISE EXCEPTION 'instruction-policy proposal must identify its exact inactive draft'
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1 FROM workspace_instruction_policy_heads head
    WHERE head.account_id = NEW.account_id
      AND head.workspace_id = NEW.workspace_id
      AND head.revision_id = NEW.draft_revision_id
  ) OR EXISTS (
    SELECT 1 FROM workspace_instruction_policy_activation_events event
    WHERE event.account_id = NEW.account_id
      AND event.workspace_id = NEW.workspace_id
      AND event.new_revision_id = NEW.draft_revision_id
  ) THEN
    RAISE EXCEPTION 'instruction-policy proposal must identify a never-activated inactive draft'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_validate_revision_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_workspace_id uuid;
  target_kind text;
  target_scope text;
  target_role_key text;
BEGIN
  IF NEW."supersedes_revision_id" IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT "workspace_id", "kind", "scope", "role_key"
    INTO target_workspace_id, target_kind, target_scope, target_role_key
    FROM "workspace_instruction_policy_revisions"
    WHERE "id" = NEW."supersedes_revision_id";
  IF NOT FOUND
    OR target_workspace_id IS DISTINCT FROM NEW."workspace_id"
    OR target_kind IS DISTINCT FROM NEW."kind"
    OR target_scope IS DISTINCT FROM NEW."scope"
    OR target_role_key IS DISTINCT FROM NEW."role_key"
  THEN
    RAISE EXCEPTION 'superseded instruction-policy revision must use the same workspace and target'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_instruction_policy_validate_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  session_policy_role text;
  session_metadata jsonb;
  metadata_role_present boolean;
  metadata_role_candidate text;
  canonical_policy_role text;
  canonical_role_source text;
  canonical_entries jsonb;
  turn_accepted_at timestamptz;
BEGIN
  SELECT session.policy_role, session.metadata, turn.created_at
    INTO session_policy_role, session_metadata, turn_accepted_at
  FROM session_turn_attempts attempt
  JOIN session_turns turn
    ON turn.account_id = attempt.account_id
    AND turn.workspace_id = attempt.workspace_id
    AND turn.session_id = attempt.session_id
    AND turn.id = attempt.turn_id
  JOIN sessions session
    ON session.account_id = attempt.account_id
    AND session.workspace_id = attempt.workspace_id
    AND session.id = attempt.session_id
  WHERE attempt.id = NEW.attempt_id
    AND attempt.account_id = NEW.account_id
    AND attempt.workspace_id = NEW.workspace_id
    AND attempt.session_id = NEW.session_id
    AND attempt.turn_id = NEW.turn_id
    AND attempt.execution_generation = NEW.execution_generation
    AND turn.execution_generation = NEW.execution_generation
    AND attempt.state IN ('claimed', 'running')
    AND turn.active_attempt_id = attempt.id
    AND session.active_turn_id = turn.id
    AND turn.status IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
    AND NOT EXISTS (
      SELECT 1
      FROM session_attempt_interruptions interruption
      WHERE interruption.workspace_id = NEW.workspace_id
        AND interruption.attempt_id = NEW.attempt_id
        AND interruption.state IN ('pending', 'delivered', 'acknowledged')
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'instruction-policy snapshot requires an exact active attempt'
      USING ERRCODE = '23514';
  END IF;

  IF session_policy_role IS NOT NULL THEN
    canonical_policy_role := session_policy_role;
    canonical_role_source := 'session_binding';
  ELSE
    metadata_role_present := coalesce(session_metadata ? 'role', false);
    IF metadata_role_present AND jsonb_typeof(session_metadata->'role') = 'string' THEN
      metadata_role_candidate := workspace_instruction_policy_normalize_role_key(
        session_metadata->>'role'
      );
    END IF;
    IF metadata_role_candidate IS NOT NULL
      AND length(metadata_role_candidate) BETWEEN 1 AND 64
      AND metadata_role_candidate ~ '^[a-z0-9](?:[a-z0-9._-]*[a-z0-9])?$'
      AND metadata_role_candidate !~ '--'
    THEN
      canonical_policy_role := metadata_role_candidate;
      canonical_role_source := 'metadata_fallback';
    ELSIF metadata_role_present THEN
      canonical_policy_role := NULL;
      canonical_role_source := 'invalid_metadata_fallback';
    ELSE
      canonical_policy_role := NULL;
      canonical_role_source := 'none';
    END IF;
  END IF;

  IF NEW.policy_role IS DISTINCT FROM canonical_policy_role
    OR NEW.role_source IS DISTINCT FROM canonical_role_source
  THEN
    RAISE EXCEPTION 'instruction-policy snapshot role does not match the immutable session binding'
      USING ERRCODE = '23514';
  END IF;

  canonical_entries := workspace_instruction_policy_canonical_snapshot_entries(
    NEW.account_id,
    NEW.workspace_id,
    canonical_policy_role,
    turn_accepted_at
  );
  IF NEW.entries IS DISTINCT FROM canonical_entries
    OR NEW.entry_hash IS DISTINCT FROM encode(
      sha256(convert_to(canonical_entries::text, 'UTF8')),
      'hex'
    )
  THEN
    RAISE EXCEPTION 'instruction-policy snapshot is not the canonical locked policy set'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$_$;

CREATE FUNCTION workspace_learning_policy_apply_activation(p_operation_id uuid, p_request_fingerprint text, p_account_id uuid, p_workspace_id uuid, p_target_revision_id uuid, p_expected_current_revision_id uuid, p_expected_activation_version bigint, p_type text, p_actor_subject_id text, p_reason text) RETURNS TABLE(event_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog', 'pg_temp'
    AS $_$
    DECLARE
      target_revision record;
      current_head record;
      existing_event record;
      next_activation_version bigint;
      event_created_at timestamptz;
      context_account_id uuid;
      context_workspace_id uuid;
      context_subject_id text;
      context_principal_kind text;
    BEGIN
      context_account_id := NULLIF(current_setting('opengeni.account_id', true), '')::uuid;
      context_workspace_id := NULLIF(current_setting('opengeni.workspace_id', true), '')::uuid;
      context_subject_id := NULLIF(current_setting('opengeni.subject_id', true), '');
      context_principal_kind := NULLIF(current_setting('opengeni.principal_kind', true), '');
      IF context_account_id IS DISTINCT FROM p_account_id
        OR context_workspace_id IS DISTINCT FROM p_workspace_id
        OR context_subject_id IS DISTINCT FROM p_actor_subject_id
        OR context_principal_kind IS DISTINCT FROM 'human_session'
      THEN
        RAISE EXCEPTION 'learning-policy activation requires exact human workspace authority'
          USING ERRCODE = '42501';
      END IF;
      IF p_request_fingerprint !~ '^[0-9a-f]{64}$'
        OR p_expected_activation_version < 0
        OR p_type NOT IN ('activate', 'rollback')
        OR length(btrim(p_actor_subject_id)) NOT BETWEEN 1 AND 1024
        OR length(btrim(p_reason)) NOT BETWEEN 1 AND 4096
      THEN
        RAISE EXCEPTION 'learning-policy activation input is invalid'
          USING ERRCODE = '22023';
      END IF;

      PERFORM 1
      FROM "workspaces" workspace
      WHERE workspace."id" = p_workspace_id AND workspace."account_id" = p_account_id
      FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'workspace was not found' USING ERRCODE = '42501';
      END IF;

      SELECT * INTO existing_event
      FROM "workspace_learning_policy_activation_events" event
      WHERE event."workspace_id" = p_workspace_id
        AND event."operation_id" = p_operation_id;
      IF FOUND THEN
        IF existing_event."request_fingerprint" IS DISTINCT FROM p_request_fingerprint THEN
          RAISE EXCEPTION 'learning-policy operation id was reused'
            USING ERRCODE = 'P1471';
        END IF;
        event_id := existing_event."id";
        RETURN NEXT;
        RETURN;
      END IF;
      IF EXISTS (
        SELECT 1 FROM "workspace_learning_policy_revisions" revision
        WHERE revision."workspace_id" = p_workspace_id
          AND revision."operation_id" = p_operation_id
      ) THEN
        RAISE EXCEPTION 'learning-policy operation id was reused'
          USING ERRCODE = 'P1471';
      END IF;

      SELECT * INTO target_revision
      FROM "workspace_learning_policy_revisions" revision
      WHERE revision."id" = p_target_revision_id
        AND revision."account_id" = p_account_id
        AND revision."workspace_id" = p_workspace_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'learning-policy revision was not found' USING ERRCODE = '23503';
      END IF;

      SELECT * INTO current_head
      FROM "workspace_learning_policy_heads" head
      WHERE head."account_id" = p_account_id
        AND head."workspace_id" = p_workspace_id
      FOR UPDATE;
      IF coalesce(current_head."activation_version", 0) IS DISTINCT FROM p_expected_activation_version
        OR current_head."revision_id" IS DISTINCT FROM p_expected_current_revision_id
      THEN
        RAISE EXCEPTION 'learning-policy active revision changed'
          USING ERRCODE = '40001';
      END IF;
      IF current_head."revision_id" IS NOT NULL
        AND current_head."revision_id" = target_revision."id"
      THEN
        RAISE EXCEPTION 'learning-policy revision is already active'
          USING ERRCODE = '23514';
      END IF;
      IF p_type = 'rollback' THEN
        IF current_head."revision_id" IS NULL OR NOT EXISTS (
          SELECT 1
          FROM "workspace_learning_policy_activation_events" event
          WHERE event."account_id" = p_account_id
            AND event."workspace_id" = p_workspace_id
            AND event."new_revision_id" = target_revision."id"
        ) THEN
          RAISE EXCEPTION 'learning-policy rollback target was not previously active'
            USING ERRCODE = '23514';
        END IF;
      END IF;

      -- The event timestamp is accepted-order evidence. Stamp it only after
      -- workspace/head serialization and successful CAS so a dependent
      -- activation that began earlier cannot sort before its predecessor.
      event_created_at := clock_timestamp();
      next_activation_version := coalesce(current_head."activation_version", 0) + 1;
      PERFORM set_config(
        'opengeni.workspace_learning_policy_lifecycle_workspace_id',
        p_workspace_id::text,
        true
      );
      IF current_head."id" IS NULL THEN
        INSERT INTO "workspace_learning_policy_heads" (
          "account_id", "workspace_id", "revision_id", "revision",
          "policy_hash", "activation_version", "activated_at"
        ) VALUES (
          p_account_id, p_workspace_id, target_revision."id", target_revision."revision",
          target_revision."policy_hash", next_activation_version, event_created_at
        );
      ELSE
        UPDATE "workspace_learning_policy_heads"
        SET "revision_id" = target_revision."id",
          "revision" = target_revision."revision",
          "policy_hash" = target_revision."policy_hash",
          "activation_version" = next_activation_version,
          "activated_at" = event_created_at
        WHERE "id" = current_head."id";
      END IF;
      PERFORM set_config('opengeni.workspace_learning_policy_lifecycle_workspace_id', '', true);

      INSERT INTO "workspace_learning_policy_activation_events" (
        "operation_id", "request_fingerprint", "account_id", "workspace_id",
        "type", "activation_version",
        "old_revision_id", "old_revision", "old_policy_hash",
        "new_revision_id", "new_revision", "new_policy_hash",
        "actor_subject_id", "reason", "created_at"
      ) VALUES (
        p_operation_id, p_request_fingerprint, p_account_id, p_workspace_id,
        p_type, next_activation_version,
        current_head."revision_id", current_head."revision", current_head."policy_hash",
        target_revision."id", target_revision."revision", target_revision."policy_hash",
        p_actor_subject_id, p_reason, event_created_at
      ) RETURNING "id" INTO event_id;
      RETURN NEXT;
    END
    $_$;

CREATE FUNCTION workspace_learning_policy_canonical_at(p_account_id uuid, p_workspace_id uuid, p_accepted_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE WHEN active."id" IS NULL THEN
    jsonb_build_object(
      'revisionId', NULL,
      'revision', NULL,
      'policyHash', NULL,
      'activationVersion', 0,
      'activatedAt', NULL,
      'workspaceMode', 'suggest',
      'sourceOverrides', '[]'::jsonb
    )
  ELSE
    jsonb_build_object(
      'revisionId', revision."id"::text,
      'revision', revision."revision",
      'policyHash', revision."policy_hash",
      'activationVersion', active."activation_version",
      'activatedAt', to_char(
        active."created_at" AT TIME ZONE 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      ),
      'workspaceMode', revision."workspace_mode",
      'sourceOverrides', revision."source_overrides"
    )
  END
  FROM (SELECT 1) singleton
  LEFT JOIN LATERAL (
    SELECT event.*
    FROM "workspace_learning_policy_activation_events" event
    WHERE event."account_id" = p_account_id
      AND event."workspace_id" = p_workspace_id
      AND event."created_at" <= p_accepted_at
    ORDER BY event."created_at" DESC, event."activation_version" DESC, event."id" DESC
    LIMIT 1
  ) active ON true
  LEFT JOIN "workspace_learning_policy_revisions" revision
    ON revision."account_id" = active."account_id"
    AND revision."workspace_id" = active."workspace_id"
    AND revision."id" = active."new_revision_id"
    AND revision."revision" = active."new_revision"
    AND revision."policy_hash" = active."new_policy_hash";
$$;

CREATE FUNCTION workspace_learning_policy_get_or_create_snapshot(p_account_id uuid, p_workspace_id uuid, p_session_id uuid, p_turn_id uuid, p_attempt_id uuid, p_execution_generation integer) RETURNS TABLE(snapshot_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '{{schema}}', 'pg_catalog'
    AS $$
    DECLARE
      accepted_at timestamptz;
      canonical jsonb;
      existing_snapshot record;
      snapshot_revision_id uuid;
      snapshot_revision bigint;
      snapshot_policy_hash text;
      snapshot_activation_version bigint;
      snapshot_activated_at timestamptz;
      snapshot_workspace_mode text;
      snapshot_source_overrides jsonb;
    BEGIN
      IF NULLIF(current_setting('opengeni.account_id', true), '')::uuid IS DISTINCT FROM p_account_id
        OR NULLIF(current_setting('opengeni.workspace_id', true), '')::uuid IS DISTINCT FROM p_workspace_id
      THEN
        RAISE EXCEPTION 'learning-policy snapshot requires exact workspace authority'
          USING ERRCODE = '42501';
      END IF;

      SELECT * INTO existing_snapshot
      FROM "workspace_learning_policy_snapshots" snapshot
      WHERE snapshot."account_id" = p_account_id
        AND snapshot."workspace_id" = p_workspace_id
        AND snapshot."attempt_id" = p_attempt_id;
      IF FOUND THEN
        IF existing_snapshot."session_id" IS DISTINCT FROM p_session_id
          OR existing_snapshot."turn_id" IS DISTINCT FROM p_turn_id
          OR existing_snapshot."execution_generation" IS DISTINCT FROM p_execution_generation
        THEN
          RAISE EXCEPTION 'learning-policy snapshot attempt identity conflicted'
            USING ERRCODE = '23514';
        END IF;
        snapshot_id := existing_snapshot."id";
        RETURN NEXT;
        RETURN;
      END IF;

      PERFORM 1
      FROM "workspaces" workspace
      WHERE workspace."id" = p_workspace_id
        AND workspace."account_id" = p_account_id
      FOR KEY SHARE OF workspace;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'learning-policy snapshot requires an exact active attempt'
          USING ERRCODE = '23514';
      END IF;

      PERFORM 1
      FROM "sessions" session
      WHERE session."account_id" = p_account_id
        AND session."workspace_id" = p_workspace_id
        AND session."id" = p_session_id
        AND session."active_turn_id" = p_turn_id
      FOR SHARE OF session;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'learning-policy snapshot requires an exact active attempt'
          USING ERRCODE = '23514';
      END IF;

      SELECT turn."created_at" INTO accepted_at
      FROM "session_turns" turn
      WHERE turn."account_id" = p_account_id
        AND turn."workspace_id" = p_workspace_id
        AND turn."session_id" = p_session_id
        AND turn."id" = p_turn_id
        AND turn."execution_generation" = p_execution_generation
        AND turn."active_attempt_id" = p_attempt_id
        AND turn."status" IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
      FOR SHARE OF turn;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'learning-policy snapshot requires an exact active attempt'
          USING ERRCODE = '23514';
      END IF;

      PERFORM 1
      FROM "session_turn_attempts" attempt
      WHERE attempt."id" = p_attempt_id
        AND attempt."account_id" = p_account_id
        AND attempt."workspace_id" = p_workspace_id
        AND attempt."session_id" = p_session_id
        AND attempt."turn_id" = p_turn_id
        AND attempt."execution_generation" = p_execution_generation
        AND attempt."state" IN ('claimed', 'running')
      FOR SHARE OF attempt;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'learning-policy snapshot requires an exact active attempt'
          USING ERRCODE = '23514';
      END IF;

      -- This attempt SHARE lock is also the interruption-creation fence. Every
      -- supported interruption writer takes the exact attempt FOR UPDATE before
      -- inserting session_attempt_interruptions. Row locks live until transaction
      -- end, so no such writer can cross the revalidation -> insert -> commit
      -- interval below.
      -- A lock acquisition may wait behind Pause, Steer, replacement, or
      -- settlement. Re-evaluate the complete tuple in a fresh READ COMMITTED
      -- statement after the canonical rows are locked so a pre-wait snapshot
      -- cannot miss the change that just released the lock.
      PERFORM 1
      FROM "sessions" session
      JOIN "session_turns" turn
        ON turn."account_id" = session."account_id"
        AND turn."workspace_id" = session."workspace_id"
        AND turn."session_id" = session."id"
      JOIN "session_turn_attempts" attempt
        ON attempt."account_id" = turn."account_id"
        AND attempt."workspace_id" = turn."workspace_id"
        AND attempt."session_id" = turn."session_id"
        AND attempt."turn_id" = turn."id"
      WHERE session."account_id" = p_account_id
        AND session."workspace_id" = p_workspace_id
        AND session."id" = p_session_id
        AND session."active_turn_id" = p_turn_id
        AND turn."id" = p_turn_id
        AND turn."execution_generation" = p_execution_generation
        AND turn."active_attempt_id" = p_attempt_id
        AND turn."status" IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
        AND attempt."id" = p_attempt_id
        AND attempt."execution_generation" = p_execution_generation
        AND attempt."state" IN ('claimed', 'running')
        AND NOT EXISTS (
          SELECT 1
          FROM "session_attempt_interruptions" interruption
          WHERE interruption."workspace_id" = p_workspace_id
            AND interruption."attempt_id" = p_attempt_id
            AND interruption."state" IN ('pending', 'delivered', 'acknowledged')
        );
      IF NOT FOUND THEN
        RAISE EXCEPTION 'learning-policy snapshot requires an exact active attempt'
          USING ERRCODE = '23514';
      END IF;

      canonical := workspace_learning_policy_canonical_at(
        p_account_id,
        p_workspace_id,
        accepted_at
      );
      snapshot_revision_id := (canonical->>'revisionId')::uuid;
      snapshot_revision := (canonical->>'revision')::bigint;
      snapshot_policy_hash := canonical->>'policyHash';
      snapshot_activation_version := (canonical->>'activationVersion')::bigint;
      snapshot_activated_at := (canonical->>'activatedAt')::timestamptz;
      snapshot_workspace_mode := canonical->>'workspaceMode';
      snapshot_source_overrides := canonical->'sourceOverrides';

      INSERT INTO "workspace_learning_policy_snapshots" (
        "account_id", "workspace_id", "session_id", "turn_id", "attempt_id",
        "execution_generation", "revision_id", "revision", "policy_hash",
        "activation_version", "activated_at", "workspace_mode", "source_overrides",
        "snapshot_hash"
      ) VALUES (
        p_account_id, p_workspace_id, p_session_id, p_turn_id, p_attempt_id,
        p_execution_generation, snapshot_revision_id, snapshot_revision, snapshot_policy_hash,
        snapshot_activation_version, snapshot_activated_at, snapshot_workspace_mode,
        snapshot_source_overrides,
        workspace_learning_policy_snapshot_hash(
          snapshot_revision_id,
          snapshot_revision,
          snapshot_policy_hash,
          snapshot_activation_version,
          snapshot_activated_at,
          snapshot_workspace_mode,
          snapshot_source_overrides
        )
      )
      ON CONFLICT ("account_id", "workspace_id", "attempt_id") DO NOTHING
      RETURNING "id" INTO snapshot_id;

      IF snapshot_id IS NULL THEN
        SELECT snapshot."id" INTO snapshot_id
        FROM "workspace_learning_policy_snapshots" snapshot
        WHERE snapshot."account_id" = p_account_id
          AND snapshot."workspace_id" = p_workspace_id
          AND snapshot."attempt_id" = p_attempt_id
          AND snapshot."session_id" = p_session_id
          AND snapshot."turn_id" = p_turn_id
          AND snapshot."execution_generation" = p_execution_generation;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'learning-policy snapshot concurrent identity conflicted'
            USING ERRCODE = '23514';
        END IF;
      END IF;
      RETURN NEXT;
    END
    $$;

CREATE FUNCTION workspace_learning_policy_guard_head_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  lifecycle_workspace_id text;
BEGIN
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND NOT EXISTS (
      SELECT 1 FROM "workspaces" workspace WHERE workspace."id" = OLD."workspace_id"
    )
  THEN
    RETURN OLD;
  END IF;
  lifecycle_workspace_id := current_setting(
    'opengeni.workspace_learning_policy_lifecycle_workspace_id',
    true
  );
  IF lifecycle_workspace_id IS DISTINCT FROM coalesce(NEW."workspace_id", OLD."workspace_id")::text THEN
    RAISE EXCEPTION 'learning-policy heads change only through the lifecycle function'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW."id" IS DISTINCT FROM OLD."id"
      OR NEW."account_id" IS DISTINCT FROM OLD."account_id"
      OR NEW."workspace_id" IS DISTINCT FROM OLD."workspace_id"
      OR NEW."activation_version" IS DISTINCT FROM OLD."activation_version" + 1
    THEN
      RAISE EXCEPTION 'invalid learning-policy head transition'
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'learning-policy heads cannot be deleted directly'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_learning_policy_hash(p_workspace_mode text, p_source_overrides jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT encode(
    sha256(convert_to(
      jsonb_build_array(
        'workspace_learning_policy',
        1,
        p_workspace_mode,
        p_source_overrides
      )::text,
      'UTF8'
    )),
    'hex'
  );
$$;

CREATE FUNCTION workspace_learning_policy_reject_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND NOT EXISTS (
      SELECT 1 FROM "workspaces" workspace WHERE workspace."id" = OLD."workspace_id"
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'workspace learning-policy history is immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION workspace_learning_policy_reject_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Parent lifecycle deletion is the sole mutation exception. PostgreSQL's
  -- cascading constraint trigger runs only after its parent row is absent;
  -- require both nested trigger context and one missing ownership edge so
  -- direct or unrelated-trigger deletes remain fail-closed.
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND (
      NOT EXISTS (SELECT 1 FROM "managed_accounts" WHERE "id" = OLD."account_id")
      OR NOT EXISTS (SELECT 1 FROM "workspaces" WHERE "id" = OLD."workspace_id")
      OR NOT EXISTS (SELECT 1 FROM "sessions" WHERE "id" = OLD."session_id")
      OR NOT EXISTS (SELECT 1 FROM "session_turns" WHERE "id" = OLD."turn_id")
      OR NOT EXISTS (SELECT 1 FROM "session_turn_attempts" WHERE "id" = OLD."attempt_id")
    )
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'workspace learning-policy snapshots are immutable'
    USING ERRCODE = '55000';
END;
$$;

CREATE FUNCTION workspace_learning_policy_snapshot_hash(p_revision_id uuid, p_revision bigint, p_policy_hash text, p_activation_version bigint, p_activated_at timestamp with time zone, p_workspace_mode text, p_source_overrides jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT encode(
    sha256(convert_to(
      jsonb_build_array(
        'workspace_learning_policy_snapshot',
        1,
        p_revision_id,
        p_revision,
        p_policy_hash,
        p_activation_version,
        CASE WHEN p_activated_at IS NULL THEN NULL ELSE to_char(
          p_activated_at AT TIME ZONE 'UTC',
          'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
        ) END,
        p_workspace_mode,
        p_source_overrides
      )::text,
      'UTF8'
    )),
    'hex'
  );
$$;

CREATE FUNCTION workspace_learning_policy_source_overrides_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  entry jsonb;
  canonical jsonb;
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'array'
    OR jsonb_array_length(value) > 256
    OR octet_length(convert_to(value::text, 'UTF8')) > 65536
  THEN
    RETURN false;
  END IF;

  FOR entry IN SELECT item FROM jsonb_array_elements(value) AS entries(item) LOOP
    IF jsonb_typeof(entry) IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(entry)) <> 3
      OR NOT (entry ? 'kind' AND entry ? 'id' AND entry ? 'mode')
      OR jsonb_typeof(entry->'kind') IS DISTINCT FROM 'string'
      OR jsonb_typeof(entry->'id') IS DISTINCT FROM 'string'
      OR jsonb_typeof(entry->'mode') IS DISTINCT FROM 'string'
      OR entry->>'kind' IS DISTINCT FROM lower(btrim(entry->>'kind'))
      OR length(entry->>'kind') NOT BETWEEN 1 AND 96
      OR entry->>'kind' !~ '^[a-z0-9](?:[a-z0-9._-]*[a-z0-9])?$'
      OR entry->>'id' IS DISTINCT FROM btrim(entry->>'id')
      OR length(entry->>'id') NOT BETWEEN 1 AND 1024
      OR entry->>'mode' NOT IN ('off', 'suggest', 'automatic')
    THEN
      RETURN false;
    END IF;
  END LOOP;

  IF (
    SELECT count(*)
    FROM (
      SELECT DISTINCT candidate->>'kind', candidate->>'id'
      FROM jsonb_array_elements(value) AS candidates(candidate)
    ) distinct_entries
  ) <> jsonb_array_length(value)
  THEN
    RETURN false;
  END IF;

  SELECT coalesce(
    jsonb_agg(candidate ORDER BY candidate->>'kind' COLLATE "C", candidate->>'id' COLLATE "C"),
    '[]'::jsonb
  ) INTO canonical
  FROM jsonb_array_elements(value) AS candidates(candidate);

  RETURN value = canonical;
END;
$_$;

CREATE FUNCTION workspace_learning_policy_validate_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM "workspace_learning_policy_revisions" revision
    WHERE revision."id" = NEW."new_revision_id"
      AND revision."account_id" = NEW."account_id"
      AND revision."workspace_id" = NEW."workspace_id"
      AND revision."revision" = NEW."new_revision"
      AND revision."policy_hash" = NEW."new_policy_hash"
  ) THEN
    RAISE EXCEPTION 'learning-policy activation event has an invalid new revision'
      USING ERRCODE = '23514';
  END IF;
  IF NEW."old_revision_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM "workspace_learning_policy_revisions" revision
    WHERE revision."id" = NEW."old_revision_id"
      AND revision."account_id" = NEW."account_id"
      AND revision."workspace_id" = NEW."workspace_id"
      AND revision."revision" = NEW."old_revision"
      AND revision."policy_hash" = NEW."old_policy_hash"
  ) THEN
    RAISE EXCEPTION 'learning-policy activation event has an invalid old revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_learning_policy_validate_head() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM "workspace_learning_policy_revisions" revision
    WHERE revision."id" = NEW."revision_id"
      AND revision."account_id" = NEW."account_id"
      AND revision."workspace_id" = NEW."workspace_id"
      AND revision."revision" = NEW."revision"
      AND revision."policy_hash" = NEW."policy_hash"
  ) THEN
    RAISE EXCEPTION 'learning-policy head must identify an exact immutable revision'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_learning_policy_validate_revision_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW."supersedes_revision_id" IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM "workspace_learning_policy_revisions" previous
    WHERE previous."id" = NEW."supersedes_revision_id"
      AND previous."account_id" = NEW."account_id"
      AND previous."workspace_id" = NEW."workspace_id"
  ) THEN
    RAISE EXCEPTION 'superseded learning-policy revision must belong to the exact workspace'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_learning_policy_validate_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  accepted_at timestamptz;
  canonical jsonb;
BEGIN
  SELECT turn."created_at" INTO accepted_at
  FROM "session_turn_attempts" attempt
  JOIN "session_turns" turn
    ON turn."account_id" = attempt."account_id"
    AND turn."workspace_id" = attempt."workspace_id"
    AND turn."session_id" = attempt."session_id"
    AND turn."id" = attempt."turn_id"
  JOIN "sessions" session
    ON session."account_id" = attempt."account_id"
    AND session."workspace_id" = attempt."workspace_id"
    AND session."id" = attempt."session_id"
  WHERE attempt."id" = NEW."attempt_id"
    AND attempt."account_id" = NEW."account_id"
    AND attempt."workspace_id" = NEW."workspace_id"
    AND attempt."session_id" = NEW."session_id"
    AND attempt."turn_id" = NEW."turn_id"
    AND attempt."execution_generation" = NEW."execution_generation"
    AND turn."execution_generation" = NEW."execution_generation"
    AND attempt."state" IN ('claimed', 'running')
    AND turn."active_attempt_id" = attempt."id"
    AND session."active_turn_id" = turn."id"
    AND turn."status" IN ('running', 'requires_action', 'recovering', 'waiting_capacity')
    AND NOT EXISTS (
      SELECT 1
      FROM "session_attempt_interruptions" interruption
      WHERE interruption."workspace_id" = NEW."workspace_id"
        AND interruption."attempt_id" = NEW."attempt_id"
        AND interruption."state" IN ('pending', 'delivered', 'acknowledged')
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'learning-policy snapshot requires an exact active attempt'
      USING ERRCODE = '23514';
  END IF;

  canonical := workspace_learning_policy_canonical_at(
    NEW."account_id",
    NEW."workspace_id",
    accepted_at
  );
  IF NEW."revision_id" IS DISTINCT FROM (canonical->>'revisionId')::uuid
    OR NEW."revision" IS DISTINCT FROM (canonical->>'revision')::bigint
    OR NEW."policy_hash" IS DISTINCT FROM canonical->>'policyHash'
    OR NEW."activation_version" IS DISTINCT FROM (canonical->>'activationVersion')::bigint
    OR NEW."activated_at" IS DISTINCT FROM (canonical->>'activatedAt')::timestamptz
    OR NEW."workspace_mode" IS DISTINCT FROM canonical->>'workspaceMode'
    OR NEW."source_overrides" IS DISTINCT FROM canonical->'sourceOverrides'
  THEN
    RAISE EXCEPTION 'learning-policy snapshot is not the canonical accepted policy'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION workspace_membership_removal_command(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', '{{schema}}', 'pg_temp'
    AS $$
DECLARE

  previous_membership_lifecycle text := pg_catalog.current_setting('opengeni.organization_tenancy_lifecycle', true);
  removal_fenced_access_id uuid;
  account_id_value uuid := nullif(p_command ->> 'organizationId', '')::uuid;
  workspace_id_value uuid := nullif(p_command ->> 'workspaceId', '')::uuid;
  actor_subject text := p_command ->> 'actorSubjectId';
  target_subject text := p_command ->> 'targetSubjectId';
  operation_id_value uuid := nullif(p_command ->> 'operationId', '')::uuid;
  input_hash_value text;
  target_membership_id uuid;
  membership_row_id uuid;
  now_value timestamptz := pg_catalog.clock_timestamp();
  affected_session_ids uuid[] := ARRAY[]::uuid[];
  affected_realtime_ids uuid[] := ARRAY[]::uuid[];
  cancelled_turn_ids uuid[] := ARRAY[]::uuid[];
  cancelled_turn record;
  cancelled_request record;
  cancelled_sequence bigint;
  cancelled_association text;
  settled_update_ids uuid[];
  settled_history_item_id uuid;
  interruption_operation_id uuid;
  visibility_capability_id uuid;
  activity_revision_value bigint;
  previous_workspace text := pg_catalog.current_setting('opengeni.workspace_id', true);
  previous_visibility_capability text := pg_catalog.current_setting(
    'opengeni.session_visibility_write_capability', true
  );
  previous_activity_gate_state text := pg_catalog.current_setting(
    'opengeni.session_activity_gate_state', true
  );
  previous_activity_gate_workspace text := pg_catalog.current_setting(
    'opengeni.session_activity_gate_workspace_id', true
  );
BEGIN

  PERFORM pg_catalog.set_config('opengeni.organization_tenancy_lifecycle', 'organization_membership_lifecycle', true);
  removal_fenced_access_id := opengeni_private.open_session_tenancy_fenced_access(session_tenancy_fence_target_schema());
  IF p_command IS NULL
    OR (p_command ->> 'action') IS DISTINCT FROM 'remove'
    OR account_id_value IS NULL
    OR workspace_id_value IS NULL
    OR actor_subject IS NULL
    OR target_subject IS NULL
    OR operation_id_value IS NULL
    OR actor_subject IS DISTINCT FROM opengeni_private.current_subject_id()
    OR account_id_value IS DISTINCT FROM opengeni_private.current_account_id()
  THEN
    RAISE EXCEPTION 'workspace membership removal authority is invalid'
      USING ERRCODE = '42501';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'organization-membership:' || account_id_value::text, 0
  ));
  PERFORM acquire_session_tenancy_fence(workspace_id_value);

  input_hash_value := pg_catalog.encode(
    pg_catalog.sha256(pg_catalog.convert_to(p_command::text, 'UTF8')), 'hex'
  );
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = account_id_value AND workspace.id = workspace_id_value;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'workspace not found' USING ERRCODE = 'P0002';
  END IF;

  -- The command runs after the application settled the target's pending
  -- protocol state and finalized that workspace activity gate. Its own gated
  -- session writes need the commit guards DEFERRED again (exactly the 0275
  -- wrapper's reasoning).
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard DEFERRED;

  -- The personal-state fence the pre-0278 delete path took: session listing
  -- takes its shared counterpart and pin mutation the same exclusive one, so
  -- a racing snapshot/pin writer cannot recreate personal rows after this
  -- cleanup. Same key derivation as lockSessionPersonalStateExclusive.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'session-personal-state:' || workspace_id_value::text || ':' || target_subject, 0
  ));

  visibility_capability_id := pg_catalog.gen_random_uuid();
  INSERT INTO session_visibility_write_capabilities (
    backend_pid, transaction_id, capability_id
  ) VALUES (
    pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
    visibility_capability_id
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_visibility_write_capability',
    visibility_capability_id::text, true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', workspace_id_value::text, true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_state', 'open', true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_workspace_id', workspace_id_value::text, true
  );

  -- Canonical lock prefix for this workspace, then the exact affected rows.
  PERFORM 1 FROM workspace_inference_controls control
  WHERE control.account_id = account_id_value
    AND control.workspace_id = workspace_id_value
  FOR SHARE;
  PERFORM 1 FROM workspaces workspace
  WHERE workspace.account_id = account_id_value
    AND workspace.id = workspace_id_value
  FOR KEY SHARE;
  -- Task rows before membership/session rows (0275 writer order; reentrant
  -- with the preparation pass in the same transaction).
  PERFORM 1 FROM scheduled_tasks task
  WHERE task.account_id = account_id_value
    AND task.workspace_id = workspace_id_value
    AND task.deleted_at IS NULL
    AND task.status = 'active'
    AND (
      (task.created_by_kind = 'subject' AND task.created_by_subject_id = target_subject)
      OR EXISTS (
        SELECT 1 FROM scheduled_task_revision_authorities authority
        WHERE authority.task_id = task.id
          AND authority.task_authority_revision = task.authority_revision
          AND authority.subject_id = target_subject
      )
      OR EXISTS (
        SELECT 1 FROM scheduled_task_personal_resource_authorities authority
        WHERE authority.task_id = task.id
          AND authority.task_authority_revision = task.authority_revision
          AND authority.initiating_human_subject_id = target_subject
      )
      OR EXISTS (
        SELECT 1 FROM scheduled_task_connection_authority_snapshots snapshot
        WHERE snapshot.task_id = task.id
          AND snapshot.task_authority_revision = task.authority_revision
          AND snapshot.owner_subject_id = target_subject
      )
    )
  ORDER BY task.id
  FOR UPDATE;
  -- Serialize the administering roster before re-running the guards: the
  -- actor's organization membership (shared - the organization lifecycle
  -- takes it FOR UPDATE) and every admin/actor/target workspace membership
  -- row in id order. Two concurrent removals of the two last administering
  -- members therefore serialize, and the loser re-reads a roster with only
  -- one administering member left and fails closed.
  PERFORM 1 FROM organization_memberships org_actor
  WHERE org_actor.account_id = account_id_value
    AND org_actor.subject_id = actor_subject
  FOR SHARE;
  PERFORM 1 FROM workspace_memberships roster
  WHERE roster.account_id = account_id_value
    AND roster.workspace_id = workspace_id_value
    AND (
      roster.subject_id IN (actor_subject, target_subject)
      OR roster.permissions ?| ARRAY['workspace:admin', 'members:manage']
    )
  ORDER BY roster.id
  FOR UPDATE;
  PERFORM opengeni_private.assert_workspace_membership_removal_actor(
    account_id_value, workspace_id_value, actor_subject, target_subject
  );
  SELECT membership.id INTO membership_row_id
  FROM workspace_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.workspace_id = workspace_id_value
    AND membership.subject_id = target_subject;
  IF membership_row_id IS NULL THEN
    DELETE FROM session_visibility_write_capabilities capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id()
      AND capability.capability_id = visibility_capability_id;
    PERFORM pg_catalog.set_config(
      'opengeni.session_visibility_write_capability',
      coalesce(previous_visibility_capability, ''), true
    );
    PERFORM pg_catalog.set_config(
      'opengeni.workspace_id', coalesce(previous_workspace, ''), true
    );
    PERFORM pg_catalog.set_config(
      'opengeni.session_activity_gate_state',
      coalesce(previous_activity_gate_state, ''), true
    );
    PERFORM pg_catalog.set_config(
      'opengeni.session_activity_gate_workspace_id',
      coalesce(previous_activity_gate_workspace, ''), true
    );
    PERFORM opengeni_private.close_session_tenancy_fenced_access(removal_fenced_access_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_membership_lifecycle, ''), true
  );
    RETURN pg_catalog.jsonb_build_object('removed', false);
  END IF;
  SELECT membership.id INTO target_membership_id
  FROM organization_memberships membership
  WHERE membership.account_id = account_id_value
    AND membership.subject_id = target_subject;
  PERFORM 1 FROM sessions affected
  WHERE affected.account_id = account_id_value
    AND affected.workspace_id = workspace_id_value
    AND (
      (target_membership_id IS NOT NULL
        AND affected.owner_organization_membership_id = target_membership_id)
      OR EXISTS (
        SELECT 1 FROM session_turns initiated
        WHERE initiated.session_id = affected.id
          AND initiated.initiating_human_subject_id = target_subject
      )
    )
  ORDER BY affected.id
  FOR NO KEY UPDATE;
  PERFORM 1 FROM session_turns turn_row
  WHERE turn_row.account_id = account_id_value
    AND turn_row.workspace_id = workspace_id_value
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = turn_row.session_id
        AND (
          (target_membership_id IS NOT NULL
            AND owned.owner_organization_membership_id = target_membership_id)
          OR turn_row.initiating_human_subject_id = target_subject
        )
    )
  ORDER BY turn_row.id
  FOR UPDATE;
  PERFORM 1 FROM session_turn_attempts attempt
  WHERE attempt.account_id = account_id_value
    AND attempt.workspace_id = workspace_id_value
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = attempt.session_id
        AND (
          (target_membership_id IS NOT NULL
            AND owned.owner_organization_membership_id = target_membership_id)
          OR EXISTS (
            SELECT 1 FROM session_turns initiated
            WHERE initiated.id = attempt.turn_id
              AND initiated.initiating_human_subject_id = target_subject
          )
        )
    )
  ORDER BY attempt.id
  FOR UPDATE;
  PERFORM 1 FROM session_realtime_modes realtime
  WHERE realtime.account_id = account_id_value
    AND realtime.workspace_id = workspace_id_value
    AND realtime.owner_subject_id = target_subject
    AND realtime.state = 'active'
  ORDER BY realtime.id
  FOR UPDATE;
  SELECT COALESCE(pg_catalog.array_agg(realtime.id ORDER BY realtime.id), ARRAY[]::uuid[])
  INTO affected_realtime_ids
  FROM session_realtime_modes realtime
  WHERE realtime.account_id = account_id_value
    AND realtime.workspace_id = workspace_id_value
    AND realtime.owner_subject_id = target_subject
    AND realtime.state = 'active';
  PERFORM 1 FROM session_realtime_connections connection
  WHERE connection.account_id = account_id_value
    AND connection.workspace_id = workspace_id_value
    AND connection.realtime_id = ANY(affected_realtime_ids)
    AND connection.state IN ('negotiating', 'ready', 'active')
  ORDER BY connection.id
  FOR UPDATE;

  -- Pending tool calls with no live attempt need canonical protocol
  -- settlement first, exactly as the organization lifecycle requires.
  IF EXISTS (
    SELECT 1
    FROM session_turns turn_row
    JOIN sessions owned ON owned.id = turn_row.session_id
    WHERE turn_row.account_id = account_id_value
      AND turn_row.workspace_id = workspace_id_value
      AND turn_row.status IN (
        'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
      )
      AND (
        (target_membership_id IS NOT NULL
          AND owned.owner_organization_membership_id = target_membership_id)
        OR turn_row.initiating_human_subject_id = target_subject
      )
      AND EXISTS (
        SELECT 1 FROM session_pending_tool_calls pending
        WHERE pending.account_id = turn_row.account_id
          AND pending.workspace_id = turn_row.workspace_id
          AND pending.session_id = turn_row.session_id
          AND pending.turn_id = turn_row.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM session_turn_attempts live_attempt
        WHERE live_attempt.account_id = turn_row.account_id
          AND live_attempt.workspace_id = turn_row.workspace_id
          AND live_attempt.session_id = turn_row.session_id
          AND live_attempt.turn_id = turn_row.id
          AND live_attempt.id = turn_row.active_attempt_id
          AND live_attempt.state IN ('claimed', 'running')
      )
  ) THEN
    RAISE EXCEPTION 'pending tool calls require canonical protocol settlement'
      USING ERRCODE = '55000';
  END IF;

  SELECT COALESCE(pg_catalog.array_agg(DISTINCT turn_row.session_id), ARRAY[]::uuid[])
  INTO affected_session_ids
  FROM session_turns turn_row
  JOIN sessions owned
    ON owned.account_id = turn_row.account_id
   AND owned.workspace_id = turn_row.workspace_id
   AND owned.id = turn_row.session_id
  WHERE turn_row.account_id = account_id_value
    AND turn_row.workspace_id = workspace_id_value
    AND turn_row.status IN (
      'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
    )
    AND (
      (target_membership_id IS NOT NULL
        AND owned.owner_organization_membership_id = target_membership_id)
      OR turn_row.initiating_human_subject_id = target_subject
    );
  affected_session_ids := ARRAY(
    SELECT DISTINCT candidate.session_id
    FROM (
      SELECT unnest(affected_session_ids) AS session_id
      UNION ALL
      SELECT realtime.session_id
      FROM session_realtime_modes realtime
      WHERE realtime.id = ANY(affected_realtime_ids)
    ) candidate
    ORDER BY candidate.session_id
  );

  interruption_operation_id := pg_catalog.gen_random_uuid();
  INSERT INTO session_command_receipts (
    id, account_id, workspace_id, actor_type, actor_subject_id,
    action, operation_key, canonical_request_hash, result
  ) VALUES (
    interruption_operation_id, account_id_value, workspace_id_value,
    CASE WHEN actor_subject LIKE 'api_key:%' THEN 'service' ELSE 'human' END, actor_subject, 'workspace.membership.remove',
    'workspace-membership:' || operation_id_value::text,
    input_hash_value,
    pg_catalog.jsonb_build_object(
      'workspaceMembershipOperationId', operation_id_value,
      'workspaceMembershipId', membership_row_id,
      'targetSubjectId', target_subject
    )
  );
  INSERT INTO session_attempt_interruptions (
    account_id, workspace_id, session_id, operation_id, attempt_id,
    kind, control_revision
  )
  SELECT attempt.account_id, attempt.workspace_id, attempt.session_id,
    interruption_operation_id, attempt.id, 'authority_change',
    CASE WHEN target_membership_id IS NOT NULL
      AND owned.owner_organization_membership_id = target_membership_id
      THEN owned.authority_epoch + 1 ELSE owned.authority_epoch END
  FROM session_turn_attempts attempt
  JOIN sessions owned ON owned.id = attempt.session_id
  JOIN session_turns initiated ON initiated.id = attempt.turn_id
  WHERE attempt.account_id = account_id_value
    AND attempt.workspace_id = workspace_id_value
    AND (
      (target_membership_id IS NOT NULL
        AND owned.owner_organization_membership_id = target_membership_id)
      OR initiated.initiating_human_subject_id = target_subject
    )
    AND attempt.state IN ('claimed', 'running')
  ON CONFLICT ON CONSTRAINT session_attempt_interruptions_operation_attempt_uq
  DO NOTHING;

  WITH cancelled AS (
    UPDATE session_turns turn_row
    SET status = 'cancelled', active_attempt_id = NULL,
      cancelled_by = actor_subject, cancel_reason = 'authority_changed',
      finished_at = now_value, updated_at = now_value,
      version = turn_row.version + 1
    WHERE turn_row.account_id = account_id_value
      AND turn_row.workspace_id = workspace_id_value
      AND turn_row.status IN (
        'queued', 'running', 'requires_action', 'recovering', 'waiting_capacity'
      )
      AND EXISTS (
        SELECT 1 FROM sessions owned
        WHERE owned.account_id = turn_row.account_id
          AND owned.workspace_id = turn_row.workspace_id
          AND owned.id = turn_row.session_id
          AND (
            (target_membership_id IS NOT NULL
              AND owned.owner_organization_membership_id = target_membership_id)
            OR turn_row.initiating_human_subject_id = target_subject
          )
      )
      AND NOT EXISTS (
        SELECT 1 FROM session_turn_attempts live_attempt
        WHERE live_attempt.account_id = turn_row.account_id
          AND live_attempt.workspace_id = turn_row.workspace_id
          AND live_attempt.session_id = turn_row.session_id
          AND live_attempt.turn_id = turn_row.id
          AND live_attempt.id = turn_row.active_attempt_id
          AND live_attempt.state IN ('claimed', 'running')
      )
    RETURNING turn_row.id
  )
  SELECT COALESCE(pg_catalog.array_agg(cancelled.id ORDER BY cancelled.id), ARRAY[]::uuid[])
  INTO cancelled_turn_ids
  FROM cancelled;

  FOR cancelled_turn IN
    SELECT turn_row.id, turn_row.session_id, turn_row.execution_generation
    FROM session_turns turn_row
    WHERE turn_row.account_id = account_id_value
      AND turn_row.workspace_id = workspace_id_value
      AND turn_row.id = ANY(cancelled_turn_ids)
    ORDER BY turn_row.session_id, turn_row.id
  LOOP
    SELECT affected.last_sequence,
      CASE WHEN affected.active_turn_id = cancelled_turn.id
        THEN 'current' ELSE NULL END
    INTO cancelled_sequence, cancelled_association
    FROM sessions affected
    WHERE affected.account_id = account_id_value
      AND affected.workspace_id = workspace_id_value
      AND affected.id = cancelled_turn.session_id;
    FOR cancelled_request IN
      UPDATE session_human_input_requests request_row
      SET status = 'cancelled', response = '{"outcome":"cancelled"}'::jsonb,
        responded_by = actor_subject, responded_at = now_value,
        updated_at = now_value
      WHERE request_row.account_id = account_id_value
        AND request_row.workspace_id = workspace_id_value
        AND request_row.session_id = cancelled_turn.session_id
        AND request_row.turn_id = cancelled_turn.id
        AND request_row.status = 'pending'
      RETURNING request_row.id, request_row.creation_attempt_id
    LOOP
      cancelled_sequence := cancelled_sequence + 1;
      INSERT INTO session_events (
        account_id, workspace_id, session_id, sequence, type, payload,
        payload_codec_version, turn_id, turn_generation,
        turn_attempt_id, turn_association, occurred_at
      ) VALUES (
        account_id_value, workspace_id_value, cancelled_turn.session_id,
        cancelled_sequence, 'user.humanInputResponse',
        pg_catalog.jsonb_build_object(
          'requestId', cancelled_request.id,
          'response', pg_catalog.jsonb_build_object('outcome', 'cancelled')
        ), 1, cancelled_turn.id, cancelled_turn.execution_generation,
        cancelled_request.creation_attempt_id, cancelled_association, now_value
      );
    END LOOP;
    SELECT
      pg_catalog.array_agg(
        update_row.id ORDER BY update_row.created_at, update_row.id
      ),
      (pg_catalog.array_agg(
        update_row.delivered_history_item_id
        ORDER BY update_row.created_at, update_row.id
      ))[1]
    INTO settled_update_ids, settled_history_item_id
    FROM session_system_updates update_row
    WHERE update_row.account_id = account_id_value
      AND update_row.workspace_id = workspace_id_value
      AND update_row.session_id = cancelled_turn.session_id
      AND update_row.delivered_turn_id = cancelled_turn.id
      AND update_row.state = 'delivered';
    IF COALESCE(pg_catalog.array_length(settled_update_ids, 1), 0) > 0
      AND NOT EXISTS (
        SELECT 1 FROM session_events prior_settlement
        WHERE prior_settlement.account_id = account_id_value
          AND prior_settlement.workspace_id = workspace_id_value
          AND prior_settlement.session_id = cancelled_turn.session_id
          AND prior_settlement.turn_id = cancelled_turn.id
          AND prior_settlement.type = 'system.update.settled'
      )
    THEN
      cancelled_sequence := cancelled_sequence + 1;
      INSERT INTO session_events (
        account_id, workspace_id, session_id, sequence, type, payload,
        payload_codec_version, turn_id, turn_generation,
        turn_association, occurred_at
      ) VALUES (
        account_id_value, workspace_id_value, cancelled_turn.session_id,
        cancelled_sequence, 'system.update.settled',
        pg_catalog.jsonb_build_object(
          'updateIds', pg_catalog.to_jsonb(settled_update_ids),
          'count', pg_catalog.array_length(settled_update_ids, 1),
          'historyItemId', settled_history_item_id,
          'outcome', 'cancelled'
        ), 1, cancelled_turn.id, cancelled_turn.execution_generation,
        cancelled_association, now_value
      );
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM session_events prior_cancel
      WHERE prior_cancel.account_id = account_id_value
        AND prior_cancel.workspace_id = workspace_id_value
        AND prior_cancel.session_id = cancelled_turn.session_id
        AND prior_cancel.turn_id = cancelled_turn.id
        AND prior_cancel.type = 'turn.cancelled'
    ) THEN
      cancelled_sequence := cancelled_sequence + 1;
      INSERT INTO session_events (
        account_id, workspace_id, session_id, sequence, type, payload,
        payload_codec_version, turn_id, turn_generation,
        turn_association, occurred_at
      ) VALUES (
        account_id_value, workspace_id_value, cancelled_turn.session_id,
        cancelled_sequence, 'turn.cancelled',
        pg_catalog.jsonb_build_object('reason', 'authority_changed'),
        1, cancelled_turn.id, cancelled_turn.execution_generation,
        cancelled_association, now_value
      );
    END IF;
    UPDATE sessions affected
    SET last_sequence = cancelled_sequence, updated_at = now_value
    WHERE affected.account_id = account_id_value
      AND affected.workspace_id = workspace_id_value
      AND affected.id = cancelled_turn.session_id;
  END LOOP;

  UPDATE interaction_interventions intervention
  SET status = 'cancelled', response_actor_subject_id = actor_subject,
    version = intervention.version + 1, settled_at = now_value,
    updated_at = now_value
  WHERE intervention.account_id = account_id_value
    AND intervention.workspace_id = workspace_id_value
    AND intervention.originating_turn_id = ANY(cancelled_turn_ids)
    AND intervention.status = 'open';
  DELETE FROM agent_run_states run_state
  WHERE run_state.account_id = account_id_value
    AND run_state.workspace_id = workspace_id_value
    AND run_state.turn_id = ANY(cancelled_turn_ids);
  UPDATE codex_capacity_waiters waiter
  SET status = 'superseded', observed_wake_revision = waiter.wake_revision,
    last_wake_reason = 'workspace_membership_remove',
    updated_at = now_value
  WHERE waiter.account_id = account_id_value
    AND waiter.workspace_id = workspace_id_value
    AND waiter.blocked_turn_id = ANY(cancelled_turn_ids)
    AND waiter.status = 'waiting';
  UPDATE xai_capacity_waiters waiter
  SET status = 'superseded', observed_wake_revision = waiter.wake_revision,
    last_wake_reason = 'workspace_membership_remove',
    updated_at = now_value
  WHERE waiter.account_id = account_id_value
    AND waiter.workspace_id = workspace_id_value
    AND waiter.blocked_turn_id = ANY(cancelled_turn_ids)
    AND waiter.status = 'waiting';
  UPDATE session_realtime_connections connection
  SET state = 'closed', closed_at = now_value, updated_at = now_value
  WHERE connection.account_id = account_id_value
    AND connection.workspace_id = workspace_id_value
    AND connection.realtime_id = ANY(affected_realtime_ids)
    AND connection.state IN ('negotiating', 'ready', 'active');
  WITH ended AS (
    UPDATE session_realtime_modes realtime
    SET state = 'ended', version = realtime.version + 1,
      ended_at = now_value, end_reason = 'authority_revoked',
      updated_at = now_value
    WHERE realtime.account_id = account_id_value
      AND realtime.workspace_id = workspace_id_value
      AND realtime.id = ANY(affected_realtime_ids)
      AND realtime.state = 'active'
    RETURNING realtime.id, realtime.session_id, realtime.operation_id,
      realtime.version, realtime.connection_epoch
  ), advanced AS (
    UPDATE sessions affected
    SET last_sequence = affected.last_sequence + 1, updated_at = now_value
    FROM ended
    WHERE affected.account_id = account_id_value
      AND affected.workspace_id = workspace_id_value
      AND affected.id = ended.session_id
    RETURNING affected.id AS session_id, affected.last_sequence,
      ended.id AS realtime_id, ended.operation_id,
      ended.version, ended.connection_epoch
  )
  INSERT INTO session_events (
    account_id, workspace_id, session_id, sequence, type, payload, occurred_at
  )
  SELECT account_id_value, workspace_id_value, advanced.session_id,
    advanced.last_sequence, 'session.realtime.ended',
    pg_catalog.jsonb_build_object(
      'realtimeId', advanced.realtime_id,
      'operationId', advanced.operation_id,
      'reason', 'authority_revoked',
      'version', advanced.version,
      'connectionEpoch', advanced.connection_epoch
    ), now_value
  FROM advanced;
  UPDATE sessions affected
  SET active_turn_id = CASE
        WHEN affected.active_turn_id = ANY(cancelled_turn_ids) THEN NULL
        ELSE affected.active_turn_id
      END,
    status = CASE
      WHEN affected.active_turn_id = ANY(cancelled_turn_ids) THEN
        CASE WHEN EXISTS (
          SELECT 1 FROM session_turns queued
          WHERE queued.account_id = affected.account_id
            AND queued.workspace_id = affected.workspace_id
            AND queued.session_id = affected.id
            AND queued.status = 'queued'
        ) THEN 'queued' ELSE 'idle' END
      ELSE affected.status
    END,
    queue_head_position = COALESCE((
      SELECT min(queued.position)::bigint FROM session_turns queued
      WHERE queued.account_id = affected.account_id
        AND queued.workspace_id = affected.workspace_id
        AND queued.session_id = affected.id
        AND queued.status = 'queued'
    ), 0),
    queue_tail_position = COALESCE((
      SELECT max(queued.position)::bigint FROM session_turns queued
      WHERE queued.account_id = affected.account_id
        AND queued.workspace_id = affected.workspace_id
        AND queued.session_id = affected.id
        AND queued.status = 'queued'
    ), 0),
    queue_version = affected.queue_version + 1,
    updated_at = now_value
  WHERE affected.account_id = account_id_value
    AND affected.workspace_id = workspace_id_value
    AND EXISTS (
      SELECT 1 FROM session_turns cancelled
      WHERE cancelled.account_id = affected.account_id
        AND cancelled.workspace_id = affected.workspace_id
        AND cancelled.session_id = affected.id
        AND cancelled.id = ANY(cancelled_turn_ids)
    );
  UPDATE session_system_updates update_row SET state = 'cancelled'
  WHERE update_row.account_id = account_id_value
    AND update_row.workspace_id = workspace_id_value
    AND update_row.state = 'pending'
    AND target_membership_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = update_row.session_id
        AND owned.owner_organization_membership_id = target_membership_id
    );
  UPDATE session_system_update_outbox outbox
  SET status = 'failed', last_error = 'workspace_membership_remove',
    updated_at = now_value
  WHERE outbox.account_id = account_id_value
    AND outbox.workspace_id = workspace_id_value
    AND outbox.status = 'pending'
    AND target_membership_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM sessions source_session
      WHERE source_session.id = outbox.source_session_id
        AND source_session.owner_organization_membership_id = target_membership_id
    );
  UPDATE session_goals goal_row
  SET status = 'paused', paused_reason = 'api',
    rationale = 'Workspace membership was removed; explicit reauthorization is required.',
    version = goal_row.version + 1, updated_at = now_value
  WHERE goal_row.account_id = account_id_value
    AND goal_row.workspace_id = workspace_id_value
    AND goal_row.status = 'active'
    AND target_membership_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = goal_row.session_id
        AND owned.owner_organization_membership_id = target_membership_id
    );
  UPDATE scheduled_tasks task
  SET status = 'paused', personal_connection_delegations = '[]'::jsonb,
    authority_revision = task.authority_revision + 1,
    updated_at = now_value
  WHERE task.account_id = account_id_value
    AND task.workspace_id = workspace_id_value
    AND task.deleted_at IS NULL
    AND task.status = 'active'
    AND (
      (task.created_by_kind = 'subject' AND task.created_by_subject_id = target_subject)
      OR EXISTS (
        SELECT 1 FROM scheduled_task_revision_authorities authority
        WHERE authority.task_id = task.id
          AND authority.task_authority_revision = task.authority_revision
          AND authority.subject_id = target_subject
      )
      OR EXISTS (
        SELECT 1 FROM scheduled_task_personal_resource_authorities authority
        WHERE authority.task_id = task.id
          AND authority.task_authority_revision = task.authority_revision
          AND authority.initiating_human_subject_id = target_subject
      )
      OR EXISTS (
        SELECT 1 FROM scheduled_task_connection_authority_snapshots snapshot
        WHERE snapshot.task_id = task.id
          AND snapshot.task_authority_revision = task.authority_revision
          AND snapshot.owner_subject_id = target_subject
      )
    );
  UPDATE organization_user_resource_grants grant_row
  SET status = 'revoked', revoked_at = now_value,
    generation = grant_row.generation + 1, updated_at = now_value
  WHERE grant_row.account_id = account_id_value
    AND grant_row.workspace_id = workspace_id_value
    AND grant_row.status = 'active'
    AND target_membership_id IS NOT NULL
    AND grant_row.owner_organization_membership_id = target_membership_id;
  UPDATE organization_user_resource_grants grant_row
  SET status = 'revoked', revoked_at = now_value,
    generation = grant_row.generation + 1, updated_at = now_value
  WHERE grant_row.account_id = account_id_value
    AND grant_row.workspace_id = workspace_id_value
    AND grant_row.status = 'active'
    AND target_membership_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM sessions owned
      WHERE owned.id = grant_row.session_id
        AND owned.owner_organization_membership_id = target_membership_id
        AND owned.authority_epoch = grant_row.authority_epoch
    );
  IF target_membership_id IS NOT NULL THEN
    WITH advanced AS (
      UPDATE sessions owned SET
        authority_epoch = owned.authority_epoch + 1,
        initial_personal_connection_delegations = '[]'::jsonb,
        last_sequence = owned.last_sequence + 1
      WHERE owned.account_id = account_id_value
        AND owned.workspace_id = workspace_id_value
        AND owned.owner_organization_membership_id = target_membership_id
      RETURNING owned.id, owned.workspace_id, owned.last_sequence,
        owned.authority_epoch
    )
    INSERT INTO session_events (
      account_id, workspace_id, session_id, sequence, type, payload, occurred_at
    )
    SELECT account_id_value, advanced.workspace_id, advanced.id,
      advanced.last_sequence, 'session.authority.revoked',
      pg_catalog.jsonb_build_object(
        'operationId', operation_id_value,
        'organizationMembershipId', target_membership_id,
        'previousAuthorityEpoch', advanced.authority_epoch - 1,
        'authorityEpoch', advanced.authority_epoch
      ), now_value
    FROM advanced;
  END IF;
  INSERT INTO session_workflow_wake_outbox (
    session_id, account_id, workspace_id, temporal_workflow_id,
    reason, control_revision
  )
  SELECT affected.id, affected.account_id, affected.workspace_id,
    COALESCE(affected.temporal_workflow_id, 'session-' || affected.id::text),
    'workspace_membership_remove', 1
  FROM sessions affected
  WHERE affected.account_id = account_id_value
    AND affected.workspace_id = workspace_id_value
    AND affected.id = ANY(affected_session_ids)
  ON CONFLICT (session_id) DO UPDATE SET
    wake_revision = session_workflow_wake_outbox.wake_revision + 1,
    control_revision = session_workflow_wake_outbox.wake_revision + 1,
    temporal_workflow_id = EXCLUDED.temporal_workflow_id,
    reason = EXCLUDED.reason, attempts = 0,
    next_attempt_at = now_value, last_error = NULL,
    updated_at = now_value;

  -- Personal per-workspace rows and the membership itself, then the activity
  -- gate finalization exactly as the organization lifecycle performs it.
  DELETE FROM session_list_snapshots snapshot
  WHERE snapshot.workspace_id = workspace_id_value
    AND snapshot.subject_id = target_subject;
  DELETE FROM session_pins pin
  WHERE pin.workspace_id = workspace_id_value
    AND pin.subject_id = target_subject;
  DELETE FROM new_session_drafts draft
  WHERE draft.workspace_id = workspace_id_value
    AND draft.subject_id = target_subject;
  DELETE FROM workspace_memberships membership
  WHERE membership.id = membership_row_id;

  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_state', 'preparing', true
  );
  SET CONSTRAINTS ALL IMMEDIATE;
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard DEFERRED;
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_state', 'finalizing', true
  );
  UPDATE workspace_session_activity_revisions counter
  SET revision = counter.revision + 1
  WHERE counter.workspace_id = workspace_id_value
  RETURNING counter.revision INTO activity_revision_value;
  IF activity_revision_value IS NULL THEN
    RAISE EXCEPTION 'workspace membership session activity counter is unavailable'
      USING ERRCODE = '55000';
  END IF;
  UPDATE sessions affected
  SET activity_revision = activity_revision_value,
    activity_revision_pending_xid = NULL
  WHERE affected.account_id = account_id_value
    AND affected.workspace_id = workspace_id_value
    AND affected.activity_revision_pending_xid
      = pg_catalog.pg_current_xact_id()::text::bigint;
  SET CONSTRAINTS sessions_activity_insert_commit_guard,
    sessions_activity_update_commit_guard IMMEDIATE;

  DELETE FROM session_visibility_write_capabilities capability
  WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
    AND capability.transaction_id = pg_catalog.pg_current_xact_id()
    AND capability.capability_id = visibility_capability_id;
  PERFORM pg_catalog.set_config(
    'opengeni.session_visibility_write_capability',
    coalesce(previous_visibility_capability, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', coalesce(previous_workspace, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_state',
    coalesce(previous_activity_gate_state, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_workspace_id',
    coalesce(previous_activity_gate_workspace, ''), true
  );
  PERFORM opengeni_private.close_session_tenancy_fenced_access(removal_fenced_access_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_membership_lifecycle, ''), true
  );
  RETURN pg_catalog.jsonb_build_object(
    'removed', true,
    'workspaceMembershipId', membership_row_id,
    'cancelledTurnIds', pg_catalog.to_jsonb(cancelled_turn_ids),
    'affectedSessionIds', pg_catalog.to_jsonb(affected_session_ids)
  );
EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config(
    'opengeni.workspace_id', coalesce(previous_workspace, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_visibility_write_capability',
    coalesce(previous_visibility_capability, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_state',
    coalesce(previous_activity_gate_state, ''), true
  );
  PERFORM pg_catalog.set_config(
    'opengeni.session_activity_gate_workspace_id',
    coalesce(previous_activity_gate_workspace, ''), true
  );
  PERFORM opengeni_private.close_session_tenancy_fenced_access(removal_fenced_access_id);
  PERFORM pg_catalog.set_config(
    'opengeni.organization_tenancy_lifecycle', coalesce(previous_membership_lifecycle, ''), true
  );
  RAISE;
END
$$;

CREATE TABLE opengeni_private.artifact_catalog_pins (
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    kind text NOT NULL,
    artifact_id text NOT NULL,
    pinned_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT artifact_catalog_pins_artifact_id_check CHECK (((length(artifact_id) >= 1) AND (length(artifact_id) <= 128))),
    CONSTRAINT artifact_catalog_pins_kind_check CHECK ((kind = ANY (ARRAY['site'::text, 'document'::text, 'spreadsheet'::text, 'presentation'::text, 'image'::text, 'file'::text])))
);

ALTER TABLE ONLY opengeni_private.artifact_catalog_pins FORCE ROW LEVEL SECURITY;

