    CONSTRAINT credit_promotion_policy_revisions_operator_check CHECK (((operator = btrim(operator)) AND ((length(operator) >= 1) AND (length(operator) <= 200)))),
    CONSTRAINT credit_promotion_policy_revisions_reason_check CHECK (((reason = btrim(reason)) AND ((length(reason) >= 6) AND (length(reason) <= 1000))))
);

