CREATE TABLE opengeni_private.inbox_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    recipient_subject_id text NOT NULL,
    kind text NOT NULL,
    source_key text NOT NULL,
    title text NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    choices jsonb DEFAULT '[]'::jsonb NOT NULL,
    urgency text DEFAULT 'normal'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    content_version integer DEFAULT 1 NOT NULL,
    seen_version integer DEFAULT 0 NOT NULL,
    snoozed_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    subtitle text DEFAULT ''::text NOT NULL,
    facts jsonb DEFAULT '[]'::jsonb NOT NULL,
    link jsonb,
    event_sequence integer,
    sender_subject_id text,
    sender_label text,
    CONSTRAINT inbox_items_body_check CHECK ((char_length(body) <= 2000)),
    CONSTRAINT inbox_items_choices_check CHECK (((jsonb_typeof(choices) = 'array'::text) AND (jsonb_array_length(choices) <= 4))),
    CONSTRAINT inbox_items_content_version_check CHECK ((content_version > 0)),
    CONSTRAINT inbox_items_event_sequence_check CHECK (((event_sequence IS NULL) OR (event_sequence > 0))),
    CONSTRAINT inbox_items_facts_check CHECK (((jsonb_typeof(facts) = 'array'::text) AND (jsonb_array_length(facts) <= 4))),
    CONSTRAINT inbox_items_kind_check CHECK ((kind = ANY (ARRAY['question'::text, 'approval'::text, 'goal_paused'::text, 'notification'::text, 'reply'::text]))),
    CONSTRAINT inbox_items_link_check CHECK (((link IS NULL) OR (jsonb_typeof(link) = 'object'::text))),
    CONSTRAINT inbox_items_recipient_subject_id_check CHECK (((char_length(recipient_subject_id) >= 1) AND (char_length(recipient_subject_id) <= 300))),
    CONSTRAINT inbox_items_seen_version_check CHECK ((seen_version >= 0)),
    CONSTRAINT inbox_items_sender_label_check CHECK (((sender_label IS NULL) OR ((char_length(sender_label) >= 1) AND (char_length(sender_label) <= 200)))),
    CONSTRAINT inbox_items_sender_subject_id_check CHECK (((sender_subject_id IS NULL) OR ((char_length(sender_subject_id) >= 1) AND (char_length(sender_subject_id) <= 300)))),
    CONSTRAINT inbox_items_source_key_check CHECK (((char_length(source_key) >= 1) AND (char_length(source_key) <= 200))),
    CONSTRAINT inbox_items_status_check CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text, 'withdrawn'::text, 'dismissed'::text]))),
    CONSTRAINT inbox_items_subtitle_check CHECK ((char_length(subtitle) <= 120)),
    CONSTRAINT inbox_items_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 200))),
    CONSTRAINT inbox_items_urgency_check CHECK ((urgency = ANY (ARRAY['normal'::text, 'time_sensitive'::text])))
);

ALTER TABLE ONLY opengeni_private.inbox_items FORCE ROW LEVEL SECURITY;

