CREATE TABLE opengeni_private.subscription_runtime_capabilities (
    backend_pid integer NOT NULL,
    transaction_id xid8 NOT NULL,
    capability_kind text NOT NULL,
    account_id uuid NOT NULL,
    workspace_id uuid,
    session_id uuid,
    turn_id uuid,
    connection_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    provider text,
    session_owner_subject_id text,
    turn_human_subject_id text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT subscription_runtime_capabilities_kind_chk CHECK ((capability_kind = ANY (ARRAY['personal_access'::text, 'session_access'::text, 'binding_access'::text, 'lifecycle'::text, 'designation_management'::text, 'codex_refresh_authorized'::text, 'codex_refresh_write'::text, 'codex_apps_refresh_authorized'::text, 'codex_connection_refresh_authorized'::text, 'codex_connection_owner'::text, 'codex_reset_credit_fence'::text, 'refresh_authorized'::text, 'refresh_write'::text, 'connection_refresh_authorized'::text, 'connection_owner'::text]))),
    CONSTRAINT subscription_runtime_capabilities_provider_chk CHECK ((((capability_kind = 'personal_access'::text) AND (provider = ANY (ARRAY['codex'::text, 'claude'::text, 'xai'::text])) AND (session_id IS NOT NULL) AND (turn_id IS NOT NULL) AND (session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NOT NULL)) OR ((capability_kind = 'session_access'::text) AND (provider IS NULL) AND (session_id IS NOT NULL) AND (turn_id IS NOT NULL) AND (((session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NOT NULL)) OR ((session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL)))) OR ((capability_kind = 'binding_access'::text) AND (provider = ANY (ARRAY['codex'::text, 'claude'::text, 'xai'::text])) AND (session_id IS NOT NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NOT NULL)) OR ((capability_kind = 'lifecycle'::text) AND (provider IS NULL) AND (session_id IS NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL)) OR ((capability_kind = 'designation_management'::text) AND (provider IS NULL) AND (session_id IS NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL) AND (workspace_id IS NOT NULL)) OR ((capability_kind = ANY (ARRAY['codex_refresh_authorized'::text, 'codex_refresh_write'::text])) AND (provider = 'codex'::text) AND (workspace_id IS NOT NULL) AND (session_id IS NOT NULL) AND (turn_id IS NOT NULL) AND (((session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NOT NULL)) OR ((session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL)))) OR ((capability_kind = ANY (ARRAY['codex_apps_refresh_authorized'::text, 'codex_connection_refresh_authorized'::text, 'codex_refresh_write'::text])) AND (provider = 'codex'::text) AND (workspace_id IS NOT NULL) AND (session_id IS NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL)) OR ((capability_kind = ANY (ARRAY['codex_connection_owner'::text, 'codex_reset_credit_fence'::text])) AND (provider = 'codex'::text) AND (session_id IS NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NULL)) OR ((capability_kind = ANY (ARRAY['refresh_authorized'::text, 'refresh_write'::text])) AND (provider IS NOT NULL) AND (provider ~ '^[a-z][a-z0-9_]{1,31}$'::text) AND (workspace_id IS NOT NULL) AND (session_id IS NOT NULL) AND (turn_id IS NOT NULL) AND (((session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NOT NULL)) OR ((session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL)))) OR ((capability_kind = ANY (ARRAY['connection_refresh_authorized'::text, 'refresh_write'::text])) AND (provider IS NOT NULL) AND (provider ~ '^[a-z][a-z0-9_]{1,31}$'::text) AND (workspace_id IS NOT NULL) AND (session_id IS NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NULL) AND (turn_human_subject_id IS NULL)) OR ((capability_kind = 'connection_owner'::text) AND (provider IS NOT NULL) AND (provider ~ '^[a-z][a-z0-9_]{1,31}$'::text) AND (session_id IS NULL) AND (turn_id IS NULL) AND (session_owner_subject_id IS NOT NULL) AND (turn_human_subject_id IS NULL))))
);

