CREATE TABLE opengeni_private.usage_allowance_attribution_receipts (
    account_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    source_kind text NOT NULL,
    source_id text NOT NULL,
    session_id uuid,
    attribution jsonb NOT NULL,
    quantity bigint,
    idempotency_key text,
    CONSTRAINT usage_allowance_attribution_receipts_attribution_check CHECK ((jsonb_typeof(attribution) = 'object'::text)),
    CONSTRAINT usage_allowance_attribution_receipts_attribution_check1 CHECK (COALESCE(
CASE (attribution ->> 'kind'::text)
    WHEN 'unknown'::text THEN (attribution = '{"kind": "unknown"}'::jsonb)
    WHEN 'service'::text THEN (attribution = '{"kind": "service"}'::jsonb)
    WHEN 'human'::text THEN ((attribution = jsonb_build_object('kind', 'human', 'initiatingHumanSubjectId', (attribution -> 'initiatingHumanSubjectId'::text))) AND (jsonb_typeof((attribution -> 'initiatingHumanSubjectId'::text)) = 'string'::text) AND ((octet_length((attribution ->> 'initiatingHumanSubjectId'::text)) >= 1) AND (octet_length((attribution ->> 'initiatingHumanSubjectId'::text)) <= 1024)))
    WHEN 'turn'::text THEN ((attribution = jsonb_build_object('kind', 'turn', 'turnId', (attribution -> 'turnId'::text), 'initiatingHumanSubjectId', (attribution -> 'initiatingHumanSubjectId'::text))) AND (COALESCE((attribution ->> 'turnId'::text), ''::text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (((attribution -> 'initiatingHumanSubjectId'::text) = 'null'::jsonb) OR ((jsonb_typeof((attribution -> 'initiatingHumanSubjectId'::text)) = 'string'::text) AND ((octet_length((attribution ->> 'initiatingHumanSubjectId'::text)) >= 1) AND (octet_length((attribution ->> 'initiatingHumanSubjectId'::text)) <= 1024)))))
    ELSE false
END, false)),
    CONSTRAINT usage_allowance_attribution_receipts_check1 CHECK (((source_kind <> 'turn'::text) OR ((session_id IS NOT NULL) AND ((attribution ->> 'kind'::text) = 'turn'::text) AND ((attribution ->> 'turnId'::text) = source_id)))),
    CONSTRAINT usage_allowance_attribution_receipts_source_id_check CHECK (((octet_length(source_id) >= 1) AND (octet_length(source_id) <= 1024))),
    CONSTRAINT usage_attribution_source_kind CHECK ((source_kind = ANY (ARRAY['turn'::text, 'schedule'::text, 'knowledge_query'::text, 'voice_transcription'::text]))),
    CONSTRAINT usage_attribution_source_shape CHECK (COALESCE((((source_kind = 'knowledge_query'::text) AND (session_id IS NULL) AND (quantity IS NOT NULL) AND (idempotency_key = ('knowledge.query_cost:'::text || source_id))) OR ((source_kind = 'voice_transcription'::text) AND (session_id IS NULL) AND (quantity IS NOT NULL) AND (idempotency_key = ('voice.transcription_cost:'::text || source_id))) OR ((source_kind = ANY (ARRAY['turn'::text, 'schedule'::text])) AND (quantity IS NULL) AND (idempotency_key IS NULL))), false))
);

