    request_digest text NOT NULL,
    kind text NOT NULL,
    target_kind text NOT NULL,
    target_id text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    phase text DEFAULT 'admitted'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    result jsonb,
    error_code text,
    created_by_subject_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT capability_operations_idempotency_chk CHECK ((((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 200)) AND (request_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT capability_operations_kind_chk CHECK ((kind = ANY (ARRAY['install'::text, 'connect'::text, 'configure'::text, 'update'::text, 'repair'::text, 'disconnect'::text, 'uninstall'::text]))),
    CONSTRAINT capability_operations_state_chk CHECK ((((length(phase) >= 1) AND (length(phase) <= 120)) AND (version > 0) AND ((result IS NULL) OR ((jsonb_typeof(result) = 'object'::text) AND (octet_length(convert_to((result)::text, 'UTF8'::name)) <= 131072))) AND ((error_code IS NULL) OR ((length(error_code) >= 1) AND (length(error_code) <= 120))) AND ((length(btrim(created_by_subject_id)) >= 1) AND (length(btrim(created_by_subject_id)) <= 1024)) AND ((status = ANY (ARRAY['completed'::text, 'failed'::text])) = (completed_at IS NOT NULL)))),
    CONSTRAINT capability_operations_status_chk CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'completed'::text, 'failed'::text, 'outcome_unknown'::text]))),
    CONSTRAINT capability_operations_target_chk CHECK (((target_kind = ANY (ARRAY['plugin'::text, 'integration'::text, 'skill'::text, 'facet_binding'::text])) AND ((length(target_id) >= 1) AND (length(target_id) <= 512))))
);

